--
-- Name: complete_requested_account_deletion_v1(); Type: FUNCTION; Schema: participant_identity; Owner: postgres
--

CREATE FUNCTION participant_identity.complete_requested_account_deletion_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare request_value participant_identity.account_deletion_requests_v1%rowtype;
declare table_name text;
declare linked_players text[];
begin
  select * into request_value from participant_identity.account_deletion_requests_v1
    where auth_user_id = old.id for update;
  if not found then return old; end if;
  perform participant_identity.lock_deletion_governance_v1();
  if participant_identity.account_deletion_status_v1(old.id) <> 'READY' then
    raise exception using errcode = '55000', message = 'ACCOUNT_DELETION_PROTECTED';
  end if;
  update production_control.director_entitlements set status = 'REVOKED', revoked_at = clock_timestamp()
    where auth_user_id = old.id and status = 'ACTIVE';
  select array_agg(player_id) into linked_players from participant_identity.user_player_links where auth_user_id = old.id;
  -- Bounded account-owned records only. No scoring/tournament table is edited.
  foreach table_name in array array[
    'participant_phone_otp_attempts', 'participant_auth_client_diagnostics',
    'participant_auth_otp_attempts', 'participant_auth_rehearsals',
    'production_participant_enrollment_claims', 'production_auth_candidates',
    'participant_auth_identifiers', 'tournament_roles', 'user_player_links'
  ] loop
    if to_regclass('participant_identity.' || table_name) is not null then
      execute format('delete from participant_identity.%I where auth_user_id = $1', table_name) using old.id;
    end if;
  end loop;
  foreach table_name in array array['player_approved_phones_v1', 'player_login_preferences_v1'] loop
    if to_regclass('participant_identity.' || table_name) is not null then
      execute format('delete from participant_identity.%I where player_id = any($1)', table_name) using linked_players;
    end if;
  end loop;
  delete from participant_identity.participant_identity_contacts where player_id = any(linked_players);
  delete from participant_identity.review_access_v1 where auth_user_id = old.id;
  update participant_identity.account_deletion_requests_v1 set
    status = 'COMPLETED', auth_user_id = null, completed_at = clock_timestamp(), updated_at = clock_timestamp()
    where request_id = request_value.request_id;
  return old;
end;
$_$;


ALTER FUNCTION participant_identity.complete_requested_account_deletion_v1() OWNER TO postgres;

--
-- Name: enforce_current_phone_auth_link(); Type: FUNCTION; Schema: participant_identity; Owner: postgres
--

CREATE FUNCTION participant_identity.enforce_current_phone_auth_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'public', 'auth', 'pg_temp'
    AS $$
declare canonical_auth_user_id uuid;
begin
  if new.identifier_type <> 'PHONE'
     or new.status not in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED') then
    return new;
  end if;

  select link.auth_user_id into canonical_auth_user_id
  from participant_identity.user_player_links link
  where link.player_id = new.player_id
    and link.status = 'ACTIVE'
  for key share;

  if canonical_auth_user_id is null then
    raise exception 'Current mobile ownership requires one active Player Passport Auth link.'
      using errcode = 'P0001';
  end if;

  if new.auth_user_id <> canonical_auth_user_id then
    raise exception 'Current mobile ownership must use the active Player Passport Auth user.'
      using errcode = 'P0001';
  end if;

  if not exists (
    select 1
    from participant_identity.participant_auth_identifiers email_identifier
    where email_identifier.player_id = new.player_id
      and email_identifier.auth_user_id = canonical_auth_user_id
      and email_identifier.identifier_type = 'EMAIL'
      and email_identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
  ) then
    raise exception 'Current mobile ownership requires matching email ownership for the active Auth user.'
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION participant_identity.enforce_current_phone_auth_link() OWNER TO postgres;

