--
-- Name: require_live_authorship_v1(); Type: FUNCTION; Schema: participant_identity; Owner: postgres
--

CREATE FUNCTION participant_identity.require_live_authorship_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare subject uuid;
begin
  subject := (to_jsonb(new)->>tg_argv[0])::uuid;
  if subject is null then return new; end if;
  -- Retaining an existing attribution is not assigning a new author. The
  -- registry FK still protects it, including after legitimate Auth deletion.
  if tg_op = 'UPDATE' and subject = (to_jsonb(old)->>tg_argv[0])::uuid then
    return new;
  end if;
  -- Serialize new attribution with Auth DELETE/key changes until transaction
  -- end. An unlocked existence check is insufficient under MVCC. If DELETE
  -- wins, this waits and then rejects (or serialization fails at higher
  -- isolation); if attribution wins, DELETE waits for its commit/rollback.
  perform 1 from auth.users where id = subject for key share;
  if not found then
    raise exception using errcode = '23503', message = 'LIVE_AUTHOR_AUTH_REQUIRED';
  end if;
  insert into participant_identity.historical_authorship_v1 values(subject) on conflict do nothing;
  return new;
end;
$$;


ALTER FUNCTION participant_identity.require_live_authorship_v1() OWNER TO postgres;

--
-- Name: resolve_approved_participant_tournament(uuid); Type: FUNCTION; Schema: participant_identity; Owner: postgres
--

CREATE FUNCTION participant_identity.resolve_approved_participant_tournament(target_auth_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'participant_identity', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
  select contact.tournament_id
  from participant_identity.user_player_links link
  join participant_identity.participant_identity_contacts contact
    on contact.player_id = link.player_id
   and contact.identity_active
   and link.email_identity_hash = encode(extensions.digest(contact.email_normalized::text, 'sha256'::text), 'hex')
  join scoring_authority.tournament_players membership
    on membership.tournament_id = contact.tournament_id
   and membership.player_id = contact.player_id
   and membership.participation_status = 'ACTIVE'
  join participant_identity.identity_context_revisions revision
    on revision.tournament_id = contact.tournament_id
  join lateral (
    select run.approved_at
    from participant_identity.identity_config_import_runs run
    where run.tournament_id = contact.tournament_id
      and run.status = 'APPROVED'
      and run.source_fingerprint = revision.configuration_fingerprint
    order by run.approved_at desc nulls last, run.requested_at desc
    limit 1
  ) approved on true
  where link.auth_user_id = target_auth_user_id
    and link.status = 'ACTIVE'
  order by approved.approved_at desc nulls last, contact.updated_at desc, contact.tournament_id
  limit 1
$$;


ALTER FUNCTION participant_identity.resolve_approved_participant_tournament(target_auth_user_id uuid) OWNER TO postgres;

--
-- Name: suppress_requested_deletion_portraits_v1(); Type: FUNCTION; Schema: participant_identity; Owner: postgres
--

CREATE FUNCTION participant_identity.suppress_requested_deletion_portraits_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare target_players text[]; next_revision bigint;
begin
 if not exists(select 1 from participant_identity.account_deletion_requests_v1 where auth_user_id=old.id) then
   return old;
 end if;
 perform participant_identity.lock_deletion_governance_v1();
 if participant_identity.account_deletion_status_v1(old.id)<>'READY' then
   raise exception using errcode='55000',message='ACCOUNT_DELETION_PROTECTED';
 end if;
 -- Serialize revisions through transaction commit, not a nontransactional sequence.
 perform 1 from participant_identity.player_portrait_policy_clock_v1 where singleton for update;
 select array_agg(distinct l.player_id order by l.player_id) into target_players
 from participant_identity.user_player_links l
 where l.auth_user_id=old.id and not exists(
   select 1 from participant_identity.player_portrait_policy_v1 p where p.player_id=l.player_id);
 if cardinality(target_players)>0 then
   update participant_identity.player_portrait_policy_clock_v1 set revision=revision+1
    where singleton returning revision into next_revision;
   insert into participant_identity.player_portrait_policy_v1(player_id,policy,revision)
    select unnest(target_players),'SUPPRESSED',next_revision;
 end if;
 -- Subsequent Auth cleanup/guards remain authoritative. Any failure rolls this back.
 return old;
end $$;


ALTER FUNCTION participant_identity.suppress_requested_deletion_portraits_v1() OWNER TO postgres;

--
-- Name: access_governance_global_status_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.access_governance_global_status_v1(target_player text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
  select coalesce(profile.global_status, case
    when pg_catalog.upper(pg_catalog.btrim(coalesce(
      player.source_payload->>'Active', 'TRUE'
    ))) in ('FALSE', 'NO', '0', 'INACTIVE', 'ALUMNI') then 'ALUMNI'
    else 'ACTIVE'
  end)
  from scoring_authority.players player
  left join production_control.player_governance_profiles_v1 profile
    on profile.player_id = player.player_id
  where player.player_id = target_player
$$;


ALTER FUNCTION production_control.access_governance_global_status_v1(target_player text) OWNER TO postgres;

