ALTER FUNCTION production_control.access_governance_revision_v1(target_tournament text) OWNER TO postgres;

--
-- Name: access_governance_slug_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.access_governance_slug_v1(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select pg_catalog.btrim(pg_catalog.regexp_replace(
    pg_catalog.regexp_replace(
      pg_catalog.lower(pg_catalog.btrim(coalesce(value, ''))),
      '[^a-z0-9]+', '-', 'g'
    ), '-+', '-', 'g'
  ), '-')
$$;


ALTER FUNCTION production_control.access_governance_slug_v1(value text) OWNER TO postgres;

--
-- Name: adopt_production_odds_publication_authority_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.adopt_production_odds_publication_authority_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing_response jsonb;
  response_value jsonb;
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  current_value scoring_authority.odds_publication_current%rowtype;
  snapshot_value scoring_authority.odds_published_snapshots%rowtype;
  config scoring_authority.odds_input_configurations%rowtype;
  binding jsonb;
  binding_fingerprint text;
begin
  if not pg_catalog.pg_has_role(session_user, current_user, 'USAGE') then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DATABASE_OWNER_REQUIRED';
  end if;
  if input->>'operation' is distinct from
       'ADOPT_PRODUCTION_ODDS_PUBLICATION_AUTHORITY_V1'
     or pg_catalog.upper(coalesce(input->>'environment', '')) <> 'PRODUCTION'
     or input->>'project_ref' is distinct from 'ymqhhtxaywtqllynrmxe'
     or input->>'project_url' is distinct from
       'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or input->>'source_workbook_id' is distinct from
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'vercel_team_id' is distinct from
       'team_kPw5zaib8uaQJALAwj4fWI6R'
     or input->>'vercel_environment' is distinct from 'production'
     or input->>'canonical_domain' is distinct from 'https://baggerinv.com'
     or input->>'tournament_id' is distinct from '2026'
     or coalesce((input->>'tournament_year')::integer, 0) <> 2026
     or input->>'expected_snapshot_id' is distinct from
       '65f54c41-2dc3-4b2c-8570-a4d23056649a'
     or input->>'expected_payload_hash' is distinct from
       '6529536209651e61eff2027c3b2c9ef5323dc021699159b1e0565ef39169128f'
     or input->>'expected_google_publication_fingerprint' is distinct from
       'fbd456e560c2d6dcc4737a9fb11e8c3488ad24d8a7e27c61ddb5ee8e04559a0f'
     or input->>'expected_import_fingerprint' is distinct from
       '99d33b84b9c336b130adf3ec18d54b612c6461de697f365fb42662de39448e64'
     or input->>'expected_published_at' is distinct from
       '2026-07-20T02:54:17.133Z'
     or coalesce(input->>'expected_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'expected_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'expected_authority_epoch_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or pg_catalog.jsonb_typeof(input->'expected_activation_revision')
       is distinct from 'number'
     or input->>'expected_activation_revision' !~ '^[0-9]+$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_AUTHORITY_ADOPTION_INPUT_INVALID';
  end if;

  existing_response := production_control.lookup_cutover_receipt(
    'ADOPT_ODDS_PUBLICATION_AUTHORITY_V1', input
  );
  if existing_response is not null then return existing_response; end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  perform pg_catalog.pg_advisory_xact_lock(731132026057::bigint);

  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select value.* into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = gate.active_epoch_id;
  select value.* into strict current_value
  from scoring_authority.odds_publication_current value
  where value.tournament_id = '2026' for update;
  select value.* into strict snapshot_value
  from scoring_authority.odds_published_snapshots value
  where value.id = '65f54c41-2dc3-4b2c-8570-a4d23056649a'::uuid;
  select value.* into strict config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = '2026' and value.is_current;

  if resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.google_workbook_id <>
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_read_authority <> 'SUPABASE'
     or resource.scoring_authority <> 'SUPABASE'
     or resource.participant_identity_authority <> 'SUPABASE'
     or not resource.public_supabase_reads_enabled
     or not resource.scoring_ingress_enabled
     or not resource.workers_enabled
     or resource.odds_publication_authority <> 'GOOGLE'
     or resource.odds_publication_enabled
     or activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.read_cutover_phase <> 'OBSERVATION'
     or activation.current_authority <> 'SUPABASE'
     or activation.maintenance_state <> 'NORMAL'
     or not activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.expected_deployment_commit is distinct from
       input->>'expected_deployment_commit'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from epoch.epoch_id
     or epoch.epoch_id is distinct from
       (input->>'expected_authority_epoch_id')::uuid
     or epoch.status <> 'COMMITTED'
     or epoch.authority_after <> 'SUPABASE'
     or gate.state <> 'OPEN'
     or gate.authority <> 'SUPABASE'
     or gate.admission_deployment_id is distinct from
       input->>'expected_deployment_id'
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or gate.unresolved_client_queues <> 0
     or current_value.contract_version <>
       'production-odds-publication-v1'
     or current_value.publication_authority <> 'GOOGLE'
     or current_value.publication_state <> 'UNPUBLISHED'
     or current_value.current_snapshot_id is not null
     or current_value.publication_revision <> 0
     or exists (
       select 1 from production_control.worker_controls
       where worker_name = 'ODDS_GOOGLE_MIRROR'
         and (enabled or google_writes_allowed)
     )
     or exists (select 1 from scoring_authority.odds_google_mirror_jobs)
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ODDS_AUTHORITY_ADOPTION_NOT_SAFE';
  end if;

  if snapshot_value.tournament_id <> '2026'
     or snapshot_value.milestone <> 'Pre-Tournament'
     or snapshot_value.phase_order <> 0
     or snapshot_value.publication_revision <> 1
     or snapshot_value.published_at is distinct from
       '2026-07-20T02:54:17.133Z'::timestamptz
     or snapshot_value.payload_hash <>
       '6529536209651e61eff2027c3b2c9ef5323dc021699159b1e0565ef39169128f'
     or snapshot_value.google_publication_fingerprint <>
       'fbd456e560c2d6dcc4737a9fb11e8c3488ad24d8a7e27c61ddb5ee8e04559a0f'
     or not snapshot_value.is_current_for_milestone
     or not snapshot_value.is_current_official
     or not snapshot_value.publication_verified
     or snapshot_value.publication_authority <> 'GOOGLE'
     or snapshot_value.authority_contract_version <>
       'legacy-google-published-odds-v1'
     or coalesce((snapshot_value.published_payload->>'year')::integer, 0) <> 2026
     or snapshot_value.published_payload->>'phase' <> 'Pre-Tournament'
     or pg_catalog.jsonb_typeof(snapshot_value.published_payload->'teams')
       <> 'array'
     or pg_catalog.jsonb_array_length(
       snapshot_value.published_payload->'teams'
     ) <> 2
     or pg_catalog.jsonb_typeof(snapshot_value.published_payload->'players')
       <> 'array'
     or pg_catalog.jsonb_array_length(
       snapshot_value.published_payload->'players'
     ) <> 24
     or (select pg_catalog.count(*)
         from scoring_authority.odds_published_snapshots value
         where value.tournament_id = '2026' and value.is_current_official) <> 1
     or not exists (
       select 1 from scoring_authority.odds_snapshot_import_runs value
       where value.tournament_id = '2026'
         and value.source_workbook_id =
           '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
         and value.import_fingerprint =
           '99d33b84b9c336b130adf3ec18d54b612c6461de697f365fb42662de39448e64'
         and value.current_official_milestone = 'Pre-Tournament'
         and value.status = 'APPLIED'
         and value.snapshot_count = 1
     )
     or config.validation_status <> 'VALID'
     or config.source_workbook_id <>
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or config.settings_fingerprint <>
       '2b9fb9a625b9f33f28db35834e0cf78128d5dfc82acbee66606ec3e700cf0684'
     or config.ratings_fingerprint <>
       '27b32865de26bed9a1c057bf7fafcb954154c9f6942affd5c280729d3a6df018'
     or config.pairing_fingerprint <>
       'f9babd64464a824d89250e4fb2c17eb4e74db4c5ebd8c39887f28f8b0f94dc47'
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ODDS_CERTIFIED_SNAPSHOT_MISMATCH';
  end if;

  binding := pg_catalog.jsonb_build_object(
    'contract_version', 'production-odds-publication-v1',
    'environment', 'PRODUCTION',
    'project_ref', resource.project_ref,
    'project_url', resource.project_url,
    'source_workbook_id', resource.google_workbook_id,
    'vercel_project_id', 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'vercel_team_id', 'team_kPw5zaib8uaQJALAwj4fWI6R',
    'vercel_environment', 'production',
    'deployment_id', gate.admission_deployment_id,
    'deployment_commit', activation.expected_deployment_commit,
    'canonical_domain', resource.canonical_domain,
    'tournament_id', resource.current_tournament_id,
    'authority_epoch_id', epoch.epoch_id,
    'activation_revision', activation.activation_revision,
    'adoption_snapshot_id', snapshot_value.id,
    'adoption_payload_hash', snapshot_value.payload_hash,
    'google_publication_retired', true,
    'google_mirror_retired', true
  );
  binding_fingerprint :=
    production_control.odds_publication_v1_hash(binding);

  update scoring_authority.odds_publication_current
  set publication_authority = 'SUPABASE',
      publication_state = 'PUBLISHED', freshness = 'CURRENT',
      current_snapshot_id = snapshot_value.id, publication_revision = 1,
      source_calculation_revision = pg_catalog.jsonb_build_object(
        'origin', 'LEGACY_GOOGLE_ADOPTED',
        'snapshot_import_fingerprint',
          '99d33b84b9c336b130adf3ec18d54b612c6461de697f365fb42662de39448e64',
        'input_configuration_id', config.id,
        'configuration_revision', config.configuration_revision,
        'settings_fingerprint', config.settings_fingerprint,
        'ratings_fingerprint', config.ratings_fingerprint,
        'pairing_fingerprint', config.pairing_fingerprint,
        'bundle_fingerprint', config.bundle_fingerprint
      ),
      published_at = snapshot_value.published_at,
      published_by_player_id = null, published_by_auth_user_id = null,
      authority_epoch_id = epoch.epoch_id,
      resource_binding = binding,
      resource_binding_fingerprint = binding_fingerprint,
      adoption_kind = 'LEGACY_GOOGLE_ADOPTED',
      activated_by = pg_catalog.left(input->>'actor_id', 160),
      activated_at = pg_catalog.now(), updated_at = pg_catalog.now()
  where tournament_id = '2026';

  update production_control.resource_scope
  set odds_publication_authority = 'SUPABASE',
      odds_publication_enabled = true,
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION';

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_ODDS_PUBLICATION_AUTHORITY_ADOPTED',
    'publication_authority', 'SUPABASE',
    'publication_contract_version', 'production-odds-publication-v1',
    'publication_state', 'PUBLISHED',
    'freshness', 'CURRENT',
    'snapshot_id', snapshot_value.id,
    'publication_revision', 1,
    'published_at', snapshot_value.published_at,
    'adoption_kind', 'LEGACY_GOOGLE_ADOPTED',
    'resource_binding_fingerprint', binding_fingerprint,
    'mirror_created', false,
    'google_writes', 0,
    'idempotent', false
  );

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'ODDS_PUBLICATION_AUTHORITY_MIGRATED_TO_SUPABASE',
    pg_catalog.left(input->>'actor_id', 160),
    response_value - 'ok' - 'idempotent'
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_ODDS_PUBLICATION_AUTHORITY_ADOPTED',
    'CHAMPIONSHIP_ODDS_PUBLICATION', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  perform production_control.store_cutover_receipt(
    'ADOPT_ODDS_PUBLICATION_AUTHORITY_V1', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.adopt_production_odds_publication_authority_v1(input jsonb) OWNER TO postgres;

--
-- Name: advance_annual_scoring_transition_v1(uuid, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.advance_annual_scoring_transition_v1(target_transition_id uuid, input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  canonical_context jsonb:=jsonb_build_object('resource_class','PRODUCTION','resource_id','BAGGER_INV_PRODUCTION');
  transition_value production_control.annual_scoring_transitions_v1%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  target production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(
    input#>>'{authorization,player_id}'
  ));
  actor_auth uuid := (input#>>'{authorization,auth_user_id}')::uuid;
  drain_input jsonb;
  drain_response jsonb;
  finalize_input jsonb;
  finalize_response jsonb;
  certificate jsonb;
  readiness jsonb;
  lease_fingerprint text;
  revisions jsonb;
  checkpoints jsonb;
  unresolved integer;
  unresolved_outbox integer;
  unresolved_archive integer;
  post_close_count integer;
  next_lifecycle_revision bigint;
begin
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION')then
    canonical_context:=production_control.annual_resource_context_v2();
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict transition_value
  from production_control.annual_scoring_transitions_v1 value
  where value.transition_id = target_transition_id for update;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = canonical_context->>'resource_id' for update;
  select value.* into strict target
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = transition_value.successor_tournament_id
  for update;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.runtime_generation_id = transition_value.runtime_generation_id
  for update;
  select value.* into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = transition_value.predecessor_closure_id
  for update;
  if transition_value.transition_status = 'CLOSED' then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_CLOSED',
      'transitionId', transition_value.transition_id,
      'predecessorTournamentId', transition_value.predecessor_tournament_id,
      'successorTournamentId', transition_value.successor_tournament_id,
      'expectedPointerRevision', transition_value.expected_pointer_revision,
      'runtimeGenerationId', transition_value.runtime_generation_id,
      'authorityGenerationId', transition_value.authority_generation_id,
      'admissionGenerationId', transition_value.admission_generation_id,
      'readinessFingerprint', transition_value.readiness_fingerprint,
      'pointerChanged', false, 'predecessorClosed', true,
      'successorActivated', false, 'idempotent', true
    );
  end if;
  if transition_value.transition_status <> 'CLOSING'
     or pointer.tournament_id <> transition_value.predecessor_tournament_id
     or pointer.pointer_revision <> transition_value.expected_pointer_revision
     or input->>'expected_current_tournament_id' is distinct from
       pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or target.lifecycle <> 'READY_FOR_ACTIVATION'
     or generation.generation_status <> 'PREPARED'
     or closure.status not in ('CLOSING', 'CLOSED') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_DRAIN_REVISION_CONFLICT';
  end if;

  if canonical_context->>'resource_class'='CERTIFICATION' then
    drain_response:=production_control.drain_certification_annual_predecessor_v1(closure.closure_id);
    if not coalesce((drain_response->>'ready_to_finalize')::boolean,false)then
      return jsonb_build_object('ok',true,'code','PRODUCTION_ANNUAL_SCORING_PREDECESSOR_DRAINING',
       'transitionId',target_transition_id,'predecessorTournamentId',pointer.tournament_id,'successorTournamentId',target.tournament_id,
       'closureId',closure.closure_id,'activeOrUnresolvedLeases',drain_response->'active_or_unresolved_leases',
       'pointerChanged',false,'predecessorClosed',false,'successorActivated',false,'idempotent',false);
    end if;
  elsif pointer.tournament_id = '2026' then
    select value.* into strict activation
    from production_control.cutover_activation_state value
    where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
    select value.* into strict gate
    from scoring_authority.ingress_gates value
    where value.tournament_id = '2026' for update;
    if closure.status = 'CLOSING' then
      drain_input := input || pg_catalog.jsonb_build_object(
        'actor_id', actor_player,
        'closure_id', closure.closure_id,
        'external_fence_evidence_id', closure.external_fence_evidence_id,
        'expected_activation_revision', activation.activation_revision,
        'expected_authority_generation', activation.authority_generation_id,
        'expected_admission_generation', gate.admission_generation_id,
        'expected_admission_revision', gate.admission_revision,
        'request_fingerprint', production_control.future_runtime_hash_v2(
          pg_catalog.jsonb_build_object(
            'operationRequestId', input->>'operation_request_id',
            'requestPayloadHash', input->>'request_payload_hash',
            'transitionId', target_transition_id,
            'stage', 'DRAIN_PREDECESSOR'
          )
        )
      );
      drain_response := public.drain_production_scoring_admission(drain_input);
      if coalesce((drain_response->>'ready_to_finalize')::boolean, false)
           is not true then
        return pg_catalog.jsonb_build_object(
          'ok', true,
          'code', 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_DRAINING',
          'transitionId', target_transition_id,
          'predecessorTournamentId', pointer.tournament_id,
          'successorTournamentId', target.tournament_id,
          'closureId', closure.closure_id,
          'activeOrUnresolvedLeases',
            coalesce((drain_response->>'active_or_unresolved_leases')::integer, 0),
          'pointerChanged', false, 'predecessorClosed', false,
          'successorActivated', false, 'idempotent', false
        );
      end if;
      select value.* into strict activation
      from production_control.cutover_activation_state value
      where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
      select value.* into strict gate
      from scoring_authority.ingress_gates value
      where value.tournament_id = '2026' for update;
      revisions := production_control.current_match_revisions('2026');
      checkpoints := production_control.current_google_checkpoints('2026');
      finalize_input := input || pg_catalog.jsonb_build_object(
        'actor_id', actor_player,
        'closure_id', closure.closure_id,
        'external_fence_evidence_id', closure.external_fence_evidence_id,
        'expected_activation_revision', activation.activation_revision,
        'expected_authority_generation', activation.authority_generation_id,
        'expected_admission_generation', gate.admission_generation_id,
        'expected_admission_revision', gate.admission_revision,
        'boundary_captured_at', pg_catalog.clock_timestamp(),
        'lease_set_fingerprint', drain_response->>'lease_set_fingerprint',
        'supabase_match_revisions', revisions,
        'google_checkpoints', checkpoints,
        'request_fingerprint', production_control.future_runtime_hash_v2(
          pg_catalog.jsonb_build_object(
            'operationRequestId', input->>'operation_request_id',
            'requestPayloadHash', input->>'request_payload_hash',
            'transitionId', target_transition_id,
            'stage', 'FINALIZE_PREDECESSOR'
          )
        )
      );
      finalize_response :=
        public.finalize_production_scoring_admission(finalize_input);
    end if;
  else
    select value.* into strict annual
    from production_control.annual_scoring_runtime_authorities_v1 value
    where value.tournament_id = pointer.tournament_id for update;
    perform value.lease_id
    from scoring_authority.scoring_ingress_leases value
    where value.tournament_id = pointer.tournament_id
      and value.admission_generation_id = annual.admission_generation_id
    order by value.lease_id for update;
    unresolved := production_control.annual_scoring_unresolved_count_v1(
      pointer.tournament_id, annual.admission_generation_id
    );
    unresolved_outbox := 0; -- Retired external delivery is not required work.
    unresolved_archive := 0; -- Canonical snapshots already committed; export is retired.
    select pg_catalog.count(*)::integer into post_close_count
    from scoring_authority.scoring_ingress_leases value
    where value.tournament_id = pointer.tournament_id
      and value.admission_generation_id = annual.admission_generation_id
      and value.admission_sequence > closure.lease_high_watermark;
    update production_control.annual_scoring_runtime_authorities_v1 set
      admission_revision = admission_revision + 1,
      updated_at = pg_catalog.clock_timestamp()
    where runtime_generation_id = annual.runtime_generation_id
    returning * into annual;
    if unresolved <> 0 or unresolved_outbox <> 0
       or unresolved_archive <> 0 or post_close_count <> 0 then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'code', 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_DRAINING',
        'transitionId', target_transition_id,
        'predecessorTournamentId', pointer.tournament_id,
        'successorTournamentId', target.tournament_id,
        'closureId', closure.closure_id,
        'activeOrUnresolvedLeases', unresolved,
        'unresolvedOutbox', unresolved_outbox,
        'unresolvedArchive', unresolved_archive,
        'postCloseLeaseCount', post_close_count,
        'pointerChanged', false, 'predecessorClosed', false,
        'successorActivated', false, 'idempotent', false
      );
    end if;
    lease_fingerprint :=
      production_control.annual_scoring_lease_fingerprint_v1(
        pointer.tournament_id, annual.admission_generation_id
      );
    revisions := production_control.current_match_revisions(
      pointer.tournament_id
    );
    checkpoints := production_control.current_google_checkpoints(
      pointer.tournament_id
    );
    update production_control.scoring_admission_closures set
      status = 'CLOSED',
      closed_admission_revision = annual.admission_revision + 1,
      final_source_fingerprint =
        pg_catalog.lower(input->>'final_source_fingerprint'),
      reconciliation_fingerprint =
        pg_catalog.lower(input->>'reconciliation_fingerprint'),
      lease_set_fingerprint = lease_fingerprint,
      supabase_match_revisions = revisions,
      google_checkpoints = checkpoints,
      closed_at = pg_catalog.clock_timestamp()
    where closure_id = closure.closure_id
      and status = 'CLOSING'
    returning * into closure;
    if not found then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_ANNUAL_SCORING_DRAIN_REVISION_CONFLICT';
    end if;
    update production_control.annual_scoring_runtime_authorities_v1 set
      authority_status = 'CLOSED', admission_state = 'CLOSED',
      admission_revision = admission_revision + 1,
      closed_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp()
    where runtime_generation_id = annual.runtime_generation_id;
  end if;

  certificate :=
    production_control.annual_scoring_predecessor_certificate_v1(
      pointer.tournament_id
    );
  readiness := production_control.annual_scoring_transition_readiness_v1(
    target.tournament_id
  );
  if coalesce((certificate->>'certified')::boolean, false) is not true
     or coalesce((readiness->>'ready')::boolean, false) is not true then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_CERTIFICATION_REQUIRED',
      detail = coalesce((readiness->'blockers')::text, '[]');
  end if;
  update production_control.future_annual_runtime_generations_v1 set
    readiness_fingerprint = readiness->>'fingerprint',
    runtime_revision = runtime_revision + 1,
    updated_at = pg_catalog.clock_timestamp()
  where runtime_generation_id = generation.runtime_generation_id
    and generation_status = 'PREPARED';
  update production_control.future_tournament_catalog_v1 set
    readiness_fingerprint = readiness->>'fingerprint',
    readiness_setup_revision = setup_revision,
    updated_by_player_id = actor_player,
    updated_by_auth_user_id = actor_auth,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target.tournament_id
    and lifecycle = 'READY_FOR_ACTIVATION'
    and lifecycle_revision = target.lifecycle_revision;
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PRECOMMIT_ABORTED';
  end if;
  update production_control.future_runtime_promotions_v2 set
    runtime_status = 'READY', updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target.tournament_id;
  update production_control.annual_scoring_transitions_v1 set
    transition_status = 'CLOSED',
    predecessor_boundary_fingerprint = certificate->>'fingerprint',
    readiness_fingerprint = readiness->>'fingerprint',
    updated_at = pg_catalog.clock_timestamp()
  where transition_id = transition_value.transition_id
    and transition_status = 'CLOSING';
  perform production_control.assert_future_scoring_runtime_capability_v1(
    target.tournament_id, generation.runtime_generation_id,
    generation.authority_generation_id, generation.admission_generation_id
  );
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_CLOSED',
    'transitionId', transition_value.transition_id,
    'predecessorTournamentId', pointer.tournament_id,
    'successorTournamentId', target.tournament_id,
    'expectedPointerRevision', pointer.pointer_revision,
    'runtimeGenerationId', generation.runtime_generation_id,
    'authorityGenerationId', generation.authority_generation_id,
    'admissionGenerationId', generation.admission_generation_id,
    'readinessFingerprint', readiness->>'fingerprint',
    'pointerChanged', false, 'predecessorClosed', true,
    'successorActivated', false, 'idempotent', false
  );
end;
$$;


ALTER FUNCTION production_control.advance_annual_scoring_transition_v1(target_transition_id uuid, input jsonb) OWNER TO postgres;

--
-- Name: allocate_global_course_id_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.allocate_global_course_id_v1() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  allocator production_control.global_course_id_allocator_v1%rowtype;
  candidate text;
begin
  select value.* into strict allocator
  from production_control.global_course_id_allocator_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  loop
    if allocator.next_number > 999999 then
      raise exception using errcode = '54000',
        message = 'PRODUCTION_GLOBAL_COURSE_ID_SPACE_EXHAUSTED';
    end if;
    candidate := 'CRS' || pg_catalog.lpad(
      allocator.next_number::text, 6, '0'
    );
    allocator.next_number := allocator.next_number + 1;
    exit when not exists (
      select 1 from scoring_authority.global_course_library_v1 value
      where value.course_id = candidate
    );
  end loop;
  update production_control.global_course_id_allocator_v1 set
    next_number = allocator.next_number,
    allocator_revision = allocator_revision + 1,
    updated_at = pg_catalog.clock_timestamp()
  where scope_key = 'BAGGER_INV_PRODUCTION';
  return candidate;
end;
$$;


ALTER FUNCTION production_control.allocate_global_course_id_v1() OWNER TO postgres;

--
-- Name: annual_calcutta_resource_fingerprint_v1(text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_calcutta_resource_fingerprint_v1(target text, runtime_generation uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select production_control.calcutta_v1_hash(
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-annual-calcutta-v1',
      'environment', 'PRODUCTION',
      'project_ref', resource.project_ref,
      'project_url', resource.project_url,
      'source_workbook_id', resource.source_workbook_id,
      'tournament_id', target,
      'runtime_generation_id', runtime_generation,
      'pointer_revision', pointer.pointer_revision,
      'lifecycle_revision', pointer.lifecycle_revision
    )
  )
  from production_control.future_tournament_resources_v1 resource
  join production_control.current_tournament_pointer_v1 pointer
    on pointer.scope_key = 'BAGGER_INV_PRODUCTION'
   and pointer.tournament_id = resource.tournament_id
  where resource.tournament_id = target
$$;


ALTER FUNCTION production_control.annual_calcutta_resource_fingerprint_v1(target text, runtime_generation uuid) OWNER TO postgres;

--
-- Name: annual_odds_pairing_fingerprint_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_odds_pairing_fingerprint_v1(target_tournament_id text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target text := pg_catalog.btrim(coalesce(target_tournament_id, ''));
  catalog production_control.future_tournament_catalog_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  manifest jsonb;
begin
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target;
  select value.* into promotion
  from production_control.future_runtime_promotions_v2 value
  where value.tournament_id = target;
  manifest := pg_catalog.jsonb_build_object(
    'contractVersion', 'production-annual-odds-pairing-context-v1',
    'tournamentId', target,
    'setupRevision', catalog.setup_revision,
    'promotionRevision', coalesce(promotion.promotion_revision, 0),
    'promotionFingerprint', coalesce(
      promotion.promoted_manifest_fingerprint, ''
    ),
    'matches', coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'matchId', match_value.match_id,
        'roundNumber', match_value.round_number,
        'format', match_value.format,
        'status', match_value.status,
        'snapshotId', match_value.scoring_snapshot_id,
        'snapshotHash', coalesce(snapshot.canonical_hash, ''),
        'preparedSetupRevision', detail.prepared_setup_revision,
        'configurationFingerprint', coalesce(
          detail.prepared_configuration_fingerprint, ''
        ),
        'participants', coalesce((select pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'playerId', participant.player_id,
            'teamId', roster.team_id,
            'teamSide', participant.team_side,
            'playerSlot', participant.player_slot,
            'handicapRevisionId', participant.handicap_revision_id
          ) order by participant.team_side, participant.player_slot)
          from scoring_authority.match_participants participant
          left join scoring_authority.tournament_players roster
            on roster.tournament_id = target
           and roster.player_id = participant.player_id
          where participant.match_id = match_value.match_id), '[]'::jsonb)
      ) order by match_value.round_number, match_value.match_id)
      from scoring_authority.matches match_value
      left join scoring_authority.tournament_setup_match_details_v1 detail
        on detail.match_id = match_value.match_id
      left join scoring_authority.scoring_snapshots snapshot
        on snapshot.snapshot_id = match_value.scoring_snapshot_id
      where match_value.tournament_id = target), '[]'::jsonb)
  );
  return production_control.future_runtime_hash_v2(manifest);
exception when no_data_found then
  raise exception using errcode = '55000',
    message = 'PRODUCTION_ANNUAL_ODDS_PAIRING_CONTEXT_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.annual_odds_pairing_fingerprint_v1(target_tournament_id text) OWNER TO postgres;

