--
-- Name: annual_resource_context_v2(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_resource_context_v2() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;
 s production_control.resource_scope%rowtype;p production_control.current_tournament_pointer_v1%rowtype;
begin
 select * into strict r from production_control.canonical_resource_v1 where singleton;
 if r.resource_class='CERTIFICATION' then return production_control.current_canonical_resource_context_v1();end if;
 select * into strict s from production_control.resource_scope where scope_key='BAGGER_INV_PRODUCTION';
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=s.scope_key;
 return jsonb_build_object('resource_class','PRODUCTION','resource_id',s.scope_key,'project_ref',s.project_ref,
  'project_url',s.project_url,'provenance_id',s.google_workbook_id,'installation_id',r.installation_id,
  'registration_revision',r.registration_revision,'manifest_digest',r.manifest_digest,'schema_digest',r.schema_digest,
  'current_tournament_id',p.tournament_id,'current_tournament_year',p.tournament_year,'pointer_revision',p.pointer_revision,
  'lifecycle_revision',p.lifecycle_revision,'governance_tournament_id','2026');
end;$$;


ALTER FUNCTION production_control.annual_resource_context_v2() OWNER TO postgres;

--
-- Name: annual_scoring_lease_fingerprint_v1(text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_scoring_lease_fingerprint_v1(target_tournament_id text, target_admission_generation_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select pg_catalog.encode(extensions.digest(
    coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'lease_id', lease.lease_id,
      'admission_sequence', lease.admission_sequence,
      'match_id', lease.match_id,
      'operation', lease.operation,
      'resolution_state', lease.resolution_state,
      'provider_readback_fingerprint', lease.provider_readback_fingerprint,
      'resolution_fingerprint', lease.resolution_fingerprint
    ) order by lease.admission_sequence, lease.lease_id), '[]'::jsonb)::text,
    'sha256'
  ), 'hex')
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = target_tournament_id
    and lease.admission_generation_id = target_admission_generation_id
$$;


ALTER FUNCTION production_control.annual_scoring_lease_fingerprint_v1(target_tournament_id text, target_admission_generation_id uuid) OWNER TO postgres;

--
-- Name: annual_scoring_platform_certification_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_scoring_platform_certification_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  certification
    production_control.annual_scoring_platform_certifications_v1%rowtype;
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  release production_control.postcutover_application_release_rebindings%rowtype;
  normal_head production_control.postcutover_normal_release_head%rowtype;
  normal_release
    production_control.postcutover_normal_release_rebindings%rowtype;
  binding production_control.maintenance_deployment_capability_bindings%rowtype;
  deployment_value text;
  commit_value text;
  contract_value text;
  ceiling_value text;
  resource_hash text;
  certification_hash text;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  select value.* into strict certification
  from production_control.annual_scoring_platform_certifications_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = certification.scope_key;
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = certification.scope_key;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = certification.platform_tournament_id;
  -- The immutable row is adoption evidence, not a release pin.  Every call
  -- still proves the currently bound release and capability; a legitimate
  -- serial application-release rebind can advance these values, while a stale
  -- or unbound deployment remains rejected.
  select value.* into normal_head
  from production_control.postcutover_normal_release_head value
  where value.scope_key = certification.scope_key;
  if found then
    select value.* into strict normal_release
    from production_control.postcutover_normal_release_rebindings value
    where value.release_rebind_id = normal_head.release_rebind_id
      and value.release_sequence = normal_head.release_sequence;
    select value.* into strict binding
    from production_control.maintenance_deployment_capability_bindings value
    where value.capability_binding_id = normal_release.capability_binding_id;
    deployment_value := normal_release.deployment_id;
    commit_value := normal_release.deployment_commit;
    contract_value := normal_release.capability_contract;
    ceiling_value := normal_release.capability_ceiling;
  else
    select value.* into release
    from production_control.postcutover_application_release_rebindings value
    where value.scope_key = certification.scope_key;
    if found then
      select value.* into strict binding
      from production_control.maintenance_deployment_capability_bindings value
      where value.capability_binding_id = release.capability_binding_id;
      deployment_value := release.deployment_id;
      commit_value := release.deployment_commit;
      contract_value := release.capability_contract;
      ceiling_value := release.capability_ceiling;
    else
      select value.* into strict binding
      from production_control.maintenance_deployment_capability_bindings value
      where value.epoch_id = activation.authority_generation_id;
      deployment_value := binding.deployment_id;
      commit_value := binding.deployment_commit;
      contract_value := binding.contract_version;
      ceiling_value := binding.capability_ceiling;
    end if;
  end if;
  if input->>'deployment_id' is distinct from deployment_value
       or pg_catalog.lower(coalesce(input->>'deployment_commit', ''))
         is distinct from commit_value
       or input->>'deployment_capability_contract'
         is distinct from contract_value
       or input->>'deployment_capability_ceiling'
         is distinct from ceiling_value
       or activation.expected_deployment_commit is distinct from
         commit_value
       or gate.admission_deployment_id is distinct from deployment_value
       or binding.capability_fingerprint is distinct from pg_catalog.encode(
         extensions.digest(binding.capability_manifest::text, 'sha256'), 'hex'
       ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_CURRENT_RELEASE_REQUIRED';
  end if;
  resource_hash := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'environment', 'PRODUCTION',
      'scopeKey', resource.scope_key,
      'projectRef', resource.project_ref,
      'projectUrl', resource.project_url,
      'sourceWorkbookId', resource.google_workbook_id,
      'platformTournamentId', certification.platform_tournament_id
    )
  );
  certification_hash := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion', certification.contract_version,
      'resourceFingerprint', resource_hash,
      'authorityGenerationId', certification.authority_generation_id,
      'admissionGenerationId', certification.admission_generation_id,
      'deploymentId', certification.deployment_id,
      'deploymentCommit', certification.deployment_commit,
      'capabilityContract', certification.capability_contract,
      'capabilityCeiling', certification.capability_ceiling
    )
  );
  if resource.current_tournament_id <> '2026'
     or resource.current_tournament_year <> 2026
     or resource.project_ref is distinct from certification.project_ref
     or resource.project_url is distinct from certification.project_url
     or resource.google_workbook_id is distinct from
       certification.source_workbook_id
     or resource_hash is distinct from certification.resource_fingerprint
     or activation.authority_generation_id is distinct from
       certification.authority_generation_id
     or gate.admission_generation_id is distinct from
       certification.admission_generation_id
     or certification_hash is distinct from
       certification.certification_fingerprint then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_CERTIFICATION_REQUIRED';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'contractVersion', certification.contract_version,
    'platformTournamentId', certification.platform_tournament_id,
    'platformAuthorityGenerationId',
      certification.authority_generation_id,
    'platformAdmissionGenerationId',
      certification.admission_generation_id,
    'adoptionDeploymentId', certification.deployment_id,
    'adoptionDeploymentCommit', certification.deployment_commit,
    'adoptionCapabilityContract', certification.capability_contract,
    'adoptionCapabilityCeiling', certification.capability_ceiling,
    'resourceFingerprint', certification.resource_fingerprint,
    'certificationFingerprint', certification.certification_fingerprint
  );
end;
$$;


ALTER FUNCTION production_control.annual_scoring_platform_certification_v1(input jsonb) OWNER TO postgres;

--
-- Name: annual_scoring_predecessor_certificate_pre_derived_workers_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_scoring_predecessor_certificate_pre_derived_workers_v1(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  baseline jsonb;
  blockers jsonb;
  runtime_generation uuid;
  net_skins_unresolved integer;
  calcutta_unresolved integer;
  odds_unresolved integer;
  odds_mirror_rows integer;
  generation_mismatch integer;
  fingerprint_value text;
begin
  baseline := production_control
    .annual_scoring_predecessor_certificate_pre_side_games_v1(
      target_tournament_id
    );
  blockers := coalesce(baseline->'blockers', '[]'::jsonb);
  if target_tournament_id <> '2026' then
    select value.runtime_generation_id into runtime_generation
    from production_control.annual_scoring_runtime_authorities_v1 value
    where value.tournament_id = target_tournament_id;
  end if;

  select pg_catalog.count(*)::integer into net_skins_unresolved
  from scoring_authority.net_skins_v1_recalculation_jobs value
  where value.tournament_id = target_tournament_id
    and value.status not in ('SUCCEEDED', 'SUPERSEDED');
  select pg_catalog.count(*)::integer into calcutta_unresolved
  from scoring_authority.calcutta_v1_recalculation_jobs value
  where value.tournament_id = target_tournament_id
    and value.status not in ('SUCCEEDED', 'SUPERSEDED');
  select pg_catalog.count(*)::integer into odds_unresolved
  from scoring_authority.odds_calculation_jobs value
  where value.tournament_id = target_tournament_id
    and not (
      (value.status = 'FAILED'
        and value.publication_status = 'NOT_REQUESTED')
      or (value.status = 'SUPERSEDED'
        and value.publication_status = 'STALE')
      or (value.status = 'SUCCEEDED'
        and value.publication_status in ('PUBLISHED', 'REHEARSAL_ONLY'))
    );
  odds_mirror_rows := 0; -- External mirror retired.

  generation_mismatch := 0;
  if target_tournament_id <> '2026' then
    select (
      (select pg_catalog.count(*)
       from scoring_authority.net_skins_v1_recalculation_jobs value
       where value.tournament_id = target_tournament_id
         and value.status not in ('SUCCEEDED', 'SUPERSEDED')
         and value.runtime_generation_id is distinct from runtime_generation)
      +
      (select pg_catalog.count(*)
       from scoring_authority.calcutta_v1_recalculation_jobs value
       where value.tournament_id = target_tournament_id
         and value.status not in ('SUCCEEDED', 'SUPERSEDED')
         and value.runtime_generation_id is distinct from runtime_generation)
      +
      (select pg_catalog.count(*)
       from scoring_authority.odds_calculation_jobs value
       where value.tournament_id = target_tournament_id
         and not (
           (value.status = 'FAILED'
             and value.publication_status = 'NOT_REQUESTED')
           or (value.status = 'SUPERSEDED'
             and value.publication_status = 'STALE')
           or (value.status = 'SUCCEEDED'
             and value.publication_status in ('PUBLISHED', 'REHEARSAL_ONLY'))
         )
         and value.runtime_generation_id is distinct from runtime_generation)

    )::integer into generation_mismatch;
  end if;

  if net_skins_unresolved <> 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      'PREDECESSOR_NET_SKINS_DRAIN_INCOMPLETE'
    );
  end if;
  if calcutta_unresolved <> 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      'PREDECESSOR_CALCUTTA_DRAIN_INCOMPLETE'
    );
  end if;
  if odds_unresolved <> 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      'PREDECESSOR_ODDS_DRAIN_INCOMPLETE'
    );
  end if;

  if generation_mismatch <> 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      'PREDECESSOR_SIDE_GAME_GENERATION_MISMATCH'
    );
  end if;

  fingerprint_value := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion',
        'production-annual-scoring-side-game-close-certificate-v1',
      'baselineFingerprint', baseline->>'fingerprint',
      'tournamentId', target_tournament_id,
      'runtimeGenerationId', runtime_generation,
      'netSkinsUnresolved', net_skins_unresolved,
      'calcuttaUnresolved', calcutta_unresolved,
      'oddsUnresolved', odds_unresolved,
      'oddsMirrorRows', odds_mirror_rows,
      'generationMismatch', generation_mismatch,
      'blockers', blockers
    )
  );
  return baseline || pg_catalog.jsonb_build_object(
    'certified', pg_catalog.jsonb_array_length(blockers) = 0,
    'fingerprint', fingerprint_value,
    'blockers', blockers,
    'sideGameDrain', pg_catalog.jsonb_build_object(
      'runtimeGenerationId', runtime_generation,
      'netSkinsUnresolved', net_skins_unresolved,
      'calcuttaUnresolved', calcutta_unresolved,
      'oddsUnresolved', odds_unresolved,
      'oddsMirrorRows', odds_mirror_rows,
      'generationMismatch', generation_mismatch
    )
  );
end;
$$;


ALTER FUNCTION production_control.annual_scoring_predecessor_certificate_pre_derived_workers_v1(target_tournament_id text) OWNER TO postgres;

--
-- Name: annual_scoring_predecessor_certificate_pre_side_games_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_scoring_predecessor_certificate_pre_side_games_v1(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  legacy_root production_control.scoring_admission_closures%rowtype;
  authority_generation uuid;
  admission_generation uuid;
  blocker_values jsonb := '[]'::jsonb;
  fingerprint_value text;
  unresolved_leases integer;
  legacy_blockers integer := 0;
  post_close_lease_count integer := 0;
  unresolved_outbox integer;
  unresolved_archive integer;
begin
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION')then
    return production_control.certification_annual_predecessor_certificate_v1(target_tournament_id);
  end if;
  if target_tournament_id = '2026' then
    select value.* into strict activation
    from production_control.cutover_activation_state value
    where value.scope_key = 'BAGGER_INV_PRODUCTION';
    select value.* into strict gate
    from scoring_authority.ingress_gates value
    where value.tournament_id = '2026';
    select value.* into closure
    from production_control.scoring_admission_closures value
    where value.closure_id = gate.active_closure_id;
    authority_generation := activation.authority_generation_id;
    admission_generation := gate.admission_generation_id;
    if closure.closure_kind = 'SUPABASE_INGRESS' then
      select value.* into legacy_root
      from production_control.scoring_admission_closures value
      where value.closure_id = closure.prior_legacy_closure_id;
    else
      legacy_root := closure;
    end if;
    if gate.state <> 'PAUSED' or gate.admission_state <> 'CLOSED'
       or closure.closure_id is null
       or closure.tournament_id <> '2026'
       or closure.closure_kind <> 'SUPABASE_INGRESS'
       or closure.authority <> 'SUPABASE'
       or closure.status <> 'CLOSED'
       or closure.authority_generation_id is distinct from
         authority_generation
       or closure.admission_generation_id is distinct from
         admission_generation
       or legacy_root.closure_kind <> 'LEGACY_ADMISSION'
       or legacy_root.status <> 'CONSUMED' then
      blocker_values := blocker_values || pg_catalog.jsonb_build_array(
        'PREDECESSOR_SCORING_ADMISSION_NOT_CLOSED'
      );
    end if;
  else
    select value.* into annual
    from production_control.annual_scoring_runtime_authorities_v1 value
    where value.tournament_id = target_tournament_id;
    select value.* into closure
    from production_control.scoring_admission_closures value
    where value.closure_id = annual.active_closure_id;
    select value.* into legacy_root
    from production_control.scoring_admission_closures value
    where value.closure_id = annual.legacy_root_closure_id;
    authority_generation := annual.authority_generation_id;
    admission_generation := annual.admission_generation_id;
    if annual.runtime_generation_id is null
       or annual.authority_status <> 'CLOSED'
       or annual.admission_state <> 'CLOSED'
       or closure.closure_id is null
       or closure.tournament_id <> target_tournament_id
       or closure.closure_kind <> 'SUPABASE_INGRESS'
       or closure.authority <> 'SUPABASE'
       or closure.status <> 'CLOSED'
       or closure.authority_generation_id is distinct from
         authority_generation
       or closure.admission_generation_id is distinct from
         admission_generation
       or legacy_root.closure_kind <> 'LEGACY_ADMISSION'
       or legacy_root.status <> 'CONSUMED' then
      blocker_values := blocker_values || pg_catalog.jsonb_build_array(
        'PREDECESSOR_SCORING_ADMISSION_NOT_CLOSED'
      );
    end if;
  end if;
  unresolved_leases :=
    production_control.annual_scoring_unresolved_count_v1(
      target_tournament_id, admission_generation
    );
  if target_tournament_id = '2026' then
    legacy_blockers :=
      production_control.scoring_admission_legacy_blocker_count(
        gate.admission_enforced_at
      );
  end if;
  select pg_catalog.count(*)::integer into post_close_lease_count
  from scoring_authority.scoring_ingress_leases value
  where value.tournament_id = target_tournament_id
    and value.admission_generation_id = admission_generation
    and value.admission_sequence > closure.lease_high_watermark;
  unresolved_outbox := 0; -- Retired external delivery is not required work.
  unresolved_archive := 0; -- Canonical snapshots already committed; export is retired.
  if unresolved_leases <> 0 or legacy_blockers <> 0
     or post_close_lease_count <> 0 or unresolved_outbox <> 0
     or unresolved_archive <> 0 then
    blocker_values := blocker_values || pg_catalog.jsonb_build_array(
      'PREDECESSOR_SCORING_DRAIN_INCOMPLETE'
    );
  end if;
  if not exists (
       select 1 from scoring_authority.matches value
       where value.tournament_id = target_tournament_id
     ) or exists (
       select 1 from scoring_authority.matches value
       where value.tournament_id = target_tournament_id
         and (value.status <> 'FINAL' or not value.scorecard_complete
           or value.unresolved_mutations <> 0)
     ) then
    blocker_values := blocker_values || pg_catalog.jsonb_build_array(
      'PREDECESSOR_FINAL_SCORING_FACTS_REQUIRED'
    );
  end if;
  fingerprint_value := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-annual-scoring-close-certificate-v1',
      'tournamentId', target_tournament_id,
      'closureId', closure.closure_id,
      'legacyRootClosureId', legacy_root.closure_id,
      'authorityGenerationId', authority_generation,
      'admissionGenerationId', admission_generation,
      'closedAdmissionRevision', closure.closed_admission_revision,
      'leaseSetFingerprint', closure.lease_set_fingerprint,
      'matchRevisions', closure.supabase_match_revisions,
      'googleCheckpoints', closure.google_checkpoints,
      'unresolvedLeases', unresolved_leases,
      'legacyAdmissionBlockers', legacy_blockers,
      'postCloseLeaseCount', post_close_lease_count,
      'unresolvedOutbox', unresolved_outbox,
      'unresolvedArchive', unresolved_archive
    )
  );
  return pg_catalog.jsonb_build_object(
    'certified', pg_catalog.jsonb_array_length(blocker_values) = 0,
    'tournamentId', target_tournament_id,
    'closureId', closure.closure_id,
    'legacyRootClosureId', legacy_root.closure_id,
    'authorityGenerationId', authority_generation,
    'admissionGenerationId', admission_generation,
    'legacyAdmissionBlockers', legacy_blockers,
    'postCloseLeaseCount', post_close_lease_count,
    'fingerprint', fingerprint_value,
    'blockers', blocker_values
  );
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'certified', false, 'tournamentId', target_tournament_id,
    'fingerprint', null,
    'blockers', pg_catalog.jsonb_build_array(
      'PREDECESSOR_SCORING_CLOSE_CERTIFICATE_UNAVAILABLE'
    )
  );
end;
$$;


ALTER FUNCTION production_control.annual_scoring_predecessor_certificate_pre_side_games_v1(target_tournament_id text) OWNER TO postgres;

--
-- Name: annual_scoring_predecessor_certificate_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_scoring_predecessor_certificate_v1(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  baseline jsonb;
  blockers jsonb;
  runtime_generation uuid;
  competition_unresolved integer;
  intelligence_unresolved integer;
  competition_generation_mismatch integer := 0;
  intelligence_generation_mismatch integer := 0;
  fingerprint_value text;
begin
  baseline := production_control
    .annual_scoring_predecessor_certificate_pre_derived_workers_v1(
      target_tournament_id
    );
  blockers := coalesce(baseline->'blockers', '[]'::jsonb);
  if target_tournament_id <> '2026' then
    select value.runtime_generation_id into runtime_generation
    from production_control.annual_scoring_runtime_authorities_v1 value
    where value.tournament_id = target_tournament_id;
  end if;
  select pg_catalog.count(*)::integer into competition_unresolved
  from scoring_authority.competition_recalculation_jobs value
  where value.tournament_id = target_tournament_id
    and value.round_number = 0
    and value.engine_key in ('TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES')
    and value.status <> 'SUCCEEDED';
  select pg_catalog.count(*)::integer into intelligence_unresolved
  from scoring_authority.competition_recalculation_jobs value
  where value.tournament_id = target_tournament_id
    and value.round_number = 0
    and value.engine_key in (
      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
      'TOURNAMENT_FINAL_RECAP'
    )
    and value.status <> 'SUCCEEDED';
  if target_tournament_id <> '2026' then
    select pg_catalog.count(*)::integer
      into competition_generation_mismatch
    from scoring_authority.competition_recalculation_jobs value
    where value.tournament_id = target_tournament_id
      and value.round_number = 0
      and value.engine_key in ('TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES')
      and value.status <> 'SUCCEEDED'
      and value.runtime_generation_id is distinct from runtime_generation;
    select pg_catalog.count(*)::integer
      into intelligence_generation_mismatch
    from scoring_authority.competition_recalculation_jobs value
    where value.tournament_id = target_tournament_id
      and value.round_number = 0
      and value.engine_key in (
        'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
        'TOURNAMENT_FINAL_RECAP'
      )
      and value.status <> 'SUCCEEDED'
      and value.runtime_generation_id is distinct from runtime_generation;
  end if;
  if competition_unresolved + intelligence_unresolved <> 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      'PREDECESSOR_DERIVED_WORK_DRAIN_INCOMPLETE'
    );
  end if;
  if competition_generation_mismatch
       + intelligence_generation_mismatch <> 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      'PREDECESSOR_DERIVED_WORK_GENERATION_MISMATCH'
    );
  end if;
  if production_control.score_derived_intents_pending_v1(target_tournament_id) then
    blockers := blockers || jsonb_build_array('PREDECESSOR_SCORE_DERIVED_INTENTS_PENDING');
  end if;
  fingerprint_value := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion',
        'production-annual-scoring-derived-worker-close-certificate-v1',
      'baselineFingerprint', baseline->>'fingerprint',
      'tournamentId', target_tournament_id,
      'runtimeGenerationId', runtime_generation,
      'competitionUnresolved', competition_unresolved,
      'intelligenceUnresolved', intelligence_unresolved,
      'competitionGenerationMismatch',
        competition_generation_mismatch,
      'intelligenceGenerationMismatch',
        intelligence_generation_mismatch,
      'blockers', blockers
    )
  );
  return baseline || pg_catalog.jsonb_build_object(
    'certified', pg_catalog.jsonb_array_length(blockers) = 0,
    'fingerprint', fingerprint_value,
    'blockers', blockers,
    'derivedWorkerDrain', pg_catalog.jsonb_build_object(
      'runtimeGenerationId', runtime_generation,
      'competitionUnresolved', competition_unresolved,
      'intelligenceUnresolved', intelligence_unresolved,
      'competitionGenerationMismatch',
        competition_generation_mismatch,
      'intelligenceGenerationMismatch',
        intelligence_generation_mismatch
    )
  );
end;
$$;


ALTER FUNCTION production_control.annual_scoring_predecessor_certificate_v1(target_tournament_id text) OWNER TO postgres;

--
-- Name: annual_scoring_transition_readiness_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_scoring_transition_readiness_v1(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  baseline jsonb;
  certificate jsonb;
  blockers jsonb;
  fingerprint_value text;
begin
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = production_control.canonical_annual_scope_key_v2();
  baseline := production_control.future_runtime_readiness_v2(
    target_tournament_id
  );
  select coalesce(pg_catalog.jsonb_agg(value), '[]'::jsonb)
    into blockers
  from pg_catalog.jsonb_array_elements(
    coalesce(baseline->'blockers', '[]'::jsonb)
  ) value
  where value->>'code' <>
    'FUTURE_PREDECESSOR_SCORING_CLOSE_FENCE_NOT_CERTIFIED';
  -- Preserve069's missing-certificate denial for Production only. Certification
  -- retains its separately admitted origin and does not acquire this certificate.
  if production_control.canonical_annual_scope_key_v2() = 'BAGGER_INV_PRODUCTION'
     and not exists (
       select 1 from production_control.annual_scoring_platform_certifications_v1
       where scope_key = 'BAGGER_INV_PRODUCTION'
     ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PRODUCTION_ANNUAL_SCORING_PLATFORM_CERTIFICATION_REQUIRED',
        'section', 'Activation',
        'message', 'Annual activation requires its lawful platform certification.'
      )
    );
  end if;
  certificate :=
    production_control.annual_scoring_predecessor_certificate_v1(
      pointer.tournament_id
    );
  if coalesce((certificate->>'certified')::boolean, false) is not true then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'FUTURE_PREDECESSOR_SCORING_CLOSE_FENCE_NOT_CERTIFIED',
        'section', 'Activation',
        'message', 'The current tournament scoring close and drain boundary is not certified.',
        'details', certificate->'blockers'
      )
    );
  end if;
  fingerprint_value := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-annual-scoring-transition-readiness-v1',
      'targetTournamentId', target_tournament_id,
      'predecessorTournamentId', pointer.tournament_id,
      'expectedPointerRevision', pointer.pointer_revision,
      'baselineFingerprint', baseline->>'fingerprint',
      'predecessorBoundaryFingerprint', certificate->>'fingerprint',
      'blockers', blockers
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'contractVersion',
      'production-annual-scoring-transition-readiness-v1',
    'targetTournamentId', target_tournament_id,
    'predecessorTournamentId', pointer.tournament_id,
    'expectedPointerRevision', pointer.pointer_revision,
    'ready', pg_catalog.jsonb_array_length(blockers) = 0,
    'fingerprint', fingerprint_value,
    'predecessorCertificate', certificate,
    'blockers', blockers
  );
end;
$$;


ALTER FUNCTION production_control.annual_scoring_transition_readiness_v1(target_tournament_id text) OWNER TO postgres;

--
-- Name: annual_scoring_unresolved_count_v1(text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_scoring_unresolved_count_v1(target_tournament_id text, target_admission_generation_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select pg_catalog.count(*)::integer
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = target_tournament_id
    and lease.admission_generation_id = target_admission_generation_id
    and lease.resolution_state in (
      'ADMITTED', 'WRITE_STARTED', 'AMBIGUOUS', 'PARTIAL_WRITE',
      'LEGACY_UNCLASSIFIED'
    )
$$;


ALTER FUNCTION production_control.annual_scoring_unresolved_count_v1(target_tournament_id text, target_admission_generation_id uuid) OWNER TO postgres;

--
-- Name: annual_side_game_implementation_manifest_pre_delivery_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_side_game_implementation_manifest_pre_delivery_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare baseline jsonb; helpers jsonb; column_manifest jsonb; valid_count integer;
begin
  baseline:=production_control.annual_side_game_implementation_manifest_pre_score_recovery_v1();
  select jsonb_agg(jsonb_build_object('signature',signature,'source',p.prosrc,
      'securityDefiner',p.prosecdef,'configuration',p.proconfig,'acl',p.proacl) order by signature),
    count(*) filter(where p.prosecdef and p.proconfig=array['search_path=pg_catalog']::text[]
      and not has_function_privilege('anon',p.oid,'EXECUTE')
      and not has_function_privilege('authenticated',p.oid,'EXECUTE')
      and has_function_privilege('service_role',p.oid,'EXECUTE')=exposed)::integer
    into helpers,valid_count
  from (values
    ('production_control.read_score_mutation_status_v1(jsonb,text)',false),
    ('public.read_production_score_mutation_status_v1(jsonb)',true),
    ('production_control.annual_side_game_implementation_manifest_pre_score_recovery_v1()',false)
  ) required(signature,exposed) left join pg_proc p on p.oid=to_regprocedure(signature);
  if valid_count<>3 then
    raise exception using errcode='55000',message='SCORE_RECOVERY_HELPER_SECURITY_REQUIRED';
  end if;
  select jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod),
    'notNull',attnotnull) into column_manifest from pg_attribute
    where attrelid='scoring_authority.score_mutations'::regclass
      and attname='originating_auth_user_id' and not attisdropped and atttypid='uuid'::regtype;
  if column_manifest is null then
    raise exception using errcode='55000',message='SCORE_RECOVERY_ORIGIN_COLUMN_REQUIRED';
  end if;
  return baseline||jsonb_build_object('scoreRecoveryContract','score-mutation-recovery-v1',
    'scoreRecoveryHelpers',helpers,'scoreRecoveryOriginColumn',column_manifest,
    'scoreRecoveryCanonical2026Source',(select prosrc from pg_proc
      where oid='public.submit_production_hole_score(jsonb)'::regprocedure));
end;
$$;


ALTER FUNCTION production_control.annual_side_game_implementation_manifest_pre_delivery_v1() OWNER TO postgres;

--
-- Name: annual_side_game_implementation_manifest_pre_score_intents_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_side_game_implementation_manifest_pre_score_intents_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  baseline jsonb;
  trigger_manifest jsonb;
  derived_trigger_function_manifest jsonb;
  derived_trigger_function_secure boolean;
  valid_count integer;
begin
  baseline := production_control
    .annual_side_game_implementation_manifest_pre_triggers_v1();
  -- The trigger catalog proves where events are routed; separately retain the
  -- exact executable definition they reach. This closes the gap where all
  -- nine bindings remain intact while the shared trigger function body or
  -- privilege topology changes after certification.
  select pg_catalog.jsonb_build_object(
      'signature',
        'scoring_authority.enqueue_annual_derived_v1_change()',
      'source', procedure_value.prosrc,
      'securityDefiner', procedure_value.prosecdef,
      'volatility', procedure_value.provolatile::text,
      'configuration', coalesce(
        pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
      ),
      'acl', coalesce(
        pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
      ),
      'definitionFingerprint', production_control.future_runtime_hash_v2(
        pg_catalog.jsonb_build_object(
          'source', procedure_value.prosrc,
          'securityDefiner', procedure_value.prosecdef,
          'volatility', procedure_value.provolatile::text,
          'configuration', coalesce(
            pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
          ),
          'acl', coalesce(
            pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
          )
        )
      ),
      'effectiveExecute', pg_catalog.jsonb_build_object(
        'anon', pg_catalog.has_function_privilege(
          'anon', procedure_value.oid, 'EXECUTE'
        ),
        'authenticated', pg_catalog.has_function_privilege(
          'authenticated', procedure_value.oid, 'EXECUTE'
        ),
        'serviceRole', pg_catalog.has_function_privilege(
          'service_role', procedure_value.oid, 'EXECUTE'
        )
      )
    ),
    procedure_value.prosecdef
      and procedure_value.provolatile::text = 'v'
      and coalesce(
        procedure_value.proconfig, array[]::text[]
      ) = array['search_path=pg_catalog']::text[]
      and not pg_catalog.has_function_privilege(
        'anon', procedure_value.oid, 'EXECUTE'
      )
      and not pg_catalog.has_function_privilege(
        'authenticated', procedure_value.oid, 'EXECUTE'
      )
      and not pg_catalog.has_function_privilege(
        'service_role', procedure_value.oid, 'EXECUTE'
      )
  into derived_trigger_function_manifest, derived_trigger_function_secure
  from pg_catalog.pg_proc procedure_value
  where procedure_value.oid = pg_catalog.to_regprocedure(
    'scoring_authority.enqueue_annual_derived_v1_change()'
  );
  if derived_trigger_function_manifest is null
     or derived_trigger_function_secure is not true then
    raise exception using errcode = '55000',
      message =
        'PRODUCTION_ANNUAL_DERIVED_TRIGGER_FUNCTION_SECURITY_REQUIRED';
  end if;

  with expected(
    ordinal, table_schema, table_name, trigger_name, target_function,
    trigger_type, update_columns
  ) as (values
    (1, 'scoring_authority', 'hole_scores',
      'production_annual_net_skins_v1_hole_score_recalculation',
      'scoring_authority.enqueue_annual_net_skins_v1_change()',
      29, array[]::text[]),
    (2, 'scoring_authority', 'matches',
      'production_annual_net_skins_v1_match_lifecycle_recalculation',
      'scoring_authority.enqueue_annual_net_skins_v1_change()',
      17, array[
        'finalized_at', 'match_revision', 'scorecard_complete', 'status'
      ]::text[]),
    (3, 'scoring_authority', 'hole_scores',
      'production_calcutta_v1_hole_score_recalculation',
      'scoring_authority.enqueue_production_calcutta_v1_change()',
      29, array[]::text[]),
    (4, 'scoring_authority', 'matches',
      'production_calcutta_v1_match_lifecycle_recalculation',
      'scoring_authority.enqueue_production_calcutta_v1_change()',
      17, array[
        'finalized_at', 'match_revision', 'result_winner',
        'scorecard_complete', 'status'
      ]::text[]),
    (5, 'scoring_authority', 'rounds',
      'production_calcutta_v1_round_lifecycle_recalculation',
      'scoring_authority.enqueue_production_calcutta_v1_change()',
      17, array['status']::text[]),
    (6, 'scoring_authority', 'hole_scores',
      'production_annual_derived_v1_hole_score_change',
      'scoring_authority.enqueue_annual_derived_v1_change()',
      29, array[]::text[]),
    (7, 'scoring_authority', 'matches',
      'production_annual_derived_v1_match_change',
      'scoring_authority.enqueue_annual_derived_v1_change()',
      17, array[
        'finalized_at', 'match_revision', 'result_winner',
        'scorecard_complete', 'status'
      ]::text[]),
    (8, 'scoring_authority', 'odds_published_snapshots',
      'production_annual_derived_v1_odds_publication_change',
      'scoring_authority.enqueue_annual_derived_v1_change()',
      21, array[
        'is_current_official', 'payload_hash', 'publication_revision'
      ]::text[]),
    (9, 'scoring_authority', 'net_skins_v1_result_revisions',
      'production_annual_derived_v1_net_skins_result_change',
      'scoring_authority.enqueue_annual_derived_v1_change()',
      21, array[
        'is_current', 'payload_hash', 'result_revision'
      ]::text[])
  ), actual as (
    select expected.*, trigger_value.oid as trigger_oid,
      trigger_value.tgenabled::text as enabled,
      trigger_value.tgtype::integer as actual_trigger_type,
      trigger_value.tgnargs::integer as actual_argument_count,
      trigger_value.tgqual is null as predicate_absent,
      trigger_value.tgconstraint = 0 as constraint_absent,
      not trigger_value.tgdeferrable as non_deferrable,
      not trigger_value.tginitdeferred as initially_immediate,
      procedure_value.oid::pg_catalog.regprocedure::text as actual_function,
      coalesce((
        select pg_catalog.array_agg(attribute_value.attname::text order by
          attribute_value.attname)
        from pg_catalog.unnest(
          trigger_value.tgattr::smallint[]
        ) as attribute_number(attnum)
        join pg_catalog.pg_attribute attribute_value
          on attribute_value.attrelid = trigger_value.tgrelid
         and attribute_value.attnum = attribute_number.attnum
      ), array[]::text[]) as actual_update_columns,
      case when trigger_value.oid is null then null
        else pg_catalog.pg_get_triggerdef(trigger_value.oid, true) end
        as definition
    from expected
    left join pg_catalog.pg_namespace namespace_value
      on namespace_value.nspname = expected.table_schema
    left join pg_catalog.pg_class table_value
      on table_value.relnamespace = namespace_value.oid
     and table_value.relname = expected.table_name
    left join pg_catalog.pg_trigger trigger_value
      on trigger_value.tgrelid = table_value.oid
     and trigger_value.tgname = expected.trigger_name
     and not trigger_value.tgisinternal
    left join pg_catalog.pg_proc procedure_value
      on procedure_value.oid = trigger_value.tgfoid
  ), projected as (
    select *, trigger_oid is not null and enabled = 'O'
      and actual_trigger_type = trigger_type
      and actual_argument_count = 0 and predicate_absent
      and constraint_absent and non_deferrable and initially_immediate
      and actual_function = target_function
      and actual_update_columns = update_columns as valid
    from actual
  )
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'table', table_schema || '.' || table_name,
      'trigger', trigger_name,
      'targetFunction', actual_function,
      'triggerType', actual_trigger_type,
      'argumentCount', actual_argument_count,
      'predicateAbsent', predicate_absent,
      'constraintAbsent', constraint_absent,
      'nonDeferrable', non_deferrable,
      'initiallyImmediate', initially_immediate,
      'updateColumns', actual_update_columns,
      'enabled', enabled,
      'definition', definition
    ) order by ordinal),
    pg_catalog.count(*) filter (where valid)::integer
  into trigger_manifest, valid_count
  from projected;
  if valid_count <> 9 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_TRIGGER_BINDING_REQUIRED';
  end if;
  return baseline || pg_catalog.jsonb_build_object(
    'derivedTriggerFunctionContract',
      'production-annual-derived-trigger-function-v1',
    'derivedTriggerFunction', derived_trigger_function_manifest,
    'triggerBindingContract',
      'production-annual-side-game-trigger-bindings-v1',
    'triggerBindings', trigger_manifest
  );
end;
$$;


ALTER FUNCTION production_control.annual_side_game_implementation_manifest_pre_score_intents_v1() OWNER TO postgres;

--
-- Name: annual_side_game_implementation_manifest_pre_score_recovery_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_side_game_implementation_manifest_pre_score_recovery_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare baseline jsonb; helper_manifest jsonb; expected_count integer; valid_count integer;
  table_manifest jsonb; index_manifest jsonb;
begin
  baseline := production_control.annual_side_game_implementation_manifest_pre_score_intents_v1();
  select jsonb_agg(jsonb_build_object('signature', signature, 'source', p.prosrc,
      'securityDefiner', p.prosecdef, 'volatility', p.provolatile,
      'configuration', p.proconfig, 'acl', p.proacl) order by signature),
    count(*)::integer, count(*) filter (where p.prosecdef
      and p.proconfig = array['search_path=pg_catalog']::text[]
      and not has_function_privilege('anon', p.oid, 'EXECUTE')
      and not has_function_privilege('authenticated', p.oid, 'EXECUTE')
      and not has_function_privilege('service_role', p.oid, 'EXECUTE'))::integer
    into helper_manifest, expected_count, valid_count
  from (values
    ('production_control.append_score_derived_intent_v1(text,text,integer,text,text,jsonb,uuid)'),
    ('production_control.flush_score_derived_intents_v1(text,text,integer)'),
    ('production_control.score_derived_intents_pending_v1(text)'),
    ('production_control.annual_side_game_implementation_manifest_pre_score_intents_v1()')
  ) required(signature) left join pg_proc p on p.oid = to_regprocedure(signature);
  if expected_count <> 4 or valid_count <> 4 then
    raise exception using errcode = '55000', message = 'SCORE_DERIVED_INTENT_HELPER_SECURITY_REQUIRED';
  end if;
  select jsonb_build_object('rls', relrowsecurity, 'acl', relacl,
      'constraints', (select jsonb_agg(pg_get_constraintdef(oid) order by conname)
        from pg_constraint where conrelid = table_row.oid))
    into table_manifest from pg_class table_row
    where table_row.oid = 'scoring_authority.score_derived_intents_v1'::regclass
      and relrowsecurity
      and not has_table_privilege('anon', table_row.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
      and not has_table_privilege('authenticated', table_row.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
      and not has_table_privilege('service_role', table_row.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER');
  if table_manifest is null then
    raise exception using errcode = '55000', message = 'SCORE_DERIVED_INTENT_TABLE_SECURITY_REQUIRED';
  end if;
  select jsonb_agg(pg_get_indexdef(indexrelid) order by indexrelid::regclass::text)
    into index_manifest from pg_index
    where indrelid = 'scoring_authority.score_derived_intents_v1'::regclass;
  return baseline || jsonb_build_object('scoreDerivedIntentContract', 'score-derived-intent-v1',
    'scoreDerivedIntentHelpers', helper_manifest, 'scoreDerivedIntentTable', table_manifest,
    'scoreDerivedIntentIndexes', index_manifest);
end;
$$;


ALTER FUNCTION production_control.annual_side_game_implementation_manifest_pre_score_recovery_v1() OWNER TO postgres;

--
-- Name: annual_side_game_implementation_manifest_pre_triggers_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_side_game_implementation_manifest_pre_triggers_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  core_runtime_signatures constant text[] := array[
    'production_control.assert_annual_scoring_runtime_v1(jsonb,text,text)',
    'production_control.assert_annual_scoring_runtime_pre_side_games_v1(jsonb,text,text)',
    'production_control.assert_annual_scoring_platform_v1(jsonb,text,text)',
    'production_control.annual_scoring_platform_certification_v1(jsonb)',
    'production_control.assert_future_production_scoring_runtime_v1(jsonb,text)',
    'production_control.assert_future_scoring_runtime_capability_v1(text,uuid,uuid,uuid)',
    'production_control.assert_future_scoring_runtime_capability_pre_side_games_v1(text,uuid,uuid,uuid)'
  ];
  core_runtime_volatility constant text[] := array[
    'v', 'v', 's', 's', 'v', 'v', 's'
  ];
  odds_signatures constant text[] := array[
    'public.dispatch_production_annual_odds_v1(jsonb)',
    'public.future_production_dispatch_odds_v1(jsonb)',
    'public.read_published_odds_view(text,text)',
    'production_control.assert_annual_odds_runtime_v1(jsonb,text)',
    'production_control.current_annual_odds_inputs_v1(text,text,jsonb,boolean)',
    'production_control.current_annual_odds_inputs_before_pairing_context_v1(text,text,jsonb,boolean)',
    'production_control.annual_odds_pairing_fingerprint_v1(text)',
    'production_control.materialize_future_annual_odds_inputs_v1(jsonb,jsonb)',
    'public.synchronize_production_future_annual_projection_v1(jsonb)',
    'public.synchronize_production_future_annual_projection_before_odds_v1(jsonb)',
    'production_control.assert_annual_odds_job_scope_v1(jsonb,text,scoring_authority.odds_calculation_jobs)',
    'production_control.annual_odds_publication_projection_v1(text)',
    'production_control.publish_annual_odds_v1(jsonb,text)'
  ];
  net_skins_signatures constant text[] := array[
    'public.future_production_configure_net_skins_v1(jsonb)',
    'public.future_production_enqueue_net_skins_recalculation_v1(jsonb)',
    'public.future_production_claim_net_skins_recalculation_v1(jsonb)',
    'public.future_production_complete_net_skins_recalculation_v1(jsonb)',
    'public.future_production_fail_net_skins_recalculation_v1(jsonb)',
    'production_control.assert_annual_net_skins_v1(jsonb,text)',
    'production_control.read_annual_net_skins_v1(text)',
    'production_control.build_annual_net_skins_v1_manifest(text,integer[])',
    'production_control.enqueue_annual_net_skins_v1_round(text,uuid,integer,text,text)',
    'production_control.normalize_annual_net_skins_v1_official_result(text,integer,jsonb)',
    'scoring_authority.enqueue_annual_net_skins_v1_change()'
  ];
  calcutta_signatures constant text[] := array[
    'public.future_production_configure_calcutta_v1(jsonb)',
    'public.future_production_replace_calcutta_auction_facts_v1(jsonb)',
    'public.future_production_publish_calcutta_v1(jsonb)',
    'public.future_production_unpublish_calcutta_v1(jsonb)',
    'public.future_production_enqueue_calcutta_recalculation_v1(jsonb)',
    'public.future_production_claim_calcutta_recalculation_v1(jsonb)',
    'public.future_production_complete_calcutta_recalculation_v1(jsonb)',
    'public.future_production_fail_calcutta_recalculation_v1(jsonb)',
    'public.future_production_inspect_calcutta_v1(jsonb)',
    'public.future_production_resolve_calcutta_postcommit_match_v1(jsonb)',
    'public.resolve_production_calcutta_postcommit_match_v1(jsonb)',
    'production_control.assert_annual_calcutta_runtime_v1(jsonb,text)',
    'production_control.annual_calcutta_resource_fingerprint_v1(text,uuid)',
    'production_control.build_annual_calcutta_v1_configuration(jsonb,text)',
    'production_control.build_annual_calcutta_v1_auction(jsonb,text)',
    'production_control.enqueue_annual_calcutta_v1(text,uuid,bigint,text,text,boolean,text,text)',
    'production_control.mutate_annual_calcutta_publication_v1(jsonb,boolean)',
    'production_control.project_annual_calcutta_v1_result(text,jsonb)',
    'production_control.validate_annual_calcutta_v1_result(text,text,jsonb)',
    'production_control.project_production_calcutta_v1_result(jsonb)',
    'production_control.project_production_calcutta_v1_result_frozen_2026_v1(jsonb)',
    'production_control.read_annual_calcutta_v1(text,text)', 'production_control.read_annual_calcutta_v1(text,text,uuid)', 'production_control.native_calcutta_reader_v1(text,text,uuid)', 'public.read_native_review_context_v1(uuid,text)',
    'scoring_authority.enqueue_production_calcutta_v1_change()'
  ];
  odds_manifest jsonb;
  net_skins_manifest jsonb;
  calcutta_manifest jsonb;
  core_runtime_manifest jsonb;
  core_runtime_count integer;
  secure_core_runtime_count integer;
  odds_operations jsonb;
  net_skins_operations jsonb;
  calcutta_operations jsonb;
  annual_target_manifest jsonb;
  annual_target_count integer;
  enabled_target_count integer;
  exposed_target_count integer;
  dispatcher_manifest jsonb;
  dispatcher_is_security_definer boolean;
  dispatcher_has_fixed_path boolean;
  dispatcher_anon_execute boolean;
  dispatcher_authenticated_execute boolean;
  dispatcher_service_execute boolean;
begin
  -- The side-game certificate is also the final release gate for the central
  -- annual resolver/assertion chain. Bind both sides of every wrapper added by
  -- this migration: otherwise a post-certification replacement of the
  -- predecessor can preserve the wrapper body while changing what PREPARE,
  -- scoring, or ACTIVATE actually proves. Raw pg_proc evidence and effective
  -- privileges are retained in deterministic signature order.
  with expected as (
    select requested.signature, requested.ordinality,
      core_runtime_volatility[requested.ordinality::integer]
        as expected_volatility
    from pg_catalog.unnest(core_runtime_signatures) with ordinality
      requested(signature, ordinality)
  )
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'signature', expected.signature,
      'source', procedure_value.prosrc,
      'securityDefiner', procedure_value.prosecdef,
      'volatility', procedure_value.provolatile::text,
      'configuration', coalesce(
        pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
      ),
      'acl', coalesce(
        pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
      ),
      'definitionFingerprint', production_control.future_runtime_hash_v2(
        pg_catalog.jsonb_build_object(
          'source', procedure_value.prosrc,
          'securityDefiner', procedure_value.prosecdef,
          'volatility', procedure_value.provolatile::text,
          'configuration', coalesce(
            pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
          ),
          'acl', coalesce(
            pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
          )
        )
      ),
      'effectiveExecute', pg_catalog.jsonb_build_object(
        'anon', pg_catalog.has_function_privilege(
          'anon', procedure_value.oid, 'EXECUTE'
        ),
        'authenticated', pg_catalog.has_function_privilege(
          'authenticated', procedure_value.oid, 'EXECUTE'
        ),
        'serviceRole', pg_catalog.has_function_privilege(
          'service_role', procedure_value.oid, 'EXECUTE'
        )
      )
    ) order by expected.ordinality),
    pg_catalog.count(procedure_value.oid)::integer,
    pg_catalog.count(*) filter (where
      procedure_value.oid is not null
      and procedure_value.prosecdef
      and procedure_value.provolatile::text = expected.expected_volatility
      and coalesce(
        procedure_value.proconfig, array[]::text[]
      ) = array['search_path=pg_catalog']::text[]
      and not pg_catalog.has_function_privilege(
        'anon', procedure_value.oid, 'EXECUTE'
      )
      and not pg_catalog.has_function_privilege(
        'authenticated', procedure_value.oid, 'EXECUTE'
      )
      and not pg_catalog.has_function_privilege(
        'service_role', procedure_value.oid, 'EXECUTE'
      )
    )::integer
  into core_runtime_manifest, core_runtime_count,
    secure_core_runtime_count
  from expected
  left join pg_catalog.pg_proc procedure_value
    on procedure_value.oid = pg_catalog.to_regprocedure(expected.signature);

  if core_runtime_count <> pg_catalog.cardinality(core_runtime_signatures)
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CORE_RUNTIME_IMPLEMENTATION_REQUIRED';
  end if;
  if secure_core_runtime_count <>
       pg_catalog.cardinality(core_runtime_signatures) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CORE_RUNTIME_SECURITY_REQUIRED';
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'signature', requested.signature,
    'definitionFingerprint', production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'source', procedure_value.prosrc,
        'securityDefiner', procedure_value.prosecdef,
        'volatility', procedure_value.provolatile::text,
        'configuration', coalesce(
          pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
        ),
        'acl', coalesce(
          pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
        )
      )
    )
  ) order by requested.ordinality) into odds_manifest
  from pg_catalog.unnest(odds_signatures) with ordinality
    requested(signature, ordinality)
  join pg_catalog.pg_proc procedure_value
    on procedure_value.oid = pg_catalog.to_regprocedure(requested.signature);

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'signature', requested.signature,
    'definitionFingerprint', production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'source', procedure_value.prosrc,
        'securityDefiner', procedure_value.prosecdef,
        'volatility', procedure_value.provolatile::text,
        'configuration', coalesce(
          pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
        ),
        'acl', coalesce(
          pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
        )
      )
    )
  ) order by requested.ordinality) into net_skins_manifest
  from pg_catalog.unnest(net_skins_signatures) with ordinality
    requested(signature, ordinality)
  join pg_catalog.pg_proc procedure_value
    on procedure_value.oid = pg_catalog.to_regprocedure(requested.signature);

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'signature', requested.signature,
    'definitionFingerprint', production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'source', procedure_value.prosrc,
        'securityDefiner', procedure_value.prosecdef,
        'volatility', procedure_value.provolatile::text,
        'configuration', coalesce(
          pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
        ),
        'acl', coalesce(
          pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
        )
      )
    )
  ) order by requested.ordinality) into calcutta_manifest
  from pg_catalog.unnest(calcutta_signatures) with ordinality
    requested(signature, ordinality)
  join pg_catalog.pg_proc procedure_value
    on procedure_value.oid = pg_catalog.to_regprocedure(requested.signature);

  if pg_catalog.jsonb_array_length(coalesce(odds_manifest, '[]'::jsonb))
       <> pg_catalog.cardinality(odds_signatures)
     or pg_catalog.jsonb_array_length(
       coalesce(net_skins_manifest, '[]'::jsonb)
     ) <> pg_catalog.cardinality(net_skins_signatures)
     or pg_catalog.jsonb_array_length(
       coalesce(calcutta_manifest, '[]'::jsonb)
     ) <> pg_catalog.cardinality(calcutta_signatures) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_IMPLEMENTATION_REQUIRED';
  end if;

  -- Direct annual targets accept the operation name as part of their bounded
  -- dispatcher input. They must therefore never be executable by an API role:
  -- only the generic dispatcher may be exposed to service_role. Use effective
  -- privilege checks so role-membership or PUBLIC grants cannot be hidden by
  -- hashing the raw ACL alone.
  select pg_catalog.count(*)::integer into enabled_target_count
  from production_control.annual_scoring_rpc_allowlist_v1 value
  where value.enabled;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'operation', allowlist.operation_name,
      'target', allowlist.target_rpc,
      'securityDefiner', procedure_value.prosecdef,
      'configuration', coalesce(
        pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
      ),
      'definitionFingerprint', production_control.future_runtime_hash_v2(
        pg_catalog.jsonb_build_object(
          'source', procedure_value.prosrc,
          'securityDefiner', procedure_value.prosecdef,
          'volatility', procedure_value.provolatile::text,
          'configuration', coalesce(
            pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
          ),
          'acl', coalesce(
            pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
          )
        )
      ),
      'effectiveExecute', pg_catalog.jsonb_build_object(
        'anon', pg_catalog.has_function_privilege(
          'anon', procedure_value.oid, 'EXECUTE'
        ),
        'authenticated', pg_catalog.has_function_privilege(
          'authenticated', procedure_value.oid, 'EXECUTE'
        ),
        'serviceRole', pg_catalog.has_function_privilege(
          'service_role', procedure_value.oid, 'EXECUTE'
        )
      )
    ) order by allowlist.operation_name),
    pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter (where
      pg_catalog.has_function_privilege(
        'anon', procedure_value.oid, 'EXECUTE'
      ) or pg_catalog.has_function_privilege(
        'authenticated', procedure_value.oid, 'EXECUTE'
      ) or pg_catalog.has_function_privilege(
        'service_role', procedure_value.oid, 'EXECUTE'
      )
    )::integer
  into annual_target_manifest, annual_target_count, exposed_target_count
  from production_control.annual_scoring_rpc_allowlist_v1 allowlist
  join pg_catalog.pg_proc procedure_value on procedure_value.oid =
    pg_catalog.to_regprocedure(allowlist.target_rpc || '(jsonb)')
  where allowlist.enabled;

  select pg_catalog.jsonb_build_object(
      'signature',
        'public.dispatch_production_annual_scoring_v1(jsonb)',
      'securityDefiner', procedure_value.prosecdef,
      'configuration', coalesce(
        pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
      ),
      'definitionFingerprint', production_control.future_runtime_hash_v2(
        pg_catalog.jsonb_build_object(
          'source', procedure_value.prosrc,
          'securityDefiner', procedure_value.prosecdef,
          'volatility', procedure_value.provolatile::text,
          'configuration', coalesce(
            pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
          ),
          'acl', coalesce(
            pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
          )
        )
      ),
      'effectiveExecute', pg_catalog.jsonb_build_object(
        'anon', pg_catalog.has_function_privilege(
          'anon', procedure_value.oid, 'EXECUTE'
        ),
        'authenticated', pg_catalog.has_function_privilege(
          'authenticated', procedure_value.oid, 'EXECUTE'
        ),
        'serviceRole', pg_catalog.has_function_privilege(
          'service_role', procedure_value.oid, 'EXECUTE'
        )
      )
    ), procedure_value.prosecdef,
    coalesce(procedure_value.proconfig, array[]::text[])
      @> array['search_path=pg_catalog']::text[],
    pg_catalog.has_function_privilege(
      'anon', procedure_value.oid, 'EXECUTE'
    ),
    pg_catalog.has_function_privilege(
      'authenticated', procedure_value.oid, 'EXECUTE'
    ),
    pg_catalog.has_function_privilege(
      'service_role', procedure_value.oid, 'EXECUTE'
    )
  into dispatcher_manifest, dispatcher_is_security_definer,
    dispatcher_has_fixed_path, dispatcher_anon_execute,
    dispatcher_authenticated_execute, dispatcher_service_execute
  from pg_catalog.pg_proc procedure_value
  where procedure_value.oid = pg_catalog.to_regprocedure(
    'public.dispatch_production_annual_scoring_v1(jsonb)'
  );

  if annual_target_count is distinct from enabled_target_count
     or exposed_target_count <> 0
     or dispatcher_manifest is null
     or dispatcher_is_security_definer is not true
     or dispatcher_has_fixed_path is not true
     or dispatcher_anon_execute is not false
     or dispatcher_authenticated_execute is not false
     or dispatcher_service_execute is not true then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_DISPATCH_PRIVILEGE_TOPOLOGY_REQUIRED';
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'operation', value.operation_name,
    'target', value.target_rpc,
    'phase', value.required_phase,
    'class', value.operation_class,
    'worker', value.required_worker
  ) order by value.operation_name) into odds_operations
  from production_control.annual_scoring_rpc_allowlist_v1 value
  where value.operation_name = 'dispatch_production_annual_odds_v1'
    and value.enabled;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'operation', value.operation_name,
    'target', value.target_rpc,
    'phase', value.required_phase,
    'class', value.operation_class,
    'worker', value.required_worker
  ) order by value.operation_name) into net_skins_operations
  from production_control.annual_scoring_rpc_allowlist_v1 value
  where value.operation_name in (
    'configure_production_net_skins_v1',
    'enqueue_production_net_skins_v1_recalculation',
    'claim_production_net_skins_v1_recalculation',
    'complete_production_net_skins_v1_recalculation',
    'fail_production_net_skins_v1_recalculation'
  ) and value.enabled;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'operation', value.operation_name,
    'target', value.target_rpc,
    'phase', value.required_phase,
    'class', value.operation_class,
    'worker', value.required_worker
  ) order by value.operation_name) into calcutta_operations
  from production_control.annual_scoring_rpc_allowlist_v1 value
  where value.operation_name in (
    'configure_production_calcutta_v1',
    'replace_production_calcutta_v1_auction_facts',
    'publish_production_calcutta_v1',
    'unpublish_production_calcutta_v1',
    'enqueue_production_calcutta_v1_recalculation',
    'claim_production_calcutta_v1_recalculation',
    'complete_production_calcutta_v1_recalculation',
    'fail_production_calcutta_v1_recalculation',
    'inspect_production_calcutta_v1',
    'resolve_production_calcutta_postcommit_match_v1'
  ) and value.enabled;

  if pg_catalog.jsonb_array_length(coalesce(odds_operations, '[]'::jsonb)) <> 1
     or pg_catalog.jsonb_array_length(
       coalesce(net_skins_operations, '[]'::jsonb)
     ) <> 5
     or pg_catalog.jsonb_array_length(
       coalesce(calcutta_operations, '[]'::jsonb)
     ) <> 10 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_ALLOWLIST_REQUIRED';
  end if;

  return pg_catalog.jsonb_build_object(
    'contractVersion', 'production-annual-side-game-implementation-v1',
    'coreRuntime', pg_catalog.jsonb_build_object(
      'contractVersion', 'production-annual-core-runtime-manifest-v1',
      'functions', core_runtime_manifest
    ),
    'annualDispatchSecurity', pg_catalog.jsonb_build_object(
      'contractVersion', 'production-annual-dispatch-privileges-v1',
      'dispatcher', dispatcher_manifest,
      'targets', annual_target_manifest
    ),
    'odds', pg_catalog.jsonb_build_object(
      'functions', odds_manifest,
      'annualDispatcher', odds_operations,
      'operations', (
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'operation', value.operation_name,
          'class', value.operation_class,
          'enabled', value.enabled
        ) order by value.operation_name)
        from production_control.annual_odds_operation_allowlist_v1 value
      )
    ),
    'netSkins', pg_catalog.jsonb_build_object(
      'functions', net_skins_manifest,
      'operations', net_skins_operations
    ),
    'calcutta', pg_catalog.jsonb_build_object(
      'functions', calcutta_manifest,
      'operations', calcutta_operations
    )
  );
end;
$$;


ALTER FUNCTION production_control.annual_side_game_implementation_manifest_pre_triggers_v1() OWNER TO postgres;

--
-- Name: annual_side_game_implementation_manifest_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.annual_side_game_implementation_manifest_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare baseline jsonb; helper_manifest jsonb; queue_manifest jsonb; table_manifest jsonb; required_count integer; valid_count integer;
begin
 baseline:=production_control.annual_side_game_implementation_manifest_pre_delivery_v1();
 select jsonb_agg(jsonb_build_object('signature',signature,'source',p.prosrc,'acl',p.proacl,
   'definer',p.prosecdef,'configuration',p.proconfig) order by signature),count(*),
   count(*) filter(where p.prosecdef and p.proconfig=array['search_path=pg_catalog']::text[]
    and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE')
    and (has_function_privilege('service_role',p.oid,'EXECUTE')=is_public))
 into helper_manifest,required_count,valid_count from (values
  ('production_control.lock_net_skins_storylines_v1(text,jsonb)',false),
  ('production_control.derived_final_recap_ready_v1(text)',false),
  ('production_control.capture_derived_delivery_provenance_v1()',false),
  ('production_control.capture_derived_intent_attempt_v1()',false),
  ('production_control.recover_derived_calcutta_activation_v1(text)',false),
  ('production_control.derived_delivery_retryable_v1(text)',false),
  ('production_control.derived_delivery_delay_v1(integer,text)',false),
  ('production_control.capture_derived_delivery_transition_v1()',false),
  ('production_control.assert_score_derived_delivery_scope_v1(jsonb)',false),
  ('production_control.intelligence_delivery_ready_v1(text,jsonb)',false),
  ('production_control.annual_side_game_implementation_manifest_pre_delivery_v1()',false),
  ('public.future_production_score_derived_delivery_tick_v1(jsonb)',false),
  ('public.future_production_requeue_score_derived_delivery_v1(jsonb)',false),
  ('public.future_production_fail_intelligence_derived_bundle_v1(jsonb)',false),
  ('public.future_production_fail_score_derived_preclaim_v1(jsonb)',false),
  ('public.score_derived_delivery_tick_v1(jsonb)',true),
  ('public.fail_score_derived_preclaim_v1(jsonb)',true),
  ('public.requeue_score_derived_delivery_v1(jsonb)',true),
  ('public.fail_intelligence_derived_bundle_v1(jsonb)',true)
 )required(signature,is_public) left join pg_proc p on p.oid=to_regprocedure(signature);
 if required_count<>19 or valid_count<>19 then raise exception 'DERIVED_DELIVERY_HELPER_SECURITY_REQUIRED'; end if;
 -- The clone preserves its reviewed predecessor search_path and all other attributes.
 if has_function_privilege('service_role','production_control.enqueue_score_calcutta_v1(text,text,boolean,text,text)','EXECUTE')
  or has_function_privilege('anon','production_control.enqueue_score_calcutta_v1(text,text,boolean,text,text)','EXECUTE')
  or has_function_privilege('authenticated','production_control.enqueue_score_calcutta_v1(text,text,boolean,text,text)','EXECUTE') then
  raise exception 'DERIVED_DELIVERY_PRIVATE_ENQUEUE_REQUIRED'; end if;
 select jsonb_agg(jsonb_build_object('table',c.relname,'rls',c.relrowsecurity,'acl',c.relacl,
  'columns',(select jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod),'notNull',attnotnull)
    order by attnum) from pg_attribute where attrelid=c.oid and attnum>0 and not attisdropped),
  'constraints',(select jsonb_agg(pg_get_constraintdef(oid) order by conname) from pg_constraint where conrelid=c.oid),
  'indexes',(select jsonb_agg(pg_get_indexdef(indexrelid) order by indexrelid::regclass::text) from pg_index where indrelid=c.oid),
  'triggers',(select jsonb_agg(pg_get_triggerdef(oid) order by tgname) from pg_trigger where tgrelid=c.oid and not tgisinternal)) order by c.relname)
 into queue_manifest from pg_class c where c.oid in('scoring_authority.calcutta_v1_recalculation_jobs'::regclass,
  'scoring_authority.net_skins_v1_recalculation_jobs'::regclass,'scoring_authority.competition_recalculation_jobs'::regclass,
  'scoring_authority.score_derived_intents_v1'::regclass);
 select jsonb_build_object('rls',relrowsecurity,'acl',relacl,
  'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,
     'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
     where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
  'constraints',(select jsonb_agg(pg_get_constraintdef(oid) order by conname) from pg_constraint where conrelid=c.oid),
  'indexes',(select jsonb_agg(pg_get_indexdef(indexrelid) order by indexrelid::regclass::text) from pg_index where indrelid=c.oid),
  'triggers',(select jsonb_agg(pg_get_triggerdef(oid) order by tgname) from pg_trigger where tgrelid=c.oid and not tgisinternal),
  'sequenceAcl',(select relacl from pg_class where oid='production_control.score_derived_delivery_attempts_v1_event_id_seq'::regclass))
 into table_manifest from pg_class c
 where c.oid='production_control.score_derived_delivery_attempts_v1'::regclass and relrowsecurity
  and not has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
  and not has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
  and not has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER');
 if table_manifest is null then raise exception 'DERIVED_DELIVERY_ATTEMPT_SECURITY_REQUIRED'; end if;
 return baseline||jsonb_build_object('googleRuntimeContract','google-runtime-retired-v1','scoreDerivedDeliveryContract','score-derived-delivery-v1',
  'scoreDerivedDeliveryHelpers',helper_manifest,'scoreDerivedDeliveryQueues',queue_manifest,
  'scoreDerivedDeliveryAttempts',table_manifest,'scoreDerivedCalcuttaWorkerLocks',
  (select jsonb_agg(jsonb_build_object('signature',signature,'source',p.prosrc,'acl',p.proacl,
    'owner',p.proowner,'definer',p.prosecdef,'configuration',p.proconfig) order by signature)
   from (values
    ('public.claim_production_calcutta_v1_recalculation(jsonb)'),
    ('public.complete_production_calcutta_v1_recalculation(jsonb)'),
    ('public.fail_production_calcutta_v1_recalculation(jsonb)'),
    ('public.future_production_claim_calcutta_recalculation_v1(jsonb)'),
    ('public.future_production_complete_calcutta_recalculation_v1(jsonb)'),
    ('public.future_production_fail_calcutta_recalculation_v1(jsonb)')
   ) required(signature) join pg_proc p on p.oid=signature::regprocedure),
  'scoreDerivedNetSkinsCompletionLocks',
  (select jsonb_agg(jsonb_build_object('signature',signature,'source',p.prosrc,'acl',p.proacl,
    'owner',p.proowner,'definer',p.prosecdef,'configuration',p.proconfig) order by signature)
   from (values ('public.complete_production_net_skins_v1_recalculation(jsonb)'),
    ('public.future_production_complete_net_skins_recalculation_v1(jsonb)')) required(signature)
   join pg_proc p on p.oid=signature::regprocedure),
  'scoreDerivedCurrentEnqueue',
  (select jsonb_build_object('source',prosrc,'acl',proacl,'definer',prosecdef,'configuration',proconfig)
   from pg_proc where oid='production_control.enqueue_score_calcutta_v1(text,text,boolean,text,text)'::regprocedure));
end;
$$;


ALTER FUNCTION production_control.annual_side_game_implementation_manifest_v1() OWNER TO postgres;

--
-- Name: append_score_derived_intent_v1(text, text, integer, text, text, jsonb, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.append_score_derived_intent_v1(target text, target_match text, target_round integer, family_value text, reason_value text, revision_value jsonb, generation_value uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  insert into scoring_authority.score_derived_intents_v1 as stored (
    tournament_id, match_id, round_number, source_transaction, family,
    reason, canonical_revision, runtime_generation_id
  ) values (
    target, target_match, target_round, txid_current(), family_value,
    reason_value, revision_value, generation_value
  ) on conflict (tournament_id, match_id, source_transaction, family)
  do update set reason = excluded.reason,
    canonical_revision = stored.canonical_revision || excluded.canonical_revision,
    status = 'PENDING', attempts = 0, last_sqlstate = null,
    completed_at = null, available_at = clock_timestamp(),
    updated_at = clock_timestamp();
end;
$$;


ALTER FUNCTION production_control.append_score_derived_intent_v1(target text, target_match text, target_round integer, family_value text, reason_value text, revision_value jsonb, generation_value uuid) OWNER TO postgres;

--
-- Name: apply_expired_identity_recovery_v1(uuid, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_expired_identity_recovery_v1(approval uuid, expected_plan_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare reviewed production_control.expired_identity_recovery_approvals_v1%rowtype;
 receipt production_control.expired_identity_recovery_receipts_v1%rowtype;
 before_state jsonb; after_state jsonb; result text;
begin
 perform production_control.expired_identity_operator_guard_v1();
 perform production_control.expired_identity_lock_v1();
 perform production_control.expired_identity_operator_guard_v1();
 select * into reviewed from production_control.expired_identity_recovery_approvals_v1 where approval_id=approval for update;
 if not found or reviewed.plan_hash is distinct from expected_plan_hash then raise exception 'EXPIRED_IDENTITY_APPROVAL_REQUIRED'; end if;
 perform production_control.assert_access_governance_owner_v1('2026',reviewed.actor_player_id,reviewed.actor_auth_user_id);
 before_state := production_control.inspect_expired_identity_recovery_v1(reviewed.target_player_id,reviewed.target_auth_user_id,reviewed.historical_request_id);
 if before_state->'authority' is distinct from reviewed.expected_state->'authority' then raise exception 'EXPIRED_IDENTITY_REVIEW_STALE'; end if;
 select * into receipt from production_control.expired_identity_recovery_receipts_v1 where approval_id=approval;
 if found then
  if before_state->>'state'<>'COMPLETE'
   or encode(extensions.digest(before_state::text,'sha256'),'hex') is distinct from receipt.after_state_hash then
   raise exception 'EXPIRED_IDENTITY_RECEIPT_DRIFT'; end if;
  return jsonb_build_object('ok',true,'status','ALREADY_COMPLETE','approvalId',approval,'sessionIssued',false);
 end if;
 if reviewed.expires_at<=clock_timestamp() then raise exception 'EXPIRED_IDENTITY_APPROVAL_EXPIRED'; end if;
 if before_state->>'state'='COMPLETE' then
  if (before_state->>'linkRevision')::bigint is distinct from (reviewed.expected_state->>'linkRevision')::bigint+1
   or (before_state->>'identifierRevision')::bigint is distinct from (reviewed.expected_state->>'identifierRevision')::bigint+1
   or not exists(select 1 from participant_identity.participant_auth_otp_attempts where request_id=reviewed.historical_request_id and status='VERIFIED') then
   raise exception 'EXPIRED_IDENTITY_UNRECEIPTED_COMPLETION'; end if;
  result := 'ALREADY_COMPLETED_BY_NORMAL_LOGIN';
 else
  if before_state is distinct from reviewed.expected_state then raise exception 'EXPIRED_IDENTITY_REVIEW_STALE'; end if;
  update participant_identity.user_player_links set status='ACTIVE',link_revision=link_revision+1,
   linked_at=coalesce(linked_at,clock_timestamp()),linked_by='owner-reviewed-expired-certification-recovery',updated_at=clock_timestamp()
   where auth_user_id=reviewed.target_auth_user_id and player_id=reviewed.target_player_id and status='PENDING';
  update participant_identity.participant_auth_identifiers set status='VERIFIED',revision=revision+1,
   verified_at=clock_timestamp(),verification_source='OWNER_REVIEWED_PROVIDER_CONFIRMED_RECOVERY',
   updated_by='owner-reviewed-expired-certification-recovery',updated_at=clock_timestamp()
   where auth_user_id=reviewed.target_auth_user_id and player_id=reviewed.target_player_id and identifier_type='EMAIL' and status='VERIFICATION_PENDING';
  insert into participant_identity.tournament_roles(tournament_id,auth_user_id,role,role_active,granted_by)
   values('2026',reviewed.target_auth_user_id,'PARTICIPANT',true,'owner-reviewed-expired-certification-recovery');
  result := 'RECOVERED';
 end if;
 after_state := production_control.inspect_expired_identity_recovery_v1(reviewed.target_player_id,reviewed.target_auth_user_id,reviewed.historical_request_id);
 if after_state->>'state'<>'COMPLETE' then raise exception 'EXPIRED_IDENTITY_COMPLETION_FAILED'; end if;
 insert into production_control.expired_identity_recovery_receipts_v1
 (approval_id,player_id,actor_player_id,plan_hash,outcome,before_state_hash,after_state_hash,before_link_revision,after_link_revision)
 values(approval,reviewed.target_player_id,reviewed.actor_player_id,reviewed.plan_hash,result,
 encode(extensions.digest(before_state::text,'sha256'),'hex'),encode(extensions.digest(after_state::text,'sha256'),'hex'),
 (before_state->>'linkRevision')::bigint,(after_state->>'linkRevision')::bigint);
 return jsonb_build_object('ok',true,'status',result,'approvalId',approval,'sessionIssued',false);
end $$;


ALTER FUNCTION production_control.apply_expired_identity_recovery_v1(approval uuid, expected_plan_hash text) OWNER TO postgres;

--
-- Name: apply_player_email_v1(text, text, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_player_email_v1(target_player text, target_email text, actor_player text, actor_auth_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'extensions'
    AS $_$
declare
  normalized text := pg_catalog.lower(pg_catalog.btrim(target_email));
  domain_value text := pg_catalog.split_part(normalized, '@', 2);
  current_value participant_identity.participant_identity_contacts%rowtype;
  current_context participant_identity.identity_context_revisions%rowtype;
  next_identity_revision bigint;
  fingerprint_value text;
  active_roster_count integer;
  active_contact_count integer;
  workbook_id constant text :=
    '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4';
begin
  if pg_catalog.length(normalized) > 320
     or normalized !~* (
       '^[A-Z0-9.!#$%&''*+/=?^_`{|}~-]+@'
       || '[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?'
       || '(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$'
     )::pg_catalog.text collate "C"
     or domain_value ~* '(^|\.)(example\.(com|net|org)|invalid|test|localhost)$'
     or pg_catalog.split_part(normalized, '@', 1)
       ~* '(^|[+._-])(test|fake|placeholder|dummy)([+._-]|$)' then
    raise exception using errcode = '22023',
      message = 'PLAYER_ACCESS_EMAIL_INVALID';
  end if;
  if not exists (
    select 1 from scoring_authority.tournament_players membership
    where membership.tournament_id = '2026'
      and membership.player_id = target_player
      and membership.participation_status = 'ACTIVE'
  ) then
    raise exception using errcode = '22023',
      message = 'PLAYER_ACCESS_ACTIVE_MEMBERSHIP_REQUIRED';
  end if;
  if exists (
    select 1 from participant_identity.participant_identity_contacts contact
    where contact.tournament_id = '2026'
      and contact.identity_active
      and contact.email_normalized = normalized
      and contact.player_id <> target_player
  ) or exists (
    select 1 from participant_identity.participant_auth_identifiers identifier
    where identifier.identifier_type = 'EMAIL'
      and identifier.normalized_value_private = normalized
      and identifier.player_id <> target_player
      and identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
  ) or exists (
    select 1 from auth.users auth_user
    where pg_catalog.lower(pg_catalog.btrim(auth_user.email)) = normalized
      and not exists (
        select 1 from participant_identity.user_player_links target_link
        where target_link.auth_user_id = auth_user.id
          and target_link.player_id = target_player
          and target_link.status in ('PENDING', 'ACTIVE', 'SUSPENDED')
      )
  ) then
    raise exception using errcode = '23505',
      message = 'PLAYER_ACCESS_EMAIL_COLLISION';
  end if;

  select value.* into current_value
  from participant_identity.participant_identity_contacts value
  where value.tournament_id = '2026' and value.player_id = target_player;
  if found and current_value.identity_active
     and current_value.email_normalized = normalized then
    return false;
  end if;
  if found and current_value.email_normalized is distinct from normalized
     and exists (
       select 1 from participant_identity.user_player_links link
       where link.player_id = target_player
         and link.status in ('PENDING', 'ACTIVE', 'SUSPENDED')
     ) then
    raise exception using errcode = '55000',
      message = 'PLAYER_ACCESS_LINKED_EMAIL_REPAIR_REQUIRED';
  end if;
  perform claim.claim_id
  from participant_identity.production_participant_enrollment_claims claim
  where claim.tournament_id = '2026'
    and claim.status in ('PENDING', 'CLEANUP_REQUIRED')
  order by claim.claim_id
  for update;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-participant-identity-config-v1:2026', 0
  ));
  update participant_identity.production_participant_enrollment_claims set
    status = 'CANCELLED',
    cancelled_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = '2026'
    and status = 'PENDING'
    and expires_at <= pg_catalog.clock_timestamp();
  if exists (
    select 1
    from participant_identity.production_participant_enrollment_claims claim
    where claim.tournament_id = '2026'
      and (
        (claim.status = 'PENDING'
          and claim.expires_at > pg_catalog.clock_timestamp())
        or claim.status = 'CLEANUP_REQUIRED'
      )
  ) then
    raise exception using errcode = '55000',
      message = 'PLAYER_ACCESS_ENROLLMENT_CLAIM_IN_FLIGHT';
  end if;

  select value.* into strict current_context
  from participant_identity.identity_context_revisions value
  where value.tournament_id = '2026' for update;
  next_identity_revision := current_context.context_revision + 1;

  update participant_identity.participant_identity_contacts set
    configuration_revision = next_identity_revision,
    source_system = 'DIRECTOR_CONSOLE',
    source_workbook_id = workbook_id,
    source_updated_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = '2026' and identity_active;

  insert into participant_identity.participant_identity_contacts (
    tournament_id, player_id, email, email_normalized, identity_active,
    configuration_revision, verified_by, verified_at, source_system,
    source_workbook_id, source_updated_at
  ) values (
    '2026', target_player, normalized, normalized, true,
    next_identity_revision, actor_player, pg_catalog.clock_timestamp(),
    'DIRECTOR_CONSOLE', workbook_id, pg_catalog.clock_timestamp()
  ) on conflict (tournament_id, player_id) do update set
    email = excluded.email,
    email_normalized = excluded.email_normalized,
    identity_active = true,
    configuration_revision = excluded.configuration_revision,
    verified_by = excluded.verified_by,
    verified_at = excluded.verified_at,
    source_system = excluded.source_system,
    source_workbook_id = excluded.source_workbook_id,
    source_updated_at = excluded.source_updated_at,
    updated_at = pg_catalog.clock_timestamp();

  select production_control.player_access_hash_v1(
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-players-access-v1',
      'configuration_revision', next_identity_revision,
      'contacts', coalesce(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'player_id', contact.player_id,
          'email_normalized', contact.email_normalized
        ) order by contact.player_id
      ), '[]'::jsonb)
    )
  ) into fingerprint_value
  from participant_identity.participant_identity_contacts contact
  where contact.tournament_id = '2026' and contact.identity_active;

  select pg_catalog.count(*)::integer into active_roster_count
  from scoring_authority.tournament_players membership
  where membership.tournament_id = '2026'
    and membership.participation_status = 'ACTIVE';
  select pg_catalog.count(*)::integer into active_contact_count
  from participant_identity.participant_identity_contacts contact
  where contact.tournament_id = '2026' and contact.identity_active;

  insert into participant_identity.identity_config_import_runs (
    tournament_id, source_system, source_workbook_id, source_fingerprint,
    configuration_revision, status, roster_count, received_count,
    valid_count, missing_count, duplicate_count, malformed_count,
    shared_count, inactive_count, unknown_player_count,
    mapping_conflict_count, validation_report, requested_by, approved_by,
    approved_at
  ) values (
    '2026', 'DIRECTOR_CONSOLE', workbook_id, fingerprint_value,
    next_identity_revision, 'APPROVED', active_roster_count,
    active_contact_count, active_contact_count,
    greatest(active_roster_count - active_contact_count, 0),
    0, 0, 0, 0, 0, 0,
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-players-access-v1',
      'authoring_authority', 'SUPABASE_DIRECTOR',
      'approved_identifier_count', active_contact_count,
      'auth_users_created', 0,
      'otp_sent', false
    ), actor_player, actor_player, pg_catalog.clock_timestamp()
  );

  update participant_identity.identity_context_revisions set
    context_revision = next_identity_revision,
    configuration_fingerprint = fingerprint_value,
    updated_by = actor_player,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = '2026';

  return true;
end;
$_$;


ALTER FUNCTION production_control.apply_player_email_v1(target_player text, target_email text, actor_player text, actor_auth_user uuid) OWNER TO postgres;

--
-- Name: apply_player_phone_v1(text, text, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_player_phone_v1(target_player text, target_phone text, actor_player text, actor_auth_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'participant_identity', 'scoring_authority'
    AS $_$
declare
  current_value participant_identity.player_approved_phones_v1%rowtype;
begin
  if target_phone !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception using errcode = '22023',
      message = 'PLAYER_ACCESS_PHONE_INVALID';
  end if;
  if not exists (
    select 1 from scoring_authority.tournament_players membership
    where membership.tournament_id = '2026'
      and membership.player_id = target_player
      and membership.participation_status = 'ACTIVE'
  ) then
    raise exception using errcode = '22023',
      message = 'PLAYER_ACCESS_ACTIVE_MEMBERSHIP_REQUIRED';
  end if;
  if exists (
    select 1 from participant_identity.player_approved_phones_v1 phone
    where phone.phone_e164 = target_phone
      and phone.player_id <> target_player
      and phone.status in ('APPROVED', 'VERIFIED')
  ) or exists (
    select 1 from participant_identity.participant_auth_identifiers identifier
    where identifier.identifier_type = 'PHONE'
      and identifier.normalized_value_private = target_phone
      and identifier.player_id <> target_player
      and identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
  ) or exists (
    select 1 from auth.users auth_user
    where pg_catalog.btrim(coalesce(auth_user.phone, '')) = target_phone
      and not exists (
        select 1 from participant_identity.user_player_links target_link
        where target_link.auth_user_id = auth_user.id
          and target_link.player_id = target_player
          and target_link.status in ('PENDING', 'ACTIVE', 'SUSPENDED')
      )
  ) then
    raise exception using errcode = '23505',
      message = 'PLAYER_ACCESS_PHONE_COLLISION';
  end if;
  select value.* into current_value
  from participant_identity.player_approved_phones_v1 value
  where value.tournament_id = '2026' and value.player_id = target_player;
  if found and current_value.phone_e164 = target_phone
     and current_value.status in ('APPROVED', 'VERIFIED') then
    return false;
  end if;
  if found and current_value.status = 'VERIFIED' then
    raise exception using errcode = '55000',
      message = 'PLAYER_ACCESS_VERIFIED_PHONE_REPAIR_REQUIRED';
  end if;
  if exists (
    select 1 from participant_identity.participant_auth_identifiers identifier
    where identifier.player_id = target_player
      and identifier.identifier_type = 'PHONE'
      and identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING')
  ) then
    raise exception using errcode = '55000',
      message = 'PLAYER_ACCESS_PHONE_CLAIM_IN_FLIGHT';
  end if;
  if exists (
    select 1 from participant_identity.participant_auth_identifiers identifier
    where identifier.player_id = target_player
      and identifier.identifier_type = 'PHONE'
      and identifier.status = 'VERIFIED'
      and identifier.normalized_value_private <> target_phone
  ) then
    raise exception using errcode = '55000',
      message = 'PLAYER_ACCESS_VERIFIED_PHONE_REPAIR_REQUIRED';
  end if;
  insert into participant_identity.player_approved_phones_v1 (
    tournament_id, player_id, phone_e164, status, phone_revision,
    approved_at, approved_by_player_id, approved_by_auth_user_id
  ) values (
    '2026', target_player, target_phone, 'APPROVED', 1,
    pg_catalog.clock_timestamp(), actor_player, actor_auth_user
  ) on conflict (tournament_id, player_id) do update set
    phone_e164 = excluded.phone_e164,
    status = 'APPROVED',
    phone_revision = participant_identity.player_approved_phones_v1.phone_revision + 1,
    approved_at = excluded.approved_at,
    approved_by_player_id = excluded.approved_by_player_id,
    approved_by_auth_user_id = excluded.approved_by_auth_user_id,
    verified_at = null,
    revoked_at = null,
    updated_at = pg_catalog.clock_timestamp();
  return true;
end;
$_$;


ALTER FUNCTION production_control.apply_player_phone_v1(target_player text, target_phone text, actor_player text, actor_auth_user uuid) OWNER TO postgres;

--
-- Name: apply_tournament_setup_course_v1(jsonb, bigint, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_tournament_setup_course_v1(input jsonb, next_revision bigint, actor_player text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  payload jsonb := case when pg_catalog.jsonb_typeof(input->'course') = 'object'
    then input->'course' else input end;
  requested_course text := pg_catalog.btrim(coalesce(
    payload->>'course_id', payload->>'courseId', ''
  ));
  target_course text;
  target_tee text := pg_catalog.btrim(coalesce(
    payload->>'tee_id', payload->>'tee', ''
  ));
  target_name text;
  target_location text;
  target_rating numeric;
  target_slope integer;
  target_par integer;
  holes_input jsonb := payload->'holes';
  rounds_input jsonb;
  normalized_holes jsonb := '[]'::jsonb;
  normalized_rounds jsonb := '[]'::jsonb;
  hole_value jsonb;
  round_value jsonb;
  hole_number integer;
  hole_par integer;
  stroke_index integer;
  yardage_value integer;
  round_number_value integer;
  current_manifest jsonb;
  target_manifest jsonb;
  changed_value boolean := false;
  dependencies jsonb;
  equivalence jsonb;
  warning_values jsonb := '[]'::jsonb;
begin
  if requested_course = '' or target_tee = '' then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_COURSE_ID_TEE_REQUIRED';
  end if;
  select known.course_id into target_course
  from (
    select course.course_id, 1 priority
    from scoring_authority.tournament_setup_course_tees_v1 course
    where course.tournament_id = '2026'
    union all
    select snapshot.course_id, 2
    from scoring_authority.scoring_snapshots snapshot
    where snapshot.tournament_id = '2026'
    union all
    select identity_value.course_id, 3
    from scoring_authority.completed_history_course_identities identity_value
  ) known
  where pg_catalog.lower(known.course_id) = pg_catalog.lower(requested_course)
  order by (known.course_id = requested_course) desc, known.priority
  limit 1;
  if target_course is null then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_EXISTING_COURSE_ID_REQUIRED';
  end if;
  target_name := pg_catalog.btrim(coalesce(
    payload->>'course_name', payload->>'display_name',
    payload->>'displayName', payload->>'name',
    (select course.display_name
      from scoring_authority.tournament_setup_course_tees_v1 course
      where course.tournament_id = '2026'
        and course.course_id = target_course and course.tee_id = target_tee),
    (select identity_value.canonical_name
      from scoring_authority.completed_history_course_identities identity_value
      where identity_value.course_id = target_course),
    target_course
  ));
  target_location := nullif(pg_catalog.btrim(coalesce(
    payload->>'location', nullif(pg_catalog.concat_ws(', ',
      nullif(pg_catalog.btrim(payload->>'city'), ''),
      nullif(pg_catalog.btrim(payload->>'state'), '')
    ), ''),
    (select course.location
      from scoring_authority.tournament_setup_course_tees_v1 course
      where course.tournament_id = '2026'
        and course.course_id = target_course and course.tee_id = target_tee),
    (select identity_value.canonical_location
      from scoring_authority.completed_history_course_identities identity_value
      where identity_value.course_id = target_course), ''
  )), '');
  begin
    target_rating := coalesce(payload->>'rating',
      payload->>'courseRating')::numeric;
    target_slope := coalesce(payload->>'slope',
      payload->>'slopeRating')::integer;
    target_par := (payload->>'par')::integer;
  exception when others then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_COURSE_SCORING_VALUES_INVALID';
  end;
  if target_name = '' or pg_catalog.length(target_name) > 240
     or target_rating is null or target_rating <= 0 or target_rating > 100
     or target_slope not between 55 and 155
     or target_par not between 54 and 90
     or pg_catalog.jsonb_typeof(holes_input) is distinct from 'array'
     or pg_catalog.jsonb_array_length(holes_input) <> 18 then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_COURSE_SCORING_VALUES_INVALID';
  end if;
  for hole_value in
    select item from pg_catalog.jsonb_array_elements(holes_input) item
  loop
    begin
      hole_number := coalesce(hole_value->>'hole_number',
        hole_value->>'holeNumber', hole_value->>'number')::integer;
      hole_par := (hole_value->>'par')::integer;
      stroke_index := coalesce(hole_value->>'stroke_index',
        hole_value->>'strokeIndex')::integer;
      yardage_value := nullif(hole_value->>'yardage', '')::integer;
    exception when others then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_SETUP_HOLE_DEFINITION_INVALID';
    end;
    if hole_number not between 1 and 18 or hole_par not between 3 and 6
       or stroke_index not between 1 and 18
       or (yardage_value is not null and yardage_value not between 1 and 999)
    then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_SETUP_HOLE_DEFINITION_INVALID';
    end if;
    normalized_holes := normalized_holes || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'hole_number', hole_number, 'par', hole_par,
        'stroke_index', stroke_index, 'yardage', yardage_value
      )
    );
  end loop;
  select pg_catalog.jsonb_agg(value order by (value->>'hole_number')::integer)
    into normalized_holes
  from pg_catalog.jsonb_array_elements(normalized_holes) value;
  if (select pg_catalog.count(distinct (value->>'hole_number')::integer)
      from pg_catalog.jsonb_array_elements(normalized_holes) value) <> 18
     or (select pg_catalog.count(distinct (value->>'stroke_index')::integer)
      from pg_catalog.jsonb_array_elements(normalized_holes) value) <> 18
     or (select pg_catalog.sum((value->>'par')::integer)
      from pg_catalog.jsonb_array_elements(normalized_holes) value)
        <> target_par then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_HOLE_NUMBER_STROKE_INDEX_INCOMPLETE';
  end if;

  rounds_input := case
    when pg_catalog.jsonb_typeof(payload->'round_numbers') = 'array'
      then payload->'round_numbers'
    when pg_catalog.jsonb_typeof(payload->'roundNumbers') = 'array'
      then payload->'roundNumbers'
    when coalesce(payload->>'round_number', payload->>'roundNumber', '') <> ''
      then pg_catalog.jsonb_build_array(coalesce(payload->>'round_number',
        payload->>'roundNumber')::integer)
    else '[]'::jsonb end;
  if pg_catalog.jsonb_array_length(rounds_input) = 0 then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_COURSE_ROUND_ASSIGNMENT_REQUIRED';
  end if;
  for round_value in
    select item from pg_catalog.jsonb_array_elements(rounds_input) item
  loop
    begin
      round_number_value := (round_value #>> '{}')::integer;
    exception when others then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_SETUP_COURSE_ROUND_INVALID';
    end;
    if not exists (
      select 1 from scoring_authority.rounds round_row
      where round_row.tournament_id = '2026'
        and round_row.round_number = round_number_value
    ) then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_SETUP_COURSE_ROUND_INVALID';
    end if;
    normalized_rounds := normalized_rounds ||
      pg_catalog.jsonb_build_array(round_number_value);
  end loop;
  select pg_catalog.jsonb_agg(value order by (value #>> '{}')::integer)
    into normalized_rounds
  from (
    select distinct value from (
      select value
      from pg_catalog.jsonb_array_elements(normalized_rounds) value
      union all
      select pg_catalog.to_jsonb(assignment.round_number)
      from scoring_authority.tournament_setup_round_courses_v1 assignment
      where assignment.tournament_id = '2026'
        and assignment.course_id = target_course
        and assignment.tee_id = target_tee
    ) retained
  ) deduplicated;

  select pg_catalog.jsonb_build_object(
    'course_id', course.course_id, 'tee', course.tee_id,
    'display_name', course.display_name, 'location', course.location,
    'rating', course.rating, 'slope', course.slope, 'par', course.par,
    'holes', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'hole_number', hole.hole_number, 'par', hole.par,
        'stroke_index', hole.stroke_index, 'yardage', hole.yardage
      ) order by hole.hole_number)
      from scoring_authority.tournament_setup_course_holes_v1 hole
      where hole.tournament_id = course.tournament_id
        and hole.course_id = course.course_id and hole.tee_id = course.tee_id
    ), '[]'::jsonb),
    'round_numbers', coalesce((
      select pg_catalog.jsonb_agg(assignment.round_number
        order by assignment.round_number)
      from scoring_authority.tournament_setup_round_courses_v1 assignment
      where assignment.tournament_id = course.tournament_id
        and assignment.course_id = course.course_id
        and assignment.tee_id = course.tee_id
    ), '[]'::jsonb)
  ) into current_manifest
  from scoring_authority.tournament_setup_course_tees_v1 course
  where course.tournament_id = '2026' and course.course_id = target_course
    and course.tee_id = target_tee;
  target_manifest := pg_catalog.jsonb_build_object(
    'course_id', target_course, 'tee', target_tee,
    'display_name', target_name, 'location', target_location,
    'rating', target_rating, 'slope', target_slope, 'par', target_par,
    'holes', normalized_holes, 'round_numbers', normalized_rounds
  );
  changed_value := current_manifest is distinct from target_manifest;
  if changed_value then
    -- Match the existing publication -> Odds-runtime lock order. Job requests
    -- and worker transitions hold the shared runtime lock; publication holds
    -- the publication lock. Keep both proofs stable through the Setup commit.
    perform pg_catalog.pg_advisory_xact_lock(731132026057::bigint);
    perform pg_catalog.pg_advisory_xact_lock(731102026031::bigint);
    perform 1 from scoring_authority.matches m
    where m.tournament_id = '2026' and (
      m.round_number in (select (r #>> '{}')::integer
        from pg_catalog.jsonb_array_elements(normalized_rounds) r)
      or exists (select 1 from scoring_authority.scoring_snapshots s
        where s.snapshot_id = m.scoring_snapshot_id
          and s.course_id = target_course and s.tee = target_tee)
    ) order by m.match_id for update;
    if exists (
      select 1
      from scoring_authority.matches match_value
      join scoring_authority.scoring_snapshots snapshot
        on snapshot.snapshot_id = match_value.scoring_snapshot_id
      where match_value.tournament_id = '2026'
        and snapshot.course_id = target_course and snapshot.tee = target_tee
        and not production_control.handicap_v1_match_is_unstarted(
          match_value.match_id
        )
    ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'TOURNAMENT_SETUP_STARTED_MATCH_LOCKED',
        'blockers', pg_catalog.jsonb_build_array('STARTED_MATCH_DEPENDENCY')
      );
    end if;
    dependencies := production_control.tournament_setup_dependency_codes_v1(
      null, null, null, null, 'COURSE'
    );
    -- Never change the shared dependency guard. This exception removes only
    -- an existing published-snapshot dependency, never active/publish-ready work.
    if dependencies ? 'ODDS_PUBLICATION_DEPENDENCY'
       and exists (select 1 from scoring_authority.odds_publication_current p
         where p.tournament_id = '2026' and p.publication_state = 'PUBLISHED')
       and not exists (select 1 from scoring_authority.odds_calculation_jobs j
         where j.tournament_id = '2026' and (
           j.status in ('PENDING', 'RUNNING', 'RETRYABLE')
           or (j.status = 'SUCCEEDED' and j.publication_status = 'READY')
         )) then
      equivalence := production_control.certify_identical_legacy_course_adoption_v1(
        '2026', target_manifest
      );
      if coalesce((equivalence->>'eligible')::boolean, false) then
        select coalesce(pg_catalog.jsonb_agg(code), '[]'::jsonb) into dependencies
        from pg_catalog.jsonb_array_elements(dependencies) code
        where code #>> '{}' <> 'ODDS_PUBLICATION_DEPENDENCY';
        warning_values := pg_catalog.jsonb_build_array('ODDS_PUBLICATION_REVIEW_REQUIRED');
      end if;
    end if;
    if pg_catalog.jsonb_array_length(dependencies) > 0 then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'TOURNAMENT_SETUP_DEPENDENCY_BLOCKED',
        'blockers', dependencies
      );
    end if;
    insert into scoring_authority.tournament_setup_course_tees_v1 (
      tournament_id, course_id, tee_id, display_name, location,
      rating, slope, par, setup_revision, updated_by_player_id
    ) values (
      '2026', target_course, target_tee, target_name, target_location,
      target_rating, target_slope, target_par, next_revision, actor_player
    ) on conflict (tournament_id, course_id, tee_id) do update set
      display_name = excluded.display_name,
      location = excluded.location,
      rating = excluded.rating,
      slope = excluded.slope,
      par = excluded.par,
      setup_revision = excluded.setup_revision,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
    delete from scoring_authority.tournament_setup_course_holes_v1
    where tournament_id = '2026' and course_id = target_course
      and tee_id = target_tee;
    insert into scoring_authority.tournament_setup_course_holes_v1 (
      tournament_id, course_id, tee_id, hole_number, par, stroke_index,
      yardage, setup_revision
    ) select '2026', target_course, target_tee,
      (value->>'hole_number')::integer, (value->>'par')::integer,
      (value->>'stroke_index')::integer,
      nullif(value->>'yardage', '')::integer, next_revision
    from pg_catalog.jsonb_array_elements(normalized_holes) value;
    insert into scoring_authority.tournament_setup_round_courses_v1 (
      tournament_id, round_number, course_id, tee_id, setup_revision,
      updated_by_player_id
    ) select '2026', (value #>> '{}')::integer, target_course,
      target_tee, next_revision, actor_player
    from pg_catalog.jsonb_array_elements(rounds_input) value
    on conflict (tournament_id, round_number) do update set
      course_id = excluded.course_id,
      tee_id = excluded.tee_id,
      setup_revision = excluded.setup_revision,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
    insert into scoring_authority.tournament_setup_match_details_v1 (
      match_id, tournament_id, round_number, match_number, course_id, tee_id,
      tee_time, starting_hole, setup_revision, prepared_setup_revision,
      prepared_configuration_fingerprint, updated_by_player_id
    )
    select match_value.match_id, '2026', match_value.round_number,
      nullif(pg_catalog.regexp_replace(match_value.match_id, '^.*-', ''), '')::integer,
      target_course, target_tee,
      nullif(presentation.tee_time, '')::time,
      coalesce(nullif(presentation.starting_hole, '')::integer, 1),
      next_revision, null, null, actor_player
    from scoring_authority.matches match_value
    join scoring_authority.scoring_snapshots snapshot
      on snapshot.snapshot_id = match_value.scoring_snapshot_id
    left join scoring_authority.game_center_presentations presentation
      on presentation.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
      and snapshot.course_id = target_course and snapshot.tee = target_tee
      and production_control.handicap_v1_match_is_unstarted(
        match_value.match_id
      )
    on conflict (match_id) do update set
      setup_revision = excluded.setup_revision,
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
    update scoring_authority.tournament_setup_match_details_v1 detail set
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      setup_revision = next_revision,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where detail.tournament_id = '2026'
      and (detail.course_id = target_course and detail.tee_id = target_tee
        or detail.round_number in (
          select (value #>> '{}')::integer
          from pg_catalog.jsonb_array_elements(normalized_rounds) value
        ));
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'changed', changed_value,
    'warnings', warning_values,
    'targetKind', 'COURSE_TEE',
    'targetId', target_course || ':' || target_tee,
    'safeMetadata', pg_catalog.jsonb_build_object(
      'courseId', target_course, 'tee', target_tee,
      'holeCount', 18, 'roundNumbers', normalized_rounds,
      'complete', true,
      'identicalLegacyAdoption', coalesce((equivalence->>'eligible')::boolean, false)
    )
  );
end;
$$;


ALTER FUNCTION production_control.apply_tournament_setup_course_v1(input jsonb, next_revision bigint, actor_player text) OWNER TO postgres;

--
-- Name: apply_tournament_setup_match_v1(jsonb, bigint, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_tournament_setup_match_v1(input jsonb, next_revision bigint, actor_player text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  payload jsonb := case when pg_catalog.jsonb_typeof(input->'match') = 'object'
    then input->'match' else input end;
  target_round integer;
  target_number integer;
  target_match text;
  supplied_match text := pg_catalog.btrim(coalesce(
    payload->>'match_id', payload->>'matchId', ''
  ));
  target_course text := pg_catalog.btrim(coalesce(
    payload->>'course_id', payload->>'courseId', ''
  ));
  target_tee text := pg_catalog.btrim(coalesce(
    payload->>'tee_id', payload->>'tee', ''
  ));
  target_tee_time time without time zone;
  round_value scoring_authority.rounds%rowtype;
  course_value scoring_authority.tournament_setup_course_tees_v1%rowtype;
  current_match scoring_authority.matches%rowtype;
  current_detail scoring_authority.tournament_setup_match_details_v1%rowtype;
  current_snapshot scoring_authority.scoring_snapshots%rowtype;
  changed_value boolean := false;
  semantic_change boolean := false;
  course_change boolean := false;
  dependencies jsonb;
begin
  begin
    target_round := coalesce(payload->>'round_number',
      payload->>'roundNumber')::integer;
    target_number := coalesce(payload->>'match_number',
      payload->>'matchNumber')::integer;
    target_tee_time := nullif(coalesce(payload->>'tee_time',
      payload->>'teeTime'), '')::time;
  exception when others then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_MATCH_INPUT_INVALID';
  end;
  if target_round not between 1 and 99 or target_number not between 1 and 99
     or target_course = '' then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_MATCH_INPUT_INVALID';
  end if;
  target_match := pg_catalog.format('2026-R%s-%s', target_round, target_number);
  if supplied_match <> '' and supplied_match <> target_match then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_MATCH_ID_INVALID';
  end if;
  select value.* into strict round_value
  from scoring_authority.rounds value
  where value.tournament_id = '2026' and value.round_number = target_round;
  if target_tee = '' then
    select assignment.tee_id into target_tee
    from scoring_authority.tournament_setup_round_courses_v1 assignment
    where assignment.tournament_id = '2026'
      and assignment.round_number = target_round
      and assignment.course_id = target_course;
  end if;
  if pg_catalog.btrim(coalesce(target_tee, '')) = '' then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_MATCH_TEE_ASSIGNMENT_REQUIRED';
  end if;
  select value.* into strict course_value
  from scoring_authority.tournament_setup_course_tees_v1 value
  where value.tournament_id = '2026' and value.course_id = target_course
    and value.tee_id = target_tee;
  if not exists (
    select 1
    from scoring_authority.tournament_setup_round_courses_v1 assignment
    where assignment.tournament_id = '2026'
      and assignment.round_number = target_round
      and assignment.course_id = target_course
      and assignment.tee_id = target_tee
  ) then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_MATCH_ROUND_COURSE_MISMATCH';
  end if;
  select value.* into current_match
  from scoring_authority.matches value where value.match_id = target_match for update;
  if current_match.match_id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'TOURNAMENT_SETUP_EXISTING_MATCH_REQUIRED',
      'blockers', pg_catalog.jsonb_build_array(
        'Tournament Setup can update only an existing canonical match.'
      )
    );
  end if;
  select value.* into current_detail
  from scoring_authority.tournament_setup_match_details_v1 value
  where value.match_id = target_match for update;
  select value.* into strict current_snapshot
  from scoring_authority.scoring_snapshots value
  where value.snapshot_id = current_match.scoring_snapshot_id;
  semantic_change := current_match.round_number is distinct from target_round
    or current_match.format is distinct from round_value.format
    or current_snapshot.course_id is distinct from target_course
    or current_snapshot.tee is distinct from target_tee;
  course_change := current_snapshot.course_id is distinct from target_course
    or current_snapshot.tee is distinct from target_tee;
  changed_value := semantic_change or current_detail.match_id is null
    or current_detail.tee_time is distinct from target_tee_time
    or current_detail.course_id is distinct from target_course
    or current_detail.tee_id is distinct from target_tee;
  if changed_value then
    perform production_control.assert_tournament_setup_match_mutable_v1(
      target_match
    );
    if semantic_change then
      dependencies := production_control.tournament_setup_dependency_codes_v1(
        null, null, target_round, target_match, 'MATCH'
      );
      if pg_catalog.jsonb_array_length(dependencies) > 0 then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'TOURNAMENT_SETUP_DEPENDENCY_BLOCKED',
          'blockers', dependencies
        );
      end if;
    end if;
    update scoring_authority.matches set
      round_number = target_round,
      format = round_value.format,
      match_revision = match_revision + case when semantic_change then 1 else 0 end,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = target_match;
    insert into scoring_authority.tournament_setup_match_details_v1 (
      match_id, tournament_id, round_number, match_number, course_id, tee_id,
      tee_time, starting_hole, setup_revision, prepared_setup_revision,
      prepared_configuration_fingerprint, updated_by_player_id
    ) values (
      target_match, '2026', target_round, target_number, target_course,
      target_tee, target_tee_time, null, next_revision, null, null,
      actor_player
    ) on conflict (match_id) do update set
      round_number = excluded.round_number,
      match_number = excluded.match_number,
      course_id = excluded.course_id,
      tee_id = excluded.tee_id,
      tee_time = excluded.tee_time,
      setup_revision = excluded.setup_revision,
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
    insert into scoring_authority.game_center_presentations (
      match_id, tournament_id, course_name, course_logo, course_yardage,
      tee_time, starting_hole, display_match_number, match_sort_order,
      team_1_logo, team_1_primary_color, team_1_secondary_color,
      team_2_logo, team_2_primary_color, team_2_secondary_color,
      tournament_location, tournament_logo, tournament_status,
      tournament_time_zone, source_workbook_id, source_updated_at,
      source_payload_hash, imported_by
    ) values (
      target_match, '2026', course_value.display_name, '', '',
      coalesce(target_tee_time::text, ''), '',
      target_number::text, target_round * 100 + target_number,
      coalesce((select template.team_1_logo
        from scoring_authority.game_center_presentations template
        where template.tournament_id = '2026'
        order by template.match_sort_order limit 1), ''),
      coalesce((select template.team_1_primary_color
        from scoring_authority.game_center_presentations template
        where template.tournament_id = '2026'
        order by template.match_sort_order limit 1), ''),
      coalesce((select template.team_1_secondary_color
        from scoring_authority.game_center_presentations template
        where template.tournament_id = '2026'
        order by template.match_sort_order limit 1), ''),
      coalesce((select template.team_2_logo
        from scoring_authority.game_center_presentations template
        where template.tournament_id = '2026'
        order by template.match_sort_order limit 1), ''),
      coalesce((select template.team_2_primary_color
        from scoring_authority.game_center_presentations template
        where template.tournament_id = '2026'
        order by template.match_sort_order limit 1), ''),
      coalesce((select template.team_2_secondary_color
        from scoring_authority.game_center_presentations template
        where template.tournament_id = '2026'
        order by template.match_sort_order limit 1), ''),
      coalesce((select operational.destination
        from scoring_authority.tournament_setup_operational_v1 operational
        where operational.tournament_id = '2026'), ''),
      coalesce((select template.tournament_logo
        from scoring_authority.game_center_presentations template
        where template.tournament_id = '2026'
        order by template.match_sort_order limit 1), ''),
      'UPCOMING',
      coalesce((select operational.timezone
        from scoring_authority.tournament_setup_operational_v1 operational
        where operational.tournament_id = '2026'), 'America/Chicago'),
      (select tournament.source_workbook_id
       from scoring_authority.tournaments tournament
       where tournament.tournament_id = '2026'),
      null,
      production_control.tournament_setup_hash_v1(
        pg_catalog.jsonb_build_object(
          'match_id', target_match, 'course_name', course_value.display_name,
          'tee_time', target_tee_time,
          'match_number', target_number, 'round_number', target_round
        )
      ), actor_player
    ) on conflict (match_id) do update set
      course_name = excluded.course_name,
      course_logo = case when course_change then excluded.course_logo
        else scoring_authority.game_center_presentations.course_logo end,
      course_yardage = case when course_change then excluded.course_yardage
        else scoring_authority.game_center_presentations.course_yardage end,
      tee_time = excluded.tee_time,
      display_match_number = excluded.display_match_number,
      match_sort_order = excluded.match_sort_order,
      tournament_location = excluded.tournament_location,
      tournament_status = excluded.tournament_status,
      tournament_time_zone = excluded.tournament_time_zone,
      source_payload_hash = excluded.source_payload_hash,
      imported_by = excluded.imported_by,
      updated_at = pg_catalog.clock_timestamp();
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'changed', changed_value,
    'targetKind', 'MATCH', 'targetId', target_match,
    'safeMetadata', pg_catalog.jsonb_build_object(
      'matchId', target_match, 'roundNumber', target_round,
      'matchNumber', target_number, 'format', round_value.format,
      'courseId', target_course, 'tee', target_tee,
      'created', false,
      'scoringPermissionGranted', false,
      'scoringMutationCreated', false
    )
  );
exception when no_data_found then
  raise exception using errcode = '22023',
    message = 'TOURNAMENT_SETUP_ROUND_OR_COURSE_NOT_FOUND';
end;
$$;


ALTER FUNCTION production_control.apply_tournament_setup_match_v1(input jsonb, next_revision bigint, actor_player text) OWNER TO postgres;

--
-- Name: apply_tournament_setup_membership_v1(jsonb, bigint, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_tournament_setup_membership_v1(input jsonb, next_revision bigint, actor_player text, actor_auth uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  payload jsonb := case when pg_catalog.jsonb_typeof(input->'membership') = 'object'
    then input->'membership' else input end;
  target_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    payload->>'player_id', payload->>'playerId', ''
  )));
  target_team text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    payload->>'team_id', payload->>'teamId', ''
  )));
  team_value scoring_authority.teams%rowtype;
  current_value scoring_authority.tournament_players%rowtype;
  dependencies jsonb;
  warning_values jsonb := '[]'::jsonb;
  invalidated_match_count integer := 0;
  changed_value boolean := false;
begin
  if target_player = '' or target_team = '' or not exists (
    select 1 from scoring_authority.players player
    where player.player_id = target_player
      and production_control.access_governance_global_status_v1(player.player_id)
        = 'ACTIVE'
  ) then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_ACTIVE_GLOBAL_PLAYER_REQUIRED';
  end if;
  select value.* into strict team_value
  from scoring_authority.teams value
  where value.tournament_id = '2026' and value.team_id = target_team;
  select value.* into current_value
  from scoring_authority.tournament_players value
  where value.tournament_id = '2026' and value.player_id = target_player
  for update;
  if current_value.player_id is not null
     and current_value.participation_status <> 'ACTIVE' then
    raise exception using errcode = '55000',
      message = 'TOURNAMENT_SETUP_MEMBERSHIP_REACTIVATION_REQUIRES_ACCESS_GOVERNANCE';
  end if;
  changed_value := current_value.player_id is null
    or current_value.team_id is distinct from target_team
    or current_value.team_side is distinct from team_value.team_side
    or current_value.participation_status is distinct from 'ACTIVE';
  if changed_value then
    dependencies := production_control.tournament_setup_dependency_codes_v1(
      target_player, target_team, null, null, 'ROSTER'
    );
    if pg_catalog.jsonb_array_length(dependencies) > 0 then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'TOURNAMENT_SETUP_DEPENDENCY_BLOCKED',
        'blockers', dependencies
      );
    end if;
    insert into scoring_authority.tournament_players (
      tournament_id, player_id, team_id, team_side, participation_status,
      source_roster_key, source_payload
    ) values (
      '2026', target_player, target_team, team_value.team_side, 'ACTIVE',
      '2026:' || target_player, '{}'::jsonb
    ) on conflict (tournament_id, player_id) do update set
      team_id = excluded.team_id,
      team_side = excluded.team_side,
      updated_at = pg_catalog.clock_timestamp();
    if current_value.player_id is null then
      insert into production_control.access_governance_membership_revisions_v1 (
        tournament_id, player_id, membership_revision,
        participation_status, updated_by_player_id, updated_by_auth_user_id
      ) values (
        '2026', target_player, 1, 'ACTIVE', actor_player, actor_auth
      ) on conflict (tournament_id, player_id) do nothing;
    end if;
    update scoring_authority.tournament_setup_match_details_v1 detail set
      setup_revision = next_revision,
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where detail.tournament_id = '2026'
      and exists (
        select 1
        from scoring_authority.match_participants participant
        join scoring_authority.matches match_value
          on match_value.match_id = participant.match_id
         and match_value.tournament_id = '2026'
        where participant.match_id = detail.match_id
          and participant.player_id = target_player
          and match_value.status = 'UPCOMING'
          and match_value.scored_holes = 0
          and match_value.current_hole = 0
          and match_value.finalized_at is null
          and not match_value.scorecard_complete
          and not exists (
            select 1 from scoring_authority.hole_scores score
            where score.match_id = match_value.match_id
          )
          and not exists (
            select 1
            from scoring_authority.finalized_scorecard_snapshots final_value
            where final_value.match_id = match_value.match_id
          )
      );
    get diagnostics invalidated_match_count = row_count;
    if invalidated_match_count > 0 then
      warning_values := warning_values || pg_catalog.jsonb_build_array(
        'Affected unstarted match scoring context requires preparation.'
      );
    end if;
  end if;
  if not exists (
    select 1
    from scoring_authority.handicap_revision_current current_handicap
    join scoring_authority.handicap_revision_entries entry
      on entry.revision_id = current_handicap.revision_id
     and entry.player_id = target_player
    where current_handicap.tournament_id = '2026'
  ) then
    warning_values := warning_values || pg_catalog.jsonb_build_array(
      'Player added to roster — handicap required'
    );
  end if;
  if not exists (
    select 1 from scoring_authority.match_participants participant
    where participant.player_id = target_player
  ) then
    warning_values := warning_values || pg_catalog.jsonb_build_array(
      'Player added — pairing assignment required'
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'changed', changed_value,
    'targetKind', 'MEMBERSHIP', 'targetId', target_player,
    'warnings', warning_values,
    'safeMetadata', pg_catalog.jsonb_build_object(
      'teamId', target_team,
      'teamSide', team_value.team_side,
      'membershipStatus', 'ACTIVE',
      'invalidatedMatchCount', invalidated_match_count,
      'teamChanged', current_value.player_id is not null
        and current_value.team_id is distinct from target_team,
      'authUserCreated', false,
      'scoringPermissionGranted', false
    )
  );
exception when no_data_found then
  raise exception using errcode = '22023',
    message = 'TOURNAMENT_SETUP_TEAM_NOT_FOUND';
end;
$$;


ALTER FUNCTION production_control.apply_tournament_setup_membership_v1(input jsonb, next_revision bigint, actor_player text, actor_auth uuid) OWNER TO postgres;

--
-- Name: apply_tournament_setup_pairings_v1(jsonb, bigint, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_tournament_setup_pairings_v1(input jsonb, next_revision bigint, actor_player text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  payload jsonb := case when pg_catalog.jsonb_typeof(input->'pairings') = 'object'
    then input->'pairings' else input end;
  target_match text := pg_catalog.btrim(coalesce(
    payload->>'match_id', payload->>'matchId', ''
  ));
  supplied_format text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    payload->>'format', ''
  )));
  participants_input jsonb := payload->'participants';
  normalized jsonb := '[]'::jsonb;
  item jsonb;
  player_value text;
  side_value integer;
  slot_value integer;
  expected_count integer;
  participant_count integer;
  match_value scoring_authority.matches%rowtype;
  current_handicap uuid;
  current_manifest jsonb;
  context_value jsonb;
  participant_item jsonb;
  dependencies jsonb;
  filtered_dependencies jsonb;
  warnings_value jsonb := '[]'::jsonb;
  next_permission_revision bigint;
  changed_value boolean := false;
  legacy_setup_materialized boolean := false;
begin
  if target_match = '' or pg_catalog.jsonb_typeof(participants_input)
       is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_PAIRINGS_INPUT_INVALID';
  end if;
  select value.* into strict match_value
  from scoring_authority.matches value
  where value.tournament_id = '2026' and value.match_id = target_match
  for update;
  if supplied_format <> match_value.format then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_PAIRING_FORMAT_MISMATCH';
  end if;
  expected_count := case when match_value.format = 'SI' then 2 else 4 end;
  participant_count := pg_catalog.jsonb_array_length(participants_input);
  if participant_count not in (0, expected_count) then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_PAIRING_COUNT_INVALID';
  end if;

  if participant_count = expected_count then
    for item in select value
      from pg_catalog.jsonb_array_elements(participants_input) entry(value)
    loop
      begin
        player_value := pg_catalog.upper(pg_catalog.btrim(coalesce(
          item->>'player_id', item->>'playerId', ''
        )));
        side_value := coalesce(item->>'team_side', item->>'teamSide')::integer;
        slot_value := coalesce(item->>'player_slot', item->>'playerSlot')::integer;
      exception when others then
        raise exception using errcode = '22023',
          message = 'TOURNAMENT_SETUP_PAIRING_STRUCTURE_INVALID';
      end;
      if player_value = '' or side_value not in (1, 2)
         or slot_value not between 1 and (case when match_value.format = 'SI'
           then 1 else 2 end)
         or not exists (
           select 1 from scoring_authority.tournament_players membership
           where membership.tournament_id = '2026'
             and membership.player_id = player_value
             and membership.team_side = side_value
             and membership.participation_status = 'ACTIVE'
         ) then
        raise exception using errcode = '22023',
          message = 'TOURNAMENT_SETUP_PAIRING_ACTIVE_TEAM_MEMBERSHIP_REQUIRED';
      end if;
      normalized := normalized || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'player_id', player_value, 'team_side', side_value,
          'player_slot', slot_value
        )
      );
    end loop;
    select coalesce(pg_catalog.jsonb_agg(value order by
        (value->>'team_side')::integer, (value->>'player_slot')::integer),
        '[]'::jsonb)
      into normalized
    from pg_catalog.jsonb_array_elements(normalized) value;
    if (select pg_catalog.count(distinct value->>'player_id')
        from pg_catalog.jsonb_array_elements(normalized) value) <> expected_count
       or (select pg_catalog.count(distinct
          (value->>'team_side') || ':' || (value->>'player_slot'))
        from pg_catalog.jsonb_array_elements(normalized) value) <> expected_count
       or (select pg_catalog.count(*)
        from pg_catalog.jsonb_array_elements(normalized) value
        where (value->>'team_side')::integer = 1) <> expected_count / 2
       or (select pg_catalog.count(*)
        from pg_catalog.jsonb_array_elements(normalized) value
        where (value->>'team_side')::integer = 2) <> expected_count / 2 then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_SETUP_PAIRING_STRUCTURE_INVALID';
    end if;
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(normalized) requested
      join scoring_authority.match_participants participant
        on participant.player_id = requested->>'player_id'
      join scoring_authority.matches other_match
        on other_match.match_id = participant.match_id
       and other_match.tournament_id = '2026'
       and other_match.round_number = match_value.round_number
       and other_match.match_id <> target_match
    ) then
      raise exception using errcode = '23505',
        message = 'TOURNAMENT_SETUP_ROUND_DUPLICATE_PLAYER';
    end if;
    select current_value.revision_id into strict current_handicap
    from scoring_authority.handicap_revision_current current_value
    where current_value.tournament_id = '2026';
    if exists (
      select 1 from pg_catalog.jsonb_array_elements(normalized) requested
      where not exists (
        select 1 from scoring_authority.handicap_revision_entries entry
        where entry.revision_id = current_handicap
          and entry.tournament_id = '2026'
          and entry.player_id = requested->>'player_id'
      )
    ) then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_SETUP_PAIRING_APPROVED_HANDICAP_REQUIRED';
    end if;
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'player_id', participant.player_id,
    'team_side', participant.team_side,
    'player_slot', participant.player_slot
  ) order by participant.team_side, participant.player_slot), '[]'::jsonb)
  into current_manifest
  from scoring_authority.match_participants participant
  where participant.match_id = target_match;
  changed_value := current_manifest is distinct from normalized;

  if changed_value then
    if participant_count = 0 then
      perform production_control.assert_tournament_setup_pairing_clear_safe_v1(
        target_match
      );
    else
      perform production_control.assert_tournament_setup_match_mutable_v1(
        target_match
      );
    end if;
    dependencies := production_control.tournament_setup_dependency_codes_v1(
      null, null, match_value.round_number, target_match, 'PAIRINGS'
    );
    if participant_count = 0 then
      select coalesce(pg_catalog.jsonb_agg(value order by value), '[]'::jsonb)
      into filtered_dependencies
      from pg_catalog.jsonb_array_elements_text(dependencies) value
      where value not in (
        'ACTIVE_SCORING_ACCESS_DEPENDENCY', 'ODDS_PUBLICATION_DEPENDENCY'
      );
      if dependencies ? 'ODDS_PUBLICATION_DEPENDENCY' then
        warnings_value := pg_catalog.jsonb_build_array(
          'Published Odds remain unchanged; review them after new pairings are configured.'
        );
      end if;
    else
      filtered_dependencies := dependencies;
    end if;
    if pg_catalog.jsonb_array_length(filtered_dependencies) > 0 then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'TOURNAMENT_SETUP_DEPENDENCY_BLOCKED',
        'blockers', filtered_dependencies
      );
    end if;

    if participant_count = 0 then
      legacy_setup_materialized :=
        production_control.materialize_tournament_setup_legacy_match_v1(
          target_match, next_revision, actor_player
        );
    elsif not exists (
      select 1 from scoring_authority.tournament_setup_match_details_v1 detail
      where detail.match_id = target_match
    ) then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_SETUP_MATCH_DETAILS_REQUIRED';
    end if;

    next_permission_revision := match_value.permission_revision + 1;
    delete from scoring_authority.scoring_permissions permission
    where permission.match_id = target_match;
    delete from scoring_authority.match_participants participant
    where participant.match_id = target_match;

    if participant_count = expected_count then
      insert into scoring_authority.match_participants (
        match_id, player_id, team_side, player_slot, tournament_handicap,
        handicap_index, course_handicap, playing_handicap, final_strokes,
        handicap_revision_id
      )
      select target_match, requested->>'player_id',
        (requested->>'team_side')::integer,
        (requested->>'player_slot')::integer,
        handicap.tournament_handicap, handicap.tournament_handicap,
        handicap.tournament_handicap, 0, 0, current_handicap
      from pg_catalog.jsonb_array_elements(normalized) requested
      join scoring_authority.handicap_revision_entries handicap
        on handicap.revision_id = current_handicap
       and handicap.tournament_id = '2026'
       and handicap.player_id = requested->>'player_id';
      context_value := production_control.handicap_v1_match_context(
        target_match, current_handicap
      );
      for participant_item in select value
        from pg_catalog.jsonb_array_elements(
          context_value->'participants'
        ) item(value)
      loop
        update scoring_authority.match_participants set
          tournament_handicap =
            (participant_item->>'tournament_handicap')::numeric,
          handicap_index = (participant_item->>'handicap_index')::numeric,
          course_handicap = (participant_item->>'course_handicap')::numeric,
          playing_handicap = (participant_item->>'playing_handicap')::numeric,
          final_strokes = (participant_item->>'final_strokes')::integer,
          handicap_revision_id = current_handicap
        where match_id = target_match
          and player_id = participant_item->>'player_id';
      end loop;
      insert into scoring_authority.scoring_permissions (
        match_id, player_id, can_score, permission_revision,
        revoked_at, updated_at
      )
      select target_match, requested->>'player_id', false,
        next_permission_revision, pg_catalog.clock_timestamp(),
        pg_catalog.clock_timestamp()
      from pg_catalog.jsonb_array_elements(normalized) requested;
    else
      delete from scoring_authority.match_holes hole
      where hole.match_id = target_match;
    end if;

    update scoring_authority.matches set
      permission_revision = next_permission_revision,
      match_revision = match_revision + 1,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = target_match;
    update scoring_authority.tournament_setup_match_details_v1 set
      setup_revision = next_revision,
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = target_match;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true, 'changed', changed_value,
    'targetKind', 'PAIRINGS', 'targetId', target_match,
    'warnings', warnings_value,
    'safeMetadata', pg_catalog.jsonb_build_object(
      'matchId', target_match, 'format', match_value.format,
      'participantCount', participant_count,
      'handicapRevisionId', current_handicap,
      'pairingsCleared', participant_count = 0,
      'legacySetupMaterialized', legacy_setup_materialized,
      'legacySnapshotRetained', match_value.scoring_snapshot_id,
      'scoringPermissionGranted', false,
      'scoringMutationCreated', false
    )
  );
exception when no_data_found then
  raise exception using errcode = '22023',
    message = 'TOURNAMENT_SETUP_MATCH_OR_HANDICAP_CONTEXT_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.apply_tournament_setup_pairings_v1(input jsonb, next_revision bigint, actor_player text) OWNER TO postgres;

--
-- Name: apply_tournament_setup_round_v1(jsonb, bigint, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_tournament_setup_round_v1(input jsonb, next_revision bigint, actor_player text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  payload jsonb := case when pg_catalog.jsonb_typeof(input->'round') = 'object'
    then input->'round' else input end;
  target_round integer;
  target_format text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    payload->>'format', ''
  )));
  target_name text := pg_catalog.btrim(coalesce(
    payload->>'round_name', payload->>'name', ''
  ));
  target_allowance numeric;
  target_team_size integer;
  target_points numeric;
  target_order integer;
  current_value scoring_authority.rounds%rowtype;
  current_detail scoring_authority.tournament_setup_round_details_v1%rowtype;
  changed_value boolean := false;
  dependencies jsonb;
begin
  begin
    target_round := coalesce(payload->>'round_number',
      payload->>'roundNumber')::integer;
    target_allowance := nullif(coalesce(payload->>'handicap_allowance',
      payload->>'handicapAllowance'), '')::numeric;
    target_team_size := coalesce(payload->>'team_size',
      payload->>'teamSize')::integer;
    target_points := coalesce(payload->>'points_available',
      payload->>'pointsAvailable')::numeric;
    target_order := coalesce(payload->>'display_order',
      payload->>'displayOrder', target_round::text)::integer;
  exception when others then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_ROUND_INPUT_INVALID';
  end;
  if target_round is null or target_round not between 1 and 3
     or target_format not in ('BB', 'SC', 'SI')
     or target_name = '' or pg_catalog.length(target_name) > 160
     or target_team_size is null or target_points is null
     or target_order is null
     or target_team_size <> (case when target_format = 'SI' then 1 else 2 end)
     or target_points < 0 or target_order not between 1 and 99
     or pg_catalog.upper(coalesce(payload->>'status', 'UPCOMING')) <> 'UPCOMING'
  then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_ROUND_INPUT_INVALID';
  end if;
  select value.* into current_value
  from scoring_authority.rounds value
  where value.tournament_id = '2026' and value.round_number = target_round
  for update;
  if current_value.tournament_id is null then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_EXISTING_ROUND_REQUIRED';
  end if;
  if current_value.status <> 'UPCOMING' then
    raise exception using errcode = '55000',
      message = 'TOURNAMENT_SETUP_ROUND_STARTED_LOCKED';
  end if;
  select value.* into current_detail
  from scoring_authority.tournament_setup_round_details_v1 value
  where value.tournament_id = '2026' and value.round_number = target_round
  for update;
  changed_value := current_value.tournament_id is null
    or current_value.format is distinct from target_format
    or current_value.name is distinct from target_name
    or current_value.handicap_allowance is distinct from target_allowance
    or current_detail.team_size is distinct from target_team_size
    or current_detail.points_available is distinct from target_points
    or current_detail.display_order is distinct from target_order;
  if changed_value then
    dependencies := production_control.tournament_setup_dependency_codes_v1(
      null, null, target_round, null, 'ROUND'
    );
    if pg_catalog.jsonb_array_length(dependencies) > 0 then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'TOURNAMENT_SETUP_DEPENDENCY_BLOCKED',
        'blockers', dependencies
      );
    end if;
    update scoring_authority.rounds set
      format = target_format,
      name = target_name,
      handicap_allowance = target_allowance,
      source_payload = pg_catalog.jsonb_set(
        source_payload, array['Points Available']::text[],
        pg_catalog.to_jsonb(target_points), true
      )
    where tournament_id = '2026' and round_number = target_round
      and status = 'UPCOMING';
    insert into scoring_authority.tournament_setup_round_details_v1 (
      tournament_id, round_number, team_size, points_available,
      display_order, setup_revision, updated_by_player_id
    ) values (
      '2026', target_round, target_team_size, target_points,
      target_order, next_revision, actor_player
    ) on conflict (tournament_id, round_number) do update set
      team_size = excluded.team_size,
      points_available = excluded.points_available,
      display_order = excluded.display_order,
      setup_revision = excluded.setup_revision,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
    update scoring_authority.tournament_setup_match_details_v1 set
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      setup_revision = next_revision,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = '2026' and round_number = target_round;
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'changed', changed_value,
    'targetKind', 'ROUND', 'targetId', target_round::text,
    'safeMetadata', pg_catalog.jsonb_build_object(
      'roundNumber', target_round,
      'format', target_format,
      'teamSizePerSide', target_team_size,
      'pointsAvailable', target_points,
      'status', 'UPCOMING'
    )
  );
end;
$$;


ALTER FUNCTION production_control.apply_tournament_setup_round_v1(input jsonb, next_revision bigint, actor_player text) OWNER TO postgres;

--
-- Name: apply_tournament_setup_scoring_context_v1(jsonb, bigint, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_tournament_setup_scoring_context_v1(input jsonb, next_revision bigint, actor_player text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  payload jsonb := case
    when pg_catalog.jsonb_typeof(input->'scoring_context') = 'object'
      then input->'scoring_context'
    else input end;
  target_match text := pg_catalog.btrim(coalesce(
    payload->>'match_id', payload->>'matchId', ''
  ));
  match_value scoring_authority.matches%rowtype;
  current_snapshot scoring_authority.scoring_snapshots%rowtype;
  round_value scoring_authority.rounds%rowtype;
  detail_value scoring_authority.tournament_setup_match_details_v1%rowtype;
  course_value scoring_authority.tournament_setup_course_tees_v1%rowtype;
  current_handicap uuid;
  holes_value jsonb;
  participant_manifest jsonb;
  preparation_fingerprint text;
  next_snapshot_revision bigint;
  next_snapshot_id text;
  context_value jsonb;
  participant_item jsonb;
  next_snapshot_hash text;
  dependencies jsonb;
  expected_count integer;
  changed_value boolean := true;
begin
  if target_match = '' then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_SCORING_CONTEXT_INPUT_INVALID';
  end if;
  select value.* into strict match_value
  from scoring_authority.matches value
  where value.tournament_id = '2026' and value.match_id = target_match
  for update;
  perform production_control.assert_tournament_setup_match_mutable_v1(
    target_match
  );
  select value.* into strict current_snapshot
  from scoring_authority.scoring_snapshots value
  where value.snapshot_id = match_value.scoring_snapshot_id
    and value.match_id = target_match for update;
  select value.* into strict round_value
  from scoring_authority.rounds value
  where value.tournament_id = '2026'
    and value.round_number = match_value.round_number;
  if match_value.format <> round_value.format then
    raise exception using errcode = '55000',
      message = 'TOURNAMENT_SETUP_MATCH_ROUND_FORMAT_MISMATCH';
  end if;
  select value.* into strict detail_value
  from scoring_authority.tournament_setup_match_details_v1 value
  where value.match_id = target_match for update;
  select value.* into strict course_value
  from scoring_authority.tournament_setup_course_tees_v1 value
  where value.tournament_id = '2026'
    and value.course_id = detail_value.course_id
    and value.tee_id = detail_value.tee_id;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'hole_number', hole.hole_number, 'par', hole.par,
    'stroke_index', hole.stroke_index, 'yardage', hole.yardage
  ) order by hole.hole_number) into holes_value
  from scoring_authority.tournament_setup_course_holes_v1 hole
  where hole.tournament_id = '2026'
    and hole.course_id = detail_value.course_id
    and hole.tee_id = detail_value.tee_id;
  if pg_catalog.jsonb_array_length(coalesce(holes_value, '[]'::jsonb)) <> 18
     or (select pg_catalog.sum((value->>'par')::integer)
       from pg_catalog.jsonb_array_elements(holes_value) value)
       <> course_value.par then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_COURSE_HOLES_INCOMPLETE';
  end if;
  expected_count := case when match_value.format = 'SI' then 2 else 4 end;
  if (select pg_catalog.count(*)
      from scoring_authority.match_participants participant
      where participant.match_id = target_match) <> expected_count then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_PAIRINGS_INCOMPLETE';
  end if;
  select current_value.revision_id into strict current_handicap
  from scoring_authority.handicap_revision_current current_value
  where current_value.tournament_id = '2026';
  if exists (
    select 1 from scoring_authority.match_participants participant
    where participant.match_id = target_match
      and not exists (
        select 1 from scoring_authority.handicap_revision_entries entry
        where entry.revision_id = current_handicap
          and entry.tournament_id = '2026'
          and entry.player_id = participant.player_id
      )
  ) then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_APPROVED_HANDICAP_COVERAGE_REQUIRED';
  end if;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'player_id', participant.player_id,
    'team_side', participant.team_side,
    'player_slot', participant.player_slot
  ) order by participant.team_side, participant.player_slot)
  into participant_manifest
  from scoring_authority.match_participants participant
  where participant.match_id = target_match;
  preparation_fingerprint := production_control.tournament_setup_hash_v1(
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-tournament-setup-v1',
      'tournament_id', '2026', 'match_id', target_match,
      'round_number', match_value.round_number, 'format', match_value.format,
      'handicap_allowance', round_value.handicap_allowance,
      'course_id', detail_value.course_id, 'tee', detail_value.tee_id,
      'rating', course_value.rating, 'slope', course_value.slope,
      'par', course_value.par, 'holes', holes_value,
      'participants', participant_manifest,
      'handicap_revision_id', current_handicap,
      'setup_revision', detail_value.setup_revision
    )
  );
  if detail_value.prepared_setup_revision = detail_value.setup_revision
     and detail_value.prepared_configuration_fingerprint =
       preparation_fingerprint
     and current_snapshot.handicap_revision_id = current_handicap
     and current_snapshot.course_id = detail_value.course_id
     and current_snapshot.tee = detail_value.tee_id then
    changed_value := false;
  end if;
  if changed_value then
    dependencies := production_control.tournament_setup_dependency_codes_v1(
      null, null, match_value.round_number, target_match, 'SCORING_CONTEXT'
    );
    if pg_catalog.jsonb_array_length(dependencies) > 0 then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'TOURNAMENT_SETUP_DEPENDENCY_BLOCKED',
        'blockers', dependencies
      );
    end if;
    select coalesce(pg_catalog.max(snapshot.snapshot_revision), 0) + 1
      into next_snapshot_revision
    from scoring_authority.scoring_snapshots snapshot
    where snapshot.match_id = target_match;
    next_snapshot_id := target_match || ':S' || next_snapshot_revision::text;
    next_snapshot_hash := production_control.tournament_setup_hash_v1(
      pg_catalog.jsonb_build_object(
        'preparation_fingerprint', preparation_fingerprint,
        'snapshot_revision', next_snapshot_revision,
        'state', 'PREPARING'
      )
    );
    insert into scoring_authority.scoring_snapshots (
      snapshot_id, tournament_id, match_id, snapshot_revision,
      scoring_rules_version, format, handicap_allowance,
      course_id, tee, rating, slope, par, match_netting_baseline,
      hole_definitions, participant_configuration, team_configuration,
      effective_at, canonical_hash, handicap_revision_id
    ) values (
      next_snapshot_id, '2026', target_match, next_snapshot_revision,
      current_snapshot.scoring_rules_version, match_value.format,
      round_value.handicap_allowance,
      detail_value.course_id, detail_value.tee_id, course_value.rating,
      course_value.slope, course_value.par,
      current_snapshot.match_netting_baseline, holes_value,
      current_snapshot.participant_configuration,
      current_snapshot.team_configuration,
      pg_catalog.clock_timestamp(), next_snapshot_hash, current_handicap
    );
    update scoring_authority.matches set
      scoring_snapshot_id = next_snapshot_id,
      match_revision = match_revision + 1,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = target_match;
    context_value := production_control.handicap_v1_match_context(
      target_match, current_handicap
    );
    for participant_item in select value
      from pg_catalog.jsonb_array_elements(
        context_value->'participants'
      ) item(value)
    loop
      update scoring_authority.match_participants set
        tournament_handicap =
          (participant_item->>'tournament_handicap')::numeric,
        handicap_index = (participant_item->>'handicap_index')::numeric,
        course_handicap = (participant_item->>'course_handicap')::numeric,
        playing_handicap = (participant_item->>'playing_handicap')::numeric,
        final_strokes = (participant_item->>'final_strokes')::integer,
        handicap_revision_id = current_handicap
      where match_id = target_match
        and player_id = participant_item->>'player_id';
    end loop;
    next_snapshot_hash := production_control.tournament_setup_hash_v1(
      pg_catalog.jsonb_build_object(
        'preparation_fingerprint', preparation_fingerprint,
        'snapshot_revision', next_snapshot_revision,
        'participants', context_value->'participant_configuration',
        'teams', context_value->'team_configuration'
      )
    );
    update scoring_authority.scoring_snapshots set
      participant_configuration = context_value->'participant_configuration',
      team_configuration = context_value->'team_configuration',
      canonical_hash = next_snapshot_hash,
      handicap_revision_id = current_handicap
    where snapshot_id = next_snapshot_id;
    delete from scoring_authority.match_holes hole
    where hole.match_id = target_match;
    insert into scoring_authority.match_holes (
      match_id, hole_number, snapshot_id, stroke_index, par, yardage
    ) select target_match, (value->>'hole_number')::integer,
      next_snapshot_id, (value->>'stroke_index')::integer,
      (value->>'par')::integer, nullif(value->>'yardage', '')::integer
    from pg_catalog.jsonb_array_elements(holes_value) value;
    update scoring_authority.tournament_setup_match_details_v1 set
      prepared_setup_revision = setup_revision,
      prepared_configuration_fingerprint = preparation_fingerprint,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = target_match;
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'changed', changed_value,
    'targetKind', 'SCORING_CONTEXT', 'targetId', target_match,
    'snapshotPrepared', true,
    'safeMetadata', pg_catalog.jsonb_build_object(
      'matchId', target_match,
      'snapshotId', case when changed_value then next_snapshot_id
        else current_snapshot.snapshot_id end,
      'snapshotRevision', case when changed_value then next_snapshot_revision
        else current_snapshot.snapshot_revision end,
      'handicapRevisionId', current_handicap,
      'scoringPermissionGranted', false,
      'scoringMutationCreated', false
    )
  );
exception when no_data_found then
  raise exception using errcode = '22023',
    message = 'TOURNAMENT_SETUP_SCORING_CONTEXT_REQUIRED_FACT_MISSING';
end;
$$;


ALTER FUNCTION production_control.apply_tournament_setup_scoring_context_v1(input jsonb, next_revision bigint, actor_player text) OWNER TO postgres;

--
-- Name: apply_tournament_setup_team_v1(jsonb, bigint, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_tournament_setup_team_v1(input jsonb, next_revision bigint, actor_player text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  payload jsonb := case when pg_catalog.jsonb_typeof(input->'team') = 'object'
    then input->'team' else input end;
  target_team text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    payload->>'team_id', payload->>'teamId', ''
  )));
  target_captain text;
  current_team scoring_authority.teams%rowtype;
  current_detail scoring_authority.tournament_setup_team_details_v1%rowtype;
  current_captain text;
  next_name text;
  captain_supplied boolean;
  changed_value boolean := false;
  dependencies jsonb;
begin
  select value.* into strict current_team
  from scoring_authority.teams value
  where value.tournament_id = '2026' and value.team_id = target_team
  for update;
  select value.* into current_detail
  from scoring_authority.tournament_setup_team_details_v1 value
  where value.tournament_id = '2026' and value.team_id = target_team
  for update;
  if coalesce(payload->>'team_side', payload->>'teamSide',
       current_team.team_side::text) <> current_team.team_side::text then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_TEAM_SIDE_IMMUTABLE';
  end if;
  next_name := case when payload ? 'team_name' or payload ? 'name'
    then pg_catalog.btrim(coalesce(payload->>'team_name', payload->>'name'))
    else current_team.name end;
  if next_name = '' or pg_catalog.length(next_name) > 160 then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_TEAM_NAME_INVALID';
  end if;
  captain_supplied := payload ? 'captain_player_id' or payload ? 'captainPlayerId';
  current_captain := coalesce(current_detail.captain_player_id,
    nullif(current_team.source_payload->>'Captain', ''));
  target_captain := case when captain_supplied then nullif(
    pg_catalog.upper(pg_catalog.btrim(coalesce(
      payload->>'captain_player_id', payload->>'captainPlayerId', ''
    ))), '') else current_captain end;
  if target_captain is not null and not exists (
    select 1 from scoring_authority.tournament_players membership
    where membership.tournament_id = '2026'
      and membership.player_id = target_captain
      and membership.team_id = target_team
      and membership.team_side = current_team.team_side
      and membership.participation_status = 'ACTIVE'
  ) then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_CAPTAIN_ACTIVE_TEAM_MEMBERSHIP_REQUIRED';
  end if;
  changed_value := current_team.name is distinct from next_name
    or current_captain is distinct from target_captain;
  if changed_value then
    dependencies := production_control.tournament_setup_dependency_codes_v1(
      target_captain, target_team, null, null, 'TEAM'
    );
    if pg_catalog.jsonb_array_length(dependencies) > 0 then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'TOURNAMENT_SETUP_DEPENDENCY_BLOCKED',
        'blockers', dependencies
      );
    end if;
    update scoring_authority.teams set
      name = next_name,
      source_payload = case when captain_supplied then pg_catalog.jsonb_set(
        source_payload, array['Captain']::text[],
        pg_catalog.to_jsonb(coalesce(target_captain, '')), true
      ) else source_payload end
    where tournament_id = '2026' and team_id = target_team;
    insert into scoring_authority.tournament_setup_team_details_v1 (
      tournament_id, team_id, captain_player_id, setup_revision,
      updated_by_player_id
    ) values (
      '2026', target_team, target_captain, next_revision, actor_player
    ) on conflict (tournament_id, team_id) do update set
      captain_player_id = excluded.captain_player_id,
      setup_revision = excluded.setup_revision,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'changed', changed_value,
    'targetKind', 'TEAM', 'targetId', target_team,
    'safeMetadata', pg_catalog.jsonb_build_object(
      'teamSide', current_team.team_side,
      'nameChanged', current_team.name is distinct from next_name,
      'captainChanged', current_captain is distinct from target_captain
    )
  );
exception when no_data_found then
  raise exception using errcode = '22023',
    message = 'TOURNAMENT_SETUP_TEAM_NOT_FOUND';
end;
$$;


ALTER FUNCTION production_control.apply_tournament_setup_team_v1(input jsonb, next_revision bigint, actor_player text) OWNER TO postgres;

--
-- Name: apply_tournament_setup_tournament_v1(jsonb, bigint, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.apply_tournament_setup_tournament_v1(input jsonb, next_revision bigint, actor_player text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  payload jsonb := case when pg_catalog.jsonb_typeof(input->'tournament') = 'object'
    then input->'tournament' else input end;
  current_tournament scoring_authority.tournaments%rowtype;
  current_operational scoring_authority.tournament_setup_operational_v1%rowtype;
  next_name text;
  next_destination text;
  next_start date;
  next_end date;
  next_timezone text;
  requested_status text;
  metadata_supplied boolean;
  changed_value boolean := false;
begin
  select value.* into strict current_tournament
  from scoring_authority.tournaments value
  where value.tournament_id = '2026' for update;
  select value.* into current_operational
  from scoring_authority.tournament_setup_operational_v1 value
  where value.tournament_id = '2026' for update;

  if coalesce(payload->>'tournament_id', payload->>'tournamentId', '2026')
       <> '2026'
     or coalesce(payload->>'tournament_year', payload->>'tournamentYear',
       payload->>'year', '2026') <> '2026'
     or coalesce(payload->>'source_workbook_id', payload->>'sourceWorkbookId',
       current_tournament.source_workbook_id)
       <> current_tournament.source_workbook_id then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_IMMUTABLE_RESOURCE_FIELD';
  end if;
  requested_status := pg_catalog.upper(pg_catalog.btrim(coalesce(
    payload->>'operational_status', payload->>'status', 'UPCOMING'
  )));
  if requested_status <> 'UPCOMING' then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_OPERATIONAL_STATUS_OWNER_DECISION_REQUIRED';
  end if;

  next_name := case
    when payload ? 'tournament_name'
      then pg_catalog.btrim(payload->>'tournament_name')
    when payload ? 'name'
      then pg_catalog.btrim(payload->>'name')
    else current_tournament.name end;
  if next_name = '' or pg_catalog.length(next_name) > 240 then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_NAME_INVALID';
  end if;
  next_destination := case
    when payload ? 'destination' then nullif(pg_catalog.btrim(
      payload->>'destination'
    ), '') else current_operational.destination end;
  next_timezone := case when payload ? 'time_zone' or payload ? 'timezone'
    then nullif(pg_catalog.btrim(coalesce(payload->>'time_zone',
      payload->>'timezone')), '')
    else current_operational.timezone end;
  begin
    next_start := case
      when payload ? 'start_date' then nullif(payload->>'start_date', '')::date
      when payload ? 'startDate' then nullif(payload->>'startDate', '')::date
      else current_operational.start_date end;
    next_end := case
      when payload ? 'end_date' then nullif(payload->>'end_date', '')::date
      when payload ? 'endDate' then nullif(payload->>'endDate', '')::date
      else current_operational.end_date end;
  exception when others then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_DATES_INVALID';
  end;
  if next_start is not null and next_end is not null and next_start > next_end then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_DATES_INVALID';
  end if;
  if next_timezone is not null and not exists (
    select 1 from pg_catalog.pg_timezone_names timezone_value
    where timezone_value.name = next_timezone
  ) then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_TIMEZONE_INVALID';
  end if;
  if next_destination is not null and pg_catalog.length(next_destination) > 240 then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_DESTINATION_INVALID';
  end if;

  metadata_supplied := payload ? 'destination' or payload ? 'start_date'
    or payload ? 'startDate' or payload ? 'end_date' or payload ? 'endDate'
    or payload ? 'time_zone' or payload ? 'timezone';
  if current_tournament.name is distinct from next_name then
    update scoring_authority.tournaments set
      name = next_name, updated_at = pg_catalog.clock_timestamp()
    where tournament_id = '2026';
    changed_value := true;
  end if;
  if metadata_supplied and (
    current_operational.tournament_id is null
    or current_operational.destination is distinct from next_destination
    or current_operational.start_date is distinct from next_start
    or current_operational.end_date is distinct from next_end
    or current_operational.timezone is distinct from next_timezone
  ) then
    insert into scoring_authority.tournament_setup_operational_v1 (
      tournament_id, destination, start_date, end_date, timezone,
      operational_status, setup_revision, updated_by_player_id
    ) values (
      '2026', next_destination, next_start, next_end, next_timezone,
      'UPCOMING', next_revision, actor_player
    ) on conflict (tournament_id) do update set
      destination = excluded.destination,
      start_date = excluded.start_date,
      end_date = excluded.end_date,
      timezone = excluded.timezone,
      operational_status = 'UPCOMING',
      setup_revision = excluded.setup_revision,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
    changed_value := true;
  end if;
  if metadata_supplied then
    update scoring_authority.game_center_presentations as presentation set
      tournament_location = coalesce(next_destination, ''),
      tournament_time_zone = coalesce(next_timezone, 'America/Chicago'),
      source_payload_hash = production_control.tournament_setup_hash_v1(
        pg_catalog.jsonb_build_object(
          'contractVersion', 'production-tournament-setup-v1',
          'tournamentId', '2026',
          'setupRevision', next_revision,
          'matchId', presentation.match_id,
          'destination', next_destination,
          'timeZone', next_timezone,
          'sourceWorkbookId', presentation.source_workbook_id
        )
      ),
      imported_by = 'production-tournament-setup-v1',
      source_updated_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp()
    where presentation.tournament_id = '2026'
      and (
        presentation.tournament_location is distinct from
          coalesce(next_destination, '')
        or presentation.tournament_time_zone is distinct from
          coalesce(next_timezone, 'America/Chicago')
      );
    if found then
      changed_value := true;
    end if;
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'changed', changed_value,
    'targetKind', 'TOURNAMENT', 'targetId', '2026',
    'safeMetadata', pg_catalog.jsonb_build_object(
      'nameChanged', current_tournament.name is distinct from next_name,
      'operationalMetadataChanged', metadata_supplied and changed_value,
      'status', 'UPCOMING', 'statusEditable', false
    )
  );
end;
$$;


ALTER FUNCTION production_control.apply_tournament_setup_tournament_v1(input jsonb, next_revision bigint, actor_player text) OWNER TO postgres;

--
-- Name: assert_access_governance_owner_v1(text, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_access_governance_owner_v1(target_tournament text, actor_player text, actor_auth_user uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
begin
  if not exists (
    select 1
    from production_control.tournament_owner_capabilities_v1 owner_value
    where owner_value.tournament_id = target_tournament
      and owner_value.player_id = actor_player
      and owner_value.auth_user_id = actor_auth_user
      and owner_value.status = 'ACTIVE'
      and owner_value.revoked_at is null
  ) then
    raise exception using errcode = '42501',
      message = 'ACCESS_GOVERNANCE_ACTIVE_OWNER_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_access_governance_owner_v1(target_tournament text, actor_player text, actor_auth_user uuid) OWNER TO postgres;

--
-- Name: assert_access_governance_runtime_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_access_governance_runtime_v1(input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $_$
begin
  if input->>'contract_version' is distinct from
       'production-access-governance-v1'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'tournament_id' is distinct from '2026'
     or pg_catalog.upper(pg_catalog.btrim(coalesce(
       input->>'actor_player_id', ''
     ))) !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
     or coalesce(input->>'actor_auth_user_id', '')
       !~ '^[0-9a-fA-F-]{36}$' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ACCESS_GOVERNANCE_SCOPE_REQUIRED';
  end if;
  perform production_control.assert_player_access_runtime_v1(
    input || pg_catalog.jsonb_build_object(
      'contract_version', 'production-players-access-v1',
      'authorization', pg_catalog.jsonb_build_object(
        'player_id', input->>'actor_player_id',
        'auth_user_id', input->>'actor_auth_user_id',
        'tournament_id', '2026',
        'role', 'DIRECTOR'
      )
    )
  );
end;
$_$;


ALTER FUNCTION production_control.assert_access_governance_runtime_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_access_governance_safe_reason_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_access_governance_safe_reason_v1(reason_value text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if pg_catalog.length(pg_catalog.btrim(coalesce(reason_value, '')))
       not between 10 and 500
     or reason_value ~ '@'
     or reason_value ~ '\+[1-9][0-9]{7,14}'
     or reason_value ~* '(bearer[[:space:]]|eyJ[a-zA-Z0-9_-]{10,}|secret|token=)'
  then
    raise exception using errcode = '22023',
      message = 'ACCESS_GOVERNANCE_SAFE_REASON_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_access_governance_safe_reason_v1(reason_value text) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: resource_scope; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.resource_scope (
    scope_key text NOT NULL,
    project_ref text NOT NULL,
    project_url text NOT NULL,
    google_workbook_id text NOT NULL,
    vercel_project text NOT NULL,
    canonical_domain text NOT NULL,
    current_tournament_id text NOT NULL,
    current_tournament_year integer NOT NULL,
    current_tournament_read_authority text DEFAULT 'GOOGLE'::text NOT NULL,
    scoring_authority text DEFAULT 'GOOGLE'::text NOT NULL,
    participant_identity_authority text DEFAULT 'PASSPORT'::text NOT NULL,
    public_supabase_reads_enabled boolean DEFAULT false NOT NULL,
    scoring_ingress_enabled boolean DEFAULT false NOT NULL,
    google_writes_enabled boolean DEFAULT false NOT NULL,
    auth_user_creation_enabled boolean DEFAULT false NOT NULL,
    odds_publication_enabled boolean DEFAULT false NOT NULL,
    workers_enabled boolean DEFAULT false NOT NULL,
    contract_version text DEFAULT 'production-foundation-v1'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    odds_publication_authority text DEFAULT 'GOOGLE'::text NOT NULL,
    CONSTRAINT production_resource_current_read_authority_check CHECK ((current_tournament_read_authority = ANY (ARRAY['GOOGLE'::text, 'SUPABASE'::text]))),
    CONSTRAINT production_resource_identity_authority_check CHECK ((participant_identity_authority = ANY (ARRAY['PASSPORT'::text, 'SUPABASE'::text]))),
    CONSTRAINT production_resource_odds_publication_authority_check CHECK ((odds_publication_authority = ANY (ARRAY['GOOGLE'::text, 'SUPABASE'::text]))),
    CONSTRAINT production_resource_scoring_authority_check CHECK ((scoring_authority = ANY (ARRAY['GOOGLE'::text, 'SUPABASE'::text]))),
    CONSTRAINT resource_scope_canonical_domain_check CHECK ((canonical_domain = 'https://baggerinv.com'::text)),
    CONSTRAINT resource_scope_current_tournament_id_check CHECK ((current_tournament_id = '2026'::text)),
    CONSTRAINT resource_scope_current_tournament_year_check CHECK ((current_tournament_year = 2026)),
    CONSTRAINT resource_scope_google_workbook_id_check CHECK ((google_workbook_id = '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'::text)),
    CONSTRAINT resource_scope_project_ref_check CHECK ((project_ref = 'ymqhhtxaywtqllynrmxe'::text)),
    CONSTRAINT resource_scope_project_url_check CHECK ((project_url = 'https://ymqhhtxaywtqllynrmxe.supabase.co'::text)),
    CONSTRAINT resource_scope_scope_key_check CHECK ((scope_key = 'BAGGER_INV_PRODUCTION'::text)),
