ALTER TABLE production_control.resource_scope OWNER TO postgres;

--
-- Name: assert_active_production_director_sync_actor(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_active_production_director_sync_actor(input jsonb, required_phase text) RETURNS production_control.resource_scope
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth'
    AS $$
declare
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  actor_user uuid;
  actor_player text := btrim(coalesce(input->>'actor_player_id', ''));
begin
  resource := production_control.assert_production_cutover_read_scope(input, required_phase);
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';

  begin
    actor_user := nullif(btrim(coalesce(input->>'actor_auth_user_id', '')), '')::uuid;
  exception when others then
    raise exception using errcode = '42501', message = 'PRODUCTION_DIRECTOR_SYNC_ACTOR_REQUIRED';
  end;

  if actor_user is null
     or actor_player = ''
     or resource.participant_identity_authority <> 'SUPABASE'
     or upper(btrim(coalesce(input->>'operation_authority', ''))) <> 'GOOGLE_DIRECTOR_SYNC'
     or coalesce((input->>'expected_activation_revision')::bigint, -1)
       <> activation.activation_revision
     or not exists (
       select 1
       from production_control.director_entitlements entitlement
       join participant_identity.user_player_links link
         on link.auth_user_id = entitlement.auth_user_id
        and link.player_id = entitlement.player_id
        and link.status = 'ACTIVE'
       join participant_identity.tournament_roles role_value
         on role_value.tournament_id = entitlement.tournament_id
        and role_value.auth_user_id = entitlement.auth_user_id
        and role_value.role = 'DIRECTOR'
        and role_value.role_active
       join auth.users auth_user
         on auth_user.id = entitlement.auth_user_id
        and auth_user.email_confirmed_at is not null
       where entitlement.auth_user_id = actor_user
         and entitlement.player_id = actor_player
         and entitlement.tournament_id = resource.current_tournament_id
         and entitlement.status = 'ACTIVE'
     ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_ACTIVE_DIRECTOR_SYNC_ENTITLEMENT_REQUIRED';
  end if;

  return resource;
end;
$$;


ALTER FUNCTION production_control.assert_active_production_director_sync_actor(input jsonb, required_phase text) OWNER TO postgres;

--
-- Name: assert_annual_calcutta_runtime_v1(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_calcutta_runtime_v1(input jsonb, expected_operation text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  authority production_control.annual_scoring_runtime_authorities_v1%rowtype;
  annual_resource production_control.future_tournament_resources_v1%rowtype;
  activation production_control.cutover_activation_state%rowtype;
begin
  -- The dispatcher and this target-side assertion both bind the exact
  -- pointer/runtime/destination. Keeping the target-side check means a direct
  -- service-role call cannot bypass the annual allowlist.
  if production_control.assert_annual_scoring_runtime_v1(
       input, expected_operation, null
     ) = '2026' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CALCUTTA_RUNTIME_REQUIRED';
  end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  select value.* into strict authority
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.runtime_generation_id = generation.runtime_generation_id;
  select value.* into strict annual_resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';

  if pointer.tournament_id = '2026'
     or input->>'contract_version' is distinct from 'production-calcutta-v1'
     or input->>'expected_current_tournament_id'
       is distinct from pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or input->>'expected_runtime_generation_id'
       is distinct from generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id'
       is distinct from generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id'
       is distinct from generation.admission_generation_id::text
     or coalesce((input->>'expected_activation_revision')::bigint, -1)
       <> activation.activation_revision
     or generation.pointer_revision <> pointer.pointer_revision
     or generation.authority <> 'SUPABASE'
     or generation.ingress_state <> 'OPEN'
     or catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision
     or authority.authority_status <> 'ACTIVE'
     or authority.admission_state <> 'OPEN'
     or authority.pointer_revision <> pointer.pointer_revision
     or authority.lifecycle_revision <> pointer.lifecycle_revision
     or authority.authority_generation_id is distinct from
       generation.authority_generation_id
     or authority.admission_generation_id is distinct from
       generation.admission_generation_id
     or annual_resource.resource_status <> 'CURRENT_RESOURCE_BOUND'
     or annual_resource.source_workbook_id is null
     or annual_resource.project_ref is distinct from input->>'project_ref'
     or annual_resource.project_url is distinct from input->>'project_url'
     or annual_resource.source_workbook_id
       is distinct from input->>'annual_destination_workbook_id' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CALCUTTA_RUNTIME_REQUIRED';
  end if;
  return pointer.tournament_id;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CALCUTTA_RUNTIME_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.assert_annual_calcutta_runtime_v1(input jsonb, expected_operation text) OWNER TO postgres;

--
-- Name: assert_annual_current_read_pre_side_games_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_current_read_pre_side_games_v1(input jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  annual_authority production_control.annual_scoring_runtime_authorities_v1%rowtype;
  annual_resource production_control.future_tournament_resources_v1%rowtype;
  google_destination jsonb;
  active_count integer;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  select value.* into strict annual_authority
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.runtime_generation_id = generation.runtime_generation_id
    and value.authority_status = 'ACTIVE'
    and value.admission_state = 'OPEN';
  select value.* into strict annual_resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = pointer.tournament_id;
  if pg_catalog.to_regclass(
       'production_control.future_google_writer_targets_v2'
     ) is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CURRENT_READ_RUNTIME_REQUIRED';
  end if;
  execute $destination$
    select pg_catalog.jsonb_build_object(
      'writerGenerationId', target.writer_generation_id,
      'destinationWorkbookId', target.destination_workbook_id,
      'targetContractFingerprint', target.target_contract_fingerprint,
      'writerDestinationWorkbookId', writer.destination_workbook_id
    )
    from production_control.future_google_writer_targets_v2 target
    join production_control.future_google_writer_generations_v2 writer
      on writer.writer_generation_id = target.writer_generation_id
     and writer.certification_status = 'CERTIFIED'
    where target.tournament_id = $1
      and target.contract_status = 'CERTIFIED'
  $destination$ into google_destination using pointer.tournament_id;
  select pg_catalog.count(*)::integer into active_count
  from production_control.future_annual_runtime_generations_v1 value
  where value.generation_status = 'ACTIVE';
  if pointer.tournament_id = '2026'
     or input->>'target_tournament_id' is distinct from pointer.tournament_id
     or input->>'expected_current_tournament_id'
       is distinct from pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or input->>'expected_runtime_generation_id'
       is distinct from generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id'
       is distinct from generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id'
       is distinct from generation.admission_generation_id::text
     or active_count <> 1
     or generation.pointer_revision <> pointer.pointer_revision
     or generation.authority <> 'SUPABASE'
     or generation.ingress_state <> 'OPEN'
     or catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision
     or annual_authority.pointer_revision <> pointer.pointer_revision
     or annual_authority.lifecycle_revision <> pointer.lifecycle_revision
     or annual_authority.authority_generation_id is distinct from
       generation.authority_generation_id
     or annual_authority.admission_generation_id is distinct from
       generation.admission_generation_id
     or annual_resource.resource_status <> 'CURRENT_RESOURCE_BOUND'
     or annual_resource.source_workbook_id is null
     or google_destination is null
     or google_destination->>'writerGenerationId' is distinct from
       annual_authority.google_writer_generation_id::text
     or google_destination->>'destinationWorkbookId' is distinct from
       annual_authority.destination_workbook_id
     or google_destination->>'writerDestinationWorkbookId' is distinct from
       annual_authority.destination_workbook_id
     or google_destination->>'destinationWorkbookId' is distinct from
       annual_resource.source_workbook_id
     or google_destination->>'targetContractFingerprint' is distinct from
       annual_authority.google_target_contract_fingerprint then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CURRENT_READ_RUNTIME_REQUIRED';
  end if;
  return pointer.tournament_id;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CURRENT_READ_RUNTIME_REQUIRED';
end;
$_$;


ALTER FUNCTION production_control.assert_annual_current_read_pre_side_games_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_annual_current_read_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_current_read_v1(input jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
