--
-- Name: odds_calculation_jobs; Type: TABLE; Schema: scoring_authority; Owner: postgres
--

CREATE TABLE scoring_authority.odds_calculation_jobs (
    job_id text NOT NULL,
    tournament_id text NOT NULL,
    phase text NOT NULL,
    total_iterations integer NOT NULL,
    completed_iterations integer DEFAULT 0 NOT NULL,
    engine_version text NOT NULL,
    publication_contract_version text NOT NULL,
    checkpoint_contract_version text NOT NULL,
    deterministic_seed text NOT NULL,
    input_fingerprint text NOT NULL,
    settings_fingerprint text NOT NULL,
    invocation_fingerprint text NOT NULL,
    source_revision jsonb DEFAULT '{}'::jsonb NOT NULL,
    input_snapshot jsonb NOT NULL,
    checkpoint_payload jsonb NOT NULL,
    checkpoint_hash text NOT NULL,
    checkpoint_count integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    claim_token uuid,
    lease_expires_at timestamp with time zone,
    requested_by text NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    output_timestamp timestamp with time zone NOT NULL,
    result_payload jsonb,
    result_fingerprint text,
    output_payload_bytes integer,
    resource_metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_error_code text,
    last_error_safe text,
    superseded_by text,
    superseded_at timestamp with time zone,
    publication_status text DEFAULT 'NOT_REQUESTED'::text NOT NULL,
    publication_reference jsonb DEFAULT '{}'::jsonb NOT NULL,
    input_configuration_id uuid,
    effective_settings_fingerprint text,
    input_bundle_fingerprint text,
    production_operation_mode text NOT NULL,
    production_deployment_commit text NOT NULL,
    production_candidate_hostname text,
    lease_owner text,
    runtime_generation_id uuid,
    CONSTRAINT odds_calculation_jobs_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT odds_calculation_jobs_check CHECK (((completed_iterations >= 0) AND (completed_iterations <= total_iterations))),
    CONSTRAINT odds_calculation_jobs_check1 CHECK (((invocation_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (invocation_fingerprint = job_id))),
    CONSTRAINT odds_calculation_jobs_checkpoint_count_check CHECK ((checkpoint_count >= 0)),
    CONSTRAINT odds_calculation_jobs_checkpoint_hash_check CHECK ((checkpoint_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT odds_calculation_jobs_checkpoint_payload_check CHECK ((jsonb_typeof(checkpoint_payload) = 'object'::text)),
    CONSTRAINT odds_calculation_jobs_input_fingerprint_check CHECK ((input_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT odds_calculation_jobs_input_snapshot_check CHECK ((jsonb_typeof(input_snapshot) = 'object'::text)),
    CONSTRAINT odds_calculation_jobs_job_id_check CHECK ((job_id ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT odds_calculation_jobs_output_payload_bytes_check CHECK (((output_payload_bytes IS NULL) OR (output_payload_bytes >= 0))),
    CONSTRAINT odds_calculation_jobs_phase_check CHECK ((phase = ANY (ARRAY['Pre-Tournament'::text, 'After Round 1'::text, 'After Round 2'::text, 'Round 3 Pairings Announced'::text, 'Final Results'::text]))),
    CONSTRAINT odds_calculation_jobs_publication_reference_check CHECK ((jsonb_typeof(publication_reference) = 'object'::text)),
    CONSTRAINT odds_calculation_jobs_publication_status_check CHECK ((publication_status = ANY (ARRAY['NOT_REQUESTED'::text, 'READY'::text, 'PUBLISHED'::text, 'STALE'::text, 'REHEARSAL_ONLY'::text]))),
    CONSTRAINT odds_calculation_jobs_resource_metrics_check CHECK ((jsonb_typeof(resource_metrics) = 'object'::text)),
    CONSTRAINT odds_calculation_jobs_result_fingerprint_check CHECK (((result_fingerprint IS NULL) OR (result_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT odds_calculation_jobs_result_payload_check CHECK (((result_payload IS NULL) OR (jsonb_typeof(result_payload) = 'object'::text))),
    CONSTRAINT odds_calculation_jobs_settings_fingerprint_check CHECK ((settings_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT odds_calculation_jobs_source_revision_check CHECK ((jsonb_typeof(source_revision) = 'object'::text)),
    CONSTRAINT odds_calculation_jobs_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'RETRYABLE'::text, 'SUPERSEDED'::text]))),
    CONSTRAINT odds_calculation_jobs_total_iterations_check CHECK ((total_iterations = ANY (ARRAY[10000, 25000, 50000, 100000]))),
    CONSTRAINT production_odds_deployment_commit_check CHECK (((production_deployment_commit IS NULL) OR (production_deployment_commit ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT production_odds_effective_settings_fingerprint_check CHECK (((effective_settings_fingerprint IS NULL) OR (effective_settings_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_odds_initial_publication_separation_check CHECK (
CASE
    WHEN (production_operation_mode = 'CERTIFICATION'::text) THEN COALESCE(((production_operation_mode = 'CERTIFICATION'::text) AND (production_deployment_commit ~ '^[0-9a-f]{40}$'::text) AND (production_candidate_hostname IS NULL) AND ((source_revision ->> 'certification_odds_contract'::text) = 'certification-odds-v1'::text) AND ((source_revision ->> 'resource_class'::text) = 'CERTIFICATION'::text) AND ((source_revision ->> 'resource_id'::text) ~~ 'CERTIFICATION:%'::text) AND ((source_revision ->> 'installation_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND ((source_revision ->> 'certification_ingress_generation_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND (NOT (source_revision ?| ARRAY['rehearsal_fixture_contract'::text, 'rehearsal_fixture_fingerprint'::text, 'rehearsal_namespace'::text, 'google_publication_reference'::text])) AND (NOT (COALESCE((input_snapshot -> 'metadata'::text), '{}'::jsonb) ? 'productionRehearsalFixture'::text)) AND (((status = 'SUCCEEDED'::text) AND (publication_status = 'READY'::text) AND (publication_reference = '{}'::jsonb)) OR ((status = 'SUCCEEDED'::text) AND (publication_status = 'PUBLISHED'::text) AND ((publication_reference ->> 'contract_version'::text) = 'production-odds-publication-v1'::text) AND ((publication_reference ->> 'snapshot_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND (((publication_reference ->> 'publication_revision'::text))::bigint > 0) AND (((publication_reference ->> 'expected_predecessor_revision'::text))::bigint >= 0) AND (publication_reference ? 'expected_predecessor_snapshot_id'::text) AND ((publication_reference ->> 'request_fingerprint'::text) ~ '^[0-9a-f]{64}$'::text)) OR ((status = 'SUPERSEDED'::text) AND (publication_status = 'STALE'::text) AND (publication_reference = '{}'::jsonb)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'RETRYABLE'::text, 'FAILED'::text])) AND (publication_status = 'NOT_REQUESTED'::text) AND (publication_reference = '{}'::jsonb)))), false)
