    CASE production_operation_mode
        WHEN 'STEP11_REHEARSAL'::text THEN COALESCE(((publication_reference = '{}'::jsonb) AND (((status = 'SUCCEEDED'::text) AND (publication_status = 'REHEARSAL_ONLY'::text)) OR ((status = 'SUPERSEDED'::text) AND (publication_status = 'STALE'::text)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'RETRYABLE'::text, 'FAILED'::text])) AND (publication_status = 'NOT_REQUESTED'::text)))), false)
        WHEN 'PRODUCTION_CUTOVER'::text THEN COALESCE((((status = 'SUCCEEDED'::text) AND (publication_status = 'READY'::text) AND (publication_reference = '{}'::jsonb)) OR ((status = 'SUCCEEDED'::text) AND (publication_status = 'PUBLISHED'::text) AND ((publication_reference ->> 'contract_version'::text) = 'production-odds-publication-v1'::text) AND ((publication_reference ->> 'snapshot_id'::text) ~ '^[0-9a-fA-F-]{36}$'::text) AND (COALESCE(((publication_reference ->> 'publication_revision'::text))::bigint, (0)::bigint) > 0) AND (COALESCE(((publication_reference ->> 'expected_predecessor_revision'::text))::bigint, ('-1'::integer)::bigint) >= 0) AND (publication_reference ? 'expected_predecessor_snapshot_id'::text) AND ((publication_reference ->> 'request_fingerprint'::text) ~ '^[0-9a-f]{64}$'::text)) OR ((status = 'SUPERSEDED'::text) AND (publication_status = 'STALE'::text) AND (publication_reference = '{}'::jsonb)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'RETRYABLE'::text, 'FAILED'::text])) AND (publication_status = 'NOT_REQUESTED'::text) AND (publication_reference = '{}'::jsonb))), false)
        ELSE false
    END
END),
    CONSTRAINT production_odds_input_bundle_fingerprint_check CHECK (((input_bundle_fingerprint IS NULL) OR (input_bundle_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_odds_operation_mode_check CHECK (
CASE
    WHEN (production_operation_mode = 'CERTIFICATION'::text) THEN COALESCE(((production_operation_mode = 'CERTIFICATION'::text) AND (production_deployment_commit ~ '^[0-9a-f]{40}$'::text) AND (production_candidate_hostname IS NULL) AND ((source_revision ->> 'certification_odds_contract'::text) = 'certification-odds-v1'::text) AND ((source_revision ->> 'resource_class'::text) = 'CERTIFICATION'::text) AND ((source_revision ->> 'resource_id'::text) ~~ 'CERTIFICATION:%'::text) AND ((source_revision ->> 'installation_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND ((source_revision ->> 'certification_ingress_generation_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND (NOT (source_revision ?| ARRAY['rehearsal_fixture_contract'::text, 'rehearsal_fixture_fingerprint'::text, 'rehearsal_namespace'::text, 'google_publication_reference'::text])) AND (NOT (COALESCE((input_snapshot -> 'metadata'::text), '{}'::jsonb) ? 'productionRehearsalFixture'::text)) AND (((status = 'SUCCEEDED'::text) AND (publication_status = 'READY'::text) AND (publication_reference = '{}'::jsonb)) OR ((status = 'SUCCEEDED'::text) AND (publication_status = 'PUBLISHED'::text) AND ((publication_reference ->> 'contract_version'::text) = 'production-odds-publication-v1'::text) AND ((publication_reference ->> 'snapshot_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND (((publication_reference ->> 'publication_revision'::text))::bigint > 0) AND (((publication_reference ->> 'expected_predecessor_revision'::text))::bigint >= 0) AND (publication_reference ? 'expected_predecessor_snapshot_id'::text) AND ((publication_reference ->> 'request_fingerprint'::text) ~ '^[0-9a-f]{64}$'::text)) OR ((status = 'SUPERSEDED'::text) AND (publication_status = 'STALE'::text) AND (publication_reference = '{}'::jsonb)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'RETRYABLE'::text, 'FAILED'::text])) AND (publication_status = 'NOT_REQUESTED'::text) AND (publication_reference = '{}'::jsonb)))), false)
    ELSE ((production_operation_mode IS NULL) OR (production_operation_mode = ANY (ARRAY['STEP11_REHEARSAL'::text, 'PRODUCTION_CUTOVER'::text])))
END),
    CONSTRAINT production_odds_step11_rehearsal_fixture_check CHECK (
CASE
    WHEN (production_operation_mode = 'CERTIFICATION'::text) THEN COALESCE(((production_operation_mode = 'CERTIFICATION'::text) AND (production_deployment_commit ~ '^[0-9a-f]{40}$'::text) AND (production_candidate_hostname IS NULL) AND ((source_revision ->> 'certification_odds_contract'::text) = 'certification-odds-v1'::text) AND ((source_revision ->> 'resource_class'::text) = 'CERTIFICATION'::text) AND ((source_revision ->> 'resource_id'::text) ~~ 'CERTIFICATION:%'::text) AND ((source_revision ->> 'installation_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND ((source_revision ->> 'certification_ingress_generation_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND (NOT (source_revision ?| ARRAY['rehearsal_fixture_contract'::text, 'rehearsal_fixture_fingerprint'::text, 'rehearsal_namespace'::text, 'google_publication_reference'::text])) AND (NOT (COALESCE((input_snapshot -> 'metadata'::text), '{}'::jsonb) ? 'productionRehearsalFixture'::text)) AND (((status = 'SUCCEEDED'::text) AND (publication_status = 'READY'::text) AND (publication_reference = '{}'::jsonb)) OR ((status = 'SUCCEEDED'::text) AND (publication_status = 'PUBLISHED'::text) AND ((publication_reference ->> 'contract_version'::text) = 'production-odds-publication-v1'::text) AND ((publication_reference ->> 'snapshot_id'::text) ~ '^[0-9a-f-]{36}$'::text) AND (((publication_reference ->> 'publication_revision'::text))::bigint > 0) AND (((publication_reference ->> 'expected_predecessor_revision'::text))::bigint >= 0) AND (publication_reference ? 'expected_predecessor_snapshot_id'::text) AND ((publication_reference ->> 'request_fingerprint'::text) ~ '^[0-9a-f]{64}$'::text)) OR ((status = 'SUPERSEDED'::text) AND (publication_status = 'STALE'::text) AND (publication_reference = '{}'::jsonb)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'RETRYABLE'::text, 'FAILED'::text])) AND (publication_status = 'NOT_REQUESTED'::text) AND (publication_reference = '{}'::jsonb)))), false)
    ELSE
    CASE production_operation_mode
        WHEN 'STEP11_REHEARSAL'::text THEN COALESCE(((jsonb_typeof(source_revision) = 'object'::text) AND (jsonb_typeof(input_snapshot) = 'object'::text) AND (production_deployment_commit ~ '^[0-9a-f]{40}$'::text) AND (length(production_candidate_hostname) > 0) AND COALESCE(((source_revision ->> 'production_job_identity_contract'::text) = 'production-odds-calculation-job-identity-v2'::text), false) AND COALESCE(((source_revision ->> 'rehearsal_fixture_contract'::text) = 'production-odds-step11-rehearsal-fixture-v1'::text), false) AND COALESCE(((source_revision ->> 'rehearsal_fixture_fingerprint'::text) ~ '^[0-9a-f]{64}$'::text), false) AND COALESCE(((source_revision ->> 'rehearsal_namespace'::text) ~ '^STEP11_ODDS_[0-9a-f]{40}_[0-9a-f]{16}$'::text), false) AND COALESCE(((input_snapshot #>> '{metadata,productionRehearsalFixture,contractVersion}'::text[]) = 'production-odds-step11-rehearsal-fixture-v1'::text), false) AND COALESCE(((input_snapshot #>> '{metadata,productionRehearsalFixture,candidateSha}'::text[]) = production_deployment_commit), false) AND COALESCE(((input_snapshot #>> '{metadata,productionRehearsalFixture,candidateHostname}'::text[]) = production_candidate_hostname), false) AND COALESCE(((input_snapshot #>> '{metadata,productionRehearsalFixture,namespace}'::text[]) = (source_revision ->> 'rehearsal_namespace'::text)), false) AND COALESCE(((input_snapshot #>> '{metadata,productionRehearsalFixture,fixtureFingerprint}'::text[]) = (source_revision ->> 'rehearsal_fixture_fingerprint'::text)), false) AND COALESCE(((input_snapshot #> '{metadata,productionRehearsalFixture}'::text[]) @> '{"mirrorEligible": false, "publicationEligible": false, "externalGoogleWrites": 0, "databasePairingWrites": 0, "canonicalPairingsMutated": false}'::jsonb), false)), false)
        WHEN 'PRODUCTION_CUTOVER'::text THEN COALESCE(((jsonb_typeof(source_revision) = 'object'::text) AND (jsonb_typeof(input_snapshot) = 'object'::text) AND (production_deployment_commit ~ '^[0-9a-f]{40}$'::text) AND COALESCE(((source_revision ->> 'production_job_identity_contract'::text) = 'production-odds-calculation-job-identity-v2'::text), false) AND (production_candidate_hostname IS NULL) AND COALESCE((NOT (COALESCE((input_snapshot -> 'metadata'::text), '{}'::jsonb) ? 'productionRehearsalFixture'::text)), false) AND COALESCE((NOT (source_revision ? 'rehearsal_fixture_contract'::text)), false) AND COALESCE((NOT (source_revision ? 'rehearsal_fixture_fingerprint'::text)), false) AND COALESCE((NOT (source_revision ? 'rehearsal_namespace'::text)), false)), false)
        ELSE false
    END
END)
);


ALTER TABLE scoring_authority.odds_calculation_jobs OWNER TO postgres;

--
-- Name: assert_annual_odds_job_scope_v1(jsonb, text, scoring_authority.odds_calculation_jobs); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_odds_job_scope_v1(input jsonb, target text, retained scoring_authority.odds_calculation_jobs) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare revision jsonb := retained.source_revision;
begin
  if retained.tournament_id is distinct from target
     or retained.runtime_generation_id is distinct from
       (input->>'expected_runtime_generation_id')::uuid
     or retained.production_operation_mode <> 'PRODUCTION_CUTOVER'
     or retained.production_deployment_commit is distinct from
       input->>'deployment_commit'
     or retained.production_candidate_hostname is not null
     or revision->>'production_job_identity_contract' is distinct from
       'production-odds-calculation-job-identity-v2'
     or revision->>'annual_odds_contract' is distinct from
       'production-annual-odds-dispatch-v1'
     or revision->>'annual_tournament_id' is distinct from target
     or revision->>'annual_runtime_generation_id' is distinct from
       input->>'expected_runtime_generation_id'
     or coalesce((revision->>'annual_pointer_revision')::bigint, -1)
       <> coalesce((input->>'expected_pointer_revision')::bigint, -2)
     or revision->>'annual_authority_generation_id' is distinct from
       input->>'expected_annual_authority_generation_id'
     or revision->>'annual_admission_generation_id' is distinct from
       input->>'expected_annual_admission_generation_id'
     or revision ? 'rehearsal_fixture_contract'
     or revision ? 'rehearsal_fixture_fingerprint'
     or revision ? 'rehearsal_namespace' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_ODDS_JOB_SCOPE_MISMATCH';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_annual_odds_job_scope_v1(input jsonb, target text, retained scoring_authority.odds_calculation_jobs) OWNER TO postgres;

--
-- Name: assert_annual_odds_runtime_v1(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_odds_runtime_v1(input jsonb, expected_odds_operation text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target text;
  annual_operation
    production_control.annual_odds_operation_allowlist_v1%rowtype;
  resource production_control.resource_scope%rowtype;
  runtime production_control.odds_calculation_runtime%rowtype;
  worker production_control.worker_controls%rowtype;
  worker_contract production_control.worker_contracts%rowtype;
  annual_resource production_control.future_tournament_resources_v1%rowtype;
  annual_catalog production_control.future_tournament_catalog_v1%rowtype;
begin
  select value.* into annual_operation
  from production_control.annual_odds_operation_allowlist_v1 value
  where value.operation_name = expected_odds_operation and value.enabled;
  if annual_operation.operation_name is null
     or input->>'annual_odds_dispatch_contract'
       is distinct from 'production-annual-odds-dispatch-v1'
     or input->>'annual_odds_operation'
       is distinct from annual_operation.operation_name then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ANNUAL_ODDS_OPERATION_NOT_ALLOWLISTED';
  end if;
  target := production_control.assert_annual_scoring_runtime_v1(
    input, 'dispatch_production_annual_odds_v1', null
  );
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict runtime
  from production_control.odds_calculation_runtime value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict worker
  from production_control.worker_controls value
  where value.worker_name = 'ODDS_CALCULATION';
  select value.* into strict worker_contract
  from production_control.worker_contracts value
  where value.worker_name = 'ODDS_CALCULATION';
  select value.* into strict annual_resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target;
  select value.* into strict annual_catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target;
  if target = '2026'
     -- The top-level resource tuple remains the immutable Step-12 platform
     -- assertion. The annual Odds target is a separate server-bound domain
     -- tuple and must match the current pointer-selected catalog row.
     or input->>'tournament_id' is distinct from '2026'
     or coalesce((input->>'tournament_year')::integer, 0) <> 2026
     or input->>'target_tournament_id' is distinct from target
     or coalesce((input->>'target_tournament_year')::integer, 0)
       <> annual_catalog.tournament_year
     or resource.odds_publication_authority <> 'SUPABASE'
     or not resource.odds_publication_enabled
     or resource.scoring_authority <> 'SUPABASE'
     or resource.current_tournament_read_authority <> 'SUPABASE'
     or not resource.workers_enabled
     or not runtime.enabled
     or runtime.operation_mode <> 'PRODUCTION_CUTOVER'
     or runtime.cutover_phase <> 'ODDS_WAR_ROOM'
     or runtime.deployment_commit is distinct from input->>'deployment_commit'
     or not worker.enabled or worker.google_writes_allowed
     or not worker_contract.operation_allowed
     or worker_contract.scheduler_installed
     or worker_contract.authoritative_write_allowed
     or annual_resource.resource_status <> 'CURRENT_RESOURCE_BOUND'
     or annual_resource.source_workbook_id is null
     or annual_resource.source_workbook_id is distinct from
       input->>'annual_destination_workbook_id'
     or exists (
       select 1 from production_control.worker_controls value
       where value.worker_name = 'ODDS_GOOGLE_MIRROR'
         and (value.enabled or value.google_writes_allowed)
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_ODDS_RUNTIME_REQUIRED';
  end if;
  return target;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_ODDS_RUNTIME_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.assert_annual_odds_runtime_v1(input jsonb, expected_odds_operation text) OWNER TO postgres;

--
-- Name: assert_annual_scoring_platform_v1(jsonb, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_scoring_platform_v1(input jsonb, required_phase text, required_worker text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  release production_control.postcutover_application_release_rebindings%rowtype;
  normal_head production_control.postcutover_normal_release_head%rowtype;
  normal_release
    production_control.postcutover_normal_release_rebindings%rowtype;
  binding production_control.maintenance_deployment_capability_bindings%rowtype;
  deployment_value text;
  commit_value text;
  contract_value text;
  ceiling_value text;
  requested_worker text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    required_worker, ''
  )));
  phase_rank integer := production_control.cutover_phase_rank(required_phase);
begin
  perform production_control.annual_scoring_platform_certification_v1(input);
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  select value.* into normal_head
  from production_control.postcutover_normal_release_head value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if found then
    select value.* into strict normal_release
    from production_control.postcutover_normal_release_rebindings value
    where value.release_rebind_id = normal_head.release_rebind_id
      and value.release_sequence = normal_head.release_sequence;
    select value.* into strict binding
    from production_control.maintenance_deployment_capability_bindings value
    where value.capability_binding_id = normal_release.capability_binding_id;
    deployment_value := normal_release.deployment_id;
    commit_value := normal_release.deployment_commit;
    contract_value := normal_release.capability_contract;
    ceiling_value := normal_release.capability_ceiling;
  else
    select value.* into release
    from production_control.postcutover_application_release_rebindings value
    where value.scope_key = 'BAGGER_INV_PRODUCTION';
    if found then
      select value.* into strict binding
      from production_control.maintenance_deployment_capability_bindings value
      where value.capability_binding_id = release.capability_binding_id;
      deployment_value := release.deployment_id;
      commit_value := release.deployment_commit;
      contract_value := release.capability_contract;
      ceiling_value := release.capability_ceiling;
    else
      select value.* into strict binding
      from production_control.maintenance_deployment_capability_bindings value
      where value.epoch_id = activation.authority_generation_id;
      deployment_value := binding.deployment_id;
      commit_value := binding.deployment_commit;
      contract_value := binding.contract_version;
      ceiling_value := binding.capability_ceiling;
    end if;
  end if;
  if input->>'deployment_id' is distinct from deployment_value
       or pg_catalog.lower(coalesce(input->>'deployment_commit', ''))
         is distinct from commit_value
       or input->>'deployment_capability_contract'
         is distinct from contract_value
       or input->>'deployment_capability_ceiling'
         is distinct from ceiling_value
       or binding.capability_fingerprint is distinct from pg_catalog.encode(
         extensions.digest(binding.capability_manifest::text, 'sha256'), 'hex'
       ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_ATTESTATION_REQUIRED';
  end if;
  if activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or activation.active_transition_epoch_id is not null
     or activation.authority_generation_id is distinct from
       nullif(input->>'expected_epoch_id', '')::uuid
     or activation.expected_deployment_commit is distinct from
       pg_catalog.lower(input->>'deployment_commit')
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_year <> 2026
     or resource.scoring_authority <> 'SUPABASE'
     or phase_rank < 0
     or production_control.cutover_phase_rank(
       coalesce(ceiling_value, binding.capability_ceiling)
     ) < phase_rank
     or gate.authority <> 'SUPABASE'
     or gate.active_epoch_id is distinct from
       activation.authority_generation_id then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_ATTESTATION_REQUIRED';
  end if;
  if requested_worker <> '' and (
       requested_worker not in (
         'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE'
       )
       or not resource.workers_enabled
       or not resource.google_writes_enabled
       or not exists (
         select 1
         from production_control.worker_controls controls
         join production_control.worker_contracts contracts
           using (worker_name)
         where controls.worker_name = requested_worker
           and controls.enabled and controls.google_writes_allowed
           and contracts.operation_allowed
           and contracts.requires_google_write
           and not contracts.authoritative_write_allowed
           and coalesce(controls.metadata->>'activation_epoch_id', '') =
             activation.authority_generation_id::text
           and coalesce(controls.metadata->>'deployment_commit', '') =
             activation.expected_deployment_commit
       )
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_WORKER_NOT_ENABLED';
  end if;
exception
  when invalid_text_representation then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_ATTESTATION_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.assert_annual_scoring_platform_v1(input jsonb, required_phase text, required_worker text) OWNER TO postgres;

--
-- Name: assert_annual_scoring_runtime_pre_side_games_v1(jsonb, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_scoring_runtime_pre_side_games_v1(input jsonb, expected_operation text, required_worker text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  operation production_control.annual_scoring_rpc_allowlist_v1%rowtype;
  active_generation_count integer;
  readiness jsonb;
  certified_writer jsonb;
begin
  -- The shared transaction lock is held through the invoked scoring RPC.
  -- Annual close/transition/abort take the exclusive counterpart of this
  -- exact legacy key, so an admitted mutation cannot cross the boundary.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into operation
  from production_control.annual_scoring_rpc_allowlist_v1 value
  where value.operation_name = expected_operation and value.enabled;
  if operation.operation_name is null
     or input->>'annual_scoring_dispatch_contract'
       is distinct from 'production-annual-scoring-dispatch-v1'
     or input->>'annual_scoring_operation'
       is distinct from operation.operation_name
     or coalesce(required_worker, '') is distinct from
       coalesce(operation.required_worker, '') then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ANNUAL_SCORING_OPERATION_NOT_ALLOWLISTED';
  end if;
  perform production_control.assert_annual_scoring_platform_v1(
    input, operation.required_phase, operation.required_worker
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if pointer.tournament_id = '2026' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_TARGET_REQUIRED';
  end if;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  select value.* into strict annual
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.runtime_generation_id = generation.runtime_generation_id;
-- Google runtime retired; canonical authority checks remain below.
  select pg_catalog.count(*)::integer into active_generation_count
  from production_control.future_annual_runtime_generations_v1 value
  where value.generation_status = 'ACTIVE';
  if input->>'expected_current_tournament_id'
       is distinct from pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or input->>'expected_runtime_generation_id'
       is distinct from generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id'
       is distinct from generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id'
       is distinct from generation.admission_generation_id::text
     or generation.authority_generation_id
       is distinct from annual.authority_generation_id
     or generation.admission_generation_id
       is distinct from annual.admission_generation_id
     or generation.pointer_revision <> pointer.pointer_revision
     or annual.pointer_revision <> pointer.pointer_revision
     or active_generation_count <> 1
     or catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision
     or annual.lifecycle_revision <> pointer.lifecycle_revision
     or annual.platform_tournament_id <> '2026'
     or annual.platform_authority_generation_id is distinct from
       nullif(input->>'expected_epoch_id', '')::uuid
     or annual.platform_admission_generation_id is distinct from (
       select value.admission_generation_id
       from production_control.annual_scoring_platform_certifications_v1 value
       where value.scope_key = 'BAGGER_INV_PRODUCTION'
     )
     or annual.authority_status not in ('ACTIVE', 'CLOSED')
     or (operation.operation_class = 'MUTATION' and (
       annual.authority_status <> 'ACTIVE'
       or annual.admission_state <> 'OPEN'
     ))
     or (operation.operation_class = 'WORKER' and (
       annual.authority_status <> 'ACTIVE'
       or annual.admission_state not in ('OPEN', 'CLOSING')
     ))
     or not exists (
       select 1 from scoring_authority.tournaments tournament_value
       where tournament_value.tournament_id = pointer.tournament_id
         and tournament_value.scoring_authority = 'SUPABASE'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_RUNTIME_REQUIRED';
  end if;
  if operation.operation_name = 'mutate_production_match_control'
     and pg_catalog.upper(coalesce(input->>'operation', '')) = 'MARK_LIVE'
  then
    readiness :=
      production_control.assert_future_production_match_scoring_ready_v1(
        input->>'match_id', pointer.tournament_id
      );
    if coalesce((readiness->>'ready')::boolean, false) is not true then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ANNUAL_MARK_LIVE_READINESS_REQUIRED';
    end if;
  end if;
  return pointer.tournament_id;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_RUNTIME_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.assert_annual_scoring_runtime_pre_side_games_v1(input jsonb, expected_operation text, required_worker text) OWNER TO postgres;

--
-- Name: assert_annual_scoring_runtime_v1(jsonb, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_scoring_runtime_v1(input jsonb, expected_operation text, required_worker text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target text;
begin
  target := production_control.assert_annual_scoring_runtime_pre_side_games_v1(
    input, expected_operation, required_worker
  );
  perform production_control.ensure_annual_side_game_runtime_v1(
    target, (input->>'expected_runtime_generation_id')::uuid,
    (input->>'expected_annual_authority_generation_id')::uuid,
    (input->>'expected_annual_admission_generation_id')::uuid,
    false
  );
  return target;
exception
  when invalid_text_representation then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_RUNTIME_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.assert_annual_scoring_runtime_v1(input jsonb, expected_operation text, required_worker text) OWNER TO postgres;

--
-- Name: assert_annual_transition_platform_owner_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_annual_transition_platform_owner_v1(input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', input->>'actor_player_id', ''
  )));
  actor_auth uuid;
begin
  begin
    perform production_control.assert_production_service_role();
  exception when others then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_FUTURE_RUNTIME_SERVICE_ROLE_REQUIRED';
  end;
  if not exists (
    select 1 from production_control.annual_scoring_platform_certifications_v1
    where scope_key = 'BAGGER_INV_PRODUCTION'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_CERTIFICATION_REQUIRED';
  end if;
  select value.* into strict scope
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if input->>'contract_version'
       is distinct from 'production-future-runtime-activation-v2'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'project_ref' is distinct from scope.project_ref
     or input->>'project_url' is distinct from scope.project_url
     or input->>'source_workbook_id' is distinct from scope.google_workbook_id
     or input->>'project_ref' ~* '(preview|staging|test)'
     or input->>'source_workbook_id' ~* '(preview|staging|test)'
     or input->>'tournament_id' is distinct from '2026'
     or coalesce((input->>'tournament_year')::integer, -1) <> 2026
     or input#>>'{authorization,tournament_id}' is distinct from '2026'
     or input#>>'{authorization,role}' is distinct from 'DIRECTOR'
     or actor_player !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_OWNER_REQUIRED';
  end if;
  begin
    actor_auth := coalesce(
      nullif(input#>>'{authorization,auth_user_id}', ''),
      nullif(input->>'actor_auth_user_id', '')
    )::uuid;
  exception when others then
    actor_auth := null;
  end;
  if actor_auth is null
     or (input ? 'actor_player_id' and pg_catalog.upper(pg_catalog.btrim(
       input->>'actor_player_id'
     )) is distinct from actor_player)
     or (input ? 'actor_auth_user_id' and pg_catalog.lower(pg_catalog.btrim(
       input->>'actor_auth_user_id'
     )) is distinct from actor_auth::text)
     or not exists (
       select 1
       from participant_identity.user_player_links link
       where link.auth_user_id = actor_auth
         and link.player_id = actor_player
         and link.status = 'ACTIVE'
         and link.revoked_at is null
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_OWNER_REQUIRED';
  end if;
  begin
    perform production_control.assert_access_governance_owner_v1(
      '2026', actor_player, actor_auth
    );
  exception when others then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_OWNER_REQUIRED';
  end;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ANNUAL_SCORING_PLATFORM_OWNER_REQUIRED';
end;
$_$;


ALTER FUNCTION production_control.assert_annual_transition_platform_owner_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_calcutta_nonempty_revision_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_calcutta_nonempty_revision_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare facts jsonb;
begin
  if TG_TABLE_NAME='calcutta_v1_publication_revisions' then
    if NEW.publication_state <> 'PUBLISHED' then return NEW; end if;
  end if;
  select auction_manifest into facts from scoring_authority.calcutta_v1_auction_fact_revisions
    where tournament_id=NEW.tournament_id and auction_revision=NEW.auction_revision;
  if facts is null or jsonb_array_length(facts->'purchases')=0 then
    raise exception using errcode='55000', message='PRODUCTION_CALCUTTA_AUCTION_FACTS_REQUIRED';
  end if;
  return NEW;
end; $$;


ALTER FUNCTION production_control.assert_calcutta_nonempty_revision_v1() OWNER TO postgres;

--
-- Name: assert_candidate_read_scope(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_candidate_read_scope(input jsonb) RETURNS production_control.resource_scope
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'auth', 'pg_temp'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_CANDIDATE_SERVICE_ROLE_REQUIRED';
  end if;
  select value.* into scope
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if scope.scope_key is null
     or upper(btrim(coalesce(input->>'environment', ''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref', '')) <> scope.project_ref
     or btrim(coalesce(input->>'project_url', '')) <> scope.project_url
     or btrim(coalesce(input->>'source_workbook_id', '')) <> scope.google_workbook_id
     or btrim(coalesce(input->>'tournament_id', '')) <> '2026'
     or scope.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or scope.project_url <> 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or scope.google_workbook_id <> '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or scope.vercel_project <> 'bagger-inv'
     or scope.canonical_domain <> 'https://baggerinv.com'
     or scope.current_tournament_read_authority <> 'GOOGLE'
     or scope.scoring_authority <> 'GOOGLE'
     or scope.participant_identity_authority <> 'PASSPORT'
     or scope.public_supabase_reads_enabled
     or scope.scoring_ingress_enabled
     or scope.google_writes_enabled
     or scope.auth_user_creation_enabled
     or scope.odds_publication_enabled
     or scope.workers_enabled
     or exists (
       select 1 from production_control.worker_controls worker
       where worker.enabled or worker.scheduler_installed or worker.google_writes_allowed
     ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_CANDIDATE_DORMANT_SCOPE_REQUIRED';
  end if;
  return scope;
end;
$$;


ALTER FUNCTION production_control.assert_candidate_read_scope(input jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_annual_actor_v2(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_annual_actor_v2(input jsonb, context jsonb, require_owner boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
 pointer production_control.current_tournament_pointer_v1%rowtype;
 actor_player text:=upper(btrim(coalesce(input#>>'{authorization,player_id}',input->>'actor_player_id','')));
 actor_auth uuid; owner_valid boolean:=false; director_valid boolean:=false;
begin
 if context->>'governance_tournament_id' is distinct from '2026' then
  raise exception using errcode='42501',message='CANONICAL_ANNUAL_GOVERNANCE_CONTRACT_REQUIRED'; end if;
 select * into strict pointer from production_control.current_tournament_pointer_v1
 where scope_key=context->>'resource_id';
 if pointer.tournament_id is distinct from context->>'current_tournament_id' then
  raise exception using errcode='40001',message='CANONICAL_ANNUAL_POINTER_STALE'; end if;
  begin
    actor_auth := coalesce(
      nullif(input#>>'{authorization,auth_user_id}', ''),
      nullif(input->>'actor_auth_user_id', '')
    )::uuid;
  exception when others then
    actor_auth := null;
  end;
  if actor_player !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
     or actor_auth is null
     or input#>>'{authorization,tournament_id}'
       is distinct from pointer.tournament_id
     or input#>>'{authorization,role}' is distinct from 'DIRECTOR'
     or (input ? 'actor_player_id' and pg_catalog.upper(pg_catalog.btrim(
       input->>'actor_player_id'
     )) is distinct from actor_player)
     or (input ? 'actor_auth_user_id' and pg_catalog.lower(pg_catalog.btrim(
       input->>'actor_auth_user_id'
     )) is distinct from actor_auth::text)
     or not exists (
       select 1
       from participant_identity.user_player_links link
       where link.auth_user_id = actor_auth
         and link.player_id = actor_player
         and link.status = 'ACTIVE'
         and link.revoked_at is null
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_FUTURE_RUNTIME_DIRECTOR_REQUIRED';
  end if;
  select exists (
    select 1
    from production_control.tournament_owner_capabilities_v1 owner_value
    where owner_value.tournament_id = '2026'
      and owner_value.player_id = actor_player
      and owner_value.auth_user_id = actor_auth
      and owner_value.status = 'ACTIVE'
      and owner_value.revoked_at is null
  ) into owner_valid;
  select exists (
    select 1
    from scoring_authority.tournament_players membership
    join participant_identity.tournament_roles role_value
      on role_value.tournament_id = membership.tournament_id
     and role_value.auth_user_id = actor_auth
     and role_value.role = 'DIRECTOR'
     and role_value.role_active
     and role_value.revoked_at is null
    join production_control.director_entitlements entitlement
      on entitlement.tournament_id = membership.tournament_id
     and entitlement.auth_user_id = actor_auth
     and entitlement.player_id = membership.player_id
     and entitlement.role in ('DIRECTOR', 'OWNER')
     and entitlement.status = 'ACTIVE'
     and entitlement.revoked_at is null
    where membership.tournament_id = pointer.tournament_id
      and membership.player_id = actor_player
      and membership.participation_status = 'ACTIVE'
  ) into director_valid;
  if require_owner and not owner_valid then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_FUTURE_RUNTIME_OWNER_REQUIRED';
  end if;
  if not require_owner and not owner_valid and not director_valid then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_FUTURE_RUNTIME_DIRECTOR_REQUIRED';
  end if;
  if require_owner then
    begin
      perform production_control.assert_access_governance_owner_v1(
        '2026', actor_player, actor_auth
      );
    exception when others then
      raise exception using errcode = '42501',
        message = 'PRODUCTION_FUTURE_RUNTIME_OWNER_REQUIRED';
    end;
  end if;
exception when invalid_text_representation or numeric_value_out_of_range then
 raise exception using errcode='42501',message='PRODUCTION_FUTURE_RUNTIME_EXACT_RESOURCE_REQUIRED';
end;
$_$;


ALTER FUNCTION production_control.assert_canonical_annual_actor_v2(input jsonb, context jsonb, require_owner boolean) OWNER TO postgres;

--
-- Name: assert_canonical_annual_context_v2(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_annual_context_v2(input jsonb, context jsonb, require_owner boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare live jsonb;
begin
 if context->>'resource_class'='PRODUCTION' then
  live:=production_control.production_annual_context_v2(input,require_owner);
  if live is distinct from context then raise exception using errcode='40001',message='CANONICAL_ANNUAL_POINTER_STALE';end if;
  return;
 end if;
 live:=production_control.current_certification_context_v1();
 if live is distinct from context or context->>'resource_class' is distinct from 'CERTIFICATION'
   or context->>'phase' is distinct from 'ANNUAL'
   or context->>'governance_tournament_id' is distinct from '2026'
   or input->>'environment' is distinct from 'CERTIFICATION'
   or input->>'contract_version' is distinct from 'production-future-year-administration-v1'
   or input->>'tournament_id' is distinct from context->>'current_tournament_id'
   or input->>'tournament_year' is distinct from context->>'current_tournament_year'
   or input->'authorization' is distinct from context->'authorization' then
  raise exception using errcode='42501',message='CANONICAL_ANNUAL_CONTEXT_REQUIRED'; end if;
 perform production_control.assert_canonical_annual_actor_v2(input,context,require_owner);
end;
$$;


ALTER FUNCTION production_control.assert_canonical_annual_context_v2(input jsonb, context jsonb, require_owner boolean) OWNER TO postgres;

--
-- Name: assert_canonical_annual_transition_context_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_annual_transition_context_v2(input jsonb, context jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare live jsonb; marker production_control.canonical_operation_context_v1%rowtype;
begin
 if context->>'resource_class'='PRODUCTION' then
  if context<>jsonb_build_object('resource_class','PRODUCTION','resource_id','BAGGER_INV_PRODUCTION')then
   raise exception using errcode='42501',message='CANONICAL_ANNUAL_CONTEXT_REQUIRED';end if;
  -- Only original admitted Production wrappers call this private core branch.
  -- Its resource/actor admission remains at the original wrapper boundary.
  if not exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='PRODUCTION')then
   raise exception using errcode='42501',message='CANONICAL_ANNUAL_CONTEXT_REQUIRED';end if;
  return;
 end if;
 live:=production_control.current_certification_context_v1();
 select * into strict marker from production_control.canonical_operation_context_v1
 where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 if context is distinct from live or context->>'phase' is distinct from 'ANNUAL'
  or not marker.mutation or input->>'operation_request_id' is distinct from context->>'operation_request_id'
  or context->>'resource_class' is distinct from 'CERTIFICATION'
  or input->>'environment' is distinct from 'CERTIFICATION'
  or input#>>'{authorization,player_id}' is distinct from context#>>'{authorization,player_id}'
  or input#>>'{authorization,auth_user_id}' is distinct from context#>>'{authorization,auth_user_id}'
  or input#>>'{authorization,role}' is distinct from 'DIRECTOR' then
  raise exception using errcode='42501',message='CANONICAL_ANNUAL_CONTEXT_REQUIRED';end if;
 -- Current authority was verified before constructing this stable logical
 -- operation envelope. Historical request target is never new write authority.
end;$$;


ALTER FUNCTION production_control.assert_canonical_annual_transition_context_v2(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_derived_scope_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_derived_scope_v1(input jsonb, context jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if context is null then return production_control.assert_score_derived_delivery_scope_v1(input); end if;
 if (context->>'current_tournament_year')::integer>2026 then
  if input->>'contract_version' is distinct from 'score-derived-delivery-v1' then raise exception using errcode='42501',message='CERTIFICATION_DERIVED_CONTEXT_REQUIRED';end if;
  return production_control.assert_canonical_future_worker_runtime_v1(input,context);
 end if;
 perform production_control.assert_canonical_scoring_context_v1(input,context,'RUNTIME');
 if context->>'phase' not in('WORKERS','DIRECTOR') or input->>'contract_version' is distinct from 'score-derived-delivery-v1' then
  raise exception using errcode='42501',message='CERTIFICATION_DERIVED_CONTEXT_REQUIRED'; end if;
 return context->>'tournament_id';
end;
$$;


ALTER FUNCTION production_control.assert_canonical_derived_scope_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_financial_worker_context_v1(jsonb, jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_financial_worker_context_v1(input jsonb, context jsonb, family text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if context is null then
  if family='CALCUTTA' then perform production_control.assert_production_calcutta_v1_runtime(input);
  elsif family='NET_SKINS' then perform production_control.assert_production_net_skins_v1_runtime(input);
  else raise exception using errcode='42501',message='CERTIFICATION_DERIVED_FAMILY_INVALID'; end if;
  return;
 end if;
 perform production_control.assert_canonical_scoring_context_v1(input,context,'RUNTIME');
 if (family='CALCUTTA' and context->>'phase' is distinct from 'WORKERS')
  or (family='NET_SKINS' and context->>'phase' is distinct from 'DIRECTOR') then
  raise exception using errcode='42501',message='CERTIFICATION_DERIVED_CONTEXT_REQUIRED'; end if;
 if input->>'expected_activation_revision' is distinct from context->>'activation_revision' then
  raise exception using errcode='40001',message=case family when 'CALCUTTA' then 'PRODUCTION_CALCUTTA_ACTIVATION_REVISION_CONFLICT' else 'PRODUCTION_NET_SKINS_ACTIVATION_REVISION_CONFLICT' end;
 end if;
end;
$$;


ALTER FUNCTION production_control.assert_canonical_financial_worker_context_v1(input jsonb, context jsonb, family text) OWNER TO postgres;

--
-- Name: assert_canonical_future_authoring_resource_v2(jsonb, jsonb, text, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_future_authoring_resource_v2(input jsonb, resource_context jsonb, required_contract text, require_owner boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare live jsonb; registered production_control.canonical_resource_v1%rowtype;
begin
 if resource_context->>'resource_class'='PRODUCTION' then
  perform production_control.assert_annual_future_admin_scope_v1(input,required_contract,true,require_owner);
  live:=production_control.annual_resource_context_v2();
  if live->>'resource_class'<>'PRODUCTION' or live->>'resource_id' is distinct from resource_context->>'resource_id'
    or live->>'current_tournament_id' is distinct from resource_context->>'current_tournament_id' then
   raise exception using errcode='42501',message='CANONICAL_AUTHORING_RESOURCE_REQUIRED'; end if;
  return;
 end if;
 live:=production_control.current_certification_context_v1();
 select * into strict registered from production_control.canonical_resource_v1 where singleton;
 if resource_context is distinct from live or live->>'phase' is distinct from 'ANNUAL'
   or live->>'resource_class' is distinct from 'CERTIFICATION'
   or registered.resource_class is distinct from 'CERTIFICATION'
   or registered.resource_id is distinct from live->>'resource_id'
   or registered.database_name is distinct from current_database()
   or input->>'contract_version' is distinct from required_contract
   or input->>'environment' is distinct from 'CERTIFICATION'
   or input->>'project_ref' is distinct from registered.project_ref
   or input->>'project_url' is distinct from registered.project_url
   or input->>'source_workbook_id' is distinct from registered.provenance_id
   or input->>'tournament_id' is distinct from live->>'current_tournament_id'
   or input->>'tournament_year' is distinct from live->>'current_tournament_year'
   or input->'authorization' is distinct from live->'authorization' then
  raise exception using errcode='42501',message='CANONICAL_AUTHORING_RESOURCE_REQUIRED'; end if;
 perform production_control.assert_canonical_annual_actor_v2(input,live,require_owner);
end;
$$;


ALTER FUNCTION production_control.assert_canonical_future_authoring_resource_v2(input jsonb, resource_context jsonb, required_contract text, require_owner boolean) OWNER TO postgres;

--
-- Name: assert_canonical_future_calcutta_worker_v1(jsonb, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_future_calcutta_worker_v1(input jsonb, expected_operation text, resource_context jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  authority production_control.annual_scoring_runtime_authorities_v1%rowtype;
  annual_resource production_control.future_tournament_resources_v1%rowtype;
  activation production_control.cutover_activation_state%rowtype;
begin
  if resource_context is null then return production_control.assert_annual_calcutta_runtime_v1(input,expected_operation);end if;
  if input->>'annual_scoring_operation' is distinct from expected_operation then raise exception using errcode='42501',message='CERTIFICATION_FUTURE_WORKER_NOT_ADMITTED';end if;
  -- The dispatcher and this target-side assertion both bind the exact
  -- pointer/runtime/destination. Keeping the target-side check means a direct
  -- service-role call cannot bypass the annual allowlist.
  if production_control.assert_canonical_future_worker_runtime_v1(input,resource_context) = '2026' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CALCUTTA_RUNTIME_REQUIRED';
  end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = resource_context->>'resource_id';
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  select value.* into strict authority
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.runtime_generation_id = generation.runtime_generation_id;
  select value.* into strict annual_resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = pointer.tournament_id;
  activation.activation_revision:=(resource_context->>'activation_revision')::bigint;

  if pointer.tournament_id = '2026'
     or input->>'contract_version' is distinct from 'production-calcutta-v1'
     or input->>'expected_current_tournament_id'
       is distinct from pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or input->>'expected_runtime_generation_id'
       is distinct from generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id'
       is distinct from generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id'
       is distinct from generation.admission_generation_id::text
     or coalesce((input->>'expected_activation_revision')::bigint, -1)
       <> activation.activation_revision
     or generation.pointer_revision <> pointer.pointer_revision
     or generation.authority <> 'SUPABASE'
     or generation.ingress_state <> 'OPEN'
     or catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision
     or authority.authority_status <> 'ACTIVE'
     or authority.admission_state <> 'OPEN'
     or authority.pointer_revision <> pointer.pointer_revision
     or authority.lifecycle_revision <> pointer.lifecycle_revision
     or authority.authority_generation_id is distinct from
       generation.authority_generation_id
     or authority.admission_generation_id is distinct from
       generation.admission_generation_id
     or annual_resource.resource_status <> 'CURRENT_RESOURCE_BOUND'
     or annual_resource.source_workbook_id is null
     or annual_resource.project_ref is distinct from input->>'project_ref'
     or annual_resource.project_url is distinct from input->>'project_url'
     or annual_resource.source_workbook_id
       is distinct from input->>'annual_destination_workbook_id' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CALCUTTA_RUNTIME_REQUIRED';
  end if;
  return pointer.tournament_id;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CALCUTTA_RUNTIME_REQUIRED';
end;

$$;


ALTER FUNCTION production_control.assert_canonical_future_calcutta_worker_v1(input jsonb, expected_operation text, resource_context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_future_identity_runtime_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_future_identity_runtime_v1(resource_context jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  context participant_identity.future_tournament_identity_contexts_v1%rowtype;
  roster_count_value integer;
  binding_count_value integer;
  enrolled_count_value integer;
begin
  if resource_context is null then return production_control.assert_future_participant_identity_runtime_v1();end if;
  perform production_control.assert_current_certification_future_context_v1(resource_context);
  perform production_control.assert_production_service_role();
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = resource_context->>'resource_id';
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  select value.* into strict context
  from participant_identity.future_tournament_identity_contexts_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.status = 'CERTIFIED';
  select pg_catalog.count(*)::integer into roster_count_value
  from scoring_authority.tournament_players membership
  where membership.tournament_id = pointer.tournament_id
    and membership.participation_status = 'ACTIVE';
  select pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter (
      where binding.enrollment_state = 'ENROLLED'
    )::integer
  into binding_count_value, enrolled_count_value
  from participant_identity.future_tournament_participant_bindings_v1 binding
  where binding.tournament_id = pointer.tournament_id;
  if pointer.tournament_year <= 2026
     or catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision
     or generation.pointer_revision <> pointer.pointer_revision
     or generation.authority <> 'SUPABASE'
     or generation.ingress_state <> 'OPEN'
     or context.runtime_generation_id <> generation.runtime_generation_id
     or context.authority_generation_id
       <> generation.authority_generation_id
     or context.admission_generation_id
       <> generation.admission_generation_id
     or context.pointer_revision <> generation.pointer_revision
     or context.roster_count <> roster_count_value
     or binding_count_value <> roster_count_value
     or context.enrolled_count <> enrolled_count_value
     or context.not_enrolled_count <>
       roster_count_value - enrolled_count_value
     or context.binding_fingerprint is distinct from
       production_control
         .future_participant_identity_binding_fingerprint_v1(
           pointer.tournament_id
         )
     or exists (
       select 1
       from participant_identity.future_tournament_participant_bindings_v1
         binding
       left join production_control
         .future_participant_identity_eligibility_v1(
           pointer.tournament_id
         ) eligibility
         on eligibility.player_id = binding.player_id
       where binding.tournament_id = pointer.tournament_id
         and (eligibility.player_id is null
           or (binding.enrollment_state = 'ENROLLED'
             and not eligibility.runtime_eligible)
           or (binding.contact_state = 'APPROVED'
             and not eligibility.contact_approved))
     )
     or not exists (
       select 1
       from production_control.future_global_owner_eligibility_v1()
     ) then
    raise exception using errcode = '55000',
      message = 'FUTURE_PARTICIPANT_IDENTITY_RUNTIME_REQUIRED';
  end if;
  return pointer.tournament_id;
end;

$$;


ALTER FUNCTION production_control.assert_canonical_future_identity_runtime_v1(resource_context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_future_net_skins_worker_v1(jsonb, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_future_net_skins_worker_v1(input jsonb, expected_operation text, resource_context jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target text;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
begin
  if resource_context is null then return production_control.assert_annual_net_skins_v1(input,expected_operation);end if;
  if input->>'annual_scoring_operation' is distinct from expected_operation then raise exception using errcode='42501',message='CERTIFICATION_FUTURE_WORKER_NOT_ADMITTED';end if;
  target := production_control.assert_canonical_future_worker_runtime_v1(input,resource_context);
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target
    and value.runtime_generation_id =
      (input->>'expected_runtime_generation_id')::uuid
    and value.generation_status = 'ACTIVE';
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target;
  if target = '2026'
     or resource.resource_status <> 'CURRENT_RESOURCE_BOUND'
     or resource.source_workbook_id is null
     or resource.source_workbook_id is distinct from
       input->>'annual_destination_workbook_id'
     or generation.pointer_revision < 1 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_NET_SKINS_RUNTIME_REQUIRED';
  end if;
  return target;
exception
  when invalid_text_representation or no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_NET_SKINS_RUNTIME_REQUIRED';
end;

$$;


ALTER FUNCTION production_control.assert_canonical_future_net_skins_worker_v1(input jsonb, expected_operation text, resource_context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_future_scoring_actor_v1(jsonb, text, boolean, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_future_scoring_actor_v1(input jsonb, target_tournament text, require_director boolean, resource_context jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  actor text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_role text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,role}', 'PLAYER'
  )));
  actor_auth_user uuid;
  current_identity_target text;
begin
  begin
    actor_auth_user := nullif(
      input#>>'{authorization,auth_user_id}', ''
    )::uuid;
  exception when others then
    actor_auth_user := null;
  end;
  current_identity_target := production_control
    .assert_canonical_future_identity_runtime_v1(resource_context);
  if target_tournament <> current_identity_target
     or input#>>'{authorization,tournament_id}'
       is distinct from target_tournament
     or actor = '' or actor_auth_user is null
     or actor_role not in ('PLAYER', 'DIRECTOR')
     or (require_director and actor_role <> 'DIRECTOR')
     or not exists (
       select 1
       from production_control.future_participant_identity_eligibility_v1(
         target_tournament
       ) eligibility
       where eligibility.player_id = actor
         and eligibility.auth_user_id = actor_auth_user
         and eligibility.runtime_eligible
     )
     or (actor_role = 'DIRECTOR' and (
       not exists (
         select 1
         from participant_identity.tournament_roles role_value
         where role_value.tournament_id = target_tournament
           and role_value.auth_user_id = actor_auth_user
           and role_value.role = 'DIRECTOR'
           and role_value.role_active
           and role_value.revoked_at is null
       )
       or not exists (
         select 1
         from production_control.director_entitlements entitlement
         where entitlement.tournament_id = target_tournament
           and entitlement.auth_user_id = actor_auth_user
           and entitlement.player_id = actor
           and entitlement.role in ('DIRECTOR', 'OWNER')
           and entitlement.status = 'ACTIVE'
           and entitlement.revoked_at is null
       )
     )) then
    raise exception using errcode = '42501', message = case
      when require_director or actor_role = 'DIRECTOR'
        then 'PRODUCTION_DIRECTOR_AUTHORIZATION_REQUIRED'
      else 'PRODUCTION_SCORING_AUTHORIZATION_REQUIRED'
    end;
  end if;
end;

$$;


ALTER FUNCTION production_control.assert_canonical_future_scoring_actor_v1(input jsonb, target_tournament text, require_director boolean, resource_context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_future_scoring_runtime_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_future_scoring_runtime_v1(input jsonb, resource_context jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  operation production_control.annual_scoring_rpc_allowlist_v1%rowtype;
  active_generation_count integer;
  readiness jsonb;
  certified_writer jsonb;
  origin production_control.certification_initialization_origins_v1%rowtype;
  live jsonb;
begin
  if resource_context is null then return production_control.assert_future_production_scoring_runtime_v1(input);end if;
  live:=production_control.assert_current_certification_future_context_v1(resource_context);
  select * into strict origin from production_control.certification_initialization_origins_v1
   where resource_id=live->>'resource_id';
  -- The shared transaction lock is held through the invoked scoring RPC.
  -- Annual close/transition/abort take the exclusive counterpart of this
  -- exact legacy key, so an admitted mutation cannot cross the boundary.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into operation
  from production_control.annual_scoring_rpc_allowlist_v1 value
  where value.operation_name = input->>'annual_scoring_operation' and value.enabled;
  if operation.operation_name is null
     or input->>'annual_scoring_dispatch_contract'
       is distinct from 'production-annual-scoring-dispatch-v1'
     or input->>'annual_scoring_operation'
       is distinct from operation.operation_name
     or operation.required_worker is not null then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ANNUAL_SCORING_OPERATION_NOT_ALLOWLISTED';
  end if;
  if input->>'annual_scoring_operation' not in ('submit_production_hole_score','finalize_production_match',
     'reopen_production_match','read_production_scoring_authority','read_production_scoring_participant_context','mutate_production_match_control')
   or live->>'phase' is distinct from (case input->>'annual_scoring_operation'
    when 'submit_production_hole_score' then 'SCORING' when 'finalize_production_match' then 'SCORING'
    when 'reopen_production_match' then 'DIRECTOR' when 'mutate_production_match_control' then 'DIRECTOR' else 'READS' end) then
   raise exception using errcode='42501',message='CERTIFICATION_FUTURE_OPERATION_NOT_ADMITTED';end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = live->>'resource_id';
  if pointer.tournament_id = '2026' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_TARGET_REQUIRED';
  end if;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  select value.* into strict annual
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.runtime_generation_id = generation.runtime_generation_id;
-- Google runtime retired; canonical authority checks remain below.
  select pg_catalog.count(*)::integer into active_generation_count
  from production_control.future_annual_runtime_generations_v1 value
  where value.generation_status = 'ACTIVE';
  if input->>'expected_current_tournament_id'
       is distinct from pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or input->>'expected_runtime_generation_id'
       is distinct from generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id'
       is distinct from generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id'
       is distinct from generation.admission_generation_id::text
     or generation.authority_generation_id
       is distinct from annual.authority_generation_id
     or generation.admission_generation_id
       is distinct from annual.admission_generation_id
     or generation.pointer_revision <> pointer.pointer_revision
     or annual.pointer_revision <> pointer.pointer_revision
     or active_generation_count <> 1
     or catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision
     or annual.lifecycle_revision <> pointer.lifecycle_revision
     or annual.platform_tournament_id <> '2026'
     or annual.resource_class is distinct from 'CERTIFICATION'
     or annual.certification_resource_id is distinct from origin.resource_id
     or annual.platform_authority_generation_id is distinct from origin.authority_epoch_id
     or annual.platform_admission_generation_id is distinct from origin.admission_generation_id
     or generation.authority_generation_id::text is distinct from live->>'authority_epoch_id'
     or not exists(select 1 from production_control.certification_ingress_generations_v1 ingress_generation
       where ingress_generation.resource_id=origin.resource_id
        and ingress_generation.generation_id=generation.admission_generation_id
        and ingress_generation.tournament_id=pointer.tournament_id
        and ingress_generation.pointer_revision=pointer.pointer_revision
        and ingress_generation.authority_epoch_id=generation.authority_generation_id
        and (operation.operation_class='READ' and ingress_generation.state in('OPEN','CLOSING','CLOSED')
          or operation.operation_class='MUTATION' and ingress_generation.state='OPEN'
          or operation.operation_class='WORKER' and ingress_generation.state in('OPEN','CLOSING')))
     or annual.authority_status not in ('ACTIVE', 'CLOSED')
     or (operation.operation_class = 'MUTATION' and (
       annual.authority_status <> 'ACTIVE'
       or annual.admission_state <> 'OPEN'
     ))
     or (operation.operation_class = 'WORKER' and (
       annual.authority_status <> 'ACTIVE'
       or annual.admission_state not in ('OPEN', 'CLOSING')
     ))
     or not exists (
       select 1 from scoring_authority.tournaments tournament_value
       where tournament_value.tournament_id = pointer.tournament_id
         and tournament_value.scoring_authority = 'SUPABASE'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_RUNTIME_REQUIRED';
  end if;
  if operation.operation_name = 'mutate_production_match_control'
     and pg_catalog.upper(coalesce(input->>'operation', '')) = 'MARK_LIVE'
  then
    readiness :=
      production_control.assert_future_production_match_scoring_ready_v1(
        input->>'match_id', pointer.tournament_id
      );
    if coalesce((readiness->>'ready')::boolean, false) is not true then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ANNUAL_MARK_LIVE_READINESS_REQUIRED';
    end if;
  end if;
  perform production_control.ensure_annual_side_game_runtime_v1(pointer.tournament_id,
   generation.runtime_generation_id,generation.authority_generation_id,generation.admission_generation_id,false);
  return pointer.tournament_id;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_RUNTIME_REQUIRED';
end;

$$;


ALTER FUNCTION production_control.assert_canonical_future_scoring_runtime_v1(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_future_worker_runtime_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_future_worker_runtime_v1(input jsonb, resource_context jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$


declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  operation production_control.annual_scoring_rpc_allowlist_v1%rowtype;
  active_generation_count integer;
  readiness jsonb;
  certified_writer jsonb;
  origin production_control.certification_initialization_origins_v1%rowtype;
  live jsonb;
begin
  if resource_context is null then return production_control.assert_future_production_scoring_runtime_v1(input);end if;
  live:=production_control.assert_current_certification_future_context_v1(resource_context);
  select * into strict origin from production_control.certification_initialization_origins_v1
   where resource_id=live->>'resource_id';
  -- The shared transaction lock is held through the invoked scoring RPC.
  -- Annual close/transition/abort take the exclusive counterpart of this
  -- exact legacy key, so an admitted mutation cannot cross the boundary.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into operation
  from production_control.annual_scoring_rpc_allowlist_v1 value
  where value.operation_name = input->>'annual_scoring_operation' and value.enabled;
  if operation.operation_name is null
     or input->>'annual_scoring_dispatch_contract'
       is distinct from 'production-annual-scoring-dispatch-v1'
     or input->>'annual_scoring_operation'
       is distinct from operation.operation_name
     or operation.required_worker is not null then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ANNUAL_SCORING_OPERATION_NOT_ALLOWLISTED';
  end if;
  if input->>'annual_scoring_operation' not in('claim_competition_derived_jobs','write_competition_derived_snapshot','mark_competition_derived_job_failed','claim_intelligence_derived_bundle','write_intelligence_derived_bundle','claim_production_calcutta_v1_recalculation','complete_production_calcutta_v1_recalculation','fail_production_calcutta_v1_recalculation','claim_production_net_skins_v1_recalculation','complete_production_net_skins_v1_recalculation','fail_production_net_skins_v1_recalculation','score_derived_delivery_tick_v1','fail_score_derived_preclaim_v1','fail_intelligence_derived_bundle_v1','requeue_score_derived_delivery_v1')
    or live->>'phase' is distinct from (case when input->>'annual_scoring_operation' in('claim_production_net_skins_v1_recalculation','complete_production_net_skins_v1_recalculation','fail_production_net_skins_v1_recalculation','requeue_score_derived_delivery_v1') then 'DIRECTOR' else 'WORKERS' end) then
   raise exception using errcode='42501',message='CERTIFICATION_FUTURE_WORKER_NOT_ADMITTED';end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = live->>'resource_id';
  if pointer.tournament_id = '2026' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_TARGET_REQUIRED';
  end if;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  select value.* into strict annual
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.runtime_generation_id = generation.runtime_generation_id;
-- Google runtime retired; canonical authority checks remain below.
  select pg_catalog.count(*)::integer into active_generation_count
  from production_control.future_annual_runtime_generations_v1 value
  where value.generation_status = 'ACTIVE';
  if input->>'expected_current_tournament_id'
       is distinct from pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or input->>'expected_runtime_generation_id'
       is distinct from generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id'
       is distinct from generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id'
       is distinct from generation.admission_generation_id::text
     or generation.authority_generation_id
       is distinct from annual.authority_generation_id
     or generation.admission_generation_id
       is distinct from annual.admission_generation_id
     or generation.pointer_revision <> pointer.pointer_revision
     or annual.pointer_revision <> pointer.pointer_revision
     or active_generation_count <> 1
     or catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision
     or annual.lifecycle_revision <> pointer.lifecycle_revision
     or annual.platform_tournament_id <> '2026'
     or annual.resource_class is distinct from 'CERTIFICATION'
     or annual.certification_resource_id is distinct from origin.resource_id
     or annual.platform_authority_generation_id is distinct from origin.authority_epoch_id
     or annual.platform_admission_generation_id is distinct from origin.admission_generation_id
     or generation.authority_generation_id::text is distinct from live->>'authority_epoch_id'
     or not exists(select 1 from production_control.certification_ingress_generations_v1 ingress_generation
       where ingress_generation.resource_id=origin.resource_id
        and ingress_generation.generation_id=generation.admission_generation_id
        and ingress_generation.tournament_id=pointer.tournament_id
        and ingress_generation.pointer_revision=pointer.pointer_revision
        and ingress_generation.authority_epoch_id=generation.authority_generation_id
        and (operation.operation_class='READ' and ingress_generation.state in('OPEN','CLOSING','CLOSED')
          or operation.operation_class='MUTATION' and ingress_generation.state='OPEN'
          or operation.operation_class='WORKER' and ingress_generation.state in('OPEN','CLOSING')))
     or annual.authority_status not in ('ACTIVE', 'CLOSED')
     or (operation.operation_class = 'MUTATION' and (
       annual.authority_status <> 'ACTIVE'
       or annual.admission_state <> 'OPEN'
     ))
     or (operation.operation_class = 'WORKER' and (
       annual.authority_status <> 'ACTIVE'
       or annual.admission_state not in ('OPEN', 'CLOSING')
     ))
     or not exists (
       select 1 from scoring_authority.tournaments tournament_value
       where tournament_value.tournament_id = pointer.tournament_id
         and tournament_value.scoring_authority = 'SUPABASE'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_RUNTIME_REQUIRED';
  end if;
  if operation.operation_name = 'mutate_production_match_control'
     and pg_catalog.upper(coalesce(input->>'operation', '')) = 'MARK_LIVE'
  then
    readiness :=
      production_control.assert_future_production_match_scoring_ready_v1(
        input->>'match_id', pointer.tournament_id
      );
    if coalesce((readiness->>'ready')::boolean, false) is not true then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ANNUAL_MARK_LIVE_READINESS_REQUIRED';
    end if;
  end if;
  perform production_control.ensure_annual_side_game_runtime_v1(pointer.tournament_id,
   generation.runtime_generation_id,generation.authority_generation_id,generation.admission_generation_id,false);
  return pointer.tournament_id;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_RUNTIME_REQUIRED';
end;


$$;


ALTER FUNCTION production_control.assert_canonical_future_worker_runtime_v1(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_odds_job_v1(jsonb, text, scoring_authority.odds_calculation_jobs, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_odds_job_v1(input jsonb, target text, retained scoring_authority.odds_calculation_jobs, context jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if context is null then perform production_control.assert_annual_odds_job_scope_v1(input,target,retained);return;end if;
 if retained.tournament_id is distinct from target or retained.runtime_generation_id is distinct from nullif(input->>'expected_runtime_generation_id','')::uuid
  or retained.production_operation_mode is distinct from 'CERTIFICATION' or retained.production_deployment_commit is distinct from context->>'release_commit'
  or retained.production_candidate_hostname is not null or retained.source_revision->>'resource_id'is distinct from context->>'resource_id'
  or retained.source_revision->>'installation_id'is distinct from context->>'installation_id'
  or retained.source_revision->>'certification_odds_contract'is distinct from 'certification-odds-v1'
  or retained.source_revision->>'certification_ingress_generation_id'is distinct from input->>'certification_ingress_generation_id'
  or retained.source_revision->>'annual_authority_generation_id'is distinct from context->>'authority_epoch_id'
  or retained.source_revision->>'annual_pointer_revision'is distinct from context->>'pointer_revision'then
  raise exception using errcode='42501',message='CERTIFICATION_ODDS_JOB_SCOPE_DENIED';end if;
end;$$;


ALTER FUNCTION production_control.assert_canonical_odds_job_v1(input jsonb, target text, retained scoring_authority.odds_calculation_jobs, context jsonb) OWNER TO postgres;

--
-- Name: assert_canonical_scoring_context_v1(jsonb, jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_canonical_scoring_context_v1(input jsonb, context jsonb, guard_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare current_context jsonb;
begin
 if context is null then
  if guard_kind='RUNTIME' then perform production_control.assert_production_scoring_runtime(input);
  elsif guard_kind='EXACT_READ' then perform production_control.assert_exact_cutover_resource_scope(input,true);
  else raise exception using errcode='42501',message='CANONICAL_DOMAIN_GUARD_INVALID'; end if;
  return;
 end if;
 current_context:=production_control.current_certification_context_v1();
 if current_context is null or context->>'resource_class' is distinct from 'CERTIFICATION'
  or context->>'resource_id' is distinct from current_context->>'resource_id'
  or context->>'installation_id' is distinct from current_context->>'installation_id'
  or context->>'context_token' is distinct from current_context->>'context_token'
  or context->>'tournament_id' is distinct from '2026'
  or context->>'current_tournament_id' is distinct from '2026'
  or (input ? 'tournament_id' and input->>'tournament_id' is distinct from '2026')
  or (input ? 'expected_epoch_id' and input->>'expected_epoch_id' is distinct from context->>'authority_epoch_id') then
  raise exception using errcode='42501',message='CERTIFICATION_DOMAIN_CONTEXT_REQUIRED';
 end if;
end;
$$;


ALTER FUNCTION production_control.assert_canonical_scoring_context_v1(input jsonb, context jsonb, guard_kind text) OWNER TO postgres;

--
-- Name: assert_certification_annual_abort_drain_v1(uuid, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_annual_abort_drain_v1(target_closure uuid, ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c production_control.scoring_admission_closures%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;e jsonb;
begin
 perform production_control.assert_certification_annual_cached_context_v1(ctx);
 if production_control.current_certification_context_v1() is distinct from ctx then
  raise exception using errcode='PT409',message='CANONICAL_RESOURCE_CONTEXT_STALE';end if;
 select * into strict c from production_control.scoring_admission_closures where closure_id=target_closure for update;
 select * into strict g from production_control.certification_ingress_generations_v1
  where resource_id=ctx->>'resource_id' and generation_id=c.admission_generation_id for update;
 if c.resource_class<>'CERTIFICATION' or c.certification_resource_id<>g.resource_id
  or c.tournament_id is distinct from ctx->>'current_tournament_id' or c.tournament_id<>g.tournament_id
  or c.authority_generation_id<>g.authority_epoch_id or c.status not in('CLOSING','CLOSED')
  or g.state not in('CLOSING','CLOSED') or c.lease_high_watermark is distinct from g.high_watermark
  or c.closing_admission_revision<>g.revision or g.pointer_revision::text is distinct from ctx->>'pointer_revision' then
  raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_ABORT_NOT_SAFE';end if;
 e:=production_control.close_certification_ingress_generation_v1(g.resource_id,g.generation_id,g.revision);
 if e->>'state'<>'CLOSED' or not(e->>'drained')::boolean or not(e->>'fingerprint_matches')::boolean then
  raise exception using errcode='55000',message='CERTIFICATION_ANNUAL_ABORT_DRAIN_REQUIRED';end if;
 -- The immutable generation contains actual evidence. The outer abort may
 -- reopen the tournament only by installing a different generation identifier.
exception when no_data_found then raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_ABORT_NOT_SAFE';
end;$$;


ALTER FUNCTION production_control.assert_certification_annual_abort_drain_v1(target_closure uuid, ctx jsonb) OWNER TO postgres;

--
-- Name: assert_certification_annual_cached_context_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_annual_cached_context_v1(ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare m production_control.canonical_operation_context_v1%rowtype;
 r production_control.canonical_resource_v1%rowtype;
 a production_control.certification_admission_v1%rowtype;
 fence bigint:=production_control.scoring_admission_lock_key();
begin
 perform production_control.assert_production_service_role();
 if not exists(select 1 from pg_locks l where l.pid=pg_backend_pid() and l.locktype='advisory'
  and l.database=(select oid from pg_database where datname=current_database())
  and l.classid=((fence>>32)&4294967295)::oid and l.objid=(fence&4294967295)::oid
  and l.objsubid=1 and l.mode='ExclusiveLock' and l.granted) then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_EXCLUSIVE_FENCE_REQUIRED';end if;
 select * into strict m from production_control.canonical_operation_context_v1
  where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 select * into strict r from production_control.canonical_resource_v1 where singleton for share;
 select * into strict a from production_control.certification_admission_v1 where resource_id=r.resource_id for update;
 if m.phase<>'ANNUAL' or not m.mutation or m.context is distinct from ctx
  or ctx->>'resource_class' is distinct from 'CERTIFICATION' or ctx->>'phase' is distinct from 'ANNUAL'
  or r.resource_class<>'CERTIFICATION' or r.database_name<>current_database()
  or ctx->>'resource_id' is distinct from r.resource_id or ctx->>'installation_id' is distinct from r.installation_id::text
  or ctx->>'project_ref' is distinct from r.project_ref or ctx->>'project_url' is distinct from r.project_url
  or ctx->>'registration_revision' is distinct from r.registration_revision::text
  or ctx->>'manifest_digest' is distinct from r.manifest_digest or ctx->>'schema_digest' is distinct from r.schema_digest
  or ctx->>'binding_id' is distinct from a.binding_id::text or not a.enabled
  or ctx->>'authority_epoch_id' is distinct from a.authority_epoch_id::text
  or ctx->>'activation_revision' is distinct from a.activation_revision::text
  or ctx->>'admission_revision' is distinct from a.admission_revision::text
  or ctx->>'release_commit' is distinct from a.release_commit
  or ctx#>>'{authorization,role}' is distinct from 'DIRECTOR'
  or not exists(select 1 from production_control.future_global_owner_eligibility_v1() o
   where o.player_id=ctx#>>'{authorization,player_id}' and o.auth_user_id::text=ctx#>>'{authorization,auth_user_id}')
  or exists(select 1 from production_control.resource_scope) or exists(select 1 from production_control.cutover_activation_state) then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CACHED_CONTEXT_REQUIRED';end if;
exception when no_data_found then raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CACHED_CONTEXT_REQUIRED';
end;$$;


ALTER FUNCTION production_control.assert_certification_annual_cached_context_v1(ctx jsonb) OWNER TO postgres;

--
-- Name: assert_certification_context_v1(jsonb, text, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_context_v1(input jsonb, required_phase text, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare resource production_control.canonical_resource_v1%rowtype;
  admission production_control.certification_admission_v1%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  context jsonb; token text; operation_id text;
begin
  perform production_control.assert_production_service_role();
  if required_phase is null or required_phase not in('READS','SCORING','DIRECTOR','WORKERS','ANNUAL')
    or input->>'contract_version' is distinct from 'certification-runtime-v1'
    or input->>'phase' is distinct from required_phase
    or jsonb_typeof(input->'resource') is distinct from 'object'
    or input#>>'{resource,resource_class}' is distinct from 'CERTIFICATION'
    or jsonb_typeof(input->'deployment') is distinct from 'object' then
    raise exception using errcode='42501',message='CANONICAL_RESOURCE_CONTEXT_REQUIRED';
  end if;
  perform pg_advisory_xact_lock_shared(production_control.scoring_admission_lock_key());
  select * into strict resource from production_control.canonical_resource_v1 where singleton for share;
  if resource.resource_class<>'CERTIFICATION' or resource.database_name<>current_database()
    or exists(select 1 from production_control.resource_scope)
    or exists(select 1 from production_control.cutover_activation_state)
    or input#>>'{resource,resource_id}' is distinct from resource.resource_id
    or input#>>'{resource,installation_id}' is distinct from resource.installation_id::text
    or input#>>'{resource,project_ref}' is distinct from resource.project_ref
    or input#>>'{resource,project_url}' is distinct from resource.project_url then
    raise exception using errcode='42501',message='CANONICAL_RESOURCE_BINDING_DENIED';
  end if;
  if input#>>'{resource,schema_contract}' is distinct from resource.schema_contract
    or input#>>'{resource,schema_digest}' is distinct from resource.schema_digest then
    raise exception using errcode='55000',message='CANONICAL_RESOURCE_SCHEMA_UNAVAILABLE';
  end if;
  if input#>>'{resource,registration_revision}' is distinct from resource.registration_revision::text
    or input#>>'{resource,manifest_digest}' is distinct from resource.manifest_digest then
    raise exception using errcode='40001',message='CANONICAL_RESOURCE_REGISTRATION_STALE';
  end if;
  select * into strict admission from production_control.certification_admission_v1 where resource_id=resource.resource_id for share;
  if not admission.enabled or not required_phase=any(admission.capabilities)
    or input#>>'{deployment,vercel_team_id}' is distinct from resource.vercel_team_id
    or input#>>'{deployment,vercel_project_id}' is distinct from resource.vercel_project_id
    or input#>>'{deployment,git_branch}' is distinct from admission.git_branch
    or input#>>'{deployment,deployment_class}' is distinct from admission.deployment_class
    or input#>>'{deployment,release_commit}' is distinct from admission.release_commit
    or input#>>'{deployment,deployment_id}' is distinct from admission.deployment_id
    or input#>>'{deployment,deployment_origin}' is distinct from admission.deployment_origin then
    raise exception using errcode='42501',message='CANONICAL_RESOURCE_DEPLOYMENT_DENIED';
  end if;
  select * into strict pointer from production_control.current_tournament_pointer_v1 where scope_key=resource.resource_id for share;
  select * into strict gate from scoring_authority.ingress_gates where tournament_id=pointer.tournament_id for share;
  if gate.authority<>'SUPABASE'
    or gate.active_epoch_id is distinct from admission.authority_epoch_id
    or not exists(select 1 from scoring_authority.tournaments t where t.tournament_id=pointer.tournament_id
      and t.tournament_year=pointer.tournament_year and t.scoring_authority='SUPABASE')
    or not exists(select 1 from scoring_authority.authority_epochs e where e.epoch_id=admission.authority_epoch_id
      and e.status='COMMITTED' and e.authority_after='SUPABASE') then
    raise exception using errcode='55000',message='CANONICAL_RESOURCE_RUNTIME_UNAVAILABLE';
  end if;
  -- Reads/annual transitions must observe closed ingress safely; mutation
  -- domain/lifecycle guards remain independently enforced by their cores.
  if required_phase in('SCORING','DIRECTOR','WORKERS') and (gate.state<>'OPEN' or gate.unresolved_client_queues<>0) then
    raise exception using errcode='55000',message='CANONICAL_RESOURCE_INGRESS_CLOSED';
  end if;
  context:=jsonb_build_object(
    'resource_id',resource.resource_id,'resource_class',resource.resource_class,
    'installation_id',resource.installation_id,'project_ref',resource.project_ref,'project_url',resource.project_url,
    'registration_revision',resource.registration_revision,'manifest_digest',resource.manifest_digest,
    'schema_contract',resource.schema_contract,'schema_digest',resource.schema_digest,
    'binding_id',admission.binding_id,'current_tournament_id',pointer.tournament_id,'tournament_id',pointer.tournament_id,
    'current_tournament_year',pointer.tournament_year,'pointer_revision',pointer.pointer_revision,
    'governance_tournament_id',admission.governance_tournament_id,
    'authority_epoch_id',admission.authority_epoch_id,'activation_revision',admission.activation_revision,
    'admission_revision',admission.admission_revision,'release_commit',admission.release_commit,
    'vercel_team_id',resource.vercel_team_id,'vercel_project_id',resource.vercel_project_id,
    'git_branch',admission.git_branch,'deployment_class',admission.deployment_class,
    'deployment_id',admission.deployment_id,'deployment_origin',admission.deployment_origin);
  token:=production_control.tournament_setup_hash_v1(context);
  if (mutation or input ? 'expected_context_token') and input->>'expected_context_token' is distinct from token then
    raise exception using errcode='PT409',message='CANONICAL_RESOURCE_CONTEXT_STALE';
  end if;
  if mutation then
    operation_id:=coalesce(input->>'operation_request_id',input->>'mutation_key');
    if operation_id is null then
      raise exception using errcode='22023',message='CANONICAL_RESOURCE_OPERATION_ID_REQUIRED';
    end if;
    if required_phase='SCORING' or (required_phase='DIRECTOR' and input->>'operation_id'='SCORING.REOPEN_MATCH') then
      if operation_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$' then
        raise exception using errcode='22023',message='CANONICAL_RESOURCE_OPERATION_ID_INVALID';
      end if;
    else
      perform operation_id::uuid;
    end if;
  end if;
  return context||jsonb_build_object('context_token',token,
    'resource_fingerprint',production_control.tournament_setup_hash_v1(to_jsonb(resource)-'created_at'),
    'phase',required_phase,'operation_request_id',operation_id,'authorization',input->'authorization',
    'actor_auth_user_id',input#>>'{authorization,auth_user_id}','actor_player_id',input#>>'{authorization,player_id}');
exception when no_data_found then
  raise exception using errcode='55000',message='CANONICAL_RESOURCE_NOT_INSTALLED';
when invalid_text_representation or numeric_value_out_of_range then
  raise exception using errcode='22023',message='CANONICAL_RESOURCE_INPUT_INVALID';
end;
$_$;


ALTER FUNCTION production_control.assert_certification_context_v1(input jsonb, required_phase text, mutation boolean) OWNER TO postgres;

--
-- Name: assert_certification_current_projection_v1(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_current_projection_v1(target text, context jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c jsonb:=production_control.current_certification_context_v1();r production_control.canonical_resource_v1%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;g production_control.future_annual_runtime_generations_v1%rowtype;
 catalog production_control.future_tournament_catalog_v1%rowtype;i production_control.certification_ingress_generations_v1%rowtype;
begin
 select * into strict r from production_control.canonical_resource_v1 where singleton;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=r.resource_id;
 if context is distinct from c or c->>'phase' is distinct from 'READS' or r.resource_class<>'CERTIFICATION'
  or r.database_name<>current_database() or c->>'resource_id' is distinct from r.resource_id
  or target is distinct from c->>'current_tournament_id' or target is distinct from p.tournament_id
  or c->>'pointer_revision' is distinct from p.pointer_revision::text then
  raise exception using errcode='42501',message='CERTIFICATION_READ_CONTEXT_DENIED';end if;
 if target<>'2026'then
  select * into strict g from production_control.future_annual_runtime_generations_v1 where tournament_id=target and generation_status='ACTIVE';
  select * into strict catalog from production_control.future_tournament_catalog_v1 where tournament_id=target;
  select * into strict i from production_control.certification_ingress_generations_v1
   where resource_id=r.resource_id and generation_id=g.admission_generation_id;
  if catalog.lifecycle<>'ACTIVE' or catalog.lifecycle_revision<>p.lifecycle_revision
   or g.pointer_revision<>p.pointer_revision or g.authority<>'SUPABASE'
   or g.authority_generation_id::text is distinct from c->>'authority_epoch_id'
   or i.authority_epoch_id<>g.authority_generation_id or i.tournament_id<>target or i.pointer_revision<>p.pointer_revision then
   raise exception using errcode='42501',message='CERTIFICATION_READ_CONTEXT_DENIED';end if;
 end if;
exception when no_data_found then raise exception using errcode='42501',message='CERTIFICATION_READ_CONTEXT_DENIED';
end;$$;


ALTER FUNCTION production_control.assert_certification_current_projection_v1(target text, context jsonb) OWNER TO postgres;

--
-- Name: assert_certification_historical_identity_v1(text, text, uuid, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_historical_identity_v1(target_tournament text, target_player text, target_auth_user uuid, target_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
 resource production_control.canonical_resource_v1%rowtype;
 context participant_identity.future_tournament_identity_contexts_v1%rowtype;
 generation production_control.future_annual_runtime_generations_v1%rowtype;
 binding participant_identity.future_tournament_participant_bindings_v1%rowtype;
 eligibility record;
 annual_resource production_control.future_tournament_resources_v1%rowtype;
begin
 perform production_control.assert_production_service_role();
 select * into strict resource from production_control.canonical_resource_v1 where singleton;
 if resource.resource_class<>'CERTIFICATION' or resource.database_name<>current_database()
  or resource.provenance_id is distinct from 'urn:bagger:synthetic:'||resource.installation_id::text
  or target_tournament is null or target_tournament!~'^[0-9]{4}$' or target_tournament<='2026'
  or target_player is null or target_auth_user is null or target_role is null
  or target_role not in('PLAYER','DIRECTOR') then
  raise exception using errcode='42501',message='CERTIFICATION_INGRESS_RECOVERY_AUTHORIZATION_REQUIRED';end if;
 select * into strict annual_resource from production_control.future_tournament_resources_v1
  where tournament_id=target_tournament;
 select * into strict context from participant_identity.future_tournament_identity_contexts_v1
  where tournament_id=target_tournament;
 select * into strict generation from production_control.future_annual_runtime_generations_v1
  where runtime_generation_id=context.runtime_generation_id and tournament_id=target_tournament;
 select * into strict binding from participant_identity.future_tournament_participant_bindings_v1
  where tournament_id=target_tournament and player_id=target_player;
 -- Core retains the original approved-run, approved-contact, email, unique-link,
 -- verified identifier, and confirmed Auth equality predicates. Its computed
 -- runtime_eligible is intentionally not execution authority in this read path.
 select * into strict eligibility from production_control.future_participant_identity_eligibility_core_v1(
  target_tournament,resource.resource_id,resource.provenance_id) where player_id=target_player;
 if annual_resource.project_ref is distinct from resource.project_ref
  or annual_resource.project_url is distinct from resource.project_url
  or annual_resource.source_workbook_id is distinct from resource.provenance_id
  or context.status<>'CERTIFIED' or context.source_identity_tournament_id<>'2026'
  or context.binding_fingerprint is distinct from production_control.future_participant_identity_binding_fingerprint_v1(target_tournament)
  or generation.authority<>'SUPABASE'
  or context.authority_generation_id is distinct from generation.authority_generation_id
  or context.admission_generation_id is distinct from generation.admission_generation_id
  or context.pointer_revision is distinct from generation.pointer_revision
  or binding.enrollment_state<>'ENROLLED' or binding.contact_state<>'APPROVED'
  or binding.binding_revision is distinct from context.binding_revision
  or binding.source_identity_tournament_id<>'2026'
  or not eligibility.contact_approved or not eligibility.linked_verified
  or eligibility.auth_user_id is distinct from target_auth_user
  or binding.bound_link_revision is distinct from eligibility.link_revision
  or binding.source_configuration_revision is distinct from eligibility.source_configuration_revision
  or binding.source_contact_fingerprint is distinct from eligibility.source_contact_fingerprint
  or not exists(select 1 from participant_identity.participant_identity_contacts c
   where c.tournament_id=target_tournament and c.player_id=target_player and c.identity_active
    and c.email_normalized=eligibility.source_email_normalized)
  or not exists(select 1 from participant_identity.tournament_roles r
   where r.tournament_id=target_tournament and r.auth_user_id=target_auth_user
    and r.role='PARTICIPANT' and r.role_active and r.revoked_at is null) then
  raise exception using errcode='42501',message='CERTIFICATION_INGRESS_RECOVERY_AUTHORIZATION_REQUIRED';end if;
 -- DIRECTOR entitlement/role and exact originating lease actor are independently
 -- enforced by136 before this helper. This helper grants neither role nor lease.
exception when no_data_found then
 raise exception using errcode='42501',message='CERTIFICATION_INGRESS_RECOVERY_AUTHORIZATION_REQUIRED';
end;$_$;


ALTER FUNCTION production_control.assert_certification_historical_identity_v1(target_tournament text, target_player text, target_auth_user uuid, target_role text) OWNER TO postgres;

--
-- Name: assert_certification_ingress_recovery_actor_v1(jsonb, text, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_ingress_recovery_actor_v1(input jsonb, target_tournament text, require_director boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare actor text:=input#>>'{authorization,player_id}';role_name text:=input#>>'{authorization,role}';
 auth_id uuid:=(input#>>'{authorization,auth_user_id}')::uuid;
begin
 if actor is null or auth_id is null or role_name is null or role_name not in('PLAYER','DIRECTOR')
  or(require_director and role_name<>'DIRECTOR')or not exists(
   select 1 from participant_identity.user_player_links l
   join auth.users u on u.id=l.auth_user_id and u.email_confirmed_at is not null
   join participant_identity.participant_auth_identifiers v on v.auth_user_id=l.auth_user_id and v.player_id=l.player_id
    and v.identifier_type='EMAIL'and v.status='VERIFIED'and v.revoked_at is null
   join participant_identity.tournament_roles r on r.tournament_id=target_tournament and r.auth_user_id=l.auth_user_id
    and r.role=case when role_name='DIRECTOR'then'DIRECTOR'else'PARTICIPANT'end and r.role_active and r.revoked_at is null
   join scoring_authority.tournament_players t on t.tournament_id=target_tournament and t.player_id=l.player_id and t.participation_status='ACTIVE'
   where l.auth_user_id=auth_id and l.player_id=actor and l.status='ACTIVE'and l.revoked_at is null)
  or(role_name='DIRECTOR'and not exists(select 1 from production_control.director_entitlements e
   where e.auth_user_id=auth_id and e.player_id=actor and e.tournament_id=target_tournament
    and e.role in('DIRECTOR','OWNER')and e.status='ACTIVE'and e.revoked_at is null))then
   raise exception using errcode='42501',message='CERTIFICATION_INGRESS_RECOVERY_AUTHORIZATION_REQUIRED';end if;
 if target_tournament<>'2026'then
  -- Installed by the separately reviewed annual identity extension. Until then,
  -- future-target recovery fails closed; it cannot borrow current write gates.
  perform production_control.assert_certification_historical_identity_v1(target_tournament,actor,auth_id,role_name);
 end if;
end;$$;


ALTER FUNCTION production_control.assert_certification_ingress_recovery_actor_v1(input jsonb, target_tournament text, require_director boolean) OWNER TO postgres;

--
-- Name: assert_certification_odds_actor_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_odds_actor_v1(input jsonb, context jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if input#>>'{authorization,role}'is distinct from 'DIRECTOR'
  or coalesce((input#>>'{authorization,impersonating}')::boolean,false)
  or coalesce((input#>>'{authorization,impersonated}')::boolean,false)
  or coalesce((input#>>'{authorization,is_impersonating}')::boolean,false)
  or nullif(input#>>'{authorization,impersonating_player_id}','')is not null
  or input#>>'{authorization,tournament_id}'is distinct from context->>'tournament_id'then
  raise exception using errcode='42501',message='CERTIFICATION_ODDS_DIRECTOR_REQUIRED';end if;
 if context->>'tournament_id'='2026'then perform production_control.assert_production_scoring_actor(input,true);
 else perform production_control.assert_canonical_future_scoring_actor_v1(input,context->>'tournament_id',true,context);end if;
end;$$;


ALTER FUNCTION production_control.assert_certification_odds_actor_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: assert_certification_odds_live_source_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_odds_live_source_v1(target text, snapshot jsonb, context jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare current_value jsonb;captured jsonb:=snapshot#>'{metadata,sourceRevision}';
 captured_fingerprint text:=snapshot#>>'{metadata,certificationLiveSourceFingerprint}';
begin
 perform production_control.lock_certification_odds_source_v1(target,context);
 current_value:=public.read_leaderboards_core_view(target);
 if current_value->>'ok'is distinct from'true'
  or jsonb_typeof(captured)is distinct from'object' or captured='{}'::jsonb
  or captured->>'tournamentId'is distinct from target
  or captured is distinct from current_value#>'{data,source_revision}'
  or captured_fingerprint is null or captured_fingerprint!~'^[0-9a-f]{64}$'
  or captured_fingerprint is distinct from production_control.future_runtime_hash_v2((current_value->'data')-'query_ms')then
  raise exception using errcode='40001',message='ODDS_CALCULATION_SOURCE_ADVANCED';end if;
end;$_$;


ALTER FUNCTION production_control.assert_certification_odds_live_source_v1(target text, snapshot jsonb, context jsonb) OWNER TO postgres;

--
-- Name: canonical_resource_v1; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.canonical_resource_v1 (
    singleton boolean DEFAULT true NOT NULL,
    resource_id text NOT NULL,
    resource_class text NOT NULL,
    installation_id uuid NOT NULL,
    database_name text NOT NULL,
    project_ref text NOT NULL,
    project_url text NOT NULL,
    vercel_team_id text NOT NULL,
    vercel_project_id text NOT NULL,
    registration_revision bigint NOT NULL,
    manifest_digest text NOT NULL,
    schema_contract text NOT NULL,
    schema_digest text NOT NULL,
    provenance_id text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT canonical_resource_v1_check CHECK ((project_url = (('https://'::text || project_ref) || '.supabase.co'::text))),
    CONSTRAINT canonical_resource_v1_check1 CHECK ((((resource_class = 'PRODUCTION'::text) AND (resource_id = 'BAGGER_INV_PRODUCTION'::text) AND (project_ref = 'ymqhhtxaywtqllynrmxe'::text) AND (provenance_id = '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'::text)) OR ((resource_class = 'CERTIFICATION'::text) AND (resource_id = ('CERTIFICATION:'::text || (installation_id)::text)) AND (project_ref <> ALL (ARRAY['ymqhhtxaywtqllynrmxe'::text, 'idgigvjjqkfbqjeredpb'::text])) AND (provenance_id = ('urn:bagger:synthetic:'::text || (installation_id)::text))))),
    CONSTRAINT canonical_resource_v1_manifest_digest_check CHECK ((manifest_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT canonical_resource_v1_project_ref_check CHECK ((project_ref ~ '^[a-z]{20}$'::text)),
    CONSTRAINT canonical_resource_v1_registration_revision_check CHECK ((registration_revision > 0)),
    CONSTRAINT canonical_resource_v1_resource_class_check CHECK ((resource_class = ANY (ARRAY['PRODUCTION'::text, 'CERTIFICATION'::text]))),
    CONSTRAINT canonical_resource_v1_schema_contract_check CHECK ((schema_contract = 'canonical-resource-v1'::text)),
    CONSTRAINT canonical_resource_v1_schema_digest_check CHECK ((schema_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT canonical_resource_v1_singleton_check CHECK (singleton),
    CONSTRAINT canonical_resource_v1_vercel_project_id_check CHECK (((length(vercel_project_id) >= 6) AND (length(vercel_project_id) <= 100))),
    CONSTRAINT canonical_resource_v1_vercel_team_id_check CHECK (((length(vercel_team_id) >= 6) AND (length(vercel_team_id) <= 100)))
);


ALTER TABLE production_control.canonical_resource_v1 OWNER TO postgres;

--
-- Name: assert_certification_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certification_read_v1(context jsonb, input jsonb) RETURNS production_control.canonical_resource_v1
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare verified jsonb; r production_control.canonical_resource_v1%rowtype;
begin
 verified:=production_control.current_certification_context_v1();
 if context->>'context_token' is distinct from verified->>'context_token'
   or context->>'resource_id' is distinct from verified->>'resource_id'
   or verified->>'phase' is distinct from 'READS'
   or input ?| array['authorization','resource','deployment','environment','project_ref','project_url','source_workbook_id',
     'resource_id','installation_id','activation_revision','release_commit','binding_id']
   or (input ? 'target_tournament_id' and input->>'target_tournament_id' is distinct from '2026') then
  raise exception using errcode='42501',message='CERTIFICATION_READ_CONTEXT_DENIED';
 end if;
 select * into strict r from production_control.canonical_resource_v1 where resource_id=verified->>'resource_id';
 return r;
end;
$$;


ALTER FUNCTION production_control.assert_certification_read_v1(context jsonb, input jsonb) OWNER TO postgres;

--
-- Name: assert_certified_google_writer_fence_rehearsal(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_certified_google_writer_fence_rehearsal(target_candidate_commit text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
begin
  perform production_control.assert_no_unrestored_google_writer_fence_rehearsal();
  if target_candidate_commit !~ '^[0-9a-f]{40}$'
     or exists (
       select 1
       from production_control.google_writer_provider_fences value
       where value.status in (
         'INSTALLING', 'ABORTING', 'INSTALLED', 'REMOVAL_AUTHORIZED'
       )
     )
     or not exists (
       select 1
       from production_control.google_writer_provider_fences fence
       join production_control.google_writer_provider_fence_verifications
         verification
         on verification.verification_id = fence.active_verification_id
        and verification.fence_id = fence.fence_id
       join production_control.google_writer_provider_fence_install_aborts abort_value
         on abort_value.fence_id = fence.fence_id
       join production_control.google_writer_provider_fence_install_dispatches
         install_dispatch
         on install_dispatch.dispatch_id = verification.install_dispatch_id
       join production_control.google_writer_provider_fence_abort_dispatches
         restore_dispatch
         on restore_dispatch.dispatch_id = abort_value.restore_dispatch_id
       where fence.lifecycle_mode = 'REHEARSAL'
         and fence.status = 'REHEARSAL_RESTORED'
         and fence.candidate_deployment_commit = target_candidate_commit
         and fence.rehearsal_restored_at is not null
         and fence.acl_reader_confirmed_at is not null
         and fence.acl_writer_restored_at is not null
         and fence.restore_global_writer_stop_active_at is not null
         and fence.acl_writer_restored_at >=
           fence.restore_global_writer_stop_active_at + interval '1810 seconds'
         and verification.acl_contract_version = 'DRIVE_ACL_V2'
         and verification.protection_count = 0
         and verification.protection_records = '[]'::jsonb
         and verification.protected_sheet_ids = '[]'::jsonb
         and verification.protected_range_ids = '[]'::jsonb
         and verification.legacy_role = 'reader'
         and not verification.legacy_can_edit
         and not verification.legacy_can_share
         and install_dispatch.outcome_status = 'TARGET_CONFIRMED'
         and install_dispatch.transition_proof->>'currentRole' = 'reader'
         and install_dispatch.transition_proof->'currentLegacyCanEdit' =
           'false'::jsonb
         and install_dispatch.transition_proof->'currentLegacyCanShare' =
           'false'::jsonb
         and restore_dispatch.outcome_status = 'TARGET_CONFIRMED'
         and restore_dispatch.transition_proof->>'currentRole' = 'writer'
         and restore_dispatch.transition_proof->'currentLegacyCanEdit' =
           'true'::jsonb
         and restore_dispatch.transition_proof->'currentLegacyCanShare' =
           'true'::jsonb
         and abort_value.removed_protected_range_ids = '[]'::jsonb
         and abort_value.active_run_owned_protection_count = 0
         and abort_value.restored_legacy_role = 'writer'
         and abort_value.restored_legacy_can_edit
         and abort_value.restored_legacy_can_share
     )
     or not exists (
       select 1
       from production_control.cutover_activation_state activation
       cross join production_control.resource_scope resource
       cross join scoring_authority.ingress_gates gate
       where activation.scope_key = 'BAGGER_INV_PRODUCTION'
         and resource.scope_key = 'BAGGER_INV_PRODUCTION'
         and gate.tournament_id = '2026'
         and activation.state = 'DORMANT'
         and activation.current_authority = 'GOOGLE'
         and not activation.scoring_ingress_enabled
         and activation.active_transition_epoch_id is null
         and activation.active_google_writer_provider_fence_id is null
         and activation.active_google_writer_provider_verification_id is null
         and activation.active_vercel_quiesce_evidence_id is null
         and resource.scoring_authority = 'GOOGLE'
         and resource.participant_identity_authority = 'PASSPORT'
         and resource.current_tournament_read_authority = 'GOOGLE'
         and not resource.scoring_ingress_enabled
         and not resource.workers_enabled
         and gate.state = 'PAUSED'
         and gate.authority = 'GOOGLE'
         and gate.admission_state = 'OPEN'
         and not gate.admission_protocol_enforced
         and gate.active_closure_id is null
         and gate.external_fence_evidence_id is null
         and gate.google_writer_provider_fence_id is null
         and gate.google_writer_provider_verification_id is null
         and exists (
           select 1
           from production_control.google_writer_provider_fences certified_fence
           join production_control.google_writer_provider_fence_install_dispatches
             certified_dispatch
             on certified_dispatch.fence_id = certified_fence.fence_id
           where certified_fence.lifecycle_mode = 'REHEARSAL'
             and certified_fence.status = 'REHEARSAL_RESTORED'
             and certified_fence.candidate_deployment_commit =
               target_candidate_commit
             and certified_dispatch.outcome_status = 'TARGET_CONFIRMED'
             and gate.provider_principal_fingerprint =
               certified_dispatch.transition_intent->>'legacyPrincipalFingerprint'
         )
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_DRIVE_ACL_REHEARSAL_CERTIFICATION_REQUIRED';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_certified_google_writer_fence_rehearsal(target_candidate_commit text) OWNER TO postgres;

--
-- Name: assert_current_certification_future_context_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_current_certification_future_context_v1(resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c jsonb; r production_control.canonical_resource_v1%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;
begin
 c:=production_control.current_certification_context_v1();
 select * into strict r from production_control.canonical_resource_v1 where singleton;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=r.resource_id;
 if resource_context is distinct from c or r.resource_class is distinct from 'CERTIFICATION'
  or r.database_name is distinct from current_database() or c->>'resource_id' is distinct from r.resource_id
  or c->>'current_tournament_id' is distinct from p.tournament_id
  or c->>'tournament_id' is distinct from p.tournament_id or p.tournament_year<=2026
  or (c->>'pointer_revision')::bigint is distinct from p.pointer_revision then
  raise exception using errcode='42501',message='CERTIFICATION_FUTURE_CONTEXT_REQUIRED';end if;
 return c;
end;$$;


ALTER FUNCTION production_control.assert_current_certification_future_context_v1(resource_context jsonb) OWNER TO postgres;

--
-- Name: assert_current_external_scoring_fence(uuid, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_current_external_scoring_fence(target_evidence_id uuid, target_deployment_commit text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  evidence production_control.scoring_external_fence_evidence%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
begin
  select * into evidence
  from production_control.scoring_external_fence_evidence value
  where value.evidence_id = target_evidence_id;
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_EXTERNAL_SCORING_ACL_FENCE_EVIDENCE_REQUIRED';
  end if;
  select * into fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = evidence.provider_fence_id;
  if not found
     or evidence.revoked_at is not null
     or evidence.expires_at <= pg_catalog.clock_timestamp()
     or evidence.captured_at > pg_catalog.clock_timestamp() + interval '30 seconds'
     or evidence.captured_at < pg_catalog.clock_timestamp() - interval '2100 seconds'
     or (fence.lifecycle_mode = 'CUTOVER' and
       evidence.deployment_commit is distinct from
         pg_catalog.lower(target_deployment_commit))
     or (fence.lifecycle_mode = 'REHEARSAL' and
       evidence.deployment_commit is distinct from
         fence.candidate_deployment_commit)
     or not evidence.legacy_deployments_fenced
     or not evidence.legacy_google_credentials_fenced
     or not evidence.non_owner_manual_google_scoring_fenced
     or not evidence.owner_override_operationally_frozen
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_EXTERNAL_SCORING_ACL_FENCE_EVIDENCE_REQUIRED';
  end if;
  perform production_control.assert_current_google_writer_provider_fence(
    evidence.provider_fence_id, evidence.provider_fence_verification_id,
    case when fence.lifecycle_mode = 'REHEARSAL'
      then fence.candidate_deployment_commit else target_deployment_commit end,
    true
  );
end;
$$;


ALTER FUNCTION production_control.assert_current_external_scoring_fence(target_evidence_id uuid, target_deployment_commit text) OWNER TO postgres;

--
-- Name: assert_current_google_writer_provider_fence(uuid, uuid, text, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_current_google_writer_provider_fence(target_fence_id uuid, target_verification_id uuid, target_candidate_commit text, require_fresh_quiesce boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  fence production_control.google_writer_provider_fences%rowtype;
  verification
    production_control.google_writer_provider_fence_verifications%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  install_dispatch
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  readback_2
    production_control.google_writer_provider_fence_settlement_observations%rowtype;
begin
  select * into fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = target_fence_id;
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_FENCE_REQUIRED';
  end if;
  select * into verification
  from production_control.google_writer_provider_fence_verifications value
  where value.verification_id = target_verification_id
    and value.fence_id = fence.fence_id;
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_VERIFICATION_REQUIRED';
  end if;
  select * into quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = verification.quiesce_evidence_id;
  select * into install_dispatch
  from production_control.google_writer_provider_fence_install_dispatches value
  where value.dispatch_id = verification.install_dispatch_id
    and value.fence_id = fence.fence_id;
  select * into readback_2
  from production_control.google_writer_provider_fence_settlement_observations value
  where value.observation_id = verification.settlement_readback_2_observation_id
    and value.fence_id = fence.fence_id;

  if fence.status is distinct from 'INSTALLED'
     or fence.active_verification_id is distinct from verification.verification_id
     or target_candidate_commit !~ '^[0-9a-f]{40}$'
     or (fence.lifecycle_mode = 'CUTOVER' and
       fence.candidate_deployment_commit is distinct from
         pg_catalog.lower(target_candidate_commit))
     or verification.acl_contract_version is distinct from 'DRIVE_ACL_V2'
     or verification.expires_at <= pg_catalog.clock_timestamp()
     or verification.protection_count <> 0
     or verification.protection_records is distinct from '[]'::jsonb
     or verification.protected_sheet_ids is distinct from '[]'::jsonb
     or verification.protected_range_ids is distinct from '[]'::jsonb
     or verification.legacy_role is distinct from 'reader'
     or verification.legacy_can_edit
     or verification.legacy_can_share
     or verification.recovery_only
     or not verification.legacy_deployments_fenced
     or not verification.legacy_google_credentials_fenced
     or not verification.non_owner_manual_google_scoring_fenced
     or not verification.owner_override_operationally_frozen
     or verification.global_writer_stop_active_at is distinct from
       fence.global_writer_stop_active_at
     or install_dispatch.dispatch_id is null
     or install_dispatch.outcome_status is distinct from 'TARGET_CONFIRMED'
     or install_dispatch.provider_mutation_class is distinct from
       'DRIVE_LEGACY_PERMISSION_WRITER_TO_READER_V1'
     or install_dispatch.transition_intent_fingerprint is distinct from
       verification.acl_transition_intent_fingerprint
     or install_dispatch.transition_proof_fingerprint is distinct from
       verification.acl_transition_proof_fingerprint
     or install_dispatch.transition_proof is distinct from
       verification.acl_transition_proof
     or install_dispatch.transition_proof->>'currentRole' is distinct from
       'reader'
     or install_dispatch.transition_proof->'currentLegacyCanEdit'
       is distinct from 'false'::jsonb
     or install_dispatch.transition_proof->'currentLegacyCanShare'
       is distinct from 'false'::jsonb
     or readback_2.observation_id is null
     or readback_2.stage is distinct from 'SETTLEMENT_READBACK_2'
     or readback_2.acl_transition_intent_fingerprint is distinct from
       verification.acl_transition_intent_fingerprint
     or readback_2.acl_transition_proof_fingerprint is distinct from
       verification.acl_transition_proof_fingerprint
     or readback_2.acl_transition_proof is distinct from
       verification.acl_transition_proof
     or readback_2.acl_fingerprint is distinct from verification.acl_fingerprint
     or readback_2.permission_inventory_fingerprint is distinct from
       verification.permission_inventory_fingerprint
     or readback_2.legacy_edit_capability_fingerprint is distinct from
       verification.legacy_edit_capability_fingerprint
     or quiesce.evidence_id is null
     or quiesce.purpose is distinct from fence.lifecycle_mode
     or quiesce.candidate_deployment_id is distinct from
       fence.candidate_deployment_id
     or quiesce.candidate_deployment_commit is distinct from
       fence.candidate_deployment_commit
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or (require_fresh_quiesce and (
       quiesce.status is distinct from 'VERIFIED'
       or quiesce.expires_at <= pg_catalog.clock_timestamp()
       or quiesce.owner_freeze_expires_at <= pg_catalog.clock_timestamp()
     ))
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_FENCE_NOT_CURRENT';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_current_google_writer_provider_fence(target_fence_id uuid, target_verification_id uuid, target_candidate_commit text, require_fresh_quiesce boolean) OWNER TO postgres;

