--
-- Name: assert_current_shadow_v2_dormant(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_current_shadow_v2_dormant() RETURNS production_control.resource_scope
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
begin
  select * into strict scope
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';

  if scope.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or scope.project_url <> 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or scope.google_workbook_id <> '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or scope.vercel_project <> 'bagger-inv'
     or scope.canonical_domain <> 'https://baggerinv.com'
     or scope.current_tournament_id <> '2026'
     or scope.current_tournament_year <> 2026
     or scope.current_tournament_read_authority <> 'GOOGLE'
     or scope.scoring_authority <> 'GOOGLE'
     or scope.participant_identity_authority <> 'PASSPORT'
     or scope.public_supabase_reads_enabled
     or scope.scoring_ingress_enabled
     or scope.google_writes_enabled
     or scope.auth_user_creation_enabled
     or scope.odds_publication_enabled
     or scope.workers_enabled then
    raise exception using errcode = '42501', message = 'DORMANT_PRODUCTION_FOUNDATION_REQUIRED';
  end if;
  if not exists (
    select 1 from production_control.tournament_scopes tournament_scope
    where tournament_scope.tournament_id = '2026'
      and tournament_scope.tournament_year = 2026
      and tournament_scope.source_workbook_id = scope.google_workbook_id
      and tournament_scope.scope_kind = 'CURRENT_TOURNAMENT'
      and tournament_scope.active_for_shadow_import
  ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_TOURNAMENT_SCOPE_REQUIRED';
  end if;
  if exists (
    select 1 from production_control.worker_controls
    where enabled or scheduler_installed or google_writes_allowed
  ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_SHADOW_WORKERS_MUST_REMAIN_DORMANT';
  end if;
  return scope;
end;
$$;


ALTER FUNCTION production_control.assert_current_shadow_v2_dormant() OWNER TO postgres;

--
-- Name: assert_current_vercel_alias_recaptures(uuid, integer); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_current_vercel_alias_recaptures(target_evidence_id uuid, required_recapture_count integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
  begin_attestation production_control.vercel_provider_attestations%rowtype;
  finalize_attestation production_control.vercel_provider_attestations%rowtype;
  begin_capture production_control.vercel_provider_alias_captures%rowtype;
  finalize_capture production_control.vercel_provider_alias_captures%rowtype;
  response_value jsonb;
begin
  if target_evidence_id is null or required_recapture_count not in (1, 2) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_ALIAS_RECAPTURE_INPUT_INVALID';
  end if;
  select * into strict evidence
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = target_evidence_id;
  select * into strict begin_attestation
  from production_control.vercel_provider_attestations value
  where value.evidence_id = target_evidence_id
    and value.stage = 'BEGIN' and value.status = 'BOUND';
  select * into strict begin_capture
  from production_control.vercel_provider_alias_captures value
  where value.attestation_id = begin_attestation.attestation_id;
  perform production_control.assert_exact_vercel_alias_inventory(
    begin_capture.alias_inventory_records,
    begin_capture.alias_inventory_fingerprint,
    evidence.candidate_deployment_id,
    evidence.candidate_alias_origin,
    evidence.candidate_immutable_origin,
    evidence.purpose
  );

  if begin_capture.stage is distinct from 'BEGIN' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_ALIAS_RECAPTURE_BEGIN_MISMATCH';
  end if;
  if required_recapture_count = 2 then
    select * into strict finalize_attestation
    from production_control.vercel_provider_attestations value
    where value.evidence_id = target_evidence_id
      and value.stage = 'FINALIZE' and value.status = 'BOUND';
    select * into strict finalize_capture
    from production_control.vercel_provider_alias_captures value
    where value.attestation_id = finalize_attestation.attestation_id;
    perform production_control.assert_exact_vercel_alias_inventory(
      finalize_capture.alias_inventory_records,
      finalize_capture.alias_inventory_fingerprint,
      evidence.candidate_deployment_id,
      evidence.candidate_alias_origin,
      evidence.candidate_immutable_origin,
      evidence.purpose
    );
    if finalize_capture.stage is distinct from 'FINALIZE'
       or begin_attestation.attestation_id = finalize_attestation.attestation_id
       or begin_attestation.attestation_fingerprint =
         finalize_attestation.attestation_fingerprint
       or begin_attestation.provider_observed_at >=
         finalize_attestation.provider_observed_at
       or begin_capture.alias_inventory_count is distinct from
         finalize_capture.alias_inventory_count
       or begin_capture.alias_inventory_fingerprint is distinct from
         finalize_capture.alias_inventory_fingerprint
       or begin_capture.alias_inventory_records is distinct from
         finalize_capture.alias_inventory_records
       or begin_capture.alias_pagination_page_count is distinct from
         finalize_capture.alias_pagination_page_count
       or begin_capture.alias_pagination_fingerprint is distinct from
         finalize_capture.alias_pagination_fingerprint then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_ALIAS_RECAPTURE_FINALIZE_DRIFT';
    end if;
  elsif exists (
    select 1 from production_control.vercel_provider_attestations value
    where value.evidence_id = target_evidence_id and value.stage = 'FINALIZE'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_ALIAS_RECAPTURE_COUNT_MISMATCH';
  end if;

  response_value := production_control.vercel_alias_recapture_response(
    target_evidence_id
  );
  if (response_value->>'alias_recapture_count')::integer is distinct from
       required_recapture_count then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_ALIAS_RECAPTURE_COUNT_MISMATCH';
  end if;
  return response_value;
end;
$$;


ALTER FUNCTION production_control.assert_current_vercel_alias_recaptures(target_evidence_id uuid, required_recapture_count integer) OWNER TO postgres;

--
-- Name: assert_draft_authoring_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_draft_authoring_resource_v2(input jsonb, resource_context jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  target text := pg_catalog.btrim(coalesce(
    input->>'target_tournament_id',''));
  target_year integer;
begin
  perform production_control.assert_canonical_future_authoring_resource_v2(
    input, resource_context, 'production-draft-authoring-v1', false
  );
  begin target_year := (input->>'target_tournament_year')::integer;
  exception when others then
    raise exception using errcode='22023',
      message='DRAFT_TOURNAMENT_REQUIRED';
  end;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key=(resource_context->>'resource_id');
  if target !~ '^20[0-9]{2}$' or target <> target_year::text then
    raise exception using errcode='22023',
      message='DRAFT_TOURNAMENT_REQUIRED';
  end if;
  if target = pointer.tournament_id then
    if target_year <> pointer.tournament_year or not exists (
      select 1 from production_control.future_tournament_catalog_v1 value
      where value.tournament_id=target
        and value.tournament_year=target_year
        and value.lifecycle='ACTIVE'
        and value.lifecycle_revision=pointer.lifecycle_revision
    ) then
      raise exception using errcode='55000',
        message='DRAFT_CURRENT_TOURNAMENT_REQUIRED';
    end if;
  elsif not exists (
    select 1
    from production_control.future_tournament_catalog_v1 catalog
    join production_control.future_tournament_resources_v1 resource
      on resource.tournament_id=catalog.tournament_id
    where catalog.tournament_id=target
      and catalog.tournament_year=target_year
      and catalog.tournament_year>pointer.tournament_year
      and catalog.lifecycle in ('DRAFT','CONFIGURING','READY_FOR_ACTIVATION')
      and resource.project_ref=input->>'project_ref'
      and resource.project_url=input->>'project_url'
      and (resource_context->>'resource_class'='CERTIFICATION'
        or resource.project_ref !~* '(preview|staging|test)')
  ) then
    raise exception using errcode='42501',
      message='DRAFT_FUTURE_TOURNAMENT_REQUIRED';
  end if;
  return target;
end;

$_$;


ALTER FUNCTION production_control.assert_draft_authoring_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

