--
-- Name: assert_exact_cutover_resource_scope(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_exact_cutover_resource_scope(input jsonb, require_staged_release boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
begin
  perform production_control.assert_production_service_role();

  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';

  if resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.project_url <> 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or resource.google_workbook_id <> '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.vercel_project <> 'bagger-inv'
     or resource.canonical_domain <> 'https://baggerinv.com'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_year <> 2026 then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_RESOURCE_SCOPE_INVALID';
  end if;

  if upper(coalesce(input->>'environment', '')) <> 'PRODUCTION'
     or input->>'project_ref' is distinct from resource.project_ref
     or input->>'project_url' is distinct from resource.project_url
     or input->>'source_workbook_id' is distinct from resource.google_workbook_id
     or input->>'tournament_id' is distinct from resource.current_tournament_id then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_RESOURCE_ASSERTION_FAILED';
  end if;

  if require_staged_release then
    if activation.state = 'DORMANT'
       or activation.expected_deployment_commit is null
       or activation.expected_vercel_project_id
          is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
       or input->>'deployment_commit' is distinct from activation.expected_deployment_commit then
      raise exception using errcode = 'P0001', message = 'PRODUCTION_EXACT_RELEASE_REQUIRED';
    end if;
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_exact_cutover_resource_scope(input jsonb, require_staged_release boolean) OWNER TO postgres;

--
-- Name: assert_exact_google_writer_fence_protections(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_exact_google_writer_fence_protections(input jsonb, description_prefix text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  normalized jsonb;
  sheet_ids jsonb;
  record_count integer;
  unique_range_count integer;
begin
  if pg_catalog.jsonb_typeof(input) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_PROTECTIONS_ARRAY_REQUIRED';
  end if;
  normalized :=
    production_control.normalized_google_writer_fence_protections(input);
  record_count := pg_catalog.jsonb_array_length(normalized);
  select pg_catalog.count(distinct (value->>'protectedRangeId')::bigint)::integer,
    coalesce(pg_catalog.jsonb_agg(
      (value->>'sheetId')::bigint order by (value->>'sheetId')::bigint
    ), '[]'::jsonb)
  into unique_range_count, sheet_ids
  from pg_catalog.jsonb_array_elements(normalized) value;
  if record_count <> 17
     or unique_range_count <> 17
     or normalized is distinct from input
     or sheet_ids is distinct from
       production_control.expected_google_writer_fence_sheet_ids()
     or exists (
       select 1 from pg_catalog.jsonb_array_elements(normalized) value
       where (value->>'protectedRangeId')::bigint <= 0
         or value->>'description' is distinct from
           description_prefix || ':' || (value->>'sheetId')
         or value->>'warningOnly' is distinct from 'false'
         or value->>'dedicatedRequestingUserCanEdit' is distinct from 'true'
         or value->>'legacyRequestingUserCanEdit' is distinct from 'false'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_PROTECTIONS_MISMATCH';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_exact_google_writer_fence_protections(input jsonb, description_prefix text) OWNER TO postgres;

--
-- Name: assert_exact_vercel_alias_inventory(jsonb, text, text, text, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_exact_vercel_alias_inventory(input jsonb, expected_fingerprint text, candidate_deployment_id text, candidate_alias_origin text, candidate_immutable_origin text, purpose_value text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  normalized jsonb;
  candidate_alias_hostname text;
  candidate_immutable_hostname text;
begin
  if pg_catalog.jsonb_typeof(input) is distinct from 'array'
     or pg_catalog.jsonb_array_length(input) <> 56
     or coalesce(expected_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or coalesce(candidate_deployment_id, '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(candidate_alias_origin, '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(candidate_immutable_origin, '')
       !~ '^https://[a-z0-9.-]+$'
     or purpose_value not in ('REHEARSAL', 'CUTOVER')
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(input) value
       where pg_catalog.jsonb_typeof(value) is distinct from 'array'
          or pg_catalog.jsonb_array_length(value) <> 5
          or coalesce(value->>0, '') !~ '^[a-z0-9.-]+$'
          or coalesce(value->>1, '') !~ '^dpl_[A-Za-z0-9]{8,64}$'
          or coalesce(value->>2, '') !~ '^[a-z0-9.-]+[.]vercel[.]app$'
          or not (
            (value->3 = 'null'::jsonb and value->4 = 'null'::jsonb)
            or (
              coalesce(value->>3, '') ~ '^[a-z0-9.-]+$'
              and pg_catalog.jsonb_typeof(value->4) = 'number'
              and (value->>4)::integer in (301, 302, 307, 308)
            )
          )
     ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_ALIAS_INVENTORY_INPUT_INVALID';
  end if;

  normalized := production_control.normalized_vercel_alias_inventory(input);
  candidate_alias_hostname := pg_catalog.lower(pg_catalog.regexp_replace(
    pg_catalog.rtrim(candidate_alias_origin, '/'), '^https://', ''
  ));
  candidate_immutable_hostname := pg_catalog.lower(pg_catalog.regexp_replace(
    pg_catalog.rtrim(candidate_immutable_origin, '/'), '^https://', ''
  ));
  if normalized is distinct from input
     or (select pg_catalog.count(distinct value->>0)
       from pg_catalog.jsonb_array_elements(normalized) value) <> 56
     or production_control.vercel_alias_inventory_fingerprint(normalized)
       is distinct from expected_fingerprint
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized) value
       where value = pg_catalog.jsonb_build_array(
         'bagger-inv-git-agent-course-hole-be25e6-sandbagger-invitational.vercel.app',
         'dpl_73dJVxZVEXkUqrinj17RHVFcjP7j',
         'bagger-kj3c0pkvm-sandbagger-invitational.vercel.app',
         null, null
       )) <> 1
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized) value
       where value = pg_catalog.jsonb_build_array(
         candidate_alias_hostname, candidate_deployment_id,
         candidate_immutable_hostname, null, null
       )) <> 1
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized) value
       where value = pg_catalog.jsonb_build_array(
         'baggerinv.com',
         case when purpose_value = 'CUTOVER' then candidate_deployment_id
           else 'dpl_5uQB4VBY3FEgWHTS5vZYU2J9rmM2' end,
         case when purpose_value = 'CUTOVER' then candidate_immutable_hostname
           else 'bagger-drmix94o0-sandbagger-invitational.vercel.app' end,
         null, null
       )) <> 1
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized) value
       where value = pg_catalog.jsonb_build_array(
         'bagger-inv.vercel.app',
         case when purpose_value = 'CUTOVER' then candidate_deployment_id
           else 'dpl_5uQB4VBY3FEgWHTS5vZYU2J9rmM2' end,
         case when purpose_value = 'CUTOVER' then candidate_immutable_hostname
           else 'bagger-drmix94o0-sandbagger-invitational.vercel.app' end,
         null, null
       )) <> 1
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized) value
       where value = pg_catalog.jsonb_build_array(
         'www.baggerinv.com',
         case when purpose_value = 'CUTOVER' then candidate_deployment_id
           else 'dpl_5uQB4VBY3FEgWHTS5vZYU2J9rmM2' end,
         case when purpose_value = 'CUTOVER' then candidate_immutable_hostname
           else 'bagger-drmix94o0-sandbagger-invitational.vercel.app' end,
         'baggerinv.com', 308
       )) <> 1
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized) value
       where value = pg_catalog.jsonb_build_array(
         'bagger-inv-git-main-sandbagger-invitational.vercel.app',
         'dpl_5uQB4VBY3FEgWHTS5vZYU2J9rmM2',
         'bagger-drmix94o0-sandbagger-invitational.vercel.app',
         null, null
       )) <> 1 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_ALIAS_INVENTORY_MISMATCH';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_exact_vercel_alias_inventory(input jsonb, expected_fingerprint text, candidate_deployment_id text, candidate_alias_origin text, candidate_immutable_origin text, purpose_value text) OWNER TO postgres;

--
-- Name: assert_exact_vercel_live_inventory(jsonb, jsonb, text, text, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_exact_vercel_live_inventory(retained_inventory jsonb, live_inventory jsonb, candidate_deployment_id text, candidate_deployment_commit text, candidate_immutable_origin text, candidate_deployment_target text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  normalized_retained jsonb;
  normalized_live jsonb;
  retained_candidate_scope text;
  dynamic_candidate_scope text;
  retained_candidate_count integer;
  live_candidate_count integer;
  expected_count integer;
begin
  perform production_control.assert_exact_vercel_origin_inventory(
    retained_inventory
  );
  if candidate_deployment_target is distinct from 'PREVIEW'
     or coalesce(candidate_deployment_id, '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(candidate_deployment_commit, '') !~ '^[0-9a-f]{40}$'
     or coalesce(candidate_immutable_origin, '')
       !~ '^https://[a-z0-9.-]+$'
     or pg_catalog.jsonb_typeof(live_inventory) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_LIVE_ORIGIN_INVENTORY_INPUT_INVALID';
  end if;
  normalized_retained :=
    production_control.normalized_vercel_origin_inventory(retained_inventory);
  normalized_live :=
    production_control.normalized_vercel_origin_inventory(live_inventory);
  -- The authenticated control surface is deployment-bound Project Preview for
  -- every v4 transition mode. Production-target inventory remains retained as
  -- historical evidence, but it can never be selected as the live candidate.
  retained_candidate_scope := 'PROJECT_PREVIEW';
  dynamic_candidate_scope := 'PROJECT_PREVIEW';

  select pg_catalog.count(*)::integer
  into retained_candidate_count
  from pg_catalog.jsonb_array_elements(normalized_retained) value
  where value->>0 = candidate_deployment_id
    and value->>1 = pg_catalog.lower(candidate_deployment_commit)
    and value->>2 = pg_catalog.lower(pg_catalog.rtrim(
      candidate_immutable_origin, '/'
    ))
    and value->>3 = retained_candidate_scope
    and value->>4 = 'READY'
    and coalesce(value->>5, '') ~ '^[0-9a-f]{64}$';
  select pg_catalog.count(*)::integer
  into live_candidate_count
  from pg_catalog.jsonb_array_elements(normalized_live) value
  where value->>0 = candidate_deployment_id
    and value->>1 = pg_catalog.lower(candidate_deployment_commit)
    and value->>2 = pg_catalog.lower(pg_catalog.rtrim(
      candidate_immutable_origin, '/'
    ))
    and value->>3 = case when retained_candidate_count = 1
      then retained_candidate_scope else dynamic_candidate_scope end
    and value->>4 = 'READY'
    and coalesce(value->>5, '') ~ '^[0-9a-f]{64}$';
  expected_count := pg_catalog.jsonb_array_length(normalized_retained)
    + case when retained_candidate_count = 1 then 0 else 1 end;

  if normalized_live is distinct from live_inventory
     or retained_candidate_count not in (0, 1)
     or live_candidate_count <> 1
     or pg_catalog.jsonb_array_length(normalized_live) <> expected_count
     or (select pg_catalog.count(distinct value->>0)
       from pg_catalog.jsonb_array_elements(normalized_live) value) <>
       expected_count
     or (select pg_catalog.count(distinct value->>2)
       from pg_catalog.jsonb_array_elements(normalized_live) value) <>
       expected_count
     or exists (
       select value
       from pg_catalog.jsonb_array_elements(normalized_retained)
       except
       select value
       from pg_catalog.jsonb_array_elements(normalized_live)
     )
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(normalized_live) live(record)
       where not exists (
         select 1
         from pg_catalog.jsonb_array_elements(normalized_retained) retained(record)
         where retained.record = live.record
       ) and not (
         live.record->>0 = candidate_deployment_id
         and live.record->>1 = pg_catalog.lower(candidate_deployment_commit)
         and live.record->>2 = pg_catalog.lower(pg_catalog.rtrim(
           candidate_immutable_origin, '/'
         ))
         and live.record->>3 = dynamic_candidate_scope
         and live.record->>4 = 'READY'
         and coalesce(live.record->>5, '') ~ '^[0-9a-f]{64}$'
       )
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_LIVE_ORIGIN_INVENTORY_MISMATCH';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_exact_vercel_live_inventory(retained_inventory jsonb, live_inventory jsonb, candidate_deployment_id text, candidate_deployment_commit text, candidate_immutable_origin text, candidate_deployment_target text) OWNER TO postgres;

--
-- Name: assert_exact_vercel_live_inventory_v2(jsonb, jsonb, text, text, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_exact_vercel_live_inventory_v2(retained_inventory jsonb, live_inventory jsonb, candidate_deployment_id text, candidate_deployment_commit text, candidate_immutable_origin text, candidate_deployment_target text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  normalized_retained jsonb;
  normalized_reviewed jsonb;
  normalized_live jsonb;
  expected_candidate jsonb;
  expected_candidate_record jsonb;
  live_count integer;
begin
  if candidate_deployment_target not in ('PREVIEW', 'PRODUCTION')
     or pg_catalog.jsonb_typeof(live_inventory) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_LIVE_ORIGIN_INVENTORY_INPUT_INVALID';
  end if;
  normalized_retained :=
    production_control.normalized_vercel_origin_inventory(retained_inventory);
  normalized_reviewed := production_control.normalized_vercel_origin_inventory(
    '[
      [
        "dpl_32Upq6iEQoD2MVdxcWWVihj66hEg",
        "41b0517e4e1679536438109ea61028663c80508f",
        "https://bagger-c1miwfnb1-sandbagger-invitational.vercel.app",
        "FEATURE_PREVIEW", "READY", "GIT"
      ],
      [
        "dpl_44fXUMdcS7QbQiJvMimX1DozcZrR",
        "fdda563eaab6569a6c8e0442ef8118fdc0db8569",
        "https://bagger-m3t3ao7ui-sandbagger-invitational.vercel.app",
        "FEATURE_PREVIEW", "READY", "GIT"
      ],
      [
        "dpl_ENU4XkC1dpbj9aho5gTz2x8zw9qP",
        "85eb5efce7f5c9d9292e007fc093c05d7dd5c356",
        "https://bagger-7zpm6cjp3-sandbagger-invitational.vercel.app",
        "FEATURE_PREVIEW", "READY", "GIT"
      ],
      [
        "dpl_6m9FqCvd8pe1epaxyYMmkRhK7Pc6",
        "3fcbaa287fcb306fa3b47310f01ed6eb3901749c",
        "https://bagger-phzmni50c-sandbagger-invitational.vercel.app",
        "FEATURE_PREVIEW", "READY", "GIT"
      ],
      [
        "dpl_Ux3JFpeS8MxMoKj19kL63tzQ9FjQ",
        "3fcbaa287fcb306fa3b47310f01ed6eb3901749c",
        "https://bagger-dc2m041un-sandbagger-invitational.vercel.app",
        "FEATURE_PREVIEW", "READY", "GIT"
      ]
    ]'::jsonb
  );
  normalized_live :=
    production_control.normalized_vercel_origin_inventory(live_inventory);
  expected_candidate := production_control.expected_vercel_live_inventory(
    '[]'::jsonb, candidate_deployment_id, candidate_deployment_commit,
    candidate_immutable_origin, candidate_deployment_target
  );
  expected_candidate_record := expected_candidate->0;
  live_count := pg_catalog.jsonb_array_length(normalized_live);

  if normalized_live is distinct from live_inventory
     or live_count < pg_catalog.jsonb_array_length(normalized_retained)
       + pg_catalog.jsonb_array_length(normalized_reviewed) + 1
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(
         normalized_retained || normalized_reviewed
       ) required(record)
       where required.record->>0 = candidate_deployment_id
          or required.record->>2 = pg_catalog.lower(pg_catalog.rtrim(
            candidate_immutable_origin, '/'
          ))
     )
     or (select pg_catalog.count(distinct value->>0)
       from pg_catalog.jsonb_array_elements(normalized_live) value) <>
       live_count
     or (select pg_catalog.count(distinct value->>2)
       from pg_catalog.jsonb_array_elements(normalized_live) value) <>
       live_count
     or exists (
       select value from pg_catalog.jsonb_array_elements(normalized_retained)
       except
       select value from pg_catalog.jsonb_array_elements(normalized_live)
     )
     or exists (
       select value from pg_catalog.jsonb_array_elements(normalized_reviewed)
       except
       select value from pg_catalog.jsonb_array_elements(normalized_live)
     )
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized_live) value
       where value = expected_candidate_record) <> 1
     or exists (
       select 1 from pg_catalog.jsonb_array_elements(normalized_live) value
       where (value->>0 = candidate_deployment_id
           or value->>2 = pg_catalog.lower(pg_catalog.rtrim(
             candidate_immutable_origin, '/'
           )))
         and value is distinct from expected_candidate_record
     )
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(normalized_live) live(record)
       join pg_catalog.jsonb_array_elements(normalized_reviewed) reviewed(record)
         on live.record->>0 = reviewed.record->>0
           or live.record->>2 = reviewed.record->>2
       where live.record is distinct from reviewed.record
     )
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(normalized_live) live(record)
       where pg_catalog.jsonb_typeof(live.record) is distinct from 'array'
         or pg_catalog.jsonb_array_length(live.record) <> 6
         or coalesce(live.record->>0, '') !~ '^dpl_[A-Za-z0-9]{8,64}$'
         or (live.record->1 <> 'null'::jsonb
           and coalesce(live.record->>1, '') !~ '^[0-9a-f]{40}$')
         or coalesce(live.record->>2, '') !~ '^https://[a-z0-9.-]+$'
         or live.record->>3 not in (
           'MAIN_PRODUCTION', 'FEATURE_PREVIEW',
           'CUTOVER_PRODUCTION_CANDIDATE'
         )
         or live.record->>4 not in ('READY', 'ERROR', 'BLOCKED')
         or live.record->>5 not in (
           'GIT', 'REDEPLOY_INHERITED_GIT',
           'VERCEL_API_RESOLVED_GIT',
           'VERCEL_CLI_SHA_UNAVAILABLE'
         )
         or (not exists (
           select 1
           from pg_catalog.jsonb_array_elements(normalized_retained)
             retained(record)
           where retained.record = live.record
         ) and not exists (
           select 1
           from pg_catalog.jsonb_array_elements(normalized_reviewed)
             reviewed(record)
           where reviewed.record = live.record
         ) and (
           live.record->1 = 'null'::jsonb
           or live.record->>1 <> pg_catalog.lower(candidate_deployment_commit)
           or (candidate_deployment_target = 'PREVIEW'
             and live.record->>3 <> 'FEATURE_PREVIEW')
           or (candidate_deployment_target = 'PRODUCTION'
             and live.record->>3 not in (
               'FEATURE_PREVIEW', 'CUTOVER_PRODUCTION_CANDIDATE'
             ))
           or live.record->>5 <> 'GIT'
         ))
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_LIVE_ORIGIN_INVENTORY_MISMATCH';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_exact_vercel_live_inventory_v2(retained_inventory jsonb, live_inventory jsonb, candidate_deployment_id text, candidate_deployment_commit text, candidate_immutable_origin text, candidate_deployment_target text) OWNER TO postgres;

--
-- Name: assert_exact_vercel_live_inventory_v3(jsonb, jsonb, text, text, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_exact_vercel_live_inventory_v3(retained_inventory jsonb, live_inventory jsonb, candidate_deployment_id text, candidate_deployment_commit text, candidate_immutable_origin text, candidate_deployment_target text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  normalized_live jsonb;
  reviewed_addition jsonb;
  reviewed_record jsonb;
  delegated_live jsonb;
begin
  normalized_live :=
    production_control.normalized_vercel_origin_inventory(live_inventory);
  reviewed_addition := production_control.normalized_vercel_origin_inventory(
    '[
      [
        "dpl_idZKEn956pcuEXctKS5HPoWfEn4Y",
        "b6f50d24d9a96c845305210b958ccf716bbf994d",
        "https://bagger-aggbtffot-sandbagger-invitational.vercel.app",
        "FEATURE_PREVIEW", "READY", "GIT"
      ]
    ]'::jsonb
  );
  reviewed_record := reviewed_addition->0;

  if normalized_live is distinct from live_inventory
     or candidate_deployment_id = reviewed_record->>0
     or pg_catalog.lower(pg_catalog.rtrim(candidate_immutable_origin, '/')) =
       reviewed_record->>2
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized_live) value
       where value = reviewed_record) <> 1
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(normalized_live) value
       where (value->>0 = reviewed_record->>0
           or value->>2 = reviewed_record->>2)
         and value is distinct from reviewed_record
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_LIVE_ORIGIN_INVENTORY_MISMATCH';
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      value order by (value->>0) collate "C",
        pg_catalog.lower(pg_catalog.rtrim(value->>2, '/'))
    ),
    '[]'::jsonb
  )
  into delegated_live
  from pg_catalog.jsonb_array_elements(normalized_live) value
  where value is distinct from reviewed_record;

  perform production_control.assert_exact_vercel_live_inventory_v2(
    retained_inventory,
    delegated_live,
    candidate_deployment_id,
    candidate_deployment_commit,
    candidate_immutable_origin,
    candidate_deployment_target
  );
end;
$$;


ALTER FUNCTION production_control.assert_exact_vercel_live_inventory_v3(retained_inventory jsonb, live_inventory jsonb, candidate_deployment_id text, candidate_deployment_commit text, candidate_immutable_origin text, candidate_deployment_target text) OWNER TO postgres;

--
-- Name: assert_exact_vercel_origin_inventory(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_exact_vercel_origin_inventory(input jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  normalized jsonb;
  record_count integer;
begin
  if pg_catalog.jsonb_typeof(input) is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_ORIGIN_INVENTORY_ARRAY_REQUIRED';
  end if;
  normalized := production_control.normalized_vercel_origin_inventory(input);
  record_count := pg_catalog.jsonb_array_length(normalized);
  if normalized is distinct from input
     or record_count <> 1292
     or (select pg_catalog.count(distinct value->>0)
       from pg_catalog.jsonb_array_elements(normalized) value) <> record_count
     or (select pg_catalog.count(distinct value->>2)
       from pg_catalog.jsonb_array_elements(normalized) value) <> record_count
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(normalized) value
       where pg_catalog.jsonb_typeof(value) is distinct from 'array'
         or pg_catalog.jsonb_array_length(value) <> 6
         or coalesce(value->>0, '') !~ '^dpl_[A-Za-z0-9]{8,64}$'
         or (value->1 <> 'null'::jsonb
           and coalesce(value->>1, '') !~ '^[0-9a-f]{40}$')
         or coalesce(value->>2, '') !~ '^https://[a-z0-9.-]+$'
         or value->>3 not in ('PRODUCTION_TARGET', 'PROJECT_PREVIEW')
         or value->>4 not in ('READY', 'ERROR', 'BLOCKED')
         or coalesce(value->>5, '') !~ '^[0-9a-f]{64}$'
     )
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized) value
       where value->>3 = 'PRODUCTION_TARGET') <> 458
     or (select pg_catalog.count(*)
       from pg_catalog.jsonb_array_elements(normalized) value
       where value->>3 = 'PROJECT_PREVIEW') <> 834
     or not (normalized @> pg_catalog.jsonb_build_array(
       '["dpl_5uQB4VBY3FEgWHTS5vZYU2J9rmM2","561a61946be3536c7e32b46be53e4683cbb45579","https://bagger-drmix94o0-sandbagger-invitational.vercel.app","PRODUCTION_TARGET","READY","0383e746abde16275626a8bcd41a38853eb9fe6e2cb036ef7658d21c23d9f5e8"]'::jsonb
     ))
     or not (normalized @> pg_catalog.jsonb_build_array(
