--
-- Name: assert_exact_worker_resource_scope(text, text, text, text, text, text, text, integer); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_exact_worker_resource_scope(requested_worker_name text, requested_project_ref text, requested_project_url text, requested_google_workbook_id text, requested_vercel_project text, requested_canonical_domain text, requested_tournament_id text, requested_tournament_year integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  scope_row production_control.resource_scope%rowtype;
begin
  select * into strict scope_row
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';

  if scope_row.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or scope_row.project_url <> 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or scope_row.google_workbook_id <> '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or scope_row.vercel_project <> 'bagger-inv'
     or scope_row.canonical_domain <> 'https://baggerinv.com'
     or scope_row.current_tournament_id <> '2026'
     or scope_row.current_tournament_year <> 2026 then
    raise exception using
      errcode = 'P0001',
      message = 'PRODUCTION_RESOURCE_SCOPE_INVALID';
  end if;

  if requested_project_ref is distinct from scope_row.project_ref
     or requested_project_url is distinct from scope_row.project_url
     or requested_google_workbook_id is distinct from scope_row.google_workbook_id
     or requested_vercel_project is distinct from scope_row.vercel_project
     or requested_canonical_domain is distinct from scope_row.canonical_domain
     or requested_tournament_id is distinct from scope_row.current_tournament_id
     or requested_tournament_year is distinct from scope_row.current_tournament_year then
    raise exception using
      errcode = 'P0001',
      message = 'PRODUCTION_RESOURCE_ASSERTION_FAILED';
  end if;

  if not exists (
    select 1
    from production_control.tournament_scopes t
    where t.tournament_id = requested_tournament_id
      and t.tournament_year = requested_tournament_year
      and t.source_workbook_id = requested_google_workbook_id
      and t.scope_kind = 'CURRENT_TOURNAMENT'
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'PRODUCTION_TOURNAMENT_SCOPE_INVALID';
  end if;

  if not exists (
    select 1
    from production_control.worker_contracts c
    join production_control.worker_controls w using (worker_name)
    where c.worker_name = requested_worker_name
      and c.scope_key = 'BAGGER_INV_PRODUCTION'
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'PRODUCTION_WORKER_CONTRACT_UNKNOWN';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_exact_worker_resource_scope(requested_worker_name text, requested_project_ref text, requested_project_url text, requested_google_workbook_id text, requested_vercel_project text, requested_canonical_domain text, requested_tournament_id text, requested_tournament_year integer) OWNER TO postgres;

--
-- Name: assert_frozen_2026_current_read_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_frozen_2026_current_read_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if pointer.tournament_id <> '2026' or pointer.tournament_year <> 2026 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CURRENT_READ_POINTER_NOT_2026';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_frozen_2026_current_read_v1() OWNER TO postgres;

--
-- Name: assert_frozen_2026_derived_worker_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_frozen_2026_derived_worker_v1(input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
begin
  -- This assertion acquires and retains the shared scoring-admission lock,
  -- proves the pointer is still 2026, and preserves every installed resource,
  -- deployment, epoch, capability, authority, and admission predicate.
  perform production_control.assert_production_scoring_runtime(input, null);
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if production_control.cutover_phase_rank(activation.read_cutover_phase)
       < production_control.cutover_phase_rank('WORKERS')
     or not resource.workers_enabled then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_DERIVED_WORKER_RUNTIME_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_frozen_2026_derived_worker_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_future_compatibility_worker_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_compatibility_worker_v1(input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
begin
  begin
    perform production_control.assert_production_service_role();
  exception when others then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_FUTURE_COMPATIBILITY_SERVICE_ROLE_REQUIRED';
  end;
  select value.* into strict scope
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if input->>'contract_version'
       is distinct from 'production-future-google-match-provisioning-v1'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'project_ref' is distinct from scope.project_ref
     or input->>'project_url' is distinct from scope.project_url
     or input->>'source_workbook_id' is distinct from scope.google_workbook_id
     or coalesce(input->>'target_tournament_id', '') !~ '^[0-9]{4}$'
     or input->>'target_tournament_id' = scope.current_tournament_id then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_FUTURE_COMPATIBILITY_SCOPE_REQUIRED';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_future_compatibility_worker_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_future_google_writer_live_implementation_v2(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_google_writer_live_implementation_v2(target_tournament_id text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target production_control.future_google_writer_targets_v2%rowtype;
  writer production_control.future_google_writer_generations_v2%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  target_id text := pg_catalog.btrim(target_tournament_id);
begin
  select target_value.* into strict target
  from production_control.future_google_writer_targets_v2 target_value
  where target_value.tournament_id = target_id
    and target_value.contract_status = 'CERTIFIED';
  select generation.* into strict writer
  from production_control.future_google_writer_generations_v2 generation
  where generation.writer_generation_id = target.writer_generation_id
    and generation.certification_status = 'CERTIFIED';
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target_id;
  select value.* into strict promotion
  from production_control.future_runtime_promotions_v2 value
  where value.tournament_id = target_id;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target_id;
  if writer.implementation_fingerprint is distinct from
       production_control.future_google_writer_implementation_fingerprint_v2()
     or target.certification_contract_version is distinct from
       'production-annual-google-writer-certification-v1'
     or target.destination_workbook_id is distinct from
       resource.source_workbook_id
     or target.resource_revision is distinct from resource.resource_revision
     or target.resource_binding_fingerprint is distinct from
       production_control.future_google_writer_resource_fingerprint_v1(
         target_id
       )
     or target.promotion_revision is distinct from
       promotion.promotion_revision
     or target.source_setup_revision is distinct from
       promotion.source_setup_revision
     or target.source_setup_revision is distinct from catalog.setup_revision
     or target.promoted_manifest_fingerprint is distinct from
       promotion.promoted_manifest_fingerprint
     or target.target_contract_fingerprint is distinct from
       production_control.future_google_writer_target_fingerprint_v1(
         target_id
       )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_CERTIFICATION_STALE';
  end if;
exception when no_data_found then
  raise exception using errcode = '55000',
    message = 'PRODUCTION_FUTURE_GOOGLE_WRITER_CONTRACT_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.assert_future_google_writer_live_implementation_v2(target_tournament_id text) OWNER TO postgres;

--
-- Name: assert_future_google_writer_pre_implementation_cert_v2(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_google_writer_pre_implementation_cert_v2(input jsonb, require_exact_contract boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  target production_control.future_google_writer_targets_v2%rowtype;
  writer production_control.future_google_writer_generations_v2%rowtype;
  target_id text := pg_catalog.btrim(coalesce(
    input->>'target_tournament_id', ''
  ));
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  -- Resolve the deployment/runtime binding only after holding the shared
  -- admission lock so a concurrent annual application rebind cannot validate
  -- the predecessor deployment and then race past its atomic replacement.
  perform production_control.assert_annual_scoring_platform_v1(
    input, 'WORKERS', null
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict target
  from production_control.future_google_writer_targets_v2 value
  where value.tournament_id = target_id
    and value.contract_status = 'CERTIFIED';
  select value.* into strict writer
  from production_control.future_google_writer_generations_v2 value
  where value.writer_generation_id = target.writer_generation_id
    and value.certification_status = 'CERTIFIED';
  if target_id = '' or target_id = '2026'
     or pointer.tournament_id = target_id
     or target.destination_workbook_id
       is distinct from writer.destination_workbook_id
     or not exists (
       select 1 from production_control.future_runtime_promotions_v2 value
       where value.tournament_id = target_id
         and value.runtime_status in ('PROMOTED', 'READY')
     ) or (require_exact_contract and (
       input->>'contract_version' is distinct from writer.contract_version
       or input->>'expected_writer_generation_id'
         is distinct from writer.writer_generation_id::text
       or input->>'destination_workbook_id'
         is distinct from writer.destination_workbook_id
       or input->>'expected_target_contract_fingerprint'
         is distinct from target.target_contract_fingerprint
     )) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_WRITER_CONTRACT_REQUIRED';
  end if;
  return target_id;
exception
  when invalid_text_representation or no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_WRITER_CONTRACT_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.assert_future_google_writer_pre_implementation_cert_v2(input jsonb, require_exact_contract boolean) OWNER TO postgres;

--
-- Name: assert_future_google_writer_v2(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_google_writer_v2(input jsonb, require_exact_contract boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
begin
  target_id := production_control
    .assert_future_google_writer_pre_implementation_cert_v2(
      input, require_exact_contract
    );
  perform production_control
    .assert_future_google_writer_live_implementation_v2(target_id);
  return target_id;
exception when no_data_found then
  raise exception using errcode = '55000',
    message = 'PRODUCTION_FUTURE_GOOGLE_WRITER_CONTRACT_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.assert_future_google_writer_v2(input jsonb, require_exact_contract boolean) OWNER TO postgres;

--
-- Name: assert_future_participant_identity_runtime_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_participant_identity_runtime_v1() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  context participant_identity.future_tournament_identity_contexts_v1%rowtype;
  roster_count_value integer;
  binding_count_value integer;
  enrolled_count_value integer;
begin
  perform production_control.assert_production_service_role();
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  select value.* into strict context
  from participant_identity.future_tournament_identity_contexts_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.status = 'CERTIFIED';
  select pg_catalog.count(*)::integer into roster_count_value
  from scoring_authority.tournament_players membership
  where membership.tournament_id = pointer.tournament_id
    and membership.participation_status = 'ACTIVE';
  select pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter (
      where binding.enrollment_state = 'ENROLLED'
    )::integer
  into binding_count_value, enrolled_count_value
  from participant_identity.future_tournament_participant_bindings_v1 binding
  where binding.tournament_id = pointer.tournament_id;
  if pointer.tournament_year <= 2026
     or catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision
     or generation.pointer_revision <> pointer.pointer_revision
     or generation.authority <> 'SUPABASE'
     or generation.ingress_state <> 'OPEN'
     or context.runtime_generation_id <> generation.runtime_generation_id
     or context.authority_generation_id
       <> generation.authority_generation_id
     or context.admission_generation_id
       <> generation.admission_generation_id
     or context.pointer_revision <> generation.pointer_revision
     or context.roster_count <> roster_count_value
     or binding_count_value <> roster_count_value
     or context.enrolled_count <> enrolled_count_value
     or context.not_enrolled_count <>
       roster_count_value - enrolled_count_value
     or context.binding_fingerprint is distinct from
       production_control
         .future_participant_identity_binding_fingerprint_v1(
           pointer.tournament_id
         )
     or exists (
       select 1
       from participant_identity.future_tournament_participant_bindings_v1
         binding
       left join production_control
         .future_participant_identity_eligibility_v1(
           pointer.tournament_id
         ) eligibility
         on eligibility.player_id = binding.player_id
       where binding.tournament_id = pointer.tournament_id
         and (eligibility.player_id is null
           or (binding.enrollment_state = 'ENROLLED'
             and not eligibility.runtime_eligible)
           or (binding.contact_state = 'APPROVED'
             and not eligibility.contact_approved))
     )
     or not exists (
       select 1
       from production_control.future_global_owner_eligibility_v1()
     ) then
    raise exception using errcode = '55000',
      message = 'FUTURE_PARTICIPANT_IDENTITY_RUNTIME_REQUIRED';
  end if;
  return pointer.tournament_id;
end;
$$;


ALTER FUNCTION production_control.assert_future_participant_identity_runtime_v1() OWNER TO postgres;

--
-- Name: assert_future_production_match_scoring_ready_v1(text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_production_match_scoring_ready_v1(target_match_id text, target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  reasons jsonb := '[]'::jsonb;
  match_value scoring_authority.matches%rowtype;
  round_value scoring_authority.rounds%rowtype;
  detail_value scoring_authority.tournament_setup_match_details_v1%rowtype;
  binding production_control.future_runtime_match_bindings_v2%rowtype;
  assignment scoring_authority.tournament_setup_round_courses_v1%rowtype;
  course_value scoring_authority.tournament_setup_course_tees_v1%rowtype;
  snapshot_value scoring_authority.scoring_snapshots%rowtype;
  current_handicap uuid;
  expected_count integer;
  participant_count integer;
  holes_value jsonb;
  match_holes_value jsonb;
  context_value jsonb;
  current_participant_values jsonb;
begin
  select value.* into match_value from scoring_authority.matches value
  where value.match_id = target_match_id
    and value.tournament_id = target_tournament;
  if match_value.match_id is null then
    return pg_catalog.jsonb_build_object(
      'ready', false,
      'contractVersion', 'production-match-scoring-readiness-v1',
      'matchId', target_match_id,
      'reasons', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'code', 'MATCH_NOT_FOUND',
        'message', 'The canonical Production match does not exist.'
      ))
    );
  end if;
  select value.* into round_value from scoring_authority.rounds value
  where value.tournament_id = target_tournament
    and value.round_number = match_value.round_number;
  select value.* into detail_value
  from scoring_authority.tournament_setup_match_details_v1 value
  where value.tournament_id = target_tournament
    and value.match_id = target_match_id;
  select value.* into binding
  from production_control.future_runtime_match_bindings_v2 value
  where value.tournament_id = target_tournament
    and value.match_id = target_match_id;
  select value.* into snapshot_value
  from scoring_authority.scoring_snapshots value
  where value.snapshot_id = match_value.scoring_snapshot_id
    and value.tournament_id = target_tournament
    and value.match_id = target_match_id;
  if round_value.tournament_id is null
     or round_value.format not in ('BB', 'SC', 'SI')
     or round_value.format is distinct from match_value.format then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_CONFIGURATION_INVALID',
        'message', 'The match does not match its canonical round configuration.'
      )
    );
  end if;
  if detail_value.match_id is null
     or binding.match_id is null
     or binding.runtime_state <> 'PREPARED'
     or detail_value.prepared_setup_revision is distinct from detail_value.setup_revision
     or detail_value.prepared_configuration_fingerprint is null
     or detail_value.prepared_configuration_fingerprint
       is distinct from binding.configuration_fingerprint then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SETUP_SNAPSHOT_STALE',
        'message', 'The match setup changed after its scoring snapshot was prepared.'
      )
    );
  end if;
  if snapshot_value.snapshot_id is null
     or snapshot_value.snapshot_revision is distinct from (
       select pg_catalog.max(candidate.snapshot_revision)
       from scoring_authority.scoring_snapshots candidate
       where candidate.match_id = target_match_id
         and candidate.tournament_id = target_tournament
     ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_SNAPSHOT_NOT_CURRENT',
        'message', 'The match needs its latest scoring snapshot prepared.'
      )
    );
  end if;
  select value.* into assignment
  from scoring_authority.tournament_setup_round_courses_v1 value
  where value.tournament_id = target_tournament
    and value.round_number = match_value.round_number;
  select value.* into course_value
  from scoring_authority.tournament_setup_course_tees_v1 value
  where value.tournament_id = target_tournament
    and value.course_id = detail_value.course_id
    and value.tee_id = detail_value.tee_id;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'hole_number', hole.hole_number, 'par', hole.par,
    'stroke_index', hole.stroke_index, 'yardage', hole.yardage
  ) order by hole.hole_number) into holes_value
  from scoring_authority.tournament_setup_course_holes_v1 hole
  where hole.tournament_id = target_tournament
    and hole.course_id = detail_value.course_id
    and hole.tee_id = detail_value.tee_id;
  if assignment.tournament_id is null
     or assignment.course_id is distinct from detail_value.course_id
     or assignment.tee_id is distinct from detail_value.tee_id
     or course_value.tournament_id is null
     or course_value.rating is null
     or course_value.slope not between 55 and 155
     or course_value.par not between 54 and 90
     or pg_catalog.jsonb_typeof(holes_value) is distinct from 'array'
     or pg_catalog.jsonb_array_length(coalesce(holes_value, '[]'::jsonb)) <> 18
     or (select pg_catalog.count(distinct (hole->>'hole_number')::integer)
       from pg_catalog.jsonb_array_elements(coalesce(holes_value, '[]'::jsonb)) hole) <> 18
     or (select pg_catalog.count(distinct (hole->>'stroke_index')::integer)
       from pg_catalog.jsonb_array_elements(coalesce(holes_value, '[]'::jsonb)) hole) <> 18
     or (select pg_catalog.sum((hole->>'par')::integer)
       from pg_catalog.jsonb_array_elements(coalesce(holes_value, '[]'::jsonb)) hole)
       is distinct from course_value.par then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'COURSE_HOLES_INCOMPLETE',
        'message', 'The course requires 18 complete, valid hole definitions.'
      )
    );
  end if;
  if snapshot_value.snapshot_id is not null and (
       snapshot_value.format is distinct from match_value.format
       or snapshot_value.handicap_allowance is distinct from round_value.handicap_allowance
       or snapshot_value.course_id is distinct from course_value.course_id
       or snapshot_value.tee is distinct from course_value.tee_id
       or snapshot_value.rating is distinct from course_value.rating
       or snapshot_value.slope is distinct from course_value.slope
       or snapshot_value.par is distinct from course_value.par
       or snapshot_value.hole_definitions is distinct from holes_value
     ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_SNAPSHOT_CONFIGURATION_STALE',
        'message', 'The scoring snapshot no longer matches the current setup facts.'
      )
    );
  end if;
  expected_count := case when match_value.format = 'SI' then 2 else 4 end;
  select pg_catalog.count(*)::integer into participant_count
  from scoring_authority.match_participants participant
  where participant.match_id = target_match_id;
  if participant_count <> expected_count
     or (select pg_catalog.count(distinct participant.player_id)
       from scoring_authority.match_participants participant
       where participant.match_id = target_match_id) <> expected_count
     or (select pg_catalog.count(*) from scoring_authority.match_participants participant
       where participant.match_id = target_match_id and participant.team_side = 1)
       <> expected_count / 2
     or (select pg_catalog.count(*) from scoring_authority.match_participants participant
       where participant.match_id = target_match_id and participant.team_side = 2)
       <> expected_count / 2 then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PAIRINGS_INCOMPLETE',
        'message', 'The match requires complete, unique Player pairings.'
      )
    );
  end if;
  if exists (
    select 1 from scoring_authority.match_participants participant
    left join scoring_authority.tournament_players membership
      on membership.tournament_id = target_tournament
     and membership.player_id = participant.player_id
    left join scoring_authority.teams team
      on team.tournament_id = membership.tournament_id
     and team.team_id = membership.team_id
     and team.team_side = membership.team_side
    where participant.match_id = target_match_id
      and (membership.player_id is null
        or membership.participation_status <> 'ACTIVE'
        or membership.team_side <> participant.team_side
        or team.team_id is null)
  ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PAIRING_TEAM_MEMBERSHIP_INVALID',
        'message', 'A paired Player does not have the required active team membership.'
      )
    );
  end if;
  if exists (
    select 1 from scoring_authority.match_participants participant
    join scoring_authority.matches other_match
      on other_match.match_id = participant.match_id
     and other_match.tournament_id = target_tournament
     and other_match.round_number = match_value.round_number
    where participant.player_id in (
      select current_participant.player_id
      from scoring_authority.match_participants current_participant
      where current_participant.match_id = target_match_id
    )
    group by participant.player_id having pg_catalog.count(*) > 1
  ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_DUPLICATE_PLAYER',
        'message', 'A paired Player appears more than once in this round.'
      )
    );
  end if;
  select value.revision_id into current_handicap
  from scoring_authority.handicap_revision_current value
  where value.tournament_id = target_tournament;
  if current_handicap is null
     or snapshot_value.handicap_revision_id is distinct from current_handicap
     or exists (
       select 1 from scoring_authority.match_participants participant
       left join scoring_authority.handicap_revision_entries entry
         on entry.revision_id = current_handicap
        and entry.tournament_id = target_tournament
        and entry.player_id = participant.player_id
       where participant.match_id = target_match_id
         and (entry.player_id is null
           or participant.handicap_revision_id is distinct from current_handicap)
     ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'HANDICAP_CONTEXT_NOT_CURRENT',
        'message', 'Every paired Player needs the current approved handicap context.'
      )
    );
  end if;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'hole_number', hole.hole_number, 'par', hole.par,
    'stroke_index', hole.stroke_index, 'yardage', hole.yardage
  ) order by hole.hole_number) into match_holes_value
  from scoring_authority.match_holes hole
  where hole.match_id = target_match_id
    and hole.snapshot_id = snapshot_value.snapshot_id;
  if match_holes_value is distinct from holes_value then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_HOLES_NOT_CURRENT',
        'message', 'The match hole scoring context is not current.'
      )
    );
  end if;
  if (select pg_catalog.count(*) from scoring_authority.scoring_permissions permission
      where permission.match_id = target_match_id) <> participant_count
     or exists (
       select 1 from scoring_authority.match_participants participant
       left join scoring_authority.scoring_permissions permission
         on permission.match_id = participant.match_id
        and permission.player_id = participant.player_id
       where participant.match_id = target_match_id
         and (permission.player_id is null
           or permission.permission_revision <> match_value.permission_revision)
     )
     or exists (
       select 1 from scoring_authority.scoring_permissions permission
       left join scoring_authority.match_participants participant
         on participant.match_id = permission.match_id
        and participant.player_id = permission.player_id
       where permission.match_id = target_match_id
         and participant.player_id is null
     ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_PERMISSION_COVERAGE_INVALID',
        'message', 'Scoring access records do not match the current pairings.'
      )
    );
  end if;
  if match_value.scored_holes <> 0 or match_value.current_hole <> 0
     or match_value.holes_remaining <> 18
     or match_value.team_1_holes_won <> 0 or match_value.team_2_holes_won <> 0
     or match_value.running_result <> 'Scheduled'
     or match_value.result_winner <> '' or match_value.clinched
     or match_value.scorecard_complete or match_value.finalized_at is not null
     or match_value.unresolved_mutations <> 0
     or exists (select 1 from scoring_authority.hole_scores score
       where score.match_id = target_match_id)
     or exists (select 1 from scoring_authority.score_mutations mutation
       where mutation.match_id = target_match_id)
     or exists (select 1 from scoring_authority.finalized_scorecard_snapshots final_value
       where final_value.match_id = target_match_id)
     or exists (select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = target_tournament
         and lease.match_id = target_match_id
         and lease.expires_at > pg_catalog.clock_timestamp()) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'MATCH_ALREADY_HAS_SCORING_ACTIVITY',
        'message', 'The match already has scoring activity and cannot be started from setup.'
      )
    );
  end if;
  if pg_catalog.jsonb_array_length(reasons) = 0 then
    begin
      context_value := production_control.future_handicap_match_context_v2(
        target_match_id, current_handicap
      );
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'player_id', participant.player_id,
        'team_side', participant.team_side,
        'player_slot', participant.player_slot,
        'tournament_handicap', participant.tournament_handicap,
        'handicap_index', participant.handicap_index,
        'course_handicap', participant.course_handicap,
        'playing_handicap', participant.playing_handicap,
        'final_strokes', participant.final_strokes
      ) order by participant.team_side, participant.player_slot)
      into current_participant_values
      from scoring_authority.match_participants participant
      where participant.match_id = target_match_id;
      if current_participant_values is distinct from
           context_value->'participants' then
        reasons := reasons || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'SCORING_PARTICIPANT_HANDICAPS_STALE',
            'message', 'The paired Player handicap values must be refreshed.'
          )
        );
      end if;
      if snapshot_value.participant_configuration is distinct from
           context_value->'participant_configuration'
         or snapshot_value.team_configuration is distinct from
           context_value->'team_configuration' then
        reasons := reasons || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'SCORING_HANDICAP_PROJECTION_STALE',
            'message', 'The scoring handicap projection must be refreshed.'
          )
        );
      end if;
    exception when others then
      reasons := reasons || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'SCORING_HANDICAP_PROJECTION_INCOMPLETE',
          'message', 'The scoring handicap projection is incomplete.'
        )
      );
    end;
  end if;
  return pg_catalog.jsonb_build_object(
    'ready', pg_catalog.jsonb_array_length(reasons) = 0,
    'contractVersion', 'production-match-scoring-readiness-v1',
    'matchId', target_match_id, 'source', 'TOURNAMENT_SETUP_V1',
    'reasons', reasons
  );
exception when others then
  return pg_catalog.jsonb_build_object(
    'ready', false,
    'contractVersion', 'production-match-scoring-readiness-v1',
    'matchId', target_match_id,
    'reasons', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'code', 'SCORING_READINESS_UNAVAILABLE',
      'message', 'Scoring readiness could not be verified safely.'
    ))
  );
end;
$$;


ALTER FUNCTION production_control.assert_future_production_match_scoring_ready_v1(target_match_id text, target_tournament text) OWNER TO postgres;

--
-- Name: assert_future_production_scoring_actor_v1(jsonb, text, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_production_scoring_actor_v1(input jsonb, target_tournament text, require_director boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  actor text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_role text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,role}', 'PLAYER'
  )));
  actor_auth_user uuid;
  current_identity_target text;
begin
  begin
    actor_auth_user := nullif(
      input#>>'{authorization,auth_user_id}', ''
    )::uuid;
  exception when others then
    actor_auth_user := null;
  end;
  current_identity_target := production_control
    .assert_future_participant_identity_runtime_v1();
  if target_tournament <> current_identity_target
     or input#>>'{authorization,tournament_id}'
       is distinct from target_tournament
     or actor = '' or actor_auth_user is null
     or actor_role not in ('PLAYER', 'DIRECTOR')
     or (require_director and actor_role <> 'DIRECTOR')
     or not exists (
       select 1
       from production_control.future_participant_identity_eligibility_v1(
         target_tournament
       ) eligibility
       where eligibility.player_id = actor
         and eligibility.auth_user_id = actor_auth_user
         and eligibility.runtime_eligible
     )
     or (actor_role = 'DIRECTOR' and (
       not exists (
         select 1
         from participant_identity.tournament_roles role_value
         where role_value.tournament_id = target_tournament
           and role_value.auth_user_id = actor_auth_user
           and role_value.role = 'DIRECTOR'
           and role_value.role_active
           and role_value.revoked_at is null
       )
       or not exists (
         select 1
         from production_control.director_entitlements entitlement
         where entitlement.tournament_id = target_tournament
           and entitlement.auth_user_id = actor_auth_user
           and entitlement.player_id = actor
           and entitlement.role in ('DIRECTOR', 'OWNER')
           and entitlement.status = 'ACTIVE'
           and entitlement.revoked_at is null
       )
     )) then
    raise exception using errcode = '42501', message = case
      when require_director or actor_role = 'DIRECTOR'
        then 'PRODUCTION_DIRECTOR_AUTHORIZATION_REQUIRED'
      else 'PRODUCTION_SCORING_AUTHORIZATION_REQUIRED'
    end;
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_future_production_scoring_actor_v1(input jsonb, target_tournament text, require_director boolean) OWNER TO postgres;

--
-- Name: assert_future_production_scoring_runtime_v1(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_production_scoring_runtime_v1(input jsonb, required_worker text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  return production_control.assert_annual_scoring_runtime_v1(
    input, input->>'annual_scoring_operation', required_worker
  );
end;
$$;


ALTER FUNCTION production_control.assert_future_production_scoring_runtime_v1(input jsonb, required_worker text) OWNER TO postgres;

--
-- Name: assert_future_runtime_service_scope_v2(jsonb, boolean, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_runtime_service_scope_v2(input jsonb, require_director boolean DEFAULT true, require_owner boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if pg_catalog.upper(pg_catalog.btrim(coalesce(input->>'action', '')))
       in ('ACTIVATE_TOURNAMENT', 'CLOSE_TOURNAMENT') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SCORING_TRANSITION_REQUIRED';
  end if;
  perform production_control
    .assert_future_runtime_service_scope_v2_pre_annual_scoring_fence(
      input, require_director, require_owner
    );
end;
$$;


ALTER FUNCTION production_control.assert_future_runtime_service_scope_v2(input jsonb, require_director boolean, require_owner boolean) OWNER TO postgres;

--
-- Name: assert_future_runtime_service_scope_v2_pre_annual_scoring_fence(jsonb, boolean, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_runtime_service_scope_v2_pre_annual_scoring_fence(input jsonb, require_director boolean DEFAULT true, require_owner boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform production_control.assert_annual_future_admin_scope_v1(
    input, 'production-future-runtime-activation-v2',
    require_director, require_owner
  );
end;
$$;


ALTER FUNCTION production_control.assert_future_runtime_service_scope_v2_pre_annual_scoring_fence(input jsonb, require_director boolean, require_owner boolean) OWNER TO postgres;

--
-- Name: assert_future_scoring_runtime_capability_pre_side_games_v1(text, uuid, uuid, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_scoring_runtime_capability_pre_side_games_v1(target_tournament_id text, expected_runtime_generation_id uuid, expected_authority_generation_id uuid, expected_admission_generation_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  generation production_control.future_annual_runtime_generations_v1%rowtype;
begin
  select value.* into generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target_tournament_id
    and value.runtime_generation_id = expected_runtime_generation_id;
  if generation.runtime_generation_id is null
     or generation.generation_status <> 'PREPARED'
     or generation.authority_generation_id <> expected_authority_generation_id
     or generation.admission_generation_id <> expected_admission_generation_id
     or expected_authority_generation_id = expected_admission_generation_id
     or expected_runtime_generation_id in (
       expected_authority_generation_id, expected_admission_generation_id
     )
     or generation.authority <> 'SUPABASE'
     or generation.ingress_state <> 'OPEN'
     or not exists (
       select 1 from scoring_authority.tournaments tournament_value
       where tournament_value.tournament_id = target_tournament_id
         and tournament_value.scoring_authority = 'SUPABASE'
     )
     or exists (
       select 1 from scoring_authority.matches match_value
       where match_value.tournament_id = target_tournament_id
         and (match_value.status <> 'UPCOMING'
           or match_value.match_revision <> 0
           or match_value.scored_holes <> 0
           or match_value.scorecard_complete
           or match_value.finalized_at is not null)
     )
     or exists (
       select 1 from scoring_authority.scoring_permissions permission
       join scoring_authority.matches match_value
         on match_value.match_id = permission.match_id
       where match_value.tournament_id = target_tournament_id
         and permission.can_score
     )
     or exists (
       select 1 from scoring_authority.hole_scores score
       join scoring_authority.matches match_value
         on match_value.match_id = score.match_id
       where match_value.tournament_id = target_tournament_id
     ) then
    raise exception using errcode = '55000',
      message = 'FUTURE_SCORING_RUNTIME_CAPABILITY_INVALID';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_future_scoring_runtime_capability_pre_side_games_v1(target_tournament_id text, expected_runtime_generation_id uuid, expected_authority_generation_id uuid, expected_admission_generation_id uuid) OWNER TO postgres;

--
-- Name: assert_future_scoring_runtime_capability_v1(text, uuid, uuid, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_future_scoring_runtime_capability_v1(target_tournament_id text, expected_runtime_generation_id uuid, expected_authority_generation_id uuid, expected_admission_generation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform production_control
    .assert_future_scoring_runtime_capability_pre_side_games_v1(
      target_tournament_id, expected_runtime_generation_id,
      expected_authority_generation_id, expected_admission_generation_id
    );
  -- PREPARE, DRAIN, and ACTIVATE all reach this assertion while the annual
  -- transition holds the exclusive scoring-admission lock. Recompute the live
  -- SQL/ACL/trigger manifest here so a post-certification writer drift cannot
  -- survive until pointer commit.
  -- Google runtime retired: external delivery is not canonical authority.
  perform production_control.ensure_annual_side_game_runtime_v1(
    target_tournament_id, expected_runtime_generation_id,
    expected_authority_generation_id, expected_admission_generation_id,
    true
  );
end;
$$;


ALTER FUNCTION production_control.assert_future_scoring_runtime_capability_v1(target_tournament_id text, expected_runtime_generation_id uuid, expected_authority_generation_id uuid, expected_admission_generation_id uuid) OWNER TO postgres;

