--
-- Name: assert_handicap_source_runtime_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_handicap_source_runtime_v1(input jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if input->>'contract_version' is distinct from 'production-handicap-source-v1'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'tournament_id' is distinct from '2026'
     or input#>>'{authorization,tournament_id}' is distinct from '2026'
     or input#>>'{authorization,role}' is distinct from 'DIRECTOR'
     or pg_catalog.upper(pg_catalog.btrim(coalesce(input->>'actor_player_id', '')))
       is distinct from pg_catalog.upper(pg_catalog.btrim(coalesce(input#>>'{authorization,player_id}', '')))
     or pg_catalog.lower(pg_catalog.btrim(coalesce(input->>'actor_auth_user_id', '')))
       is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(input#>>'{authorization,auth_user_id}', ''))) then
    raise exception using errcode = '42501', message = 'PRODUCTION_HANDICAP_SOURCE_SCOPE_REQUIRED';
  end if;
  select value.* into strict scope from production_control.resource_scope value where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict pointer from production_control.current_tournament_pointer_v1 value where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if input->>'project_ref' is distinct from scope.project_ref
     or input->>'project_url' is distinct from scope.project_url
     or input->>'source_workbook_id' is distinct from scope.google_workbook_id
     or scope.current_tournament_id <> '2026' or scope.current_tournament_year <> 2026
     or pointer.tournament_id <> '2026' or pointer.tournament_year <> 2026 then
    raise exception using errcode = '42501', message = 'PRODUCTION_HANDICAP_SOURCE_EXACT_RESOURCE_REQUIRED';
  end if;
  perform production_control.assert_production_scoring_actor(input, true);
  return '2026';
end;
$$;


ALTER FUNCTION production_control.assert_handicap_source_runtime_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_initial_owner_adoption_resource_scope_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_initial_owner_adoption_resource_scope_v1(input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  database_owner text;
  claim_role text;
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
begin
  select pg_catalog.pg_get_userbyid(database_value.datdba)
    into strict database_owner
  from pg_catalog.pg_database database_value
  where database_value.datname = pg_catalog.current_database();
  claim_role := coalesce(
    nullif(pg_catalog.current_setting('request.jwt.claim.role', true), ''),
    nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb
      ->>'role'
  );
  if not pg_catalog.pg_has_role(
       session_user, database_owner, 'member'
     )
     or claim_role is not null then
    raise exception using errcode = '42501',
      message = 'ACCESS_GOVERNANCE_DATABASE_OWNER_SESSION_REQUIRED';
  end if;

  if input->>'contract_version' is distinct from
       'production-access-governance-v1'
     or input->>'action' is distinct from 'INITIAL_OWNER_ADOPTION' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ACCESS_GOVERNANCE_SCOPE_REQUIRED';
  end if;

  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';

  if resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.project_url <>
       'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or resource.google_workbook_id <>
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.vercel_project <> 'bagger-inv'
     or resource.canonical_domain <> 'https://baggerinv.com'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_year <> 2026
     or not exists (
       select 1
       from scoring_authority.tournaments tournament
       where tournament.tournament_id = '2026'
         and tournament.tournament_year = 2026
     ) then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_RESOURCE_SCOPE_INVALID';
  end if;

  if pg_catalog.upper(coalesce(input->>'environment', '')) <> 'PRODUCTION'
     or input->>'project_ref' is distinct from resource.project_ref
     or input->>'project_url' is distinct from resource.project_url
     or input->>'source_workbook_id'
       is distinct from resource.google_workbook_id
     or input->>'tournament_id'
       is distinct from resource.current_tournament_id then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_RESOURCE_ASSERTION_FAILED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_initial_owner_adoption_resource_scope_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_isolated_director_operation_context_v1(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_isolated_director_operation_context_v1(input jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare binding production_control.isolated_director_context_v1%rowtype;
  gate scoring_authority.ingress_gates%rowtype; current_target text; token text; actor text; actor_auth uuid; request_id uuid;
begin
  perform production_control.assert_production_service_role();
  -- Annual transitions take this existing fence exclusively before locking
  -- the pointer/gate. Match that order before any isolated context row lock.
  perform pg_advisory_xact_lock_shared(production_control.scoring_admission_lock_key());
  if input->>'contract_version' is distinct from 'isolated-director-operations-v1'
    or jsonb_typeof(input->'resource') is distinct from 'object'
    or input#>>'{authorization,tournament_id}' is distinct from '2026'
    or input#>>'{authorization,role}' is distinct from 'DIRECTOR' then
    raise exception using errcode='42501',message='ISOLATED_DIRECTOR_CONTEXT_REQUIRED';
  end if;
  select * into strict binding from production_control.isolated_director_context_v1
    where scope_key='ISOLATED_DIRECTOR_V1' for share;
  if not binding.enabled or binding.database_name is distinct from current_database()
    or input#>>'{resource,binding_id}' is distinct from binding.binding_id::text
    or input#>>'{resource,project_ref}' is distinct from binding.project_ref
    or input#>>'{resource,project_url}' is distinct from binding.project_url
    or binding.admission_state<>'OPEN' then
    raise exception using errcode='42501',message='ISOLATED_DIRECTOR_CONTEXT_REQUIRED';
  end if;
  -- Never admit this profile to a canonical database without the established
  -- current golf/identity authority and safe ingress state.
  select tournament_id into strict current_target from production_control.current_tournament_pointer_v1
    where scope_key='BAGGER_INV_PRODUCTION' for share;
  select * into strict gate from scoring_authority.ingress_gates
    where tournament_id=binding.tournament_id for share;
  if gate.authority<>'SUPABASE' or gate.state<>'OPEN'
    or gate.active_epoch_id is distinct from binding.authority_epoch_id
    or gate.unresolved_client_queues<>0
    or current_target is distinct from '2026'
    or not exists(select 1 from scoring_authority.tournaments where tournament_id=binding.tournament_id
      and tournament_year=2026 and scoring_authority='SUPABASE') then
    raise exception using errcode='55000',message='ISOLATED_DIRECTOR_RUNTIME_NOT_SAFE';
  end if;
  -- This existing verifier checks confirmed Auth/link/verified identifier,
  -- ACTIVE membership/role and the canonical Director entitlement. It has no
  -- hosted-resource assertion and is not replaced or weakened here.
  perform production_control.assert_production_scoring_actor(input,true);
  actor:=input#>>'{authorization,player_id}';
  actor_auth:=(input#>>'{authorization,auth_user_id}')::uuid;
  token:=production_control.tournament_setup_hash_v1(to_jsonb(binding)-'created_at');
  if (mutation or input ? 'expected_context_token')
    and input->>'expected_context_token' is distinct from token then
    raise exception using errcode='40001',message='ISOLATED_DIRECTOR_CONTEXT_STALE';
  end if;
  if mutation or input->>'mode'='status' then
    request_id:=(input->>'operation_request_id')::uuid;
    if request_id is null then raise exception using errcode='22023',message='ISOLATED_DIRECTOR_OPERATION_ID_REQUIRED'; end if;
  end if;
  return jsonb_build_object('binding_id',binding.binding_id,'context_token',token,
    'tournament_id',binding.tournament_id,'governance_tournament_id',binding.governance_tournament_id,
    'activation_revision',binding.activation_revision,'admission_revision',binding.admission_revision,
    'authority_epoch_id',binding.authority_epoch_id,'release_commit',binding.release_commit,
    'resource_fingerprint',production_control.tournament_setup_hash_v1(jsonb_build_object(
      'environment','ISOLATED','binding_id',binding.binding_id,'project_ref',binding.project_ref,
      'project_url',binding.project_url,'database_name',binding.database_name,'tournament_id',binding.tournament_id,
      'activation_revision',binding.activation_revision,'admission_revision',binding.admission_revision,
      'authority_epoch_id',binding.authority_epoch_id,'release_commit',binding.release_commit)),
    'actor_auth_user_id',actor_auth,'actor_player_id',actor,
    'authorization',input->'authorization','operation_request_id',request_id);
exception when no_data_found then
  raise exception using errcode='42501',message='ISOLATED_DIRECTOR_CONTEXT_REQUIRED';
when invalid_text_representation or numeric_value_out_of_range then
  raise exception using errcode='22023',message='ISOLATED_DIRECTOR_INPUT_INVALID';
end;
$$;


ALTER FUNCTION production_control.assert_isolated_director_operation_context_v1(input jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: assert_legacy_provider_origin_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_legacy_provider_origin_v1() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if not exists (
    select 1
    from production_control.resource_scope resource
    join production_control.cutover_activation_state activation using (scope_key)
    join production_control.current_tournament_pointer_v1 pointer using (scope_key)
    join scoring_authority.ingress_gates gate
      on gate.tournament_id = '2026'
    join scoring_authority.authority_epochs epoch
      on epoch.epoch_id = activation.authority_generation_id
    join production_control.scoring_admission_closures closure
      on closure.closure_id = epoch.admission_closure_id
    join production_control.scoring_external_fence_evidence evidence
      on evidence.evidence_id = epoch.external_fence_evidence_id
    where resource.scope_key = 'BAGGER_INV_PRODUCTION'
      and resource.project_ref = 'ymqhhtxaywtqllynrmxe'
      and resource.project_url = 'https://ymqhhtxaywtqllynrmxe.supabase.co'
      and resource.google_workbook_id = '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
      and resource.vercel_project = 'bagger-inv'
      and resource.canonical_domain = 'https://baggerinv.com'
      and resource.current_tournament_id = '2026'
      and resource.current_tournament_year = 2026
      and resource.scoring_authority = 'SUPABASE'
      and resource.scoring_ingress_enabled
      and pointer.tournament_id = '2026'
      and activation.boundary_mode = 'PROVIDER_FENCE_V2'
      and activation.state = 'SCORING_COMMITTED'
      and activation.current_authority = 'SUPABASE'
      and activation.scoring_ingress_enabled
      and activation.active_transition_epoch_id is null
      and gate.boundary_mode = 'PROVIDER_FENCE_V2'
      and gate.authority = 'SUPABASE'
      and gate.admission_state = 'CLOSED'
      and gate.admission_protocol_enforced
      and gate.active_epoch_id = epoch.epoch_id
      and epoch.boundary_mode = 'PROVIDER_FENCE_V2'
      and epoch.status = 'COMMITTED'
      and epoch.epoch_type = 'CUTOVER'
      and epoch.authority_before = 'GOOGLE'
      and epoch.authority_after = 'SUPABASE'
      and epoch.tournament_id = '2026'
      and epoch.deployment_commit = activation.expected_deployment_commit
      and closure.boundary_mode = 'PROVIDER_FENCE_V2'
      and closure.closure_kind = 'LEGACY_ADMISSION'
      and closure.authority = 'GOOGLE'
      and closure.status = 'CONSUMED'
      and closure.consumed_epoch_id = epoch.epoch_id
      and closure.tournament_id = '2026'
      and closure.deployment_id = gate.admission_deployment_id
      and evidence.deployment_id = gate.admission_deployment_id
      and evidence.deployment_commit = activation.expected_deployment_commit
      and evidence.vercel_project_id = activation.expected_vercel_project_id
      and evidence.source_workbook_id = resource.google_workbook_id
      and evidence.legacy_deployments_fenced
      and evidence.legacy_google_credentials_fenced
      and evidence.non_owner_manual_google_scoring_fenced
      and evidence.owner_override_operationally_frozen
      and evidence.revoked_at is null
      and epoch.admission_generation_id = closure.admission_generation_id
      and epoch.closure_boundary_fingerprint = closure.lease_set_fingerprint
      and closure.external_fence_evidence_id = evidence.evidence_id
      and epoch.google_writer_provider_fence_id = evidence.provider_fence_id
      and epoch.google_writer_provider_verification_id = evidence.provider_fence_verification_id
      and closure.google_writer_provider_fence_id = evidence.provider_fence_id
      and closure.google_writer_provider_verification_id = evidence.provider_fence_verification_id
      and not exists (
        select 1 from production_control.maintenance_deployment_capability_bindings binding
        where binding.epoch_id = epoch.epoch_id
      )
      and not exists (
        select 1 from production_control.postcutover_application_release_rebindings
        where scope_key = resource.scope_key
      )
      and not exists (
        select 1 from production_control.postcutover_normal_release_head
        where scope_key = resource.scope_key
      )
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_LEGACY_PROVIDER_ORIGIN_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_legacy_provider_origin_v1() OWNER TO postgres;

--
-- Name: assert_maintenance_common_input(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_maintenance_common_input(input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'boundary_mode' is distinct from 'MAINTENANCE_WINDOW_V1'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = '' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_EXACT_INPUT_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_maintenance_common_input(input jsonb) OWNER TO postgres;

--
-- Name: assert_maintenance_cutover_commit_safe(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_maintenance_cutover_commit_safe(input jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  capability
    production_control.maintenance_deployment_capability_bindings%rowtype;
begin
  perform production_control
    .assert_maintenance_cutover_commit_safe_pre_capability(input);
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  select value.* into capability
  from production_control.maintenance_deployment_capability_bindings value
  where value.epoch_id = gate.active_epoch_id
    and value.deployment_id = gate.admission_deployment_id;
  if activation.boundary_mode = 'MAINTENANCE_WINDOW_V1' then
    if not found then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_RUNTIME_CAPABILITY_REQUIRED';
    end if;
    perform production_control.assert_production_maintenance_runtime_capability(
      input, 'SCORING_COMMIT'
    );
    if activation.read_cutover_phase <> 'SCORING_COMMIT'
       or capability.deployment_id is distinct from input->>'deployment_id'
       or capability.deployment_commit is distinct from
         pg_catalog.lower(input->>'deployment_commit')
       or capability.epoch_id is distinct from (input->>'epoch_id')::uuid
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_SCORING_COMMIT_PHASE_REQUIRED';
    end if;
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_maintenance_cutover_commit_safe(input jsonb) OWNER TO postgres;

--
-- Name: assert_maintenance_cutover_commit_safe_pre_capability(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_maintenance_cutover_commit_safe_pre_capability(input jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  commit_captured_at timestamptz;
begin
  perform production_control.assert_maintenance_common_input(input);
  perform production_control.assert_no_active_physical_writer_fence();
  commit_captured_at := (input->>'commit_google_captured_at')::timestamptz;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = (input->>'closure_id')::uuid;
  select * into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = (input->>'epoch_id')::uuid;
  if coalesce(input->>'commit_google_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or input->>'commit_google_source_fingerprint' is distinct from
       closure.final_source_fingerprint
     or input->>'supabase_shadow_fingerprint' is distinct from
       closure.supabase_shadow_fingerprint
     or commit_captured_at < epoch.created_at
     or commit_captured_at > pg_catalog.now()
     or commit_captured_at < pg_catalog.now() - interval '5 minutes'
     or activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.maintenance_state <> 'SCORING_MAINTENANCE'
     or activation.state <> 'CUTOVER_PREPARED'
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or resource.scoring_authority <> 'GOOGLE'
     or resource.scoring_ingress_enabled or resource.workers_enabled
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'GOOGLE' or gate.state <> 'PAUSED'
     or gate.admission_state <> 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.unresolved_client_queues <> 0
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or gate.active_closure_id is distinct from closure.closure_id
     or activation.active_transition_epoch_id is distinct from epoch.epoch_id
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.status <> 'CLOSED'
     or closure.final_source_fingerprint is distinct from
       closure.supabase_shadow_fingerprint
     or closure.unexplained_difference_count <> 0
     or epoch.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or epoch.status <> 'PREPARED' or epoch.epoch_type <> 'CUTOVER'
     or epoch.authority_before <> 'GOOGLE'
     or epoch.authority_after <> 'SUPABASE'
     or epoch.admission_closure_id is distinct from closure.closure_id
     or epoch.admission_generation_id is distinct from
       gate.admission_generation_id
     or epoch.closed_admission_revision is distinct from
       gate.admission_revision
     or epoch.closure_boundary_fingerprint is distinct from
       closure.lease_set_fingerprint
     or epoch.source_fingerprint is distinct from
       closure.final_source_fingerprint
     or epoch.supabase_shadow_fingerprint is distinct from
       closure.supabase_shadow_fingerprint
     or epoch.reconciliation_fingerprint is distinct from
       pg_catalog.lower(input->>'reconciliation_fingerprint')
     or epoch.supabase_match_revisions is distinct from
       production_control.current_match_revisions('2026')
     or epoch.google_checkpoints is distinct from
       production_control.current_google_checkpoints('2026')
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
     or exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026'
         and lease.protocol_version = 'ADMISSION_V2'
         and lease.admission_generation_id = gate.admission_generation_id
         and lease.admission_sequence > closure.lease_high_watermark
     )
     or exists (
       select 1 from scoring_authority.google_outbox_events event
       where event.tournament_id = '2026' and event.status <> 'DELIVERED'
     )
     or exists (
       select 1 from scoring_authority.scorecard_archive_jobs job
       where job.tournament_id = '2026'
         and job.status not in ('VERIFIED', 'SUPERSEDED')
     )
     or exists (
       select 1 from production_control.worker_controls value
       where value.enabled
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_CUTOVER_COMMIT_NOT_SAFE';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_maintenance_cutover_commit_safe_pre_capability(input jsonb) OWNER TO postgres;

--
-- Name: assert_maintenance_cutover_prepare_safe(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_maintenance_cutover_prepare_safe(input jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
begin
  perform production_control.assert_maintenance_cutover_snapshot_safe(input);
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = (input->>'closure_id')::uuid;
  if activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or closure.final_source_fingerprint is distinct from
       pg_catalog.lower(input->>'source_fingerprint')
     or closure.supabase_shadow_fingerprint is distinct from
       pg_catalog.lower(input->>'supabase_shadow_fingerprint')
     or closure.reconciliation_fingerprint is distinct from
       pg_catalog.lower(input->>'reconciliation_fingerprint')
     or closure.lease_set_fingerprint is distinct from
       pg_catalog.lower(input->>'closure_boundary_fingerprint')
     or closure.supabase_match_revisions is distinct from
       input->'supabase_match_revisions'
     or closure.google_checkpoints is distinct from
       input->'google_checkpoints'
     or activation.active_transition_epoch_id is not null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_CUTOVER_PREPARE_NOT_SAFE';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_maintenance_cutover_prepare_safe(input jsonb) OWNER TO postgres;

--
-- Name: assert_maintenance_cutover_snapshot_safe(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_maintenance_cutover_snapshot_safe(input jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
begin
  perform production_control.assert_maintenance_common_input(input);
  perform production_control.assert_no_active_physical_writer_fence();
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = (input->>'closure_id')::uuid;
  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.maintenance_state <> 'SCORING_MAINTENANCE'
     or activation.state <> 'GOOGLE_LEASE_ARMED'
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or resource.scoring_authority <> 'GOOGLE'
     or resource.scoring_ingress_enabled or resource.workers_enabled
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'GOOGLE' or gate.state <> 'PAUSED'
     or gate.admission_state <> 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.unresolved_client_queues <> 0
     or gate.active_closure_id is distinct from closure.closure_id
     or gate.external_fence_evidence_id is not null
     or gate.google_writer_provider_fence_id is not null
     or gate.google_writer_provider_verification_id is not null
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.status <> 'CLOSED'
     or closure.authority <> 'GOOGLE'
     or closure.closure_kind <> 'LEGACY_ADMISSION'
     or closure.final_source_fingerprint is null
     or closure.final_source_fingerprint is distinct from
       closure.first_source_fingerprint
     or closure.final_source_fingerprint is distinct from
       closure.supabase_shadow_fingerprint
     or closure.unexplained_difference_count <> 0
     or closure.first_source_captured_at is null
     or closure.second_source_captured_at is null
     or closure.second_source_captured_at <
       closure.first_source_captured_at + interval '1 second'
     or closure.second_source_captured_at <
       pg_catalog.now() - interval '5 minutes'
     or closure.authority_generation_id is distinct from
       activation.authority_generation_id
     or closure.admission_generation_id is distinct from
       gate.admission_generation_id
     or closure.closed_admission_revision is distinct from
       gate.admission_revision
     or closure.lease_set_fingerprint is distinct from
       production_control.scoring_admission_lease_set_fingerprint(
         gate.admission_generation_id
       )
     or closure.supabase_match_revisions is distinct from
       production_control.current_match_revisions('2026')
     or closure.google_checkpoints is distinct from
       production_control.current_google_checkpoints('2026')
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
     or exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026'
         and lease.protocol_version = 'ADMISSION_V2'
         and lease.admission_generation_id = gate.admission_generation_id
         and lease.admission_sequence > closure.lease_high_watermark
     )
     or exists (
       select 1 from scoring_authority.google_outbox_events event
       where event.tournament_id = '2026' and event.status <> 'DELIVERED'
     )
     or exists (
       select 1 from scoring_authority.scorecard_archive_jobs job
       where job.tournament_id = '2026'
         and job.status not in ('VERIFIED', 'SUPERSEDED')
     )
     or exists (
       select 1 from production_control.worker_controls value
       where value.enabled
     )
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_CUTOVER_SNAPSHOT_NOT_SAFE';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_maintenance_cutover_snapshot_safe(input jsonb) OWNER TO postgres;

--
-- Name: assert_maintenance_google_reopen_safe(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_maintenance_google_reopen_safe(input jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
begin
  perform production_control.assert_maintenance_common_input(input);
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  if activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or resource.scoring_authority <> 'GOOGLE'
     or resource.scoring_ingress_enabled
     or gate.authority <> 'GOOGLE' or gate.state <> 'PAUSED'
     or activation.active_transition_epoch_id is not null
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     )
     or activation.first_supabase_write_observed_at is not null
        and coalesce(input->>'reconciliation_complete', 'false') <> 'true'
     or coalesce((input->>'lost_write_count')::integer, 0) <> 0
     or coalesce((input->>'duplicate_write_count')::integer, 0) <> 0
     or coalesce((input->>'unresolved_write_count')::integer, 0) <> 0 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_GOOGLE_REOPEN_NOT_SAFE';
  end if;
end;
$$;


