--
-- Name: assert_production_participant_identity_cutover_frozen_2026_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_participant_identity_cutover_frozen_2026_v1() RETURNS production_control.resource_scope
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth', 'pg_temp'
    AS $$
declare resource production_control.resource_scope%rowtype;
declare activation production_control.cutover_activation_state%rowtype;
