--
-- Name: assert_production_presentation_shadow_scope(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_presentation_shadow_scope(input jsonb) RETURNS production_control.resource_scope
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  expected_tabs constant jsonb := '["Tournaments","Live Tournaments","Players","Handicaps","Team Names","Courses","Live Matches","Matches","Tournament Timeline","Net Skins","Calcutta Purchases","Calcutta Ownership","Calcutta Point Structure","Calcutta Payout"]'::jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_PRESENTATION_SERVICE_ROLE_REQUIRED';
  end if;
  select value.* into strict scope
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if scope.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or scope.project_url <> 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or scope.google_workbook_id <> '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or scope.vercel_project <> 'bagger-inv'
     or scope.canonical_domain <> 'https://baggerinv.com'
     or scope.current_tournament_id <> '2026'
     or scope.current_tournament_year <> 2026
     or upper(btrim(coalesce(input->>'environment', ''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref', '')) <> scope.project_ref
     or btrim(coalesce(input->>'project_url', '')) <> scope.project_url
     or btrim(coalesce(input->>'source_workbook_id', '')) <> scope.google_workbook_id
     or btrim(coalesce(input->>'tournament_id', '')) <> scope.current_tournament_id
     or coalesce((input->>'tournament_year')::integer, 0) <> scope.current_tournament_year
     or btrim(coalesce(input->>'operation', '')) <> 'PRODUCTION_PRESENTATION_SHADOW_IMPORT'
     or btrim(coalesce(input->>'contract_version', '')) <> 'production-presentation-shadow-v1'
     or coalesce(input->'source_tabs', 'null'::jsonb) <> expected_tabs
     or btrim(coalesce(input->>'requested_by', '')) = ''
     or lower(btrim(coalesce(input->>'request_fingerprint', ''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(input->>'source_fingerprint', ''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(input->>'payload_fingerprint', ''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(input->>'current_shadow_source_fingerprint', ''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(input->>'current_shadow_database_fingerprint', ''))) !~ '^[0-9a-f]{64}$'
     or scope.current_tournament_read_authority <> 'GOOGLE'
     or scope.scoring_authority <> 'GOOGLE'
     or scope.participant_identity_authority <> 'PASSPORT'
     or scope.public_supabase_reads_enabled
     or scope.scoring_ingress_enabled
     or scope.google_writes_enabled
     or scope.auth_user_creation_enabled
     or scope.odds_publication_enabled
     or scope.workers_enabled
     or exists (
       select 1 from production_control.worker_controls worker
       where worker.enabled or worker.scheduler_installed or worker.google_writes_allowed
     ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_PRESENTATION_DORMANT_SCOPE_REQUIRED';
  end if;
  if coalesce((input#>>'{safety,shadow_only}')::boolean, false) is not true
     or coalesce((input#>>'{safety,authoritative}')::boolean, true) is not false
     or upper(btrim(coalesce(input#>>'{safety,scoring_authority}', ''))) <> 'GOOGLE'
     or upper(btrim(coalesce(input#>>'{safety,participant_identity_authority}', ''))) <> 'PASSPORT'
     or coalesce((input#>>'{safety,scoring_ingress_enabled}')::boolean, true)
     or coalesce((input#>>'{safety,public_reads_enabled}')::boolean, true)
     or coalesce((input#>>'{safety,workers_enabled}')::boolean, true)
     or coalesce((input#>>'{safety,google_writes}')::integer, 1) <> 0
     or coalesce((input#>>'{safety,outbox_events}')::integer, 1) <> 0
     or coalesce((input#>>'{safety,archive_jobs}')::integer, 1) <> 0
     or coalesce((input#>>'{safety,mirror_jobs}')::integer, 1) <> 0 then
    raise exception using errcode = '42501', message = 'PRODUCTION_PRESENTATION_SHADOW_SAFETY_REQUIRED';
  end if;
  if exists (select 1 from scoring_authority.google_outbox_events where tournament_id = '2026')
     or exists (select 1 from scoring_authority.scorecard_archive_jobs where tournament_id = '2026')
     or exists (select 1 from scoring_authority.odds_google_mirror_jobs where tournament_id = '2026') then
    raise exception using errcode = '42501', message = 'PRODUCTION_PRESENTATION_DELIVERY_QUEUES_MUST_BE_EMPTY';
  end if;
  return scope;
end;
$_$;


ALTER FUNCTION production_control.assert_production_presentation_shadow_scope(input jsonb) OWNER TO postgres;

--
-- Name: assert_production_scoring_actor(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_scoring_actor(input jsonb, require_director boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth'
    AS $$
declare
  actor text := btrim(coalesce(input#>>'{authorization,player_id}', ''));
  actor_role text := upper(coalesce(input#>>'{authorization,role}', 'PLAYER'));
  actor_auth_user uuid := nullif(input#>>'{authorization,auth_user_id}', '')::uuid;
begin
  if input#>>'{authorization,tournament_id}' <> '2026'
     or actor = ''
     or actor_auth_user is null
     or actor_role not in ('PLAYER', 'DIRECTOR')
     or (require_director and actor_role <> 'DIRECTOR') then
    raise exception using errcode = '42501', message = case when require_director
      then 'PRODUCTION_DIRECTOR_AUTHORIZATION_REQUIRED'
      else 'PRODUCTION_SCORING_AUTHORIZATION_REQUIRED' end;
  end if;

  -- Never trust a role/player assertion supplied by the server request. Re-read
  -- the current Auth link, confirmed identifier, tournament membership and
  -- role on every mutation so revoked/stale sessions lose authority promptly.
  if not exists (
    select 1
    from participant_identity.user_player_links link
    join auth.users auth_user
      on auth_user.id = link.auth_user_id and auth_user.email_confirmed_at is not null
    join participant_identity.participant_auth_identifiers identifier
      on identifier.auth_user_id = link.auth_user_id
     and identifier.player_id = link.player_id
     and identifier.identifier_type = 'EMAIL'
     and identifier.status = 'VERIFIED'
    join participant_identity.tournament_roles tournament_role
      on tournament_role.tournament_id = '2026'
     and tournament_role.auth_user_id = link.auth_user_id
     and tournament_role.role = case when actor_role = 'DIRECTOR' then 'DIRECTOR' else 'PARTICIPANT' end
     and tournament_role.role_active
     and tournament_role.revoked_at is null
    join scoring_authority.tournament_players membership
      on membership.tournament_id = '2026'
     and membership.player_id = link.player_id
     and membership.participation_status = 'ACTIVE'
    where link.auth_user_id = actor_auth_user
      and link.player_id = actor
      and link.status = 'ACTIVE'
      and link.revoked_at is null
  ) then
    raise exception using errcode = '42501', message = case when require_director
      then 'PRODUCTION_DIRECTOR_AUTHORIZATION_REQUIRED'
      else 'PRODUCTION_SCORING_AUTHORIZATION_REQUIRED' end;
  end if;

  if actor_role = 'DIRECTOR' and not exists (
    select 1
    from production_control.director_entitlements entitlement
    where entitlement.auth_user_id = actor_auth_user
      and entitlement.tournament_id = '2026'
      and entitlement.player_id = actor
      and entitlement.role in ('DIRECTOR', 'OWNER')
      and entitlement.status = 'ACTIVE'
      and entitlement.revoked_at is null
  ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_DIRECTOR_AUTHORIZATION_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_production_scoring_actor(input jsonb, require_director boolean) OWNER TO postgres;

--
-- Name: scoring_ingress_leases; Type: TABLE; Schema: scoring_authority; Owner: postgres
--

CREATE TABLE scoring_authority.scoring_ingress_leases (
    lease_id uuid DEFAULT gen_random_uuid() NOT NULL,
    tournament_id text NOT NULL,
    match_id text NOT NULL,
    authority text NOT NULL,
    actor_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    operation text,
    authority_generation_id uuid,
    deployment_commit text,
    request_fingerprint text,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    completed_at timestamp with time zone,
    protocol_version text DEFAULT 'LEGACY_V1'::text NOT NULL,
    admission_sequence bigint,
    admission_generation_id uuid,
    admission_revision bigint,
    admitted_activation_revision bigint,
    lease_nonce_hash text,
    operation_request_id uuid,
    writer_intent text,
    request_payload_hash text,
    resolution_state text DEFAULT 'LEGACY_UNCLASSIFIED'::text NOT NULL,
    write_started_at timestamp with time zone,
    outcome_reported_at timestamp with time zone,
    provider_mutation_key text,
    provider_before_fingerprint text,
    provider_after_fingerprint text,
    provider_readback_fingerprint text,
    outcome_evidence_fingerprint text,
    resolution_fingerprint text,
    resolved_at timestamp with time zone,
    resolved_by text,
    close_fence_id uuid,
    last_error_code text,
    provider_credential_class text,
    provider_principal_fingerprint text,
    CONSTRAINT production_scoring_lease_activation_revision_check CHECK (((admitted_activation_revision IS NULL) OR (admitted_activation_revision >= 0))),
    CONSTRAINT production_scoring_lease_admission_revision_check CHECK (((admission_revision IS NULL) OR (admission_revision >= 0))),
    CONSTRAINT production_scoring_lease_admission_sequence_check CHECK (((admission_sequence IS NULL) OR (admission_sequence > 0))),
    CONSTRAINT production_scoring_lease_deployment_commit_check CHECK (((deployment_commit IS NULL) OR (deployment_commit ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT production_scoring_lease_nonce_hash_check CHECK (((lease_nonce_hash IS NULL) OR (lease_nonce_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_operation_check CHECK (((operation IS NULL) OR (operation ~ '^[A-Z0-9:_-]{3,100}$'::text))),
    CONSTRAINT production_scoring_lease_outcome_evidence_check CHECK (((outcome_evidence_fingerprint IS NULL) OR (outcome_evidence_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_protocol_version_check CHECK ((protocol_version = ANY (ARRAY['LEGACY_V1'::text, 'ADMISSION_V2'::text]))),
    CONSTRAINT production_scoring_lease_provider_after_check CHECK (((provider_after_fingerprint IS NULL) OR (provider_after_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_provider_before_check CHECK (((provider_before_fingerprint IS NULL) OR (provider_before_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_provider_credential_class_check CHECK (((provider_credential_class IS NULL) OR (provider_credential_class = 'LEGACY_PROVIDER_FENCEABLE'::text))),
    CONSTRAINT production_scoring_lease_provider_principal_fingerprint_check CHECK (((provider_principal_fingerprint IS NULL) OR (provider_principal_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_provider_readback_check CHECK (((provider_readback_fingerprint IS NULL) OR (provider_readback_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_request_fingerprint_check CHECK (((request_fingerprint IS NULL) OR (request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_request_payload_hash_check CHECK (((request_payload_hash IS NULL) OR (request_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_resolution_fingerprint_check CHECK (((resolution_fingerprint IS NULL) OR (resolution_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_lease_resolution_state_check CHECK ((resolution_state = ANY (ARRAY['LEGACY_UNCLASSIFIED'::text, 'ADMITTED'::text, 'WRITE_STARTED'::text, 'CONFIRMED_WRITE'::text, 'PROVEN_NO_WRITE'::text, 'AMBIGUOUS'::text, 'PARTIAL_WRITE'::text, 'RESOLVED_WRITE'::text, 'RESOLVED_NO_WRITE'::text]))),
    CONSTRAINT production_scoring_lease_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'COMPLETED'::text, 'EXPIRED'::text]))),
    CONSTRAINT production_scoring_lease_v2_shape_check CHECK (((protocol_version <> 'ADMISSION_V2'::text) OR ((admission_sequence IS NOT NULL) AND (admission_generation_id IS NOT NULL) AND (admission_revision IS NOT NULL) AND (admitted_activation_revision IS NOT NULL) AND (lease_nonce_hash IS NOT NULL) AND (operation_request_id IS NOT NULL) AND (writer_intent = 'CANONICAL_LEGACY'::text) AND (request_payload_hash IS NOT NULL) AND (request_fingerprint IS NOT NULL)))),
    CONSTRAINT production_scoring_lease_writer_intent_check CHECK (((writer_intent IS NULL) OR (writer_intent = 'CANONICAL_LEGACY'::text))),
    CONSTRAINT scoring_ingress_leases_authority_check CHECK ((authority = ANY (ARRAY['GOOGLE'::text, 'SUPABASE'::text])))
);


ALTER TABLE scoring_authority.scoring_ingress_leases OWNER TO postgres;

--
-- Name: assert_production_scoring_lease_nonce(scoring_authority.scoring_ingress_leases, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_scoring_lease_nonce(lease scoring_authority.scoring_ingress_leases, supplied_nonce text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
begin
  if lease.protocol_version <> 'ADMISSION_V2'
     or coalesce(supplied_nonce, '')
       !~ '^[0-9a-fA-F-]{36}$'
     or lease.lease_nonce_hash is distinct from pg_catalog.encode(
       extensions.digest(pg_catalog.lower(supplied_nonce), 'sha256'), 'hex'
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_SCORING_LEASE_NONCE_INVALID';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_production_scoring_lease_nonce(lease scoring_authority.scoring_ingress_leases, supplied_nonce text) OWNER TO postgres;

--
-- Name: assert_production_scoring_runtime(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_scoring_runtime(input jsonb, required_worker text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  boundary_mode_value text;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if pointer.tournament_id <> '2026' then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_LEGACY_SCORING_POINTER_CHANGED';
  end if;
  select boundary_mode into strict boundary_mode_value
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';
  if boundary_mode_value = 'PROVIDER_FENCE_V2' then
    perform production_control.assert_legacy_provider_origin_v1();
  else
    perform production_control.annual_scoring_platform_certification_v1(input);
  end if;
  perform production_control
    .assert_production_scoring_runtime_pre_annual_pointer_fence(
      input, required_worker
    );
end;
$$;


ALTER FUNCTION production_control.assert_production_scoring_runtime(input jsonb, required_worker text) OWNER TO postgres;

--
-- Name: assert_production_scoring_runtime_pre_annual_pointer_fence(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_scoring_runtime_pre_annual_pointer_fence(input jsonb, required_worker text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  perform production_control
    .assert_production_scoring_runtime_pre_application_release(
      input, required_worker
    );
end;
$$;


ALTER FUNCTION production_control.assert_production_scoring_runtime_pre_annual_pointer_fence(input jsonb, required_worker text) OWNER TO postgres;

--
-- Name: assert_production_scoring_runtime_pre_application_release(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_scoring_runtime_pre_application_release(input jsonb, required_worker text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  capability_bound boolean := false;
  capability_claimed boolean :=
    pg_catalog.btrim(coalesce(
      input->>'deployment_capability_contract', ''
    )) <> '' or pg_catalog.btrim(coalesce(
      input->>'deployment_capability_ceiling', ''
    )) <> '';
  capability_required boolean := false;
  required_database_phase text;
begin
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  capability_bound := exists (
    select 1
    from production_control.maintenance_deployment_capability_bindings value
    where value.epoch_id = gate.active_epoch_id
  );
  capability_required :=
    activation.boundary_mode = 'MAINTENANCE_WINDOW_V1'
    and production_control.cutover_phase_rank(activation.read_cutover_phase)
      >= production_control.cutover_phase_rank('SCORING_COMMIT');
  if capability_bound or capability_claimed or capability_required
  then
    if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1' then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_RUNTIME_CAPABILITY_REQUIRED';
    end if;
    required_database_phase := case
      when pg_catalog.btrim(coalesce(required_worker, '')) <> ''
        then 'WORKERS'
      else 'SCORING_COMMIT'
    end;
    if production_control.cutover_phase_rank(activation.read_cutover_phase)
         < production_control.cutover_phase_rank(required_database_phase)
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_CUTOVER_SCORING_DATABASE_PHASE_REQUIRED';
    end if;
    perform production_control.assert_production_maintenance_runtime_capability(
      input, required_database_phase
    );
  end if;
  perform production_control
    .assert_production_scoring_runtime_pre_capability(input, required_worker);
end;
$$;


ALTER FUNCTION production_control.assert_production_scoring_runtime_pre_application_release(input jsonb, required_worker text) OWNER TO postgres;

--
-- Name: assert_production_scoring_runtime_pre_capability(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_scoring_runtime_pre_capability(input jsonb, required_worker text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  active_closure production_control.scoring_admission_closures%rowtype;
  legacy_closure production_control.scoring_admission_closures%rowtype;
  required_worker_name text := pg_catalog.upper(
    coalesce(required_worker, '')
  );
  normal_runtime boolean := false;
  rollback_worker_drain boolean := false;
begin
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1' then
    perform production_control.assert_production_scoring_runtime_provider_fence_v2(
      input, required_worker
    );
    return;
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  select * into strict active_closure
  from production_control.scoring_admission_closures value
  where value.closure_id = gate.active_closure_id;
  if active_closure.closure_kind = 'SUPABASE_INGRESS' then
    select * into strict legacy_closure
    from production_control.scoring_admission_closures value
    where value.closure_id = active_closure.prior_legacy_closure_id;
  else
    legacy_closure := active_closure;
  end if;
  normal_runtime :=
    activation.maintenance_state = 'NORMAL'
    and activation.scoring_ingress_enabled
    and resource.scoring_ingress_enabled
    and gate.state = 'OPEN'
    and active_closure.boundary_mode = 'MAINTENANCE_WINDOW_V1'
    and active_closure.closure_kind = 'LEGACY_ADMISSION'
    and active_closure.authority = 'GOOGLE'
    and active_closure.status = 'CONSUMED'
    and active_closure.consumed_epoch_id = activation.authority_generation_id;
  rollback_worker_drain :=
    required_worker_name in (
      'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE'
    )
    and activation.maintenance_state = 'SCORING_MAINTENANCE'
    and not activation.scoring_ingress_enabled
    and not resource.scoring_ingress_enabled
    and gate.state = 'PAUSED'
    and active_closure.boundary_mode = 'MAINTENANCE_WINDOW_V1'
    and active_closure.closure_kind = 'SUPABASE_INGRESS'
    and active_closure.authority = 'SUPABASE'
    and active_closure.status in ('CLOSING', 'CLOSED')
    and active_closure.prior_legacy_closure_id = legacy_closure.closure_id
    and legacy_closure.boundary_mode = 'MAINTENANCE_WINDOW_V1'
    and legacy_closure.closure_kind = 'LEGACY_ADMISSION'
    and legacy_closure.status = 'CONSUMED';
  if activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or activation.authority_generation_id is distinct from
       nullif(input->>'expected_epoch_id', '')::uuid
     or resource.scoring_authority <> 'SUPABASE'
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'SUPABASE'
     or gate.admission_state <> 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.active_epoch_id is distinct from
       activation.authority_generation_id
     or not (normal_runtime or rollback_worker_drain)
     or not exists (
       select 1 from scoring_authority.tournaments value
       where value.tournament_id = '2026'
         and value.scoring_authority = 'SUPABASE'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SUPABASE_SCORING_MAINTENANCE_BOUNDARY_REQUIRED';
  end if;
  if required_worker_name <> '' and (
       required_worker_name not in (
         'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE'
       )
       or not resource.workers_enabled
       or not resource.google_writes_enabled
       or not exists (
         select 1
         from production_control.worker_controls controls
         join production_control.worker_contracts contracts
           using (worker_name)
         where controls.worker_name = required_worker_name
           and controls.enabled and controls.google_writes_allowed
           and contracts.operation_allowed
           and contracts.requires_google_write
           and not contracts.authoritative_write_allowed
           and coalesce(
             controls.metadata->>'activation_epoch_id', ''
           ) = activation.authority_generation_id::text
           and coalesce(
             controls.metadata->>'deployment_commit', ''
           ) = activation.expected_deployment_commit
       )
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_WORKER_NOT_ENABLED';
  end if;
  perform pg_catalog.set_config(
    'production_control.scoring_runtime_authority_generation',
    activation.authority_generation_id::text, true
  );
  perform pg_catalog.set_config(
    'production_control.scoring_runtime_admission_generation',
    gate.admission_generation_id::text, true
  );
end;
$$;


ALTER FUNCTION production_control.assert_production_scoring_runtime_pre_capability(input jsonb, required_worker text) OWNER TO postgres;

--
-- Name: assert_production_scoring_runtime_provider_fence_v2(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_scoring_runtime_provider_fence_v2(input jsonb, required_worker text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  active_closure production_control.scoring_admission_closures%rowtype;
  legacy_closure production_control.scoring_admission_closures%rowtype;
  required_worker_name text := pg_catalog.upper(
    coalesce(required_worker, '')
  );
  normal_supabase_runtime boolean := false;
  rollback_worker_drain boolean := false;
begin
  -- The transaction-scoped shared lock remains held through the caller RPC.
  -- Close/prepare/commit/reopen use the exclusive counterpart, so no Supabase
  -- canonical mutation can cross an admission boundary after this assertion.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  select * into strict active_closure
  from production_control.scoring_admission_closures value
  where value.closure_id = gate.active_closure_id;

  if active_closure.closure_kind = 'SUPABASE_INGRESS' then
    select * into strict legacy_closure
    from production_control.scoring_admission_closures value
    where value.closure_id = active_closure.prior_legacy_closure_id;
  else
    legacy_closure := active_closure;
  end if;

  normal_supabase_runtime :=
    gate.state = 'OPEN'
    and active_closure.closure_kind = 'LEGACY_ADMISSION'
    and active_closure.authority = 'GOOGLE'
    and active_closure.status = 'CONSUMED'
    and active_closure.consumed_epoch_id = activation.authority_generation_id
    and active_closure.admission_generation_id = gate.admission_generation_id
    and active_closure.deployment_id = gate.admission_deployment_id
    and active_closure.external_fence_evidence_id = gate.external_fence_evidence_id;

  -- A Supabase mutation that held the shared authority lock may have committed
  -- immediately before rollback acquired the exclusive lock and paused new
  -- ingress. Its durable Google mirror/archive work must remain drainable or
  -- rollback finalization would deadlock on its own unresolved-queue checks.
  -- This exception is intentionally worker-only: every participant/Director
  -- canonical mutation calls this function without required_worker and stays
  -- rejected while the execution gate is PAUSED.
  rollback_worker_drain :=
    required_worker_name in (
      'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE'
    )
    and gate.state = 'PAUSED'
    and active_closure.closure_kind = 'SUPABASE_INGRESS'
    and active_closure.authority = 'SUPABASE'
    and active_closure.status = 'CLOSING'
    and active_closure.authority_generation_id =
      activation.authority_generation_id
    and active_closure.admission_generation_id = gate.admission_generation_id
    and active_closure.deployment_id = gate.admission_deployment_id
    and active_closure.external_fence_evidence_id =
      gate.external_fence_evidence_id
    and active_closure.prior_legacy_closure_id = legacy_closure.closure_id
    and legacy_closure.closure_kind = 'LEGACY_ADMISSION'
    and legacy_closure.authority = 'GOOGLE'
    and legacy_closure.status = 'CONSUMED'
    and legacy_closure.consumed_epoch_id = activation.authority_generation_id
    and activation.active_transition_epoch_id is null;

  if activation.state is distinct from 'SCORING_COMMITTED'
     or activation.current_authority is distinct from 'SUPABASE'
     or not activation.scoring_ingress_enabled
     or activation.authority_generation_id is distinct from
       nullif(input->>'expected_epoch_id', '')::uuid
     or resource.scoring_authority is distinct from 'SUPABASE'
     or not resource.scoring_ingress_enabled
     or gate.admission_state is distinct from 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.active_closure_id is null
     or gate.external_fence_evidence_id is null
     or gate.authority is distinct from 'SUPABASE'
     or gate.active_epoch_id
       is distinct from activation.authority_generation_id
     or not (normal_supabase_runtime or rollback_worker_drain)
     or not exists (
       select 1 from scoring_authority.tournaments value
       where value.tournament_id = '2026'
         and value.scoring_authority = 'SUPABASE'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SUPABASE_SCORING_ADMISSION_V2_REQUIRED';
  end if;

  if required_worker_name <> '' then
    if required_worker_name not in (
         'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE'
       )
       or not resource.workers_enabled
       or not resource.google_writes_enabled
       or not exists (
         select 1
         from production_control.worker_controls controls
         join production_control.worker_contracts contracts
           using (worker_name)
         where controls.worker_name = required_worker_name
           and controls.enabled
           and controls.google_writes_allowed
           and contracts.operation_allowed
           and contracts.requires_google_write
           and not contracts.authoritative_write_allowed
           and coalesce(
             controls.metadata->>'activation_epoch_id', ''
           ) = activation.authority_generation_id::text
           and coalesce(
             controls.metadata->>'deployment_commit', ''
           ) = activation.expected_deployment_commit
           and coalesce(
             controls.metadata->>'google_service_account', ''
           ) = activation.expected_google_service_account
       ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_SCORING_WORKER_NOT_ENABLED';
    end if;
  end if;
  perform pg_catalog.set_config(
    'production_control.scoring_runtime_authority_generation',
    activation.authority_generation_id::text,
    true
  );
  perform pg_catalog.set_config(
    'production_control.scoring_runtime_admission_generation',
    gate.admission_generation_id::text,
    true
  );
end;
$$;


ALTER FUNCTION production_control.assert_production_scoring_runtime_provider_fence_v2(input jsonb, required_worker text) OWNER TO postgres;

--
-- Name: assert_production_service_role(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_production_service_role() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  claim_role text;
  claims_text text;
begin
  claims_text := nullif(current_setting('request.jwt.claims', true), '');
  claim_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    case when claims_text is null then null else claims_text::jsonb->>'role' end
  );
  if claim_role is distinct from 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_SERVICE_ROLE_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_production_service_role() OWNER TO postgres;

--
-- Name: assert_projection_read_scope(jsonb, text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_projection_read_scope(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  resource production_control.resource_scope%rowtype;
begin
  select * into strict resource from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  if not resource.public_supabase_reads_enabled then
    perform production_control.assert_projection_read_scope_dormant_internal(
      input, expected_domain, expected_contract, expected_tabs
    );
    return;
  end if;
  perform production_control.assert_production_cutover_read_scope(
    input, production_control.projection_required_phase(expected_domain)
  );
  if upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref','')) <> resource.project_ref
     or btrim(coalesce(input->>'project_url','')) <> resource.project_url
     or btrim(coalesce(input->>'source_workbook_id','')) <> resource.google_workbook_id
     or btrim(coalesce(input->>'tournament_id','')) <> resource.current_tournament_id
     or coalesce((input->>'tournament_year')::integer,0) <> resource.current_tournament_year
     or upper(btrim(coalesce(input->>'domain',''))) <> expected_domain
     or btrim(coalesce(input->>'contract_version','')) <> expected_contract
     or coalesce(input->'source_tabs','null'::jsonb) <> expected_tabs then
    raise exception using errcode = '42501', message = 'PRODUCTION_PROJECTION_READ_SCOPE_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_projection_read_scope(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) OWNER TO postgres;

--
-- Name: assert_projection_read_scope_dormant_internal(jsonb, text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_projection_read_scope_dormant_internal(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
begin
  select * into strict scope from production_control.resource_scope
  where scope_key='BAGGER_INV_PRODUCTION';
  if upper(btrim(coalesce(input->>'environment','')))<>'PRODUCTION'
     or btrim(coalesce(input->>'project_ref',''))<>scope.project_ref
     or btrim(coalesce(input->>'project_url',''))<>scope.project_url
     or btrim(coalesce(input->>'source_workbook_id',''))<>scope.google_workbook_id
     or btrim(coalesce(input->>'tournament_id',''))<>scope.current_tournament_id
     or coalesce((input->>'tournament_year')::integer,0)<>scope.current_tournament_year
     or upper(btrim(coalesce(input->>'domain','')))<>expected_domain
     or btrim(coalesce(input->>'contract_version',''))<>expected_contract
     or coalesce(input->'source_tabs','null'::jsonb)<>expected_tabs then
    raise exception using errcode='42501',message='PRODUCTION_PROJECTION_READ_SCOPE_REQUIRED';
  end if;
  if scope.current_tournament_read_authority<>'GOOGLE'
     or scope.scoring_authority<>'GOOGLE'
     or scope.participant_identity_authority<>'PASSPORT'
     or scope.public_supabase_reads_enabled or scope.scoring_ingress_enabled
     or scope.google_writes_enabled or scope.auth_user_creation_enabled
     or scope.odds_publication_enabled or scope.workers_enabled then
    raise exception using errcode='42501',message='DORMANT_PRODUCTION_FOUNDATION_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_projection_read_scope_dormant_internal(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) OWNER TO postgres;

--
-- Name: assert_projection_scope(jsonb, text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_projection_scope(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    AS $_$
declare
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  source_text text := coalesce(input->>'source_canonical_json','');
  payload_text text := coalesce(input->>'payload_canonical_json','');
  source_value jsonb;
  payload_value jsonb;
  settings_text text;
  effective_settings_text text;
  settings_value jsonb;
  effective_settings_value jsonb;
  snapshot_value jsonb;
  snapshot_item jsonb;
  snapshot_text text;
begin
  select * into strict resource from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  if not resource.public_supabase_reads_enabled then
    perform production_control.assert_projection_scope_dormant_internal(
      input, expected_domain, expected_contract, expected_tabs
    );
    return;
  end if;

  perform production_control.assert_production_cutover_read_scope(
    input, production_control.projection_required_phase(expected_domain)
  );
  select * into strict activation from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';
  if upper(btrim(coalesce(input->>'operation_authority',''))) <> 'GOOGLE_DIRECTOR_SYNC'
     or coalesce((input->>'expected_activation_revision')::bigint,-1)
       <> activation.activation_revision
     or upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref','')) <> resource.project_ref
     or btrim(coalesce(input->>'project_url','')) <> resource.project_url
     or btrim(coalesce(input->>'source_workbook_id','')) <> resource.google_workbook_id
     or btrim(coalesce(input->>'tournament_id','')) <> resource.current_tournament_id
     or coalesce((input->>'tournament_year')::integer,0) <> resource.current_tournament_year
     or upper(btrim(coalesce(input->>'domain',''))) <> expected_domain
     or btrim(coalesce(input->>'contract_version','')) <> expected_contract
     or coalesce(input->'source_tabs','null'::jsonb) <> expected_tabs
     or lower(btrim(coalesce(input->>'source_fingerprint',''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(input->>'payload_fingerprint',''))) !~ '^[0-9a-f]{64}$'
     or btrim(coalesce(input->>'requested_by','')) = ''
     or upper(btrim(coalesce(input->>'validation_status',''))) not in ('VALID','NOT_CONFIGURED')
     or jsonb_typeof(coalesce(input->'validation_diagnostics','{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(input->'source_payload','null'::jsonb)) not in ('object','array')
     or jsonb_typeof(coalesce(input->'payload','null'::jsonb)) <> 'object'
     or btrim(source_text) = '' or btrim(payload_text) = '' then
    raise exception using errcode = '42501', message = 'PRODUCTION_ACTIVE_SYNC_SCOPE_REQUIRED';
  end if;

  begin
    source_value := source_text::jsonb;
    payload_value := payload_text::jsonb;
  exception when others then
    raise exception using errcode = '22023', message = 'PRODUCTION_PROJECTION_CANONICAL_JSON_INVALID';
  end;
  if source_value is distinct from input->'source_payload'
     or payload_value is distinct from input->'payload'
     or encode(extensions.digest(source_text,'sha256'),'hex')
       <> lower(btrim(input->>'source_fingerprint'))
     or encode(extensions.digest(payload_text,'sha256'),'hex')
       <> lower(btrim(input->>'payload_fingerprint')) then
    raise exception using errcode = '22023', message = 'PRODUCTION_PROJECTION_CANONICAL_EVIDENCE_MISMATCH';
  end if;

  if expected_domain = 'PREDICTION_SETTINGS' then
    settings_text := coalesce(input->>'settings_canonical_json','');
    effective_settings_text := coalesce(input->>'effective_settings_canonical_json','');
    if btrim(settings_text) = '' or btrim(effective_settings_text) = '' then
      raise exception using errcode = '22023', message = 'PRODUCTION_PREDICTION_SETTINGS_CANONICAL_EVIDENCE_REQUIRED';
    end if;
    begin
      settings_value := settings_text::jsonb;
      effective_settings_value := effective_settings_text::jsonb;
    exception when others then
      raise exception using errcode = '22023', message = 'PRODUCTION_PREDICTION_SETTINGS_CANONICAL_JSON_INVALID';
    end;
    if settings_value is distinct from input#>'{payload,settings}'
       or effective_settings_value is distinct from input#>'{payload,effective_settings}'
       or encode(extensions.digest(settings_text,'sha256'),'hex')
         <> lower(btrim(coalesce(input#>>'{payload,settings_fingerprint}','')))
       or encode(extensions.digest(effective_settings_text,'sha256'),'hex')
         <> lower(btrim(coalesce(input#>>'{payload,effective_settings_fingerprint}',''))) then
      raise exception using errcode = '22023', message = 'PRODUCTION_PREDICTION_SETTINGS_INNER_FINGERPRINT_MISMATCH';
    end if;
  end if;

  if expected_domain = 'PUBLISHED_ODDS' then
    if jsonb_typeof(input#>'{payload,snapshots}') <> 'array' then
      raise exception using errcode = '22023', message = 'PRODUCTION_PUBLISHED_ODDS_CANONICAL_EVIDENCE_REQUIRED';
    end if;
    for snapshot_item in select value from jsonb_array_elements(input#>'{payload,snapshots}')
    loop
      snapshot_text := coalesce(snapshot_item->>'published_payload_canonical_json','');
      if btrim(snapshot_text) = '' then
        raise exception using errcode = '22023', message = 'PRODUCTION_PUBLISHED_ODDS_CANONICAL_EVIDENCE_REQUIRED';
      end if;
      begin snapshot_value := snapshot_text::jsonb;
      exception when others then
        raise exception using errcode = '22023', message = 'PRODUCTION_PUBLISHED_ODDS_CANONICAL_JSON_INVALID';
      end;
      if snapshot_value is distinct from snapshot_item->'published_payload'
         or encode(extensions.digest(snapshot_text,'sha256'),'hex')
           <> lower(btrim(coalesce(snapshot_item->>'payload_hash',''))) then
        raise exception using errcode = '22023', message = 'PRODUCTION_PUBLISHED_ODDS_SNAPSHOT_HASH_MISMATCH';
      end if;
    end loop;
  end if;

  if not exists (
    select 1 from production_control.tournament_scopes value
    where value.tournament_id = resource.current_tournament_id
      and value.tournament_year = resource.current_tournament_year
      and value.source_workbook_id = resource.google_workbook_id
      and value.scope_kind = 'CURRENT_TOURNAMENT'
      and value.active_for_shadow_import
  ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_TOURNAMENT_SCOPE_REQUIRED';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_projection_scope(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) OWNER TO postgres;

--
-- Name: assert_projection_scope_dormant_internal(jsonb, text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_projection_scope_dormant_internal(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  source_text text := coalesce(input->>'source_canonical_json','');
  payload_text text := coalesce(input->>'payload_canonical_json','');
  source_value jsonb;
  payload_value jsonb;
  settings_text text;
  effective_settings_text text;
  settings_value jsonb;
  effective_settings_value jsonb;
  snapshot_value jsonb;
  snapshot_item jsonb;
  snapshot_text text;
begin
  select * into strict scope
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';

  if upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref','')) <> scope.project_ref
     or btrim(coalesce(input->>'project_url','')) <> scope.project_url
     or btrim(coalesce(input->>'source_workbook_id','')) <> scope.google_workbook_id
     or btrim(coalesce(input->>'tournament_id','')) <> scope.current_tournament_id
     or coalesce((input->>'tournament_year')::integer, 0) <> scope.current_tournament_year
     or upper(btrim(coalesce(input->>'domain',''))) <> expected_domain
     or btrim(coalesce(input->>'contract_version','')) <> expected_contract
     or coalesce(input->'source_tabs','null'::jsonb) <> expected_tabs
     or lower(btrim(coalesce(input->>'source_fingerprint',''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(input->>'payload_fingerprint',''))) !~ '^[0-9a-f]{64}$'
     or btrim(coalesce(input->>'requested_by','')) = ''
     or upper(btrim(coalesce(input->>'validation_status',''))) not in ('VALID','NOT_CONFIGURED')
     or jsonb_typeof(coalesce(input->'validation_diagnostics','{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(input->'source_payload','null'::jsonb)) not in ('object','array')
     or jsonb_typeof(coalesce(input->'payload','null'::jsonb)) <> 'object'
     or btrim(source_text) = ''
     or btrim(payload_text) = '' then
    raise exception using errcode = '42501', message = 'PRODUCTION_PROJECTION_SCOPE_REQUIRED';
  end if;

  begin
    source_value := source_text::jsonb;
    payload_value := payload_text::jsonb;
  exception when others then
    raise exception using errcode = '22023', message = 'PRODUCTION_PROJECTION_CANONICAL_JSON_INVALID';
  end;

  if source_value is distinct from input->'source_payload'
     or payload_value is distinct from input->'payload'
     or encode(extensions.digest(source_text,'sha256'),'hex')
       <> lower(btrim(input->>'source_fingerprint'))
     or encode(extensions.digest(payload_text,'sha256'),'hex')
       <> lower(btrim(input->>'payload_fingerprint')) then
    raise exception using errcode = '22023', message = 'PRODUCTION_PROJECTION_CANONICAL_EVIDENCE_MISMATCH';
  end if;

  if expected_domain = 'PREDICTION_SETTINGS' then
    settings_text := coalesce(input->>'settings_canonical_json','');
    effective_settings_text := coalesce(input->>'effective_settings_canonical_json','');
    if btrim(settings_text) = '' or btrim(effective_settings_text) = '' then
      raise exception using errcode = '22023', message = 'PRODUCTION_PREDICTION_SETTINGS_CANONICAL_EVIDENCE_REQUIRED';
    end if;
    begin
      settings_value := settings_text::jsonb;
      effective_settings_value := effective_settings_text::jsonb;
    exception when others then
      raise exception using errcode = '22023', message = 'PRODUCTION_PREDICTION_SETTINGS_CANONICAL_JSON_INVALID';
    end;
    if settings_value is distinct from input#>'{payload,settings}'
       or effective_settings_value is distinct from input#>'{payload,effective_settings}'
       or encode(extensions.digest(settings_text,'sha256'),'hex')
         <> lower(btrim(coalesce(input#>>'{payload,settings_fingerprint}','')))
       or encode(extensions.digest(effective_settings_text,'sha256'),'hex')
         <> lower(btrim(coalesce(input#>>'{payload,effective_settings_fingerprint}',''))) then
      raise exception using errcode = '22023', message = 'PRODUCTION_PREDICTION_SETTINGS_INNER_FINGERPRINT_MISMATCH';
    end if;
  end if;

  if expected_domain = 'PUBLISHED_ODDS' then
    if jsonb_typeof(input#>'{payload,snapshots}') <> 'array' then
      raise exception using errcode = '22023', message = 'PRODUCTION_PUBLISHED_ODDS_CANONICAL_EVIDENCE_REQUIRED';
    end if;
    for snapshot_item in
      select value from jsonb_array_elements(input#>'{payload,snapshots}')
    loop
      snapshot_text := coalesce(snapshot_item->>'published_payload_canonical_json','');
      if btrim(snapshot_text) = '' then
        raise exception using errcode = '22023', message = 'PRODUCTION_PUBLISHED_ODDS_CANONICAL_EVIDENCE_REQUIRED';
      end if;
      begin
        snapshot_value := snapshot_text::jsonb;
      exception when others then
        raise exception using errcode = '22023', message = 'PRODUCTION_PUBLISHED_ODDS_CANONICAL_JSON_INVALID';
      end;
      if snapshot_value is distinct from snapshot_item->'published_payload'
         or encode(extensions.digest(snapshot_text,'sha256'),'hex')
           <> lower(btrim(coalesce(snapshot_item->>'payload_hash',''))) then
        raise exception using errcode = '22023', message = 'PRODUCTION_PUBLISHED_ODDS_SNAPSHOT_HASH_MISMATCH';
      end if;
    end loop;
  end if;

  if scope.current_tournament_read_authority <> 'GOOGLE'
     or scope.scoring_authority <> 'GOOGLE'
     or scope.participant_identity_authority <> 'PASSPORT'
     or scope.public_supabase_reads_enabled
     or scope.scoring_ingress_enabled
     or scope.google_writes_enabled
     or scope.auth_user_creation_enabled
     or scope.odds_publication_enabled
     or scope.workers_enabled then
    raise exception using errcode = '42501', message = 'DORMANT_PRODUCTION_FOUNDATION_REQUIRED';
  end if;

  if not exists (
    select 1 from production_control.tournament_scopes s
    where s.tournament_id = scope.current_tournament_id
      and s.tournament_year = scope.current_tournament_year
      and s.source_workbook_id = scope.google_workbook_id
      and s.scope_kind = 'CURRENT_TOURNAMENT'
      and s.active_for_shadow_import
  ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_TOURNAMENT_SCOPE_REQUIRED';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_projection_scope_dormant_internal(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) OWNER TO postgres;

--
-- Name: assert_score_derived_delivery_scope_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_score_derived_delivery_scope_v1(input jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare target text;
begin
  if input->>'contract_version' is distinct from 'score-derived-delivery-v1' then
    raise exception using errcode='22023',message='DERIVED_DELIVERY_CONTRACT_REQUIRED';
  end if;
  select tournament_id into strict target from production_control.current_tournament_pointer_v1
    where scope_key='BAGGER_INV_PRODUCTION';
  if target='2026' then perform production_control.assert_frozen_2026_derived_worker_v1(input);
  else
    if input->>'annual_scoring_operation' is null or input->>'annual_scoring_operation' not in(
      'score_derived_delivery_tick_v1','fail_score_derived_preclaim_v1','fail_intelligence_derived_bundle_v1','requeue_score_derived_delivery_v1') then
      raise exception using errcode='42501',message='DERIVED_DELIVERY_OPERATION_REQUIRED'; end if;
    perform production_control.assert_future_production_scoring_runtime_v1(input);
    if not exists(select 1 from production_control.resource_scope where scope_key='BAGGER_INV_PRODUCTION' and workers_enabled)
      or (select production_control.cutover_phase_rank(read_cutover_phase) from production_control.cutover_activation_state
        where scope_key='BAGGER_INV_PRODUCTION')<production_control.cutover_phase_rank('WORKERS') then
      raise exception using errcode='55000',message='PRODUCTION_DERIVED_WORKER_RUNTIME_REQUIRED'; end if;
  end if;
  return target;
end;
$$;


ALTER FUNCTION production_control.assert_score_derived_delivery_scope_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_scoring_admission_optimistic_input(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_scoring_admission_optimistic_input(input jsonb, require_external_fence boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
begin
  if pg_catalog.jsonb_typeof(input->'expected_activation_revision') is distinct from 'number'
     or input->>'expected_activation_revision' !~ '^[0-9]+$'
     or coalesce(input->>'expected_authority_generation', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_admission_generation', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.jsonb_typeof(input->'expected_admission_revision') is distinct from 'number'
     or input->>'expected_admission_revision' !~ '^[0-9]+$'
     or coalesce(input->>'deployment_id', '') !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'deployment_commit', '') !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or (require_external_fence and coalesce(
       input->>'external_fence_evidence_id', ''
     ) !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$') then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_ADMISSION_OPTIMISTIC_INPUT_REQUIRED';
  end if;
end;
$_$;


ALTER FUNCTION production_control.assert_scoring_admission_optimistic_input(input jsonb, require_external_fence boolean) OWNER TO postgres;

--
-- Name: assert_tournament_awards_runtime_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_tournament_awards_runtime_v1(input jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
begin
  -- This private assertion accepts both the legacy role claim and the
  -- consolidated JWT claims emitted for the server-only sb_secret_ transport.
  -- It also revalidates the exact Production project/workbook/tournament scope.
  perform production_control.assert_exact_cutover_resource_scope(input, false);

  if input->>'contract_version'
       is distinct from 'production-tournament-awards-v1'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'tournament_id' is distinct from '2026'
     or input#>>'{authorization,tournament_id}' is distinct from '2026'
     or input#>>'{authorization,role}' is distinct from 'DIRECTOR'
     or pg_catalog.upper(pg_catalog.btrim(coalesce(
       input->>'actor_player_id', ''
     ))) is distinct from pg_catalog.upper(pg_catalog.btrim(coalesce(
       input#>>'{authorization,player_id}', ''
     )))
     or pg_catalog.lower(pg_catalog.btrim(coalesce(
       input->>'actor_auth_user_id', ''
     ))) is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(
       input#>>'{authorization,auth_user_id}', ''
     ))) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_TOURNAMENT_AWARDS_SCOPE_REQUIRED';
  end if;

  select value.* into strict scope
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';

  if input->>'project_ref' is distinct from scope.project_ref
     or input->>'project_url' is distinct from scope.project_url
     or input->>'source_workbook_id' is distinct from scope.google_workbook_id
     or scope.current_tournament_id <> '2026'
     or scope.current_tournament_year <> 2026
     or pointer.tournament_id <> '2026'
     or pointer.tournament_year <> 2026 then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_TOURNAMENT_AWARDS_EXACT_RESOURCE_REQUIRED';
  end if;

  -- Re-read the Auth link, active tournament role, current roster membership,
  -- and Director entitlement rather than trusting the server request payload.
  perform production_control.assert_production_scoring_actor(input, true);
  return '2026';
end;
$$;


ALTER FUNCTION production_control.assert_tournament_awards_runtime_v1(input jsonb) OWNER TO postgres;

--
-- Name: assert_tournament_setup_match_mutable_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_tournament_setup_match_mutable_v1(target_match_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  match_value scoring_authority.matches%rowtype;
begin
  select value.* into strict match_value
  from scoring_authority.matches value
  where value.tournament_id = '2026' and value.match_id = target_match_id
  for update;
  perform 1
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = '2026'
    and lease.match_id = target_match_id
    and lease.expires_at > pg_catalog.clock_timestamp()
  for update;
  if not production_control.handicap_v1_match_is_unstarted(target_match_id)
     or exists (
       select 1 from scoring_authority.scoring_permissions permission
       where permission.match_id = target_match_id
         and (permission.can_score or permission.revoked_at is null
           or permission.permission_revision
             <> match_value.permission_revision)
     )
     or exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026'
         and lease.match_id = target_match_id
         and lease.expires_at > pg_catalog.clock_timestamp()
     ) then
    raise exception using errcode = '55000',
      message = 'TOURNAMENT_SETUP_MATCH_FROZEN';
  end if;
exception when no_data_found then
  raise exception using errcode = '22023',
    message = 'TOURNAMENT_SETUP_MATCH_NOT_FOUND';
end;
$$;


ALTER FUNCTION production_control.assert_tournament_setup_match_mutable_v1(target_match_id text) OWNER TO postgres;

--
-- Name: assert_tournament_setup_pairing_clear_safe_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_tournament_setup_pairing_clear_safe_v1(target_match_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  match_value scoring_authority.matches%rowtype;
begin
  select value.* into strict match_value
  from scoring_authority.matches value
  where value.tournament_id = '2026' and value.match_id = target_match_id
  for update;

  perform 1
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = '2026'
    and lease.match_id = target_match_id
    and lease.expires_at > pg_catalog.clock_timestamp()
  for update;

  if not production_control.handicap_v1_match_is_unstarted(target_match_id)
     or exists (
       select 1
       from scoring_authority.scoring_permissions permission
       where permission.match_id = target_match_id
         and (permission.can_score
           or permission.permission_revision <> match_value.permission_revision)
     )
     or exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026'
         and lease.match_id = target_match_id
         and lease.expires_at > pg_catalog.clock_timestamp()
     )
     or exists (
       select 1 from scoring_authority.finalized_scorecard_snapshots finalized
       where finalized.match_id = target_match_id
     ) then
    raise exception using errcode = '55000',
      message = 'TOURNAMENT_SETUP_PAIRING_CLEAR_UNSAFE';
  end if;
exception when no_data_found then
  raise exception using errcode = '22023',
    message = 'TOURNAMENT_SETUP_MATCH_NOT_FOUND';
end;
$$;


ALTER FUNCTION production_control.assert_tournament_setup_pairing_clear_safe_v1(target_match_id text) OWNER TO postgres;

--
-- Name: assert_tournament_setup_runtime_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_tournament_setup_runtime_v1(input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
begin
  -- Reuse the installed exact-resource, Supabase-authority, current-runtime,
  -- linked-identity, and active Director entitlement proof. Only the contract
  -- discriminator is rebound; caller authorization/resource assertions are not.
  perform production_control.assert_player_access_runtime_v1(
    input || pg_catalog.jsonb_build_object(
      'contract_version', 'production-players-access-v1'
    )
  );
  if input->>'contract_version'
       is distinct from 'production-tournament-setup-v1'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'tournament_id' is distinct from '2026' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_TOURNAMENT_SETUP_SCOPE_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_tournament_setup_runtime_v1(input jsonb) OWNER TO postgres;

--
-- Name: vercel_provider_attestation_challenges; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.vercel_provider_attestation_challenges (
    challenge_id uuid NOT NULL,
    challenge_request_id uuid NOT NULL,
    operation_request_id uuid NOT NULL,
    evidence_request_id uuid NOT NULL,
    stage text NOT NULL,
    purpose text NOT NULL,
    issue_request_fingerprint text NOT NULL,
    issue_payload_hash text NOT NULL,
    challenge_request_fingerprint text NOT NULL,
    status text DEFAULT 'ISSUED'::text NOT NULL,
    authenticated_actor_fingerprint text NOT NULL,
    vercel_project_id text NOT NULL,
    vercel_team_id text NOT NULL,
    candidate_deployment_id text NOT NULL,
    candidate_deployment_commit text NOT NULL,
    candidate_deployment_target text NOT NULL,
    candidate_alias_origin text NOT NULL,
    candidate_immutable_origin text NOT NULL,
    routing_rule_id text NOT NULL,
    routing_rule_config_version text NOT NULL,
    routing_rule_scope text NOT NULL,
    actor_id text NOT NULL,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    consumed_attestation_id uuid,
    consume_request_id uuid,
    consume_request_fingerprint text,
    consume_payload_hash text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    abandon_request_id uuid,
    abandon_request_fingerprint text,
    abandon_payload_hash text,
    abandoned_at timestamp with time zone,
    abandonment_reason text,
    CONSTRAINT production_vercel_challenge_candidate_target_v4_check CHECK ((((purpose = 'REHEARSAL'::text) AND (candidate_deployment_target = 'PREVIEW'::text)) OR ((purpose = 'CUTOVER'::text) AND (candidate_deployment_target = ANY (ARRAY['PREVIEW'::text, 'PRODUCTION'::text]))))),
    CONSTRAINT vercel_provider_attestation__authenticated_actor_fingerpr_check CHECK ((authenticated_actor_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestation__challenge_request_fingerprin_check CHECK ((challenge_request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestation_c_abandon_request_fingerprint_check CHECK (((abandon_request_fingerprint IS NULL) OR (abandon_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_provider_attestation_c_candidate_deployment_commit_check CHECK ((candidate_deployment_commit ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT vercel_provider_attestation_c_candidate_deployment_target_check CHECK ((candidate_deployment_target = ANY (ARRAY['PREVIEW'::text, 'PRODUCTION'::text]))),
    CONSTRAINT vercel_provider_attestation_c_consume_request_fingerprint_check CHECK (((consume_request_fingerprint IS NULL) OR (consume_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_provider_attestation_c_routing_rule_config_version_check CHECK ((routing_rule_config_version ~ '^[A-Za-z0-9_.:-]{1,160}$'::text)),
    CONSTRAINT vercel_provider_attestation_ch_candidate_immutable_origin_check CHECK ((candidate_immutable_origin ~ '^https://[a-z0-9.-]+$'::text)),
    CONSTRAINT vercel_provider_attestation_cha_issue_request_fingerprint_check CHECK ((issue_request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestation_chall_candidate_deployment_id_check CHECK ((candidate_deployment_id ~ '^dpl_[A-Za-z0-9]{8,64}$'::text)),
    CONSTRAINT vercel_provider_attestation_challe_candidate_alias_origin_check CHECK ((candidate_alias_origin ~ '^https://[a-z0-9.-]+$'::text)),
    CONSTRAINT vercel_provider_attestation_challeng_abandon_payload_hash_check CHECK (((abandon_payload_hash IS NULL) OR (abandon_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_provider_attestation_challeng_consume_payload_hash_check CHECK (((consume_payload_hash IS NULL) OR (consume_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_provider_attestation_challenges_abandonment_reason_check CHECK (((abandonment_reason IS NULL) OR (abandonment_reason = ANY (ARRAY['EXPIRED_UNCONSUMED_BEGIN_SUPERSEDED'::text, 'EXPIRED_UNCONSUMED_FINALIZE_SUPERSEDED'::text, 'EXPIRED_CONSUMED_UNBOUND_PROVIDER_ATTESTATION_SUPERSEDED'::text])))),
    CONSTRAINT vercel_provider_attestation_challenges_actor_id_check CHECK (((btrim(actor_id) <> ''::text) AND (length(actor_id) <= 160))),
    CONSTRAINT vercel_provider_attestation_challenges_check CHECK (((expires_at > issued_at) AND (expires_at <= (issued_at + '00:02:00'::interval)))),
    CONSTRAINT vercel_provider_attestation_challenges_check2 CHECK ((((status = 'ISSUED'::text) AND (consumed_at IS NULL) AND (consumed_attestation_id IS NULL) AND (consume_request_id IS NULL) AND (consume_request_fingerprint IS NULL) AND (consume_payload_hash IS NULL) AND (abandon_request_id IS NULL) AND (abandon_request_fingerprint IS NULL) AND (abandon_payload_hash IS NULL) AND (abandoned_at IS NULL) AND (abandonment_reason IS NULL)) OR ((status = 'CONSUMED'::text) AND (consumed_at IS NOT NULL) AND (consumed_attestation_id IS NOT NULL) AND (consume_request_id IS NOT NULL) AND (consume_request_fingerprint IS NOT NULL) AND (consume_payload_hash IS NOT NULL) AND (abandon_request_id IS NULL) AND (abandon_request_fingerprint IS NULL) AND (abandon_payload_hash IS NULL) AND (abandoned_at IS NULL) AND (abandonment_reason IS NULL)) OR ((status = 'ABANDONED'::text) AND (abandon_request_id IS NOT NULL) AND (abandon_request_fingerprint IS NOT NULL) AND (abandon_payload_hash IS NOT NULL) AND (abandoned_at IS NOT NULL) AND (((consumed_at IS NULL) AND (consumed_attestation_id IS NULL) AND (consume_request_id IS NULL) AND (consume_request_fingerprint IS NULL) AND (consume_payload_hash IS NULL) AND (abandoned_at >= expires_at) AND (((stage = 'BEGIN'::text) AND ((abandonment_reason IS NULL) OR (abandonment_reason = 'EXPIRED_UNCONSUMED_BEGIN_SUPERSEDED'::text))) OR ((stage = 'FINALIZE'::text) AND (abandonment_reason = 'EXPIRED_UNCONSUMED_FINALIZE_SUPERSEDED'::text)))) OR ((consumed_at IS NOT NULL) AND (consumed_attestation_id IS NOT NULL) AND (consume_request_id IS NOT NULL) AND (consume_request_fingerprint IS NOT NULL) AND (consume_payload_hash IS NOT NULL) AND (abandonment_reason = 'EXPIRED_CONSUMED_UNBOUND_PROVIDER_ATTESTATION_SUPERSEDED'::text)))))),
    CONSTRAINT vercel_provider_attestation_challenges_issue_payload_hash_check CHECK ((issue_payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestation_challenges_purpose_check CHECK ((purpose = ANY (ARRAY['REHEARSAL'::text, 'CUTOVER'::text]))),
    CONSTRAINT vercel_provider_attestation_challenges_routing_rule_id_check CHECK ((routing_rule_id ~ '^[A-Za-z0-9_.:-]{3,160}$'::text)),
    CONSTRAINT vercel_provider_attestation_challenges_routing_rule_scope_check CHECK ((routing_rule_scope = 'PRODUCTION_GOOGLE_CANONICAL_WRITER_QUIESCE'::text)),
    CONSTRAINT vercel_provider_attestation_challenges_stage_check CHECK ((stage = ANY (ARRAY['BEGIN'::text, 'FINALIZE'::text]))),
    CONSTRAINT vercel_provider_attestation_challenges_status_check CHECK ((status = ANY (ARRAY['ISSUED'::text, 'CONSUMED'::text, 'ABANDONED'::text]))),
    CONSTRAINT vercel_provider_attestation_challenges_vercel_project_id_check CHECK ((vercel_project_id = 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'::text)),
    CONSTRAINT vercel_provider_attestation_challenges_vercel_team_id_check CHECK ((vercel_team_id ~ '^[A-Za-z0-9_.:-]{3,160}$'::text))
);


ALTER TABLE production_control.vercel_provider_attestation_challenges OWNER TO postgres;

--
-- Name: assert_vercel_provider_challenge_abandon_binding(production_control.vercel_provider_attestation_challenges, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.assert_vercel_provider_challenge_abandon_binding(challenge production_control.vercel_provider_attestation_challenges, input jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if challenge.challenge_request_id is distinct from
       (input->>'challenge_request_id')::uuid
     or challenge.operation_request_id is distinct from
       (input->>'operation_request_id')::uuid
     or challenge.evidence_request_id is distinct from
       (input->>'evidence_request_id')::uuid
     or challenge.stage is distinct from pg_catalog.upper(input->>'stage')
     or challenge.purpose is distinct from pg_catalog.upper(input->>'purpose')
     or challenge.authenticated_actor_fingerprint is distinct from
       input->>'authenticated_actor_fingerprint'
     or challenge.actor_id is distinct from input->>'actor_id'
     or challenge.vercel_project_id is distinct from input->>'vercel_project_id'
     or challenge.vercel_team_id is distinct from input->>'vercel_team_id'
     or challenge.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or challenge.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or challenge.candidate_deployment_target is distinct from
       input->>'candidate_deployment_target'
     or challenge.candidate_alias_origin is distinct from
       pg_catalog.lower(input->>'candidate_alias_origin')
     or challenge.candidate_immutable_origin is distinct from
       pg_catalog.lower(input->>'candidate_immutable_origin')
     or challenge.routing_rule_id is distinct from input->>'routing_rule_id'
     or challenge.routing_rule_config_version is distinct from
       input->>'routing_rule_config_version'
     or challenge.routing_rule_scope is distinct from
       input->>'routing_rule_scope' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDON_BINDING_MISMATCH';
  end if;
end;
$$;


ALTER FUNCTION production_control.assert_vercel_provider_challenge_abandon_binding(challenge production_control.vercel_provider_attestation_challenges, input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_postcutover_normal_release(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.authorize_production_postcutover_normal_release(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  head production_control.postcutover_normal_release_head%rowtype;
  predecessor
    production_control.postcutover_normal_release_rebindings%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  binding
    production_control.maintenance_deployment_capability_bindings%rowtype;
  existing production_control.postcutover_normal_release_intents%rowtype;
  annual_context jsonb;
  target_sequence bigint;
  manifest jsonb;
  manifest_fingerprint text;
  payload_hash text := production_control.cutover_payload_hash(input);
  response_value jsonb;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  if pointer.tournament_id = '2026' then
    return production_control
      .authorize_production_postcutover_normal_release_frozen_2026_v1(input);
  end if;

  if not pg_catalog.pg_has_role(session_user, current_user, 'USAGE') then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DATABASE_OWNER_REQUIRED';
  end if;
  if input->>'operation' is distinct from
       'AUTHORIZE_PRODUCTION_POSTCUTOVER_NORMAL_RELEASE'
     or pg_catalog.upper(coalesce(input->>'environment', '')) <> 'PRODUCTION'
     or input->>'project_ref' is distinct from 'ymqhhtxaywtqllynrmxe'
     or input->>'project_url' is distinct from
       'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or input->>'source_workbook_id' is distinct from
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or input->>'tournament_id' is distinct from '2026'
     or coalesce(input->>'target_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'expected_predecessor_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'expected_predecessor_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'expected_authority_generation', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_admission_generation', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_current_tournament_id', '')
       !~ '^[0-9]{4}$'
     or pg_catalog.jsonb_typeof(input->'expected_pointer_revision')
       is distinct from 'number'
     or coalesce(input->>'expected_pointer_revision', '') !~ '^[0-9]+$'
     or coalesce(input->>'expected_runtime_generation_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_annual_authority_generation_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_annual_admission_generation_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or pg_catalog.jsonb_typeof(input->'expected_activation_revision')
       is distinct from 'number'
     or coalesce(input->>'expected_activation_revision', '') !~ '^[0-9]+$'
     or pg_catalog.jsonb_typeof(input->'expected_admission_revision')
       is distinct from 'number'
     or coalesce(input->>'expected_admission_revision', '') !~ '^[0-9]+$'
     or (input ? 'expected_release_sequence' and (
       pg_catalog.jsonb_typeof(input->'expected_release_sequence')
         is distinct from 'number'
       or coalesce(input->>'expected_release_sequence', '') !~ '^[0-9]+$'
     )) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INTENT_INVALID';
  end if;

  perform production_control.bootstrap_postcutover_normal_release_baseline();
  select value.* into strict head
  from production_control.postcutover_normal_release_head value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict predecessor
  from production_control.postcutover_normal_release_rebindings value
  where value.release_rebind_id = head.release_rebind_id;
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select value.* into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = gate.active_epoch_id;
  select value.* into strict binding
  from production_control.maintenance_deployment_capability_bindings value
  where value.capability_binding_id = predecessor.capability_binding_id;
  annual_context :=
    production_control.postcutover_annual_release_context_v1();
  target_sequence := head.release_sequence + 1;
  manifest := production_control.postcutover_annual_release_manifest_v1(
    target_sequence, predecessor.release_rebind_id,
    head.deployment_id, head.deployment_commit,
    input->>'target_deployment_commit', activation.activation_revision,
    gate.admission_revision, epoch.epoch_id,
    activation.authority_generation_id, gate.admission_generation_id,
    binding.capability_binding_id, binding.contract_version,
    binding.capability_ceiling, annual_context
  );
  manifest_fingerprint := pg_catalog.encode(
    extensions.digest(manifest::text, 'sha256'), 'hex'
  );

  select value.* into existing
  from production_control.postcutover_normal_release_intents value
  where value.request_fingerprint = input->>'request_fingerprint';
  if found then
    if existing.payload_hash is distinct from payload_hash
       or existing.authorization_fingerprint is distinct from
         manifest_fingerprint then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INTENT_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_AUTHORIZED',
      'release_intent_id', existing.release_intent_id,
      'release_sequence', existing.release_sequence,
      'target_deployment_commit', existing.target_deployment_commit,
      'status', existing.status,
      'authorization_fingerprint', existing.authorization_fingerprint,
      'idempotent', true
    );
  end if;

  if (input ? 'expected_release_sequence' and
       (input->>'expected_release_sequence')::bigint <> target_sequence)
     or input->>'expected_current_tournament_id' is distinct from
       annual_context->>'tournamentId'
     or (input->>'expected_pointer_revision')::bigint <>
       (annual_context->>'pointerRevision')::bigint
     or pg_catalog.lower(input->>'expected_runtime_generation_id')
       is distinct from pg_catalog.lower(
         annual_context->>'runtimeGenerationId'
       )
     or pg_catalog.lower(input->>'expected_annual_authority_generation_id')
       is distinct from pg_catalog.lower(
         annual_context->>'annualAuthorityGenerationId'
       )
     or pg_catalog.lower(input->>'expected_annual_admission_generation_id')
       is distinct from pg_catalog.lower(
         annual_context->>'annualAdmissionGenerationId'
       )
     or input->>'expected_predecessor_deployment_id' is distinct from
       head.deployment_id
     or input->>'expected_predecessor_deployment_commit' is distinct from
       head.deployment_commit
     or activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.read_cutover_phase <> 'OBSERVATION'
     or activation.current_authority <> 'SUPABASE'
     or activation.maintenance_state <> 'NORMAL'
     or not activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.expected_deployment_commit is distinct from
       head.deployment_commit
     or activation.activation_revision <>
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.google_workbook_id <>
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_read_authority <> 'SUPABASE'
     or resource.scoring_authority <> 'SUPABASE'
     or resource.participant_identity_authority <> 'SUPABASE'
     or resource.odds_publication_authority <> 'SUPABASE'
     or not resource.odds_publication_enabled
     or not resource.public_supabase_reads_enabled
     or not resource.scoring_ingress_enabled
     or not resource.workers_enabled
     or resource.google_writes_enabled
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'SUPABASE'
     or gate.state <> 'OPEN'
     or gate.admission_state <> 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision <>
       (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from head.deployment_id
     or gate.unresolved_client_queues <> 0
     or binding.contract_version <>
       'production-maintenance-single-deployment-capability-v1'
     or binding.capability_ceiling <> 'OBSERVATION'
     or exists (
       select 1 from production_control.postcutover_normal_release_intents value
       where value.scope_key = 'BAGGER_INV_PRODUCTION'
         and value.status = 'PENDING'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INTENT_NOT_SAFE';
  end if;
  perform production_control.assert_no_active_physical_writer_fence();

  insert into production_control.postcutover_normal_release_intents (
    scope_key, contract_version, status, release_sequence,
    predecessor_release_rebind_id, predecessor_deployment_id,
    predecessor_deployment_commit, target_deployment_commit,
    epoch_id, authority_generation_id, admission_generation_id,
    capability_binding_id, capability_contract, capability_ceiling,
    expected_activation_revision, expected_admission_revision,
    authorization_manifest, authorization_fingerprint,
    request_fingerprint, payload_hash, authorized_by
  ) values (
    'BAGGER_INV_PRODUCTION',
    'production-postcutover-normal-release-intent-v1', 'PENDING',
    target_sequence, predecessor.release_rebind_id,
    head.deployment_id, head.deployment_commit,
    input->>'target_deployment_commit', epoch.epoch_id,
    activation.authority_generation_id, gate.admission_generation_id,
    binding.capability_binding_id, binding.contract_version,
    binding.capability_ceiling, activation.activation_revision,
    gate.admission_revision, manifest, manifest_fingerprint,
    input->>'request_fingerprint', payload_hash,
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into existing;

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_AUTHORIZED',
    'release_intent_id', existing.release_intent_id,
    'release_sequence', existing.release_sequence,
    'target_deployment_commit', existing.target_deployment_commit,
    'status', existing.status,
    'authorization_fingerprint', existing.authorization_fingerprint,
    'current_tournament_id', annual_context->>'tournamentId',
    'runtime_generation_id', annual_context->>'runtimeGenerationId',
    'idempotent', false
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_AUTHORIZED',
    'APPLICATION_RELEASE', annual_context->>'tournamentId',
    pg_catalog.left(input->>'actor_id', 160),
    input->>'request_fingerprint', 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  return response_value;
exception
  when no_data_found or too_many_rows or invalid_text_representation
    or numeric_value_out_of_range then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INTENT_NOT_SAFE';
end;
$_$;


ALTER FUNCTION production_control.authorize_production_postcutover_normal_release(input jsonb) OWNER TO postgres;

