     or gate.state <> 'OPEN'
     or gate.admission_state <> 'CLOSED'
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_revision is distinct from head.admission_revision
     or gate.admission_deployment_id is distinct from head.deployment_id
     or gate.unresolved_client_queues <> 0
     or epoch.status <> 'COMMITTED'
     or epoch.epoch_id is distinct from activation.authority_generation_id
     or binding.contract_version <>
       'production-maintenance-single-deployment-capability-v1'
     or binding.capability_ceiling <> 'OBSERVATION'
     or exists (
       select 1
       from production_control.postcutover_normal_release_intents value
       where value.scope_key = 'BAGGER_INV_PRODUCTION'
         and value.status = 'PENDING'
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INTENT_NOT_SAFE';
  end if;
  perform production_control.assert_no_active_physical_writer_fence();

  insert into production_control.postcutover_normal_release_intents (
    scope_key, contract_version, status, release_sequence,
    predecessor_release_rebind_id, predecessor_deployment_id,
    predecessor_deployment_commit, target_deployment_commit,
    epoch_id, authority_generation_id, admission_generation_id,
    capability_binding_id, capability_contract, capability_ceiling,
    expected_activation_revision, expected_admission_revision,
    authorization_manifest, authorization_fingerprint,
    request_fingerprint, payload_hash, authorized_by
  ) values (
    'BAGGER_INV_PRODUCTION',
    'production-postcutover-normal-release-intent-v1', 'PENDING',
    target_sequence, predecessor.release_rebind_id,
    head.deployment_id, head.deployment_commit,
    input->>'target_deployment_commit', epoch.epoch_id,
    activation.authority_generation_id, gate.admission_generation_id,
    binding.capability_binding_id, binding.contract_version,
    binding.capability_ceiling, activation.activation_revision,
    gate.admission_revision, manifest, manifest_fingerprint,
    input->>'request_fingerprint', payload_hash,
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into existing;

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_AUTHORIZED',
    'release_intent_id', existing.release_intent_id,
    'release_sequence', existing.release_sequence,
    'target_deployment_commit', existing.target_deployment_commit,
    'status', existing.status,
    'authorization_fingerprint', existing.authorization_fingerprint,
    'idempotent', false
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_AUTHORIZED',
    'APPLICATION_RELEASE', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    input->>'request_fingerprint', 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.authorize_production_postcutover_normal_release_frozen_2026_v1(input jsonb) OWNER TO postgres;

--
-- Name: bind_current_vercel_routing_rule_audit(text, uuid, boolean, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.bind_current_vercel_routing_rule_audit(target_subject_kind text, target_subject_id uuid, create_if_missing boolean, audit_input jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  normalized_kind text := pg_catalog.upper(target_subject_kind);
  binding jsonb;
begin
  if target_subject_id is null
     or normalized_kind not in ('CHALLENGE', 'ATTESTATION', 'QUIESCE') then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_ROUTING_RULE_AUDIT_SUBJECT_INVALID';
  end if;

  if create_if_missing then
    perform production_control.assert_exact_vercel_routing_rule_audit(audit_input);
    if normalized_kind = 'CHALLENGE' then
      if not exists (
        select 1
        from production_control.vercel_provider_attestation_challenges value
        where value.challenge_id = target_subject_id
      ) then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_VERCEL_ROUTING_RULE_AUDIT_SUBJECT_MISSING';
      end if;
      insert into production_control.vercel_routing_rule_audit_bindings (
        subject_kind, challenge_id, routing_rule_hostname_operator,
        routing_rule_canonical_hostname,
        routing_rule_earlier_active_bypass_rule_count,
        routing_rule_global_invocation_quiescence_proved,
        routing_rule_candidate_control_host_count,
        routing_rule_candidate_control_hosts_fingerprint,
        routing_rule_canonical_apex_safe_method_count,
        routing_rule_canonical_apex_safe_methods_fingerprint,
        routing_rule_canonical_apex_safe_method_writer_route_count,
        routing_rule_canonical_apex_safe_method_writer_routes_fingerprint
      ) values (
        normalized_kind, target_subject_id, 'DOES_NOT_EQUAL',
        'baggerinv.com', 0, true, 2,
        pg_catalog.lower(audit_input->>'routing_rule_candidate_control_hosts_fingerprint'),
        3,
        '798954f7a6aab53443a1fac2333ce7043f7c5c5bf5bdbffdfdd19f18433e96e7',
        10,
        '8f3bcfaf2b8fd6825ce5fb56385b1a1aa2e23da7bfe96b42e7e9c3ec23f4bcd7'
      ) on conflict (challenge_id) do nothing;
    elsif normalized_kind = 'ATTESTATION' then
      if not exists (
        select 1
        from production_control.vercel_provider_attestations value
        where value.attestation_id = target_subject_id
      ) then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_VERCEL_ROUTING_RULE_AUDIT_SUBJECT_MISSING';
      end if;
      insert into production_control.vercel_routing_rule_audit_bindings (
        subject_kind, attestation_id, routing_rule_hostname_operator,
        routing_rule_canonical_hostname,
        routing_rule_earlier_active_bypass_rule_count,
        routing_rule_global_invocation_quiescence_proved,
        routing_rule_candidate_control_host_count,
        routing_rule_candidate_control_hosts_fingerprint,
        routing_rule_canonical_apex_safe_method_count,
        routing_rule_canonical_apex_safe_methods_fingerprint,
        routing_rule_canonical_apex_safe_method_writer_route_count,
        routing_rule_canonical_apex_safe_method_writer_routes_fingerprint
      ) values (
        normalized_kind, target_subject_id, 'DOES_NOT_EQUAL',
        'baggerinv.com', 0, true, 2,
        pg_catalog.lower(audit_input->>'routing_rule_candidate_control_hosts_fingerprint'),
        3,
        '798954f7a6aab53443a1fac2333ce7043f7c5c5bf5bdbffdfdd19f18433e96e7',
        10,
        '8f3bcfaf2b8fd6825ce5fb56385b1a1aa2e23da7bfe96b42e7e9c3ec23f4bcd7'
      ) on conflict (attestation_id) do nothing;
    else
      if not exists (
        select 1
        from production_control.vercel_writer_quiesce_evidence value
        where value.evidence_id = target_subject_id
      ) then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_VERCEL_ROUTING_RULE_AUDIT_SUBJECT_MISSING';
      end if;
      insert into production_control.vercel_routing_rule_audit_bindings (
        subject_kind, quiesce_evidence_id,
        routing_rule_hostname_operator, routing_rule_canonical_hostname,
        routing_rule_earlier_active_bypass_rule_count,
        routing_rule_global_invocation_quiescence_proved,
        routing_rule_candidate_control_host_count,
        routing_rule_candidate_control_hosts_fingerprint,
        routing_rule_canonical_apex_safe_method_count,
        routing_rule_canonical_apex_safe_methods_fingerprint,
        routing_rule_canonical_apex_safe_method_writer_route_count,
        routing_rule_canonical_apex_safe_method_writer_routes_fingerprint
      ) values (
        normalized_kind, target_subject_id, 'DOES_NOT_EQUAL',
        'baggerinv.com', 0, true, 2,
        pg_catalog.lower(audit_input->>'routing_rule_candidate_control_hosts_fingerprint'),
        3,
        '798954f7a6aab53443a1fac2333ce7043f7c5c5bf5bdbffdfdd19f18433e96e7',
        10,
        '8f3bcfaf2b8fd6825ce5fb56385b1a1aa2e23da7bfe96b42e7e9c3ec23f4bcd7'
      ) on conflict (quiesce_evidence_id) do nothing;
    end if;
  end if;

  select pg_catalog.jsonb_build_object(
    'routing_rule_hostname_operator', value.routing_rule_hostname_operator,
    'routing_rule_canonical_hostname', value.routing_rule_canonical_hostname,
    'routing_rule_earlier_active_bypass_rule_count',
      value.routing_rule_earlier_active_bypass_rule_count,
    'routing_rule_global_invocation_quiescence_proved',
      value.routing_rule_global_invocation_quiescence_proved,
    'routing_rule_candidate_control_host_count',
      value.routing_rule_candidate_control_host_count,
    'routing_rule_candidate_control_hosts_fingerprint',
      value.routing_rule_candidate_control_hosts_fingerprint,
    'routing_rule_canonical_apex_safe_method_count',
      value.routing_rule_canonical_apex_safe_method_count,
    'routing_rule_canonical_apex_safe_methods_fingerprint',
      value.routing_rule_canonical_apex_safe_methods_fingerprint,
    'routing_rule_canonical_apex_safe_method_writer_route_count',
      value.routing_rule_canonical_apex_safe_method_writer_route_count,
    'routing_rule_canonical_apex_safe_method_writer_routes_fingerprint',
      value.routing_rule_canonical_apex_safe_method_writer_routes_fingerprint
  ) into binding
  from production_control.vercel_routing_rule_audit_bindings value
  where (normalized_kind = 'CHALLENGE'
      and value.challenge_id = target_subject_id)
     or (normalized_kind = 'ATTESTATION'
      and value.attestation_id = target_subject_id)
     or (normalized_kind = 'QUIESCE'
      and value.quiesce_evidence_id = target_subject_id);

  if binding is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_ROUTING_RULE_AUDIT_BINDING_MISSING';
  end if;
  if audit_input is not null and (
       binding->>'routing_rule_hostname_operator' is distinct from
         audit_input->>'routing_rule_hostname_operator'
       or binding->>'routing_rule_canonical_hostname' is distinct from
         audit_input->>'routing_rule_canonical_hostname'
       or binding->>'routing_rule_earlier_active_bypass_rule_count' is distinct from
         audit_input->>'routing_rule_earlier_active_bypass_rule_count'
       or binding->'routing_rule_global_invocation_quiescence_proved' is distinct from
         audit_input->'routing_rule_global_invocation_quiescence_proved'
       or binding->>'routing_rule_candidate_control_host_count' is distinct from
         audit_input->>'routing_rule_candidate_control_host_count'
       or binding->>'routing_rule_candidate_control_hosts_fingerprint' is distinct from
         pg_catalog.lower(audit_input->>'routing_rule_candidate_control_hosts_fingerprint')
       or binding->>'routing_rule_canonical_apex_safe_method_count' is distinct from
         audit_input->>'routing_rule_canonical_apex_safe_method_count'
       or binding->>'routing_rule_canonical_apex_safe_methods_fingerprint' is distinct from
         audit_input->>'routing_rule_canonical_apex_safe_methods_fingerprint'
       or binding->>'routing_rule_canonical_apex_safe_method_writer_route_count'
         is distinct from
           audit_input->>'routing_rule_canonical_apex_safe_method_writer_route_count'
       or binding->>'routing_rule_canonical_apex_safe_method_writer_routes_fingerprint'
         is distinct from
           audit_input->>'routing_rule_canonical_apex_safe_method_writer_routes_fingerprint'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_ROUTING_RULE_AUDIT_REPLAY_MISMATCH';
  end if;
  return binding;
end;
$$;


ALTER FUNCTION production_control.bind_current_vercel_routing_rule_audit(target_subject_kind text, target_subject_id uuid, create_if_missing boolean, audit_input jsonb) OWNER TO postgres;

--
-- Name: bind_future_participant_identity_runtime_v1(text, uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.bind_future_participant_identity_runtime_v1(target_tournament_id text, target_runtime_generation_id uuid, target_authority_generation_id uuid, target_admission_generation_id uuid, target_actor_player_id text, target_actor_auth_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  resource production_control.resource_scope%rowtype;
  resource_context jsonb;
  provenance_value text;
  identity_source_system text := 'PRODUCTION_FUTURE_RUNTIME_BINDING';
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  source_context participant_identity.identity_context_revisions%rowtype;
  source_run participant_identity.identity_config_import_runs%rowtype;
  existing participant_identity.future_tournament_identity_contexts_v1%rowtype;
  roster_count_value integer;
  contact_count_value integer;
  enrolled_count_value integer;
  not_enrolled_count_value integer;
  binding_fingerprint_value text;
  source_manifest jsonb;
begin
  perform production_control.assert_production_service_role();
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION') then
    resource_context:=production_control.annual_resource_context_v2();
    if resource_context->>'resource_class' is distinct from 'CERTIFICATION'
      or resource_context->>'provenance_id' is distinct from 'urn:bagger:synthetic:'||(resource_context->>'installation_id') then
      raise exception using errcode='42501',message='FUTURE_PARTICIPANT_IDENTITY_RESOURCE_MISMATCH';end if;
    provenance_value:=resource_context->>'provenance_id';
    identity_source_system:='CERTIFICATION_FUTURE_RUNTIME_BINDING';
    select value.* into strict pointer from production_control.current_tournament_pointer_v1 value
     where value.scope_key=resource_context->>'resource_id';
  else
    select value.* into strict resource
    from production_control.resource_scope value
    where value.scope_key = 'BAGGER_INV_PRODUCTION';
    select value.* into strict pointer
    from production_control.current_tournament_pointer_v1 value
    where value.scope_key = 'BAGGER_INV_PRODUCTION';
    provenance_value:=resource.google_workbook_id;
  end if;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pg_catalog.btrim(target_tournament_id)
  for update;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = catalog.tournament_id
    and value.runtime_generation_id = target_runtime_generation_id
  for update;
  if catalog.tournament_year <= 2026
     or catalog.lifecycle <> 'READY_FOR_ACTIVATION'
     or pointer.tournament_id = catalog.tournament_id
     or generation.generation_status <> 'PREPARED'
     or generation.pointer_revision <> pointer.pointer_revision + 1
     or generation.authority_generation_id
       <> target_authority_generation_id
     or generation.admission_generation_id
       <> target_admission_generation_id
     or target_runtime_generation_id in (
       target_authority_generation_id, target_admission_generation_id
     )
     or target_authority_generation_id = target_admission_generation_id
     or generation.authority <> 'SUPABASE'
     or generation.ingress_state <> 'OPEN'
     or target_actor_player_id is null
     or target_actor_auth_user_id is null then
    raise exception using errcode = '55000',
      message = 'FUTURE_PARTICIPANT_IDENTITY_BINDING_SCOPE_INVALID';
  end if;
  if resource_context is null and (resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.project_url <> 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or pg_catalog.btrim(coalesce(resource.google_workbook_id, '')) = '') then
    raise exception using errcode = '42501',
      message = 'FUTURE_PARTICIPANT_IDENTITY_RESOURCE_MISMATCH';
  end if;

  select value.* into strict source_context
  from participant_identity.identity_context_revisions value
  where value.tournament_id = '2026';
  select value.* into strict source_run
  from participant_identity.identity_config_import_runs value
  where value.tournament_id = '2026'
    and value.configuration_revision = source_context.context_revision
    and value.source_fingerprint = source_context.configuration_fingerprint
    and value.status = 'APPROVED'
    and value.approved_at is not null
  order by value.approved_at desc, value.requested_at desc
  limit 1;
  if source_context.configuration_fingerprint !~ '^[0-9a-f]{64}$'
     or source_run.source_workbook_id is distinct from
       provenance_value then
    raise exception using errcode = '55000',
      message = 'FUTURE_PARTICIPANT_IDENTITY_SOURCE_NOT_CERTIFIED';
  end if;

  select pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter (
      where eligibility.contact_approved
    )::integer,
    pg_catalog.count(*) filter (
      where eligibility.linked_verified
    )::integer
  into roster_count_value, contact_count_value, enrolled_count_value
  from production_control.future_participant_identity_eligibility_v1(
    catalog.tournament_id
  ) eligibility;
  not_enrolled_count_value := roster_count_value - enrolled_count_value;
  if roster_count_value < 1 or contact_count_value < 1 then
    raise exception using errcode = '55000',
      message = 'FUTURE_PARTICIPANT_IDENTITY_APPROVED_ROSTER_REQUIRED';
  end if;
  if not exists (
    select 1
    from production_control.future_global_owner_eligibility_v1() owner_value
    where owner_value.player_id = target_actor_player_id
      and owner_value.auth_user_id = target_actor_auth_user_id
  ) then
    raise exception using errcode = '42501',
      message = 'FUTURE_PARTICIPANT_IDENTITY_OWNER_REQUIRED';
  end if;
  if not exists (
    select 1
    from production_control.future_participant_identity_eligibility_v1(
      catalog.tournament_id
    ) eligibility
    join production_control.director_entitlements entitlement
      on entitlement.tournament_id = catalog.tournament_id
     and entitlement.player_id = eligibility.player_id
     and entitlement.auth_user_id = eligibility.auth_user_id
     and entitlement.role = 'DIRECTOR'
     and entitlement.status = 'ACTIVE'
     and entitlement.revoked_at is null
    join participant_identity.tournament_roles role_value
      on role_value.tournament_id = entitlement.tournament_id
     and role_value.auth_user_id = entitlement.auth_user_id
     and role_value.role = 'DIRECTOR'
     and role_value.role_active
     and role_value.revoked_at is null
    where eligibility.linked_verified
  ) then
    raise exception using errcode = '55000',
      message = 'FUTURE_PARTICIPANT_IDENTITY_DIRECTOR_REQUIRED';
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'playerId', eligibility.player_id,
      'contactState', case when eligibility.contact_approved
        then 'APPROVED' else 'MISSING' end,
      'state', case when eligibility.linked_verified
        then 'ENROLLED' else 'NOT_ENROLLED' end,
      'sourceContactFingerprint', case when eligibility.contact_approved
        then eligibility.source_contact_fingerprint else null end,
      'linkRevision', case when eligibility.linked_verified
        then eligibility.link_revision else null end
    ) order by eligibility.player_id
  ), '[]'::jsonb)
  into source_manifest
  from production_control.future_participant_identity_eligibility_v1(
    catalog.tournament_id
  ) eligibility;
  binding_fingerprint_value := encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.jsonb_build_object(
      'contract', 'production-future-participant-identity-context-v1',
      'tournamentId', catalog.tournament_id,
      'runtimeGenerationId', target_runtime_generation_id,
      'authorityGenerationId', target_authority_generation_id,
      'admissionGenerationId', target_admission_generation_id,
      'pointerRevision', generation.pointer_revision,
      'sourceTournamentId', '2026',
      'sourceContextRevision', source_context.context_revision,
      'sourceConfigurationFingerprint',
        source_context.configuration_fingerprint,
      'roster', source_manifest
    )::text, 'UTF8'), 'sha256'), 'hex');

  select value.* into existing
  from participant_identity.future_tournament_identity_contexts_v1 value
  where value.tournament_id = catalog.tournament_id;
  if existing.tournament_id is not null then
    if existing.runtime_generation_id <> target_runtime_generation_id
       or existing.authority_generation_id
         <> target_authority_generation_id
       or existing.admission_generation_id
         <> target_admission_generation_id
       or existing.pointer_revision <> generation.pointer_revision
       or existing.binding_fingerprint <> binding_fingerprint_value
       or existing.roster_count <> roster_count_value
       or existing.enrolled_count <> enrolled_count_value
       or existing.not_enrolled_count <> not_enrolled_count_value then
      raise exception using errcode = '40001',
        message = 'FUTURE_PARTICIPANT_IDENTITY_BINDING_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'tournamentId', catalog.tournament_id,
      'rosterCount', existing.roster_count,
      'approvedContactCount', contact_count_value,
      'enrolledCount', existing.enrolled_count,
      'notEnrolledCount', existing.not_enrolled_count,
      'bindingRevision', existing.binding_revision,
      'bindingFingerprint', existing.binding_fingerprint,
      'idempotent', true
    );
  end if;

  insert into participant_identity.future_tournament_identity_contexts_v1 (
    tournament_id, contract_version, binding_revision,
    source_identity_tournament_id, source_context_revision,
    source_configuration_fingerprint, binding_fingerprint,
    roster_count, enrolled_count, not_enrolled_count, status,
    certified_by_player_id, certified_by_auth_user_id,
    runtime_generation_id, authority_generation_id,
    admission_generation_id, pointer_revision
  ) values (
    catalog.tournament_id,
    'production-future-participant-identity-context-v1',
    1, '2026', source_context.context_revision,
    source_context.configuration_fingerprint, binding_fingerprint_value,
    roster_count_value, enrolled_count_value, not_enrolled_count_value,
    'CERTIFIED', target_actor_player_id, target_actor_auth_user_id,
    target_runtime_generation_id, target_authority_generation_id,
    target_admission_generation_id, generation.pointer_revision
  );

  insert into participant_identity.future_tournament_participant_bindings_v1 (
    tournament_id, player_id, enrollment_state, contact_state,
    source_identity_tournament_id, source_configuration_revision,
    source_contact_fingerprint, bound_link_revision, binding_revision
  )
  select catalog.tournament_id, eligibility.player_id,
    case when eligibility.linked_verified
      then 'ENROLLED' else 'NOT_ENROLLED' end,
    case when eligibility.contact_approved
      then 'APPROVED' else 'MISSING' end,
    case when eligibility.contact_approved then '2026' else null end,
    case when eligibility.contact_approved
      then eligibility.source_configuration_revision else null end,
    case when eligibility.contact_approved
      then eligibility.source_contact_fingerprint else null end,
    case when eligibility.linked_verified
      then eligibility.link_revision else null end,
    1
  from production_control.future_participant_identity_eligibility_v1(
    catalog.tournament_id
  ) eligibility;

  insert into participant_identity.identity_context_revisions (
    tournament_id, context_revision, configuration_fingerprint, updated_by
  ) values (
    catalog.tournament_id, 1, binding_fingerprint_value,
    'future-runtime-identity-binding-v2'
  );
  insert into participant_identity.identity_config_import_runs (
    tournament_id, source_system, source_workbook_id,
    source_fingerprint, configuration_revision, status,
    roster_count, received_count, valid_count, missing_count,
    duplicate_count, malformed_count, shared_count, inactive_count,
    unknown_player_count, mapping_conflict_count, validation_report,
    requested_by, approved_by, approved_at
  ) values (
    catalog.tournament_id, identity_source_system,
    provenance_value, binding_fingerprint_value, 1, 'APPROVED',
    roster_count_value, contact_count_value, contact_count_value,
    roster_count_value - contact_count_value, 0, 0, 0, 0, 0, 0,
    pg_catalog.jsonb_build_object(
      'contractVersion',
        'production-future-participant-identity-context-v1',
      'partialRosterPolicy', true,
      'approvedContactCount', contact_count_value,
      'linkedVerifiedCount', enrolled_count_value,
      'controlledFirstLoginEligibleCount',
        contact_count_value - enrolled_count_value,
      'rawIdentifiersStoredInReport', false
    ), 'future-runtime-identity-binding-v2', target_actor_player_id,
    pg_catalog.clock_timestamp()
  );
  insert into participant_identity.participant_identity_contacts (
    tournament_id, player_id, email, email_normalized, identity_active,
    configuration_revision, verified_by, verified_at, source_system,
    source_workbook_id, source_updated_at
  )
  select catalog.tournament_id, eligibility.player_id,
    eligibility.source_email, eligibility.source_email_normalized, true, 1,
    'future-runtime-identity-binding-v2', pg_catalog.clock_timestamp(),
    identity_source_system, provenance_value,
    eligibility.source_updated_at
  from production_control.future_participant_identity_eligibility_v1(
    catalog.tournament_id
  ) eligibility
  where eligibility.contact_approved;

  insert into participant_identity.tournament_roles (
    tournament_id, auth_user_id, role, role_active, granted_by
  )
  select catalog.tournament_id, eligibility.auth_user_id,
    'PARTICIPANT', true, 'future-runtime-identity-binding-v2'
  from production_control.future_participant_identity_eligibility_v1(
    catalog.tournament_id
  ) eligibility
  where eligibility.linked_verified
  on conflict (tournament_id, auth_user_id, role) do update set
    role_active = true, revoked_at = null, revoked_by = null,
    role_revision = participant_identity.tournament_roles.role_revision + 1,
    updated_at = pg_catalog.clock_timestamp();

  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, player_id, actor_id, actor_name,
    configuration_revision, safe_metadata
  ) values (
    'FUTURE_TOURNAMENT_IDENTITY_RUNTIME_BOUND', catalog.tournament_id,
    target_actor_player_id, target_actor_player_id,
    'future-runtime-owner-activation-v2', 1,
    pg_catalog.jsonb_build_object(
      'contractVersion',
        'production-future-participant-identity-context-v1',
      'rosterCount', roster_count_value,
      'approvedContactCount', contact_count_value,
      'enrolledCount', enrolled_count_value,
      'notEnrolledCount', not_enrolled_count_value,
      'controlledFirstLoginEligibleCount',
        contact_count_value - enrolled_count_value,
      'rawIdentifiersStoredInAudit', false,
      'authUsersCreated', false,
      'ownerAddedToAnnualRoster', false,
      'futureDirectorEntitlementCloned', false
    ) || case when resource_context is null then '{}'::jsonb else pg_catalog.jsonb_build_object(
      'resourceClass','CERTIFICATION','resourceId',resource_context->>'resource_id',
      'installationId',resource_context->>'installation_id','provenanceId',provenance_value) end
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'tournamentId', catalog.tournament_id,
    'rosterCount', roster_count_value,
    'approvedContactCount', contact_count_value,
    'enrolledCount', enrolled_count_value,
    'notEnrolledCount', not_enrolled_count_value,
    'bindingRevision', 1,
    'bindingFingerprint', binding_fingerprint_value,
    'idempotent', false
  );
end;
$_$;


ALTER FUNCTION production_control.bind_future_participant_identity_runtime_v1(target_tournament_id text, target_runtime_generation_id uuid, target_authority_generation_id uuid, target_admission_generation_id uuid, target_actor_player_id text, target_actor_auth_user_id uuid) OWNER TO postgres;

--
-- Name: bind_pending_annual_jobs_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.bind_pending_annual_jobs_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.generation_status = 'ACTIVE'
     and old.generation_status is distinct from 'ACTIVE' then
    -- Google runtime retired: external delivery is not canonical authority.
    -- Google runtime retired: external delivery is not canonical authority.
    update scoring_authority.competition_recalculation_jobs set
      runtime_generation_id = new.runtime_generation_id,
      status = 'PENDING', started_at = null, completed_at = null,
      claim_token = null, claimed_by = null, lease_expires_at = null,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = new.tournament_id
      and runtime_generation_id is null;
    update scoring_authority.net_skins_v1_recalculation_jobs set
      runtime_generation_id = new.runtime_generation_id
    where tournament_id = new.tournament_id
      and runtime_generation_id is null;
    update scoring_authority.calcutta_v1_recalculation_jobs set
      runtime_generation_id = new.runtime_generation_id
    where tournament_id = new.tournament_id
      and runtime_generation_id is null;
    update scoring_authority.odds_calculation_jobs set
      runtime_generation_id = new.runtime_generation_id
    where tournament_id = new.tournament_id
      and runtime_generation_id is null;
    -- Google runtime retired: external delivery is not canonical authority.
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.bind_pending_annual_jobs_v1() OWNER TO postgres;

--
-- Name: bind_production_maintenance_release_candidate(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.bind_production_maintenance_release_candidate(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  prior_binding production_control.maintenance_release_candidates%rowtype;
  target_release text := pg_catalog.lower(
    coalesce(input->>'deployment_commit', '')
  );
begin
  if not pg_catalog.pg_has_role(session_user, current_user, 'USAGE') then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DATABASE_OWNER_REQUIRED';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select value.* into prior_binding
  from production_control.maintenance_release_candidates value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;

  if prior_binding.binding_id is not null
     and (prior_binding.release_sha is distinct from target_release
       or prior_binding.candidate_deployment_id is distinct from
         input->>'deployment_id')
  then
    if activation.state <> 'DORMANT'
       or activation.current_authority <> 'GOOGLE'
       or activation.maintenance_state <> 'NORMAL'
       or activation.expected_deployment_commit is not null
       or activation.active_transition_epoch_id is not null
       or activation.first_supabase_write_possible_at is not null
       or activation.first_supabase_write_observed_at is not null
       or resource.current_tournament_read_authority <> 'GOOGLE'
       or resource.scoring_authority <> 'GOOGLE'
       or resource.participant_identity_authority <> 'PASSPORT'
       or resource.public_supabase_reads_enabled
       or resource.scoring_ingress_enabled
       or resource.workers_enabled
       or resource.google_writes_enabled
       or resource.odds_publication_enabled
       or gate.authority <> 'GOOGLE'
       or gate.state not in ('OPEN', 'PAUSED')
       or gate.admission_state <> 'OPEN'
       or exists (
         select 1
         from scoring_authority.authority_epochs epoch
         where epoch.tournament_id = '2026'
           and epoch.status in ('PREPARED', 'COMMITTED')
       )
       or exists (
         select 1
         from production_control.maintenance_runtime_deployment_rebindings value
         where value.deployment_commit = prior_binding.release_sha
       )
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_RELEASE_SUPERSESSION_NOT_SAFE';
    end if;
    insert into production_control.maintenance_release_candidate_history (
      original_binding_id, archived_binding,
      superseded_by_release_sha, superseded_by_candidate_deployment_id,
      superseded_by_actor
    ) values (
      prior_binding.binding_id, pg_catalog.to_jsonb(prior_binding),
      target_release, input->>'deployment_id',
      pg_catalog.left(input->>'actor_id', 160)
    );
    delete from production_control.maintenance_release_candidates
    where binding_id = prior_binding.binding_id;
  end if;

  return production_control
    .bind_production_maintenance_release_candidate_pre_capability(input);
end;
$$;


ALTER FUNCTION production_control.bind_production_maintenance_release_candidate(input jsonb) OWNER TO postgres;

--
-- Name: bind_production_maintenance_release_candidate_pre_capability(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.bind_production_maintenance_release_candidate_pre_capability(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  resource production_control.resource_scope%rowtype;
  legacy_provenance jsonb;
  prior_binding production_control.maintenance_release_candidates%rowtype;
  binding production_control.maintenance_release_candidates%rowtype;
  target_release text := pg_catalog.lower(
    coalesce(input->>'deployment_commit', '')
  );
  binding_manifest jsonb;
  binding_fingerprint text;
  candidate_observed_at timestamptz;
  prior_claim_role text;
  response_value jsonb;
begin
  if not pg_catalog.pg_has_role(session_user, current_user, 'USAGE') then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DATABASE_OWNER_REQUIRED';
  end if;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.project_url <> 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or resource.google_workbook_id <>
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.vercel_project <> 'bagger-inv'
     or resource.canonical_domain <> 'https://baggerinv.com'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_year <> 2026
  then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_RESOURCE_SCOPE_INVALID';
  end if;
  if pg_catalog.upper(coalesce(input->>'environment', '')) <> 'PRODUCTION'
     or input->>'project_ref' is distinct from resource.project_ref
     or input->>'project_url' is distinct from resource.project_url
     or input->>'source_workbook_id' is distinct from
       resource.google_workbook_id
     or input->>'tournament_id' is distinct from
       resource.current_tournament_id
  then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_RESOURCE_ASSERTION_FAILED';
  end if;
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  perform production_control.assert_no_active_physical_writer_fence();
  if input->>'boundary_mode' is distinct from 'MAINTENANCE_WINDOW_V1'
     or input->>'maintenance_provenance_contract' is distinct from
       'production-maintenance-staging-provenance-v2'
     or target_release !~ '^[0-9a-f]{40}$'
     or pg_catalog.lower(coalesce(input->>'candidate_commit_sha', ''))
       is distinct from target_release
     or input->>'candidate_deployment_status' is distinct from 'READY'
     or input->>'candidate_deployment_target' is distinct from 'PREVIEW'
     or input->>'candidate_runtime_environment' is distinct from 'preview'
     or input->>'candidate_evidence_contract' is distinct from
       'vercel-ready-live-runtime-v1'
     or input->>'candidate_git_branch' is distinct from
       'feature/mock-tournament-qa-integration'
     or input->>'candidate_hostname' is distinct from
       'bagger-inv-git-feature-mock-tour-b4f752-sandbagger-invitational.vercel.app'
     or coalesce(input->>'candidate_deployment_hostname', '')
       !~ '^[a-z0-9-]+\.vercel\.app$'
     or input->>'candidate_deployment_hostname' in (
       'bagger-inv-git-feature-mock-tour-b4f752-sandbagger-invitational.vercel.app',
       'baggerinv.com', 'www.baggerinv.com'
     )
     or input->>'vercel_project' is distinct from 'bagger-inv'
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'vercel_team_id' is distinct from
       'team_kPw5zaib8uaQJALAwj4fWI6R'
     or input->>'preview_isolation_contract' is distinct from
       'production-shadow-candidate-v1'
     or input->'preview_isolation_allowed' is distinct from 'true'::jsonb
     or input->'preview_commit_approved' is distinct from 'true'::jsonb
     or input->'preview_no_authoritative_features' is distinct from
       'true'::jsonb
     or input->'step11_allowed' is distinct from 'true'::jsonb
     or input->'step11_sha_approved' is distinct from 'true'::jsonb
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_RELEASE_BINDING_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  candidate_observed_at :=
    (input->>'candidate_evidence_observed_at')::timestamptz;
  if candidate_observed_at is null
     or candidate_observed_at > pg_catalog.now()
     or candidate_observed_at < pg_catalog.now() - interval '15 minutes'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_RELEASE_EVIDENCE_NOT_CURRENT';
  end if;

  select value.* into prior_binding
  from production_control.maintenance_release_candidates value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  if found and (
    prior_binding.release_sha is distinct from target_release
    or prior_binding.candidate_deployment_id is distinct from
      input->>'deployment_id'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_RELEASE_BINDING_ALREADY_BOUND';
  end if;

  -- Migration 049 remains immutable.  Its exact dormant-state and semantic
  -- parity implementation is reused with its certified release value, then
  -- this migration binds the newly Ready release separately and explicitly.
  -- The legacy helper is PostgREST-shaped, so the already-authorized database
  -- owner supplies its claim locally for this call only; the prior claim is
  -- restored before the one-shot binding is persisted.
  prior_claim_role := pg_catalog.current_setting(
    'request.jwt.claim.role', true
  );
  perform pg_catalog.set_config(
    'request.jwt.claim.role', 'service_role', true
  );
  legacy_provenance :=
    production_control.production_maintenance_stage_provenance_v1(
      production_control.production_maintenance_legacy_049_input(input)
    );
  perform pg_catalog.set_config(
    'request.jwt.claim.role', coalesce(prior_claim_role, ''), true
  );

  binding_manifest := pg_catalog.jsonb_build_object(
    'domain', 'BAGGER_MAINTENANCE_RELEASE_BINDING_V1',
    'contract_version', 'production-maintenance-release-binding-v1',
    'release_sha', target_release,
    'candidate_deployment_id', input->>'deployment_id',
    'candidate_deployment_hostname',
      input->>'candidate_deployment_hostname',
    'candidate_deployment_status', 'READY',
    'candidate_evidence_contract', 'vercel-ready-live-runtime-v1',
    'candidate_evidence_observed_at', candidate_observed_at,
    'candidate_deployment_target', 'PREVIEW',
    'candidate_runtime_environment', 'preview',
    'candidate_git_branch', 'feature/mock-tournament-qa-integration',
    'candidate_hostname', input->>'candidate_hostname',
    'vercel_project', 'bagger-inv',
    'vercel_project_id', 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'vercel_team_id', 'team_kPw5zaib8uaQJALAwj4fWI6R',
    'project_ref', 'ymqhhtxaywtqllynrmxe',
    'source_workbook_id',
      '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4',
    'tournament_id', '2026',
    'activation_revision', legacy_provenance->'activation_revision',
    'authority_generation_id',
      legacy_provenance->'authority_generation_id',
    'admission_revision', legacy_provenance->'admission_revision',
    'admission_generation_id',
      legacy_provenance->'admission_generation_id',
    'source_fingerprint', pg_catalog.lower(input->>'source_fingerprint'),
    'semantic_parity_contract',
      'production-current-shadow-semantic-parity-v1',
    'semantic_payload_fingerprint',
      legacy_provenance->>'semantic_payload_fingerprint',
    'semantic_database_fingerprint',
      legacy_provenance->>'semantic_database_fingerprint',
    'semantic_parity', true,
    'unexplained_semantic_difference_count', 0,
    'preview_isolation_allowed', true,
    'preview_commit_approved', true,
    'preview_no_authoritative_features', true,
    'step11_allowed', true,
    'step11_sha_approved', true,
    'first_supabase_canonical_write_possible', false,
    'first_supabase_canonical_write_observed', false
  );
  binding_fingerprint := pg_catalog.encode(
    extensions.digest(binding_manifest::text, 'sha256'), 'hex'
  );

  if prior_binding.binding_id is not null then
    if prior_binding.binding_manifest is distinct from binding_manifest
       or prior_binding.binding_fingerprint is distinct from
         binding_fingerprint
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_RELEASE_BINDING_IMMUTABLE';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_MAINTENANCE_RELEASE_CANDIDATE_BOUND',
      'binding_id', prior_binding.binding_id,
      'release_sha', prior_binding.release_sha,
      'candidate_deployment_id', prior_binding.candidate_deployment_id,
      'binding_manifest', prior_binding.binding_manifest,
      'binding_fingerprint', prior_binding.binding_fingerprint,
      'semantic_parity', true,
      'first_supabase_canonical_write_possible', false,
      'first_supabase_canonical_write_observed', false,
      'idempotent', true
    );
  end if;

  insert into production_control.maintenance_release_candidates (
    contract_version, release_sha, candidate_deployment_id,
    candidate_hostname, candidate_deployment_hostname,
    candidate_evidence_observed_at, vercel_project_id, vercel_team_id,
    activation_revision, authority_generation_id, admission_revision,
    admission_generation_id, source_fingerprint,
    semantic_payload_fingerprint, semantic_database_fingerprint,
    binding_manifest, binding_fingerprint, request_fingerprint,
    payload_hash, actor_id
  ) values (
    'production-maintenance-release-binding-v1', target_release,
    input->>'deployment_id', input->>'candidate_hostname',
    input->>'candidate_deployment_hostname', candidate_observed_at,
    'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'team_kPw5zaib8uaQJALAwj4fWI6R',
    (legacy_provenance->>'activation_revision')::bigint,
    (legacy_provenance->>'authority_generation_id')::uuid,
    (legacy_provenance->>'admission_revision')::bigint,
    (legacy_provenance->>'admission_generation_id')::uuid,
    pg_catalog.lower(input->>'source_fingerprint'),
    legacy_provenance->>'semantic_payload_fingerprint',
    legacy_provenance->>'semantic_database_fingerprint',
    binding_manifest, binding_fingerprint,
    pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(input),
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into binding;

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_MAINTENANCE_RELEASE_CANDIDATE_BOUND',
    'binding_id', binding.binding_id,
    'release_sha', binding.release_sha,
    'candidate_deployment_id', binding.candidate_deployment_id,
    'binding_manifest', binding.binding_manifest,
    'binding_fingerprint', binding.binding_fingerprint,
    'semantic_parity', true,
    'first_supabase_canonical_write_possible', false,
    'first_supabase_canonical_write_observed', false,
    'idempotent', false
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_MAINTENANCE_RELEASE_CANDIDATE_BOUND',
    'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent' - 'binding_manifest'
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.bind_production_maintenance_release_candidate_pre_capability(input jsonb) OWNER TO postgres;

--
-- Name: bootstrap_postcutover_normal_release_baseline(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.bootstrap_postcutover_normal_release_baseline() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  baseline
    production_control.postcutover_application_release_rebindings%rowtype;
  baseline_release_id uuid;
begin
  select value.* into baseline
  from production_control.postcutover_application_release_rebindings value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if not found then return; end if;

  insert into production_control.postcutover_normal_release_rebindings (
    scope_key, boundary_mode, contract_version, release_kind,
    release_sequence, predecessor_release_sequence,
    baseline_application_rebind_id, predecessor_release_rebind_id,
    capability_binding_id, tournament_id, epoch_id,
    authority_generation_id, admission_generation_id,
    predecessor_deployment_id, predecessor_deployment_commit,
    deployment_id, deployment_commit, deployment_hostname,
    vercel_project_id, vercel_team_id,
    capability_contract, capability_ceiling,
    activation_revision_before, activation_revision_after,
    admission_revision_before, admission_revision_after,
    runtime_manifest, runtime_fingerprint, runtime_observed_at,
    request_fingerprint, payload_hash, actor_id, response_value,
    created_at
  ) values (
    'BAGGER_INV_PRODUCTION', 'MAINTENANCE_WINDOW_V1',
    'production-postcutover-normal-release-rebind-v1', 'BASELINE_053',
    1, null,
    baseline.application_rebind_id, null,
    baseline.capability_binding_id, baseline.tournament_id, baseline.epoch_id,
    baseline.authority_generation_id, baseline.admission_generation_id,
    baseline.prior_deployment_id, baseline.prior_deployment_commit,
    baseline.deployment_id, baseline.deployment_commit,
    baseline.deployment_hostname, baseline.vercel_project_id,
    baseline.vercel_team_id, baseline.capability_contract,
    baseline.capability_ceiling, baseline.activation_revision_before,
    baseline.activation_revision_after, baseline.admission_revision_before,
    baseline.admission_revision_after, baseline.runtime_manifest,
    baseline.runtime_fingerprint, baseline.runtime_observed_at,
    baseline.request_fingerprint, baseline.payload_hash, baseline.actor_id,
    baseline.response_value, baseline.created_at
  )
  on conflict (release_sequence) do nothing
  returning release_rebind_id into baseline_release_id;

  if baseline_release_id is null then
    select value.release_rebind_id into strict baseline_release_id
    from production_control.postcutover_normal_release_rebindings value
    where value.release_kind = 'BASELINE_053'
      and value.baseline_application_rebind_id =
        baseline.application_rebind_id;
  end if;

  insert into production_control.postcutover_normal_release_head (
    scope_key, release_sequence, release_rebind_id,
    deployment_id, deployment_commit,
    activation_revision, admission_revision, updated_at
  ) values (
    'BAGGER_INV_PRODUCTION', 1, baseline_release_id,
    baseline.deployment_id, baseline.deployment_commit,
    baseline.activation_revision_after, baseline.admission_revision_after,
    pg_catalog.now()
  ) on conflict (scope_key) do nothing;
  return;
end;
$$;


ALTER FUNCTION production_control.bootstrap_postcutover_normal_release_baseline() OWNER TO postgres;

