--
-- Name: build_annual_net_skins_v1_manifest(text, integer[]); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.build_annual_net_skins_v1_manifest(target text, selected_round_numbers integer[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  round_row scoring_authority.rounds%rowtype;
  match_row record;
  participant_row record;
  side_value integer;
  expected_participants integer;
  participant_count integer;
  stable_participant_count integer;
  hole_count integer;
  team_players text[];
  team_handicap_value numeric;
  entry_value jsonb;
  entries_value jsonb;
  rounds_value jsonb := '[]'::jsonb;
  match_ids_value jsonb;
  round_manifest jsonb;
  format_value text;
  buy_in_value numeric;
  entry_type_value text;
  selected_count integer;
begin
  if target = '' or target = '2026'
     or selected_round_numbers is null
     or coalesce(pg_catalog.array_length(selected_round_numbers, 1), 0) = 0
     or exists (
       select 1 from pg_catalog.unnest(selected_round_numbers) value
       where value not between 1 and 99
     )
     or (select pg_catalog.count(*)
       from pg_catalog.unnest(selected_round_numbers) value) <>
       (select pg_catalog.count(distinct value)
       from pg_catalog.unnest(selected_round_numbers) value) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_ELIGIBLE_ROUNDS_INVALID';
  end if;
  selected_count := pg_catalog.array_length(selected_round_numbers, 1);
  if (select pg_catalog.count(*)
      from scoring_authority.rounds value
      where value.tournament_id = target
        and value.round_number = any(selected_round_numbers)
        and value.format in ('BB', 'SC', 'SI')) <> selected_count then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
  end if;

  for round_row in
    select value.* from scoring_authority.rounds value
    where value.tournament_id = target
      and value.round_number = any(selected_round_numbers)
    order by value.round_number
  loop
    format_value := round_row.format;
    expected_participants := case format_value when 'SI' then 2 else 4 end;
    buy_in_value := case format_value when 'SC' then 50 else 25 end;
    entry_type_value := case format_value
      when 'SC' then 'PAIRING' else 'INDIVIDUAL' end;
    entries_value := '[]'::jsonb;
    match_ids_value := '[]'::jsonb;
    if not exists (
      select 1 from scoring_authority.matches value
      where value.tournament_id = target
        and value.round_number = round_row.round_number
    ) then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
    end if;

    for match_row in
      select match_value.*, snapshot.team_configuration,
        coalesce(nullif(presentation.display_match_number, ''),
          match_value.match_id) as engine_match_number
      from scoring_authority.matches match_value
      join scoring_authority.scoring_snapshots snapshot
        on snapshot.snapshot_id = match_value.scoring_snapshot_id
       and snapshot.tournament_id = match_value.tournament_id
       and snapshot.match_id = match_value.match_id
      left join scoring_authority.game_center_presentations presentation
        on presentation.match_id = match_value.match_id
       and presentation.tournament_id = match_value.tournament_id
      where match_value.tournament_id = target
        and match_value.round_number = round_row.round_number
      order by match_value.match_id
    loop
      if match_row.format <> format_value then
        raise exception using errcode = '23514',
          message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
      end if;
      select pg_catalog.count(*),
        pg_catalog.count(distinct participant.player_id) filter (
          where participant.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
            and exists (
              select 1 from scoring_authority.tournament_players membership
              where membership.tournament_id = target
                and membership.player_id = participant.player_id
                and membership.participation_status = 'ACTIVE'
            )
        ) into participant_count, stable_participant_count
      from scoring_authority.match_participants participant
      where participant.match_id = match_row.match_id;
      if participant_count <> expected_participants
         or stable_participant_count <> expected_participants then
        raise exception using errcode = '23514',
          message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
      end if;
      select pg_catalog.count(distinct hole.hole_number) into hole_count
      from scoring_authority.match_holes hole
      where hole.match_id = match_row.match_id
        and hole.hole_number between 1 and 18;
      if hole_count <> 18 then
        raise exception using errcode = '23514',
          message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
      end if;
      match_ids_value := match_ids_value ||
        pg_catalog.jsonb_build_array(match_row.match_id);

      if format_value = 'SC' then
        for side_value in 1..2 loop
          select pg_catalog.array_agg(participant.player_id order by
              participant.player_slot, participant.player_id)
            into team_players
          from scoring_authority.match_participants participant
          where participant.match_id = match_row.match_id
            and participant.team_side = side_value;
          team_handicap_value := nullif(
            match_row.team_configuration->>
              pg_catalog.format('team_%s_strokes', side_value), ''
          )::numeric;
          if coalesce(pg_catalog.array_length(team_players, 1), 0) <> 2
             or team_handicap_value is null then
            raise exception using errcode = '23514',
              message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
          end if;
          entry_value := pg_catalog.jsonb_build_object(
            'entry_id', pg_catalog.format('%s:R%s:PAIRING:%s:S%s',
              target, round_row.round_number, match_row.match_id, side_value),
            'entry_type', 'PAIRING', 'match_id', match_row.match_id,
            'match_number', match_row.engine_match_number,
            'player_ids', pg_catalog.to_jsonb(team_players),
            'player_id_1', team_players[1], 'player_id_2', team_players[2],
            'team_handicap', team_handicap_value,
            'individual_stroke_allocation', null,
            'buy_in', buy_in_value, 'eligible', true
          );
          entries_value := entries_value ||
            pg_catalog.jsonb_build_array(entry_value);
        end loop;
      else
        for participant_row in
          select participant.*
          from scoring_authority.match_participants participant
          where participant.match_id = match_row.match_id
          order by participant.team_side, participant.player_slot,
            participant.player_id
        loop
          entry_value := pg_catalog.jsonb_build_object(
            'entry_id', pg_catalog.format('%s:R%s:PLAYER:%s', target,
              round_row.round_number, participant_row.player_id),
            'entry_type', 'INDIVIDUAL', 'match_id', match_row.match_id,
            'match_number', match_row.engine_match_number,
            'player_ids', pg_catalog.jsonb_build_array(
              participant_row.player_id),
            'player_id_1', participant_row.player_id, 'player_id_2', null,
            'team_handicap', null, 'individual_stroke_allocation',
              participant_row.final_strokes,
            'buy_in', buy_in_value, 'eligible', true
          );
          entries_value := entries_value ||
            pg_catalog.jsonb_build_array(entry_value);
        end loop;
      end if;
    end loop;

    if pg_catalog.jsonb_array_length(entries_value) = 0
       or (select pg_catalog.count(distinct player_id) from (
         select pg_catalog.jsonb_array_elements_text(entry->'player_ids')
           player_id from pg_catalog.jsonb_array_elements(entries_value) entry
       ) players) <>
       (select pg_catalog.count(*) from (
         select pg_catalog.jsonb_array_elements_text(entry->'player_ids')
           player_id from pg_catalog.jsonb_array_elements(entries_value) entry
       ) players) then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
    end if;
    round_manifest := pg_catalog.jsonb_build_object(
      'round_id', pg_catalog.format('%s:R%s', target,
        round_row.round_number),
      'round_number', round_row.round_number, 'round_name', round_row.name,
      'format', format_value, 'entry_type', entry_type_value,
      'buy_in_per_entry', buy_in_value,
      'expected_pot', pg_catalog.jsonb_array_length(entries_value) *
        buy_in_value,
      'eligible_holes', (select pg_catalog.jsonb_agg(value order by value)
        from pg_catalog.generate_series(1, 18) value),
      'net_handicap_basis', case format_value
        when 'SC' then 'CANONICAL_SCORING_SNAPSHOT_TEAM_STROKES'
        else 'CANONICAL_MATCH_PARTICIPANT_FINAL_STROKES' end,
      'completion_rule',
        'ALL_ELIGIBLE_ENTRIES_18_HOLES_AND_REFERENCED_MATCHES_OFFICIAL',
      'payout_rounding', 'NONE', 'tie_rule', 'NO_SKIN_NO_CARRY',
      'carry_rule', 'NO_CARRY', 'publication_policy', 'OFFICIAL_ONLY',
      'match_ids', match_ids_value, 'entries', entries_value
    );
    round_manifest := round_manifest || pg_catalog.jsonb_build_object(
      'configuration_fingerprint',
      production_control.net_skins_v1_hash(round_manifest)
    );
    rounds_value := rounds_value ||
      pg_catalog.jsonb_build_array(round_manifest);
  end loop;
  return pg_catalog.jsonb_build_object(
    'contract_version', 'production-net-skins-v1',
    'tournament_id', target, 'state', 'CONFIGURED',
    'publication_policy', 'OFFICIAL_ONLY', 'rounds', rounds_value
  );
end;
$_$;


ALTER FUNCTION production_control.build_annual_net_skins_v1_manifest(target text, selected_round_numbers integer[]) OWNER TO postgres;

--
-- Name: build_production_calcutta_v1_auction(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.build_production_calcutta_v1_auction(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'scoring_authority'
    AS $$
declare
  purchase_value jsonb;
  ownership_value jsonb;
  entrant_value text;
  owner_value text;
  price_value numeric;
  share_value numeric;
  purchases_value jsonb := '[]'::jsonb;
  ownership_value_out jsonb := '[]'::jsonb;
  seen_entrants text[] := '{}'::text[];
  seen_ownership text[] := '{}'::text[];
  pot_value numeric := 0;
begin
  if input->>'contract_version' is distinct from 'production-calcutta-v1'
     or pg_catalog.jsonb_typeof(coalesce(
       input->'purchases', 'null'::jsonb
     )) <> 'array'
     or pg_catalog.jsonb_typeof(coalesce(
       input->'ownership', 'null'::jsonb
     )) <> 'array'
     or pg_catalog.jsonb_array_length(input->'purchases') = 0
     or pg_catalog.jsonb_array_length(input->'ownership') = 0 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_AUCTION_INPUT_INVALID';
  end if;

  for purchase_value in
    select value from pg_catalog.jsonb_array_elements(input->'purchases') value
    order by value->>'player_id'
  loop
    if pg_catalog.jsonb_typeof(purchase_value) <> 'object'
       or not (purchase_value ?& array[
         'player_id', 'purchase_price'
       ])
       or purchase_value->'player_id' = 'null'::jsonb
       or purchase_value->'purchase_price' = 'null'::jsonb then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_PURCHASE_INVALID';
    end if;
    entrant_value := pg_catalog.btrim(coalesce(
      purchase_value->>'player_id', ''
    ));
    price_value := (purchase_value->>'purchase_price')::numeric;
    if entrant_value = '' or entrant_value = any(seen_entrants)
       or price_value < 0 or not exists (
         select 1 from scoring_authority.tournament_players membership
         where membership.tournament_id = '2026'
           and membership.player_id = entrant_value
           and membership.participation_status = 'ACTIVE'
       ) then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_PURCHASE_INVALID';
    end if;
    seen_entrants := pg_catalog.array_append(seen_entrants, entrant_value);
    pot_value := pot_value + price_value;
    purchases_value := purchases_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'player_id', entrant_value,
        'purchase_price', price_value
      )
    );
  end loop;
  for ownership_value in
    select value from pg_catalog.jsonb_array_elements(input->'ownership') value
    order by value->>'player_id', value->>'owner_player_id'
  loop
    if pg_catalog.jsonb_typeof(ownership_value) <> 'object'
       or not (ownership_value ?& array[
         'player_id', 'owner_player_id', 'ownership_fraction'
       ])
       or ownership_value->'player_id' = 'null'::jsonb
       or ownership_value->'owner_player_id' = 'null'::jsonb
       or ownership_value->'ownership_fraction' = 'null'::jsonb then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_OWNERSHIP_INVALID';
    end if;
    entrant_value := pg_catalog.btrim(coalesce(
      ownership_value->>'player_id', ''
    ));
    owner_value := pg_catalog.btrim(coalesce(
      ownership_value->>'owner_player_id', ''
    ));
    share_value := (ownership_value->>'ownership_fraction')::numeric;
    if entrant_value = '' or not (entrant_value = any(seen_entrants))
       or owner_value = '' or share_value <= 0 or share_value > 1
       or (entrant_value || ':' || owner_value) = any(seen_ownership)
       or not exists (
         select 1 from scoring_authority.tournament_players membership
         where membership.tournament_id = '2026'
           and membership.player_id = owner_value
           and membership.participation_status = 'ACTIVE'
       ) then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_OWNERSHIP_INVALID';
    end if;
    seen_ownership := pg_catalog.array_append(
      seen_ownership, entrant_value || ':' || owner_value
    );
    ownership_value_out := ownership_value_out ||
      pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'player_id', entrant_value,
        'owner_player_id', owner_value,
        'ownership_fraction', share_value
      ));
  end loop;

  if exists (
    select 1 from pg_catalog.unnest(seen_entrants) entrant
    where coalesce((
      select pg_catalog.sum((owner_row->>'ownership_fraction')::numeric)
      from pg_catalog.jsonb_array_elements(ownership_value_out) owner_row
      where owner_row->>'player_id' = entrant
    ), 0) <> 1
  ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_OWNERSHIP_TOTAL_MISMATCH';
  end if;

  return pg_catalog.jsonb_build_object(
    'contract_version', 'production-calcutta-v1',
    'tournament_id', '2026',
    'state', 'AUCTION_COMPLETE',
    'currency_code', 'USD',
    'auction_unit', 'PLAYER',
    'entry_workflow', 'MANUAL_FINAL_AUCTION_FACTS',
    'pot', pot_value,
    'purchases', purchases_value,
    'ownership', ownership_value_out
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_AUCTION_INPUT_INVALID';
end;
$$;


ALTER FUNCTION production_control.build_production_calcutta_v1_auction(input jsonb) OWNER TO postgres;

--
-- Name: build_production_calcutta_v1_configuration(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.build_production_calcutta_v1_configuration(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  row_value jsonb;
  place_value integer;
  point_rows jsonb := '[]'::jsonb;
  payout_rows jsonb := '[]'::jsonb;
  seen_places integer[] := '{}'::integer[];
  total_payout numeric := 0;
  positive_points boolean := false;
  fraction_value numeric;
begin
  if input->>'contract_version' is distinct from 'production-calcutta-v1'
     or pg_catalog.jsonb_typeof(coalesce(
       input->'point_structure', 'null'::jsonb
     )) <> 'array'
     or pg_catalog.jsonb_typeof(coalesce(
       input->'payout_structure', 'null'::jsonb
     )) <> 'array'
     or pg_catalog.jsonb_array_length(input->'point_structure') = 0
     or pg_catalog.jsonb_array_length(input->'payout_structure') = 0 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_INPUT_INVALID';
  end if;

  for row_value in
    select value from pg_catalog.jsonb_array_elements(
      input->'point_structure'
    ) value order by (value->>'place')::integer
  loop
    if pg_catalog.jsonb_typeof(row_value) <> 'object'
       or not (row_value ?& array[
         'place', 'round_1_award', 'round_2_award', 'round_3_award'
       ])
       or row_value->'place' = 'null'::jsonb
       or row_value->'round_1_award' = 'null'::jsonb
       or row_value->'round_2_award' = 'null'::jsonb
       or row_value->'round_3_award' = 'null'::jsonb then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_POINT_STRUCTURE_INVALID';
    end if;
    place_value := (row_value->>'place')::integer;
    if place_value < 1 or place_value = any(seen_places)
       or (row_value->>'round_1_award')::numeric < 0
       or (row_value->>'round_2_award')::numeric < 0
       or (row_value->>'round_3_award')::numeric < 0 then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_POINT_STRUCTURE_INVALID';
    end if;
    seen_places := pg_catalog.array_append(seen_places, place_value);
    positive_points := positive_points
      or (row_value->>'round_1_award')::numeric > 0
      or (row_value->>'round_2_award')::numeric > 0
      or (row_value->>'round_3_award')::numeric > 0;
    point_rows := point_rows || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'place', place_value,
        'round_1_award', (row_value->>'round_1_award')::numeric,
        'round_2_award', (row_value->>'round_2_award')::numeric,
        'round_3_award', (row_value->>'round_3_award')::numeric
      )
    );
  end loop;
  if not positive_points then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_POINT_STRUCTURE_INVALID';
  end if;

  seen_places := '{}'::integer[];
  for row_value in
    select value from pg_catalog.jsonb_array_elements(
      input->'payout_structure'
    ) value order by (value->>'place')::integer
  loop
    if pg_catalog.jsonb_typeof(row_value) <> 'object'
       or not (row_value ?& array[
         'place', 'round_1_fraction', 'round_2_fraction',
         'round_3_fraction', 'overall_fraction'
       ])
       or row_value->'place' = 'null'::jsonb
       or row_value->'round_1_fraction' = 'null'::jsonb
       or row_value->'round_2_fraction' = 'null'::jsonb
       or row_value->'round_3_fraction' = 'null'::jsonb
       or row_value->'overall_fraction' = 'null'::jsonb then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_PAYOUT_STRUCTURE_INVALID';
    end if;
    place_value := (row_value->>'place')::integer;
    if place_value < 1 or place_value = any(seen_places)
       or (row_value->>'round_1_fraction')::numeric < 0
       or (row_value->>'round_2_fraction')::numeric < 0
       or (row_value->>'round_3_fraction')::numeric < 0
       or (row_value->>'overall_fraction')::numeric < 0 then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_PAYOUT_STRUCTURE_INVALID';
    end if;
    seen_places := pg_catalog.array_append(seen_places, place_value);
    fraction_value :=
      (row_value->>'round_1_fraction')::numeric
      + (row_value->>'round_2_fraction')::numeric
      + (row_value->>'round_3_fraction')::numeric
      + (row_value->>'overall_fraction')::numeric;
    total_payout := total_payout + fraction_value;
    payout_rows := payout_rows || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'place', place_value,
        'round_1_fraction',
          (row_value->>'round_1_fraction')::numeric,
        'round_2_fraction',
          (row_value->>'round_2_fraction')::numeric,
        'round_3_fraction',
          (row_value->>'round_3_fraction')::numeric,
        'overall_fraction', (row_value->>'overall_fraction')::numeric
      )
    );
  end loop;
  if total_payout <> 1 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_PAYOUT_TOTAL_MISMATCH';
  end if;

  return pg_catalog.jsonb_build_object(
    'contract_version', 'production-calcutta-v1',
    'tournament_id', '2026',
    'tournament_year', 2026,
    'state', 'CONFIGURED',
    'currency_code', 'USD',
    'publication_policy',
      'DIRECTOR_CONTROLLED_PARTICIPANT_FULL_MARKET',
    'point_structure', point_rows,
    'payout_structure', payout_rows,
    'financial_contract', pg_catalog.jsonb_build_object(
      'auction_unit', 'PLAYER',
      'eligible_entrants', 'ACTIVE_TOURNAMENT_PLAYERS',
      'auction_workflow', 'MANUAL_FINAL_AUCTION_FACTS',
      'live_bidding', false,
      'minimum_bid', null,
      'opening_bid', null,
      'bid_increment', null,
      'pot_rule', 'SUM_PURCHASE_PRICES',
      'round_scoring_basis',
        'CANONICAL_SUPABASE_OFFICIAL_GROSS_NET_RESULTS',
      'overall_scoring_basis', 'DESCENDING_TOTAL_CALCUTTA_POINTS',
      'tie_rule',
        'COMPETITION_RANK_WITH_OCCUPIED_PLACE_AWARD_AVERAGING',
      'payout_rounding', 'NONE',
      'scramble_asset',
        'PLAYER_PURCHASE_WITH_PAIRING_PERFORMANCE_SPLIT_EQUALLY',
      'completion_rule',
        'ALL_PURCHASED_PLAYERS_HAVE_OFFICIAL_COMPLETED_ROUND_RESULT',
      'settlement_tracking', 'NOT_MODELED',
      'payout_total_fraction', 1
    )
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_INPUT_INVALID';
end;
$$;


ALTER FUNCTION production_control.build_production_calcutta_v1_configuration(input jsonb) OWNER TO postgres;

--
-- Name: build_production_net_skins_v1_manifest(integer[]); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.build_production_net_skins_v1_manifest(selected_round_numbers integer[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  round_row scoring_authority.rounds%rowtype;
  match_row record;
  participant_row record;
  side_value integer;
  expected_participants integer;
  participant_count integer;
  stable_participant_count integer;
  hole_count integer;
  team_players text[];
  team_handicap_value numeric;
  entry_value jsonb;
  entries_value jsonb;
  rounds_value jsonb := '[]'::jsonb;
  match_ids_value jsonb;
  round_manifest jsonb;
  format_value text;
  buy_in_value numeric;
  entry_type_value text;
  expected_pot_value numeric;
  selected_count integer;
begin
  if selected_round_numbers is null
     or coalesce(pg_catalog.array_length(selected_round_numbers, 1), 0) = 0
     or exists (
       select 1 from pg_catalog.unnest(selected_round_numbers) value
       where value not between 1 and 99
     )
     or (
       select pg_catalog.count(*)
       from pg_catalog.unnest(selected_round_numbers) value
     ) <> (
       select pg_catalog.count(distinct value)
       from pg_catalog.unnest(selected_round_numbers) value
     ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_ELIGIBLE_ROUNDS_INVALID';
  end if;

  selected_count := pg_catalog.array_length(selected_round_numbers, 1);
  if (
    select pg_catalog.count(*)
    from scoring_authority.rounds value
    where value.tournament_id = '2026'
      and value.round_number = any(selected_round_numbers)
      and value.format in ('BB', 'SC', 'SI')
  ) <> selected_count then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
  end if;

  for round_row in
    select value.*
    from scoring_authority.rounds value
    where value.tournament_id = '2026'
      and value.round_number = any(selected_round_numbers)
    order by value.round_number
  loop
    format_value := round_row.format;
    expected_participants := case format_value
      when 'SI' then 2 else 4 end;
    buy_in_value := case format_value when 'SC' then 50 else 25 end;
    entry_type_value := case format_value
      when 'SC' then 'PAIRING' else 'INDIVIDUAL' end;
    entries_value := '[]'::jsonb;
    match_ids_value := '[]'::jsonb;

    if not exists (
      select 1 from scoring_authority.matches value
      where value.tournament_id = '2026'
        and value.round_number = round_row.round_number
    ) then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
    end if;

    for match_row in
      select
        match_value.*,
        snapshot.team_configuration,
        coalesce(nullif(presentation.display_match_number, ''),
          match_value.match_id) as engine_match_number
      from scoring_authority.matches match_value
      join scoring_authority.scoring_snapshots snapshot
        on snapshot.snapshot_id = match_value.scoring_snapshot_id
       and snapshot.tournament_id = match_value.tournament_id
       and snapshot.match_id = match_value.match_id
      left join scoring_authority.game_center_presentations presentation
        on presentation.match_id = match_value.match_id
       and presentation.tournament_id = match_value.tournament_id
      where match_value.tournament_id = '2026'
        and match_value.round_number = round_row.round_number
      order by match_value.match_id
    loop
      if match_row.format <> format_value then
        raise exception using errcode = '23514',
          message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
      end if;

      select
        pg_catalog.count(*),
        pg_catalog.count(distinct participant.player_id) filter (
          where participant.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
            and exists (
              select 1
              from scoring_authority.tournament_players membership
              where membership.tournament_id = '2026'
                and membership.player_id = participant.player_id
                and membership.participation_status = 'ACTIVE'
            )
        )
        into participant_count, stable_participant_count
      from scoring_authority.match_participants participant
      where participant.match_id = match_row.match_id;

      if participant_count <> expected_participants
         or stable_participant_count <> expected_participants then
        raise exception using errcode = '23514',
          message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
      end if;

      select pg_catalog.count(distinct hole.hole_number) into hole_count
      from scoring_authority.match_holes hole
      where hole.match_id = match_row.match_id
        and hole.hole_number between 1 and 18;
      if hole_count <> 18 then
        raise exception using errcode = '23514',
          message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
      end if;

      match_ids_value := match_ids_value || pg_catalog.jsonb_build_array(
        match_row.match_id
      );

      if format_value = 'SC' then
        for side_value in 1..2 loop
          select pg_catalog.array_agg(participant.player_id order by
              participant.player_slot, participant.player_id)
            into team_players
          from scoring_authority.match_participants participant
          where participant.match_id = match_row.match_id
            and participant.team_side = side_value;
          team_handicap_value := nullif(
            match_row.team_configuration->>
              pg_catalog.format('team_%s_strokes', side_value), ''
          )::numeric;
          if coalesce(pg_catalog.array_length(team_players, 1), 0) <> 2
             or team_handicap_value is null then
            raise exception using errcode = '23514',
              message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
          end if;
          entry_value := pg_catalog.jsonb_build_object(
            'entry_id', pg_catalog.format(
              '2026:R%s:PAIRING:%s:S%s', round_row.round_number,
              match_row.match_id, side_value
            ),
            'entry_type', 'PAIRING',
            'match_id', match_row.match_id,
            'match_number', match_row.engine_match_number,
            'player_ids', pg_catalog.to_jsonb(team_players),
            'player_id_1', team_players[1],
            'player_id_2', team_players[2],
            'team_handicap', team_handicap_value,
            'individual_stroke_allocation', null,
            'buy_in', buy_in_value,
            'eligible', true
          );
          entries_value := entries_value ||
            pg_catalog.jsonb_build_array(entry_value);
        end loop;
      else
        for participant_row in
          select participant.*
          from scoring_authority.match_participants participant
          where participant.match_id = match_row.match_id
          order by participant.team_side, participant.player_slot,
            participant.player_id
        loop
          entry_value := pg_catalog.jsonb_build_object(
            'entry_id', pg_catalog.format(
              '2026:R%s:PLAYER:%s', round_row.round_number,
              participant_row.player_id
            ),
            'entry_type', 'INDIVIDUAL',
            'match_id', match_row.match_id,
            'match_number', match_row.engine_match_number,
            'player_ids', pg_catalog.jsonb_build_array(
              participant_row.player_id
            ),
            'player_id_1', participant_row.player_id,
            'player_id_2', null,
            'team_handicap', null,
            'individual_stroke_allocation',
              participant_row.final_strokes,
            'buy_in', buy_in_value,
            'eligible', true
          );
          entries_value := entries_value ||
            pg_catalog.jsonb_build_array(entry_value);
        end loop;
      end if;
    end loop;

    if pg_catalog.jsonb_array_length(entries_value) = 0
       or (
         select pg_catalog.count(distinct player_id)
         from (
           select pg_catalog.jsonb_array_elements_text(
             entry->'player_ids'
           ) as player_id
           from pg_catalog.jsonb_array_elements(entries_value) entry
         ) player_values
       ) <> (
         select pg_catalog.count(*)
         from (
           select pg_catalog.jsonb_array_elements_text(
             entry->'player_ids'
           ) as player_id
           from pg_catalog.jsonb_array_elements(entries_value) entry
         ) player_values
       ) then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_INCOMPLETE';
    end if;

    expected_pot_value :=
      pg_catalog.jsonb_array_length(entries_value) * buy_in_value;
    round_manifest := pg_catalog.jsonb_build_object(
      'round_id', pg_catalog.format('2026:R%s', round_row.round_number),
      'round_number', round_row.round_number,
      'round_name', round_row.name,
      'format', format_value,
      'entry_type', entry_type_value,
      'buy_in_per_entry', buy_in_value,
      'expected_pot', expected_pot_value,
      'eligible_holes', (
        select pg_catalog.jsonb_agg(value order by value)
        from pg_catalog.generate_series(1, 18) value
      ),
      'net_handicap_basis', case format_value
        when 'SC' then 'CANONICAL_SCORING_SNAPSHOT_TEAM_STROKES'
        else 'CANONICAL_MATCH_PARTICIPANT_FINAL_STROKES' end,
      'completion_rule',
        'ALL_ELIGIBLE_ENTRIES_18_HOLES_AND_REFERENCED_MATCHES_OFFICIAL',
      'payout_rounding', 'NONE',
      'tie_rule', 'NO_SKIN_NO_CARRY',
      'carry_rule', 'NO_CARRY',
      'publication_policy', 'OFFICIAL_ONLY',
      'match_ids', match_ids_value,
      'entries', entries_value
    );
    round_manifest := round_manifest || pg_catalog.jsonb_build_object(
      'configuration_fingerprint',
      production_control.net_skins_v1_hash(round_manifest)
    );
    rounds_value := rounds_value ||
      pg_catalog.jsonb_build_array(round_manifest);
  end loop;

  return pg_catalog.jsonb_build_object(
    'contract_version', 'production-net-skins-v1',
    'tournament_id', '2026',
    'state', 'CONFIGURED',
    'publication_policy', 'OFFICIAL_ONLY',
    'rounds', rounds_value
  );
end;
$_$;


ALTER FUNCTION production_control.build_production_net_skins_v1_manifest(selected_round_numbers integer[]) OWNER TO postgres;

--
-- Name: build_production_participant_identity_enrollment_inspection(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.build_production_participant_identity_enrollment_inspection() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  resource production_control.resource_scope%rowtype;
  active_roster_count integer := 0;
  active_contact_count integer := 0;
  enrolled_count integer := 0;
  not_enrolled_count integer := 0;
  invalid_enrolled_count integer := 0;
  residual_authority_count integer := 0;
  distinct_email_count integer := 0;
  players_value jsonb := '[]'::jsonb;
begin
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';

  if resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.project_url <> 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or resource.google_workbook_id
       <> '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.vercel_project <> 'bagger-inv'
     or resource.canonical_domain <> 'https://baggerinv.com'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_year <> 2026 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_RESOURCE_SCOPE_INVALID';
  end if;

  with active_roster as (
    select membership.player_id
    from scoring_authority.tournament_players membership
    where membership.tournament_id = '2026'
      and membership.participation_status = 'ACTIVE'
  ),
  active_contacts as (
    select contact.*
    from participant_identity.participant_identity_contacts contact
    where contact.tournament_id = '2026'
      and contact.identity_active
  ),
  eligible_contacts as (
    select distinct contact.player_id, contact.email_normalized
    from active_contacts contact
    join active_roster membership
      on membership.player_id = contact.player_id
    join participant_identity.identity_context_revisions current_revision
      on current_revision.tournament_id = contact.tournament_id
     and current_revision.context_revision = contact.configuration_revision
    join participant_identity.identity_config_import_runs import_run
      on import_run.tournament_id = contact.tournament_id
     and import_run.configuration_revision = contact.configuration_revision
     and import_run.source_fingerprint
       = current_revision.configuration_fingerprint
     and import_run.status = 'APPROVED'
     and import_run.approved_at is not null
     and import_run.source_workbook_id = resource.google_workbook_id
    where contact.source_workbook_id = resource.google_workbook_id
      and contact.source_system = import_run.source_system
      and contact.player_id = pg_catalog.upper(pg_catalog.btrim(contact.player_id))
      and contact.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
      and contact.email_normalized
        = pg_catalog.lower(pg_catalog.btrim(contact.email))
      and contact.email_normalized ~* (
        '^[A-Z0-9.!#$%&''*+/=?^_`{|}~-]+@'
        || '[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?'
        || '(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$'
      )::pg_catalog.text collate "C"
      and pg_catalog.split_part(contact.email_normalized, '@', 2)
        !~* '(^|\.)(example\.(com|net|org)|invalid|test|localhost)$'
  ),
  residual_identity_players as (
    select roster.player_id
    from active_roster roster
    where not exists (
      select 1 from active_contacts contact
      where contact.player_id = roster.player_id
    )
      and (
        exists (
          select 1
          from participant_identity.user_player_links link
          where link.player_id = roster.player_id
            and link.status in ('PENDING', 'ACTIVE', 'SUSPENDED')
        )
        or exists (
          select 1
          from participant_identity.participant_auth_identifiers identifier
          where identifier.player_id = roster.player_id
            and identifier.identifier_type = 'EMAIL'
            and identifier.status in (
              'ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED'
            )
        )
      )
  ),
  roster_status as (
    select
      roster.player_id,
      eligible.email_normalized,
      case
        when eligible.player_id is not null then 'ENROLLED'
        when active_contact.player_id is not null
          or residual.player_id is not null then 'INVALID_ENROLLMENT'
        else 'NOT_ENROLLED'
      end as enrollment_status
    from active_roster roster
    left join active_contacts active_contact
      on active_contact.player_id = roster.player_id
    left join eligible_contacts eligible
      on eligible.player_id = roster.player_id
    left join residual_identity_players residual
      on residual.player_id = roster.player_id
  ),
  totals as (
    select
      (select pg_catalog.count(*) from active_roster)::integer
        as active_roster_count,
      (select pg_catalog.count(*) from active_contacts)::integer
        as active_contact_count,
      (select pg_catalog.count(*) from eligible_contacts)::integer
        as enrolled_count,
      (select pg_catalog.count(*) from roster_status
        where enrollment_status = 'NOT_ENROLLED')::integer
        as not_enrolled_count,
      (
        (select pg_catalog.count(*) from active_contacts)
        - (select pg_catalog.count(*) from eligible_contacts)
        + (select pg_catalog.count(*) from residual_identity_players)
      )::integer as invalid_enrolled_count,
      (select pg_catalog.count(*) from residual_identity_players)::integer
        as residual_authority_count,
      (select pg_catalog.count(distinct pg_catalog.lower(email_normalized))
        from eligible_contacts)::integer as distinct_email_count,
      coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'playerId', status.player_id,
            'enrollmentStatus', status.enrollment_status
          ) || case
            when status.enrollment_status = 'ENROLLED' then
              pg_catalog.jsonb_build_object(
                'maskedEmail',
                pg_catalog.left(
                  pg_catalog.split_part(status.email_normalized, '@', 1), 1
                ) || '***@' ||
                pg_catalog.left(
                  pg_catalog.split_part(status.email_normalized, '@', 2), 1
                ) || '***.' ||
                pg_catalog.reverse(
                  pg_catalog.split_part(
                    pg_catalog.reverse(
                      pg_catalog.split_part(status.email_normalized, '@', 2)
                    ),
                    '.',
                    1
                  )
                )
              )
            else '{}'::jsonb
          end
          order by status.player_id
        )
        from roster_status status
      ), '[]'::jsonb) as players
  )
  select
    totals.active_roster_count,
    totals.active_contact_count,
    totals.enrolled_count,
    totals.not_enrolled_count,
    totals.invalid_enrolled_count,
    totals.residual_authority_count,
    totals.distinct_email_count,
    totals.players
  into
    active_roster_count,
    active_contact_count,
    enrolled_count,
    not_enrolled_count,
    invalid_enrolled_count,
    residual_authority_count,
    distinct_email_count,
    players_value
  from totals;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'contractVersion', 'production-participant-identity-partial-enrollment-v1',
    'enrollmentPolicy', 'APPROVED_PARTIAL_ROSTER',
    'activeRosterCount', active_roster_count,
    'enrolledCount', enrolled_count,
    'notEnrolledCount', not_enrolled_count,
    'invalidEnrolledCount', invalid_enrolled_count,
    'residualAuthorityCount', residual_authority_count,
    'distinctEmailCount', distinct_email_count,
    'activationEligible',
      active_roster_count >= 1
      and enrolled_count >= 1
      and active_contact_count = enrolled_count
      and invalid_enrolled_count = 0
      and distinct_email_count = enrolled_count,
    'players', players_value
  );
end;
$_$;


ALTER FUNCTION production_control.build_production_participant_identity_enrollment_inspection() OWNER TO postgres;

--
-- Name: calcutta_source_before_full_net_v3(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.calcutta_source_before_full_net_v3(target_tournament_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'scoring_authority'
    AS $$
  select pg_catalog.jsonb_build_object(
    'tournament_id', target_tournament_id,
    'calculation_policy', 'calcutta-bb-si-full-course-handicap-v1',
    'rounds', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'round_number', round_value.round_number,
        'format', round_value.format,
        'status', round_value.status
      ) order by round_value.round_number)
      from scoring_authority.rounds round_value
      where round_value.tournament_id = target_tournament_id
        and round_value.round_number between 1 and 3
    ), '[]'::jsonb),
    'matches', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'match_id', match_value.match_id,
        'round_number', match_value.round_number,
        'format', match_value.format,
        'status', match_value.status,
        'match_revision', match_value.match_revision,
        'permission_revision', match_value.permission_revision,
        'scored_holes', match_value.scored_holes,
        'scorecard_complete', match_value.scorecard_complete,
        'result_winner', match_value.result_winner,
        'finalized_at', match_value.finalized_at,
        'scoring_snapshot_id', match_value.scoring_snapshot_id,
        'participants', coalesce((
          select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'player_id', participant.player_id,
            'team_side', participant.team_side,
            'player_slot', participant.player_slot,
            'course_handicap', participant.course_handicap,
            'playing_handicap', participant.playing_handicap,
            'final_strokes', participant.final_strokes,
            'handicap_revision_id', participant.handicap_revision_id
          ) order by participant.team_side, participant.player_slot,
            participant.player_id)
          from scoring_authority.match_participants participant
          where participant.match_id = match_value.match_id
        ), '[]'::jsonb)
      ) order by match_value.round_number, match_value.match_id)
      from scoring_authority.matches match_value
      where match_value.tournament_id = target_tournament_id
        and match_value.round_number between 1 and 3
    ), '[]'::jsonb),
    'holes', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'match_id', score.match_id,
        'round_number', match_value.round_number,
        'hole_number', score.hole_number,
        'hole_revision', score.hole_revision,
        'team_1_gross_scores', score.team_1_gross_scores,
        'team_2_gross_scores', score.team_2_gross_scores,
        'team_1_strokes', score.team_1_strokes,
        'team_2_strokes', score.team_2_strokes,
        'team_1_net_score', score.team_1_net_score,
        'team_2_net_score', score.team_2_net_score,
        'hole_winner', score.hole_winner
      ) order by match_value.round_number, score.match_id, score.hole_number)
      from scoring_authority.hole_scores score
      join scoring_authority.matches match_value
        on match_value.match_id = score.match_id
      where match_value.tournament_id = target_tournament_id
        and match_value.round_number between 1 and 3
    ), '[]'::jsonb)
  )
$$;


ALTER FUNCTION production_control.calcutta_source_before_full_net_v3(target_tournament_id text) OWNER TO postgres;

--
-- Name: calcutta_v1_completed_rounds(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.calcutta_v1_completed_rounds() RETURNS integer[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'scoring_authority'
    AS $$
  select coalesce(pg_catalog.array_agg(candidate.round_number
    order by candidate.round_number), '{}'::integer[])
  from pg_catalog.generate_series(1, 3) candidate(round_number)
  where exists (
      select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = '2026'
        and match_value.round_number = candidate.round_number
    )
    and not exists (
      select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = '2026'
        and match_value.round_number = candidate.round_number
        and (match_value.status <> 'FINAL'
          or not match_value.scorecard_complete
          or match_value.finalized_at is null)
    )
    and not exists (
      select 1
      from scoring_authority.calcutta_v1_current current_value
      join scoring_authority.calcutta_v1_auction_fact_revisions auction
        on auction.auction_revision_id = current_value.auction_revision_id
      cross join lateral pg_catalog.jsonb_array_elements(
        auction.auction_manifest->'purchases'
      ) purchase
      where current_value.tournament_id = '2026'
        and not exists (
          select 1
          from scoring_authority.matches match_value
          join scoring_authority.match_participants participant
            on participant.match_id = match_value.match_id
          where match_value.tournament_id = '2026'
            and match_value.round_number = candidate.round_number
            and match_value.status = 'FINAL'
            and match_value.scorecard_complete
            and match_value.finalized_at is not null
            and participant.player_id = purchase->>'player_id'
        )
    )
$$;


ALTER FUNCTION production_control.calcutta_v1_completed_rounds() OWNER TO postgres;

--
-- Name: calcutta_v1_completed_rounds(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.calcutta_v1_completed_rounds(target text) RETURNS integer[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(pg_catalog.array_agg(candidate.round_number
    order by candidate.round_number), '{}'::integer[])
  from pg_catalog.generate_series(1, 3) candidate(round_number)
  where exists (
      select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = target
        and match_value.round_number = candidate.round_number
    )
    and not exists (
      select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = target
        and match_value.round_number = candidate.round_number
        and (match_value.status <> 'FINAL'
          or not match_value.scorecard_complete
          or match_value.finalized_at is null)
    )
    and not exists (
      select 1
      from scoring_authority.calcutta_v1_current current_value
      join scoring_authority.calcutta_v1_auction_fact_revisions auction
        on auction.auction_revision_id = current_value.auction_revision_id
      cross join lateral pg_catalog.jsonb_array_elements(
        auction.auction_manifest->'purchases'
      ) purchase
      where current_value.tournament_id = target and not exists (
        select 1 from scoring_authority.matches match_value
        join scoring_authority.match_participants participant
          on participant.match_id = match_value.match_id
        where match_value.tournament_id = target
          and match_value.round_number = candidate.round_number
          and match_value.status = 'FINAL'
          and match_value.scorecard_complete
          and match_value.finalized_at is not null
          and participant.player_id = purchase->>'player_id'
      )
    )
$$;


ALTER FUNCTION production_control.calcutta_v1_completed_rounds(target text) OWNER TO postgres;

--
-- Name: calcutta_v1_hash(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.calcutta_v1_hash(input jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
  select pg_catalog.encode(extensions.digest(input::text, 'sha256'), 'hex')
$$;


ALTER FUNCTION production_control.calcutta_v1_hash(input jsonb) OWNER TO postgres;

--
-- Name: calcutta_v1_source_revision(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.calcutta_v1_source_revision(target_tournament_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select production_control.calcutta_source_before_full_net_v3(target_tournament_id)||jsonb_build_object(
    'calculation_policy','production-full-course-handicap-v1','full_net_authority',production_control.full_net_tournament_v1(
      target_tournament_id,production_control.calcutta_v1_completed_rounds(target_tournament_id)));
$$;


ALTER FUNCTION production_control.calcutta_v1_source_revision(target_tournament_id text) OWNER TO postgres;

--
-- Name: canonical_abort_annual_scoring_transition_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_abort_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  transition_value production_control.annual_scoring_transitions_v1%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  target production_control.future_tournament_catalog_v1%rowtype;
  successor_generation
    production_control.future_annual_runtime_generations_v1%rowtype;
  current_generation
    production_control.future_annual_runtime_generations_v1%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  legacy_root production_control.scoring_admission_closures%rowtype;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(
    input#>>'{authorization,player_id}'
  ));
  actor_auth uuid := (input#>>'{authorization,auth_user_id}')::uuid;
  next_admission_generation uuid := extensions.gen_random_uuid();
  admission_was_stopped boolean;
  predecessor_was_closed boolean;
  post_close_count integer;
  identity_rebind jsonb;
  side_game_rebind jsonb;
  response_value jsonb;
begin
  perform production_control.assert_canonical_annual_transition_context_v2(input,canonical_context);
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'ABORT', input, canonical_context
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'ABORT', input, canonical_context
  );
  if existing is not null then return existing; end if;
  select value.* into strict transition_value
  from production_control.annual_scoring_transitions_v1 value
  where value.transition_id = (input->>'transition_id')::uuid
  for update;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = canonical_context->>'resource_id' for update;
  select value.* into strict target
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = transition_value.successor_tournament_id
  for update;
  select value.* into strict successor_generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.runtime_generation_id = transition_value.runtime_generation_id
  for update;
  admission_was_stopped := transition_value.transition_status in (
    'CLOSING', 'CLOSED'
  );
  predecessor_was_closed := transition_value.transition_status = 'CLOSED';
  if transition_value.transition_status not in (
       'PREPARED', 'CLOSING', 'CLOSED'
     )
     or pointer.tournament_id <>
       transition_value.predecessor_tournament_id
     or pointer.pointer_revision <>
       transition_value.expected_pointer_revision
     or input->>'expected_current_tournament_id' is distinct from
       pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or target.lifecycle <> 'READY_FOR_ACTIVATION'
     or target.lifecycle_revision <>
       transition_value.successor_prepared_lifecycle_revision
     or successor_generation.generation_status <> 'PREPARED'
     or input->>'expected_runtime_generation_id' is distinct from
       successor_generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id' is distinct from
       successor_generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id' is distinct from
       successor_generation.admission_generation_id::text then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_ABORT_NOT_SAFE';
  end if;

  if admission_was_stopped then
    select value.* into strict closure
    from production_control.scoring_admission_closures value
    where value.closure_id = transition_value.predecessor_closure_id
    for update;
    if canonical_context->>'resource_class'='CERTIFICATION' then
      perform production_control.assert_certification_annual_abort_drain_v1(closure.closure_id,canonical_context);
    else
    select pg_catalog.count(*)::integer into post_close_count
    from scoring_authority.scoring_ingress_leases value
    where value.tournament_id = pointer.tournament_id
      and value.admission_generation_id = closure.admission_generation_id
      and value.admission_sequence > closure.lease_high_watermark;
    if production_control.annual_scoring_unresolved_count_v1(
         pointer.tournament_id, closure.admission_generation_id
       ) <> 0
       or post_close_count <> 0 then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ANNUAL_SCORING_ABORT_DRAIN_REQUIRED';
    end if;

    end if;

    if canonical_context->>'resource_class'='CERTIFICATION' then
      perform production_control.rebind_certification_annual_abort_v1(closure.closure_id,input,next_admission_generation,canonical_context);
    elsif pointer.tournament_id = '2026' then
      select value.* into strict activation
      from production_control.cutover_activation_state value
      where value.scope_key = canonical_context->>'resource_id' for update;
      select value.* into strict gate
      from scoring_authority.ingress_gates value
      where value.tournament_id = '2026' for update;
      select value.* into strict legacy_root
      from production_control.scoring_admission_closures value
      where value.closure_id = closure.prior_legacy_closure_id;
      if coalesce((input->>'expected_platform_activation_revision')::bigint, -1)
           <> activation.activation_revision
         or input->>'expected_platform_authority_generation_id'
           is distinct from activation.authority_generation_id::text
         or input->>'expected_platform_admission_generation_id'
           is distinct from gate.admission_generation_id::text
         or coalesce((input->>'expected_platform_admission_revision')::bigint, -1)
           <> gate.admission_revision
         or activation.state <> 'SCORING_COMMITTED'
         or activation.current_authority <> 'SUPABASE'
         or not activation.scoring_ingress_enabled
         or activation.active_transition_epoch_id is not null
         or gate.state <> 'PAUSED'
         or gate.authority <> 'SUPABASE'
         or gate.admission_state <> 'CLOSED'
         or gate.active_closure_id is distinct from closure.closure_id
         or closure.closure_kind <> 'SUPABASE_INGRESS'
         or closure.authority <> 'SUPABASE'
         or closure.status not in ('CLOSING', 'CLOSED')
         or legacy_root.closure_kind <> 'LEGACY_ADMISSION'
         or legacy_root.status <> 'CONSUMED' then
        raise exception using errcode = '40001',
          message = 'PRODUCTION_ANNUAL_SCORING_ABORT_NOT_SAFE';
      end if;
      update production_control.scoring_admission_closures set
        status = 'REOPENED', reopened_at = pg_catalog.clock_timestamp()
      where closure_id = closure.closure_id;
      update scoring_authority.ingress_gates set
        state = 'OPEN', authority = 'SUPABASE',
        admission_state = 'CLOSED',
        admission_revision = admission_revision + 1,
        active_closure_id = legacy_root.closure_id,
        external_fence_evidence_id = legacy_root.external_fence_evidence_id,
        unresolved_client_queues = 0,
        updated_by = actor_player,
        updated_at = pg_catalog.clock_timestamp()
      where tournament_id = '2026';
      update production_control.cutover_activation_state set
        activation_revision = activation_revision + 1,
        updated_by = actor_player,
        updated_at = pg_catalog.clock_timestamp()
      where scope_key = canonical_context->>'resource_id';
    else
      select value.* into strict annual
      from production_control.annual_scoring_runtime_authorities_v1 value
      where value.tournament_id = pointer.tournament_id for update;
      select value.* into strict current_generation
      from production_control.future_annual_runtime_generations_v1 value
      where value.runtime_generation_id = annual.runtime_generation_id
        and value.generation_status = 'ACTIVE' for update;
      if annual.active_closure_id is distinct from closure.closure_id
         or annual.authority_status not in ('ACTIVE', 'CLOSED')
         or annual.admission_state not in ('CLOSING', 'CLOSED')
         or annual.admission_generation_id is distinct from
           current_generation.admission_generation_id
         or input->>'expected_predecessor_runtime_generation_id'
           is distinct from
           current_generation.runtime_generation_id::text
         or input->>'expected_predecessor_annual_authority_generation_id'
           is distinct from
           annual.authority_generation_id::text
         or input->>'expected_predecessor_annual_admission_generation_id'
           is distinct from
           annual.admission_generation_id::text
         or coalesce(
           (input->>'expected_predecessor_annual_admission_revision')::bigint,
           -1
         )
           <> annual.admission_revision then
        raise exception using errcode = '40001',
          message = 'PRODUCTION_ANNUAL_SCORING_ABORT_NOT_SAFE';
      end if;
      update production_control.future_annual_runtime_generations_v1 set
        admission_generation_id = next_admission_generation,
        runtime_revision = runtime_revision + 1,
        updated_at = pg_catalog.clock_timestamp()
      where runtime_generation_id = current_generation.runtime_generation_id
        and admission_generation_id = annual.admission_generation_id;
      if pg_catalog.to_regprocedure(
        'production_control.rebind_future_participant_identity_admission_generation_v1(text,uuid,uuid,uuid,uuid,bigint)'
      ) is null then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_ANNUAL_IDENTITY_ADMISSION_REBIND_REQUIRED';
      end if;
      execute 'select production_control.rebind_future_participant_identity_admission_generation_v1($1,$2,$3,$4,$5,$6)'
        into identity_rebind
        using pointer.tournament_id, current_generation.runtime_generation_id,
          current_generation.authority_generation_id,
          annual.admission_generation_id, next_admission_generation,
          pointer.pointer_revision;
      update production_control.scoring_admission_closures set
        status = 'REOPENED', reopened_at = pg_catalog.clock_timestamp()
      where closure_id = closure.closure_id;
      update production_control.annual_scoring_runtime_authorities_v1 set
        authority_status = 'ACTIVE', admission_state = 'OPEN',
        admission_generation_id = next_admission_generation,
        admission_revision = admission_revision + 1,
        active_closure_id = null, closed_at = null,
        updated_at = pg_catalog.clock_timestamp()
      where runtime_generation_id = annual.runtime_generation_id;
      if pg_catalog.to_regprocedure(
        'production_control.rebind_annual_side_game_admission_generation_v1(text,uuid,uuid,uuid,uuid,bigint)'
      ) is null then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_ANNUAL_SIDE_GAME_ADMISSION_REBIND_REQUIRED';
      end if;
      execute 'select production_control.rebind_annual_side_game_admission_generation_v1($1,$2,$3,$4,$5,$6)'
        into side_game_rebind
        using pointer.tournament_id, current_generation.runtime_generation_id,
          current_generation.authority_generation_id,
          annual.admission_generation_id, next_admission_generation,
          pointer.pointer_revision;
    end if;
  end if;

  update production_control.future_annual_runtime_generations_v1 set
    generation_status = 'ABORTED',
    closed_by_player_id = actor_player,
    closed_at = pg_catalog.clock_timestamp(),
    runtime_revision = runtime_revision + 1,
    updated_at = pg_catalog.clock_timestamp()
  where runtime_generation_id = transition_value.runtime_generation_id
    and generation_status = 'PREPARED';
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_ABORT_NOT_SAFE';
  end if;
  update production_control.future_tournament_catalog_v1 set
    lifecycle = 'CONFIGURING', lifecycle_revision = lifecycle_revision + 1,
    readiness_fingerprint = null, readiness_setup_revision = null,
    updated_by_player_id = actor_player,
    updated_by_auth_user_id = actor_auth,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target.tournament_id
    and lifecycle = 'READY_FOR_ACTIVATION';
  update production_control.future_runtime_promotions_v2 set
    runtime_status = 'PROMOTED', updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target.tournament_id
    and runtime_status = 'READY';
  update production_control.annual_scoring_transitions_v1 set
    transition_status = 'ABORTED', aborted_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where transition_id = transition_value.transition_id
    and transition_status in ('PREPARED', 'CLOSING', 'CLOSED');
  if admission_was_stopped and canonical_context->>'resource_class'='CERTIFICATION' then
    perform production_control.install_certification_annual_reopened_generation_v1(closure.closure_id,next_admission_generation,canonical_context);
  end if;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_ANNUAL_SCORING_PRECOMMIT_ABORTED_SAFE',
    'transitionId', transition_value.transition_id,
    'predecessorTournamentId', pointer.tournament_id,
    'successorTournamentId', target.tournament_id,
    'pointerRevision', pointer.pointer_revision,
    'pointerChanged', false, 'predecessorClosed', false,
    'predecessorWasClosed', predecessor_was_closed,
    'successorActivated', false,
    'predecessorAdmissionReopened', admission_was_stopped,
    'requiresExplicitAdmissionRecovery', false,
    'idempotent', false
  );
  perform production_control.store_canonical_annual_scoring_receipt_v2(
    'ABORT', input, response_value, canonical_context
  );
  return response_value;
exception
  when invalid_text_representation or no_data_found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_ABORT_NOT_SAFE';
end;
$_$;


ALTER FUNCTION production_control.canonical_abort_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_activate_annual_scoring_transition_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_activate_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  origin_value production_control.certification_initialization_origins_v1%rowtype;
  existing jsonb;
  transition_value production_control.annual_scoring_transitions_v1%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  predecessor production_control.future_tournament_catalog_v1%rowtype;
  successor production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  prior_annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  certificate jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  legacy_root_id uuid;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(
    input#>>'{authorization,player_id}'
  ));
  actor_auth uuid := (input#>>'{authorization,auth_user_id}')::uuid;
  predecessor_next_revision bigint;
  successor_next_revision bigint;
  certified_writer jsonb;
  response_value jsonb;
begin
  perform production_control.assert_canonical_annual_transition_context_v2(input,canonical_context);
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'ACTIVATE', input, canonical_context
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'ACTIVATE', input, canonical_context
  );
  if existing is not null then return existing; end if;
  select value.* into strict transition_value
  from production_control.annual_scoring_transitions_v1 value
  where value.transition_id = (input->>'transition_id')::uuid
  for update;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = canonical_context->>'resource_id' for update;
  select value.* into strict predecessor
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = transition_value.predecessor_tournament_id
  for update;
  select value.* into strict successor
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = transition_value.successor_tournament_id
  for update;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.runtime_generation_id = transition_value.runtime_generation_id
  for update;
  if canonical_context->>'resource_class'='PRODUCTION' then
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = canonical_context->>'resource_id';
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  else
    select * into strict origin_value from production_control.certification_initialization_origins_v1
    where resource_id=canonical_context->>'resource_id';
  end if;
  certificate :=
    production_control.annual_scoring_predecessor_certificate_v1(
      pointer.tournament_id
    );
  select value.* into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = transition_value.predecessor_closure_id;
  if pointer.tournament_id <> '2026' then
    select value.* into strict prior_annual
    from production_control.annual_scoring_runtime_authorities_v1 value
    where value.tournament_id = pointer.tournament_id for update;
    legacy_root_id := prior_annual.legacy_root_closure_id;
  else
    legacy_root_id := closure.prior_legacy_closure_id;
  end if;
  if transition_value.transition_status <> 'CLOSED'
     or pointer.tournament_id <> transition_value.predecessor_tournament_id
     or pointer.pointer_revision <> transition_value.expected_pointer_revision
     or input->>'expected_current_tournament_id' is distinct from
       pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or predecessor.lifecycle <> 'ACTIVE'
     or predecessor.lifecycle_revision <>
       transition_value.predecessor_lifecycle_revision
     or successor.lifecycle <> 'READY_FOR_ACTIVATION'
     or successor.lifecycle_revision <>
       transition_value.successor_prepared_lifecycle_revision
     or successor.readiness_fingerprint is distinct from
       transition_value.readiness_fingerprint
     or generation.generation_status <> 'PREPARED'
     or generation.pointer_revision <> pointer.pointer_revision + 1
     or generation.authority_generation_id is distinct from
       transition_value.authority_generation_id
     or generation.admission_generation_id is distinct from
       transition_value.admission_generation_id
     or input->>'expected_runtime_generation_id'
       is distinct from generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id'
       is distinct from generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id'
       is distinct from generation.admission_generation_id::text
     or coalesce((certificate->>'certified')::boolean, false) is not true
     or certificate->>'closureId'
       is distinct from transition_value.predecessor_closure_id::text
     or certificate->>'fingerprint'
       is distinct from transition_value.predecessor_boundary_fingerprint
     or exists (
       select 1 from production_control.future_annual_runtime_generations_v1
       where generation_status = 'ACTIVE'
         and tournament_id <> pointer.tournament_id
     ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PRECOMMIT_ABORTED',
      detail = coalesce((certificate->'blockers')::text, '[]');
  end if;
  perform production_control.assert_future_scoring_runtime_capability_v1(
    successor.tournament_id, generation.runtime_generation_id,
    generation.authority_generation_id, generation.admission_generation_id
  );


  if pg_catalog.to_regprocedure(
    'production_control.bind_future_participant_identity_runtime_v1(text,uuid,uuid,uuid,text,uuid)'
  ) is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_IDENTITY_CAPABILITY_REQUIRED';
  end if;
  execute 'select production_control.bind_future_participant_identity_runtime_v1($1,$2,$3,$4,$5,$6)'
    using successor.tournament_id, generation.runtime_generation_id,
      generation.authority_generation_id, generation.admission_generation_id,
      actor_player, actor_auth;
  predecessor_next_revision := predecessor.lifecycle_revision + 1;
  successor_next_revision := successor.lifecycle_revision + 1;
  update production_control.future_tournament_catalog_v1 set
    lifecycle = 'CLOSED', lifecycle_revision = predecessor_next_revision,
    updated_by_player_id = actor_player,
    updated_by_auth_user_id = actor_auth,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = predecessor.tournament_id
    and lifecycle = 'ACTIVE'
    and lifecycle_revision = predecessor.lifecycle_revision;
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_POINTER_CAS_FAILED';
  end if;
  if predecessor.tournament_id <> '2026' then
    update production_control.future_annual_runtime_generations_v1 set
      generation_status = 'CLOSED',
      closed_by_player_id = actor_player,
      closed_at = pg_catalog.clock_timestamp(),
      runtime_revision = runtime_revision + 1,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = predecessor.tournament_id
      and generation_status = 'ACTIVE';
    if not found then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_ANNUAL_SCORING_POINTER_CAS_FAILED';
    end if;
  end if;
  update production_control.future_tournament_catalog_v1 set
    lifecycle = 'ACTIVE', lifecycle_revision = successor_next_revision,
    updated_by_player_id = actor_player,
    updated_by_auth_user_id = actor_auth,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = successor.tournament_id
    and lifecycle = 'READY_FOR_ACTIVATION'
    and lifecycle_revision = successor.lifecycle_revision;
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_POINTER_CAS_FAILED';
  end if;
  update production_control.current_tournament_pointer_v1 set
    tournament_id = successor.tournament_id,
    tournament_year = successor.tournament_year,
    pointer_revision = pointer.pointer_revision + 1,
    lifecycle_revision = successor_next_revision,
    updated_by_player_id = actor_player,
    updated_by_auth_user_id = actor_auth,
    updated_at = pg_catalog.clock_timestamp()
  where scope_key = canonical_context->>'resource_id'
    and tournament_id = predecessor.tournament_id
    and pointer_revision = transition_value.expected_pointer_revision
    and lifecycle_revision = predecessor.lifecycle_revision;
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_POINTER_CAS_FAILED';
  end if;
  update production_control.future_annual_runtime_generations_v1 set
    generation_status = 'ACTIVE',
    pointer_revision = pointer.pointer_revision + 1,
    activated_by_player_id = actor_player,
    activated_by_auth_user_id = actor_auth,
    activated_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where runtime_generation_id = generation.runtime_generation_id
    and generation_status = 'PREPARED';
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_POINTER_CAS_FAILED';
  end if;
  insert into production_control.annual_scoring_runtime_authorities_v1 (
    resource_class,certification_resource_id,runtime_generation_id, tournament_id, platform_tournament_id,
    platform_authority_generation_id, platform_admission_generation_id,
    pointer_revision, lifecycle_revision, authority_generation_id,
    admission_generation_id, google_writer_generation_id,
    destination_workbook_id, google_target_contract_fingerprint,
    authority_status, admission_state,
    admission_revision, legacy_root_closure_id,
    predecessor_tournament_id, predecessor_closure_id,
    predecessor_boundary_fingerprint, activated_by_player_id,
    activated_by_auth_user_id
  ) values (
    canonical_context->>'resource_class',case when canonical_context->>'resource_class'='CERTIFICATION' then canonical_context->>'resource_id' end,
    generation.runtime_generation_id, successor.tournament_id, '2026',
    case when canonical_context->>'resource_class'='CERTIFICATION' then origin_value.authority_epoch_id else activation.authority_generation_id end,
    case when canonical_context->>'resource_class'='CERTIFICATION' then origin_value.admission_generation_id else gate.admission_generation_id end,
    pointer.pointer_revision + 1, successor_next_revision,
    generation.authority_generation_id, generation.admission_generation_id,
    null, null, null, -- Retired optional destination metadata; never fabricated certification.
    'ACTIVE', 'OPEN', 1, legacy_root_id,
    predecessor.tournament_id, closure.closure_id,
    transition_value.predecessor_boundary_fingerprint,
    actor_player, actor_auth
  );
  update production_control.future_runtime_promotions_v2 set
    runtime_status = 'ACTIVE', updated_at = pg_catalog.clock_timestamp()
  where tournament_id = successor.tournament_id;
  update production_control.annual_scoring_transitions_v1 set
    transition_status = 'COMMITTED',
    committed_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where transition_id = transition_value.transition_id
    and transition_status = 'CLOSED';
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_POINTER_CAS_FAILED';
  end if;
  if canonical_context->>'resource_class'='CERTIFICATION' then
    perform production_control.install_certification_annual_successor_v1(transition_value.transition_id,canonical_context);
  end if;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_ANNUAL_SCORING_TRANSITION_COMMITTED',
    'transitionId', transition_value.transition_id,
    'predecessorTournamentId', predecessor.tournament_id,
    'successorTournamentId', successor.tournament_id,
    'pointerRevision', pointer.pointer_revision + 1,
    'runtimeGenerationId', generation.runtime_generation_id,
    'authorityGenerationId', generation.authority_generation_id,
    'admissionGenerationId', generation.admission_generation_id,
    'predecessorClosed', true, 'successorActivated', true,
    'pointerChanged', true, 'idempotent', false
  );
  perform production_control.store_canonical_annual_scoring_receipt_v2(
    'ACTIVATE', input, response_value, canonical_context
  );
  return response_value;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PRECOMMIT_ABORTED';
end;
$_$;


ALTER FUNCTION production_control.canonical_activate_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_annual_scope_key_v2(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_annual_scope_key_v2() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION')then
  return production_control.current_certification_context_v1()->>'resource_id';
 end if;
 return 'BAGGER_INV_PRODUCTION';
end;$$;


ALTER FUNCTION production_control.canonical_annual_scope_key_v2() OWNER TO postgres;

--
-- Name: canonical_calcutta_auction_core_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_calcutta_auction_core_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  current_value scoring_authority.calcutta_v1_current%rowtype;
  auction_value scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  publication_value scoring_authority.calcutta_v1_publication_revisions%rowtype;
  existing_response jsonb;
  response_value jsonb;
  manifest_value jsonb;
  auction_fingerprint_value text;
  resource_fingerprint_value text;
  request_fingerprint_value text := pg_catalog.lower(
    coalesce(input->>'request_fingerprint', '')
  );
  payload_hash_value text := production_control.calcutta_v1_hash(input);
  actor_player text := pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  ));
  actor_auth_user uuid := nullif(
    input#>>'{authorization,auth_user_id}', ''
  )::uuid;
begin
  existing_response := production_control.lookup_cutover_receipt(
    'CALCUTTA_V1_REPLACE_AUCTION', input
  );
  if existing_response is not null then return existing_response; end if;
  if request_fingerprint_value !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_AUCTION_INPUT_INVALID';
  end if;

  if context is null then
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  end if;
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026'
  for update;

  if current_value.state = 'NOT_CONFIGURED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REQUIRED';
  end if;
  if current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1)
     or current_value.configuration_fingerprint is distinct from
       nullif(input->>'expected_configuration_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REVISION_CONFLICT';
  end if;
  if current_value.auction_revision <>
       coalesce((input->>'expected_auction_revision')::bigint, -1)
     or current_value.auction_fingerprint is distinct from
       nullif(input->>'expected_auction_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_AUCTION_REVISION_CONFLICT';
  end if;
  if current_value.publication_revision <>
       coalesce((input->>'expected_publication_revision')::bigint, -1) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_PUBLICATION_REVISION_CONFLICT';
  end if;

  manifest_value :=
    production_control.build_production_calcutta_v1_auction(input);
  auction_fingerprint_value := production_control.calcutta_v1_hash(
    manifest_value
  );
  if context is null then
  resource_fingerprint_value := production_control.calcutta_v1_hash(
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-calcutta-v1',
      'environment', 'PRODUCTION',
      'project_ref', resource.project_ref,
      'project_url', resource.project_url,
      'source_workbook_id', resource.google_workbook_id,
      'tournament_id', resource.current_tournament_id,
      'vercel_project_id', input->>'vercel_project_id',
      'vercel_team_id', input->>'vercel_team_id',
      'vercel_environment', 'production',
      'deployment_commit', activation.expected_deployment_commit,
      'authority_epoch_id', activation.authority_generation_id,
      'activation_revision', activation.activation_revision
    )
  );
  else
    resource_fingerprint_value := context->>'resource_fingerprint';
  end if;

  insert into scoring_authority.calcutta_v1_auction_fact_revisions (
    tournament_id, auction_revision, state, auction_manifest,
    auction_fingerprint, resource_fingerprint, activation_revision,
    authority_epoch_id, recorded_by_player_id, recorded_by_auth_user_id,
    request_fingerprint, request_payload_hash, recorded_at
  ) values (
    '2026', current_value.auction_revision + 1, 'AUCTION_COMPLETE',
    manifest_value, auction_fingerprint_value, resource_fingerprint_value,
    case when context is null then activation.activation_revision else (context->>'activation_revision')::bigint end, case when context is null then activation.authority_generation_id else (context->>'authority_epoch_id')::uuid end,
    actor_player, actor_auth_user, request_fingerprint_value,
    payload_hash_value, pg_catalog.now()
  ) returning * into auction_value;

  insert into scoring_authority.calcutta_v1_publication_revisions (
    tournament_id, publication_revision, configuration_revision,
    auction_revision, configuration_fingerprint, auction_fingerprint,
    publication_state, action, actor_player_id, actor_auth_user_id,
    request_fingerprint, request_payload_hash, published_at
  ) values (
    '2026', current_value.publication_revision + 1,
    current_value.configuration_revision, auction_value.auction_revision,
    current_value.configuration_fingerprint, auction_fingerprint_value,
    'UNPUBLISHED', 'AUCTION_REPLACED', actor_player, actor_auth_user,
    production_control.calcutta_v1_hash(pg_catalog.jsonb_build_object(
      'operation', 'AUCTION_REPLACED',
      'request_fingerprint', request_fingerprint_value
    )), payload_hash_value, null
  ) returning * into publication_value;

  update scoring_authority.calcutta_v1_recalculation_jobs
  set status = 'SUPERSEDED', claimed_by = null, claim_token = null,
      lease_expires_at = null, completed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' and status in ('PENDING', 'RUNNING');
  update scoring_authority.calcutta_v1_result_revisions
  set is_current = false, superseded_at = pg_catalog.now()
  where tournament_id = '2026' and is_current;

  update scoring_authority.calcutta_v1_current
  set auction_revision_id = auction_value.auction_revision_id,
      auction_revision = auction_value.auction_revision,
      auction_fingerprint = auction_fingerprint_value,
      publication_revision_id = publication_value.publication_revision_id,
      publication_revision = publication_value.publication_revision,
      publication_state = 'UNPUBLISHED', state = 'AUCTION_COMPLETE',
      result_revision = 0, updated_at = pg_catalog.now()
  where tournament_id = '2026';

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'PRODUCTION_CALCUTTA_V1_AUCTION_REPLACED', actor_player,
    pg_catalog.jsonb_build_object(
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', auction_value.auction_revision,
      'auction_fingerprint', auction_fingerprint_value,
      'publication_revision', publication_value.publication_revision,
      'publication_state', 'UNPUBLISHED',
      'purchase_count', pg_catalog.jsonb_array_length(
        manifest_value->'purchases'
      ),
      'ownership_count', pg_catalog.jsonb_array_length(
        manifest_value->'ownership'
      ),
      'pot', manifest_value->>'pot',
      'currency_code', 'USD',
      'authority_changed', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_CALCUTTA_V1_AUCTION_REPLACED', 'CALCUTTA', '2026',
    actor_player, request_fingerprint_value, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'configuration_revision', current_value.configuration_revision,
      'auction_revision', auction_value.auction_revision,
      'auction_fingerprint', auction_fingerprint_value,
      'publication_revision', publication_value.publication_revision,
      'publication_state', 'UNPUBLISHED'
    )
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_CALCUTTA_V1_AUCTION_REPLACED',
    'state', 'AUCTION_COMPLETE',
    'publication_state', 'UNPUBLISHED',
    'configuration_revision', current_value.configuration_revision,
    'configuration_fingerprint', current_value.configuration_fingerprint,
    'auction_revision', auction_value.auction_revision,
    'auction_fingerprint', auction_fingerprint_value,
    'publication_revision', publication_value.publication_revision,
    'currency_code', 'USD',
    'pot', manifest_value->>'pot',
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'CALCUTTA_V1_REPLACE_AUCTION', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.canonical_calcutta_auction_core_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: canonical_calcutta_clear_core_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_calcutta_clear_core_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  current_value scoring_authority.calcutta_v1_current%rowtype;
  auction_value scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  publication_value scoring_authority.calcutta_v1_publication_revisions%rowtype;
  existing_response jsonb;
  response_value jsonb;
  manifest_value jsonb;
  predecessor_manifest jsonb;
  target_player text := pg_catalog.btrim(coalesce(input->>'player_id', ''));
  remaining_purchases jsonb;
  remaining_ownership jsonb;
  pot_value numeric;
  auction_fingerprint_value text;
  resource_fingerprint_value text;
  request_fingerprint_value text := pg_catalog.lower(
    coalesce(input->>'request_fingerprint', '')
  );
  payload_hash_value text := production_control.calcutta_v1_hash(input);
  actor_player text := pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  ));
  actor_auth_user uuid := nullif(
    input#>>'{authorization,auth_user_id}', ''
  )::uuid;
begin
  existing_response := production_control.lookup_cutover_receipt(
    'CALCUTTA_V1_CLEAR_ENTRY', input
  );
  if existing_response is not null then return existing_response; end if;
  if request_fingerprint_value !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_AUCTION_INPUT_INVALID';
  end if;

  if context is null then
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  end if;
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026'
  for update;

  -- Recheck after acquiring the same canonical locks used by Save/Publish.
  -- Concurrent retries must return the original receipt, not create revisions.
  existing_response := production_control.lookup_cutover_receipt('CALCUTTA_V1_CLEAR_ENTRY', input);
  if existing_response is not null then return existing_response; end if;
  if current_value.publication_state <> 'UNPUBLISHED' then
    raise exception using errcode='55000', message='PRODUCTION_CALCUTTA_CLEAR_PUBLISHED_DENIED';
  end if;
  if current_value.result_revision <> 0
     or exists(select 1 from scoring_authority.calcutta_v1_result_revisions
       where tournament_id='2026' and (is_current or auction_revision_id=current_value.auction_revision_id))
     or exists(select 1 from scoring_authority.calcutta_v1_recalculation_jobs
       where tournament_id='2026' and status in ('PENDING','RUNNING')) then
    raise exception using errcode='55000', message='PRODUCTION_CALCUTTA_CLEAR_RESULT_DEPENDENCY';
  end if;
  if not exists(select 1 from scoring_authority.tournament_players
      where tournament_id='2026' and player_id=target_player and participation_status='ACTIVE') then
    raise exception using errcode='22023', message='PRODUCTION_CALCUTTA_CLEAR_PLAYER_DENIED';
  end if;
  if current_value.state = 'NOT_CONFIGURED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REQUIRED';
  end if;
  if current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1)
     or current_value.configuration_fingerprint is distinct from
       nullif(input->>'expected_configuration_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REVISION_CONFLICT';
  end if;
  if current_value.auction_revision <>
       coalesce((input->>'expected_auction_revision')::bigint, -1)
     or current_value.auction_fingerprint is distinct from
       nullif(input->>'expected_auction_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_AUCTION_REVISION_CONFLICT';
  end if;
  if current_value.publication_revision <>
       coalesce((input->>'expected_publication_revision')::bigint, -1) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_PUBLICATION_REVISION_CONFLICT';
  end if;

  select auction_manifest into strict predecessor_manifest
  from scoring_authority.calcutta_v1_auction_fact_revisions
  where auction_revision_id=current_value.auction_revision_id and tournament_id='2026';
  if not exists(select 1 from jsonb_array_elements(predecessor_manifest->'purchases') p
      where p->>'player_id'=target_player) then
    raise exception using errcode='55000', message='PRODUCTION_CALCUTTA_ENTRY_NOT_ENTERED';
  end if;
  select coalesce(jsonb_agg(p order by p->>'player_id'),'[]'::jsonb),
         coalesce(sum((p->>'purchase_price')::numeric),0)
    into remaining_purchases,pot_value
    from jsonb_array_elements(predecessor_manifest->'purchases') p where p->>'player_id'<>target_player;
  select coalesce(jsonb_agg(o order by o->>'player_id',o->>'owner_player_id'),'[]'::jsonb)
    into remaining_ownership
    from jsonb_array_elements(predecessor_manifest->'ownership') o where o->>'player_id'<>target_player;
  -- Derive exclusively from locked canonical facts; the client cannot replace another entry.
  manifest_value := predecessor_manifest || jsonb_build_object(
    'purchases',remaining_purchases,'ownership',remaining_ownership,'pot',pot_value);
  if jsonb_array_length(remaining_purchases)>0 then
    manifest_value := production_control.build_production_calcutta_v1_auction(manifest_value);
  elsif remaining_ownership <> '[]'::jsonb then
    raise exception using errcode='55000', message='PRODUCTION_CALCUTTA_CLEAR_ORPHAN_OWNERSHIP';
  end if;
  auction_fingerprint_value := production_control.calcutta_v1_hash(
    manifest_value
  );
  if context is null then
  resource_fingerprint_value := production_control.calcutta_v1_hash(
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-calcutta-v1',
      'environment', 'PRODUCTION',
      'project_ref', resource.project_ref,
      'project_url', resource.project_url,
      'source_workbook_id', resource.google_workbook_id,
      'tournament_id', resource.current_tournament_id,
      'vercel_project_id', input->>'vercel_project_id',
      'vercel_team_id', input->>'vercel_team_id',
      'vercel_environment', 'production',
      'deployment_commit', activation.expected_deployment_commit,
      'authority_epoch_id', activation.authority_generation_id,
      'activation_revision', activation.activation_revision
    )
  );
  else
    resource_fingerprint_value := context->>'resource_fingerprint';
  end if;

  insert into scoring_authority.calcutta_v1_auction_fact_revisions (
    tournament_id, auction_revision, state, auction_manifest,
    auction_fingerprint, resource_fingerprint, activation_revision,
    authority_epoch_id, recorded_by_player_id, recorded_by_auth_user_id,
    request_fingerprint, request_payload_hash, recorded_at
  ) values (
    '2026', current_value.auction_revision + 1, 'AUCTION_COMPLETE',
    manifest_value, auction_fingerprint_value, resource_fingerprint_value,
    case when context is null then activation.activation_revision else (context->>'activation_revision')::bigint end, case when context is null then activation.authority_generation_id else (context->>'authority_epoch_id')::uuid end,
    actor_player, actor_auth_user, request_fingerprint_value,
    payload_hash_value, pg_catalog.now()
  ) returning * into auction_value;

  insert into scoring_authority.calcutta_v1_publication_revisions (
    tournament_id, publication_revision, configuration_revision,
    auction_revision, configuration_fingerprint, auction_fingerprint,
    publication_state, action, actor_player_id, actor_auth_user_id,
    request_fingerprint, request_payload_hash, published_at
  ) values (
    '2026', current_value.publication_revision + 1,
    current_value.configuration_revision, auction_value.auction_revision,
    current_value.configuration_fingerprint, auction_fingerprint_value,
    'UNPUBLISHED', 'AUCTION_REPLACED', actor_player, actor_auth_user,
    production_control.calcutta_v1_hash(pg_catalog.jsonb_build_object(
      'operation', 'AUCTION_REPLACED',
      'request_fingerprint', request_fingerprint_value
    )), payload_hash_value, null
  ) returning * into publication_value;

  update scoring_authority.calcutta_v1_current
  set auction_revision_id = auction_value.auction_revision_id,
      auction_revision = auction_value.auction_revision,
      auction_fingerprint = auction_fingerprint_value,
      publication_revision_id = publication_value.publication_revision_id,
      publication_revision = publication_value.publication_revision,
      publication_state = 'UNPUBLISHED', state = 'AUCTION_COMPLETE',
      result_revision = 0, updated_at = pg_catalog.now()
  where tournament_id = '2026';

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'PRODUCTION_CALCUTTA_V1_ENTRY_CLEARED', actor_player,
    pg_catalog.jsonb_build_object(
      'cleared_player_id', target_player,
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', auction_value.auction_revision,
      'auction_fingerprint', auction_fingerprint_value,
      'publication_revision', publication_value.publication_revision,
      'publication_state', 'UNPUBLISHED',
      'prior_auction_revision', current_value.auction_revision,
      'purchase_count', pg_catalog.jsonb_array_length(
        manifest_value->'purchases'
      ),
      'ownership_count', pg_catalog.jsonb_array_length(
        manifest_value->'ownership'
      ),
      'pot', manifest_value->>'pot',
      'currency_code', 'USD',
      'authority_changed', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_CALCUTTA_V1_ENTRY_CLEARED', 'CALCUTTA', '2026',
    actor_player, request_fingerprint_value, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'cleared_player_id', target_player,
      'prior_auction_revision', current_value.auction_revision,
      'configuration_revision', current_value.configuration_revision,
      'auction_revision', auction_value.auction_revision,
      'auction_fingerprint', auction_fingerprint_value,
      'publication_revision', publication_value.publication_revision,
      'publication_state', 'UNPUBLISHED'
    )
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_CALCUTTA_V1_ENTRY_CLEARED',
    'state', 'AUCTION_COMPLETE',
    'cleared_player_id', target_player,
    'publication_state', 'UNPUBLISHED',
    'configuration_revision', current_value.configuration_revision,
    'configuration_fingerprint', current_value.configuration_fingerprint,
    'auction_revision', auction_value.auction_revision,
    'auction_fingerprint', auction_fingerprint_value,
    'publication_revision', publication_value.publication_revision,
    'currency_code', 'USD',
    'pot', manifest_value->>'pot',
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'CALCUTTA_V1_CLEAR_ENTRY', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.canonical_calcutta_clear_core_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: canonical_claim_calcutta_v1_recalculation_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_claim_calcutta_v1_recalculation_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.calcutta_v1_current%rowtype;
  configuration_value scoring_authority.calcutta_v1_configuration_revisions%rowtype;
  auction_value scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  job_value scoring_authority.calcutta_v1_recalculation_jobs%rowtype;
  existing_response jsonb;
  response_value jsonb;
  calculation_input jsonb;
  core_view jsonb;
  current_source jsonb;
  current_source_fingerprint text;
  replacement_job jsonb;
  expected_result_revision bigint;
  worker_value text := pg_catalog.btrim(coalesce(input->>'worker_id', ''));
  lease_seconds_value integer := least(
    300, greatest(
      15, coalesce((input->>'lease_seconds')::integer, 60)
    )
  );
  claim_token_value uuid;
begin
  perform production_control.assert_canonical_financial_worker_context_v1(input,canonical_context,'CALCUTTA');
  existing_response := production_control.lookup_cutover_receipt(
    'CALCUTTA_V1_CLAIM', input
  );
  if existing_response is not null then return existing_response; end if;
  if worker_value = '' or pg_catalog.length(worker_value) > 160 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_WORKER_ID_REQUIRED';
  end if;

  perform production_control.flush_score_derived_intents_v1('2026', 'CALCUTTA', 8);
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026'
  for update;
  if current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1)
     or current_value.configuration_fingerprint is distinct from
       nullif(input->>'expected_configuration_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REVISION_CONFLICT';
  end if;
  if current_value.auction_revision <>
       coalesce((input->>'expected_auction_revision')::bigint, -1)
     or current_value.auction_fingerprint is distinct from
       nullif(input->>'expected_auction_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_AUCTION_REVISION_CONFLICT';
  end if;
  if current_value.auction_revision = 0 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_AUCTION_FACTS_REQUIRED';
  end if;



  update scoring_authority.calcutta_v1_recalculation_jobs
  set status = case when attempts >= 5 then 'FAILED' else 'PENDING' end,
      claimed_by = null, claim_token = null, lease_expires_at = null,
      completed_at = case when attempts >= 5
        then pg_catalog.now() else null end,
      last_error_code = case when attempts >= 5
        then 'PRODUCTION_CALCUTTA_LEASE_EXHAUSTED' else null end,
      last_error_safe = case when attempts >= 5
        then 'Calcutta recalculation is temporarily unavailable.' else null end,
      updated_at = pg_catalog.now()
  where tournament_id = '2026'
    and configuration_revision = current_value.configuration_revision
    and configuration_fingerprint = current_value.configuration_fingerprint
    and auction_revision = current_value.auction_revision
    and auction_fingerprint = current_value.auction_fingerprint
    and activation_revision =
      (input->>'expected_activation_revision')::bigint
    and status = 'RUNNING' and lease_expires_at <= pg_catalog.now();

  select value.* into job_value
  from scoring_authority.calcutta_v1_recalculation_jobs value
  where value.tournament_id = '2026'
    and value.configuration_revision = current_value.configuration_revision
    and value.configuration_fingerprint =
      current_value.configuration_fingerprint
    and value.auction_revision = current_value.auction_revision
    and value.auction_fingerprint = current_value.auction_fingerprint
    and value.activation_revision =
      (input->>'expected_activation_revision')::bigint
    and value.status = 'PENDING' and value.delivery_dead_letter_at is null
    and value.delivery_attempts<5 and value.delivery_available_at<=clock_timestamp() and value.attempts < 5
  order by value.requested_at, value.job_id
  for update skip locked
  limit 1;

  if not found then
    if exists (
      select 1 from scoring_authority.calcutta_v1_recalculation_jobs value
      where value.tournament_id = '2026'
        and value.configuration_revision = current_value.configuration_revision
        and value.auction_revision = current_value.auction_revision
        and value.status = 'FAILED'
    ) then
      update scoring_authority.calcutta_v1_current
      set state = 'UNAVAILABLE', updated_at = pg_catalog.now()
      where tournament_id = '2026';
    end if;
    response_value := pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_CALCUTTA_V1_RECALCULATION_EMPTY',
      'job', null,
      'calculation_input', null,
      'idempotent', false
    );
    perform production_control.store_cutover_receipt(
      'CALCUTTA_V1_CLAIM', input, response_value
    );
    return response_value;
  end if;

  current_source := production_control.calcutta_v1_source_revision('2026');
  current_source_fingerprint := production_control.calcutta_v1_hash(
    current_source
  );
  if current_source_fingerprint <> job_value.source_fingerprint then
    update scoring_authority.calcutta_v1_recalculation_jobs
    set status = 'SUPERSEDED', completed_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    where job_id = job_value.job_id;
    replacement_job := case when job_value.delivery_score_origin then
      production_control.enqueue_score_calcutta_v1(
      'SOURCE_ADVANCED_BEFORE_CLAIM', worker_value, false, null, null
    )
      else production_control.enqueue_production_calcutta_v1(
      'SOURCE_ADVANCED_BEFORE_CLAIM', worker_value, false, null, null
    ) end;
    select value.* into strict job_value
    from scoring_authority.calcutta_v1_recalculation_jobs value
    where value.job_id = (replacement_job->>'job_id')::uuid
    for update;
  end if;

  claim_token_value := extensions.gen_random_uuid();
  update scoring_authority.calcutta_v1_recalculation_jobs
  set status = 'RUNNING', attempts = attempts + 1,
      claimed_by = worker_value, claim_token = claim_token_value,
      lease_expires_at = pg_catalog.now()
        + pg_catalog.make_interval(secs => lease_seconds_value),
      started_at = pg_catalog.now(), completed_at = null,
      updated_at = pg_catalog.now()
  where job_id = job_value.job_id
  returning * into job_value;

  select coalesce(pg_catalog.max(value.result_revision), 0)
    into expected_result_revision
  from scoring_authority.calcutta_v1_result_revisions value
  where value.tournament_id = '2026';
  select value.* into strict configuration_value
  from scoring_authority.calcutta_v1_configuration_revisions value
  where value.configuration_revision_id =
    current_value.configuration_revision_id;
  select value.* into strict auction_value
  from scoring_authority.calcutta_v1_auction_fact_revisions value
  where value.auction_revision_id = current_value.auction_revision_id;

  core_view := public.read_leaderboards_core_view('2026');
  core_view := jsonb_set(core_view,'{data,full_net_authority}',production_control.full_net_tournament_v1('2026'));
  if coalesce((core_view->>'ok')::boolean, false) is not true then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_CANONICAL_INPUT_UNAVAILABLE';
  end if;
  calculation_input := pg_catalog.jsonb_build_object(
    'tournament', core_view#>'{data,tournament}',
    'configuration', pg_catalog.jsonb_build_object(
      'tournament_id', '2026',
      'tournament_year', 2026,
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint',
        current_value.configuration_fingerprint,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'purchases', auction_value.auction_manifest->'purchases',
      'ownership', auction_value.auction_manifest->'ownership',
      'point_structure',
        configuration_value.configuration_manifest->'point_structure',
      'payout_structure',
        configuration_value.configuration_manifest->'payout_structure',
      'financial_contract',
        configuration_value.configuration_manifest->'financial_contract'
    ),
    'core_view', core_view->'data'
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_CALCUTTA_V1_RECALCULATION_CLAIMED',
    'job', pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id,
      'configuration_revision', job_value.configuration_revision,
      'configuration_fingerprint', job_value.configuration_fingerprint,
      'auction_revision', job_value.auction_revision,
      'auction_fingerprint', job_value.auction_fingerprint,
      'activation_revision', job_value.activation_revision,
      'source_fingerprint', job_value.source_fingerprint,
      'claim_token', job_value.claim_token,
      'lease_expires_at', job_value.lease_expires_at,
      'expected_result_revision', expected_result_revision
    ),
    'calculation_input', calculation_input,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'CALCUTTA_V1_CLAIM', input, response_value
  );
  return response_value;
end;
$$;


ALTER FUNCTION production_control.canonical_claim_calcutta_v1_recalculation_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_claim_competition_derived_jobs_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_claim_competition_derived_jobs_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_tournament text := pg_catalog.btrim(coalesce(
    input->>'tournament_id', ''
  ));
  target_engines text[];
  claims jsonb;
begin
  if canonical_context is not null then
    perform production_control.assert_canonical_scoring_context_v1(input,canonical_context,'RUNTIME');
    if canonical_context->>'phase' is distinct from 'WORKERS' then raise exception using errcode='42501',message='CERTIFICATION_DERIVED_CONTEXT_REQUIRED'; end if;
  end if;
  if (canonical_context is null and pg_catalog.upper(pg_catalog.btrim(coalesce(
       input->>'environment', ''
     ))) <> 'PREVIEW')
     or target_tournament = ''
     or pg_catalog.jsonb_typeof(input->'engine_keys') <> 'array' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_DERIVED_CLAIM_REQUIRED'
    );
  end if;
  select coalesce(pg_catalog.array_agg(
    pg_catalog.upper(pg_catalog.btrim(value))
  ), array[]::text[]) into target_engines
  from pg_catalog.jsonb_array_elements_text(input->'engine_keys') value;
  if pg_catalog.cardinality(target_engines) = 0 or exists (
    select 1 from pg_catalog.unnest(target_engines) requested(engine_key)
    where requested.engine_key not in (
      'TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES'
    )
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'DERIVED_ENGINE_NOT_SUPPORTED'
    );
  end if;
  with candidates as (
    select value.tournament_id, value.round_number, value.engine_key
    from scoring_authority.competition_recalculation_jobs value
    where value.tournament_id = target_tournament
      and value.round_number = 0
      and value.engine_key = any(target_engines)
      and value.status in ('PENDING', 'FAILED') and value.delivery_dead_letter_at is null
      and value.delivery_attempts<5 and value.delivery_available_at<=clock_timestamp()
    order by value.engine_key
    for update skip locked
  ), claimed as (
    update scoring_authority.competition_recalculation_jobs value set
      status = 'RUNNING', attempts = value.attempts + 1,
      started_at = pg_catalog.clock_timestamp(), completed_at = null,
      last_error_code = null, last_error_safe = null,
      updated_at = pg_catalog.now()
    from candidates candidate
    where value.tournament_id = candidate.tournament_id
      and value.round_number = candidate.round_number
      and value.engine_key = candidate.engine_key
    returning value.engine_key, value.started_at, value.requested_at,
      value.requested_source_revision, value.attempts
  ) select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'engine_key', engine_key, 'claim_started_at', started_at,
      'requested_at', requested_at,
      'requested_source_revision', requested_source_revision,
      'attempt', attempts
    ) order by engine_key), '[]'::jsonb)
  into claims from claimed;
  return pg_catalog.jsonb_build_object('ok', true, 'claims', claims);
end;
$$;


ALTER FUNCTION production_control.canonical_claim_competition_derived_jobs_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_claim_intelligence_derived_bundle_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_claim_intelligence_derived_bundle_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target text := pg_catalog.btrim(coalesce(input->>'tournament_id', ''));
  actor text := pg_catalog.left(pg_catalog.btrim(coalesce(
    input->>'requested_by', ''
  )), 180);
  claim_time timestamptz := pg_catalog.clock_timestamp();
  key_value text;
begin
  if canonical_context is not null then
    perform production_control.assert_canonical_scoring_context_v1(input,canonical_context,'RUNTIME');
    if canonical_context->>'phase' is distinct from 'WORKERS' then raise exception using errcode='42501',message='CERTIFICATION_DERIVED_CONTEXT_REQUIRED'; end if;
  end if;
  if (canonical_context is null and pg_catalog.upper(pg_catalog.btrim(coalesce(
       input->>'environment', ''
     ))) <> 'PREVIEW')
     or target = '' or actor = '' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_INTELLIGENCE_CLAIM_REQUIRED'
    );
  end if;
  if not production_control.intelligence_delivery_ready_v1(target,input->'engine_keys') then
    return jsonb_build_object('ok',true,'empty',true,'code','NO_PENDING_INTELLIGENCE');
  end if;
  for key_value in
    select pg_catalog.upper(pg_catalog.btrim(value))
    from pg_catalog.jsonb_array_elements_text(input->'engine_keys') value
  loop
    if key_value not in (
      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
      'TOURNAMENT_FINAL_RECAP'
    ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'DERIVED_ENGINE_NOT_SUPPORTED'
      );
    end if;
    insert into scoring_authority.competition_recalculation_jobs (
      tournament_id, round_number, engine_key, status,
      requested_source_revision, requested_at, started_at, updated_at
    ) values (
      target, 0, key_value, 'RUNNING',
      pg_catalog.jsonb_build_object('requestedBy', actor),
      claim_time, claim_time, pg_catalog.now()
    ) on conflict (tournament_id, round_number, engine_key) do update set
      status = 'RUNNING',
      requested_source_revision = scoring_authority.competition_recalculation_jobs.requested_source_revision,
      requested_at = claim_time, started_at = claim_time,
      completed_at = null, last_error_code = null,
      last_error_safe = null, updated_at = pg_catalog.now();
  end loop;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'claim_started_at', claim_time
  );
end;
$$;


ALTER FUNCTION production_control.canonical_claim_intelligence_derived_bundle_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_claim_net_skins_v1_recalculation_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_claim_net_skins_v1_recalculation_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  job_value scoring_authority.net_skins_v1_recalculation_jobs%rowtype;
  existing_response jsonb;
  response_value jsonb;
  calculation_input jsonb;
  worker_value text := pg_catalog.btrim(coalesce(input->>'worker_id', ''));
  lease_seconds_value integer := least(300, greatest(
    15, coalesce((input->>'lease_seconds')::integer, 60)
  ));
  current_source jsonb;
  current_source_fingerprint text;
  expected_result_revision bigint;
  claim_token_value uuid;
begin
  perform production_control.assert_canonical_financial_worker_context_v1(input,canonical_context,'NET_SKINS');
  existing_response := production_control.lookup_cutover_receipt(
    'NET_SKINS_V1_CLAIM', input
  );
  if existing_response is not null then return existing_response; end if;
  if worker_value = '' or pg_catalog.length(worker_value) > 160 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_WORKER_ID_REQUIRED';
  end if;

  select value.* into strict current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = '2026';
  if current_value.state <> 'CONFIGURED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_NET_SKINS_CONFIGURATION_REQUIRED';
  end if;
  if current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_NET_SKINS_CONFIGURATION_REVISION_CONFLICT';
  end if;

  perform production_control.flush_score_derived_intents_v1('2026', 'NET_SKINS', 8);

  update scoring_authority.net_skins_v1_recalculation_jobs
  set status = case when attempts >= 5 then 'FAILED' else 'PENDING' end,
      claimed_by = null,
      claim_token = null,
      lease_expires_at = null,
      completed_at = case when attempts >= 5
        then pg_catalog.now() else null end,
      last_error_code = case when attempts >= 5
        then 'PRODUCTION_NET_SKINS_LEASE_EXHAUSTED' else null end,
      last_error_safe = case when attempts >= 5
        then 'Net Skins recalculation is temporarily unavailable.' else null end,
      updated_at = pg_catalog.now()
  where tournament_id = '2026'
    and configuration_revision = current_value.configuration_revision
    and status = 'RUNNING'
    and lease_expires_at <= pg_catalog.now();

  select value.* into job_value
  from scoring_authority.net_skins_v1_recalculation_jobs value
  where value.tournament_id = '2026'
    and value.configuration_revision = current_value.configuration_revision
    and value.status = 'PENDING' and value.delivery_dead_letter_at is null
    and value.delivery_attempts<5 and value.delivery_available_at<=clock_timestamp()
    and value.attempts < 5
  order by value.requested_at, value.round_number
  for update skip locked
  limit 1;

  if not found then
    response_value := pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_NET_SKINS_V1_RECALCULATION_EMPTY',
      'job', null,
      'calculation_input', null,
      'idempotent', false
    );
    perform production_control.store_cutover_receipt(
      'NET_SKINS_V1_CLAIM', input, response_value
    );
    return response_value;
  end if;

  current_source := production_control.net_skins_v1_round_source_revision(
    '2026', job_value.round_number
  );
  current_source_fingerprint :=
    production_control.net_skins_v1_hash(current_source);
  if current_source_fingerprint <> job_value.source_fingerprint then
    update scoring_authority.net_skins_v1_recalculation_jobs
    set status = 'SUPERSEDED', completed_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    where job_id = job_value.job_id;
    job_value := production_control.enqueue_production_net_skins_v1_round(
      job_value.round_number, 'SOURCE_ADVANCED_BEFORE_CLAIM', worker_value
    );
    select value.* into job_value
    from scoring_authority.net_skins_v1_recalculation_jobs value
    where value.job_id = job_value.job_id
    for update;
  end if;

  claim_token_value := extensions.gen_random_uuid();
  update scoring_authority.net_skins_v1_recalculation_jobs
  set status = 'RUNNING',
      attempts = attempts + 1,
      claimed_by = worker_value,
      claim_token = claim_token_value,
      lease_expires_at = pg_catalog.now()
        + pg_catalog.make_interval(secs => lease_seconds_value),
      started_at = pg_catalog.now(),
      completed_at = null,
      updated_at = pg_catalog.now()
  where job_id = job_value.job_id
  returning * into job_value;

  select coalesce(pg_catalog.max(value.result_revision), 0)
    into expected_result_revision
  from scoring_authority.net_skins_v1_result_revisions value
  where value.tournament_id = '2026'
    and value.round_number = job_value.round_number;

  calculation_input := public.read_net_skins_input_view('2026');
  calculation_input := jsonb_set(calculation_input,'{data,full_net_authority}',production_control.full_net_tournament_v1('2026'));
  calculation_input := jsonb_set(calculation_input,'{data,net_skins_entry_authority}',production_control.net_skins_entries_projection_v1('2026'));
  if coalesce((calculation_input->>'ok')::boolean, false) is not true then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_NET_SKINS_CANONICAL_INPUT_UNAVAILABLE';
  end if;

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_NET_SKINS_V1_RECALCULATION_CLAIMED',
    'job', pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id,
      'round_number', job_value.round_number,
      'configuration_revision', job_value.configuration_revision,
      'configuration_fingerprint', job_value.configuration_fingerprint,
      'source_fingerprint', job_value.source_fingerprint,
      'claim_token', job_value.claim_token,
      'lease_expires_at', job_value.lease_expires_at,
      'expected_result_revision', expected_result_revision
    ),
    'calculation_input', calculation_input->'data',
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'NET_SKINS_V1_CLAIM', input, response_value
  );
  return response_value;
end;
$$;


ALTER FUNCTION production_control.canonical_claim_net_skins_v1_recalculation_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_close_annual_scoring_transition_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_close_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  existing jsonb;
  transition_value production_control.annual_scoring_transitions_v1%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  target production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  close_response jsonb;
  response_value jsonb;
begin
  perform production_control.assert_canonical_annual_transition_context_v2(input,canonical_context);
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'CLOSE', input, canonical_context
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'CLOSE', input, canonical_context
  );
  if existing is not null then return existing; end if;
  select value.* into strict transition_value
  from production_control.annual_scoring_transitions_v1 value
  where value.transition_id = (input->>'transition_id')::uuid
  for update;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = canonical_context->>'resource_id' for update;
  select value.* into strict target
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = transition_value.successor_tournament_id
  for update;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.runtime_generation_id = transition_value.runtime_generation_id
  for update;
  if transition_value.transition_status <> 'PREPARED'
     or transition_value.predecessor_closure_id is not null
     or pointer.tournament_id <> transition_value.predecessor_tournament_id
     or pointer.pointer_revision <> transition_value.expected_pointer_revision
     or input->>'expected_current_tournament_id' is distinct from
       pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or target.lifecycle <> 'READY_FOR_ACTIVATION'
     or target.lifecycle_revision <>
       transition_value.successor_prepared_lifecycle_revision
     or generation.generation_status <> 'PREPARED'
     or input->>'expected_runtime_generation_id' is distinct from
       generation.runtime_generation_id::text
     or input->>'expected_annual_authority_generation_id' is distinct from
       generation.authority_generation_id::text
     or input->>'expected_annual_admission_generation_id' is distinct from
       generation.admission_generation_id::text then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_CLOSE_REVISION_CONFLICT';
  end if;
  close_response :=
    production_control.close_annual_scoring_predecessor_v1(
      input, pointer.tournament_id
    );
  update production_control.annual_scoring_transitions_v1 set
    transition_status = 'CLOSING',
    predecessor_closure_id = (close_response->>'closure_id')::uuid,
    updated_at = pg_catalog.clock_timestamp()
  where transition_id = transition_value.transition_id
    and transition_status = 'PREPARED';
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_CLOSE_REVISION_CONFLICT';
  end if;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_CLOSING',
    'transitionId', transition_value.transition_id,
    'predecessorTournamentId', pointer.tournament_id,
    'successorTournamentId', target.tournament_id,
    'closureId', close_response->>'closure_id',
    'activeOrUnresolvedLeases',
      coalesce((close_response->>'active_or_unresolved_leases')::integer, 0),
    'pointerChanged', false,
    'predecessorAdmissionStopped', true,
    'predecessorClosed', false,
    'successorActivated', false,
    'idempotent', false
  );
  perform production_control.store_canonical_annual_scoring_receipt_v2(
    'CLOSE', input, response_value, canonical_context
  );
  return response_value;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_CLOSE_REVISION_CONFLICT';
end;
$$;


ALTER FUNCTION production_control.canonical_close_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_commit_draft_revision_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_commit_draft_revision_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}','')));
  actor_auth uuid;
  request_id uuid;
  draft_id_value uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash','')));
  expected_value bigint;
  database_hash text;
  prior_receipt jsonb;
  draft production_control.draft_authoring_drafts_v1%rowtype;
  current_revision scoring_authority.draft_revisions%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  resource production_control.canonical_resource_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  annual_resource production_control.future_tournament_resources_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  binding production_control.future_annual_projection_bindings_v1%rowtype;
  final_picks jsonb;
  validation jsonb;
  next_revision bigint;
  next_binding_revision bigint;
  revision_id_value uuid;
  source_hash text;
  binding_payload_hash text;
  selected_count integer;
  effective_at_value timestamptz;
  projection_row jsonb;
  projection_value jsonb;
  response_value jsonb;
  operation_value text;
  mutability jsonb;
  pick_event record;
begin
  target := production_control.assert_draft_authoring_resource_v2(input, resource_context);
  if input->>'operation' is distinct from
       'COMMIT_PRODUCTION_DRAFT_REVISION_V1'
     or coalesce(input->>'operation_request_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'draft_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_revision','') !~ '^[0-9]+$'
     or input->>'confirmation' is distinct from 'SAVE DRAFT REVISION' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_COMMIT_INPUT_INVALID');
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  draft_id_value := (input->>'draft_id')::uuid;
  expected_value := (input->>'expected_revision')::bigint;
  database_hash := production_control.draft_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation','COMMIT','tournamentId',target,
      'actorPlayerId',actor_player,'actorAuthUserId',actor_auth,
      'draftId',draft_id_value,'expectedRevision',expected_value,
      'confirmation',input->>'confirmation'));
  prior_receipt := production_control.draft_operation_receipt_v1(
    target,'COMMIT',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-draft-authoring:'||target,0));
  prior_receipt := production_control.draft_operation_receipt_v1(
    target,'COMMIT',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  mutability := production_control.draft_mutability_v1(target);
  if not coalesce((mutability->>'editable')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_CORRECTION_REQUIRED','mutability',mutability);
  end if;
  select value.* into strict draft
  from production_control.draft_authoring_drafts_v1 value
  where value.draft_id=draft_id_value and value.tournament_id=target
  for update;
  select revision.* into current_revision
  from scoring_authority.draft_current_revisions current_value
  join scoring_authority.draft_revisions revision
    on revision.revision_id=current_value.revision_id
  where current_value.tournament_id=target for update of current_value;
  if coalesce(current_revision.revision_number,0)<>expected_value
     or draft.expected_revision<>expected_value then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_PREDECESSOR_STALE',
      'currentRevision',coalesce(current_revision.revision_number,0));
  end if;
  if draft.state<>'VALIDATED' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_STAGED_REVISION_NOT_VALIDATED');
  end if;
  effective_at_value := pg_catalog.clock_timestamp();
  final_picks := production_control.draft_commit_pick_provenance_v1(
    draft.picks,actor_player,effective_at_value);
  validation := production_control.validate_draft_authoring_v1(
    target,draft.configuration,final_picks);
  if not coalesce((validation->>'pass')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_VALIDATION_FAILED',
      'issues',validation->'issues');
  end if;
  if current_revision.revision_id is not null
     and current_revision.payload_fingerprint=
       validation->>'payloadFingerprint' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_NO_CHANGES');
  end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key=(resource_context->>'resource_id');
  select value.* into strict resource
  from production_control.canonical_resource_v1 value
  where value.resource_id=(resource_context->>'resource_id');
  select coalesce(pg_catalog.max(value.revision_number),0)+1
    into next_revision
  from scoring_authority.draft_revisions value
  where value.tournament_id=target;
  source_hash := production_control.draft_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'authoringAuthority','SUPABASE_DIRECTOR',
      'authoringContract','production-draft-authoring-v1',
      'tournamentId',target,'revision',next_revision,
      'configuration',validation->'configuration',
      'picks',validation->'picks'));
  selected_count := (validation#>>'{diagnostics,selectedPicks}')::integer;
  operation_value := case when draft.authoring_kind='COPIED_PREVIOUS'
    then 'DIRECTOR_CLONE' else 'DIRECTOR_REVISION' end;
  perform pg_catalog.set_config(
    'scoring_authority.draft_projection_import','on',true);
  insert into scoring_authority.draft_revisions (
    project_ref,source_workbook_id,source_tabs,tournament_id,tournament_year,
    revision_number,previous_revision_id,source_fingerprint,
    configuration_fingerprint,picks_fingerprint,payload_fingerprint,
    contract_version,validation_status,validation_diagnostics,
    source_settings,source_picks,configuration,presentation_seed,
    operation,correction_reason,synchronized_by,synchronized_at
  ) values (
    resource.project_ref,resource.provenance_id,
    '["Draft Settings","Draft Picks"]'::jsonb,target,target::integer,
    next_revision,current_revision.revision_id,source_hash,
    validation->>'configurationFingerprint',validation->>'picksFingerprint',
    validation->>'payloadFingerprint','draft-projection-v1','VALID',
    (validation->'diagnostics')||pg_catalog.jsonb_build_object(
      'authoringAuthority','SUPABASE_DIRECTOR',
      'authoringContract','production-draft-authoring-v1'),
    validation->'configuration',validation->'picks',
    validation->'configuration',validation->'presentationSeed',
    operation_value,null,actor_player,effective_at_value
  ) returning revision_id into revision_id_value;
  insert into scoring_authority.draft_configuration_facts (
    revision_id,tournament_id,tournament_year,draft_name,draft_date,draft_time,
    time_zone,location,status_mode,draft_format,total_picks,team_1_id,team_2_id,
    team_1_captain_player_id,team_2_captain_player_id,first_pick_team_id,notes
  ) values (
    revision_id_value,target,target::integer,
    validation#>>'{configuration,name}',
    nullif(validation#>>'{configuration,date}',''),
    nullif(validation#>>'{configuration,time}',''),
    nullif(validation#>>'{configuration,time_zone}',''),
    nullif(validation#>>'{configuration,location}',''),
    nullif(validation#>>'{configuration,status_mode}',''),
    nullif(validation#>>'{configuration,format}',''),
    (validation#>>'{configuration,total_picks}')::integer,
    validation#>>'{configuration,team_1_id}',
    validation#>>'{configuration,team_2_id}',
    nullif(validation#>>'{configuration,team_1_captain_player_id}',''),
    nullif(validation#>>'{configuration,team_2_captain_player_id}',''),
    validation#>>'{configuration,first_pick_team_id}',
    nullif(validation#>>'{configuration,notes}',''));
  insert into scoring_authority.draft_pick_facts (
    revision_id,tournament_id,tournament_year,pick_number,round_number,
    pick_within_round,source_team_id,team_id,player_id,player_name_snapshot,
    selected_at_source,selected_by_source,pick_status,notes,
    presentation_snapshot
  ) select revision_id_value,target,target::integer,
    (item.value->>'pick_number')::integer,
    (item.value->>'round_number')::integer,
    (item.value->>'pick_within_round')::integer,
    nullif(item.value->>'source_team_id',''),nullif(item.value->>'team_id',''),
    nullif(item.value->>'player_id',''),nullif(item.value->>'player_name',''),
    nullif(item.value->>'selected_at',''),nullif(item.value->>'selected_by',''),
    item.value->>'status',nullif(item.value->>'notes',''),
    coalesce(item.value->'presentation','{}'::jsonb)
  from pg_catalog.jsonb_array_elements(validation->'picks') item;
  insert into scoring_authority.draft_current_revisions (
    tournament_id,tournament_year,revision_id,advanced_by,advanced_at
  ) values (
    target,target::integer,revision_id_value,actor_player,effective_at_value
  ) on conflict (tournament_id) do update set
    tournament_year=excluded.tournament_year,
    revision_id=excluded.revision_id,advanced_by=excluded.advanced_by,
    advanced_at=excluded.advanced_at;
  insert into production_control.draft_revision_provenance_v1 (
    revision_id,tournament_id,authoring_authority,authoring_contract,draft_id,
    actor_player_id,actor_auth_user_id,authoring_kind,selected_pick_count,
    created_at
  ) values (
    revision_id_value,target,'SUPABASE_DIRECTOR',
    'production-draft-authoring-v1',draft_id_value,actor_player,actor_auth,
    draft.authoring_kind,selected_count,effective_at_value);

  if target<>pointer.tournament_id then
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id=target for update;
    select value.* into strict annual_resource
    from production_control.future_tournament_resources_v1 value
    where value.tournament_id=target
      and value.source_workbook_id is not null
      and value.resource_status='CURRENT_RESOURCE_BOUND' for share;
    select value.* into promotion
    from production_control.future_runtime_promotions_v2 value
    where value.tournament_id=target;
    select value.* into binding
    from production_control.future_annual_projection_bindings_v1 value
    where value.tournament_id=target and value.domain='DRAFT' for update;
    update production_control.future_tournament_catalog_v1 value set
      lifecycle=case when value.lifecycle='READY_FOR_ACTIVATION'
        then 'CONFIGURING' else value.lifecycle end,
      lifecycle_revision=case when value.lifecycle='READY_FOR_ACTIVATION'
        then value.lifecycle_revision+1 else value.lifecycle_revision end,
      setup_revision=case when promotion.tournament_id is null
        then value.setup_revision+1 else value.setup_revision end,
      readiness_fingerprint=null,readiness_setup_revision=null,
      updated_by_player_id=actor_player,updated_at=effective_at_value
    where value.tournament_id=target;
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id=target;
    next_binding_revision:=coalesce(binding.binding_revision,0)+1;
    projection_row:=production_control.draft_projection_row_v1(
      revision_id_value);
    projection_value:=pg_catalog.jsonb_build_object(
      'drafts',pg_catalog.jsonb_build_array(projection_row),
      'synchronization_fingerprint',source_hash,
      'authoring_authority','SUPABASE_DIRECTOR');
    binding_payload_hash:=production_control.draft_authoring_hash_v1(
      projection_value);
    insert into production_control.future_annual_projection_bindings_v1 (
      tournament_id,domain,source_workbook_id,source_revision,
      binding_revision,source_fingerprint,payload_fingerprint,projection,
      certification_status,certified_by_player_id,certified_at,
      authoring_authority
    ) values (
      target,'DRAFT',annual_resource.source_workbook_id,next_revision,
      next_binding_revision,source_hash,binding_payload_hash,projection_value,
      'CERTIFIED',actor_player,effective_at_value,'SUPABASE_DIRECTOR'
    ) on conflict (tournament_id,domain) do update set
      source_workbook_id=excluded.source_workbook_id,
      source_revision=excluded.source_revision,
      binding_revision=excluded.binding_revision,
      source_fingerprint=excluded.source_fingerprint,
      payload_fingerprint=excluded.payload_fingerprint,
      projection=excluded.projection,
      certification_status=excluded.certification_status,
      certified_by_player_id=excluded.certified_by_player_id,
      certified_at=excluded.certified_at,
      authoring_authority=excluded.authoring_authority,
      updated_at=effective_at_value;
  end if;
  update production_control.draft_authoring_drafts_v1 set
    state='COMMITTED',configuration=validation->'configuration',
    picks=validation->'picks',presentation_seed=validation->'presentationSeed',
    configuration_fingerprint=validation->>'configurationFingerprint',
    picks_fingerprint=validation->>'picksFingerprint',
    payload_fingerprint=validation->>'payloadFingerprint',
    validation_diagnostics=validation->'diagnostics'||
      pg_catalog.jsonb_build_object('committed',true),
    committed_revision_id=revision_id_value,committed_at=effective_at_value
  where draft_id=draft_id_value;
  response_value:=pg_catalog.jsonb_build_object(
    'ok',true,'code','DRAFT_REVISION_COMMITTED','idempotent',false,
    'tournamentId',target,'revisionId',revision_id_value,
    'revision',next_revision,'previousRevisionId',current_revision.revision_id,
    'authoringAuthority','SUPABASE_DIRECTOR',
    'selectedPickCount',selected_count,'effectiveAt',effective_at_value,
    'current',production_control.draft_projection_row_v1(revision_id_value));
  insert into production_control.draft_authoring_audit_events_v1 (
    tournament_id,draft_id,revision_id,action,actor_player_id,
    actor_auth_user_id,operation_request_id,summary
  ) values (
    target,draft_id_value,revision_id_value,'REVISION_COMMITTED',
    actor_player,actor_auth,request_id,pg_catalog.jsonb_build_object(
      'revision',next_revision,'predecessorRevision',expected_value,
      'selectedPickCount',selected_count,
      'summary','Draft Revision '||next_revision||' saved'));
  for pick_event in
    select current_pick.pick_number,current_pick.team_id,
      current_pick.player_id,current_pick.pick_status,
      previous_pick.player_id as previous_player_id,
      previous_pick.team_id as previous_team_id
    from scoring_authority.draft_pick_facts current_pick
    left join scoring_authority.draft_pick_facts previous_pick
      on previous_pick.revision_id=current_revision.revision_id
     and previous_pick.pick_number=current_pick.pick_number
     and previous_pick.pick_status='SELECTED'
    where current_pick.revision_id=revision_id_value and (
      (current_pick.pick_status='SELECTED' and (
        previous_pick.pick_number is null
        or previous_pick.player_id is distinct from current_pick.player_id
        or previous_pick.team_id is distinct from current_pick.team_id
      )) or (
        current_pick.pick_status<>'SELECTED'
        and previous_pick.pick_number is not null
      )
    )
    order by current_pick.pick_number
  loop
    insert into production_control.draft_authoring_audit_events_v1 (
      tournament_id,draft_id,revision_id,action,actor_player_id,
      actor_auth_user_id,operation_request_id,summary
    ) values (
      target,draft_id_value,revision_id_value,
      case when pick_event.previous_player_id is null
             and pick_event.pick_status='SELECTED'
        then 'PICK_RECORDED' else 'PICK_CORRECTED' end,
      actor_player,actor_auth,request_id,pg_catalog.jsonb_strip_nulls(
        pg_catalog.jsonb_build_object(
        'pickNumber',pick_event.pick_number,
        'playerId',case when pick_event.pick_status='SELECTED'
          then pick_event.player_id else null end,
        'teamId',pick_event.team_id,
        'summary',case
          when pick_event.pick_status<>'SELECTED'
            then 'Pick '||pick_event.pick_number||' cleared'
          when pick_event.previous_player_id is null
          then 'Pick '||pick_event.pick_number||' recorded — Player '||
            pick_event.player_id||' to Team '||pick_event.team_id
          else 'Pick '||pick_event.pick_number||' corrected — Player '||
            pick_event.player_id||' to Team '||pick_event.team_id end)));
  end loop;
  if (
       pg_catalog.upper(validation#>>'{configuration,status_mode}')='COMPLETE'
       or selected_count >= (validation#>>'{configuration,total_picks}')::integer
     ) and not (
       pg_catalog.upper(coalesce(
         current_revision.configuration->>'status_mode',''))='COMPLETE'
       or (
         coalesce((current_revision.configuration->>'total_picks')::integer,0)>0
         and (select pg_catalog.count(*)::integer
           from scoring_authority.draft_pick_facts previous_pick
           where previous_pick.revision_id=current_revision.revision_id
             and previous_pick.pick_status='SELECTED') >=
           coalesce((current_revision.configuration->>'total_picks')::integer,0)
       )
     ) then
    insert into production_control.draft_authoring_audit_events_v1 (
      tournament_id,draft_id,revision_id,action,actor_player_id,
      actor_auth_user_id,operation_request_id,summary
    ) values (
      target,draft_id_value,revision_id_value,'DRAFT_COMPLETED',
      actor_player,actor_auth,request_id,pg_catalog.jsonb_build_object(
        'revision',next_revision,
        'summary','Draft completed at Revision '||next_revision));
  end if;
  insert into production_control.operation_audit_events (
    event_type,domain,tournament_id,actor,request_fingerprint,result,details
  ) values (
    'PRODUCTION_DRAFT_REVISION_COMMITTED','DRAFT',target,actor_player,null,
    'SUCCEEDED',pg_catalog.jsonb_build_object(
      'revision',next_revision,'selected_pick_count',selected_count,
      'authoring_authority','SUPABASE_DIRECTOR'));
  insert into production_control.draft_operation_receipts_v1 (
    tournament_id,operation,operation_request_id,
    declared_request_payload_hash,request_payload_hash,
    actor_player_id,actor_auth_user_id,response
  ) values (
    target,'COMMIT',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value);
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','DRAFT_STAGED_REVISION_NOT_FOUND');
when unique_violation then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','DRAFT_OPERATION_CONFLICT');
end;

$_$;


ALTER FUNCTION production_control.canonical_commit_draft_revision_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_commit_prediction_settings_revision_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_commit_prediction_settings_revision_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  request_id uuid;
  draft_id_value uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash', ''
  )));
  expected_revision bigint;
  database_hash text;
  prior_receipt jsonb;
  draft production_control.prediction_settings_drafts_v1%rowtype;
  current_config scoring_authority.odds_input_configurations%rowtype;
  seed_config scoring_authority.odds_input_configurations%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  binding production_control.future_annual_projection_bindings_v1%rowtype;
  validation jsonb;
  pairing_fingerprint_value text;
  next_revision bigint;
  next_binding_revision bigint;
  next_bundle text;
  source_fingerprint_value text;
  source_workbook_value text;
  projection_value jsonb;
  payload_fingerprint_value text;
  configuration_id_value uuid;
  effective_at_value timestamptz;
  response_value jsonb;
begin
  target := production_control.assert_prediction_settings_authoring_resource_v2(input, resource_context);
  if input->>'operation' is distinct from
       'COMMIT_PRODUCTION_PREDICTION_SETTINGS_REVISION_V1'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'draft_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_configuration_revision', '')
       !~ '^[0-9]+$'
     or input->>'confirmation' is distinct from
       'SAVE PREDICTION SETTINGS REVISION' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_COMMIT_INPUT_INVALID'
    );
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  draft_id_value := (input->>'draft_id')::uuid;
  expected_revision := (input->>'expected_configuration_revision')::bigint;
  database_hash := production_control.prediction_settings_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation', 'COMMIT', 'tournamentId', target,
      'actorPlayerId', actor_player, 'actorAuthUserId', actor_auth,
      'draftId', draft_id_value,
      'expectedConfigurationRevision', expected_revision,
      'confirmation', input->>'confirmation'
    )
  );
  prior_receipt := production_control.prediction_settings_receipt_v1(
    target, 'COMMIT', request_id, declared_hash, database_hash
  );
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-prediction-settings:' || target, 0
  ));
  prior_receipt := production_control.prediction_settings_receipt_v1(
    target, 'COMMIT', request_id, declared_hash, database_hash
  );
  if prior_receipt is not null then return prior_receipt; end if;
  select value.* into strict draft
  from production_control.prediction_settings_drafts_v1 value
  where value.draft_id = draft_id_value
    and value.tournament_id = target for update;
  select value.* into current_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target and value.is_current for update;
  if coalesce(current_config.configuration_revision, 0) <> expected_revision
     or draft.expected_configuration_revision <> expected_revision then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_PREDECESSOR_STALE'
    );
  end if;
  if draft.state <> 'VALIDATED' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_DRAFT_NOT_VALIDATED'
    );
  end if;
  validation := production_control.validate_prediction_settings_v1(
    draft.canonical_settings, current_config.canonical_settings
  );
  if not coalesce((validation->>'pass')::boolean, false)
     or coalesce((validation->>'changedSettingCount')::integer, 0) = 0 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_VALIDATION_FAILED',
      'issues', validation->'issues'
    );
  end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = (resource_context->>'resource_id');
  if current_config.id is not null then
    seed_config := current_config;
  else
    select value.* into strict seed_config
    from scoring_authority.odds_input_configurations value
    where value.tournament_id = pointer.tournament_id
      and value.is_current and value.validation_status = 'VALID';
  end if;
  if target = pointer.tournament_id then
    pairing_fingerprint_value := seed_config.pairing_fingerprint;
    source_workbook_value := seed_config.source_workbook_id;
  else
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target for update;
    select value.* into promotion
    from production_control.future_runtime_promotions_v2 value
    where value.tournament_id = target;
    select value.* into strict resource
    from production_control.future_tournament_resources_v1 value
    where value.tournament_id = target
      and value.source_workbook_id is not null
      and value.resource_status = 'CURRENT_RESOURCE_BOUND'
    for share;
    select value.* into binding
    from production_control.future_annual_projection_bindings_v1 value
    where value.tournament_id = target
      and value.domain = 'PREDICTION_SETTINGS'
    for update;

    -- Match the installed annual-projection invalidation semantics.  Before
    -- promotion, Prediction Settings are part of the setup manifest and
    -- advance setup revision.  After promotion, the promoted structure stays
    -- immutable, but readiness is cleared and a Ready candidate is returned
    -- to Configuring for explicit review.
    update production_control.future_tournament_catalog_v1 value set
      lifecycle = case when value.lifecycle = 'READY_FOR_ACTIVATION'
        then 'CONFIGURING' else value.lifecycle end,
      lifecycle_revision = case
        when value.lifecycle = 'READY_FOR_ACTIVATION'
          then value.lifecycle_revision + 1
        else value.lifecycle_revision end,
      setup_revision = case when promotion.tournament_id is null
        then value.setup_revision + 1 else value.setup_revision end,
      readiness_fingerprint = null,
      readiness_setup_revision = null,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where value.tournament_id = target;
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target;

    source_workbook_value := resource.source_workbook_id;
    pairing_fingerprint_value := production_control
      .annual_odds_pairing_fingerprint_v1(target);
  end if;
  select coalesce(pg_catalog.max(value.configuration_revision), 0) + 1
    into next_revision
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target;
  source_fingerprint_value := production_control.prediction_settings_hash_v1(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-prediction-settings-authoring-v1',
      'authoringAuthority', 'SUPABASE_DIRECTOR',
      'tournamentId', target,
      'configurationRevision', next_revision,
      'canonicalSettings', validation->'canonicalSettings'
    )
  );
  next_bundle := production_control.prediction_settings_hash_v1(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-odds-input-bundle-v1',
      'tournamentId', target,
      'configurationRevision', next_revision,
      'settingsFingerprint', validation->>'settingsFingerprint',
      'effectiveSettingsFingerprint',
        validation->>'effectiveSettingsFingerprint',
      'ratingsFingerprint', seed_config.ratings_fingerprint,
      'pairingFingerprint', pairing_fingerprint_value,
      'previousConfigurationId', current_config.id
    )
  );
  effective_at_value := pg_catalog.clock_timestamp();
  update scoring_authority.odds_input_configurations set
    is_current = false,
    superseded_at = effective_at_value
  where tournament_id = target and is_current;
  insert into scoring_authority.odds_input_configurations (
    tournament_id, configuration_revision, source_workbook_id,
    settings, historical_ratings, settings_fingerprint,
    ratings_fingerprint, pairing_fingerprint, bundle_fingerprint,
    is_current, imported_by, source_tab, source_fingerprint,
    canonical_settings, effective_settings,
    effective_settings_fingerprint, settings_contract_version,
    validation_status, validation_diagnostics, synchronized_at,
    previous_configuration_id
  ) values (
    target, next_revision, source_workbook_value,
    validation->'settingsRows', seed_config.historical_ratings,
    validation->>'settingsFingerprint', seed_config.ratings_fingerprint,
    pairing_fingerprint_value, next_bundle, true,
    'Production Director ' || actor_player, 'Prediction Settings',
    source_fingerprint_value, validation->'canonicalSettings',
    validation->'effectiveSettings',
    validation->>'effectiveSettingsFingerprint',
    'prediction-settings-v1', 'VALID',
    pg_catalog.jsonb_build_object(
      'authoringAuthority', 'SUPABASE_DIRECTOR',
      'authoringContract', 'production-prediction-settings-authoring-v1',
      'completeSchema', true,
      'legacyRecalibrationProfile',
        (validation->>'legacyRecalibrationProfile')::boolean,
      'changedSettingCount',
        (validation->>'changedSettingCount')::integer,
      'annualSetupRevision', case when target = pointer.tournament_id
        then null else catalog.setup_revision end,
      'annualProjectionBindingRevision', case
        when target = pointer.tournament_id then null
        else coalesce(binding.binding_revision, 0) + 1 end,
      'automaticCalculationRequested', false,
      'automaticPublicationRequested', false
    ) || case when resource_context->>'resource_class'='CERTIFICATION'
      and target<>pointer.tournament_id then jsonb_build_object(
        'certificationStructuralContract','certification-odds-pairing-structure-v1',
        'certificationStructuralFingerprint',production_control.certification_odds_pairing_structure_fingerprint_v1(target),
        'certificationStructuralSetupRevision',catalog.setup_revision)
      else '{}'::jsonb end,
    effective_at_value, current_config.id
  ) returning id into configuration_id_value;

  if target <> pointer.tournament_id then
    next_binding_revision := coalesce(binding.binding_revision, 0) + 1;
    projection_value := pg_catalog.jsonb_build_object(
      'environment', 'PRODUCTION',
      'tournament_id', target,
      'tournament_year', catalog.tournament_year,
      'source_workbook_id', source_workbook_value,
      'source_tab', 'Prediction Settings',
      'source_revision', next_revision,
      'settings', validation->'settingsRows',
      'source_fingerprint', source_fingerprint_value,
      'settings_fingerprint', validation->>'settingsFingerprint',
      'canonical_settings', validation->'canonicalSettings',
      'effective_settings', validation->'effectiveSettings',
      'effective_settings_fingerprint',
        validation->>'effectiveSettingsFingerprint',
      'settings_contract_version', 'prediction-settings-v1',
      'validation_status', 'VALID',
      'validation_diagnostics', pg_catalog.jsonb_build_object(
        'authoringAuthority', 'SUPABASE_DIRECTOR',
        'authoringContract',
          'production-prediction-settings-authoring-v1',
        'annualSetupRevision', catalog.setup_revision,
        'annualProjectionBindingRevision', next_binding_revision,
        'completeSchema', true
      ),
      'authoring_authority', 'SUPABASE_DIRECTOR'
    );
    payload_fingerprint_value := production_control
      .prediction_settings_hash_v1(projection_value);
    insert into production_control.future_annual_projection_bindings_v1 (
      tournament_id, domain, source_workbook_id, source_revision,
      binding_revision, source_fingerprint, payload_fingerprint,
      projection, certification_status, certified_by_player_id,
      certified_at, authoring_authority
    ) values (
      target, 'PREDICTION_SETTINGS', source_workbook_value, next_revision,
      next_binding_revision, source_fingerprint_value,
      payload_fingerprint_value, projection_value, 'CERTIFIED',
      actor_player, effective_at_value, 'SUPABASE_DIRECTOR'
    ) on conflict (tournament_id, domain) do update set
      source_workbook_id = excluded.source_workbook_id,
      source_revision = excluded.source_revision,
      binding_revision = excluded.binding_revision,
      source_fingerprint = excluded.source_fingerprint,
      payload_fingerprint = excluded.payload_fingerprint,
      projection = excluded.projection,
      certification_status = excluded.certification_status,
      certified_by_player_id = excluded.certified_by_player_id,
      certified_at = excluded.certified_at,
      authoring_authority = excluded.authoring_authority,
      updated_at = effective_at_value;
  end if;
  insert into production_control.prediction_settings_revision_provenance_v1 (
    configuration_id, tournament_id, authoring_authority,
    authoring_contract, draft_id, actor_player_id, actor_auth_user_id,
    changed_setting_count, created_at
  ) values (
    configuration_id_value, target, 'SUPABASE_DIRECTOR',
    'production-prediction-settings-authoring-v1', draft_id_value,
    actor_player, actor_auth,
    (validation->>'changedSettingCount')::integer, effective_at_value
  );
  update production_control.prediction_settings_drafts_v1 set
    state = 'COMMITTED',
    committed_configuration_id = configuration_id_value,
    committed_at = effective_at_value
  where draft_id = draft_id_value;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PREDICTION_SETTINGS_REVISION_COMMITTED',
    'idempotent', false,
    'tournamentId', target,
    'configurationId', configuration_id_value,
    'configurationRevision', next_revision,
    'effectiveAt', effective_at_value,
    'directorPlayerId', actor_player,
    'changedKeys', validation->'changedKeys',
    'changedSettingCount',
      (validation->>'changedSettingCount')::integer,
    'recalculationRequired', true,
    'automaticCalculationRequested', false,
    'automaticPublicationRequested', false,
    'publishedSnapshotUnchanged', true,
    'authoringAuthority', 'SUPABASE_DIRECTOR'
  );
  insert into production_control.prediction_settings_audit_events_v1 (
    tournament_id, draft_id, configuration_id, action,
    actor_player_id, actor_auth_user_id, operation_request_id,
    request_payload_hash, summary
  ) values (
    target, draft_id_value, configuration_id_value,
    'REVISION_COMMITTED', actor_player, actor_auth, request_id,
    database_hash, pg_catalog.jsonb_build_object(
      'configurationRevision', next_revision,
      'predecessorConfigurationRevision', expected_revision,
      'changedSettingCount',
        (validation->>'changedSettingCount')::integer,
      'recalculationRequired', true,
      'automaticCalculationRequested', false,
      'automaticPublicationRequested', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_PREDICTION_SETTINGS_REVISION_COMMITTED',
    'PREDICTION_SETTINGS', target, actor_player, database_hash,
    'SUCCEEDED', pg_catalog.jsonb_build_object(
      'configuration_revision', next_revision,
      'changed_setting_count',
        (validation->>'changedSettingCount')::integer,
      'authoring_authority', 'SUPABASE_DIRECTOR',
      'recalculation_required', true,
      'automatic_calculation_requested', false,
      'automatic_publication_requested', false
    )
  );
  insert into production_control.prediction_settings_operation_receipts_v1 (
    tournament_id, operation, operation_request_id,
    declared_request_payload_hash, request_payload_hash,
    actor_player_id, actor_auth_user_id, response
  ) values (
    target, 'COMMIT', request_id, declared_hash, database_hash,
    actor_player, actor_auth, response_value
  );
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok', false, 'code', 'PREDICTION_SETTINGS_ODDS_CONTEXT_REQUIRED'
  );
when unique_violation then
  return pg_catalog.jsonb_build_object(
    'ok', false, 'code', 'PREDICTION_SETTINGS_OPERATION_CONFLICT'
  );
end;

$_$;


ALTER FUNCTION production_control.canonical_commit_prediction_settings_revision_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_complete_calcutta_v1_recalculation_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_complete_calcutta_v1_recalculation_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.calcutta_v1_current%rowtype;
  job_value scoring_authority.calcutta_v1_recalculation_jobs%rowtype;
  result_value scoring_authority.calcutta_v1_result_revisions%rowtype;
  existing_response jsonb;
  response_value jsonb;
  current_source jsonb;
  current_source_fingerprint text;
  current_result_revision bigint;
  job_id_value uuid := nullif(input->>'job_id', '')::uuid;
  claim_token_value uuid := nullif(input->>'claim_token', '')::uuid;
  worker_value text := pg_catalog.btrim(coalesce(input->>'worker_id', ''));
  requested_result_state text := pg_catalog.upper(coalesce(
    input->>'result_state', ''
  ));
  result_state_value text;
  result_payload_value jsonb := input->'result_payload';
  payload_hash_value text;
begin
  perform production_control.assert_canonical_financial_worker_context_v1(input,canonical_context,'CALCUTTA');
  existing_response := production_control.lookup_cutover_receipt(
    'CALCUTTA_V1_COMPLETE', input
  );
  if existing_response is not null then return existing_response; end if;
  if job_id_value is null or claim_token_value is null or worker_value = ''
     or input->>'engine_version' is distinct from 'calcutta-full-net-v3'
     or requested_result_state not in ('PROVISIONAL', 'OFFICIAL')
     or pg_catalog.jsonb_typeof(coalesce(
       result_payload_value, 'null'::jsonb
     )) <> 'object' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_COMPLETION_INPUT_INVALID';
  end if;
  result_state_value := requested_result_state;

  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026'
  for update;
  if current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1)
     or current_value.configuration_fingerprint is distinct from
       nullif(input->>'expected_configuration_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REVISION_CONFLICT';
  end if;
  if current_value.auction_revision <>
       coalesce((input->>'expected_auction_revision')::bigint, -1)
     or current_value.auction_fingerprint is distinct from
       nullif(input->>'expected_auction_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_AUCTION_REVISION_CONFLICT';
  end if;

  select value.* into job_value
  from scoring_authority.calcutta_v1_recalculation_jobs value
  where value.job_id = job_id_value
  for update;
  if not found or job_value.status <> 'RUNNING'
     or job_value.configuration_revision <>
       current_value.configuration_revision
     or job_value.configuration_fingerprint <>
       current_value.configuration_fingerprint
     or job_value.auction_revision <> current_value.auction_revision
     or job_value.auction_fingerprint <> current_value.auction_fingerprint
     or job_value.activation_revision <>
       (input->>'expected_activation_revision')::bigint
     or job_value.claim_token <> claim_token_value
     or job_value.claimed_by <> worker_value
     or job_value.lease_expires_at <= pg_catalog.now()
     or input->>'expected_source_fingerprint' is distinct from
       job_value.source_fingerprint then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CALCUTTA_JOB_LEASE_REQUIRED';
  end if;

  current_source := production_control.calcutta_v1_source_revision('2026');
  current_source_fingerprint := production_control.calcutta_v1_hash(
    current_source
  );
  if current_source_fingerprint <> job_value.source_fingerprint then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_SOURCE_REVISION_CONFLICT';
  end if;

  payload_hash_value := production_control.calcutta_v1_hash(
    result_payload_value
  );
  perform production_control.validate_production_calcutta_v1_result(
    result_state_value, result_payload_value
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'production-calcutta-v1:result:2026', 202608290056
    )
  );
  select coalesce(pg_catalog.max(value.result_revision), 0)
    into current_result_revision
  from scoring_authority.calcutta_v1_result_revisions value
  where value.tournament_id = '2026';
  if current_result_revision <>
       coalesce((input->>'expected_result_revision')::bigint, -1) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_RESULT_REVISION_CONFLICT';
  end if;

  update scoring_authority.calcutta_v1_result_revisions
  set is_current = false, superseded_at = pg_catalog.now()
  where tournament_id = '2026' and is_current;
  insert into scoring_authority.calcutta_v1_result_revisions (
    tournament_id, configuration_revision_id, configuration_revision,
    configuration_fingerprint, auction_revision_id, auction_revision,
    auction_fingerprint, result_revision, job_id, engine_version,
    source_fingerprint, result_state, engine_result_payload, payload_hash,
    is_current, calculated_by, calculated_at
  ) values (
    '2026', job_value.configuration_revision_id,
    job_value.configuration_revision, job_value.configuration_fingerprint,
    job_value.auction_revision_id, job_value.auction_revision,
    job_value.auction_fingerprint, current_result_revision + 1,
    job_value.job_id, 'calcutta-full-net-v3', job_value.source_fingerprint,
    result_state_value, result_payload_value, payload_hash_value,
    true, worker_value, pg_catalog.now()
  ) returning * into result_value;

  update scoring_authority.calcutta_v1_recalculation_jobs
  set status = 'SUCCEEDED', claimed_by = null, claim_token = null,
      lease_expires_at = null, completed_at = pg_catalog.now(),
      last_error_code = null, last_error_safe = null,
      updated_at = pg_catalog.now()
  where job_id = job_value.job_id;
  update scoring_authority.calcutta_v1_current
  set state = case
        when result_state_value = 'OFFICIAL' then 'OFFICIAL'
        when pg_catalog.jsonb_array_length(
          result_payload_value->'completedRounds'
        ) > 0 then 'IN_PROGRESS'
        else 'AUCTION_COMPLETE' end,
      result_revision = result_value.result_revision,
      updated_at = pg_catalog.now()
  where tournament_id = '2026';

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'PRODUCTION_CALCUTTA_V1_RECALCULATION_COMPLETED',
    worker_value, pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id,
      'configuration_revision', job_value.configuration_revision,
      'configuration_fingerprint', job_value.configuration_fingerprint,
      'auction_revision', job_value.auction_revision,
      'auction_fingerprint', job_value.auction_fingerprint,
      'result_revision', result_value.result_revision,
      'result_state', requested_result_state,
      'source_fingerprint', job_value.source_fingerprint,
      'result_fingerprint', payload_hash_value,
      'publication_changed', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_CALCUTTA_V1_RECALCULATION_COMPLETED', 'CALCUTTA',
    '2026', worker_value, pg_catalog.lower(input->>'request_fingerprint'),
    'SUCCEEDED', pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id,
      'configuration_revision', job_value.configuration_revision,
      'auction_revision', job_value.auction_revision,
      'result_revision', result_value.result_revision,
      'result_state', requested_result_state,
      'publication_changed', false
    )
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_CALCUTTA_V1_RECALCULATION_COMPLETED',
    'job_id', job_value.job_id,
    'configuration_revision', job_value.configuration_revision,
    'configuration_fingerprint', job_value.configuration_fingerprint,
    'auction_revision', job_value.auction_revision,
    'auction_fingerprint', job_value.auction_fingerprint,
    'result_revision', result_value.result_revision,
    'result_state', requested_result_state,
    'result_fingerprint', payload_hash_value,
    'publication_state', current_value.publication_state,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'CALCUTTA_V1_COMPLETE', input, response_value
  );
  return response_value;
end;
$$;


ALTER FUNCTION production_control.canonical_complete_calcutta_v1_recalculation_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_complete_net_skins_v1_recalculation_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_complete_net_skins_v1_recalculation_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  job_value scoring_authority.net_skins_v1_recalculation_jobs%rowtype;
  existing_response jsonb;
  response_value jsonb;
  result_value scoring_authority.net_skins_v1_result_revisions%rowtype;
  job_id_value uuid := nullif(input->>'job_id', '')::uuid;
  claim_token_value uuid := nullif(input->>'claim_token', '')::uuid;
  worker_value text := pg_catalog.btrim(coalesce(input->>'worker_id', ''));
  result_state_value text := pg_catalog.upper(coalesce(
    input->>'result_state', ''
  ));
  result_payload_value jsonb := input->'result_payload';
  normalized_result_value jsonb;
  payload_hash_value text;
  current_source_value jsonb;
  current_source_fingerprint text;
  current_result_revision bigint;
  expected_result_revision bigint := coalesce(
    (input->>'expected_result_revision')::bigint, -1
  );
begin
  perform production_control.assert_canonical_financial_worker_context_v1(input,canonical_context,'NET_SKINS');
  existing_response := production_control.lookup_cutover_receipt(
    'NET_SKINS_V1_COMPLETE', input
  );
  if existing_response is not null then return existing_response; end if;
  if job_id_value is null or claim_token_value is null or worker_value = ''
     or input->>'engine_version' is distinct from 'net-skins-full-net-v2'
     or result_state_value not in ('PROVISIONAL', 'OFFICIAL')
     or pg_catalog.jsonb_typeof(coalesce(
       result_payload_value, 'null'::jsonb
     )) <> 'object' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_COMPLETION_INPUT_INVALID';
  end if;

  perform production_control.lock_net_skins_storylines_v1('2026',input);
  select value.* into strict current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = '2026'
  for update;
  if current_value.state <> 'CONFIGURED'
     or current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_NET_SKINS_CONFIGURATION_REVISION_CONFLICT';
  end if;
  select value.* into job_value
  from scoring_authority.net_skins_v1_recalculation_jobs value
  where value.job_id = job_id_value
  for update;
  if not found
     or job_value.status <> 'RUNNING'
     or job_value.configuration_revision <>
       current_value.configuration_revision
     or job_value.claim_token <> claim_token_value
     or job_value.claimed_by <> worker_value
     or job_value.lease_expires_at <= pg_catalog.now() then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_NET_SKINS_JOB_LEASE_REQUIRED';
  end if;
  if input->>'source_fingerprint'
       is distinct from job_value.source_fingerprint then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_NET_SKINS_SOURCE_REVISION_CONFLICT';
  end if;

  current_source_value :=
    production_control.net_skins_v1_round_source_revision(
      '2026', job_value.round_number
    );
  current_source_fingerprint :=
    production_control.net_skins_v1_hash(current_source_value);
  if current_source_fingerprint <> job_value.source_fingerprint then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_NET_SKINS_SOURCE_REVISION_CONFLICT';
  end if;
  if coalesce((result_payload_value->>'round')::integer, 0) <>
       job_value.round_number then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_RESULT_ROUND_MISMATCH';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format('production-net-skins-v1:2026:R%s',
        job_value.round_number), 202608290055
    )
  );
  select coalesce(pg_catalog.max(value.result_revision), 0)
    into current_result_revision
  from scoring_authority.net_skins_v1_result_revisions value
  where value.tournament_id = '2026'
    and value.round_number = job_value.round_number;
  if current_result_revision <> expected_result_revision then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_NET_SKINS_RESULT_REVISION_CONFLICT';
  end if;

  if result_state_value = 'OFFICIAL' then
    normalized_result_value :=
      production_control.normalize_production_net_skins_v1_official_result(
        job_value.round_number, result_payload_value
      );
  else
    normalized_result_value := null;
    if pg_catalog.jsonb_typeof(coalesce(
         result_payload_value->'skins', 'null'::jsonb
       )) <> 'array'
       or pg_catalog.jsonb_typeof(coalesce(
         result_payload_value->'leaderboard', 'null'::jsonb
       )) <> 'array' then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_NET_SKINS_PROVISIONAL_RESULT_INVALID';
    end if;
  end if;
  payload_hash_value := production_control.net_skins_v1_hash(
    result_payload_value
  );

  update scoring_authority.net_skins_v1_result_revisions
  set is_current = false, superseded_at = pg_catalog.now()
  where tournament_id = '2026'
    and round_number = job_value.round_number
    and is_current;

  insert into scoring_authority.net_skins_v1_result_revisions (
    tournament_id, round_number, configuration_revision_id,
    configuration_revision, result_revision, job_id, engine_version,
    configuration_fingerprint, source_fingerprint, result_state,
    engine_result_payload, public_result_payload, payload_hash, is_current,
    calculated_by, calculated_at, published_at
  ) values (
    '2026', job_value.round_number,
    job_value.configuration_revision_id,
    job_value.configuration_revision, current_result_revision + 1,
    job_value.job_id, 'net-skins-full-net-v2',
    job_value.configuration_fingerprint, job_value.source_fingerprint,
    result_state_value, result_payload_value, normalized_result_value,
    payload_hash_value, true, worker_value, pg_catalog.now(),
    case when result_state_value = 'OFFICIAL'
      then pg_catalog.now() else null end
  ) returning * into result_value;

  update scoring_authority.net_skins_v1_recalculation_jobs
  set status = 'SUCCEEDED',
      claimed_by = null,
      claim_token = null,
      lease_expires_at = null,
      completed_at = pg_catalog.now(),
      last_error_code = null,
      last_error_safe = null,
      updated_at = pg_catalog.now()
  where job_id = job_value.job_id;

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'PRODUCTION_NET_SKINS_V1_RECALCULATION_COMPLETED',
    worker_value, pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id,
      'round_number', job_value.round_number,
      'configuration_revision', job_value.configuration_revision,
      'result_revision', result_value.result_revision,
      'result_state', result_state_value,
      'source_fingerprint', job_value.source_fingerprint,
      'payload_hash', payload_hash_value,
      'published', result_state_value = 'OFFICIAL'
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_NET_SKINS_V1_RECALCULATION_COMPLETED', 'NET_SKINS',
    '2026', worker_value, pg_catalog.lower(input->>'request_fingerprint'),
    'SUCCEEDED', pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id,
      'round_number', job_value.round_number,
      'configuration_revision', job_value.configuration_revision,
      'result_revision', result_value.result_revision,
      'result_state', result_state_value,
      'published', result_state_value = 'OFFICIAL'
    )
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_NET_SKINS_V1_RECALCULATION_COMPLETED',
    'job_id', job_value.job_id,
    'round_number', job_value.round_number,
    'configuration_revision', job_value.configuration_revision,
    'result_revision', result_value.result_revision,
    'result_state', result_state_value,
    'published', result_state_value = 'OFFICIAL',
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'NET_SKINS_V1_COMPLETE', input, response_value
  );
  return response_value;
end;
$$;


ALTER FUNCTION production_control.canonical_complete_net_skins_v1_recalculation_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_completed_history_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_completed_history_read_v1(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  resource production_control.resource_scope%rowtype;
  cert_resource production_control.canonical_resource_v1%rowtype;
  source_ref text; source_provenance text;
  mode_value text := upper(btrim(coalesce(input->>'mode', input->>'scope', 'YEARS')));
  target_year integer;
  revision_value uuid;
  result_value jsonb;
begin
  if canonical_context is null then
    resource := production_control.assert_production_cutover_read_scope(input, 'READ_CUTOVER');
    source_ref:=resource.project_ref; source_provenance:=resource.google_workbook_id;
  else
    cert_resource:=production_control.assert_certification_read_v1(canonical_context,input);
    source_ref:=cert_resource.project_ref; source_provenance:=cert_resource.provenance_id;
  end if;
  if mode_value = 'YEARS' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'tournament_id', revision.tournament_id,
      'tournament_year', revision.tournament_year,
      'revision_id', revision.revision_id,
      'revision_number', revision.revision_number,
      'source_fingerprint', revision.source_fingerprint,
      'payload_fingerprint', revision.payload_fingerprint,
      'import_contract_version', revision.import_contract_version,
      'correction_set_version', revision.correction_set_version,
      'importer_version', revision.importer_version,
      'certified_at', revision.certified_at,
      'canonical_counts', revision.canonical_counts,
      'certification', revision.certification,
      'tournament', jsonb_build_object(
        'name', tournament.name, 'start_date', fact.start_date, 'end_date', fact.end_date,
        'destination', fact.destination, 'lifecycle', fact.lifecycle,
        'score_availability', fact.score_availability,
        'official_team_1_points', fact.official_team_1_points,
        'official_team_2_points', fact.official_team_2_points,
        'total_awarded_points', fact.total_awarded_points,
        'champion_team_side', fact.champion_team_side,
        'champion_team_id', fact.champion_team_id
      )
    ) order by revision.tournament_year), '[]'::jsonb)
    into result_value
    from scoring_authority.completed_history_current_revisions current_pointer
    join scoring_authority.completed_history_revisions revision
      on revision.revision_id = current_pointer.revision_id
    join scoring_authority.tournaments tournament
      on tournament.tournament_id = revision.tournament_id
    join scoring_authority.completed_history_tournament_facts fact
      on fact.revision_id = revision.revision_id
    where revision.project_ref = source_ref
      and revision.source_workbook_id = source_provenance;
  elsif mode_value = 'YEAR' then
    begin
      target_year := coalesce(input->>'tournament_year', input->>'year')::integer;
    exception when others then
      return jsonb_build_object('ok', false, 'code', 'HISTORICAL_YEAR_REQUIRED');
    end;
    if target_year not between 2017 and 2025 then
      return jsonb_build_object('ok', false, 'code', 'HISTORICAL_YEAR_REQUIRED');
    end if;
    select current_pointer.revision_id into revision_value
    from scoring_authority.completed_history_current_revisions current_pointer
    join scoring_authority.completed_history_revisions revision
      on revision.revision_id = current_pointer.revision_id
    where current_pointer.tournament_year = target_year
      and revision.project_ref = source_ref
      and revision.source_workbook_id = source_provenance;
    if revision_value is null then
      return jsonb_build_object('ok', false, 'code', 'HISTORICAL_YEAR_NOT_CERTIFIED');
    end if;
    select jsonb_build_object(
      'revision', to_jsonb(revision),
      'tournament', to_jsonb(tournament) || to_jsonb(fact),
      'players', coalesce((
        select jsonb_agg(jsonb_build_object(
          'player_id', player.player_id,
          'display_name', player.display_name
        ) order by player.player_id)
        from scoring_authority.completed_history_roster_facts roster
        join scoring_authority.players player on player.player_id = roster.player_id
        where roster.revision_id = revision_value
      ), '[]'::jsonb),
      'teams', coalesce((
        select jsonb_agg(to_jsonb(team_fact) order by team_fact.team_side)
        from scoring_authority.completed_history_team_facts team_fact
        where team_fact.revision_id = revision_value
      ), '[]'::jsonb),
      'roster', coalesce((
        select jsonb_agg(to_jsonb(roster) order by roster.team_side, roster.display_name, roster.player_id)
        from scoring_authority.completed_history_roster_facts roster
        where roster.revision_id = revision_value
      ), '[]'::jsonb),
      'rounds', coalesce((
        select jsonb_agg(to_jsonb(round_fact) order by round_fact.round_number)
        from scoring_authority.completed_history_round_facts round_fact
        where round_fact.revision_id = revision_value
      ), '[]'::jsonb),
      'courses', coalesce((
        select jsonb_agg(jsonb_build_object(
          'course_id', course.course_id,
          'canonical_name', course.canonical_name,
          'canonical_location', course.canonical_location
        ) order by course.course_id)
        from (
          select distinct appearance.course_id
          from scoring_authority.completed_history_course_appearances appearance
          where appearance.revision_id = revision_value
        ) year_course
        join scoring_authority.completed_history_course_identities course
          on course.course_id = year_course.course_id
      ), '[]'::jsonb),
      'course_appearances', coalesce((
        select jsonb_agg(to_jsonb(appearance) || jsonb_build_object(
          'canonical_name', course.canonical_name,
          'canonical_location', course.canonical_location
        ) order by appearance.round_number)
        from scoring_authority.completed_history_course_appearances appearance
        join scoring_authority.completed_history_course_identities course
          on course.course_id = appearance.course_id
        where appearance.revision_id = revision_value
      ), '[]'::jsonb),
      'matches', coalesce((
        select jsonb_agg(to_jsonb(match_value) order by match_value.round_number, match_value.match_id)
        from scoring_authority.completed_history_matches match_value
        where match_value.revision_id = revision_value
      ), '[]'::jsonb),
      'match_participants', coalesce((
        select jsonb_agg(to_jsonb(participant) order by participant.match_id, participant.team_side, participant.player_slot)
        from scoring_authority.completed_history_match_participants participant
        where participant.revision_id = revision_value
      ), '[]'::jsonb),
      'scorecards', coalesce((
        select jsonb_agg(to_jsonb(scorecard) order by scorecard.match_id, scorecard.scorecard_id)
        from scoring_authority.completed_history_scorecards scorecard
        where scorecard.revision_id = revision_value
      ), '[]'::jsonb),
      'awards', coalesce((
        select jsonb_agg(to_jsonb(award) order by award.award_type, award.award_id)
        from scoring_authority.completed_history_awards award
        where award.revision_id = revision_value
      ), '[]'::jsonb),
      'record_eligibility', coalesce((
        select jsonb_agg(to_jsonb(eligibility) order by eligibility.match_id, eligibility.player_id)
        from scoring_authority.completed_history_record_eligibility eligibility
        where eligibility.revision_id = revision_value
      ), '[]'::jsonb),
      'corrections', coalesce((
        select jsonb_agg(to_jsonb(correction) order by correction.correction_id)
        from scoring_authority.completed_history_correction_applications correction
        where correction.revision_id = revision_value
      ), '[]'::jsonb)
    ) into result_value
    from scoring_authority.completed_history_revisions revision
    join scoring_authority.tournaments tournament
      on tournament.tournament_id = revision.tournament_id
    join scoring_authority.completed_history_tournament_facts fact
      on fact.revision_id = revision.revision_id
    where revision.revision_id = revision_value;
  else
    return jsonb_build_object(
      'ok', false, 'code', 'PRODUCTION_CUTOVER_HISTORY_MODE_NOT_ALLOWED'
    );
  end if;
  if canonical_context is not null then return production_control.mark_certification_read_v1(
    jsonb_build_object('ok',true,'data',result_value),canonical_context); end if;
  return production_control.mark_cutover_read_response(
    jsonb_build_object('ok', true, 'data', result_value), 'READ_CUTOVER'
  );
end;
$$;


ALTER FUNCTION production_control.canonical_completed_history_read_v1(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_configure_net_skins_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_configure_net_skins_v1(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  existing_value scoring_authority.net_skins_v1_configuration_revisions%rowtype;
  revision_value scoring_authority.net_skins_v1_configuration_revisions%rowtype;
  selected_rounds integer[];
  manifest_value jsonb;
  round_value jsonb;
  entry_value jsonb;
  overall_fingerprint text;
  resource_fingerprint_value text;
  request_fingerprint_value text := pg_catalog.lower(
    coalesce(input->>'request_fingerprint', '')
  );
  payload_hash_value text := production_control.net_skins_v1_hash(input);
  expected_configuration bigint := coalesce(
    (input->>'expected_configuration_revision')::bigint, -1
  );
  actor_player text := pg_catalog.btrim(
    coalesce(input#>>'{authorization,player_id}', '')
  );
  actor_auth_user uuid := nullif(
    input#>>'{authorization,auth_user_id}', ''
  )::uuid;
  response_value jsonb;
  round_count integer := 0;
  entry_count integer := 0;
  affected_rows bigint;
begin
  if canonical_context is null then
    perform production_control.assert_production_net_skins_v1_runtime(input);
  else
    perform production_control.assert_canonical_scoring_context_v1(input, canonical_context, 'RUNTIME');
    if canonical_context->>'tournament_id' is distinct from '2026'
      or canonical_context->>'resource_class' is distinct from 'CERTIFICATION'
      or (not production_control.model_d_context_v1(canonical_context) and (canonical_context->>'resource_id' is distinct from 'CERTIFICATION:2857f707-065a-405d-b5fc-b5b6fa1b0f51' or canonical_context->>'project_ref' is distinct from 'trmcwrljjxwhgtikfdgu')) then
      raise exception using errcode='42501',message='CERTIFICATION_NET_SKINS_TARGET_DENIED';
    end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('production-tournament-setup-v1:'||'2026',0));
  perform production_control.assert_production_scoring_actor(input, true);

  if input->>'contract_version'
       is distinct from 'production-net-skins-v1'
     or input->>'publication_policy' is distinct from 'OFFICIAL_ONLY'
     or request_fingerprint_value !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(coalesce(
       input->'eligible_round_numbers', 'null'::jsonb
     )) <> 'array' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_CONFIGURATION_INPUT_INVALID';
  end if;

  select value.* into existing_value
  from scoring_authority.net_skins_v1_configuration_revisions value
  where value.request_fingerprint = request_fingerprint_value;
  if found then
    if existing_value.request_payload_hash <> payload_hash_value then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_NET_SKINS_IDEMPOTENCY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_NET_SKINS_V1_CONFIGURED',
      'configuration_revision', existing_value.configuration_revision,
      'configuration_fingerprint',
        existing_value.configuration_fingerprint,
      'state', existing_value.state,
      'rounds', existing_value.configuration_manifest->'rounds',
      'idempotent', true
    );
  end if;

  begin
    select pg_catalog.array_agg(value::integer order by value::integer)
      into selected_rounds
    from pg_catalog.jsonb_array_elements_text(
      input->'eligible_round_numbers'
    ) value;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_ELIGIBLE_ROUNDS_INVALID';
  end;

  if canonical_context is null then
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  else
    -- Same domain operation; identity is from the admitted private marker,
    -- never a caller-selected resource, financial fact or Production row.
    activation.activation_revision := (canonical_context->>'activation_revision')::bigint;
    activation.authority_generation_id := (canonical_context->>'authority_epoch_id')::uuid;
    activation.expected_deployment_commit := canonical_context->>'release_commit';
    resource.project_ref := canonical_context->>'project_ref';
    resource.project_url := canonical_context->>'project_url';
    resource.current_tournament_id := canonical_context->>'tournament_id';
    resource.google_workbook_id := 'urn:bagger:synthetic:'||(canonical_context->>'installation_id');
    -- Absence is a revision-zero CAS expectation, never a fabricated ledger row.
  end if;
  if canonical_context is null then
  select value.* into strict current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = '2026'
  for update;
  else
    select value.* into current_value from scoring_authority.net_skins_v1_configuration_current value
      where value.tournament_id='2026' for update;
    current_value.configuration_revision:=coalesce(current_value.configuration_revision,0);
  end if;

  if activation.activation_revision < 0
     or activation.activation_revision <>
       (input->>'expected_activation_revision')::bigint then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_NET_SKINS_ACTIVATION_REVISION_CONFLICT';
  end if;
  if current_value.configuration_revision <> expected_configuration then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_NET_SKINS_CONFIGURATION_REVISION_CONFLICT';
  end if;

  manifest_value :=
    production_control.full_net_skins_manifest_v2('2026',selected_rounds,input->'entry_revisions');
  overall_fingerprint := production_control.net_skins_v1_hash(manifest_value);
  resource_fingerprint_value := production_control.net_skins_v1_hash(
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-net-skins-v1',
      'environment', case when canonical_context is null then 'PRODUCTION' else 'CERTIFICATION' end,
      'project_ref', resource.project_ref,
      'project_url', resource.project_url,
      'source_workbook_id', resource.google_workbook_id,
      'tournament_id', resource.current_tournament_id,
      'vercel_project_id', input->>'vercel_project_id',
      'vercel_team_id', input->>'vercel_team_id',
      'vercel_environment', case when canonical_context is null then 'production' else 'preview' end,
      'deployment_commit', activation.expected_deployment_commit,
      'authority_epoch_id', activation.authority_generation_id,
      'activation_revision', activation.activation_revision
    )
  );

  insert into scoring_authority.net_skins_v1_configuration_revisions (
    tournament_id, configuration_revision, contract_version, state,
    publication_policy, configuration_manifest, configuration_fingerprint,
    resource_fingerprint, activation_revision, authority_epoch_id,
    configured_by_player_id, configured_by_auth_user_id,
    request_fingerprint, request_payload_hash, configured_at
  ) values (
    '2026', current_value.configuration_revision + 1,
    'production-net-skins-v1', 'CONFIGURED', 'OFFICIAL_ONLY',
    manifest_value, overall_fingerprint, resource_fingerprint_value,
    activation.activation_revision, activation.authority_generation_id,
    actor_player, actor_auth_user, request_fingerprint_value,
    payload_hash_value, pg_catalog.now()
  ) returning * into revision_value;

  -- Preserve revision history in the immutable V1 ledger while updating the
  -- installed canonical engine-input tables atomically.
  update scoring_authority.net_skins_configurations
  set enabled = false,
      configuration_revision = revision_value.configuration_revision,
      imported_by = actor_player,
      updated_at = pg_catalog.now()
  where tournament_id = '2026';

  for round_value in
    select value
    from pg_catalog.jsonb_array_elements(manifest_value->'rounds') value
  loop
    round_count := round_count + 1;
    insert into scoring_authority.net_skins_configurations (
      tournament_id, round_number, format, enabled, entry_type,
      buy_in_per_entry, expected_pot, completion_rule, payout_rounding,
      tie_rule, configuration_revision, configuration_fingerprint,
      source_workbook_id, imported_by, imported_at, approved_at, updated_at
    ) values (
      '2026', (round_value->>'round_number')::integer,
      round_value->>'format', true, round_value->>'entry_type',
      (round_value->>'buy_in_per_entry')::numeric,
      (round_value->>'expected_pot')::numeric,
      round_value->>'completion_rule', round_value->>'payout_rounding',
      round_value->>'tie_rule', revision_value.configuration_revision,
      round_value->>'configuration_fingerprint',
      resource.google_workbook_id, actor_player, pg_catalog.now(),
      pg_catalog.now(), pg_catalog.now()
    ) on conflict (tournament_id, round_number) do update set
      format = excluded.format,
      enabled = true,
      entry_type = excluded.entry_type,
      buy_in_per_entry = excluded.buy_in_per_entry,
      expected_pot = excluded.expected_pot,
      completion_rule = excluded.completion_rule,
      payout_rounding = excluded.payout_rounding,
      tie_rule = excluded.tie_rule,
      configuration_revision = excluded.configuration_revision,
      configuration_fingerprint = excluded.configuration_fingerprint,
      source_workbook_id = excluded.source_workbook_id,
      imported_by = excluded.imported_by,
      imported_at = excluded.imported_at,
      approved_at = excluded.approved_at,
      updated_at = excluded.updated_at;

    delete from scoring_authority.net_skins_configuration_entries
    where tournament_id = '2026'
      and round_number = (round_value->>'round_number')::integer;

    for entry_value in
      select value
      from pg_catalog.jsonb_array_elements(round_value->'entries') value
    loop
      entry_count := entry_count + 1;
      insert into scoring_authority.net_skins_configuration_entries (
        tournament_id, round_number, entry_id, match_number, format,
        player_id_1, player_id_2, team_handicap, buy_in, eligible,
        source_payload, created_at, updated_at
      ) values (
        '2026', (round_value->>'round_number')::integer,
        entry_value->>'entry_id', entry_value->>'match_number',
        round_value->>'format', entry_value->>'player_id_1',
        nullif(entry_value->>'player_id_2', ''),
        nullif(entry_value->>'team_handicap', '')::numeric,
        (entry_value->>'buy_in')::numeric, true,
        pg_catalog.jsonb_build_object(
          'Contract Version', 'production-net-skins-v1',
          'Canonical Match ID', entry_value->>'match_id',
          'Stable Player IDs', entry_value->'player_ids',
          'Eligible Holes', round_value->'eligible_holes',
          'Net Handicap Basis', round_value->>'net_handicap_basis',
          'Entry Revision',entry_value->'entry_revision','Entry Key',entry_value->>'entry_key','Entry Binding Fingerprint',entry_value->>'binding_fingerprint','Individual Stroke Allocation',
            entry_value->'individual_stroke_allocation'
        ),
        pg_catalog.now(), pg_catalog.now()
      );
    end loop;
  end loop;

  if canonical_context is null then
  update scoring_authority.net_skins_v1_configuration_current
  set configuration_revision_id = revision_value.configuration_revision_id,
      configuration_revision = revision_value.configuration_revision,
      state = 'CONFIGURED',
      updated_at = pg_catalog.now()
  where tournament_id = '2026';
  else
    insert into scoring_authority.net_skins_v1_configuration_current(tournament_id,configuration_revision_id,configuration_revision,state)
    values('2026',revision_value.configuration_revision_id,revision_value.configuration_revision,'CONFIGURED')
    on conflict(tournament_id) do update set configuration_revision_id=excluded.configuration_revision_id,
      configuration_revision=excluded.configuration_revision,state=excluded.state,updated_at=pg_catalog.now();
  end if;
  get diagnostics affected_rows = row_count;
  if canonical_context is not null and affected_rows <> 1 then
    raise exception using errcode='PT409',message='CERTIFICATION_NET_SKINS_POINTER_DRIFT';
  end if;

  update scoring_authority.net_skins_v1_recalculation_jobs
  set status = 'SUPERSEDED',
      claimed_by = null,
      claim_token = null,
      lease_expires_at = null,
      completed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where tournament_id = '2026'
    and status in ('PENDING', 'RUNNING');

  update scoring_authority.net_skins_v1_result_revisions
  set is_current = false,
      superseded_at = pg_catalog.now()
  where tournament_id = '2026' and is_current;

  insert into scoring_authority.net_skins_configuration_import_runs (
    tournament_id, source_workbook_id, configuration_fingerprint,
    status, round_count, entry_count, requested_by, imported_at
  ) values (
    '2026', resource.google_workbook_id, overall_fingerprint,
    'APPLIED', round_count, entry_count, actor_player, pg_catalog.now()
  );

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'PRODUCTION_NET_SKINS_V1_CONFIGURED', actor_player,
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-net-skins-v1',
      'configuration_revision', revision_value.configuration_revision,
      'configuration_fingerprint', overall_fingerprint,
      'resource_fingerprint', resource_fingerprint_value,
      'round_count', round_count,
      'entry_count', entry_count,
      'publication_policy', 'OFFICIAL_ONLY',
      'authority_changed', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_NET_SKINS_V1_CONFIGURED', 'NET_SKINS', '2026',
    actor_player, request_fingerprint_value, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'configuration_revision', revision_value.configuration_revision,
      'configuration_fingerprint', overall_fingerprint,
      'resource_fingerprint', resource_fingerprint_value,
      'round_count', round_count,
      'entry_count', entry_count,
      'publication_policy', 'OFFICIAL_ONLY'
    )
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_NET_SKINS_V1_CONFIGURED',
    'configuration_revision', revision_value.configuration_revision,
    'configuration_fingerprint', overall_fingerprint,
    'state', 'CONFIGURED',
    'rounds', manifest_value->'rounds',
    'idempotent', false
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.canonical_configure_net_skins_v1(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_create_guide_draft_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_create_guide_draft_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  target_year integer;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}','')));
  actor_auth uuid;
  request_id uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash','')));
  expected_revision bigint;
  expected_revision_id_text text := pg_catalog.lower(pg_catalog.btrim(
    coalesce(input->>'expected_published_revision_id','')));
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason',''));
  authoring_value jsonb := coalesce(input->'authoring_content',input->'content');
  projection_value jsonb := input->'projection_payload';
  validation jsonb;
  current_value jsonb;
  database_hash text;
  prior_receipt jsonb;
  draft_id_value uuid;
  response_value jsonb;
begin
  target := production_control.assert_guide_authoring_resource_v2(input, resource_context);
  target_year := target::integer;
  if input->>'operation' is distinct from
       'CREATE_PRODUCTION_GUIDE_DRAFT_V1'
     or coalesce(input->>'operation_request_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_published_revision','') !~ '^[0-9]+$'
     or coalesce(input->>'authoring_content_fingerprint','')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'content_fingerprint','') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'projection_payload_hash','') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'canonical_reference_fingerprint','')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(authoring_value) is distinct from 'object'
     or pg_catalog.jsonb_typeof(projection_value) is distinct from 'object'
     or reason_value='' or pg_catalog.length(reason_value)>500 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_INPUT_INVALID');
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  expected_revision := (input->>'expected_published_revision')::bigint;
  validation := production_control.validate_guide_draft_structure_v1(
    target,target_year,authoring_value,projection_value,
    input->>'authoring_content_fingerprint',input->>'content_fingerprint',
    input->>'projection_payload_hash');
  database_hash := production_control.guide_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation','CREATE','tournamentId',target,
      'actorPlayerId',actor_player,'actorAuthUserId',actor_auth,
      'expectedPublishedRevision',expected_revision,
      'expectedPublishedRevisionId',expected_revision_id_text,
      'authoringContent',authoring_value,'projectionPayload',projection_value,
      'canonicalReferenceFingerprint',
        input->>'canonical_reference_fingerprint',
      'reason',reason_value));
  prior_receipt := production_control.guide_operation_receipt_v1(
    target,'CREATE',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  if not coalesce((validation->>'pass')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_VALIDATION_FAILED',
      'issues',validation->'issues');
  end if;
  if input->>'canonical_reference_fingerprint' is distinct from
       production_control.guide_canonical_reference_fingerprint_v1(target) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_CANONICAL_REFERENCE_STALE');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-guide-authoring:'||target,0));
  prior_receipt := production_control.guide_operation_receipt_v1(
    target,'CREATE',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  if input->>'canonical_reference_fingerprint' is distinct from
       production_control.guide_canonical_reference_fingerprint_v1(target) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_CANONICAL_REFERENCE_STALE');
  end if;
  current_value := production_control.guide_current_publication_v1(target);
  if (current_value->>'revision')::bigint <> expected_revision
     or (expected_revision_id_text <> '' and expected_revision_id_text
       is distinct from pg_catalog.lower(coalesce(
         current_value->>'revisionId',''))) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_PREDECESSOR_STALE',
      'currentRevision',(current_value->>'revision')::bigint,
      'currentRevisionId',current_value->>'revisionId');
  end if;
  if exists (select 1
    from production_control.guide_authoring_drafts_v1 value
    where value.tournament_id=target and value.state in ('DRAFT','VALIDATED'))
  then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_OPEN_DRAFT_EXISTS');
  end if;
  insert into production_control.guide_authoring_drafts_v1 (
    tournament_id,tournament_year,draft_version,state,authoring_kind,
    expected_published_revision,expected_published_revision_id,
    authoring_content,projection_payload,authoring_content_fingerprint,
    content_fingerprint,projection_payload_hash,canonical_reference_fingerprint,
    validation_diagnostics,
    reason,created_by_player_id,created_by_auth_user_id
  ) values (
    target,target_year,1,'DRAFT','DIRECTOR_EDIT',expected_revision,
    nullif(expected_revision_id_text,'')::uuid,
    validation->'authoringContent',validation->'projectionPayload',
    validation->>'authoringContentFingerprint',
    validation->>'contentFingerprint',validation->>'projectionPayloadHash',
    input->>'canonical_reference_fingerprint',
    (validation->'diagnostics')||pg_catalog.jsonb_build_object(
      'validated',false,'requiresReview',false),reason_value,
    actor_player,actor_auth
  ) returning draft_id into draft_id_value;
  response_value := pg_catalog.jsonb_build_object(
    'ok',true,'code','GUIDE_DRAFT_CREATED','idempotent',false,
    'tournamentId',target,'draftId',draft_id_value,'draftVersion',1,
    'state','DRAFT','expectedPublishedRevision',expected_revision,
    'authoringContent',validation->'authoringContent',
    'preview',validation->'projectionPayload',
    'projectionPayload',validation->'projectionPayload',
    'validationDiagnostics',validation->'diagnostics');
  insert into production_control.guide_authoring_audit_events_v1 (
    tournament_id,draft_id,action,actor_player_id,actor_auth_user_id,summary
  ) values (
    target,draft_id_value,'DRAFT_CREATED',actor_player,actor_auth,
    pg_catalog.jsonb_build_object(
      'draftVersion',1,
      'predecessorRevision',expected_revision,
      'itemCount',validation#>>'{diagnostics,authoringItemCount}'));
  insert into production_control.guide_authoring_operation_receipts_v1 (
    tournament_id,operation,operation_request_id,
    declared_request_payload_hash,request_payload_hash,
    actor_player_id,actor_auth_user_id,response
  ) values (
    target,'CREATE',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value);
  return response_value;
exception when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_INPUT_INVALID');
when unique_violation then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_OPERATION_CONFLICT');
end;

$_$;


ALTER FUNCTION production_control.canonical_create_guide_draft_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_current_view_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_current_view_read_v1(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'participant_identity'
    AS $$
declare
  resource production_control.resource_scope%rowtype;
  cert_resource production_control.canonical_resource_v1%rowtype;
  source_provenance text;
  surface text := upper(btrim(coalesce(input->>'surface', '')));
  required_phase text := case
    when surface in ('PUBLISHED_ODDS', 'GUIDE_COURSE_CONTEXT') then 'READ_CUTOVER'
    when surface = 'ODDS_INPUT' then 'ODDS_WAR_ROOM'
    else 'CURRENT_READS' end;
  player_id_value text := btrim(coalesce(input->>'player_id', ''));
  match_id_value text := btrim(coalesce(input->>'match_id', ''));
  engine_keys_value text[];
  result_value jsonb;
  finalized_value jsonb;
begin
  if canonical_context is null then
    resource := production_control.assert_production_cutover_read_scope(input, required_phase);
    source_provenance:=resource.google_workbook_id;
  else
    cert_resource:=production_control.assert_certification_read_v1(canonical_context,input);
    source_provenance:=cert_resource.provenance_id;
    if surface<>'HISTORY_2026' and canonical_context->>'current_tournament_id'<>'2026' then
      raise exception using errcode='55000',message='CERTIFICATION_CURRENT_READ_POINTER_NOT_2026';
    end if;
  end if;
  if surface in ('TOURNAMENT_LIVE', 'LEADERBOARDS', 'GUIDE_COURSE_CONTEXT') then
    result_value := public.read_leaderboards_core_view('2026');
  elsif surface = 'HISTORY_2026' then
    result_value:=production_control.canonical_finalized_tournament_projection_v1('2026','production-2026-history-v1');
  elsif surface = 'PARTICIPANT_HOME' then
    if player_id_value = '' then result_value := jsonb_build_object('ok',false,'code','PLAYER_ID_REQUIRED');
    else result_value := public.read_participant_home_view('2026', player_id_value); end if;
  elsif surface = 'MY_MATCH' then
    if player_id_value = '' then result_value := jsonb_build_object('ok',false,'code','PLAYER_ID_REQUIRED');
    else result_value := public.read_my_match_view('2026', player_id_value); end if;
  elsif surface = 'GAME_CENTER' then
    if match_id_value = '' or not exists (
      select 1 from scoring_authority.matches value
      where value.match_id = match_id_value and value.tournament_id = '2026'
    ) then result_value := jsonb_build_object('ok',false,'code','PRODUCTION_MATCH_NOT_FOUND');
    else result_value := public.read_game_center_view(match_id_value); end if;
  elsif surface = 'MATCH_AUTHORIZATION' then
    result_value := public.read_match_authorization_matrix('2026');
  elsif surface = 'NET_SKINS_INPUT' then
    result_value := public.read_net_skins_input_view('2026');
  elsif surface = 'NET_SKINS_RESULT' then
    result_value := public.read_net_skins_result_view('2026');
  elsif surface = 'CALCUTTA_CONFIGURATION' then
    result_value := public.read_calcutta_configuration_view('2026');
  elsif surface = 'PUBLISHED_ODDS' then
    if canonical_context is null then
      result_value := public.read_published_odds_view('2026', source_provenance);
    else result_value:=production_control.certification_published_odds_read_v1('2026',canonical_context);end if;
  elsif surface = 'ODDS_INPUT' then
    result_value := public.read_championship_odds_inputs('2026');
  elsif surface = 'PARTICIPANT_IDENTITY' then
    if player_id_value = '' then result_value := jsonb_build_object('ok',false,'code','PLAYER_ID_REQUIRED');
    else result_value := public.read_participant_identity_context('2026', player_id_value); end if;
  elsif surface = 'COMPETITION_DERIVED' then
    if jsonb_typeof(input->'engine_keys') <> 'array' then
      result_value := jsonb_build_object('ok',false,'code','ENGINE_KEYS_REQUIRED');
    else
      select array_agg(value) into engine_keys_value
      from jsonb_array_elements_text(input->'engine_keys') value;
      if engine_keys_value is null or cardinality(engine_keys_value) = 0 or exists (
        select 1 from unnest(engine_keys_value) value where value not in (
          'TEAM_MOMENTUM','TOURNAMENT_STORYLINES','CALCUTTA',
          'TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL','TOURNAMENT_FINAL_RECAP'
        )
      ) then result_value := jsonb_build_object('ok',false,'code','ENGINE_KEYS_INVALID');
      else result_value := public.read_competition_derived_state('2026', engine_keys_value); end if;
    end if;
  else
    result_value := jsonb_build_object('ok',false,'code','PRODUCTION_CUTOVER_SURFACE_NOT_ALLOWED');
  end if;
  if canonical_context is not null then return production_control.mark_certification_read_v1(result_value,canonical_context); end if;
  return production_control.mark_cutover_read_response(result_value, required_phase);
end;
$$;


ALTER FUNCTION production_control.canonical_current_view_read_v1(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_director_entitlement_read_v1(uuid, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_director_entitlement_read_v1(target_auth_user_id uuid, target_tournament_id text, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'public', 'auth', 'pg_temp'
    AS $$
begin
  if canonical_context is null then
  perform production_control.assert_production_participant_identity_cutover();
  else
    perform production_control.assert_certification_read_v1(canonical_context,jsonb_build_object('target_tournament_id',coalesce(target_tournament_id,'2026')));
    if canonical_context->>'current_tournament_id'<>'2026' then raise exception using errcode='55000',message='CERTIFICATION_IDENTITY_POINTER_NOT_2026'; end if;
  end if;
  if target_auth_user_id is null or btrim(coalesce(target_tournament_id, '')) <> '2026' then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_SCOPE_INVALID');
  end if;
  return coalesce((select jsonb_build_object(
    'ok', true, 'found', true, 'active', entitlement.status = 'ACTIVE',
    'status', entitlement.status, 'tournamentId', entitlement.tournament_id,
    'directorPlayerId', entitlement.player_id, 'role', entitlement.role,
    'revision', coalesce((select max(event.event_id)
      from production_control.director_entitlement_events event
      where event.entitlement_id = entitlement.entitlement_id), 0),
    'grantedAt', entitlement.granted_at, 'revokedAt', entitlement.revoked_at
  ) from production_control.director_entitlements entitlement
  join participant_identity.user_player_links link
    on link.auth_user_id = entitlement.auth_user_id
    and link.player_id = entitlement.player_id and link.status = 'ACTIVE'
  join auth.users auth_user
    on auth_user.id = entitlement.auth_user_id and auth_user.email_confirmed_at is not null
  where entitlement.auth_user_id = target_auth_user_id
    and entitlement.tournament_id = '2026'
    and exists (select 1 from participant_identity.tournament_roles role_row
      where role_row.tournament_id = '2026'
        and role_row.auth_user_id = entitlement.auth_user_id
        and role_row.role = 'DIRECTOR' and role_row.role_active)),
  jsonb_build_object('ok', true, 'found', false, 'active', false));
end;
$$;


ALTER FUNCTION production_control.canonical_director_entitlement_read_v1(target_auth_user_id uuid, target_tournament_id text, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_director_financial_operation_v2(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_director_financial_operation_v2(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare payload jsonb:=coalesce(input->'payload','{}'); domain_input jsonb; fingerprint text; result jsonb;
 status_read boolean:=not mutation and input->>'mode'='status'; original_token text;
 entry_receipt production_control.net_skins_entry_revisions_v1%rowtype; operation_name text;
begin
 if context->>'tournament_id' is distinct from '2026' or jsonb_typeof(payload) is distinct from 'object' then
   raise exception using errcode='42501',message='ISOLATED_DIRECTOR_CONTEXT_REQUIRED';
 end if;
 original_token:=case when status_read then input->>'expected_context_token' else context->>'context_token' end;
 if input->>'family'='NET_SKINS_ENTRIES' then
   if not mutation and not coalesce(status_read,false) then return production_control.net_skins_entries_projection_v1('2026'); end if;
   if input->>'action' is distinct from 'save' then raise exception using errcode='22023',message='ISOLATED_DIRECTOR_OPERATION_INVALID'; end if;
   domain_input:=payload||jsonb_build_object('contract_version','production-tournament-setup-v1',
     'environment',coalesce(context->>'resource_class','ISOLATED'),'tournament_id','2026','context_binding_id',context->>'binding_id',
     'context_token',original_token,'actor_auth_user_id',context->>'actor_auth_user_id',
     'actor_player_id',context->>'actor_player_id','authorization',context->'authorization',
     'operation_request_id',context->>'operation_request_id');
   if status_read then
     select * into entry_receipt from production_control.net_skins_entry_revisions_v1
       where tournament_id='2026' and request_id=(context->>'operation_request_id')::uuid;
     if found then
       if entry_receipt.request_hash is distinct from production_control.tournament_setup_hash_v1(domain_input) then
         raise exception 'TOURNAMENT_SETUP_IDEMPOTENCY_CONFLICT'; end if;
       return jsonb_build_object('ok',true,'outcome','COMMITTED','receipt',entry_receipt.response);
     end if;
     return jsonb_build_object('ok',true,'outcome','UNKNOWN','receipt',null,'code','ISOLATED_DIRECTOR_RECEIPT_NOT_FOUND');
   end if;
   result:=production_control.canonical_net_skins_entries_core_v1(domain_input);
 elsif input->>'family'='CALCUTTA_MANAGEMENT' then
   if not mutation and not coalesce(status_read,false) then
     return production_control.director_calcutta_management_projection_v1('2026',(payload->>'predecessor_auction_revision')::bigint);
   end if;
   operation_name:=case input->>'action' when 'replace-auction' then 'CALCUTTA_V1_REPLACE_AUCTION' when 'clear-entry' then 'CALCUTTA_V1_CLEAR_ENTRY' else null end;
   if operation_name is null then raise exception using errcode='22023',message='ISOLATED_DIRECTOR_OPERATION_INVALID'; end if;
   fingerprint:=production_control.calcutta_v1_hash(jsonb_build_object('binding_id',context->>'binding_id',
     'family',input->>'family','action',input->>'action','operation_request_id',context->>'operation_request_id'));
   domain_input:=payload||jsonb_build_object('contract_version','production-calcutta-v1',
     'environment',coalesce(context->>'resource_class','ISOLATED'),'tournament_id','2026','expected_tournament_id','2026',
     'context_binding_id',context->>'binding_id','context_token',original_token,
     'actor_id',context->>'actor_player_id','operation_request_id',context->>'operation_request_id',
     'authorization',context->'authorization','request_fingerprint',fingerprint);
   if status_read then
     result:=production_control.lookup_cutover_receipt(operation_name,domain_input);
     if result is not null then return jsonb_build_object('ok',true,'outcome','COMMITTED','receipt',result); end if;
     return jsonb_build_object('ok',true,'outcome','UNKNOWN','receipt',null,'code','ISOLATED_DIRECTOR_RECEIPT_NOT_FOUND');
   end if;
   insert into production_control.isolated_financial_audit_context_v1(backend_pid,transaction_id,tournament_id,action,operation_request_id,request_fingerprint,context)
   values(pg_backend_pid(),pg_current_xact_id(),'2026',input->>'action',(context->>'operation_request_id')::uuid,fingerprint,context);
   if input->>'action'='replace-auction' then result:=production_control.canonical_calcutta_auction_core_v1(domain_input,context);
   else result:=production_control.canonical_calcutta_clear_core_v1(domain_input,context); end if;
   delete from production_control.isolated_financial_audit_context_v1 where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 else raise exception using errcode='22023',message='ISOLATED_DIRECTOR_OPERATION_INVALID';
 end if;
 if coalesce((result->>'ok')::boolean,false) and not coalesce((result->>'idempotent')::boolean,false) then
   insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
   values(case when context->>'resource_class'='CERTIFICATION' then 'CERTIFICATION_DIRECTOR_FINANCIAL_OPERATION' else 'ISOLATED_DIRECTOR_FINANCIAL_OPERATION' end,input->>'family','2026',context->>'actor_player_id',fingerprint,'SUCCEEDED',
     jsonb_build_object('runtime',coalesce(context->>'resource_class','ISOLATED'),'context_binding_id',context->>'binding_id','context_token',context->>'context_token',
       'actor_auth_user_id',context->>'actor_auth_user_id','operation_request_id',context->>'operation_request_id',
       'action',input->>'action','resource_id',context->>'resource_id','installation_id',context->>'installation_id','activation_revision',context->'activation_revision','release_commit',context->>'release_commit','receipt',result));
 end if;
 return result;
end;
$$;


ALTER FUNCTION production_control.canonical_director_financial_operation_v2(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: canonical_director_setup_operation_v2(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_director_setup_operation_v2(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
 family text:=input->>'family'; action text:=input->>'action';
 payload jsonb:=coalesce(input->'payload','{}'::jsonb);
 command jsonb; operation text; match_id_value text; current_read jsonb; control_matches jsonb;
 setup_receipt production_control.tournament_setup_operation_receipts_v1%rowtype;
 control_receipt scoring_authority.score_mutations%rowtype; expected_hash text;
begin
 if context->>'tournament_id' is distinct from '2026'
  or context->>'governance_tournament_id' is distinct from '2026'
  or context->>'actor_player_id' is null or context->>'actor_auth_user_id' is null
  or family not in('TOURNAMENT_SETUP','ROUND_PAIRINGS','MATCH_CONTROL')
  or jsonb_typeof(payload) is distinct from 'object' then
  raise exception using errcode='42501',message='ISOLATED_DIRECTOR_CONTEXT_REQUIRED';
 end if;
 command:=(payload-array['environment','project_ref','project_url','source_workbook_id','tournament_id',
  'authorization','actor_player_id','actor_auth_user_id','request_payload_hash','operation_request_id','mutation_key']) ||
  jsonb_build_object('contract_version','production-tournament-setup-v1','environment',coalesce(context->>'resource_class','ISOLATED'),
   'tournament_id',context->>'tournament_id','actor_player_id',context->>'actor_player_id',
   'actor_auth_user_id',context->>'actor_auth_user_id','operation_request_id',context->>'operation_request_id',
   'authorization',jsonb_build_object('tournament_id',context->>'tournament_id',
    'player_id',context->>'actor_player_id','auth_user_id',context->>'actor_auth_user_id','role','DIRECTOR'));
 if not mutation and input->>'mode' is distinct from 'status' then
  current_read:=production_control.canonical_tournament_setup_read_v1(command ||
   jsonb_build_object('operation','READ_PRODUCTION_TOURNAMENT_SETUP_V1'));
  if family='MATCH_CONTROL' then
   select coalesce(jsonb_agg(item.value || jsonb_build_object(
    'matchRevision',m.match_revision,'permissionRevision',m.permission_revision,
    'scorecardComplete',m.scorecard_complete,'unresolvedMutations',m.unresolved_mutations,
    'resultWinner',m.result_winner,'scoringLocked',m.scoring_locked,
    'scoringReady',coalesce((item.value->>'scoring_ready')::boolean,false),
    'permissionComplete',(select count(*) from scoring_authority.scoring_permissions p where p.match_id=m.match_id)=
      (select count(*) from scoring_authority.match_participants p where p.match_id=m.match_id)
      and exists(select 1 from scoring_authority.match_participants p where p.match_id=m.match_id),
    'accessState',case when not exists(select 1 from scoring_authority.scoring_permissions p where p.match_id=m.match_id and p.can_score and p.revoked_at is null) then 'REVOKED'
      when not exists(select 1 from scoring_authority.scoring_permissions p where p.match_id=m.match_id and (not p.can_score or p.revoked_at is not null or p.permission_revision<>m.permission_revision)) then 'ACTIVE' else 'MIXED' end)
    order by m.round_number,m.match_id),'[]') into control_matches
   from jsonb_array_elements(current_read#>'{data,matches}') item(value)
   join scoring_authority.matches m on m.match_id=item.value->>'matchId' and m.tournament_id=context->>'tournament_id';
   current_read:=jsonb_set(current_read,'{data,matches}',control_matches);
  end if;
  return current_read;
 end if;
 if family='MATCH_CONTROL' then
  operation:=case action when 'mark-live' then 'MARK_LIVE' when 'scoring-lock' then 'SCORING_LOCK'
   when 'scoring-unlock' then 'SCORING_UNLOCK' when 'access-activate' then 'ACCESS_ACTIVATE'
   when 'access-revoke' then 'ACCESS_REVOKE' end;
  match_id_value:=payload->>'match_id';
  if operation is null or coalesce(match_id_value,'')='' or
   coalesce(payload->>'expected_match_revision','')!~'^[0-9]+$' or
   coalesce(payload->>'expected_permission_revision','')!~'^[0-9]+$' then
   raise exception using errcode='22023',message='ISOLATED_DIRECTOR_CONTROL_INPUT_INVALID'; end if;
  command:=command || jsonb_build_object('operation',operation,'mutation_key',context->>'operation_request_id',
   'authorization',(command->'authorization') || jsonb_build_object('match_id',match_id_value,
    'permission_revision',(payload->>'expected_permission_revision')::bigint));
  if input->>'mode'='status' then
   expected_hash:=production_control.cutover_payload_hash(jsonb_build_object(
    'match_id',match_id_value,'operation',operation,'actor_id',context->>'actor_player_id'));
   select * into control_receipt from scoring_authority.score_mutations
    where match_id=match_id_value and mutation_key=context->>'operation_request_id';
   if not found then return jsonb_build_object('ok',true,'outcome','UNKNOWN','receipt',null,
    'code','ISOLATED_DIRECTOR_RECEIPT_NOT_FOUND'); end if;
   if control_receipt.payload_hash is distinct from expected_hash then
    raise exception 'IDEMPOTENCY_CONFLICT'; end if;
   return jsonb_build_object('ok',true,'outcome','COMMITTED','receipt',control_receipt.result);
  end if;
  return production_control.canonical_match_control_v1(command,input);
 end if;
 operation:=case action when 'update-tournament' then 'UPDATE_TOURNAMENT' when 'update-team' then 'UPDATE_TEAM'
  when 'assign-roster-team' then 'ASSIGN_ROSTER_TEAM' when 'update-round' then 'UPDATE_ROUND'
  when 'upsert-course' then 'UPSERT_COURSE' when 'upsert-match' then 'UPSERT_MATCH'
  when 'replace-pairings' then 'REPLACE_PAIRINGS' when 'prepare-scoring-context' then 'PREPARE_SCORING_CONTEXT'
  when 'replace-round-pairings' then 'REPLACE_ROUND_PAIRINGS' end;
 if operation is null or (family='ROUND_PAIRINGS') is distinct from (operation='REPLACE_ROUND_PAIRINGS')
  or (payload ? 'operation' and payload->>'operation' is distinct from operation) then
  raise exception using errcode='22023',message='ISOLATED_DIRECTOR_SETUP_ACTION_INVALID'; end if;
 command:=command||jsonb_build_object('operation',operation);
 expected_hash:=production_control.tournament_setup_hash_v1(command);
 command:=command||jsonb_build_object('request_payload_hash',expected_hash);
 if input->>'mode'='status' then
  select r.* into setup_receipt from production_control.tournament_setup_operation_receipts_v1 r
   where r.tournament_id=context->>'tournament_id' and r.action=operation
    and r.operation_request_id=(context->>'operation_request_id')::uuid;
  if not found then return jsonb_build_object('ok',true,'outcome','UNKNOWN','receipt',null,
   'code','ISOLATED_DIRECTOR_RECEIPT_NOT_FOUND'); end if;
  if setup_receipt.declared_request_payload_hash is distinct from expected_hash
   or setup_receipt.database_request_payload_hash is distinct from expected_hash then
   raise exception 'TOURNAMENT_SETUP_IDEMPOTENCY_CONFLICT'; end if;
  return jsonb_build_object('ok',true,'outcome','COMMITTED','receipt',setup_receipt.response);
 end if;
 return production_control.mutate_late_r3_dispatch_v1(command,family='ROUND_PAIRINGS');
end;
$_$;


ALTER FUNCTION production_control.canonical_director_setup_operation_v2(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: canonical_draft_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_draft_read_v1(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  resource production_control.resource_scope%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  scope_value text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'target_scope','YEARS')));
  selected_year integer;
  player_value text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'target_player_id','')));
  drafts_value jsonb;
begin
  if canonical_context is null then
  perform production_control.assert_production_service_role();
  select value.* into strict resource from production_control.resource_scope value
  where value.scope_key='BAGGER_INV_PRODUCTION';
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key());
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key='BAGGER_INV_PRODUCTION';
  if input->>'environment' is distinct from 'PRODUCTION'
     or input->>'project_ref' is distinct from resource.project_ref
     or input->>'project_url' is distinct from resource.project_url
     or input->>'source_workbook_id' is distinct from resource.google_workbook_id
     or input->>'contract_version' is distinct from 'draft-projection-v1'
     or input->'source_tabs' is distinct from
       '["Draft Settings","Draft Picks"]'::jsonb
     or scope_value not in ('CURRENT','YEAR','YEARS','PLAYER') then
    raise exception using errcode='42501',
      message='PRODUCTION_DRAFT_READ_SCOPE_REQUIRED';
  end if;
  else
    perform production_control.assert_certification_read_v1(canonical_context,input);
    select value.* into strict pointer from production_control.current_tournament_pointer_v1 value
     where value.scope_key=canonical_context->>'resource_id';
    if scope_value not in ('CURRENT','YEAR','YEARS','PLAYER') then
      raise exception using errcode='42501',message='CERTIFICATION_DRAFT_READ_SCOPE_REQUIRED';
    end if;
  end if;
  if scope_value='CURRENT' then
    if canonical_context is not null then
      if pointer.tournament_id<>'2026' then raise exception using errcode='55000',message='CERTIFICATION_CURRENT_READ_POINTER_NOT_2026'; end if;
    elsif pointer.tournament_id='2026' and pointer.tournament_year=2026 then
      perform production_control.assert_frozen_2026_current_read_v1();
    else
      perform production_control.assert_annual_current_read_v1(input);
    end if;
    selected_year := pointer.tournament_year;
  elsif scope_value='YEAR' then
    begin selected_year := (input->>'target_year')::integer;
    exception when others then
      raise exception using errcode='22023',message='DRAFT_YEAR_REQUIRED';
    end;
    if selected_year not between 2000 and 2200 then
      raise exception using errcode='22023',message='DRAFT_YEAR_REQUIRED';
    end if;
  elsif scope_value='PLAYER' and player_value !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$' then
    raise exception using errcode='22023',message='DRAFT_PLAYER_REQUIRED';
  end if;
  select coalesce(pg_catalog.jsonb_agg(
    production_control.draft_projection_row_v1(current_value.revision_id)
    order by current_value.tournament_year),'[]'::jsonb) into drafts_value
  from scoring_authority.draft_current_revisions current_value
  where current_value.tournament_year<=pointer.tournament_year
    and ((scope_value='YEARS')
      or (scope_value in ('CURRENT','YEAR')
        and current_value.tournament_year=selected_year)
      or (scope_value='PLAYER' and exists (
        select 1 from scoring_authority.draft_pick_facts pick
        where pick.revision_id=current_value.revision_id
          and pick.player_id=player_value and pick.pick_status='SELECTED'
      )));
  return pg_catalog.jsonb_build_object(
    'ok',true,
    'data',pg_catalog.jsonb_build_object(
      'contract_version','draft-projection-v1',
      'validation_status','VALID','drafts',drafts_value,
      'authoritative',true,'shadow_only',false,
      'google_foreground_requests',0,'fallback_used',false,
      'current_tournament_id',pointer.tournament_id,
      'current_tournament_year',pointer.tournament_year
    )
  );
end;
$_$;


ALTER FUNCTION production_control.canonical_draft_read_v1(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_drain_annual_scoring_transition_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_drain_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  existing jsonb;
  response_value jsonb;
begin
  perform production_control.assert_canonical_annual_transition_context_v2(input,canonical_context);
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'DRAIN', input, canonical_context
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'DRAIN', input, canonical_context
  );
  if existing is not null then return existing; end if;
  response_value := production_control.advance_annual_scoring_transition_v1(
    (input->>'transition_id')::uuid, input
  );
  perform production_control.store_canonical_annual_scoring_receipt_v2(
    'DRAIN', input, response_value, canonical_context
  );
  return response_value;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_DRAIN_REVISION_CONFLICT';
end;
$$;


ALTER FUNCTION production_control.canonical_drain_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_execution_activation_revision_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_execution_activation_revision_v1() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare resource production_control.canonical_resource_v1%rowtype; context jsonb; revision bigint;
begin
 select * into strict resource from production_control.canonical_resource_v1 where singleton;
 if resource.resource_class='PRODUCTION' then
  select activation_revision into strict revision from production_control.cutover_activation_state where scope_key='BAGGER_INV_PRODUCTION';
  return revision;
 end if;
 context:=production_control.current_certification_context_v1();
 if context->>'resource_id' is distinct from resource.resource_id then
  raise exception using errcode='42501',message='CERTIFICATION_DOMAIN_CONTEXT_REQUIRED'; end if;
 return (context->>'activation_revision')::bigint;
end;
$$;


ALTER FUNCTION production_control.canonical_execution_activation_revision_v1() OWNER TO postgres;

--
-- Name: canonical_execution_resource_id_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_execution_resource_id_v1() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare resource production_control.canonical_resource_v1%rowtype; context jsonb;
begin
 select * into strict resource from production_control.canonical_resource_v1 where singleton;
 if resource.resource_class='PRODUCTION' then return resource.resource_id; end if;
 context:=production_control.current_certification_context_v1();
 if context->>'resource_id' is distinct from resource.resource_id then
  raise exception using errcode='42501',message='CERTIFICATION_DOMAIN_CONTEXT_REQUIRED'; end if;
 return resource.resource_id;
end;
$$;


