--
-- Name: canonical_future_finalize_match_v1_resource(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_finalize_match_v1_resource(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target_tournament text;
  match_row scoring_authority.matches%rowtype;
  next_match_row scoring_authority.matches%rowtype;
  mutation_row scoring_authority.score_mutations%rowtype;
  target_match text := input->>'match_id';
  mutation_identity text := input->>'mutation_key';
  actor text := input#>>'{authorization,player_id}';
  actor_role text := pg_catalog.upper(coalesce(input#>>'{authorization,role}', 'PLAYER'));
  expected_match bigint := coalesce((input->>'expected_match_revision')::bigint, -1);
  supplied_permission bigint := coalesce((input#>>'{authorization,permission_revision}')::bigint, -1);
  next_revision bigint;
  next_permission_revision bigint;
  payload_hash_value text;
  result_value jsonb;
  before_permissions jsonb;
  after_permissions jsonb;
  progress jsonb;
  archive_result jsonb;
  transition_at timestamptz := pg_catalog.clock_timestamp();
begin
  target_tournament := production_control.assert_canonical_future_scoring_runtime_v1(input,resource_context);
  perform production_control.assert_canonical_future_scoring_actor_v1(input,target_tournament,false,resource_context);
  select * into match_row from scoring_authority.matches
  where match_id = target_match and tournament_id = target_tournament for update;
  if not found then return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FOUND'); end if;
  if input#>>'{authorization,match_id}' <> target_match or actor_role not in ('PLAYER', 'DIRECTOR') then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'UNAUTHORIZED');
  end if;
  payload_hash_value := production_control.cutover_payload_hash(pg_catalog.jsonb_build_object(
    'match_id', target_match, 'action', 'FINALIZE', 'actor_id', actor));
  select * into mutation_row from scoring_authority.score_mutations
  where match_id = target_match and mutation_key = mutation_identity;
  if found then
    if mutation_row.payload_hash = payload_hash_value then
      return mutation_row.result || pg_catalog.jsonb_build_object('idempotent', true);
    end if;
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT');
  end if;
  if supplied_permission <> match_row.permission_revision then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE',
      'current_permission_revision', match_row.permission_revision);
  end if;
  if actor_role = 'PLAYER' and not exists (
    select 1 from scoring_authority.scoring_permissions
    where match_id = target_match and player_id = actor and can_score
      and revoked_at is null and permission_revision = match_row.permission_revision
  ) then return pg_catalog.jsonb_build_object('ok', false, 'code', 'UNAUTHORIZED'); end if;
  if match_row.status = 'FINAL' then return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_FINAL'); end if;
  if match_row.scoring_locked then return pg_catalog.jsonb_build_object('ok', false, 'code', 'SCORING_LOCKED'); end if;
  if expected_match <> match_row.match_revision then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_REVISION_CONFLICT',
      'current_match_revision', match_row.match_revision);
  end if;
  if match_row.scored_holes <> 18 or not match_row.scorecard_complete then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'SCORECARD_INCOMPLETE',
      'scored_holes', match_row.scored_holes);
  end if;
  if match_row.unresolved_mutations > 0 then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'UNRESOLVED_MUTATIONS');
  end if;
  progress := scoring_authority.match_progress(target_match, match_row.format);
  if pg_catalog.btrim(coalesce(progress->>'result_winner', '')) = ''
     or progress->>'result_winner' <> match_row.result_winner
     or coalesce((progress->>'scorecard_complete')::boolean, false) is not true
     or progress->>'team_1_points' is null or progress->>'team_2_points' is null then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'RESULT_UNAVAILABLE');
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(permission)
    order by player_id), '[]'::jsonb) into before_permissions
  from scoring_authority.scoring_permissions permission where match_id = target_match;
  next_revision := match_row.match_revision + 1;
  next_permission_revision := match_row.permission_revision + 1;
  update scoring_authority.matches set status = 'FINAL', scoring_locked = true,
    match_revision = next_revision, permission_revision = next_permission_revision,
    finalized_at = transition_at, authority_updated_at = transition_at,
    updated_at = transition_at
  where match_id = target_match and tournament_id = target_tournament returning * into next_match_row;
  update scoring_authority.scoring_permissions set can_score = false,
    permission_revision = next_permission_revision, revoked_at = transition_at,
    updated_at = transition_at where match_id = target_match;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(permission)
    order by player_id), '[]'::jsonb) into after_permissions
  from scoring_authority.scoring_permissions permission where match_id = target_match;
  archive_result := scoring_authority.capture_finalized_scorecard_snapshot(target_match, actor);
  result_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'FINALIZED', 'match_id', target_match,
    'google_target_match_id', target_match, 'match_revision', next_revision,
    'permission_revision', next_permission_revision,
    'previous_permission_revision', match_row.permission_revision,
    'scoring_locked', true, 'access_active', false,
    'result_winner', match_row.result_winner, 'scorecard_complete', true,
    'scored_holes', 18, 'updated_at', transition_at, 'match', progress,
    'team_1_points', (progress->>'team_1_points')::numeric,
    'team_2_points', (progress->>'team_2_points')::numeric,
    'scorecard_archive', archive_result,
    'permission_transition', pg_catalog.jsonb_build_object(
      'before', before_permissions, 'after', after_permissions),
    'audit_created', true, 'google_outbox_created', false);
  insert into scoring_authority.score_mutations
    (match_id, mutation_key, mutation_type, payload_hash,
      previous_match_revision, next_match_revision, result, actor_id)
  values (target_match, mutation_identity, 'FINALIZE', payload_hash_value,
    match_row.match_revision, next_revision, result_value, actor);
  insert into scoring_authority.score_revision_history
    (match_id, mutation_key, action, previous_match_revision,
      next_match_revision, before_state, after_state, actor_id)
  values (target_match, mutation_identity, 'MATCH_FINALIZED', match_row.match_revision,
    next_revision,
    pg_catalog.jsonb_build_object('match', pg_catalog.to_jsonb(match_row), 'permissions', before_permissions),
    pg_catalog.jsonb_build_object('match', pg_catalog.to_jsonb(next_match_row), 'permissions', after_permissions), actor);
  insert into scoring_authority.audit_events
    (tournament_id, match_id, mutation_key, action, actor_id, metadata)
  values (target_tournament, target_match, mutation_identity, 'MATCH_FINALIZED', actor, result_value);
  -- Google runtime retired: external delivery is not canonical authority.
  return result_value;
end;

$$;


ALTER FUNCTION production_control.canonical_future_finalize_match_v1_resource(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_identity_for_auth_v1(uuid, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_identity_for_auth_v1(target_auth_user_id uuid, target_tournament_id text, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target_id text;
  target_player text;
  context_value jsonb;
begin
  target_id := production_control
    .assert_canonical_future_identity_runtime_v1(resource_context);
  if target_auth_user_id is null
     or nullif(pg_catalog.btrim(coalesce(target_tournament_id, '')), '')
       is distinct from target_id then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PRODUCTION_AUTH_SCOPE_INVALID'
    );
  end if;
  select eligibility.player_id into target_player
  from production_control.future_participant_identity_eligibility_v1(
    target_id
  ) eligibility
  where eligibility.auth_user_id = target_auth_user_id
    and eligibility.runtime_eligible;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACTIVE_USER_PLAYER_LINK_REQUIRED'
    );
  end if;
  context_value := public.read_participant_identity_context(
    target_id, target_player
  );
  if coalesce((context_value->>'ok')::boolean, false) then
    return pg_catalog.jsonb_set(
      context_value, '{data,authUserId}',
      pg_catalog.to_jsonb(target_auth_user_id), true
    );
  end if;
  return context_value;
end;

$$;


ALTER FUNCTION production_control.canonical_future_identity_for_auth_v1(target_auth_user_id uuid, target_tournament_id text, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_identity_for_player_v1(text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_identity_for_player_v1(target_tournament_id text, target_player_id text, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target_id text;
  target_user uuid;
begin
  target_id := production_control
    .assert_canonical_future_identity_runtime_v1(resource_context);
  if pg_catalog.btrim(coalesce(target_tournament_id, '')) <> target_id then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PRODUCTION_AUTH_SCOPE_INVALID'
    );
  end if;
  select eligibility.auth_user_id into target_user
  from production_control.future_participant_identity_eligibility_v1(
    target_id
  ) eligibility
  where eligibility.player_id = pg_catalog.btrim(target_player_id)
    and eligibility.runtime_eligible;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACTIVE_USER_PLAYER_LINK_REQUIRED'
    );
  end if;
  return production_control.canonical_future_identity_for_auth_v1(
    target_user, target_id, resource_context
  );
end;

$$;


ALTER FUNCTION production_control.canonical_future_identity_for_player_v1(target_tournament_id text, target_player_id text, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_mutate_match_control_v1_resource(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_mutate_match_control_v1_resource(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target_tournament text;
  match_row scoring_authority.matches%rowtype;
  next_match_row scoring_authority.matches%rowtype;
  mutation_row scoring_authority.score_mutations%rowtype;
  target_match text := input->>'match_id';
  operation text := pg_catalog.upper(coalesce(input->>'operation', ''));
  mutation_identity text := input->>'mutation_key';
  actor text := input#>>'{authorization,player_id}';
  expected_match bigint := coalesce((input->>'expected_match_revision')::bigint, -1);
  expected_permission bigint := coalesce((input#>>'{authorization,permission_revision}')::bigint, -1);
  next_match_revision bigint;
  next_permission_revision bigint;
  permission_changes boolean;
  target_locked boolean;
  target_access boolean;
  event_type text;
  payload_hash_value text;
  result_value jsonb;
  before_permissions jsonb;
  after_permissions jsonb;
  readiness_value jsonb;
  transition_at timestamptz := pg_catalog.clock_timestamp();
begin
  target_tournament := production_control.assert_canonical_future_scoring_runtime_v1(input,resource_context);
  perform production_control.assert_canonical_future_scoring_actor_v1(input,target_tournament,true,resource_context);
  if operation not in ('MARK_LIVE', 'SCORING_LOCK', 'SCORING_UNLOCK', 'ACCESS_ACTIVATE', 'ACCESS_REVOKE')
     or coalesce(target_match, '') = '' or coalesce(mutation_identity, '') = '' then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'INVALID_CONTROL_OPERATION');
  end if;
  if operation = 'MARK_LIVE' then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'production-access-governance-v1:' || target_tournament, 0));
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'production-tournament-setup-v1:' || target_tournament, 0));
  end if;
  select * into match_row from scoring_authority.matches
  where match_id = target_match and tournament_id = target_tournament for update;
  if not found then return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FOUND'); end if;
  if input#>>'{authorization,match_id}' <> target_match then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'DIRECTOR_REQUIRED');
  end if;
  payload_hash_value := production_control.cutover_payload_hash(pg_catalog.jsonb_build_object(
    'match_id', target_match, 'operation', operation, 'actor_id', actor));
  select * into mutation_row from scoring_authority.score_mutations
  where match_id = target_match and mutation_key = mutation_identity;
  if found then
    if mutation_row.payload_hash = payload_hash_value then
      return mutation_row.result || pg_catalog.jsonb_build_object('idempotent', true);
    end if;
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT');
  end if;
  if expected_match <> match_row.match_revision then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_REVISION_CONFLICT',
      'current_match_revision', match_row.match_revision);
  end if;
  if expected_permission <> match_row.permission_revision then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE',
      'current_permission_revision', match_row.permission_revision);
  end if;
  if match_row.status = 'FINAL' then return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_FINAL'); end if;
  if operation = 'MARK_LIVE' and match_row.status = 'LIVE' then
    return pg_catalog.jsonb_build_object('ok', true, 'code', 'NO_CHANGE',
      'semantic_noop', true, 'match_id', target_match,
      'match_revision', match_row.match_revision,
      'permission_revision', match_row.permission_revision,
      'status', match_row.status, 'scoring_locked', match_row.scoring_locked,
      'google_outbox_created', false);
  end if;
  if operation = 'MARK_LIVE' and match_row.status <> 'UPCOMING' then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_NOT_UPCOMING');
  end if;
  if operation = 'MARK_LIVE' then
    readiness_value := production_control.assert_future_production_match_scoring_ready_v1(
      target_match, target_tournament);
    if coalesce((readiness_value->>'ready')::boolean, false) is not true then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'PRODUCTION_MATCH_NOT_SCORING_READY',
        'match_id', target_match, 'match_revision', match_row.match_revision,
        'permission_revision', match_row.permission_revision,
        'status', match_row.status, 'scoring_locked', match_row.scoring_locked,
        'scoring_readiness_contract', 'production-match-scoring-readiness-v1',
        'reasons', coalesce(readiness_value->'reasons', '[]'::jsonb),
        'audit_created', false, 'google_outbox_created', false);
    end if;
  end if;
  if operation in ('SCORING_UNLOCK', 'ACCESS_ACTIVATE') and (
       (operation = 'ACCESS_ACTIVATE' and match_row.scoring_locked)
       or (operation = 'SCORING_UNLOCK' and not match_row.scoring_locked)
     ) then
    if operation = 'ACCESS_ACTIVATE' and match_row.scoring_locked then
      return pg_catalog.jsonb_build_object('ok', false, 'code', 'SCORING_LOCKED');
    end if;
    if not exists (select 1 from scoring_authority.scoring_permissions
      where match_id = target_match and (not can_score or revoked_at is not null
        or permission_revision <> match_row.permission_revision)) then
      return pg_catalog.jsonb_build_object('ok', true, 'code', 'NO_CHANGE',
        'semantic_noop', true, 'match_id', target_match,
        'match_revision', match_row.match_revision,
        'permission_revision', match_row.permission_revision,
        'scoring_locked', match_row.scoring_locked,
        'access_active', true, 'google_outbox_created', false);
    end if;
  end if;
  if operation = 'SCORING_LOCK' and match_row.scoring_locked and not exists (
    select 1 from scoring_authority.scoring_permissions
    where match_id = target_match and (can_score or revoked_at is null
      or permission_revision <> match_row.permission_revision)
  ) then
    return pg_catalog.jsonb_build_object('ok', true, 'code', 'NO_CHANGE',
      'semantic_noop', true, 'match_id', target_match,
      'match_revision', match_row.match_revision,
      'permission_revision', match_row.permission_revision,
      'scoring_locked', true, 'access_active', false,
      'google_outbox_created', false);
  end if;
  if operation = 'ACCESS_REVOKE' and not exists (
    select 1 from scoring_authority.scoring_permissions
    where match_id = target_match and (can_score or revoked_at is null
      or permission_revision <> match_row.permission_revision)
  ) then
    return pg_catalog.jsonb_build_object('ok', true, 'code', 'NO_CHANGE',
      'semantic_noop', true, 'match_id', target_match,
      'match_revision', match_row.match_revision,
      'permission_revision', match_row.permission_revision,
      'scoring_locked', match_row.scoring_locked, 'access_active', false,
      'google_outbox_created', false);
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(permission)
    order by permission.player_id), '[]'::jsonb) into before_permissions
  from scoring_authority.scoring_permissions permission where match_id = target_match;
  next_match_revision := match_row.match_revision + 1;
  permission_changes := operation <> 'MARK_LIVE';
  next_permission_revision := match_row.permission_revision + case when permission_changes then 1 else 0 end;
  target_locked := case operation when 'SCORING_LOCK' then true
    when 'SCORING_UNLOCK' then false else match_row.scoring_locked end;
  target_access := case operation when 'SCORING_LOCK' then false
    when 'SCORING_UNLOCK' then true when 'ACCESS_ACTIVATE' then true
    when 'ACCESS_REVOKE' then false else exists (select 1
      from scoring_authority.scoring_permissions where match_id = target_match
        and can_score and revoked_at is null) end;
  event_type := case operation when 'MARK_LIVE' then 'MATCH_MARKED_LIVE'
    when 'SCORING_LOCK' then 'SCORING_LOCKED'
    when 'SCORING_UNLOCK' then 'SCORING_UNLOCKED'
    when 'ACCESS_ACTIVATE' then 'SCORING_ACCESS_ACTIVATED'
    else 'SCORING_ACCESS_REVOKED' end;
  update scoring_authority.matches set
    status = case when operation = 'MARK_LIVE' then 'LIVE' else status end,
    scoring_locked = target_locked, match_revision = next_match_revision,
    permission_revision = next_permission_revision,
    authority_updated_at = transition_at, updated_at = transition_at
  where match_id = target_match and tournament_id = target_tournament returning * into next_match_row;
  if permission_changes then
    update scoring_authority.scoring_permissions set can_score = target_access,
      permission_revision = next_permission_revision,
      revoked_at = case when target_access then null else transition_at end,
      updated_at = transition_at where match_id = target_match;
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(permission)
    order by permission.player_id), '[]'::jsonb) into after_permissions
  from scoring_authority.scoring_permissions permission where match_id = target_match;
  result_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', operation, 'match_id', target_match,
    'google_target_match_id', target_match, 'match_revision', next_match_revision,
    'previous_permission_revision', match_row.permission_revision,
    'permission_revision', next_permission_revision, 'status', next_match_row.status,
    'scoring_locked', target_locked, 'access_active', target_access,
    'updated_at', transition_at,
    'permission_transition', pg_catalog.jsonb_build_object(
      'before', before_permissions, 'after', after_permissions),
    'audit_created', true, 'google_outbox_created', false);
  insert into scoring_authority.score_mutations (
    match_id, mutation_key, mutation_type, payload_hash,
    previous_match_revision, next_match_revision, result, actor_id
  ) values (target_match, mutation_identity, operation, payload_hash_value,
    match_row.match_revision, next_match_revision, result_value, actor);
  insert into scoring_authority.score_revision_history (
    match_id, mutation_key, action, previous_match_revision,
    next_match_revision, before_state, after_state, actor_id
  ) values (target_match, mutation_identity, event_type, match_row.match_revision,
    next_match_revision,
    pg_catalog.jsonb_build_object('match', pg_catalog.to_jsonb(match_row), 'permissions', before_permissions),
    pg_catalog.jsonb_build_object('match', pg_catalog.to_jsonb(next_match_row), 'permissions', after_permissions), actor);
  insert into scoring_authority.audit_events
    (tournament_id, match_id, mutation_key, action, actor_id, metadata)
  values (target_tournament, target_match, mutation_identity, event_type, actor, result_value);
  -- Google runtime retired: external delivery is not canonical authority.
  return result_value;
end;

$$;


ALTER FUNCTION production_control.canonical_future_mutate_match_control_v1_resource(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_read_scoring_authority_v1_resource(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_read_scoring_authority_v1_resource(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target_tournament text;
  target_match text := input->>'match_id';
  mode text := pg_catalog.upper(coalesce(input->>'mode', 'DIAGNOSTICS'));
  payload jsonb;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
begin
  target_tournament := production_control.assert_canonical_future_scoring_runtime_v1(input,resource_context);
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target_tournament and value.generation_status = 'ACTIVE';
  if mode = 'MATCH' then
    select pg_catalog.to_jsonb(match_value) into payload
    from scoring_authority.matches match_value
    where match_id = target_match and tournament_id = target_tournament;
  elsif mode = 'SCORECARD' then
    select pg_catalog.jsonb_build_object(
      'match', pg_catalog.to_jsonb(match_value),
      'holes', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(hole) order by hole_number)
        from scoring_authority.hole_scores hole where hole.match_id = match_value.match_id), '[]'::jsonb)
    ) into payload from scoring_authority.matches match_value
    where match_id = target_match and tournament_id = target_tournament;
  elsif mode = 'CURRENT_STATE' then
    select pg_catalog.jsonb_build_object(
      'matches', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value) order by round_number, match_id)
        from scoring_authority.matches value where tournament_id = target_tournament), '[]'::jsonb),
      'holes', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(hole) order by hole.match_id, hole.hole_number)
        from scoring_authority.hole_scores hole join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = target_tournament), '[]'::jsonb),
      'players', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value) order by player_id)
        from scoring_authority.tournament_players value where tournament_id = target_tournament), '[]'::jsonb),
      'snapshots', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value) order by match_id)
        from scoring_authority.scoring_snapshots value where tournament_id = target_tournament), '[]'::jsonb),
      'permissions', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(permission) order by match_id, player_id)
        from scoring_authority.scoring_permissions permission join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = target_tournament), '[]'::jsonb),
      'checkpoints', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(checkpoint) order by match_id)
        from scoring_authority.google_match_checkpoints checkpoint join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = target_tournament), '[]'::jsonb)
    ) into payload;
  elsif mode = 'DIAGNOSTICS' then
    select pg_catalog.jsonb_build_object(
      'matches', (select pg_catalog.count(*) from scoring_authority.matches where tournament_id = target_tournament),
      'holes', (select pg_catalog.count(*) from scoring_authority.hole_scores hole join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = target_tournament),
      'permissions', (select pg_catalog.count(*) from scoring_authority.scoring_permissions permission join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = target_tournament),
      'pending_outbox', 0 /* external Google delivery retired */,
      'authority', (select scoring_authority from scoring_authority.tournaments where tournament_id = target_tournament),
      'ingress', pg_catalog.jsonb_build_object(
        'tournament_id', target_tournament, 'state', generation.ingress_state,
        'authority', generation.authority,
        'active_epoch_id', generation.authority_generation_id,
        'unresolved_client_queues', 0, 'updated_at', generation.updated_at)
    ) into payload;
  else
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'INVALID_READ_MODE');
  end if;
  return pg_catalog.jsonb_build_object('ok', true, 'mode', mode, 'data', payload);
end;

$$;


ALTER FUNCTION production_control.canonical_future_read_scoring_authority_v1_resource(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_read_scoring_participant_context_v1_resource(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_read_scoring_participant_context_v1_resource(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target_tournament text;
  target_match text := input->>'match_id';
  actor text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'player_id', ''
  )));
  actor_auth_user uuid := nullif(input->>'auth_user_id', '')::uuid;
  participant_role text := pg_catalog.upper(coalesce(
    input->>'role', 'PLAYER'
  ));
  supplied_permission_revision bigint := coalesce(
    (input->>'permission_revision')::bigint, -1
  );
  match_row scoring_authority.matches%rowtype;
  permission_ok boolean := false;
begin
  target_tournament := production_control
    .assert_canonical_future_scoring_runtime_v1(input,resource_context);
  if production_control.assert_canonical_future_identity_runtime_v1(resource_context)
       <> target_tournament then
    raise exception using errcode = '55000',
      message = 'FUTURE_PARTICIPANT_IDENTITY_RUNTIME_REQUIRED';
  end if;
  select value.* into match_row
  from scoring_authority.matches value
  where value.match_id = target_match
    and value.tournament_id = target_tournament;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'MATCH_NOT_FOUND'
    );
  end if;
  if actor_auth_user is not null
     and participant_role in ('PLAYER', 'DIRECTOR')
     and supplied_permission_revision = match_row.permission_revision
     and exists (
       select 1
       from production_control.future_participant_identity_eligibility_v1(
         target_tournament
       ) eligibility
       where eligibility.auth_user_id = actor_auth_user
         and eligibility.player_id = actor
         and eligibility.runtime_eligible
     )
     and (participant_role <> 'DIRECTOR' or (
       exists (
         select 1
         from participant_identity.tournament_roles role_value
         where role_value.tournament_id = target_tournament
           and role_value.auth_user_id = actor_auth_user
           and role_value.role = 'DIRECTOR'
           and role_value.role_active
           and role_value.revoked_at is null
       )
       and exists (
         select 1
         from production_control.director_entitlements entitlement
         where entitlement.auth_user_id = actor_auth_user
           and entitlement.tournament_id = target_tournament
           and entitlement.player_id = actor
           and entitlement.role = 'DIRECTOR'
           and entitlement.status = 'ACTIVE'
           and entitlement.revoked_at is null
       )
     )) then
    if participant_role = 'PLAYER' then
      select exists (
        select 1
        from scoring_authority.scoring_permissions permission
        where permission.match_id = target_match
          and permission.player_id = actor
          and permission.can_score
          and permission.revoked_at is null
          and permission.permission_revision = match_row.permission_revision
      ) into permission_ok;
    elsif participant_role = 'DIRECTOR' then
      permission_ok := true;
    end if;
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'data', pg_catalog.jsonb_build_object(
      'match', pg_catalog.to_jsonb(match_row),
      'holes', coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(hole) order by hole.hole_number
        )
        from scoring_authority.hole_scores hole
        where hole.match_id = target_match
      ), '[]'::jsonb),
      'authorization', pg_catalog.jsonb_build_object(
        'verified', permission_ok,
        'writable', permission_ok and match_row.status <> 'FINAL'
          and not match_row.scoring_locked,
        'permission_revision', match_row.permission_revision
      )
    )
  );
end;

$$;


ALTER FUNCTION production_control.canonical_future_read_scoring_participant_context_v1_resource(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_reopen_match_v1_resource(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_reopen_match_v1_resource(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target_tournament text;
  match_row scoring_authority.matches%rowtype;
  next_match_row scoring_authority.matches%rowtype;
  mutation_row scoring_authority.score_mutations%rowtype;
  target_match text := input->>'match_id';
  mutation_identity text := input->>'mutation_key';
  actor text := input#>>'{authorization,player_id}';
  expected_match bigint := coalesce((input->>'expected_match_revision')::bigint, -1);
  supplied_permission bigint := coalesce((input#>>'{authorization,permission_revision}')::bigint, -1);
  next_revision bigint;
  next_permission_revision bigint;
  payload_hash_value text;
  result_value jsonb;
  before_permissions jsonb;
  after_permissions jsonb;
  archive_result jsonb;
  transition_at timestamptz := pg_catalog.clock_timestamp();
begin
  target_tournament := production_control.assert_canonical_future_scoring_runtime_v1(input,resource_context);
  perform production_control.assert_canonical_future_scoring_actor_v1(input,target_tournament,true,resource_context);
  select * into match_row from scoring_authority.matches
  where match_id = target_match and tournament_id = target_tournament for update;
  if not found then return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FOUND'); end if;
  if input#>>'{authorization,match_id}' <> target_match then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'DIRECTOR_REQUIRED');
  end if;
  payload_hash_value := production_control.cutover_payload_hash(pg_catalog.jsonb_build_object(
    'match_id', target_match, 'action', 'REOPEN', 'actor_id', actor));
  select * into mutation_row from scoring_authority.score_mutations
  where match_id = target_match and mutation_key = mutation_identity;
  if found then
    if mutation_row.payload_hash = payload_hash_value then
      return mutation_row.result || pg_catalog.jsonb_build_object('idempotent', true);
    end if;
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT');
  end if;
  if supplied_permission <> match_row.permission_revision then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE',
      'current_permission_revision', match_row.permission_revision);
  end if;
  if match_row.status <> 'FINAL' then return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FINAL'); end if;
  if expected_match <> match_row.match_revision then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_REVISION_CONFLICT',
      'current_match_revision', match_row.match_revision);
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(permission)
    order by player_id), '[]'::jsonb) into before_permissions
  from scoring_authority.scoring_permissions permission where match_id = target_match;
  next_revision := match_row.match_revision + 1;
  next_permission_revision := match_row.permission_revision + 1;
  update scoring_authority.matches set status = 'LIVE', scoring_locked = false,
    match_revision = next_revision, permission_revision = next_permission_revision,
    finalized_at = null, authority_updated_at = transition_at, updated_at = transition_at
  where match_id = target_match and tournament_id = target_tournament returning * into next_match_row;
  update scoring_authority.scoring_permissions set can_score = true,
    permission_revision = next_permission_revision, revoked_at = null,
    updated_at = transition_at where match_id = target_match;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(permission)
    order by player_id), '[]'::jsonb) into after_permissions
  from scoring_authority.scoring_permissions permission where match_id = target_match;
  archive_result := scoring_authority.invalidate_finalized_scorecard_snapshot(target_match, next_revision, actor);
  result_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'REOPENED', 'match_id', target_match,
    'google_target_match_id', target_match, 'match_revision', next_revision,
    'permission_revision', next_permission_revision,
    'previous_permission_revision', match_row.permission_revision,
    'scoring_locked', false, 'access_active', true,
    'scorecard_complete', match_row.scorecard_complete, 'updated_at', transition_at,
    'official_points_active', false, 'scorecard_archive', archive_result,
    'permission_transition', pg_catalog.jsonb_build_object(
      'before', before_permissions, 'after', after_permissions),
    'audit_created', true, 'google_outbox_created', false);
  insert into scoring_authority.score_mutations
    (match_id, mutation_key, mutation_type, payload_hash,
      previous_match_revision, next_match_revision, result, actor_id)
  values (target_match, mutation_identity, 'REOPEN', payload_hash_value,
    match_row.match_revision, next_revision, result_value, actor);
  insert into scoring_authority.score_revision_history
    (match_id, mutation_key, action, previous_match_revision,
      next_match_revision, before_state, after_state, actor_id)
  values (target_match, mutation_identity, 'MATCH_REOPENED', match_row.match_revision,
    next_revision,
    pg_catalog.jsonb_build_object('match', pg_catalog.to_jsonb(match_row), 'permissions', before_permissions),
    pg_catalog.jsonb_build_object('match', pg_catalog.to_jsonb(next_match_row), 'permissions', after_permissions), actor);
  insert into scoring_authority.audit_events
    (tournament_id, match_id, mutation_key, action, actor_id, metadata)
  values (target_tournament, target_match, mutation_identity, 'MATCH_REOPENED', actor, result_value);
  -- Google runtime retired: external delivery is not canonical authority.
  return result_value;
end;

$$;


ALTER FUNCTION production_control.canonical_future_reopen_match_v1_resource(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_submit_hole_score_v1_resource(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_submit_hole_score_v1_resource(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

declare
  target_tournament text;
  match_row scoring_authority.matches%rowtype;
  hole_row scoring_authority.hole_scores%rowtype;
  mutation_row scoring_authority.score_mutations%rowtype;
  permission_row scoring_authority.scoring_permissions%rowtype;
  target_match text := input->>'match_id';
  target_hole integer := nullif(input->>'hole_number', '')::integer;
  mutation_identity text := input->>'mutation_key';
  actor text := input#>>'{authorization,player_id}';
  actor_role text := pg_catalog.upper(coalesce(input#>>'{authorization,role}', 'PLAYER'));
  team_1_gross jsonb := input->'team_1_gross_scores';
  team_2_gross jsonb := input->'team_2_gross_scores';
  expected_match bigint := coalesce(nullif(input->>'expected_match_revision', '')::bigint, -1);
  expected_hole bigint := coalesce(nullif(input->>'expected_hole_revision', '')::bigint, -1);
  expected_count integer;
  current_hole_revision bigint := 0;
  hole_exists boolean := false;
  next_hole_revision bigint;
  next_match_revision bigint;
  stroke_index_value integer;
  team_1_strokes jsonb;
  team_2_strokes jsonb;
  team_1_net integer;
  team_2_net integer;
  winner text;
  progress jsonb;
  before_state jsonb;
  payload_hash_value text;
  result_value jsonb;
  transition_at timestamptz := pg_catalog.clock_timestamp();
begin
  target_tournament := production_control.assert_canonical_future_scoring_runtime_v1(input,resource_context);
  perform production_control.assert_canonical_future_scoring_actor_v1(input,target_tournament,false,resource_context);
  if coalesce(target_match, '') = '' or coalesce(mutation_identity, '') = '' then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'INVALID_REQUEST');
  end if;
  select * into match_row from scoring_authority.matches
  where match_id = target_match and tournament_id = target_tournament for update;
  if not found then return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FOUND'); end if;
  if input#>>'{authorization,match_id}' <> target_match then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'UNAUTHORIZED');
  end if;
  if actor_role = 'PLAYER' then
    select * into permission_row from scoring_authority.scoring_permissions
    where match_id = target_match and player_id = actor;
    if not found or not permission_row.can_score or permission_row.revoked_at is not null then
      return pg_catalog.jsonb_build_object('ok', false, 'code', 'UNAUTHORIZED');
    end if;
    if coalesce((input#>>'{authorization,permission_revision}')::bigint, -1) <> permission_row.permission_revision
       or permission_row.permission_revision <> match_row.permission_revision then
      return pg_catalog.jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE',
        'current_permission_revision', match_row.permission_revision);
    end if;
  elsif actor_role = 'DIRECTOR' then
    if coalesce((input#>>'{authorization,permission_revision}')::bigint, -1) <> match_row.permission_revision then
      return pg_catalog.jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE',
        'current_permission_revision', match_row.permission_revision);
    end if;
  else return pg_catalog.jsonb_build_object('ok', false, 'code', 'UNAUTHORIZED');
  end if;
  payload_hash_value := production_control.cutover_payload_hash(pg_catalog.jsonb_build_object(
    'match_id', target_match, 'hole_number', target_hole,
    'team_1_gross_scores', team_1_gross, 'team_2_gross_scores', team_2_gross,
    'actor_id', actor));
  select * into mutation_row from scoring_authority.score_mutations
  where match_id = target_match and mutation_key = mutation_identity;
  if found then
    if mutation_row.payload_hash = payload_hash_value then
      return mutation_row.result || pg_catalog.jsonb_build_object('idempotent', true);
    end if;
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT');
  end if;
  if match_row.scoring_locked then return pg_catalog.jsonb_build_object('ok', false, 'code', 'SCORING_LOCKED'); end if;
  if match_row.status = 'FINAL' then return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_FINAL'); end if;
  if target_hole not between 1 and 18 then return pg_catalog.jsonb_build_object('ok', false, 'code', 'INVALID_HOLE'); end if;
  if expected_match <> match_row.match_revision then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_REVISION_CONFLICT',
      'current_match_revision', match_row.match_revision);
  end if;
  select * into hole_row from scoring_authority.hole_scores
  where match_id = target_match and hole_number = target_hole;
  hole_exists := found;
  if hole_exists then current_hole_revision := hole_row.hole_revision; end if;
  if expected_hole <> current_hole_revision then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'HOLE_REVISION_CONFLICT',
      'current_hole_revision', current_hole_revision);
  end if;
  expected_count := case when match_row.format = 'BB' then 2 else 1 end;
  if not scoring_authority.valid_gross_scores(team_1_gross, expected_count)
     or not scoring_authority.valid_gross_scores(team_2_gross, expected_count) then
    return pg_catalog.jsonb_build_object('ok', false, 'code', 'INVALID_GROSS_SCORES');
  end if;
  if hole_exists and hole_row.team_1_gross_scores = team_1_gross
     and hole_row.team_2_gross_scores = team_2_gross then
    progress := scoring_authority.match_progress(target_match, match_row.format);
    return pg_catalog.jsonb_build_object('ok', true, 'code', 'NO_CHANGE',
      'semantic_noop', true, 'idempotent', true, 'match_id', target_match,
      'hole_number', target_hole, 'hole_revision', hole_row.hole_revision,
      'match_revision', match_row.match_revision, 'updated_at', hole_row.updated_at,
      'match', progress, 'audit_created', false, 'google_outbox_created', false);
  end if;
  select stroke_index into stroke_index_value from scoring_authority.match_holes
  where match_id = target_match and hole_number = target_hole;
  if stroke_index_value is null then return pg_catalog.jsonb_build_object('ok', false, 'code', 'INVALID_SCORING_SNAPSHOT'); end if;
  if match_row.format = 'SC' then
    select pg_catalog.jsonb_build_array(scoring_authority.strokes_on_hole((snapshot.team_configuration->>'team_1_strokes')::integer, stroke_index_value)),
      pg_catalog.jsonb_build_array(scoring_authority.strokes_on_hole((snapshot.team_configuration->>'team_2_strokes')::integer, stroke_index_value))
    into team_1_strokes, team_2_strokes from scoring_authority.scoring_snapshots snapshot
    where snapshot.snapshot_id = match_row.scoring_snapshot_id and snapshot.tournament_id = target_tournament;
  else
    select pg_catalog.jsonb_agg(scoring_authority.strokes_on_hole(participant.final_strokes, stroke_index_value) order by participant.player_slot)
    into team_1_strokes from scoring_authority.match_participants participant
    where match_id = target_match and team_side = 1;
    select pg_catalog.jsonb_agg(scoring_authority.strokes_on_hole(participant.final_strokes, stroke_index_value) order by participant.player_slot)
    into team_2_strokes from scoring_authority.match_participants participant
    where match_id = target_match and team_side = 2;
  end if;
  if match_row.format = 'BB' then
    select pg_catalog.min(gross::integer - stroke::integer) into team_1_net
    from pg_catalog.jsonb_array_elements_text(team_1_gross) with ordinality g(gross, n)
    join pg_catalog.jsonb_array_elements_text(team_1_strokes) with ordinality s(stroke, n2) on n = n2;
    select pg_catalog.min(gross::integer - stroke::integer) into team_2_net
    from pg_catalog.jsonb_array_elements_text(team_2_gross) with ordinality g(gross, n)
    join pg_catalog.jsonb_array_elements_text(team_2_strokes) with ordinality s(stroke, n2) on n = n2;
  else
    team_1_net := (team_1_gross->>0)::integer - (team_1_strokes->>0)::integer;
    team_2_net := (team_2_gross->>0)::integer - (team_2_strokes->>0)::integer;
  end if;
  winner := case when team_1_net = team_2_net then 'Halved'
    when team_1_net < team_2_net then 'Team 1' else 'Team 2' end;
  before_state := case when current_hole_revision = 0 then '{}'::jsonb else pg_catalog.to_jsonb(hole_row) end;
  next_hole_revision := current_hole_revision + 1;
  next_match_revision := match_row.match_revision + 1;
  insert into scoring_authority.hole_scores (
    match_id, hole_number, hole_revision, team_1_gross_scores, team_2_gross_scores,
    team_1_strokes, team_2_strokes, team_1_net_score, team_2_net_score,
    hole_winner, mutation_key, actor_id
  ) values (
    target_match, target_hole, next_hole_revision, team_1_gross, team_2_gross,
    team_1_strokes, team_2_strokes, team_1_net, team_2_net, winner, mutation_identity, actor
  ) on conflict (match_id, hole_number) do update set
    hole_revision = excluded.hole_revision,
    team_1_gross_scores = excluded.team_1_gross_scores,
    team_2_gross_scores = excluded.team_2_gross_scores,
    team_1_strokes = excluded.team_1_strokes,
    team_2_strokes = excluded.team_2_strokes,
    team_1_net_score = excluded.team_1_net_score,
    team_2_net_score = excluded.team_2_net_score,
    hole_winner = excluded.hole_winner, mutation_key = excluded.mutation_key,
    actor_id = excluded.actor_id, updated_at = transition_at;
  progress := scoring_authority.match_progress(target_match, match_row.format);
  update scoring_authority.matches set
    match_revision = next_match_revision,
    scored_holes = (progress->>'scored_holes')::integer,
    current_hole = (progress->>'current_hole')::integer,
    holes_remaining = (progress->>'holes_remaining')::integer,
    team_1_holes_won = (progress->>'team_1_holes_won')::integer,
    team_2_holes_won = (progress->>'team_2_holes_won')::integer,
    running_result = progress->>'running_result', result_winner = progress->>'result_winner',
    clinched = (progress->>'clinched')::boolean,
    scorecard_complete = (progress->>'scorecard_complete')::boolean,
    authority_updated_at = transition_at, updated_at = transition_at
  where match_id = target_match and tournament_id = target_tournament;
  result_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'ACCEPTED', 'match_id', target_match,
    'google_target_match_id', target_match, 'hole_number', target_hole,
    'hole_revision', next_hole_revision, 'match_revision', next_match_revision,
    'permission_revision', match_row.permission_revision, 'updated_at', transition_at,
    'gross', pg_catalog.jsonb_build_object('team_1', team_1_gross, 'team_2', team_2_gross),
    'strokes', pg_catalog.jsonb_build_object('team_1', team_1_strokes, 'team_2', team_2_strokes),
    'net', pg_catalog.jsonb_build_object('team_1', team_1_net, 'team_2', team_2_net),
    'hole_winner', winner, 'match', progress,
    'audit_created', true, 'google_outbox_created', false);
  insert into scoring_authority.score_mutations (
    match_id, mutation_key, mutation_type, hole_number, payload_hash,
    previous_match_revision, next_match_revision, previous_hole_revision,
    next_hole_revision, result, actor_id, originating_auth_user_id
  ) values (target_match, mutation_identity, 'HOLE_SCORE', target_hole, payload_hash_value,
    match_row.match_revision, next_match_revision, current_hole_revision,
    next_hole_revision, result_value, actor, (input#>>'{authorization,auth_user_id}')::uuid);
  insert into scoring_authority.score_revision_history (
    match_id, hole_number, mutation_key, action, previous_match_revision,
    next_match_revision, previous_hole_revision, next_hole_revision,
    before_state, after_state, actor_id
  ) values (target_match, target_hole, mutation_identity, 'HOLE_SCORE_UPSERTED',
    match_row.match_revision, next_match_revision, current_hole_revision,
    next_hole_revision, before_state, result_value, actor);
  insert into scoring_authority.audit_events
    (tournament_id, match_id, mutation_key, action, actor_id, metadata)
  values (target_tournament, target_match, mutation_identity, 'HOLE_SCORE_UPSERTED', actor, result_value);
  -- Google runtime retired: external delivery is not canonical authority.
  return result_value;
end;

$$;


ALTER FUNCTION production_control.canonical_future_submit_hole_score_v1_resource(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_write_competition_derived_snapshot_v1_resource(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_write_competition_derived_snapshot_v1_resource(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  generation_id uuid;
  token uuid;
  worker text := pg_catalog.left(pg_catalog.btrim(coalesce(
    input->>'worker_id', ''
  )), 160);
  target_round integer := coalesce((input->>'round_number')::integer, 0);
  target_engine text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'engine_key', ''
  )));
  target_engine_version text := pg_catalog.btrim(coalesce(
    input->>'engine_version', ''
  ));
  target_configuration text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'configuration_fingerprint', ''
  )));
  target_source text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'source_fingerprint', ''
  )));
  target_payload_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'payload_hash', ''
  )));
  target_payload jsonb := coalesce(input->'result_payload', 'null'::jsonb);
  target_actor text := pg_catalog.btrim(coalesce(input->>'calculated_by', ''));
  target_calculated_at timestamptz := coalesce(
    (input->>'calculated_at')::timestamptz, pg_catalog.clock_timestamp()
  );
  target_started_at timestamptz := coalesce(
    (input->>'started_at')::timestamptz, target_calculated_at
  );
  target_claim_started_at timestamptz :=
    (input->>'claim_started_at')::timestamptz;
  target_duration numeric := greatest(
    0, coalesce((input->>'duration_ms')::numeric, 0)
  );
  snapshot_id uuid;
  run_id uuid;
  logical_replay boolean := false;
begin
  target := production_control.assert_canonical_future_worker_runtime_v1(input,resource_context);
  generation_id := (input->>'expected_runtime_generation_id')::uuid;
  token := nullif(input->>'claim_token', '')::uuid;
  if token is null or worker = '' or target_round <> 0
     or target_actor = '' or target_engine_version = ''
     or target_engine not in ('TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES')
     or target_configuration !~ '^[0-9a-f]{64}$'
     or target_source !~ '^[0-9a-f]{64}$'
     or target_payload_hash !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(target_payload) <> 'object'
     or target_claim_started_at is null or not exists (
    select 1 from scoring_authority.competition_recalculation_jobs value
    where value.tournament_id = target and value.round_number = target_round
      and value.engine_key = target_engine
      and value.runtime_generation_id = generation_id
      and value.status = 'RUNNING' and value.claim_token = token
      and value.claimed_by = worker
      and value.lease_expires_at >= pg_catalog.clock_timestamp()
      and value.started_at = target_claim_started_at
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'STALE_DERIVED_JOB', 'superseded', true
    );
  end if;

  select value.id into snapshot_id
  from scoring_authority.competition_derived_snapshots value
  where value.tournament_id = target and value.round_number = target_round
    and value.engine_key = target_engine
    and value.engine_version = target_engine_version
    and value.configuration_fingerprint = target_configuration
    and value.source_fingerprint = target_source
    and value.payload_hash = target_payload_hash
  limit 1;
  logical_replay := snapshot_id is not null;
  update scoring_authority.competition_derived_snapshots value set
    is_current = false
  where value.tournament_id = target and value.round_number = target_round
    and value.engine_key = target_engine and value.is_current
    and value.id is distinct from snapshot_id;
  if snapshot_id is null then
    insert into scoring_authority.competition_derived_snapshots (
      tournament_id, round_number, engine_key, engine_version,
      configuration_fingerprint, source_fingerprint, result_state,
      result_payload, payload_hash, is_current, calculated_at
    ) values (
      target, target_round, target_engine, target_engine_version,
      target_configuration, target_source, 'PROVISIONAL', target_payload,
      target_payload_hash, true, target_calculated_at
    ) returning id into snapshot_id;
  else
    update scoring_authority.competition_derived_snapshots value set
      is_current = true, result_payload = target_payload,
      calculated_at = target_calculated_at
    where value.id = snapshot_id;
  end if;
  insert into scoring_authority.competition_derived_runs (
    tournament_id, round_number, engine_key, engine_version,
    configuration_fingerprint, source_fingerprint, payload_hash, status,
    calculated_by, started_at, completed_at, duration_ms
  ) values (
    target, target_round, target_engine, target_engine_version,
    target_configuration, target_source, target_payload_hash, 'SUCCEEDED',
    target_actor, target_started_at, target_calculated_at, target_duration
  ) on conflict (
    tournament_id, round_number, engine_key, engine_version,
    configuration_fingerprint, source_fingerprint, payload_hash, status
  ) do update set
    completed_at = excluded.completed_at,
    duration_ms = excluded.duration_ms,
    calculated_by = excluded.calculated_by
  returning id into run_id;
  update scoring_authority.competition_recalculation_jobs value set
    status = 'SUCCEEDED', requested_source_revision =
      pg_catalog.jsonb_build_object(
        'sourceFingerprint', target_source,
        'configurationFingerprint', target_configuration,
        'payloadHash', target_payload_hash
      ),
    completed_at = pg_catalog.clock_timestamp(),
    last_error_code = null, last_error_safe = null,
    claim_token = null, claimed_by = null, lease_expires_at = null,
    updated_at = pg_catalog.clock_timestamp()
  where value.tournament_id = target and value.round_number = target_round
    and value.engine_key = target_engine
    and value.runtime_generation_id = generation_id
    and value.status = 'RUNNING' and value.claim_token = token
    and value.claimed_by = worker and value.started_at = target_claim_started_at;
  if not found then
    raise exception using errcode = '40001', message = 'STALE_DERIVED_JOB';
  end if;
  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    target, target_engine || '_DERIVED_STATE_CALCULATED', target_actor,
    pg_catalog.jsonb_build_object(
      'snapshotId', snapshot_id, 'runId', run_id,
      'runtimeGenerationId', generation_id,
      'sourceFingerprint', target_source,
      'payloadHash', target_payload_hash,
      'engineVersion', target_engine_version,
      'logicalReplay', logical_replay,
      'claimStartedAt', target_claim_started_at
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'snapshot_id', snapshot_id,
    'run_id', run_id, 'logical_replay', logical_replay,
    'runtime_generation_id', generation_id
  );
end;

$_$;


ALTER FUNCTION production_control.canonical_future_write_competition_derived_snapshot_v1_resource(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_future_write_intelligence_derived_bundle_v1_resource(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_future_write_intelligence_derived_bundle_v1_resource(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  generation_id uuid;
  token uuid;
  worker text := pg_catalog.left(pg_catalog.btrim(coalesce(
    input->>'worker_id', ''
  )), 160);
  engine jsonb;
  key_value text;
  target_source text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'source_fingerprint', ''
  )));
  target_actor text := pg_catalog.left(pg_catalog.btrim(coalesce(
    input->>'calculated_by', ''
  )), 180);
  target_duration numeric := greatest(
    0, coalesce((input->>'duration_ms')::numeric, 0)
  );
  target_engine_version text;
  target_payload jsonb;
  target_payload_hash text;
  target_claim timestamptz;
  target_configuration_fingerprint text;
  snapshot_id uuid;
  written jsonb := '[]'::jsonb;
begin
  target := production_control.assert_canonical_future_worker_runtime_v1(input,resource_context);
  generation_id := (input->>'expected_runtime_generation_id')::uuid;
  token := nullif(input->>'claim_token', '')::uuid;
  if token is null or worker = '' or target_actor = ''
     or target_source !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(input->'engines') <> 'array' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_INTELLIGENCE_BUNDLE_REQUIRED'
    );
  end if;
  for engine in select value
    from pg_catalog.jsonb_array_elements(input->'engines') value
  loop
    key_value := pg_catalog.upper(pg_catalog.btrim(engine->>'key'));
    target_engine_version := pg_catalog.btrim(coalesce(
      engine->>'version', ''
    ));
    target_payload := coalesce(engine->'result', 'null'::jsonb);
    target_payload_hash := pg_catalog.lower(pg_catalog.btrim(coalesce(
      engine->>'payload_hash', ''
    )));
    begin
      target_claim := (engine->>'claim_started_at')::timestamptz;
    exception when others then
      target_claim := null;
    end;
    if key_value not in (
      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
      'TOURNAMENT_FINAL_RECAP'
    ) or target_engine_version = ''
      or pg_catalog.jsonb_typeof(target_payload) <> 'object'
      or target_payload_hash !~ '^[0-9a-f]{64}$'
      or target_claim is null then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'INVALID_INTELLIGENCE_ENGINE_PAYLOAD'
      );
    end if;
    if key_value = 'TOURNAMENT_FINAL_RECAP'
       and coalesce((input#>>'{final_gate,eligible}')::boolean, false)
         is not true then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'FINAL_RECAP_GATE_REQUIRED'
      );
    end if;
    if not exists (
      select 1 from scoring_authority.competition_recalculation_jobs value
      where value.tournament_id = target and value.round_number = 0
        and value.engine_key = key_value
        and value.runtime_generation_id = generation_id
        and value.status = 'RUNNING' and value.claim_token = token
        and value.claimed_by = worker
        and value.lease_expires_at >= pg_catalog.clock_timestamp()
        and value.started_at = target_claim
    ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'STALE_INTELLIGENCE_WORKER',
        'superseded', true, 'engineKey', key_value
      );
    end if;
    target_configuration_fingerprint := pg_catalog.encode(extensions.digest(
      target_engine_version || ':canonical-supabase-input-v1', 'sha256'
    ), 'hex');
    select value.id into snapshot_id
    from scoring_authority.competition_derived_snapshots value
    where value.tournament_id = target and value.round_number = 0
      and value.engine_key = key_value
      and value.engine_version = target_engine_version
      and value.source_fingerprint = target_source
      and value.payload_hash = target_payload_hash
    limit 1;
    update scoring_authority.competition_derived_snapshots value set
      is_current = false
    where value.tournament_id = target and value.round_number = 0
      and value.engine_key = key_value and value.is_current
      and value.id is distinct from snapshot_id;
    if snapshot_id is null then
      insert into scoring_authority.competition_derived_snapshots (
        tournament_id, round_number, engine_key, engine_version,
        configuration_fingerprint, source_fingerprint, result_state,
        result_payload, payload_hash, is_current, calculated_at
      ) values (
        target, 0, key_value, target_engine_version,
        target_configuration_fingerprint, target_source,
        case when key_value = 'TOURNAMENT_FINAL_RECAP'
          then 'OFFICIAL' else 'PROVISIONAL' end,
        target_payload, target_payload_hash, true,
        pg_catalog.clock_timestamp()
      ) returning id into snapshot_id;
    else
      update scoring_authority.competition_derived_snapshots value set
        is_current = true, result_payload = target_payload,
        calculated_at = pg_catalog.clock_timestamp()
      where value.id = snapshot_id;
    end if;
    insert into scoring_authority.competition_derived_runs (
      tournament_id, round_number, engine_key, engine_version,
      configuration_fingerprint, source_fingerprint, payload_hash, status,
      calculated_by, started_at, completed_at, duration_ms
    ) values (
      target, 0, key_value, target_engine_version,
      target_configuration_fingerprint, target_source, target_payload_hash,
      'SUCCEEDED', target_actor, target_claim,
      pg_catalog.clock_timestamp(), target_duration
    ) on conflict (
      tournament_id, round_number, engine_key, engine_version,
      configuration_fingerprint, source_fingerprint, payload_hash, status
    ) do update set
      completed_at = pg_catalog.clock_timestamp(),
      duration_ms = excluded.duration_ms,
      calculated_by = excluded.calculated_by;
    update scoring_authority.competition_recalculation_jobs value set
      status = 'SUCCEEDED',
      requested_source_revision = pg_catalog.jsonb_build_object(
        'sourceFingerprint', target_source,
        'payloadHash', target_payload_hash
      ), completed_at = pg_catalog.clock_timestamp(),
      last_error_code = null, last_error_safe = null,
      claim_token = null, claimed_by = null, lease_expires_at = null,
      updated_at = pg_catalog.clock_timestamp()
    where value.tournament_id = target and value.round_number = 0
      and value.engine_key = key_value
      and value.runtime_generation_id = generation_id
      and value.status = 'RUNNING' and value.claim_token = token
      and value.claimed_by = worker and value.started_at = target_claim;
    if not found then
      raise exception using errcode = '40001',
        message = 'STALE_INTELLIGENCE_WORKER';
    end if;
    written := written || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'engineKey', key_value, 'snapshotId', snapshot_id
      )
    );
  end loop;
  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    target, 'INTELLIGENCE_DERIVED_BUNDLE_CALCULATED', target_actor,
    pg_catalog.jsonb_build_object(
      'runtimeGenerationId', generation_id,
      'sourceFingerprint', target_source,
      'engines', written, 'finalGate', input->'final_gate'
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'written', written, 'final_gate', input->'final_gate',
    'runtime_generation_id', generation_id
  );
end;

$_$;


ALTER FUNCTION production_control.canonical_future_write_intelligence_derived_bundle_v1_resource(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_guide_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_guide_read_v1(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  result_value jsonb;
  tournament_value jsonb;
  courses_value jsonb;
begin
  -- Preserve the annual pointer and exact release/resource/service checks.
  if canonical_context is null then perform production_control.assert_frozen_2026_current_read_v1();
  elsif canonical_context->>'current_tournament_id'<>'2026' then raise exception using errcode='55000',message='CERTIFICATION_CURRENT_READ_POINTER_NOT_2026'; end if;
  result_value := production_control.canonical_projection_read_v1(input,'GUIDE','guide-projection-v1',
    '["Tournaments","Guide Sections","Tournament Itinerary","Tournament Timeline","Rule Book","Tournament Rules","Rounds","Dining","Local Guide","Important Contacts","Courses"]'::jsonb,canonical_context);
  if coalesce((result_value->>'ok')::boolean, false) is not true then
    return result_value;
  end if;
  if result_value#>>'{data,tournament_id}' is distinct from '2026'
     or result_value#>>'{data,tournament_year}' is distinct from '2026' then
    raise exception using errcode = '55000', message = 'GUIDE_CANONICAL_CONTEXT_UNAVAILABLE';
  end if;
  select pg_catalog.jsonb_build_object(
    'tournament_id', value.tournament_id,
    'tournament_year', value.tournament_year,
    'name', value.name
  ) into strict tournament_value
  from scoring_authority.tournaments value where value.tournament_id = '2026';

  -- Reuse the same canonical assignment/tee/hole reader as Guide authoring.
  -- It already handles the frozen snapshot fallback; do not duplicate it here.
  courses_value := production_control.guide_canonical_course_context_v1('2026');
  if scoring_authority.guide_course_context_is_eligible(courses_value) is not true then
    raise exception using errcode = '55000', message = 'GUIDE_CANONICAL_CONTEXT_UNAVAILABLE';
  end if;
  return pg_catalog.jsonb_set(result_value, '{data}', result_value->'data' ||
    pg_catalog.jsonb_build_object(
      'tournament', tournament_value,
      'course_context', courses_value,
      'delivery_fingerprint', pg_catalog.encode(extensions.digest(
        pg_catalog.jsonb_build_object(
          'publication', result_value#>>'{data,payload_fingerprint}',
          'tournament', tournament_value,
          'course_context', courses_value
        )::text, 'sha256'), 'hex')
    ));
end;
$$;


ALTER FUNCTION production_control.canonical_guide_read_v1(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_identity_for_auth_v1(uuid, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_identity_for_auth_v1(target_auth_user_id uuid, target_tournament_id text, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare target_tournament text := btrim(coalesce(target_tournament_id, '2026'));
declare target_player text;
declare context jsonb;
begin
  if canonical_context is null then
  perform production_control.assert_production_participant_identity_cutover();
  else
    perform production_control.assert_certification_read_v1(canonical_context,jsonb_build_object('target_tournament_id',coalesce(target_tournament_id,'2026')));
    if canonical_context->>'current_tournament_id'<>'2026' then raise exception using errcode='55000',message='CERTIFICATION_IDENTITY_POINTER_NOT_2026'; end if;
  end if;
  if target_auth_user_id is null or target_tournament <> '2026' then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_SCOPE_INVALID');
  end if;
  select link.player_id into target_player
  from participant_identity.user_player_links link
  join auth.users auth_user on auth_user.id = link.auth_user_id and auth_user.email_confirmed_at is not null
  join participant_identity.participant_auth_identifiers identifier
    on identifier.auth_user_id = link.auth_user_id and identifier.player_id = link.player_id
    and identifier.identifier_type = 'EMAIL' and identifier.status = 'VERIFIED'
    and lower(btrim(auth_user.email)) = identifier.normalized_value_private
  join participant_identity.participant_identity_contacts contact
    on contact.tournament_id = '2026' and contact.player_id = link.player_id
    and contact.identity_active and contact.email_normalized = identifier.normalized_value_private
  join scoring_authority.tournament_players membership
    on membership.tournament_id = contact.tournament_id and membership.player_id = contact.player_id
    and membership.participation_status = 'ACTIVE'
  where link.auth_user_id = target_auth_user_id and link.status = 'ACTIVE';
  if not found then return jsonb_build_object('ok', false, 'code', 'ACTIVE_USER_PLAYER_LINK_REQUIRED'); end if;
  context := public.read_participant_identity_context('2026', target_player);
  if coalesce((context->>'ok')::boolean, false) then
    return jsonb_set(context, '{data,authUserId}', to_jsonb(target_auth_user_id), true);
  end if;
  return context;
end;
$$;


ALTER FUNCTION production_control.canonical_identity_for_auth_v1(target_auth_user_id uuid, target_tournament_id text, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_identity_for_player_v1(text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_identity_for_player_v1(target_tournament_id text, target_player_id text, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'public', 'pg_temp'
    AS $$
declare target_user uuid;
begin
  if canonical_context is null then
  perform production_control.assert_production_participant_identity_cutover();
  else
    perform production_control.assert_certification_read_v1(canonical_context,jsonb_build_object('target_tournament_id',coalesce(target_tournament_id,'2026')));
    if canonical_context->>'current_tournament_id'<>'2026' then raise exception using errcode='55000',message='CERTIFICATION_IDENTITY_POINTER_NOT_2026'; end if;
  end if;
  if btrim(coalesce(target_tournament_id, '')) <> '2026' then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_SCOPE_INVALID');
  end if;
  select auth_user_id into target_user from participant_identity.user_player_links
    where player_id = btrim(target_player_id) and status = 'ACTIVE';
  if not found then return jsonb_build_object('ok', false, 'code', 'ACTIVE_USER_PLAYER_LINK_REQUIRED'); end if;
  return production_control.canonical_identity_for_auth_v1(target_user, '2026',canonical_context);
end;
$$;


ALTER FUNCTION production_control.canonical_identity_for_player_v1(target_tournament_id text, target_player_id text, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_mark_competition_derived_job_failed_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_mark_competition_derived_job_failed_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_tournament text := pg_catalog.btrim(coalesce(
    input->>'tournament_id', ''
  ));
  target_engine text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'engine_key', ''
  )));
  target_claim timestamptz := (input->>'claim_started_at')::timestamptz;
  updated_count integer := 0;
begin
  if canonical_context is not null then
    perform production_control.assert_canonical_scoring_context_v1(input,canonical_context,'RUNTIME');
    if canonical_context->>'phase' is distinct from 'WORKERS' then raise exception using errcode='42501',message='CERTIFICATION_DERIVED_CONTEXT_REQUIRED'; end if;
  end if;
  if (canonical_context is null and pg_catalog.upper(pg_catalog.btrim(coalesce(
       input->>'environment', ''
     ))) <> 'PREVIEW')
     or target_tournament = ''
     or target_engine not in ('TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES')
     or target_claim is null then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_DERIVED_FAILURE_REQUIRED'
    );
  end if;
  update scoring_authority.competition_recalculation_jobs value set
    status = 'FAILED', completed_at = pg_catalog.now(),
    last_error_code = pg_catalog.left(pg_catalog.btrim(coalesce(
      input->>'error_code', 'DERIVED_CALCULATION_FAILED'
    )), 120),
    last_error_safe = pg_catalog.left(pg_catalog.btrim(coalesce(
      input->>'error_safe',
      'Prepared competition content is temporarily unavailable.'
    )), 400),
    updated_at = pg_catalog.now()
  where value.tournament_id = target_tournament
    and value.round_number = 0 and value.engine_key = target_engine
    and value.status = 'RUNNING' and value.started_at = target_claim;
  get diagnostics updated_count = row_count;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'marked', updated_count = 1,
    'superseded', updated_count = 0
  );
end;
$$;


ALTER FUNCTION production_control.canonical_mark_competition_derived_job_failed_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_match_control_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_match_control_v1(input jsonb, isolated_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  rechecked_context jsonb;
  match_row scoring_authority.matches%rowtype;
  next_match_row scoring_authority.matches%rowtype;
  mutation_row scoring_authority.score_mutations%rowtype;
  target_match text := input->>'match_id';
  operation text := pg_catalog.upper(coalesce(input->>'operation', ''));
  mutation_identity text := input->>'mutation_key';
  actor text := input#>>'{authorization,player_id}';
  expected_match bigint := coalesce(
    (input->>'expected_match_revision')::bigint, -1
  );
  expected_permission bigint := coalesce(
    (input#>>'{authorization,permission_revision}')::bigint, -1
  );
  next_match_revision bigint;
  next_permission_revision bigint;
  permission_changes boolean;
  target_locked boolean;
  target_access boolean;
  event_type text;
  mutation_type text;
  payload_hash_value text;
  result_value jsonb;
  before_permissions jsonb;
  after_permissions jsonb;
  readiness_value jsonb;
  transition_at timestamptz := pg_catalog.clock_timestamp();
begin
  -- Initial admission is enforced by the Production or isolated entry point.
  if operation not in (
       'MARK_LIVE', 'SCORING_LOCK', 'SCORING_UNLOCK',
       'ACCESS_ACTIVATE', 'ACCESS_REVOKE'
     ) or coalesce(target_match, '') = ''
       or coalesce(mutation_identity, '') = '' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'INVALID_CONTROL_OPERATION'
    );
  end if;
  -- Tournament Setup always acquires this lock before locking a match. Use the
  -- same order so a setup commit and MARK_LIVE cannot pass one another.
  if operation in ('MARK_LIVE', 'ACCESS_ACTIVATE', 'SCORING_UNLOCK') then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'production-access-governance-v1:2026', 0
    ));
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'production-tournament-setup-v1:2026', 0
    ));
  end if;
  select * into match_row from scoring_authority.matches
    where match_id = target_match and tournament_id = '2026' for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'MATCH_NOT_FOUND'
    );
  end if;
  if input#>>'{authorization,match_id}' <> target_match then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'DIRECTOR_REQUIRED'
    );
  end if;
  -- Access-granting operations must validate the current canonical readiness
  -- inside the same transaction, before receipt replay or any permission write.
  -- Setup/access governance hold the advisory locks above; handicap approval
  -- takes all affected match row locks before advancing its current pointer.
  -- READ COMMITTED ensures a waiter sees authority committed before its lock.
  if operation in ('ACCESS_ACTIVATE', 'SCORING_UNLOCK') then
    if pg_catalog.current_setting('transaction_isolation') <> 'read committed' then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'SCORING_READINESS_REFRESH_REQUIRED'
      );
    end if;
    if isolated_input is null then
      perform production_control.assert_production_scoring_runtime(input);
      perform production_control.assert_production_scoring_actor(input, true);
    elsif isolated_input->>'contract_version'='certification-runtime-v1' then
      rechecked_context:=production_control.current_certification_context_v1();
      perform production_control.assert_canonical_scoring_context_v1(input,rechecked_context,'RUNTIME');
      perform production_control.assert_production_scoring_actor(input,true);
      if isolated_input->>'operation_id' is distinct from 'DIRECTOR.MATCH_CONTROL'
        or isolated_input#>>'{payload,match_id}' is distinct from target_match
        or isolated_input->>'operation_request_id' is distinct from mutation_identity
        or isolated_input#>>'{authorization,player_id}' is distinct from input#>>'{authorization,player_id}'
        or isolated_input#>>'{authorization,auth_user_id}' is distinct from input#>>'{authorization,auth_user_id}' then
        raise exception using errcode='42501',message='CERTIFICATION_DOMAIN_CONTEXT_REQUIRED';
      end if;
    else
      rechecked_context:=production_control.assert_isolated_director_operation_context_v1(isolated_input,true);
      if isolated_input->>'family' is distinct from 'MATCH_CONTROL'
        or isolated_input#>>'{payload,match_id}' is distinct from target_match
        or rechecked_context->>'actor_player_id' is distinct from input#>>'{authorization,player_id}'
        or rechecked_context->>'actor_auth_user_id' is distinct from input#>>'{authorization,auth_user_id}'
        or rechecked_context->>'operation_request_id' is distinct from mutation_identity
        or rechecked_context->>'tournament_id' is distinct from input->>'tournament_id' then
        raise exception using errcode='42501',message='ISOLATED_DIRECTOR_CONTEXT_REQUIRED';
      end if;
    end if;
    if match_row.status = 'FINAL' then
      return pg_catalog.jsonb_build_object('ok',false,'code','MATCH_FINAL');
    end if;
    if exists(select 1 from scoring_authority.score_mutations r where r.match_id=target_match
      and ((r.mutation_type in('ACCESS_ACTIVATE','SCORING_UNLOCK') and r.result->>'scoring_context_hash' is not null)
        or r.mutation_type in('HOLE_SCORE','FINALIZE','REOPEN')))
      or exists(select 1 from scoring_authority.hole_scores h where h.match_id=target_match)
      or match_row.scored_holes>0 then
      readiness_value := production_control.assert_production_match_resume_ready_v1(target_match);
    else
      readiness_value := production_control.assert_production_match_scoring_ready_v1(target_match);
    end if;
    if coalesce((readiness_value->>'ready')::boolean, false) is not true then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', case when readiness_value->>'contractVersion'='production-match-resume-readiness-v1'
          then 'PRODUCTION_MATCH_NOT_RESUME_READY' else 'PRODUCTION_MATCH_NOT_SCORING_READY' end,
        'match_id', target_match,
        'scoring_readiness_contract', readiness_value->>'contractVersion',
        'reasons', coalesce(readiness_value->'reasons', '[]'::jsonb),
        'audit_created', false, 'google_outbox_created', false
      );
    end if;
    if expected_match <> match_row.match_revision then
      return pg_catalog.jsonb_build_object('ok', false, 'code', 'MATCH_REVISION_CONFLICT');
    end if;
    if expected_permission <> match_row.permission_revision then
      return pg_catalog.jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE');
    end if;
  end if;
  payload_hash_value := production_control.cutover_payload_hash(
    pg_catalog.jsonb_build_object(
      'match_id', target_match, 'operation', operation, 'actor_id', actor
    )
  );
  select * into mutation_row from scoring_authority.score_mutations
    where match_id = target_match and mutation_key = mutation_identity;
  if found then
    if mutation_row.payload_hash = payload_hash_value then
      return mutation_row.result || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'IDEMPOTENCY_CONFLICT'
    );
  end if;
  if expected_match <> match_row.match_revision then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'MATCH_REVISION_CONFLICT',
      'current_match_revision', match_row.match_revision
    );
  end if;
  if expected_permission <> match_row.permission_revision then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PERMISSION_STALE',
      'current_permission_revision', match_row.permission_revision
    );
  end if;
  if match_row.status = 'FINAL' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'MATCH_FINAL'
    );
  end if;
  if operation = 'MARK_LIVE' and match_row.status = 'LIVE' then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'NO_CHANGE', 'semantic_noop', true,
      'match_id', target_match,
      'match_revision', match_row.match_revision,
      'permission_revision', match_row.permission_revision,
      'status', match_row.status,
      'scoring_locked', match_row.scoring_locked,
      'google_outbox_created', false
    );
  end if;
  if operation = 'MARK_LIVE' and match_row.status <> 'UPCOMING' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'MATCH_NOT_UPCOMING'
    );
  end if;
  if operation = 'MARK_LIVE' then
    readiness_value :=
      production_control.assert_production_match_scoring_ready_v1(
        target_match
      );
    if coalesce((readiness_value->>'ready')::boolean, false) is not true then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'code', 'PRODUCTION_MATCH_NOT_SCORING_READY',
        'match_id', target_match,
        'match_revision', match_row.match_revision,
        'permission_revision', match_row.permission_revision,
        'status', match_row.status,
        'scoring_locked', match_row.scoring_locked,
        'scoring_readiness_contract',
          'production-match-scoring-readiness-v1',
        'reasons', coalesce(readiness_value->'reasons', '[]'::jsonb),
        'audit_created', false,
        'google_outbox_created', false
      );
    end if;
  end if;
  if operation in ('SCORING_UNLOCK', 'ACCESS_ACTIVATE') and (
       (operation = 'ACCESS_ACTIVATE' and match_row.scoring_locked)
       or (operation = 'SCORING_UNLOCK' and not match_row.scoring_locked)
     ) then
    if operation = 'ACCESS_ACTIVATE' and match_row.scoring_locked then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'SCORING_LOCKED'
      );
    end if;
    if not exists (
      select 1 from scoring_authority.scoring_permissions
      where match_id = target_match and (
        not can_score or revoked_at is not null
        or permission_revision <> match_row.permission_revision
      )
    ) then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'code', 'NO_CHANGE', 'semantic_noop', true,
        'match_id', target_match,
        'match_revision', match_row.match_revision,
        'permission_revision', match_row.permission_revision,
        'scoring_locked', match_row.scoring_locked,
        'access_active', true,
        'google_outbox_created', false
      );
    end if;
  end if;
  if operation = 'SCORING_LOCK' and match_row.scoring_locked and not exists (
    select 1 from scoring_authority.scoring_permissions
    where match_id = target_match and (
      can_score or revoked_at is null
      or permission_revision <> match_row.permission_revision
    )
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'NO_CHANGE', 'semantic_noop', true,
      'match_id', target_match,
      'match_revision', match_row.match_revision,
      'permission_revision', match_row.permission_revision,
      'scoring_locked', true,
      'access_active', false,
      'google_outbox_created', false
    );
  end if;
  if operation = 'ACCESS_REVOKE' and not exists (
    select 1 from scoring_authority.scoring_permissions
    where match_id = target_match and (
      can_score or revoked_at is null
      or permission_revision <> match_row.permission_revision
    )
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'NO_CHANGE', 'semantic_noop', true,
      'match_id', target_match,
      'match_revision', match_row.match_revision,
      'permission_revision', match_row.permission_revision,
      'scoring_locked', match_row.scoring_locked,
      'access_active', false,
      'google_outbox_created', false
    );
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.to_jsonb(permission) order by player_id
  ), '[]'::jsonb) into before_permissions
  from scoring_authority.scoring_permissions permission
  where match_id = target_match;
  next_match_revision := match_row.match_revision + 1;
  permission_changes := operation <> 'MARK_LIVE';
  next_permission_revision := match_row.permission_revision
    + case when permission_changes then 1 else 0 end;
  target_locked := case operation
    when 'SCORING_LOCK' then true
    when 'SCORING_UNLOCK' then false
    else match_row.scoring_locked end;
  target_access := case operation
    when 'SCORING_LOCK' then false
    when 'SCORING_UNLOCK' then true
    when 'ACCESS_ACTIVATE' then true
    when 'ACCESS_REVOKE' then false
    else exists (
      select 1 from scoring_authority.scoring_permissions
      where match_id = target_match and can_score and revoked_at is null
    ) end;
  event_type := case operation
    when 'MARK_LIVE' then 'MATCH_MARKED_LIVE'
    when 'SCORING_LOCK' then 'SCORING_LOCKED'
    when 'SCORING_UNLOCK' then 'SCORING_UNLOCKED'
    when 'ACCESS_ACTIVATE' then 'SCORING_ACCESS_ACTIVATED'
    else 'SCORING_ACCESS_REVOKED' end;
  mutation_type := operation;

  update scoring_authority.matches set
    status = case when operation = 'MARK_LIVE' then 'LIVE' else status end,
    scoring_locked = target_locked,
    match_revision = next_match_revision,
    permission_revision = next_permission_revision,
    authority_updated_at = transition_at,
    updated_at = transition_at
  where match_id = target_match returning * into next_match_row;
  if permission_changes then
    update scoring_authority.scoring_permissions set
      can_score = target_access,
      permission_revision = next_permission_revision,
      revoked_at = case when target_access then null else transition_at end,
      updated_at = transition_at
    where match_id = target_match;
  end if;
  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.to_jsonb(permission) order by player_id
  ), '[]'::jsonb) into after_permissions
  from scoring_authority.scoring_permissions permission
  where match_id = target_match;
  result_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', operation,
    'match_id', target_match,
    'google_target_match_id', target_match,
    'match_revision', next_match_revision,
    'previous_permission_revision', match_row.permission_revision,
    'permission_revision', next_permission_revision,
    'status', next_match_row.status,
    'scoring_locked', target_locked,
    'access_active', target_access,
    'updated_at', transition_at,
    'permission_transition', pg_catalog.jsonb_build_object(
      'before', before_permissions, 'after', after_permissions
    ),
    'scoring_context_hash', case when operation in('ACCESS_ACTIVATE','SCORING_UNLOCK')
      then production_control.match_resume_context_hash_v1(target_match) else null end,
    'audit_created', true,
    'google_outbox_created', false
  );
  insert into scoring_authority.score_mutations (
    match_id, mutation_key, mutation_type, payload_hash,
    previous_match_revision, next_match_revision, result, actor_id
  ) values (
    target_match, mutation_identity, mutation_type, payload_hash_value,
    match_row.match_revision, next_match_revision, result_value, actor
  );
  insert into scoring_authority.score_revision_history (
    match_id, mutation_key, action, previous_match_revision,
    next_match_revision, before_state, after_state, actor_id
  ) values (
    target_match, mutation_identity, event_type,
    match_row.match_revision, next_match_revision,
    pg_catalog.jsonb_build_object(
      'match', pg_catalog.to_jsonb(match_row),
      'permissions', before_permissions
    ),
    pg_catalog.jsonb_build_object(
      'match', pg_catalog.to_jsonb(next_match_row),
      'permissions', after_permissions
    ),
    actor
  );
  insert into scoring_authority.audit_events (
    tournament_id, match_id, mutation_key, action, actor_id, metadata
  ) values (
    '2026', target_match, mutation_identity, event_type, actor, result_value
  );
  -- Google runtime retired: external delivery is not canonical authority.
  return result_value;
end;
$$;


ALTER FUNCTION production_control.canonical_match_control_v1(input jsonb, isolated_input jsonb) OWNER TO postgres;

--
-- Name: canonical_mutate_future_runtime_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_mutate_future_runtime_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  action_value text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'action', ''
  )));
  target_id text := pg_catalog.btrim(coalesce(
    input->>'target_tournament_id', ''
  ));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  request_id uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash', ''
  )));
  database_hash text;
  expected_revision bigint;
  receipt production_control.future_runtime_operation_receipts_v2%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  match_value scoring_authority.matches%rowtype;
  binding production_control.future_runtime_match_bindings_v2%rowtype;
  detail scoring_authority.tournament_setup_match_details_v1%rowtype;
  current_handicap uuid;
  handicap_revision_id_value uuid;
  next_revision bigint;
  prior_revision bigint := 0;
  result_value jsonb;
  safe_metadata jsonb := '{}'::jsonb;
  target_kind text := 'RUNTIME';
  target_object text;
  changed_value boolean := true;
  course_id_value text;
  tee_id_value text;
  course_name text;
  course_location text;
  rating_value numeric;
  slope_value integer;
  par_value integer;
  target_round_value integer;
  context_revision_value bigint;
  hole_value jsonb;
  hole_number_value integer;
  hole_par_value integer;
  stroke_index_value integer;
  yardage_value integer;
  manifest_fingerprint text;
  participants_input jsonb;
  participant jsonb;
  normalized jsonb := '[]'::jsonb;
  expected_count integer;
  player_value text;
  side_value integer;
  slot_value integer;
  context_value jsonb;
  holes_value jsonb;
  participant_manifest jsonb;
  preparation_fingerprint text;
  next_snapshot_revision bigint;
  next_snapshot_id text;
  next_snapshot_hash text;
  readiness jsonb;
  blockers jsonb;
  previous_pointer_revision bigint;
  source_fingerprint text;
  archive_fingerprint text;
  generation_id uuid;
  authority_generation_id_value uuid;
  admission_generation_id_value uuid;
  target_player_value text;
  target_auth_value uuid;
  target_auth_candidates uuid[];
  entitlement_value production_control.director_entitlements%rowtype;
  role_changed boolean := false;
begin
  if action_value not in (
    'ADD_GLOBAL_COURSE', 'CONFIGURE_GLOBAL_COURSE_CONTEXT',
    'ASSIGN_FUTURE_COURSE', 'PROMOTE_RUNTIME_STRUCTURE',
    'STAGE_HANDICAPS', 'APPROVE_HANDICAPS', 'CONFIGURE_MATCH',
    'REPLACE_PAIRINGS', 'PREPARE_SCORING_CONTEXT',
    'GRANT_FUTURE_DIRECTOR',
    'MARK_READY_FOR_ACTIVATION', 'ACTIVATE_TOURNAMENT',
    'CLOSE_TOURNAMENT', 'PREPARE_ARCHIVE_PLAN'
  ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_RUNTIME_ACTION_INVALID';
  end if;
  -- Both public wrappers reject legacy activation/close; keep the fence here too.
  if action_value in ('ACTIVATE_TOURNAMENT','CLOSE_TOURNAMENT') then
   raise exception using errcode='55000',message='PRODUCTION_ANNUAL_SCORING_TRANSITION_REQUIRED'; end if;
  perform production_control.assert_canonical_future_authoring_resource_v2(
    input, resource_context, 'production-future-runtime-activation-v2', action_value in (
      'ADD_GLOBAL_COURSE', 'CONFIGURE_GLOBAL_COURSE_CONTEXT',
      'PROMOTE_RUNTIME_STRUCTURE', 'GRANT_FUTURE_DIRECTOR',
      'MARK_READY_FOR_ACTIVATION', 'ACTIVATE_TOURNAMENT',
      'CLOSE_TOURNAMENT', 'PREPARE_ARCHIVE_PLAN'
    )
  );
  begin
    actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
    request_id := (input->>'operation_request_id')::uuid;
    expected_revision := (input->>'expected_revision')::bigint;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_RUNTIME_INPUT_INVALID';
  end;
  perform production_control.assert_access_governance_safe_reason_v1(
    input->>'reason'
  );
  database_hash := production_control.future_runtime_hash_v2(
    input - 'request_payload_hash'
  );
  if declared_hash !~ '^[0-9a-f]{64}$'
     or declared_hash <> database_hash then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_RUNTIME_PAYLOAD_HASH_INVALID';
  end if;
  select value.* into receipt
  from production_control.future_runtime_operation_receipts_v2 value
  where value.action = action_value
    and value.operation_request_id = request_id;
  if receipt.receipt_id is not null then
    if receipt.database_request_payload_hash <> database_hash
       or receipt.declared_request_payload_hash <> declared_hash then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_FUTURE_RUNTIME_IDEMPOTENCY_CONFLICT';
    end if;
    return receipt.response || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'future-runtime-v2:' || action_value || ':' || coalesce(target_id, ''), 0
    )
  );
  select value.* into receipt
  from production_control.future_runtime_operation_receipts_v2 value
  where value.action = action_value
    and value.operation_request_id = request_id;
  if receipt.receipt_id is not null then
    if receipt.database_request_payload_hash <> database_hash
       or receipt.declared_request_payload_hash <> declared_hash then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_FUTURE_RUNTIME_IDEMPOTENCY_CONFLICT';
    end if;
    return receipt.response || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;
  target_object := nullif(target_id, '');

  if action_value = 'GRANT_FUTURE_DIRECTOR' then
    target_player_value := pg_catalog.upper(pg_catalog.btrim(coalesce(
      input->>'target_player_id', ''
    )));
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    select value.governance_revision into prior_revision
    from production_control.future_tournament_director_governance_v1 value
    where value.tournament_id = target_id for update;
    prior_revision := coalesce(prior_revision, 0);
    if target_player_value !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
       or catalog.tournament_year <= 2026
       or catalog.tournament_year <> (input->>'target_tournament_year')::integer
       or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
       or target_id = (select value.tournament_id
         from production_control.current_tournament_pointer_v1 value
         where value.scope_key = (resource_context->>'resource_id'))
       or expected_revision <> prior_revision
       or production_control.access_governance_global_status_v1(
         target_player_value
       ) <> 'ACTIVE'
       or not exists (
         select 1
         from production_control.future_tournament_roster_v1 membership
         where membership.tournament_id = target_id
           and membership.player_id = target_player_value
           and membership.participation_status = 'ACTIVE'
       ) then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_FUTURE_DIRECTOR_PREDECESSOR_INVALID';
    end if;

    select pg_catalog.array_agg(candidate.auth_user_id order by
      candidate.auth_user_id::text) into target_auth_candidates
    from (
      select distinct link.auth_user_id
      from participant_identity.user_player_links link
      join auth.users auth_user on auth_user.id = link.auth_user_id
      join participant_identity.participant_auth_identifiers identifier
        on identifier.player_id = link.player_id
       and identifier.auth_user_id = link.auth_user_id
       and identifier.status = 'VERIFIED'
       and identifier.revoked_at is null
      where link.player_id = target_player_value
        and link.status = 'ACTIVE' and link.revoked_at is null
        and (
          (identifier.identifier_type = 'EMAIL'
            and auth_user.email_confirmed_at is not null
            and pg_catalog.lower(pg_catalog.btrim(coalesce(
              auth_user.email, ''
            ))) = identifier.normalized_value_private)
          or (identifier.identifier_type = 'PHONE'
            and auth_user.phone_confirmed_at is not null
            and pg_catalog.btrim(coalesce(auth_user.phone, '')) =
              identifier.normalized_value_private)
        )
    ) candidate;
    if coalesce(pg_catalog.cardinality(target_auth_candidates), 0) <> 1 then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_FUTURE_DIRECTOR_LINKED_IDENTITY_REQUIRED';
    end if;
    target_auth_value := target_auth_candidates[1];

    select value.* into entitlement_value
    from production_control.director_entitlements value
    where value.tournament_id = target_id
      and value.auth_user_id = target_auth_value;
    if entitlement_value.entitlement_id is not null and (
      entitlement_value.player_id is distinct from target_player_value
      or entitlement_value.role <> 'DIRECTOR'
    ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_FUTURE_DIRECTOR_IDENTITY_CONFLICT';
    end if;
    changed_value := entitlement_value.entitlement_id is null
      or entitlement_value.status <> 'ACTIVE'
      or entitlement_value.revoked_at is not null;
    if changed_value then
      insert into production_control.director_entitlements (
        auth_user_id, tournament_id, player_id, role, status,
        granted_by, granted_at, revoked_at
      ) values (
        target_auth_value, target_id, target_player_value, 'DIRECTOR',
        'ACTIVE', actor_player, pg_catalog.clock_timestamp(), null
      ) on conflict (auth_user_id, tournament_id) do update set
        player_id = excluded.player_id, role = 'DIRECTOR', status = 'ACTIVE',
        granted_by = excluded.granted_by, granted_at = excluded.granted_at,
        revoked_at = null;
      select value.* into strict entitlement_value
      from production_control.director_entitlements value
      where value.tournament_id = target_id
        and value.auth_user_id = target_auth_value;
      insert into production_control.director_entitlement_events (
        entitlement_id, action, actor, reason
      ) values (
        entitlement_value.entitlement_id, 'GRANTED', actor_player,
        pg_catalog.btrim(input->>'reason')
      );
    end if;
    role_changed := not exists (
      select 1 from participant_identity.tournament_roles role_value
      where role_value.tournament_id = target_id
        and role_value.auth_user_id = target_auth_value
        and role_value.role = 'DIRECTOR'
        and role_value.role_active and role_value.revoked_at is null
    );
    insert into participant_identity.tournament_roles (
      tournament_id, auth_user_id, role, role_active, role_revision,
      granted_at, granted_by, revoked_at, revoked_by
    ) values (
      target_id, target_auth_value, 'DIRECTOR', true, 1,
      pg_catalog.clock_timestamp(), actor_player, null, null
    ) on conflict (tournament_id, auth_user_id, role) do update set
      role_active = true,
      role_revision = participant_identity.tournament_roles.role_revision +
        case when participant_identity.tournament_roles.role_active
          and participant_identity.tournament_roles.revoked_at is null
          then 0 else 1 end,
      granted_at = case when participant_identity.tournament_roles.role_active
          and participant_identity.tournament_roles.revoked_at is null
        then participant_identity.tournament_roles.granted_at
        else pg_catalog.clock_timestamp() end,
      granted_by = case when participant_identity.tournament_roles.role_active
          and participant_identity.tournament_roles.revoked_at is null
        then participant_identity.tournament_roles.granted_by
        else actor_player end,
      revoked_at = null, revoked_by = null,
      updated_at = case when participant_identity.tournament_roles.role_active
          and participant_identity.tournament_roles.revoked_at is null
        then participant_identity.tournament_roles.updated_at
        else pg_catalog.clock_timestamp() end;
    changed_value := changed_value or role_changed;
    next_revision := prior_revision + case when changed_value then 1 else 0 end;
    if changed_value then
      insert into production_control.future_tournament_director_governance_v1 (
        tournament_id, governance_revision, updated_by_player_id,
        updated_by_auth_user_id
      ) values (
        target_id, next_revision, actor_player, actor_auth
      ) on conflict (tournament_id) do update set
        governance_revision = excluded.governance_revision,
        updated_by_player_id = excluded.updated_by_player_id,
        updated_by_auth_user_id = excluded.updated_by_auth_user_id,
        updated_at = pg_catalog.clock_timestamp();
    end if;
    target_kind := 'IDENTITY';
    target_object := target_player_value;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Future tournament Director granted',
      'playerId', target_player_value, 'role', 'DIRECTOR',
      'identityChanged', false, 'membershipChanged', false
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_DIRECTOR_GRANTED',
      'action', action_value, 'tournamentId', target_id,
      'targetPlayerId', target_player_value,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'changed', changed_value, 'idempotent', false
    );

  elsif action_value = 'ADD_GLOBAL_COURSE' then
    select value.allocator_revision into strict prior_revision
    from production_control.global_course_id_allocator_v1 value
    where value.scope_key = (resource_context->>'resource_id') for update;
    if expected_revision <> prior_revision then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_GLOBAL_COURSE_ALLOCATOR_REVISION_STALE';
    end if;
    course_name := pg_catalog.btrim(coalesce(input->>'display_name', ''));
    course_location := nullif(pg_catalog.btrim(coalesce(
      input->>'location', ''
    )), '');
    if course_name = '' or pg_catalog.length(course_name) > 240
       or (course_location is not null
         and pg_catalog.length(course_location) > 240)
       or exists (
         select 1 from scoring_authority.global_course_library_v1 value
         where pg_catalog.lower(value.display_name) =
           pg_catalog.lower(course_name)
           and coalesce(pg_catalog.lower(value.location), '') =
             coalesce(pg_catalog.lower(course_location), '')
       ) then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_GLOBAL_COURSE_IDENTITY_CONFLICT';
    end if;
    course_id_value := production_control.allocate_global_course_id_v1();
    insert into scoring_authority.global_course_catalog_v1 (
      course_id, display_name, location, catalog_status, identity_source,
      catalog_revision, created_by_player_id, created_by_auth_user_id
    ) values (
      course_id_value, course_name, course_location, 'ACTIVE',
      'DIRECTOR_CREATED', 1, actor_player, actor_auth
    );
    next_revision := prior_revision + 1;
    target_kind := 'GLOBAL_COURSE';
    target_object := course_id_value;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Global Course created', 'courseId', course_id_value
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_GLOBAL_COURSE_CREATED',
      'action', action_value, 'courseId', course_id_value,
      'catalogRevision', 1, 'priorRevision', prior_revision,
      'nextRevision', next_revision, 'scoringReady', false,
      'idempotent', false
    );

  elsif action_value = 'CONFIGURE_GLOBAL_COURSE_CONTEXT' then
    course_id_value := pg_catalog.btrim(coalesce(input->>'course_id', ''));
    tee_id_value := pg_catalog.btrim(coalesce(input->>'tee_id', ''));
    holes_value := input->'holes';
    begin
      rating_value := (input->>'rating')::numeric;
      slope_value := (input->>'slope')::integer;
      par_value := (input->>'par')::integer;
    exception when others then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_GLOBAL_COURSE_CONTEXT_INPUT_INVALID';
    end;
    select value.catalog_revision into strict prior_revision
    from scoring_authority.global_course_catalog_v1 value
    where value.course_id = course_id_value
      and value.identity_source = 'DIRECTOR_CREATED'
      and value.catalog_status = 'ACTIVE'
    for update;
    if expected_revision <> prior_revision
       or tee_id_value = '' or pg_catalog.length(tee_id_value) > 120
       or rating_value <= 0 or rating_value > 100
       or slope_value not between 55 and 155
       or par_value not between 54 and 90
       or pg_catalog.jsonb_typeof(holes_value) <> 'array'
       or pg_catalog.jsonb_array_length(holes_value) <> 18 then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_GLOBAL_COURSE_CONTEXT_PREDECESSOR_INVALID';
    end if;
    normalized := '[]'::jsonb;
    for hole_value in
      select entry.value from pg_catalog.jsonb_array_elements(holes_value)
        entry(value)
    loop
      begin
        hole_number_value := (hole_value->>'hole_number')::integer;
        hole_par_value := (hole_value->>'par')::integer;
        stroke_index_value := (hole_value->>'stroke_index')::integer;
        yardage_value := nullif(hole_value->>'yardage', '')::integer;
      exception when others then
        raise exception using errcode = '22023',
          message = 'PRODUCTION_GLOBAL_COURSE_HOLE_INPUT_INVALID';
      end;
      if hole_number_value not between 1 and 18
         or hole_par_value not between 3 and 6
         or stroke_index_value not between 1 and 18
         or (yardage_value is not null
           and yardage_value not between 1 and 999) then
        raise exception using errcode = '22023',
          message = 'PRODUCTION_GLOBAL_COURSE_HOLE_INPUT_INVALID';
      end if;
      normalized := normalized || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'hole_number', hole_number_value, 'par', hole_par_value,
          'stroke_index', stroke_index_value, 'yardage', yardage_value
        )
      );
    end loop;
    if (select pg_catalog.count(distinct (entry->>'hole_number')::integer)
          from pg_catalog.jsonb_array_elements(normalized) entry) <> 18
       or (select pg_catalog.count(distinct (entry->>'stroke_index')::integer)
          from pg_catalog.jsonb_array_elements(normalized) entry) <> 18
       or (select pg_catalog.sum((entry->>'par')::integer)
          from pg_catalog.jsonb_array_elements(normalized) entry) <> par_value then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_GLOBAL_COURSE_HOLES_INCOMPLETE';
    end if;
    next_revision := prior_revision + 1;
    delete from scoring_authority.global_course_hole_contexts_v1 value
    where value.course_id = course_id_value and value.tee_id = tee_id_value;
    insert into scoring_authority.global_course_tee_contexts_v1 (
      course_id, tee_id, rating, slope, par, context_revision,
      configured_by_player_id, configured_by_auth_user_id
    ) values (
      course_id_value, tee_id_value, rating_value, slope_value, par_value,
      next_revision, actor_player, actor_auth
    ) on conflict (course_id, tee_id) do update set
      rating = excluded.rating, slope = excluded.slope, par = excluded.par,
      context_revision = excluded.context_revision,
      configured_by_player_id = excluded.configured_by_player_id,
      configured_by_auth_user_id = excluded.configured_by_auth_user_id,
      updated_at = pg_catalog.clock_timestamp();
    insert into scoring_authority.global_course_hole_contexts_v1 (
      course_id, tee_id, hole_number, par, stroke_index, yardage,
      context_revision
    ) select course_id_value, tee_id_value,
      (entry->>'hole_number')::integer, (entry->>'par')::integer,
      (entry->>'stroke_index')::integer,
      nullif(entry->>'yardage', '')::integer, next_revision
    from pg_catalog.jsonb_array_elements(normalized) entry;
    update scoring_authority.global_course_catalog_v1 value set
      catalog_revision = next_revision,
      updated_at = pg_catalog.clock_timestamp()
    where value.course_id = course_id_value;
    target_kind := 'GLOBAL_COURSE';
    target_object := course_id_value || ':' || tee_id_value;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Global Course scoring context configured',
      'courseId', course_id_value, 'teeId', tee_id_value,
      'holeCount', 18
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_GLOBAL_COURSE_CONTEXT_CONFIGURED',
      'action', action_value, 'courseId', course_id_value,
      'teeId', tee_id_value, 'contextRevision', next_revision,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'scoringReady', true, 'idempotent', false
    );

  elsif action_value = 'ASSIGN_FUTURE_COURSE' then
    course_id_value := pg_catalog.btrim(coalesce(input->>'course_id', ''));
    tee_id_value := pg_catalog.btrim(coalesce(input->>'tee_id', ''));
    begin
      target_round_value := (input->>'round_number')::integer;
      context_revision_value := (input->>'course_context_revision')::bigint;
    exception when others then
      raise exception using errcode = '22023',
        message = 'FUTURE_GLOBAL_COURSE_ASSIGNMENT_INPUT_INVALID';
    end;
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    select value.context_revision into strict context_revision_value
    from scoring_authority.global_course_tee_contexts_v1 value
    join scoring_authority.global_course_catalog_v1 course
      on course.course_id = value.course_id
    where value.course_id = course_id_value and value.tee_id = tee_id_value
      and value.context_revision = context_revision_value
      and course.catalog_status = 'ACTIVE'
      and course.identity_source = 'DIRECTOR_CREATED';
    prior_revision := catalog.setup_revision;
    if expected_revision <> prior_revision
       or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
       or exists (select 1
         from production_control.future_runtime_promotions_v2 promotion_value
         where promotion_value.tournament_id = target_id)
       or not exists (
         select 1 from production_control.future_tournament_rounds_v1 round_value
         where round_value.tournament_id = target_id
           and round_value.round_number = target_round_value
       )
       or (select pg_catalog.count(*)
         from scoring_authority.global_course_hole_contexts_v1 hole
         where hole.course_id = course_id_value
           and hole.tee_id = tee_id_value
           and hole.context_revision = context_revision_value) <> 18
       or (select pg_catalog.count(distinct hole.stroke_index)
         from scoring_authority.global_course_hole_contexts_v1 hole
         where hole.course_id = course_id_value
           and hole.tee_id = tee_id_value
           and hole.context_revision = context_revision_value) <> 18 then
      raise exception using errcode = '40001',
        message = 'FUTURE_GLOBAL_COURSE_ASSIGNMENT_PREDECESSOR_INVALID';
    end if;
    next_revision := prior_revision + 1;
    insert into production_control.future_tournament_course_references_v1 (
      tournament_id, round_number, course_id, tee_id,
      source_tournament_id, source_round_number, source_setup_revision,
      reference_status, setup_revision, updated_by_player_id
    ) values (
      target_id, target_round_value, course_id_value, tee_id_value,
      target_id, null, context_revision_value, 'GLOBAL_COURSE_CONTEXT',
      next_revision, actor_player
    ) on conflict (tournament_id, round_number) do update set
      course_id = excluded.course_id, tee_id = excluded.tee_id,
      source_tournament_id = excluded.source_tournament_id,
      source_round_number = excluded.source_round_number,
      source_setup_revision = excluded.source_setup_revision,
      reference_status = excluded.reference_status,
      setup_revision = excluded.setup_revision,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
    update production_control.future_tournament_catalog_v1 value set
      lifecycle = 'CONFIGURING', setup_revision = next_revision,
      readiness_fingerprint = null, readiness_setup_revision = null,
      updated_by_player_id = actor_player,
      updated_by_auth_user_id = actor_auth,
      updated_at = pg_catalog.clock_timestamp()
    where value.tournament_id = target_id;
    target_kind := 'COURSE_ASSIGNMENT';
    target_object := target_id || ':R' || target_round_value::text;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Validated global Course assigned to future round',
      'courseId', course_id_value, 'teeId', tee_id_value,
      'roundNumber', target_round_value
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_GLOBAL_COURSE_ASSIGNED',
      'action', action_value, 'tournamentId', target_id,
      'roundNumber', target_round_value, 'courseId', course_id_value,
      'teeId', tee_id_value, 'courseContextRevision', context_revision_value,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'idempotent', false
    );

  elsif action_value = 'CONFIGURE_MATCH' then
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    select value.* into strict match_value
    from scoring_authority.matches value
    where value.tournament_id = target_id
      and value.match_id = input->>'match_id' for update;
    select value.* into strict binding
    from production_control.future_runtime_match_bindings_v2 value
    where value.tournament_id = target_id
      and value.match_id = match_value.match_id for update;
    prior_revision := binding.runtime_revision;
    if expected_revision <> prior_revision
       or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
       or match_value.status <> 'UPCOMING' or match_value.match_revision <> 0
       or not match_value.scoring_locked
       or not exists (
         select 1 from scoring_authority.tournament_setup_course_tees_v1 tee
         join scoring_authority.tournament_setup_round_courses_v1 assignment
           on assignment.tournament_id = tee.tournament_id
          and assignment.course_id = tee.course_id
          and assignment.tee_id = tee.tee_id
         where tee.tournament_id = target_id
           and assignment.round_number = match_value.round_number
           and tee.course_id = input->>'course_id'
           and tee.tee_id = input->>'tee_id'
       ) then
      raise exception using errcode = '40001',
        message = 'FUTURE_MATCH_CONFIGURATION_PREDECESSOR_INVALID';
    end if;
    begin
      side_value := coalesce((input->>'starting_hole')::integer, 1);
      slot_value := (input->>'match_number')::integer;
    exception when others then
      raise exception using errcode = '22023',
        message = 'FUTURE_MATCH_CONFIGURATION_INPUT_INVALID';
    end;
    if side_value not between 1 and 18 or slot_value not between 1 and 99
       or (select pg_catalog.count(*)
         from scoring_authority.tournament_setup_course_holes_v1 hole
         where hole.tournament_id = target_id
           and hole.course_id = input->>'course_id'
           and hole.tee_id = input->>'tee_id') <> 18 then
      raise exception using errcode = '22023',
        message = 'FUTURE_MATCH_COURSE_CONTEXT_INCOMPLETE';
    end if;
    if match_value.scoring_snapshot_id is not null then
      delete from scoring_authority.match_holes value
      where value.match_id = match_value.match_id;
      update scoring_authority.matches set
        scoring_snapshot_id = null, scoring_locked = true,
        updated_at = pg_catalog.clock_timestamp()
      where match_id = match_value.match_id;
    end if;
    next_revision := prior_revision + 1;
    insert into scoring_authority.tournament_setup_match_details_v1 (
      match_id, tournament_id, round_number, match_number,
      course_id, tee_id, tee_time, starting_hole, setup_revision,
      prepared_setup_revision, prepared_configuration_fingerprint,
      updated_by_player_id
    ) values (
      match_value.match_id, target_id, match_value.round_number, slot_value,
      input->>'course_id', input->>'tee_id',
      nullif(input->>'tee_time', '')::time, side_value, next_revision,
      null, null, actor_player
    ) on conflict (match_id) do update set
      match_number = excluded.match_number,
      course_id = excluded.course_id, tee_id = excluded.tee_id,
      tee_time = excluded.tee_time, starting_hole = excluded.starting_hole,
      setup_revision = excluded.setup_revision,
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_at = pg_catalog.clock_timestamp();
    update production_control.future_runtime_match_bindings_v2 set
      runtime_revision = next_revision, runtime_state = 'CONFIGURED',
      configuration_fingerprint = null,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = match_value.match_id;
    target_kind := 'MATCH'; target_object := match_value.match_id;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Future match configured', 'matchId', match_value.match_id,
      'round', match_value.round_number
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_MATCH_CONFIGURED',
      'action', action_value, 'tournamentId', target_id,
      'matchId', match_value.match_id, 'priorRevision', prior_revision,
      'nextRevision', next_revision, 'snapshotPrepared', false,
      'idempotent', false
    );

  elsif action_value = 'REPLACE_PAIRINGS' then
    participants_input := input->'participants';
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    select value.* into strict match_value
    from scoring_authority.matches value
    where value.tournament_id = target_id
      and value.match_id = input->>'match_id' for update;
    select value.* into strict binding
    from production_control.future_runtime_match_bindings_v2 value
    where value.match_id = match_value.match_id for update;
    select value.* into strict detail
    from scoring_authority.tournament_setup_match_details_v1 value
    where value.match_id = match_value.match_id;
    select value.revision_id into strict current_handicap
    from scoring_authority.handicap_revision_current value
    where value.tournament_id = target_id;
    prior_revision := binding.runtime_revision;
    expected_count := case when match_value.format = 'SI' then 2 else 4 end;
    if expected_revision <> prior_revision
       or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
       or match_value.status <> 'UPCOMING' or match_value.match_revision <> 0
       or pg_catalog.jsonb_typeof(participants_input) <> 'array'
       or pg_catalog.jsonb_array_length(participants_input) <> expected_count then
      raise exception using errcode = '40001',
        message = 'FUTURE_PAIRINGS_PREDECESSOR_INVALID';
    end if;
    for participant in select value
      from pg_catalog.jsonb_array_elements(participants_input) entry(value)
    loop
      begin
        player_value := pg_catalog.upper(pg_catalog.btrim(
          participant->>'player_id'
        ));
        side_value := (participant->>'team_side')::integer;
        slot_value := (participant->>'player_slot')::integer;
      exception when others then
        raise exception using errcode = '22023',
          message = 'FUTURE_PAIRING_STRUCTURE_INVALID';
      end;
      if side_value not in (1, 2)
         or slot_value not between 1 and
           (case when match_value.format = 'SI' then 1 else 2 end)
         or not exists (
           select 1 from scoring_authority.tournament_players membership
           where membership.tournament_id = target_id
             and membership.player_id = player_value
             and membership.team_side = side_value
             and membership.participation_status = 'ACTIVE'
             and membership.handicap_revision_id = current_handicap
             and membership.tournament_handicap is not null
         ) then
        raise exception using errcode = '22023',
          message = 'FUTURE_PAIRING_ACTIVE_TEAM_HANDICAP_REQUIRED';
      end if;
      normalized := normalized || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'player_id', player_value, 'team_side', side_value,
          'player_slot', slot_value
        )
      );
    end loop;
    if (select pg_catalog.count(distinct item->>'player_id')
      from pg_catalog.jsonb_array_elements(normalized) item) <> expected_count
       or (select pg_catalog.count(distinct
          (item->>'team_side') || ':' || (item->>'player_slot'))
        from pg_catalog.jsonb_array_elements(normalized) item) <> expected_count
       or (select pg_catalog.count(*)
        from pg_catalog.jsonb_array_elements(normalized) item
        where (item->>'team_side')::integer = 1) <> expected_count / 2
       or (select pg_catalog.count(*)
        from pg_catalog.jsonb_array_elements(normalized) item
        where (item->>'team_side')::integer = 2) <> expected_count / 2
       or exists (
         select 1 from pg_catalog.jsonb_array_elements(normalized) requested
         join scoring_authority.match_participants other
           on other.player_id = requested->>'player_id'
         join scoring_authority.matches other_match
           on other_match.match_id = other.match_id
          and other_match.tournament_id = target_id
          and other_match.round_number = match_value.round_number
          and other_match.match_id <> match_value.match_id
       ) then
      raise exception using errcode = '23505',
        message = 'FUTURE_PAIRING_DUPLICATE_OR_UNBALANCED';
    end if;
    if match_value.scoring_snapshot_id is not null then
      delete from scoring_authority.match_holes value
      where value.match_id = match_value.match_id;
      update scoring_authority.matches set scoring_snapshot_id = null,
        scoring_locked = true, updated_at = pg_catalog.clock_timestamp()
      where match_id = match_value.match_id;
    end if;
    delete from scoring_authority.scoring_permissions value
    where value.match_id = match_value.match_id;
    delete from scoring_authority.match_participants value
    where value.match_id = match_value.match_id;
    insert into scoring_authority.match_participants (
      match_id, player_id, team_side, player_slot, tournament_handicap,
      handicap_index, course_handicap, playing_handicap, final_strokes,
      handicap_revision_id
    ) select match_value.match_id, item->>'player_id',
      (item->>'team_side')::integer, (item->>'player_slot')::integer,
      entry.tournament_handicap, entry.tournament_handicap,
      entry.tournament_handicap, 0, 0, current_handicap
    from pg_catalog.jsonb_array_elements(normalized) item
    join scoring_authority.handicap_revision_entries entry
      on entry.revision_id = current_handicap
     and entry.tournament_id = target_id
     and entry.player_id = item->>'player_id';
    next_revision := prior_revision + 1;
    insert into scoring_authority.scoring_permissions (
      match_id, player_id, can_score, permission_revision,
      revoked_at, updated_at
    ) select match_value.match_id, item->>'player_id', false,
      next_revision, pg_catalog.clock_timestamp(), pg_catalog.clock_timestamp()
    from pg_catalog.jsonb_array_elements(normalized) item;
    update scoring_authority.matches set
      permission_revision = next_revision,
      scoring_locked = true, updated_at = pg_catalog.clock_timestamp()
    where match_id = match_value.match_id;
    update scoring_authority.tournament_setup_match_details_v1 set
      setup_revision = next_revision,
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = match_value.match_id;
    update production_control.future_runtime_match_bindings_v2 set
      runtime_revision = next_revision, runtime_state = 'PAIRED',
      configuration_fingerprint = null,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = match_value.match_id;
    target_kind := 'PAIRINGS'; target_object := match_value.match_id;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Future match pairings replaced',
      'matchId', match_value.match_id, 'participantCount', expected_count,
      'scoringAccessGranted', false
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_PAIRINGS_REPLACED',
      'action', action_value, 'tournamentId', target_id,
      'matchId', match_value.match_id, 'participantCount', expected_count,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'scoringAccessGranted', false, 'idempotent', false
    );

  elsif action_value = 'MARK_READY_FOR_ACTIVATION' then
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    prior_revision := catalog.lifecycle_revision;
    readiness := production_control.future_runtime_readiness_v2(target_id);
    if expected_revision <> prior_revision
       or catalog.lifecycle <> 'CONFIGURING'
       or not (readiness->>'ready')::boolean
       or input->>'readiness_fingerprint'
         is distinct from readiness->>'fingerprint' then
      raise exception using errcode = '40001',
        message = 'FUTURE_ACTIVATION_READINESS_STALE_OR_BLOCKED';
    end if;
    next_revision := prior_revision + 1;
    update production_control.future_tournament_catalog_v1 set
      lifecycle = 'READY_FOR_ACTIVATION',
      lifecycle_revision = next_revision,
      readiness_fingerprint = readiness->>'fingerprint',
      readiness_setup_revision = setup_revision,
      updated_by_player_id = actor_player,
      updated_by_auth_user_id = actor_auth,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    update production_control.future_runtime_promotions_v2 set
      runtime_status = 'READY', updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    target_kind := 'ACTIVATION'; target_object := target_id;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Tournament marked Ready for Activation',
      'readinessFingerprint', readiness->>'fingerprint'
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_TOURNAMENT_READY',
      'action', action_value, 'tournamentId', target_id,
      'lifecycle', 'READY_FOR_ACTIVATION',
      'readinessFingerprint', readiness->>'fingerprint',
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'idempotent', false
    );

  elsif action_value = 'ACTIVATE_TOURNAMENT' then
    select value.* into strict pointer
    from production_control.current_tournament_pointer_v1 value
    where value.scope_key = (resource_context->>'resource_id') for update;
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    select value.* into strict activation
    from production_control.cutover_activation_state value
    where value.scope_key = (resource_context->>'resource_id') for update;
    readiness := production_control.future_runtime_readiness_v2(target_id);
    begin previous_pointer_revision :=
      (input->>'expected_pointer_revision')::bigint;
    exception when others then
      raise exception using errcode = '22023',
        message = 'FUTURE_ACTIVATION_POINTER_REVISION_INVALID';
    end;
    prior_revision := catalog.lifecycle_revision;
    if expected_revision <> prior_revision
       or previous_pointer_revision <> pointer.pointer_revision
       or catalog.lifecycle <> 'READY_FOR_ACTIVATION'
       or catalog.readiness_fingerprint is null
       or catalog.readiness_fingerprint <> readiness->>'fingerprint'
       or input->>'readiness_fingerprint'
         is distinct from readiness->>'fingerprint'
       or not (readiness->>'ready')::boolean
       or not exists (
         select 1 from production_control.future_tournament_catalog_v1 current_value
         where current_value.tournament_id = pointer.tournament_id
           and current_value.lifecycle = 'CLOSED'
       )
       or activation.state <> 'SCORING_COMMITTED'
       or activation.current_authority <> 'SUPABASE'
       or not activation.scoring_ingress_enabled
       or activation.active_transition_epoch_id is not null
       or exists (select 1 from scoring_authority.scoring_ingress_leases value
         where value.expires_at > pg_catalog.clock_timestamp())
       or exists (select 1 from scoring_authority.google_outbox_events value
         where value.status in ('PENDING', 'PROCESSING', 'RETRYABLE'))
       or exists (select 1 from scoring_authority.scorecard_archive_jobs value
         where value.status in ('PENDING', 'PROCESSING', 'RETRYABLE')) then
      raise exception using errcode = '40001',
        message = 'FUTURE_TOURNAMENT_ACTIVATION_PREDECESSOR_INVALID';
    end if;
    if exists (select 1 from production_control.future_annual_runtime_generations_v1
      where generation_status = 'ACTIVE') then
      raise exception using errcode = '55000',
        message = 'FUTURE_ACTIVE_RUNTIME_GENERATION_EXISTS';
    end if;
    next_revision := prior_revision + 1;
    generation_id := extensions.gen_random_uuid();
    authority_generation_id_value := extensions.gen_random_uuid();
    admission_generation_id_value := extensions.gen_random_uuid();
    insert into production_control.future_annual_runtime_generations_v1 (
      runtime_generation_id, tournament_id, generation_status,
      runtime_revision, pointer_revision, authority_generation_id,
      admission_generation_id, authority, ingress_state,
      readiness_fingerprint
    ) values (
      generation_id, target_id, 'PREPARED', 1,
      pointer.pointer_revision + 1, authority_generation_id_value,
      admission_generation_id_value, 'SUPABASE', 'OPEN',
      readiness->>'fingerprint'
    );
    if pg_catalog.to_regprocedure(
      'production_control.assert_future_scoring_runtime_capability_v1(text,uuid,uuid,uuid)'
    ) is null then
      raise exception using errcode = '55000',
        message = 'FUTURE_SCORING_RUNTIME_CAPABILITY_NOT_INSTALLED';
    end if;
    execute 'select production_control.assert_future_scoring_runtime_capability_v1($1,$2,$3,$4)'
      using target_id, generation_id, authority_generation_id_value,
        admission_generation_id_value;
    if pg_catalog.to_regprocedure(
      'production_control.bind_future_participant_identity_runtime_v1(text,uuid,uuid,uuid,text,uuid)'
    ) is null then
      raise exception using errcode = '55000',
        message = 'FUTURE_PARTICIPANT_IDENTITY_CAPABILITY_NOT_INSTALLED';
    end if;
    execute 'select production_control.bind_future_participant_identity_runtime_v1($1,$2,$3,$4,$5,$6)'
      using target_id, generation_id, authority_generation_id_value,
        admission_generation_id_value, actor_player, actor_auth;
    update production_control.future_tournament_catalog_v1 set
      lifecycle = 'ACTIVE', lifecycle_revision = next_revision,
      updated_by_player_id = actor_player,
      updated_by_auth_user_id = actor_auth,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    update production_control.current_tournament_pointer_v1 set
      tournament_id = target_id, tournament_year = catalog.tournament_year,
      pointer_revision = pointer.pointer_revision + 1,
      lifecycle_revision = next_revision,
      updated_by_player_id = actor_player,
      updated_by_auth_user_id = actor_auth,
      updated_at = pg_catalog.clock_timestamp()
    where scope_key = (resource_context->>'resource_id')
      and pointer_revision = previous_pointer_revision;
    if not found then
      raise exception using errcode = '40001',
        message = 'FUTURE_TOURNAMENT_POINTER_CAS_FAILED';
    end if;
    update production_control.future_annual_runtime_generations_v1 set
      generation_status = 'ACTIVE', activated_by_player_id = actor_player,
      activated_by_auth_user_id = actor_auth,
      activated_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp()
    where runtime_generation_id = generation_id
      and generation_status = 'PREPARED';
    update production_control.future_runtime_promotions_v2 set
      runtime_status = 'ACTIVE', updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    target_kind := 'ACTIVATION'; target_object := target_id;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Future tournament activated',
      'pointerRevision', pointer.pointer_revision + 1,
      'runtimeGenerationId', generation_id
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_TOURNAMENT_ACTIVATED',
      'action', action_value, 'tournamentId', target_id,
      'tournamentYear', catalog.tournament_year,
      'runtimeGenerationId', generation_id,
      'authorityGenerationId', authority_generation_id_value,
      'admissionGenerationId', admission_generation_id_value,
      'pointerRevision', pointer.pointer_revision + 1,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'idempotent', false
    );

  elsif action_value = 'CLOSE_TOURNAMENT' then
    select value.* into strict pointer
    from production_control.current_tournament_pointer_v1 value
    where value.scope_key = (resource_context->>'resource_id') for update;
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    prior_revision := catalog.lifecycle_revision;
    blockers := '[]'::jsonb;
    if pointer.tournament_id <> target_id or catalog.lifecycle <> 'ACTIVE' then
      blockers := blockers || pg_catalog.jsonb_build_array(
        'CURRENT_ACTIVE_TOURNAMENT_REQUIRED'
      );
    end if;
    if not exists (select 1 from scoring_authority.matches value
      where value.tournament_id = target_id)
       or exists (select 1 from scoring_authority.matches value
        where value.tournament_id = target_id
          and (value.status <> 'FINAL' or not value.scorecard_complete
            or value.unresolved_mutations <> 0)) then
      blockers := blockers || pg_catalog.jsonb_build_array(
        'ALL_MATCHES_FINAL_REQUIRED'
      );
    end if;
    if exists (select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = target_id and not exists (
        select 1 from scoring_authority.finalized_scorecard_snapshots final
        where final.match_id = match_value.match_id and final.state = 'CURRENT'
          and final.match_revision = match_value.match_revision
          and final.scoring_snapshot_id = match_value.scoring_snapshot_id
      )) then
      blockers := blockers || pg_catalog.jsonb_build_array(
        'FINAL_SCORECARD_SNAPSHOT_REQUIRED'
      );
    end if;
    if exists (select 1 from scoring_authority.scoring_ingress_leases value
      where value.tournament_id = target_id
        and value.expires_at > pg_catalog.clock_timestamp())
       or exists (select 1 from scoring_authority.google_outbox_events value
        where value.tournament_id = target_id
          and value.status in ('PENDING', 'PROCESSING', 'RETRYABLE'))
       or exists (select 1 from scoring_authority.scorecard_archive_jobs value
        where value.tournament_id = target_id
          and value.status in ('PENDING', 'PROCESSING', 'RETRYABLE')) then
      blockers := blockers || pg_catalog.jsonb_build_array(
        'SCORING_OR_ARCHIVE_QUEUE_UNRESOLVED'
      );
    end if;
    if exists (
      select 1 from scoring_authority.net_skins_v1_configuration_current cfg
      where cfg.tournament_id = target_id and cfg.state = 'CONFIGURED'
        and exists (select 1 from scoring_authority.rounds round_value
          where round_value.tournament_id = target_id and not exists (
            select 1 from scoring_authority.net_skins_v1_result_revisions result
            where result.tournament_id = target_id
              and result.round_number = round_value.round_number
              and result.result_state = 'OFFICIAL' and result.is_current
          ))
    ) or exists (
      select 1 from scoring_authority.calcutta_v1_current value
      where value.tournament_id = target_id
        and value.state not in ('NOT_CONFIGURED', 'OFFICIAL')
    ) then
      blockers := blockers || pg_catalog.jsonb_build_array(
        'CONFIGURED_SIDE_GAME_OFFICIAL_RESULT_REQUIRED'
      );
    end if;
    if expected_revision <> prior_revision
       or pg_catalog.jsonb_array_length(blockers) > 0 then
      raise exception using errcode = '40001',
        message = 'FUTURE_TOURNAMENT_CLOSE_BLOCKED',
        detail = blockers::text;
    end if;
    next_revision := prior_revision + 1;
    update production_control.future_tournament_catalog_v1 set
      lifecycle = 'CLOSED', lifecycle_revision = next_revision,
      updated_by_player_id = actor_player,
      updated_by_auth_user_id = actor_auth,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    update production_control.future_annual_runtime_generations_v1 set
      generation_status = 'CLOSED', closed_by_player_id = actor_player,
      closed_at = pg_catalog.clock_timestamp(),
      runtime_revision = runtime_revision + 1,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id and generation_status = 'ACTIVE';
    update production_control.future_runtime_promotions_v2 set
      runtime_status = 'CLOSED', updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    target_kind := 'CLOSE'; target_object := target_id;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Tournament closed', 'newScoringAllowed', false
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_TOURNAMENT_CLOSED',
      'action', action_value, 'tournamentId', target_id,
      'lifecycle', 'CLOSED', 'priorRevision', prior_revision,
      'nextRevision', next_revision, 'idempotent', false
    );

  elsif action_value = 'PREPARE_ARCHIVE_PLAN' then
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    prior_revision := coalesce((select pg_catalog.max(value.plan_revision)
      from production_control.future_archive_plans_v1 value
      where value.tournament_id = target_id), 0);
    if expected_revision <> prior_revision or catalog.lifecycle <> 'CLOSED' then
      raise exception using errcode = '40001',
        message = 'FUTURE_ARCHIVE_PLAN_PREDECESSOR_INVALID';
    end if;
    blockers := '[]'::jsonb;
    if exists (select 1 from scoring_authority.matches value
      where value.tournament_id = target_id and (
        value.status <> 'FINAL' or not value.scorecard_complete
      )) then blockers := blockers || pg_catalog.jsonb_build_array(
      'FINAL_MATCH_FACTS_INCOMPLETE'
    ); end if;
    if exists (select 1 from scoring_authority.scorecard_archive_checkpoints value
      where value.tournament_id = target_id and value.status <> 'VERIFIED') then
      blockers := blockers || pg_catalog.jsonb_build_array(
        'ROUND_SCORECARDS_ARCHIVE_INCOMPLETE'
      );
    end if;
    source_fingerprint := production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'contractVersion', 'production-future-archive-source-v1',
        'tournamentId', target_id,
        'tournament', (select pg_catalog.to_jsonb(value)
          from scoring_authority.tournaments value
          where value.tournament_id = target_id),
        'teams', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.team_side) from scoring_authority.teams value
          where value.tournament_id = target_id),
        'roster', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.player_id)
          from scoring_authority.tournament_players value
          where value.tournament_id = target_id),
        'rounds', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.round_number) from scoring_authority.rounds value
          where value.tournament_id = target_id),
        'matches', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.match_id) from scoring_authority.matches value
          where value.tournament_id = target_id),
        'finalizedScorecards', (select pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'matchId', value.match_id, 'matchRevision', value.match_revision,
            'snapshotRevision', value.snapshot_revision,
            'sourceFingerprint', value.source_fingerprint,
            'payloadHash', value.payload_hash
          ) order by value.match_id)
          from scoring_authority.finalized_scorecard_snapshots value
          where value.tournament_id = target_id and value.state = 'CURRENT')
      )
    );
    archive_fingerprint := production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'contractVersion', 'production-future-archive-plan-v1',
        'tournamentId', target_id,
        'lifecycleRevision', catalog.lifecycle_revision,
        'sourceFingerprint', source_fingerprint,
        'blockers', blockers,
        'actualHistoryPromotionInstalled', false
      )
    );
    next_revision := prior_revision + 1;
    insert into production_control.future_archive_plans_v1 (
      tournament_id, plan_revision, lifecycle_revision,
      source_fingerprint, archive_fingerprint, readiness_status,
      blocker_codes, created_by_player_id
    ) values (
      target_id, next_revision, catalog.lifecycle_revision,
      source_fingerprint, archive_fingerprint,
      case when pg_catalog.jsonb_array_length(blockers) = 0
        then 'READY' else 'BLOCKED' end,
      blockers, actor_player
    );
    target_kind := 'ARCHIVE_PLAN'; target_object := target_id;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Archive readiness plan prepared',
      'ready', pg_catalog.jsonb_array_length(blockers) = 0,
      'historyPromotionExecuted', false
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_ARCHIVE_PLAN_PREPARED',
      'action', action_value, 'tournamentId', target_id,
      'planRevision', next_revision,
      'readinessStatus', case when pg_catalog.jsonb_array_length(blockers) = 0
        then 'READY' else 'BLOCKED' end,
      'blockers', blockers, 'sourceFingerprint', source_fingerprint,
      'archiveFingerprint', archive_fingerprint,
      'historyPromotionExecuted', false,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'idempotent', false
    );

  elsif action_value = 'PREPARE_SCORING_CONTEXT' then
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    select value.* into strict match_value
    from scoring_authority.matches value
    where value.tournament_id = target_id
      and value.match_id = input->>'match_id' for update;
    select value.* into strict binding
    from production_control.future_runtime_match_bindings_v2 value
    where value.match_id = match_value.match_id for update;
    select value.* into strict detail
    from scoring_authority.tournament_setup_match_details_v1 value
    where value.match_id = match_value.match_id;
    select value.revision_id into strict current_handicap
    from scoring_authority.handicap_revision_current value
    where value.tournament_id = target_id;
    prior_revision := binding.runtime_revision;
    expected_count := case when match_value.format = 'SI' then 2 else 4 end;
    if expected_revision <> prior_revision
       or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
       or match_value.status <> 'UPCOMING' or match_value.match_revision <> 0
       or (select pg_catalog.count(*)
         from scoring_authority.match_participants value
         where value.match_id = match_value.match_id) <> expected_count
       or (select pg_catalog.count(*)
         from scoring_authority.tournament_setup_course_holes_v1 hole
         where hole.tournament_id = target_id
           and hole.course_id = detail.course_id
           and hole.tee_id = detail.tee_id) <> 18 then
      raise exception using errcode = '40001',
        message = 'FUTURE_SCORING_CONTEXT_PREDECESSOR_INVALID';
    end if;
    select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'hole_number', hole.hole_number, 'par', hole.par,
      'stroke_index', hole.stroke_index, 'yardage', hole.yardage
    ) order by hole.hole_number) into strict holes_value
    from scoring_authority.tournament_setup_course_holes_v1 hole
    where hole.tournament_id = target_id
      and hole.course_id = detail.course_id and hole.tee_id = detail.tee_id;
    context_value := production_control.future_handicap_match_context_v2(
      match_value.match_id, current_handicap
    );
    participant_manifest := context_value->'participant_configuration';
    preparation_fingerprint := production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'contractVersion', 'production-future-scoring-context-v1',
        'tournamentId', target_id, 'matchId', match_value.match_id,
        'round', match_value.round_number, 'format', match_value.format,
        'courseId', detail.course_id, 'teeId', detail.tee_id,
        'startingHole', detail.starting_hole,
        'holes', holes_value, 'participants', participant_manifest,
        'teams', context_value->'team_configuration',
        'handicapRevisionId', current_handicap,
        'setupRevision', detail.setup_revision,
        'runtimeRevision', binding.runtime_revision
      )
    );
    select coalesce(pg_catalog.max(value.snapshot_revision), 0) + 1
      into next_snapshot_revision
    from scoring_authority.scoring_snapshots value
    where value.match_id = match_value.match_id;
    next_snapshot_id := match_value.match_id || ':S' || next_snapshot_revision;
    next_snapshot_hash := production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'preparationFingerprint', preparation_fingerprint,
        'snapshotRevision', next_snapshot_revision,
        'participantConfiguration', participant_manifest,
        'teamConfiguration', context_value->'team_configuration'
      )
    );
    insert into scoring_authority.scoring_snapshots (
      snapshot_id, tournament_id, match_id, snapshot_revision,
      scoring_rules_version, format, handicap_allowance,
      course_id, tee, rating, slope, par, match_netting_baseline,
      hole_definitions, participant_configuration, team_configuration,
      effective_at, canonical_hash, handicap_revision_id
    ) select next_snapshot_id, target_id, match_value.match_id,
      next_snapshot_revision, 'production-scoring-rules-v1',
      match_value.format, round_value.handicap_allowance,
      detail.course_id, detail.tee_id, tee.rating, tee.slope, tee.par,
      'LOWEST_PLAYING_HANDICAP', holes_value, participant_manifest,
      context_value->'team_configuration', pg_catalog.clock_timestamp(),
      next_snapshot_hash, current_handicap
    from scoring_authority.rounds round_value
    join scoring_authority.tournament_setup_course_tees_v1 tee
      on tee.tournament_id = round_value.tournament_id
     and tee.course_id = detail.course_id and tee.tee_id = detail.tee_id
    where round_value.tournament_id = target_id
      and round_value.round_number = match_value.round_number;
    update scoring_authority.match_participants participant set
      tournament_handicap = (item->>'tournament_handicap')::numeric,
      handicap_index = (item->>'handicap_index')::numeric,
      course_handicap = (item->>'course_handicap')::numeric,
      playing_handicap = (item->>'playing_handicap')::numeric,
      final_strokes = (item->>'final_strokes')::integer,
      handicap_revision_id = current_handicap
    from pg_catalog.jsonb_array_elements(context_value->'participants') item
    where participant.match_id = match_value.match_id
      and participant.player_id = item->>'player_id';
    delete from scoring_authority.match_holes value
    where value.match_id = match_value.match_id;
    insert into scoring_authority.match_holes (
      match_id, hole_number, snapshot_id, stroke_index, par, yardage
    ) select match_value.match_id, (item->>'hole_number')::integer,
      next_snapshot_id, (item->>'stroke_index')::integer,
      (item->>'par')::integer, nullif(item->>'yardage', '')::integer
    from pg_catalog.jsonb_array_elements(holes_value) item;
    update scoring_authority.matches set
      scoring_snapshot_id = next_snapshot_id,
      scoring_locked = true, updated_at = pg_catalog.clock_timestamp()
    where match_id = match_value.match_id;
    next_revision := prior_revision + 1;
    update scoring_authority.tournament_setup_match_details_v1 set
      prepared_setup_revision = setup_revision,
      prepared_configuration_fingerprint = preparation_fingerprint,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = match_value.match_id;
    update production_control.future_runtime_match_bindings_v2 set
      runtime_revision = next_revision, runtime_state = 'PREPARED',
      configuration_fingerprint = preparation_fingerprint,
      updated_at = pg_catalog.clock_timestamp()
    where match_id = match_value.match_id;
    target_kind := 'SCORING_CONTEXT'; target_object := match_value.match_id;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Future scoring snapshot prepared',
      'matchId', match_value.match_id,
      'snapshotRevision', next_snapshot_revision,
      'scoringAccessGranted', false, 'scoreFactsChanged', false
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_SCORING_CONTEXT_PREPARED',
      'action', action_value, 'tournamentId', target_id,
      'matchId', match_value.match_id, 'snapshotId', next_snapshot_id,
      'snapshotRevision', next_snapshot_revision,
      'configurationFingerprint', preparation_fingerprint,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'scoringAccessGranted', false, 'idempotent', false
    );


  elsif action_value = 'STAGE_HANDICAPS' then
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    select value.* into strict promotion
    from production_control.future_runtime_promotions_v2 value
    where value.tournament_id = target_id;
    select coalesce(value.revision_number, 0), value.revision_id
      into prior_revision, current_handicap
    from scoring_authority.handicap_revision_current value
    where value.tournament_id = target_id;
    prior_revision := coalesce(prior_revision, 0);
    if expected_revision <> prior_revision
       or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
       or promotion.tournament_id is null
       or pg_catalog.jsonb_typeof(input->'entries') <> 'array'
       or pg_catalog.jsonb_array_length(input->'entries') < 1 then
      raise exception using errcode = '40001',
        message = 'FUTURE_HANDICAP_STAGE_PREDECESSOR_INVALID';
    end if;
    if (select pg_catalog.count(*)
      from pg_catalog.jsonb_array_elements(input->'entries')) <>
       (select pg_catalog.count(*)
        from scoring_authority.tournament_players value
        where value.tournament_id = target_id
          and value.participation_status = 'ACTIVE')
       or (select pg_catalog.count(distinct pg_catalog.upper(
          pg_catalog.btrim(item->>'player_id')))
        from pg_catalog.jsonb_array_elements(input->'entries') item) <>
         pg_catalog.jsonb_array_length(input->'entries')
       or exists (
         select 1 from pg_catalog.jsonb_array_elements(input->'entries') item
         where coalesce(item->>'player_id', '') !~
             '^[A-Za-z0-9][A-Za-z0-9_-]{1,31}$'
           or coalesce(item->>'tournament_handicap', '') !~
             '^-?[0-9]+(?:\.[0-9]+)?$'
           or not exists (
             select 1 from scoring_authority.tournament_players membership
             where membership.tournament_id = target_id
               and membership.player_id = pg_catalog.upper(
                 pg_catalog.btrim(item->>'player_id')
               )
               and membership.participation_status = 'ACTIVE'
           )
       ) then
      raise exception using errcode = '22023',
        message = 'FUTURE_HANDICAP_COMPLETE_ACTIVE_ROSTER_REQUIRED';
    end if;
    next_revision := coalesce((select pg_catalog.max(value.revision_number)
      from scoring_authority.handicap_revisions value
      where value.tournament_id = target_id), 0) + 1;
    handicap_revision_id_value := extensions.gen_random_uuid();
    manifest_fingerprint := production_control.future_runtime_hash_v2(
      (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'player_id', pg_catalog.upper(pg_catalog.btrim(item->>'player_id')),
        'tournament_handicap', (item->>'tournament_handicap')::numeric,
        'source_index', nullif(item->>'source_index', '')::numeric,
        'low_index', nullif(item->>'low_index', '')::numeric
      ) order by pg_catalog.upper(pg_catalog.btrim(item->>'player_id')))
      from pg_catalog.jsonb_array_elements(input->'entries') item)
    );
    insert into scoring_authority.handicap_revisions (
      revision_id, tournament_id, revision_number, status,
      effective_date, method, source_metadata, source_evidence_date,
      canonical_fingerprint, roster_fingerprint,
      predecessor_revision, predecessor_revision_id,
      context_contract_version, created_by, created_by_auth_user_id
    ) values (
      handicap_revision_id_value, target_id, next_revision, 'DRAFT',
      catalog.start_date,
      pg_catalog.btrim(coalesce(input->>'method', 'DIRECTOR_REVIEW')),
      pg_catalog.jsonb_build_object(
        'source', 'DIRECTOR_FUTURE_RUNTIME_V2',
        'sourceYear', input->>'source_year',
        'carryForwardApproved', false
      ), nullif(input->>'source_evidence_date', '')::date,
      manifest_fingerprint,
      production_control.handicap_v1_roster_fingerprint(target_id),
      prior_revision, current_handicap,
      'production-handicap-context-v1', actor_player, actor_auth
    );
    insert into scoring_authority.handicap_revision_entries (
      revision_id, tournament_id, player_id, tournament_handicap,
      source_index, low_index, source_metadata
    ) select handicap_revision_id_value, target_id,
      pg_catalog.upper(pg_catalog.btrim(item->>'player_id')),
      (item->>'tournament_handicap')::numeric,
      nullif(item->>'source_index', '')::numeric,
      nullif(item->>'low_index', '')::numeric,
      pg_catalog.jsonb_build_object('source', 'DIRECTOR_FUTURE_RUNTIME_V2')
    from pg_catalog.jsonb_array_elements(input->'entries') item;
    insert into scoring_authority.handicap_audit_events (
      tournament_id, revision_id, action, actor_player_id,
      actor_auth_user_id, operation_request_id, request_payload_hash,
      canonical_fingerprint, before_state, after_state
    ) values (
      target_id, handicap_revision_id_value, 'REVISION_STAGED', actor_player,
      actor_auth, request_id, database_hash, manifest_fingerprint,
      pg_catalog.jsonb_build_object('approvedRevision', prior_revision),
      pg_catalog.jsonb_build_object(
        'draftRevision', next_revision, 'entryCount',
          pg_catalog.jsonb_array_length(input->'entries')
      )
    );
    target_kind := 'HANDICAP';
    target_object := handicap_revision_id_value::text;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Future handicap revision staged',
      'revision', next_revision,
      'entryCount', pg_catalog.jsonb_array_length(input->'entries')
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_HANDICAPS_STAGED',
      'action', action_value, 'tournamentId', target_id,
      'revisionId', handicap_revision_id_value, 'revisionNumber', next_revision,
      'canonicalFingerprint', manifest_fingerprint,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'idempotent', false
    );

  elsif action_value = 'APPROVE_HANDICAPS' then
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    begin handicap_revision_id_value :=
      (input->>'handicap_revision_id')::uuid;
    exception when others then
      raise exception using errcode = '22023',
        message = 'FUTURE_HANDICAP_REVISION_ID_INVALID';
    end;
    select coalesce(value.revision_number, 0), value.revision_id
      into prior_revision, current_handicap
    from scoring_authority.handicap_revision_current value
    where value.tournament_id = target_id;
    prior_revision := coalesce(prior_revision, 0);
    if expected_revision <> prior_revision
       or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
       or not exists (
         select 1 from scoring_authority.handicap_revisions value
         where value.revision_id = handicap_revision_id_value
           and value.tournament_id = target_id and value.status = 'DRAFT'
           and value.predecessor_revision = prior_revision
       )
       or (select pg_catalog.count(*)
         from scoring_authority.handicap_revision_entries value
         where value.revision_id = handicap_revision_id_value) <>
         (select pg_catalog.count(*)
          from scoring_authority.tournament_players value
          where value.tournament_id = target_id
            and value.participation_status = 'ACTIVE') then
      raise exception using errcode = '40001',
        message = 'FUTURE_HANDICAP_APPROVAL_PREDECESSOR_INVALID';
    end if;
    if current_handicap is not null then
      update scoring_authority.handicap_revisions set
        status = 'SUPERSEDED', superseded_at = pg_catalog.clock_timestamp()
    where scoring_authority.handicap_revisions.revision_id = current_handicap;
    end if;
    update scoring_authority.handicap_revisions set
      status = 'APPROVED', approved_by = actor_player,
      approved_by_auth_user_id = actor_auth,
      approved_at = pg_catalog.clock_timestamp()
    where scoring_authority.handicap_revisions.revision_id =
      handicap_revision_id_value;
    select value.revision_number into strict next_revision
    from scoring_authority.handicap_revisions value
    where value.revision_id = handicap_revision_id_value;
    insert into scoring_authority.handicap_revision_current (
      tournament_id, revision_id, revision_number
    ) values (target_id, handicap_revision_id_value, next_revision)
    on conflict (tournament_id) do update set
      revision_id = excluded.revision_id,
      revision_number = excluded.revision_number,
      updated_at = pg_catalog.clock_timestamp();
    update scoring_authority.tournament_players membership set
      tournament_handicap = entry.tournament_handicap,
      handicap_revision_id = handicap_revision_id_value,
      updated_at = pg_catalog.clock_timestamp()
    from scoring_authority.handicap_revision_entries entry
    where entry.revision_id = handicap_revision_id_value
      and entry.tournament_id = target_id
      and membership.tournament_id = entry.tournament_id
      and membership.player_id = entry.player_id;
    -- A changed approved context invalidates only affected private, unstarted
    -- future snapshots.  Immutable snapshot rows remain as evidence.
    delete from scoring_authority.match_holes hole
    using scoring_authority.matches handicap_match
    where handicap_match.tournament_id = target_id
      and handicap_match.status = 'UPCOMING' and handicap_match.match_revision = 0
      and hole.match_id = handicap_match.match_id;
    update scoring_authority.matches set
      scoring_snapshot_id = null, scoring_locked = true,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id and status = 'UPCOMING'
      and match_revision = 0 and scoring_snapshot_id is not null;
    update scoring_authority.tournament_setup_match_details_v1 set
      prepared_setup_revision = null,
      prepared_configuration_fingerprint = null,
      updated_by_player_id = actor_player,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    update production_control.future_runtime_match_bindings_v2 set
      runtime_state = case when exists (
        select 1 from scoring_authority.match_participants participant
        where participant.match_id = future_runtime_match_bindings_v2.match_id
      ) then 'PAIRED' else 'CONFIGURED' end,
      runtime_revision = runtime_revision + 1,
      configuration_fingerprint = null,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    update scoring_authority.match_participants participant set
      tournament_handicap = entry.tournament_handicap,
      handicap_index = entry.tournament_handicap,
      handicap_revision_id = handicap_revision_id_value
    from scoring_authority.handicap_revision_entries entry,
      scoring_authority.matches handicap_match
    where handicap_match.match_id = participant.match_id
      and handicap_match.tournament_id = target_id
      and entry.revision_id = handicap_revision_id_value
      and entry.player_id = participant.player_id;
    insert into scoring_authority.handicap_audit_events (
      tournament_id, revision_id, action, actor_player_id,
      actor_auth_user_id, operation_request_id, request_payload_hash,
      canonical_fingerprint, before_state, after_state
    ) select target_id, value.revision_id, 'REVISION_APPROVED', actor_player,
      actor_auth, request_id, database_hash, value.canonical_fingerprint,
      pg_catalog.jsonb_build_object('approvedRevision', prior_revision),
      pg_catalog.jsonb_build_object('approvedRevision', next_revision)
    from scoring_authority.handicap_revisions value
    where value.revision_id = handicap_revision_id_value;
    target_kind := 'HANDICAP';
    target_object := handicap_revision_id_value::text;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Future handicap revision approved',
      'revision', next_revision, 'scoringFactsChanged', false
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_HANDICAPS_APPROVED',
      'action', action_value, 'tournamentId', target_id,
      'revisionId', handicap_revision_id_value,
      'revisionNumber', next_revision,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'snapshotsInvalidated', true, 'scoreFactsChanged', false,
      'idempotent', false
    );


  elsif action_value = 'PROMOTE_RUNTIME_STRUCTURE' then
    if target_id = '' then
      raise exception using errcode = '22023',
        message = 'FUTURE_RUNTIME_TARGET_REQUIRED';
    end if;
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id for update;
    select value.* into strict pointer
    from production_control.current_tournament_pointer_v1 value
    where value.scope_key = (resource_context->>'resource_id');
    select value.* into strict resource
    from production_control.future_tournament_resources_v1 value
    where value.tournament_id = target_id;
    prior_revision := coalesce((select value.promotion_revision
      from production_control.future_runtime_promotions_v2 value
      where value.tournament_id = target_id), 0);
    if expected_revision <> prior_revision
       or pointer.tournament_id = target_id
       or target_id = '2026'
       or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
       or catalog.setup_revision <= 0
       or resource.source_workbook_id is null
       or resource.project_ref is distinct from
         (select project_ref from production_control.canonical_resource_v1
          where resource_id = (resource_context->>'resource_id'))
       or resource.project_url is distinct from
         (select project_url from production_control.canonical_resource_v1
          where resource_id = (resource_context->>'resource_id')) then
      raise exception using errcode = '40001',
        message = 'FUTURE_RUNTIME_PROMOTION_PREDECESSOR_INVALID';
    end if;
    if prior_revision > 0 then
      raise exception using errcode = '55000',
        message = 'FUTURE_RUNTIME_ALREADY_PROMOTED';
    end if;
    if exists (select 1 from scoring_authority.tournaments value
      where value.tournament_id = target_id)
       or (select pg_catalog.count(*)
        from production_control.future_tournament_teams_v1 value
        where value.tournament_id = target_id and value.active) <> 2
       or not exists (select 1
        from production_control.future_tournament_roster_v1 value
        where value.tournament_id = target_id
          and value.participation_status = 'ACTIVE')
       or exists (select 1
        from production_control.future_tournament_roster_v1 value
        where value.tournament_id = target_id
          and value.participation_status = 'ACTIVE'
          and (value.team_id is null or value.team_side is null))
       or not exists (select 1
        from production_control.future_tournament_rounds_v1 value
        where value.tournament_id = target_id)
       or not exists (select 1
        from production_control.future_match_definitions_v1 value
        where value.tournament_id = target_id) then
      raise exception using errcode = '55000',
        message = 'FUTURE_RUNTIME_STAGED_STRUCTURE_INCOMPLETE';
    end if;
    manifest_fingerprint := production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'contractVersion', 'production-future-runtime-promotion-v2',
        'tournamentId', target_id, 'year', catalog.tournament_year,
        'setupRevision', catalog.setup_revision,
        'teams', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.team_side)
          from production_control.future_tournament_teams_v1 value
          where value.tournament_id = target_id),
        'roster', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.player_id)
          from production_control.future_tournament_roster_v1 value
          where value.tournament_id = target_id),
        'rounds', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.round_number)
          from production_control.future_tournament_rounds_v1 value
          where value.tournament_id = target_id),
        'courses', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.round_number)
          from production_control.future_tournament_course_references_v1 value
          where value.tournament_id = target_id),
        'matches', (select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(value)
          order by value.round_number, value.match_number)
          from production_control.future_match_definitions_v1 value
          where value.tournament_id = target_id)
      )
    );
    insert into scoring_authority.tournaments (
      tournament_id, tournament_year, name, source_workbook_id,
      scoring_authority
    ) values (
      target_id, catalog.tournament_year, catalog.tournament_name,
      resource.source_workbook_id, 'SUPABASE'
    );
    insert into scoring_authority.teams (
      tournament_id, team_id, team_side, name, source_payload
    ) select target_id, value.team_id, value.team_side, value.team_name,
      pg_catalog.jsonb_build_object(
        'futureRuntimePromotion', true,
        'captainPlayerId', value.captain_player_id
      )
    from production_control.future_tournament_teams_v1 value
    where value.tournament_id = target_id and value.active;
    insert into scoring_authority.tournament_players (
      tournament_id, player_id, team_id, team_side,
      participation_status, source_roster_key, source_payload
    ) select target_id, value.player_id, value.team_id, value.team_side,
      value.participation_status,
      target_id || ':' || value.player_id,
      pg_catalog.jsonb_build_object('futureRuntimePromotion', true)
    from production_control.future_tournament_roster_v1 value
    where value.tournament_id = target_id
      and value.team_id is not null and value.team_side is not null;
    insert into scoring_authority.rounds (
      tournament_id, round_number, format, name, handicap_allowance,
      status, source_payload
    ) select target_id, value.round_number, value.format, value.round_name,
      value.handicap_allowance, 'UPCOMING',
      pg_catalog.jsonb_build_object('futureRuntimePromotion', true)
    from production_control.future_tournament_rounds_v1 value
    where value.tournament_id = target_id;
    insert into production_control.tournament_setup_context_v1 (
      tournament_id, contract_version, revision,
      updated_by_player_id, updated_by_auth_user_id
    ) values (
      target_id, 'production-tournament-setup-v1', catalog.setup_revision,
      actor_player, actor_auth
    );
    insert into scoring_authority.tournament_setup_operational_v1 (
      tournament_id, destination, start_date, end_date, timezone,
      operational_status, setup_revision, updated_by_player_id
    ) values (
      target_id, catalog.destination, catalog.start_date, catalog.end_date,
      catalog.timezone, 'UPCOMING', catalog.setup_revision, actor_player
    );
    insert into scoring_authority.tournament_setup_team_details_v1 (
      tournament_id, team_id, captain_player_id, setup_revision,
      updated_by_player_id
    ) select target_id, value.team_id, value.captain_player_id,
      catalog.setup_revision, actor_player
    from production_control.future_tournament_teams_v1 value
    where value.tournament_id = target_id and value.active;
    insert into scoring_authority.tournament_setup_round_details_v1 (
      tournament_id, round_number, team_size, points_available,
      display_order, setup_revision, updated_by_player_id
    ) select target_id, value.round_number, value.team_size,
      value.points_available, value.round_number, catalog.setup_revision,
      actor_player
    from production_control.future_tournament_rounds_v1 value
    where value.tournament_id = target_id;
    insert into scoring_authority.tournament_setup_course_tees_v1 (
      tournament_id, course_id, tee_id, display_name, location,
      rating, slope, par, setup_revision, updated_by_player_id
    ) select distinct target_id, source.course_id, source.tee_id,
      source.display_name, source.location, source.rating, source.slope,
      source.par, catalog.setup_revision, actor_player
    from (
      select reference.tournament_id, existing.course_id, existing.tee_id,
        existing.display_name, existing.location, existing.rating,
        existing.slope, existing.par
      from production_control.future_tournament_course_references_v1 reference
      join scoring_authority.tournament_setup_course_tees_v1 existing
        on existing.tournament_id = reference.source_tournament_id
       and existing.course_id = reference.course_id
       and existing.tee_id = reference.tee_id
      where reference.reference_status = 'EXISTING_REFERENCE'
      union all
      select reference.tournament_id, context.course_id, context.tee_id,
        global_course.display_name, global_course.location, context.rating,
        context.slope, context.par
      from production_control.future_tournament_course_references_v1 reference
      join scoring_authority.global_course_tee_contexts_v1 context
        on context.course_id = reference.course_id
       and context.tee_id = reference.tee_id
       and context.context_revision = reference.source_setup_revision
      join scoring_authority.global_course_catalog_v1 global_course
        on global_course.course_id = context.course_id
       and global_course.catalog_status = 'ACTIVE'
      where reference.reference_status = 'GLOBAL_COURSE_CONTEXT'
    ) source
    where source.tournament_id = target_id;
    insert into scoring_authority.tournament_setup_course_holes_v1 (
      tournament_id, course_id, tee_id, hole_number, par,
      stroke_index, yardage, setup_revision
    ) select target_id, source.course_id, source.tee_id,
      source.hole_number, source.par, source.stroke_index, source.yardage,
      catalog.setup_revision
    from (
      select reference.tournament_id, existing.course_id, existing.tee_id,
        existing.hole_number, existing.par, existing.stroke_index,
        existing.yardage
      from production_control.future_tournament_course_references_v1 reference
      join scoring_authority.tournament_setup_course_holes_v1 existing
        on existing.tournament_id = reference.source_tournament_id
       and existing.course_id = reference.course_id
       and existing.tee_id = reference.tee_id
      where reference.reference_status = 'EXISTING_REFERENCE'
      union all
      select reference.tournament_id, context.course_id, context.tee_id,
        context.hole_number, context.par, context.stroke_index,
        context.yardage
      from production_control.future_tournament_course_references_v1 reference
      join scoring_authority.global_course_hole_contexts_v1 context
        on context.course_id = reference.course_id
       and context.tee_id = reference.tee_id
       and context.context_revision = reference.source_setup_revision
      where reference.reference_status = 'GLOBAL_COURSE_CONTEXT'
    ) source
    where source.tournament_id = target_id;
    insert into scoring_authority.tournament_setup_round_courses_v1 (
      tournament_id, round_number, course_id, tee_id,
      setup_revision, updated_by_player_id
    ) select target_id, value.round_number, value.course_id, value.tee_id,
      catalog.setup_revision, actor_player
    from production_control.future_tournament_course_references_v1 value
    where value.tournament_id = target_id;
    insert into production_control.future_runtime_promotions_v2 (
      tournament_id, contract_version, promotion_revision,
      source_setup_revision, promoted_manifest_fingerprint,
      runtime_status, promoted_by_player_id, promoted_by_auth_user_id
    ) values (
      target_id, 'production-future-runtime-activation-v2', 1,
      catalog.setup_revision, manifest_fingerprint, 'PROMOTED',
      actor_player, actor_auth
    );
    insert into scoring_authority.matches (
      match_id, tournament_id, round_number, format, scoring_snapshot_id,
      status, scoring_locked
    ) select value.match_id, target_id, value.round_number, value.format,
      null, 'UPCOMING', true
    from production_control.future_match_definitions_v1 value
    where value.tournament_id = target_id;
    insert into production_control.future_runtime_match_bindings_v2 (
      tournament_id, match_id, structural_setup_revision,
      runtime_revision, runtime_state
    ) select target_id, value.match_id, value.setup_revision, 1, 'PROMOTED'
    from production_control.future_match_definitions_v1 value
    where value.tournament_id = target_id;
    -- Certification has no legacy presentation import. Derive the required
    -- display identity from the same promoted canonical setup facts atomically.
    -- No score, readiness state or archive certificate is manufactured here.
    if resource_context->>'resource_class'='CERTIFICATION' then
      insert into scoring_authority.game_center_presentations(
        match_id,tournament_id,course_name,course_yardage,display_match_number,match_sort_order,
        tournament_location,tournament_status,tournament_time_zone,source_workbook_id,
        source_payload_hash,imported_by)
      select definition.match_id,target_id,tee.display_name,
        coalesce((select sum(h.yardage)::text from scoring_authority.tournament_setup_course_holes_v1 h
          where h.tournament_id=target_id and h.course_id=assignment.course_id and h.tee_id=assignment.tee_id),''),
        definition.match_number::text,row_number() over(order by definition.round_number,definition.match_number)::integer,
        coalesce(catalog.destination,''),'UPCOMING',catalog.timezone,resource.source_workbook_id,
        production_control.future_runtime_hash_v2(jsonb_build_object('contract','canonical-promotion-presentation-v1',
          'match',to_jsonb(definition),'course',to_jsonb(assignment),'tee',to_jsonb(tee),
          'timezone',catalog.timezone,'resource_id',resource_context->>'resource_id')),
        'certification-canonical-promotion-v1'
      from production_control.future_match_definitions_v1 definition
      join scoring_authority.tournament_setup_round_courses_v1 assignment
        on assignment.tournament_id=definition.tournament_id and assignment.round_number=definition.round_number
      join scoring_authority.tournament_setup_course_tees_v1 tee on tee.tournament_id=assignment.tournament_id
        and tee.course_id=assignment.course_id and tee.tee_id=assignment.tee_id
      where definition.tournament_id=target_id;
      if (select count(*) from scoring_authority.game_center_presentations where tournament_id=target_id)
        <> (select count(*) from scoring_authority.matches where tournament_id=target_id) then
        raise exception using errcode='55000',message='CERTIFICATION_PROMOTION_PRESENTATION_INCOMPLETE';end if;
    end if;
    -- Google runtime retired: external delivery is not canonical authority.
    -- Google runtime retired: external delivery is not canonical authority.
    update production_control.future_tournament_catalog_v1 set
      lifecycle = 'CONFIGURING', lifecycle_revision = lifecycle_revision + 1,
      readiness_fingerprint = null, readiness_setup_revision = null,
      updated_by_player_id = actor_player,
      updated_by_auth_user_id = actor_auth,
      updated_at = pg_catalog.clock_timestamp()
    where tournament_id = target_id;
    prior_revision := 0;
    next_revision := 1;
    target_kind := 'RUNTIME';
    target_object := target_id;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', 'Future tournament structure promoted',
      'runtimeMatches', (select pg_catalog.count(*)
        from scoring_authority.matches where tournament_id = target_id),
      'scoringAccessCreated', false, 'scoresCreated', false
    );
    result_value := pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_FUTURE_RUNTIME_PROMOTED',
      'action', action_value, 'tournamentId', target_id,
      'promotionRevision', 1, 'manifestFingerprint', manifest_fingerprint,
      'priorRevision', prior_revision, 'nextRevision', next_revision,
      'scoringAccessCreated', false, 'scoreFactsCreated', false,
      'idempotent', false
    );

  end if;

  if result_value is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_RUNTIME_RESULT_REQUIRED';
  end if;
  insert into production_control.future_runtime_audit_events_v2 (
    tournament_id, action, target_kind, target_id, actor_player_id,
    prior_revision, next_revision, operation_request_id, result, safe_metadata
  ) values (
    nullif(target_id, ''), action_value, target_kind,
    coalesce(target_object, target_id, 'GLOBAL'), actor_player,
    prior_revision, next_revision, request_id,
    case when changed_value then 'CHANGED' else 'NO_CHANGE' end,
    safe_metadata
  );
  insert into production_control.future_runtime_operation_receipts_v2 (
    tournament_id, action, operation_request_id,
    declared_request_payload_hash, database_request_payload_hash,
    actor_player_id, actor_auth_user_id, prior_revision, next_revision,
    response
  ) values (
    nullif(target_id, ''), action_value, request_id,
    declared_hash, database_hash, actor_player, actor_auth,
    prior_revision, next_revision, result_value
  );
  return result_value;
end;

$_$;


ALTER FUNCTION production_control.canonical_mutate_future_runtime_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_mutate_future_year_administration_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_mutate_future_year_administration_v2(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  action_value text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'operation', input->>'action', ''
  )));
  target_id text := pg_catalog.btrim(coalesce(
    input->>'target_tournament_id', ''
  ));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  operation_request uuid;
  receipt_uuid uuid := extensions.gen_random_uuid();
  expected_revision bigint;
  current_revision bigint;
  next_revision bigint;
  declared_hash text := pg_catalog.lower(coalesce(
    input->>'request_payload_hash', ''
  ));
  database_hash text;
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason', ''));
  receipt production_control.future_year_operation_receipts_v1%rowtype;
  tournament_value production_control.future_tournament_catalog_v1%rowtype;
  response_value jsonb;
  readiness_value jsonb;
  safe_metadata jsonb := '{}'::jsonb;
  target_kind text := 'TOURNAMENT';
  audit_target text;
  creation_mode text;
  clone_source text;
  tournament_year integer;
  name_value text;
  destination_value text;
  start_value date;
  end_value date;
  timezone_value text;
  item jsonb;
  item_player text;
  item_team text;
  item_side integer;
  target_team text;
  target_side integer;
  target_round integer;
  target_format text;
  team_size_value integer;
  points_value numeric;
  allowance_value numeric;
  target_course text;
  target_tee text;
  source_setup bigint;
  match_count_value integer;
  generated_count integer := 0;
  summary_value text;
begin
  perform production_control.assert_canonical_annual_context_v2(
    input, context, action_value in ('CREATE_TOURNAMENT', 'MARK_READY')
  );
  if action_value in ('ACTIVATE_TOURNAMENT', 'ACTIVATE') then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'FUTURE_TOURNAMENT_ACTIVATION_NOT_INSTALLED'
    );
  elsif action_value in ('CLOSE_TOURNAMENT', 'CLOSE') then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'FUTURE_TOURNAMENT_CLOSE_NOT_INSTALLED'
    );
  elsif action_value in ('ARCHIVE_TOURNAMENT', 'ARCHIVE') then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'FUTURE_TOURNAMENT_ARCHIVE_NOT_INSTALLED'
    );
  elsif action_value in ('CREATE_COURSE', 'ADD_COURSE') then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'GLOBAL_COURSE_CREATION_NOT_INSTALLED'
    );
  end if;
  if action_value not in (
       'CREATE_TOURNAMENT', 'UPDATE_TOURNAMENT', 'CONFIGURE_TEAM',
       'REPLACE_ROSTER', 'CONFIGURE_ROUND', 'ASSIGN_COURSE',
       'GENERATE_MATCH_STRUCTURE', 'MARK_READY'
     )
     or target_id !~ '^[0-9]{4}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_revision', '') !~ '^[0-9]+$' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PRODUCTION_FUTURE_YEAR_INPUT_INVALID'
    );
  end if;
  begin
    actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
    operation_request := (input->>'operation_request_id')::uuid;
    expected_revision := (input->>'expected_revision')::bigint;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PRODUCTION_FUTURE_YEAR_INPUT_INVALID'
    );
  end;
  perform production_control.assert_access_governance_safe_reason_v1(
    reason_value
  );
  database_hash := production_control.future_year_hash_v1(
    input - 'request_payload_hash'
  );
  select value.* into receipt
  from production_control.future_year_operation_receipts_v1 value
  where value.target_tournament_id = target_id
    and value.action = action_value
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.database_request_payload_hash = database_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PRODUCTION_FUTURE_YEAR_IDEMPOTENCY_CONFLICT'
    );
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-future-year-administration-v1:' || target_id, 0
  ));
  select value.* into receipt
  from production_control.future_year_operation_receipts_v1 value
  where value.target_tournament_id = target_id
    and value.action = action_value
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.database_request_payload_hash = database_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PRODUCTION_FUTURE_YEAR_IDEMPOTENCY_CONFLICT'
    );
  end if;

  if action_value = 'CREATE_TOURNAMENT' then
    if expected_revision <> 0 or target_id = '2026'
       or exists (
         select 1
         from production_control.future_tournament_catalog_v1 value
         where value.tournament_id = target_id
       ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'FUTURE_TOURNAMENT_CREATE_PREDECESSOR_INVALID'
      );
    end if;
    begin
      -- Annual CREATE v1: tournament_year is current authorization scope.
      -- The future year is explicit target metadata, never a scope override.
      if pg_catalog.jsonb_typeof(input->'target_tournament_year') is distinct from 'number'
         or coalesce(input->>'target_tournament_year', '') !~ '^[0-9]{4}$' then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TOURNAMENT_METADATA_INVALID'
        );
      end if;
      tournament_year := (input->>'target_tournament_year')::integer;
      start_value := nullif(input->>'start_date', '')::date;
      end_value := nullif(input->>'end_date', '')::date;
    exception when others then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'FUTURE_TOURNAMENT_METADATA_INVALID'
      );
    end;
    name_value := pg_catalog.btrim(coalesce(
      input->>'tournament_name', ''
    ));
    destination_value := nullif(pg_catalog.btrim(coalesce(
      input->>'destination', ''
    )), '');
    timezone_value := nullif(pg_catalog.btrim(coalesce(
      input->>'time_zone', input->>'timezone', ''
    )), '');
    creation_mode := pg_catalog.upper(pg_catalog.btrim(coalesce(
      input->>'creation_mode', 'BLANK'
    )));
    clone_source := nullif(pg_catalog.btrim(coalesce(
      input->>'clone_source_tournament_id', ''
    )), '');
    if tournament_year <= (input->>'tournament_year')::integer
       or tournament_year > 2200 or target_id <> tournament_year::text
       or name_value = '' or pg_catalog.length(name_value) > 180
       or destination_value is null or start_value is null or end_value is null
       or start_value > end_value or timezone_value is null
       or not exists (
         select 1 from pg_catalog.pg_timezone_names zone
         where zone.name = timezone_value
       )
       or creation_mode not in ('BLANK', 'CLONE_STRUCTURE')
       or (creation_mode = 'CLONE_STRUCTURE' and clone_source <> '2026')
       or (creation_mode = 'BLANK' and clone_source is not null) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'FUTURE_TOURNAMENT_METADATA_INVALID'
      );
    end if;
    insert into production_control.future_tournament_catalog_v1 (
      tournament_id, tournament_year, contract_version, tournament_name,
      destination, start_date, end_date, timezone, lifecycle,
      lifecycle_revision, setup_revision, creation_mode,
      clone_source_tournament_id, created_by_player_id,
      created_by_auth_user_id, updated_by_player_id,
      updated_by_auth_user_id, source_manifest
    ) values (
      target_id, tournament_year,
      'production-future-year-administration-v1', name_value,
      destination_value, start_value, end_value, timezone_value, 'DRAFT',
      1, 1, creation_mode, clone_source, actor_player, actor_auth,
      actor_player, actor_auth, pg_catalog.jsonb_build_object(
        'cloneContractVersion', case when creation_mode = 'CLONE_STRUCTURE'
          then 'production-future-structure-clone-v1' else null end,
        'allowlistedDomains', case when creation_mode = 'CLONE_STRUCTURE'
          then pg_catalog.jsonb_build_array('TEAMS', 'ROUNDS',
            'COURSE_REFERENCES') else '[]'::jsonb end,
        'forbiddenFactsCopied', false
      )
    );
    insert into production_control.future_tournament_resources_v1 (
      tournament_id, project_ref, project_url, source_workbook_id,
      resource_status, resource_revision, google_compatibility_policy,
      updated_by_player_id
    )
    select target_id, scope.project_ref, scope.project_url, scope.provenance_id,
      'CURRENT_RESOURCE_BOUND', 1, 'RETIRED', actor_player
    from production_control.canonical_resource_v1 scope
    where scope.resource_id = context->>'resource_id';
    if creation_mode = 'CLONE_STRUCTURE' then
      insert into production_control.future_tournament_teams_v1 (
        tournament_id, team_id, team_side, team_name, captain_player_id,
        active, setup_revision, updated_by_player_id
      )
      select target_id, team.team_id, team.team_side, team.name, null,
        true, 1, actor_player
      from scoring_authority.teams team
      where team.tournament_id = '2026';
      insert into production_control.future_tournament_rounds_v1 (
        tournament_id, round_number, round_name, format, team_size,
        points_available, handicap_allowance, setup_revision,
        updated_by_player_id
      )
      select target_id, round_value.round_number, round_value.name,
        round_value.format,
        case when round_value.format = 'SI' then 1 else 2 end,
        coalesce(detail.points_available, 0),
        coalesce(round_value.handicap_allowance, 1), 1, actor_player
      from scoring_authority.rounds round_value
      left join scoring_authority.tournament_setup_round_details_v1 detail
        on detail.tournament_id = round_value.tournament_id
       and detail.round_number = round_value.round_number
      where round_value.tournament_id = '2026';
      insert into production_control.future_tournament_course_references_v1 (
        tournament_id, round_number, course_id, tee_id,
        source_tournament_id, source_round_number, source_setup_revision,
        setup_revision, updated_by_player_id
      )
      select target_id, assignment.round_number, assignment.course_id,
        assignment.tee_id, '2026', assignment.round_number,
        assignment.setup_revision, 1, actor_player
      from scoring_authority.tournament_setup_round_courses_v1 assignment
      where assignment.tournament_id = '2026'
        and exists (
          select 1
          from production_control.future_tournament_rounds_v1 target_round_value
          where target_round_value.tournament_id = target_id
            and target_round_value.round_number = assignment.round_number
        );
    end if;
    current_revision := 0;
    next_revision := 1;
    target_kind := 'TOURNAMENT';
    audit_target := target_id;
    summary_value := case when creation_mode = 'CLONE_STRUCTURE'
      then 'Future tournament Draft created from an allowlisted structure clone.'
      else 'Blank future tournament Draft created.' end;
    safe_metadata := pg_catalog.jsonb_build_object(
      'summary', summary_value, 'creationMode', creation_mode,
      'forbiddenFactsCopied', false, 'scoringFactsCreated', false,
      'membershipCopied', false, 'identityCopied', false
    );
  else
    select value.* into tournament_value
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = target_id
    for update;
    if tournament_value.tournament_id is null then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'FUTURE_TOURNAMENT_NOT_FOUND'
      );
    end if;
    if tournament_value.lifecycle not in ('DRAFT', 'CONFIGURING')
       or target_id = '2026' then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'FUTURE_TOURNAMENT_STRUCTURE_LOCKED'
      );
    end if;
    current_revision := tournament_value.setup_revision;
    if expected_revision <> current_revision then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'FUTURE_TOURNAMENT_REVISION_STALE',
        'expectedRevision', current_revision
      );
    end if;
    next_revision := current_revision + 1;

    if action_value = 'UPDATE_TOURNAMENT' then
      begin
        start_value := nullif(input->>'start_date', '')::date;
        end_value := nullif(input->>'end_date', '')::date;
      exception when others then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TOURNAMENT_METADATA_INVALID'
        );
      end;
      name_value := pg_catalog.btrim(coalesce(
        input->>'tournament_name', ''
      ));
      destination_value := nullif(pg_catalog.btrim(coalesce(
        input->>'destination', ''
      )), '');
      timezone_value := nullif(pg_catalog.btrim(coalesce(
        input->>'time_zone', input->>'timezone', ''
      )), '');
      if name_value = '' or destination_value is null
         or start_value is null or end_value is null or start_value > end_value
         or timezone_value is null or not exists (
           select 1 from pg_catalog.pg_timezone_names zone
           where zone.name = timezone_value
         ) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TOURNAMENT_METADATA_INVALID'
        );
      end if;
      update production_control.future_tournament_catalog_v1 value set
        tournament_name = name_value,
        destination = destination_value,
        start_date = start_value, end_date = end_value,
        timezone = timezone_value
      where value.tournament_id = target_id;
      target_kind := 'TOURNAMENT';
      audit_target := target_id;
      summary_value := 'Future tournament operational details updated.';
    elsif action_value = 'CONFIGURE_TEAM' then
      target_team := pg_catalog.upper(pg_catalog.btrim(coalesce(
        input->>'team_id', ''
      )));
      name_value := pg_catalog.btrim(coalesce(input->>'team_name', ''));
      begin
        target_side := (input->>'team_side')::integer;
      exception when others then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TEAM_INPUT_INVALID'
        );
      end;
      item_player := nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(
        input->>'captain_player_id', ''
      ))), '');
      if target_team !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'
         or target_side not in (1, 2) or name_value = '' then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TEAM_CAPTAIN_OR_INPUT_INVALID'
        );
      end if;
      if exists (
        select 1 from production_control.future_tournament_teams_v1 team
        where team.tournament_id = target_id and team.team_id = target_team
          and team.team_side <> target_side
      ) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TEAM_SIDE_IMMUTABLE'
        );
      end if;
      if exists (
        select 1 from production_control.future_tournament_teams_v1 team
        where team.tournament_id = target_id
          and team.team_side = target_side and team.team_id <> target_team
      ) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TEAM_SIDE_ALREADY_ASSIGNED'
        );
      end if;
      if item_player is not null and not exists (
        select 1 from production_control.future_tournament_roster_v1 roster
        where roster.tournament_id = target_id
          and roster.player_id = item_player
          and roster.team_id = target_team
          and roster.team_side = target_side
          and roster.participation_status = 'ACTIVE'
      ) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TEAM_CAPTAIN_OR_INPUT_INVALID'
        );
      end if;
      insert into production_control.future_tournament_teams_v1 (
        tournament_id, team_id, team_side, team_name, captain_player_id,
        active, setup_revision, updated_by_player_id
      ) values (
        target_id, target_team, target_side, name_value, item_player,
        coalesce((input->>'active')::boolean, true),
        next_revision, actor_player
      ) on conflict (tournament_id, team_id) do update set
        team_side = excluded.team_side, team_name = excluded.team_name,
        captain_player_id = excluded.captain_player_id,
        active = excluded.active, setup_revision = excluded.setup_revision,
        updated_by_player_id = excluded.updated_by_player_id,
        updated_at = pg_catalog.clock_timestamp();
      target_kind := 'TEAM';
      audit_target := target_team;
      summary_value := 'Future tournament team configuration updated.';
    elsif action_value = 'REPLACE_ROSTER' then
      if pg_catalog.jsonb_typeof(input->'roster') is distinct from 'array'
         or pg_catalog.jsonb_array_length(input->'roster') > 200
         or exists (
           select 1 from (
             select pg_catalog.upper(pg_catalog.btrim(value->>'player_id')) id,
               pg_catalog.count(*)
             from pg_catalog.jsonb_array_elements(input->'roster') value
             group by 1 having pg_catalog.count(*) > 1
           ) duplicate
         ) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_ROSTER_INPUT_INVALID'
        );
      end if;
      for item in select value
        from pg_catalog.jsonb_array_elements(input->'roster') value
      loop
        item_player := pg_catalog.upper(pg_catalog.btrim(coalesce(
          item->>'player_id', ''
        )));
        item_team := nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(
          item->>'team_id', ''
        ))), '');
        if item_player !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
           or not exists (
             select 1 from scoring_authority.players player
             where player.player_id = item_player
               and production_control.access_governance_global_status_v1(
                 player.player_id
               ) = 'ACTIVE'
           )
           or pg_catalog.upper(pg_catalog.btrim(coalesce(
             item->>'participation_status', 'ACTIVE'
           ))) not in ('ACTIVE', 'INACTIVE', 'WITHDRAWN') then
          return pg_catalog.jsonb_build_object(
            'ok', false, 'code', 'FUTURE_ROSTER_PLAYER_INVALID'
          );
        end if;
        if item_team is not null then
          select team.team_side into item_side
          from production_control.future_tournament_teams_v1 team
          where team.tournament_id = target_id
            and team.team_id = item_team and team.active;
          if item_side is null
             or (item ? 'team_side'
               and (item->>'team_side')::integer <> item_side) then
            return pg_catalog.jsonb_build_object(
              'ok', false, 'code', 'FUTURE_ROSTER_TEAM_INVALID'
            );
          end if;
        else
          item_side := null;
        end if;
      end loop;
      delete from production_control.future_tournament_roster_v1 roster
      where roster.tournament_id = target_id;
      for item in select value
        from pg_catalog.jsonb_array_elements(input->'roster') value
      loop
        item_player := pg_catalog.upper(pg_catalog.btrim(item->>'player_id'));
        item_team := nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(
          item->>'team_id', ''
        ))), '');
        select team.team_side into item_side
        from production_control.future_tournament_teams_v1 team
        where team.tournament_id = target_id and team.team_id = item_team;
        insert into production_control.future_tournament_roster_v1 (
          tournament_id, player_id, team_id, team_side,
          participation_status, setup_revision, updated_by_player_id
        ) values (
          target_id, item_player, item_team, item_side,
          pg_catalog.upper(pg_catalog.btrim(coalesce(
            item->>'participation_status', 'ACTIVE'
          ))), next_revision, actor_player
        );
      end loop;
      target_kind := 'ROSTER';
      audit_target := target_id;
      summary_value := 'Future tournament roster selection replaced atomically.';
      safe_metadata := pg_catalog.jsonb_build_object(
        'rosterCount', pg_catalog.jsonb_array_length(input->'roster'),
        'identityCopied', false, 'authUsersCreated', false
      );
    elsif action_value = 'CONFIGURE_ROUND' then
      begin
        target_round := (input->>'round_number')::integer;
        team_size_value := (input->>'team_size')::integer;
        points_value := (input->>'points_available')::numeric;
        allowance_value := (input->>'handicap_allowance')::numeric;
      exception when others then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_ROUND_INPUT_INVALID'
        );
      end;
      target_format := pg_catalog.upper(pg_catalog.btrim(coalesce(
        input->>'format', ''
      )));
      name_value := pg_catalog.btrim(coalesce(input->>'round_name', ''));
      if target_round not between 1 and 99
         or target_format not in ('BB', 'SC', 'SI')
         or name_value = '' or points_value < 0
         or allowance_value < 0 or allowance_value > 1
         or (target_format in ('BB', 'SC') and team_size_value <> 2)
         or (target_format = 'SI' and team_size_value <> 1) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_ROUND_INPUT_INVALID'
        );
      end if;
      if exists (
        select 1
        from production_control.future_match_definitions_v1 match_value
        join production_control.future_tournament_rounds_v1 round_value
          on round_value.tournament_id = match_value.tournament_id
         and round_value.round_number = match_value.round_number
        where match_value.tournament_id = target_id
          and match_value.round_number = target_round
          and (round_value.format is distinct from target_format
            or round_value.team_size is distinct from team_size_value)
      ) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_ROUND_MATCH_STRUCTURE_LOCKED'
        );
      end if;
      insert into production_control.future_tournament_rounds_v1 (
        tournament_id, round_number, round_name, format, team_size,
        points_available, handicap_allowance, setup_revision,
        updated_by_player_id
      ) values (
        target_id, target_round, name_value, target_format,
        team_size_value, points_value, allowance_value,
        next_revision, actor_player
      ) on conflict (tournament_id, round_number) do update set
        round_name = excluded.round_name, format = excluded.format,
        team_size = excluded.team_size,
        points_available = excluded.points_available,
        handicap_allowance = excluded.handicap_allowance,
        setup_revision = excluded.setup_revision,
        updated_by_player_id = excluded.updated_by_player_id,
        updated_at = pg_catalog.clock_timestamp();
      target_kind := 'ROUND';
      audit_target := target_id || ':R' || target_round::text;
      summary_value := 'Future tournament round configuration updated.';
    elsif action_value = 'ASSIGN_COURSE' then
      begin
        target_round := (input->>'round_number')::integer;
      exception when others then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_COURSE_REFERENCE_INVALID'
        );
      end;
      target_course := pg_catalog.btrim(coalesce(input->>'course_id', ''));
      target_tee := pg_catalog.btrim(coalesce(input->>'tee', ''));
      begin
        item_side := nullif(input->>'source_round_number', '')::integer;
      exception when others then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_COURSE_REFERENCE_INVALID'
        );
      end;
      if coalesce(input->>'source_tournament_id', '2026') <> '2026'
         or target_course !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,95}$'
         or target_tee = '' or not exists (
           select 1
           from production_control.future_tournament_rounds_v1 round_value
           where round_value.tournament_id = target_id
             and round_value.round_number = target_round
         ) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_COURSE_REFERENCE_INVALID'
        );
      end if;
      select tee.setup_revision into source_setup
      from scoring_authority.tournament_setup_course_tees_v1 tee
      where tee.tournament_id = '2026' and tee.course_id = target_course
        and tee.tee_id = target_tee
        and (item_side is null or exists (
          select 1
          from scoring_authority.tournament_setup_round_courses_v1 assignment
          where assignment.tournament_id = '2026'
            and assignment.round_number = item_side
            and assignment.course_id = tee.course_id
            and assignment.tee_id = tee.tee_id
        ));
      if source_setup is null or (
        select pg_catalog.count(*)
        from scoring_authority.tournament_setup_course_holes_v1 hole
        where hole.tournament_id = '2026'
          and hole.course_id = target_course and hole.tee_id = target_tee
      ) <> 18 then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_EXISTING_COURSE_TEE_REQUIRED'
        );
      end if;
      insert into production_control.future_tournament_course_references_v1 (
        tournament_id, round_number, course_id, tee_id,
        source_tournament_id, source_round_number, source_setup_revision,
        setup_revision, updated_by_player_id
      ) values (
        target_id, target_round, target_course, target_tee,
        '2026', item_side, source_setup, next_revision, actor_player
      ) on conflict (tournament_id, round_number) do update set
        course_id = excluded.course_id, tee_id = excluded.tee_id,
        source_tournament_id = excluded.source_tournament_id,
        source_round_number = excluded.source_round_number,
        source_setup_revision = excluded.source_setup_revision,
        setup_revision = excluded.setup_revision,
        updated_by_player_id = excluded.updated_by_player_id,
        updated_at = pg_catalog.clock_timestamp();
      target_kind := 'COURSE_REFERENCE';
      audit_target := target_id || ':R' || target_round::text;
      summary_value := 'Existing certified course and tee referenced for a future round.';
    elsif action_value = 'GENERATE_MATCH_STRUCTURE' then
      begin
        target_round := (input->>'round_number')::integer;
        match_count_value := (input->>'match_count')::integer;
      exception when others then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_MATCH_STRUCTURE_INPUT_INVALID'
        );
      end;
      select round_value.format into target_format
      from production_control.future_tournament_rounds_v1 round_value
      where round_value.tournament_id = target_id
        and round_value.round_number = target_round;
      if target_format is null or match_count_value not between 1 and 99 then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_MATCH_STRUCTURE_INPUT_INVALID'
        );
      end if;
      if exists (
        select 1 from production_control.future_match_definitions_v1 match_value
        where match_value.tournament_id = target_id
          and match_value.round_number = target_round
      ) then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_MATCH_STRUCTURE_ALREADY_GENERATED'
        );
      end if;
      insert into production_control.future_match_definitions_v1 (
        tournament_id, match_id, round_number, match_number, format, team_size,
        setup_revision, created_by_player_id
      )
      select target_id,
        target_id || '-R' || target_round::text || '-' || sequence::text,
        target_round, sequence, target_format,
        (select round_value.team_size
         from production_control.future_tournament_rounds_v1 round_value
         where round_value.tournament_id = target_id
           and round_value.round_number = target_round),
        next_revision, actor_player
      from pg_catalog.generate_series(1, match_count_value) sequence;
      get diagnostics generated_count = row_count;
      -- Google runtime retired: external delivery is not canonical authority.
      target_kind := 'MATCH_STRUCTURE';
      audit_target := target_id || ':R' || target_round::text;
      summary_value := 'Empty future match structure generated without scoring facts.';
      safe_metadata := pg_catalog.jsonb_build_object(
        'matchDefinitionCount', generated_count,
        'runtimeMatchesCreated', false, 'snapshotsCreated', false,
        'scoringAccessCreated', false,
        'googleWriterInvoked', false
      );
    elsif action_value = 'MARK_READY' then
      readiness_value := production_control.future_year_readiness_v1(target_id);
      if not coalesce((readiness_value->>'readyForActivation')::boolean, false)
      then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'code', 'FUTURE_TOURNAMENT_NOT_READY',
          'readiness', readiness_value
        );
      end if;
      update production_control.future_tournament_catalog_v1 value set
        lifecycle = 'READY_FOR_ACTIVATION',
        lifecycle_revision = value.lifecycle_revision + 1,
        readiness_fingerprint = readiness_value->>'fingerprint',
        readiness_setup_revision = value.setup_revision
      where value.tournament_id = target_id;
      target_kind := 'READINESS';
      audit_target := target_id;
      summary_value := 'Future tournament marked Ready for Activation.';
    end if;

    update production_control.future_tournament_catalog_v1 value set
      lifecycle = case
        when action_value = 'MARK_READY' then value.lifecycle
        when value.lifecycle = 'DRAFT' then 'CONFIGURING'
        else value.lifecycle end,
      setup_revision = next_revision,
      readiness_fingerprint = case when action_value = 'MARK_READY'
        then value.readiness_fingerprint else null end,
      readiness_setup_revision = case when action_value = 'MARK_READY'
        then value.readiness_setup_revision else null end,
      updated_by_player_id = actor_player,
      updated_by_auth_user_id = actor_auth,
      updated_at = pg_catalog.clock_timestamp()
    where value.tournament_id = target_id;
  end if;

  readiness_value := production_control.future_year_readiness_v1(target_id);
  safe_metadata := safe_metadata || pg_catalog.jsonb_build_object(
    'summary', summary_value,
    'authorityChanged', false, 'currentPointerChanged', false,
    'tournamentFactsChanged', false
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_FUTURE_YEAR_' || action_value || '_COMPLETED',
    'operation', action_value, 'idempotent', false,
    'target_tournament_id', target_id,
    'revision', next_revision,
    'receipt_id', receipt_uuid,
    'lifecycle', (
      select value.lifecycle
      from production_control.future_tournament_catalog_v1 value
      where value.tournament_id = target_id
    ),
    'readiness', readiness_value
  );
  insert into production_control.future_year_audit_events_v1 (
    provenance_tournament_id, target_tournament_id, action,
    target_kind, target_id, actor_player_id, actor_auth_user_id,
    operation_request_id, prior_revision, next_revision,
    result, safe_metadata
  ) values (
    '2026', target_id, action_value, target_kind,
    coalesce(audit_target, target_id), actor_player, actor_auth,
    operation_request, current_revision, next_revision,
    'CHANGED', safe_metadata
  );
  insert into production_control.future_year_operation_receipts_v1 (
    receipt_id, provenance_tournament_id, target_tournament_id, action,
    operation_request_id, declared_request_payload_hash,
    database_request_payload_hash, actor_player_id, actor_auth_user_id,
    prior_revision, next_revision, response
  ) values (
    receipt_uuid, '2026', target_id, action_value, operation_request,
    declared_hash, database_hash, actor_player, actor_auth,
    current_revision, next_revision, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.canonical_mutate_future_year_administration_v2(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: canonical_net_skins_entries_core_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_net_skins_entries_core_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare rn integer; expected bigint; request_id_value uuid; hash_value text; current_revision bigint;
  prior production_control.net_skins_entry_revisions_v1%rowtype;
  field jsonb; row_value jsonb; canonical jsonb:='[]'; item jsonb; configured_value boolean; response_value jsonb;
begin
  if coalesce(input->>'round_number','') !~ '^[1-9][0-9]?$' or coalesce(input->>'expected_revision','') !~ '^[0-9]+$'
    or jsonb_typeof(input->'configured') is distinct from 'boolean' or jsonb_typeof(input->'entries') is distinct from 'array'
    or input->>'actor_player_id' is distinct from input#>>'{authorization,player_id}'
    or input->>'actor_auth_user_id' is distinct from input#>>'{authorization,auth_user_id}' then
    raise exception 'TOURNAMENT_SETUP_SKINS_ENTRIES_INPUT_INVALID'; end if;
  rn:=(input->>'round_number')::integer; expected:=(input->>'expected_revision')::bigint;
  configured_value:=(input->>'configured')::boolean; request_id_value:=(input->>'operation_request_id')::uuid;
  if request_id_value is null then raise exception 'TOURNAMENT_SETUP_OPERATION_REQUEST_ID_REQUIRED'; end if;
  hash_value:=production_control.tournament_setup_hash_v1(input);
  -- Serialize with ordinary single/round pair saves, then with financial workers.
  perform pg_advisory_xact_lock(hashtextextended('production-tournament-setup-v1:2026',0));
  select * into prior from production_control.net_skins_entry_revisions_v1 where tournament_id='2026' and request_id=request_id_value;
  if found then
    if prior.request_hash is distinct from hash_value then raise exception 'TOURNAMENT_SETUP_IDEMPOTENCY_CONFLICT'; end if;
    return prior.response||jsonb_build_object('idempotent',true);
  end if;
  lock table scoring_authority.matches,scoring_authority.match_participants,scoring_authority.tournament_players,
    scoring_authority.scoring_permissions,scoring_authority.scoring_ingress_leases,
    scoring_authority.net_skins_configuration_entries,scoring_authority.net_skins_v1_recalculation_jobs,
    scoring_authority.net_skins_v1_result_revisions in share mode;
  select coalesce(max(revision),0) into current_revision from production_control.net_skins_entry_revisions_v1
    where tournament_id='2026' and round_number=rn;
  if expected<>current_revision then raise exception 'TOURNAMENT_SETUP_SKINS_ENTRIES_REVISION_STALE'; end if;
  if not exists(select 1 from scoring_authority.rounds where tournament_id='2026' and round_number=rn and format in('BB','SC','SI'))
    then raise exception 'TOURNAMENT_SETUP_SKINS_ROUND_INVALID'; end if;
  if exists(select 1 from scoring_authority.matches m where m.tournament_id='2026' and m.round_number=rn
      and not production_control.handicap_v1_match_is_unstarted(m.match_id))
    or exists(select 1 from scoring_authority.scoring_permissions p join scoring_authority.matches m using(match_id)
      where m.tournament_id='2026' and m.round_number=rn and p.can_score and p.revoked_at is null)
    or exists(select 1 from scoring_authority.scoring_ingress_leases l join scoring_authority.matches m using(match_id)
      where m.tournament_id='2026' and m.round_number=rn and l.expires_at>clock_timestamp())
    or exists(select 1 from scoring_authority.net_skins_configuration_entries where tournament_id='2026' and round_number=rn)
    or exists(select 1 from scoring_authority.net_skins_v1_result_revisions where tournament_id='2026' and round_number=rn)
    or exists(select 1 from scoring_authority.net_skins_v1_recalculation_jobs where tournament_id='2026' and round_number=rn and status in('PENDING','RUNNING'))
    then raise exception 'TOURNAMENT_SETUP_SKINS_ENTRIES_DEPENDENCY_BLOCKED'; end if;
  field:=production_control.net_skins_entry_field_v1('2026',rn);
  if exists(select 1 from jsonb_array_elements(field) f cross join lateral jsonb_array_elements_text(f->'playerIds') p
    group by p having count(*)>1) then raise exception 'TOURNAMENT_SETUP_SKINS_DUPLICATE_PLAYER'; end if;
  if input->>'field_fingerprint' is distinct from production_control.tournament_setup_hash_v1(field)
    then raise exception 'TOURNAMENT_SETUP_SKINS_PAIRING_STALE'; end if;
  if jsonb_array_length(input->'entries')<>jsonb_array_length(field)
    or (select count(distinct value->>'key') from jsonb_array_elements(input->'entries'))<>jsonb_array_length(field)
    then raise exception 'TOURNAMENT_SETUP_SKINS_ENTRY_SET_INVALID'; end if;
  for item in select value from jsonb_array_elements(field) loop
    select value into row_value from jsonb_array_elements(input->'entries') where value->>'key'=item->>'key';
    if row_value is null or jsonb_typeof(row_value->'entered') is distinct from 'boolean'
      or row_value->>'bindingFingerprint' is distinct from item->>'bindingFingerprint'
      or (not configured_value and row_value->>'entered'='true') then
      raise exception 'TOURNAMENT_SETUP_SKINS_ENTRY_BINDING_INVALID'; end if;
    canonical:=canonical||jsonb_build_array(item||jsonb_build_object('entered',(row_value->>'entered')::boolean));
  end loop;
  if configured_value and jsonb_array_length(field)=0 then raise exception 'TOURNAMENT_SETUP_SKINS_PAIRINGS_REQUIRED'; end if;
  response_value:=jsonb_build_object('ok',true,'revision',current_revision+1,'roundNumber',rn,'idempotent',false,
    'scoringMutationCreated',false,'financialMutationCreated',false,'publicationCreated',false);
  insert into production_control.net_skins_entry_revisions_v1(tournament_id,round_number,revision,request_id,request_hash,
    field_fingerprint,configured,entries,actor_player_id,actor_auth_user_id,response)
    values('2026',rn,current_revision+1,request_id_value,hash_value,input->>'field_fingerprint',configured_value,canonical,
      input->>'actor_player_id',(input->>'actor_auth_user_id')::uuid,response_value);
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.canonical_net_skins_entries_core_v1(input jsonb) OWNER TO postgres;

--
-- Name: canonical_odds_dispatch_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_odds_dispatch_v2(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  operation_name text := pg_catalog.btrim(coalesce(
    input->>'annual_odds_operation', ''
  ));
  target text;
  destination text;
  config scoring_authority.odds_input_configurations%rowtype;
  retained scoring_authority.odds_calculation_jobs%rowtype;
  inserted scoring_authority.odds_calculation_jobs%rowtype;
  existing_checkpoint scoring_authority.odds_calculation_checkpoints%rowtype;
  invocation_value jsonb;
  canonical_value jsonb;
  input_snapshot_value jsonb;
  checkpoint_value jsonb;
  job text := pg_catalog.lower(coalesce(input->>'job_id', ''));
  input_hash text := pg_catalog.lower(coalesce(
    input->>'input_fingerprint', ''
  ));
  checkpoint_hash_value text := pg_catalog.lower(coalesce(
    input->>'checkpoint_hash', ''
  ));
  result_hash text := pg_catalog.lower(coalesce(
    input->>'result_fingerprint', ''
  ));
  claim uuid;
  progress integer;
  retryable boolean;
  superseded_count integer := 0;
  next_sequence integer;
  jobs jsonb;
  checkpoints jsonb;
  publication_result jsonb;
begin
  if context is null then target := production_control.assert_annual_odds_runtime_v1(input,operation_name);
  else target:=context->>'tournament_id';perform production_control.certification_odds_runtime_v1(context);end if;
  destination := input->>'annual_destination_workbook_id';
  if context is not null and operation_name in('read_production_odds_calculation_inputs',
    'request_production_odds_calculation_job','claim_production_odds_calculation_job',
    'checkpoint_production_odds_calculation_job','complete_production_odds_calculation_job',
    'publish_production_championship_odds_v1') then
   perform production_control.lock_certification_odds_source_v1(target,context);
  end if;

  if operation_name = 'read_production_odds_calculation_inputs' then
    perform production_control.current_canonical_odds_inputs_v2(
      target, destination, input, false
    ,context);
    if context is null then return public.read_championship_odds_inputs(target);end if;
    publication_result:=public.read_championship_odds_inputs(target);
    -- Existing canonical read data; exclude measurement only. This supplements
    -- the old source_revision, which does not enumerate team/roster/round data.
    return jsonb_set(jsonb_set(publication_result,'{data,certification_context}',
      production_control.certification_odds_runtime_v1(context)),
      '{data,certification_live_source_fingerprint}',to_jsonb(production_control.future_runtime_hash_v2(
        (publication_result#>'{data,current_state}')-'query_ms')));
  end if;

  if operation_name = 'request_production_odds_calculation_job' then
    if context is not null then
     perform production_control.assert_certification_odds_live_source_v1(target,input->'input_snapshot',context);
    end if;
    config := production_control.current_canonical_odds_inputs_v2(
      target, destination, input, true
    ,context);
    if job !~ '^[0-9a-f]{64}$'
       or job <> pg_catalog.lower(coalesce(
         input->>'invocation_fingerprint', ''
       ))
       or input_hash !~ '^[0-9a-f]{64}$'
       or checkpoint_hash_value !~ '^[0-9a-f]{64}$'
       or input->>'target_tournament_id' is distinct from target
       or coalesce((input->>'target_tournament_year')::integer, 0)
         <> target::integer
       or input->>'phase' not in (
         'Pre-Tournament', 'After Round 1', 'After Round 2',
         'Round 3 Pairings Announced', 'Final Results'
       )
       or coalesce((input->>'total_iterations')::integer, 0)
         not in (10000, 25000, 50000, 100000)
       or pg_catalog.btrim(coalesce(input->>'engine_version', '')) = ''
       or pg_catalog.btrim(coalesce(
         input->>'publication_contract_version', ''
       )) = ''
       or pg_catalog.btrim(coalesce(
         input->>'checkpoint_contract_version', ''
       )) = ''
       or pg_catalog.btrim(coalesce(
         input->>'deterministic_seed', ''
       )) = ''
       or pg_catalog.btrim(coalesce(input->>'requested_by', '')) = ''
       or pg_catalog.btrim(coalesce(input->>'output_timestamp', '')) = ''
       or pg_catalog.jsonb_typeof(input->'input_snapshot') <> 'object'
       or pg_catalog.jsonb_typeof(input->'checkpoint_payload') <> 'object'
       or pg_catalog.jsonb_typeof(input->'source_revision') <> 'object'
       or pg_catalog.btrim(coalesce(
         input->>'invocation_canonical_json', ''
       )) = ''
       or pg_catalog.btrim(coalesce(
         input->>'input_snapshot_canonical_json', ''
       )) = ''
       or pg_catalog.btrim(coalesce(
         input->>'checkpoint_canonical_json', ''
       )) = '' then
      raise exception using errcode = '22023',
        message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_JOB_REQUIRED';
    end if;
    begin
      invocation_value := (input->>'invocation_canonical_json')::jsonb;
      input_snapshot_value :=
        (input->>'input_snapshot_canonical_json')::jsonb;
      checkpoint_value := (input->>'checkpoint_canonical_json')::jsonb;
    exception when others then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_ODDS_CANONICAL_JSON_INVALID';
    end;
    if input_snapshot_value is distinct from input->'input_snapshot'
       or checkpoint_value is distinct from input->'checkpoint_payload'
       or pg_catalog.encode(extensions.digest(
         input->>'input_snapshot_canonical_json', 'sha256'
       ), 'hex') <> input_hash
       or pg_catalog.encode(extensions.digest(
         input->>'checkpoint_canonical_json', 'sha256'
       ), 'hex') <> checkpoint_hash_value
       or pg_catalog.encode(extensions.digest(
         input->>'invocation_canonical_json', 'sha256'
       ), 'hex') <> job
       or invocation_value->>'tournamentId' is distinct from target
       or invocation_value->>'phase' is distinct from input->>'phase'
       or coalesce((invocation_value->>'iterations')::integer, 0)
         <> (input->>'total_iterations')::integer
       or invocation_value->>'inputFingerprint' is distinct from input_hash
       or invocation_value->>'settingsFingerprint' is distinct from
         config.settings_fingerprint
       or invocation_value->>'operationMode' is distinct from
         (case when context is null then 'PRODUCTION_CUTOVER' else 'CERTIFICATION' end)
       or invocation_value->>'annualRuntimeGenerationId' is distinct from
         input->>'expected_runtime_generation_id'
       or coalesce((invocation_value->>'annualPointerRevision')::bigint, -1)
         <> (input->>'expected_pointer_revision')::bigint
       or invocation_value->>'annualAuthorityGenerationId' is distinct from
         input->>'expected_annual_authority_generation_id'
       or invocation_value->>'annualAdmissionGenerationId' is distinct from
         input->>'expected_annual_admission_generation_id'
       or input#>>'{input_snapshot,metadata,settingsFingerprint}'
         is distinct from config.settings_fingerprint
       or input#>>'{input_snapshot,sheets,tournaments,0,Tournament ID}'
         is distinct from target then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_ODDS_DETERMINISTIC_IDENTITY_MISMATCH';
    end if;
    if context is not null and(invocation_value->>'certificationResourceId' is distinct from context->>'resource_id'
      or invocation_value->>'certificationInstallationId' is distinct from context->>'installation_id'
      or invocation_value->>'certificationIngressGenerationId' is distinct from input->>'certification_ingress_generation_id'
      or invocation_value->>'jobIdentityContract' is distinct from 'certification-odds-calculation-job-identity-v1'
      or invocation_value->>'jobContractVersion' is distinct from 'championship-odds-calculation-job-v1'
      or invocation_value->>'deploymentCommit' is distinct from context->>'release_commit'
      or invocation_value->>'engineVersion' is distinct from input->>'engine_version'
      or invocation_value->>'publicationContractVersion' is distinct from input->>'publication_contract_version'
      or invocation_value->>'checkpointContractVersion' is distinct from input->>'checkpoint_contract_version'
      or invocation_value->>'deterministicSeed' is distinct from input->>'deterministic_seed')then
      raise exception using errcode='23514',message='CERTIFICATION_ODDS_DETERMINISTIC_IDENTITY_MISMATCH';end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('production-annual-odds-job:' || job));
    select value.* into retained
    from scoring_authority.odds_calculation_jobs value
    where value.job_id = job for update;
    if found then
      perform production_control.assert_canonical_odds_job_v1(input,target,retained,context);
      if retained.input_fingerprint <> input_hash
         or retained.input_configuration_id <> config.id
         or retained.input_bundle_fingerprint <> config.bundle_fingerprint
         or retained.total_iterations <>
           (input->>'total_iterations')::integer then
        raise exception using errcode = '23505',
          message = 'PRODUCTION_ODDS_CALCULATION_JOB_IDENTITY_CONFLICT';
      end if;
      return pg_catalog.jsonb_build_object(
        'ok', true, 'changed', false, 'duplicate', true,
        'job', pg_catalog.to_jsonb(retained) - 'input_snapshot'
          - 'checkpoint_payload' - 'result_payload' - 'claim_token',
        'publication_created', false, 'mirror_created', false
      );
    end if;
    insert into scoring_authority.odds_calculation_jobs (
      job_id, tournament_id, phase, total_iterations, engine_version,
      publication_contract_version, checkpoint_contract_version,
      deterministic_seed, input_fingerprint, settings_fingerprint,
      invocation_fingerprint, source_revision, input_snapshot,
      checkpoint_payload, checkpoint_hash, requested_by, output_timestamp,
      resource_metrics, input_configuration_id,
      effective_settings_fingerprint, input_bundle_fingerprint,
      production_operation_mode, production_deployment_commit,
      production_candidate_hostname, publication_status,
      publication_reference, runtime_generation_id
    ) values (
      job, target, input->>'phase',
      (input->>'total_iterations')::integer, input->>'engine_version',
      input->>'publication_contract_version',
      input->>'checkpoint_contract_version', input->>'deterministic_seed',
      input_hash, config.settings_fingerprint, job,
      input->'source_revision', input->'input_snapshot',
      input->'checkpoint_payload', checkpoint_hash_value,
      pg_catalog.left(input->>'requested_by', 180),
      (input->>'output_timestamp')::timestamptz,
      coalesce(input->'resource_metrics', '{}'::jsonb), config.id,
      config.effective_settings_fingerprint, config.bundle_fingerprint,
      (case when context is null then 'PRODUCTION_CUTOVER' else 'CERTIFICATION' end), input->>'deployment_commit', null,
      'NOT_REQUESTED', '{}'::jsonb,
      (input->>'expected_runtime_generation_id')::uuid
    ) returning * into inserted;
    update scoring_authority.odds_calculation_jobs value set
      status = 'SUPERSEDED', publication_status = 'STALE',
      superseded_by = job, superseded_at = pg_catalog.clock_timestamp(),
      claim_token = null, lease_owner = null, lease_expires_at = null,
      last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
      last_error_safe = (case when context is null then 'Canonical Production calculation inputs advanced.' else 'Canonical Certification calculation inputs advanced.' end),
      updated_at = pg_catalog.clock_timestamp()
    where value.job_id <> job and value.tournament_id = target
      and (value.runtime_generation_id = (input->>'expected_runtime_generation_id')::uuid or(context is not null and value.runtime_generation_id is null and input->>'expected_runtime_generation_id' is null))
      and value.phase = input->>'phase'
      and value.production_operation_mode = (case when context is null then 'PRODUCTION_CUTOVER' else 'CERTIFICATION' end)
      and value.input_bundle_fingerprint is distinct from
        config.bundle_fingerprint
      and value.status in ('PENDING', 'RUNNING', 'RETRYABLE', 'SUCCEEDED')
      and value.publication_status <> 'PUBLISHED';
    get diagnostics superseded_count = row_count;
    insert into production_control.operation_audit_events (
      event_type, domain, tournament_id, actor, request_fingerprint,
      result, details
    ) values (
      (case when context is null then 'PRODUCTION_ODDS_CALCULATION_REQUESTED' else 'CERTIFICATION_ODDS_CALCULATION_REQUESTED' end),
      'CHAMPIONSHIP_ODDS_CALCULATION', target,
      pg_catalog.left(input->>'requested_by', 160), job, 'SUCCEEDED',
      pg_catalog.jsonb_build_object(
        'job_id', job, 'phase', input->>'phase',
        'iterations', (input->>'total_iterations')::integer,
        'runtime_generation_id', input->>'expected_runtime_generation_id',
        'input_fingerprint', input_hash,
        'settings_fingerprint', config.settings_fingerprint,
        'input_bundle_fingerprint', config.bundle_fingerprint,
        'superseded_jobs', superseded_count,
        'publication_created', false, 'mirror_created', false
      ) || case when context is null then '{}'::jsonb else jsonb_build_object(
       'resource_class','CERTIFICATION','resource_id',context->>'resource_id','installation_id',context->>'installation_id',
       'release_commit',context->>'release_commit','certification_ingress_generation_id',input->>'certification_ingress_generation_id')end
    );
    return pg_catalog.jsonb_build_object(
      'ok', true, 'changed', true, 'duplicate', false,
      'superseded_jobs', superseded_count,
      'job', pg_catalog.to_jsonb(inserted) - 'input_snapshot'
        - 'checkpoint_payload' - 'result_payload' - 'claim_token',
      'publication_created', false, 'mirror_created', false
    );
  end if;

  if operation_name = 'claim_production_odds_calculation_job' then
    if job !~ '^[0-9a-f]{64}$'
       or pg_catalog.btrim(coalesce(input->>'worker_id', '')) = '' then
      raise exception using errcode = '22023',
        message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_CLAIM_REQUIRED';
    end if;
    select value.* into retained
    from scoring_authority.odds_calculation_jobs value
    where value.job_id = job for update;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_JOB_NOT_FOUND'
      );
    end if;
    perform production_control.assert_canonical_odds_job_v1(input,target,retained,context);
    -- A published job is retained history. A worker retry may observe its
    -- existing terminal result, but must never supersede it after source or
    -- configuration advancement. Preserve the existing completed/conflict
    -- outcomes; only Certification skips inapplicable current-input checks.
    if context is not null and retained.status='SUCCEEDED'
      and retained.publication_status='PUBLISHED' then
     if operation_name='claim_production_odds_calculation_job' then
      return jsonb_build_object('ok',true,'deliver',false,'completed',true,
       'job',to_jsonb(retained)-'claim_token');
     end if;
     return jsonb_build_object('ok',false,'code','ODDS_CALCULATION_RESULT_CONFLICT');
    end if;
    begin
      if context is not null then
       perform production_control.assert_certification_odds_live_source_v1(target,retained.input_snapshot,context);
      end if;
      config := production_control.current_canonical_odds_inputs_v2(
        target, destination,
        input || pg_catalog.jsonb_build_object(
          'input_configuration_id', retained.input_configuration_id,
          'configuration_revision',
            retained.source_revision->>'configuration_revision',
          'settings_fingerprint', retained.settings_fingerprint,
          'effective_settings_fingerprint',
            retained.effective_settings_fingerprint,
          'input_bundle_fingerprint', retained.input_bundle_fingerprint,
          'source_revision', retained.source_revision
        ), true
      ,context);
    exception when sqlstate '40001' then
      update scoring_authority.odds_calculation_jobs set
        status = 'SUPERSEDED', publication_status = 'STALE',
        superseded_at = pg_catalog.clock_timestamp(), claim_token = null,
        lease_owner = null, lease_expires_at = null,
        last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
        last_error_safe = (case when context is null then 'Canonical Production calculation inputs advanced.' else 'Canonical Certification calculation inputs advanced.' end),
        updated_at = pg_catalog.clock_timestamp()
      where job_id = job;
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_JOB_SUPERSEDED',
        'retryable', false
      );
    end;
    if retained.input_configuration_id <> config.id
       or retained.input_bundle_fingerprint <> config.bundle_fingerprint then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_ANNUAL_ODDS_INPUT_REVISION_STALE';
    end if;
    if retained.status = 'SUCCEEDED' then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'deliver', false, 'completed', true,
        'job', pg_catalog.to_jsonb(retained) - 'claim_token'
      );
    end if;
    if retained.status in ('SUPERSEDED', 'FAILED') then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_JOB_' || retained.status,
        'retryable', false
      );
    end if;
    if retained.status = 'RUNNING'
       and retained.lease_expires_at > pg_catalog.clock_timestamp() then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'deliver', false, 'in_progress', true,
        'job', pg_catalog.to_jsonb(retained) - 'input_snapshot'
          - 'checkpoint_payload' - 'result_payload' - 'claim_token'
      );
    end if;
    update scoring_authority.odds_calculation_jobs set
      status = 'RUNNING', attempt_count = attempt_count + 1,
      claim_token = extensions.gen_random_uuid(),
      lease_owner = pg_catalog.left(input->>'worker_id', 180),
      lease_expires_at = pg_catalog.clock_timestamp() + interval '12 minutes',
      started_at = coalesce(started_at, pg_catalog.clock_timestamp()),
      updated_at = pg_catalog.clock_timestamp(), last_error_code = null,
      last_error_safe = null
    where job_id = job returning * into retained;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'deliver', true, 'job', pg_catalog.to_jsonb(retained),
      'publication_created', false, 'mirror_created', false
    );
  end if;

  if operation_name = 'checkpoint_production_odds_calculation_job' then
    begin claim := nullif(input->>'claim_token', '')::uuid;
    exception when others then claim := null; end;
    progress := coalesce((input->>'completed_iterations')::integer, 0);
    if job !~ '^[0-9a-f]{64}$' or claim is null
       or checkpoint_hash_value !~ '^[0-9a-f]{64}$'
       or pg_catalog.jsonb_typeof(input->'checkpoint_payload') <> 'object'
       or pg_catalog.btrim(coalesce(
         input->>'checkpoint_canonical_json', ''
       )) = '' then
      raise exception using errcode = '22023',
        message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_CHECKPOINT_REQUIRED';
    end if;
    begin canonical_value := (input->>'checkpoint_canonical_json')::jsonb;
    exception when others then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_ODDS_CANONICAL_JSON_INVALID';
    end;
    if canonical_value is distinct from input->'checkpoint_payload'
       or pg_catalog.encode(extensions.digest(
         input->>'checkpoint_canonical_json', 'sha256'
       ), 'hex') <> checkpoint_hash_value then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_ODDS_CHECKPOINT_FINGERPRINT_MISMATCH';
    end if;
    select value.* into retained
    from scoring_authority.odds_calculation_jobs value
    where value.job_id = job for update;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_JOB_NOT_FOUND'
      );
    end if;
    perform production_control.assert_canonical_odds_job_v1(input,target,retained,context);
    if context is not null and operation_name='checkpoint_production_odds_calculation_job' then
     perform production_control.assert_certification_odds_live_source_v1(target,retained.input_snapshot,context);
    end if;
    if retained.status <> 'RUNNING'
       or retained.claim_token is distinct from claim
       or retained.lease_expires_at <= pg_catalog.clock_timestamp() then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_CLAIM_STALE',
        'retryable', false
      );
    end if;
    if progress < retained.completed_iterations
       or progress > retained.total_iterations then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_PROGRESS_INVALID'
      );
    end if;
    if progress = retained.completed_iterations then
      if retained.checkpoint_hash = checkpoint_hash_value then
        return pg_catalog.jsonb_build_object(
          'ok', true, 'duplicate', true,
          'checkpoint_count', retained.checkpoint_count,
          'completed_iterations', retained.completed_iterations
        );
      end if;
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_CHECKPOINT_CONFLICT'
      );
    end if;
    select value.* into existing_checkpoint
    from scoring_authority.odds_calculation_checkpoints value
    where value.job_id = job and value.completed_iterations = progress;
    if found then
      if existing_checkpoint.checkpoint_hash = checkpoint_hash_value then
        return pg_catalog.jsonb_build_object(
          'ok', true, 'duplicate', true,
          'checkpoint_count', retained.checkpoint_count,
          'completed_iterations', progress
        );
      end if;
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_CHECKPOINT_CONFLICT'
      );
    end if;
    next_sequence := retained.checkpoint_count + 1;
    insert into scoring_authority.odds_calculation_checkpoints (
      job_id, checkpoint_sequence, completed_iterations,
      checkpoint_contract_version, checkpoint_payload, checkpoint_hash,
      attempt_number, resource_metrics
    ) values (
      job, next_sequence, progress, retained.checkpoint_contract_version,
      input->'checkpoint_payload', checkpoint_hash_value,
      retained.attempt_count, coalesce(input->'resource_metrics', '{}'::jsonb)
    );
    update scoring_authority.odds_calculation_jobs set
      completed_iterations = progress,
      checkpoint_payload = input->'checkpoint_payload',
      checkpoint_hash = checkpoint_hash_value,
      checkpoint_count = next_sequence,
      resource_metrics = coalesce(input->'resource_metrics', resource_metrics),
      lease_expires_at = pg_catalog.clock_timestamp() + interval '12 minutes',
      updated_at = pg_catalog.clock_timestamp()
    where job_id = job;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'duplicate', false, 'completed_iterations', progress,
      'total_iterations', retained.total_iterations,
      'checkpoint_count', next_sequence,
      'publication_created', false, 'mirror_created', false
    );
  end if;

  if operation_name = 'complete_production_odds_calculation_job' then
    begin claim := nullif(input->>'claim_token', '')::uuid;
    exception when others then claim := null; end;
    if job !~ '^[0-9a-f]{64}$' or claim is null
       or result_hash !~ '^[0-9a-f]{64}$'
       or pg_catalog.jsonb_typeof(input->'result_payload') <> 'object'
       or pg_catalog.jsonb_typeof(
         input->'result_fingerprint_payload'
       ) <> 'object'
       or pg_catalog.btrim(coalesce(
         input->>'result_canonical_json', ''
       )) = '' then
      raise exception using errcode = '22023',
        message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_RESULT_REQUIRED';
    end if;
    begin canonical_value := (input->>'result_canonical_json')::jsonb;
    exception when others then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_ODDS_CANONICAL_JSON_INVALID';
    end;
    if canonical_value is distinct from input->'result_fingerprint_payload'
       or input->'result_fingerprint_payload' is distinct from
         (input->'result_payload') - 'publishedAt'
       or pg_catalog.encode(extensions.digest(
         input->>'result_canonical_json', 'sha256'
       ), 'hex') <> result_hash then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_ODDS_RESULT_FINGERPRINT_MISMATCH';
    end if;
    select value.* into retained
    from scoring_authority.odds_calculation_jobs value
    where value.job_id = job for update;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_JOB_NOT_FOUND'
      );
    end if;
    perform production_control.assert_canonical_odds_job_v1(input,target,retained,context);
    -- A published job is retained history. A worker retry may observe its
    -- existing terminal result, but must never supersede it after source or
    -- configuration advancement. Preserve the existing completed/conflict
    -- outcomes; only Certification skips inapplicable current-input checks.
    if context is not null and retained.status='SUCCEEDED'
      and retained.publication_status='PUBLISHED' then
     if operation_name='claim_production_odds_calculation_job' then
      return jsonb_build_object('ok',true,'deliver',false,'completed',true,
       'job',to_jsonb(retained)-'claim_token');
     end if;
     return jsonb_build_object('ok',false,'code','ODDS_CALCULATION_RESULT_CONFLICT');
    end if;
    begin
      if context is not null then
       perform production_control.assert_certification_odds_live_source_v1(target,retained.input_snapshot,context);
      end if;
      config := production_control.current_canonical_odds_inputs_v2(
        target, destination,
        input || pg_catalog.jsonb_build_object(
          'input_configuration_id', retained.input_configuration_id,
          'configuration_revision',
            retained.source_revision->>'configuration_revision',
          'settings_fingerprint', retained.settings_fingerprint,
          'effective_settings_fingerprint',
            retained.effective_settings_fingerprint,
          'input_bundle_fingerprint', retained.input_bundle_fingerprint,
          'source_revision', retained.source_revision
        ), true
      ,context);
    exception when sqlstate '40001' then
      update scoring_authority.odds_calculation_jobs set
        status = 'SUPERSEDED', publication_status = 'STALE',
        superseded_at = pg_catalog.clock_timestamp(), claim_token = null,
        lease_owner = null, lease_expires_at = null,
        last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
        last_error_safe = (case when context is null then 'Canonical Production calculation inputs advanced.' else 'Canonical Certification calculation inputs advanced.' end),
        updated_at = pg_catalog.clock_timestamp()
      where job_id = job;
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_JOB_SUPERSEDED',
        'retryable', false, 'publication_created', false,
        'mirror_created', false
      );
    end;
    if retained.input_configuration_id <> config.id
       or retained.input_bundle_fingerprint <> config.bundle_fingerprint then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_ANNUAL_ODDS_INPUT_REVISION_STALE';
    end if;
    if retained.status = 'SUCCEEDED' then
      if retained.result_fingerprint = result_hash
         and retained.publication_status = 'READY' then
        return pg_catalog.jsonb_build_object(
          'ok', true, 'duplicate', true, 'job_id', job,
          'result_fingerprint', result_hash,
          'publication_status', retained.publication_status,
          'publication_eligible', true,
          'publication_created', false, 'mirror_created', false
        );
      end if;
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_RESULT_CONFLICT'
      );
    end if;
    if context is not null and operation_name='checkpoint_production_odds_calculation_job' then
     perform production_control.assert_certification_odds_live_source_v1(target,retained.input_snapshot,context);
    end if;
    if retained.status <> 'RUNNING'
       or retained.claim_token is distinct from claim
       or retained.lease_expires_at <= pg_catalog.clock_timestamp() then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_CLAIM_STALE'
      );
    end if;
    if retained.completed_iterations <> retained.total_iterations then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_INCOMPLETE'
      );
    end if;
    if input->'result_payload'->>'phase' is distinct from retained.phase
       or coalesce((input->'result_payload'->>'year')::integer, 0)
         <> target::integer then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_ODDS_RESULT_TOURNAMENT_MISMATCH';
    end if;
    update scoring_authority.odds_calculation_jobs set
      status = 'SUCCEEDED', publication_status = 'READY',
      publication_reference = '{}'::jsonb,
      result_payload = input->'result_payload',
      result_fingerprint = result_hash,
      output_payload_bytes = greatest(
        0, coalesce((input->>'output_payload_bytes')::integer, 0)
      ),
      resource_metrics = coalesce(input->'resource_metrics', resource_metrics),
      claim_token = null, lease_owner = null, lease_expires_at = null,
      completed_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp(),
      last_error_code = null, last_error_safe = null
    where job_id = job returning * into retained;
    insert into production_control.operation_audit_events (
      event_type, domain, tournament_id, actor, request_fingerprint,
      result, details
    ) values (
      (case when context is null then 'PRODUCTION_ODDS_CALCULATION_SUCCEEDED' else 'CERTIFICATION_ODDS_CALCULATION_SUCCEEDED' end),
      'CHAMPIONSHIP_ODDS_CALCULATION', target, retained.requested_by,
      job, 'SUCCEEDED', pg_catalog.jsonb_build_object(
        'job_id', job, 'phase', retained.phase,
        'iterations', retained.total_iterations,
        'runtime_generation_id', retained.runtime_generation_id,
        'result_fingerprint', result_hash,
        'checkpoint_count', retained.checkpoint_count,
        'attempt_count', retained.attempt_count,
        'publication_status', 'READY',
        'publication_eligible', true,
        'publication_created', false, 'mirror_created', false
      ) || case when context is null then '{}'::jsonb else jsonb_build_object(
       'resource_class','CERTIFICATION','resource_id',context->>'resource_id','installation_id',context->>'installation_id',
       'release_commit',context->>'release_commit','certification_ingress_generation_id',input->>'certification_ingress_generation_id')end
    );
    return pg_catalog.jsonb_build_object(
      'ok', true, 'duplicate', false, 'job_id', job,
      'result_fingerprint', result_hash,
      'checkpoint_count', retained.checkpoint_count,
      'attempt_count', retained.attempt_count,
      'publication_status', 'READY', 'publication_eligible', true,
      'publication_created', false, 'mirror_created', false
    );
  end if;

  if operation_name = 'fail_production_odds_calculation_job' then
    begin claim := nullif(input->>'claim_token', '')::uuid;
    exception when others then claim := null; end;
    retryable := coalesce((input->>'retryable')::boolean, true);
    if job !~ '^[0-9a-f]{64}$' or claim is null then
      raise exception using errcode = '22023',
        message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_FAILURE_REQUIRED';
    end if;
    select value.* into retained
    from scoring_authority.odds_calculation_jobs value
    where value.job_id = job for update;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'marked', false, 'stale_claim', true,
        'publication_created', false, 'mirror_created', false
      );
    end if;
    perform production_control.assert_canonical_odds_job_v1(input,target,retained,context);
    if context is not null and operation_name='checkpoint_production_odds_calculation_job' then
     perform production_control.assert_certification_odds_live_source_v1(target,retained.input_snapshot,context);
    end if;
    if retained.status <> 'RUNNING'
       or retained.claim_token is distinct from claim then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'marked', false, 'stale_claim', true,
        'publication_created', false, 'mirror_created', false
      );
    end if;
    update scoring_authority.odds_calculation_jobs set
      status = case when retryable then 'RETRYABLE' else 'FAILED' end,
      claim_token = null, lease_owner = null, lease_expires_at = null,
      last_error_code = pg_catalog.left(coalesce(
        nullif(input->>'error_code', ''), 'ODDS_CALCULATION_FAILED'
      ), 120),
      last_error_safe = pg_catalog.left(coalesce(
        nullif(input->>'error_safe', ''),
        'Championship calculation stopped safely.'
      ), 400),
      completed_at = case when retryable then completed_at
        else pg_catalog.clock_timestamp() end,
      updated_at = pg_catalog.clock_timestamp()
    where job_id = job returning * into retained;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'marked', true, 'retryable', retryable,
      'status', retained.status,
      'completed_iterations', retained.completed_iterations,
      'checkpoint_count', retained.checkpoint_count,
      'publication_created', false, 'mirror_created', false
    );
  end if;

  if operation_name = 'supersede_production_odds_calculation_job' then
    if job !~ '^[0-9a-f]{64}$' then
      raise exception using errcode = '22023',
        message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_SUPERSESSION_REQUIRED';
    end if;
    select value.* into retained
    from scoring_authority.odds_calculation_jobs value
    where value.job_id = job for update;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_JOB_NOT_FOUND'
      );
    end if;
    perform production_control.assert_canonical_odds_job_v1(input,target,retained,context);
    config := production_control.current_canonical_odds_inputs_v2(
      target, destination, input, false
    ,context);
    if retained.input_bundle_fingerprint = config.bundle_fingerprint
       and retained.input_configuration_id = config.id then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'ODDS_CALCULATION_INPUTS_STILL_CURRENT'
      );
    end if;
    update scoring_authority.odds_calculation_jobs set
      status = 'SUPERSEDED', publication_status = 'STALE',
      superseded_at = pg_catalog.clock_timestamp(), claim_token = null,
      lease_owner = null, lease_expires_at = null,
      last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
      last_error_safe = (case when context is null then 'Canonical Production calculation inputs advanced.' else 'Canonical Certification calculation inputs advanced.' end),
      updated_at = pg_catalog.clock_timestamp()
    where job_id = job
      and status in ('PENDING', 'RUNNING', 'RETRYABLE', 'SUCCEEDED')
    returning * into retained;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'superseded', found,
      'publication_created', false, 'mirror_created', false
    );
  end if;

  if operation_name = 'read_production_odds_calculation_jobs' then
    if job <> '' and job !~ '^[0-9a-f]{64}$' then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_ODDS_JOB_ID_INVALID';
    end if;
    if job <> '' then
      select value.* into retained
      from scoring_authority.odds_calculation_jobs value
      where value.job_id = job;
      if found then
        perform production_control.assert_canonical_odds_job_v1(input,target,retained,context);
      end if;
    end if;
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(value) - 'claim_token'
      order by value.requested_at desc
    ), '[]'::jsonb) into jobs
    from scoring_authority.odds_calculation_jobs value
    where value.tournament_id = target
      and (value.runtime_generation_id = (input->>'expected_runtime_generation_id')::uuid or(context is not null and value.runtime_generation_id is null and input->>'expected_runtime_generation_id' is null))
      and value.production_operation_mode = (case when context is null then 'PRODUCTION_CUTOVER' else 'CERTIFICATION' end)
      and value.production_deployment_commit = input->>'deployment_commit'
      and value.production_candidate_hostname is null
      and value.source_revision->>(case when context is null then 'production_job_identity_contract' else 'job_identity_contract' end)
        = (case when context is null then 'production-odds-calculation-job-identity-v2' else 'certification-odds-calculation-job-identity-v1' end)
      and value.source_revision->>'annual_odds_contract'
        = (case when context is null then 'production-annual-odds-dispatch-v1' else 'certification-odds-v1' end)
      and (job = '' or value.job_id = job);
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(checkpoint) - 'checkpoint_payload'
      order by checkpoint.job_id, checkpoint.checkpoint_sequence
    ), '[]'::jsonb) into checkpoints
    from scoring_authority.odds_calculation_checkpoints checkpoint
    join scoring_authority.odds_calculation_jobs value
      on value.job_id = checkpoint.job_id
    where value.tournament_id = target
      and (value.runtime_generation_id = (input->>'expected_runtime_generation_id')::uuid or(context is not null and value.runtime_generation_id is null and input->>'expected_runtime_generation_id' is null))
      and value.production_operation_mode = (case when context is null then 'PRODUCTION_CUTOVER' else 'CERTIFICATION' end)
      and value.production_deployment_commit = input->>'deployment_commit'
      and value.production_candidate_hostname is null
      and value.source_revision->>'annual_odds_contract'
        = (case when context is null then 'production-annual-odds-dispatch-v1' else 'certification-odds-v1' end)
      and (job = '' or checkpoint.job_id = job);
    return pg_catalog.jsonb_build_object(
      'ok', true, 'jobs', jobs, 'checkpoints', checkpoints,
      'operation_mode', (case when context is null then 'PRODUCTION_CUTOVER' else 'CERTIFICATION' end),
      'deployment_commit', input->>'deployment_commit',
      'candidate_hostname', null,
      'runtime_generation_id', input->>'expected_runtime_generation_id',
      'publication_created', false, 'mirror_created', false
    );
  end if;

  if operation_name = 'read_production_odds_publication_v1' then
    if context is null then return production_control.annual_odds_publication_projection_v1(target);end if;
    return production_control.certification_odds_publication_state_v1(target,context);
  end if;

  if operation_name = 'publish_production_championship_odds_v1' then
    publication_result:=production_control.canonical_publish_odds_v2(input,target,context);
    return publication_result;
  end if;

  raise exception using errcode = '42501',
    message = 'PRODUCTION_ANNUAL_ODDS_OPERATION_NOT_ALLOWLISTED';
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ANNUAL_ODDS_INPUT_INVALID';
end;
$_$;


ALTER FUNCTION production_control.canonical_odds_dispatch_v2(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: odds_input_configurations; Type: TABLE; Schema: scoring_authority; Owner: postgres
--

CREATE TABLE scoring_authority.odds_input_configurations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tournament_id text NOT NULL,
    configuration_revision bigint NOT NULL,
    source_workbook_id text NOT NULL,
    settings jsonb NOT NULL,
    historical_ratings jsonb NOT NULL,
    settings_fingerprint text NOT NULL,
    ratings_fingerprint text NOT NULL,
    pairing_fingerprint text NOT NULL,
    bundle_fingerprint text NOT NULL,
    is_current boolean DEFAULT true NOT NULL,
    imported_by text NOT NULL,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    source_tab text,
    source_fingerprint text,
    canonical_settings jsonb,
    effective_settings jsonb,
    effective_settings_fingerprint text,
    settings_contract_version text,
    validation_status text,
    validation_diagnostics jsonb,
    synchronized_at timestamp with time zone,
    previous_configuration_id uuid,
    CONSTRAINT odds_input_canonical_settings_object CHECK (((canonical_settings IS NULL) OR (jsonb_typeof(canonical_settings) = 'object'::text))),
    CONSTRAINT odds_input_configurations_bundle_fingerprint_check CHECK ((bundle_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT odds_input_configurations_configuration_revision_check CHECK ((configuration_revision > 0)),
    CONSTRAINT odds_input_configurations_historical_ratings_check CHECK ((jsonb_typeof(historical_ratings) = 'object'::text)),
    CONSTRAINT odds_input_configurations_ratings_fingerprint_check CHECK ((ratings_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT odds_input_configurations_settings_check CHECK ((jsonb_typeof(settings) = 'array'::text)),
    CONSTRAINT odds_input_configurations_settings_fingerprint_check CHECK ((settings_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT odds_input_effective_fingerprint_format CHECK (((effective_settings_fingerprint IS NULL) OR (effective_settings_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT odds_input_effective_settings_object CHECK (((effective_settings IS NULL) OR (jsonb_typeof(effective_settings) = 'object'::text))),
    CONSTRAINT odds_input_source_fingerprint_format CHECK (((source_fingerprint IS NULL) OR (source_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT odds_input_validation_status CHECK (((validation_status IS NULL) OR (validation_status = ANY (ARRAY['VALID'::text, 'INVALID'::text]))))
);


ALTER TABLE scoring_authority.odds_input_configurations OWNER TO postgres;

--
-- Name: canonical_odds_inputs_v2(text, text, jsonb, boolean, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_odds_inputs_v2(target text, destination_workbook text, input jsonb, require_exact_revision boolean, context jsonb) RETURNS scoring_authority.odds_input_configurations
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  config scoring_authority.odds_input_configurations%rowtype;
  revision jsonb := input->'source_revision';
begin
  select value.* into strict config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target and value.is_current;
  if (context is null and target = '2026')
     or config.source_workbook_id is distinct from destination_workbook
     or config.validation_status is distinct from 'VALID'
     or config.settings_contract_version is distinct from
       'prediction-settings-v1'
     or coalesce(config.source_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or config.settings_fingerprint !~ '^[0-9a-f]{64}$'
     or config.effective_settings_fingerprint !~ '^[0-9a-f]{64}$'
     or config.bundle_fingerprint !~ '^[0-9a-f]{64}$'
     or config.ratings_fingerprint !~ '^[0-9a-f]{64}$'
     or config.pairing_fingerprint !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(config.effective_settings) <> 'object'
     or scoring_authority.jsonb_object_length(
       config.effective_settings
     ) <> 30 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_PREDICTION_SETTINGS_NOT_CURRENT';
  end if;
  if require_exact_revision and (
    pg_catalog.jsonb_typeof(revision) <> 'object'
    or input->>'input_configuration_id' is distinct from config.id::text
    or coalesce((input->>'configuration_revision')::bigint, -1)
      <> config.configuration_revision
    or pg_catalog.lower(coalesce(input->>'settings_fingerprint', ''))
      is distinct from config.settings_fingerprint
    or pg_catalog.lower(coalesce(
      input->>'effective_settings_fingerprint', ''
    )) is distinct from config.effective_settings_fingerprint
    or pg_catalog.lower(coalesce(input->>'input_bundle_fingerprint', ''))
      is distinct from config.bundle_fingerprint
    or pg_catalog.lower(coalesce(revision->>'source_fingerprint', ''))
      is distinct from pg_catalog.lower(config.source_fingerprint)
    or pg_catalog.lower(coalesce(revision->>'bundle_fingerprint', ''))
      is distinct from config.bundle_fingerprint
    or pg_catalog.lower(coalesce(revision->>'settings_fingerprint', ''))
      is distinct from config.settings_fingerprint
    or pg_catalog.lower(coalesce(
      revision->>'effective_settings_fingerprint', ''
    )) is distinct from config.effective_settings_fingerprint
    or pg_catalog.lower(coalesce(revision->>'ratings_fingerprint', ''))
      is distinct from config.ratings_fingerprint
    or pg_catalog.lower(coalesce(revision->>'pairing_fingerprint', ''))
      is distinct from config.pairing_fingerprint
    or coalesce((revision->>'configuration_revision')::bigint, -1)
      <> config.configuration_revision
    or revision->>'annual_tournament_id' is distinct from target
    or revision->>'annual_runtime_generation_id' is distinct from
      input->>'expected_runtime_generation_id'
    or coalesce((revision->>'annual_pointer_revision')::bigint, -1)
      <> coalesce((input->>'expected_pointer_revision')::bigint, -2)
    or revision->>'annual_authority_generation_id' is distinct from
      input->>'expected_annual_authority_generation_id'
    or revision->>'annual_admission_generation_id' is distinct from
      input->>'expected_annual_admission_generation_id'
  ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_ODDS_INPUT_REVISION_STALE';
  end if;
  return config;
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_ODDS_INPUT_CONFIGURATION_REQUIRED';
end;
$_$;


ALTER FUNCTION production_control.canonical_odds_inputs_v2(target text, destination_workbook text, input jsonb, require_exact_revision boolean, context jsonb) OWNER TO postgres;

--
-- Name: canonical_player_editorial_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_player_editorial_read_v1(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  result_value jsonb;
  players_value jsonb;
begin
  result_value := production_control.canonical_projection_read_v1(
    input,
    'PLAYER_EDITORIAL',
    'player-public-profile-v1',
    '["Players"]'::jsonb,canonical_context
  );

  if result_value->>'ok' is distinct from 'true'
     or pg_catalog.jsonb_typeof(
       result_value#>'{data,payload,players}'
     ) is distinct from 'array' then
    return result_value;
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    case when profile.player_id is null then editorial.value
      else pg_catalog.jsonb_set(
        editorial.value,
        '{public_profile,Active}',
        pg_catalog.to_jsonb(profile.global_status = 'ACTIVE'),
        true
      )
    end order by editorial.ordinality
  ), '[]'::jsonb)
  into players_value
  from pg_catalog.jsonb_array_elements(
    result_value#>'{data,payload,players}'
  ) with ordinality as editorial(value, ordinality)
  left join production_control.player_governance_profiles_v1 profile
    on profile.player_id = pg_catalog.btrim(coalesce(
      editorial.value->>'player_id', ''
    ));

  return pg_catalog.jsonb_set(
    result_value,
    '{data,payload,players}',
    players_value,
    false
  );
end;
$$;


ALTER FUNCTION production_control.canonical_player_editorial_read_v1(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_prepare_annual_scoring_transition_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_prepare_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  existing jsonb;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  target production_control.future_tournament_catalog_v1%rowtype;
  readiness jsonb;
  generation_id uuid := extensions.gen_random_uuid();
  authority_id uuid := extensions.gen_random_uuid();
  admission_id uuid := extensions.gen_random_uuid();
  actor_player text := pg_catalog.upper(pg_catalog.btrim(
    input#>>'{authorization,player_id}'
  ));
  actor_auth uuid := (input#>>'{authorization,auth_user_id}')::uuid;
  transition_value production_control.annual_scoring_transitions_v1%rowtype;
  response_value jsonb;
begin
  perform production_control.assert_canonical_annual_transition_context_v2(input,canonical_context);
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'PREPARE', input, canonical_context
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_canonical_annual_scoring_receipt_v2(
    'PREPARE', input, canonical_context
  );
  if existing is not null then return existing; end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = canonical_context->>'resource_id' for update;
  select value.* into strict target
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = input->>'target_tournament_id' for update;
  readiness := production_control.annual_scoring_transition_readiness_v1(
    target.tournament_id
  );
  if input->>'expected_current_tournament_id' is distinct from
       pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or coalesce((input->>'expected_revision')::bigint, -1)
       <> target.lifecycle_revision
     or target.lifecycle <> 'CONFIGURING'
     or input->>'readiness_fingerprint'
       is distinct from readiness->>'fingerprint'
     or pointer.tournament_id = target.tournament_id
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(
         coalesce(readiness->'blockers', '[]'::jsonb)
       ) blocker
       where blocker->>'code' <>
         'FUTURE_PREDECESSOR_SCORING_CLOSE_FENCE_NOT_CERTIFIED'
     )
     or exists (
       select 1
       from production_control.annual_scoring_transitions_v1 value
       where value.transition_status in ('PREPARED', 'CLOSING', 'CLOSED')
     )
     or exists (
       select 1
       from production_control.postcutover_normal_release_intents value
       where value.scope_key = canonical_context->>'resource_id'
         and value.status = 'PENDING'
     )
     or exists (
       select 1
       from production_control.future_annual_runtime_generations_v1 value
       where value.tournament_id = target.tournament_id
         and value.generation_status <> 'ABORTED'
     ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PRECOMMIT_ABORTED',
      detail = coalesce((readiness->'blockers')::text, '[]');
  end if;
  insert into production_control.future_annual_runtime_generations_v1 (
    runtime_generation_id, tournament_id, generation_status,
    runtime_revision, pointer_revision, authority_generation_id,
    admission_generation_id, authority, ingress_state,
    readiness_fingerprint
  ) values (
    generation_id, target.tournament_id, 'PREPARED', 1,
    pointer.pointer_revision + 1, authority_id, admission_id,
    'SUPABASE', 'OPEN', readiness->>'fingerprint'
  );
  update production_control.future_tournament_catalog_v1 set
    lifecycle = 'READY_FOR_ACTIVATION',
    lifecycle_revision = lifecycle_revision + 1,
    readiness_fingerprint = readiness->>'fingerprint',
    readiness_setup_revision = setup_revision,
    updated_by_player_id = actor_player,
    updated_by_auth_user_id = actor_auth,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target.tournament_id
    and lifecycle = 'CONFIGURING'
    and lifecycle_revision = target.lifecycle_revision;
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PRECOMMIT_ABORTED';
  end if;
  update production_control.future_runtime_promotions_v2 set
    runtime_status = 'READY', updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target.tournament_id;
  insert into production_control.annual_scoring_transitions_v1 (
    resource_class,certification_resource_id,contract_version, transition_status, predecessor_tournament_id,
    successor_tournament_id, expected_pointer_revision,
    predecessor_lifecycle_revision,
    successor_prepared_lifecycle_revision, predecessor_closure_id,
    predecessor_boundary_fingerprint, runtime_generation_id,
    authority_generation_id, admission_generation_id,
    readiness_fingerprint, prepared_by_player_id,
    prepared_by_auth_user_id
  ) values (
    canonical_context->>'resource_class',case when canonical_context->>'resource_class'='CERTIFICATION' then canonical_context->>'resource_id' end,
    'production-annual-scoring-transition-v1', 'PREPARED',
    pointer.tournament_id, target.tournament_id, pointer.pointer_revision,
    pointer.lifecycle_revision, target.lifecycle_revision + 1,
    null, null, generation_id, authority_id, admission_id,
    readiness->>'fingerprint', actor_player, actor_auth
  ) returning * into transition_value;
  perform production_control.assert_future_scoring_runtime_capability_v1(
    target.tournament_id, generation_id, authority_id, admission_id
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_ANNUAL_SCORING_TRANSITION_PREPARED',
    'transitionId', transition_value.transition_id,
    'predecessorTournamentId', pointer.tournament_id,
    'successorTournamentId', target.tournament_id,
    'expectedPointerRevision', pointer.pointer_revision,
    'runtimeGenerationId', generation_id,
    'authorityGenerationId', authority_id,
    'admissionGenerationId', admission_id,
    'readinessFingerprint', readiness->>'fingerprint',
    'pointerChanged', false, 'predecessorClosed', false,
    'predecessorAdmissionStopped', false,
    'successorActivated', false, 'idempotent', false
  );
  perform production_control.store_canonical_annual_scoring_receipt_v2(
    'PREPARE', input, response_value, canonical_context
  );
  return response_value;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PRECOMMIT_ABORTED';
end;
$$;


ALTER FUNCTION production_control.canonical_prepare_annual_scoring_transition_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_projection_read_v1(jsonb, text, text, jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_projection_read_v1(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  revision production_control.projection_revisions%rowtype;
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  active_read boolean;
  cert_resource production_control.canonical_resource_v1%rowtype;
begin
  if canonical_context is null then
  perform production_control.assert_projection_read_scope(
    input, expected_domain, expected_contract, expected_tabs
  );
  select * into strict resource from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict activation from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';
  active_read := resource.public_supabase_reads_enabled;
  else
    cert_resource:=production_control.assert_certification_read_v1(canonical_context,input);
    if canonical_context->>'current_tournament_id'<>'2026'
      or input->>'domain' is distinct from expected_domain
      or input->>'contract_version' is distinct from expected_contract
      or input->'source_tabs' is distinct from expected_tabs then
      raise exception using errcode='42501',message='CERTIFICATION_PROJECTION_CONTRACT_REQUIRED';
    end if;
    active_read:=true;
  end if;
  select value.* into revision
  from production_control.projection_current pointer
  join production_control.projection_revisions value on value.revision_id = pointer.revision_id
  where pointer.domain = expected_domain and pointer.tournament_id = '2026';
  if revision.revision_id is null then
    return jsonb_build_object('ok',false,'code',expected_domain || '_PROJECTION_UNAVAILABLE');
  end if;
  if canonical_context is not null and (revision.project_ref is distinct from cert_resource.project_ref
    or revision.project_url is distinct from cert_resource.project_url
    or revision.source_workbook_id is distinct from cert_resource.provenance_id) then
    raise exception using errcode='55000',message='CERTIFICATION_PROJECTION_PROVENANCE_INVALID';
  end if;
  return jsonb_build_object('ok',true,'data',jsonb_build_object(
    'domain',revision.domain,'tournament_id',revision.tournament_id,
    'tournament_year',revision.tournament_year,'revision_id',revision.revision_id,
    'revision_number',revision.revision_number,'previous_revision_id',revision.previous_revision_id,
    'source_workbook_id',revision.source_workbook_id,'source_tabs',revision.source_tabs,
    'contract_version',revision.contract_version,'source_fingerprint',revision.source_fingerprint,
    'payload_fingerprint',revision.payload_fingerprint,'validation_status',revision.validation_status,
    'validation_diagnostics',revision.validation_diagnostics,'payload',revision.projection_payload,
    'imported_by',revision.imported_by,'imported_at',revision.imported_at,
    'google_foreground_requests',0,'fallback_used',false,
    'authoritative',active_read,'shadow_only',not active_read
  ),
  'google_foreground_requests',0,'fallback_used',false,
  'authoritative',active_read,'shadow_only',not active_read,
  'cutover_phase',case when active_read and canonical_context is null then activation.read_cutover_phase else null end,
  'activation_revision',case when canonical_context is not null then (canonical_context->>'activation_revision')::bigint when active_read then activation.activation_revision else null end,
  'deployment_commit',case when canonical_context is not null then canonical_context->>'release_commit' when active_read then activation.expected_deployment_commit else null end);
end;
$$;


ALTER FUNCTION production_control.canonical_projection_read_v1(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_publish_calcutta_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_publish_calcutta_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  current_value scoring_authority.calcutta_v1_current%rowtype;
  publication_value scoring_authority.calcutta_v1_publication_revisions%rowtype;
  existing_response jsonb;
  response_value jsonb;
  job_value jsonb;
  result_value scoring_authority.calcutta_v1_result_revisions%rowtype;
  source_fingerprint text;
  affected_rows bigint;
  request_fingerprint_value text := pg_catalog.lower(
    coalesce(input->>'request_fingerprint', '')
  );
  actor_player text := pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  ));
  actor_auth_user uuid := nullif(
    input#>>'{authorization,auth_user_id}', ''
  )::uuid;
begin
  if context is null then
    perform production_control.assert_production_calcutta_v1_runtime(input);
  else
    perform production_control.assert_canonical_scoring_context_v1(input,context,'RUNTIME');
    if context->>'phase' is distinct from 'DIRECTOR'
      or (not production_control.model_d_context_v1(context) and (context->>'resource_id' is distinct from 'CERTIFICATION:2857f707-065a-405d-b5fc-b5b6fa1b0f51' or context->>'project_ref' is distinct from 'trmcwrljjxwhgtikfdgu')) then
      raise exception using errcode='42501',message='CERTIFICATION_CALCUTTA_PUBLICATION_TARGET_DENIED';
    end if;
    -- Match/source mutations lock access/setup before match rows. Use that
    -- same order so current-result validation and publication are atomic.
    perform pg_advisory_xact_lock(hashtextextended('production-access-governance-v1:2026',0));
    perform pg_advisory_xact_lock(hashtextextended('production-tournament-setup-v1:2026',0));
    perform 1 from scoring_authority.matches m where m.tournament_id='2026' order by m.match_id for share;
  end if;
  perform production_control.assert_production_scoring_actor(input, true);
  existing_response := production_control.lookup_cutover_receipt(
    'CALCUTTA_V1_PUBLISH', input
  );
  if existing_response is not null then return existing_response; end if;
  if request_fingerprint_value !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_PUBLICATION_INPUT_INVALID';
  end if;

  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026'
  for update;
  if current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1)
     or current_value.configuration_fingerprint is distinct from
       nullif(input->>'expected_configuration_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REVISION_CONFLICT';
  end if;
  if current_value.auction_revision <>
       coalesce((input->>'expected_auction_revision')::bigint, -1)
     or current_value.auction_fingerprint is distinct from
       nullif(input->>'expected_auction_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_AUCTION_REVISION_CONFLICT';
  end if;
  if current_value.publication_revision <>
       coalesce((input->>'expected_publication_revision')::bigint, -1) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_PUBLICATION_REVISION_CONFLICT';
  end if;
  if current_value.state = 'NOT_CONFIGURED'
     or current_value.auction_revision = 0
     or current_value.auction_revision_id is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_AUCTION_FACTS_REQUIRED';
  end if;

  if context is not null then
    source_fingerprint:=production_control.calcutta_v1_hash(production_control.calcutta_v1_source_revision('2026'));
    select r.* into result_value from scoring_authority.calcutta_v1_result_revisions r
      where r.tournament_id='2026' and r.is_current and r.result_revision=current_value.result_revision
        and r.configuration_revision=current_value.configuration_revision
        and r.configuration_fingerprint=current_value.configuration_fingerprint
        and r.auction_revision=current_value.auction_revision
        and r.auction_fingerprint=current_value.auction_fingerprint;
    if not found or result_value.source_fingerprint is distinct from source_fingerprint
      or result_value.result_revision is distinct from (input->>'expected_result_revision')::bigint
      or source_fingerprint is distinct from input->>'expected_source_fingerprint' then
      raise exception using errcode='PT409',message='PRODUCTION_CALCUTTA_RESULT_SOURCE_CONFLICT';
    end if;
  end if;

  if current_value.publication_state = 'PUBLISHED' then
    response_value := pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_CALCUTTA_V1_ALREADY_PUBLISHED',
      'state', current_value.state,
      'publication_state', 'PUBLISHED',
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'publication_revision', current_value.publication_revision,
      'result_revision', nullif(current_value.result_revision, 0),
      'job', null,
      'idempotent', true
    );
    perform production_control.store_cutover_receipt(
      'CALCUTTA_V1_PUBLISH', input, response_value
    );
    return response_value;
  end if;

  insert into scoring_authority.calcutta_v1_publication_revisions (
    tournament_id, publication_revision, configuration_revision,
    auction_revision, configuration_fingerprint, auction_fingerprint,
    publication_state, action, actor_player_id, actor_auth_user_id,
    request_fingerprint, request_payload_hash, published_at
  ) values (
    '2026', current_value.publication_revision + 1,
    current_value.configuration_revision, current_value.auction_revision,
    current_value.configuration_fingerprint,
    current_value.auction_fingerprint, 'PUBLISHED',
    'DIRECTOR_PUBLISHED', actor_player, actor_auth_user,
    request_fingerprint_value,
    production_control.calcutta_v1_hash(input), pg_catalog.now()
  ) returning * into publication_value;

  update scoring_authority.calcutta_v1_current
  set publication_revision_id = publication_value.publication_revision_id,
      publication_revision = publication_value.publication_revision,
      publication_state = 'PUBLISHED', updated_at = pg_catalog.now()
  where tournament_id = '2026';

  get diagnostics affected_rows=row_count;
  if affected_rows<>1 then raise exception using errcode='PT409',message='PRODUCTION_CALCUTTA_PUBLICATION_POINTER_DRIFT';end if;

  job_value := production_control.enqueue_production_calcutta_v1(
    'DIRECTOR_PUBLISHED', actor_player, false, null, null
  );
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026';

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'PRODUCTION_CALCUTTA_V1_PUBLISHED', actor_player,
    pg_catalog.jsonb_build_object(
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'publication_revision', current_value.publication_revision,
      'result_revision', nullif(current_value.result_revision, 0),
      'publication_policy',
        'DIRECTOR_CONTROLLED_PARTICIPANT_FULL_MARKET',
      'authority_changed', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_CALCUTTA_V1_PUBLISHED', 'CALCUTTA', '2026',
    actor_player, request_fingerprint_value, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'configuration_revision', current_value.configuration_revision,
      'auction_revision', current_value.auction_revision,
      'publication_revision', current_value.publication_revision,
      'result_revision', nullif(current_value.result_revision, 0),
      'job_id', job_value->>'job_id'
    )
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_CALCUTTA_V1_PUBLISHED',
    'state', current_value.state,
    'publication_state', 'PUBLISHED',
    'configuration_revision', current_value.configuration_revision,
    'configuration_fingerprint', current_value.configuration_fingerprint,
    'auction_revision', current_value.auction_revision,
    'auction_fingerprint', current_value.auction_fingerprint,
    'publication_revision', current_value.publication_revision,
    'result_revision', nullif(current_value.result_revision, 0),
    'job', job_value,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'CALCUTTA_V1_PUBLISH', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.canonical_publish_calcutta_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: canonical_publish_guide_draft_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_publish_guide_draft_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  target_year integer;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}','')));
  actor_auth uuid;
  request_id uuid;
  draft_id_value uuid;
  expected_draft_version bigint;
  expected_published_revision bigint;
  expected_published_revision_id_text text := pg_catalog.lower(
    pg_catalog.btrim(coalesce(input->>'expected_published_revision_id','')));
  expected_content_fingerprint text := pg_catalog.lower(
    pg_catalog.btrim(coalesce(input->>'expected_content_fingerprint','')));
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason',''));
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash','')));
  authoring_value jsonb := coalesce(input->'authoring_content',input->'content');
  projection_value jsonb := input->'projection_payload';
  database_hash text;
  prior_receipt jsonb;
  draft production_control.guide_authoring_drafts_v1%rowtype;
  current_value jsonb;
  validation jsonb;
  annual_pointer production_control.current_tournament_pointer_v1%rowtype;
  resource production_control.canonical_resource_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  annual_resource production_control.future_tournament_resources_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  binding production_control.future_annual_projection_bindings_v1%rowtype;
  next_revision bigint;
  next_binding_revision bigint;
  native_revision_id uuid;
  previous_native_revision_id uuid;
  production_revision_id uuid;
  legacy_current_projection_id uuid;
  guide_revision_id uuid;
  source_value jsonb;
  source_text text;
  content_text text;
  payload_text text;
  source_hash text;
  effective_at_value timestamptz;
  response_value jsonb;
begin
  target := production_control.assert_guide_authoring_resource_v2(input, resource_context);
  target_year := target::integer;
  if input->>'operation' is distinct from
       'PUBLISH_PRODUCTION_GUIDE_DRAFT_V1'
     or coalesce(input->>'operation_request_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'draft_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_draft_version','') !~ '^[1-9][0-9]*$'
     or coalesce(input->>'expected_published_revision','') !~ '^[0-9]+$'
     or expected_content_fingerprint !~ '^[0-9a-f]{64}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authoring_content_fingerprint','')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'content_fingerprint','') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'projection_payload_hash','') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'canonical_reference_fingerprint','')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(authoring_value) is distinct from 'object'
     or pg_catalog.jsonb_typeof(projection_value) is distinct from 'object'
     or input->>'confirmation' is distinct from
       'PUBLISH TOURNAMENT GUIDE'
     or reason_value='' or pg_catalog.length(reason_value)>500 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_PUBLISH_INPUT_INVALID');
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  draft_id_value := (input->>'draft_id')::uuid;
  expected_draft_version := (input->>'expected_draft_version')::bigint;
  expected_published_revision :=
    (input->>'expected_published_revision')::bigint;
  database_hash := production_control.guide_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation','PUBLISH','tournamentId',target,
      'actorPlayerId',actor_player,'actorAuthUserId',actor_auth,
      'draftId',draft_id_value,'expectedDraftVersion',expected_draft_version,
      'expectedPublishedRevision',expected_published_revision,
      'expectedPublishedRevisionId',expected_published_revision_id_text,
      'expectedContentFingerprint',expected_content_fingerprint,
      'authoringContent',authoring_value,'projectionPayload',projection_value,
      'canonicalReferenceFingerprint',
        input->>'canonical_reference_fingerprint',
      'confirmation',input->>'confirmation','reason',reason_value));
  prior_receipt := production_control.guide_operation_receipt_v1(
    target,'PUBLISH',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-guide-authoring:'||target,0));
  prior_receipt := production_control.guide_operation_receipt_v1(
    target,'PUBLISH',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  perform 1 from production_control.guide_authoring_current_v1 value
    where value.tournament_id=target for update;
  if target='2026' then
    select value.revision_id into legacy_current_projection_id
    from production_control.projection_current value
    where value.domain='GUIDE' and value.tournament_id=target for update;
    perform 1 from scoring_authority.guide_projection_current value
      where value.tournament_id=target for update;
  else
    perform 1 from production_control.future_annual_projection_bindings_v1 value
      where value.tournament_id=target and value.domain='GUIDE' for update;
  end if;
  select value.* into strict draft
  from production_control.guide_authoring_drafts_v1 value
  where value.draft_id=draft_id_value and value.tournament_id=target
  for update;
  current_value := production_control.guide_current_publication_v1(target);
  if draft.state<>'VALIDATED' or draft.draft_version<>expected_draft_version
     or coalesce((draft.validation_diagnostics->>'validated')::boolean,false)
       is not true
     or coalesce((draft.validation_diagnostics->>'validatedDraftVersion')::bigint,0)
       <> expected_draft_version then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_VALIDATED_DRAFT_REQUIRED');
  end if;
  if draft.expected_published_revision<>(current_value->>'revision')::bigint
     or draft.expected_published_revision_id::text is distinct from
       nullif(current_value->>'revisionId','')
     or expected_published_revision<>draft.expected_published_revision
     or (expected_published_revision_id_text<>'' and
       expected_published_revision_id_text is distinct from
         pg_catalog.lower(coalesce(current_value->>'revisionId',''))) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_PREDECESSOR_STALE',
      'currentRevision',(current_value->>'revision')::bigint);
  end if;
  if authoring_value is distinct from draft.authoring_content
     or projection_value is distinct from draft.projection_payload then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_DRAFT_CONTENT_STALE');
  end if;
  if input->>'canonical_reference_fingerprint' is distinct from
       production_control.guide_canonical_reference_fingerprint_v1(target)
     or draft.canonical_reference_fingerprint is distinct from
       input->>'canonical_reference_fingerprint'
     or draft.validated_canonical_reference_fingerprint is distinct from
       input->>'canonical_reference_fingerprint' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_CANONICAL_REFERENCE_STALE');
  end if;
  validation := production_control.validate_guide_authoring_v1(
    target,target_year,authoring_value,projection_value,
    input->>'authoring_content_fingerprint',input->>'content_fingerprint',
    input->>'projection_payload_hash');
  if not coalesce((validation->>'pass')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_VALIDATION_FAILED','issues',validation->'issues');
  end if;
  if validation->>'authoringContentFingerprint' is distinct from
       draft.authoring_content_fingerprint
     or validation->>'contentFingerprint' is distinct from
       draft.content_fingerprint
     or validation->>'contentFingerprint' is distinct from
       draft.validated_content_fingerprint
     or validation->>'projectionPayloadHash' is distinct from
       draft.projection_payload_hash
     or expected_content_fingerprint is distinct from
       draft.validated_content_fingerprint then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_DRAFT_VALIDATION_STALE');
  end if;
  if current_value->>'projectionPayloadHash' =
       validation->>'projectionPayloadHash' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_NO_CHANGES');
  end if;

  select value.* into strict annual_pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key=(resource_context->>'resource_id');
  select value.* into strict resource
  from production_control.canonical_resource_v1 value
  where value.resource_id=(resource_context->>'resource_id');
  select value.revision_id into previous_native_revision_id
  from production_control.guide_authoring_current_v1 value
  where value.tournament_id=target;
  next_revision := (current_value->>'revision')::bigint + 1;
  effective_at_value := pg_catalog.clock_timestamp();
  source_value := pg_catalog.jsonb_build_object(
    'tournamentId',target,
    'source',pg_catalog.jsonb_build_object(
      'authoringAuthority','SUPABASE_DIRECTOR',
      'authoringContract','production-guide-authoring-v1',
      'sourceTabs',production_control.guide_authoring_source_tabs_v1(),
      'draftId',draft_id_value,'draftVersion',draft.draft_version));
  source_text := production_control.guide_authoring_canonical_json_v1(
    source_value);
  content_text := production_control.guide_authoring_canonical_json_v1(
    validation->'projectionPayload'->'content');
  payload_text := production_control.guide_authoring_canonical_json_v1(
    validation->'projectionPayload');
  source_hash := pg_catalog.encode(extensions.digest(source_text,'sha256'),'hex');

  if target='2026' then
    insert into production_control.projection_revisions (
      domain,tournament_id,tournament_year,revision_number,
      previous_revision_id,project_ref,project_url,source_workbook_id,
      source_tabs,contract_version,source_fingerprint,payload_fingerprint,
      source_payload,projection_payload,validation_status,
      validation_diagnostics,imported_by,imported_at
    ) values (
      'GUIDE','2026',2026,next_revision,
      legacy_current_projection_id,
      resource.project_ref,resource.project_url,resource.provenance_id,
      production_control.guide_authoring_source_tabs_v1(),
      'guide-projection-v1',source_hash,
      validation->>'projectionPayloadHash',source_value,
      validation->'projectionPayload','VALID',
      (validation->'diagnostics')||pg_catalog.jsonb_build_object(
        'authoringAuthority','SUPABASE_DIRECTOR',
        'authoringContract','production-guide-authoring-v1'),
      actor_player,effective_at_value
    ) returning revision_id into production_revision_id;
    insert into production_control.projection_current (
      domain,tournament_id,revision_id,advanced_by,advanced_at
    ) values (
      'GUIDE','2026',production_revision_id,actor_player,effective_at_value
    ) on conflict (domain,tournament_id) do update set
      revision_id=excluded.revision_id,advanced_by=excluded.advanced_by,
      advanced_at=excluded.advanced_at;

    select value.revision_id into guide_revision_id
    from scoring_authority.guide_content_revisions value
    where value.tournament_id='2026'
      and value.content_fingerprint=validation->>'contentFingerprint';
    if guide_revision_id is null then
      insert into scoring_authority.guide_content_revisions (
        tournament_id,projection_revision,source_workbook_id,
        content_fingerprint,source_workbook_fingerprint,payload_hash,
        source_canonical_json,content_canonical_json,payload_canonical_json,
        content_payload,validation_status,source_metadata,
        source_sync_sequence,trigger_type,imported_by,imported_at
      ) values (
        '2026',next_revision,resource.provenance_id,
        validation->>'contentFingerprint',source_hash,
        validation->>'projectionPayloadHash',source_text,content_text,
        payload_text,validation->'projectionPayload','VALID',
        pg_catalog.jsonb_build_object(
          'authoringAuthority','SUPABASE_DIRECTOR',
          'authoringContract','production-guide-authoring-v1',
          'draftVersion',draft.draft_version),
        next_revision,'MANUAL',actor_player,effective_at_value
      ) returning revision_id into guide_revision_id;
    end if;
    insert into scoring_authority.guide_projection_current (
      tournament_id,source_workbook_id,revision_id,publication_sequence,
      source_sync_sequence,published_at,last_verified_at
    ) values (
      '2026',resource.provenance_id,guide_revision_id,next_revision,
      next_revision,effective_at_value,effective_at_value
    ) on conflict (tournament_id) do update set
      source_workbook_id=excluded.source_workbook_id,
      revision_id=excluded.revision_id,
      publication_sequence=excluded.publication_sequence,
      source_sync_sequence=excluded.source_sync_sequence,
      published_at=excluded.published_at,
      last_verified_at=excluded.last_verified_at;
  else
    select value.* into strict catalog
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id=target for update;
    select value.* into strict annual_resource
    from production_control.future_tournament_resources_v1 value
    where value.tournament_id=target for share;
    select value.* into promotion
    from production_control.future_runtime_promotions_v2 value
    where value.tournament_id=target;
    select value.* into binding
    from production_control.future_annual_projection_bindings_v1 value
    where value.tournament_id=target and value.domain='GUIDE' for update;
    update production_control.future_tournament_catalog_v1 value set
      lifecycle=case when value.lifecycle='READY_FOR_ACTIVATION'
        then 'CONFIGURING' else value.lifecycle end,
      lifecycle_revision=case when value.lifecycle='READY_FOR_ACTIVATION'
        then value.lifecycle_revision+1 else value.lifecycle_revision end,
      setup_revision=case when promotion.tournament_id is null
        then value.setup_revision+1 else value.setup_revision end,
      readiness_fingerprint=null,readiness_setup_revision=null,
      updated_by_player_id=actor_player,updated_at=effective_at_value
    where value.tournament_id=target;
    next_binding_revision:=coalesce(binding.binding_revision,0)+1;
    insert into production_control.future_annual_projection_bindings_v1 (
      tournament_id,domain,source_workbook_id,source_revision,
      binding_revision,source_fingerprint,payload_fingerprint,projection,
      certification_status,certified_by_player_id,certified_at,
      authoring_authority
    ) values (
      target,'GUIDE',coalesce(annual_resource.source_workbook_id,
        'SUPABASE_DIRECTOR'),next_revision,
      next_binding_revision,source_hash,validation->>'projectionPayloadHash',
      validation->'projectionPayload','CERTIFIED',actor_player,
      effective_at_value,'SUPABASE_DIRECTOR'
    ) on conflict (tournament_id,domain) do update set
      source_workbook_id=excluded.source_workbook_id,
      source_revision=excluded.source_revision,
      binding_revision=excluded.binding_revision,
      source_fingerprint=excluded.source_fingerprint,
      payload_fingerprint=excluded.payload_fingerprint,
      projection=excluded.projection,
      certification_status=excluded.certification_status,
      certified_by_player_id=excluded.certified_by_player_id,
      certified_at=excluded.certified_at,
      authoring_authority=excluded.authoring_authority,
      updated_at=effective_at_value;
  end if;

  insert into production_control.guide_authoring_revisions_v1 (
    tournament_id,tournament_year,revision_number,
    previous_published_revision,previous_published_revision_id,
    previous_native_revision_id,draft_id,authoring_content,
    projection_payload,authoring_content_fingerprint,content_fingerprint,
    projection_payload_hash,validation_diagnostics,
    production_projection_revision_id,guide_content_revision_id,
    annual_binding_revision,published_by_player_id,published_by_auth_user_id,
    published_at
  ) values (
    target,target_year,next_revision,(current_value->>'revision')::bigint,
    nullif(current_value->>'revisionId','')::uuid,previous_native_revision_id,
    draft_id_value,validation->'authoringContent',
    validation->'projectionPayload',validation->>'authoringContentFingerprint',
    validation->>'contentFingerprint',validation->>'projectionPayloadHash',
    (validation->'diagnostics')||pg_catalog.jsonb_build_object(
      'authoringAuthority','SUPABASE_DIRECTOR'),production_revision_id,
    guide_revision_id,case when target='2026' then null
      else next_binding_revision end,actor_player,actor_auth,effective_at_value
  ) returning revision_id into native_revision_id;
  insert into production_control.guide_authoring_revision_provenance_v1 (
    revision_id,tournament_id,authoring_authority,authoring_contract,draft_id,
    actor_player_id,actor_auth_user_id,authoring_kind,source_tournament_id,
    created_at
  ) values (
    native_revision_id,target,'SUPABASE_DIRECTOR',
    'production-guide-authoring-v1',draft_id_value,actor_player,actor_auth,
    draft.authoring_kind,draft.source_tournament_id,effective_at_value);
  insert into production_control.guide_authoring_current_v1 (
    tournament_id,tournament_year,revision_id,revision_number,
    advanced_by_player_id,advanced_by_auth_user_id,advanced_at
  ) values (
    target,target_year,native_revision_id,next_revision,
    actor_player,actor_auth,effective_at_value
  ) on conflict (tournament_id) do update set
    tournament_year=excluded.tournament_year,
    revision_id=excluded.revision_id,revision_number=excluded.revision_number,
    advanced_by_player_id=excluded.advanced_by_player_id,
    advanced_by_auth_user_id=excluded.advanced_by_auth_user_id,
    advanced_at=excluded.advanced_at;
  update production_control.guide_authoring_drafts_v1 set
    state='SUPERSEDED',published_revision_id=null,published_at=null,
    validated_content_fingerprint=null,
    validated_canonical_reference_fingerprint=null,
    updated_at=effective_at_value
  where tournament_id=target and state='PUBLISHED';
  update production_control.guide_authoring_drafts_v1 set
    state='PUBLISHED',draft_version=draft_version+1,
    published_revision_id=native_revision_id,published_at=effective_at_value,
    updated_at=effective_at_value
  where draft_id=draft_id_value;

  response_value:=pg_catalog.jsonb_build_object(
    'ok',true,'code','GUIDE_REVISION_PUBLISHED','idempotent',false,
    'tournamentId',target,'revisionId',native_revision_id,
    'revision',next_revision,
    'previousRevision',(current_value->>'revision')::bigint,
    'authoringAuthority','SUPABASE_DIRECTOR',
    'effectiveAt',effective_at_value,
    'current',pg_catalog.jsonb_build_object(
      'revision',next_revision,'revisionId',native_revision_id,
      'authoringAuthority','SUPABASE_DIRECTOR',
      'projectionPayload',validation->'projectionPayload',
      'contentFingerprint',validation->>'contentFingerprint',
      'projectionPayloadHash',validation->>'projectionPayloadHash'));
  insert into production_control.guide_authoring_audit_events_v1 (
    tournament_id,draft_id,revision_id,action,actor_player_id,
    actor_auth_user_id,summary
  ) values (
    target,draft_id_value,native_revision_id,'REVISION_PUBLISHED',
    actor_player,actor_auth,pg_catalog.jsonb_build_object(
      'revision',next_revision,
      'predecessorRevision',(current_value->>'revision')::bigint,
      'summary','Tournament Guide Revision '||next_revision||' published'));
  insert into production_control.operation_audit_events (
    event_type,domain,tournament_id,actor,request_fingerprint,result,details
  ) values (
    'PRODUCTION_GUIDE_REVISION_PUBLISHED','GUIDE',target,actor_player,null,
    'SUCCEEDED',pg_catalog.jsonb_build_object(
      'revision',next_revision,'authoring_authority','SUPABASE_DIRECTOR'));
  insert into production_control.guide_authoring_operation_receipts_v1 (
    tournament_id,operation,operation_request_id,
    declared_request_payload_hash,request_payload_hash,
    actor_player_id,actor_auth_user_id,response
  ) values (
    target,'PUBLISH',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value);
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_DRAFT_OR_RESOURCE_NOT_FOUND');
when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_PUBLISH_INPUT_INVALID');
when unique_violation then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_OPERATION_CONFLICT');
end;

$_$;


ALTER FUNCTION production_control.canonical_publish_guide_draft_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_publish_odds_v2(jsonb, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_publish_odds_v2(input jsonb, target text, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  annual_resource production_control.future_tournament_resources_v1%rowtype;
  current_value scoring_authority.odds_publication_current%rowtype;
  current_snapshot scoring_authority.odds_published_snapshots%rowtype;
  job scoring_authority.odds_calculation_jobs%rowtype;
  config scoring_authority.odds_input_configurations%rowtype;
  created_snapshot scoring_authority.odds_published_snapshots%rowtype;
  response_value jsonb;
  binding jsonb;
  source_revision_value jsonb;
  binding_fingerprint text;
  payload_hash_value text;
  expected_revision bigint := coalesce(
    (input->>'expected_publication_revision')::bigint, -1
  );
  expected_snapshot uuid;
  next_revision bigint;
  next_milestone_revision bigint;
  phase_order_value integer;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth_user uuid;
  expected_authority_epoch uuid;
  request_fingerprint_value text := pg_catalog.lower(coalesce(
    input->>'request_fingerprint', ''
  ));
  expected_request_fingerprint text;
begin
  begin
    expected_snapshot := nullif(input->>'expected_snapshot_id', '')::uuid;
    actor_auth_user := nullif(
      input#>>'{authorization,auth_user_id}', ''
    )::uuid;
    expected_authority_epoch := nullif(
      input->>'expected_authority_epoch_id', ''
    )::uuid;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_PUBLICATION_INPUT_INVALID';
  end;
  if context is null then
  perform production_control.assert_future_production_scoring_actor_v1(
    input, target, true
  );
  expected_request_fingerprint := pg_catalog.encode(extensions.digest(
    pg_catalog.concat_ws(E'\n',
      'production-odds-publication-v1', 'PUBLISH', target,
      pg_catalog.lower(coalesce(input->>'job_id', '')),
      coalesce(input->>'expected_activation_revision', ''),
      pg_catalog.lower(coalesce(input->>'expected_authority_epoch_id', '')),
      pg_catalog.lower(coalesce(
        input#>>'{authorization,auth_user_id}', ''
      )), actor_player
    ), 'sha256'
  ), 'hex');
  if target = '2026'
     or input->>'operation' is distinct from
       'PUBLISH_PRODUCTION_CHAMPIONSHIP_ODDS_V1'
     or input->>'contract_version' is distinct from
       'production-odds-publication-v1'
     or input->>'target_tournament_id' is distinct from target
     or coalesce((input->>'target_tournament_year')::integer, 0)
       <> target::integer
     or input->>'vercel_team_id' is distinct from
       'team_kPw5zaib8uaQJALAwj4fWI6R'
     or input->>'vercel_environment' is distinct from 'production'
     or input->>'canonical_domain' is distinct from 'https://baggerinv.com'
     or coalesce(input->>'job_id', '') !~ '^[0-9a-f]{64}$'
     or expected_revision < 0
     or coalesce(input->>'deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'deployment_commit', '') !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'expected_activation_revision', '') !~ '^[0-9]+$'
     or expected_authority_epoch is null
     or request_fingerprint_value !~ '^[0-9a-f]{64}$'
     or request_fingerprint_value is distinct from
       expected_request_fingerprint then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_PUBLICATION_INPUT_INVALID';
  end if;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target
    and value.runtime_generation_id =
      (input->>'expected_runtime_generation_id')::uuid
    and value.generation_status = 'ACTIVE';
  select value.* into strict annual_resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target;
  else
    perform production_control.certification_odds_runtime_v1(context);
    perform production_control.assert_certification_odds_actor_v1(input,context);
    expected_request_fingerprint:=input->>'_certification_request_fingerprint';
    if input->>'operation'is distinct from 'PUBLISH_PRODUCTION_CHAMPIONSHIP_ODDS_V1'
     or input->>'contract_version'is distinct from 'production-odds-publication-v1'
     or input->>'target_tournament_id'is distinct from target or input->>'target_tournament_year'is distinct from target
     or coalesce(input->>'job_id','')!~'^[0-9a-f]{64}$'or expected_revision<0
     or expected_authority_epoch is distinct from (context->>'authority_epoch_id')::uuid
     or expected_request_fingerprint is null or request_fingerprint_value is distinct from expected_request_fingerprint then
     raise exception using errcode='22023',message='CERTIFICATION_ODDS_PUBLICATION_INPUT_INVALID';end if;
    generation.runtime_generation_id:=nullif(input->>'expected_runtime_generation_id','')::uuid;
    generation.pointer_revision:=(context->>'pointer_revision')::bigint;
    generation.authority_generation_id:=(context->>'authority_epoch_id')::uuid;
    generation.admission_generation_id:=(input->>'certification_ingress_generation_id')::uuid;
    annual_resource.source_workbook_id:=input->>'annual_destination_workbook_id';
  end if;
  select value.* into current_value
  from scoring_authority.odds_publication_current value
  where value.tournament_id = target for update;
  select value.* into job
  from scoring_authority.odds_calculation_jobs value
  where value.job_id = input->>'job_id' for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ODDS_CALCULATION_JOB_NOT_FOUND'
    );
  end if;
  perform production_control.assert_canonical_odds_job_v1(input,target,job,context);
  if job.status = 'SUCCEEDED'
     and job.publication_status = 'PUBLISHED'
     and job.publication_reference->>'contract_version'
       = 'production-odds-publication-v1'
     and job.publication_reference->>'request_fingerprint'
       = request_fingerprint_value then
    select value.* into strict created_snapshot
    from scoring_authority.odds_published_snapshots value
    where value.id = (job.publication_reference->>'snapshot_id')::uuid;
    if current_value.tournament_id is null
       or current_value.publication_authority <> 'SUPABASE'
       or current_value.current_snapshot_id <> created_snapshot.id
       or current_value.publication_revision < 1
       or created_snapshot.tournament_id <> target
       or created_snapshot.source_calculation_job_id <> job.job_id then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ODDS_PUBLICATION_REPLAY_STATE_INVALID';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_ODDS_PUBLISHED',
      'idempotent', true, 'publication_authority', 'SUPABASE',
      'publication_contract_version', 'production-odds-publication-v1',
      'snapshot_id', created_snapshot.id,
      'publication_revision', current_value.publication_revision,
      'publication_state', current_value.publication_state,
      'freshness', current_value.freshness,
      'published_at', created_snapshot.published_at,
      'published_payload', created_snapshot.published_payload,
      'runtime_generation_id', generation.runtime_generation_id,
      'mirror_created', false, 'google_writes', 0
    );
  end if;
  if context is null then
  if resource.odds_publication_authority <> 'SUPABASE'
     or not resource.odds_publication_enabled
     or resource.scoring_authority <> 'SUPABASE'
     or resource.current_tournament_read_authority <> 'SUPABASE'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.read_cutover_phase <> 'OBSERVATION'
     or activation.current_authority <> 'SUPABASE'
     or activation.maintenance_state <> 'NORMAL'
     or not activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or activation.activation_revision <>
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       expected_authority_epoch
     or annual_resource.resource_status <> 'CURRENT_RESOURCE_BOUND'
     or annual_resource.source_workbook_id is distinct from
       input->>'annual_destination_workbook_id'
     or generation.authority <> 'SUPABASE'
     or generation.ingress_state <> 'OPEN'
     or exists (
       select 1 from production_control.worker_controls value
       where value.worker_name = 'ODDS_GOOGLE_MIRROR'
         and (value.enabled or value.google_writes_allowed)
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ODDS_PUBLICATION_NOT_SAFE';
  end if;
  end if;
  if current_value.tournament_id is null then
    if expected_revision <> 0 or expected_snapshot is not null then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_ODDS_PUBLICATION_REVISION_CONFLICT';
    end if;
  elsif current_value.publication_authority <> 'SUPABASE'
     or current_value.publication_state <> 'PUBLISHED'
     or current_value.publication_revision <> expected_revision
     or current_value.current_snapshot_id is distinct from expected_snapshot
  then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ODDS_PUBLICATION_REVISION_CONFLICT';
  end if;
  if job.status <> 'SUCCEEDED'
     or job.publication_status <> 'READY'
     or job.publication_reference <> '{}'::jsonb
     or pg_catalog.jsonb_typeof(job.result_payload) <> 'object'
     or coalesce(job.result_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or job.result_payload->>'phase' is distinct from job.phase
     or coalesce((job.result_payload->>'year')::integer, 0) <> target::integer
     or pg_catalog.jsonb_typeof(job.result_payload->'teams') <> 'array'
     or pg_catalog.jsonb_array_length(job.result_payload->'teams') = 0
     or pg_catalog.jsonb_typeof(job.result_payload->'players') <> 'array'
     or pg_catalog.jsonb_array_length(job.result_payload->'players') = 0
     or (job.result_payload->>'publishedAt')::timestamptz
       is distinct from job.output_timestamp then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ODDS_CALCULATION_NOT_PUBLISHABLE';
  end if;
  if context is not null then
   perform production_control.assert_certification_odds_live_source_v1(target,job.input_snapshot,context);
  end if;
  config := production_control.current_canonical_odds_inputs_v2(
    target, annual_resource.source_workbook_id,
    input || pg_catalog.jsonb_build_object(
      'input_configuration_id', job.input_configuration_id,
      'configuration_revision',
        job.source_revision->>'configuration_revision',
      'settings_fingerprint', job.settings_fingerprint,
      'effective_settings_fingerprint', job.effective_settings_fingerprint,
      'input_bundle_fingerprint', job.input_bundle_fingerprint,
      'source_revision', job.source_revision
    ), true,context
  );
  if context is not null and(input->>'milestone'is distinct from job.phase
    or input->>'expected_source_fingerprint'is distinct from job.source_revision->>'source_fingerprint'
    or input->>'expected_result_fingerprint'is distinct from job.result_fingerprint
    or(job.phase='Final Results'and(select count(*)from scoring_authority.matches where tournament_id=target)<>24))then
    raise exception using errcode='40001',message='CERTIFICATION_ODDS_PUBLICATION_RESULT_STALE';end if;
  phase_order_value := pg_catalog.array_position(array[
    'Pre-Tournament', 'After Round 1', 'After Round 2',
    'Round 3 Pairings Announced', 'Final Results'
  ], job.phase) - 1;
  if current_value.current_snapshot_id is not null then
    select value.* into strict current_snapshot
    from scoring_authority.odds_published_snapshots value
    where value.id = current_value.current_snapshot_id;
    if phase_order_value < current_snapshot.phase_order then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ODDS_PUBLICATION_PHASE_REGRESSION';
    end if;
  end if;
  if job.phase = 'Final Results' and exists (
    select 1 from scoring_authority.matches value
    where value.tournament_id = target
      and (value.status <> 'FINAL' or value.scorecard_complete is not true)
  ) then
    raise exception using errcode = '55000',
      message = 'FINAL_RESULTS_NOT_READY';
  end if;
  next_revision := expected_revision + 1;
  select coalesce(pg_catalog.max(value.publication_revision), 0) + 1
    into next_milestone_revision
  from scoring_authority.odds_published_snapshots value
  where value.tournament_id = target and value.milestone = job.phase;
  source_revision_value := job.source_revision ||
    pg_catalog.jsonb_build_object(
      'calculation_job_id', job.job_id,
      'calculation_result_fingerprint', job.result_fingerprint,
      'input_configuration_id', config.id,
      'configuration_revision', config.configuration_revision,
      'settings_fingerprint', config.settings_fingerprint,
      'effective_settings_fingerprint',
        config.effective_settings_fingerprint,
      'ratings_fingerprint', config.ratings_fingerprint,
      'pairing_fingerprint', config.pairing_fingerprint,
      'bundle_fingerprint', config.bundle_fingerprint,
      'runtime_generation_id', generation.runtime_generation_id,
      'pointer_revision', generation.pointer_revision,
      'annual_authority_generation_id', generation.authority_generation_id,
      'annual_admission_generation_id', generation.admission_generation_id
    );
  if context is not null then
    -- Both components have already been checked against current canonical
    -- authority under148's publication locks. Keep their original meanings.
    source_revision_value:=source_revision_value||jsonb_build_object(
      'publication_source_identity',jsonb_build_object(
        'contract_version','certification-odds-publication-source-v1',
        'configuration_source_fingerprint',job.source_revision->>'source_fingerprint',
        'canonical_live_source_fingerprint',job.input_snapshot#>>'{metadata,certificationLiveSourceFingerprint}'));
    source_revision_value:=jsonb_set(source_revision_value,'{publication_source_identity,fingerprint}',
      to_jsonb(production_control.odds_publication_v1_hash(source_revision_value->'publication_source_identity')));
  end if;
  if context is null then
  binding := pg_catalog.jsonb_build_object(
    'contract_version', 'production-odds-publication-v1',
    'annual_contract_version', 'production-annual-odds-dispatch-v1',
    'environment', 'PRODUCTION', 'project_ref', resource.project_ref,
    'project_url', resource.project_url,
    'source_workbook_id', annual_resource.source_workbook_id,
    'vercel_project_id', 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'vercel_team_id', 'team_kPw5zaib8uaQJALAwj4fWI6R',
    'vercel_environment', 'production',
    'deployment_id', input->>'deployment_id',
    'deployment_commit', input->>'deployment_commit',
    'canonical_domain', resource.canonical_domain,
    'tournament_id', target,
    'runtime_generation_id', generation.runtime_generation_id,
    'pointer_revision', generation.pointer_revision,
    'authority_generation_id', generation.authority_generation_id,
    'admission_generation_id', generation.admission_generation_id,
    'platform_authority_epoch_id', expected_authority_epoch,
    'activation_revision', activation.activation_revision,
    'publication_revision', next_revision,
    'source_calculation_job_id', job.job_id,
    'google_publication_retired', true,
    'google_mirror_retired', true
  );
  else
    binding:=jsonb_build_object('contract_version','certification-odds-publication-v1','resource_class','CERTIFICATION',
      'resource_id',context->>'resource_id','installation_id',context->>'installation_id','project_ref',context->>'project_ref',
      'tournament_id',target,'authority_epoch_id',context->>'authority_epoch_id','runtime_generation_id',generation.runtime_generation_id,
      'ingress_generation_id',input->>'certification_ingress_generation_id','pointer_revision',generation.pointer_revision,
      'release_commit',context->>'release_commit','deployment_id',context->>'deployment_id','deployment_origin',context->>'deployment_origin',
      'activation_revision',context->>'activation_revision','admission_revision',context->>'admission_revision',
      'publication_revision',next_revision,'operation_request_id',input->>'operation_request_id','source_calculation_job_id',job.job_id,
      'previous_publication_state',case when expected_revision=0 then 'NEVER_PUBLISHED'else 'PUBLISHED'end,
      'previous_snapshot_id',expected_snapshot,'source_fingerprint',job.source_revision->>'source_fingerprint',
      'result_fingerprint',job.result_fingerprint,'actor_player_id',actor_player,'actor_auth_user_id',actor_auth_user)
      ||jsonb_build_object('publication_source_identity',source_revision_value->'publication_source_identity');
  end if;
  binding_fingerprint :=
    production_control.odds_publication_v1_hash(binding);
  payload_hash_value :=
    production_control.odds_publication_v1_hash(job.result_payload);
  update scoring_authority.odds_published_snapshots set
    is_current_for_milestone = false
  where tournament_id = target and milestone = job.phase
    and is_current_for_milestone;
  update scoring_authority.odds_published_snapshots set
    is_current_official = false
  where tournament_id = target and is_current_official;
  insert into scoring_authority.odds_published_snapshots (
    tournament_id, milestone, phase_order, publication_revision,
    published_at, published_payload, payload_hash, source_fingerprint,
    engine_version, engine_metadata, google_publication_fingerprint,
    google_publication_reference, is_current_for_milestone,
    is_current_official, publication_verified, imported_by,
    logical_payload_hash, settings_fingerprint, ratings_fingerprint,
    pairing_fingerprint, deterministic_seed, publication_actor_id,
    mirror_status, authority_contract_version, publication_authority,
    publication_state_revision, source_calculation_job_id,
    source_calculation_revision, published_by_auth_user_id,
    published_by_player_id, authority_epoch_id, resource_binding,
    resource_binding_fingerprint
  ) values (
    target, job.phase, phase_order_value, next_milestone_revision,
    job.output_timestamp, job.result_payload, payload_hash_value,
    case when context is null then nullif(job.source_revision->>'source_fingerprint', '')
      else source_revision_value#>>'{publication_source_identity,fingerprint}'end,
    job.engine_version, pg_catalog.jsonb_build_object(
      'iterations', job.total_iterations, 'phaseOrder', phase_order_value,
      'calculationJobId', job.job_id,
      'resultFingerprint', job.result_fingerprint,
      'runtimeGenerationId', generation.runtime_generation_id
    ), null, null, true, true, true,
    (case when context is null then 'production-odds-publication-v1'else 'certification-odds-publication-v1'end), job.result_fingerprint,
    config.settings_fingerprint, config.ratings_fingerprint,
    config.pairing_fingerprint, job.deterministic_seed, actor_player,
    'RETIRED', 'production-odds-publication-v1', 'SUPABASE',
    next_revision, job.job_id, source_revision_value, actor_auth_user,
    actor_player, expected_authority_epoch, binding, binding_fingerprint
  ) returning * into created_snapshot;
  insert into scoring_authority.odds_publication_current (
    tournament_id, contract_version, publication_authority,
    publication_state, freshness, current_snapshot_id,
    publication_revision, source_calculation_revision, published_at,
    published_by_player_id, published_by_auth_user_id, authority_epoch_id,
    resource_binding, resource_binding_fingerprint, adoption_kind,
    activated_by, activated_at, updated_at
  ) values (
    target, 'production-odds-publication-v1', 'SUPABASE', 'PUBLISHED',
    'CURRENT', created_snapshot.id, next_revision, source_revision_value,
    created_snapshot.published_at, actor_player, actor_auth_user,
    expected_authority_epoch, binding, binding_fingerprint, null,
    actor_player, pg_catalog.clock_timestamp(), pg_catalog.clock_timestamp()
  ) on conflict (tournament_id) do update set
    publication_state = excluded.publication_state,
    freshness = excluded.freshness,
    current_snapshot_id = excluded.current_snapshot_id,
    publication_revision = excluded.publication_revision,
    source_calculation_revision = excluded.source_calculation_revision,
    published_at = excluded.published_at,
    published_by_player_id = excluded.published_by_player_id,
    published_by_auth_user_id = excluded.published_by_auth_user_id,
    authority_epoch_id = excluded.authority_epoch_id,
    resource_binding = excluded.resource_binding,
    resource_binding_fingerprint = excluded.resource_binding_fingerprint,
    adoption_kind = null, activated_by = excluded.activated_by,
    activated_at = coalesce(
      scoring_authority.odds_publication_current.activated_at,
      excluded.activated_at
    ), updated_at = excluded.updated_at;
  update scoring_authority.odds_calculation_jobs set
    publication_status = 'PUBLISHED',
    publication_reference = pg_catalog.jsonb_build_object(
      'contract_version', 'production-odds-publication-v1',
      'snapshot_id', created_snapshot.id,
      'publication_revision', next_revision,
      'expected_predecessor_revision', expected_revision,
      'expected_predecessor_snapshot_id', expected_snapshot,
      'request_fingerprint', request_fingerprint_value,
      'runtime_generation_id', generation.runtime_generation_id
    ), updated_at = pg_catalog.clock_timestamp()
  where job_id = job.job_id;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_ODDS_PUBLISHED',
    'idempotent', false, 'publication_authority', 'SUPABASE',
    'publication_contract_version', 'production-odds-publication-v1',
    'snapshot_id', created_snapshot.id,
    'publication_revision', next_revision,
    'publication_state', 'PUBLISHED', 'freshness', 'CURRENT',
    'published_at', created_snapshot.published_at,
    'published_payload', created_snapshot.published_payload,
    'runtime_generation_id', generation.runtime_generation_id,
    'mirror_created', false, 'google_writes', 0
  );
  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    target, 'CHAMPIONSHIP_ODDS_PUBLISHED_SUPABASE', actor_player,
    (response_value - 'ok' - 'idempotent' - 'published_payload') || case when context is null then '{}'::jsonb else jsonb_build_object('resource_binding',binding)end
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    (case when context is null then 'PRODUCTION_CHAMPIONSHIP_ODDS_PUBLISHED'else 'CERTIFICATION_CHAMPIONSHIP_ODDS_PUBLISHED'end),
    'CHAMPIONSHIP_ODDS_PUBLICATION', target, actor_player,
    request_fingerprint_value, 'SUCCEEDED',
    (response_value - 'ok' - 'idempotent' - 'published_payload') || case when context is null then '{}'::jsonb else jsonb_build_object('resource_binding',binding)end
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.canonical_publish_odds_v2(input jsonb, target text, context jsonb) OWNER TO postgres;

--
-- Name: canonical_published_odds_projection_v2(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_published_odds_projection_v2(target text, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  started_at timestamptz := pg_catalog.clock_timestamp();
  tournament_value scoring_authority.tournaments%rowtype;
  current_value scoring_authority.odds_publication_current%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  epoch_value uuid;activation_revision_value bigint;
  snapshots jsonb;
  history_count integer;
  publication_value jsonb;
begin
  if canonical_context is null then
    if target = '2026' then
      raise exception using errcode = '55000',message = 'PRODUCTION_ANNUAL_ODDS_TARGET_REQUIRED';
    end if;
    select value.* into strict activation from production_control.cutover_activation_state value
      where value.scope_key = 'BAGGER_INV_PRODUCTION';
    select value.* into strict generation from production_control.future_annual_runtime_generations_v1 value
      where value.tournament_id=target and value.generation_status='ACTIVE';
    epoch_value:=activation.authority_generation_id;activation_revision_value:=activation.activation_revision;
  else
    perform production_control.assert_certification_current_projection_v1(target,canonical_context);
    epoch_value:=(canonical_context->>'authority_epoch_id')::uuid;
    activation_revision_value:=(canonical_context->>'activation_revision')::bigint;
    if target<>'2026' then
      select value.* into strict generation from production_control.future_annual_runtime_generations_v1 value
       where value.tournament_id=target and value.generation_status='ACTIVE';
    end if;
  end if;
  select value.* into strict tournament_value from scoring_authority.tournaments value where value.tournament_id=target;
  select value.* into current_value
  from scoring_authority.odds_publication_current value
  where value.tournament_id = target;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'milestone', value.milestone,
    'phase_order', value.phase_order,
    'publication_revision', value.publication_revision,
    'publication_state_revision', value.publication_state_revision,
    'published_at', value.published_at,
    'payload', value.published_payload,
    'payload_hash', value.payload_hash,
    'logical_payload_hash', value.logical_payload_hash,
    'source_fingerprint', value.source_fingerprint,
    'engine_version', value.engine_version,
    'engine_metadata', value.engine_metadata,
    'settings_fingerprint', value.settings_fingerprint,
    'ratings_fingerprint', value.ratings_fingerprint,
    'pairing_fingerprint', value.pairing_fingerprint,
    'authority_contract_version', value.authority_contract_version,
    'origin_authority', value.publication_authority,
    'source_calculation_job_id', value.source_calculation_job_id,
    'published_by_player_id', value.published_by_player_id,
    'google_publication_fingerprint', null,
    'is_current_official', value.is_current_official,
    'publication_verified', value.publication_verified,
    'imported_at', value.imported_at
  ) order by value.phase_order), '[]'::jsonb), pg_catalog.count(*)
    into snapshots, history_count
  from scoring_authority.odds_published_snapshots value
  where value.tournament_id = target
    and value.is_current_for_milestone and value.publication_verified;
  if current_value.tournament_id is null then
    publication_value := pg_catalog.jsonb_build_object(
      'contract_version', 'production-odds-publication-v1',
      'authority', 'SUPABASE', 'state', 'UNPUBLISHED',
      'snapshot_id', null, 'publication_revision', 0,
      'source_calculation_revision', '{}'::jsonb,
      'published_at', null, 'published_by_player_id', null,
      'freshness', 'UNPUBLISHED', 'stale', false,
      'authority_epoch_id', epoch_value,
      'activation_revision', activation_revision_value,
      'resource_binding_fingerprint', null, 'adoption_kind', null,
      'google_publication_fallback', false, 'google_mirror', 'RETIRED',
      'runtime_generation_id', generation.runtime_generation_id
    );
  elsif current_value.publication_authority <> 'SUPABASE'
     or current_value.publication_state <> 'PUBLISHED'
     or current_value.current_snapshot_id is null
     or current_value.publication_revision < 1 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_ODDS_PUBLICATION_STATE_INVALID';
  else
    publication_value := pg_catalog.jsonb_build_object(
      'contract_version', current_value.contract_version,
      'authority', current_value.publication_authority,
      'state', current_value.publication_state,
      'snapshot_id', current_value.current_snapshot_id,
      'publication_revision', current_value.publication_revision,
      'source_calculation_revision',
        current_value.source_calculation_revision,
      'published_at', current_value.published_at,
      'published_by_player_id', current_value.published_by_player_id,
      'freshness', current_value.freshness,
      'stale', current_value.freshness = 'STALE',
      'authority_epoch_id', current_value.authority_epoch_id,
      'activation_revision', activation_revision_value,
      'resource_binding_fingerprint',
        current_value.resource_binding_fingerprint,
      'adoption_kind', current_value.adoption_kind,
      'google_publication_fallback', false, 'google_mirror', 'RETIRED',
      'runtime_generation_id', generation.runtime_generation_id
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'data', pg_catalog.jsonb_build_object(
      'tournament', pg_catalog.to_jsonb(tournament_value),
      'publication', publication_value, 'snapshots', snapshots,
      'history_count', history_count,
      'query_ms', extract(epoch from (
        pg_catalog.clock_timestamp() - started_at
      )) * 1000
    )
  );
end;
$$;


ALTER FUNCTION production_control.canonical_published_odds_projection_v2(target text, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_read_future_year_administration_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_read_future_year_administration_v2(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  selected_id text := nullif(pg_catalog.btrim(coalesce(
    input->>'target_tournament_id', ''
  )), '');
  selected_value production_control.future_tournament_catalog_v1%rowtype;
  pointer_value production_control.current_tournament_pointer_v1%rowtype;
  catalog_value jsonb;
  selected_json jsonb;
  teams_value jsonb;
  roster_value jsonb;
  rounds_value jsonb;
  courses_value jsonb;
  matches_value jsonb;
  jobs_value jsonb;
  players_value jsonb;
  library_value jsonb;
  audit_value jsonb;
  readiness_value jsonb;
  editable boolean;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  actor_is_owner boolean := false;
begin
  perform production_control.assert_canonical_annual_context_v2(input, context, false);
  if input->>'operation'
       is distinct from 'READ_PRODUCTION_FUTURE_YEAR_ADMINISTRATION_V1'
     or (selected_id is not null and (
       selected_id !~ '^[0-9]{4}$' or selected_id = '2026'
     )) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_YEAR_READ_INPUT_INVALID';
  end if;
  select value.* into strict pointer_value
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = context->>'resource_id';
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  actor_is_owner := exists (
    select 1
    from production_control.tournament_owner_capabilities_v1 owner_value
    where owner_value.tournament_id = '2026'
      and owner_value.player_id = actor_player
      and owner_value.auth_user_id = actor_auth
      and owner_value.status = 'ACTIVE'
      and owner_value.revoked_at is null
  );
  select value.* into selected_value
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = selected_id;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'tournamentId', value.tournament_id,
    'tournamentYear', value.tournament_year,
    'name', value.tournament_name,
    'lifecycle', value.lifecycle,
    'setupRevision', value.setup_revision,
    'lifecycleRevision', value.lifecycle_revision,
    'creationMode', value.creation_mode,
    'cloneSourceTournamentId', value.clone_source_tournament_id,
    'isCurrent', value.tournament_id = pointer_value.tournament_id
  ) order by value.tournament_year), '[]'::jsonb)
  into catalog_value
  from production_control.future_tournament_catalog_v1 value;

  if selected_value.tournament_id is null then
    selected_json := null;
    teams_value := '[]'::jsonb;
    roster_value := '[]'::jsonb;
    rounds_value := '[]'::jsonb;
    courses_value := '[]'::jsonb;
    matches_value := '[]'::jsonb;
    jobs_value := '[]'::jsonb;
    readiness_value := production_control.future_year_readiness_v1(selected_id);
    editable := false;
  else
    editable := selected_value.lifecycle in ('DRAFT', 'CONFIGURING');
    selected_json := pg_catalog.jsonb_build_object(
      'tournamentId', selected_value.tournament_id,
      'tournamentYear', selected_value.tournament_year,
      'name', selected_value.tournament_name,
      'destination', selected_value.destination,
      'startDate', selected_value.start_date,
      'endDate', selected_value.end_date,
      'timezone', selected_value.timezone,
      'lifecycle', selected_value.lifecycle,
      'lifecycleRevision', selected_value.lifecycle_revision,
      'setupRevision', selected_value.setup_revision,
      'creationMode', selected_value.creation_mode,
      'cloneSourceTournamentId', selected_value.clone_source_tournament_id,
      'readinessFingerprint', selected_value.readiness_fingerprint,
      'readinessSetupRevision', selected_value.readiness_setup_revision,
      'isCurrent', selected_value.tournament_id = pointer_value.tournament_id
    );
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'teamId', team.team_id, 'teamSide', team.team_side,
      'name', team.team_name,
      'captainPlayerId', team.captain_player_id,
      'captainName', captain.display_name,
      'active', team.active, 'setupRevision', team.setup_revision
    ) order by team.team_side), '[]'::jsonb) into teams_value
    from production_control.future_tournament_teams_v1 team
    left join scoring_authority.players captain
      on captain.player_id = team.captain_player_id
    where team.tournament_id = selected_id;
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'playerId', roster.player_id, 'displayName', player.display_name,
      'teamId', roster.team_id, 'teamSide', roster.team_side,
      'participationStatus', roster.participation_status,
      'setupRevision', roster.setup_revision
    ) order by player.display_name, roster.player_id), '[]'::jsonb)
    into roster_value
    from production_control.future_tournament_roster_v1 roster
    join scoring_authority.players player on player.player_id = roster.player_id
    where roster.tournament_id = selected_id;
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'roundNumber', round_value.round_number,
      'name', round_value.round_name, 'format', round_value.format,
      'teamSize', round_value.team_size,
      'pointsAvailable', round_value.points_available::text,
      'handicapAllowance', round_value.handicap_allowance::text,
      'setupRevision', round_value.setup_revision
    ) order by round_value.round_number), '[]'::jsonb) into rounds_value
    from production_control.future_tournament_rounds_v1 round_value
    where round_value.tournament_id = selected_id;
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'roundNumber', course.round_number, 'courseId', course.course_id,
      'tee', course.tee_id,
      'sourceTournamentId', course.source_tournament_id,
      'sourceRoundNumber', course.source_round_number,
      'sourceSetupRevision', course.source_setup_revision,
      'referenceStatus', course.reference_status,
      'setupRevision', course.setup_revision
    ) order by course.round_number), '[]'::jsonb) into courses_value
    from production_control.future_tournament_course_references_v1 course
    where course.tournament_id = selected_id;
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'matchDefinitionId', match_value.match_definition_id,
      'matchId', match_value.match_id,
      'roundNumber', match_value.round_number,
      'matchNumber', match_value.match_number,
      'format', match_value.format, 'teamSize', match_value.team_size,
      'lifecycle', match_value.lifecycle,
      'hasRuntimeMatch', false, 'hasScoringSnapshot', false,
      'hasScoringAccess', false, 'setupRevision', match_value.setup_revision
    ) order by match_value.round_number, match_value.match_number), '[]'::jsonb)
    into matches_value
    from production_control.future_match_definitions_v1 match_value
    where match_value.tournament_id = selected_id;
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'jobId', job.job_id, 'matchId', job.match_id,
      'requirementClass', job.requirement_class, 'status', job.status,
      'writerInstalled', false, 'safeErrorCode', job.safe_error_code
    ) order by job.match_id), '[]'::jsonb) into jobs_value
    from production_control.future_match_google_compatibility_jobs_v1 job
    where job.tournament_id = selected_id;
    readiness_value := production_control.future_year_readiness_v1(selected_id);
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'playerId', player.player_id, 'displayName', player.display_name,
    'globalStatus', production_control.access_governance_global_status_v1(
      player.player_id
    )
  ) order by player.display_name, player.player_id), '[]'::jsonb)
  into players_value from scoring_authority.players player;

  -- Only current certified course/tee contexts with all 18 holes are
  -- assignable. Historical identities alone do not prove scoring context.
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'courseId', candidate.course_id, 'name', candidate.course_name,
    'location', candidate.location, 'tees', candidate.tees,
    'assignable', true
  ) order by candidate.course_name, candidate.course_id), '[]'::jsonb)
  into library_value
  from (
    select tee.course_id, pg_catalog.min(tee.display_name) as course_name,
      pg_catalog.min(tee.location) as location,
      pg_catalog.jsonb_agg(tee.tee_id order by tee.tee_id) as tees
    from scoring_authority.tournament_setup_course_tees_v1 tee
    where tee.tournament_id = '2026'
      and (
        select pg_catalog.count(*)
        from scoring_authority.tournament_setup_course_holes_v1 hole
        where hole.tournament_id = tee.tournament_id
          and hole.course_id = tee.course_id and hole.tee_id = tee.tee_id
      ) = 18
    group by tee.course_id
  ) candidate;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id', audit.event_id, 'action', audit.action,
    'targetKind', audit.target_kind, 'targetId', audit.target_id,
    'actorPlayerId', audit.actor_player_id, 'result', audit.result,
    'timestamp', audit.occurred_at,
    'summary', audit.safe_metadata->>'summary'
  ) order by audit.occurred_at desc), '[]'::jsonb) into audit_value
  from (
    select value.*
    from production_control.future_year_audit_events_v1 value
    where value.target_tournament_id = selected_id
    order by value.occurred_at desc
    limit 50
  ) audit;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'data', pg_catalog.jsonb_build_object(
      'contractVersion', 'production-future-year-administration-v1',
      'currentTournament', pg_catalog.jsonb_build_object(
        'tournamentId', pointer_value.tournament_id,
        'tournamentYear', pointer_value.tournament_year,
        'pointerRevision', pointer_value.pointer_revision,
        'lifecycleRevision', pointer_value.lifecycle_revision,
        'lifecycle', 'ACTIVE'
      ),
      'selectedTournament', selected_json,
      'catalog', catalog_value, 'teams', teams_value,
      'roster', roster_value, 'rounds', rounds_value,
      'courseAssignments', courses_value,
      'matchDefinitions', matches_value,
      'compatibilityJobs', jobs_value,
      'playerCatalog', players_value, 'courseLibrary', library_value,
      'audit', audit_value, 'readiness', readiness_value,
      'activationPlan', pg_catalog.jsonb_build_object(
        'status', 'BLOCKED', 'executable', false,
        'code', 'FUTURE_TOURNAMENT_ACTIVATION_NOT_INSTALLED',
        'blockers', readiness_value->'blockers'
      ),
      'capabilities', pg_catalog.jsonb_build_object(
        'createTournament', actor_is_owner,
        'cloneStructure', actor_is_owner,
        'editTournament', editable, 'configureTeams', editable,
        'replaceRoster', editable, 'configureRounds', editable,
        'assignExistingCourse', editable,
        'generateMatchStructure', editable, 'markReady', false,
        'activateTournament', false, 'closeTournament', false,
        'archiveTournament', false, 'createGlobalCourse', false,
        'runtimeMatchCreation', false,
        'googleCompatibilityWriter', false
      )
    )
  );
end;
$_$;


ALTER FUNCTION production_control.canonical_read_future_year_administration_v2(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: canonical_read_net_skins_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_read_net_skins_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  revision_value scoring_authority.net_skins_v1_configuration_revisions%rowtype;
  round_value jsonb;
  job_value scoring_authority.net_skins_v1_recalculation_jobs%rowtype;
  result_value scoring_authority.net_skins_v1_result_revisions%rowtype;
  source_revision_value jsonb;
  source_fingerprint_value text;
  source_fingerprints_value jsonb := '{}'::jsonb;
  entries_value jsonb;
  eligible_players_value jsonb;
  rounds_value jsonb := '[]'::jsonb;
  round_state text;
  top_state text := 'CONFIGURED';
  round_stale boolean;
  any_unavailable boolean := false;
  any_in_progress boolean := false;
  all_official boolean := true;
  max_result_revision bigint := 0;
  max_calculated_at timestamptz;
  max_published_at timestamptz;
  top_source_fingerprint text;
  revision_token text;
begin
  perform production_control.assert_production_service_role();
  if context is null then
  perform production_control.assert_production_cutover_read_scope(
    input, 'OBSERVATION'
  );
  if pg_catalog.upper(coalesce(input->>'environment', '')) <> 'PRODUCTION'
     or input->>'tournament_id' is distinct from '2026' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_NET_SKINS_RESOURCE_ASSERTION_FAILED';
  end if;
  else
    perform production_control.assert_canonical_scoring_context_v1(input,context,'RUNTIME');
    if context->>'phase' is distinct from 'READS'
      or (not production_control.model_d_context_v1(context) and (context->>'resource_id' is distinct from 'CERTIFICATION:2857f707-065a-405d-b5fc-b5b6fa1b0f51' or context->>'project_ref' is distinct from 'trmcwrljjxwhgtikfdgu'))
      or context is distinct from production_control.current_certification_context_v1()
      or input->>'tournament_id' is distinct from '2026'
      or exists(select 1 from jsonb_object_keys(input)k where k not in('player_id','tournament_id'))
      or not production_control.native_calcutta_reader_v1(input->>'player_id','2026',null::uuid) then
      raise exception using errcode='42501',message='CERTIFICATION_NET_SKINS_PARTICIPANT_READ_DENIED';end if;
  end if;

  select value.* into strict current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = '2026';
  select value.* into strict revision_value
  from scoring_authority.net_skins_v1_configuration_revisions value
  where value.configuration_revision_id =
    current_value.configuration_revision_id;

  if current_value.state = 'NOT_CONFIGURED' then
    revision_token := pg_catalog.format(
      'net-skins-v1:%s:0:NOT_CONFIGURED',
      current_value.configuration_revision
    );
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'data', pg_catalog.jsonb_build_object(
        'contract_version', 'production-net-skins-v1',
        'tournament_id', '2026',
        'state', 'NOT_CONFIGURED',
        'publication_policy', 'OFFICIAL_ONLY',
        'configuration_revision', current_value.configuration_revision,
        'result_revision', null,
        'configuration_fingerprint', null,
        'revision', revision_token,
        'freshness', pg_catalog.jsonb_build_object(
          'stale', false,
          'configured_at', null,
          'calculated_at', null,
          'published_at', null,
          'source_fingerprint', null
        ),
        'rounds', '[]'::jsonb
      )
    );
  end if;

  for round_value in
    select value
    from pg_catalog.jsonb_array_elements(
      revision_value.configuration_manifest->'rounds'
    ) value
    order by (value->>'round_number')::integer
  loop
    source_revision_value :=
      production_control.net_skins_v1_round_source_revision(
        '2026', (round_value->>'round_number')::integer
      );
    source_fingerprint_value :=
      production_control.net_skins_v1_hash(source_revision_value);
    source_fingerprints_value := source_fingerprints_value ||
      pg_catalog.jsonb_build_object(
        round_value->>'round_number', source_fingerprint_value
      );

    job_value := null;
    select value.* into job_value
    from scoring_authority.net_skins_v1_recalculation_jobs value
    where value.tournament_id = '2026'
      and value.round_number = (round_value->>'round_number')::integer
      and value.configuration_revision =
        current_value.configuration_revision
    order by value.requested_at desc, value.job_id desc
    limit 1;

    result_value := null;
    select value.* into result_value
    from scoring_authority.net_skins_v1_result_revisions value
    where value.tournament_id = '2026'
      and value.round_number = (round_value->>'round_number')::integer
      and value.configuration_revision =
        current_value.configuration_revision
      and value.is_current
    limit 1;

    if result_value.result_id is not null
       and result_value.result_state = 'OFFICIAL'
       and result_value.source_fingerprint = source_fingerprint_value then
      round_state := 'OFFICIAL';
      round_stale := false;
    elsif job_value.job_id is not null
       and job_value.source_fingerprint = source_fingerprint_value
       and job_value.status = 'FAILED' then
      round_state := 'UNAVAILABLE';
      round_stale := true;
    elsif job_value.job_id is not null
       and job_value.source_fingerprint = source_fingerprint_value
       and job_value.status in ('PENDING', 'RUNNING') then
      round_state := 'IN_PROGRESS';
      round_stale := true;
    elsif result_value.result_id is not null
       and result_value.result_state = 'PROVISIONAL'
       and result_value.source_fingerprint = source_fingerprint_value then
      round_state := 'IN_PROGRESS';
      round_stale := true;
    elsif exists (
      select 1
      from scoring_authority.matches match_value
      where match_value.tournament_id = '2026'
        and match_value.round_number =
          (round_value->>'round_number')::integer
        and (match_value.status <> 'UPCOMING'
          or match_value.scored_holes > 0)
    ) then
      round_state := 'IN_PROGRESS';
      round_stale := true;
    else
      round_state := 'CONFIGURED';
      round_stale := false;
    end if;

    entries_value := coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'entry_id', entry->>'entry_id',
          'entry_type', entry->>'entry_type',
          'match_id', entry->>'match_id',
          'player_ids', entry->'player_ids'
        ) order by entry->>'entry_id'
      )
      from pg_catalog.jsonb_array_elements(round_value->'entries') entry
      where coalesce((entry->>'eligible')::boolean, false)
    ), '[]'::jsonb);
    eligible_players_value := coalesce((
      select pg_catalog.jsonb_agg(player_id order by player_id)
      from (
        select distinct pg_catalog.jsonb_array_elements_text(
          entry->'player_ids'
        ) as player_id
        from pg_catalog.jsonb_array_elements(round_value->'entries') entry
        where coalesce((entry->>'eligible')::boolean, false)
      ) player_values
    ), '[]'::jsonb);

    any_unavailable := any_unavailable or round_state = 'UNAVAILABLE';
    any_in_progress := any_in_progress or round_state = 'IN_PROGRESS';
    all_official := all_official and round_state = 'OFFICIAL';
    max_result_revision := greatest(
      max_result_revision, coalesce(result_value.result_revision, 0)
    );
    if result_value.calculated_at is not null
       and (max_calculated_at is null
         or result_value.calculated_at > max_calculated_at) then
      max_calculated_at := result_value.calculated_at;
    end if;
    if result_value.published_at is not null
       and (max_published_at is null
         or result_value.published_at > max_published_at) then
      max_published_at := result_value.published_at;
    end if;

    rounds_value := rounds_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'round_id', round_value->>'round_id',
        'round_number', (round_value->>'round_number')::integer,
        'format', round_value->>'format',
        'entry_type', round_value->>'entry_type',
        'buy_in_per_entry', (round_value->>'buy_in_per_entry')::numeric,
        'eligible_entry_count', pg_catalog.jsonb_array_length(entries_value),
        'eligible_player_ids', eligible_players_value,
        'match_ids', round_value->'match_ids',
        'entries', entries_value,
        'state', round_state,
        'configuration_revision', current_value.configuration_revision,
        'result_revision', case when result_value.result_id is null
          then null else result_value.result_revision end,
        'configuration_fingerprint',
          round_value->>'configuration_fingerprint',
        'freshness', pg_catalog.jsonb_build_object(
          'stale', round_stale,
          'calculated_at', result_value.calculated_at,
          'published_at', case when round_state = 'OFFICIAL'
            then result_value.published_at else null end,
          'source_fingerprint', source_fingerprint_value
        ),
        'result_payload', case when round_state = 'OFFICIAL'
          then result_value.engine_result_payload || jsonb_build_object('participantLabels', production_control.native_published_skins_labels_v1('2026',result_value.engine_result_payload)) else null end,
        'official_results', case when round_state = 'OFFICIAL'
          then result_value.public_result_payload else null end
      )
    );
  end loop;

  top_state := case
    when any_unavailable then 'UNAVAILABLE'
    when all_official and pg_catalog.jsonb_array_length(rounds_value) > 0
      then 'OFFICIAL'
    when any_in_progress
      or exists (
        select 1
        from pg_catalog.jsonb_array_elements(rounds_value) value
        where value->>'state' = 'OFFICIAL'
      ) then 'IN_PROGRESS'
    else 'CONFIGURED'
  end;
  top_source_fingerprint := production_control.net_skins_v1_hash(
    source_fingerprints_value
  );
  revision_token := pg_catalog.format(
    'net-skins-v1:%s:%s:%s',
    current_value.configuration_revision,
    max_result_revision,
    top_state
  );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'data', pg_catalog.jsonb_build_object(
      'contract_version', 'production-net-skins-v1',
      'tournament_id', '2026',
      'state', top_state,
      'publication_policy', 'OFFICIAL_ONLY',
      'configuration_revision', current_value.configuration_revision,
      'result_revision', case when max_result_revision = 0
        then null else max_result_revision end,
      'configuration_fingerprint',
        revision_value.configuration_fingerprint,
      'revision', revision_token,
      'freshness', pg_catalog.jsonb_build_object(
        'stale', any_unavailable or any_in_progress,
        'configured_at', revision_value.configured_at,
        'calculated_at', max_calculated_at,
        'published_at', max_published_at,
        'source_fingerprint', top_source_fingerprint
      ),
      'rounds', rounds_value
    )
  );
end;
$$;


ALTER FUNCTION production_control.canonical_read_net_skins_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: canonical_read_published_calcutta_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_read_published_calcutta_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  started_at timestamptz := pg_catalog.clock_timestamp();
  current_value scoring_authority.calcutta_v1_current%rowtype;
  configuration_value scoring_authority.calcutta_v1_configuration_revisions%rowtype;
  auction_value scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  publication_value scoring_authority.calcutta_v1_publication_revisions%rowtype;
  result_value scoring_authority.calcutta_v1_result_revisions%rowtype;
  job_value scoring_authority.calcutta_v1_recalculation_jobs%rowtype;
  source_revision_value jsonb;
  source_fingerprint_value text;
  completed_rounds_value integer[] := '{}'::integer[];
  market_value jsonb;
  participant_result_value jsonb;
  state_value text;
  revision_value text;
  result_is_fresh boolean := false;
  result_is_stale boolean := false;
  updating_value boolean := false;
  expose_result boolean := false;
  participant_player text := pg_catalog.btrim(coalesce(
    input->>'player_id', ''
  ));
begin
  perform production_control.assert_production_service_role();
  if context is null then
  perform production_control.assert_production_cutover_read_scope(
    input, 'OBSERVATION'
  );
  if pg_catalog.upper(coalesce(input->>'environment', '')) <> 'PRODUCTION'
     or input->>'tournament_id' is distinct from '2026'
     or not production_control.native_calcutta_reader_v1(participant_player,'2026',nullif(input->>'observer_auth_user_id','')::uuid) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CALCUTTA_PARTICIPANT_RESOURCE_REQUIRED';
  end if;
  else
    perform production_control.assert_canonical_scoring_context_v1(input,context,'RUNTIME');
    if context->>'phase' is distinct from 'READS'
      or (not production_control.model_d_context_v1(context) and (context->>'resource_id' is distinct from 'CERTIFICATION:2857f707-065a-405d-b5fc-b5b6fa1b0f51' or context->>'project_ref' is distinct from 'trmcwrljjxwhgtikfdgu'))
      or input ? 'observer_auth_user_id'
      or not production_control.native_calcutta_reader_v1(participant_player,'2026',null::uuid) then
      raise exception using errcode='42501',message='CERTIFICATION_CALCUTTA_PARTICIPANT_READ_DENIED';end if;
  end if;

  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026';
  select value.* into strict configuration_value
  from scoring_authority.calcutta_v1_configuration_revisions value
  where value.configuration_revision_id =
    current_value.configuration_revision_id;

  if current_value.auction_revision > 0 then
    select value.* into strict auction_value
    from scoring_authority.calcutta_v1_auction_fact_revisions value
    where value.auction_revision_id = current_value.auction_revision_id;
    source_revision_value :=
      production_control.calcutta_v1_source_revision('2026');
    source_fingerprint_value := production_control.calcutta_v1_hash(
      source_revision_value
    );
    completed_rounds_value :=
      production_control.calcutta_v1_completed_rounds();

    select value.* into result_value
    from scoring_authority.calcutta_v1_result_revisions value
    where value.tournament_id = '2026'
      and value.configuration_revision = current_value.configuration_revision
      and value.configuration_fingerprint =
        current_value.configuration_fingerprint
      and value.auction_revision = current_value.auction_revision
      and value.auction_fingerprint = current_value.auction_fingerprint
      and value.is_current
    limit 1;
    result_is_fresh := result_value.result_id is not null
      and (result_value.source_fingerprint = source_fingerprint_value or production_control.late_r3_result_compatible_v1(result_value.result_id,source_fingerprint_value));
    result_is_stale := result_value.result_id is not null
      and result_value.source_fingerprint <> source_fingerprint_value and not production_control.late_r3_result_compatible_v1(result_value.result_id,source_fingerprint_value);

    select value.* into job_value
    from scoring_authority.calcutta_v1_recalculation_jobs value
    where value.tournament_id = '2026'
      and value.configuration_revision = current_value.configuration_revision
      and value.configuration_fingerprint =
        current_value.configuration_fingerprint
      and value.auction_revision = current_value.auction_revision
      and value.auction_fingerprint = current_value.auction_fingerprint
      and value.source_fingerprint = source_fingerprint_value
    order by value.requested_at desc, value.job_id desc
    limit 1;
    updating_value := (job_value.job_id is not null
      and job_value.status in ('PENDING', 'RUNNING'))
      or exists (select 1 from scoring_authority.score_derived_intents_v1 intent
        where intent.tournament_id = '2026' and intent.family = 'CALCUTTA'
          and intent.status in ('PENDING', 'RETRYABLE'));
  end if;

  if current_value.publication_revision > 0 then
    select value.* into strict publication_value
    from scoring_authority.calcutta_v1_publication_revisions value
    where value.publication_revision_id =
      current_value.publication_revision_id;
  end if;

  state_value := case
    when current_value.state = 'NOT_CONFIGURED' then 'NOT_CONFIGURED'
    when current_value.auction_revision = 0 then 'CONFIGURED'
    when result_is_fresh and result_value.result_state = 'OFFICIAL'
      then 'OFFICIAL'
    when result_is_fresh
      and pg_catalog.jsonb_array_length(
        result_value.engine_result_payload->'completedRounds'
      ) > 0 then 'IN_PROGRESS'
    when result_is_fresh then 'AUCTION_COMPLETE'
    -- A Reopen invalidates OFFICIAL semantics immediately. Withhold the old
    -- payload until the worker commits a new canonical revision.
    when result_is_stale and updating_value
      and result_value.result_state = 'OFFICIAL'
      and not (3 = any(completed_rounds_value)) then 'UNAVAILABLE'
    when result_is_stale and updating_value
      and result_value.result_state = 'OFFICIAL'
      then 'OFFICIAL'
    when result_is_stale and updating_value
      and pg_catalog.jsonb_array_length(
        result_value.engine_result_payload->'completedRounds'
      ) > 0 then 'IN_PROGRESS'
    when result_is_stale and updating_value then 'AUCTION_COMPLETE'
    when result_is_stale then 'UNAVAILABLE'
    when job_value.job_id is not null and job_value.status = 'FAILED'
      then 'UNAVAILABLE'
    else 'AUCTION_COMPLETE'
  end;

  expose_result := current_value.publication_state = 'PUBLISHED'
    and result_value.result_id is not null
    and state_value <> 'UNAVAILABLE';

  if current_value.publication_state = 'PUBLISHED' then
    market_value := pg_catalog.jsonb_build_object(
      'pot', (auction_value.auction_manifest->>'pot')::numeric::text,
      'purchases', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'player', pg_catalog.jsonb_build_object(
            'player_id', purchase->>'player_id',
            'display_name', entrant.display_name
          ),
          'purchase_price',
            (purchase->>'purchase_price')::numeric::text,
          'owners', coalesce((
            select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
              'player', pg_catalog.jsonb_build_object(
                'player_id', ownership->>'owner_player_id',
                'display_name', owner_player.display_name
              ),
              'ownership_fraction',
                (ownership->>'ownership_fraction')::numeric::text
            ) order by ownership->>'owner_player_id')
            from pg_catalog.jsonb_array_elements(
              auction_value.auction_manifest->'ownership'
            ) ownership
            join scoring_authority.players owner_player
              on owner_player.player_id = ownership->>'owner_player_id'
            where ownership->>'player_id' = purchase->>'player_id'
          ), '[]'::jsonb)
        ) order by purchase->>'player_id')
        from pg_catalog.jsonb_array_elements(
          auction_value.auction_manifest->'purchases'
        ) purchase
        join scoring_authority.players entrant
          on entrant.player_id = purchase->>'player_id'
      ), '[]'::jsonb)
    );
  else
    market_value := null;
  end if;
  participant_result_value := case when expose_result
    then production_control.project_production_calcutta_v1_result(
      result_value.engine_result_payload
    ) else null end;

  revision_value := pg_catalog.format(
    'calcutta-v1:%s:%s:%s:%s:%s:%s',
    current_value.configuration_revision,
    current_value.auction_revision,
    current_value.publication_revision,
    case when result_value.result_id is null
      then 0 else result_value.result_revision end,
    state_value, current_value.publication_state
  );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'data', pg_catalog.jsonb_build_object(
      'contract_version', 'production-calcutta-v1',
      'tournament_id', '2026',
      'state', state_value,
      'publication_policy',
        'DIRECTOR_CONTROLLED_PARTICIPANT_FULL_MARKET',
      'publication_state', current_value.publication_state,
      'published', current_value.publication_state = 'PUBLISHED',
      'currency_code', 'USD',
      'configuration_revision', current_value.configuration_revision,
      'auction_revision', current_value.auction_revision,
      'publication_revision', current_value.publication_revision,
      'result_revision', case when result_value.result_id is null
        then null else result_value.result_revision end,
      'configuration_fingerprint', case
        when state_value = 'NOT_CONFIGURED' then null
        else current_value.configuration_fingerprint end,
      'auction_fingerprint', current_value.auction_fingerprint,
      'result_fingerprint', case when result_value.result_id is null
        then null else result_value.payload_hash end,
      'revision', revision_value,
      'freshness', pg_catalog.jsonb_build_object(
        'stale', result_is_stale, 'lifecycle_compatible', production_control.late_r3_result_compatible_v1(result_value.result_id,source_fingerprint_value), 'original_result_source_fingerprint', result_value.source_fingerprint,
        'updating', updating_value,
        'configured_at', configuration_value.configured_at,
        'auction_recorded_at', auction_value.recorded_at,
        'published_at', case
          when current_value.publication_state = 'PUBLISHED'
            then publication_value.published_at
          else null end,
        'calculated_at', result_value.calculated_at,
        'source_fingerprint', source_fingerprint_value
      ),
      'market', market_value,
      'result', participant_result_value,
      'query_ms', pg_catalog.round(extract(epoch from
        (pg_catalog.clock_timestamp() - started_at)) * 1000, 3)
    )
  );
end;
$$;


ALTER FUNCTION production_control.canonical_read_published_calcutta_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: canonical_read_scoring_authority_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_read_scoring_authority_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  target_match text := input->>'match_id';
  mode text := upper(coalesce(input->>'mode', 'DIAGNOSTICS'));
  payload jsonb;
begin
  perform production_control.assert_canonical_scoring_context_v1(input, canonical_context, 'EXACT_READ');
  if mode = 'MATCH' then
    select to_jsonb(match_value) into payload
    from scoring_authority.matches match_value
    where match_id = target_match and tournament_id = '2026';
  elsif mode = 'SCORECARD' then
    select jsonb_build_object(
      'match', to_jsonb(match_value),
      'holes', coalesce((select jsonb_agg(to_jsonb(hole) order by hole_number)
        from scoring_authority.hole_scores hole where hole.match_id = match_value.match_id), '[]'::jsonb)
    ) into payload
    from scoring_authority.matches match_value
    where match_id = target_match and tournament_id = '2026';
  elsif mode = 'CURRENT_STATE' then
    select jsonb_build_object(
      'matches', coalesce((select jsonb_agg(to_jsonb(match_value) order by round_number, match_id)
        from scoring_authority.matches match_value where tournament_id = '2026'), '[]'::jsonb),
      'holes', coalesce((select jsonb_agg(to_jsonb(hole) order by hole.match_id, hole.hole_number)
        from scoring_authority.hole_scores hole join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = '2026'), '[]'::jsonb),
      'players', coalesce((select jsonb_agg(to_jsonb(player) order by player_id)
        from scoring_authority.tournament_players player where tournament_id = '2026'), '[]'::jsonb),
      'snapshots', coalesce((select jsonb_agg(to_jsonb(snapshot) order by match_id)
        from scoring_authority.scoring_snapshots snapshot where tournament_id = '2026'), '[]'::jsonb),
      'permissions', coalesce((select jsonb_agg(to_jsonb(permission) order by match_id, player_id)
        from scoring_authority.scoring_permissions permission join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = '2026'), '[]'::jsonb),
      'checkpoints', coalesce((select jsonb_agg(to_jsonb(checkpoint) order by match_id)
        from scoring_authority.google_match_checkpoints checkpoint join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = '2026'), '[]'::jsonb)
    ) into payload;
  elsif mode = 'DIAGNOSTICS' then
    select jsonb_build_object(
      'matches', (select count(*) from scoring_authority.matches where tournament_id = '2026'),
      'holes', (select count(*) from scoring_authority.hole_scores hole join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = '2026'),
      'permissions', (select count(*) from scoring_authority.scoring_permissions permission join scoring_authority.matches match_value using (match_id)
        where match_value.tournament_id = '2026'),
      'pending_outbox', 0 /* external Google delivery retired */,
      'authority', (select scoring_authority from scoring_authority.tournaments where tournament_id = '2026'),
      'ingress', (select to_jsonb(gate) from scoring_authority.ingress_gates gate where tournament_id = '2026')
    ) into payload;
  else
    return jsonb_build_object('ok', false, 'code', 'INVALID_READ_MODE');
  end if;
  return jsonb_build_object('ok', true, 'mode', mode, 'data', payload);
end;
$$;


ALTER FUNCTION production_control.canonical_read_scoring_authority_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_read_scoring_participant_context_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_read_scoring_participant_context_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth'
    AS $$
declare
  target_match text := input->>'match_id';
  actor text := input->>'player_id';
  actor_auth_user uuid := nullif(input->>'auth_user_id', '')::uuid;
  participant_role text := upper(coalesce(input->>'role', 'PLAYER'));
  supplied_permission_revision bigint := coalesce((input->>'permission_revision')::bigint, -1);
  match_row scoring_authority.matches%rowtype;
  permission_ok boolean := false;
begin
  perform production_control.assert_canonical_scoring_context_v1(input, canonical_context, 'EXACT_READ');
  select * into match_row from scoring_authority.matches
    where match_id = target_match and tournament_id = '2026';
  if not found then return jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FOUND'); end if;
  if actor_auth_user is not null
     and input->>'tournament_id' = '2026'
     and supplied_permission_revision = match_row.permission_revision
     and exists (
       select 1
       from participant_identity.user_player_links link
       join auth.users auth_user
         on auth_user.id = link.auth_user_id and auth_user.email_confirmed_at is not null
       join participant_identity.participant_auth_identifiers identifier
         on identifier.auth_user_id = link.auth_user_id
        and identifier.player_id = link.player_id
        and identifier.identifier_type = 'EMAIL'
        and identifier.status = 'VERIFIED'
       join participant_identity.tournament_roles tournament_role
         on tournament_role.tournament_id = '2026'
        and tournament_role.auth_user_id = link.auth_user_id
        and tournament_role.role = case when participant_role = 'DIRECTOR' then 'DIRECTOR' else 'PARTICIPANT' end
        and tournament_role.role_active
        and tournament_role.revoked_at is null
       join scoring_authority.tournament_players membership
         on membership.tournament_id = '2026'
        and membership.player_id = link.player_id
        and membership.participation_status = 'ACTIVE'
       where link.auth_user_id = actor_auth_user
         and link.player_id = actor
         and link.status = 'ACTIVE'
         and link.revoked_at is null
     )
     and (participant_role <> 'DIRECTOR' or exists (
       select 1 from production_control.director_entitlements entitlement
       where entitlement.auth_user_id = actor_auth_user
         and entitlement.tournament_id = '2026'
         and entitlement.player_id = actor
         and entitlement.role in ('DIRECTOR', 'OWNER')
         and entitlement.status = 'ACTIVE'
         and entitlement.revoked_at is null
     )) then
    if participant_role = 'PLAYER' then
      select exists (select 1 from scoring_authority.scoring_permissions
        where match_id = target_match and player_id = actor and can_score
          and revoked_at is null and permission_revision = match_row.permission_revision)
        into permission_ok;
    elsif participant_role = 'DIRECTOR' then
      permission_ok := true;
    end if;
  end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'match', to_jsonb(match_row),
    'holes', coalesce((select jsonb_agg(to_jsonb(hole) order by hole_number)
      from scoring_authority.hole_scores hole where hole.match_id = target_match), '[]'::jsonb),
    'authorization', jsonb_build_object(
      'verified', permission_ok,
      'writable', permission_ok and match_row.status <> 'FINAL' and not match_row.scoring_locked,
      'permission_revision', match_row.permission_revision
    )
  ));
end;
$$;


ALTER FUNCTION production_control.canonical_read_scoring_participant_context_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_reopen_match_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_reopen_match_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  match_row scoring_authority.matches%rowtype;
  next_match_row scoring_authority.matches%rowtype;
  mutation_row scoring_authority.score_mutations%rowtype;
  target_match text := input->>'match_id';
  mutation_identity text := input->>'mutation_key';
  actor text := input#>>'{authorization,player_id}';
  expected_match bigint := coalesce((input->>'expected_match_revision')::bigint, -1);
  supplied_permission bigint := coalesce((input#>>'{authorization,permission_revision}')::bigint, -1);
  next_revision bigint;
  next_permission_revision bigint;
  payload_hash_value text;
  result_value jsonb;
  before_permissions jsonb;
  after_permissions jsonb;
  archive_result jsonb;
  transition_at timestamptz := clock_timestamp();
begin
  perform production_control.assert_canonical_scoring_context_v1(input, canonical_context, 'RUNTIME');
  perform production_control.assert_production_scoring_actor(input, true);
  select * into match_row from scoring_authority.matches
    where match_id = target_match and tournament_id = '2026' for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FOUND'); end if;
  if input#>>'{authorization,match_id}' <> target_match then
    return jsonb_build_object('ok', false, 'code', 'DIRECTOR_REQUIRED');
  end if;
  payload_hash_value := production_control.cutover_payload_hash(jsonb_build_object(
    'match_id', target_match, 'action', 'REOPEN', 'actor_id', actor
  ));
  select * into mutation_row from scoring_authority.score_mutations
    where match_id = target_match and mutation_key = mutation_identity;
  if found then
    if mutation_row.payload_hash = payload_hash_value then
      return mutation_row.result || jsonb_build_object('idempotent', true);
    end if;
    return jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT');
  end if;
  if supplied_permission <> match_row.permission_revision then
    return jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE',
      'current_permission_revision', match_row.permission_revision);
  end if;
  if match_row.status <> 'FINAL' then return jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FINAL'); end if;
  if expected_match <> match_row.match_revision then
    return jsonb_build_object('ok', false, 'code', 'MATCH_REVISION_CONFLICT',
      'current_match_revision', match_row.match_revision);
  end if;
  select coalesce(jsonb_agg(to_jsonb(permission) order by player_id), '[]'::jsonb)
    into before_permissions from scoring_authority.scoring_permissions permission
    where match_id = target_match;
  next_revision := match_row.match_revision + 1;
  next_permission_revision := match_row.permission_revision + 1;
  update scoring_authority.matches set
    status = 'LIVE', scoring_locked = false, match_revision = next_revision,
    permission_revision = next_permission_revision, finalized_at = null,
    authority_updated_at = transition_at, updated_at = transition_at
  where match_id = target_match returning * into next_match_row;
  update scoring_authority.scoring_permissions set
    can_score = true, permission_revision = next_permission_revision,
    revoked_at = null, updated_at = transition_at
  where match_id = target_match;
  select coalesce(jsonb_agg(to_jsonb(permission) order by player_id), '[]'::jsonb)
    into after_permissions from scoring_authority.scoring_permissions permission
    where match_id = target_match;
  archive_result := scoring_authority.invalidate_finalized_scorecard_snapshot(
    target_match, next_revision, actor
  );
  result_value := jsonb_build_object(
    'ok', true, 'code', 'REOPENED', 'match_id', target_match,
    'google_target_match_id', target_match, 'match_revision', next_revision,
    'permission_revision', next_permission_revision,
    'previous_permission_revision', match_row.permission_revision,
    'scoring_locked', false, 'access_active', true,
    'scorecard_complete', match_row.scorecard_complete, 'updated_at', transition_at,
    'official_points_active', false, 'scorecard_archive', archive_result,
    'permission_transition', jsonb_build_object('before', before_permissions, 'after', after_permissions),
    'audit_created', true, 'google_outbox_created', false
  );
  insert into scoring_authority.score_mutations (
    match_id, mutation_key, mutation_type, payload_hash,
    previous_match_revision, next_match_revision, result, actor_id
  ) values (
    target_match, mutation_identity, 'REOPEN', payload_hash_value,
    match_row.match_revision, next_revision, result_value, actor
  );
  insert into scoring_authority.score_revision_history (
    match_id, mutation_key, action, previous_match_revision,
    next_match_revision, before_state, after_state, actor_id
  ) values (
    target_match, mutation_identity, 'MATCH_REOPENED', match_row.match_revision,
    next_revision,
    jsonb_build_object('match', to_jsonb(match_row), 'permissions', before_permissions),
    jsonb_build_object('match', to_jsonb(next_match_row), 'permissions', after_permissions), actor
  );
  insert into scoring_authority.audit_events (tournament_id, match_id, mutation_key, action, actor_id, metadata)
    values ('2026', target_match, mutation_identity, 'MATCH_REOPENED', actor, result_value);
  -- Google runtime retired: external delivery is not canonical authority.
  return result_value;
end;
$$;


ALTER FUNCTION production_control.canonical_reopen_match_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_requeue_score_derived_delivery_v1_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_requeue_score_derived_delivery_v1_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare target text; generation uuid; family_value text:=input->>'family'; identity_value text:=input->>'work_identity';
  request_value uuid:=(input->>'request_id')::uuid; table_name text; predicate text; retained jsonb; lookup_identity text;
  expected_cycle bigint:=(input->>'expected_cycle')::bigint;
  expected_attempt integer:=(input->>'expected_attempt')::integer; next_cycle bigint; prior_event bigint;
  request_hash text; prior_hash text; actor_id uuid:=(input#>>'{authorization,auth_user_id}')::uuid;
begin
 target:=production_control.assert_canonical_derived_scope_v1(input,canonical_context);
 if target<>'2026' then select runtime_generation_id into strict generation from production_control.annual_scoring_runtime_authorities_v1
  where tournament_id=target and authority_status='ACTIVE'; end if;
 if target='2026' then perform production_control.assert_production_scoring_actor(input,true);
 else perform production_control.assert_canonical_future_scoring_actor_v1(input,target,true,canonical_context); end if;
 if request_value is null or identity_value is null or expected_cycle is null or expected_attempt is null
    or length(btrim(coalesce(input->>'reason','')))<3 or length(input->>'reason')>120 then
  raise exception using errcode='22023',message='DERIVED_REQUEUE_IDENTITY_AND_REASON_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended(request_value::text,202609280124));
 request_hash:=encode(extensions.digest(jsonb_build_object('target',target,'family',family_value,'identity',identity_value,
   'cycle',expected_cycle,'attempt',expected_attempt,'reason',input->>'reason','actor',actor_id)::text,'sha256'),'hex');
 select event_id,recovery_request_hash into prior_event,prior_hash from production_control.score_derived_delivery_attempts_v1 where recovery_request_id=request_value;
 if found then
  if prior_hash is distinct from request_hash then raise exception using errcode='22023',message='DERIVED_REQUEUE_REQUEST_REUSE_CONFLICT'; end if;
  return jsonb_build_object('ok',true,'idempotent',true,'eventId',prior_event); end if;
 if family_value='INTENT' then
  select to_jsonb(v) into retained from scoring_authority.score_derived_intents_v1 v
   where v.tournament_id=target and v.intent_id=identity_value::uuid for update;
  if retained is null or retained->>'status'<>'DEAD_LETTER' or (retained->>'delivery_cycle')::bigint<>expected_cycle
     or (retained->>'attempts')::integer<>expected_attempt then
   raise exception using errcode='40001',message='DERIVED_REQUEUE_STATE_CHANGED'; end if;
  if nullif(retained->>'runtime_generation_id','')::uuid is distinct from generation then
   raise exception using errcode='55000',message='DERIVED_REQUEUE_GENERATION_CHANGED'; end if;
  next_cycle:=expected_cycle+1;
  update scoring_authority.score_derived_intents_v1 set status='PENDING',attempts=0,last_sqlstate=null,
   available_at=clock_timestamp(),delivery_cycle=next_cycle,updated_at=clock_timestamp() where intent_id=identity_value::uuid;
 else
  table_name:=case family_value when 'CALCUTTA' then 'calcutta_v1_recalculation_jobs'
   when 'NET_SKINS' then 'net_skins_v1_recalculation_jobs' when 'COMPETITION' then 'competition_recalculation_jobs'
   when 'INTELLIGENCE' then 'competition_recalculation_jobs' end;
  if table_name is null then raise exception using errcode='22023',message='DERIVED_REQUEUE_FAMILY_INVALID'; end if;
  if table_name='competition_recalculation_jobs' then
   lookup_identity:=substring(identity_value from length(target)+4);
   if identity_value<>target||':0:'||lookup_identity or lookup_identity not in
      ('TEAM_MOMENTUM','TOURNAMENT_STORYLINES','TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL','TOURNAMENT_FINAL_RECAP') then
    raise exception using errcode='22023',message='DERIVED_REQUEUE_IDENTITY_INVALID'; end if;
   predicate:='round_number=0 and engine_key=$2';
  else
   if identity_value !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    raise exception using errcode='22023',message='DERIVED_REQUEUE_IDENTITY_INVALID'; end if;
   lookup_identity:=identity_value;
   predicate:='job_id=$2::uuid';
  end if;
  execute format('select to_jsonb(v) from scoring_authority.%I v where tournament_id=$1 and %s for update',table_name,predicate)
   into retained using target,lookup_identity;
  if retained is null or retained->>'status'<>'FAILED' or retained->>'delivery_dead_letter_at' is null
     or (retained->>'delivery_cycle')::bigint<>expected_cycle or (retained->>'delivery_attempts')::integer<>expected_attempt
     or (table_name='competition_recalculation_jobs' and
       (case when retained->>'engine_key' in('TEAM_MOMENTUM','TOURNAMENT_STORYLINES') then 'COMPETITION' else 'INTELLIGENCE' end)<>family_value) then
   raise exception using errcode='40001',message='DERIVED_REQUEUE_STATE_CHANGED'; end if;
  if nullif(retained->>'runtime_generation_id','')::uuid is distinct from generation then
   raise exception using errcode='55000',message='DERIVED_REQUEUE_GENERATION_CHANGED'; end if;
  if family_value='CALCUTTA' and (not exists(select 1 from scoring_authority.calcutta_v1_current c
      where c.tournament_id=target and c.configuration_revision=(retained->>'configuration_revision')::bigint
      and c.configuration_fingerprint=retained->>'configuration_fingerprint'
      and c.auction_revision=(retained->>'auction_revision')::bigint and c.auction_fingerprint=retained->>'auction_fingerprint')
    or retained->>'source_fingerprint' is distinct from production_control.calcutta_v1_hash(production_control.calcutta_v1_source_revision(target))) then
   raise exception using errcode='55000',message='DERIVED_REQUEUE_FINANCIAL_SOURCE_CHANGED'; end if;
  if family_value='NET_SKINS' and (not exists(select 1 from scoring_authority.net_skins_v1_configuration_current c
      where c.tournament_id=target and c.configuration_revision=(retained->>'configuration_revision')::bigint)
    or retained->>'source_fingerprint' is distinct from production_control.net_skins_v1_hash(
      production_control.net_skins_v1_round_source_revision(target,(retained->>'round_number')::integer))) then
   raise exception using errcode='55000',message='DERIVED_REQUEUE_FINANCIAL_SOURCE_CHANGED'; end if;
  if retained->>'engine_key'='TOURNAMENT_FINAL_RECAP' and not production_control.derived_final_recap_ready_v1(target) then
   raise exception using errcode='55000',message='DERIVED_FINAL_RECAP_GATE_REQUIRED'; end if;
  next_cycle:=expected_cycle+1;
  execute format('update scoring_authority.%I set status=''PENDING'',completed_at=null,attempts=0,
   delivery_attempts=0,delivery_cycle=$3,delivery_dead_letter_at=null,delivery_error_class=null,
   delivery_available_at=clock_timestamp(),last_error_code=null,last_error_safe=null,updated_at=clock_timestamp()
   where tournament_id=$1 and %s',table_name,predicate) using target,lookup_identity,next_cycle;
 end if;
 insert into production_control.score_derived_delivery_attempts_v1
  (tournament_id,family,work_identity,cycle,attempt,transition,safe_code,recovery_request_id,recovery_request_hash,recovery_actor_id,recovery_reason,runtime_generation_id,originating_activation_revision)
 values(target,family_value,identity_value,next_cycle,0,'REQUEUED','AUTHORIZED_CAUSE_CORRECTION',request_value,request_hash,actor_id,input->>'reason',generation,nullif(retained->>'activation_revision','')::bigint)
 returning event_id into prior_event;
 return jsonb_build_object('ok',true,'idempotent',false,'eventId',prior_event,'cycle',next_cycle);
end;
$_$;


ALTER FUNCTION production_control.canonical_requeue_score_derived_delivery_v1_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_score_derived_delivery_tick_v1_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_score_derived_delivery_tick_v1_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare target text; generation uuid; activation bigint; final_ready boolean:=false; result_value jsonb; total integer:=0; terminal_count integer;
  family_value text; calcutta_current scoring_authority.calcutta_v1_current%rowtype;
  worker text:=btrim(coalesce(input->>'worker_id',''));
begin
  target:=production_control.assert_canonical_derived_scope_v1(input,canonical_context);
  if worker !~ '^[A-Za-z0-9_.:-]{1,160}$' or input->>'operation_id' is null then
    raise exception using errcode='22023',message='DERIVED_DELIVERY_WORKER_REQUIRED';
  end if;
  if target<>'2026' then select runtime_generation_id into strict generation
    from production_control.annual_scoring_runtime_authorities_v1 where tournament_id=target and authority_status='ACTIVE'; end if;
  activation:=production_control.canonical_execution_activation_revision_v1();
  -- One family per transaction. Combining financial and Competition queue locks
  -- here inverts existing match controls and owner Net Skins completion order.
  -- The supported adapter calls all three families in separate RPC transactions.
  family_value:=input->>'materialization_family';
  if family_value is null or family_value not in('NET_SKINS','CALCUTTA','COMPETITION') then
    raise exception using errcode='22023',message='DERIVED_MATERIALIZATION_FAMILY_REQUIRED'; end if;
  -- Preserve123's ordered Net Skins prefix within its isolated transaction.
  begin
    result_value:=production_control.flush_score_derived_intents_v1(target,family_value,8);
    total:=total+coalesce((result_value->>'processed')::integer,0);
    if coalesce((result_value->>'cancelled')::boolean,false) then
      -- The timeout receipt is durable when this RPC commits. Do no more database
      -- traversal after cancellation; incomplete status cannot be mistaken for idle.
      return jsonb_build_object('ok',true,'cancelled',true,'statusIncomplete',true,
        'materialized',total,'pendingAutomatic',1,'blockedAutomatic',0,'activeLeases',0,'terminal',0,
        'ready',jsonb_build_object('CALCUTTA',false,'COMPETITION',false,'INTELLIGENCE',false),
        'work','[]'::jsonb,'waitingOwner',jsonb_build_object('NET_SKINS',0));
    end if;
  end;
  if family_value='CALCUTTA' then perform production_control.recover_derived_calcutta_activation_v1(target); end if;
  -- Existing annual leases plus a bounded expiry for frozen2026 timestamp claims.
  if family_value='COMPETITION' then
  -- Lock the complete bounded marker set before testing a changing lease clock.
  -- This matches controls even if another marker expires while locks are awaited.
  perform 1 from scoring_authority.competition_recalculation_jobs
    where tournament_id=target and round_number=0 and engine_key in
      ('TEAM_MOMENTUM','TOURNAMENT_STORYLINES','TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL','TOURNAMENT_FINAL_RECAP')
    order by case engine_key when 'TEAM_MOMENTUM' then 1 when 'TOURNAMENT_STORYLINES' then 2
      when 'TOURNAMENT_INTELLIGENCE' then 3 when 'PROJECTION_EDITORIAL' then 4 when 'TOURNAMENT_FINAL_RECAP' then 5 end for update;
  update scoring_authority.competition_recalculation_jobs set status='FAILED',completed_at=clock_timestamp(),
    last_error_code='DERIVED_LEASE_EXPIRED',last_error_safe='Derived work will be retried.',
    claim_token=null,claimed_by=null,lease_expires_at=null
    where tournament_id=target and round_number=0 and engine_key in('TEAM_MOMENTUM','TOURNAMENT_STORYLINES','TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL','TOURNAMENT_FINAL_RECAP')
      and runtime_generation_id is not distinct from generation and status='RUNNING'
      and coalesce(lease_expires_at,started_at+interval '90 seconds')<clock_timestamp();
  end if;
  select * into calcutta_current from scoring_authority.calcutta_v1_current where tournament_id=target;
  final_ready:=production_control.derived_final_recap_ready_v1(target);
  select count(*) into terminal_count from (
    (select 1 from scoring_authority.score_derived_intents_v1 where tournament_id=target and status='DEAD_LETTER' limit 101)
    union all (select 1 from scoring_authority.calcutta_v1_recalculation_jobs where tournament_id=target and delivery_dead_letter_at is not null limit 101)
    union all (select 1 from scoring_authority.net_skins_v1_recalculation_jobs where tournament_id=target and delivery_dead_letter_at is not null limit 101)
    union all (select 1 from scoring_authority.competition_recalculation_jobs where tournament_id=target and round_number=0 and delivery_dead_letter_at is not null limit 5)
    limit 101
  ) bounded;
  return jsonb_build_object('ok',true,'scope',jsonb_build_object('tournamentId',target,'runtimeGenerationId',generation),
    'cancelled',false,'statusIncomplete',false,'materialized',total,'terminal',terminal_count,'terminalTruncated',terminal_count=101,
    'pendingAutomatic',(select count(*) from (
      (select 1 from scoring_authority.score_derived_intents_v1 where tournament_id=target and runtime_generation_id is not distinct from generation and family in('CALCUTTA','COMPETITION') and status<>'SUCCEEDED' limit 101)
      union all (select 1 from scoring_authority.calcutta_v1_recalculation_jobs where tournament_id=target and runtime_generation_id is not distinct from generation and activation_revision=activation
        and configuration_revision=calcutta_current.configuration_revision and auction_revision=calcutta_current.auction_revision
        and status in('PENDING','RUNNING') limit 1)
      union all (select 1 from scoring_authority.competition_recalculation_jobs where tournament_id=target and round_number=0
        and runtime_generation_id is not distinct from generation
        and (engine_key in('TEAM_MOMENTUM','TOURNAMENT_STORYLINES','TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL')
          or (final_ready and engine_key='TOURNAMENT_FINAL_RECAP')) and status<>'SUCCEEDED' limit 5)
      limit 101)bounded),
    'pendingAutomaticLimit',101,
    'blockedAutomatic',(select count(*) from (
      (select 1 from scoring_authority.score_derived_intents_v1 where tournament_id=target
        and runtime_generation_id is distinct from generation and family in('CALCUTTA','COMPETITION') and status<>'SUCCEEDED' limit 101)
      union all (select 1 from scoring_authority.calcutta_v1_recalculation_jobs where tournament_id=target and status in('PENDING','RUNNING')
        and (runtime_generation_id is distinct from generation or activation_revision<>activation
          or configuration_revision<>calcutta_current.configuration_revision or auction_revision<>calcutta_current.auction_revision) limit 1)
      union all (select 1 from scoring_authority.competition_recalculation_jobs where tournament_id=target and round_number=0
        and runtime_generation_id is distinct from generation and (engine_key<>'TOURNAMENT_FINAL_RECAP' or final_ready) and status<>'SUCCEEDED' limit 5)
      limit 101)bounded),'blockedAutomaticLimit',101,
    'activeLeases',(select count(*) from (
      (select 1 from scoring_authority.calcutta_v1_recalculation_jobs where tournament_id=target and runtime_generation_id is not distinct from generation and activation_revision=activation and status='RUNNING' and lease_expires_at>=clock_timestamp() limit 1)
      union all (select 1 from scoring_authority.competition_recalculation_jobs where tournament_id=target and round_number=0 and runtime_generation_id is not distinct from generation and status='RUNNING'
        and coalesce(lease_expires_at,started_at+interval '90 seconds')>=clock_timestamp() limit 5)
    )bounded),
    'ready',jsonb_build_object(
      'CALCUTTA',calcutta_current.configuration_revision>0 and calcutta_current.auction_revision>0 and exists(
        select 1 from scoring_authority.calcutta_v1_recalculation_jobs where tournament_id=target
          and runtime_generation_id is not distinct from generation
          and activation_revision=activation
          and configuration_revision=calcutta_current.configuration_revision and auction_revision=calcutta_current.auction_revision
          and (status='PENDING' or(status='RUNNING' and lease_expires_at<clock_timestamp()))
          and delivery_dead_letter_at is null and delivery_available_at<=clock_timestamp()),
      'COMPETITION',exists(select 1 from scoring_authority.competition_recalculation_jobs where tournament_id=target and round_number=0 and runtime_generation_id is not distinct from generation
        and engine_key in('TEAM_MOMENTUM','TOURNAMENT_STORYLINES') and status in('PENDING','FAILED')
        and delivery_dead_letter_at is null and delivery_available_at<=clock_timestamp()),
      'INTELLIGENCE',exists(select 1 from scoring_authority.competition_recalculation_jobs where tournament_id=target and round_number=0 and runtime_generation_id is not distinct from generation
        and (engine_key in('TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL') or (final_ready and engine_key='TOURNAMENT_FINAL_RECAP'))
        and status in('PENDING','FAILED') and delivery_dead_letter_at is null and delivery_available_at<=clock_timestamp())
        and not exists(select 1 from scoring_authority.competition_recalculation_jobs where tournament_id=target and round_number=0
          and (engine_key in('TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL') or (final_ready and engine_key='TOURNAMENT_FINAL_RECAP'))
          and (runtime_generation_id is distinct from generation or delivery_dead_letter_at is not null or (delivery_attempts>=5 and status<>'SUCCEEDED')
            or delivery_available_at>clock_timestamp() or(status='RUNNING' and coalesce(lease_expires_at,started_at+interval '90 seconds')>=clock_timestamp())))
        and not exists(select 1 from scoring_authority.competition_recalculation_jobs sibling
          where sibling.tournament_id=target and sibling.round_number=0
            and (sibling.engine_key in('TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL') or(final_ready and sibling.engine_key='TOURNAMENT_FINAL_RECAP'))
            and sibling.requested_source_revision is distinct from (select demand.requested_source_revision
              from scoring_authority.competition_recalculation_jobs demand where demand.tournament_id=target and demand.round_number=0
                and (demand.engine_key in('TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL') or(final_ready and demand.engine_key='TOURNAMENT_FINAL_RECAP'))
                and demand.status in('PENDING','FAILED') order by demand.engine_key limit 1))),
    'waitingPublication',jsonb_build_object('FINAL_RECAP',(select count(*) from scoring_authority.competition_recalculation_jobs
      where tournament_id=target and round_number=0 and engine_key='TOURNAMENT_FINAL_RECAP' and status<>'SUCCEEDED'
        and runtime_generation_id is not distinct from generation and not final_ready)),
    'waitingOwner',jsonb_build_object('NET_SKINS',(select count(*) from scoring_authority.net_skins_v1_recalculation_jobs
      where tournament_id=target and round_number between 1 and 3 and runtime_generation_id is not distinct from generation
        and configuration_revision=(select configuration_revision from scoring_authority.net_skins_v1_configuration_current where tournament_id=target) and status in('PENDING','RUNNING'))),
    'work',coalesce((select jsonb_agg(v) from (
      select 'CALCUTTA'::text as family,job_id::text as key,delivery_cycle as cycle,delivery_attempts as attempt
      from scoring_authority.calcutta_v1_recalculation_jobs where tournament_id=target and status='PENDING'
        and activation_revision=activation and configuration_revision=calcutta_current.configuration_revision and auction_revision=calcutta_current.auction_revision
        and runtime_generation_id is not distinct from generation and delivery_dead_letter_at is null and delivery_available_at<=clock_timestamp()
      union all select case when engine_key in('TEAM_MOMENTUM','TOURNAMENT_STORYLINES') then 'COMPETITION' else 'INTELLIGENCE' end,
        engine_key,delivery_cycle,delivery_attempts from scoring_authority.competition_recalculation_jobs
        where tournament_id=target and round_number=0 and (engine_key<>'TOURNAMENT_FINAL_RECAP' or final_ready) and status in('PENDING','FAILED')
        and runtime_generation_id is not distinct from generation and delivery_dead_letter_at is null and delivery_available_at<=clock_timestamp()
      limit 6
    )v),'[]'::jsonb),
    'calcutta',jsonb_build_object('configurationRevision',calcutta_current.configuration_revision,
      'configurationFingerprint',calcutta_current.configuration_fingerprint,'auctionRevision',calcutta_current.auction_revision,
      'auctionFingerprint',calcutta_current.auction_fingerprint));
end;
$_$;


ALTER FUNCTION production_control.canonical_score_derived_delivery_tick_v1_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_stage_draft_revision_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_stage_draft_revision_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}','')));
  actor_auth uuid;
  request_id uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash','')));
  expected_value bigint;
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason',''));
  database_hash text;
  prior_receipt jsonb;
  current_pointer scoring_authority.draft_current_revisions%rowtype;
  current_revision scoring_authority.draft_revisions%rowtype;
  predecessor_picks jsonb := '[]'::jsonb;
  sanitized_picks jsonb;
  validation jsonb;
  next_draft_revision bigint;
  draft_id_value uuid;
  response_value jsonb;
  mutability jsonb;
begin
  target := production_control.assert_draft_authoring_resource_v2(input, resource_context);
  if input->>'operation' is distinct from
       'STAGE_PRODUCTION_DRAFT_REVISION_V1'
     or coalesce(input->>'operation_request_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_revision','') !~ '^[0-9]+$'
     or pg_catalog.jsonb_typeof(input->'configuration') is distinct from 'object'
     or pg_catalog.jsonb_typeof(input->'picks') is distinct from 'array'
     or reason_value='' or pg_catalog.length(reason_value)>500 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_INPUT_INVALID');
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  expected_value := (input->>'expected_revision')::bigint;
  database_hash := production_control.draft_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation','STAGE','tournamentId',target,
      'actorPlayerId',actor_player,'actorAuthUserId',actor_auth,
      'expectedRevision',expected_value,
      'configuration',input->'configuration','picks',input->'picks',
      'reason',reason_value));
  prior_receipt := production_control.draft_operation_receipt_v1(
    target,'STAGE',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-draft-authoring:'||target,0));
  prior_receipt := production_control.draft_operation_receipt_v1(
    target,'STAGE',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  mutability := production_control.draft_mutability_v1(target);
  if not coalesce((mutability->>'editable')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_CORRECTION_REQUIRED',
      'mutability',mutability);
  end if;
  select value.* into current_pointer
  from scoring_authority.draft_current_revisions value
  where value.tournament_id=target for update;
  if current_pointer.revision_id is not null then
    select value.* into current_revision
    from scoring_authority.draft_revisions value
    where value.revision_id=current_pointer.revision_id;
    predecessor_picks := production_control.draft_projection_row_v1(
      current_pointer.revision_id)->'picks';
  end if;
  if coalesce(current_revision.revision_number,0)<>expected_value then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_PREDECESSOR_STALE',
      'currentRevision',coalesce(current_revision.revision_number,0));
  end if;
  sanitized_picks := production_control.draft_sanitize_pick_provenance_v1(
    input->'picks',predecessor_picks);
  validation := production_control.validate_draft_authoring_v1(
    target,input->'configuration',sanitized_picks);
  if not coalesce((validation->>'pass')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_VALIDATION_FAILED',
      'issues',validation->'issues');
  end if;
  if current_revision.revision_id is not null
     and current_revision.payload_fingerprint=
       validation->>'payloadFingerprint' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_NO_CHANGES');
  end if;
  update production_control.draft_authoring_drafts_v1 set state='SUPERSEDED'
  where tournament_id=target and state in ('STAGED','VALIDATED');
  select coalesce(pg_catalog.max(value.draft_revision),0)+1
    into next_draft_revision
  from production_control.draft_authoring_drafts_v1 value
  where value.tournament_id=target;
  insert into production_control.draft_authoring_drafts_v1 (
    tournament_id,draft_revision,state,authoring_kind,expected_revision,
    predecessor_revision_id,configuration,picks,presentation_seed,
    configuration_fingerprint,picks_fingerprint,payload_fingerprint,
    validation_diagnostics,reason,created_by_player_id,
    created_by_auth_user_id
  ) values (
    target,next_draft_revision,'STAGED','DIRECTOR_EDIT',expected_value,
    current_revision.revision_id,validation->'configuration',validation->'picks',
    validation->'presentationSeed',validation->>'configurationFingerprint',
    validation->>'picksFingerprint',validation->>'payloadFingerprint',
    validation->'diagnostics',reason_value,actor_player,actor_auth
  ) returning draft_id into draft_id_value;
  response_value := pg_catalog.jsonb_build_object(
    'ok',true,'code','DRAFT_REVISION_STAGED','idempotent',false,
    'tournamentId',target,'draftId',draft_id_value,
    'draftRevision',next_draft_revision,'state','STAGED',
    'expectedRevision',expected_value,
    'configuration',validation->'configuration','picks',validation->'picks',
    'validationDiagnostics',validation->'diagnostics');
  insert into production_control.draft_authoring_audit_events_v1 (
    tournament_id,draft_id,action,actor_player_id,actor_auth_user_id,
    operation_request_id,summary
  ) values (
    target,draft_id_value,'REVISION_STAGED',actor_player,actor_auth,request_id,
    pg_catalog.jsonb_build_object(
      'draftRevision',next_draft_revision,
      'predecessorRevision',expected_value,
      'totalPicks',(validation#>>'{configuration,total_picks}')::integer,
      'selectedPicks',(validation#>>'{diagnostics,selectedPicks}')::integer));
  insert into production_control.draft_operation_receipts_v1 (
    tournament_id,operation,operation_request_id,
    declared_request_payload_hash,request_payload_hash,
    actor_player_id,actor_auth_user_id,response
  ) values (
    target,'STAGE',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value);
  return response_value;
exception when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','DRAFT_INPUT_INVALID');
when unique_violation then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','DRAFT_OPERATION_CONFLICT');
end;

$_$;


ALTER FUNCTION production_control.canonical_stage_draft_revision_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_stage_prediction_settings_revision_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_stage_prediction_settings_revision_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  request_id uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash', ''
  )));
  expected_revision bigint;
  current_config scoring_authority.odds_input_configurations%rowtype;
  validation jsonb;
  database_hash text;
  prior_receipt jsonb;
  next_draft_revision bigint;
  draft_id_value uuid;
  response_value jsonb;
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason', ''));
begin
  target := production_control.assert_prediction_settings_authoring_resource_v2(input, resource_context);
  if input->>'operation' is distinct from
       'STAGE_PRODUCTION_PREDICTION_SETTINGS_REVISION_V1'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_configuration_revision', '')
       !~ '^[0-9]+$'
     or pg_catalog.jsonb_typeof(input->'canonical_settings')
       is distinct from 'object'
     or reason_value = '' or pg_catalog.length(reason_value) > 500 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_INPUT_INVALID'
    );
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  expected_revision := (input->>'expected_configuration_revision')::bigint;
  database_hash := production_control.prediction_settings_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation', 'STAGE', 'tournamentId', target,
      'actorPlayerId', actor_player, 'actorAuthUserId', actor_auth,
      'expectedConfigurationRevision', expected_revision,
      'canonicalSettings', input->'canonical_settings',
      'reason', reason_value
    )
  );
  prior_receipt := production_control.prediction_settings_receipt_v1(
    target, 'STAGE', request_id, declared_hash, database_hash
  );
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-prediction-settings:' || target, 0
  ));
  prior_receipt := production_control.prediction_settings_receipt_v1(
    target, 'STAGE', request_id, declared_hash, database_hash
  );
  if prior_receipt is not null then return prior_receipt; end if;
  select value.* into current_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target and value.is_current for update;
  if coalesce(current_config.configuration_revision, 0) <> expected_revision then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_PREDECESSOR_STALE',
      'currentRevision', coalesce(current_config.configuration_revision, 0)
    );
  end if;
  validation := production_control.validate_prediction_settings_v1(
    input->'canonical_settings', current_config.canonical_settings
  );
  if not coalesce((validation->>'pass')::boolean, false) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_VALIDATION_FAILED',
      'issues', validation->'issues'
    );
  end if;
  if coalesce((validation->>'changedSettingCount')::integer, 0) = 0 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_NO_CHANGES'
    );
  end if;
  update production_control.prediction_settings_drafts_v1 set
    state = 'SUPERSEDED'
  where tournament_id = target and state in ('STAGED', 'VALIDATED');
  select coalesce(pg_catalog.max(value.draft_revision), 0) + 1
    into next_draft_revision
  from production_control.prediction_settings_drafts_v1 value
  where value.tournament_id = target;
  insert into production_control.prediction_settings_drafts_v1 (
    tournament_id, draft_revision, state, authoring_kind,
    expected_configuration_revision, predecessor_configuration_id,
    canonical_settings, effective_settings, settings_fingerprint,
    effective_settings_fingerprint, changed_keys,
    validation_diagnostics, reason, created_by_player_id,
    created_by_auth_user_id
  ) values (
    target, next_draft_revision, 'STAGED', 'DIRECTOR_EDIT',
    expected_revision, current_config.id,
    validation->'canonicalSettings', validation->'effectiveSettings',
    validation->>'settingsFingerprint',
    validation->>'effectiveSettingsFingerprint',
    validation->'changedKeys',
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-prediction-settings-authoring-v1',
      'settingsContractVersion', 'prediction-settings-v1',
      'completeSchema', true,
      'legacyRecalibrationProfile',
        coalesce((validation->>'legacyRecalibrationProfile')::boolean, false),
      'issues', '[]'::jsonb
    ),
    reason_value, actor_player, actor_auth
  ) returning draft_id into draft_id_value;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PREDICTION_SETTINGS_REVISION_STAGED',
    'idempotent', false,
    'tournamentId', target,
    'draftId', draft_id_value,
    'draftRevision', next_draft_revision,
    'state', 'STAGED',
    'expectedConfigurationRevision', expected_revision,
    'changedKeys', validation->'changedKeys',
    'changedSettingCount',
      (validation->>'changedSettingCount')::integer,
    'recalculationRequiredAfterCommit', true
  );
  insert into production_control.prediction_settings_audit_events_v1 (
    tournament_id, draft_id, action, actor_player_id,
    actor_auth_user_id, operation_request_id, request_payload_hash, summary
  ) values (
    target, draft_id_value, 'REVISION_STAGED', actor_player, actor_auth,
    request_id, database_hash, pg_catalog.jsonb_build_object(
      'draftRevision', next_draft_revision,
      'predecessorConfigurationRevision', expected_revision,
      'changedSettingCount',
        (validation->>'changedSettingCount')::integer
    )
  );
  insert into production_control.prediction_settings_operation_receipts_v1 (
    tournament_id, operation, operation_request_id,
    declared_request_payload_hash, request_payload_hash,
    actor_player_id, actor_auth_user_id, response
  ) values (
    target, 'STAGE', request_id, declared_hash, database_hash,
    actor_player, actor_auth, response_value
  );
  return response_value;
exception when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'ok', false, 'code', 'PREDICTION_SETTINGS_INPUT_INVALID'
  );
end;

$_$;


ALTER FUNCTION production_control.canonical_stage_prediction_settings_revision_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_submit_hole_score_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_submit_hole_score_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    AS $$
declare
  match_row scoring_authority.matches%rowtype;
  hole_row scoring_authority.hole_scores%rowtype;
  mutation_row scoring_authority.score_mutations%rowtype;
  permission_row scoring_authority.scoring_permissions%rowtype;
  target_match text := input->>'match_id';
  target_hole integer := nullif(input->>'hole_number', '')::integer;
  mutation_identity text := input->>'mutation_key';
  actor text := input#>>'{authorization,player_id}';
  actor_role text := upper(coalesce(input#>>'{authorization,role}', 'PLAYER'));
  team_1_gross jsonb := input->'team_1_gross_scores';
  team_2_gross jsonb := input->'team_2_gross_scores';
  expected_match bigint := coalesce(nullif(input->>'expected_match_revision', '')::bigint, -1);
  expected_hole bigint := coalesce(nullif(input->>'expected_hole_revision', '')::bigint, -1);
  expected_count integer;
  current_hole_revision bigint := 0;
  hole_exists boolean := false;
  next_hole_revision bigint;
  next_match_revision bigint;
  stroke_index_value integer;
  team_1_strokes jsonb;
  team_2_strokes jsonb;
  team_1_net integer;
  team_2_net integer;
  winner text;
  progress jsonb;
  before_state jsonb;
  payload_hash_value text;
  result_value jsonb;
  transition_at timestamptz := clock_timestamp();
begin
  perform production_control.assert_canonical_scoring_context_v1(input, canonical_context, 'RUNTIME');
  perform production_control.assert_production_scoring_actor(input, false);
  if coalesce(target_match, '') = '' or coalesce(mutation_identity, '') = '' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_REQUEST');
  end if;
  select * into match_row from scoring_authority.matches
    where match_id = target_match and tournament_id = '2026' for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'MATCH_NOT_FOUND'); end if;
  if input#>>'{authorization,match_id}' <> target_match then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHORIZED');
  end if;
  if actor_role = 'PLAYER' then
    select * into permission_row from scoring_authority.scoring_permissions
      where match_id = target_match and player_id = actor;
    if not found or not permission_row.can_score or permission_row.revoked_at is not null then
      return jsonb_build_object('ok', false, 'code', 'UNAUTHORIZED');
    end if;
    if coalesce((input#>>'{authorization,permission_revision}')::bigint, -1) <> permission_row.permission_revision
       or permission_row.permission_revision <> match_row.permission_revision then
      return jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE',
        'current_permission_revision', match_row.permission_revision);
    end if;
  elsif actor_role = 'DIRECTOR' then
    if coalesce((input#>>'{authorization,permission_revision}')::bigint, -1) <> match_row.permission_revision then
      return jsonb_build_object('ok', false, 'code', 'PERMISSION_STALE',
        'current_permission_revision', match_row.permission_revision);
    end if;
  else
    return jsonb_build_object('ok', false, 'code', 'UNAUTHORIZED');
  end if;
  payload_hash_value := production_control.cutover_payload_hash(jsonb_build_object(
    'match_id', target_match, 'hole_number', target_hole,
    'team_1_gross_scores', team_1_gross, 'team_2_gross_scores', team_2_gross,
    'actor_id', actor
  ));
  select * into mutation_row from scoring_authority.score_mutations
    where match_id = target_match and mutation_key = mutation_identity;
  if found then
    if mutation_row.payload_hash = payload_hash_value then
      return mutation_row.result || jsonb_build_object('idempotent', true);
    end if;
    return jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_CONFLICT');
  end if;
  if match_row.scoring_locked then return jsonb_build_object('ok', false, 'code', 'SCORING_LOCKED'); end if;
  if match_row.status = 'FINAL' then return jsonb_build_object('ok', false, 'code', 'MATCH_FINAL'); end if;
  if target_hole not between 1 and 18 then return jsonb_build_object('ok', false, 'code', 'INVALID_HOLE'); end if;
  if expected_match <> match_row.match_revision then
    return jsonb_build_object('ok', false, 'code', 'MATCH_REVISION_CONFLICT',
      'current_match_revision', match_row.match_revision);
  end if;
  select * into hole_row from scoring_authority.hole_scores
    where match_id = target_match and hole_number = target_hole;
  hole_exists := found;
  if hole_exists then current_hole_revision := hole_row.hole_revision; end if;
  if expected_hole <> current_hole_revision then
    return jsonb_build_object('ok', false, 'code', 'HOLE_REVISION_CONFLICT',
      'current_hole_revision', current_hole_revision);
  end if;
  expected_count := case when match_row.format = 'BB' then 2 else 1 end;
  if not scoring_authority.valid_gross_scores(team_1_gross, expected_count)
     or not scoring_authority.valid_gross_scores(team_2_gross, expected_count) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_GROSS_SCORES');
  end if;
  if hole_exists and hole_row.team_1_gross_scores = team_1_gross
     and hole_row.team_2_gross_scores = team_2_gross then
    progress := scoring_authority.match_progress(target_match, match_row.format);
    return jsonb_build_object('ok', true, 'code', 'NO_CHANGE', 'semantic_noop', true,
      'idempotent', true, 'match_id', target_match, 'hole_number', target_hole,
      'hole_revision', hole_row.hole_revision, 'match_revision', match_row.match_revision,
      'updated_at', hole_row.updated_at, 'match', progress,
      'audit_created', false, 'google_outbox_created', false);
  end if;
  select stroke_index into stroke_index_value from scoring_authority.match_holes
    where match_id = target_match and hole_number = target_hole;
  if stroke_index_value is null then return jsonb_build_object('ok', false, 'code', 'INVALID_SCORING_SNAPSHOT'); end if;
  if match_row.format = 'SC' then
    select jsonb_build_array(scoring_authority.strokes_on_hole((snapshot.team_configuration->>'team_1_strokes')::integer, stroke_index_value)),
      jsonb_build_array(scoring_authority.strokes_on_hole((snapshot.team_configuration->>'team_2_strokes')::integer, stroke_index_value))
      into team_1_strokes, team_2_strokes
    from scoring_authority.scoring_snapshots snapshot
    where snapshot_id = match_row.scoring_snapshot_id;
  else
    select jsonb_agg(scoring_authority.strokes_on_hole(participant.final_strokes, stroke_index_value) order by participant.player_slot)
      into team_1_strokes from scoring_authority.match_participants participant
      where match_id = target_match and team_side = 1;
    select jsonb_agg(scoring_authority.strokes_on_hole(participant.final_strokes, stroke_index_value) order by participant.player_slot)
      into team_2_strokes from scoring_authority.match_participants participant
      where match_id = target_match and team_side = 2;
  end if;
  if match_row.format = 'BB' then
    select min(gross::integer - stroke::integer) into team_1_net
    from jsonb_array_elements_text(team_1_gross) with ordinality g(gross, n)
    join jsonb_array_elements_text(team_1_strokes) with ordinality s(stroke, n2) on n = n2;
    select min(gross::integer - stroke::integer) into team_2_net
    from jsonb_array_elements_text(team_2_gross) with ordinality g(gross, n)
    join jsonb_array_elements_text(team_2_strokes) with ordinality s(stroke, n2) on n = n2;
  else
    team_1_net := (team_1_gross->>0)::integer - (team_1_strokes->>0)::integer;
    team_2_net := (team_2_gross->>0)::integer - (team_2_strokes->>0)::integer;
  end if;
  winner := case when team_1_net = team_2_net then 'Halved'
    when team_1_net < team_2_net then 'Team 1' else 'Team 2' end;
  before_state := case when current_hole_revision = 0 then '{}'::jsonb else to_jsonb(hole_row) end;
  next_hole_revision := current_hole_revision + 1;
  next_match_revision := match_row.match_revision + 1;
  insert into scoring_authority.hole_scores (
    match_id, hole_number, hole_revision, team_1_gross_scores, team_2_gross_scores,
    team_1_strokes, team_2_strokes, team_1_net_score, team_2_net_score,
    hole_winner, mutation_key, actor_id
  ) values (
    target_match, target_hole, next_hole_revision, team_1_gross, team_2_gross,
    team_1_strokes, team_2_strokes, team_1_net, team_2_net, winner, mutation_identity, actor
  ) on conflict (match_id, hole_number) do update set
    hole_revision = excluded.hole_revision,
    team_1_gross_scores = excluded.team_1_gross_scores,
    team_2_gross_scores = excluded.team_2_gross_scores,
    team_1_strokes = excluded.team_1_strokes,
    team_2_strokes = excluded.team_2_strokes,
    team_1_net_score = excluded.team_1_net_score,
    team_2_net_score = excluded.team_2_net_score,
    hole_winner = excluded.hole_winner,
    mutation_key = excluded.mutation_key,
    actor_id = excluded.actor_id,
    updated_at = transition_at;
  progress := scoring_authority.match_progress(target_match, match_row.format);
  update scoring_authority.matches set
    match_revision = next_match_revision,
    scored_holes = (progress->>'scored_holes')::integer,
    current_hole = (progress->>'current_hole')::integer,
    holes_remaining = (progress->>'holes_remaining')::integer,
    team_1_holes_won = (progress->>'team_1_holes_won')::integer,
    team_2_holes_won = (progress->>'team_2_holes_won')::integer,
    running_result = progress->>'running_result',
    result_winner = progress->>'result_winner',
    clinched = (progress->>'clinched')::boolean,
    scorecard_complete = (progress->>'scorecard_complete')::boolean,
    authority_updated_at = transition_at,
    updated_at = transition_at
  where match_id = target_match;
  result_value := jsonb_build_object(
    'ok', true, 'code', 'ACCEPTED', 'match_id', target_match,
    'google_target_match_id', target_match, 'hole_number', target_hole,
    'hole_revision', next_hole_revision, 'match_revision', next_match_revision,
    'permission_revision', match_row.permission_revision, 'updated_at', transition_at,
    'gross', jsonb_build_object('team_1', team_1_gross, 'team_2', team_2_gross),
    'strokes', jsonb_build_object('team_1', team_1_strokes, 'team_2', team_2_strokes),
    'net', jsonb_build_object('team_1', team_1_net, 'team_2', team_2_net),
    'hole_winner', winner, 'match', progress,
    'audit_created', true, 'google_outbox_created', false
  );
  insert into scoring_authority.score_mutations (
    match_id, mutation_key, mutation_type, hole_number, payload_hash,
    previous_match_revision, next_match_revision, previous_hole_revision,
    next_hole_revision, result, actor_id, originating_auth_user_id
  ) values (
    target_match, mutation_identity, 'HOLE_SCORE', target_hole, payload_hash_value,
    match_row.match_revision, next_match_revision, current_hole_revision,
    next_hole_revision, result_value, actor, (input#>>'{authorization,auth_user_id}')::uuid
  );
  insert into scoring_authority.score_revision_history (
    match_id, hole_number, mutation_key, action, previous_match_revision,
    next_match_revision, previous_hole_revision, next_hole_revision,
    before_state, after_state, actor_id
  ) values (
    target_match, target_hole, mutation_identity, 'HOLE_SCORE_UPSERTED',
    match_row.match_revision, next_match_revision, current_hole_revision,
    next_hole_revision, before_state, result_value, actor
  );
  insert into scoring_authority.audit_events (tournament_id, match_id, mutation_key, action, actor_id, metadata)
    values ('2026', target_match, mutation_identity, 'HOLE_SCORE_UPSERTED', actor, result_value);
  -- Google runtime retired: external delivery is not canonical authority.
  return result_value;
end;
$$;


ALTER FUNCTION production_control.canonical_submit_hole_score_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_tournament_setup_read_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_tournament_setup_read_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare result_value jsonb; data_value jsonb; matches_value jsonb;
begin
  result_value:=production_control.read_tournament_setup_before_round_workspace_v1(input);
  data_value:=result_value->'data';
  if result_value->>'ok' is distinct from 'true'
    or jsonb_typeof(data_value) is distinct from 'object'
    or jsonb_typeof(data_value->'matches') is distinct from 'array' then
    raise exception 'TOURNAMENT_SETUP_RESPONSE_INVALID';
  end if;
  select jsonb_agg(item.value || jsonb_build_object(
    'detailsManaged',d.match_id is not null,
    'contextFingerprint',production_control.tournament_setup_hash_v1(jsonb_build_object(
      'details',to_jsonb(d),'round',to_jsonb(r),'course',to_jsonb(c),
      'holes',(select jsonb_agg(to_jsonb(h) order by h.hole_number)
        from scoring_authority.tournament_setup_course_holes_v1 h where h.tournament_id='2026'
          and h.course_id=d.course_id and h.tee_id=d.tee_id),
      'snapshot',item.value->'snapshot',
      'handicap',(select revision_id from scoring_authority.handicap_revision_current where tournament_id='2026')
    ))) order by (item.value->>'roundNumber')::integer,(item.value->>'matchNumber')::integer)
    into matches_value from jsonb_array_elements(data_value->'matches') item(value)
    left join scoring_authority.tournament_setup_match_details_v1 d on d.match_id=item.value->>'matchId'
    left join scoring_authority.rounds r on r.tournament_id='2026' and r.round_number=(item.value->>'roundNumber')::integer
    left join scoring_authority.tournament_setup_course_tees_v1 c on c.tournament_id='2026' and c.course_id=d.course_id and c.tee_id=d.tee_id;
  return jsonb_set(result_value,'{data}',data_value || jsonb_build_object(
    'matches',coalesce(matches_value,'[]'::jsonb),
    'approvedHandicapRevisionId',(select revision_id from scoring_authority.handicap_revision_current where tournament_id='2026'),
    'approvedHandicapRevisionNumber',(select to_jsonb(c)->'revision_number' from scoring_authority.handicap_revision_current c where tournament_id='2026')));
end;
$$;


ALTER FUNCTION production_control.canonical_tournament_setup_read_v1(input jsonb) OWNER TO postgres;

--
-- Name: canonical_validate_draft_revision_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_validate_draft_revision_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}','')));
  actor_auth uuid;
  request_id uuid;
  draft_id_value uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash','')));
  expected_value bigint;
  database_hash text;
  prior_receipt jsonb;
  draft production_control.draft_authoring_drafts_v1%rowtype;
  current_revision scoring_authority.draft_revisions%rowtype;
  validation jsonb;
  response_value jsonb;
  mutability jsonb;
begin
  target := production_control.assert_draft_authoring_resource_v2(input, resource_context);
  if input->>'operation' is distinct from
       'VALIDATE_PRODUCTION_DRAFT_REVISION_V1'
     or coalesce(input->>'operation_request_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'draft_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_revision','') !~ '^[0-9]+$' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_INPUT_INVALID');
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  draft_id_value := (input->>'draft_id')::uuid;
  expected_value := (input->>'expected_revision')::bigint;
  database_hash := production_control.draft_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation','VALIDATE','tournamentId',target,
      'actorPlayerId',actor_player,'actorAuthUserId',actor_auth,
      'draftId',draft_id_value,'expectedRevision',expected_value));
  prior_receipt := production_control.draft_operation_receipt_v1(
    target,'VALIDATE',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-draft-authoring:'||target,0));
  prior_receipt := production_control.draft_operation_receipt_v1(
    target,'VALIDATE',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  mutability := production_control.draft_mutability_v1(target);
  if not coalesce((mutability->>'editable')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_CORRECTION_REQUIRED','mutability',mutability);
  end if;
  select value.* into strict draft
  from production_control.draft_authoring_drafts_v1 value
  where value.draft_id=draft_id_value and value.tournament_id=target
  for update;
  select revision.* into current_revision
  from scoring_authority.draft_current_revisions pointer
  join scoring_authority.draft_revisions revision
    on revision.revision_id=pointer.revision_id
  where pointer.tournament_id=target for update of pointer;
  if coalesce(current_revision.revision_number,0)<>expected_value
     or draft.expected_revision<>expected_value
     or draft.state not in ('STAGED','VALIDATED') then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_PREDECESSOR_STALE');
  end if;
  validation := production_control.validate_draft_authoring_v1(
    target,draft.configuration,draft.picks);
  if not coalesce((validation->>'pass')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_VALIDATION_FAILED',
      'issues',validation->'issues');
  end if;
  update production_control.draft_authoring_drafts_v1 set
    state='VALIDATED',configuration=validation->'configuration',
    picks=validation->'picks',presentation_seed=validation->'presentationSeed',
    configuration_fingerprint=validation->>'configurationFingerprint',
    picks_fingerprint=validation->>'picksFingerprint',
    payload_fingerprint=validation->>'payloadFingerprint',
    validation_diagnostics=validation->'diagnostics'||
      pg_catalog.jsonb_build_object('validated',true),
    validated_at=coalesce(validated_at,pg_catalog.clock_timestamp())
  where draft_id=draft_id_value;
  if draft.state='STAGED' then
    insert into production_control.draft_authoring_audit_events_v1 (
      tournament_id,draft_id,action,actor_player_id,actor_auth_user_id,
      operation_request_id,summary
    ) values (
      target,draft_id_value,'REVISION_VALIDATED',actor_player,actor_auth,
      request_id,pg_catalog.jsonb_build_object(
        'draftRevision',draft.draft_revision,
        'totalPicks',(validation#>>'{configuration,total_picks}')::integer,
        'selectedPicks',(validation#>>'{diagnostics,selectedPicks}')::integer));
  end if;
  response_value := pg_catalog.jsonb_build_object(
    'ok',true,'code','DRAFT_REVISION_VALIDATED',
    'idempotent',draft.state='VALIDATED','tournamentId',target,
    'draftId',draft_id_value,'draftRevision',draft.draft_revision,
    'state','VALIDATED','configuration',validation->'configuration',
    'picks',validation->'picks',
    'validationDiagnostics',validation->'diagnostics');
  insert into production_control.draft_operation_receipts_v1 (
    tournament_id,operation,operation_request_id,
    declared_request_payload_hash,request_payload_hash,
    actor_player_id,actor_auth_user_id,response
  ) values (
    target,'VALIDATE',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value);
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','DRAFT_STAGED_REVISION_NOT_FOUND');
end;

$_$;


ALTER FUNCTION production_control.canonical_validate_draft_revision_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_validate_guide_draft_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_validate_guide_draft_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  target_year integer;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}','')));
  actor_auth uuid;
  request_id uuid;
  draft_id_value uuid;
  expected_draft_version bigint;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash','')));
  authoring_value jsonb := coalesce(input->'authoring_content',input->'content');
  projection_value jsonb := input->'projection_payload';
  database_hash text;
  prior_receipt jsonb;
  draft production_control.guide_authoring_drafts_v1%rowtype;
  current_value jsonb;
  validation jsonb;
  next_version bigint;
  response_value jsonb;
begin
  target := production_control.assert_guide_authoring_resource_v2(input, resource_context);
  target_year := target::integer;
  if input->>'operation' is distinct from
       'VALIDATE_PRODUCTION_GUIDE_DRAFT_V1'
     or coalesce(input->>'operation_request_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'draft_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_draft_version','') !~ '^[1-9][0-9]*$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authoring_content_fingerprint','')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'content_fingerprint','') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'projection_payload_hash','') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'canonical_reference_fingerprint','')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(authoring_value) is distinct from 'object'
     or pg_catalog.jsonb_typeof(projection_value) is distinct from 'object' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_INPUT_INVALID');
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  draft_id_value := (input->>'draft_id')::uuid;
  expected_draft_version := (input->>'expected_draft_version')::bigint;
  database_hash := production_control.guide_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation','VALIDATE','tournamentId',target,
      'actorPlayerId',actor_player,'actorAuthUserId',actor_auth,
      'draftId',draft_id_value,'expectedDraftVersion',expected_draft_version,
      'authoringContent',authoring_value,'projectionPayload',projection_value,
      'canonicalReferenceFingerprint',
        input->>'canonical_reference_fingerprint'));
  prior_receipt := production_control.guide_operation_receipt_v1(
    target,'VALIDATE',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-guide-authoring:'||target,0));
  prior_receipt := production_control.guide_operation_receipt_v1(
    target,'VALIDATE',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  select value.* into strict draft
  from production_control.guide_authoring_drafts_v1 value
  where value.draft_id=draft_id_value and value.tournament_id=target
  for update;
  current_value := production_control.guide_current_publication_v1(target);
  if draft.state not in ('DRAFT','VALIDATED')
     or draft.draft_version<>expected_draft_version then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_DRAFT_VERSION_STALE',
      'currentDraftVersion',draft.draft_version);
  end if;
  if draft.expected_published_revision<>(current_value->>'revision')::bigint
     or draft.expected_published_revision_id::text is distinct from
       nullif(current_value->>'revisionId','') then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_PREDECESSOR_STALE');
  end if;
  if coalesce((draft.validation_diagnostics->>'requiresReview')::boolean,false)
  then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_COPY_REVIEW_REQUIRED');
  end if;
  if authoring_value is distinct from draft.authoring_content then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_DRAFT_CONTENT_STALE');
  end if;
  if input->>'canonical_reference_fingerprint' is distinct from
       production_control.guide_canonical_reference_fingerprint_v1(target) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_CANONICAL_REFERENCE_STALE');
  end if;
  validation := production_control.validate_guide_authoring_v1(
    target,target_year,authoring_value,projection_value,
    input->>'authoring_content_fingerprint',input->>'content_fingerprint',
    input->>'projection_payload_hash');
  if not coalesce((validation->>'pass')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_VALIDATION_FAILED','issues',validation->'issues');
  end if;
  next_version := case when draft.state='VALIDATED'
      and draft.projection_payload=projection_value
      and draft.authoring_content_fingerprint=
        validation->>'authoringContentFingerprint'
      and draft.content_fingerprint=validation->>'contentFingerprint'
      and draft.projection_payload_hash=validation->>'projectionPayloadHash'
      and draft.canonical_reference_fingerprint=
        input->>'canonical_reference_fingerprint'
      and draft.validated_canonical_reference_fingerprint=
        input->>'canonical_reference_fingerprint'
    then draft.draft_version else draft.draft_version+1 end;
  if next_version<>draft.draft_version then
    update production_control.guide_authoring_drafts_v1 set
      draft_version=next_version,state='VALIDATED',
      projection_payload=validation->'projectionPayload',
      authoring_content_fingerprint=
        validation->>'authoringContentFingerprint',
      content_fingerprint=validation->>'contentFingerprint',
      projection_payload_hash=validation->>'projectionPayloadHash',
      canonical_reference_fingerprint=
        input->>'canonical_reference_fingerprint',
      validated_content_fingerprint=validation->>'contentFingerprint',
      validated_canonical_reference_fingerprint=
        input->>'canonical_reference_fingerprint',
      validation_diagnostics=(validation->'diagnostics')||
        pg_catalog.jsonb_build_object(
          'validated',true,'validatedDraftVersion',next_version,
          'requiresReview',false),
      validated_at=pg_catalog.clock_timestamp(),
      updated_at=pg_catalog.clock_timestamp()
    where draft_id=draft_id_value;
    insert into production_control.guide_authoring_audit_events_v1 (
      tournament_id,draft_id,action,actor_player_id,actor_auth_user_id,summary
    ) values (
      target,draft_id_value,'VALIDATION_COMPLETED',actor_player,actor_auth,
      pg_catalog.jsonb_build_object(
        'draftVersion',next_version,
        'issueCount',0,
        'itemCount',validation#>>'{diagnostics,authoringItemCount}'));
  end if;
  response_value := pg_catalog.jsonb_build_object(
    'ok',true,'code','GUIDE_DRAFT_VALIDATED','idempotent',false,
    'tournamentId',target,'draftId',draft_id_value,
    'draftVersion',next_version,'state','VALIDATED',
    'authoringContent',validation->'authoringContent',
    'preview',validation->'projectionPayload',
    'projectionPayload',validation->'projectionPayload',
    'validationDiagnostics',validation->'diagnostics');
  insert into production_control.guide_authoring_operation_receipts_v1 (
    tournament_id,operation,operation_request_id,
    declared_request_payload_hash,request_payload_hash,
    actor_player_id,actor_auth_user_id,response
  ) values (
    target,'VALIDATE',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value);
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_DRAFT_NOT_FOUND');
when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_INPUT_INVALID');
end;

$_$;


ALTER FUNCTION production_control.canonical_validate_guide_draft_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_validate_prediction_settings_revision_resource_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_validate_prediction_settings_revision_resource_v2(input jsonb, resource_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

declare
  target text;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  request_id uuid;
  draft_id_value uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash', ''
  )));
  expected_revision bigint;
  database_hash text;
  prior_receipt jsonb;
  draft production_control.prediction_settings_drafts_v1%rowtype;
  current_config scoring_authority.odds_input_configurations%rowtype;
  validation jsonb;
  response_value jsonb;
begin
  target := production_control.assert_prediction_settings_authoring_resource_v2(input, resource_context);
  if input->>'operation' is distinct from
       'VALIDATE_PRODUCTION_PREDICTION_SETTINGS_REVISION_V1'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'draft_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_configuration_revision', '')
       !~ '^[0-9]+$' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_INPUT_INVALID'
    );
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  draft_id_value := (input->>'draft_id')::uuid;
  expected_revision := (input->>'expected_configuration_revision')::bigint;
  database_hash := production_control.prediction_settings_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation', 'VALIDATE', 'tournamentId', target,
      'actorPlayerId', actor_player, 'actorAuthUserId', actor_auth,
      'draftId', draft_id_value,
      'expectedConfigurationRevision', expected_revision
    )
  );
  prior_receipt := production_control.prediction_settings_receipt_v1(
    target, 'VALIDATE', request_id, declared_hash, database_hash
  );
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-prediction-settings:' || target, 0
  ));
  prior_receipt := production_control.prediction_settings_receipt_v1(
    target, 'VALIDATE', request_id, declared_hash, database_hash
  );
  if prior_receipt is not null then return prior_receipt; end if;
  select value.* into strict draft
  from production_control.prediction_settings_drafts_v1 value
  where value.draft_id = draft_id_value
    and value.tournament_id = target for update;
  select value.* into current_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target and value.is_current for update;
  if coalesce(current_config.configuration_revision, 0) <> expected_revision
     or draft.expected_configuration_revision <> expected_revision
     or draft.state not in ('STAGED', 'VALIDATED') then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_PREDECESSOR_STALE'
    );
  end if;
  validation := production_control.validate_prediction_settings_v1(
    draft.canonical_settings, current_config.canonical_settings
  );
  if not coalesce((validation->>'pass')::boolean, false) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_VALIDATION_FAILED',
      'issues', validation->'issues'
    );
  end if;
  if coalesce((validation->>'changedSettingCount')::integer, 0) = 0 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_NO_CHANGES'
    );
  end if;
  update production_control.prediction_settings_drafts_v1 set
    state = 'VALIDATED',
    effective_settings = validation->'effectiveSettings',
    settings_fingerprint = validation->>'settingsFingerprint',
    effective_settings_fingerprint =
      validation->>'effectiveSettingsFingerprint',
    changed_keys = validation->'changedKeys',
    validation_diagnostics = validation_diagnostics ||
      pg_catalog.jsonb_build_object('validated', true),
    validated_at = coalesce(validated_at, pg_catalog.clock_timestamp())
  where draft_id = draft_id_value;
  if draft.state = 'STAGED' then
    insert into production_control.prediction_settings_audit_events_v1 (
      tournament_id, draft_id, action, actor_player_id,
      actor_auth_user_id, operation_request_id, request_payload_hash, summary
    ) values (
      target, draft_id_value, 'REVISION_VALIDATED',
      actor_player, actor_auth, request_id, database_hash,
      pg_catalog.jsonb_build_object(
        'draftRevision', draft.draft_revision,
        'changedSettingCount',
          (validation->>'changedSettingCount')::integer
      )
    );
  end if;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PREDICTION_SETTINGS_REVISION_VALIDATED',
    'idempotent', draft.state = 'VALIDATED',
    'draftId', draft_id_value,
    'draftRevision', draft.draft_revision,
    'state', 'VALIDATED',
    'canonicalSettings', draft.canonical_settings,
    'effectiveSettings', validation->'effectiveSettings',
    'changedKeys', validation->'changedKeys',
    'changedSettingCount',
      (validation->>'changedSettingCount')::integer
  );
  insert into production_control.prediction_settings_operation_receipts_v1 (
    tournament_id, operation, operation_request_id,
    declared_request_payload_hash, request_payload_hash,
    actor_player_id, actor_auth_user_id, response
  ) values (
    target, 'VALIDATE', request_id, declared_hash, database_hash,
    actor_player, actor_auth, response_value
  );
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok', false, 'code', 'PREDICTION_SETTINGS_DRAFT_NOT_FOUND'
  );
end;

$_$;


ALTER FUNCTION production_control.canonical_validate_prediction_settings_revision_resource_v2(input jsonb, resource_context jsonb) OWNER TO postgres;

--
-- Name: canonical_write_competition_derived_snapshot_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_write_competition_derived_snapshot_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target_tournament text := pg_catalog.btrim(coalesce(
    input->>'tournament_id', ''
  ));
  target_round integer := coalesce((input->>'round_number')::integer, 0);
  target_engine text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'engine_key', ''
  )));
  target_engine_version text := pg_catalog.btrim(coalesce(
    input->>'engine_version', ''
  ));
  target_configuration text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'configuration_fingerprint', ''
  )));
  target_source text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'source_fingerprint', ''
  )));
  target_payload_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'payload_hash', ''
  )));
  target_payload jsonb := coalesce(input->'result_payload', 'null'::jsonb);
  target_actor text := pg_catalog.btrim(coalesce(
    input->>'calculated_by', ''
  ));
  target_calculated_at timestamptz := coalesce(
    (input->>'calculated_at')::timestamptz, pg_catalog.now()
  );
  target_started_at timestamptz := coalesce(
    (input->>'started_at')::timestamptz, target_calculated_at
  );
  target_claim_started_at timestamptz :=
    (input->>'claim_started_at')::timestamptz;
  target_duration numeric := greatest(
    0, coalesce((input->>'duration_ms')::numeric, 0)
  );
  snapshot_id uuid;
  run_id uuid;
  logical_replay boolean := false;
  claimed_job scoring_authority.competition_recalculation_jobs%rowtype;
begin
  if canonical_context is not null then
    perform production_control.assert_canonical_scoring_context_v1(input,canonical_context,'RUNTIME');
    if canonical_context->>'phase' is distinct from 'WORKERS' then raise exception using errcode='42501',message='CERTIFICATION_DERIVED_CONTEXT_REQUIRED'; end if;
  end if;
  if (canonical_context is null and pg_catalog.upper(pg_catalog.btrim(coalesce(
       input->>'environment', ''
     ))) <> 'PREVIEW') then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREVIEW_ENVIRONMENT_REQUIRED'
    );
  end if;
  if target_tournament = '' or target_actor = ''
     or target_engine_version = ''
     or target_engine not in ('TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES')
     or target_configuration !~ '^[0-9a-f]{64}$'
     or target_source !~ '^[0-9a-f]{64}$'
     or target_payload_hash !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(target_payload) <> 'object'
     or target_claim_started_at is null then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_DERIVED_SNAPSHOT_REQUIRED'
    );
  end if;
  select value.* into claimed_job
  from scoring_authority.competition_recalculation_jobs value
  where value.tournament_id = target_tournament
    and value.round_number = target_round
    and value.engine_key = target_engine and value.status = 'RUNNING'
    and value.started_at = target_claim_started_at
  for update;
  if claimed_job.engine_key is null then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'STALE_DERIVED_JOB', 'superseded', true
    );
  end if;
  select value.id into snapshot_id
  from scoring_authority.competition_derived_snapshots value
  where value.tournament_id = target_tournament
    and value.round_number = target_round
    and value.engine_key = target_engine
    and value.engine_version = target_engine_version
    and value.configuration_fingerprint = target_configuration
    and value.source_fingerprint = target_source
    and value.payload_hash = target_payload_hash
  limit 1;
  logical_replay := snapshot_id is not null;
  update scoring_authority.competition_derived_snapshots value set
    is_current = false
  where value.tournament_id = target_tournament
    and value.round_number = target_round
    and value.engine_key = target_engine and value.is_current
    and value.id is distinct from snapshot_id;
  if snapshot_id is null then
    insert into scoring_authority.competition_derived_snapshots (
      tournament_id, round_number, engine_key, engine_version,
      configuration_fingerprint, source_fingerprint, result_state,
      result_payload, payload_hash, is_current, calculated_at
    ) values (
      target_tournament, target_round, target_engine,
      target_engine_version, target_configuration, target_source,
      'PROVISIONAL', target_payload, target_payload_hash, true,
      target_calculated_at
    ) returning id into snapshot_id;
  else
    update scoring_authority.competition_derived_snapshots value set
      is_current = true, result_payload = target_payload,
      calculated_at = target_calculated_at
    where value.id = snapshot_id;
  end if;
  insert into scoring_authority.competition_derived_runs (
    tournament_id, round_number, engine_key, engine_version,
    configuration_fingerprint, source_fingerprint, payload_hash, status,
    calculated_by, started_at, completed_at, duration_ms
  ) values (
    target_tournament, target_round, target_engine, target_engine_version,
    target_configuration, target_source, target_payload_hash, 'SUCCEEDED',
    target_actor, target_started_at, target_calculated_at, target_duration
  ) on conflict (
    tournament_id, round_number, engine_key, engine_version,
    configuration_fingerprint, source_fingerprint, payload_hash, status
  ) do update set
    completed_at = excluded.completed_at,
    duration_ms = excluded.duration_ms,
    calculated_by = excluded.calculated_by
  returning id into run_id;
  update scoring_authority.competition_recalculation_jobs value set
    status = 'SUCCEEDED', requested_source_revision =
      pg_catalog.jsonb_build_object(
        'sourceFingerprint', target_source,
        'configurationFingerprint', target_configuration,
        'payloadHash', target_payload_hash
      ),
    completed_at = pg_catalog.now(), last_error_code = null,
    last_error_safe = null, updated_at = pg_catalog.now()
  where value.tournament_id = target_tournament
    and value.round_number = target_round
    and value.engine_key = target_engine and value.status = 'RUNNING'
    and value.started_at = target_claim_started_at;
  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    target_tournament, target_engine || '_DERIVED_STATE_CALCULATED',
    target_actor, pg_catalog.jsonb_build_object(
      'snapshotId', snapshot_id, 'runId', run_id,
      'sourceFingerprint', target_source,
      'payloadHash', target_payload_hash,
      'engineVersion', target_engine_version,
      'logicalReplay', logical_replay,
      'claimStartedAt', target_claim_started_at
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'snapshot_id', snapshot_id,
    'run_id', run_id, 'logical_replay', logical_replay
  );
end;
$_$;


ALTER FUNCTION production_control.canonical_write_competition_derived_snapshot_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: canonical_write_intelligence_derived_bundle_core_v2(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.canonical_write_intelligence_derived_bundle_core_v2(input jsonb, canonical_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target_tournament text := pg_catalog.btrim(coalesce(
    input->>'tournament_id', ''
  ));
  target_source text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'source_fingerprint', ''
  )));
  target_actor text := pg_catalog.left(pg_catalog.btrim(coalesce(
    input->>'calculated_by', ''
  )), 180);
  target_duration numeric := greatest(
    0, coalesce((input->>'duration_ms')::numeric, 0)
  );
  engine jsonb;
  target_engine_key text;
  target_engine_version text;
  target_payload jsonb;
  target_payload_hash text;
  target_claim timestamptz;
  snapshot_id uuid;
  written jsonb := '[]'::jsonb;
begin
  if canonical_context is not null then
    perform production_control.assert_canonical_scoring_context_v1(input,canonical_context,'RUNTIME');
    if canonical_context->>'phase' is distinct from 'WORKERS' then raise exception using errcode='42501',message='CERTIFICATION_DERIVED_CONTEXT_REQUIRED'; end if;
  end if;
  if (canonical_context is null and pg_catalog.upper(pg_catalog.btrim(coalesce(
       input->>'environment', ''
     ))) <> 'PREVIEW')
     or target_tournament = '' or target_actor = ''
     or target_source !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(input->'engines') <> 'array' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_INTELLIGENCE_BUNDLE_REQUIRED'
    );
  end if;
  if not exists (
    select 1 from scoring_authority.tournaments value
    where value.tournament_id = target_tournament
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'TOURNAMENT_NOT_FOUND'
    );
  end if;
  for engine in
    select value from pg_catalog.jsonb_array_elements(input->'engines') value
  loop
    target_engine_key := pg_catalog.upper(pg_catalog.btrim(coalesce(
      engine->>'key', ''
    )));
    target_engine_version := pg_catalog.btrim(coalesce(
      engine->>'version', ''
    ));
    target_payload := coalesce(engine->'result', 'null'::jsonb);
    target_payload_hash := pg_catalog.lower(pg_catalog.btrim(coalesce(
      engine->>'payload_hash', ''
    )));
    begin
      target_claim := (engine->>'claim_started_at')::timestamptz;
    exception when others then
      target_claim := null;
    end;
    if target_engine_key not in (
      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
      'TOURNAMENT_FINAL_RECAP'
    ) or target_engine_version = ''
      or pg_catalog.jsonb_typeof(target_payload) <> 'object'
      or target_payload_hash !~ '^[0-9a-f]{64}$'
      or target_claim is null then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'INVALID_INTELLIGENCE_ENGINE_PAYLOAD'
      );
    end if;
    if target_engine_key = 'TOURNAMENT_FINAL_RECAP'
       and coalesce((input#>>'{final_gate,eligible}')::boolean, false)
         is not true then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'FINAL_RECAP_GATE_REQUIRED'
      );
    end if;
    if not production_control
      .frozen_2026_intelligence_claim_is_current_v1(
        target_tournament, target_engine_key, target_claim
      ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'STALE_INTELLIGENCE_WORKER',
        'superseded', true, 'engineKey', target_engine_key
      );
    end if;
    select value.id into snapshot_id
    from scoring_authority.competition_derived_snapshots value
    where value.tournament_id = target_tournament
      and value.round_number = 0
      and value.engine_key = target_engine_key
      and value.engine_version = target_engine_version
      and value.source_fingerprint = target_source
      and value.payload_hash = target_payload_hash
    limit 1;
    update scoring_authority.competition_derived_snapshots value set
      is_current = false
    where value.tournament_id = target_tournament
      and value.round_number = 0
      and value.engine_key = target_engine_key and value.is_current
      and value.id is distinct from snapshot_id;
    if snapshot_id is null then
      insert into scoring_authority.competition_derived_snapshots (
        tournament_id, round_number, engine_key, engine_version,
        configuration_fingerprint, source_fingerprint, result_state,
        result_payload, payload_hash, is_current, calculated_at
      ) values (
        target_tournament, 0, target_engine_key, target_engine_version,
        pg_catalog.encode(extensions.digest(
          target_engine_version || ':canonical-supabase-input-v1',
          'sha256'
        ), 'hex'), target_source,
        case when target_engine_key = 'TOURNAMENT_FINAL_RECAP'
          then 'OFFICIAL' else 'PROVISIONAL' end,
        target_payload, target_payload_hash, true, pg_catalog.now()
      ) returning id into snapshot_id;
    else
      update scoring_authority.competition_derived_snapshots value set
        is_current = true, calculated_at = pg_catalog.now()
      where value.id = snapshot_id;
    end if;
    insert into scoring_authority.competition_derived_runs (
      tournament_id, round_number, engine_key, engine_version,
      configuration_fingerprint, source_fingerprint, payload_hash,
      status, calculated_by, started_at, completed_at, duration_ms
    ) values (
      target_tournament, 0, target_engine_key, target_engine_version,
      pg_catalog.encode(extensions.digest(
        target_engine_version || ':canonical-supabase-input-v1',
        'sha256'
      ), 'hex'), target_source, target_payload_hash, 'SUCCEEDED',
      target_actor, target_claim, pg_catalog.now(), target_duration
    ) on conflict (
      tournament_id, round_number, engine_key, engine_version,
      configuration_fingerprint, source_fingerprint, payload_hash, status
    ) do update set
      completed_at = pg_catalog.now(), duration_ms = excluded.duration_ms;
    update scoring_authority.competition_recalculation_jobs value set
      status = 'SUCCEEDED', requested_source_revision =
        pg_catalog.jsonb_build_object(
          'sourceFingerprint', target_source,
          'payloadHash', target_payload_hash
        ),
      completed_at = pg_catalog.now(), updated_at = pg_catalog.now(),
      last_error_code = null, last_error_safe = null
    where value.tournament_id = target_tournament
      and value.round_number = 0 and value.engine_key = target_engine_key
      and value.status = 'RUNNING' and value.started_at = target_claim;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'code', 'STALE_INTELLIGENCE_WORKER',
        'superseded', true, 'engineKey', target_engine_key
      );
    end if;
    written := written || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'engineKey', target_engine_key, 'snapshotId', snapshot_id
      )
    );
  end loop;
  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    target_tournament, 'INTELLIGENCE_DERIVED_BUNDLE_CALCULATED',
    target_actor, pg_catalog.jsonb_build_object(
      'sourceFingerprint', target_source,
      'engines', written, 'finalGate', input->'final_gate'
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'written', written, 'final_gate', input->'final_gate'
  );
end;
$_$;


ALTER FUNCTION production_control.canonical_write_intelligence_derived_bundle_core_v2(input jsonb, canonical_context jsonb) OWNER TO postgres;

--
-- Name: capture_certification_initialization_origin_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.capture_certification_initialization_origin_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;
 o production_control.certification_initialization_origins_v1%rowtype;
 prior production_control.certification_ingress_generations_v1%rowtype;
begin
 select * into strict r from production_control.canonical_resource_v1 where singleton;
 if r.resource_class<>'CERTIFICATION' or r.database_name<>current_database() or new.resource_id<>r.resource_id then
  raise exception using errcode='55000',message='CERTIFICATION_INITIALIZATION_RESOURCE_MISMATCH';end if;
 select * into o from production_control.certification_initialization_origins_v1 where resource_id=new.resource_id;
 if not found then
  perform production_control.record_certification_initialization_origin_v1(new.generation_id);
  return new;
 end if;
 -- Every later generation follows the actual closed predecessor in the same
 -- physical installation; existence of an origin alone grants no new lineage.
 select * into strict prior from production_control.certification_ingress_generations_v1
  where generation_id=new.predecessor_generation_id and resource_id=new.resource_id;
 if o.installation_id<>r.installation_id or o.database_name<>r.database_name
  or o.project_ref<>r.project_ref or o.project_url<>r.project_url
  or prior.state<>'CLOSED' or new.state<>'OPEN'
  or new.pointer_revision not in(prior.pointer_revision,prior.pointer_revision+1) then
  raise exception using errcode='55000',message='CERTIFICATION_INITIALIZATION_LINEAGE_MISMATCH';end if;
 return new;
exception when no_data_found then raise exception using errcode='55000',message='CERTIFICATION_INITIALIZATION_LINEAGE_REQUIRED';
end;$$;


ALTER FUNCTION production_control.capture_certification_initialization_origin_v1() OWNER TO postgres;

--
-- Name: capture_derived_delivery_provenance_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.capture_derived_delivery_provenance_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare context jsonb;
begin
 if (select resource_class from production_control.canonical_resource_v1 where singleton)='CERTIFICATION' then
  context:=production_control.current_certification_context_v1();
  if new.tournament_id is distinct from context->>'tournament_id' then
   raise exception using errcode='42501',message='CERTIFICATION_DELIVERY_TARGET_MISMATCH'; end if;
  new.handling_activation_revision:=(context->>'activation_revision')::bigint;
  new.handling_release_commit:=context->>'release_commit';
  insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
  values('CERTIFICATION_DERIVED_DELIVERY','DERIVED_DELIVERY',new.tournament_id,
   coalesce(context->>'actor_player_id','certification-derived-worker'),context->>'context_token','RECORDED',
   jsonb_build_object('runtime','CERTIFICATION','resource_id',context->>'resource_id','installation_id',context->>'installation_id',
    'binding_id',context->>'binding_id','operation_request_id',context->>'operation_request_id',
    'delivery_event_id',new.event_id,'family',new.family,'work_identity',new.work_identity,
    'originating_activation_revision',new.originating_activation_revision,
    'handling_activation_revision',new.handling_activation_revision,'handling_release_commit',new.handling_release_commit));
  return new;
 end if;
 select activation_revision,expected_deployment_commit into new.handling_activation_revision,new.handling_release_commit
 from production_control.cutover_activation_state where scope_key='BAGGER_INV_PRODUCTION';
 return new;
end;
$$;


ALTER FUNCTION production_control.capture_derived_delivery_provenance_v1() OWNER TO postgres;

--
-- Name: capture_derived_delivery_transition_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.capture_derived_delivery_transition_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare row_value jsonb; old_value jsonb; family_value text; identity_value text;
  transition_value text; retryable boolean; code_value text;
begin
  row_value:=to_jsonb(new); old_value:=case when tg_op='UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  family_value:=case tg_table_name when 'calcutta_v1_recalculation_jobs' then 'CALCUTTA'
    when 'net_skins_v1_recalculation_jobs' then 'NET_SKINS'
    else case when row_value->>'engine_key' in('TEAM_MOMENTUM','TOURNAMENT_STORYLINES') then 'COMPETITION' else 'INTELLIGENCE' end end;
  identity_value:=coalesce(row_value->>'job_id',concat(new.tournament_id,':',row_value->>'round_number',':',row_value->>'engine_key'));
  if tg_op='UPDATE' and tg_table_name='competition_recalculation_jobs'
      and old.status='RUNNING' and new.status='SUCCEEDED' then
    -- Snapshots/runs own output fingerprints. All competition-family markers
    -- retain their canonical demand identity; success is not a new demand.
    new.requested_source_revision:=old.requested_source_revision;
  end if;
  if tg_table_name='competition_recalculation_jobs' then
  if tg_op='UPDATE' and tg_table_name='competition_recalculation_jobs'
      and old.status='SUCCEEDED' and old.requested_source_revision ? 'sourceFingerprint'
      and new.status='PENDING' and new.delivery_cycle=old.delivery_cycle
      and new.requested_source_revision#>>'{revision,matchId}' is not null then
    -- Legacy successful Competition markers lost their demand identity.
    -- The legacy notification defers to the canonical trigger, which carries
    -- OLD/NEW source facts. Never invent a budget from missing provenance.
    if new.requested_source_revision->>'reason' in('MATCH_CHANGE','OFFICIAL_RESULT_CHANGE') then return old;end if;
    if jsonb_typeof(new.requested_source_revision->'priorRevision') is distinct from 'object'
      or new.requested_source_revision#>>'{priorRevision,matchId}' is distinct from new.requested_source_revision#>>'{revision,matchId}' then
      raise exception using errcode='55000',message='DERIVED_DELIVERY_SOURCE_IDENTITY_REQUIRED';
    end if;
    if new.requested_source_revision->'priorRevision'=new.requested_source_revision->'revision' then return old;end if;
  end if;
  if tg_op='UPDATE' and tg_table_name='competition_recalculation_jobs'
      and new.status='PENDING' and new.last_error_code is null
      and new.delivery_cycle=old.delivery_cycle
      and new.runtime_generation_id is not distinct from old.runtime_generation_id
      and (new.requested_source_revision-array['reason','transactional','derivedIntentId','priorRevision'])
        is not distinct from (old.requested_source_revision-array['reason','transactional','derivedIntentId','priorRevision']) then
    -- Ordinary duplicate demand is not recovery, claim expiry or a new source.
    -- Preserve success, active ownership, backoff and terminal evidence exactly.
    -- Authorized recovery explicitly advances delivery_cycle and is unaffected.
    if old.status='PENDING' and old.delivery_attempts>=5 then
      raise exception using errcode='55000',message='DERIVED_DELIVERY_RECOVERY_REQUIRED';
    end if;
    if old.status in('PENDING','RUNNING','SUCCEEDED','FAILED') then return old;end if;
  end if;
  end if;
  if tg_op='UPDATE' and new.status='PENDING' and tg_table_name='competition_recalculation_jobs'
      and ((row_value->'requested_source_revision')-array['reason','transactional','derivedIntentId','priorRevision']) is distinct from ((old_value->'requested_source_revision')-array['reason','transactional','derivedIntentId','priorRevision']) then
    if old.status='RUNNING' then
      insert into production_control.score_derived_delivery_attempts_v1
        (tournament_id,family,work_identity,cycle,attempt,transition,safe_code,worker_id,runtime_generation_id,originating_activation_revision)
      values(old.tournament_id,family_value,identity_value,old.delivery_cycle,old.delivery_attempts,
        'SUPERSEDED','CANONICAL_SOURCE_ADVANCED',left(old.claimed_by,160),old.runtime_generation_id,
        nullif(old_value->>'activation_revision','')::bigint);
    end if;
    new.delivery_cycle:=old.delivery_cycle+1; new.delivery_attempts:=0; new.attempts:=0;
    new.delivery_dead_letter_at:=null; new.delivery_error_class:=null;
    new.delivery_available_at:=clock_timestamp();
  end if;
  if tg_op='UPDATE' and tg_table_name='competition_recalculation_jobs'
      and row_value->>'engine_key' in('TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL','TOURNAMENT_FINAL_RECAP')
      and old.status='SUCCEEDED' and new.status='RUNNING' then
    -- The bundle claim already proved distinct pending demand. Rejoining a
    -- successful sibling is a new bounded attempt cycle, never failed-work reset.
    new.delivery_cycle:=old.delivery_cycle+1; new.delivery_attempts:=0;
    new.delivery_available_at:=clock_timestamp();
    code_value:='SUCCESSFUL_SIBLING_REJOINED_BUNDLE';
  end if;
  if new.status='RUNNING' and (tg_op='INSERT' or old_value->>'status'<>'RUNNING'
      or row_value->>'started_at' is distinct from old_value->>'started_at') then
    if new.delivery_dead_letter_at is not null or new.delivery_attempts>=5
       or new.delivery_available_at>clock_timestamp() then
      raise exception using errcode='55P03',message='DERIVED_DELIVERY_NOT_DUE';
    end if;
    new.delivery_attempts:=new.delivery_attempts+1;
    transition_value:='RUNNING';
  elsif tg_op='UPDATE' and old.status='RUNNING' and new.status in('FAILED','PENDING')
      and new.delivery_cycle=old.delivery_cycle then
    code_value:=coalesce(nullif(new.last_error_code,''),'DERIVED_LEASE_EXPIRED');
    retryable:=production_control.derived_delivery_retryable_v1(code_value);
    new.delivery_error_class:=case when retryable then 'RETRYABLE' else 'TERMINAL' end;
    if retryable and new.delivery_attempts<5 then
      new.status:='PENDING'; new.completed_at:=null;
      new.delivery_available_at:=clock_timestamp()+production_control.derived_delivery_delay_v1(new.delivery_attempts,identity_value);
      new.delivery_dead_letter_at:=null; transition_value:='RETRYABLE';
    else
      new.status:='FAILED'; new.completed_at:=clock_timestamp();
      new.delivery_dead_letter_at:=clock_timestamp(); transition_value:='DEAD_LETTER';
    end if;
    new.claim_token:=null; new.claimed_by:=null; new.lease_expires_at:=null;
  elsif tg_op='UPDATE' and new.status in('SUCCEEDED','SUPERSEDED') and old.status is distinct from new.status then
    transition_value:=new.status;
    new.delivery_dead_letter_at:=null; new.delivery_error_class:=null;
  end if;
  if tg_table_name='competition_recalculation_jobs' and new.status='PENDING'
      and (new.delivery_attempts>=5 or new.delivery_dead_letter_at is not null) then
    raise exception using errcode='55000',message='DERIVED_DELIVERY_RECOVERY_REQUIRED';
  end if;
  if transition_value is not null then
    insert into production_control.score_derived_delivery_attempts_v1
      (tournament_id,family,work_identity,cycle,attempt,transition,safe_code,worker_id,runtime_generation_id,originating_activation_revision)
    values(new.tournament_id,family_value,identity_value,new.delivery_cycle,new.delivery_attempts,
      transition_value,left(code_value,120),left(coalesce(row_value->>'claimed_by',old_value->>'claimed_by'),160),
      nullif(row_value->>'runtime_generation_id','')::uuid,nullif(row_value->>'activation_revision','')::bigint);
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.capture_derived_delivery_transition_v1() OWNER TO postgres;

--
-- Name: capture_derived_intent_attempt_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.capture_derived_intent_attempt_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 insert into production_control.score_derived_delivery_attempts_v1
  (tournament_id,family,work_identity,cycle,attempt,transition,safe_code,worker_id,runtime_generation_id)
 values(new.tournament_id,'INTENT',new.intent_id::text,new.delivery_cycle,new.attempts,
  case new.status when 'SUCCEEDED' then 'SUCCEEDED' when 'DEAD_LETTER' then 'DEAD_LETTER' else 'RETRYABLE' end,
  new.last_sqlstate,'score-derived-intent-worker-v1',new.runtime_generation_id);
 return new;
end;
$$;


ALTER FUNCTION production_control.capture_derived_intent_attempt_v1() OWNER TO postgres;

--
-- Name: capture_first_production_canonical_write(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.capture_first_production_canonical_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  target_tournament text;
  activation production_control.cutover_activation_state%rowtype;
  resource_context jsonb;
  ingress jsonb;
  required_receipt_type text;
begin
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION') then
    resource_context:=production_control.current_canonical_resource_context_v1();
    -- Actual same-transaction executable lease, not a stored terminal lease ID
    -- or a caller-controlled resource/context flag.
    ingress:=production_control.require_certification_ingress_execution_v1();
    select tournament_id into strict target_tournament
    from scoring_authority.matches where match_id=new.match_id;
    required_receipt_type:=case ingress->>'operation_id'
      when 'SCORING.SUBMIT_HOLE' then 'HOLE_SCORE'
      when 'SCORING.FINALIZE_MATCH' then 'FINALIZE'
      when 'SCORING.REOPEN_MATCH' then 'REOPEN'
      when 'DIRECTOR.MATCH_CONTROL' then case ingress->>'domain_action'
        when 'mark-live' then 'MARK_LIVE'
        when 'scoring-lock' then 'SCORING_LOCK'
        when 'scoring-unlock' then 'SCORING_UNLOCK'
        when 'access-activate' then 'ACCESS_ACTIVATE'
        when 'access-revoke' then 'ACCESS_REVOKE'
      end
    end;
    if ingress->>'resource_id' is distinct from resource_context->>'resource_id'
      or ingress->>'authority_epoch_id' is distinct from resource_context->>'authority_epoch_id'
      or ingress->>'tournament_id' is distinct from target_tournament
      or ingress->>'match_id' is distinct from new.match_id
      or ingress->>'operation_request_id' is distinct from new.mutation_key
      or ingress->>'actor_player_id' is distinct from new.actor_id
      or required_receipt_type is null
      or new.mutation_type is distinct from required_receipt_type
      or new.result->>'ok' is distinct from 'true' then
      raise exception using errcode='42501',message='CERTIFICATION_RECEIPT_INGRESS_MISMATCH';
    end if;
    -- Receipt plus domain audit and gateway outcome remain atomic. Certification
    -- never updates or invents the Production first-write rollback latch.
    return new;
  end if;
  select tournament_id into target_tournament
  from scoring_authority.matches
  where match_id = new.match_id;
  if target_tournament <> '2026' then return new; end if;

  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';
  if activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or not activation.scoring_ingress_enabled
     or not exists (
       select 1 from scoring_authority.ingress_gates gate
       where gate.tournament_id = '2026'
         and gate.state = 'OPEN'
         and gate.authority = 'SUPABASE'
         and gate.active_epoch_id = activation.authority_generation_id
     ) then
    return new;
  end if;

  update production_control.cutover_activation_state
  set first_supabase_write_observed_at = now(),
      first_supabase_mutation_key = new.mutation_key,
      first_supabase_match_id = new.match_id,
      first_supabase_match_revision = new.next_match_revision,
      updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
    and first_supabase_write_observed_at is null;
  if found then
    insert into production_control.operation_audit_events (
      event_type, domain, tournament_id, actor, request_fingerprint, result, details
    ) values (
      'FIRST_SUPABASE_CANONICAL_WRITE_OBSERVED', 'SCORING_AUTHORITY', '2026',
      left(new.actor_id, 160), null, 'SUCCEEDED',
      jsonb_build_object(
        'epoch_id', activation.authority_generation_id,
        'mutation_key', new.mutation_key,
        'match_id', new.match_id,
        'match_revision', new.next_match_revision
      )
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.capture_first_production_canonical_write() OWNER TO postgres;

--
-- Name: capture_isolated_auction_supersession_provenance_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.capture_isolated_auction_supersession_provenance_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare marker production_control.isolated_financial_audit_context_v1%rowtype;
begin
 select * into marker from production_control.isolated_financial_audit_context_v1
 where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id()
   and tournament_id=new.tournament_id and action in('replace-auction','clear-entry');
 if not found then return new; end if;
 new.handling_activation_revision:=(marker.context->>'activation_revision')::bigint;
 new.handling_release_commit:=marker.context->>'release_commit';
 new.safe_code:=case when marker.context->>'resource_class'='CERTIFICATION' then 'CERTIFICATION_DIRECTOR_AUCTION_SUPERSEDED' else 'ISOLATED_DIRECTOR_AUCTION_SUPERSEDED' end;
 insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
 values(case when marker.context->>'resource_class'='CERTIFICATION' then 'CERTIFICATION_DIRECTOR_DERIVED_SUPERSEDED' else 'ISOLATED_DIRECTOR_DERIVED_SUPERSEDED' end,'CALCUTTA',new.tournament_id,
   marker.context->>'actor_player_id',marker.request_fingerprint,'SUCCEEDED',jsonb_build_object(
     'runtime',coalesce(marker.context->>'resource_class','ISOLATED'),'resource_id',marker.context->>'resource_id','installation_id',marker.context->>'installation_id','context_binding_id',marker.context->>'binding_id',
     'context_token',marker.context->>'context_token','operation_request_id',marker.operation_request_id,
     'action',marker.action,'actor_auth_user_id',marker.context->>'actor_auth_user_id',
     'delivery_event_id',new.event_id,'work_identity',new.work_identity,
     'originating_activation_revision',new.originating_activation_revision,
     'handling_activation_revision',new.handling_activation_revision,'handling_release_commit',new.handling_release_commit));
 return new;
end;
$$;


ALTER FUNCTION production_control.capture_isolated_auction_supersession_provenance_v1() OWNER TO postgres;

--
-- Name: carry_forward_exact_calcutta_job_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.carry_forward_exact_calcutta_job_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    SET "TimeZone" TO 'UTC'
    AS $_$
declare
  a production_control.cutover_activation_state%rowtype;
  h production_control.postcutover_normal_release_head%rowtype;
  c scoring_authority.calcutta_v1_current%rowtype;
  j scoring_authority.calcutta_v1_recalculation_jobs%rowtype;
  auction scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  publication scoring_authority.calcutta_v1_publication_revisions%rowtype;
  prior production_control.calcutta_exact_job_recoveries_v1%rowtype;
  pre_hash text; post_hash text; response_value jsonb;
  recovery uuid := extensions.gen_random_uuid();
begin
  perform production_control.assert_production_service_role();
  if input->>'job_id' is distinct from '83ed6e87-1a2c-4100-a8d6-9480621c7e8e'
     or input->>'expected_tournament_id' is distinct from '2026'
     or input->>'contract_version' is distinct from 'production-calcutta-v1'
     or input->>'reason_code' is distinct from 'STRANDED_PENDING_JOB_AFTER_PROTECTED_RELEASE'
     or coalesce(input->>'expected_job_hash','') !~ '^[a-f0-9]{64}$'
     or coalesce(input->>'release_plan_hash','') !~ '^[a-f0-9]{64}$'
     or coalesce(input->>'request_fingerprint','') !~ '^[a-f0-9]{64}$' then
    raise exception 'PRODUCTION_CALCUTTA_RECOVERY_SCOPE_DENIED';
  end if;
  -- Same admission/release lock, followed by canonical activation/current/job locks.
  -- Table locks also serialize otherwise independent claim/result/job insertion paths.
  perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
  select * into strict a from production_control.cutover_activation_state
    where scope_key='BAGGER_INV_PRODUCTION' for update;
  select * into strict h from production_control.postcutover_normal_release_head
    where scope_key='BAGGER_INV_PRODUCTION' for update;
  perform plan_hash from production_control.release_attempts_v1
    where plan_hash=input->>'release_plan_hash' and state='ACTIVE' for share;
  if not found then raise exception 'PRODUCTION_CALCUTTA_RECOVERY_RELEASE_DENIED'; end if;
  perform production_control.assert_production_calcutta_v1_runtime(input);
  perform production_control.assert_production_scoring_actor(input,true);
  if (select tournament_id from production_control.current_tournament_pointer_v1
      where scope_key='BAGGER_INV_PRODUCTION') is distinct from '2026'
     or h.activation_revision is distinct from a.activation_revision
     or h.deployment_commit is distinct from a.expected_deployment_commit
     or not exists(select 1 from production_control.release_attempts_v1
       where plan_hash=input->>'release_plan_hash' and state='ACTIVE')
     or not exists(select 1 from production_control.postcutover_normal_release_rebindings
       where release_rebind_id=h.release_rebind_id
       and activation_revision_before=(input->>'expected_prior_activation_revision')::bigint
       and activation_revision_after=a.activation_revision)
     or a.activation_revision <= (input->>'expected_prior_activation_revision')::bigint then
    raise exception 'PRODUCTION_CALCUTTA_RECOVERY_RELEASE_DENIED';
  end if;
  select * into strict c from scoring_authority.calcutta_v1_current
    where tournament_id='2026' for update;
  lock table scoring_authority.calcutta_v1_recalculation_jobs in share row exclusive mode;
  lock table scoring_authority.calcutta_v1_auction_fact_revisions,
    scoring_authority.calcutta_v1_publication_revisions,
    scoring_authority.calcutta_v1_result_revisions in share mode;
  select * into strict j from scoring_authority.calcutta_v1_recalculation_jobs
    where job_id=(input->>'job_id')::uuid for update;
  select * into strict auction from scoring_authority.calcutta_v1_auction_fact_revisions
    where auction_revision_id=c.auction_revision_id;
  select * into strict publication from scoring_authority.calcutta_v1_publication_revisions
    where publication_revision_id=c.publication_revision_id;
  if c.configuration_revision<>2 or c.auction_revision<>37 or c.publication_revision<>41
     or c.configuration_revision is distinct from (input->>'expected_configuration_revision')::bigint
     or c.configuration_fingerprint is distinct from input->>'expected_configuration_fingerprint'
     or c.auction_revision is distinct from (input->>'expected_auction_revision')::bigint
     or c.auction_fingerprint is distinct from input->>'expected_auction_fingerprint'
     or c.publication_revision is distinct from (input->>'expected_publication_revision')::bigint
     or c.state<>'AUCTION_COMPLETE' or c.publication_state<>'PUBLISHED'
     or publication.publication_state<>'PUBLISHED' or publication.auction_revision<>c.auction_revision
     or publication.auction_fingerprint<>c.auction_fingerprint
     or c.result_revision<>0
     or exists(select 1 from scoring_authority.calcutta_v1_result_revisions where tournament_id='2026')
     or exists(select 1 from scoring_authority.calcutta_v1_auction_fact_revisions where tournament_id='2026' and auction_revision>c.auction_revision)
     or exists(select 1 from scoring_authority.calcutta_v1_publication_revisions where tournament_id='2026' and publication_revision>c.publication_revision)
     or auction.auction_fingerprint<>c.auction_fingerprint
     or production_control.calcutta_v1_hash(auction.auction_manifest)<>c.auction_fingerprint
     or jsonb_array_length(auction.auction_manifest->'purchases')<>24
     or (select count(distinct p->>'player_id') from jsonb_array_elements(auction.auction_manifest->'purchases')p)<>24
     or (select sum((p->>'purchase_price')::numeric) from jsonb_array_elements(auction.auction_manifest->'purchases')p)<>18500
     or (select count(*) from (select o->>'player_id' from jsonb_array_elements(auction.auction_manifest->'ownership')o group by o->>'player_id' having sum((o->>'ownership_fraction')::numeric)=1) s)<>24 then
    raise exception 'PRODUCTION_CALCUTTA_RECOVERY_CANONICAL_STATE_CHANGED';
  end if;
  if j.tournament_id<>'2026' or j.status<>'PENDING' or j.attempts<>0
     or j.started_at is not null or j.completed_at is not null
     or j.claimed_by is not null or j.claim_token is not null or j.lease_expires_at is not null
     or j.last_error_code is not null or j.last_error_safe is not null
     or j.configuration_revision_id<>c.configuration_revision_id
     or j.configuration_fingerprint<>c.configuration_fingerprint
     or j.auction_revision_id<>c.auction_revision_id or j.auction_revision<>c.auction_revision
     or j.auction_fingerprint<>c.auction_fingerprint
     or j.source_fingerprint<>production_control.calcutta_v1_hash(production_control.calcutta_v1_source_revision('2026'))
     or exists(select 1 from scoring_authority.calcutta_v1_recalculation_jobs other
       where other.tournament_id='2026' and other.job_id<>j.job_id
       and (other.status in ('PENDING','RUNNING','SUCCEEDED') or other.requested_at>j.requested_at)) then
    raise exception 'PRODUCTION_CALCUTTA_RECOVERY_JOB_INELIGIBLE';
  end if;
  select * into prior from production_control.calcutta_exact_job_recoveries_v1 where job_id=j.job_id;
  if found then
    if prior.prior_activation is distinct from (input->>'expected_prior_activation_revision')::bigint
       or prior.new_activation<>a.activation_revision or j.activation_revision<>a.activation_revision
       or prior.pre_state_hash is distinct from input->>'expected_job_hash'
       or prior.post_state_hash<>production_control.calcutta_v1_hash(to_jsonb(j))
       or prior.release_plan_hash is distinct from input->>'release_plan_hash' then
      raise exception 'PRODUCTION_CALCUTTA_RECOVERY_RECEIPT_CONFLICT';
    end if;
    return prior.response||jsonb_build_object('idempotent',true);
  end if;
  pre_hash:=production_control.calcutta_v1_hash(to_jsonb(j));
  if j.activation_revision is distinct from (input->>'expected_prior_activation_revision')::bigint
     or pre_hash is distinct from input->>'expected_job_hash' then
    raise exception 'PRODUCTION_CALCUTTA_RECOVERY_PRESTATE_CHANGED';
  end if;
  update scoring_authority.calcutta_v1_recalculation_jobs
    set activation_revision=a.activation_revision where job_id=j.job_id returning * into j;
  post_hash:=production_control.calcutta_v1_hash(to_jsonb(j));
  response_value:=jsonb_build_object('ok',true,'code','PRODUCTION_CALCUTTA_EXACT_JOB_CARRIED',
    'recovery_id',recovery,'job_id',j.job_id,'prior_activation',input->'expected_prior_activation_revision',
    'new_activation',a.activation_revision,'auction_revision',c.auction_revision,
    'publication_revision',c.publication_revision,'pre_state_hash',pre_hash,'post_state_hash',post_hash,
    'status',j.status,'attempts',j.attempts,'idempotent',false);
  insert into production_control.calcutta_exact_job_recoveries_v1
    (recovery_id,job_id,prior_activation,new_activation,auction_revision,publication_revision,
     pre_state_hash,post_state_hash,director_player_id,director_auth_user_id,release_plan_hash,reason_code,response)
    values(recovery,j.job_id,(input->>'expected_prior_activation_revision')::bigint,a.activation_revision,
     c.auction_revision,c.publication_revision,pre_hash,post_hash,input#>>'{authorization,player_id}',
     (input#>>'{authorization,auth_user_id}')::uuid,input->>'release_plan_hash',input->>'reason_code',response_value);
  insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
    values('PRODUCTION_CALCUTTA_EXACT_JOB_CARRIED','CALCUTTA','2026',input#>>'{authorization,player_id}',
      input->>'request_fingerprint','SUCCEEDED',response_value);
  return response_value;
end $_$;


ALTER FUNCTION production_control.carry_forward_exact_calcutta_job_v1(input jsonb) OWNER TO postgres;

--
-- Name: certification_annual_predecessor_certificate_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_annual_predecessor_certificate_v1(target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c jsonb:=production_control.annual_resource_context_v2();e jsonb;blocks jsonb:='[]';fp text;
 o production_control.certification_initialization_origins_v1%rowtype;
 closed production_control.scoring_admission_closures%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;
 a production_control.annual_scoring_runtime_authorities_v1%rowtype;
begin
 if c->>'resource_class' is distinct from 'CERTIFICATION' or c->>'phase' is distinct from 'ANNUAL'
  or c->>'current_tournament_id' is distinct from target_tournament then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CONTEXT_REQUIRED';end if;
 select * into strict o from production_control.certification_initialization_origins_v1 where resource_id=c->>'resource_id';
 select * into closed from production_control.scoring_admission_closures
 where certification_resource_id=o.resource_id and tournament_id=target_tournament and status in('CLOSING','CLOSED')
 order by closing_at desc,closure_id limit 1;
 if closed.closure_id is null then
  return jsonb_build_object('certified',false,'tournamentId',target_tournament,'fingerprint',null,
   'blockers',jsonb_build_array('PREDECESSOR_SCORING_ADMISSION_NOT_CLOSED'));end if;
 select * into strict g from production_control.certification_ingress_generations_v1
 where resource_id=o.resource_id and generation_id=closed.admission_generation_id;
 e:=production_control.certification_ingress_evidence_v1(o.resource_id,g.generation_id);
 if target_tournament<>o.initial_tournament_id then
  select * into strict a from production_control.annual_scoring_runtime_authorities_v1 where tournament_id=target_tournament;
  if a.resource_class<>'CERTIFICATION' or a.certification_resource_id<>o.resource_id or a.authority_status<>'CLOSED'
   or a.admission_state<>'CLOSED' or a.active_closure_id is distinct from closed.closure_id
   or a.admission_generation_id<>g.generation_id or a.authority_generation_id<>g.authority_epoch_id then
   blocks:=blocks||jsonb_build_array('PREDECESSOR_SCORING_ADMISSION_NOT_CLOSED');end if;
  declare ancestor production_control.scoring_admission_closures%rowtype;
   parent_generation production_control.certification_ingress_generations_v1%rowtype;
   child_generation production_control.certification_ingress_generations_v1%rowtype;
   cursor_id uuid;seen uuid[]:=array[]::uuid[];lineage_valid boolean:=false;
  begin
   child_generation:=g;
   cursor_id:=closed.prior_certification_closure_id;
   loop
    if cursor_id is null or cursor_id=any(seen)then exit;end if;
    seen:=array_append(seen,cursor_id);
    select * into ancestor from production_control.scoring_admission_closures where closure_id=cursor_id;
    if ancestor.closure_id is null or ancestor.resource_class is distinct from'CERTIFICATION'
     or ancestor.certification_resource_id is distinct from o.resource_id
     or ancestor.boundary_mode is distinct from'CERTIFICATION_INGRESS_V1'
     or ancestor.closure_kind is distinct from'SUPABASE_INGRESS'
     or ancestor.authority is distinct from'SUPABASE' then exit;end if;
    select * into parent_generation from production_control.certification_ingress_generations_v1
     where resource_id=o.resource_id and generation_id=ancestor.admission_generation_id;
    if parent_generation.generation_id is null or parent_generation.state is distinct from'CLOSED'
     or child_generation.predecessor_generation_id is distinct from parent_generation.generation_id
     or ancestor.tournament_id is distinct from parent_generation.tournament_id
     or ancestor.authority_generation_id is distinct from parent_generation.authority_epoch_id
     or ancestor.closed_admission_revision is distinct from parent_generation.revision
     or ancestor.lease_high_watermark is distinct from parent_generation.high_watermark
     or ancestor.lease_set_fingerprint is distinct from parent_generation.lease_fingerprint then exit;end if;
    if ancestor.closure_id=a.predecessor_closure_id then
     -- Existing Certification ACTIVATE retains CLOSED. Its exact COMMITTED
     -- annual transition proves consumption; do not invent a status rewrite.
     lineage_valid:=ancestor.status in('CLOSED','CONSUMED')
      and ancestor.tournament_id=a.predecessor_tournament_id and ancestor.tournament_id<>target_tournament
      and parent_generation.pointer_revision=g.pointer_revision-1
      and exists(select 1 from production_control.annual_scoring_transitions_v1 t
       where t.resource_class='CERTIFICATION' and t.certification_resource_id=o.resource_id
        and t.runtime_generation_id=a.runtime_generation_id and t.transition_status='COMMITTED'
        and t.predecessor_closure_id=a.predecessor_closure_id
        and t.predecessor_tournament_id=a.predecessor_tournament_id
        and t.predecessor_boundary_fingerprint=a.predecessor_boundary_fingerprint
        and t.successor_tournament_id=target_tournament
        and t.expected_pointer_revision=g.pointer_revision-1
        and t.authority_generation_id=g.authority_epoch_id);
     exit;
    end if;
    if ancestor.status is distinct from'REOPENED' or ancestor.tournament_id is distinct from target_tournament
     or parent_generation.authority_epoch_id is distinct from g.authority_epoch_id
     or parent_generation.pointer_revision is distinct from g.pointer_revision then exit;end if;
    child_generation:=parent_generation;
    cursor_id:=ancestor.prior_certification_closure_id;
   end loop;
   if not coalesce(lineage_valid,false)then blocks:=blocks||jsonb_build_array('PREDECESSOR_SCORING_ADMISSION_NOT_CLOSED'); end if;
  end;

 end if;
 if closed.resource_class<>'CERTIFICATION' or closed.status<>'CLOSED' or g.state<>'CLOSED'
  or exists(select 1 from production_control.certification_ingress_generations_v1 child
   where child.resource_id=g.resource_id and child.predecessor_generation_id=g.generation_id)
  or closed.authority<>'SUPABASE' or closed.closure_kind<>'SUPABASE_INGRESS'
  or g.tournament_id<>target_tournament or g.pointer_revision::text is distinct from c->>'pointer_revision'
  or closed.authority_generation_id<>g.authority_epoch_id or closed.lease_high_watermark is distinct from g.high_watermark
  or closed.lease_set_fingerprint is distinct from e->>'fingerprint'
  or closed.closed_admission_revision is distinct from g.revision
  or not exists(select 1 from scoring_authority.ingress_gates where tournament_id=target_tournament and state='PAUSED'
   and authority='SUPABASE' and active_epoch_id=g.authority_epoch_id)then
  blocks:=blocks||jsonb_build_array('PREDECESSOR_SCORING_ADMISSION_NOT_CLOSED');end if;
 if not(e->>'drained')::boolean or not(e->>'fingerprint_matches')::boolean then
  blocks:=blocks||jsonb_build_array('PREDECESSOR_SCORING_DRAIN_INCOMPLETE');end if;
 if not exists(select 1 from scoring_authority.matches where tournament_id=target_tournament)
  or exists(select 1 from scoring_authority.matches where tournament_id=target_tournament
   and(status<>'FINAL' or not scorecard_complete or unresolved_mutations<>0))
  or closed.supabase_match_revisions is distinct from production_control.current_match_revisions(target_tournament)then
  blocks:=blocks||jsonb_build_array('PREDECESSOR_FINAL_SCORING_FACTS_REQUIRED');end if;
 fp:=production_control.future_runtime_hash_v2(jsonb_build_object('contractVersion','certification-annual-close-v1',
  'resource_id',o.resource_id,'origin',o.initialization_fingerprint,'closure_id',closed.closure_id,
  'prior_closure_id',closed.prior_certification_closure_id,'authority_epoch_id',g.authority_epoch_id,
  'generation_id',g.generation_id,'closed_revision',closed.closed_admission_revision,'watermark',g.high_watermark,
  'lease_fingerprint',e->>'fingerprint','match_revisions',closed.supabase_match_revisions));
 return jsonb_build_object('certified',jsonb_array_length(blocks)=0,'tournamentId',target_tournament,
  'closureId',closed.closure_id,'certificationOriginResourceId',o.resource_id,
  'authorityGenerationId',g.authority_epoch_id,'admissionGenerationId',g.generation_id,'fingerprint',fp,
  'postCloseLeaseCount',e->'post_close_admissions','certificationIngress',e,'blockers',blocks);
exception when no_data_found then return jsonb_build_object('certified',false,'tournamentId',target_tournament,'fingerprint',null,
 'blockers',jsonb_build_array('PREDECESSOR_SCORING_CLOSE_CERTIFICATE_UNAVAILABLE'));
end;$$;


ALTER FUNCTION production_control.certification_annual_predecessor_certificate_v1(target_tournament text) OWNER TO postgres;

--
-- Name: certification_annual_transition_command_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_annual_transition_command_v1(input jsonb, ctx jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare payload jsonb:=input->'payload';r production_control.canonical_resource_v1%rowtype;command jsonb;
begin
 if ctx is distinct from production_control.current_certification_context_v1()
  or ctx->>'phase' is distinct from 'ANNUAL' or jsonb_typeof(payload) is distinct from 'object' then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CONTEXT_REQUIRED';end if;
 if payload ?| array['authorization','environment','contract_version','resource','deployment','actor_player_id','actor_auth_user_id',
  'project_ref','project_url','source_workbook_id','tournament_id','tournament_year','operation_request_id','operation_id',
  'resource_id','resource_class','installation_id','governance_tournament_id','expected_context_token','request_payload_hash']then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_AUTHORITY_FIELD_REJECTED';end if;
 perform production_control.assert_canonical_annual_actor_v2(input,ctx,true);
 select * into strict r from production_control.canonical_resource_v1 where resource_id=ctx->>'resource_id';
 -- Stable logical predecessor is an expected CAS value, not execution authority.
 -- Current authority was independently validated above. This permits exact
 -- receipt replay after successful activation without silently rebinding it.
 if coalesce(payload->>'expected_current_tournament_id','')!~'^20[0-9]{2}$'then
  raise exception using errcode='22023',message='CERTIFICATION_ANNUAL_INPUT_INVALID';end if;
 command:=payload||jsonb_build_object('contract_version','production-future-runtime-activation-v2','environment','CERTIFICATION',
  'project_ref',r.project_ref,'project_url',r.project_url,'source_workbook_id',r.provenance_id,
  'tournament_id',ctx->>'governance_tournament_id','tournament_year',(ctx->>'governance_tournament_id')::integer,
  'authorization',jsonb_build_object('role','DIRECTOR','player_id',ctx#>>'{authorization,player_id}',
   'auth_user_id',ctx#>>'{authorization,auth_user_id}','tournament_id',payload->>'expected_current_tournament_id'),
  'operation_request_id',input->>'operation_request_id');
 return command||jsonb_build_object('request_payload_hash',production_control.future_runtime_hash_v2(command));
end;$_$;


ALTER FUNCTION production_control.certification_annual_transition_command_v1(input jsonb, ctx jsonb) OWNER TO postgres;

--
-- Name: certification_calcutta_publication_projection_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_calcutta_publication_projection_v1(target text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c scoring_authority.calcutta_v1_current%rowtype;r scoring_authority.calcutta_v1_result_revisions%rowtype;fp text;
begin
 select * into strict c from scoring_authority.calcutta_v1_current where tournament_id=target;
 select * into r from scoring_authority.calcutta_v1_result_revisions where tournament_id=target and result_revision=c.result_revision and configuration_revision=c.configuration_revision and auction_revision=c.auction_revision and is_current;
 fp:=production_control.calcutta_v1_hash(production_control.calcutta_v1_source_revision(target));
 return jsonb_build_object('ok',true,'tournament_id',target,'configuration_revision',c.configuration_revision,
   'configuration_fingerprint',c.configuration_fingerprint,'auction_revision',c.auction_revision,
   'auction_fingerprint',c.auction_fingerprint,'publication_revision',c.publication_revision,'publication_state',c.publication_state,
   'result_revision',c.result_revision,'source_fingerprint',fp,'result_state',r.result_state,
   'result_current',coalesce(r.source_fingerprint=fp and r.configuration_revision=c.configuration_revision
     and r.configuration_fingerprint=c.configuration_fingerprint and r.auction_revision=c.auction_revision
     and r.auction_fingerprint=c.auction_fingerprint,false));
end;$$;


ALTER FUNCTION production_control.certification_calcutta_publication_projection_v1(target text) OWNER TO postgres;

--
-- Name: certification_closed_history_2026_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_closed_history_2026_read_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare history_value jsonb;guide_value jsonb;metadata_value jsonb;courses_value jsonb;tournament_value jsonb;
 r production_control.canonical_resource_v1%rowtype;
 revision production_control.projection_revisions%rowtype;
 pointer production_control.projection_current%rowtype;
 closure_time timestamptz;
begin
 if jsonb_typeof(input)is distinct from'object' or input->>'target_tournament_id'is distinct from'2026'
  or exists(select 1 from jsonb_object_keys(input)k where k not in('target_tournament_id','include_tournament_player_metadata'))
  or(input?'include_tournament_player_metadata'and jsonb_typeof(input->'include_tournament_player_metadata')is distinct from'boolean')then
  raise exception using errcode='22023',message='CERTIFICATION_HISTORY_INPUT_INVALID';end if;
 -- This existing boundary validates the installed READS context, exact resource,
 -- completed annual lineage, closed generation and every canonical Final snapshot.
 history_value:=production_control.certification_closed_tournament_read_v1(
  jsonb_build_object('target_tournament_id','2026'),context);
 select *into strict r from production_control.canonical_resource_v1 where singleton
  and resource_id=context->>'resource_id'and resource_class='CERTIFICATION'and database_name=current_database();
 select c.closed_at into strict closure_time
 from production_control.annual_scoring_transitions_v1 t
 join production_control.scoring_admission_closures c on c.closure_id=t.predecessor_closure_id
 where t.resource_class='CERTIFICATION'and t.certification_resource_id=r.resource_id
  and t.predecessor_tournament_id='2026'and t.transition_status='COMMITTED'
  and c.resource_class='CERTIFICATION'and c.certification_resource_id=r.resource_id
  and c.tournament_id='2026'and c.status='CLOSED';
 select *into pointer from production_control.projection_current where domain='GUIDE'and tournament_id='2026';
 select *into revision from production_control.projection_revisions where revision_id=pointer.revision_id;
 if revision.revision_id is null then return jsonb_build_object('ok',false,'code','GUIDE_PROJECTION_UNAVAILABLE');end if;
 -- Retained published authority, not a claim that the annual fingerprint pins
 -- Guide content. The same registered canonical pointer used before close is
 -- required, published before the closure; no successor/current fallback.
 if revision.domain<>'GUIDE'or revision.tournament_id<>'2026'or revision.tournament_year<>2026
  or revision.contract_version<>'guide-projection-v1'
  or revision.source_tabs is distinct from production_control.guide_authoring_source_tabs_v1()
  or revision.validation_status<>'VALID'
  or revision.project_ref is distinct from r.project_ref or revision.project_url is distinct from r.project_url
  or revision.source_workbook_id is distinct from r.provenance_id or closure_time is null
  or revision.imported_at is null or pointer.advanced_at is null
  or revision.imported_at>closure_time or pointer.advanced_at>closure_time
  or revision.payload_fingerprint is distinct from production_control.guide_authoring_hash_v1(revision.projection_payload)
  or revision.source_fingerprint is distinct from production_control.guide_authoring_hash_v1(revision.source_payload)then
  raise exception using errcode='55000',message='CERTIFICATION_HISTORY_GUIDE_PROVENANCE_UNAVAILABLE';end if;
 select jsonb_build_object('tournament_id',t.tournament_id,'tournament_year',t.tournament_year,'name',t.name)
 into strict tournament_value from scoring_authority.tournaments t where t.tournament_id='2026';
 courses_value:=production_control.guide_canonical_course_context_v1('2026');
 if scoring_authority.guide_course_context_is_eligible(courses_value)is not true then
  raise exception using errcode='55000',message='GUIDE_CANONICAL_CONTEXT_UNAVAILABLE';end if;
 guide_value:=jsonb_build_object('ok',true,'data',jsonb_build_object(
  'domain',revision.domain,'tournament_id',revision.tournament_id,'tournament_year',revision.tournament_year,
  'revision_id',revision.revision_id,'revision_number',revision.revision_number,'previous_revision_id',revision.previous_revision_id,
  'source_tabs',revision.source_tabs,'contract_version',revision.contract_version,
  'source_fingerprint',revision.source_fingerprint,'payload_fingerprint',revision.payload_fingerprint,
  'validation_status',revision.validation_status,'validation_diagnostics',revision.validation_diagnostics,
  'payload',revision.projection_payload,'imported_at',revision.imported_at,
  'tournament',tournament_value,'course_context',courses_value,
  'delivery_fingerprint',encode(extensions.digest(jsonb_build_object('publication',revision.payload_fingerprint,
   'tournament',tournament_value,'course_context',courses_value)::text,'sha256'),'hex'),
  'authoritative',true,'shadow_only',false,'google_foreground_requests',0,'fallback_used',false));
 if coalesce((input->>'include_tournament_player_metadata')::boolean,false)then
  -- The closed aggregate already uses the canonical leaderboard projection.
  -- Retain only the public presentation keys consumed by the existing merge.
  metadata_value:=jsonb_build_object('ok',true,'data',jsonb_build_object(
   'players',(select coalesce(jsonb_agg(jsonb_build_object('player_id',p->'player_id','team_side',p->'team_side',
    'presentation',jsonb_build_object('captain',p#>'{presentation,captain}'),
    'source_payload',jsonb_build_object('Captain',p#>'{source_payload,Captain}'),
    'tournament_source_payload',jsonb_build_object('Tournament Handicap',p#>'{tournament_source_payload,Tournament Handicap}',
      'Captain',p#>'{tournament_source_payload,Captain}'))),'[]')from jsonb_array_elements(history_value#>'{data,players}')p),
   'teams',(select coalesce(jsonb_agg(jsonb_build_object('team_side',t->'team_side','captain_player_id',t->'captain_player_id',
    'captain_id',t->'captain_id','source_payload',jsonb_build_object('Captain Player ID',t#>'{source_payload,Captain Player ID}',
     'Captain ID',t#>'{source_payload,Captain ID}','Captain',t#>'{source_payload,Captain}'))),'[]')
     from jsonb_array_elements(history_value#>'{data,teams}')t),
   'tournament',jsonb_build_object('source_payload',jsonb_build_object(
    'Captain Team 1',history_value#>'{data,tournament,source_payload,Captain Team 1}',
    'Captain Team 2',history_value#>'{data,tournament,source_payload,Captain Team 2}'))));
 end if;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('history',history_value,'guide',guide_value,
  'tournament_player_metadata',metadata_value),'google_foreground_requests',0,'fallback_used',false,'authoritative',true);
end;$$;


ALTER FUNCTION production_control.certification_closed_history_2026_read_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: certification_closed_tournament_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_closed_tournament_read_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare target text:=input->>'target_tournament_id';verified jsonb;r production_control.canonical_resource_v1%rowtype;
 t production_control.annual_scoring_transitions_v1%rowtype;c production_control.scoring_admission_closures%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;result_value jsonb;
begin
 verified:=production_control.current_certification_context_v1();
 if context is distinct from verified or context->>'resource_class' is distinct from 'CERTIFICATION'
  or context->>'phase' is distinct from 'READS' or jsonb_typeof(input) is distinct from 'object'
  or exists(select 1 from jsonb_object_keys(input)k where k<>'target_tournament_id')
  or target is null or target!~'^20[0-9]{2}$' or target=context->>'current_tournament_id' then
  raise exception using errcode='42501',message='CERTIFICATION_HISTORY_TARGET_DENIED';end if;
 if (context->>'current_tournament_year')::integer>2026 then
  perform production_control.assert_current_certification_future_context_v1(context);end if;
 select * into strict r from production_control.canonical_resource_v1 where singleton and resource_id=context->>'resource_id'
  and resource_class='CERTIFICATION' and database_name=current_database();
 select * into strict t from production_control.annual_scoring_transitions_v1 where resource_class='CERTIFICATION'
  and certification_resource_id=r.resource_id and predecessor_tournament_id=target and transition_status='COMMITTED';
 select * into strict c from production_control.scoring_admission_closures where closure_id=t.predecessor_closure_id
  and resource_class='CERTIFICATION'and certification_resource_id=r.resource_id and tournament_id=target
  and boundary_mode='CERTIFICATION_INGRESS_V1'and status='CLOSED';
 select * into strict g from production_control.certification_ingress_generations_v1 where resource_id=r.resource_id
  and generation_id=c.admission_generation_id and tournament_id=target and state='CLOSED'
  and authority_epoch_id=c.authority_generation_id and revision=c.closed_admission_revision
  and high_watermark=c.lease_high_watermark;
 if not exists(select 1 from production_control.future_tournament_catalog_v1 where tournament_id=target and lifecycle='CLOSED')
  or not exists(select 1 from scoring_authority.authority_epochs where epoch_id=g.authority_epoch_id and tournament_id=target
   and status='COMMITTED'and epoch_type in('CERTIFICATION_INITIALIZATION','CERTIFICATION_ANNUAL_TRANSITION')
   and boundary_mode='CERTIFICATION_INGRESS_V1')
  or not exists(select 1 from scoring_authority.matches where tournament_id=target)
  or exists(select 1 from scoring_authority.matches where tournament_id=target and(status<>'FINAL'or not scorecard_complete))then
  raise exception using errcode='42501',message='CERTIFICATION_HISTORY_CLOSED_AUTHORITY_REQUIRED';end if;
 result_value:=production_control.canonical_finalized_tournament_projection_v1(target,'canonical-completed-tournament-v1');
 if not coalesce((result_value->>'ok')::boolean,false)
  or jsonb_array_length(result_value#>'{data,finalized_snapshots}')<>(select count(*)from scoring_authority.matches where tournament_id=target)then
  raise exception using errcode='55000',message='CERTIFICATION_HISTORY_FINAL_SNAPSHOTS_REQUIRED';end if;
 return production_control.mark_certification_read_v1(result_value,context);
exception when no_data_found or too_many_rows then
 raise exception using errcode='42501',message='CERTIFICATION_HISTORY_CLOSED_AUTHORITY_REQUIRED';
end;$_$;


ALTER FUNCTION production_control.certification_closed_tournament_read_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: certification_ingress_leases_v1; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.certification_ingress_leases_v1 (
    lease_id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    admission_sequence bigint NOT NULL,
    resource_id text NOT NULL,
    admission_generation_id uuid NOT NULL,
    tournament_id text NOT NULL,
    authority_epoch_id uuid NOT NULL,
    operation_id text NOT NULL,
    operation_request_id text NOT NULL,
    target_key text NOT NULL,
    match_id text,
    domain_action text,
    actor_auth_user_id uuid NOT NULL,
    actor_player_id text NOT NULL,
    actor_role text NOT NULL,
    request_hash text NOT NULL,
    context_token text NOT NULL,
    admission_context jsonb NOT NULL,
    predecessor_auction_revision bigint,
    state text DEFAULT 'ADMITTED'::text NOT NULL,
    result jsonb,
    committed_generation_revision bigint,
    admitted_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone DEFAULT (clock_timestamp() + '00:05:00'::interval) NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT certification_ingress_leases_predecessor_auction_revision_check CHECK ((predecessor_auction_revision >= 0)),
    CONSTRAINT certification_ingress_leases_v1_actor_role_check CHECK ((actor_role = ANY (ARRAY['PLAYER'::text, 'DIRECTOR'::text]))),
    CONSTRAINT certification_ingress_leases_v1_admission_context_check CHECK ((jsonb_typeof(admission_context) = 'object'::text)),
    CONSTRAINT certification_ingress_leases_v1_check CHECK ((((state = ANY (ARRAY['ADMITTED'::text, 'UNKNOWN'::text])) AND (result IS NULL) AND (resolved_at IS NULL) AND (committed_generation_revision IS NULL)) OR ((state = 'COMMITTED'::text) AND (jsonb_typeof(result) = 'object'::text) AND (resolved_at IS NOT NULL) AND (committed_generation_revision IS NOT NULL)) OR ((state = 'NOT_COMMITTED'::text) AND (jsonb_typeof(result) = 'object'::text) AND (resolved_at IS NOT NULL) AND (committed_generation_revision IS NULL)))),
    CONSTRAINT certification_ingress_leases_v1_context_token_check CHECK ((context_token ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT certification_ingress_leases_v1_operation_request_id_check CHECK ((operation_request_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'::text)),
    CONSTRAINT certification_ingress_leases_v1_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT certification_ingress_leases_v1_state_check CHECK ((state = ANY (ARRAY['ADMITTED'::text, 'UNKNOWN'::text, 'COMMITTED'::text, 'NOT_COMMITTED'::text])))
);


ALTER TABLE production_control.certification_ingress_leases_v1 OWNER TO postgres;

--
-- Name: certification_ingress_canonical_receipt_v1(production_control.certification_ingress_leases_v1); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_ingress_canonical_receipt_v1(lease production_control.certification_ingress_leases_v1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare value jsonb;action_name text;binding uuid;fp text;
begin
 if lease.operation_id like'SCORING.%'or lease.operation_id='DIRECTOR.MATCH_CONTROL'then
  select m.result into value from scoring_authority.score_mutations m join scoring_authority.matches mt using(match_id)
   where m.match_id=lease.match_id and m.mutation_key=lease.operation_request_id and mt.tournament_id=lease.tournament_id;
 elsif lease.operation_id in('DIRECTOR.MUTATE_SETUP','DIRECTOR.MUTATE_PAIRINGS')then
  action_name:=case lease.domain_action when'update-tournament'then'UPDATE_TOURNAMENT'when'update-team'then'UPDATE_TEAM'
   when'assign-roster-team'then'ASSIGN_ROSTER_TEAM'when'update-round'then'UPDATE_ROUND'when'upsert-course'then'UPSERT_COURSE'
   when'upsert-match'then'UPSERT_MATCH'when'replace-pairings'then'REPLACE_PAIRINGS'when'prepare-scoring-context'then'PREPARE_SCORING_CONTEXT'
   when'replace-round-pairings'then'REPLACE_ROUND_PAIRINGS'end;
  select r.response into value from production_control.tournament_setup_operation_receipts_v1 r
   where r.tournament_id=lease.tournament_id and r.action=action_name and r.operation_request_id=lease.operation_request_id::uuid;
 elsif lease.operation_id='DIRECTOR.PUBLISH_CALCUTTA' then
  fp:=production_control.calcutta_v1_hash(jsonb_build_object('contract','certification-calcutta-publication-v1',
    'resource_id',lease.resource_id,'operation_request_id',lease.operation_request_id));
  select r.response into value from production_control.cutover_operation_receipts r
    where r.request_fingerprint=fp and r.operation='CALCUTTA_V1_PUBLISH' and r.actor=lease.actor_player_id;
 elsif lease.operation_id='DIRECTOR.CONFIGURE_NET_SKINS' then
  return production_control.certification_net_skins_configuration_receipt_v1(lease);
 elsif lease.operation_id='DIRECTOR.SAVE_NET_SKINS_ENTRIES'then
  select r.response into value from production_control.net_skins_entry_revisions_v1 r
   where r.tournament_id=lease.tournament_id and r.request_id=lease.operation_request_id::uuid;
 elsif lease.operation_id in('DIRECTOR.REPLACE_CALCUTTA_AUCTION','DIRECTOR.CLEAR_CALCUTTA_AUCTION')then
  select a.binding_id into strict binding from production_control.certification_admission_v1 a where resource_id=lease.resource_id;
  action_name:=case lease.operation_id when'DIRECTOR.REPLACE_CALCUTTA_AUCTION'then'replace-auction'else'clear-entry'end;
  fp:=production_control.calcutta_v1_hash(jsonb_build_object('binding_id',binding::text,'family','CALCUTTA_MANAGEMENT',
   'action',action_name,'operation_request_id',lease.operation_request_id));
  select r.response into value from production_control.cutover_operation_receipts r where request_fingerprint=fp;
 end if;
 return value;
end;$$;


ALTER FUNCTION production_control.certification_ingress_canonical_receipt_v1(lease production_control.certification_ingress_leases_v1) OWNER TO postgres;

--
-- Name: certification_ingress_evidence_v1(text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_ingress_evidence_v1(target_resource_id text, target_generation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare g production_control.certification_ingress_generations_v1%rowtype;summary jsonb;fp text;
begin
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 select * into strict g from production_control.certification_ingress_generations_v1 where resource_id=target_resource_id and generation_id=target_generation_id for update;
 select jsonb_build_object('admitted_count',count(*),'high_watermark',coalesce(max(admission_sequence),0),
 'active_count',count(*)filter(where state='ADMITTED'),'unknown_count',count(*)filter(where state='UNKNOWN'),
 'committed_count',count(*)filter(where state='COMMITTED'),'not_committed_count',count(*)filter(where state='NOT_COMMITTED'),
 'post_close_admissions',count(*)filter(where g.high_watermark is not null and admission_sequence>g.high_watermark),
 'post_close_writes',count(*)filter(where g.closing_revision is not null and committed_generation_revision>=g.closing_revision))into summary
 from production_control.certification_ingress_leases_v1 where resource_id=target_resource_id and admission_generation_id=target_generation_id;
 select production_control.cutover_payload_hash(coalesce(jsonb_agg(jsonb_build_object('sequence',admission_sequence,'operation',operation_id,
 'operation_id',operation_request_id,'target',target_key,'hash',request_hash,'state',state,'committed_revision',committed_generation_revision)
 order by admission_sequence),'[]'::jsonb))into fp
 from production_control.certification_ingress_leases_v1 where resource_id=target_resource_id and admission_generation_id=target_generation_id;
 return summary||jsonb_build_object('resource_id',target_resource_id,'generation_id',target_generation_id,'tournament_id',g.tournament_id,
 'authority_epoch_id',g.authority_epoch_id,'generation_revision',g.revision,'state',g.state,'fingerprint',fp,
 'captured_high_watermark',g.high_watermark,'captured_fingerprint',g.lease_fingerprint,
 'drained',(summary->>'active_count')::bigint=0 and(summary->>'unknown_count')::bigint=0
 and(summary->>'post_close_admissions')::bigint=0 and(summary->>'post_close_writes')::bigint=0,
 'fingerprint_matches',g.state<>'CLOSED'or g.lease_fingerprint=fp);
end;$$;


ALTER FUNCTION production_control.certification_ingress_evidence_v1(target_resource_id text, target_generation_id uuid) OWNER TO postgres;

--
-- Name: certification_ingress_identity_v1(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_ingress_identity_v1(input jsonb, recovery boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare op text:=input->>'operation_id';id text:=input->>'operation_request_id';target text:=input#>>'{authorization,tournament_id}';
 m text:=input#>>'{payload,match_id}';actor text:=input#>>'{authorization,player_id}';role_name text:=input#>>'{authorization,role}';
 auth_id uuid:=(input#>>'{authorization,auth_user_id}')::uuid;
begin
 if not production_control.certification_ingress_required_v1(op)or id is null or id!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'
  or target is null or target!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$' or actor is null or auth_id is null
  or role_name not in('PLAYER','DIRECTOR')or role_name is null then
   raise exception using errcode='22023',message='CERTIFICATION_INGRESS_IDENTITY_INVALID';end if;
 if(op like 'SCORING.%'or op='DIRECTOR.MATCH_CONTROL')and(m is null or m!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$')then
  raise exception using errcode='22023',message='CERTIFICATION_INGRESS_MATCH_REQUIRED';end if;
 if op like 'DIRECTOR.%'and id!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'then
  raise exception using errcode='22023',message='CERTIFICATION_INGRESS_IDENTITY_INVALID';end if;
 if op like 'SCORING.%'and input#>>'{authorization,match_id}'is distinct from m then
  raise exception using errcode='42501',message='CERTIFICATION_INGRESS_MATCH_DENIED';end if;
 if recovery then perform production_control.assert_certification_ingress_recovery_actor_v1(input,target,op like 'DIRECTOR.%'or op='SCORING.REOPEN_MATCH');
 elsif target='2026'then perform production_control.assert_production_scoring_actor(input,op like 'DIRECTOR.%'or op='SCORING.REOPEN_MATCH');
 else perform production_control.assert_canonical_future_scoring_actor_v1(input,target,op like 'DIRECTOR.%'or op='SCORING.REOPEN_MATCH',production_control.current_certification_context_v1());end if;
 return jsonb_build_object('operation_id',op,'operation_request_id',id,'tournament_id',target,'match_id',m,
  'target_key',case when op like 'SCORING.%'or op='DIRECTOR.MATCH_CONTROL'then 'MATCH:'||m else 'TOURNAMENT'end,
  'actor_auth_user_id',auth_id,'actor_player_id',actor,'actor_role',role_name);
exception when invalid_text_representation then raise exception using errcode='22023',message='CERTIFICATION_INGRESS_IDENTITY_INVALID';
end;$_$;


ALTER FUNCTION production_control.certification_ingress_identity_v1(input jsonb, recovery boolean) OWNER TO postgres;

--
-- Name: certification_ingress_lookup_v1(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_ingress_lookup_v1(input jsonb, lock_row boolean) RETURNS production_control.certification_ingress_leases_v1
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare r production_control.canonical_resource_v1%rowtype;i jsonb;l production_control.certification_ingress_leases_v1%rowtype;
 target_key_value text;recovery_input jsonb;
begin
 r:=production_control.certification_ingress_recovery_resource_v1(input);
 if not production_control.certification_ingress_required_v1(input->>'operation_id')
   or coalesce(input->>'operation_request_id','')!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'then
  raise exception using errcode='22023',message='CERTIFICATION_INGRESS_IDENTITY_INVALID';end if;
 target_key_value:=case when input->>'operation_id'like'SCORING.%'or input->>'operation_id'='DIRECTOR.MATCH_CONTROL'
  then'MATCH:'||(input#>>'{payload,match_id}')else'TOURNAMENT'end;
 -- Origin filtering makes another actor's operation indistinguishable from absence.
 -- Historical target is derived only from the exact stored operation in this DB.
 if lock_row then
  select * into l from production_control.certification_ingress_leases_v1 where resource_id=r.resource_id
   and operation_id=input->>'operation_id'and target_key=target_key_value and operation_request_id=input->>'operation_request_id'
   and actor_auth_user_id::text=input#>>'{authorization,auth_user_id}'and actor_player_id=input#>>'{authorization,player_id}'
   and actor_role=input#>>'{authorization,role}'for update;
 else
  select * into l from production_control.certification_ingress_leases_v1 where resource_id=r.resource_id
   and operation_id=input->>'operation_id'and target_key=target_key_value and operation_request_id=input->>'operation_request_id'
   and actor_auth_user_id::text=input#>>'{authorization,auth_user_id}'and actor_player_id=input#>>'{authorization,player_id}'
   and actor_role=input#>>'{authorization,role}';end if;
 recovery_input:=case when l.lease_id is null then input else jsonb_set(input,'{authorization,tournament_id}',to_jsonb(l.tournament_id))end;
 i:=production_control.certification_ingress_identity_v1(recovery_input,true);
 if l.lease_id is not null then
  if coalesce((input->>'verify_request')::boolean,false)and l.request_hash is distinct from production_control.certification_ingress_request_hash_v1(input,i)then
   raise exception using errcode='23505',message='CERTIFICATION_INGRESS_IDEMPOTENCY_CONFLICT';end if;
  if(input#>>'{ingress,lease_id}'is not null and input#>>'{ingress,lease_id}'is distinct from l.lease_id::text)
    or(input#>>'{ingress,admission_generation_id}'is not null and input#>>'{ingress,admission_generation_id}'is distinct from l.admission_generation_id::text)then
   raise exception using errcode='42501',message='CERTIFICATION_INGRESS_BINDING_DENIED';end if;
 end if;
 return l;
end;$_$;


ALTER FUNCTION production_control.certification_ingress_lookup_v1(input jsonb, lock_row boolean) OWNER TO postgres;

--
-- Name: certification_ingress_recovery_resource_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_ingress_recovery_resource_v1(input jsonb) RETURNS production_control.canonical_resource_v1
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;a production_control.certification_admission_v1%rowtype;
begin
 perform production_control.assert_production_service_role();
 perform pg_advisory_xact_lock_shared(production_control.scoring_admission_lock_key());
 select * into strict r from production_control.canonical_resource_v1 where singleton for share;
 select * into strict a from production_control.certification_admission_v1 where resource_id=r.resource_id for share;
 if input->>'contract_version' is distinct from 'certification-runtime-v1'
  or r.resource_class<>'CERTIFICATION' or r.database_name<>current_database()
  or exists(select 1 from production_control.resource_scope)or exists(select 1 from production_control.cutover_activation_state)
  or input#>>'{resource,resource_class}' is distinct from r.resource_class
  or input#>>'{resource,resource_id}'is distinct from r.resource_id
  or input#>>'{resource,installation_id}'is distinct from r.installation_id::text
  or input#>>'{resource,project_ref}'is distinct from r.project_ref or input#>>'{resource,project_url}'is distinct from r.project_url
  or input#>>'{resource,schema_contract}'is distinct from r.schema_contract or input#>>'{resource,schema_digest}'is distinct from r.schema_digest
  or input#>>'{resource,registration_revision}'is distinct from r.registration_revision::text
  or input#>>'{resource,manifest_digest}'is distinct from r.manifest_digest
  or input#>>'{deployment,vercel_team_id}'is distinct from r.vercel_team_id
  or input#>>'{deployment,vercel_project_id}'is distinct from r.vercel_project_id
  or input#>>'{deployment,git_branch}'is distinct from a.git_branch
  or input#>>'{deployment,deployment_class}'is distinct from a.deployment_class
  or input#>>'{deployment,release_commit}'is distinct from a.release_commit
  or input#>>'{deployment,deployment_id}'is distinct from a.deployment_id
  or input#>>'{deployment,deployment_origin}'is distinct from a.deployment_origin then
   raise exception using errcode='42501',message='CERTIFICATION_INGRESS_RESOURCE_DENIED';end if;
 return r;
exception when no_data_found then raise exception using errcode='55000',message='CERTIFICATION_INGRESS_SCHEMA_REQUIRED';
end;$$;


ALTER FUNCTION production_control.certification_ingress_recovery_resource_v1(input jsonb) OWNER TO postgres;

