--
-- Name: certification_ingress_required_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_ingress_required_v1(operation_id text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
