-- Name: certification_odds_request_hash_v1(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_odds_request_hash_v1(input jsonb, resource_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 select production_control.tournament_setup_hash_v1(jsonb_build_object('contract','certification-odds-operation-v1',
 'resource_id',resource_id,'operation_request_id',input->>'operation_request_id','operation_name',input#>>'{payload,odds_operation}',
 'actor_auth_user_id',input#>>'{authorization,auth_user_id}','actor_player_id',input#>>'{authorization,player_id}',
 'tournament_id',input#>>'{authorization,tournament_id}',
 'payload',case when input#>>'{payload,odds_operation}'='request_production_odds_calculation_job'
  then(input->'payload')-array['output_timestamp','resource_metrics','requested_by']else input->'payload'end))
$$;


ALTER FUNCTION production_control.certification_odds_request_hash_v1(input jsonb, resource_id text) OWNER TO postgres;

--
-- Name: certification_odds_runtime_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_odds_runtime_v1(context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c jsonb:=production_control.current_certification_context_v1();g production_control.certification_ingress_generations_v1%rowtype;
 annual production_control.future_annual_runtime_generations_v1%rowtype;r production_control.canonical_resource_v1%rowtype;
begin
 select * into strict r from production_control.canonical_resource_v1 where singleton;
 if context is distinct from c or c->>'resource_class'<>'CERTIFICATION' or c->>'resource_id' is distinct from r.resource_id
  or r.database_name<>current_database() or c->>'phase'not in('DIRECTOR','WORKERS')then
  raise exception using errcode='42501',message='CERTIFICATION_ODDS_CONTEXT_REQUIRED';end if;
 select * into strict g from production_control.certification_ingress_generations_v1
  where resource_id=r.resource_id and tournament_id=c->>'tournament_id'and state='OPEN'for share;
 if g.authority_epoch_id::text is distinct from c->>'authority_epoch_id'or g.pointer_revision::text is distinct from c->>'pointer_revision'then
  raise exception using errcode='40001',message='CERTIFICATION_ODDS_GENERATION_STALE';end if;
 if c->>'tournament_id'<>'2026'then
  perform production_control.assert_current_certification_future_context_v1(c);
  select * into strict annual from production_control.future_annual_runtime_generations_v1
   where tournament_id=c->>'tournament_id'and generation_status='ACTIVE';
  if annual.admission_generation_id<>g.generation_id or annual.authority_generation_id<>g.authority_epoch_id
   or annual.pointer_revision<>g.pointer_revision or annual.ingress_state<>'OPEN'or annual.authority<>'SUPABASE'then
   raise exception using errcode='40001',message='CERTIFICATION_ODDS_GENERATION_STALE';end if;
 end if;
 return c||jsonb_build_object('runtime_generation_id',annual.runtime_generation_id,
  'certification_ingress_generation_id',g.generation_id,'provenance_id',r.provenance_id);
exception when no_data_found then raise exception using errcode='55000',message='CERTIFICATION_ODDS_RUNTIME_REQUIRED';
end;$$;


ALTER FUNCTION production_control.certification_odds_runtime_v1(context jsonb) OWNER TO postgres;

--
-- Name: certification_operation_phase_v1(text, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_operation_phase_v1(operation_id text, mutation boolean) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if mutation and operation_id='DIRECTOR.CONFIGURE_ODDS_INPUTS' then return 'DIRECTOR';end if;
 if not mutation and operation_id in('DIRECTOR.READ_ODDS_INPUT_CONFIGURATION','DIRECTOR.ODDS_INPUT_CONFIGURATION_STATUS') then return 'DIRECTOR';end if;
 if mutation and operation_id='DIRECTOR.CALCULATE_NET_SKINS' then return 'DIRECTOR';end if;
 if not mutation and operation_id in('DIRECTOR.READ_NET_SKINS_CALCULATION','DIRECTOR.NET_SKINS_CALCULATION_STATUS') then return 'DIRECTOR';end if;
 if mutation and operation_id='DIRECTOR.PUBLISH_CALCUTTA' then return 'DIRECTOR';end if;
 if not mutation and operation_id='DIRECTOR.READ_CALCUTTA_PUBLICATION' then return 'DIRECTOR';end if;
 if mutation and operation_id='DIRECTOR.CONFIGURE_NET_SKINS' then return 'DIRECTOR'; end if;
 if not mutation and operation_id='DIRECTOR.READ_NET_SKINS_CONFIGURATION' then return 'DIRECTOR'; end if;
 if mutation and operation_id in('WORKERS.DELIVERY_TICK','WORKERS.FAIL_PRECLAIM','WORKERS.COMPETITION_CLAIM','WORKERS.COMPETITION_WRITE','WORKERS.COMPETITION_FAIL','WORKERS.INTELLIGENCE_CLAIM','WORKERS.INTELLIGENCE_WRITE','WORKERS.INTELLIGENCE_FAIL','WORKERS.CALCUTTA_CLAIM','WORKERS.CALCUTTA_COMPLETE','WORKERS.CALCUTTA_FAIL') then return 'WORKERS'; end if;
 if mutation and operation_id in('DIRECTOR.NET_SKINS_CLAIM','DIRECTOR.NET_SKINS_COMPLETE','DIRECTOR.NET_SKINS_FAIL','DIRECTOR.REQUEUE_DERIVED') then return 'DIRECTOR'; end if;
 if not mutation and operation_id in('SCORING.READ_AUTHORITY','SCORING.READ_PARTICIPANT_CONTEXT','SCORING.READ_MUTATION_STATUS') then return 'READS'; end if;
 if not mutation and operation_id in('SCORING.READ_DIRECTOR_OPERATION_STATUS','DIRECTOR.READ_SETUP','DIRECTOR.READ_NET_SKINS','DIRECTOR.READ_CALCUTTA',
  'DIRECTOR.SETUP_STATUS','DIRECTOR.MATCH_CONTROL_STATUS','DIRECTOR.NET_SKINS_STATUS','DIRECTOR.CALCUTTA_STATUS') then return 'DIRECTOR'; end if;
 if mutation and operation_id in('SCORING.SUBMIT_HOLE','SCORING.FINALIZE_MATCH') then return 'SCORING'; end if;
 if mutation and operation_id in('SCORING.REOPEN_MATCH','DIRECTOR.MUTATE_SETUP','DIRECTOR.MUTATE_PAIRINGS','DIRECTOR.MATCH_CONTROL','DIRECTOR.SAVE_NET_SKINS_ENTRIES','DIRECTOR.REPLACE_CALCUTTA_AUCTION','DIRECTOR.CLEAR_CALCUTTA_AUCTION') then return 'DIRECTOR'; end if;
 raise exception using errcode='42501',message='CERTIFICATION_OPERATION_NOT_ADMITTED';
end;
$$;


ALTER FUNCTION production_control.certification_operation_phase_v1(operation_id text, mutation boolean) OWNER TO postgres;

