--
-- Name: certification_successor_current_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_successor_current_read_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare target text:=coalesce(input->>'target_tournament_id',context->>'current_tournament_id');surface text:=input->>'surface';
 player_id_value text:=btrim(coalesce(input->>'player_id',''));match_id_value text:=btrim(coalesce(input->>'match_id',''));
 result_value jsonb;
begin
 perform production_control.assert_certification_current_projection_v1(target,context);
 if target='2026' or jsonb_typeof(input) is distinct from 'object'
  or exists(select 1 from jsonb_object_keys(input)k where k not in('surface','target_tournament_id','player_id','match_id'))
  or (surface not in('PARTICIPANT_HOME','MY_MATCH') and input?'player_id')
  or (surface<>'GAME_CENTER' and input?'match_id') then
  raise exception using errcode='42501',message='CERTIFICATION_READ_TARGET_DENIED';end if;
 case surface
 when 'TOURNAMENT_LIVE' then result_value:=public.read_leaderboards_core_view(target);
 when 'PARTICIPANT_HOME','MY_MATCH' then
  if player_id_value='' then return jsonb_build_object('ok',false,'code','PLAYER_ID_REQUIRED');end if;
  if not exists(select 1 from scoring_authority.tournament_players p
    where p.tournament_id=target and p.player_id=player_id_value)then
   raise exception using errcode='42501',message='CERTIFICATION_READ_PLAYER_DENIED';end if;
  if surface='PARTICIPANT_HOME'then result_value:=public.read_participant_home_view(target,player_id_value);
  else result_value:=public.read_my_match_view(target,player_id_value);end if;
 when 'GAME_CENTER' then
  if match_id_value=''or not exists(select 1 from scoring_authority.matches m
    where m.tournament_id=target and m.match_id=match_id_value)then
   return jsonb_build_object('ok',false,'code','PRODUCTION_MATCH_NOT_FOUND');end if;
  result_value:=public.read_game_center_view(match_id_value);
 else raise exception using errcode='42501',message='CERTIFICATION_FUTURE_READ_OPERATION_DENIED';end case;
 return production_control.mark_certification_read_v1(result_value,context);
end;$$;


ALTER FUNCTION production_control.certification_successor_current_read_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: certification_worker_current_projection_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certification_worker_current_projection_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare target text:=input->>'target_tournament_id';surface text:=input->>'surface';keys text[];result jsonb;
begin
 perform production_control.assert_certification_current_projection_v1(target,context);
 if jsonb_typeof(input) is distinct from 'object' or exists(select 1 from jsonb_object_keys(input)k
   where k not in('surface','target_tournament_id','engine_keys'))then
  raise exception using errcode='42501',message='CERTIFICATION_READ_TARGET_DENIED';end if;
 case surface
 when 'LEADERBOARDS'then result:=public.read_leaderboards_core_view(target);
 when 'NET_SKINS_RESULT'then result:=public.read_net_skins_result_view(target);
 when 'PUBLISHED_ODDS'then result:=production_control.certification_published_odds_read_v1(target,context);
 when 'COMPETITION_DERIVED'then
  if jsonb_typeof(input->'engine_keys') is distinct from 'array' then
   return jsonb_build_object('ok',false,'code','ENGINE_KEYS_REQUIRED');end if;
  select array_agg(value)into keys from jsonb_array_elements_text(input->'engine_keys');
  if keys is null or cardinality(keys)=0 or exists(select 1 from unnest(keys)k where k not in(
   'TEAM_MOMENTUM','TOURNAMENT_STORYLINES','CALCUTTA','TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL','TOURNAMENT_FINAL_RECAP'))then
   return jsonb_build_object('ok',false,'code','ENGINE_KEYS_INVALID');end if;
  result:=public.read_competition_derived_state(target,keys);
 else raise exception using errcode='42501',message='CERTIFICATION_FUTURE_READ_OPERATION_DENIED';end case;
 return production_control.mark_certification_read_v1(result,context);
end;$$;


ALTER FUNCTION production_control.certification_worker_current_projection_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: certify_identical_legacy_course_adoption_v1(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certify_identical_legacy_course_adoption_v1(target_tournament text, manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  holes jsonb;
  actual_holes jsonb;
  actual_rounds jsonb;
  target_course text := manifest->>'course_id';
  target_tee text := manifest->>'tee';
  rounds_value jsonb := manifest->'round_numbers';
  match_value scoring_authority.matches%rowtype;
  snapshot scoring_authority.scoring_snapshots%rowtype;
  detail scoring_authority.tournament_setup_match_details_v1%rowtype;
  matched_count integer := 0;
  hole_fingerprint text;
begin
  -- This extends only the installed current-2026 Setup operation, not annual
  -- activation, global course creation, or dormant/Preview authoring.
  if target_tournament is distinct from '2026'
     or coalesce(target_course, '') = '' or coalesce(target_tee, '') = ''
     or jsonb_typeof(rounds_value) is distinct from 'array'
     or jsonb_array_length(rounds_value) = 0
     or exists (select 1 from jsonb_array_elements_text(rounds_value) r
       where r !~ '^[1-9][0-9]*$')
     or exists (select 1 from scoring_authority.tournament_setup_course_tees_v1 c
       where c.tournament_id = target_tournament
         and c.course_id = target_course and c.tee_id = target_tee) then
    return jsonb_build_object('eligible', false);
  end if;
  holes := production_control.legacy_course_adoption_holes_v1(manifest->'holes');
  if holes is null or (select sum((h->>'par')::integer)
       from jsonb_array_elements(holes) h) is distinct from (manifest->>'par')::integer
     or (manifest->>'rating')::numeric is null
     or (manifest->>'slope')::integer is null then
    return jsonb_build_object('eligible', false);
  end if;
  hole_fingerprint := encode(extensions.digest(holes::text, 'sha256'), 'hex');

  -- The old operation materializes all matches sharing this course/tee. Require
  -- callers to name that entire round set, and reject any round whose matches
  -- disagree or hide an override. Never silently select one retained snapshot.
  select jsonb_agg(r order by r) into actual_rounds from (
    select distinct m.round_number r from scoring_authority.matches m
    join scoring_authority.scoring_snapshots s on s.snapshot_id = m.scoring_snapshot_id
    where m.tournament_id = target_tournament
      and s.course_id = target_course and s.tee = target_tee
  ) rounds;
  if actual_rounds is distinct from rounds_value then
    return jsonb_build_object('eligible', false);
  end if;
  for match_value in select m.* from scoring_authority.matches m
    where m.tournament_id = target_tournament
      and m.round_number in (select r::integer from jsonb_array_elements_text(rounds_value) r)
    order by m.match_id
  loop
    if match_value.status <> 'UPCOMING'
       or not production_control.handicap_v1_match_is_unstarted(match_value.match_id)
       or match_value.unresolved_mutations <> 0
       or exists (select 1 from scoring_authority.score_mutations s where s.match_id = match_value.match_id)
       or exists (select 1 from scoring_authority.hole_scores s where s.match_id = match_value.match_id)
       or exists (select 1 from scoring_authority.finalized_scorecard_snapshots s where s.match_id = match_value.match_id)
       or exists (select 1 from scoring_authority.scoring_ingress_leases l
         where l.match_id = match_value.match_id and l.expires_at > statement_timestamp())
       or exists (select 1 from scoring_authority.scoring_permissions p
         where p.match_id = match_value.match_id and (p.can_score or p.revoked_at is null
           or p.permission_revision <> match_value.permission_revision)) then
      return jsonb_build_object('eligible', false);
    end if;
    select s.* into strict snapshot from scoring_authority.scoring_snapshots s
      where s.snapshot_id = match_value.scoring_snapshot_id
        and s.match_id = match_value.match_id and s.tournament_id = target_tournament;
    if snapshot.course_id is distinct from target_course or snapshot.tee is distinct from target_tee
       or snapshot.rating is distinct from (manifest->>'rating')::numeric
       or snapshot.slope is distinct from (manifest->>'slope')::integer
       or snapshot.par is distinct from (manifest->>'par')::integer
       or production_control.legacy_course_adoption_holes_v1(snapshot.hole_definitions) is distinct from holes then
      return jsonb_build_object('eligible', false);
    end if;
    select jsonb_agg(jsonb_build_object('hole_number', h.hole_number, 'par', h.par,
      'stroke_index', h.stroke_index, 'yardage', h.yardage) order by h.hole_number)
      into actual_holes from scoring_authority.match_holes h where h.match_id = match_value.match_id;
    if production_control.legacy_course_adoption_holes_v1(actual_holes) is distinct from holes
       or exists (select 1 from scoring_authority.match_holes h
         where h.match_id = match_value.match_id and h.snapshot_id <> snapshot.snapshot_id)
       or encode(extensions.digest(actual_holes::text, 'sha256'), 'hex') is distinct from hole_fingerprint then
      return jsonb_build_object('eligible', false);
    end if;
    select d.* into detail from scoring_authority.tournament_setup_match_details_v1 d
      where d.match_id = match_value.match_id;
    if found and (detail.tournament_id <> target_tournament
       or detail.round_number <> match_value.round_number
       or detail.course_id is distinct from target_course or detail.tee_id is distinct from target_tee
       or detail.prepared_setup_revision is not null or detail.prepared_configuration_fingerprint is not null) then
      return jsonb_build_object('eligible', false);
    end if;
    if exists (select 1 from scoring_authority.tournament_setup_round_courses_v1 a
      where a.tournament_id = target_tournament and a.round_number = match_value.round_number
        and (a.course_id <> target_course or a.tee_id <> target_tee)) then
      return jsonb_build_object('eligible', false);
    end if;
    matched_count := matched_count + 1;
  end loop;
  if matched_count = 0 then return jsonb_build_object('eligible', false); end if;
  return jsonb_build_object('eligible', true, 'courseId', target_course, 'tee', target_tee,
    'matchCount', matched_count, 'orderedHoleFingerprint', hole_fingerprint);
exception when no_data_found or invalid_text_representation or numeric_value_out_of_range then
  return jsonb_build_object('eligible', false);
end;
$_$;


ALTER FUNCTION production_control.certify_identical_legacy_course_adoption_v1(target_tournament text, manifest jsonb) OWNER TO postgres;

--
-- Name: certify_production_auth_candidate_otp(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certify_production_auth_candidate_otp(target_request_id uuid, target_auth_user_id uuid, target_duration_ms integer, recovery boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth', 'pg_temp'
    AS $$
declare attempt participant_identity.participant_auth_otp_attempts%rowtype;
declare candidate participant_identity.production_auth_candidates%rowtype;
declare auth_user auth.users%rowtype;
begin
  perform production_control.assert_production_auth_candidate_rpc();
  select * into attempt from participant_identity.participant_auth_otp_attempts
  where request_id = target_request_id for update;
  if not found then raise exception 'OTP request was not found.'; end if;
  select * into candidate from participant_identity.production_auth_candidates
  where tournament_id = attempt.tournament_id and auth_user_id = target_auth_user_id
    and player_id = attempt.player_id and status in ('PREPARED', 'VERIFIED') for update;
  if not found or attempt.auth_user_id is distinct from target_auth_user_id
    or attempt.email_identity_hash is distinct from candidate.email_identity_hash then
    raise exception 'Verified Auth identity does not match the approved Production candidate.';
  end if;
  select * into auth_user from auth.users where id = target_auth_user_id;
  if not found or auth_user.email_confirmed_at is null
    or encode(extensions.digest(lower(btrim(coalesce(auth_user.email, '')))::text, 'sha256'), 'hex')
      is distinct from candidate.email_identity_hash
    or (auth_user.raw_app_meta_data->>'provisioning_scope')
      is distinct from 'production_shadow_director_certification'
    or (auth_user.raw_app_meta_data->>'player_id') is distinct from candidate.player_id
    or (auth_user.raw_app_meta_data->>'tournament_id') is distinct from candidate.tournament_id then
    raise exception 'Verified Auth identity does not match the approved Production identity.';
  end if;
  if not exists (
    select 1
    from participant_identity.participant_identity_contacts contact
    join participant_identity.identity_context_revisions context_revision
      on context_revision.tournament_id = contact.tournament_id
      and context_revision.context_revision = contact.configuration_revision
      and context_revision.configuration_fingerprint = candidate.identity_source_fingerprint
    join participant_identity.identity_config_import_runs import_run
      on import_run.tournament_id = contact.tournament_id
      and import_run.configuration_revision = contact.configuration_revision
      and import_run.source_fingerprint = candidate.identity_source_fingerprint
      and import_run.status = 'APPROVED' and import_run.approved_at is not null
    where contact.tournament_id = candidate.tournament_id
      and contact.player_id = candidate.player_id
      and contact.identity_active
      and contact.source_workbook_id = candidate.source_workbook_id
      and encode(extensions.digest(contact.email_normalized::text, 'sha256'), 'hex')
        = candidate.email_identity_hash
  ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_AUTH_CERTIFICATION_APPROVED_IDENTITY_REQUIRED';
  end if;
  if attempt.status = 'VERIFIED' then
    if candidate.status <> 'VERIFIED'
      or not exists (select 1 from participant_identity.user_player_links
        where auth_user_id = target_auth_user_id and player_id = attempt.player_id
          and email_identity_hash = candidate.email_identity_hash and status = 'ACTIVE')
      or not exists (select 1 from participant_identity.participant_auth_identifiers
        where auth_user_id = target_auth_user_id and player_id = attempt.player_id
          and identifier_type = 'EMAIL' and status = 'VERIFIED'
          and encode(extensions.digest(normalized_value_private::text, 'sha256'), 'hex')
            = candidate.email_identity_hash) then
      raise exception 'Previously verified Production Auth certification has drifted.';
    end if;
    return jsonb_build_object('ok', true, 'status', 'VERIFIED', 'duplicate', true,
      'recovered', recovery, 'requestId', target_request_id);
  end if;
  if attempt.status <> 'SENT' then
    raise exception 'OTP request is not awaiting verification.';
  end if;
  if candidate.status = 'PREPARED' then
    if not exists (select 1 from participant_identity.user_player_links
        where auth_user_id = target_auth_user_id and player_id = attempt.player_id
          and email_identity_hash = candidate.email_identity_hash and status = 'PENDING')
      or not exists (select 1 from participant_identity.participant_auth_identifiers
        where auth_user_id = target_auth_user_id and player_id = attempt.player_id
          and identifier_type = 'EMAIL' and status = 'VERIFICATION_PENDING'
          and encode(extensions.digest(normalized_value_private::text, 'sha256'), 'hex')
            = candidate.email_identity_hash) then
      raise exception 'The approved Production identity is not awaiting physical verification.';
    end if;
  elsif not exists (select 1 from participant_identity.user_player_links
      where auth_user_id = target_auth_user_id and player_id = attempt.player_id
        and email_identity_hash = candidate.email_identity_hash and status = 'ACTIVE')
    or not exists (select 1 from participant_identity.participant_auth_identifiers
      where auth_user_id = target_auth_user_id and player_id = attempt.player_id
        and identifier_type = 'EMAIL' and status = 'VERIFIED'
        and encode(extensions.digest(normalized_value_private::text, 'sha256'), 'hex')
          = candidate.email_identity_hash) then
    raise exception 'The verified Production identity has drifted.';
  end if;
  update participant_identity.participant_auth_otp_attempts set
    status = 'VERIFIED', safe_reason = 'SESSION_ESTABLISHED',
    verification_duration_ms = greatest(0, coalesce(target_duration_ms, 0)),
    verified_at = coalesce(verified_at, now()), updated_at = now()
  where request_id = target_request_id and status = 'SENT';
  if not found then raise exception 'OTP request certification lost its exact state.'; end if;
  if candidate.status = 'PREPARED' then
    update participant_identity.production_auth_candidates set
      status = 'VERIFIED', verified_at = now(),
      certification_revision = certification_revision + 1,
      updated_at = now()
    where tournament_id = attempt.tournament_id and auth_user_id = target_auth_user_id
      and player_id = attempt.player_id and status = 'PREPARED';
    if not found then raise exception 'Production Auth candidate certification lost its exact state.'; end if;
    update participant_identity.user_player_links set
      status = 'ACTIVE', linked_at = now(),
      linked_by = 'step10b-production-auth-certification',
      link_revision = link_revision + 1, updated_at = now()
    where auth_user_id = target_auth_user_id and player_id = attempt.player_id
      and email_identity_hash = candidate.email_identity_hash and status = 'PENDING';
    if not found then raise exception 'Production Auth Player link certification lost its exact state.'; end if;
    update participant_identity.participant_auth_identifiers set
      status = 'VERIFIED', verified_at = now(),
      verification_source = 'PRODUCTION_EMAIL_OTP',
      revision = revision + 1,
      updated_by = 'step10b-production-auth-certification', updated_at = now()
    where auth_user_id = target_auth_user_id and player_id = attempt.player_id
      and identifier_type = 'EMAIL' and status = 'VERIFICATION_PENDING'
      and encode(extensions.digest(normalized_value_private::text, 'sha256'), 'hex')
        = candidate.email_identity_hash;
    if not found then raise exception 'The approved Production email identifier is unavailable.'; end if;
  end if;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_name, request_id, safe_metadata
  ) values (
    'PRODUCTION_AUTH_CERTIFIED', attempt.tournament_id, attempt.auth_user_id,
    attempt.player_id, 'step10b-production-auth-certification', target_request_id::text,
    jsonb_build_object('result', 'VERIFIED', 'recovered', recovery,
      'candidateActivated', candidate.status = 'PREPARED',
      'otpStored', false, 'identityAuthorityChanged', false)
  );
  return jsonb_build_object('ok', true, 'status', 'VERIFIED', 'duplicate', false,
    'recovered', recovery, 'requestId', target_request_id);
end;
$$;


ALTER FUNCTION production_control.certify_production_auth_candidate_otp(target_request_id uuid, target_auth_user_id uuid, target_duration_ms integer, recovery boolean) OWNER TO postgres;

--
-- Name: certify_production_future_participant_otp_v1(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certify_production_future_participant_otp_v1(target_request_id uuid, target_auth_user_id uuid, target_duration_ms integer, recovery boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  attempt participant_identity.participant_auth_otp_attempts%rowtype;
  auth_user auth.users%rowtype;
  link participant_identity.user_player_links%rowtype;
  identifier participant_identity.participant_auth_identifiers%rowtype;
  binding participant_identity.future_tournament_participant_bindings_v1%rowtype;
  normalized text;
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  select value.* into attempt
  from participant_identity.participant_auth_otp_attempts value
  where value.request_id = target_request_id
    and value.tournament_id = target_id
  for update;
  if not found or attempt.auth_user_id is distinct from target_auth_user_id then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PARTICIPANT_OTP_IDENTITY_MISMATCH';
  end if;
  select value.* into auth_user
  from auth.users value
  where value.id = target_auth_user_id;
  select value.* into link
  from participant_identity.user_player_links value
  where value.auth_user_id = target_auth_user_id
    and value.player_id = attempt.player_id
  for update;
  select value.* into identifier
  from participant_identity.participant_auth_identifiers value
  where value.auth_user_id = target_auth_user_id
    and value.player_id = attempt.player_id
    and value.identifier_type = 'EMAIL'
    and value.status in ('VERIFICATION_PENDING', 'VERIFIED')
  for update;
  select value.* into binding
  from participant_identity.future_tournament_participant_bindings_v1 value
  where value.tournament_id = target_id
    and value.player_id = attempt.player_id
    and value.contact_state = 'APPROVED'
  for update;
  normalized := pg_catalog.lower(pg_catalog.btrim(coalesce(
    auth_user.email, ''
  )));
  if auth_user.id is null or auth_user.email_confirmed_at is null
     or link.link_id is null or link.status not in ('PENDING', 'ACTIVE')
     or link.revoked_at is not null
     or identifier.identifier_id is null
     or identifier.revoked_at is not null
     or binding.player_id is null
     or not exists (
       select 1
       from scoring_authority.tournament_players membership
       join participant_identity.participant_identity_contacts contact
         on contact.tournament_id = membership.tournament_id
        and contact.player_id = membership.player_id
        and contact.identity_active
        and contact.email_normalized = normalized
       where membership.tournament_id = target_id
         and membership.player_id = attempt.player_id
         and membership.participation_status = 'ACTIVE'
     )
     or encode(extensions.digest(normalized::text, 'sha256'), 'hex')
       <> attempt.email_identity_hash
     or identifier.normalized_value_private <> normalized
     or (attempt.verification_type = 'signup' and (
       link.status <> 'PENDING'
       or identifier.status <> 'VERIFICATION_PENDING'
       or binding.enrollment_state <> 'NOT_ENROLLED'
       or auth_user.raw_app_meta_data->>'provisioning_scope'
         <> 'production_controlled_first_login'
       or auth_user.raw_app_meta_data->>'player_id' <> attempt.player_id
       or auth_user.raw_app_meta_data->>'tournament_id' <> target_id
     ))
     or (attempt.verification_type = 'email' and (
       link.status <> 'ACTIVE'
       or identifier.status <> 'VERIFIED'
       or binding.enrollment_state <> 'ENROLLED'
     ))
     or attempt.verification_type not in ('email', 'signup') then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PARTICIPANT_VERIFIED_IDENTITY_MISMATCH';
  end if;
  if attempt.status = 'VERIFIED' then
    if link.status <> 'ACTIVE'
       or identifier.status <> 'VERIFIED'
       or binding.enrollment_state <> 'ENROLLED' then
      raise exception using errcode = 'P0001',
        message = 'PRODUCTION_PARTICIPANT_VERIFICATION_DRIFT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'status', 'VERIFIED', 'duplicate', true,
      'recovered', recovery
    );
  end if;
  if attempt.status <> 'SENT' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PARTICIPANT_OTP_NOT_AWAITING_VERIFICATION';
  end if;
  update participant_identity.participant_auth_otp_attempts set
    status = 'VERIFIED', safe_reason = 'SESSION_ESTABLISHED',
    verification_duration_ms = greatest(0, coalesce(
      target_duration_ms, 0
    )),
    verified_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where request_id = target_request_id and status = 'SENT';
  update participant_identity.user_player_links set
    status = 'ACTIVE',
    linked_at = coalesce(linked_at, pg_catalog.clock_timestamp()),
    linked_by = coalesce(
      linked_by, 'future-runtime-production-email-otp-v1'
    ),
    link_revision = link_revision + case
      when status = 'ACTIVE' then 0 else 1 end,
    updated_at = pg_catalog.clock_timestamp()
  where link_id = link.link_id;
  update participant_identity.participant_auth_identifiers set
    status = 'VERIFIED',
    verified_at = coalesce(verified_at, pg_catalog.clock_timestamp()),
    verification_source = 'PRODUCTION_EMAIL_OTP',
    revision = revision + case
      when status = 'VERIFIED' then 0 else 1 end,
    updated_by = 'future-runtime-production-email-otp-v1',
    updated_at = pg_catalog.clock_timestamp()
  where identifier_id = identifier.identifier_id;
  perform production_control.enroll_future_participant_identity_link_v1(
    target_id, attempt.player_id, target_auth_user_id
  );
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id,
    actor_name, request_id, safe_metadata
  ) values (
    'FUTURE_TOURNAMENT_PARTICIPANT_AUTH_VERIFIED', target_id,
    target_auth_user_id, attempt.player_id,
    'future-runtime-production-email-otp-v1',
    target_request_id::text,
    pg_catalog.jsonb_build_object(
      'result', 'VERIFIED', 'recovered', recovery,
      'otpStored', false, 'globalLinkReused', true
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'status', 'VERIFIED', 'duplicate', false,
    'recovered', recovery
  );
end;
$$;


ALTER FUNCTION production_control.certify_production_future_participant_otp_v1(target_request_id uuid, target_auth_user_id uuid, target_duration_ms integer, recovery boolean) OWNER TO postgres;

--
-- Name: certify_production_participant_otp(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.certify_production_participant_otp(target_request_id uuid, target_auth_user_id uuid, target_duration_ms integer, recovery boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $$
declare attempt participant_identity.participant_auth_otp_attempts%rowtype;
declare auth_user auth.users%rowtype;
declare link participant_identity.user_player_links%rowtype;
declare identifier participant_identity.participant_auth_identifiers%rowtype;
begin
  perform production_control.assert_production_participant_identity_cutover();
  select * into attempt from participant_identity.participant_auth_otp_attempts
    where request_id = target_request_id for update;
  if not found or attempt.auth_user_id is distinct from target_auth_user_id then
    raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_OTP_IDENTITY_MISMATCH';
  end if;
  select * into auth_user from auth.users where id = target_auth_user_id;
  select * into link from participant_identity.user_player_links
    where auth_user_id = target_auth_user_id and player_id = attempt.player_id for update;
  select * into identifier from participant_identity.participant_auth_identifiers
    where auth_user_id = target_auth_user_id and player_id = attempt.player_id
      and identifier_type = 'EMAIL' and status in ('VERIFICATION_PENDING','VERIFIED') for update;
  if auth_user.email_confirmed_at is null or link.link_id is null or identifier.identifier_id is null
     or encode(extensions.digest(lower(btrim(coalesce(auth_user.email, '')))::text, 'sha256'), 'hex')
       <> attempt.email_identity_hash
     or identifier.normalized_value_private <> lower(btrim(auth_user.email))
     or auth_user.raw_app_meta_data->>'player_id' <> attempt.player_id
     or auth_user.raw_app_meta_data->>'tournament_id' <> '2026'
     or auth_user.raw_app_meta_data->>'provisioning_scope' not in (
       'production_controlled_first_login','production_shadow_director_certification'
     ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_VERIFIED_IDENTITY_MISMATCH';
  end if;
  if attempt.status = 'VERIFIED' then
    if link.status <> 'ACTIVE' or identifier.status <> 'VERIFIED' then
      raise exception using errcode = 'P0001', message = 'PRODUCTION_PARTICIPANT_VERIFICATION_DRIFT';
    end if;
    return jsonb_build_object('ok', true, 'status', 'VERIFIED', 'duplicate', true,
      'recovered', recovery);
  end if;
  if attempt.status <> 'SENT' then
    raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_OTP_NOT_AWAITING_VERIFICATION';
  end if;
  update participant_identity.participant_auth_otp_attempts set
    status = 'VERIFIED', safe_reason = 'SESSION_ESTABLISHED',
    verification_duration_ms = greatest(0, coalesce(target_duration_ms, 0)),
    verified_at = now(), updated_at = now()
  where request_id = target_request_id and status = 'SENT';
  update participant_identity.user_player_links set
    status = 'ACTIVE', linked_at = coalesce(linked_at, now()),
    linked_by = coalesce(linked_by, 'production-email-otp'),
    link_revision = link_revision + case when status = 'ACTIVE' then 0 else 1 end,
    updated_at = now()
  where link_id = link.link_id;
  update participant_identity.participant_auth_identifiers set
    status = 'VERIFIED', verified_at = coalesce(verified_at, now()),
    verification_source = 'PRODUCTION_EMAIL_OTP',
    revision = revision + case when status = 'VERIFIED' then 0 else 1 end,
    updated_by = 'production-email-otp', updated_at = now()
  where identifier_id = identifier.identifier_id;
  insert into participant_identity.tournament_roles (
    tournament_id, auth_user_id, role, role_active, granted_by
  ) values ('2026', target_auth_user_id, 'PARTICIPANT', true, 'production-email-otp')
  on conflict (tournament_id, auth_user_id, role) do update set
    role_active = true, revoked_at = null, revoked_by = null,
    role_revision = participant_identity.tournament_roles.role_revision + 1,
    updated_at = now();
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_name, request_id, safe_metadata
  ) values (
    'PRODUCTION_PARTICIPANT_AUTH_VERIFIED', '2026', target_auth_user_id,
    attempt.player_id, 'production-email-otp', target_request_id::text,
    jsonb_build_object('result', 'VERIFIED', 'recovered', recovery, 'otpStored', false)
  );
  return jsonb_build_object('ok', true, 'status', 'VERIFIED', 'duplicate', false,
    'recovered', recovery);
end;
$$;


ALTER FUNCTION production_control.certify_production_participant_otp(target_request_id uuid, target_auth_user_id uuid, target_duration_ms integer, recovery boolean) OWNER TO postgres;

--
-- Name: clear_stage_provenance_on_reset(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.clear_stage_provenance_on_reset() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  -- ROLLED_BACK still has authenticated cleanup/fence-removal work to finish,
  -- so retain the binding there. Only a complete return to DORMANT starts a
  -- new certifiable staging lifecycle.
  if new.state = 'DORMANT' then
    new.staged_request_fingerprint := null;
    new.staged_payload_hash := null;
    new.staged_certification_fingerprint := null;
    new.staged_environment_delta_fingerprint_v2 := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.clear_stage_provenance_on_reset() OWNER TO postgres;

--
-- Name: close_annual_scoring_predecessor_pre_derived_workers_v1(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.close_annual_scoring_predecessor_pre_derived_workers_v1(input jsonb, target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  legacy_root production_control.scoring_admission_closures%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(
    input#>>'{authorization,player_id}'
  ));
  close_fingerprint text := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-annual-scoring-transition-v1',
      'operationRequestId', input->>'operation_request_id',
      'requestPayloadHash', input->>'request_payload_hash',
      'stage', 'CLOSE_PREDECESSOR'
    )
  );
  close_input jsonb;
  high_watermark bigint;
  unresolved integer;
  response_value jsonb;
begin
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION')then
    return production_control.close_certification_annual_predecessor_v1(input,target_tournament_id);
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  if pointer.tournament_id <> target_tournament_id
     or input->>'expected_current_tournament_id' is distinct from
       pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision
     or coalesce(input->>'start_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'final_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'reconciliation_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or not exists (
       select 1 from scoring_authority.matches value
       where value.tournament_id = pointer.tournament_id
     )
     or exists (
       select 1 from scoring_authority.matches value
       where value.tournament_id = pointer.tournament_id
         and (value.status <> 'FINAL' or not value.scorecard_complete
           or value.unresolved_mutations <> 0)
     ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_NOT_CLOSEABLE';
  end if;

  if pointer.tournament_id = '2026' then
    select value.* into strict activation
    from production_control.cutover_activation_state value
    where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
    select value.* into strict gate
    from scoring_authority.ingress_gates value
    where value.tournament_id = '2026' for update;
    if coalesce((input->>'expected_platform_activation_revision')::bigint, -1)
         <> activation.activation_revision
       or input->>'expected_platform_authority_generation_id'
         is distinct from activation.authority_generation_id::text
       or input->>'expected_platform_admission_generation_id'
         is distinct from gate.admission_generation_id::text
       or coalesce((input->>'expected_platform_admission_revision')::bigint, -1)
         <> gate.admission_revision then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_REVISION_CONFLICT';
    end if;
    close_input := input || pg_catalog.jsonb_build_object(
      'actor_id', actor_player,
      'expected_authority', 'SUPABASE',
      'expected_activation_revision', activation.activation_revision,
      'expected_authority_generation', activation.authority_generation_id,
      'expected_admission_generation', gate.admission_generation_id,
      'expected_admission_revision', gate.admission_revision,
      'request_fingerprint', close_fingerprint
    );
    return public.close_production_scoring_admission(close_input);
  end if;

  select value.* into strict annual
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = pointer.tournament_id for update;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.runtime_generation_id = annual.runtime_generation_id
    and value.generation_status = 'ACTIVE' for update;
  select value.* into strict legacy_root
  from production_control.scoring_admission_closures value
  where value.closure_id = annual.legacy_root_closure_id;
  if input->>'expected_predecessor_runtime_generation_id' is distinct from
       generation.runtime_generation_id::text
     or input->>'expected_predecessor_annual_authority_generation_id'
       is distinct from
       annual.authority_generation_id::text
     or input->>'expected_predecessor_annual_admission_generation_id'
       is distinct from
       annual.admission_generation_id::text
     or coalesce(
       (input->>'expected_predecessor_annual_admission_revision')::bigint, -1
     )
       <> annual.admission_revision
     or annual.authority_status <> 'ACTIVE'
     or annual.admission_state <> 'OPEN'
     or annual.active_closure_id is not null
     or generation.admission_generation_id is distinct from
       annual.admission_generation_id then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_REVISION_CONFLICT';
  end if;
  select coalesce(pg_catalog.max(value.admission_sequence), 0)
    into high_watermark
  from scoring_authority.scoring_ingress_leases value
  where value.tournament_id = pointer.tournament_id
    and value.admission_generation_id = annual.admission_generation_id;
  insert into production_control.scoring_admission_closures (
    closure_kind, prior_legacy_closure_id, tournament_id, authority,
    authority_generation_id, admission_generation_id, deployment_id,
    status, opening_admission_revision, closing_admission_revision,
    lease_high_watermark, start_source_fingerprint,
    external_fence_evidence_id, google_writer_provider_fence_id,
    google_writer_provider_verification_id, close_request_fingerprint,
    close_payload_hash, actor_id
  ) values (
    'SUPABASE_INGRESS', legacy_root.closure_id, pointer.tournament_id,
    'SUPABASE', annual.authority_generation_id,
    annual.admission_generation_id, legacy_root.deployment_id,
    'CLOSING', annual.admission_revision, annual.admission_revision + 1,
    high_watermark, pg_catalog.lower(input->>'start_source_fingerprint'),
    legacy_root.external_fence_evidence_id,
    legacy_root.google_writer_provider_fence_id,
    legacy_root.google_writer_provider_verification_id,
    close_fingerprint,
    production_control.future_runtime_hash_v2(
      input - 'request_payload_hash'
    ), actor_player
  ) returning * into closure;
  update scoring_authority.scoring_ingress_leases set
    close_fence_id = closure.closure_id
  where tournament_id = pointer.tournament_id
    and admission_generation_id = annual.admission_generation_id
    and resolution_state in (
      'ADMITTED', 'WRITE_STARTED', 'AMBIGUOUS', 'PARTIAL_WRITE',
      'LEGACY_UNCLASSIFIED'
    );
  unresolved := production_control.annual_scoring_unresolved_count_v1(
    pointer.tournament_id, annual.admission_generation_id
  );
  update production_control.annual_scoring_runtime_authorities_v1 set
    admission_state = 'CLOSING',
    admission_revision = admission_revision + 1,
    active_closure_id = closure.closure_id,
    updated_at = pg_catalog.clock_timestamp()
  where runtime_generation_id = annual.runtime_generation_id;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_CLOSING',
    'closure_id', closure.closure_id,
    'authority_generation_id', annual.authority_generation_id,
    'admission_generation_id', annual.admission_generation_id,
    'admission_revision', annual.admission_revision + 1,
    'admission_state', 'CLOSING',
    'active_or_unresolved_leases', unresolved,
    'lease_high_watermark', closure.lease_high_watermark,
    'idempotent', false
  );
  return response_value;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_SCORING_PREDECESSOR_REVISION_CONFLICT';
end;
$_$;


ALTER FUNCTION production_control.close_annual_scoring_predecessor_pre_derived_workers_v1(input jsonb, target_tournament_id text) OWNER TO postgres;

--
-- Name: close_annual_scoring_predecessor_v1(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.close_annual_scoring_predecessor_v1(input jsonb, target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  competition_unresolved integer;
  intelligence_unresolved integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  if production_control.score_derived_intents_pending_v1(target_tournament_id) then
    raise exception using errcode = '55000', message = 'SCORE_DERIVED_INTENTS_DRAIN_REQUIRED';
  end if;
  select pg_catalog.count(*)::integer into competition_unresolved
  from scoring_authority.competition_recalculation_jobs value
  where value.tournament_id = target_tournament_id
    and value.round_number = 0
    and value.engine_key in ('TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES')
    and value.status <> 'SUCCEEDED';
  select pg_catalog.count(*)::integer into intelligence_unresolved
  from scoring_authority.competition_recalculation_jobs value
  where value.tournament_id = target_tournament_id
    and value.round_number = 0
    and value.engine_key in (
      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
      'TOURNAMENT_FINAL_RECAP'
    )
    and value.status <> 'SUCCEEDED';
  if competition_unresolved + intelligence_unresolved <> 0 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_PREDECESSOR_DERIVED_WORK_PENDING';
  end if;
  return production_control
    .close_annual_scoring_predecessor_pre_derived_workers_v1(
      input, target_tournament_id
    );
end;
$$;


ALTER FUNCTION production_control.close_annual_scoring_predecessor_v1(input jsonb, target_tournament_id text) OWNER TO postgres;

--
-- Name: close_certification_annual_predecessor_v1(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.close_certification_annual_predecessor_v1(input jsonb, target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c jsonb:=production_control.annual_resource_context_v2();e jsonb;revisions jsonb;source_hash text;
 g production_control.certification_ingress_generations_v1%rowtype;
 o production_control.certification_initialization_origins_v1%rowtype;
 a production_control.annual_scoring_runtime_authorities_v1%rowtype;
 closed production_control.scoring_admission_closures%rowtype;prior_closure uuid;
begin
 if c->>'resource_class' is distinct from 'CERTIFICATION' or c->>'phase' is distinct from 'ANNUAL'
  or c->>'current_tournament_id' is distinct from target_tournament then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CONTEXT_REQUIRED';end if;
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 select * into strict o from production_control.certification_initialization_origins_v1 where resource_id=c->>'resource_id';
 select * into strict g from production_control.certification_ingress_generations_v1
 where resource_id=o.resource_id and tournament_id=target_tournament and state='OPEN' for update;
 if input->>'expected_certification_admission_generation_id' is distinct from g.generation_id::text
  or input->>'expected_certification_admission_revision' is distinct from g.revision::text
  or g.authority_epoch_id::text is distinct from c->>'authority_epoch_id'
  or g.pointer_revision::text is distinct from c->>'pointer_revision' then
  raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_GENERATION_STALE';end if;
 if not exists(select 1 from scoring_authority.matches where tournament_id=target_tournament)
  or exists(select 1 from scoring_authority.matches where tournament_id=target_tournament
   and(status<>'FINAL' or not scorecard_complete or unresolved_mutations<>0))then
  raise exception using errcode='55000',message='PREDECESSOR_FINAL_SCORING_FACTS_REQUIRED';end if;
 if target_tournament<>o.initial_tournament_id then
  select * into strict a from production_control.annual_scoring_runtime_authorities_v1 where tournament_id=target_tournament for update;
  if a.resource_class<>'CERTIFICATION' or a.certification_resource_id<>o.resource_id
   or a.authority_status<>'ACTIVE' or a.admission_state<>'OPEN'
   or a.admission_generation_id<>g.generation_id or a.authority_generation_id<>g.authority_epoch_id
   or a.pointer_revision<>g.pointer_revision then
   raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_GENERATION_STALE';end if;

  declare ancestor production_control.scoring_admission_closures%rowtype;
   parent_generation production_control.certification_ingress_generations_v1%rowtype;
   child_generation production_control.certification_ingress_generations_v1%rowtype;
   cursor_id uuid;seen uuid[]:=array[]::uuid[];lineage_valid boolean:=false;
  begin
   child_generation:=g;
   select closure_id into strict prior_closure from production_control.scoring_admission_closures
    where resource_class='CERTIFICATION' and certification_resource_id=o.resource_id
     and admission_generation_id=g.predecessor_generation_id;
   cursor_id:=prior_closure;
   loop
    if cursor_id is null or cursor_id=any(seen)then exit;end if;
    seen:=array_append(seen,cursor_id);
    select * into ancestor from production_control.scoring_admission_closures where closure_id=cursor_id;
    if ancestor.closure_id is null or ancestor.resource_class is distinct from'CERTIFICATION'
     or ancestor.certification_resource_id is distinct from o.resource_id
     or ancestor.boundary_mode is distinct from'CERTIFICATION_INGRESS_V1'
     or ancestor.closure_kind is distinct from'SUPABASE_INGRESS'
     or ancestor.authority is distinct from'SUPABASE' then exit;end if;
    select * into parent_generation from production_control.certification_ingress_generations_v1
     where resource_id=o.resource_id and generation_id=ancestor.admission_generation_id;
    if parent_generation.generation_id is null or parent_generation.state is distinct from'CLOSED'
     or child_generation.predecessor_generation_id is distinct from parent_generation.generation_id
     or ancestor.tournament_id is distinct from parent_generation.tournament_id
     or ancestor.authority_generation_id is distinct from parent_generation.authority_epoch_id
     or ancestor.closed_admission_revision is distinct from parent_generation.revision
     or ancestor.lease_high_watermark is distinct from parent_generation.high_watermark
     or ancestor.lease_set_fingerprint is distinct from parent_generation.lease_fingerprint then exit;end if;
    if ancestor.closure_id=a.predecessor_closure_id then
     -- Existing Certification ACTIVATE retains CLOSED. Its exact COMMITTED
     -- annual transition proves consumption; do not invent a status rewrite.
     lineage_valid:=ancestor.status in('CLOSED','CONSUMED')
      and ancestor.tournament_id=a.predecessor_tournament_id and ancestor.tournament_id<>target_tournament
      and parent_generation.pointer_revision=g.pointer_revision-1
      and exists(select 1 from production_control.annual_scoring_transitions_v1 t
       where t.resource_class='CERTIFICATION' and t.certification_resource_id=o.resource_id
        and t.runtime_generation_id=a.runtime_generation_id and t.transition_status='COMMITTED'
        and t.predecessor_closure_id=a.predecessor_closure_id
        and t.predecessor_tournament_id=a.predecessor_tournament_id
        and t.predecessor_boundary_fingerprint=a.predecessor_boundary_fingerprint
        and t.successor_tournament_id=target_tournament
        and t.expected_pointer_revision=g.pointer_revision-1
        and t.authority_generation_id=g.authority_epoch_id);
     exit;
    end if;
    if ancestor.status is distinct from'REOPENED' or ancestor.tournament_id is distinct from target_tournament
     or parent_generation.authority_epoch_id is distinct from g.authority_epoch_id
     or parent_generation.pointer_revision is distinct from g.pointer_revision then exit;end if;
    child_generation:=parent_generation;
    cursor_id:=ancestor.prior_certification_closure_id;
   end loop;
   if not coalesce(lineage_valid,false)then raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_LINEAGE_REQUIRED'; end if;
  end;

 elsif g.predecessor_generation_id is not null then
  select closure_id into strict prior_closure from production_control.scoring_admission_closures
   where certification_resource_id=o.resource_id and admission_generation_id=g.predecessor_generation_id;
 end if;
 revisions:=production_control.current_match_revisions(target_tournament);
 source_hash:=production_control.future_runtime_hash_v2(revisions);
 e:=production_control.close_certification_ingress_generation_v1(o.resource_id,g.generation_id,g.revision);
 insert into production_control.scoring_admission_closures(resource_class,certification_resource_id,closure_kind,boundary_mode,prior_certification_closure_id,
  tournament_id,authority,authority_generation_id,admission_generation_id,deployment_id,status,opening_admission_revision,
  closing_admission_revision,lease_high_watermark,start_source_fingerprint,google_checkpoints,close_request_fingerprint,close_payload_hash,actor_id)
 values('CERTIFICATION',o.resource_id,'SUPABASE_INGRESS','CERTIFICATION_INGRESS_V1',prior_closure,target_tournament,'SUPABASE',g.authority_epoch_id,g.generation_id,
  c->>'deployment_id','CLOSING',g.revision,(e->>'generation_revision')::bigint,(e->>'captured_high_watermark')::bigint,source_hash,'{}',
  production_control.future_runtime_hash_v2(jsonb_build_object('resource_id',o.resource_id,'generation_id',g.generation_id,
   'operation_request_id',input->>'operation_request_id')),production_control.future_runtime_hash_v2(input-'request_payload_hash'),
  c#>>'{authorization,player_id}') returning * into closed;
 update scoring_authority.ingress_gates set state='PAUSED',updated_by=c#>>'{authorization,player_id}',updated_at=clock_timestamp()
 where tournament_id=target_tournament and authority='SUPABASE' and active_epoch_id=g.authority_epoch_id;
 if not found then raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_GENERATION_STALE';end if;
 if a.runtime_generation_id is not null then
  update production_control.annual_scoring_runtime_authorities_v1 set admission_state='CLOSING',active_closure_id=closed.closure_id,
   admission_revision=admission_revision+1,updated_at=clock_timestamp() where runtime_generation_id=a.runtime_generation_id;
 end if;
 return jsonb_build_object('closure_id',closed.closure_id,'active_or_unresolved_leases',
  (e->>'active_count')::bigint+(e->>'unknown_count')::bigint,'certification_ingress',e);
end;$$;


ALTER FUNCTION production_control.close_certification_annual_predecessor_v1(input jsonb, target_tournament text) OWNER TO postgres;

--
-- Name: close_certification_ingress_generation_v1(text, uuid, bigint); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.close_certification_ingress_generation_v1(target_resource_id text, target_generation_id uuid, expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare g production_control.certification_ingress_generations_v1%rowtype;e jsonb;
begin
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 select * into strict g from production_control.certification_ingress_generations_v1 where resource_id=target_resource_id and generation_id=target_generation_id for update;
 if g.revision<>expected_revision then raise exception using errcode='40001',message='CERTIFICATION_INGRESS_GENERATION_STALE';end if;
 e:=production_control.certification_ingress_evidence_v1(target_resource_id,target_generation_id);
 if g.state='CLOSED'then
  if not(e->>'fingerprint_matches')::boolean or not(e->>'drained')::boolean then raise exception using errcode='55000',message='CERTIFICATION_INGRESS_CLOSED_EVIDENCE_INVALID';end if;
  return e;end if;
 if g.state='OPEN'then
  update production_control.certification_ingress_generations_v1 set state='CLOSING',revision=revision+1,
   closing_revision=revision+1,high_watermark=(e->>'high_watermark')::bigint
   where resource_id=target_resource_id and generation_id=target_generation_id returning * into g;
 end if;
 e:=production_control.certification_ingress_evidence_v1(target_resource_id,target_generation_id);
 if(e->>'drained')::boolean then
  update production_control.certification_ingress_generations_v1 set state='CLOSED',lease_fingerprint=e->>'fingerprint',closed_at=clock_timestamp()
   where resource_id=target_resource_id and generation_id=target_generation_id;
 end if;
 return production_control.certification_ingress_evidence_v1(target_resource_id,target_generation_id);
end;$$;


ALTER FUNCTION production_control.close_certification_ingress_generation_v1(target_resource_id text, target_generation_id uuid, expected_revision bigint) OWNER TO postgres;

--
-- Name: current_annual_odds_inputs_before_pairing_context_v1(text, text, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_annual_odds_inputs_before_pairing_context_v1(target text, destination_workbook text, input jsonb, require_exact_revision boolean DEFAULT true) RETURNS scoring_authority.odds_input_configurations
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  config scoring_authority.odds_input_configurations%rowtype;
  revision jsonb := input->'source_revision';
begin
  select value.* into strict config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target and value.is_current;
  if target = '2026'
     or config.source_workbook_id is distinct from destination_workbook
     or config.validation_status is distinct from 'VALID'
     or config.settings_contract_version is distinct from
       'prediction-settings-v1'
     or coalesce(config.source_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or config.settings_fingerprint !~ '^[0-9a-f]{64}$'
     or config.effective_settings_fingerprint !~ '^[0-9a-f]{64}$'
     or config.bundle_fingerprint !~ '^[0-9a-f]{64}$'
     or config.ratings_fingerprint !~ '^[0-9a-f]{64}$'
     or config.pairing_fingerprint !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(config.effective_settings) <> 'object'
     or scoring_authority.jsonb_object_length(
       config.effective_settings
     ) <> 30 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_PREDICTION_SETTINGS_NOT_CURRENT';
  end if;
  if require_exact_revision and (
    pg_catalog.jsonb_typeof(revision) <> 'object'
    or input->>'input_configuration_id' is distinct from config.id::text
    or coalesce((input->>'configuration_revision')::bigint, -1)
      <> config.configuration_revision
    or pg_catalog.lower(coalesce(input->>'settings_fingerprint', ''))
      is distinct from config.settings_fingerprint
    or pg_catalog.lower(coalesce(
      input->>'effective_settings_fingerprint', ''
    )) is distinct from config.effective_settings_fingerprint
    or pg_catalog.lower(coalesce(input->>'input_bundle_fingerprint', ''))
      is distinct from config.bundle_fingerprint
    or pg_catalog.lower(coalesce(revision->>'source_fingerprint', ''))
      is distinct from pg_catalog.lower(config.source_fingerprint)
    or pg_catalog.lower(coalesce(revision->>'bundle_fingerprint', ''))
      is distinct from config.bundle_fingerprint
    or pg_catalog.lower(coalesce(revision->>'settings_fingerprint', ''))
      is distinct from config.settings_fingerprint
    or pg_catalog.lower(coalesce(
      revision->>'effective_settings_fingerprint', ''
    )) is distinct from config.effective_settings_fingerprint
    or pg_catalog.lower(coalesce(revision->>'ratings_fingerprint', ''))
      is distinct from config.ratings_fingerprint
    or pg_catalog.lower(coalesce(revision->>'pairing_fingerprint', ''))
      is distinct from config.pairing_fingerprint
    or coalesce((revision->>'configuration_revision')::bigint, -1)
      <> config.configuration_revision
    or revision->>'annual_tournament_id' is distinct from target
    or revision->>'annual_runtime_generation_id' is distinct from
      input->>'expected_runtime_generation_id'
    or coalesce((revision->>'annual_pointer_revision')::bigint, -1)
      <> coalesce((input->>'expected_pointer_revision')::bigint, -2)
    or revision->>'annual_authority_generation_id' is distinct from
      input->>'expected_annual_authority_generation_id'
    or revision->>'annual_admission_generation_id' is distinct from
      input->>'expected_annual_admission_generation_id'
  ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ANNUAL_ODDS_INPUT_REVISION_STALE';
  end if;
  return config;
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_ODDS_INPUT_CONFIGURATION_REQUIRED';
end;
$_$;


ALTER FUNCTION production_control.current_annual_odds_inputs_before_pairing_context_v1(target text, destination_workbook text, input jsonb, require_exact_revision boolean) OWNER TO postgres;

--
-- Name: current_annual_odds_inputs_v1(text, text, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_annual_odds_inputs_v1(target text, destination_workbook text, input jsonb, require_exact_revision boolean DEFAULT true) RETURNS scoring_authority.odds_input_configurations
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  config scoring_authority.odds_input_configurations%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
begin
  config := production_control
    .current_annual_odds_inputs_before_pairing_context_v1(
      target, destination_workbook, input, require_exact_revision
    );
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target;
  if config.pairing_fingerprint is distinct from production_control
       .annual_odds_pairing_fingerprint_v1(target)
     or coalesce((config.validation_diagnostics->>
       'annualSetupRevision')::bigint, -1) <> catalog.setup_revision then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_PREDICTION_SETTINGS_NOT_CURRENT';
  end if;
  return config;
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_PREDICTION_SETTINGS_NOT_CURRENT';
end;
$$;


ALTER FUNCTION production_control.current_annual_odds_inputs_v1(target text, destination_workbook text, input jsonb, require_exact_revision boolean) OWNER TO postgres;

--
-- Name: current_canonical_odds_inputs_v2(text, text, jsonb, boolean, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_canonical_odds_inputs_v2(target text, destination text, input jsonb, exact_revision boolean, context jsonb) RETURNS scoring_authority.odds_input_configurations
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c scoring_authority.odds_input_configurations%rowtype;catalog production_control.future_tournament_catalog_v1%rowtype;
begin
 if context is null then return production_control.current_annual_odds_inputs_v1(target,destination,input,exact_revision);end if;
 c:=production_control.canonical_odds_inputs_v2(target,destination,input,exact_revision,context);
 if exact_revision and(input#>>'{source_revision,certification_odds_contract}'is distinct from 'certification-odds-v1'
  or input#>>'{source_revision,resource_id}'is distinct from context->>'resource_id'
  or input#>>'{source_revision,installation_id}'is distinct from context->>'installation_id'
  or input#>>'{source_revision,certification_ingress_generation_id}'is distinct from input->>'certification_ingress_generation_id')then
  raise exception using errcode='40001',message='CERTIFICATION_ODDS_INPUT_REVISION_STALE';end if;
 if target<>'2026'then
  select * into strict catalog from production_control.future_tournament_catalog_v1 where tournament_id=target;
  if c.validation_diagnostics->>'certificationStructuralContract'is distinct from'certification-odds-pairing-structure-v1'
   or c.validation_diagnostics->>'certificationStructuralFingerprint'is distinct from production_control.certification_odds_pairing_structure_fingerprint_v1(target)
   or coalesce((c.validation_diagnostics->>'certificationStructuralSetupRevision')::bigint,-1)<>catalog.setup_revision
   or coalesce((c.validation_diagnostics->>'annualSetupRevision')::bigint,-1)<>catalog.setup_revision then
   raise exception using errcode='55000',message='PRODUCTION_ANNUAL_PREDICTION_SETTINGS_NOT_CURRENT';end if;
 end if;return c;
end;$$;


ALTER FUNCTION production_control.current_canonical_odds_inputs_v2(target text, destination text, input jsonb, exact_revision boolean, context jsonb) OWNER TO postgres;

--
-- Name: current_canonical_resource_context_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_canonical_resource_context_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype; c jsonb;
 s production_control.resource_scope%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;
 a production_control.cutover_activation_state%rowtype;
begin
 select * into strict r from production_control.canonical_resource_v1 where singleton;
 if r.resource_class='CERTIFICATION' then
  c:=production_control.current_certification_context_v1();
  if c->>'resource_id' is distinct from r.resource_id or r.database_name<>current_database() then
   raise exception using errcode='42501',message='CERTIFICATION_DOMAIN_CONTEXT_REQUIRED';end if;
  select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=r.resource_id;
  return c||jsonb_build_object('provenance_id',r.provenance_id,'installation_id',r.installation_id,
   'schema_digest',r.schema_digest,'manifest_digest',r.manifest_digest,'lifecycle_revision',p.lifecycle_revision);
 end if;
 -- Only explicit new callers use this rich Production projection. Unchanged
 -- Production triggers retain their original early-return queries below.
 select * into strict s from production_control.resource_scope where scope_key=r.resource_id;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=r.resource_id;
 select * into strict a from production_control.cutover_activation_state where scope_key=r.resource_id;
 return to_jsonb(s)||jsonb_build_object('resource_id',r.resource_id,'resource_class','PRODUCTION',
  'installation_id',r.installation_id,'provenance_id',r.provenance_id,'schema_digest',r.schema_digest,
  'manifest_digest',r.manifest_digest,'current_tournament_id',p.tournament_id,'tournament_id',p.tournament_id,
  'current_tournament_year',p.tournament_year,'pointer_revision',p.pointer_revision,'lifecycle_revision',p.lifecycle_revision,
  'governance_tournament_id',s.current_tournament_id,'activation_revision',a.activation_revision,
  'authority_epoch_id',a.authority_generation_id);
end;$$;


ALTER FUNCTION production_control.current_canonical_resource_context_v1() OWNER TO postgres;

--
-- Name: current_certification_context_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_certification_context_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare marker production_control.canonical_operation_context_v1%rowtype; context jsonb;
begin
  select * into marker from production_control.canonical_operation_context_v1
    where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
  if not found then raise exception using errcode='42501',message='CANONICAL_RESOURCE_CONTEXT_REQUIRED'; end if;
  context:=production_control.assert_certification_context_v1(marker.validated_request,marker.phase,marker.mutation);
  if context is distinct from marker.context then
    raise exception using errcode='PT409',message='CANONICAL_RESOURCE_CONTEXT_STALE';
  end if;
  return context;
end;
$$;


ALTER FUNCTION production_control.current_certification_context_v1() OWNER TO postgres;

--
-- Name: current_google_checkpoints(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_google_checkpoints(target_tournament_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'scoring_authority'
    AS $$
  select coalesce(
    jsonb_object_agg(
      match_value.match_id,
      jsonb_build_object(
        'last_supabase_match_revision', checkpoint.last_supabase_match_revision,
        'google_match_revision', checkpoint.google_match_revision,
        'google_hole_revisions', checkpoint.google_hole_revisions,
        'verified_fingerprint', checkpoint.verified_fingerprint
      ) order by match_value.match_id
    ),
    '{}'::jsonb
  )
  from scoring_authority.matches match_value
  left join scoring_authority.google_match_checkpoints checkpoint
    on checkpoint.match_id = match_value.match_id
  where match_value.tournament_id = target_tournament_id
$$;


