--
-- Name: current_production_odds_inputs(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_production_odds_inputs(input jsonb) RETURNS scoring_authority.odds_input_configurations
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  config scoring_authority.odds_input_configurations%rowtype;
  source_revision jsonb := input->'source_revision';
begin
  select * into strict config
  from scoring_authority.odds_input_configurations
  where tournament_id = '2026' and is_current;

  if config.source_workbook_id
       is distinct from '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or config.validation_status is distinct from 'VALID'
     or config.settings_contract_version is distinct from 'prediction-settings-v1'
     or coalesce(config.source_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or coalesce(config.settings_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or coalesce(config.effective_settings_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or coalesce(config.bundle_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or coalesce(config.ratings_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or coalesce(config.pairing_fingerprint, '') !~ '^[0-9a-f]{64}$'
     or coalesce(jsonb_typeof(config.effective_settings), '') <> 'object'
     or scoring_authority.jsonb_object_length(config.effective_settings) <> 30 then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_PREDICTION_SETTINGS_NOT_CURRENT';
  end if;

  if jsonb_typeof(source_revision) <> 'object'
     or input->>'input_configuration_id' is distinct from config.id::text
     or coalesce((input->>'configuration_revision')::bigint, -1)
          <> config.configuration_revision
     or lower(coalesce(input->>'settings_fingerprint', ''))
          <> config.settings_fingerprint
     or lower(coalesce(input->>'effective_settings_fingerprint', ''))
          <> config.effective_settings_fingerprint
     or lower(coalesce(input->>'input_bundle_fingerprint', ''))
          <> config.bundle_fingerprint
     or lower(coalesce(source_revision->>'source_fingerprint', ''))
          is distinct from lower(config.source_fingerprint)
     or lower(coalesce(source_revision->>'bundle_fingerprint', ''))
          is distinct from lower(config.bundle_fingerprint)
     or lower(coalesce(source_revision->>'settings_fingerprint', ''))
          is distinct from lower(config.settings_fingerprint)
     or lower(coalesce(source_revision->>'effective_settings_fingerprint', ''))
          is distinct from lower(config.effective_settings_fingerprint)
     or lower(coalesce(source_revision->>'ratings_fingerprint', ''))
          is distinct from lower(config.ratings_fingerprint)
     or lower(coalesce(source_revision->>'pairing_fingerprint', ''))
          is distinct from lower(config.pairing_fingerprint)
     or coalesce((source_revision->>'configuration_revision')::bigint, -1)
          <> config.configuration_revision then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_ODDS_INPUT_REVISION_STALE';
  end if;
  return config;
exception when no_data_found then
  raise exception using errcode = 'P0001',
    message = 'PRODUCTION_ODDS_INPUT_CONFIGURATION_REQUIRED';
end;
$_$;


ALTER FUNCTION production_control.current_production_odds_inputs(input jsonb) OWNER TO postgres;

--
-- Name: current_tournament_shadow_projection(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_tournament_shadow_projection(target_tournament text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'tournament', coalesce((
      select to_jsonb(tournament) - 'created_at' - 'updated_at' - 'imported_at'
      from scoring_authority.tournaments tournament
      where tournament.tournament_id = target_tournament
    ), '{}'::jsonb),
    'teams', coalesce((
      select jsonb_agg(to_jsonb(team) order by team.team_side, team.team_id)
      from scoring_authority.teams team where team.tournament_id = target_tournament
    ), '[]'::jsonb),
    'tournament_players', coalesce((
      select jsonb_agg(to_jsonb(roster) - 'created_at' - 'updated_at' order by roster.team_side, roster.source_roster_key, roster.player_id)
      from scoring_authority.tournament_players roster where roster.tournament_id = target_tournament
    ), '[]'::jsonb),
    'rounds', coalesce((
      select jsonb_agg(to_jsonb(round_value) order by round_value.round_number)
      from scoring_authority.rounds round_value where round_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'snapshots', coalesce((
      select jsonb_agg(to_jsonb(snapshot) - 'imported_at' order by snapshot.match_id, snapshot.snapshot_revision)
      from scoring_authority.scoring_snapshots snapshot where snapshot.tournament_id = target_tournament
    ), '[]'::jsonb),
    'matches', coalesce((
      select jsonb_agg(to_jsonb(match_value) order by match_value.round_number, match_value.match_id)
      from scoring_authority.matches match_value where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'match_participants', coalesce((
      select jsonb_agg(to_jsonb(participant) order by participant.match_id, participant.team_side, participant.player_slot)
      from scoring_authority.match_participants participant
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'permissions', coalesce((
      select jsonb_agg(to_jsonb(permission) - 'updated_at' order by permission.match_id, permission.player_id)
      from scoring_authority.scoring_permissions permission
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'match_holes', coalesce((
      select jsonb_agg(to_jsonb(hole) order by hole.match_id, hole.hole_number)
      from scoring_authority.match_holes hole
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'hole_scores', coalesce((
      select jsonb_agg(to_jsonb(score) - 'created_at' - 'updated_at' order by score.match_id, score.hole_number)
      from scoring_authority.hole_scores score
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'checkpoints', coalesce((
      select jsonb_agg(to_jsonb(checkpoint) - 'updated_at' order by checkpoint.match_id)
      from scoring_authority.google_match_checkpoints checkpoint
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'ingress', coalesce((
      select to_jsonb(gate) - 'updated_at'
      from scoring_authority.ingress_gates gate where gate.tournament_id = target_tournament
    ), '{}'::jsonb)
  );
$$;


ALTER FUNCTION production_control.current_tournament_shadow_projection(target_tournament text) OWNER TO postgres;

--
-- Name: current_tournament_shadow_semantic_projection_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.current_tournament_shadow_semantic_projection_v1(target_tournament text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  with revision as (
    select value.*
    from production_control.current_shadow_revisions value
    where value.tournament_id = target_tournament
    order by value.imported_at desc
    limit 1
  )
  select pg_catalog.jsonb_build_object(
    'contract_version',
      'production-current-shadow-semantic-parity-v1',
    'tournament', coalesce((
      select pg_catalog.jsonb_build_object(
        'tournament_id', tournament.tournament_id,
        'tournament_year', tournament.tournament_year,
        'name', tournament.name,
        'source_workbook_id', tournament.source_workbook_id,
        'scoring_authority', pg_catalog.upper(tournament.scoring_authority),
        'lifecycle', pg_catalog.upper(coalesce(
          (select value.current_context->>'lifecycle' from revision value), ''
        )),
        'current_round', coalesce(
          ((select value.current_context->>'current_round'
            from revision value))::integer, 0
        ),
        'team_1_score', coalesce(
          ((select value.current_context->>'team_1_score'
            from revision value))::numeric, 0
        ),
        'team_2_score', coalesce(
          ((select value.current_context->>'team_2_score'
            from revision value))::numeric, 0
        ),
        'live_message', coalesce(
          (select value.current_context->>'live_message' from revision value), ''
        )
      )
      from scoring_authority.tournaments tournament
      where tournament.tournament_id = target_tournament
    ), '{}'::jsonb),
    'players', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'player_id', player.player_id,
          'display_name', player.display_name,
          'slug', coalesce(player.source_payload->>'Slug', ''),
          'active', coalesce(player.source_payload->>'Active', '')
        ) order by player.player_id collate "C"
      )
      from scoring_authority.players player
    ), '[]'::jsonb),
    'teams', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'tournament_id', team.tournament_id,
          'team_id', team.team_id,
          'team_side', team.team_side,
          'name', team.name,
          'captain_player_id', coalesce(team.source_payload->>'Captain', '')
        ) order by team.team_side, team.team_id collate "C"
      )
      from scoring_authority.teams team
      where team.tournament_id = target_tournament
    ), '[]'::jsonb),
    'tournament_players', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'tournament_id', roster.tournament_id,
          'player_id', roster.player_id,
          'team_id', roster.team_id,
          'team_side', roster.team_side,
          'participation_status', pg_catalog.upper(
            roster.participation_status
          ),
          'source_roster_key', roster.source_roster_key,
          'tournament_handicap', nullif(
            pg_catalog.btrim(coalesce(
              roster.source_payload->>'Tournament Handicap', ''
            )), ''
          )::numeric
        ) order by roster.team_side, roster.player_id collate "C"
      )
      from scoring_authority.tournament_players roster
      where roster.tournament_id = target_tournament
    ), '[]'::jsonb),
    'rounds', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'tournament_id', round_value.tournament_id,
          'round_number', round_value.round_number,
          'format', pg_catalog.upper(round_value.format),
          'name', round_value.name,
          'handicap_allowance', round_value.handicap_allowance,
          'status', pg_catalog.upper(round_value.status)
        ) order by round_value.round_number
      )
      from scoring_authority.rounds round_value
      where round_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'rules', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'tournament_id', rule->>'tournament_id',
          'round_number', (rule->>'round_number')::integer,
          'format', pg_catalog.upper(rule->>'format'),
          'points_available', (rule->>'points_available')::numeric
        ) order by (rule->>'round_number')::integer
      )
      from revision value
      cross join lateral pg_catalog.jsonb_array_elements(
        value.tournament_rules
      ) rule
    ), '[]'::jsonb),
    'pairing_state', coalesce((
      select pg_catalog.upper(value.pairing_state) from revision value
    ), ''),
    'identity_reconciliation', coalesce((
      select pg_catalog.jsonb_build_object(
        'current_only_player_ids', coalesce((
          select pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'player_id', item->>'player_id',
              'player_source_present',
                (item->>'player_source_present')::boolean,
              'roster_source_present',
                (item->>'roster_source_present')::boolean
            ) order by item->>'player_id' collate "C"
          )
          from pg_catalog.jsonb_array_elements(
            value.identity_reconciliation->'current_only_player_ids'
          ) item
        ), '[]'::jsonb),
        'historical_appearances_inferred',
          (value.identity_reconciliation
            ->>'historical_appearances_inferred')::boolean,
        'join_key', value.identity_reconciliation->>'join_key',
        'missing_player_source_ids', coalesce((
          select pg_catalog.jsonb_agg(identifier order by identifier collate "C")
          from (
            select distinct identifier
            from pg_catalog.jsonb_array_elements_text(
              value.identity_reconciliation->'missing_player_source_ids'
            ) as identifiers_source(identifier)
          ) identifiers
        ), '[]'::jsonb),
        'unresolved_current_only_ids', coalesce((
          select pg_catalog.jsonb_agg(identifier order by identifier collate "C")
          from (
            select distinct identifier
            from pg_catalog.jsonb_array_elements_text(
              value.identity_reconciliation->'unresolved_current_only_ids'
            ) as identifiers_source(identifier)
          ) identifiers
        ), '[]'::jsonb)
      ) from revision value
    ), '{}'::jsonb),
    'snapshots', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'snapshot_id', snapshot.snapshot_id,
          'tournament_id', snapshot.tournament_id,
          'match_id', snapshot.match_id,
          'snapshot_revision', snapshot.snapshot_revision,
          'scoring_rules_version', snapshot.scoring_rules_version,
          'format', pg_catalog.upper(snapshot.format),
          'handicap_allowance', snapshot.handicap_allowance,
          'course_id', snapshot.course_id,
          'tee', snapshot.tee,
          'rating', snapshot.rating,
          'slope', snapshot.slope,
          'par', snapshot.par,
          'match_netting_baseline', snapshot.match_netting_baseline,
          'hole_definitions', snapshot.hole_definitions,
          'participant_configuration', snapshot.participant_configuration,
          'team_configuration', snapshot.team_configuration
        ) order by snapshot.snapshot_id collate "C"
      )
      from scoring_authority.scoring_snapshots snapshot
      where snapshot.tournament_id = target_tournament
    ), '[]'::jsonb),
    'matches', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'match_id', match_value.match_id,
          'tournament_id', match_value.tournament_id,
          'round_number', match_value.round_number,
          'format', pg_catalog.upper(match_value.format),
          'scoring_snapshot_id', match_value.scoring_snapshot_id,
          'status', pg_catalog.upper(match_value.status),
          'scoring_locked', match_value.scoring_locked,
          'permission_revision', match_value.permission_revision,
          'match_revision', match_value.match_revision,
          'source_google_revision', match_value.source_google_revision,
          'scored_holes', match_value.scored_holes,
          'current_hole', match_value.current_hole,
          'holes_remaining', match_value.holes_remaining,
          'team_1_holes_won', match_value.team_1_holes_won,
          'team_2_holes_won', match_value.team_2_holes_won,
          'running_result', match_value.running_result,
          'result_winner', match_value.result_winner,
          'clinched', match_value.clinched,
          'scorecard_complete', match_value.scorecard_complete,
          'unresolved_mutations', match_value.unresolved_mutations,
          'finalized_at', case when match_value.finalized_at is null
            then null
            else pg_catalog.to_char(
              match_value.finalized_at at time zone 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
            )
          end
        ) order by match_value.match_id collate "C"
      )
      from scoring_authority.matches match_value
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'match_participants', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'match_id', participant.match_id,
          'player_id', participant.player_id,
          'team_side', participant.team_side,
          'player_slot', participant.player_slot,
          'handicap_index', participant.handicap_index,
          'course_handicap', participant.course_handicap,
          'playing_handicap', participant.playing_handicap,
          'final_strokes', participant.final_strokes
        ) order by participant.match_id collate "C",
          participant.team_side, participant.player_slot,
          participant.player_id collate "C"
      )
      from scoring_authority.match_participants participant
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'permissions', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'match_id', permission.match_id,
          'player_id', permission.player_id,
          'can_score', permission.can_score,
          'permission_revision', permission.permission_revision,
          'revoked_at', case when permission.revoked_at is null
            then null
            else pg_catalog.to_char(
              permission.revoked_at at time zone 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
            )
          end
        ) order by permission.match_id collate "C",
          permission.player_id collate "C"
      )
      from scoring_authority.scoring_permissions permission
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'match_holes', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'match_id', hole.match_id,
          'hole_number', hole.hole_number,
          'snapshot_id', hole.snapshot_id,
          'stroke_index', hole.stroke_index,
          'par', hole.par,
          'yardage', hole.yardage
        ) order by hole.match_id collate "C", hole.hole_number
      )
      from scoring_authority.match_holes hole
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'hole_scores', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'match_id', score.match_id,
          'hole_number', score.hole_number,
          'hole_revision', score.hole_revision,
          'team_1_gross_scores', score.team_1_gross_scores,
          'team_2_gross_scores', score.team_2_gross_scores,
          'team_1_strokes', score.team_1_strokes,
          'team_2_strokes', score.team_2_strokes,
          'team_1_net_score', score.team_1_net_score,
          'team_2_net_score', score.team_2_net_score,
          'hole_winner', score.hole_winner,
          'source_google_revision', score.source_google_revision,
          'mutation_key', score.mutation_key,
          'actor_id', score.actor_id
        ) order by score.match_id collate "C", score.hole_number
      )
      from scoring_authority.hole_scores score
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb),
    'checkpoints', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'match_id', checkpoint.match_id,
          'last_supabase_match_revision',
            checkpoint.last_supabase_match_revision,
          'google_match_revision', checkpoint.google_match_revision,
          'google_hole_revisions', checkpoint.google_hole_revisions
        ) order by checkpoint.match_id collate "C"
      )
      from scoring_authority.google_match_checkpoints checkpoint
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION production_control.current_tournament_shadow_semantic_projection_v1(target_tournament text) OWNER TO postgres;

--
-- Name: cutover_payload_hash(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.cutover_payload_hash(input jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'extensions'
    AS $$
  select encode(extensions.digest(input::text, 'sha256'), 'hex')
$$;


ALTER FUNCTION production_control.cutover_payload_hash(input jsonb) OWNER TO postgres;

--
-- Name: cutover_phase_rank(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.cutover_phase_rank(phase_value text) RETURNS integer
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
  select case upper(btrim(coalesce(phase_value, '')))
    when 'STATIC_BACKEND' then 0 when 'READ_CUTOVER' then 1
    when 'IDENTITY' then 2 when 'CURRENT_READS' then 3
    when 'SCORING_PREPARE' then 4 when 'SCORING_COMMIT' then 5
    when 'WORKERS' then 6 when 'ODDS_WAR_ROOM' then 7
    when 'OBSERVATION' then 8 else -1 end
$$;


ALTER FUNCTION production_control.cutover_phase_rank(phase_value text) OWNER TO postgres;

--
-- Name: derived_delivery_delay_v1(integer, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.derived_delivery_delay_v1(attempt integer, identity_value text) RETURNS interval
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 select make_interval(secs=>least(300,power(2,greatest(1,least(5,attempt)))::integer
   + (get_byte(extensions.digest(coalesce(identity_value,''),'sha256'),0)%3)))
$$;


ALTER FUNCTION production_control.derived_delivery_delay_v1(attempt integer, identity_value text) OWNER TO postgres;

--
-- Name: derived_delivery_retryable_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.derived_delivery_retryable_v1(code text) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
 select upper(coalesce(code,'')) ~ '^(40001|40P01|57014|55P03|08[A-Z0-9]{3})$'
   or upper(coalesce(code,'')) ~ '(TIMEOUT|CONNECTION|TRANSPORT|FETCH_FAILED|LEASE_EXPIRED|ABORTERROR|TIMEOUTERROR)'
$_$;


ALTER FUNCTION production_control.derived_delivery_retryable_v1(code text) OWNER TO postgres;

--
-- Name: derived_final_recap_ready_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.derived_final_recap_ready_v1(target text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare match_count integer; complete boolean;
begin
 select count(*),bool_and(status='FINAL' and scorecard_complete) into match_count,complete
 from scoring_authority.matches where tournament_id=target;
 if match_count<>24 or not coalesce(complete,false) then return false; end if;
 return exists(select 1 from scoring_authority.odds_published_snapshots
  where tournament_id=target and milestone='Final Results' and is_current_for_milestone and publication_verified
    and published_payload->>'phase'='Final Results');
end;
$$;


ALTER FUNCTION production_control.derived_final_recap_ready_v1(target text) OWNER TO postgres;

--
-- Name: director_calcutta_management_projection_v1(text, bigint); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.director_calcutta_management_projection_v1(target text, predecessor bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'tournament_id', target,
    'state', coalesce(c.state, 'NOT_CONFIGURED'),
    'publication_state', coalesce(c.publication_state, 'UNPUBLISHED'),
    'configuration_revision', coalesce(c.configuration_revision, 0),
    'configuration_revision_id', c.configuration_revision_id,
    'configuration_fingerprint', c.configuration_fingerprint,
    'auction_revision', coalesce(c.auction_revision, 0),
    'auction_revision_id', c.auction_revision_id,
    'auction_fingerprint', c.auction_fingerprint,
    'publication_revision', coalesce(c.publication_revision, 0),
    'currency_code', coalesce(cfg.configuration_manifest->>'currency_code', 'USD'),
    'configured_at', cfg.configured_at,
    'point_structure', coalesce((select jsonb_agg(jsonb_build_object('place', (r->>'place')::int,
      'round_1_award', r->>'round_1_award', 'round_2_award', r->>'round_2_award', 'round_3_award', r->>'round_3_award') order by (r->>'place')::int)
      from jsonb_array_elements(cfg.configuration_manifest->'point_structure') r), '[]'::jsonb),
    'payout_structure', coalesce((select jsonb_agg(jsonb_build_object('place', (r->>'place')::int,
      'round_1_fraction', r->>'round_1_fraction', 'round_2_fraction', r->>'round_2_fraction',
      'round_3_fraction', r->>'round_3_fraction', 'overall_fraction', r->>'overall_fraction') order by (r->>'place')::int)
      from jsonb_array_elements(cfg.configuration_manifest->'payout_structure') r), '[]'::jsonb),
    'purchases', coalesce((select jsonb_agg(jsonb_build_object('player_id', r->>'player_id', 'purchase_price', r->>'purchase_price') order by r->>'player_id') from jsonb_array_elements(a.auction_manifest->'purchases') r), '[]'::jsonb),
    'ownership', coalesce((select jsonb_agg(jsonb_build_object('player_id', r->>'player_id', 'owner_player_id', r->>'owner_player_id', 'ownership_fraction', r->>'ownership_fraction') order by r->>'player_id', r->>'owner_player_id') from jsonb_array_elements(a.auction_manifest->'ownership') r), '[]'::jsonb),
    'predecessor_auction_revision', predecessor,
    'predecessor_auction_fingerprint', base.auction_fingerprint,
    'predecessor_purchases', coalesce((select jsonb_agg(jsonb_build_object('player_id', r->>'player_id', 'purchase_price', r->>'purchase_price') order by r->>'player_id') from jsonb_array_elements(base.auction_manifest->'purchases') r), '[]'::jsonb),
    'predecessor_ownership', coalesce((select jsonb_agg(jsonb_build_object('player_id', r->>'player_id', 'owner_player_id', r->>'owner_player_id', 'ownership_fraction', r->>'ownership_fraction') order by r->>'player_id', r->>'owner_player_id') from jsonb_array_elements(base.auction_manifest->'ownership') r), '[]'::jsonb),
    'players', coalesce((select jsonb_agg(jsonb_build_object(
      'player_id', p.player_id, 'display_name', p.display_name) order by p.display_name, p.player_id)
      from scoring_authority.tournament_players tp join scoring_authority.players p using(player_id)
      where tp.tournament_id = target and tp.participation_status = 'ACTIVE'), '[]'::jsonb)
  ) from (select target as tournament_id) t
  left join scoring_authority.calcutta_v1_current c using(tournament_id)
  left join scoring_authority.calcutta_v1_configuration_revisions cfg
    on cfg.configuration_revision_id = c.configuration_revision_id and cfg.tournament_id = target
  left join scoring_authority.calcutta_v1_auction_fact_revisions a
    on a.auction_revision_id = c.auction_revision_id and a.tournament_id = target
  left join scoring_authority.calcutta_v1_auction_fact_revisions base
    on base.tournament_id = target and base.auction_revision = predecessor and predecessor <= c.auction_revision;
$$;


ALTER FUNCTION production_control.director_calcutta_management_projection_v1(target text, predecessor bigint) OWNER TO postgres;

--
-- Name: director_private_audit_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.director_private_audit_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
  with event_rows as (
    select audit.created_at occurred_at,
      'MATCH'::text category,
      case audit.action
        when 'MATCH_MARKED_LIVE' then 'MARK_LIVE'
        when 'SCORING_ACCESS_ACTIVATED' then 'ACCESS_ACTIVATED'
        when 'SCORING_ACCESS_REVOKED' then 'ACCESS_REVOKED'
        when 'SCORING_LOCKED' then 'LOCK_SCORING'
        when 'SCORING_UNLOCKED' then 'UNLOCK_SCORING'
        when 'MATCH_FINALIZED' then 'FINALIZE_MATCH'
        else 'REOPEN_MATCH'
      end action,
      case audit.action
        when 'MATCH_MARKED_LIVE' then pg_catalog.format(
          'Round %s · Match %s marked Live', match_value.round_number,
          coalesce(nullif(presentation.display_match_number, ''), 'current')
        )
        when 'SCORING_ACCESS_ACTIVATED' then pg_catalog.format(
          'Round %s · Match %s scoring access activated',
          match_value.round_number,
          coalesce(nullif(presentation.display_match_number, ''), 'current')
        )
        when 'SCORING_ACCESS_REVOKED' then pg_catalog.format(
          'Round %s · Match %s scoring access revoked',
          match_value.round_number,
          coalesce(nullif(presentation.display_match_number, ''), 'current')
        )
        when 'SCORING_LOCKED' then pg_catalog.format(
          'Round %s · Match %s scoring locked', match_value.round_number,
          coalesce(nullif(presentation.display_match_number, ''), 'current')
        )
        when 'SCORING_UNLOCKED' then pg_catalog.format(
          'Round %s · Match %s scoring unlocked', match_value.round_number,
          coalesce(nullif(presentation.display_match_number, ''), 'current')
        )
        when 'MATCH_FINALIZED' then pg_catalog.format(
          'Round %s · Match %s finalized', match_value.round_number,
          coalesce(nullif(presentation.display_match_number, ''), 'current')
        )
        else pg_catalog.format(
          'Round %s · Match %s reopened', match_value.round_number,
          coalesce(nullif(presentation.display_match_number, ''), 'current')
        )
      end title,
      'Tournament match control was confirmed.'::text summary,
      'SUCCESS'::text status,
      coalesce(actor.display_name, 'Tournament Director') actor_name,
      match_value.round_number,
      nullif(presentation.display_match_number, '') display_match_number
    from scoring_authority.audit_events audit
    join scoring_authority.matches match_value
      on match_value.match_id = audit.match_id
     and match_value.tournament_id = audit.tournament_id
    left join scoring_authority.game_center_presentations presentation
      on presentation.match_id = match_value.match_id
     and presentation.tournament_id = match_value.tournament_id
    left join scoring_authority.players actor
      on actor.player_id = audit.actor_id
    where audit.tournament_id = '2026'
      and audit.action in (
        'MATCH_MARKED_LIVE', 'SCORING_ACCESS_ACTIVATED',
        'SCORING_ACCESS_REVOKED', 'SCORING_LOCKED', 'SCORING_UNLOCKED',
        'MATCH_FINALIZED', 'MATCH_REOPENED'
      )
      and audit.created_at >= pg_catalog.now() - interval '90 days'

    union all

    select audit.created_at, 'HANDICAP', case audit.action
      when 'REVISION_STAGED' then 'STAGE_HANDICAP_REVISION'
      else 'APPROVE_HANDICAP_REVISION' end,
      pg_catalog.format(
        'Handicap Revision %s %s', revision.revision_number,
        case audit.action when 'REVISION_STAGED' then 'staged'
          else 'approved' end
      ),
      'The canonical tournament handicap revision was recorded.',
      'SUCCESS', coalesce(actor.display_name, 'Tournament Director'),
      null::integer, null::text
    from scoring_authority.handicap_audit_events audit
    join scoring_authority.handicap_revisions revision
      on revision.revision_id = audit.revision_id
    left join scoring_authority.players actor
      on actor.player_id = audit.actor_player_id
    where audit.tournament_id = '2026'
      and audit.action in ('REVISION_STAGED', 'REVISION_APPROVED')
      and audit.created_at >= pg_catalog.now() - interval '90 days'

    union all

    select audit.created_at,
      case
        when audit.domain in (
          'CHAMPIONSHIP_ODDS_CALCULATION',
          'CHAMPIONSHIP_ODDS_PUBLICATION'
        ) then 'ODDS'
        when audit.domain in ('NET_SKINS', 'CALCUTTA') then 'SIDE_GAME'
        when audit.domain in ('GUIDE', 'DRAFT', 'PREDICTION_SETTINGS')
          then 'SYNCHRONIZATION'
        else 'RELEASE'
      end,
      case audit.event_type
        when 'PRODUCTION_ODDS_CALCULATION_REQUESTED'
          then 'REQUEST_ODDS_CALCULATION'
        when 'PRODUCTION_ODDS_CALCULATION_SUCCEEDED'
          then 'COMPLETE_ODDS_CALCULATION'
        when 'PRODUCTION_CHAMPIONSHIP_ODDS_PUBLISHED'
          then 'PUBLISH_ODDS'
        when 'PRODUCTION_NET_SKINS_V1_CONFIGURED'
          then 'CONFIGURE_NET_SKINS'
        when 'PRODUCTION_NET_SKINS_V1_RECALCULATION_COMPLETED'
          then 'COMPLETE_NET_SKINS_RECALCULATION'
        when 'PRODUCTION_NET_SKINS_V1_RECALCULATION_FAILED'
          then 'FAIL_NET_SKINS_RECALCULATION'
        when 'PRODUCTION_CALCUTTA_V1_CONFIGURED'
          then 'CONFIGURE_CALCUTTA'
        when 'PRODUCTION_CALCUTTA_V1_AUCTION_REPLACED'
          then 'REPLACE_CALCUTTA_AUCTION'
        when 'PRODUCTION_CALCUTTA_V1_PUBLISHED'
          then 'PUBLISH_CALCUTTA'
        when 'PRODUCTION_CALCUTTA_V1_UNPUBLISHED'
          then 'UNPUBLISH_CALCUTTA'
        when 'PRODUCTION_CALCUTTA_V1_RECALCULATION_COMPLETED'
          then 'COMPLETE_CALCUTTA_RECALCULATION'
        when 'PRODUCTION_CALCUTTA_V1_RECALCULATION_FAILED'
          then 'FAIL_CALCUTTA_RECALCULATION'
        when 'PRODUCTION_DIRECTOR_PROJECTION_SYNCHRONIZED'
          then 'SYNCHRONIZE_PROJECTION'
        else 'DEPLOY_APPLICATION_RELEASE'
      end,
      case audit.event_type
        when 'PRODUCTION_ODDS_CALCULATION_REQUESTED'
          then 'Odds calculation requested'
        when 'PRODUCTION_ODDS_CALCULATION_SUCCEEDED'
          then 'Odds calculation completed'
        when 'PRODUCTION_CHAMPIONSHIP_ODDS_PUBLISHED'
          then pg_catalog.format('Odds Revision %s published',
            coalesce(nullif(audit.details->>'publication_revision', ''),
              'current'))
        when 'PRODUCTION_NET_SKINS_V1_CONFIGURED'
          then pg_catalog.format('Net Skins Revision %s configured',
            coalesce(nullif(audit.details->>'configuration_revision', ''),
              'current'))
        when 'PRODUCTION_NET_SKINS_V1_RECALCULATION_COMPLETED'
          then 'Net Skins recalculation completed'
        when 'PRODUCTION_NET_SKINS_V1_RECALCULATION_FAILED'
          then 'Net Skins recalculation stopped safely'
        when 'PRODUCTION_CALCUTTA_V1_CONFIGURED'
          then pg_catalog.format('Calcutta Revision %s configured',
            coalesce(nullif(audit.details->>'configuration_revision', ''),
              'current'))
        when 'PRODUCTION_CALCUTTA_V1_AUCTION_REPLACED'
          then pg_catalog.format('Calcutta Auction Revision %s recorded',
            coalesce(nullif(audit.details->>'auction_revision', ''),
              'current'))
        when 'PRODUCTION_CALCUTTA_V1_PUBLISHED'
          then 'Calcutta published to participants'
        when 'PRODUCTION_CALCUTTA_V1_UNPUBLISHED'
          then 'Calcutta unpublished from participants'
        when 'PRODUCTION_CALCUTTA_V1_RECALCULATION_COMPLETED'
          then 'Calcutta recalculation completed'
        when 'PRODUCTION_CALCUTTA_V1_RECALCULATION_FAILED'
          then 'Calcutta recalculation stopped safely'
        when 'PRODUCTION_DIRECTOR_PROJECTION_SYNCHRONIZED'
          then pg_catalog.format('%s Revision %s synchronized',
            case audit.domain
              when 'GUIDE' then 'Tournament Guide'
              when 'DRAFT' then 'Draft'
              else 'Prediction Settings' end,
            coalesce(nullif(audit.details->>'revisionNumber', ''), 'current'))
        else pg_catalog.format('Production application Release %s deployed',
          coalesce(nullif(audit.details->>'release_sequence', ''), 'current'))
      end,
      case
        when audit.event_type like '%FAILED'
          then 'The operation stopped safely without replacing current facts.'
        when audit.event_type = 'PRODUCTION_DIRECTOR_PROJECTION_SYNCHRONIZED'
          then 'The validated source revision is now current in Supabase.'
        when audit.event_type =
          'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_REBOUND'
          then 'The normal Production application release was bound.'
        else 'The bounded Production operation completed.'
      end,
      case when audit.event_type like '%FAILED' or audit.result <> 'SUCCEEDED'
        then 'FAILED' else 'SUCCESS' end,
      coalesce(actor.display_name, case
        when audit.domain in ('NET_SKINS', 'CALCUTTA',
          'CHAMPIONSHIP_ODDS_CALCULATION') then 'Background worker'
        else 'System' end),
      null::integer, null::text
    from production_control.operation_audit_events audit
    left join scoring_authority.players actor
      on actor.player_id = audit.actor
      or (
        audit.event_type = 'PRODUCTION_DIRECTOR_PROJECTION_SYNCHRONIZED'
        and audit.actor = 'Production Director ' || actor.player_id
      )
    where audit.tournament_id = '2026'
      and audit.created_at >= pg_catalog.now() - interval '90 days'
      and (
        (audit.domain = 'CHAMPIONSHIP_ODDS_CALCULATION'
          and audit.event_type in (
            'PRODUCTION_ODDS_CALCULATION_REQUESTED',
            'PRODUCTION_ODDS_CALCULATION_SUCCEEDED'
          ))
        or (audit.domain = 'CHAMPIONSHIP_ODDS_PUBLICATION'
          and audit.event_type = 'PRODUCTION_CHAMPIONSHIP_ODDS_PUBLISHED')
        or (audit.domain = 'NET_SKINS' and audit.event_type in (
          'PRODUCTION_NET_SKINS_V1_CONFIGURED',
          'PRODUCTION_NET_SKINS_V1_RECALCULATION_COMPLETED',
          'PRODUCTION_NET_SKINS_V1_RECALCULATION_FAILED'
        ))
        or (audit.domain = 'CALCUTTA' and audit.event_type in (
          'PRODUCTION_CALCUTTA_V1_CONFIGURED',
          'PRODUCTION_CALCUTTA_V1_AUCTION_REPLACED',
          'PRODUCTION_CALCUTTA_V1_PUBLISHED',
          'PRODUCTION_CALCUTTA_V1_UNPUBLISHED',
          'PRODUCTION_CALCUTTA_V1_RECALCULATION_COMPLETED',
          'PRODUCTION_CALCUTTA_V1_RECALCULATION_FAILED'
        ))
        or (audit.domain in ('GUIDE', 'DRAFT', 'PREDICTION_SETTINGS')
          and audit.event_type =
            'PRODUCTION_DIRECTOR_PROJECTION_SYNCHRONIZED')
        or (audit.domain = 'APPLICATION_RELEASE'
          and audit.event_type =
            'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_REBOUND')
      )
  ), bounded as (
    select pg_catalog.row_number() over (
      order by event_rows.occurred_at desc, event_rows.title
    )::integer sequence, event_rows.*
    from event_rows
    order by event_rows.occurred_at desc, event_rows.title
    limit 60
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'sequence', bounded.sequence,
    'category', bounded.category,
    'action', bounded.action,
    'title', bounded.title,
    'summary', bounded.summary,
    'status', bounded.status,
    'actor', pg_catalog.jsonb_build_object(
      'display_name', bounded.actor_name
    ),
    'context', pg_catalog.jsonb_build_object(
      'tournament_id', '2026',
      'round_number', bounded.round_number,
      'display_match_number', bounded.display_match_number
    ),
    'occurred_at', bounded.occurred_at
  ) order by bounded.occurred_at desc, bounded.sequence), '[]'::jsonb)
  from bounded
$$;


ALTER FUNCTION production_control.director_private_audit_v1() OWNER TO postgres;

--
-- Name: director_private_audit_with_access_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.director_private_audit_with_access_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
  with existing_rows as (
    select
      (item->>'occurred_at')::timestamptz occurred_at,
      coalesce(item->>'category', 'SYSTEM') category,
      coalesce(item->>'action', 'UPDATED') action,
      coalesce(item->>'title', 'Director operation completed') title,
      coalesce(item->>'summary', 'The operation was confirmed.') summary,
      coalesce(item->>'status', 'SUCCESS') status,
      coalesce(item#>>'{actor,display_name}', 'Tournament Director') actor_name,
      coalesce(item->'context', pg_catalog.jsonb_build_object(
        'tournament_id', '2026'
      )) context_value
    from pg_catalog.jsonb_array_elements(
      production_control.director_private_audit_v1()
    ) item
  ), access_rows as (
    select event.occurred_at,
      'ACCESS'::text category,
      event.action,
      case event.action
        when 'PLAYER_CREATED' then pg_catalog.format(
          '%s added as a global Player', target.display_name
        )
        when 'GLOBAL_STATUS_CHANGED' then pg_catalog.format(
          '%s global Player status changed', target.display_name
        )
        when 'MEMBERSHIP_WITHDRAWN' then pg_catalog.format(
          '%s withdrawn from the 2026 tournament', target.display_name
        )
        when 'MEMBERSHIP_REACTIVATED' then pg_catalog.format(
          '%s reactivated for the 2026 tournament', target.display_name
        )
        when 'DIRECTOR_GRANTED' then pg_catalog.format(
          '%s granted Tournament Director access', target.display_name
        )
        when 'DIRECTOR_REVOKED' then pg_catalog.format(
          '%s Tournament Director access revoked', target.display_name
        )
        else pg_catalog.format(
          '%s adopted Production Owner governance', target.display_name
        )
      end title,
      case event.action
        when 'PLAYER_CREATED'
          then 'The permanent Player record was created without tournament or Auth side effects.'
        when 'GLOBAL_STATUS_CHANGED'
          then 'The global status changed while history and identity were preserved.'
        when 'MEMBERSHIP_WITHDRAWN'
          then 'Tournament membership was withdrawn without rewriting competition facts.'
        when 'MEMBERSHIP_REACTIVATED'
          then 'Existing tournament membership was reactivated without setup side effects.'
        when 'DIRECTOR_GRANTED'
          then 'Owner-authorized Tournament Director access was granted.'
        when 'DIRECTOR_REVOKED'
          then 'Owner-authorized Tournament Director access was revoked.'
        else 'The initial Production Owner capability was adopted through the database-owner-only operation.'
      end summary,
      'SUCCESS'::text status,
      coalesce(actor.display_name, 'Tournament Director') actor_name,
      pg_catalog.jsonb_build_object('tournament_id', '2026') context_value
    from production_control.access_governance_audit_events_v1 event
    join scoring_authority.players target
      on target.player_id = event.target_player_id
    left join scoring_authority.players actor
      on actor.player_id = event.actor_player_id
    where event.tournament_id = '2026'
      and event.occurred_at >= pg_catalog.now() - interval '90 days'
  ), merged as (
    select * from existing_rows
    union all
    select * from access_rows
  ), bounded as (
    select pg_catalog.row_number() over (
      order by merged.occurred_at desc, merged.title
    )::integer sequence, merged.*
    from merged
    order by merged.occurred_at desc, merged.title
    limit 60
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'sequence', bounded.sequence,
    'category', bounded.category,
    'action', bounded.action,
    'title', bounded.title,
    'summary', bounded.summary,
    'status', bounded.status,
    'actor', pg_catalog.jsonb_build_object(
      'display_name', bounded.actor_name
    ),
    'context', bounded.context_value,
    'occurred_at', bounded.occurred_at
  ) order by bounded.occurred_at desc, bounded.sequence), '[]'::jsonb)
  from bounded
$$;


ALTER FUNCTION production_control.director_private_audit_with_access_v1() OWNER TO postgres;

--
-- Name: director_private_audit_with_draft_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.director_private_audit_with_draft_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  with existing_rows as (
    select
      (item->>'occurred_at')::timestamptz occurred_at,
      coalesce(item->>'category','SYSTEM') category,
      coalesce(item->>'action','UPDATED') action,
      coalesce(item->>'title','Director operation completed') title,
      coalesce(item->>'summary','The operation was confirmed.') summary,
      coalesce(item->>'status','SUCCESS') status,
      coalesce(item#>>'{actor,display_name}','Tournament Director') actor_name,
      coalesce(item->'context',pg_catalog.jsonb_build_object(
        'tournament_id','2026')) context_value
    from pg_catalog.jsonb_array_elements(
      production_control.director_private_audit_with_access_v1()) item
  ), draft_rows as (
    select event.created_at occurred_at,
      'DRAFT'::text category,event.action,
      case event.action
        when 'REVISION_STAGED' then pg_catalog.format(
          'Draft revision %s staged',event.summary->>'draftRevision')
        when 'REVISION_VALIDATED' then pg_catalog.format(
          'Draft revision %s validated',event.summary->>'draftRevision')
        when 'REVISION_COMMITTED' then coalesce(
          nullif(event.summary->>'summary',''),'Draft revision saved')
        when 'PICK_RECORDED' then coalesce(
          nullif(event.summary->>'summary',''),'Draft pick recorded')
        when 'PICK_CORRECTED' then coalesce(
          nullif(event.summary->>'summary',''),'Draft pick corrected')
        when 'DRAFT_COMPLETED' then coalesce(
          nullif(event.summary->>'summary',''),'Draft completed')
        when 'PREVIOUS_SETUP_COPIED' then pg_catalog.format(
          'Previous Draft setup copied to %s',event.tournament_id)
        else 'Draft operation completed'
      end title,
      case event.action
        when 'REVISION_STAGED'
          then 'Draft setup and picks were staged for Director review.'
        when 'REVISION_VALIDATED'
          then 'Draft setup and picks passed the canonical Draft checks.'
        when 'REVISION_COMMITTED'
          then 'The Supabase Draft revision became authoritative.'
        when 'PICK_RECORDED'
          then 'A Draft selection was recorded in the authoritative revision.'
        when 'PICK_CORRECTED'
          then 'A Draft selection was corrected before the Draft was frozen.'
        when 'DRAFT_COMPLETED'
          then 'The Draft became complete and ordinary editing was frozen.'
        when 'PREVIOUS_SETUP_COPIED'
          then 'Only prior-year Draft setup defaults were copied; no picks or selected Players were copied.'
        else 'The Draft operation completed.'
      end summary,
      'SUCCESS'::text status,
      coalesce(actor.display_name,'Tournament Director') actor_name,
      pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'tournament_id',event.tournament_id,
        'revision',case when event.action='REVISION_COMMITTED'
          then event.summary->'revision' else null end,
        'draft_revision',case when event.action<>'REVISION_COMMITTED'
          then event.summary->'draftRevision' else null end,
        'source_tournament_id',event.summary->'sourceTournamentId',
        'selected_pick_count',coalesce(
          event.summary->'selectedPickCount',event.summary->'selectedPicks'),
        'pick_number',event.summary->'pickNumber',
        'player_id',event.summary->'playerId',
        'team_id',event.summary->'teamId'
      )) context_value
    from production_control.draft_authoring_audit_events_v1 event
    left join scoring_authority.players actor
      on actor.player_id=event.actor_player_id
    where event.created_at>=pg_catalog.now()-interval '90 days'
  ), merged as (
    select * from existing_rows
    union all
    select * from draft_rows
  ), bounded as (
    select pg_catalog.row_number() over (
      order by merged.occurred_at desc,merged.title)::integer sequence,
      merged.*
    from merged
    order by merged.occurred_at desc,merged.title
    limit 60
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'sequence',bounded.sequence,'category',bounded.category,
    'action',bounded.action,'title',bounded.title,'summary',bounded.summary,
    'status',bounded.status,
    'actor',pg_catalog.jsonb_build_object('display_name',bounded.actor_name),
    'context',bounded.context_value,'occurred_at',bounded.occurred_at
  ) order by bounded.occurred_at desc,bounded.sequence),'[]'::jsonb)
  from bounded
$$;


ALTER FUNCTION production_control.director_private_audit_with_draft_v1() OWNER TO postgres;

--
-- Name: director_private_calcutta_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.director_private_calcutta_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.calcutta_v1_current%rowtype;
  configuration_value scoring_authority.calcutta_v1_configuration_revisions%rowtype;
  auction_value scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  publication_value scoring_authority.calcutta_v1_publication_revisions%rowtype;
  result_value scoring_authority.calcutta_v1_result_revisions%rowtype;
  source_fingerprint_value text;
  active_job boolean := false;
  configuration_view jsonb := null;
  auction_view jsonb := null;
  result_view jsonb := null;
  jobs_value jsonb := '[]'::jsonb;
  purchase_count integer := 0;
  owner_count integer := 0;
  unique_owner_count integer := 0;
  purchase_total numeric := 0;
  ownership_complete boolean := false;
  active_players_complete boolean := false;
  configuration_valid boolean := false;
  auction_valid boolean := false;
begin
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026';
  select value.* into strict configuration_value
  from scoring_authority.calcutta_v1_configuration_revisions value
  where value.configuration_revision_id =
    current_value.configuration_revision_id;

  if current_value.state <> 'NOT_CONFIGURED' then
    configuration_valid :=
      production_control.calcutta_v1_hash(
        configuration_value.configuration_manifest
      ) = current_value.configuration_fingerprint
      and pg_catalog.jsonb_array_length(
        configuration_value.configuration_manifest->'point_structure'
      ) > 0
      and pg_catalog.jsonb_array_length(
        configuration_value.configuration_manifest->'payout_structure'
      ) > 0
      and (
        select coalesce(pg_catalog.sum(
          (row_value->>'round_1_fraction')::numeric
          + (row_value->>'round_2_fraction')::numeric
          + (row_value->>'round_3_fraction')::numeric
          + (row_value->>'overall_fraction')::numeric
        ), 0)
        from pg_catalog.jsonb_array_elements(
          configuration_value.configuration_manifest->'payout_structure'
        ) row_value
      ) = 1;

    configuration_view := pg_catalog.jsonb_build_object(
      'revision', current_value.configuration_revision,
      'configured_at', configuration_value.configured_at,
      'validation_status', case when configuration_valid
        then 'VALIDATED' else 'ATTENTION' end,
      'currency_code', 'USD',
      'point_structure', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'place', (row_value->>'place')::integer,
          'round_1_award', (row_value->>'round_1_award')::numeric,
          'round_2_award', (row_value->>'round_2_award')::numeric,
          'round_3_award', (row_value->>'round_3_award')::numeric
        ) order by (row_value->>'place')::integer)
        from pg_catalog.jsonb_array_elements(
          configuration_value.configuration_manifest->'point_structure'
        ) row_value
      ), '[]'::jsonb),
      'payout_structure', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'place', (row_value->>'place')::integer,
          'round_1_fraction',
            (row_value->>'round_1_fraction')::numeric::text,
          'round_2_fraction',
            (row_value->>'round_2_fraction')::numeric::text,
          'round_3_fraction',
            (row_value->>'round_3_fraction')::numeric::text,
          'overall_fraction',
            (row_value->>'overall_fraction')::numeric::text
        ) order by (row_value->>'place')::integer)
        from pg_catalog.jsonb_array_elements(
          configuration_value.configuration_manifest->'payout_structure'
        ) row_value
      ), '[]'::jsonb),
      'rules', pg_catalog.jsonb_build_object(
        'auction_unit', 'PLAYER',
        'auction_workflow', 'MANUAL_FINAL_AUCTION_FACTS',
        'pot_rule', 'SUM_PURCHASE_PRICES',
        'tie_rule',
          'COMPETITION_RANK_WITH_OCCUPIED_PLACE_AWARD_AVERAGING',
        'payout_rounding', 'NONE',
        'scramble_asset',
          'PLAYER_PURCHASE_WITH_PAIRING_PERFORMANCE_SPLIT_EQUALLY',
        'completion_rule',
          'ALL_PURCHASED_PLAYERS_HAVE_OFFICIAL_COMPLETED_ROUND_RESULT',
        'settlement_tracking', 'NOT_MODELED'
      )
    );
  end if;

  if current_value.auction_revision > 0 then
    select value.* into strict auction_value
    from scoring_authority.calcutta_v1_auction_fact_revisions value
    where value.auction_revision_id = current_value.auction_revision_id;
    purchase_count := pg_catalog.jsonb_array_length(
      auction_value.auction_manifest->'purchases'
    );
    owner_count := pg_catalog.jsonb_array_length(
      auction_value.auction_manifest->'ownership'
    );
    select coalesce(pg_catalog.sum(
      (row_value->>'purchase_price')::numeric
    ), 0) into purchase_total
    from pg_catalog.jsonb_array_elements(
      auction_value.auction_manifest->'purchases'
    ) row_value;
    select pg_catalog.count(distinct row_value->>'owner_player_id')::integer
      into unique_owner_count
    from pg_catalog.jsonb_array_elements(
      auction_value.auction_manifest->'ownership'
    ) row_value;
    ownership_complete := not exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        auction_value.auction_manifest->'purchases'
      ) purchase
      where coalesce((
        select pg_catalog.sum(
          (ownership->>'ownership_fraction')::numeric
        )
        from pg_catalog.jsonb_array_elements(
          auction_value.auction_manifest->'ownership'
        ) ownership
        where ownership->>'player_id' = purchase->>'player_id'
      ), 0) <> 1
    );
    active_players_complete := not exists (
      select 1 from (
        select purchase->>'player_id' player_id
        from pg_catalog.jsonb_array_elements(
          auction_value.auction_manifest->'purchases'
        ) purchase
        union all
        select ownership->>'owner_player_id'
        from pg_catalog.jsonb_array_elements(
          auction_value.auction_manifest->'ownership'
        ) ownership
      ) player_values
      where not exists (
        select 1 from scoring_authority.tournament_players membership
        where membership.tournament_id = '2026'
          and membership.player_id = player_values.player_id
          and membership.participation_status = 'ACTIVE'
      )
    );
    auction_valid := production_control.calcutta_v1_hash(
        auction_value.auction_manifest
      ) = current_value.auction_fingerprint
      and purchase_total = (
        auction_value.auction_manifest->>'pot'
      )::numeric
      and ownership_complete and active_players_complete;

    auction_view := pg_catalog.jsonb_build_object(
      'revision', current_value.auction_revision,
      'recorded_at', auction_value.recorded_at,
      'currency_code', 'USD',
      'pot', (auction_value.auction_manifest->>'pot')::numeric::text,
      'purchase_count', purchase_count,
      'owner_count', unique_owner_count,
      'ownership_row_count', owner_count,
      'reconciliation_status', case when auction_valid
        then 'RECONCILED' else 'ATTENTION' end,
      'pot_reconciled', purchase_total = (
        auction_value.auction_manifest->>'pot'
      )::numeric,
      'ownership_complete', ownership_complete,
      'active_players_complete', active_players_complete,
      'purchases', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'player', pg_catalog.jsonb_build_object(
            'player_id', purchase->>'player_id',
            'display_name', entrant.display_name
          ),
          'purchase_price',
            (purchase->>'purchase_price')::numeric::text,
          'owners', coalesce((
            select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
              'player', pg_catalog.jsonb_build_object(
                'player_id', ownership->>'owner_player_id',
                'display_name', owner_player.display_name
              ),
              'ownership_fraction',
                (ownership->>'ownership_fraction')::numeric::text
            ) order by ownership->>'owner_player_id')
            from pg_catalog.jsonb_array_elements(
              auction_value.auction_manifest->'ownership'
            ) ownership
            join scoring_authority.players owner_player
              on owner_player.player_id = ownership->>'owner_player_id'
            where ownership->>'player_id' = purchase->>'player_id'
          ), '[]'::jsonb)
        ) order by purchase->>'player_id')
        from pg_catalog.jsonb_array_elements(
          auction_value.auction_manifest->'purchases'
        ) purchase
        join scoring_authority.players entrant
          on entrant.player_id = purchase->>'player_id'
      ), '[]'::jsonb)
    );

    source_fingerprint_value := production_control.calcutta_v1_hash(
      production_control.calcutta_v1_source_revision('2026')
    );
    select value.* into result_value
    from scoring_authority.calcutta_v1_result_revisions value
    where value.tournament_id = '2026'
      and value.configuration_revision = current_value.configuration_revision
      and value.auction_revision = current_value.auction_revision
      and value.is_current
    limit 1;
    active_job := exists (
      select 1 from scoring_authority.calcutta_v1_recalculation_jobs value
      where value.tournament_id = '2026'
        and value.configuration_revision = current_value.configuration_revision
        and value.auction_revision = current_value.auction_revision
        and value.source_fingerprint = source_fingerprint_value
        and value.status in ('PENDING', 'RUNNING')
    );
    result_view := pg_catalog.jsonb_build_object(
      'revision', case when result_value.result_id is null
        then null else result_value.result_revision end,
      'state', case
        when result_value.result_id is null and active_job then 'PROCESSING'
        when result_value.result_id is null then 'NOT_CALCULATED'
        when result_value.source_fingerprint = source_fingerprint_value
          then result_value.result_state
        when active_job then 'RECALCULATION_REQUIRED'
        else 'STALE' end,
      'completed_rounds', case when result_value.result_id is null
        then '[]'::jsonb
        else coalesce(result_value.engine_result_payload->'completedRounds',
          '[]'::jsonb) end,
      'calculated_at', result_value.calculated_at,
      'freshness', case
        when result_value.result_id is null and active_job then 'UPDATING'
        when result_value.result_id is null then 'MISSING'
        when result_value.source_fingerprint = source_fingerprint_value
          then 'CURRENT'
        when active_job then 'UPDATING'
        else 'STALE' end,
      'recalculation_required', result_value.result_id is null
        or result_value.source_fingerprint <> source_fingerprint_value,
      'validation_status', case when result_value.result_id is null
        then 'NOT_APPLICABLE'
        when result_value.configuration_revision =
          current_value.configuration_revision
          and result_value.auction_revision = current_value.auction_revision
        then 'VALIDATED' else 'ATTENTION' end
    );
  end if;

  if current_value.publication_revision > 0 then
    select value.* into strict publication_value
    from scoring_authority.calcutta_v1_publication_revisions value
    where value.publication_revision_id =
      current_value.publication_revision_id;
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'domain', 'CALCUTTA',
    'status', case
      when job.status = 'PENDING' then 'PENDING'
      when job.status = 'RUNNING' then 'PROCESSING'
      when job.status = 'SUCCEEDED' then 'COMPLETE'
      when job.status = 'FAILED' then 'FAILED'
      else 'STALE'
    end,
    'configuration_revision', job.configuration_revision,
    'auction_revision', job.auction_revision,
    'result_revision', (
      select pg_catalog.max(result_row.result_revision)
      from scoring_authority.calcutta_v1_result_revisions result_row
      where result_row.job_id = job.job_id
    ),
    'requested_at', job.requested_at,
    'started_at', job.started_at,
    'completed_at', job.completed_at,
    'updated_at', job.updated_at,
    'failure_description', case when job.status = 'FAILED'
      then 'Calcutta recalculation did not complete.' else null end,
    'retry_eligible', false
  ) order by job.requested_at desc), '[]'::jsonb) into jobs_value
  from (
    select value.*
    from scoring_authority.calcutta_v1_recalculation_jobs value
    where value.tournament_id = '2026'
    order by value.requested_at desc
    limit 8
  ) job;

  return pg_catalog.jsonb_build_object(
    'state', current_value.state,
    'publication_state', current_value.publication_state,
    'currency_code', 'USD',
    'configuration_revision', current_value.configuration_revision,
    'auction_revision', current_value.auction_revision,
    'publication_revision', current_value.publication_revision,
    'result_revision', nullif(current_value.result_revision, 0),
    'configuration', configuration_view,
    'auction', auction_view,
    'publication', pg_catalog.jsonb_build_object(
      'revision', current_value.publication_revision,
      'state', current_value.publication_state,
      'published_at', case when current_value.publication_state = 'PUBLISHED'
        then publication_value.published_at else null end
    ),
    'result', result_view,
    'jobs', jobs_value
  );
end;
$$;


ALTER FUNCTION production_control.director_private_calcutta_v1() OWNER TO postgres;

--
-- Name: director_private_net_skins_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.director_private_net_skins_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  total_matches integer := 0;
  ready_matches integer := 0;
  round_issue_count integer := 0;
  match_reference_count integer := 0;
  incomplete_pairing_count integer := 0;
  missing_assignment_count integer := 0;
  invalid_player_count integer := 0;
  individual_input_count integer := 0;
  scramble_pairing_count integer := 0;
  scramble_match_count integer := 0;
  scramble_player_slot_count integer := 0;
  scramble_stroke_count integer := 0;
  scramble_stroke_match_count integer := 0;
  hole_match_count integer := 0;
  missing_hole_count integer := 0;
  duplicate_player_count integer := 0;
  issues_value jsonb := '[]'::jsonb;
  by_round_value jsonb;
  jobs_value jsonb := '[]'::jsonb;
begin
  select value.* into strict current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = '2026';

  with expected(round_number, expected_format, expected_players) as (
    values (1, 'BB'::text, 4), (2, 'SC'::text, 4), (3, 'SI'::text, 2)
  )
  select pg_catalog.count(*)::integer into round_issue_count
  from expected
  left join scoring_authority.rounds round_value
    on round_value.tournament_id = '2026'
   and round_value.round_number = expected.round_number
  where round_value.round_number is null
     or round_value.format is distinct from expected.expected_format;

  if round_issue_count > 0 then
    with expected(round_number, expected_format) as (
      values (1, 'BB'::text), (2, 'SC'::text), (3, 'SI'::text)
    )
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'round', expected.round_number,
      'affected_matches', 0,
      'missing_count', 1
    ) order by expected.round_number), '[]'::jsonb) into by_round_value
    from expected
    left join scoring_authority.rounds round_value
      on round_value.tournament_id = '2026'
     and round_value.round_number = expected.round_number
    where round_value.round_number is null
       or round_value.format is distinct from expected.expected_format;
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_DEFINITIONS',
        'label', 'Tournament rounds',
        'affected_matches', 0,
        'missing_count', round_issue_count,
        'summary', pg_catalog.format(
          '%s approved tournament %s still need a supported Net Skins format.',
          round_issue_count,
          case when round_issue_count = 1 then 'round' else 'rounds' end
        ),
        'by_round', by_round_value
      )
    );
  end if;

  with expected(round_number, expected_format, expected_players) as (
    values (1, 'BB'::text, 4), (2, 'SC'::text, 4), (3, 'SI'::text, 2)
  ), match_base as (
    select match_value.match_id, match_value.round_number,
      match_value.format, expected.expected_format,
      expected.expected_players, match_value.scoring_snapshot_id,
      snapshot.snapshot_id,
      (select pg_catalog.count(*)::integer
       from scoring_authority.match_participants participant
       where participant.match_id = match_value.match_id) participant_count,
      (select pg_catalog.count(*)::integer
       from scoring_authority.match_participants participant
       where participant.match_id = match_value.match_id
         and participant.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
         and exists (
           select 1 from scoring_authority.tournament_players membership
           where membership.tournament_id = '2026'
             and membership.player_id = participant.player_id
             and membership.participation_status = 'ACTIVE'
         )) stable_participant_count,
      (select pg_catalog.count(distinct hole.hole_number)::integer
       from scoring_authority.match_holes hole
       where hole.match_id = match_value.match_id
         and hole.hole_number between 1 and 18) hole_count,
      snapshot.team_configuration
    from scoring_authority.matches match_value
    join expected on expected.round_number = match_value.round_number
    left join scoring_authority.scoring_snapshots snapshot
      on snapshot.snapshot_id = match_value.scoring_snapshot_id
     and snapshot.tournament_id = match_value.tournament_id
     and snapshot.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
  )
  select pg_catalog.count(*)::integer into total_matches from match_base;

  with expected(round_number) as (values (1), (2), (3)), missing as (
    select expected.round_number
    from expected
    where not exists (
      select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = '2026'
        and match_value.round_number = expected.round_number
    )
    union all
    select match_value.round_number
    from scoring_authority.matches match_value
    join scoring_authority.rounds round_value
      on round_value.tournament_id = match_value.tournament_id
     and round_value.round_number = match_value.round_number
    left join scoring_authority.scoring_snapshots snapshot
      on snapshot.snapshot_id = match_value.scoring_snapshot_id
     and snapshot.tournament_id = match_value.tournament_id
     and snapshot.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
      and match_value.round_number between 1 and 3
      and (snapshot.snapshot_id is null
        or match_value.format is distinct from round_value.format)
  )
  select pg_catalog.count(*)::integer into match_reference_count from missing;

  if match_reference_count > 0 then
    with expected(round_number) as (values (1), (2), (3)), missing as (
      select expected.round_number, 1 as missing_count
      from expected
      where not exists (
        select 1 from scoring_authority.matches match_value
        where match_value.tournament_id = '2026'
          and match_value.round_number = expected.round_number
      )
      union all
      select match_value.round_number, 1
      from scoring_authority.matches match_value
      join scoring_authority.rounds round_value
        on round_value.tournament_id = match_value.tournament_id
       and round_value.round_number = match_value.round_number
      left join scoring_authority.scoring_snapshots snapshot
        on snapshot.snapshot_id = match_value.scoring_snapshot_id
       and snapshot.tournament_id = match_value.tournament_id
       and snapshot.match_id = match_value.match_id
      where match_value.tournament_id = '2026'
        and match_value.round_number between 1 and 3
        and (snapshot.snapshot_id is null
          or match_value.format is distinct from round_value.format)
    )
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'round', grouped.round_number,
      'affected_matches', grouped.affected,
      'missing_count', grouped.missing_count
    ) order by grouped.round_number), '[]'::jsonb) into by_round_value
    from (
      select round_number, pg_catalog.count(*)::integer affected,
        pg_catalog.sum(missing_count)::integer missing_count
      from missing group by round_number
    ) grouped;
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'MATCH_REFERENCES',
        'label', 'Canonical match references',
        'affected_matches', match_reference_count,
        'missing_count', match_reference_count,
        'summary', pg_catalog.format(
          '%s canonical match %s still need a complete scoring snapshot and supported round reference.',
          match_reference_count,
          case when match_reference_count = 1 then 'reference' else 'references' end
        ),
        'by_round', by_round_value
      )
    );
  end if;

  with expected(round_number, expected_players) as (
    values (1, 4), (2, 4), (3, 2)
  ), counts as (
    select match_value.match_id, match_value.round_number,
      expected.expected_players,
      pg_catalog.count(participant.player_id)::integer participant_count
    from scoring_authority.matches match_value
    join expected on expected.round_number = match_value.round_number
    left join scoring_authority.match_participants participant
      on participant.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
    group by match_value.match_id, match_value.round_number,
      expected.expected_players
  )
  select
    pg_catalog.count(*) filter (
      where participant_count <> expected_players
    )::integer,
    coalesce(pg_catalog.sum(greatest(
      expected_players - participant_count, 0
    )), 0)::integer
  into incomplete_pairing_count, missing_assignment_count
  from counts;

  if incomplete_pairing_count > 0 then
    with expected(round_number, expected_players) as (
      values (1, 4), (2, 4), (3, 2)
    ), counts as (
      select match_value.match_id, match_value.round_number,
        expected.expected_players,
        pg_catalog.count(participant.player_id)::integer participant_count
      from scoring_authority.matches match_value
      join expected on expected.round_number = match_value.round_number
      left join scoring_authority.match_participants participant
        on participant.match_id = match_value.match_id
      where match_value.tournament_id = '2026'
      group by match_value.match_id, match_value.round_number,
        expected.expected_players
    )
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'round', grouped.round_number,
      'affected_matches', grouped.affected_matches,
      'missing_count', grouped.missing_count
    ) order by grouped.round_number), '[]'::jsonb) into by_round_value
    from (
      select round_number,
        pg_catalog.count(*) filter (
          where participant_count <> expected_players
        )::integer affected_matches,
        coalesce(pg_catalog.sum(greatest(
          expected_players - participant_count, 0
        )), 0)::integer missing_count
      from counts group by round_number
      having pg_catalog.count(*) filter (
        where participant_count <> expected_players
      ) > 0
    ) grouped;
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'MATCH_PARTICIPANTS',
        'label', 'Complete pairings',
        'affected_matches', incomplete_pairing_count,
        'missing_count', missing_assignment_count,
        'summary', pg_catalog.format(
          '%s %s still need complete pairings (%s participant assignments missing).',
          incomplete_pairing_count,
          case when incomplete_pairing_count = 1 then 'match' else 'matches' end,
          missing_assignment_count
        ),
        'by_round', by_round_value
      )
    );
  end if;

  select pg_catalog.count(*)::integer into invalid_player_count
  from scoring_authority.match_participants participant
  join scoring_authority.matches match_value
    on match_value.match_id = participant.match_id
  where match_value.tournament_id = '2026'
    and match_value.round_number between 1 and 3
    and (participant.player_id !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
      or not exists (
        select 1 from scoring_authority.tournament_players membership
        where membership.tournament_id = '2026'
          and membership.player_id = participant.player_id
          and membership.participation_status = 'ACTIVE'
      ));

  if invalid_player_count > 0 then
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'round', grouped.round_number,
      'affected_matches', grouped.affected_matches,
      'missing_count', grouped.missing_count
    ) order by grouped.round_number), '[]'::jsonb) into by_round_value
    from (
      select match_value.round_number,
        pg_catalog.count(distinct match_value.match_id)::integer affected_matches,
        pg_catalog.count(*)::integer missing_count
      from scoring_authority.match_participants participant
      join scoring_authority.matches match_value
        on match_value.match_id = participant.match_id
      where match_value.tournament_id = '2026'
        and match_value.round_number between 1 and 3
        and (participant.player_id !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
          or not exists (
            select 1 from scoring_authority.tournament_players membership
            where membership.tournament_id = '2026'
              and membership.player_id = participant.player_id
              and membership.participation_status = 'ACTIVE'
          ))
      group by match_value.round_number
    ) grouped;
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PLAYER_IDENTITIES',
        'label', 'Active Player IDs',
        'affected_matches', (
          select pg_catalog.count(distinct match_value.match_id)::integer
          from scoring_authority.match_participants participant
          join scoring_authority.matches match_value
            on match_value.match_id = participant.match_id
          where match_value.tournament_id = '2026'
            and (participant.player_id !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
              or not exists (
                select 1 from scoring_authority.tournament_players membership
                where membership.tournament_id = '2026'
                  and membership.player_id = participant.player_id
                  and membership.participation_status = 'ACTIVE'
              ))
        ),
        'missing_count', invalid_player_count,
        'summary', pg_catalog.format(
          '%s assigned %s still need a valid active Player ID.',
          invalid_player_count,
          case when invalid_player_count = 1 then 'participant' else 'participants' end
        ),
        'by_round', by_round_value
      )
    );
  end if;

  with expected(round_number, expected_players) as (
    values (1, 4), (3, 2)
  ), match_rows as (
    select match_value.match_id, match_value.round_number,
      expected.expected_players,
      pg_catalog.count(participant.player_id) filter (
        where participant.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
          and participant.final_strokes is not null
          and exists (
            select 1 from scoring_authority.tournament_players membership
            where membership.tournament_id = '2026'
              and membership.player_id = participant.player_id
              and membership.participation_status = 'ACTIVE'
          )
      )::integer ready_entries
    from scoring_authority.matches match_value
    join expected on expected.round_number = match_value.round_number
    left join scoring_authority.match_participants participant
      on participant.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
    group by match_value.match_id, match_value.round_number,
      expected.expected_players
  )
  select coalesce(pg_catalog.sum(greatest(
    expected_players - ready_entries, 0
  )), 0)::integer into individual_input_count
  from match_rows;

  if individual_input_count > 0 then
    with expected(round_number, expected_players) as (
      values (1, 4), (3, 2)
    ), match_rows as (
      select match_value.match_id, match_value.round_number,
        expected.expected_players,
        pg_catalog.count(participant.player_id) filter (
          where participant.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
            and participant.final_strokes is not null
            and exists (
              select 1 from scoring_authority.tournament_players membership
              where membership.tournament_id = '2026'
                and membership.player_id = participant.player_id
                and membership.participation_status = 'ACTIVE'
            )
        )::integer ready_entries
      from scoring_authority.matches match_value
      join expected on expected.round_number = match_value.round_number
      left join scoring_authority.match_participants participant
        on participant.match_id = match_value.match_id
      where match_value.tournament_id = '2026'
      group by match_value.match_id, match_value.round_number,
        expected.expected_players
    )
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'round', grouped.round_number,
      'affected_matches', grouped.affected_matches,
      'missing_count', grouped.missing_count
    ) order by grouped.round_number), '[]'::jsonb) into by_round_value
    from (
      select round_number,
        pg_catalog.count(*) filter (
          where ready_entries <> expected_players
        )::integer affected_matches,
        pg_catalog.sum(greatest(
          expected_players - ready_entries, 0
        ))::integer missing_count
      from match_rows group by round_number
      having pg_catalog.sum(greatest(
        expected_players - ready_entries, 0
      )) > 0
    ) grouped;
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'INDIVIDUAL_STROKES',
        'label', 'Individual stroke allocations',
        'affected_matches', (
          select coalesce(pg_catalog.sum(
            (item->>'affected_matches')::integer
          ), 0)::integer
          from pg_catalog.jsonb_array_elements(by_round_value) item
        ),
        'missing_count', individual_input_count,
        'summary', pg_catalog.format(
          '%s individual %s still need an active Player and canonical final-stroke allocation.',
          individual_input_count,
          case when individual_input_count = 1 then 'entry' else 'entries' end
        ),
        'by_round', by_round_value
      )
    );
  end if;

  with sides as (
    select match_value.match_id, match_value.round_number, side_value.side,
      pg_catalog.count(participant.player_id)::integer participant_count,
      pg_catalog.count(participant.player_id) filter (
        where participant.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
          and exists (
            select 1 from scoring_authority.tournament_players membership
            where membership.tournament_id = '2026'
              and membership.player_id = participant.player_id
              and membership.participation_status = 'ACTIVE'
          )
      )::integer stable_count
    from scoring_authority.matches match_value
    cross join (values (1), (2)) side_value(side)
    left join scoring_authority.match_participants participant
      on participant.match_id = match_value.match_id
     and participant.team_side = side_value.side
    where match_value.tournament_id = '2026'
      and match_value.round_number = 2
    group by match_value.match_id, match_value.round_number, side_value.side
  )
  select pg_catalog.count(*) filter (
      where participant_count <> 2 or stable_count <> 2
    )::integer,
    coalesce(pg_catalog.sum(greatest(2 - stable_count, 0)), 0)::integer,
    pg_catalog.count(distinct match_id) filter (
      where participant_count <> 2 or stable_count <> 2
    )::integer
  into scramble_pairing_count, scramble_player_slot_count,
    scramble_match_count
  from sides;

  if scramble_pairing_count > 0 then
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCRAMBLE_PAIRINGS',
        'label', 'Scramble sides',
        'affected_matches', scramble_match_count,
        'missing_count', scramble_player_slot_count,
        'summary', pg_catalog.format(
          '%s Scramble %s still need complete two-player pairings.',
          scramble_pairing_count,
          case when scramble_pairing_count = 1 then 'side' else 'sides' end
        ),
        'by_round', pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'round', 2,
            'affected_matches', scramble_match_count,
            'missing_count', scramble_player_slot_count
          )
        )
      )
    );
  end if;

  select pg_catalog.count(*)::integer,
    pg_catalog.count(distinct match_value.match_id)::integer
  into scramble_stroke_count, scramble_stroke_match_count
  from scoring_authority.matches match_value
  left join scoring_authority.scoring_snapshots snapshot
    on snapshot.snapshot_id = match_value.scoring_snapshot_id
   and snapshot.tournament_id = match_value.tournament_id
   and snapshot.match_id = match_value.match_id
  cross join (values ('team_1_strokes'), ('team_2_strokes')) key_value(key)
  where match_value.tournament_id = '2026'
    and match_value.round_number = 2
    and (
      snapshot.snapshot_id is null
      or pg_catalog.btrim(coalesce(
        snapshot.team_configuration->>key_value.key, ''
      )) !~ '^-?[0-9]+(?:\.[0-9]+)?$'
    );

  if scramble_stroke_count > 0 then
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCRAMBLE_TEAM_STROKES',
        'label', 'Scramble team handicaps',
        'affected_matches', (
          select pg_catalog.count(distinct match_value.match_id)::integer
          from scoring_authority.matches match_value
          left join scoring_authority.scoring_snapshots snapshot
            on snapshot.snapshot_id = match_value.scoring_snapshot_id
           and snapshot.tournament_id = match_value.tournament_id
           and snapshot.match_id = match_value.match_id
          where match_value.tournament_id = '2026'
            and match_value.round_number = 2
            and (snapshot.snapshot_id is null
              or pg_catalog.btrim(coalesce(
                snapshot.team_configuration->>'team_1_strokes', ''
              )) !~ '^-?[0-9]+(?:\.[0-9]+)?$'
              or pg_catalog.btrim(coalesce(
                snapshot.team_configuration->>'team_2_strokes', ''
              )) !~ '^-?[0-9]+(?:\.[0-9]+)?$')
        ),
        'missing_count', scramble_stroke_count,
        'summary', pg_catalog.format(
          '%s Scramble team handicap %s still need canonical values.',
          scramble_stroke_count,
          case when scramble_stroke_count = 1 then 'input' else 'inputs' end
        ),
        'by_round', pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'round', 2,
            'affected_matches', scramble_stroke_match_count,
            'missing_count', scramble_stroke_count
          )
        )
      )
    );
  end if;

  with hole_counts as (
    select match_value.match_id, match_value.round_number,
      pg_catalog.count(distinct hole.hole_number) filter (
        where hole.hole_number between 1 and 18
      )::integer hole_count
    from scoring_authority.matches match_value
    left join scoring_authority.match_holes hole
      on hole.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
      and match_value.round_number between 1 and 3
    group by match_value.match_id, match_value.round_number
  )
  select pg_catalog.count(*) filter (where hole_count <> 18)::integer,
    coalesce(pg_catalog.sum(greatest(18 - hole_count, 0)), 0)::integer
  into hole_match_count, missing_hole_count
  from hole_counts;

  if hole_match_count > 0 then
    with hole_counts as (
      select match_value.match_id, match_value.round_number,
        pg_catalog.count(distinct hole.hole_number) filter (
          where hole.hole_number between 1 and 18
        )::integer hole_count
      from scoring_authority.matches match_value
      left join scoring_authority.match_holes hole
        on hole.match_id = match_value.match_id
      where match_value.tournament_id = '2026'
        and match_value.round_number between 1 and 3
      group by match_value.match_id, match_value.round_number
    )
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'round', grouped.round_number,
      'affected_matches', grouped.affected_matches,
      'missing_count', grouped.missing_count
    ) order by grouped.round_number), '[]'::jsonb) into by_round_value
    from (
      select round_number,
        pg_catalog.count(*) filter (where hole_count <> 18)::integer
          affected_matches,
        pg_catalog.sum(greatest(18 - hole_count, 0))::integer
          missing_count
      from hole_counts group by round_number
      having pg_catalog.count(*) filter (where hole_count <> 18) > 0
    ) grouped;
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'HOLE_DEFINITIONS',
        'label', '18-hole course definitions',
        'affected_matches', hole_match_count,
        'missing_count', missing_hole_count,
        'summary', pg_catalog.format(
          '%s %s still need complete 18-hole definitions (%s holes missing).',
          hole_match_count,
          case when hole_match_count = 1 then 'match' else 'matches' end,
          missing_hole_count
        ),
        'by_round', by_round_value
      )
    );
  end if;

  select pg_catalog.count(*)::integer into duplicate_player_count
  from (
    select match_value.round_number, participant.player_id
    from scoring_authority.match_participants participant
    join scoring_authority.matches match_value
      on match_value.match_id = participant.match_id
    where match_value.tournament_id = '2026'
      and match_value.round_number between 1 and 3
    group by match_value.round_number, participant.player_id
    having pg_catalog.count(*) > 1
  ) duplicate_values;

  if duplicate_player_count > 0 then
    issues_value := issues_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_PLAYER_UNIQUENESS',
        'label', 'One entry per player per round',
        'affected_matches', 0,
        'missing_count', duplicate_player_count,
        'summary', pg_catalog.format(
          '%s duplicate round %s must be corrected.',
          duplicate_player_count,
          case when duplicate_player_count = 1 then 'assignment' else 'assignments' end
        ),
        'by_round', '[]'::jsonb
      )
    );
  end if;

  -- A match is ready only when the exact V1 builder predicates are true.
  with expected(round_number, expected_format, expected_players) as (
    values (1, 'BB'::text, 4), (2, 'SC'::text, 4), (3, 'SI'::text, 2)
  ), match_checks as (
    select match_value.match_id, match_value.round_number,
      match_value.format, expected.expected_format,
      expected.expected_players,
      snapshot.snapshot_id,
      snapshot.team_configuration,
      (select pg_catalog.count(*) from scoring_authority.match_participants p
       where p.match_id = match_value.match_id) participant_count,
      (select pg_catalog.count(*) from scoring_authority.match_participants p
       where p.match_id = match_value.match_id
         and p.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
         and exists (
           select 1 from scoring_authority.tournament_players membership
           where membership.tournament_id = '2026'
             and membership.player_id = p.player_id
             and membership.participation_status = 'ACTIVE'
         )) stable_count,
      (select pg_catalog.count(*) from scoring_authority.match_participants p
       where p.match_id = match_value.match_id
         and p.final_strokes is not null) individual_stroke_count,
      (select pg_catalog.count(distinct hole.hole_number)
       from scoring_authority.match_holes hole
       where hole.match_id = match_value.match_id
         and hole.hole_number between 1 and 18) hole_count,
      (select pg_catalog.count(*) from (values (1), (2)) side_value(side)
       where (select pg_catalog.count(*)
         from scoring_authority.match_participants p
         where p.match_id = match_value.match_id
           and p.team_side = side_value.side) = 2) complete_sides
    from scoring_authority.matches match_value
    join expected on expected.round_number = match_value.round_number
    left join scoring_authority.scoring_snapshots snapshot
      on snapshot.snapshot_id = match_value.scoring_snapshot_id
     and snapshot.tournament_id = match_value.tournament_id
     and snapshot.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
  )
  select pg_catalog.count(*) filter (
    where format = expected_format
      and snapshot_id is not null
      and participant_count = expected_players
      and stable_count = expected_players
      and hole_count = 18
      and (expected_format = 'SC'
        or individual_stroke_count = expected_players)
      and (expected_format <> 'SC' or (
        complete_sides = 2
        and pg_catalog.btrim(coalesce(
          team_configuration->>'team_1_strokes', ''
        )) ~ '^-?[0-9]+(?:\.[0-9]+)?$'
        and pg_catalog.btrim(coalesce(
          team_configuration->>'team_2_strokes', ''
        )) ~ '^-?[0-9]+(?:\.[0-9]+)?$'
      ))
  )::integer into ready_matches
  from match_checks;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'domain', 'NET_SKINS',
    'round', job.round_number,
    'status', case
      when job.status = 'PENDING' then 'PENDING'
      when job.status = 'RUNNING' then 'PROCESSING'
      when job.status = 'SUCCEEDED' then 'COMPLETE'
      when job.status = 'FAILED' then 'FAILED'
      else 'STALE'
    end,
    'configuration_revision', job.configuration_revision,
    'result_revision', (
      select pg_catalog.max(result_value.result_revision)
      from scoring_authority.net_skins_v1_result_revisions result_value
      where result_value.job_id = job.job_id
    ),
    'requested_at', job.requested_at,
    'started_at', job.started_at,
    'completed_at', job.completed_at,
    'updated_at', job.updated_at,
    'failure_description', case when job.status = 'FAILED'
      then 'Net Skins recalculation did not complete.' else null end,
    'retry_eligible', false
  ) order by job.requested_at desc), '[]'::jsonb) into jobs_value
  from (
    select value.*
    from scoring_authority.net_skins_v1_recalculation_jobs value
    where value.tournament_id = '2026'
    order by value.requested_at desc, value.round_number
    limit 8
  ) job;

  return pg_catalog.jsonb_build_object(
    'state', current_value.state,
    'configuration_revision', current_value.configuration_revision,
    'result_revision', (
      select pg_catalog.max(value.result_revision)
      from scoring_authority.net_skins_v1_result_revisions value
      where value.tournament_id = '2026' and value.is_current
    ),
    'readiness', pg_catalog.jsonb_build_object(
      'state', case when round_issue_count = 0
        and match_reference_count = 0
        and total_matches > 0
        and ready_matches = total_matches
        and duplicate_player_count = 0
        then 'READY' else 'NEEDS_SETUP' end,
      'can_configure', round_issue_count = 0
        and match_reference_count = 0
        and total_matches > 0
        and ready_matches = total_matches
        and duplicate_player_count = 0,
      'total_matches', total_matches,
      'ready_matches', ready_matches,
      'issues', issues_value
    ),
    'jobs', jobs_value
  );
end;
$_$;


ALTER FUNCTION production_control.director_private_net_skins_v1() OWNER TO postgres;

--
-- Name: dispatch_certification_annual_v1(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_annual_v1(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare payload jsonb:=input->'payload'; command jsonb; result jsonb; r production_control.canonical_resource_v1%rowtype;
begin
 if context->>'phase' is distinct from 'ANNUAL' or context->>'resource_class' is distinct from 'CERTIFICATION'
   or context is distinct from production_control.current_certification_context_v1()
   or jsonb_typeof(payload) is distinct from 'object' then
  raise exception using errcode='42501',message='CANONICAL_ANNUAL_CONTEXT_REQUIRED'; end if;
 if payload ?| array['authorization','environment','contract_version','resource','deployment','actor_player_id','actor_auth_user_id',
  'project_ref','project_url','source_workbook_id','tournament_id','tournament_year','operation_request_id',
  'resource_id','resource_class','installation_id','governance_tournament_id','expected_context_token'] then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_AUTHORITY_FIELD_REJECTED'; end if;
 select * into strict r from production_control.canonical_resource_v1 where resource_id=context->>'resource_id';
 command:=payload||jsonb_build_object('contract_version','production-future-year-administration-v1','environment','CERTIFICATION',
  'project_ref',r.project_ref,'project_url',r.project_url,'source_workbook_id',r.provenance_id,
  'tournament_id',context->>'current_tournament_id','tournament_year',(context->>'current_tournament_year')::integer,
  'authorization',input->'authorization');
 if mutation then
  command:=command||jsonb_build_object('operation_request_id',input->>'operation_request_id');
  result:=production_control.canonical_mutate_future_year_administration_v2(command,context);
  if coalesce((result->>'ok')::boolean,false) and not coalesce((result->>'idempotent')::boolean,false) then
   insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
   values('CERTIFICATION_ANNUAL_OPERATION','ANNUAL',context->>'current_tournament_id',input#>>'{authorization,player_id}',
    production_control.future_year_hash_v1(payload),'SUCCEEDED',jsonb_build_object('resource_class','CERTIFICATION',
     'resource_id',context->>'resource_id','installation_id',context->>'installation_id','binding_id',context->>'binding_id',
     'context_token',context->>'context_token','operation_request_id',input->>'operation_request_id',
     'release_commit',context->>'release_commit','admission_revision',context->'admission_revision',
     'actor_auth_user_id',input#>>'{authorization,auth_user_id}','receipt',result));
  end if;
  return result;
 end if;
 command:=command||jsonb_build_object('operation','READ_PRODUCTION_FUTURE_YEAR_ADMINISTRATION_V1');
 return production_control.canonical_read_future_year_administration_v2(command,context);
end;
$$;


ALTER FUNCTION production_control.dispatch_certification_annual_v1(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: dispatch_certification_calcutta_publication_v1(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_calcutta_publication_v1(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare payload jsonb:=input->'payload';command jsonb;
begin
 perform production_control.assert_canonical_scoring_context_v1('{}',context,'RUNTIME');
 if context->>'phase' is distinct from 'DIRECTOR' or context->>'tournament_id' is distinct from '2026'
   or context->>'resource_class' is distinct from 'CERTIFICATION'
   or (not production_control.model_d_context_v1(context) and (context->>'resource_id' is distinct from 'CERTIFICATION:2857f707-065a-405d-b5fc-b5b6fa1b0f51' or context->>'project_ref' is distinct from 'trmcwrljjxwhgtikfdgu'))
   or input->>'phase' is distinct from 'DIRECTOR'
   or input#>>'{authorization,tournament_id}' is distinct from context->>'tournament_id' then
   raise exception using errcode='42501',message='CERTIFICATION_CALCUTTA_PUBLICATION_TARGET_DENIED';end if;
 perform production_control.assert_production_scoring_actor(jsonb_build_object('authorization',input->'authorization'),true);
 if jsonb_typeof(payload) is distinct from 'object' or payload->>'family' is distinct from 'CALCUTTA_PUBLICATION' then
   raise exception using errcode='22023',message='PRODUCTION_CALCUTTA_PUBLICATION_INPUT_INVALID';end if;
 if not mutation then
   if input->>'operation_id' is distinct from 'DIRECTOR.READ_CALCUTTA_PUBLICATION' or payload->>'action' is distinct from 'read'
     or exists(select 1 from jsonb_object_keys(payload)k where k not in('family','action')) then
     raise exception using errcode='42501',message='CERTIFICATION_CALCUTTA_PUBLICATION_INPUT_DENIED';end if;
   return production_control.certification_calcutta_publication_projection_v1('2026');
 end if;
 if input->>'operation_id' is distinct from 'DIRECTOR.PUBLISH_CALCUTTA' or payload->>'action' is distinct from 'publish'
   or exists(select 1 from jsonb_object_keys(payload)k where k not in('family','action','expected_configuration_revision',
     'expected_configuration_fingerprint','expected_auction_revision','expected_auction_fingerprint',
     'expected_publication_revision','expected_result_revision','expected_source_fingerprint'))
   or coalesce(payload->>'expected_configuration_revision','') !~ '^[1-9][0-9]*$'
   or coalesce(payload->>'expected_auction_revision','') !~ '^[1-9][0-9]*$'
   or coalesce(payload->>'expected_publication_revision','') !~ '^(0|[1-9][0-9]*)$'
   or coalesce(payload->>'expected_result_revision','') !~ '^[1-9][0-9]*$'
   or coalesce(payload->>'expected_configuration_fingerprint','') !~ '^[0-9a-f]{64}$'
   or coalesce(payload->>'expected_auction_fingerprint','') !~ '^[0-9a-f]{64}$'
   or coalesce(payload->>'expected_source_fingerprint','') !~ '^[0-9a-f]{64}$' then
   raise exception using errcode='22023',message='PRODUCTION_CALCUTTA_PUBLICATION_INPUT_INVALID';end if;
 command:=(payload-array['family','action'])||jsonb_build_object('contract_version','production-calcutta-v1',
   'tournament_id',context->>'tournament_id','authorization',input->'authorization','actor_id',input#>>'{authorization,player_id}',
   'request_fingerprint',production_control.calcutta_v1_hash(jsonb_build_object('contract','certification-calcutta-publication-v1',
     'resource_id',context->>'resource_id','operation_request_id',input->>'operation_request_id')));
 return production_control.canonical_publish_calcutta_v1(command,context);
end;$_$;


ALTER FUNCTION production_control.dispatch_certification_calcutta_publication_v1(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: dispatch_certification_derived_operation_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_derived_operation_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare operation_id text:=input->>'operation_id'; payload jsonb:=input->'payload'; command jsonb;
begin
 if (context->>'current_tournament_year')::integer>2026 then return production_control.dispatch_certification_future_worker_v1(input,context);end if;
 perform production_control.assert_canonical_scoring_context_v1('{}',context,'RUNTIME');
 if jsonb_typeof(payload) is distinct from 'object' or payload ?| array['resource','deployment','authorization','environment',
  'project_ref','project_url','actor_player_id','actor_auth_user_id','auth_user_id','player_id','role','context_token',
  'binding_id','resource_id','resource_class','installation_id','release_commit','activation_revision',
  'admission_revision','governance_tournament_id'] then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_AUTHORITY_FIELD_REJECTED'; end if;
 if (payload ? 'tournament_id' and payload->>'tournament_id' is distinct from context->>'tournament_id')
  or (payload ? 'expected_activation_revision' and payload->>'expected_activation_revision' is distinct from context->>'activation_revision')
  or (payload ? 'expected_epoch_id' and payload->>'expected_epoch_id' is distinct from context->>'authority_epoch_id') then
  raise exception using errcode='40001',message='CERTIFICATION_DERIVED_CONTEXT_STALE'; end if;
 command:=payload||jsonb_build_object('tournament_id',context->>'tournament_id','environment','CERTIFICATION',
  'expected_activation_revision',context->'activation_revision','expected_epoch_id',context->>'authority_epoch_id',
  'operation_id',input->>'operation_request_id','authorization',input->'authorization');
 if operation_id like 'DIRECTOR.%' then
  perform production_control.assert_production_scoring_actor(command,true);
 elsif btrim(coalesce(command->>'worker_id','')) !~ '^[A-Za-z0-9_.:-]{1,160}$' then
  raise exception using errcode='22023',message='DERIVED_DELIVERY_WORKER_REQUIRED';
 end if;
 case operation_id
 when 'WORKERS.DELIVERY_TICK' then
  return production_control.canonical_score_derived_delivery_tick_v1_core_v2(command||jsonb_build_object('contract_version','score-derived-delivery-v1'),context);
 when 'WORKERS.FAIL_PRECLAIM' then
  return production_control.canonical_fail_score_derived_preclaim_v1_core_v2(command||jsonb_build_object('contract_version','score-derived-delivery-v1'),context);
 when 'WORKERS.COMPETITION_CLAIM' then
  perform production_control.flush_score_derived_intents_v1('2026','COMPETITION',8);
  return production_control.canonical_claim_competition_derived_jobs_core_v2(command,context);
 when 'WORKERS.COMPETITION_WRITE' then
  return production_control.canonical_write_competition_derived_snapshot_core_v2(command,context);
 when 'WORKERS.COMPETITION_FAIL' then
  return production_control.canonical_mark_competition_derived_job_failed_core_v2(command,context);
 when 'WORKERS.INTELLIGENCE_CLAIM' then
  perform production_control.flush_score_derived_intents_v1('2026','COMPETITION',8);
  return production_control.canonical_claim_intelligence_derived_bundle_core_v2(command,context);
 when 'WORKERS.INTELLIGENCE_WRITE' then
  return production_control.canonical_write_intelligence_derived_bundle_core_v2(command,context);
 when 'WORKERS.INTELLIGENCE_FAIL' then
  return production_control.canonical_fail_intelligence_derived_bundle_v1_core_v2(command||jsonb_build_object('contract_version','score-derived-delivery-v1'),context);
 when 'WORKERS.CALCUTTA_CLAIM' then
  return production_control.canonical_claim_calcutta_v1_recalculation_core_v2(command,context);
 when 'WORKERS.CALCUTTA_COMPLETE' then
  return production_control.canonical_complete_calcutta_v1_recalculation_core_v2(command,context);
 when 'WORKERS.CALCUTTA_FAIL' then
  return production_control.canonical_fail_calcutta_v1_recalculation_core_v2(command,context);
 when 'DIRECTOR.NET_SKINS_CLAIM' then
  return production_control.canonical_claim_net_skins_v1_recalculation_core_v2(command,context);
 when 'DIRECTOR.NET_SKINS_COMPLETE' then
  return production_control.canonical_complete_net_skins_v1_recalculation_core_v2(command,context);
 when 'DIRECTOR.NET_SKINS_FAIL' then
  return production_control.canonical_fail_net_skins_v1_recalculation_core_v2(command,context);
 when 'DIRECTOR.REQUEUE_DERIVED' then
  if command->>'request_id' is distinct from input->>'operation_request_id' then
   raise exception using errcode='22023',message='CERTIFICATION_OPERATION_ID_MISMATCH'; end if;
  return production_control.canonical_requeue_score_derived_delivery_v1_core_v2(command||jsonb_build_object('contract_version','score-derived-delivery-v1'),context);
 else raise exception using errcode='42501',message='CERTIFICATION_OPERATION_NOT_ADMITTED';
 end case;
end;
$_$;


ALTER FUNCTION production_control.dispatch_certification_derived_operation_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: dispatch_certification_future_scoring_v1(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_future_scoring_v1(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare op text:=input->>'operation_id';payload jsonb:=input->'payload';command jsonb;operation_name text;
 generation production_control.future_annual_runtime_generations_v1%rowtype;
begin
 perform production_control.assert_current_certification_future_context_v1(context);
 if jsonb_typeof(payload) is distinct from 'object' or payload ?| array['resource','deployment','authorization','environment','project_ref','project_url',
  'source_workbook_id','actor_player_id','actor_auth_user_id','auth_user_id','role','player_id','context_token','expected_context_token',
  'binding_id','resource_id','resource_class','installation_id','release_commit','activation_revision','admission_revision','governance_tournament_id',
  'annual_scoring_dispatch_contract','annual_scoring_operation','expected_runtime_generation_id','expected_annual_authority_generation_id',
  'expected_annual_admission_generation_id','expected_current_tournament_id','expected_pointer_revision'] then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_AUTHORITY_FIELD_REJECTED';end if;
 if (payload ? 'tournament_id' and payload->>'tournament_id' is distinct from context->>'tournament_id')
  or (payload ? 'expected_epoch_id' and payload->>'expected_epoch_id' is distinct from context->>'authority_epoch_id')
  or(input#>>'{authorization,tournament_id}' is not null and input#>>'{authorization,tournament_id}' is distinct from context->>'tournament_id') then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_TARGET_MISMATCH';end if;
 case op
 when 'SCORING.SUBMIT_HOLE' then operation_name:='submit_production_hole_score';
 when 'SCORING.FINALIZE_MATCH' then operation_name:='finalize_production_match';
 when 'SCORING.REOPEN_MATCH' then operation_name:='reopen_production_match';
 when 'SCORING.READ_AUTHORITY' then operation_name:='read_production_scoring_authority';
 when 'SCORING.READ_PARTICIPANT_CONTEXT' then operation_name:='read_production_scoring_participant_context';
 when 'DIRECTOR.MATCH_CONTROL' then operation_name:='mutate_production_match_control';
 when 'DIRECTOR.READ_SETUP' then
  if mutation or payload->>'family' is distinct from 'MATCH_CONTROL' then
   raise exception using errcode='42501',message='CERTIFICATION_FUTURE_OPERATION_NOT_ADMITTED';end if;
  return production_control.read_certification_future_match_control_v1(input,context);
 else raise exception using errcode='42501',message='CERTIFICATION_FUTURE_OPERATION_NOT_ADMITTED';end case;
 if mutation is distinct from (op in('SCORING.SUBMIT_HOLE','SCORING.FINALIZE_MATCH','SCORING.REOPEN_MATCH','DIRECTOR.MATCH_CONTROL')) then
  raise exception using errcode='42501',message='CERTIFICATION_FUTURE_OPERATION_NOT_ADMITTED';end if;
 select * into strict generation from production_control.future_annual_runtime_generations_v1
  where tournament_id=context->>'tournament_id' and generation_status='ACTIVE';
 command:=payload||jsonb_build_object('tournament_id',context->>'tournament_id','authorization',input->'authorization',
  'expected_epoch_id',context->>'authority_epoch_id','annual_scoring_dispatch_contract','production-annual-scoring-dispatch-v1',
  'annual_scoring_operation',operation_name,'expected_current_tournament_id',context->>'current_tournament_id',
  'expected_pointer_revision',context->'pointer_revision','expected_runtime_generation_id',generation.runtime_generation_id,
  'expected_annual_authority_generation_id',generation.authority_generation_id,'expected_annual_admission_generation_id',generation.admission_generation_id);
 if mutation and op like 'SCORING.%' and payload->>'mutation_key' is distinct from input->>'operation_request_id' then
  raise exception using errcode='22023',message='CERTIFICATION_OPERATION_ID_MISMATCH';end if;
 case op

 when 'SCORING.SUBMIT_HOLE' then return production_control.canonical_future_submit_hole_score_v1_resource(command,context);

 when 'SCORING.FINALIZE_MATCH' then return production_control.canonical_future_finalize_match_v1_resource(command,context);

 when 'SCORING.REOPEN_MATCH' then return production_control.canonical_future_reopen_match_v1_resource(command,context);

 when 'SCORING.READ_AUTHORITY' then return production_control.canonical_future_read_scoring_authority_v1_resource(command,context);

 when 'SCORING.READ_PARTICIPANT_CONTEXT' then
  return production_control.canonical_future_read_scoring_participant_context_v1_resource(command||jsonb_build_object('player_id',input#>>'{authorization,player_id}',
   'auth_user_id',input#>>'{authorization,auth_user_id}','role',input#>>'{authorization,role}'),context);
 when 'DIRECTOR.MATCH_CONTROL' then
  if payload->>'action' not in('mark-live','scoring-lock','scoring-unlock','access-activate','access-revoke')
   or coalesce(payload->>'expected_match_revision','')!~'^[0-9]+$'
   or coalesce(payload->>'expected_permission_revision','')!~'^[0-9]+$' then
   raise exception using errcode='22023',message='ISOLATED_DIRECTOR_CONTROL_INPUT_INVALID';end if;
  command:=command||jsonb_build_object('mutation_key',input->>'operation_request_id','operation',
   case payload->>'action' when 'mark-live' then 'MARK_LIVE' when 'scoring-lock' then 'SCORING_LOCK'
    when 'scoring-unlock' then 'SCORING_UNLOCK' when 'access-activate' then 'ACCESS_ACTIVATE' when 'access-revoke' then 'ACCESS_REVOKE' end,
   'authorization',input->'authorization'||jsonb_build_object('match_id',payload->>'match_id','permission_revision',payload->'expected_permission_revision'));
  return production_control.canonical_future_mutate_match_control_v1_resource(command,context);
 else raise exception using errcode='42501',message='CERTIFICATION_FUTURE_OPERATION_NOT_ADMITTED';end case;
end;$_$;


ALTER FUNCTION production_control.dispatch_certification_future_scoring_v1(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: dispatch_certification_future_worker_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_future_worker_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare op text:=input->>'operation_id';payload jsonb:=input->'payload';command jsonb;operation_name text;
 generation production_control.future_annual_runtime_generations_v1%rowtype;
 resource production_control.canonical_resource_v1%rowtype;
begin
 perform production_control.assert_current_certification_future_context_v1(context);
 if jsonb_typeof(payload) is distinct from 'object' or payload ?| array['resource','deployment','authorization','environment','project_ref','project_url',
  'source_workbook_id','annual_destination_workbook_id','actor_player_id','actor_auth_user_id','auth_user_id','player_id','role','context_token','expected_context_token',
  'binding_id','resource_id','resource_class','installation_id','release_commit','activation_revision','admission_revision','governance_tournament_id',
  'annual_scoring_dispatch_contract','annual_scoring_operation','expected_runtime_generation_id','expected_annual_authority_generation_id',
  'expected_annual_admission_generation_id','expected_current_tournament_id','expected_pointer_revision'] then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_AUTHORITY_FIELD_REJECTED';end if;
 if(payload ? 'tournament_id' and payload->>'tournament_id' is distinct from context->>'tournament_id')
  or(payload ? 'expected_activation_revision' and payload->>'expected_activation_revision' is distinct from context->>'activation_revision')
  or(payload ? 'expected_epoch_id' and payload->>'expected_epoch_id' is distinct from context->>'authority_epoch_id')
  or(input#>>'{authorization,tournament_id}' is not null and input#>>'{authorization,tournament_id}' is distinct from context->>'tournament_id') then
  raise exception using errcode='40001',message='CERTIFICATION_DERIVED_CONTEXT_STALE';end if;
 case op

 when 'WORKERS.COMPETITION_CLAIM' then operation_name:='claim_competition_derived_jobs';

 when 'WORKERS.COMPETITION_WRITE' then operation_name:='write_competition_derived_snapshot';

 when 'WORKERS.COMPETITION_FAIL' then operation_name:='mark_competition_derived_job_failed';

 when 'WORKERS.INTELLIGENCE_CLAIM' then operation_name:='claim_intelligence_derived_bundle';

 when 'WORKERS.INTELLIGENCE_WRITE' then operation_name:='write_intelligence_derived_bundle';

 when 'WORKERS.CALCUTTA_CLAIM' then operation_name:='claim_production_calcutta_v1_recalculation';

 when 'WORKERS.CALCUTTA_COMPLETE' then operation_name:='complete_production_calcutta_v1_recalculation';

 when 'WORKERS.CALCUTTA_FAIL' then operation_name:='fail_production_calcutta_v1_recalculation';

 when 'DIRECTOR.NET_SKINS_CLAIM' then operation_name:='claim_production_net_skins_v1_recalculation';

 when 'DIRECTOR.NET_SKINS_COMPLETE' then operation_name:='complete_production_net_skins_v1_recalculation';

 when 'DIRECTOR.NET_SKINS_FAIL' then operation_name:='fail_production_net_skins_v1_recalculation';

 when 'WORKERS.DELIVERY_TICK' then operation_name:='score_derived_delivery_tick_v1';

 when 'WORKERS.FAIL_PRECLAIM' then operation_name:='fail_score_derived_preclaim_v1';

 when 'WORKERS.INTELLIGENCE_FAIL' then operation_name:='fail_intelligence_derived_bundle_v1';

 when 'DIRECTOR.REQUEUE_DERIVED' then operation_name:='requeue_score_derived_delivery_v1';

 else raise exception using errcode='42501',message='CERTIFICATION_FUTURE_WORKER_NOT_ADMITTED';end case;
 select * into strict resource from production_control.canonical_resource_v1 where singleton;
 select * into strict generation from production_control.future_annual_runtime_generations_v1
  where tournament_id=context->>'tournament_id' and generation_status='ACTIVE';
 command:=payload||jsonb_build_object('tournament_id',context->>'tournament_id','authorization',input->'authorization',
  'environment','CERTIFICATION','project_ref',resource.project_ref,'project_url',resource.project_url,
  'annual_destination_workbook_id',resource.provenance_id,'source_workbook_id',resource.provenance_id,
  'expected_epoch_id',context->>'authority_epoch_id','expected_activation_revision',context->'activation_revision',
  'operation_id',input->>'operation_request_id','annual_scoring_dispatch_contract','production-annual-scoring-dispatch-v1',
  'annual_scoring_operation',operation_name,'expected_current_tournament_id',context->>'current_tournament_id',
  'expected_pointer_revision',context->'pointer_revision','expected_runtime_generation_id',generation.runtime_generation_id,
  'expected_annual_authority_generation_id',generation.authority_generation_id,'expected_annual_admission_generation_id',generation.admission_generation_id);
 if op like 'DIRECTOR.%' then perform production_control.assert_canonical_future_scoring_actor_v1(command,context->>'tournament_id',true,context);
 elsif btrim(coalesce(command->>'worker_id',''))!~'^[A-Za-z0-9_.:-]{1,160}$' then
  raise exception using errcode='22023',message='DERIVED_DELIVERY_WORKER_REQUIRED';end if;
 if op like 'WORKERS.CALCUTTA_%' then command:=command||jsonb_build_object('contract_version','production-calcutta-v1');
 elsif op like 'DIRECTOR.NET_SKINS_%' then command:=command||jsonb_build_object('contract_version','production-net-skins-v1');
 else command:=command||jsonb_build_object('contract_version','score-derived-delivery-v1');end if;
 if op='DIRECTOR.REQUEUE_DERIVED' and command->>'request_id' is distinct from input->>'operation_request_id' then
  raise exception using errcode='22023',message='CERTIFICATION_OPERATION_ID_MISMATCH';end if;
 case op

 when 'WORKERS.COMPETITION_CLAIM' then return production_control.canonical_future_claim_competition_derived_jobs_v1_resource(command,context);

 when 'WORKERS.COMPETITION_WRITE' then return production_control.canonical_future_write_competition_derived_snapshot_v1_resource(command,context);

 when 'WORKERS.COMPETITION_FAIL' then return production_control.canonical_future_fail_competition_derived_job_v1_resource(command,context);

 when 'WORKERS.INTELLIGENCE_CLAIM' then return production_control.canonical_future_claim_intelligence_derived_bundle_v1_resource(command,context);

 when 'WORKERS.INTELLIGENCE_WRITE' then return production_control.canonical_future_write_intelligence_derived_bundle_v1_resource(command,context);

 when 'WORKERS.CALCUTTA_CLAIM' then return production_control.canonical_future_claim_calcutta_recalculation_v1_resource(command,context);

 when 'WORKERS.CALCUTTA_COMPLETE' then return production_control.canonical_future_complete_calcutta_recalculation_v1_resource(command,context);

 when 'WORKERS.CALCUTTA_FAIL' then return production_control.canonical_future_fail_calcutta_recalculation_v1_resource(command,context);

 when 'DIRECTOR.NET_SKINS_CLAIM' then return production_control.canonical_future_claim_net_skins_recalculation_v1_resource(command,context);

 when 'DIRECTOR.NET_SKINS_COMPLETE' then return production_control.canonical_future_complete_net_skins_recalculation_v1_resource(command,context);

 when 'DIRECTOR.NET_SKINS_FAIL' then return production_control.canonical_future_fail_net_skins_recalculation_v1_resource(command,context);

 when 'WORKERS.DELIVERY_TICK' then return production_control.canonical_score_derived_delivery_tick_v1_core_v2(command,context);

 when 'WORKERS.FAIL_PRECLAIM' then return production_control.canonical_fail_score_derived_preclaim_v1_core_v2(command,context);

 when 'WORKERS.INTELLIGENCE_FAIL' then return production_control.canonical_fail_intelligence_derived_bundle_v1_core_v2(command,context);

 when 'DIRECTOR.REQUEUE_DERIVED' then return production_control.canonical_requeue_score_derived_delivery_v1_core_v2(command,context);

 else raise exception using errcode='42501',message='CERTIFICATION_FUTURE_WORKER_NOT_ADMITTED';end case;
end;$_$;


ALTER FUNCTION production_control.dispatch_certification_future_worker_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: dispatch_certification_net_skins_calculation_v1(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_net_skins_calculation_v1(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
 op text:=input->>'operation_id'; p jsonb:=input->'payload'; actor jsonb;
 cfg scoring_authority.net_skins_v1_configuration_current%rowtype;
 manifest jsonb; entries jsonb; r jsonb; rounds jsonb:='[]'; expected_entries jsonb:='{}'; sources jsonb:='{}';
 id text:=lower(input->>'operation_request_id'); base text; outer_fp text; phase_fp text;
 identity jsonb; prior jsonb; claimed jsonb; command jsonb; completed jsonb; failed jsonb;
 j scoring_authority.net_skins_v1_recalculation_jobs%rowtype; outcome text; state text; receipt jsonb; round_lock integer;
begin
 perform production_control.assert_canonical_scoring_context_v1('{}',context,'RUNTIME');
 if context is distinct from production_control.current_certification_context_v1()
  or context->>'phase' is distinct from 'DIRECTOR' or context->>'tournament_id' is distinct from '2026'
  or (not production_control.model_d_context_v1(context) and (context->>'resource_id' is distinct from 'CERTIFICATION:2857f707-065a-405d-b5fc-b5b6fa1b0f51' or context->>'project_ref' is distinct from 'trmcwrljjxwhgtikfdgu'))
  or op not in('DIRECTOR.CALCULATE_NET_SKINS','DIRECTOR.READ_NET_SKINS_CALCULATION','DIRECTOR.NET_SKINS_CALCULATION_STATUS')
  or mutation is distinct from (op='DIRECTOR.CALCULATE_NET_SKINS') then
  raise exception using errcode='42501',message='CERTIFICATION_NET_SKINS_CALCULATION_CONTEXT_DENIED';end if;
 actor:=jsonb_build_object('tournament_id','2026','authorization',input->'authorization');
 perform production_control.assert_production_scoring_actor(actor,true);
 if jsonb_typeof(p) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p)k
  where k not in('expected_configuration_revision','entry_revisions','source_fingerprints')) then
  raise exception using errcode='22023',message='CERTIFICATION_NET_SKINS_CALCULATION_INPUT_INVALID';end if;
 select * into cfg from scoring_authority.net_skins_v1_configuration_current where tournament_id='2026';
 if not found then
  -- Absence is a truthful configuration-zero read, not an invented ledger row.
  cfg.state:='NOT_CONFIGURED';cfg.configuration_revision:=0;manifest:='{"rounds":[]}';
 else
  select configuration_manifest into strict manifest from scoring_authority.net_skins_v1_configuration_revisions
   where configuration_revision_id=cfg.configuration_revision_id;
 end if;
 entries:=production_control.net_skins_entries_projection_v1('2026');
 for r in select value from jsonb_array_elements(manifest->'rounds') loop
  expected_entries:=expected_entries||jsonb_build_object(r->>'round_number',r->'entry_revision');
  sources:=sources||jsonb_build_object(r->>'round_number',production_control.net_skins_v1_hash(
    production_control.net_skins_v1_round_source_revision('2026',(r->>'round_number')::integer)));
  rounds:=rounds||jsonb_build_array(jsonb_build_object('round_number',(r->>'round_number')::integer,
   'entry_revision',r->'entry_revision','current_entry_revision',(select v->'revision' from jsonb_array_elements(entries->'rounds')v
    where v->>'roundNumber'=r->>'round_number'),'source_fingerprint',sources->(r->>'round_number'),
   'result_state',(select result_state from scoring_authority.net_skins_v1_result_revisions where tournament_id='2026'
    and round_number=(r->>'round_number')::integer and is_current and configuration_revision=cfg.configuration_revision)));
 end loop;
 if op='DIRECTOR.READ_NET_SKINS_CALCULATION' then
  if p<>'{}'::jsonb then raise exception using errcode='22023',message='CERTIFICATION_NET_SKINS_CALCULATION_INPUT_INVALID';end if;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('tournament_id','2026','state',cfg.state,
   'configuration_revision',cfg.configuration_revision,'entry_revisions',expected_entries,'source_fingerprints',sources,'rounds',rounds,
   'processing',(select count(*) from scoring_authority.net_skins_v1_recalculation_jobs where tournament_id='2026' and status='RUNNING'),
   'pending',(select count(*) from scoring_authority.net_skins_v1_recalculation_jobs where tournament_id='2026' and status='PENDING')));
 end if;
 if coalesce(id,'') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  or jsonb_typeof(p->'expected_configuration_revision') is distinct from 'number'
  or jsonb_typeof(p->'entry_revisions') is distinct from 'object'
  or jsonb_typeof(p->'source_fingerprints') is distinct from 'object' then
  raise exception using errcode='22023',message='CERTIFICATION_NET_SKINS_CALCULATION_INPUT_INVALID';end if;
 -- Serialize only this review identity. Receipts remain the existing durable
 -- domain ledger; no new lease, attempt budget or recovery system is introduced.
 perform pg_advisory_xact_lock(hashtextextended('certification-net-skins-calculation-v1:'||id,0));
 base:=encode(extensions.digest('certification-net-skins-calculation-v1'||chr(10)||id,'sha256'),'hex');
 outer_fp:=encode(extensions.digest('ADMISSION'||chr(10)||base,'sha256'),'hex');
 identity:=p||jsonb_build_object('request_fingerprint',outer_fp,'operation_request_id',id,
  'resource_id',context->>'resource_id','project_ref',context->>'project_ref','authorization',input->'authorization');
 prior:=production_control.lookup_cutover_receipt('CERTIFICATION_NET_SKINS_CALCULATION',identity);
 if op='DIRECTOR.NET_SKINS_CALCULATION_STATUS' then
  outcome:='UNKNOWN';state:='UNCONFIRMED';receipt:=null;
  if prior is not null then
   if prior->'job'='null'::jsonb then
    outcome:='COMMITTED';state:='NO_ELIGIBLE_WORK';receipt:=jsonb_build_object('ok',true,'code',prior->>'code','empty',true,'idempotent',true);
   else
    select * into strict j from scoring_authority.net_skins_v1_recalculation_jobs where job_id=(prior#>>'{job,job_id}')::uuid for update;
    phase_fp:=encode(extensions.digest('production-net-skins-v1'||chr(10)||'COMPLETE:'||upper(j.job_id::text)||chr(10)||base,'sha256'),'hex');
    select response into completed from production_control.cutover_operation_receipts where request_fingerprint=phase_fp and operation='NET_SKINS_V1_COMPLETE';
    phase_fp:=encode(extensions.digest('production-net-skins-v1'||chr(10)||'FAIL:'||upper(j.job_id::text)||chr(10)||base,'sha256'),'hex');
    select response into failed from production_control.cutover_operation_receipts where request_fingerprint=phase_fp and operation='NET_SKINS_V1_FAIL';
    if completed is not null then
     outcome:='COMMITTED';state:='COMPLETED';
     receipt:=(completed-'job_id')||jsonb_build_object('idempotent',true,'empty',false);
    elsif failed is not null or j.claim_token is distinct from (prior#>>'{job,claim_token}')::uuid
      or j.claimed_by is distinct from 'certification-net-skins-director-v1' or j.lease_expires_at<=clock_timestamp() then
     outcome:='NOT_COMMITTED';state:=case when failed is not null then 'FAILED' else 'CLAIM_CLOSED' end;
    else state:='CLAIM_HELD';end if;
   end if;
  end if;
  return jsonb_build_object('ok',true,'outcome',outcome,'state',state,'receipt',receipt);
 end if;
 if prior is not null then return prior;end if;
 if cfg.state<>'CONFIGURED' then raise exception using errcode='55000',message='PRODUCTION_NET_SKINS_CONFIGURATION_REQUIRED';end if;
 if p->'expected_configuration_revision' is distinct from to_jsonb(cfg.configuration_revision) then
  raise exception using errcode='40001',message='PRODUCTION_NET_SKINS_CONFIGURATION_REVISION_CONFLICT';end if;
 if p->'entry_revisions' is distinct from expected_entries or exists(select 1 from jsonb_array_elements(rounds)v
  where v->'entry_revision' is distinct from v->'current_entry_revision') then
  raise exception using errcode='40001',message='FULL_NET_ENTRY_REVISION_STALE_OR_UNAVAILABLE';end if;
 if p->'source_fingerprints' is distinct from sources then
  raise exception using errcode='40001',message='PRODUCTION_NET_SKINS_SOURCE_REVISION_CONFLICT';end if;
 -- Shipping separates explicit enqueue from process. Configuration can be
 -- saved after scores finalized, leaving no job/score intent. Materialize at
 -- most one missing configured-round demand through that same private core.
 -- Preserve a successful same-source output and exhausted/failed job history;
 -- ordinary calculation never grants a replacement budget to either.
 for round_lock in 1..3 loop
  perform pg_advisory_xact_lock(hashtextextended(format('production-net-skins-v1:enqueue:2026:R%s',round_lock),202608290055));
 end loop;
 for r in select value from jsonb_array_elements(manifest->'rounds')order by (value->>'round_number')::integer loop
  if not exists(select 1 from scoring_authority.net_skins_v1_recalculation_jobs where tournament_id='2026'
    and round_number=(r->>'round_number')::integer and configuration_revision=cfg.configuration_revision
    and source_fingerprint=sources->>(r->>'round_number') and status<>'SUPERSEDED')
   and not exists(select 1 from scoring_authority.net_skins_v1_result_revisions where tournament_id='2026'
    and round_number=(r->>'round_number')::integer and configuration_revision=cfg.configuration_revision
    and source_fingerprint=sources->>(r->>'round_number') and is_current)then
   perform production_control.enqueue_production_net_skins_v1_round((r->>'round_number')::integer,'DIRECTOR_CALCULATION_REQUEST',input#>>'{authorization,player_id}');
   exit;
  end if;
 end loop;
 -- Canonical claim supplies the input/job. The caller never selects either.
 phase_fp:=encode(extensions.digest('production-net-skins-v1'||chr(10)||'CLAIM'||chr(10)||base,'sha256'),'hex');
 command:=jsonb_build_object('expected_configuration_revision',cfg.configuration_revision,'worker_id','certification-net-skins-director-v1',
  'lease_seconds',60,'request_fingerprint',phase_fp,'expected_activation_revision',context->'activation_revision',
  'tournament_id','2026','environment','CERTIFICATION','expected_epoch_id',context->>'authority_epoch_id','authorization',input->'authorization');
 claimed:=production_control.canonical_claim_net_skins_v1_recalculation_core_v2(command,context);
 if claimed->'job'<>'null'::jsonb and claimed#>>'{job,source_fingerprint}' is distinct from p#>>array['source_fingerprints',claimed#>>'{job,round_number}'] then
  raise exception using errcode='40001',message='PRODUCTION_NET_SKINS_SOURCE_REVISION_CONFLICT';end if;
 perform production_control.store_cutover_receipt('CERTIFICATION_NET_SKINS_CALCULATION',identity,claimed);
 return claimed;
end;
$_$;


ALTER FUNCTION production_control.dispatch_certification_net_skins_calculation_v1(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: dispatch_certification_net_skins_configuration_v1(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_net_skins_configuration_v1(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare payload jsonb:=input->'payload';command jsonb;current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
 revision_value scoring_authority.net_skins_v1_configuration_revisions%rowtype;
begin
 perform production_control.assert_canonical_scoring_context_v1('{}',context,'RUNTIME');
 if context->>'tournament_id' is distinct from '2026' or context->>'resource_class' is distinct from 'CERTIFICATION'
   or (not production_control.model_d_context_v1(context) and (context->>'resource_id' is distinct from 'CERTIFICATION:2857f707-065a-405d-b5fc-b5b6fa1b0f51' or context->>'project_ref' is distinct from 'trmcwrljjxwhgtikfdgu'))
   or input->>'phase' is distinct from 'DIRECTOR'
   or input#>>'{authorization,tournament_id}' is distinct from context->>'tournament_id' then
   raise exception using errcode='42501',message='CERTIFICATION_NET_SKINS_TARGET_DENIED'; end if;
 perform production_control.assert_production_scoring_actor(jsonb_build_object('authorization',input->'authorization'),true);
 if jsonb_typeof(payload) is distinct from 'object' or payload->>'family' is distinct from 'NET_SKINS_CONFIGURATION' then
   raise exception using errcode='22023',message='CERTIFICATION_NET_SKINS_INPUT_INVALID'; end if;
 if not mutation then
   if input->>'operation_id' is distinct from 'DIRECTOR.READ_NET_SKINS_CONFIGURATION'
     or payload->>'action' is distinct from 'read'
     or exists(select 1 from jsonb_object_keys(payload) k where k not in('family','action')) then
     raise exception using errcode='42501',message='CERTIFICATION_NET_SKINS_INPUT_DENIED'; end if;
   select * into current_value from scoring_authority.net_skins_v1_configuration_current where tournament_id='2026';
   select * into revision_value from scoring_authority.net_skins_v1_configuration_revisions
     where configuration_revision_id=current_value.configuration_revision_id;
   return jsonb_build_object('ok',true,'tournament_id','2026','configuration_revision',coalesce(current_value.configuration_revision,0),
     'configuration_fingerprint',revision_value.configuration_fingerprint,'state',coalesce(current_value.state,'NOT_CONFIGURED'),
     'rounds',coalesce(revision_value.configuration_manifest->'rounds','[]'::jsonb));
 end if;
 if input->>'operation_id' is distinct from 'DIRECTOR.CONFIGURE_NET_SKINS' or payload->>'action' is distinct from 'configure'
   or exists(select 1 from jsonb_object_keys(payload) k where k not in('family','action','expected_configuration_revision','eligible_round_numbers','entry_revisions'))
   or jsonb_typeof(payload->'entry_revisions') is distinct from 'object'
   or coalesce(payload->>'expected_configuration_revision','') !~ '^(0|[1-9][0-9]*)$' then
   raise exception using errcode='22023',message='CERTIFICATION_NET_SKINS_INPUT_INVALID'; end if;
 -- The operation ID is already admitted by the durable ingress/actor gateway.
 -- No request fingerprint or resource material can be supplied in the DTO.
 command:=(payload-array['family','action'])||jsonb_build_object('contract_version','production-net-skins-v1',
   'publication_policy','OFFICIAL_ONLY','tournament_id',context->>'tournament_id','authorization',input->'authorization',
   'expected_epoch_id',context->>'authority_epoch_id','expected_activation_revision',(context->>'activation_revision')::bigint,
   'vercel_project_id',context->>'vercel_project_id','vercel_team_id',context->>'vercel_team_id',
   'request_fingerprint',production_control.certification_net_skins_configuration_fingerprint_v1(context->>'resource_id',input->>'operation_request_id'));
 return production_control.canonical_configure_net_skins_v1(command,context);
exception when raise_exception then
 -- Adapt only the manifest's documented saved-entry CAS denial. Infrastructure
 -- failures retain their original SQLSTATE; Production's null-context path is unchanged.
 if SQLERRM='FULL_NET_ENTRY_REVISION_STALE_OR_UNAVAILABLE' then
   raise exception using errcode='PT409',message='PRODUCTION_NET_SKINS_ENTRY_REVISION_CONFLICT';
 end if;
 raise;
end;$_$;


ALTER FUNCTION production_control.dispatch_certification_net_skins_configuration_v1(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: dispatch_certification_odds_configuration_v1(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_odds_configuration_v1(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
 op text:=input->>'operation_id';p jsonb:=input->'payload';target text:=context->>'tournament_id';
 actor text:=input#>>'{authorization,player_id}';request_id text:=lower(input->>'operation_request_id');
 cfg scoring_authority.odds_input_configurations%rowtype;proposed jsonb;validation jsonb;
 identity jsonb;prior jsonb;receipt jsonb;source_id text;source_hash text;pairing_hash text;ratings_hash text;bundle_hash text;
 revision bigint;new_id uuid;at_time timestamptz:=clock_timestamp();
begin
 perform production_control.assert_canonical_scoring_context_v1('{}',context,'RUNTIME');
 if context is distinct from production_control.current_certification_context_v1()
  or context->>'phase' is distinct from 'DIRECTOR' or target is distinct from '2026'
  or (not production_control.model_d_context_v1(context) and (context->>'resource_id' is distinct from 'CERTIFICATION:2857f707-065a-405d-b5fc-b5b6fa1b0f51' or context->>'project_ref' is distinct from 'trmcwrljjxwhgtikfdgu'))
  or op not in('DIRECTOR.CONFIGURE_ODDS_INPUTS','DIRECTOR.READ_ODDS_INPUT_CONFIGURATION','DIRECTOR.ODDS_INPUT_CONFIGURATION_STATUS')
  or mutation is distinct from (op='DIRECTOR.CONFIGURE_ODDS_INPUTS') then
  raise exception using errcode='42501',message='CERTIFICATION_ODDS_CONFIGURATION_CONTEXT_DENIED';end if;
 perform production_control.assert_production_scoring_actor(jsonb_build_object('tournament_id',target,'authorization',input->'authorization'),true);
 if jsonb_typeof(p) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p)k
  where k not in('expected_configuration_revision','profile','confirmation','reason')) then
  raise exception using errcode='22023',message='CERTIFICATION_ODDS_CONFIGURATION_INPUT_INVALID';end if;
 select * into cfg from scoring_authority.odds_input_configurations where tournament_id=target and is_current;
 if op='DIRECTOR.READ_ODDS_INPUT_CONFIGURATION' then
  if p<>'{}'::jsonb then raise exception using errcode='22023',message='CERTIFICATION_ODDS_CONFIGURATION_INPUT_INVALID';end if;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('tournament_id',target,
   'configuration_revision',coalesce(cfg.configuration_revision,0),'configuration_id',cfg.id,
   'state',case when cfg.id is null then 'NOT_CONFIGURED' else 'CONFIGURED' end,
   'profile','CERTIFICATION_DEFAULTS_V1','provenance',cfg.validation_diagnostics->>'authoringAuthority'));
 end if;
 if coalesce(request_id,'') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  or jsonb_typeof(p->'expected_configuration_revision') is distinct from 'number'
  or p->>'expected_configuration_revision' !~ '^[0-9]+$'
  or p->>'profile' is distinct from 'CERTIFICATION_DEFAULTS_V1'
  or p->>'confirmation' is distinct from 'CONFIGURE SYNTHETIC ODDS INPUTS'
  or coalesce(btrim(p->>'reason'),'')='' or length(p->>'reason')>500 then
  raise exception using errcode='22023',message='CERTIFICATION_ODDS_CONFIGURATION_INPUT_INVALID';end if;
 identity:=jsonb_build_object('request_fingerprint',production_control.prediction_settings_hash_v1(jsonb_build_object(
  'contract','certification-odds-input-configuration-v1','resource_id',context->>'resource_id','operation_id',request_id,
  'actor',input->'authorization')),'request_payload_hash',production_control.prediction_settings_hash_v1(p));
 perform pg_advisory_xact_lock(hashtextextended('certification-odds-inputs:'||target,0));
 prior:=production_control.lookup_cutover_receipt('CERTIFICATION_ODDS_INPUT_CONFIGURATION',identity);
 if op='DIRECTOR.ODDS_INPUT_CONFIGURATION_STATUS' then
  return jsonb_build_object('ok',true,'outcome',case when prior is null then 'NOT_COMMITTED' else 'COMMITTED' end,
   'receipt',prior);end if;
 if prior is not null then return prior||jsonb_build_object('idempotent',true);end if;
 select * into cfg from scoring_authority.odds_input_configurations where tournament_id=target and is_current for update;
 if coalesce(cfg.configuration_revision,0)<>(p->>'expected_configuration_revision')::bigint then
  raise exception using errcode='40001',message='PREDICTION_SETTINGS_PREDECESSOR_STALE';end if;
 -- Fixed reviewed synthetic profile, drawn from the canonical definitions,
 -- never from Production/Google/current settings or client-selected values.
 select jsonb_object_agg(setting_key,default_value)into proposed from production_control.prediction_setting_definitions_v1;
 validation:=production_control.validate_prediction_settings_v1(proposed,cfg.canonical_settings);
 if not coalesce((validation->>'pass')::boolean,false) or validation->>'settingsFingerprint' is distinct from
  'd95218665e2dac25867f6f7f40b4c16256201e6b51eaa38152cb88a2cc92b4c0' then
  raise exception using errcode='22023',message='PREDICTION_SETTINGS_VALIDATION_FAILED';end if;
 if cfg.id is not null and cfg.canonical_settings=validation->'canonicalSettings'
  and cfg.validation_diagnostics->>'authoringAuthority'='CERTIFICATION_SYNTHETIC' then
  receipt:=jsonb_build_object('ok',true,'code','CERTIFICATION_ODDS_INPUTS_UNCHANGED','configuration_id',cfg.id,
   'configuration_revision',cfg.configuration_revision,'idempotent',true,'provenance','CERTIFICATION_SYNTHETIC');
 else
  select provenance_id into strict source_id from production_control.canonical_resource_v1 where singleton;
  select coalesce(max(configuration_revision),0)+1 into revision from scoring_authority.odds_input_configurations where tournament_id=target;
  pairing_hash:=production_control.annual_odds_pairing_fingerprint_v1(target);
  ratings_hash:=production_control.prediction_settings_hash_v1('{}'::jsonb);
  source_hash:=production_control.prediction_settings_hash_v1(jsonb_build_object('contract','certification-odds-input-configuration-v1',
   'resource_id',context->>'resource_id','installation_id',context->>'installation_id','tournament_id',target,
   'configuration_revision',revision,'profile',p->>'profile','settings',validation->'canonicalSettings','historical_ratings','{}'::jsonb));
  bundle_hash:=production_control.prediction_settings_hash_v1(jsonb_build_object('contract','production-odds-input-bundle-v1',
   'tournament_id',target,'configuration_revision',revision,'source_fingerprint',source_hash,
   'settings_fingerprint',validation->>'settingsFingerprint','effective_settings_fingerprint',validation->>'effectiveSettingsFingerprint',
   'ratings_fingerprint',ratings_hash,'pairing_fingerprint',pairing_hash));
  update scoring_authority.odds_input_configurations set is_current=false,superseded_at=at_time where tournament_id=target and is_current;
  insert into scoring_authority.odds_input_configurations(tournament_id,configuration_revision,source_workbook_id,
   settings,historical_ratings,settings_fingerprint,ratings_fingerprint,pairing_fingerprint,bundle_fingerprint,is_current,
   imported_by,source_tab,source_fingerprint,canonical_settings,effective_settings,effective_settings_fingerprint,
   settings_contract_version,validation_status,validation_diagnostics,synchronized_at,previous_configuration_id)
  values(target,revision,source_id,validation->'settingsRows','{}',validation->>'settingsFingerprint',ratings_hash,pairing_hash,bundle_hash,true,
   'Certification Synthetic Director '||actor,'Certification Synthetic Prediction Settings',source_hash,
   validation->'canonicalSettings',validation->'effectiveSettings',validation->>'effectiveSettingsFingerprint','prediction-settings-v1','VALID',
   jsonb_build_object('authoringAuthority','CERTIFICATION_SYNTHETIC','authoringContract','certification-odds-input-configuration-v1',
    'profile',p->>'profile','synthetic',true,'ownerApproved',true,'googleAccess',false,'productionSource',false,
    'resource_id',context->>'resource_id','release_commit',context->>'release_commit','deployment_id',context->>'deployment_id',
    'director_player_id',actor,'director_auth_user_id',input#>>'{authorization,auth_user_id}',
    'completeSchema',true,'reason',p->>'reason','automaticCalculationRequested',false,'automaticPublicationRequested',false),
   at_time,cfg.id)returning scoring_authority.odds_input_configurations.id into new_id;
  receipt:=jsonb_build_object('ok',true,'code','CERTIFICATION_ODDS_INPUTS_CONFIGURED','configuration_id',new_id,
   'configuration_revision',revision,'idempotent',false,'provenance','CERTIFICATION_SYNTHETIC');
  insert into production_control.prediction_settings_audit_events_v1(tournament_id,configuration_id,action,
   actor_player_id,actor_auth_user_id,operation_request_id,request_payload_hash,summary)
  values(target,new_id,'REVISION_COMMITTED',actor,(input#>>'{authorization,auth_user_id}')::uuid,request_id::uuid,
   identity->>'request_payload_hash',receipt||jsonb_build_object('synthetic',true,'googleAccess',false,'productionSource',false));
 end if;
 perform production_control.store_cutover_receipt('CERTIFICATION_ODDS_INPUT_CONFIGURATION',identity,receipt);
 return receipt;
end;
$_$;


ALTER FUNCTION production_control.dispatch_certification_odds_configuration_v1(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: dispatch_certification_operation_v1(jsonb, jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.dispatch_certification_operation_v1(input jsonb, context jsonb, mutation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
 operation_id text:=input->>'operation_id'; payload jsonb:=input->'payload'; command jsonb;
 actor_context jsonb; dispatch_input jsonb; family text; action text; result jsonb;
 status_read boolean:=not mutation and operation_id in('DIRECTOR.SETUP_STATUS','DIRECTOR.MATCH_CONTROL_STATUS','DIRECTOR.NET_SKINS_STATUS','DIRECTOR.CALCUTTA_STATUS');
begin
 if operation_id in('DIRECTOR.CONFIGURE_ODDS_INPUTS','DIRECTOR.READ_ODDS_INPUT_CONFIGURATION','DIRECTOR.ODDS_INPUT_CONFIGURATION_STATUS') then
  return production_control.dispatch_certification_odds_configuration_v1(input,context,mutation);end if;
 if operation_id in('DIRECTOR.CALCULATE_NET_SKINS','DIRECTOR.READ_NET_SKINS_CALCULATION','DIRECTOR.NET_SKINS_CALCULATION_STATUS') then
  return production_control.dispatch_certification_net_skins_calculation_v1(input,context,mutation);end if;
 if operation_id in('DIRECTOR.PUBLISH_CALCUTTA','DIRECTOR.READ_CALCUTTA_PUBLICATION') then
  return production_control.dispatch_certification_calcutta_publication_v1(input,context,mutation);end if;
 if operation_id in('DIRECTOR.CONFIGURE_NET_SKINS','DIRECTOR.READ_NET_SKINS_CONFIGURATION') then
  return production_control.dispatch_certification_net_skins_configuration_v1(input,context,mutation);
 end if;
 if mutation and (operation_id like 'WORKERS.%' or operation_id in('DIRECTOR.NET_SKINS_CLAIM','DIRECTOR.NET_SKINS_COMPLETE','DIRECTOR.NET_SKINS_FAIL','DIRECTOR.REQUEUE_DERIVED')) then
  return production_control.dispatch_certification_derived_operation_v1(input,context);
 end if;
 if (context->>'current_tournament_year')::integer>2026 then
  return production_control.dispatch_certification_future_scoring_v1(input,context,mutation);
 end if;
 -- The marker is owner-only and revalidates registered resource/deployment,
 -- current pointer, admission revision and live ingress under transaction locks.
 perform production_control.assert_canonical_scoring_context_v1('{}'::jsonb,context,'RUNTIME');
 if jsonb_typeof(payload) is distinct from 'object' then
  raise exception using errcode='22023',message='CERTIFICATION_OPERATION_INPUT_INVALID'; end if;
 if status_read and (coalesce(input->>'operation_request_id','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  or coalesce(payload->>'original_context_token','') !~ '^[0-9a-f]{64}$') then
  raise exception using errcode='22023',message='CERTIFICATION_OPERATION_RECOVERY_INPUT_REQUIRED'; end if;
 if payload ?| array['resource','deployment','authorization','environment','project_ref','project_url',
  'actor_player_id','actor_auth_user_id','auth_user_id','role','context_token','expected_context_token',
  'binding_id','resource_id','resource_class','installation_id','release_commit','activation_revision',
  'admission_revision','governance_tournament_id'] or (payload ? 'player_id' and not coalesce(
   operation_id='DIRECTOR.CLEAR_CALCUTTA_AUCTION' or
   (operation_id='DIRECTOR.MUTATE_SETUP' and payload->>'action'='assign-roster-team'),false)) then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_AUTHORITY_FIELD_REJECTED'; end if;
 if (payload ? 'tournament_id' and payload->>'tournament_id' is distinct from context->>'tournament_id')
  or (payload ? 'expected_epoch_id' and payload->>'expected_epoch_id' is distinct from context->>'authority_epoch_id')
  or (input#>>'{authorization,tournament_id}' is not null and input#>>'{authorization,tournament_id}' is distinct from context->>'tournament_id') then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_TARGET_MISMATCH'; end if;
 command:=payload||jsonb_build_object('tournament_id',context->>'tournament_id',
  'expected_epoch_id',context->>'authority_epoch_id','authorization',input->'authorization');
 if mutation and operation_id like 'SCORING.%' and command->>'mutation_key' is distinct from input->>'operation_request_id' then
  raise exception using errcode='22023',message='CERTIFICATION_OPERATION_ID_MISMATCH'; end if;
 if operation_id in('SCORING.REOPEN_MATCH') or operation_id like 'DIRECTOR.%' then
  perform production_control.assert_production_scoring_actor(command,true);
  actor_context:=context||jsonb_build_object('actor_player_id',input#>>'{authorization,player_id}',
   'actor_auth_user_id',input#>>'{authorization,auth_user_id}','authorization',input->'authorization',
   'operation_request_id',input->>'operation_request_id',
   'resource_fingerprint',production_control.cutover_payload_hash(input->'resource'));
 end if;
 case operation_id
 when 'SCORING.READ_AUTHORITY' then
  return production_control.canonical_read_scoring_authority_v2(command,context);
 when 'SCORING.READ_PARTICIPANT_CONTEXT' then
  return production_control.canonical_read_scoring_participant_context_v2(command||jsonb_build_object(
   'player_id',input#>>'{authorization,player_id}','auth_user_id',input#>>'{authorization,auth_user_id}',
   'role',input#>>'{authorization,role}'),context);
 when 'SCORING.READ_MUTATION_STATUS' then
  return production_control.read_score_mutation_status_v1(command,'2026');
 when 'SCORING.SUBMIT_HOLE' then
  return production_control.canonical_submit_hole_score_v2(command,context);
 when 'SCORING.FINALIZE_MATCH' then
  return production_control.canonical_finalize_match_v2(command,context);
 when 'SCORING.REOPEN_MATCH' then
  return production_control.canonical_reopen_match_v2(command,context);
 when 'DIRECTOR.READ_SETUP' then
  family:=coalesce(payload->>'family','TOURNAMENT_SETUP'); action:='read';
  if family not in('TOURNAMENT_SETUP','ROUND_PAIRINGS','MATCH_CONTROL') then
   raise exception using errcode='22023',message='CERTIFICATION_OPERATION_INPUT_INVALID'; end if;
 when 'DIRECTOR.MUTATE_SETUP' then family:='TOURNAMENT_SETUP'; action:=payload->>'action';
 when 'DIRECTOR.SETUP_STATUS' then
  family:=coalesce(payload->>'family','TOURNAMENT_SETUP'); action:=payload->>'action';
  if family not in('TOURNAMENT_SETUP','ROUND_PAIRINGS') then
   raise exception using errcode='22023',message='CERTIFICATION_OPERATION_INPUT_INVALID'; end if;
 when 'DIRECTOR.MUTATE_PAIRINGS' then family:='ROUND_PAIRINGS'; action:='replace-round-pairings';
 when 'DIRECTOR.MATCH_CONTROL' then family:='MATCH_CONTROL'; action:=payload->>'action';
 when 'DIRECTOR.MATCH_CONTROL_STATUS' then family:='MATCH_CONTROL'; action:=payload->>'action';
 when 'DIRECTOR.READ_NET_SKINS' then family:='NET_SKINS_ENTRIES'; action:='read';
 when 'DIRECTOR.SAVE_NET_SKINS_ENTRIES' then family:='NET_SKINS_ENTRIES'; action:='save';
 when 'DIRECTOR.NET_SKINS_STATUS' then family:='NET_SKINS_ENTRIES'; action:='save';
 when 'DIRECTOR.READ_CALCUTTA' then family:='CALCUTTA_MANAGEMENT'; action:='read';
 when 'DIRECTOR.CALCUTTA_STATUS' then family:='CALCUTTA_MANAGEMENT'; action:=payload->>'action';
 when 'DIRECTOR.REPLACE_CALCUTTA_AUCTION' then family:='CALCUTTA_MANAGEMENT'; action:='replace-auction';
 when 'DIRECTOR.CLEAR_CALCUTTA_AUCTION' then family:='CALCUTTA_MANAGEMENT'; action:='clear-entry';
 else raise exception using errcode='42501',message='CERTIFICATION_OPERATION_NOT_ADMITTED';
 end case;
 dispatch_input:=input||jsonb_build_object('family',family,'action',action,'payload',payload-array['action','family','original_context_token']);
 if status_read then
  -- The original token is receipt-hash provenance only. The current outer
  -- context was freshly admitted and remains the sole execution authority.
  dispatch_input:=dispatch_input||jsonb_build_object('mode','status','expected_context_token',payload->>'original_context_token');
 end if;
 if family in('TOURNAMENT_SETUP','ROUND_PAIRINGS','MATCH_CONTROL') then
  return production_control.canonical_director_setup_operation_v2(dispatch_input,actor_context,mutation);
 end if;
 return production_control.canonical_director_financial_operation_v2(dispatch_input,actor_context,mutation);
end;
$_$;


ALTER FUNCTION production_control.dispatch_certification_operation_v1(input jsonb, context jsonb, mutation boolean) OWNER TO postgres;

--
-- Name: draft_authoring_canonical_json_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_authoring_canonical_json_v1(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select production_control.prediction_settings_canonical_json_v1(value)
$$;


ALTER FUNCTION production_control.draft_authoring_canonical_json_v1(value jsonb) OWNER TO postgres;

--
-- Name: draft_authoring_hash_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_authoring_hash_v1(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
  select pg_catalog.encode(extensions.digest(
    production_control.draft_authoring_canonical_json_v1(value), 'sha256'
  ), 'hex')
$$;


ALTER FUNCTION production_control.draft_authoring_hash_v1(value jsonb) OWNER TO postgres;

--
-- Name: draft_commit_pick_provenance_v1(jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_commit_pick_provenance_v1(proposed jsonb, actor_player text, committed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  item jsonb;
  result_value jsonb := '[]'::jsonb;
begin
  for item in
    select value from pg_catalog.jsonb_array_elements(proposed)
    order by (value->>'pick_number')::integer
  loop
    if pg_catalog.btrim(coalesce(item->>'player_id','')) <> '' then
      item := item || pg_catalog.jsonb_build_object(
        'selected_at',coalesce(nullif(pg_catalog.btrim(
          item->>'selected_at'),''), committed_at::text),
        'selected_by',coalesce(nullif(pg_catalog.btrim(
          item->>'selected_by'),''), actor_player)
      );
    else
      item := item || pg_catalog.jsonb_build_object(
        'selected_at','','selected_by',''
      );
    end if;
    result_value := result_value || pg_catalog.jsonb_build_array(item);
  end loop;
  return result_value;
end;
$$;


ALTER FUNCTION production_control.draft_commit_pick_provenance_v1(proposed jsonb, actor_player text, committed_at timestamp with time zone) OWNER TO postgres;

--
-- Name: draft_date_valid_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_date_valid_v1(value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  parts text[];
  year_value integer;
  month_value integer;
  day_value integer;
begin
  if pg_catalog.btrim(value)='' then return true; end if;
  parts:=pg_catalog.regexp_match(pg_catalog.btrim(value),
    '^([0-9]{4})-([0-9]{1,2})-([0-9]{1,2})$');
  if parts is not null then
    year_value:=parts[1]::integer;
    month_value:=parts[2]::integer;
    day_value:=parts[3]::integer;
  else
    parts:=pg_catalog.regexp_match(pg_catalog.btrim(value),
      '^([0-9]{1,2})/([0-9]{1,2})/([0-9]{4})$');
    if parts is null then return false; end if;
    month_value:=parts[1]::integer;
    day_value:=parts[2]::integer;
    year_value:=parts[3]::integer;
  end if;
  perform pg_catalog.make_date(year_value,month_value,day_value);
  return true;
exception when datetime_field_overflow or invalid_datetime_format then
  return false;
end;
$_$;


ALTER FUNCTION production_control.draft_date_valid_v1(value text) OWNER TO postgres;

--
-- Name: draft_mutability_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_mutability_v1(target text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  current_revision uuid;
  total_value integer := 0;
  selected_value integer := 0;
  status_value text := '';
begin
  select value.revision_id into current_revision
  from scoring_authority.draft_current_revisions value
  where value.tournament_id=target;
  if current_revision is null then
    return pg_catalog.jsonb_build_object(
      'state','SETUP_EDITABLE','editable',true,
      'code','DRAFT_NOT_CONFIGURED'
    );
  end if;
  select value.total_picks,coalesce(value.status_mode,'')
    into total_value,status_value
  from scoring_authority.draft_configuration_facts value
  where value.revision_id=current_revision;
  select pg_catalog.count(*)::integer into selected_value
  from scoring_authority.draft_pick_facts value
  where value.revision_id=current_revision and value.pick_status='SELECTED';
  if pg_catalog.upper(status_value)='COMPLETE'
     or (total_value>0 and selected_value>=total_value) then
    return pg_catalog.jsonb_build_object(
      'state','CORRECTION_REQUIRED','editable',false,
      'code','DRAFT_CORRECTION_REQUIRED',
      'selectedPicks',selected_value,'totalPicks',total_value
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'state',case when selected_value>0 then 'IN_PROGRESS'
      else 'SETUP_EDITABLE' end,
    'editable',true,'code','DRAFT_EDITABLE',
    'selectedPicks',selected_value,'totalPicks',total_value
  );
end;
$$;


ALTER FUNCTION production_control.draft_mutability_v1(target text) OWNER TO postgres;

--
-- Name: draft_operation_receipt_v1(text, text, uuid, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_operation_receipt_v1(target text, operation_value text, request_id uuid, declared_hash text, database_hash text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  receipt production_control.draft_operation_receipts_v1%rowtype;
begin
  select value.* into receipt
  from production_control.draft_operation_receipts_v1 value
  where value.tournament_id=target
    and value.operation=operation_value
    and value.operation_request_id=request_id;
  if not found then return null; end if;
  if receipt.declared_request_payload_hash=declared_hash
     and receipt.request_payload_hash=database_hash then
    return receipt.response || pg_catalog.jsonb_build_object(
      'idempotent',true);
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','DRAFT_IDEMPOTENCY_CONFLICT');
end;
$$;


ALTER FUNCTION production_control.draft_operation_receipt_v1(target text, operation_value text, request_id uuid, declared_hash text, database_hash text) OWNER TO postgres;

--
-- Name: draft_player_presentation_v1(text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_player_presentation_v1(target text, target_player text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
  select case when player.player_id is null then null else
    pg_catalog.jsonb_build_object(
      'id', player.player_id,
      'name', player.display_name,
      'image', case when coalesce(player.source_payload->>'Photo Filename','')=''
        then null else '/images/players/' ||
          pg_catalog.regexp_replace(player.source_payload->>'Photo Filename',
            '\.(png|jpe?g|webp|avif)$', '', 'i') || '.webp' end,
      'handicap', membership.tournament_handicap
    ) end
  from scoring_authority.players player
  join scoring_authority.tournament_players membership
    on membership.tournament_id = target
   and membership.player_id = player.player_id
   and membership.participation_status = 'ACTIVE'
  where player.player_id = target_player
$_$;


ALTER FUNCTION production_control.draft_player_presentation_v1(target text, target_player text) OWNER TO postgres;

--
-- Name: draft_projection_row_v1(uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_projection_row_v1(target_revision uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  revision scoring_authority.draft_revisions%rowtype;
  picks_value jsonb;
  authority_value text;
begin
  select value.* into strict revision
  from scoring_authority.draft_revisions value
  where value.revision_id=target_revision;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'pick_number',pick.pick_number,
    'round_number',pick.round_number,
    'pick_within_round',pick.pick_within_round,
    'source_team_id',coalesce(pick.source_team_id,''),
    'team_id',coalesce(pick.team_id,''),
    'player_id',coalesce(pick.player_id,''),
    'player_name',coalesce(pick.player_name_snapshot,''),
    'selected_at',coalesce(pick.selected_at_source,''),
    'selected_by',coalesce(pick.selected_by_source,''),
    'status',pick.pick_status,'notes',coalesce(pick.notes,''),
    'presentation',pick.presentation_snapshot
  ) order by pick.pick_number),'[]'::jsonb) into picks_value
  from scoring_authority.draft_pick_facts pick
  where pick.revision_id=target_revision;
  authority_value := case when exists (
    select 1 from production_control.draft_revision_provenance_v1 value
    where value.revision_id=target_revision
  ) then 'SUPABASE_DIRECTOR' else 'GOOGLE_SYNCHRONIZATION' end;
  return pg_catalog.jsonb_build_object(
    'tournament_id',revision.tournament_id,
    'tournament_year',revision.tournament_year,
    'year',revision.tournament_year,
    'revision_id',revision.revision_id,
    'revision_number',revision.revision_number,
    'previous_revision_id',revision.previous_revision_id,
    'source_fingerprint',revision.source_fingerprint,
    'configuration_fingerprint',revision.configuration_fingerprint,
    'picks_fingerprint',revision.picks_fingerprint,
    'payload_fingerprint',revision.payload_fingerprint,
    'contract_version',revision.contract_version,
    'validation_status',revision.validation_status,
    'validation_diagnostics',revision.validation_diagnostics,
    'configuration',revision.configuration,
    'picks',picks_value,'normalized_picks',picks_value,
    'presentation_seed',revision.presentation_seed,
    'operation',revision.operation,
    'synchronized_by',revision.synchronized_by,
    'synchronized_at',revision.synchronized_at,
    'authoring_authority',authority_value
  );
end;
$$;


ALTER FUNCTION production_control.draft_projection_row_v1(target_revision uuid) OWNER TO postgres;

--
-- Name: draft_sanitize_pick_provenance_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_sanitize_pick_provenance_v1(proposed jsonb, predecessor jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  item jsonb;
  prior jsonb;
  result_value jsonb := '[]'::jsonb;
begin
  if pg_catalog.jsonb_typeof(proposed) is distinct from 'array'
     or pg_catalog.jsonb_typeof(predecessor) is distinct from 'array' then
    return '[]'::jsonb;
  end if;
  for item in
    select value from pg_catalog.jsonb_array_elements(proposed)
    order by (value->>'pick_number')::integer
  loop
    select value into prior
    from pg_catalog.jsonb_array_elements(predecessor) value
    where value->>'pick_number' = item->>'pick_number'
    limit 1;
    if prior is not null
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
         prior->>'team_id',''))) = pg_catalog.upper(pg_catalog.btrim(coalesce(
         item->>'team_id','')))
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
         prior->>'player_id',''))) = pg_catalog.upper(pg_catalog.btrim(coalesce(
         item->>'player_id',''))) then
      result_value := result_value || pg_catalog.jsonb_build_array(
        item || pg_catalog.jsonb_build_object(
          'selected_at',coalesce(prior->>'selected_at',''),
          'selected_by',coalesce(prior->>'selected_by','')
        ));
    else
      result_value := result_value || pg_catalog.jsonb_build_array(
        item || pg_catalog.jsonb_build_object(
          'selected_at','','selected_by',''
        ));
    end if;
    prior := null;
  end loop;
  return result_value;
end;
$$;


ALTER FUNCTION production_control.draft_sanitize_pick_provenance_v1(proposed jsonb, predecessor jsonb) OWNER TO postgres;

--
-- Name: draft_team_presentation_v1(text, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_team_presentation_v1(target text, target_team text, captain_player text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
  select pg_catalog.jsonb_build_object(
    'id', team.team_id,
    'side', 'Team ' || team.team_side,
    'name', team.name,
    'logo', coalesce(nullif(team.source_payload->>'Team Logo', ''),
      nullif(team.source_payload->>'Logo Filename', ''), ''),
    'primaryColor', coalesce(nullif(team.source_payload->>'Primary Color', ''),
      '#0b4a3a'),
    'secondaryColor', coalesce(
      nullif(team.source_payload->>'Secondary Color', ''), '#d4b15f'),
    'averageHandicap', (
      select case
        when pg_catalog.count(*) > 0
         and pg_catalog.count(membership.tournament_handicap) =
           pg_catalog.count(*)
          then pg_catalog.avg(membership.tournament_handicap)
        else null
      end
      from scoring_authority.tournament_players membership
      where membership.tournament_id = target
        and membership.team_id = target_team
        and membership.participation_status = 'ACTIVE'
    ),
    'captainId', coalesce(captain_player, ''),
    'captain', case when player.player_id is null then null else
      pg_catalog.jsonb_build_object(
        'id', player.player_id,
        'name', player.display_name,
        'image', case when coalesce(player.source_payload->>'Photo Filename','')=''
          then null else '/images/players/' ||
            pg_catalog.regexp_replace(player.source_payload->>'Photo Filename',
              '\.(png|jpe?g|webp|avif)$', '', 'i') || '.webp' end
      ) end
  )
  from scoring_authority.teams team
  left join scoring_authority.players player
    on player.player_id = nullif(captain_player, '')
  where team.tournament_id = target and team.team_id = target_team
$_$;


ALTER FUNCTION production_control.draft_team_presentation_v1(target text, target_team text, captain_player text) OWNER TO postgres;

--
-- Name: draft_time_valid_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_time_valid_v1(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
  select pg_catalog.btrim(value)=''
    or pg_catalog.btrim(value) ~
      '^(?:[01]?[0-9]|2[0-3]):[0-5][0-9]$'
    or pg_catalog.btrim(value) ~*
      '^(?:0?[1-9]|1[0-2]):[0-5][0-9][[:space:]](?:AM|PM)$'
$_$;


ALTER FUNCTION production_control.draft_time_valid_v1(value text) OWNER TO postgres;

--
-- Name: draft_time_zone_valid_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.draft_time_zone_valid_v1(value text) RETURNS boolean
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
  select pg_catalog.btrim(value)=''
    or pg_catalog.upper(pg_catalog.btrim(value)) in (
      'UTC','GMT','CST','CDT','EST','EDT','MST','MDT','PST','PDT'
    )
    or (
      pg_catalog.btrim(value) ~
        '^[A-Za-z_]+(?:/[A-Za-z0-9_+.-]+)+$'
      and exists (select 1 from pg_catalog.pg_timezone_names zone
        where zone.name=pg_catalog.btrim(value))
    )
$_$;


ALTER FUNCTION production_control.draft_time_zone_valid_v1(value text) OWNER TO postgres;

--
-- Name: drain_certification_annual_predecessor_v1(uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.drain_certification_annual_predecessor_v1(target_closure uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c jsonb:=production_control.annual_resource_context_v2();e jsonb;revisions jsonb;closed production_control.scoring_admission_closures%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;
begin
 if c->>'resource_class' is distinct from 'CERTIFICATION' or c->>'phase' is distinct from 'ANNUAL' then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CONTEXT_REQUIRED';end if;
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 select * into strict closed from production_control.scoring_admission_closures where closure_id=target_closure for update;
 select * into strict g from production_control.certification_ingress_generations_v1
 where resource_id=c->>'resource_id' and generation_id=closed.admission_generation_id for update;
 if closed.resource_class<>'CERTIFICATION' or closed.certification_resource_id<>c->>'resource_id'
  or closed.tournament_id is distinct from c->>'current_tournament_id' or closed.status not in('CLOSING','CLOSED')
  or closed.authority_generation_id<>g.authority_epoch_id or closed.closing_admission_revision<>g.revision
  or closed.lease_high_watermark is distinct from g.high_watermark then
  raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_GENERATION_STALE';end if;
 e:=production_control.close_certification_ingress_generation_v1(g.resource_id,g.generation_id,g.revision);
 if e->>'state'<>'CLOSED' or not(e->>'drained')::boolean then
  return jsonb_build_object('ready_to_finalize',false,'active_or_unresolved_leases',
   (e->>'active_count')::bigint+(e->>'unknown_count')::bigint,'certification_ingress',e);end if;
 if not(e->>'fingerprint_matches')::boolean then
  raise exception using errcode='55000',message='CERTIFICATION_INGRESS_CLOSED_EVIDENCE_INVALID';end if;
 revisions:=production_control.current_match_revisions(closed.tournament_id);
 if closed.status='CLOSING' then
  update production_control.scoring_admission_closures set status='CLOSED',closed_at=clock_timestamp(),
   closed_admission_revision=g.revision,final_source_fingerprint=production_control.future_runtime_hash_v2(revisions),
   reconciliation_fingerprint=production_control.future_runtime_hash_v2(jsonb_build_object('resource_id',g.resource_id,
    'generation_id',g.generation_id,'watermark',g.high_watermark,'lease_fingerprint',e->>'fingerprint','match_revisions',revisions)),
   lease_set_fingerprint=e->>'fingerprint',supabase_match_revisions=revisions,google_checkpoints='{}'
  where closure_id=closed.closure_id;
  update production_control.annual_scoring_runtime_authorities_v1 set authority_status='CLOSED',admission_state='CLOSED',
   closed_at=clock_timestamp(),updated_at=clock_timestamp()
  where resource_class='CERTIFICATION' and certification_resource_id=g.resource_id and tournament_id=g.tournament_id;
 end if;
 return jsonb_build_object('ready_to_finalize',true,'active_or_unresolved_leases',0,'certification_ingress',e);
end;$$;


ALTER FUNCTION production_control.drain_certification_annual_predecessor_v1(target_closure uuid) OWNER TO postgres;

--
-- Name: enqueue_annual_calcutta_v1(text, uuid, bigint, text, text, boolean, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.enqueue_annual_calcutta_v1(target text, runtime_generation uuid, activation_revision_value bigint, reason_value text, requested_by_value text, force_value boolean DEFAULT false, request_fingerprint_value text DEFAULT NULL::text, request_payload_hash_value text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  current_value scoring_authority.calcutta_v1_current%rowtype;
  current_result scoring_authority.calcutta_v1_result_revisions%rowtype;
  job_value scoring_authority.calcutta_v1_recalculation_jobs%rowtype;
  source_revision_value jsonb;
  source_fingerprint_value text;
  completed_rounds_value integer[];
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = production_control.canonical_execution_resource_id_v1();
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target
    and value.runtime_generation_id = runtime_generation
    and value.generation_status = 'ACTIVE';
  if target = '2026' or pointer.tournament_id <> target
     or pointer.pointer_revision <> generation.pointer_revision then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_CALCUTTA_RUNTIME_REQUIRED';
  end if;
  select value.* into current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = target for update;
  if not found or current_value.state = 'NOT_CONFIGURED'
     or current_value.auction_revision = 0 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_AUCTION_FACTS_REQUIRED';
  end if;
  source_revision_value :=
    production_control.calcutta_v1_source_revision(target);
  source_fingerprint_value := production_control.calcutta_v1_hash(
    source_revision_value
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'production-calcutta-v1:enqueue:' || target, 202608300075
    )
  );
  select value.* into current_result
  from scoring_authority.calcutta_v1_result_revisions value
  where value.tournament_id = target
    and value.configuration_revision = current_value.configuration_revision
    and value.configuration_fingerprint =
      current_value.configuration_fingerprint
    and value.auction_revision = current_value.auction_revision
    and value.auction_fingerprint = current_value.auction_fingerprint
    and value.source_fingerprint = source_fingerprint_value
    and value.is_current limit 1;
  if found and not force_value then
    return pg_catalog.jsonb_build_object(
      'job_id', null, 'status', 'CURRENT',
      'tournament_id', target,
      'runtime_generation_id', runtime_generation,
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'source_fingerprint', source_fingerprint_value,
      'result_revision', current_result.result_revision
    );
  end if;
  select value.* into job_value
  from scoring_authority.calcutta_v1_recalculation_jobs value
  where value.tournament_id = target
    and value.runtime_generation_id = runtime_generation
    and value.configuration_revision = current_value.configuration_revision
    and value.configuration_fingerprint =
      current_value.configuration_fingerprint
    and value.auction_revision = current_value.auction_revision
    and value.auction_fingerprint = current_value.auction_fingerprint
    and value.activation_revision = activation_revision_value
    and value.source_fingerprint = source_fingerprint_value
    and value.status in ('PENDING', 'RUNNING')
  order by value.requested_at desc, value.job_id desc limit 1;
  if found then
    return pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id, 'status', job_value.status,
      'tournament_id', target,
      'runtime_generation_id', runtime_generation,
      'configuration_revision', job_value.configuration_revision,
      'configuration_fingerprint', job_value.configuration_fingerprint,
      'auction_revision', job_value.auction_revision,
      'auction_fingerprint', job_value.auction_fingerprint,
      'source_fingerprint', job_value.source_fingerprint,
      'result_revision', null
    );
  end if;
  update scoring_authority.calcutta_v1_recalculation_jobs set
    status = 'SUPERSEDED', claimed_by = null, claim_token = null,
    lease_expires_at = null, completed_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target and runtime_generation_id = runtime_generation
    and status in ('PENDING', 'RUNNING');
  insert into scoring_authority.calcutta_v1_recalculation_jobs (
    tournament_id, configuration_revision_id, configuration_revision,
    configuration_fingerprint, auction_revision_id, auction_revision,
    auction_fingerprint, activation_revision, source_revision,
    source_fingerprint, status, reason, requested_by,
    request_fingerprint, request_payload_hash, runtime_generation_id
  ) values (
    target, current_value.configuration_revision_id,
    current_value.configuration_revision,
    current_value.configuration_fingerprint,
    current_value.auction_revision_id, current_value.auction_revision,
    current_value.auction_fingerprint, activation_revision_value,
    source_revision_value, source_fingerprint_value, 'PENDING',
    pg_catalog.left(coalesce(nullif(reason_value, ''),
      'EXPLICIT_RECALCULATION'), 120),
    pg_catalog.left(coalesce(nullif(requested_by_value, ''),
      'production-calcutta-v1'), 160),
    request_fingerprint_value, request_payload_hash_value,
    runtime_generation
  ) returning * into job_value;
  completed_rounds_value :=
    production_control.calcutta_v1_completed_rounds(target);
  update scoring_authority.calcutta_v1_current set
    state = case
      when current_result.result_id is not null
        and current_result.result_state = 'OFFICIAL'
        and 3 = any(completed_rounds_value) then 'OFFICIAL'
      when current_result.result_id is not null
        and coalesce(pg_catalog.array_length(
          completed_rounds_value, 1
        ), 0) > 0 then 'IN_PROGRESS'
      else 'AUCTION_COMPLETE' end,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target;
  return pg_catalog.jsonb_build_object(
    'job_id', job_value.job_id, 'status', job_value.status,
    'tournament_id', target,
    'runtime_generation_id', runtime_generation,
    'configuration_revision', job_value.configuration_revision,
    'configuration_fingerprint', job_value.configuration_fingerprint,
    'auction_revision', job_value.auction_revision,
    'auction_fingerprint', job_value.auction_fingerprint,
    'source_fingerprint', job_value.source_fingerprint,
    'result_revision', null
  );
end;
$$;


ALTER FUNCTION production_control.enqueue_annual_calcutta_v1(target text, runtime_generation uuid, activation_revision_value bigint, reason_value text, requested_by_value text, force_value boolean, request_fingerprint_value text, request_payload_hash_value text) OWNER TO postgres;

--
-- Name: net_skins_v1_recalculation_jobs; Type: TABLE; Schema: scoring_authority; Owner: postgres
--

CREATE TABLE scoring_authority.net_skins_v1_recalculation_jobs (
    job_id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    tournament_id text NOT NULL,
    round_number integer NOT NULL,
    configuration_revision_id uuid NOT NULL,
    configuration_revision bigint NOT NULL,
    configuration_fingerprint text NOT NULL,
    source_revision jsonb NOT NULL,
    source_fingerprint text NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    reason text NOT NULL,
    requested_by text NOT NULL,
    request_fingerprint text,
    request_payload_hash text,
    attempts integer DEFAULT 0 NOT NULL,
    claimed_by text,
    claim_token uuid,
    lease_expires_at timestamp with time zone,
    last_error_code text,
    last_error_safe text,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    runtime_generation_id uuid,
    delivery_available_at timestamp with time zone DEFAULT '-infinity'::timestamp with time zone NOT NULL,
    delivery_cycle bigint DEFAULT 1 NOT NULL,
    delivery_attempts integer DEFAULT 0 NOT NULL,
    delivery_dead_letter_at timestamp with time zone,
    delivery_error_class text,
    CONSTRAINT net_skins_v1_recalculation_jobs_attempts_check CHECK (((attempts >= 0) AND (attempts <= 10))),
    CONSTRAINT net_skins_v1_recalculation_jobs_check CHECK ((((status = 'RUNNING'::text) AND (claimed_by IS NOT NULL) AND (btrim(claimed_by) <> ''::text) AND (claim_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (started_at IS NOT NULL) AND (completed_at IS NULL)) OR ((status <> 'RUNNING'::text) AND (claimed_by IS NULL) AND (claim_token IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT net_skins_v1_recalculation_jobs_check1 CHECK ((((status = ANY (ARRAY['SUCCEEDED'::text, 'FAILED'::text, 'SUPERSEDED'::text])) AND (completed_at IS NOT NULL)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text])) AND (completed_at IS NULL)))),
    CONSTRAINT net_skins_v1_recalculation_jobs_configuration_fingerprint_check CHECK ((configuration_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT net_skins_v1_recalculation_jobs_configuration_revision_check CHECK ((configuration_revision > 0)),
    CONSTRAINT net_skins_v1_recalculation_jobs_delivery_attempts_check CHECK (((delivery_attempts >= 0) AND (delivery_attempts <= 5))),
    CONSTRAINT net_skins_v1_recalculation_jobs_delivery_cycle_check CHECK ((delivery_cycle > 0)),
    CONSTRAINT net_skins_v1_recalculation_jobs_delivery_error_class_check CHECK ((delivery_error_class = ANY (ARRAY['RETRYABLE'::text, 'TERMINAL'::text]))),
    CONSTRAINT net_skins_v1_recalculation_jobs_reason_check CHECK (((btrim(reason) <> ''::text) AND (length(reason) <= 120))),
    CONSTRAINT net_skins_v1_recalculation_jobs_request_fingerprint_check CHECK (((request_fingerprint IS NULL) OR (request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT net_skins_v1_recalculation_jobs_request_payload_hash_check CHECK (((request_payload_hash IS NULL) OR (request_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT net_skins_v1_recalculation_jobs_requested_by_check CHECK (((btrim(requested_by) <> ''::text) AND (length(requested_by) <= 160))),
    CONSTRAINT net_skins_v1_recalculation_jobs_round_number_check CHECK (((round_number >= 1) AND (round_number <= 99))),
    CONSTRAINT net_skins_v1_recalculation_jobs_source_fingerprint_check CHECK ((source_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT net_skins_v1_recalculation_jobs_source_revision_check CHECK ((jsonb_typeof(source_revision) = 'object'::text)),
    CONSTRAINT net_skins_v1_recalculation_jobs_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'SUPERSEDED'::text])))
);


ALTER TABLE scoring_authority.net_skins_v1_recalculation_jobs OWNER TO postgres;

--
-- Name: enqueue_annual_net_skins_v1_round(text, uuid, integer, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.enqueue_annual_net_skins_v1_round(target text, runtime_generation uuid, target_round_number integer, reason_value text, requested_by_value text) RETURNS scoring_authority.net_skins_v1_recalculation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  revision_value scoring_authority.net_skins_v1_configuration_revisions%rowtype;
  job_value scoring_authority.net_skins_v1_recalculation_jobs%rowtype;
  round_value jsonb;
  source_revision_value jsonb;
  source_fingerprint_value text;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = production_control.canonical_execution_resource_id_v1();
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target
    and value.runtime_generation_id = runtime_generation
    and value.generation_status = 'ACTIVE';
  select value.* into strict annual
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = target
    and value.runtime_generation_id = runtime_generation;
  if target = '2026'
     or pointer.tournament_id <> target
     or pointer.pointer_revision <> generation.pointer_revision
     or annual.pointer_revision <> pointer.pointer_revision
     or annual.authority_status <> 'ACTIVE'
     or annual.admission_state <> 'OPEN' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_NET_SKINS_RUNTIME_REQUIRED';
  end if;

  select value.* into current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = target;
  if not found or current_value.state <> 'CONFIGURED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_NET_SKINS_CONFIGURATION_REQUIRED';
  end if;
  select value.* into strict revision_value
  from scoring_authority.net_skins_v1_configuration_revisions value
  where value.configuration_revision_id =
    current_value.configuration_revision_id
    and value.tournament_id = target;
  select value into round_value
  from pg_catalog.jsonb_array_elements(
    revision_value.configuration_manifest->'rounds'
  ) value
  where (value->>'round_number')::integer = target_round_number;
  if not found then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_ROUND_NOT_CONFIGURED';
  end if;

  source_revision_value :=
    production_control.net_skins_v1_round_source_revision(
      target, target_round_number
    );
  source_fingerprint_value :=
    production_control.net_skins_v1_hash(source_revision_value);
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format(
        'production-net-skins-v1:enqueue:%s:%s:R%s',
        target, runtime_generation, target_round_number
      ), 202608300074
    )
  );

  select value.* into job_value
  from scoring_authority.net_skins_v1_recalculation_jobs value
  where value.tournament_id = target
    and value.runtime_generation_id = runtime_generation
    and value.round_number = target_round_number
    and value.configuration_revision = current_value.configuration_revision
    and value.source_fingerprint = source_fingerprint_value
    and value.status in ('PENDING', 'RUNNING')
  order by value.requested_at desc, value.job_id desc
  limit 1;
  if found then return job_value; end if;

  update scoring_authority.net_skins_v1_recalculation_jobs set
    status = 'SUPERSEDED', claimed_by = null, claim_token = null,
    lease_expires_at = null, completed_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target
    and runtime_generation_id = runtime_generation
    and round_number = target_round_number
    and status in ('PENDING', 'RUNNING');

  insert into scoring_authority.net_skins_v1_recalculation_jobs (
    tournament_id, round_number, configuration_revision_id,
    configuration_revision, configuration_fingerprint, source_revision,
    source_fingerprint, status, reason, requested_by,
    runtime_generation_id
  ) values (
    target, target_round_number, revision_value.configuration_revision_id,
    revision_value.configuration_revision,
    round_value->>'configuration_fingerprint', source_revision_value,
    source_fingerprint_value, 'PENDING',
    pg_catalog.left(coalesce(nullif(reason_value, ''),
      'EXPLICIT_RECALCULATION'), 120),
    pg_catalog.left(coalesce(nullif(requested_by_value, ''),
      'production-net-skins-v1'), 160), runtime_generation
  ) returning * into job_value;
  return job_value;
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_NET_SKINS_RUNTIME_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.enqueue_annual_net_skins_v1_round(target text, runtime_generation uuid, target_round_number integer, reason_value text, requested_by_value text) OWNER TO postgres;

--
-- Name: enqueue_production_calcutta_v1(text, text, boolean, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.enqueue_production_calcutta_v1(reason_value text, requested_by_value text, force_value boolean DEFAULT false, request_fingerprint_value text DEFAULT NULL::text, request_payload_hash_value text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  activation_revision_value bigint;
  current_value scoring_authority.calcutta_v1_current%rowtype;
  current_result scoring_authority.calcutta_v1_result_revisions%rowtype;
  job_value scoring_authority.calcutta_v1_recalculation_jobs%rowtype;
  source_revision_value jsonb;
  source_fingerprint_value text;
  completed_rounds_value integer[];
begin
  activation_revision_value:=production_control.canonical_execution_activation_revision_v1();
  select value.* into current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026'
  for update;
  if not found or current_value.state = 'NOT_CONFIGURED'
     or current_value.auction_revision = 0 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_AUCTION_FACTS_REQUIRED';
  end if;

  source_revision_value :=
    production_control.calcutta_v1_source_revision('2026');
  source_fingerprint_value := production_control.calcutta_v1_hash(
    source_revision_value
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'production-calcutta-v1:enqueue:2026', 202608290056
    )
  );

  select value.* into current_result
  from scoring_authority.calcutta_v1_result_revisions value
  where value.tournament_id = '2026'
    and value.configuration_revision = current_value.configuration_revision
    and value.configuration_fingerprint =
      current_value.configuration_fingerprint
    and value.auction_revision = current_value.auction_revision
    and value.auction_fingerprint = current_value.auction_fingerprint
    and (value.source_fingerprint = source_fingerprint_value or production_control.late_r3_result_compatible_v1(value.result_id,source_fingerprint_value))
    and value.is_current
  limit 1;
  if found and not force_value then
    return pg_catalog.jsonb_build_object(
      'job_id', null,
      'status', 'CURRENT',
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'source_fingerprint', source_fingerprint_value,
      'result_revision', current_result.result_revision
    );
  end if;

  select value.* into job_value
  from scoring_authority.calcutta_v1_recalculation_jobs value
  where value.tournament_id = '2026'
    and value.configuration_revision = current_value.configuration_revision
    and value.configuration_fingerprint =
      current_value.configuration_fingerprint
    and value.auction_revision = current_value.auction_revision
    and value.auction_fingerprint = current_value.auction_fingerprint
    and value.activation_revision = activation_revision_value
    and value.source_fingerprint = source_fingerprint_value
    and value.status in ('PENDING', 'RUNNING')
  order by value.requested_at desc, value.job_id desc
  limit 1;
  if found then
    return pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id,
      'status', job_value.status,
      'configuration_revision', job_value.configuration_revision,
      'configuration_fingerprint', job_value.configuration_fingerprint,
      'auction_revision', job_value.auction_revision,
      'auction_fingerprint', job_value.auction_fingerprint,
      'source_fingerprint', job_value.source_fingerprint,
      'result_revision', null
    );
  end if;

  update scoring_authority.calcutta_v1_recalculation_jobs
  set status = 'SUPERSEDED', claimed_by = null, claim_token = null,
      lease_expires_at = null, completed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' and status in ('PENDING', 'RUNNING');
  insert into scoring_authority.calcutta_v1_recalculation_jobs (
    tournament_id, configuration_revision_id, configuration_revision,
    configuration_fingerprint, auction_revision_id, auction_revision,
    auction_fingerprint, activation_revision, source_revision,
    source_fingerprint, status, reason, requested_by,
    request_fingerprint, request_payload_hash
  ) values (
    '2026', current_value.configuration_revision_id,
    current_value.configuration_revision,
    current_value.configuration_fingerprint,
    current_value.auction_revision_id, current_value.auction_revision,
    current_value.auction_fingerprint, activation_revision_value,
    source_revision_value, source_fingerprint_value, 'PENDING',
    pg_catalog.left(coalesce(nullif(reason_value, ''),
      'EXPLICIT_RECALCULATION'), 120),
    pg_catalog.left(coalesce(nullif(requested_by_value, ''),
      'production-calcutta-v1'), 160),
    request_fingerprint_value, request_payload_hash_value
  ) returning * into job_value;

  completed_rounds_value :=
    production_control.calcutta_v1_completed_rounds();
  update scoring_authority.calcutta_v1_current
  set state = case
        when current_result.result_id is not null
          and current_result.result_state = 'OFFICIAL'
          and 3 = any(completed_rounds_value) then 'OFFICIAL'
        when current_result.result_id is not null
          and coalesce(pg_catalog.array_length(
            completed_rounds_value, 1
          ), 0) > 0 then 'IN_PROGRESS'
        else 'AUCTION_COMPLETE' end,
      updated_at = pg_catalog.now()
  where tournament_id = '2026';

  return pg_catalog.jsonb_build_object(
    'job_id', job_value.job_id,
    'status', job_value.status,
    'configuration_revision', job_value.configuration_revision,
    'configuration_fingerprint', job_value.configuration_fingerprint,
    'auction_revision', job_value.auction_revision,
    'auction_fingerprint', job_value.auction_fingerprint,
    'source_fingerprint', job_value.source_fingerprint,
    'result_revision', null
  );
end;
$$;


ALTER FUNCTION production_control.enqueue_production_calcutta_v1(reason_value text, requested_by_value text, force_value boolean, request_fingerprint_value text, request_payload_hash_value text) OWNER TO postgres;

--
-- Name: enqueue_production_net_skins_v1_round(integer, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.enqueue_production_net_skins_v1_round(target_round_number integer, reason_value text, requested_by_value text) RETURNS scoring_authority.net_skins_v1_recalculation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  revision_value scoring_authority.net_skins_v1_configuration_revisions%rowtype;
  job_value scoring_authority.net_skins_v1_recalculation_jobs%rowtype;
  round_value jsonb;
  source_revision_value jsonb;
  source_fingerprint_value text;
begin
  select value.* into current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = '2026';
  if not found or current_value.state <> 'CONFIGURED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_NET_SKINS_CONFIGURATION_REQUIRED';
  end if;
  select value.* into strict revision_value
  from scoring_authority.net_skins_v1_configuration_revisions value
  where value.configuration_revision_id =
    current_value.configuration_revision_id;
  select value into round_value
  from pg_catalog.jsonb_array_elements(
    revision_value.configuration_manifest->'rounds'
  ) value
  where (value->>'round_number')::integer = target_round_number;
  if not found then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_NET_SKINS_ROUND_NOT_CONFIGURED';
  end if;

  source_revision_value :=
    production_control.net_skins_v1_round_source_revision(
      '2026', target_round_number
    );
  source_fingerprint_value :=
    production_control.net_skins_v1_hash(source_revision_value);

  -- Serialize derived work per round. A score correction may legitimately
  -- restore a prior source fingerprint; historical jobs/results therefore
  -- remain immutable history rather than acting as permanent deduplication
  -- keys. Request receipts provide API idempotency, while the active-job
  -- partial index prevents concurrent work for the round.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format(
        'production-net-skins-v1:enqueue:2026:R%s', target_round_number
      ), 202608290055
    )
  );

  select value.* into job_value
  from scoring_authority.net_skins_v1_recalculation_jobs value
  where value.tournament_id = '2026'
    and value.round_number = target_round_number
    and value.configuration_revision = current_value.configuration_revision
    and value.source_fingerprint = source_fingerprint_value
    and value.status in ('PENDING', 'RUNNING')
  order by value.requested_at desc, value.job_id desc
  limit 1;
  if found then
    return job_value;
  end if;

  update scoring_authority.net_skins_v1_recalculation_jobs
  set status = 'SUPERSEDED',
      claimed_by = null,
      claim_token = null,
      lease_expires_at = null,
      completed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where tournament_id = '2026'
    and round_number = target_round_number
    and status in ('PENDING', 'RUNNING');

  insert into scoring_authority.net_skins_v1_recalculation_jobs (
    tournament_id, round_number, configuration_revision_id,
    configuration_revision, configuration_fingerprint, source_revision,
    source_fingerprint, status, reason, requested_by
  ) values (
    '2026', target_round_number,
    revision_value.configuration_revision_id,
    revision_value.configuration_revision,
    round_value->>'configuration_fingerprint', source_revision_value,
    source_fingerprint_value, 'PENDING',
    pg_catalog.left(coalesce(nullif(reason_value, ''),
      'EXPLICIT_RECALCULATION'), 120),
    pg_catalog.left(coalesce(nullif(requested_by_value, ''),
      'production-net-skins-v1'), 160)
  ) returning * into job_value;
  return job_value;
end;
$$;


ALTER FUNCTION production_control.enqueue_production_net_skins_v1_round(target_round_number integer, reason_value text, requested_by_value text) OWNER TO postgres;

--
-- Name: enqueue_score_calcutta_v1(text, text, boolean, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.enqueue_score_calcutta_v1(reason_value text, requested_by_value text, force_value boolean DEFAULT false, request_fingerprint_value text DEFAULT NULL::text, request_payload_hash_value text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  activation_revision_value bigint;
  current_value scoring_authority.calcutta_v1_current%rowtype;
  current_result scoring_authority.calcutta_v1_result_revisions%rowtype;
  job_value scoring_authority.calcutta_v1_recalculation_jobs%rowtype;
  source_revision_value jsonb;
  source_fingerprint_value text;
  completed_rounds_value integer[];
begin
  activation_revision_value:=production_control.canonical_execution_activation_revision_v1();
  select value.* into current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026'
  for update;
  if not found or current_value.state = 'NOT_CONFIGURED'
     or current_value.auction_revision = 0 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_AUCTION_FACTS_REQUIRED';
  end if;

  source_revision_value :=
    production_control.calcutta_v1_source_revision('2026');
  source_fingerprint_value := production_control.calcutta_v1_hash(
    source_revision_value
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'production-calcutta-v1:enqueue:2026', 202608290056
    )
  );

  select value.* into current_result
  from scoring_authority.calcutta_v1_result_revisions value
  where value.tournament_id = '2026'
    and value.configuration_revision = current_value.configuration_revision
    and value.configuration_fingerprint =
      current_value.configuration_fingerprint
    and value.auction_revision = current_value.auction_revision
    and value.auction_fingerprint = current_value.auction_fingerprint
    and value.source_fingerprint = source_fingerprint_value
    and value.is_current
  limit 1;
  if found and not force_value then
    return pg_catalog.jsonb_build_object(
      'job_id', null,
      'status', 'CURRENT',
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'source_fingerprint', source_fingerprint_value,
      'result_revision', current_result.result_revision
    );
  end if;

  select value.* into job_value
  from scoring_authority.calcutta_v1_recalculation_jobs value
  where value.tournament_id = '2026'
    and value.configuration_revision = current_value.configuration_revision
    and value.configuration_fingerprint =
      current_value.configuration_fingerprint
    and value.auction_revision = current_value.auction_revision
    and value.auction_fingerprint = current_value.auction_fingerprint
    and value.activation_revision = activation_revision_value
    and value.source_fingerprint = source_fingerprint_value
    and value.status in ('PENDING', 'RUNNING')
  order by value.requested_at desc, value.job_id desc
  limit 1;
  if found then
    update scoring_authority.calcutta_v1_recalculation_jobs set delivery_score_origin=true where job_id=job_value.job_id and source_fingerprint=source_fingerprint_value;
    return pg_catalog.jsonb_build_object(
      'job_id', job_value.job_id,
      'status', job_value.status,
      'configuration_revision', job_value.configuration_revision,
      'configuration_fingerprint', job_value.configuration_fingerprint,
      'auction_revision', job_value.auction_revision,
      'auction_fingerprint', job_value.auction_fingerprint,
      'source_fingerprint', job_value.source_fingerprint,
      'result_revision', null
    );
  end if;

  update scoring_authority.calcutta_v1_recalculation_jobs
  set status = 'SUPERSEDED', claimed_by = null, claim_token = null,
      lease_expires_at = null, completed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' and status in ('PENDING', 'RUNNING');
  insert into scoring_authority.calcutta_v1_recalculation_jobs (
    tournament_id, configuration_revision_id, configuration_revision,
    configuration_fingerprint, auction_revision_id, auction_revision,
    auction_fingerprint, activation_revision, source_revision,
    source_fingerprint, status, reason, requested_by,
    request_fingerprint, request_payload_hash
  ) values (
    '2026', current_value.configuration_revision_id,
    current_value.configuration_revision,
    current_value.configuration_fingerprint,
    current_value.auction_revision_id, current_value.auction_revision,
    current_value.auction_fingerprint, activation_revision_value,
    source_revision_value, source_fingerprint_value, 'PENDING',
    pg_catalog.left(coalesce(nullif(reason_value, ''),
      'EXPLICIT_RECALCULATION'), 120),
    pg_catalog.left(coalesce(nullif(requested_by_value, ''),
      'production-calcutta-v1'), 160),
    request_fingerprint_value, request_payload_hash_value
  ) returning * into job_value;

  update scoring_authority.calcutta_v1_recalculation_jobs set delivery_score_origin=true where job_id=job_value.job_id and source_fingerprint=source_fingerprint_value;
  completed_rounds_value :=
    production_control.calcutta_v1_completed_rounds();
  update scoring_authority.calcutta_v1_current
  set state = case
        when current_result.result_id is not null
          and current_result.result_state = 'OFFICIAL'
          and 3 = any(completed_rounds_value) then 'OFFICIAL'
        when current_result.result_id is not null
          and coalesce(pg_catalog.array_length(
            completed_rounds_value, 1
          ), 0) > 0 then 'IN_PROGRESS'
        else 'AUCTION_COMPLETE' end,
      updated_at = pg_catalog.now()
  where tournament_id = '2026';

  return pg_catalog.jsonb_build_object(
    'job_id', job_value.job_id,
    'status', job_value.status,
    'configuration_revision', job_value.configuration_revision,
    'configuration_fingerprint', job_value.configuration_fingerprint,
    'auction_revision', job_value.auction_revision,
    'auction_fingerprint', job_value.auction_fingerprint,
    'source_fingerprint', job_value.source_fingerprint,
    'result_revision', null
  );
end;
$$;


ALTER FUNCTION production_control.enqueue_score_calcutta_v1(reason_value text, requested_by_value text, force_value boolean, request_fingerprint_value text, request_payload_hash_value text) OWNER TO postgres;

--
-- Name: enroll_future_participant_identity_link_v1(text, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.enroll_future_participant_identity_link_v1(target_tournament_id text, target_player_id text, target_auth_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  context participant_identity.future_tournament_identity_contexts_v1%rowtype;
  binding participant_identity.future_tournament_participant_bindings_v1%rowtype;
  eligibility record;
  next_revision bigint;
  next_fingerprint text;
  enrolled_count_value integer;
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  if pg_catalog.btrim(coalesce(target_tournament_id, '')) <> target_id
     or target_auth_user_id is null then
    raise exception using errcode = '42501',
      message = 'FUTURE_PARTICIPANT_IDENTITY_ENROLLMENT_SCOPE_INVALID';
  end if;
  select value.* into strict context
  from participant_identity.future_tournament_identity_contexts_v1 value
  where value.tournament_id = target_id
  for update;
  select value.* into strict binding
  from participant_identity.future_tournament_participant_bindings_v1 value
  where value.tournament_id = target_id
    and value.player_id = pg_catalog.btrim(target_player_id)
  for update;
  select value.* into eligibility
  from production_control.future_participant_identity_eligibility_v1(
    target_id
  ) value
  where value.player_id = binding.player_id
    and value.auth_user_id = target_auth_user_id
    and value.contact_approved
    and value.linked_verified;
  if not found then
    raise exception using errcode = '42501',
      message = 'FUTURE_PARTICIPANT_IDENTITY_VERIFIED_LINK_REQUIRED';
  end if;
  if binding.enrollment_state = 'ENROLLED' then
    if binding.bound_link_revision <> eligibility.link_revision then
      raise exception using errcode = '40001',
        message = 'FUTURE_PARTICIPANT_IDENTITY_LINK_REVISION_STALE';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'tournamentId', target_id,
      'playerId', binding.player_id,
      'bindingRevision', context.binding_revision,
      'idempotent', true
    );
  end if;
  if binding.contact_state <> 'APPROVED' then
    raise exception using errcode = '42501',
      message = 'FUTURE_PARTICIPANT_IDENTITY_APPROVED_CONTACT_REQUIRED';
  end if;
  insert into participant_identity.tournament_roles (
    tournament_id, auth_user_id, role, role_active, granted_by
  ) values (
    target_id, target_auth_user_id, 'PARTICIPANT', true,
    'future-runtime-controlled-first-login-v1'
  ) on conflict (tournament_id, auth_user_id, role) do update set
    role_active = true, revoked_at = null, revoked_by = null,
    role_revision = participant_identity.tournament_roles.role_revision + 1,
    updated_at = pg_catalog.clock_timestamp();
  next_revision := context.binding_revision + 1;
  update participant_identity.future_tournament_participant_bindings_v1 set
    enrollment_state = 'ENROLLED',
    bound_link_revision = eligibility.link_revision,
    binding_revision = next_revision,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target_id and player_id = binding.player_id;
  update participant_identity.future_tournament_participant_bindings_v1 set
    binding_revision = next_revision,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target_id and player_id <> binding.player_id;
  next_fingerprint := production_control
    .future_participant_identity_binding_fingerprint_v1(target_id);
  select pg_catalog.count(*)::integer into enrolled_count_value
  from participant_identity.future_tournament_participant_bindings_v1 value
  where value.tournament_id = target_id
    and value.enrollment_state = 'ENROLLED';
  update participant_identity.future_tournament_identity_contexts_v1 set
    binding_revision = next_revision,
    binding_fingerprint = next_fingerprint,
    enrolled_count = enrolled_count_value,
    not_enrolled_count = roster_count - enrolled_count_value,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target_id;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id,
    actor_name, configuration_revision, safe_metadata
  ) values (
    'FUTURE_TOURNAMENT_PARTICIPANT_ENROLLED', target_id,
    target_auth_user_id, binding.player_id,
    'future-runtime-controlled-first-login-v1', next_revision,
    pg_catalog.jsonb_build_object(
      'rawIdentifierStoredInAudit', false,
      'authUserCreatedByDatabase', false,
      'bindingRevision', next_revision
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'tournamentId', target_id,
    'playerId', binding.player_id,
    'bindingRevision', next_revision,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION production_control.enroll_future_participant_identity_link_v1(target_tournament_id text, target_player_id text, target_auth_user_id uuid) OWNER TO postgres;

--
-- Name: ensure_annual_side_game_runtime_v1(text, uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.ensure_annual_side_game_runtime_v1(target_tournament_id text, expected_runtime_generation_id uuid, expected_authority_generation_id uuid, expected_admission_generation_id uuid, allow_binding boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  scope production_control.resource_scope%rowtype;
  resource_context jsonb;
  expected_project_ref text;
  expected_project_url text;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  writer production_control.future_google_writer_targets_v2%rowtype;
  retained
    production_control.annual_side_game_runtime_certifications_v1%rowtype;
  implementation_manifest_value jsonb;
  resource_manifest_value jsonb;
  implementation_fingerprint_value text;
  resource_fingerprint_value text;
  certification_fingerprint_value text;
begin
  if target_tournament_id is null or target_tournament_id = '2026' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_RUNTIME_REQUIRED';
  end if;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target_tournament_id
    and value.runtime_generation_id = expected_runtime_generation_id;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target_tournament_id;
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target_tournament_id;
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION') then
    resource_context:=production_control.annual_resource_context_v2();
    if resource_context->>'resource_class' is distinct from 'CERTIFICATION'
      or resource.source_workbook_id is distinct from resource_context->>'provenance_id' then
      raise exception using errcode='55000',message='PRODUCTION_ANNUAL_SIDE_GAME_RUNTIME_REQUIRED';end if;
    expected_project_ref:=resource_context->>'project_ref';
    expected_project_url:=resource_context->>'project_url';
  else
    select value.* into strict scope
    from production_control.resource_scope value
    where value.scope_key = 'BAGGER_INV_PRODUCTION';
    expected_project_ref:=scope.project_ref;
    expected_project_url:=scope.project_url;
  end if;
  select value.* into strict promotion
  from production_control.future_runtime_promotions_v2 value
  where value.tournament_id = target_tournament_id;
  -- Google runtime retired: external delivery is not canonical authority.

  implementation_manifest_value :=
    production_control.annual_side_game_implementation_manifest_v1();
  implementation_fingerprint_value :=
    production_control.future_runtime_hash_v2(
      implementation_manifest_value
    );
  resource_manifest_value := pg_catalog.jsonb_build_object(
    'contractVersion', 'production-annual-side-game-resource-v2-google-retired',
    'environment', case when resource_context is null then 'PRODUCTION' else 'CERTIFICATION' end,
    'projectRef', resource.project_ref,
    'projectUrl', resource.project_url,
    'sourceWorkbookId', resource.source_workbook_id,
    'tournamentId', target_tournament_id,
    'tournamentYear', catalog.tournament_year,
    'resourceRevision', resource.resource_revision,
    'promotionRevision', promotion.promotion_revision,
    'promotionFingerprint', promotion.promoted_manifest_fingerprint,
    'runtimeGenerationId', generation.runtime_generation_id,
    'pointerRevision', generation.pointer_revision,
    'authorityGenerationId', generation.authority_generation_id,
    'admissionGenerationId', generation.admission_generation_id,
    'externalGoogleDelivery', 'RETIRED'
  ) || case when resource_context is null then '{}'::jsonb else pg_catalog.jsonb_build_object(
    'resourceId',resource_context->>'resource_id','installationId',resource_context->>'installation_id',
    'schemaDigest',resource_context->>'schema_digest','manifestDigest',resource_context->>'manifest_digest') end;
  resource_fingerprint_value :=
    production_control.future_runtime_hash_v2(resource_manifest_value);
  certification_fingerprint_value :=
    production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'contractVersion', 'production-annual-side-game-runtime-v1',
        'resourceFingerprint', resource_fingerprint_value,
        'implementationFingerprint', implementation_fingerprint_value
      )
    );

  if generation.authority_generation_id is distinct from
       expected_authority_generation_id
     or generation.admission_generation_id is distinct from
       expected_admission_generation_id
     or resource.project_ref is distinct from expected_project_ref
     or resource.project_url is distinct from expected_project_url
     or resource.resource_status <> 'CURRENT_RESOURCE_BOUND'
     or resource.source_workbook_id is null

     or promotion.runtime_status not in ('READY', 'ACTIVE')
     or generation.generation_status not in ('PREPARED', 'ACTIVE')
     or catalog.lifecycle not in ('READY_FOR_ACTIVATION', 'ACTIVE') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_RUNTIME_REQUIRED';
  end if;

  select value.* into retained
  from production_control.annual_side_game_runtime_certifications_v1 value
  where value.runtime_generation_id = generation.runtime_generation_id
    and value.admission_generation_id = generation.admission_generation_id;
  if retained.runtime_generation_id is null then
    if not allow_binding
       or generation.generation_status not in ('PREPARED', 'ACTIVE') then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ANNUAL_SIDE_GAME_CERTIFICATION_REQUIRED';
    end if;
    insert into production_control.annual_side_game_runtime_certifications_v1 (
      runtime_generation_id, contract_version, tournament_id,
      pointer_revision, authority_generation_id, admission_generation_id,
      project_ref, project_url, source_workbook_id, resource_revision,
      resource_fingerprint, implementation_manifest,
      implementation_fingerprint, certification_fingerprint
    ) values (
      generation.runtime_generation_id,
      'production-annual-side-game-runtime-v1', target_tournament_id,
      generation.pointer_revision, generation.authority_generation_id,
      generation.admission_generation_id, resource.project_ref,
      resource.project_url, resource.source_workbook_id,
      resource.resource_revision, resource_fingerprint_value,
      implementation_manifest_value, implementation_fingerprint_value,
      certification_fingerprint_value
    ) returning * into retained;
  end if;

  if retained.contract_version <> 'production-annual-side-game-runtime-v1'
     or retained.tournament_id <> target_tournament_id
     or retained.pointer_revision <> generation.pointer_revision
     or retained.authority_generation_id is distinct from
       generation.authority_generation_id
     or retained.admission_generation_id is distinct from
       generation.admission_generation_id
     or retained.project_ref is distinct from resource.project_ref
     or retained.project_url is distinct from resource.project_url
     or retained.source_workbook_id is distinct from
       resource.source_workbook_id
     or retained.resource_revision <> resource.resource_revision
     or retained.resource_fingerprint is distinct from
       resource_fingerprint_value
     or retained.implementation_manifest is distinct from
       implementation_manifest_value
     or retained.implementation_fingerprint is distinct from
       implementation_fingerprint_value
     or retained.certification_fingerprint is distinct from
       certification_fingerprint_value then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_CERTIFICATION_REQUIRED';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'contractVersion', retained.contract_version,
    'tournamentId', retained.tournament_id,
    'runtimeGenerationId', retained.runtime_generation_id,
    'resourceFingerprint', retained.resource_fingerprint,
    'implementationFingerprint', retained.implementation_fingerprint,
    'certificationFingerprint', retained.certification_fingerprint
  );
exception
  when no_data_found or invalid_text_representation
    or numeric_value_out_of_range then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_RUNTIME_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.ensure_annual_side_game_runtime_v1(target_tournament_id text, expected_runtime_generation_id uuid, expected_authority_generation_id uuid, expected_admission_generation_id uuid, allow_binding boolean) OWNER TO postgres;

--
-- Name: execute_certification_operation_core_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.execute_certification_operation_core_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare phase text; context jsonb; result jsonb;
begin
 phase:=production_control.certification_operation_phase_v1(input->>'operation_id',true);
 context:=production_control.push_certification_context_v1(input,phase,true);
 result:=production_control.dispatch_certification_operation_v1(input,context,true);
 if coalesce((result->>'ok')::boolean,false) and not coalesce((result->>'idempotent')::boolean,false)
   and not coalesce((result->>'semantic_noop')::boolean,false) then
  insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
  values('CERTIFICATION_CANONICAL_OPERATION','CERTIFICATION',context->>'tournament_id',coalesce(input#>>'{authorization,player_id}',input#>>'{payload,worker_id}','certification-derived-worker'),
   production_control.cutover_payload_hash(input->'payload'),'SUCCEEDED',jsonb_build_object(
    'runtime','CERTIFICATION','resource_id',context->>'resource_id','installation_id',context->>'installation_id',
    'binding_id',context->>'binding_id','context_token',context->>'context_token',
    'operation_id',input->>'operation_id','operation_request_id',input->>'operation_request_id',
    'actor_auth_user_id',input#>>'{authorization,auth_user_id}','activation_revision',context->'activation_revision',
    'admission_revision',context->'admission_revision','release_commit',context->>'release_commit',
    'receipt',result));
 end if;
 perform production_control.pop_certification_context_v1();
 return result;
end;
$$;


ALTER FUNCTION production_control.execute_certification_operation_core_v1(input jsonb) OWNER TO postgres;

