--

CREATE FUNCTION production_control.frozen_2026_intelligence_claim_is_current_v1(target_tournament text, target_engine text, target_claim timestamp with time zone) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
