--
-- Name: full_net_match_v1(text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.full_net_match_v1(target text, match_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  m scoring_authority.matches%rowtype;
  s scoring_authority.scoring_snapshots%rowtype;
  r scoring_authority.handicap_revisions%rowtype;
  authority_ok boolean; side integer; p record; h record;
  ids jsonb; partners jsonb; entries jsonb:='[]'; cells jsonb;
  ch numeric; allocation integer; applied integer; gross numeric;
  complete boolean; entity_id text; slot integer;
begin
  select * into m from scoring_authority.matches where tournament_id=target and match_id=match_key;
  if not found then raise exception 'FULL_NET_MATCH_BINDING_REQUIRED'; end if;
  select * into s from scoring_authority.scoring_snapshots where snapshot_id=m.scoring_snapshot_id
    and tournament_id=target and match_id=m.match_id;
  select * into r from scoring_authority.handicap_revisions where revision_id=s.handicap_revision_id
    and tournament_id=target;
  authority_ok:=s.snapshot_id is not null and s.canonical_hash is not null
    and r.approved_at is not null and r.status in('APPROVED','SUPERSEDED')
    and s.slope is not null and s.rating is not null and s.par is not null
    and exists(select 1 from scoring_authority.tournament_setup_match_details_v1 d
      where d.tournament_id=target and d.match_id=m.match_id and d.prepared_setup_revision is not null)
    and (select count(*) from scoring_authority.match_participants where match_id=m.match_id)=case m.format when 'SI' then 2 else 4 end
    and not exists(select 1 from scoring_authority.match_participants bound
      left join scoring_authority.handicap_revision_entries e on e.revision_id=s.handicap_revision_id
        and e.tournament_id=target and e.player_id=bound.player_id
      where bound.match_id=m.match_id and (bound.handicap_revision_id is distinct from s.handicap_revision_id
        or e.player_id is null or bound.course_handicap is null
        or bound.course_handicap is distinct from e.tournament_handicap*(s.slope::numeric/113::numeric)+(s.rating-s.par::numeric)
        or not exists(select 1 from jsonb_array_elements(coalesce(s.participant_configuration->('team_'||bound.team_side),'[]')) frozen
          where frozen->>'id'=bound.player_id and (frozen->>'slot')::integer=bound.player_slot
            and frozen->>'handicap_revision_id'=s.handicap_revision_id::text
            and (frozen->>'course_handicap')::numeric=bound.course_handicap)))
    and (select count(*)=18 and count(distinct stroke_index)=18
      and min(stroke_index)=1 and max(stroke_index)=18 and min(hole_number)=1 and max(hole_number)=18
      from scoring_authority.match_holes where match_id=m.match_id);
  authority_ok:=coalesce(authority_ok,false);
  for side in 1..2 loop
    for p in select mp.* from scoring_authority.match_participants mp where mp.match_id=m.match_id
      and mp.team_side=side and (m.format<>'SC' or mp.player_slot=1) order by mp.player_slot loop
      select jsonb_agg(mp.player_id order by mp.player_slot),jsonb_agg(jsonb_build_object(
        'playerId',mp.player_id,'slot',mp.player_slot,'tournamentHandicap',e.tournament_handicap::text,
        'courseHandicap',mp.course_handicap::text) order by mp.player_slot)
      into ids,partners from scoring_authority.match_participants mp
      left join scoring_authority.handicap_revision_entries e on e.revision_id=s.handicap_revision_id
        and e.tournament_id=target and e.player_id=mp.player_id
      where mp.match_id=m.match_id and mp.team_side=side and (m.format='SC' or mp.player_id=p.player_id);
      if m.format='SC' then
        -- Exact established 058 boundary: full numeric partner CH, sum first,
        -- one PostgreSQL numeric half-away-from-zero round. NO opponent offset.
        select round(min(course_handicap)*0.35+max(course_handicap)*0.15,0) into ch
          from scoring_authority.match_participants where match_id=m.match_id and team_side=side;
        slot:=0; entity_id:=m.match_id||':S'||side;
      else ch:=p.course_handicap; slot:=p.player_slot-1; entity_id:=p.player_id;
      end if;
      allocation:=case when not authority_ok then null when m.format='SC' then ch::integer
        else round(ch,0)::integer end;
      cells:='[]';
      for h in select mh.hole_number,mh.par,mh.stroke_index,hs.team_1_gross_scores,hs.team_2_gross_scores
        from scoring_authority.match_holes mh left join scoring_authority.hole_scores hs
          on hs.match_id=mh.match_id and hs.hole_number=mh.hole_number
        where mh.match_id=m.match_id order by mh.hole_number loop
        gross:=nullif((case side when 1 then h.team_1_gross_scores else h.team_2_gross_scores end)->>slot,'')::numeric;
        -- Signed 18-hole cycles: positive SI 1 upward, negative SI 18 downward.
        applied:=case when allocation is null then null else sign(allocation)::integer*(abs(allocation)/18+
          case when (allocation>0 and h.stroke_index<=abs(allocation)%18)
            or (allocation<0 and h.stroke_index>18-abs(allocation)%18) then 1 else 0 end) end;
        cells:=cells||jsonb_build_array(jsonb_build_object('hole',h.hole_number,'par',h.par,
          'strokeIndex',h.stroke_index,'gross',gross,'fullCourseHandicapStrokes',applied,'fullNet',gross-applied));
      end loop;
      complete:=authority_ok and jsonb_array_length(cells)=18 and not exists(
        select 1 from jsonb_array_elements(cells) c where c->>'gross' is null or c->>'fullNet' is null);
      entries:=entries||jsonb_build_array(jsonb_build_object('entityId',entity_id,'playerIds',ids,
        'teamSide',side,'scope',case m.format when 'SC' then 'TEAM' else 'PLAYER' end,
        'partners',partners,'courseHandicap',case when authority_ok and m.format<>'SC' then ch::text end,
        'teamCourseHandicap',case when authority_ok and m.format='SC' then ch::text end,
        'fullCourseHandicapStrokes',allocation,'holes',cells,'complete',complete,
        'totalGross',case when complete then (select sum((c->>'gross')::numeric) from jsonb_array_elements(cells)c) end,
        'totalFullNet',case when complete then (select sum((c->>'fullNet')::numeric) from jsonb_array_elements(cells)c) end));
    end loop;
  end loop;
  return jsonb_build_object('policy','production-full-course-handicap-v1','tournamentId',target,
    'matchId',m.match_id,'roundNumber',m.round_number,'format',m.format,'authorityAvailable',authority_ok,
    'lifecycle',case when m.status='UPCOMING' then 'UNSTARTED_REFRESHABLE' else 'FROZEN' end,
    'official',m.status='FINAL' and m.scorecard_complete,'snapshotId',s.snapshot_id,'snapshotHash',s.canonical_hash,
    'handicapRevisionId',s.handicap_revision_id,'handicapRevisionFingerprint',r.canonical_fingerprint,
    'courseId',s.course_id,'tee',s.tee,'slope',s.slope,'rating',s.rating,'par',s.par,'entries',entries);
end;
$$;


ALTER FUNCTION production_control.full_net_match_v1(target text, match_key text) OWNER TO postgres;

--
-- Name: full_net_skins_manifest_v2(text, integer[], jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.full_net_skins_manifest_v2(target text, selected_rounds integer[], entry_revisions jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare rr record; opt jsonb; mp record; ids jsonb; side integer; entries jsonb; rounds jsonb:='[]'; item jsonb;
  seen text[]:='{}'; key text; entry_id text; expected integer; buy_in numeric;
  registry jsonb; saved_round jsonb; opt_ins jsonb:='[]';
begin
  if jsonb_typeof(entry_revisions) is distinct from 'object' or selected_rounds is null
    or cardinality(selected_rounds)=0 or cardinality(selected_rounds)<>(select count(distinct v) from unnest(selected_rounds)v)
    or (select count(*) from scoring_authority.rounds where tournament_id=target and round_number=any(selected_rounds)
      and format in('BB','SC','SI'))<>cardinality(selected_rounds)
  then raise exception 'FULL_NET_EXPLICIT_OPT_INS_REQUIRED'; end if;
  registry:=production_control.net_skins_entries_projection_v1(target);
  if (select count(*) from jsonb_object_keys(entry_revisions))<>cardinality(selected_rounds)
    then raise exception 'FULL_NET_ENTRY_REVISION_REQUIRED'; end if;
  for saved_round in select value from jsonb_array_elements(registry->'rounds')
    where (value->>'roundNumber')::integer=any(selected_rounds) loop
    if saved_round->>'configured' is distinct from 'true' or saved_round->>'state'<>'ENTRIES_SAVED'
      or (saved_round->>'enteredCount')::integer=0
      or entry_revisions->(saved_round->>'roundNumber') is distinct from saved_round->'revision'
      then raise exception 'FULL_NET_ENTRY_REVISION_STALE_OR_UNAVAILABLE'; end if;
    for item in select value from jsonb_array_elements(saved_round->'entrants') where value->>'entered'='true' loop
      opt_ins:=opt_ins||jsonb_build_array(jsonb_build_object('round_number',saved_round->'roundNumber',
        'match_id',item->>'matchId','player_ids',item->'playerIds','entry_revision',saved_round->'revision',
        'entry_key',item->>'key','binding_fingerprint',item->>'bindingFingerprint'));
    end loop;
  end loop;
  if exists(select 1 from jsonb_array_elements(opt_ins) o where (o->>'round_number')::integer is null
    or not (o->>'round_number')::integer=any(selected_rounds)) then raise exception 'FULL_NET_OPT_IN_ROUND_INVALID'; end if;
  for rr in select * from scoring_authority.rounds where tournament_id=target and round_number=any(selected_rounds) order by round_number loop
    entries:='[]'; buy_in:=case rr.format when 'SC' then 50 else 25 end;
    for opt in select value from jsonb_array_elements(opt_ins) order by value->>'match_id',value->'player_ids' loop
      if (opt->>'round_number')::integer<>rr.round_number then continue; end if;
      expected:=case rr.format when 'SC' then 2 else 1 end;
      if jsonb_typeof(opt->'player_ids') is distinct from 'array' or jsonb_array_length(opt->'player_ids')<>expected
        or not exists(select 1 from scoring_authority.matches where tournament_id=target and round_number=rr.round_number
          and match_id=opt->>'match_id' and format=rr.format) then raise exception 'FULL_NET_OPT_IN_BINDING_INVALID'; end if;
      select min(p.team_side) into side from scoring_authority.match_participants p where p.match_id=opt->>'match_id'
        and p.player_id in(select jsonb_array_elements_text(opt->'player_ids'));
      select jsonb_agg(p.player_id order by p.player_slot) into ids from scoring_authority.match_participants p
        join scoring_authority.tournament_players tp on tp.tournament_id=target and tp.player_id=p.player_id
        where p.match_id=opt->>'match_id' and p.team_side=side and tp.participation_status='ACTIVE'
          and (rr.format='SC' or p.player_id=opt#>>'{player_ids,0}');
      if ids is null or jsonb_array_length(ids)<>expected or not ids @> (opt->'player_ids')
        or not (opt->'player_ids') @> ids then raise exception 'FULL_NET_OPT_IN_BINDING_INVALID'; end if;
      for key in select rr.round_number||':'||value from jsonb_array_elements_text(ids) loop
        if key=any(seen) then raise exception 'FULL_NET_DUPLICATE_OPT_IN'; end if; seen:=array_append(seen,key);
      end loop;
      entry_id:=target||':R'||rr.round_number||case rr.format when 'SC' then ':PAIRING:'|| (opt->>'match_id')||':S'||side else ':PLAYER:'||(ids->>0) end;
      entries:=entries||jsonb_build_array(jsonb_build_object('entry_id',entry_id,'entry_type',case rr.format when 'SC' then 'PAIRING' else 'INDIVIDUAL' end,
        'match_id',opt->>'match_id','match_number',coalesce((select nullif(display_match_number,'') from scoring_authority.game_center_presentations
          where tournament_id=target and match_id=opt->>'match_id'),opt->>'match_id'),
        'player_ids',ids,'player_id_1',ids->>0,'player_id_2',ids->>1,'team_handicap',null,
        'individual_stroke_allocation',null,'buy_in',buy_in,'eligible',true,'eligibility_authority','DIRECTOR_EXPLICIT_ROUND_ENTRY_V1',
        'entry_revision',opt->'entry_revision','entry_key',opt->>'entry_key','binding_fingerprint',opt->>'binding_fingerprint'));
    end loop;
    item:=jsonb_build_object('round_id',target||':R'||rr.round_number,'round_number',rr.round_number,'round_name',rr.name,'format',rr.format,
      'entry_type',case rr.format when 'SC' then 'PAIRING' else 'INDIVIDUAL' end,'buy_in_per_entry',buy_in,
      'expected_pot',jsonb_array_length(entries)*buy_in,'eligible_holes',(select jsonb_agg(v) from generate_series(1,18)v),
      'net_handicap_basis','production-full-course-handicap-v1','eligibility_authority','DIRECTOR_EXPLICIT_ROUND_ENTRY_V1','entry_revision',entry_revisions->rr.round_number::text,
      'completion_rule','ALL_ELIGIBLE_ENTRIES_18_HOLES_AND_REFERENCED_MATCHES_OFFICIAL','payout_rounding','NONE',
      'tie_rule','NO_SKIN_NO_CARRY','carry_rule','NO_CARRY','publication_policy','OFFICIAL_ONLY',
      'match_ids',(select coalesce(jsonb_agg(v order by v),'[]') from(select distinct e->>'match_id' v from jsonb_array_elements(entries)e)s),
      'entries',entries);
    rounds:=rounds||jsonb_build_array(item||jsonb_build_object('configuration_fingerprint',production_control.net_skins_v1_hash(item)));
  end loop;
  return jsonb_build_object('contract_version','production-net-skins-v1','tournament_id',target,
    'calculation_policy','production-full-course-handicap-v1','entry_revisions',entry_revisions,'publication_policy','OFFICIAL_ONLY','rounds',rounds);
end;
$$;


ALTER FUNCTION production_control.full_net_skins_manifest_v2(target text, selected_rounds integer[], entry_revisions jsonb) OWNER TO postgres;

--
-- Name: full_net_tournament_v1(text, integer[]); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.full_net_tournament_v1(target text, selected_rounds integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select jsonb_build_object('policy','production-full-course-handicap-v1','tournamentId',target,'matches',
    coalesce(jsonb_agg(production_control.full_net_match_v1(target,m.match_id)
      order by m.round_number,m.match_id),'[]')) from scoring_authority.matches m
    where m.tournament_id=target and m.format in('BB','SC','SI')
      and (selected_rounds is null or m.round_number=any(selected_rounds));
$$;


ALTER FUNCTION production_control.full_net_tournament_v1(target text, selected_rounds integer[]) OWNER TO postgres;

--
-- Name: future_global_owner_eligibility_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_global_owner_eligibility_v1() RETURNS TABLE(player_id text, auth_user_id uuid, capability_revision bigint, adopted_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select owner_value.player_id, owner_value.auth_user_id,
    owner_value.capability_revision, owner_value.adopted_at
  from production_control.tournament_owner_capabilities_v1 owner_value
  join participant_identity.user_player_links link
    on link.player_id = owner_value.player_id
   and link.auth_user_id = owner_value.auth_user_id
   and link.status = 'ACTIVE'
   and link.revoked_at is null
  join participant_identity.participant_auth_identifiers identifier
    on identifier.player_id = link.player_id
   and identifier.auth_user_id = link.auth_user_id
   and identifier.identifier_type = 'EMAIL'
   and identifier.status = 'VERIFIED'
   and identifier.revoked_at is null
   and link.email_identity_hash = encode(extensions.digest(
     identifier.normalized_value_private::text, 'sha256'), 'hex')
  join auth.users auth_user
    on auth_user.id = link.auth_user_id
   and auth_user.email_confirmed_at is not null
   and pg_catalog.lower(pg_catalog.btrim(coalesce(auth_user.email, '')))
     = identifier.normalized_value_private
  where owner_value.tournament_id = '2026'
    and owner_value.status = 'ACTIVE'
    and owner_value.revoked_at is null;
$$;


ALTER FUNCTION production_control.future_global_owner_eligibility_v1() OWNER TO postgres;

--
-- Name: future_google_match_manifest_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_google_match_manifest_v1(target_match text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  match_value scoring_authority.matches%rowtype;
  detail scoring_authority.tournament_setup_match_details_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  template_live text;
  template_archive text;
  team_1_player_1 text;
  team_1_player_2 text;
  team_2_player_1 text;
  team_2_player_2 text;
  logical_fields jsonb;
begin
  select value.* into strict match_value
  from scoring_authority.matches value where value.match_id = target_match;
  select value.* into strict detail
  from scoring_authority.tournament_setup_match_details_v1 value
  where value.match_id = target_match;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = match_value.tournament_id;
  select pg_catalog.min(value.match_id) into template_live
  from scoring_authority.matches value
  where value.tournament_id = '2026' and value.format = match_value.format
    and exists (
      select 1 from scoring_authority.google_match_checkpoints checkpoint
      where checkpoint.match_id = value.match_id
    );
  select pg_catalog.min(value.match_id) into template_archive
  from scoring_authority.matches value
  where value.tournament_id = '2026' and value.format = match_value.format
    and value.status = 'FINAL'
    and exists (
      select 1 from scoring_authority.finalized_scorecard_snapshots final
      where final.match_id = value.match_id and final.state = 'CURRENT'
    );
  template_archive := coalesce(template_archive, template_live);
  if template_live is null or template_archive is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_TEMPLATE_REQUIRED';
  end if;
  select
    pg_catalog.max(value.player_id) filter (
      where value.team_side = 1 and value.player_slot = 1),
    pg_catalog.max(value.player_id) filter (
      where value.team_side = 1 and value.player_slot = 2),
    pg_catalog.max(value.player_id) filter (
      where value.team_side = 2 and value.player_slot = 1),
    pg_catalog.max(value.player_id) filter (
      where value.team_side = 2 and value.player_slot = 2)
  into team_1_player_1, team_1_player_2,
    team_2_player_1, team_2_player_2
  from scoring_authority.match_participants value
  where value.match_id = target_match;
  logical_fields := pg_catalog.jsonb_build_object(
    'Year', catalog.tournament_year,
    'Round', match_value.round_number,
    'Format', match_value.format,
    'Match', detail.match_number,
    'Course ID', detail.course_id,
    'Tee Time', coalesce(detail.tee_time::text, ''),
    'Starting Hole', detail.starting_hole,
    'Team 1 Player 1', coalesce(team_1_player_1, ''),
    'Team 1 Player 2', coalesce(team_1_player_2, ''),
    'Team 2 Player 1', coalesce(team_2_player_1, ''),
    'Team 2 Player 2', coalesce(team_2_player_2, '')
  );
  return pg_catalog.jsonb_build_object(
    'contractVersion', 'production-future-google-match-provisioning-v1',
    'tournamentId', match_value.tournament_id,
    'tournamentYear', catalog.tournament_year,
    'matchId', target_match,
    'templateLiveMatchId', template_live,
    'templateArchiveMatchId', template_archive,
    'liveMatch', logical_fields,
    'archiveMatch', logical_fields
  );
end;
$$;


ALTER FUNCTION production_control.future_google_match_manifest_v1(target_match text) OWNER TO postgres;

--
-- Name: future_google_match_manifest_v2(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_google_match_manifest_v2(target_match text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  job production_control.future_match_google_compatibility_jobs_v1%rowtype;
  manifest jsonb;
begin
  select value.* into strict job
  from production_control.future_match_google_compatibility_jobs_v1 value
  where value.match_id = target_match;
  if not job.writer_installed or job.writer_generation_id is null
     or job.destination_workbook_id is null
     or job.target_contract_fingerprint is null
     or job.structural_fingerprint is null
     or job.structural_runtime_revision is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_WRITER_BINDING_REQUIRED';
  end if;
  manifest := production_control.future_google_match_manifest_v1(target_match);
  return manifest || pg_catalog.jsonb_build_object(
    'contractVersion', 'production-future-google-match-provisioning-v2',
    'writerGenerationId', job.writer_generation_id,
    'destinationWorkbookId', job.destination_workbook_id,
    'targetContractFingerprint', job.target_contract_fingerprint,
    'structuralFingerprint', job.structural_fingerprint,
    'runtimeRevision', job.structural_runtime_revision
  );
end;
$$;


ALTER FUNCTION production_control.future_google_match_manifest_v2(target_match text) OWNER TO postgres;

--
-- Name: future_google_writer_generation_id_v2(text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_google_writer_generation_id_v2(destination_workbook text, implementation_fingerprint text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
  select (
    pg_catalog.substr(value.fingerprint, 1, 8) || '-' ||
    pg_catalog.substr(value.fingerprint, 9, 4) || '-5' ||
    pg_catalog.substr(value.fingerprint, 14, 3) || '-8' ||
    pg_catalog.substr(value.fingerprint, 18, 3) || '-' ||
    pg_catalog.substr(value.fingerprint, 21, 12)
  )::uuid
  from (
    select production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'contractVersion', 'production-future-google-writer-generation-v2',
        'destinationWorkbookId', destination_workbook,
        'implementationFingerprint', implementation_fingerprint
      )
    ) fingerprint
  ) value
$$;


ALTER FUNCTION production_control.future_google_writer_generation_id_v2(destination_workbook text, implementation_fingerprint text) OWNER TO postgres;

--
-- Name: future_google_writer_implementation_fingerprint_v2(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_google_writer_implementation_fingerprint_v2() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select production_control.future_runtime_hash_v2(
    production_control.future_google_writer_implementation_manifest_v2()
  )
$$;


ALTER FUNCTION production_control.future_google_writer_implementation_fingerprint_v2() OWNER TO postgres;

--
-- Name: future_google_writer_implementation_manifest_v2(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_google_writer_implementation_manifest_v2() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  signatures constant text[] := array[
    'production_control.future_runtime_hash_v2(jsonb)',
    'production_control.sync_future_google_writer_job_v2(text,text)',
    'production_control.sync_future_google_writer_binding_v2()',
    'production_control.reject_future_runtime_immutable_v2()',
    'production_control.future_google_match_manifest_v1(text)',
    'production_control.future_google_match_manifest_v2(text)',
    'production_control.assert_future_google_writer_pre_implementation_cert_v2(jsonb,boolean)',
    'production_control.future_google_writer_implementation_manifest_v2()',
    'production_control.future_google_writer_implementation_fingerprint_v2()',
    'production_control.future_google_writer_generation_id_v2(text,text)',
    'production_control.future_google_writer_resource_fingerprint_v1(text)',
    'production_control.future_google_writer_target_fingerprint_v1(text)',
    'production_control.assert_future_google_writer_live_implementation_v2(text)',
    'production_control.assert_future_google_writer_v2(jsonb,boolean)',
    'public.resolve_production_future_match_google_compatibility_v2(jsonb)',
    'public.claim_production_future_match_google_compatibility_v2(jsonb)',
    'public.complete_production_future_match_google_compatibility_v2(jsonb)',
    'public.fail_production_future_match_google_compatibility_v2(jsonb)',
    'public.adopt_production_future_google_destination_v1(jsonb)',
    'public.certify_production_future_google_writer_target_v1(jsonb)'
  ];
  trigger_names constant text[] := array[
    'sync_future_google_writer_binding_v2',
    'future_google_writer_generation_immutable_v2',
    'future_google_writer_target_immutable_v2',
    'production_future_google_writer_receipt_immutable_v1',
    'production_future_google_writer_audit_immutable_v1'
  ];
  relation_names constant text[] := array[
    'production_control.future_runtime_match_bindings_v2',
    'production_control.future_match_google_compatibility_jobs_v1',
    'production_control.future_google_writer_generations_v2',
    'production_control.future_google_writer_targets_v2',
    'production_control.future_google_writer_certification_receipts_v1',
    'production_control.future_google_writer_certification_audit_v1'
  ];
  function_manifest jsonb;
  trigger_manifest jsonb;
  relation_manifest jsonb;
  authorship_manifest jsonb;
begin
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'signature', requested.signature,
    'source', procedure_value.prosrc,
    'securityDefiner', procedure_value.prosecdef,
    'volatility', procedure_value.provolatile::text,
    'configuration', coalesce(
      pg_catalog.to_jsonb(procedure_value.proconfig), '[]'::jsonb
    ),
    'acl', coalesce(
      pg_catalog.to_jsonb(procedure_value.proacl), '[]'::jsonb
    ),
    'anonExecute', pg_catalog.has_function_privilege(
      'anon', procedure_value.oid, 'EXECUTE'
    ),
    'authenticatedExecute', pg_catalog.has_function_privilege(
      'authenticated', procedure_value.oid, 'EXECUTE'
    ),
    'serviceRoleExecute', pg_catalog.has_function_privilege(
      'service_role', procedure_value.oid, 'EXECUTE'
    )
  ) order by requested.ordinality) into function_manifest
  from pg_catalog.unnest(signatures) with ordinality
    requested(signature, ordinality)
  join pg_catalog.pg_proc procedure_value
    on procedure_value.oid = pg_catalog.to_regprocedure(requested.signature);
  if pg_catalog.jsonb_array_length(coalesce(
       function_manifest, '[]'::jsonb
     )) <> pg_catalog.cardinality(signatures) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_FUNCTION_REQUIRED';
  end if;
  if exists (
    select 1
    from pg_catalog.unnest(signatures) requested(signature)
    join pg_catalog.pg_proc procedure_value
      on procedure_value.oid = pg_catalog.to_regprocedure(requested.signature)
    where (
         requested.signature = any(array[
           'production_control.reject_future_runtime_immutable_v2()',
           'production_control.future_runtime_hash_v2(jsonb)',
           'production_control.future_google_writer_generation_id_v2(text,text)'
         ])
         and (
           procedure_value.prosecdef
           or not (
             case requested.signature
               when 'production_control.future_runtime_hash_v2(jsonb)'
                 then 'search_path=pg_catalog, extensions'
               else 'search_path=pg_catalog, production_control'
             end = any(coalesce(
               procedure_value.proconfig, array[]::text[]
             ))
           )
         )
       )
       or (
         requested.signature <> all(array[
           'production_control.reject_future_runtime_immutable_v2()',
           'production_control.future_runtime_hash_v2(jsonb)',
           'production_control.future_google_writer_generation_id_v2(text,text)'
         ])
         and (
           not procedure_value.prosecdef
           or not ('search_path=pg_catalog' = any(coalesce(
             procedure_value.proconfig, array[]::text[]
           )))
         )
       )
       or pg_catalog.has_function_privilege(
         'anon', procedure_value.oid, 'EXECUTE'
       )
       or pg_catalog.has_function_privilege(
         'authenticated', procedure_value.oid, 'EXECUTE'
       )
       or (
         requested.signature like 'public.%'
         and not pg_catalog.has_function_privilege(
           'service_role', procedure_value.oid, 'EXECUTE'
         )
       )
       or (
         requested.signature not like 'public.%'
         and pg_catalog.has_function_privilege(
           'service_role', procedure_value.oid, 'EXECUTE'
         )
       )
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_PRIVILEGE_REQUIRED';
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'name', trigger_value.tgname,
    'table', namespace_value.nspname || '.' || relation_value.relname,
    'definition', pg_catalog.pg_get_triggerdef(trigger_value.oid, true),
    'enabled', trigger_value.tgenabled::text,
    'function', trigger_value.tgfoid::pg_catalog.regprocedure::text,
    'functionSource', trigger_function.prosrc,
    'functionSecurityDefiner', trigger_function.prosecdef,
    'functionConfiguration', coalesce(
      pg_catalog.to_jsonb(trigger_function.proconfig), '[]'::jsonb
    ),
    'functionAcl', coalesce(
      pg_catalog.to_jsonb(trigger_function.proacl), '[]'::jsonb
    )
  ) order by trigger_value.tgname) into trigger_manifest
  from pg_catalog.pg_trigger trigger_value
  join pg_catalog.pg_class relation_value
    on relation_value.oid = trigger_value.tgrelid
  join pg_catalog.pg_namespace namespace_value
    on namespace_value.oid = relation_value.relnamespace
  join pg_catalog.pg_proc trigger_function
    on trigger_function.oid = trigger_value.tgfoid
  where not trigger_value.tgisinternal
    and trigger_value.tgname = any(trigger_names);
  if pg_catalog.jsonb_array_length(coalesce(
       trigger_manifest, '[]'::jsonb
     )) <> pg_catalog.cardinality(trigger_names) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_TRIGGER_REQUIRED';
  end if;
  -- A trigger name alone is not a safety boundary.  Prove the exact relation,
  -- function, timing/event mask and update-column set that the certified
  -- writer relies on.  This prevents a later migration from moving a named
  -- trigger to a harmless table while retaining the same apparent inventory.
  if 1 <> (
       select pg_catalog.count(*)
       from pg_catalog.pg_trigger trigger_value
       where not trigger_value.tgisinternal
         and trigger_value.tgname = 'sync_future_google_writer_binding_v2'
         and trigger_value.tgrelid = pg_catalog.to_regclass(
           'production_control.future_runtime_match_bindings_v2'
         )
         and trigger_value.tgfoid = pg_catalog.to_regprocedure(
           'production_control.sync_future_google_writer_binding_v2()'
         )
         and trigger_value.tgtype = 21
         and (
            select pg_catalog.array_agg(
              attribute_value.attname::text
              order by target_attribute.ordinality
            )
           from pg_catalog.unnest(
             trigger_value.tgattr::smallint[]
           ) with ordinality target_attribute(attnum, ordinality)
           join pg_catalog.pg_attribute attribute_value
             on attribute_value.attrelid = trigger_value.tgrelid
            and attribute_value.attnum = target_attribute.attnum
         ) = array[
           'runtime_state', 'runtime_revision',
           'structural_setup_revision', 'configuration_fingerprint'
         ]::text[]
     )
     or 1 <> (
       select pg_catalog.count(*)
       from pg_catalog.pg_trigger trigger_value
       where not trigger_value.tgisinternal
         and trigger_value.tgname =
           'future_google_writer_generation_immutable_v2'
         and trigger_value.tgrelid = pg_catalog.to_regclass(
           'production_control.future_google_writer_generations_v2'
         )
         and trigger_value.tgfoid = pg_catalog.to_regprocedure(
           'production_control.reject_future_runtime_immutable_v2()'
         )
         and trigger_value.tgtype = 27
         and pg_catalog.cardinality(
           trigger_value.tgattr::smallint[]
         ) = 0
     )
     or 1 <> (
       select pg_catalog.count(*)
       from pg_catalog.pg_trigger trigger_value
       where not trigger_value.tgisinternal
         and trigger_value.tgname = 'future_google_writer_target_immutable_v2'
         and trigger_value.tgrelid = pg_catalog.to_regclass(
           'production_control.future_google_writer_targets_v2'
         )
         and trigger_value.tgfoid = pg_catalog.to_regprocedure(
           'production_control.reject_future_runtime_immutable_v2()'
         )
         and trigger_value.tgtype = 27
         and pg_catalog.cardinality(
           trigger_value.tgattr::smallint[]
         ) = 0
     )
     or 1 <> (
       select pg_catalog.count(*)
       from pg_catalog.pg_trigger trigger_value
       where not trigger_value.tgisinternal
         and trigger_value.tgname =
           'production_future_google_writer_receipt_immutable_v1'
         and trigger_value.tgrelid = pg_catalog.to_regclass(
           'production_control.future_google_writer_certification_receipts_v1'
         )
         and trigger_value.tgfoid = pg_catalog.to_regprocedure(
           'production_control.reject_future_runtime_immutable_v2()'
         )
         and trigger_value.tgtype = 27
         and pg_catalog.cardinality(
           trigger_value.tgattr::smallint[]
         ) = 0
     )
     or 1 <> (
       select pg_catalog.count(*)
       from pg_catalog.pg_trigger trigger_value
       where not trigger_value.tgisinternal
         and trigger_value.tgname =
           'production_future_google_writer_audit_immutable_v1'
         and trigger_value.tgrelid = pg_catalog.to_regclass(
           'production_control.future_google_writer_certification_audit_v1'
         )
         and trigger_value.tgfoid = pg_catalog.to_regprocedure(
           'production_control.reject_future_runtime_immutable_v2()'
         )
         and trigger_value.tgtype = 27
         and pg_catalog.cardinality(
           trigger_value.tgattr::smallint[]
         ) = 0
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_TRIGGER_TOPOLOGY_REQUIRED';
  end if;
  if 6 <> (
    select pg_catalog.count(*)
    from pg_catalog.pg_trigger trigger_value
    where not trigger_value.tgisinternal
      and trigger_value.tgrelid = any(array[
        pg_catalog.to_regclass(
          'production_control.future_runtime_match_bindings_v2'
        ),
        pg_catalog.to_regclass(
          'production_control.future_match_google_compatibility_jobs_v1'
        ),
        pg_catalog.to_regclass(
          'production_control.future_google_writer_generations_v2'
        ),
        pg_catalog.to_regclass(
          'production_control.future_google_writer_targets_v2'
        ),
        pg_catalog.to_regclass(
          'production_control.future_google_writer_certification_receipts_v1'
        ),
        pg_catalog.to_regclass(
          'production_control.future_google_writer_certification_audit_v1'
        )
      ]::oid[])
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_TRIGGER_TOPOLOGY_REQUIRED';
  end if;
  if exists (
    select 1
    from pg_catalog.pg_trigger trigger_value
    join pg_catalog.pg_proc trigger_function
      on trigger_function.oid = trigger_value.tgfoid
    where not trigger_value.tgisinternal
      and trigger_value.tgname = any(trigger_names)
      and (trigger_value.tgenabled <> 'O'
        or (trigger_value.tgname = 'sync_future_google_writer_binding_v2'
          and not trigger_function.prosecdef)
        or not (
          'search_path=pg_catalog' = any(coalesce(
            trigger_function.proconfig, array[]::text[]
          ))
          or 'search_path=pg_catalog, production_control' = any(coalesce(
            trigger_function.proconfig, array[]::text[]
          ))
        )
        or pg_catalog.has_function_privilege(
          'anon', trigger_function.oid, 'EXECUTE'
        )
        or pg_catalog.has_function_privilege(
          'authenticated', trigger_function.oid, 'EXECUTE'
        )
        or pg_catalog.has_function_privilege(
          'service_role', trigger_function.oid, 'EXECUTE'
        ))
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_TRIGGER_SECURITY_REQUIRED';
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'relation', requested.relation_name,
    'owner', pg_catalog.pg_get_userbyid(relation_value.relowner),
    'rowSecurity', relation_value.relrowsecurity,
    'forceRowSecurity', relation_value.relforcerowsecurity,
    'acl', coalesce(pg_catalog.to_jsonb(relation_value.relacl), '[]'::jsonb),
    'policies', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'name', policy_value.polname,
        'command', policy_value.polcmd::text,
        'permissive', policy_value.polpermissive,
        'using', pg_catalog.pg_get_expr(
          policy_value.polqual, policy_value.polrelid
        ),
        'check', pg_catalog.pg_get_expr(
          policy_value.polwithcheck, policy_value.polrelid
        )
      ) order by policy_value.polname)
      from pg_catalog.pg_policy policy_value
      where policy_value.polrelid = relation_value.oid
    ), '[]'::jsonb),
    'anonDataAccess', pg_catalog.has_table_privilege(
      'anon', relation_value.oid, 'SELECT'
    ) or pg_catalog.has_table_privilege(
      'anon', relation_value.oid, 'INSERT'
    ) or pg_catalog.has_table_privilege(
      'anon', relation_value.oid, 'UPDATE'
    ) or pg_catalog.has_table_privilege(
      'anon', relation_value.oid, 'DELETE'
    ),
    'authenticatedDataAccess', pg_catalog.has_table_privilege(
      'authenticated', relation_value.oid, 'SELECT'
    ) or pg_catalog.has_table_privilege(
      'authenticated', relation_value.oid, 'INSERT'
    ) or pg_catalog.has_table_privilege(
      'authenticated', relation_value.oid, 'UPDATE'
    ) or pg_catalog.has_table_privilege(
      'authenticated', relation_value.oid, 'DELETE'
    ),
    'serviceRoleDataAccess', pg_catalog.has_table_privilege(
      'service_role', relation_value.oid, 'SELECT'
    ) or pg_catalog.has_table_privilege(
      'service_role', relation_value.oid, 'INSERT'
    ) or pg_catalog.has_table_privilege(
      'service_role', relation_value.oid, 'UPDATE'
    ) or pg_catalog.has_table_privilege(
      'service_role', relation_value.oid, 'DELETE'
    )
  ) order by requested.ordinality) into relation_manifest
  from pg_catalog.unnest(relation_names) with ordinality
    requested(relation_name, ordinality)
  join pg_catalog.pg_class relation_value
    on relation_value.oid = pg_catalog.to_regclass(requested.relation_name);
  if pg_catalog.jsonb_array_length(coalesce(
       relation_manifest, '[]'::jsonb
     )) <> pg_catalog.cardinality(relation_names) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_RELATION_REQUIRED';
  end if;
  if exists (
    select 1
    from pg_catalog.unnest(relation_names) requested(relation_name)
    join pg_catalog.pg_class relation_value
      on relation_value.oid = pg_catalog.to_regclass(requested.relation_name)
    where not relation_value.relrowsecurity
       or relation_value.relforcerowsecurity
       or exists (
         select 1 from pg_catalog.pg_policy policy_value
         where policy_value.polrelid = relation_value.oid
       )
       or pg_catalog.has_table_privilege(
         'anon', relation_value.oid, 'SELECT'
       ) or pg_catalog.has_table_privilege(
         'anon', relation_value.oid, 'INSERT'
       ) or pg_catalog.has_table_privilege(
         'anon', relation_value.oid, 'UPDATE'
       ) or pg_catalog.has_table_privilege(
         'anon', relation_value.oid, 'DELETE'
       ) or pg_catalog.has_table_privilege(
         'authenticated', relation_value.oid, 'SELECT'
       ) or pg_catalog.has_table_privilege(
         'authenticated', relation_value.oid, 'INSERT'
       ) or pg_catalog.has_table_privilege(
         'authenticated', relation_value.oid, 'UPDATE'
       ) or pg_catalog.has_table_privilege(
         'authenticated', relation_value.oid, 'DELETE'
       ) or pg_catalog.has_table_privilege(
         'service_role', relation_value.oid, 'SELECT'
       ) or pg_catalog.has_table_privilege(
         'service_role', relation_value.oid, 'INSERT'
       ) or pg_catalog.has_table_privilege(
         'service_role', relation_value.oid, 'UPDATE'
       ) or pg_catalog.has_table_privilege(
         'service_role', relation_value.oid, 'DELETE'
       ) or pg_catalog.has_table_privilege(
         'anon', relation_value.oid, 'TRUNCATE'
       ) or pg_catalog.has_table_privilege(
         'authenticated', relation_value.oid, 'TRUNCATE'
       ) or pg_catalog.has_table_privilege(
         'service_role', relation_value.oid, 'TRUNCATE'
       ) or pg_catalog.has_table_privilege(
         'anon', relation_value.oid, 'REFERENCES'
       ) or pg_catalog.has_table_privilege(
         'authenticated', relation_value.oid, 'REFERENCES'
       ) or pg_catalog.has_table_privilege(
         'service_role', relation_value.oid, 'REFERENCES'
       ) or pg_catalog.has_table_privilege(
         'anon', relation_value.oid, 'TRIGGER'
       ) or pg_catalog.has_table_privilege(
         'authenticated', relation_value.oid, 'TRIGGER'
       ) or pg_catalog.has_table_privilege(
         'service_role', relation_value.oid, 'TRIGGER'
       ) or pg_catalog.has_any_column_privilege(
         'anon', relation_value.oid, 'SELECT,INSERT,UPDATE,REFERENCES'
       ) or pg_catalog.has_any_column_privilege(
         'authenticated', relation_value.oid,
         'SELECT,INSERT,UPDATE,REFERENCES'
       ) or pg_catalog.has_any_column_privilege(
         'service_role', relation_value.oid,
         'SELECT,INSERT,UPDATE,REFERENCES'
       )
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_RELATION_SECURITY_REQUIRED';
  end if;
  if pg_catalog.has_schema_privilege(
       'anon', 'production_control', 'CREATE'
     ) or pg_catalog.has_schema_privilege(
       'authenticated', 'production_control', 'CREATE'
     ) or pg_catalog.has_schema_privilege(
       'service_role', 'production_control', 'CREATE'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_IMPLEMENTATION_SCHEMA_SECURITY_REQUIRED';
  end if;

  -- Migration102 added this exact security trigger to the receipt table.
  -- Preserve the old five-trigger topology and reject every unrecognized extra.
  if 1 <> (
    select count(*) from pg_trigger t join pg_proc p on p.oid=t.tgfoid
    where not t.tgisinternal and t.tgname='bagger_live_actor_auth_user_id'
      and t.tgrelid='production_control.future_google_writer_certification_receipts_v1'::regclass
      and t.tgfoid='participant_identity.require_live_authorship_v1()'::regprocedure
      and t.tgtype=23 and t.tgenabled='O' and t.tgnargs=1
      and encode(t.tgargs,'hex')='6163746f725f617574685f757365725f696400'
      and cardinality(t.tgattr::smallint[])=1 and (select attnum from pg_attribute
        where attrelid=t.tgrelid and attname='actor_auth_user_id' and not attisdropped)=any(t.tgattr::smallint[])
      and p.prosecdef and p.proconfig=array['search_path=pg_catalog']::text[]
      and encode(extensions.digest(p.prosrc,'sha256'),'hex')='fdc0e44e1e1445256efb4018e37998df2c3a089ffd62103a415c695f1f8491b1'
      and not has_function_privilege('anon',p.oid,'EXECUTE')
      and not has_function_privilege('authenticated',p.oid,'EXECUTE')
      and not has_function_privilege('service_role',p.oid,'EXECUTE')
  ) then
    raise exception using errcode='55000',message='PRODUCTION_FUTURE_GOOGLE_AUTHORSHIP_TOPOLOGY_REQUIRED';
  end if;
  select jsonb_build_object('name',t.tgname,'table',t.tgrelid::regclass::text,
    'definition',pg_get_triggerdef(t.oid,true),'type',t.tgtype,
    'attributes',t.tgattr::text,'arguments',encode(t.tgargs,'hex'),'enabled',t.tgenabled::text,
    'function',t.tgfoid::regprocedure::text,'functionSourceSha256',encode(extensions.digest(p.prosrc,'sha256'),'hex'),
    'functionSource',p.prosrc,'functionSecurityDefiner',p.prosecdef,
    'functionConfiguration',p.proconfig,'functionAcl',p.proacl) into authorship_manifest
    from pg_trigger t join pg_proc p on p.oid=t.tgfoid
    where not t.tgisinternal and t.tgname='bagger_live_actor_auth_user_id'
      and t.tgrelid='production_control.future_google_writer_certification_receipts_v1'::regclass;

  return pg_catalog.jsonb_build_object(
    'contractVersion', 'production-future-google-writer-implementation-v3',
    'installedContract',
      '202608300071_production_annual_reads_workers_v1',
    'requiredArtifacts', pg_catalog.jsonb_build_array(
      'LIVE_MATCHES_ROW', 'MATCHES_ROW'
    ),
    'leaseBound', true,
    'readbackRequired', true,
    'nonAuthoritative', true,
    'rollbackAllowed', false,
    'functions', function_manifest,
    'triggers', trigger_manifest,
    'liveAuthorship', authorship_manifest,
    'relations', relation_manifest
  );
end;
$$;


ALTER FUNCTION production_control.future_google_writer_implementation_manifest_v2() OWNER TO postgres;

--
-- Name: future_google_writer_resource_fingerprint_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_google_writer_resource_fingerprint_v1(target_tournament text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  resource production_control.future_tournament_resources_v1%rowtype;
begin
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target_tournament;
  return production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion',
        'production-annual-google-resource-binding-v1',
      'tournamentId', resource.tournament_id,
      'projectRef', resource.project_ref,
      'projectUrl', resource.project_url,
      'destinationWorkbookId', resource.source_workbook_id,
      'resourceStatus', resource.resource_status,
      'resourceRevision', resource.resource_revision,
      'compatibilityPolicy', resource.google_compatibility_policy
    )
  );
exception when no_data_found then
  raise exception using errcode = '55000',
    message = 'PRODUCTION_FUTURE_GOOGLE_RESOURCE_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.future_google_writer_resource_fingerprint_v1(target_tournament text) OWNER TO postgres;

--
-- Name: future_google_writer_target_fingerprint_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_google_writer_target_fingerprint_v1(target_tournament text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target production_control.future_google_writer_targets_v2%rowtype;
  writer production_control.future_google_writer_generations_v2%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  implementation_fingerprint text;
  resource_fingerprint text;
begin
  select value.* into strict target
  from production_control.future_google_writer_targets_v2 value
  where value.tournament_id = pg_catalog.btrim(target_tournament);
  select value.* into strict writer
  from production_control.future_google_writer_generations_v2 value
  where value.writer_generation_id = target.writer_generation_id;
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target.tournament_id;
  select value.* into strict promotion
  from production_control.future_runtime_promotions_v2 value
  where value.tournament_id = target.tournament_id;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target.tournament_id;
  implementation_fingerprint := production_control
    .future_google_writer_implementation_fingerprint_v2();
  resource_fingerprint := production_control
    .future_google_writer_resource_fingerprint_v1(target.tournament_id);
  return production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion',
        'production-annual-google-writer-certification-v1',
      'writerContractVersion',
        'production-future-google-match-provisioning-v2',
      'targetTournamentId', target.tournament_id,
      'tournamentYear', catalog.tournament_year,
      'setupRevision', catalog.setup_revision,
      'promotionRevision', promotion.promotion_revision,
      'promotedManifestFingerprint',
        promotion.promoted_manifest_fingerprint,
      'resourceRevision', resource.resource_revision,
      'resourceBindingFingerprint', resource_fingerprint,
      'writerGenerationId', production_control
        .future_google_writer_generation_id_v2(
          resource.source_workbook_id, implementation_fingerprint
        ),
      'implementationFingerprint', implementation_fingerprint,
      'requiredArtifacts', pg_catalog.jsonb_build_array(
        'LIVE_MATCHES_ROW', 'MATCHES_ROW'
      ),
      'nonAuthoritative', true,
      'rollbackAllowed', false
    )
  );
exception when no_data_found then
  raise exception using errcode = '55000',
    message = 'PRODUCTION_FUTURE_GOOGLE_WRITER_CONTRACT_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.future_google_writer_target_fingerprint_v1(target_tournament text) OWNER TO postgres;

--
-- Name: future_handicap_match_context_v2(text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_handicap_match_context_v2(target_match_id text, target_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  match_value scoring_authority.matches%rowtype;
  detail scoring_authority.tournament_setup_match_details_v1%rowtype;
  tee scoring_authority.tournament_setup_course_tees_v1%rowtype;
  computed jsonb;
  participant_configuration jsonb;
  team_configuration jsonb;
  team_1_playing numeric;
  team_2_playing numeric;
  team_1_strokes integer;
  team_2_strokes integer;
begin
  select value.* into strict match_value
  from scoring_authority.matches value
  where value.match_id = target_match_id;
  select value.* into strict detail
  from scoring_authority.tournament_setup_match_details_v1 value
  where value.match_id = target_match_id
    and value.tournament_id = match_value.tournament_id;
  select value.* into strict tee
  from scoring_authority.tournament_setup_course_tees_v1 value
  where value.tournament_id = match_value.tournament_id
    and value.course_id = detail.course_id and value.tee_id = detail.tee_id;
  with course_values as (
    select participant.player_id, participant.team_side,
      participant.player_slot, entry.tournament_handicap,
      entry.tournament_handicap * (tee.slope::numeric / 113::numeric)
        + (tee.rating - tee.par::numeric) course_handicap
    from scoring_authority.match_participants participant
    join scoring_authority.handicap_revision_entries entry
      on entry.revision_id = target_revision_id
     and entry.tournament_id = match_value.tournament_id
     and entry.player_id = participant.player_id
    where participant.match_id = target_match_id
  ), calculated as (
    select course.*,
      case match_value.format when 'SC' then 0::numeric
        else pg_catalog.round(course.course_handicap, 0) end playing_handicap,
      case match_value.format
        when 'BB' then pg_catalog.round((course.course_handicap
          - pg_catalog.min(course.course_handicap) over ()) * 0.9, 0)::integer
        when 'SI' then pg_catalog.round(course.course_handicap
          - pg_catalog.min(course.course_handicap) over (), 0)::integer
        else 0::integer end final_strokes
    from course_values course
  )
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'player_id', value.player_id, 'team_side', value.team_side,
    'player_slot', value.player_slot,
    'tournament_handicap', value.tournament_handicap,
    'handicap_index', value.tournament_handicap,
    'course_handicap', value.course_handicap,
    'playing_handicap', value.playing_handicap,
    'final_strokes', value.final_strokes
  ) order by value.team_side, value.player_slot)
  into strict computed from calculated value;
  select pg_catalog.jsonb_build_object(
    'team_1', coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id', item->>'player_id', 'team', 1,
      'slot', (item->>'player_slot')::integer,
      'handicap_index', (item->>'handicap_index')::numeric,
      'course_handicap', (item->>'course_handicap')::numeric,
      'playing_handicap', (item->>'playing_handicap')::numeric,
      'final_strokes', (item->>'final_strokes')::integer,
      'tournament_handicap', (item->>'tournament_handicap')::numeric,
      'handicap_revision_id', target_revision_id
    ) order by (item->>'player_slot')::integer)
      filter (where (item->>'team_side')::integer = 1), '[]'::jsonb),
    'team_2', coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id', item->>'player_id', 'team', 2,
      'slot', (item->>'player_slot')::integer,
      'handicap_index', (item->>'handicap_index')::numeric,
      'course_handicap', (item->>'course_handicap')::numeric,
      'playing_handicap', (item->>'playing_handicap')::numeric,
      'final_strokes', (item->>'final_strokes')::integer,
      'tournament_handicap', (item->>'tournament_handicap')::numeric,
      'handicap_revision_id', target_revision_id
    ) order by (item->>'player_slot')::integer)
      filter (where (item->>'team_side')::integer = 2), '[]'::jsonb),
    'all_ids', pg_catalog.jsonb_agg(item->>'player_id' order by
      (item->>'team_side')::integer, (item->>'player_slot')::integer),
    'handicap_revision_id', target_revision_id,
    'handicap_context_contract', 'production-handicap-context-v1'
  ) into participant_configuration
  from pg_catalog.jsonb_array_elements(computed) item;
  if match_value.format = 'SC' then
    select pg_catalog.round(pg_catalog.min((item->>'course_handicap')::numeric) * 0.35
      + pg_catalog.max((item->>'course_handicap')::numeric) * 0.15, 0)
      into team_1_playing from pg_catalog.jsonb_array_elements(computed) item
      where (item->>'team_side')::integer = 1;
    select pg_catalog.round(pg_catalog.min((item->>'course_handicap')::numeric) * 0.35
      + pg_catalog.max((item->>'course_handicap')::numeric) * 0.15, 0)
      into team_2_playing from pg_catalog.jsonb_array_elements(computed) item
      where (item->>'team_side')::integer = 2;
    team_1_strokes := (team_1_playing - least(team_1_playing, team_2_playing))::integer;
    team_2_strokes := (team_2_playing - least(team_1_playing, team_2_playing))::integer;
  else
    select pg_catalog.max((item->>'playing_handicap')::numeric),
      pg_catalog.max((item->>'final_strokes')::integer)
      into team_1_playing, team_1_strokes
    from pg_catalog.jsonb_array_elements(computed) item
    where (item->>'team_side')::integer = 1;
    select pg_catalog.max((item->>'playing_handicap')::numeric),
      pg_catalog.max((item->>'final_strokes')::integer)
      into team_2_playing, team_2_strokes
    from pg_catalog.jsonb_array_elements(computed) item
    where (item->>'team_side')::integer = 2;
  end if;
  team_configuration := pg_catalog.jsonb_build_object(
    'team_1_handicap', team_1_playing,
    'team_2_handicap', team_2_playing,
    'team_1_playing_handicap', team_1_playing,
    'team_2_playing_handicap', team_2_playing,
    'team_1_strokes', team_1_strokes,
    'team_2_strokes', team_2_strokes,
    'handicap_revision_id', target_revision_id,
    'handicap_context_contract', 'production-handicap-context-v1'
  );
  return pg_catalog.jsonb_build_object(
    'participants', computed,
    'participant_configuration', participant_configuration,
    'team_configuration', team_configuration
  );
exception when no_data_found then
  raise exception using errcode = '55000',
    message = 'FUTURE_HANDICAP_CONTEXT_INCOMPLETE';
end;
$$;


ALTER FUNCTION production_control.future_handicap_match_context_v2(target_match_id text, target_revision_id uuid) OWNER TO postgres;

--
-- Name: future_participant_identity_binding_fingerprint_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_participant_identity_binding_fingerprint_v1(target_tournament_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select encode(extensions.digest(pg_catalog.convert_to(
    pg_catalog.jsonb_build_object(
      'contract', context.contract_version,
      'tournamentId', context.tournament_id,
      'runtimeGenerationId', context.runtime_generation_id,
      'authorityGenerationId', context.authority_generation_id,
      'admissionGenerationId', context.admission_generation_id,
      'pointerRevision', context.pointer_revision,
      'sourceTournamentId', context.source_identity_tournament_id,
      'sourceContextRevision', context.source_context_revision,
      'sourceConfigurationFingerprint',
        context.source_configuration_fingerprint,
      'roster', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'playerId', binding.player_id,
          'contactState', binding.contact_state,
          'state', binding.enrollment_state,
          'sourceContactFingerprint', binding.source_contact_fingerprint,
          'linkRevision', binding.bound_link_revision
        ) order by binding.player_id)
        from participant_identity.future_tournament_participant_bindings_v1
          binding
        where binding.tournament_id = context.tournament_id
      ), '[]'::jsonb)
    )::text, 'UTF8'), 'sha256'), 'hex')
  from participant_identity.future_tournament_identity_contexts_v1 context
  where context.tournament_id = pg_catalog.btrim(target_tournament_id);
$$;


ALTER FUNCTION production_control.future_participant_identity_binding_fingerprint_v1(target_tournament_id text) OWNER TO postgres;

--
-- Name: future_participant_identity_eligibility_core_v1(text, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_participant_identity_eligibility_core_v1(target_tournament_id text, target_resource_id text, target_provenance_id text) RETURNS TABLE(player_id text, auth_user_id uuid, link_revision bigint, source_configuration_revision bigint, source_email text, source_email_normalized text, source_updated_at timestamp with time zone, source_contact_fingerprint text, contact_approved boolean, linked_verified boolean, runtime_eligible boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
  with resource as (
    select target_provenance_id as google_workbook_id
  ), source_context as (
    select value.context_revision, value.configuration_fingerprint
    from participant_identity.identity_context_revisions value
    where value.tournament_id = '2026'
      and value.configuration_fingerprint ~ '^[0-9a-f]{64}$'
  ), approved_run as (
    select value.source_system, value.source_workbook_id
    from participant_identity.identity_config_import_runs value
    cross join source_context
    cross join resource
    where value.tournament_id = '2026'
      and value.configuration_revision = source_context.context_revision
      and value.source_fingerprint = source_context.configuration_fingerprint
      and value.source_workbook_id = resource.google_workbook_id
      and value.status = 'APPROVED'
      and value.approved_at is not null
    order by value.approved_at desc, value.requested_at desc
    limit 1
  ), active_roster as (
    select membership.player_id
    from scoring_authority.tournament_players membership
    where membership.tournament_id = pg_catalog.btrim(target_tournament_id)
      and membership.participation_status = 'ACTIVE'
  ), approved_contacts as (
    select roster.player_id, contact.configuration_revision,
      contact.email, contact.email_normalized, contact.updated_at,
      encode(extensions.digest(pg_catalog.concat_ws('|',
        contact.player_id, contact.email_normalized,
        contact.configuration_revision::text)::text, 'sha256'), 'hex')
        as contact_fingerprint
    from active_roster roster
    join participant_identity.participant_identity_contacts contact
      on contact.tournament_id = '2026'
     and contact.player_id = roster.player_id
     and contact.identity_active
    join source_context
      on source_context.context_revision = contact.configuration_revision
    join approved_run
      on approved_run.source_workbook_id = contact.source_workbook_id
     and approved_run.source_system = contact.source_system
    where contact.player_id = pg_catalog.upper(pg_catalog.btrim(
        contact.player_id
      ))
      and contact.player_id ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
      and contact.email_normalized = pg_catalog.lower(pg_catalog.btrim(
        contact.email
      ))
      and contact.email_normalized ~* (
        '^[A-Z0-9.!#$%&''*+/=?^_`{|}~-]+@'
        || '[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?'
        || '(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$'
      )::pg_catalog.text collate "C"
      and pg_catalog.split_part(contact.email_normalized, '@', 2)
        !~* '(^|\.)(example\.(com|net|org)|invalid|test|localhost)$'
  ), link_candidates as (
    select contact.player_id, link.auth_user_id, link.link_revision,
      pg_catalog.count(*) over (partition by contact.player_id)
        as candidate_count
    from approved_contacts contact
    join participant_identity.user_player_links link
      on link.player_id = contact.player_id
     and link.status = 'ACTIVE'
     and link.revoked_at is null
     and link.email_identity_hash = encode(extensions.digest(
       contact.email_normalized::text, 'sha256'), 'hex')
    join participant_identity.participant_auth_identifiers identifier
      on identifier.player_id = link.player_id
     and identifier.auth_user_id = link.auth_user_id
     and identifier.identifier_type = 'EMAIL'
     and identifier.status = 'VERIFIED'
     and identifier.revoked_at is null
     and identifier.normalized_value_private = contact.email_normalized
    join auth.users auth_user
      on auth_user.id = link.auth_user_id
     and auth_user.email_confirmed_at is not null
     and pg_catalog.lower(pg_catalog.btrim(coalesce(auth_user.email, '')))
       = contact.email_normalized
  ), pointer as (
    select value.*
    from production_control.current_tournament_pointer_v1 value
    where value.scope_key = target_resource_id
  ), catalog as (
    select value.*
    from production_control.future_tournament_catalog_v1 value
    where value.tournament_id = pg_catalog.btrim(target_tournament_id)
  ), generation as (
    select value.*
    from production_control.future_annual_runtime_generations_v1 value
    where value.tournament_id = pg_catalog.btrim(target_tournament_id)
      and value.generation_status = 'ACTIVE'
  )
  select roster.player_id,
    link.auth_user_id, link.link_revision,
    contact.configuration_revision, contact.email,
    contact.email_normalized, contact.updated_at,
    contact.contact_fingerprint,
    contact.player_id is not null as contact_approved,
    link.player_id is not null as linked_verified,
    coalesce(link.player_id is not null
      and pointer.tournament_id = pg_catalog.btrim(target_tournament_id)
      and pointer.tournament_year > 2026
      and catalog.lifecycle = 'ACTIVE'
      and catalog.lifecycle_revision = pointer.lifecycle_revision
      and generation.pointer_revision = pointer.pointer_revision
      and generation.authority = 'SUPABASE'
      and generation.ingress_state = 'OPEN'
      and context.status = 'CERTIFIED'
      and context.runtime_generation_id = generation.runtime_generation_id
      and context.authority_generation_id = generation.authority_generation_id
      and context.admission_generation_id = generation.admission_generation_id
      and context.pointer_revision = generation.pointer_revision
      and binding.enrollment_state = 'ENROLLED'
      and binding.contact_state = 'APPROVED'
      and binding.binding_revision = context.binding_revision
      and binding.bound_link_revision = link.link_revision
      and binding.source_configuration_revision =
        contact.configuration_revision
      and binding.source_contact_fingerprint =
        contact.contact_fingerprint
      and future_contact.identity_active
      and future_contact.email_normalized = contact.email_normalized
      and participant_role.role_active
      and participant_role.revoked_at is null, false) as runtime_eligible
  from active_roster roster
  left join approved_contacts contact
    on contact.player_id = roster.player_id
  left join link_candidates link
    on link.player_id = roster.player_id
   and link.candidate_count = 1
  cross join pointer
  left join catalog on true
  left join generation on true
  left join participant_identity.future_tournament_identity_contexts_v1 context
    on context.tournament_id = pg_catalog.btrim(target_tournament_id)
  left join participant_identity.future_tournament_participant_bindings_v1 binding
    on binding.tournament_id = pg_catalog.btrim(target_tournament_id)
   and binding.player_id = roster.player_id
  left join participant_identity.participant_identity_contacts future_contact
    on future_contact.tournament_id = pg_catalog.btrim(target_tournament_id)
   and future_contact.player_id = roster.player_id
  left join participant_identity.tournament_roles participant_role
    on participant_role.tournament_id = pg_catalog.btrim(target_tournament_id)
   and participant_role.auth_user_id = link.auth_user_id
   and participant_role.role = 'PARTICIPANT'
  order by roster.player_id;
$_$;


ALTER FUNCTION production_control.future_participant_identity_eligibility_core_v1(target_tournament_id text, target_resource_id text, target_provenance_id text) OWNER TO postgres;

--
-- Name: future_participant_identity_eligibility_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_participant_identity_eligibility_v1(target_tournament_id text) RETURNS TABLE(player_id text, auth_user_id uuid, link_revision bigint, source_configuration_revision bigint, source_email text, source_email_normalized text, source_updated_at timestamp with time zone, source_contact_fingerprint text, contact_approved boolean, linked_verified boolean, runtime_eligible boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare resource_context jsonb; provenance text;
begin
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION') then
    resource_context:=production_control.annual_resource_context_v2();
    if resource_context->>'resource_class' is distinct from 'CERTIFICATION' then
      raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_RESOURCE_REQUIRED';end if;
    return query select * from production_control.future_participant_identity_eligibility_core_v1(
      target_tournament_id,resource_context->>'resource_id',resource_context->>'provenance_id');
  else
    -- Preserve missing/invalid Production source as an unapproved contact set,
    -- not a new exception. The fixed Production pointer still scopes the roster.
    select value.google_workbook_id into provenance from production_control.resource_scope value
     where value.scope_key='BAGGER_INV_PRODUCTION' and value.project_ref='ymqhhtxaywtqllynrmxe'
      and value.project_url='https://ymqhhtxaywtqllynrmxe.supabase.co';
    return query select * from production_control.future_participant_identity_eligibility_core_v1(
      target_tournament_id,'BAGGER_INV_PRODUCTION',provenance);
  end if;
end;
$$;


ALTER FUNCTION production_control.future_participant_identity_eligibility_v1(target_tournament_id text) OWNER TO postgres;

--
-- Name: future_participant_identity_readiness_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_participant_identity_readiness_v1(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  roster_count_value integer;
  contact_count_value integer;
  linked_count_value integer;
  owner_count_value integer;
  director_count_value integer;
  fingerprint_value text;
begin
  with eligibility as (
    select value.*
    from production_control.future_participant_identity_eligibility_v1(
      pg_catalog.btrim(target_tournament_id)
    ) value
  )
  select pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter (
      where eligibility.contact_approved
    )::integer,
    pg_catalog.count(*) filter (
      where eligibility.linked_verified
    )::integer
  into roster_count_value, contact_count_value, linked_count_value
  from eligibility;
  select pg_catalog.count(*)::integer into owner_count_value
  from production_control.future_global_owner_eligibility_v1();
  select pg_catalog.count(distinct eligibility.player_id)::integer
    into director_count_value
  from production_control.future_participant_identity_eligibility_v1(
    pg_catalog.btrim(target_tournament_id)
  ) eligibility
  join production_control.director_entitlements entitlement
    on entitlement.tournament_id = pg_catalog.btrim(target_tournament_id)
   and entitlement.player_id = eligibility.player_id
   and entitlement.auth_user_id = eligibility.auth_user_id
   and entitlement.role = 'DIRECTOR'
   and entitlement.status = 'ACTIVE'
   and entitlement.revoked_at is null
  join participant_identity.tournament_roles role_value
    on role_value.tournament_id = entitlement.tournament_id
   and role_value.auth_user_id = entitlement.auth_user_id
   and role_value.role = 'DIRECTOR'
   and role_value.role_active
   and role_value.revoked_at is null
  where eligibility.linked_verified;
  fingerprint_value := encode(extensions.digest(pg_catalog.convert_to(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-future-participant-identity-readiness-v1',
      'tournamentId', pg_catalog.btrim(target_tournament_id),
      'rosterCount', roster_count_value,
      'approvedContactCount', contact_count_value,
      'linkedVerifiedCount', linked_count_value,
      'notEnrolledCount', roster_count_value - linked_count_value,
      'ownerEligibleCount', owner_count_value,
      'futureDirectorEligibleCount', director_count_value
    )::text, 'UTF8'), 'sha256'), 'hex');
  return pg_catalog.jsonb_build_object(
    'contractVersion', 'production-future-participant-identity-readiness-v1',
    'tournamentId', pg_catalog.btrim(target_tournament_id),
    'ready', roster_count_value >= 1 and contact_count_value >= 1
      and owner_count_value >= 1 and director_count_value >= 1,
    'rosterCount', roster_count_value,
    'approvedContactCount', contact_count_value,
    'linkedVerifiedCount', linked_count_value,
    'notEnrolledCount', roster_count_value - linked_count_value,
    'ownerEligibleCount', owner_count_value,
    'futureDirectorEligibleCount', director_count_value,
    'partialRosterPolicy', true,
    'fingerprint', fingerprint_value
  );
end;
$$;


ALTER FUNCTION production_control.future_participant_identity_readiness_v1(target_tournament_id text) OWNER TO postgres;

--
-- Name: future_runtime_hash_v2(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_runtime_hash_v2(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
  select pg_catalog.encode(extensions.digest(value::text, 'sha256'), 'hex')
$$;


ALTER FUNCTION production_control.future_runtime_hash_v2(value jsonb) OWNER TO postgres;

--
-- Name: future_runtime_readiness_before_annual_odds_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_runtime_readiness_before_annual_odds_v1(target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  base jsonb;
  identity_value jsonb;
  blockers_value jsonb;
  counts_value jsonb;
  fingerprint_value text;
begin
  base := production_control
    .future_runtime_readiness_before_identity_v1(target_tournament);
  identity_value := production_control
    .future_participant_identity_readiness_v1(target_tournament);
  blockers_value := coalesce(base->'blockers', '[]'::jsonb);
  if not coalesce((identity_value->>'ready')::boolean, false) then
    blockers_value := blockers_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'FUTURE_PARTICIPANT_IDENTITY_NOT_READY',
        'section', 'Identity',
        'message', 'At least one approved participant contact, an eligible future Director, and an active global Owner are required.'
      )
    );
  end if;
  counts_value := coalesce(base->'counts', '{}'::jsonb) ||
    pg_catalog.jsonb_build_object(
      'identityApprovedContacts',
        (identity_value->>'approvedContactCount')::integer,
      'identityLinkedVerified',
        (identity_value->>'linkedVerifiedCount')::integer,
      'identityNotEnrolled', (identity_value->>'notEnrolledCount')::integer,
      'identityOwnerEligible', (identity_value->>'ownerEligibleCount')::integer,
      'identityFutureDirectorEligible',
        (identity_value->>'futureDirectorEligibleCount')::integer
    );
  base := base || pg_catalog.jsonb_build_object(
    'ready', pg_catalog.jsonb_array_length(blockers_value) = 0,
    'blockerCount', pg_catalog.jsonb_array_length(blockers_value),
    'blockers', blockers_value,
    'counts', counts_value,
    'participantIdentityReadiness', identity_value
  );
  fingerprint_value := production_control.future_runtime_hash_v2(
    base - 'fingerprint'
  );
  return base || pg_catalog.jsonb_build_object(
    'fingerprint', fingerprint_value
  );
end;
$$;


ALTER FUNCTION production_control.future_runtime_readiness_before_annual_odds_v1(target_tournament text) OWNER TO postgres;

--
-- Name: future_runtime_readiness_before_identity_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_runtime_readiness_before_identity_v1(target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  catalog production_control.future_tournament_catalog_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  blockers jsonb := '[]'::jsonb;
  blocker_count integer;
  team_count integer;
  roster_count integer;
  round_count integer;
  course_count integer;
  match_count integer;
  paired_count integer;
  prepared_count integer;
  compat_count integer;
  projection_count integer;
  handicap_revision bigint;
  fingerprint_value text;
begin
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target_tournament;
  select value.* into promotion
  from production_control.future_runtime_promotions_v2 value
  where value.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into team_count
  from scoring_authority.teams value
  where value.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into roster_count
  from scoring_authority.tournament_players value
  where value.tournament_id = target_tournament
    and value.participation_status = 'ACTIVE';
  select pg_catalog.count(*)::integer into round_count
  from scoring_authority.rounds value
  where value.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into course_count
  from scoring_authority.tournament_setup_round_courses_v1 value
  where value.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into match_count
  from scoring_authority.matches value
  where value.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into paired_count
  from scoring_authority.matches match_value
  where match_value.tournament_id = target_tournament
    and (select pg_catalog.count(*)
      from scoring_authority.match_participants participant
      where participant.match_id = match_value.match_id) =
      case when match_value.format = 'SI' then 2 else 4 end;
  select pg_catalog.count(*)::integer into prepared_count
  from scoring_authority.matches match_value
  join production_control.future_runtime_match_bindings_v2 binding
    on binding.match_id = match_value.match_id
   and binding.tournament_id = match_value.tournament_id
  join scoring_authority.tournament_setup_match_details_v1 detail
    on detail.match_id = match_value.match_id
  where match_value.tournament_id = target_tournament
    and match_value.scoring_snapshot_id is not null
    and binding.runtime_state = 'PREPARED'
    and detail.prepared_setup_revision = detail.setup_revision
    and detail.prepared_configuration_fingerprint =
      binding.configuration_fingerprint;
  compat_count := 0; -- Zero required Google certifications; not a fabricated PASS.
  select pg_catalog.count(*)::integer into projection_count
  from production_control.future_annual_projection_bindings_v1 value
  where value.tournament_id = target_tournament
    and value.certification_status = 'CERTIFIED';
  select value.revision_number into handicap_revision
  from scoring_authority.handicap_revision_current value
  where value.tournament_id = target_tournament;

  if promotion.tournament_id is null then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code',
        'FUTURE_RUNTIME_PROMOTION_REQUIRED', 'section', 'Runtime',
        'message', 'Promote the reviewed tournament structure.')
    );
  end if;
  if team_count <> 2 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'FUTURE_TEAMS_INCOMPLETE',
        'section', 'Teams', 'message', 'Exactly two teams are required.')
    );
  end if;
  if roster_count = 0 or exists (
    select 1 from scoring_authority.tournament_players value
    where value.tournament_id = target_tournament
      and value.participation_status = 'ACTIVE'
      and (value.team_id is null or value.team_side is null)
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'FUTURE_ROSTER_INCOMPLETE',
        'section', 'Roster',
        'message', 'Roster membership and team assignment are incomplete.')
    );
  end if;
  if handicap_revision is null or exists (
    select 1 from scoring_authority.tournament_players value
    where value.tournament_id = target_tournament
      and value.participation_status = 'ACTIVE'
      and (value.handicap_revision_id is null
        or value.tournament_handicap is null)
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code',
        'FUTURE_APPROVED_HANDICAP_REVISION_REQUIRED',
        'section', 'Handicaps',
        'message', 'Approve a complete tournament handicap revision.')
    );
  end if;
  if round_count = 0 or course_count <> round_count then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'FUTURE_COURSES_INCOMPLETE',
        'section', 'Courses',
        'message', 'Each round needs a certified course and tee.')
    );
  end if;
  if exists (
    select 1 from scoring_authority.tournament_setup_round_courses_v1 assignment
    where assignment.tournament_id = target_tournament
      and ((select pg_catalog.count(*)
        from scoring_authority.tournament_setup_course_holes_v1 hole
        where hole.tournament_id = assignment.tournament_id
          and hole.course_id = assignment.course_id
          and hole.tee_id = assignment.tee_id) <> 18
      or (select pg_catalog.count(distinct hole.stroke_index)
        from scoring_authority.tournament_setup_course_holes_v1 hole
        where hole.tournament_id = assignment.tournament_id
          and hole.course_id = assignment.course_id
          and hole.tee_id = assignment.tee_id) <> 18)
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code',
        'FUTURE_COURSE_HOLES_INCOMPLETE', 'section', 'Courses',
        'message', 'Every selected tee needs 18 unique stroke indexes.')
    );
  end if;
  if match_count = 0 or paired_count <> match_count
     or prepared_count <> match_count then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code',
        'FUTURE_MATCH_SCORING_CONTEXT_INCOMPLETE', 'section', 'Matches',
        'message', 'Pair and prepare every promoted match.')
    );
  end if;

  if projection_count <> 3 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code',
        'FUTURE_ANNUAL_PROJECTIONS_NOT_CERTIFIED',
        'section', 'Annual content',
        'message', 'Guide, Draft, and Prediction Settings need certified annual revisions.')
    );
  end if;
  if pg_catalog.to_regprocedure(
    'production_control.assert_future_scoring_runtime_capability_v1(text,uuid,uuid,uuid)'
  ) is null then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code',
        'FUTURE_SCORING_RUNTIME_CAPABILITY_NOT_INSTALLED',
        'section', 'Scoring',
        'message', 'The certified annual scoring runtime is not installed.')
    );
  end if;
  if pg_catalog.to_regprocedure(
    'production_control.bind_future_participant_identity_runtime_v1(text,uuid,uuid,uuid,text,uuid)'
  ) is null then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code',
        'FUTURE_PARTICIPANT_IDENTITY_CAPABILITY_NOT_INSTALLED',
        'section', 'Identity',
        'message', 'The certified annual participant identity binding is not installed.')
    );
  end if;
  -- Frozen 2026 scoring RPCs do not yet consume annual lifecycle state.  Keep
  -- first future activation explicitly blocked until a separately authorized
  -- shared scoring-admission overlay proves a CLOSED predecessor cannot accept
  -- another ordinary score/control mutation.  Migration 066 does not rewrite
  -- those certified RPCs or pretend catalog metadata is an enforcement fence.
  blockers := blockers || pg_catalog.jsonb_build_array(
    pg_catalog.jsonb_build_object('code',
      'FUTURE_PREDECESSOR_SCORING_CLOSE_FENCE_NOT_CERTIFIED',
      'section', 'Activation',
      'message', 'The current tournament close fence is not yet certified for activation.')
  );
  -- The future-only pointer-aware read dispatcher is installed by this
  -- migration. No caller-controlled manifest or payload can attest it.
  if exists (select 1 from scoring_authority.matches value
    where value.tournament_id = target_tournament and (
      value.status <> 'UPCOMING' or value.match_revision <> 0
      or value.scored_holes <> 0 or value.unresolved_mutations <> 0
    )) or exists (
      select 1 from scoring_authority.scoring_permissions permission
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
        and permission.can_score and permission.revoked_at is null
    ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code',
        'FUTURE_PREACTIVATION_SCORING_FACTS_FORBIDDEN',
        'section', 'Scoring',
        'message', 'Future tournaments cannot contain scoring or access facts.')
    );
  end if;
  blocker_count := pg_catalog.jsonb_array_length(blockers);
  fingerprint_value := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-future-runtime-readiness-v2',
      'tournamentId', target_tournament,
      'setupRevision', catalog.setup_revision,
      'lifecycleRevision', catalog.lifecycle_revision,
      'promotionRevision', promotion.promotion_revision,
      'promotionFingerprint', promotion.promoted_manifest_fingerprint,
      'handicapRevision', handicap_revision,
      'counts', pg_catalog.jsonb_build_object(
        'teams', team_count, 'roster', roster_count, 'rounds', round_count,
        'courses', course_count, 'matches', match_count,
        'pairings', paired_count, 'currentSnapshots', prepared_count,
        'compatibilityCertified', compat_count,
        'annualProjectionsCertified', projection_count
      ),
      'blockers', blockers
    )
  );
  return pg_catalog.jsonb_build_object(
    'contractVersion', 'production-future-runtime-readiness-v2',
    'tournamentId', target_tournament,
    'setupRevision', catalog.setup_revision,
    'lifecycleRevision', catalog.lifecycle_revision,
    'ready', blocker_count = 0,
    'fingerprint', fingerprint_value,
    'blockerCount', blocker_count,
    'blockers', blockers,
    'counts', pg_catalog.jsonb_build_object(
      'teams', team_count, 'roster', roster_count, 'rounds', round_count,
      'courses', course_count, 'matches', match_count,
      'pairings', paired_count, 'currentSnapshots', prepared_count,
      'compatibilityCertified', compat_count,
      'annualProjectionsCertified', projection_count
    )
  );
end;
$$;


ALTER FUNCTION production_control.future_runtime_readiness_before_identity_v1(target_tournament text) OWNER TO postgres;

--
-- Name: future_runtime_readiness_v2(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_runtime_readiness_v2(target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  base jsonb;
  blockers jsonb;
  counts jsonb;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  config scoring_authority.odds_input_configurations%rowtype;
  pairing_fingerprint_value text;
  current_value boolean := false;
begin
  base := production_control
    .future_runtime_readiness_before_annual_odds_v1(target_tournament);
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pg_catalog.btrim(target_tournament);
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = catalog.tournament_id;
  select value.* into config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = catalog.tournament_id and value.is_current;
  pairing_fingerprint_value := production_control
    .annual_odds_pairing_fingerprint_v1(catalog.tournament_id);
  current_value := config.id is not null
    and config.validation_status = 'VALID'
    and config.source_workbook_id = resource.source_workbook_id
    and config.settings_contract_version = 'prediction-settings-v1'
    and config.pairing_fingerprint = pairing_fingerprint_value
    and coalesce((config.validation_diagnostics->>
      'annualSetupRevision')::bigint, -1) = catalog.setup_revision;
  blockers := coalesce(base->'blockers', '[]'::jsonb);
  if not current_value then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'FUTURE_ANNUAL_ODDS_INPUTS_NOT_CURRENT',
        'section', 'Odds',
        'message', 'Synchronize Prediction Settings after the current tournament setup is complete.'
      )
    );
  end if;
  counts := coalesce(base->'counts', '{}'::jsonb) ||
    pg_catalog.jsonb_build_object(
      'annualOddsInputsCurrent', case when current_value then 1 else 0 end,
      'annualOddsInputConfigurationRevision',
        coalesce(config.configuration_revision, 0)
    );
  base := base || pg_catalog.jsonb_build_object(
    'ready', pg_catalog.jsonb_array_length(blockers) = 0,
    'blockerCount', pg_catalog.jsonb_array_length(blockers),
    'blockers', blockers,
    'counts', counts
  );
  return base || pg_catalog.jsonb_build_object(
    'fingerprint', production_control.future_runtime_hash_v2(
      base - 'fingerprint'
    )
  );
end;
$$;


ALTER FUNCTION production_control.future_runtime_readiness_v2(target_tournament text) OWNER TO postgres;

--
-- Name: future_year_hash_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_year_hash_v1(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
  select pg_catalog.encode(extensions.digest(value::text, 'sha256'), 'hex')
$$;


ALTER FUNCTION production_control.future_year_hash_v1(value jsonb) OWNER TO postgres;

--
-- Name: future_year_readiness_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.future_year_readiness_v1(target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  value production_control.future_tournament_catalog_v1%rowtype;
  blockers jsonb := '[]'::jsonb;
  team_count integer := 0;
  captain_count integer := 0;
  roster_count integer := 0;
  unassigned_count integer := 0;
  round_count integer := 0;
  course_count integer := 0;
  match_count integer := 0;
  compatibility_pending integer := 0;
  runtime_match_count integer := 0;
  runtime_snapshot_count integer := 0;
  match_format_mismatch_count integer := 0;
  structure_complete boolean;
  fingerprint_value text;
begin
  select candidate.* into value
  from production_control.future_tournament_catalog_v1 candidate
  where candidate.tournament_id = target_tournament;
  if value.tournament_id is null then
    return pg_catalog.jsonb_build_object(
      'readyForActivation', false,
      'setupStructureComplete', false,
      'fingerprint', null,
      'blockers', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'code', 'FUTURE_TOURNAMENT_NOT_FOUND',
        'section', 'Tournament',
        'message', 'The selected future tournament does not exist.'
      )),
      'counts', '{}'::jsonb
    );
  end if;

  select pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter (where exists (
      select 1
      from production_control.future_tournament_roster_v1 captain
      where captain.tournament_id = team.tournament_id
        and captain.player_id = team.captain_player_id
        and captain.team_id = team.team_id
        and captain.team_side = team.team_side
        and captain.participation_status = 'ACTIVE'
    ))::integer
  into team_count, captain_count
  from production_control.future_tournament_teams_v1 team
  where team.tournament_id = target_tournament and team.active;
  select pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter (
      where roster.team_id is null or roster.team_side is null
    )::integer
  into roster_count, unassigned_count
  from production_control.future_tournament_roster_v1 roster
  where roster.tournament_id = target_tournament
    and roster.participation_status = 'ACTIVE';
  select pg_catalog.count(*)::integer into round_count
  from production_control.future_tournament_rounds_v1 round_value
  where round_value.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into course_count
  from production_control.future_tournament_course_references_v1 course_value
  where course_value.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into match_count
  from production_control.future_match_definitions_v1 match_value
  where match_value.tournament_id = target_tournament;
  compatibility_pending := 0; -- External compatibility is not required.
  select pg_catalog.count(*)::integer into runtime_match_count
  from scoring_authority.matches match_value
  where match_value.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into runtime_snapshot_count
  from scoring_authority.scoring_snapshots snapshot
  where snapshot.tournament_id = target_tournament;
  select pg_catalog.count(*)::integer into match_format_mismatch_count
  from production_control.future_match_definitions_v1 match_value
  join production_control.future_tournament_rounds_v1 round_value
    on round_value.tournament_id = match_value.tournament_id
   and round_value.round_number = match_value.round_number
  where match_value.tournament_id = target_tournament
    and (match_value.format is distinct from round_value.format
      or match_value.team_size is distinct from round_value.team_size);

  if value.lifecycle = 'ACTIVE' then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'TOURNAMENT_ALREADY_ACTIVE', 'section', 'Lifecycle',
        'message', 'This tournament is already the current tournament.'
      )
    );
  end if;
  if value.destination is null or value.start_date is null
     or value.end_date is null or value.timezone is null then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'TOURNAMENT_METADATA_INCOMPLETE', 'section', 'Tournament',
        'message', 'Tournament dates, destination, and timezone are required.'
      )
    );
  end if;
  if not exists (
    select 1 from production_control.future_tournament_resources_v1 resource
    where resource.tournament_id = target_tournament
      and resource.resource_status = 'CURRENT_RESOURCE_BOUND'
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ANNUAL_RESOURCE_REQUIRED', 'section', 'System',
        'message', 'The future tournament needs a certified annual resource binding.'
      )
    );
  end if;
  if team_count <> 2 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'TEAMS_INCOMPLETE', 'section', 'Teams',
        'message', 'Exactly two active tournament teams are required.'
      )
    );
  elsif captain_count <> team_count then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'TEAM_CAPTAINS_INCOMPLETE', 'section', 'Teams',
        'message', 'Every active team needs an eligible captain.'
      )
    );
  end if;
  if roster_count = 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROSTER_EMPTY', 'section', 'Roster',
        'message', 'Select the future tournament roster.'
      )
    );
  elsif unassigned_count > 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROSTER_TEAM_ASSIGNMENTS_INCOMPLETE', 'section', 'Roster',
        'message', unassigned_count::text ||
          ' active roster members still need a team.'
      )
    );
  end if;
  if round_count = 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUNDS_INCOMPLETE', 'section', 'Rounds',
        'message', 'Configure the tournament rounds and formats.'
      )
    );
  elsif course_count <> round_count then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_COURSES_INCOMPLETE', 'section', 'Courses',
        'message', 'Every configured round needs an existing course reference.'
      )
    );
  end if;
  if round_count > 0 and match_count = 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'MATCH_STRUCTURE_INCOMPLETE', 'section', 'Matches',
        'message', 'Generate the empty structural match definitions.'
      )
    );
  end if;
  if match_format_mismatch_count > 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'MATCH_STRUCTURE_ROUND_FORMAT_MISMATCH',
        'section', 'Matches',
        'message', 'A generated match definition no longer matches its round format.'
      )
    );
  end if;

  if runtime_match_count > 0 or runtime_snapshot_count > 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'FUTURE_RUNTIME_FACTS_UNEXPECTED', 'section', 'Scoring',
        'message', 'A Draft tournament cannot contain live scoring facts.'
      )
    );
  end if;
  if value.lifecycle <> 'ACTIVE' then
    -- These are deliberately unresolved by this safe subset. They prevent a
    -- staging container from being mistaken for an activation-ready runtime.
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'FUTURE_HANDICAP_REVISION_REQUIRED', 'section', 'Handicaps',
        'message', 'An approved future-year handicap revision is required.'
      ),
      pg_catalog.jsonb_build_object(
        'code', 'FUTURE_PAIRINGS_AND_SCORING_PREPARATION_REQUIRED',
        'section', 'Scoring',
        'message', 'Pairings and current scoring snapshots must be prepared.'
      ),
      pg_catalog.jsonb_build_object(
        'code', 'FUTURE_TOURNAMENT_ACTIVATION_NOT_INSTALLED',
        'section', 'Activation',
        'message', 'Future tournament activation remains unavailable.'
      )
    );
  end if;

  structure_complete := value.lifecycle <> 'ACTIVE'
    and value.destination is not null and value.start_date is not null
    and value.end_date is not null and value.timezone is not null
    and team_count = 2 and captain_count = team_count
    and roster_count > 0 and unassigned_count = 0
    and round_count > 0 and course_count = round_count
    and match_count > 0 and match_format_mismatch_count = 0;
  fingerprint_value := production_control.future_year_hash_v1(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-future-year-readiness-v1',
      'tournamentId', target_tournament,
      'setupRevision', value.setup_revision,
      'lifecycleRevision', value.lifecycle_revision,
      'teamCount', team_count, 'captainCount', captain_count,
      'rosterCount', roster_count, 'unassignedCount', unassigned_count,
      'roundCount', round_count, 'courseCount', course_count,
      'matchCount', match_count,
      'compatibilityPending', compatibility_pending,
      'runtimeMatchCount', runtime_match_count,
      'runtimeSnapshotCount', runtime_snapshot_count,
      'matchFormatMismatchCount', match_format_mismatch_count,
      'blockers', blockers
    )
  );
  return pg_catalog.jsonb_build_object(
    'readyForActivation', pg_catalog.jsonb_array_length(blockers) = 0,
    'setupStructureComplete', structure_complete,
    'fingerprint', fingerprint_value,
    'blockers', blockers,
    'counts', pg_catalog.jsonb_build_object(
      'teams', team_count, 'captains', captain_count,
      'roster', roster_count, 'unassignedRoster', unassigned_count,
      'rounds', round_count, 'courseAssignments', course_count,
      'matchDefinitions', match_count,
      'compatibilityPending', compatibility_pending,
      'runtimeMatches', runtime_match_count,
      'runtimeSnapshots', runtime_snapshot_count,
      'matchFormatMismatches', match_format_mismatch_count
    )
  );
end;
$$;


ALTER FUNCTION production_control.future_year_readiness_v1(target_tournament text) OWNER TO postgres;

--
-- Name: google_drive_acl_transition_intent_fingerprint_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.google_drive_acl_transition_intent_fingerprint_v1(input jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select pg_catalog.encode(extensions.digest(pg_catalog.array_to_string(array[
    'production-google-drive-acl-transition-intent-v1',
    input->>'schemaVersion', input->>'workbookId', input->>'fenceId',
    input->>'installRequestId', input->>'transitionPhase',
    input->>'providerMutationClass', input->>'sourceRole', input->>'targetRole',
    input->>'permissionManagementScope', input->>'legacyPermissionFingerprint',
    input->>'legacyPrincipalFingerprint', input->>'dedicatedPermissionFingerprint',
    input->>'dedicatedPrincipalFingerprint',
    input->>'dedicatedDriveIdentityFingerprint',
    input->>'priorPermissionInventoryFingerprint',
    input->>'expectedTargetPermissionInventoryFingerprint',
    input->>'permissionIdentityFingerprint', input->>'sharingCapabilityFingerprint',
    input->>'priorAclFingerprint', input->>'priorLegacyCanEdit',
    input->>'priorLegacyCanShare', input->>'expectedTargetLegacyCanEdit',
    input->>'expectedTargetLegacyCanShare',
    input->>'priorLegacyEditCapabilityFingerprint',
    input->>'expectedTargetLegacyEditCapabilityFingerprint',
    input->>'legacyDriveIdentityFingerprint', input->>'permissionCount',
    input->>'priorNonOwnerEditorCount', input->>'expectedTargetNonOwnerEditorCount',
    input->>'priorEffectiveNonOwnerEditorFingerprint',
    input->>'expectedTargetEffectiveNonOwnerEditorFingerprint'
  ], E'\n', '<NULL>'), 'sha256'), 'hex')
$$;


ALTER FUNCTION production_control.google_drive_acl_transition_intent_fingerprint_v1(input jsonb) OWNER TO postgres;

--
-- Name: google_drive_acl_transition_proof_fingerprint_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.google_drive_acl_transition_proof_fingerprint_v1(input jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select pg_catalog.encode(extensions.digest(pg_catalog.array_to_string(array[
    'production-google-drive-acl-transition-proof-v1',
    input->>'schemaVersion', input->>'workbookId', input->>'fenceId',
    input->>'installRequestId', input->>'transitionPhase',
    input->>'providerMutationClass', input->>'permissionManagementScope',
    input->>'transitionIntentFingerprint', input->>'legacyPermissionFingerprint',
    input->>'legacyPrincipalFingerprint', input->>'priorRole', input->>'currentRole',
    input->>'priorPermissionInventoryFingerprint',
    input->>'currentPermissionInventoryFingerprint',
    input->>'permissionIdentityFingerprint', input->>'sharingCapabilityFingerprint',
    input->>'dedicatedDriveIdentityFingerprint',
    input->>'legacyDriveIdentityFingerprint', input->>'priorAclFingerprint',
