--
-- Name: google_writer_fence_rehearsals; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.google_writer_fence_rehearsals (
    run_id uuid NOT NULL,
    rehearsal_request_id uuid NOT NULL,
    begin_request_fingerprint text NOT NULL,
    begin_payload_hash text NOT NULL,
    status text DEFAULT 'RUNNING'::text NOT NULL,
    quiesce_evidence_id uuid NOT NULL,
    candidate_deployment_id text NOT NULL,
    candidate_deployment_commit text NOT NULL,
    vercel_project_id text NOT NULL,
    project_ref text NOT NULL,
    source_workbook_id text NOT NULL,
    tournament_id text NOT NULL,
    dedicated_google_service_account text NOT NULL,
    activation_revision bigint NOT NULL,
    authority_generation_id uuid NOT NULL,
    admission_generation_id uuid NOT NULL,
    admission_revision bigint NOT NULL,
    baseline_provider_fingerprint text NOT NULL,
    baseline_protected_ranges_fingerprint text NOT NULL,
    baseline_canonical_value_fingerprint text NOT NULL,
    writer_scope_fingerprint text NOT NULL,
    edge_quiesce_fingerprint text NOT NULL,
    origin_matrix_fingerprint text NOT NULL,
    owner_principal_fingerprint text NOT NULL,
    canonical_sheet_union_fingerprint text NOT NULL,
    owner_override_operationally_frozen boolean NOT NULL,
    owner_acknowledged_at timestamp with time zone NOT NULL,
    owner_freeze_expires_at timestamp with time zone NOT NULL,
    protection_description_prefix text NOT NULL,
    finish_request_fingerprint text,
    finish_payload_hash text,
    provider_evidence_fingerprint text,
    fenced_provider_fingerprint text,
    restored_provider_fingerprint text,
    restored_protected_ranges_fingerprint text,
    restored_canonical_value_fingerprint text,
    restoration_evidence_fingerprint text,
    run_owned_protection_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    active_run_owned_protection_count integer,
    dedicated_identity_can_edit boolean,
    legacy_identity_denied boolean,
    google_value_writes_performed boolean,
    preview_resources_accessed boolean,
    restoration_confirmed boolean DEFAULT false NOT NULL,
    certification_passed boolean,
    failure_code text,
    actor_id text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT google_writer_fence_rehearsa_active_run_owned_protection__check CHECK (((active_run_owned_protection_count IS NULL) OR (active_run_owned_protection_count >= 0))),
    CONSTRAINT google_writer_fence_rehearsa_baseline_canonical_value_fin_check CHECK ((baseline_canonical_value_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_fence_rehearsa_baseline_protected_ranges_fi_check CHECK ((baseline_protected_ranges_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_fence_rehearsa_baseline_provider_fingerprin_check CHECK ((baseline_provider_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_fence_rehearsa_canonical_sheet_union_finger_check CHECK ((canonical_sheet_union_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_fence_rehearsa_dedicated_google_service_acc_check CHECK ((dedicated_google_service_account = 'sbi-production-workbook@sandbagger-invitational.iam.gserviceaccount.com'::text)),
    CONSTRAINT google_writer_fence_rehearsa_owner_override_operationally_check CHECK (owner_override_operationally_frozen),
    CONSTRAINT google_writer_fence_rehearsa_protection_description_prefi_check CHECK ((protection_description_prefix ~ '^STEP11_6_WRITER_FENCE_REHEARSAL:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT google_writer_fence_rehearsa_provider_evidence_fingerprin_check CHECK (((provider_evidence_fingerprint IS NULL) OR (provider_evidence_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT google_writer_fence_rehearsa_restoration_evidence_fingerp_check CHECK (((restoration_evidence_fingerprint IS NULL) OR (restoration_evidence_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT google_writer_fence_rehearsa_restored_canonical_value_fin_check CHECK (((restored_canonical_value_fingerprint IS NULL) OR (restored_canonical_value_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT google_writer_fence_rehearsa_restored_protected_ranges_fi_check CHECK (((restored_protected_ranges_fingerprint IS NULL) OR (restored_protected_ranges_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT google_writer_fence_rehearsa_restored_provider_fingerprin_check CHECK (((restored_provider_fingerprint IS NULL) OR (restored_provider_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT google_writer_fence_rehearsal_candidate_deployment_commit_check CHECK ((candidate_deployment_commit ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT google_writer_fence_rehearsal_fenced_provider_fingerprint_check CHECK (((fenced_provider_fingerprint IS NULL) OR (fenced_provider_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT google_writer_fence_rehearsal_owner_principal_fingerprint_check CHECK ((owner_principal_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_fence_rehearsals_activation_revision_check CHECK ((activation_revision >= 0)),
    CONSTRAINT google_writer_fence_rehearsals_actor_id_check CHECK (((btrim(actor_id) <> ''::text) AND (length(actor_id) <= 160))),
