--
-- Name: guard_canonical_annual_receipt_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_canonical_annual_receipt_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;m production_control.canonical_operation_context_v1%rowtype;
begin
 select * into strict r from production_control.canonical_resource_v1 where singleton;
 if r.database_name<>current_database()then raise exception using errcode='42501',message='CANONICAL_RESOURCE_BINDING_DENIED';end if;
 if r.resource_class='PRODUCTION'then
  if new.certification_resource_id is not null then raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CROSS_CLASS_DENIED';end if;
  return new;
 end if;
 -- A completed activation intentionally changed current context. The private
 -- wrapper's still-held marker is exact PID/xid provenance, not re-admission.
 select * into strict m from production_control.canonical_operation_context_v1
 where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 if not m.mutation or m.phase<>'ANNUAL' or m.context->>'resource_id' is distinct from r.resource_id
  or m.context->>'installation_id' is distinct from r.installation_id::text
  or new.certification_resource_id is distinct from r.resource_id
  or new.operation_request_id::text is distinct from m.context->>'operation_request_id'
  or new.certification_actor_player_id is distinct from m.context#>>'{authorization,player_id}'
  or new.certification_actor_auth_user_id::text is distinct from m.context#>>'{authorization,auth_user_id}'then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_RECEIPT_ORIGIN_REQUIRED';end if;
 return new;
exception when no_data_found then raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_RECEIPT_ORIGIN_REQUIRED';
end;$$;


ALTER FUNCTION production_control.guard_canonical_annual_receipt_v1() OWNER TO postgres;

--
-- Name: guard_canonical_annual_row_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_canonical_annual_row_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare physical production_control.canonical_resource_v1%rowtype;
 origin production_control.certification_initialization_origins_v1%rowtype;
 prior production_control.scoring_admission_closures%rowtype;
 gen production_control.certification_ingress_generations_v1%rowtype;
 row_value jsonb:=to_jsonb(new);old_value jsonb;
begin
 select * into strict physical from production_control.canonical_resource_v1 where singleton;
 if physical.database_name<>current_database()then
  raise exception using errcode='42501',message='CANONICAL_RESOURCE_BINDING_DENIED';end if;
 if tg_op='UPDATE'then
  old_value:=to_jsonb(old);
  if row_value->>'resource_class' is distinct from old_value->>'resource_class'
   or row_value->>'certification_resource_id' is distinct from old_value->>'certification_resource_id'then
   raise exception using errcode='55000',message='CERTIFICATION_ANNUAL_PROVENANCE_IMMUTABLE';end if;
 end if;
 if physical.resource_class='PRODUCTION' then
  if row_value->>'resource_class' is distinct from 'PRODUCTION' or row_value->>'certification_resource_id' is not null then
   raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CROSS_CLASS_DENIED';end if;
  return new;
 end if;
 if row_value->>'resource_class' is distinct from 'CERTIFICATION'
  or row_value->>'certification_resource_id' is distinct from physical.resource_id then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_CROSS_CLASS_DENIED';end if;
 select * into strict origin from production_control.certification_initialization_origins_v1 where resource_id=physical.resource_id;
 if origin.installation_id<>physical.installation_id or origin.database_name<>physical.database_name then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_ORIGIN_REQUIRED';end if;
 if tg_table_name='scoring_admission_closures' then
  if tg_op='UPDATE' and
   (row_value->'closure_id' is distinct from old_value->'closure_id'
    or row_value->'admission_generation_id' is distinct from old_value->'admission_generation_id'
    or row_value->'authority_generation_id' is distinct from old_value->'authority_generation_id'
    or row_value->'tournament_id' is distinct from old_value->'tournament_id'
    or row_value->'prior_certification_closure_id' is distinct from old_value->'prior_certification_closure_id')then
   raise exception using errcode='55000',message='CERTIFICATION_ANNUAL_PROVENANCE_IMMUTABLE';end if;
  select * into strict gen from production_control.certification_ingress_generations_v1
   where resource_id=physical.resource_id and generation_id=new.admission_generation_id;
  if gen.authority_epoch_id<>new.authority_generation_id or gen.tournament_id<>new.tournament_id
   or gen.state not in('CLOSING','CLOSED') or gen.high_watermark is distinct from new.lease_high_watermark then
   raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_LINEAGE_REQUIRED';end if;
  if new.prior_certification_closure_id is not null then
   select * into strict prior from production_control.scoring_admission_closures where closure_id=new.prior_certification_closure_id;
   if prior.resource_class<>'CERTIFICATION' or prior.certification_resource_id<>physical.resource_id
    or prior.status not in('CLOSED','CONSUMED','REOPENED')
    or gen.predecessor_generation_id is distinct from prior.admission_generation_id then
    raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_LINEAGE_REQUIRED';end if;
  elsif new.tournament_id<>origin.initial_tournament_id or gen.predecessor_generation_id is not null then
   raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_LINEAGE_REQUIRED';end if;
 elsif tg_table_name='annual_scoring_runtime_authorities_v1' then
  select * into strict prior from production_control.scoring_admission_closures where closure_id=new.predecessor_closure_id;
  if prior.resource_class<>'CERTIFICATION' or prior.certification_resource_id<>physical.resource_id
   or prior.status not in('CLOSED','CONSUMED') or prior.tournament_id<>new.predecessor_tournament_id
   or new.platform_authority_generation_id<>origin.authority_epoch_id
   or new.platform_admission_generation_id<>origin.admission_generation_id then
   raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_LINEAGE_REQUIRED';end if;
 elsif tg_table_name='annual_scoring_transitions_v1' and new.predecessor_closure_id is not null then
  select * into strict prior from production_control.scoring_admission_closures where closure_id=new.predecessor_closure_id;
  if prior.resource_class<>'CERTIFICATION' or prior.certification_resource_id<>physical.resource_id
   or prior.tournament_id<>new.predecessor_tournament_id then
   raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_LINEAGE_REQUIRED';end if;
 end if;
 return new;
exception when no_data_found then raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_LINEAGE_REQUIRED';
end;$$;


ALTER FUNCTION production_control.guard_canonical_annual_row_v1() OWNER TO postgres;

--
-- Name: guard_canonical_resource_identity_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_canonical_resource_identity_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op='DELETE' then
    raise exception using errcode='55000',message='CANONICAL_RESOURCE_IDENTITY_IMMUTABLE';
  end if;
  if (to_jsonb(new)-array['registration_revision','manifest_digest','schema_contract','schema_digest'])
      is distinct from (to_jsonb(old)-array['registration_revision','manifest_digest','schema_contract','schema_digest']) then
    raise exception using errcode='55000',message='CANONICAL_RESOURCE_IDENTITY_IMMUTABLE';
  end if;
  if new.registration_revision<>old.registration_revision+1
    or exists(select 1 from production_control.certification_admission_v1 where resource_id=old.resource_id and enabled) then
    raise exception using errcode='40001',message='CANONICAL_RESOURCE_REVISION_REQUIRES_CLOSED_ADMISSION';
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.guard_canonical_resource_identity_v1() OWNER TO postgres;

--
-- Name: guard_certification_annual_epoch_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_certification_annual_epoch_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare m production_control.canonical_operation_context_v1%rowtype;
begin
 if new.epoch_type<>'CERTIFICATION_ANNUAL_TRANSITION' then return new;end if;
 select * into strict m from production_control.canonical_operation_context_v1
  where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 perform production_control.assert_certification_annual_cached_context_v1(m.context);
 if new.status<>'COMMITTED' or new.authority_before<>'SUPABASE' or new.authority_after<>'SUPABASE'
  or new.google_checkpoints<>'{}'::jsonb
  or not exists(select 1 from production_control.annual_scoring_transitions_v1 t
   join production_control.future_annual_runtime_generations_v1 g on g.runtime_generation_id=t.runtime_generation_id
   where t.resource_class='CERTIFICATION' and t.certification_resource_id=m.context->>'resource_id'
    and t.transition_status='COMMITTED' and t.predecessor_tournament_id=m.context->>'current_tournament_id'
    and t.authority_generation_id=new.epoch_id and t.successor_tournament_id=new.tournament_id
    and g.generation_status='ACTIVE' and g.authority_generation_id=new.epoch_id
    and new.actor_id=m.context#>>'{authorization,player_id}'
    and new.deployment_commit=m.context->>'release_commit') then
  raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_EPOCH_REQUIRED';end if;
 return new;
exception when no_data_found then raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_EPOCH_REQUIRED';
end;$$;


ALTER FUNCTION production_control.guard_certification_annual_epoch_v1() OWNER TO postgres;

--
-- Name: guard_certification_epoch_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_certification_epoch_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if new.epoch_type='CERTIFICATION_INITIALIZATION' and (
   new.authority_before<>'SUPABASE' or new.authority_after<>'SUPABASE'
   or new.google_checkpoints<>'{}'::jsonb
   or not exists(select 1 from production_control.canonical_resource_v1 r
     where r.resource_class='CERTIFICATION' and r.database_name=current_database())
   or exists(select 1 from production_control.resource_scope)
   or exists(select 1 from production_control.cutover_activation_state)) then
  raise exception using errcode='42501',message='CERTIFICATION_EPOCH_RESOURCE_REQUIRED';
 end if;
 return new;
end;
$$;


ALTER FUNCTION production_control.guard_certification_epoch_v1() OWNER TO postgres;

--
-- Name: guard_certification_future_resource_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_certification_future_resource_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;
begin
 select * into r from production_control.canonical_resource_v1 where singleton;
 if r.resource_class='CERTIFICATION' and (new.project_ref is distinct from r.project_ref
  or new.project_url is distinct from r.project_url
  or new.source_workbook_id is distinct from r.provenance_id
  or new.google_compatibility_policy<>'RETIRED') then
  raise exception using errcode='42501',message='CERTIFICATION_FUTURE_RESOURCE_DENIED';
 end if;
 return new;
end;
$$;


ALTER FUNCTION production_control.guard_certification_future_resource_v1() OWNER TO postgres;

--
-- Name: guard_certification_gate_boundary_mode_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_certification_gate_boundary_mode_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;e scoring_authority.authority_epochs%rowtype;
begin
 select * into r from production_control.canonical_resource_v1 where singleton;
 if r.resource_class is distinct from 'CERTIFICATION' then
  if new.boundary_mode='CERTIFICATION_INGRESS_V1' then
   raise exception using errcode='42501',message='CERTIFICATION_GATE_RESOURCE_REQUIRED';end if;
  return new;
 end if;
 select * into e from scoring_authority.authority_epochs where epoch_id=new.active_epoch_id;
 if r.database_name is distinct from current_database()
  or new.boundary_mode is distinct from 'CERTIFICATION_INGRESS_V1'
  or new.authority is distinct from 'SUPABASE'
  or e.tournament_id is distinct from new.tournament_id
  or e.boundary_mode is distinct from 'CERTIFICATION_INGRESS_V1'
  or e.epoch_type is null or e.epoch_type not in('CERTIFICATION_INITIALIZATION','CERTIFICATION_ANNUAL_TRANSITION')
  or exists(select 1 from production_control.resource_scope)
  or exists(select 1 from production_control.cutover_activation_state) then
  raise exception using errcode='42501',message='CERTIFICATION_GATE_RESOURCE_REQUIRED';end if;
 return new;
end;$$;


ALTER FUNCTION production_control.guard_certification_gate_boundary_mode_v1() OWNER TO postgres;

--
-- Name: guard_certification_ingress_generation_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_certification_ingress_generation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if tg_op='DELETE'or(to_jsonb(new)-array['state','revision','high_watermark','closing_revision','lease_fingerprint','closed_at'])
  is distinct from(to_jsonb(old)-array['state','revision','high_watermark','closing_revision','lease_fingerprint','closed_at'])
  or(old.state='CLOSED'and to_jsonb(new)is distinct from to_jsonb(old))
  or(old.state='CLOSING'and(new.state not in('CLOSING','CLOSED')or new.high_watermark is distinct from old.high_watermark
   or new.closing_revision is distinct from old.closing_revision or new.revision<>old.revision))
  or(old.state='OPEN'and(new.state<>'CLOSING'or new.revision<>old.revision+1 or new.closing_revision<>new.revision))then
  raise exception using errcode='55000',message='CERTIFICATION_INGRESS_GENERATION_IMMUTABLE';end if;
 return new;
end;$$;


ALTER FUNCTION production_control.guard_certification_ingress_generation_v1() OWNER TO postgres;

--
-- Name: guard_certification_ingress_lease_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_certification_ingress_lease_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if tg_op='DELETE' then raise exception using errcode='55000',message='CERTIFICATION_INGRESS_HISTORY_IMMUTABLE';end if;
 if tg_op='UPDATE' and ((to_jsonb(new)-array['state','result','committed_generation_revision','resolved_at'])
  is distinct from (to_jsonb(old)-array['state','result','committed_generation_revision','resolved_at'])
  or(old.state in('COMMITTED','NOT_COMMITTED')and to_jsonb(new)is distinct from to_jsonb(old))
  or(old.state='UNKNOWN'and new.state='ADMITTED'))then
  raise exception using errcode='55000',message='CERTIFICATION_INGRESS_OUTCOME_IMMUTABLE';end if;
 return new;
end;$$;


ALTER FUNCTION production_control.guard_certification_ingress_lease_v1() OWNER TO postgres;

--
-- Name: guard_certification_initialization_evidence_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_certification_initialization_evidence_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 -- Existing Production installation-ledger behavior is unchanged. Once a
 -- Certification origin references a receipt, that exact evidence is immutable.
 if tg_table_name='canonical_bootstrap_installation_v1' then
  if not exists(select 1 from production_control.certification_initialization_origins_v1 o
   where o.installation_contract=old.contract_version) then
   return case when tg_op='DELETE' then old else new end;
  end if;
 end if;
 raise exception using errcode='55000',message='CERTIFICATION_INITIALIZATION_EVIDENCE_IMMUTABLE';
end;$$;


ALTER FUNCTION production_control.guard_certification_initialization_evidence_v1() OWNER TO postgres;

--
-- Name: guard_certification_odds_job_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_certification_odds_job_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c jsonb;r production_control.canonical_resource_v1%rowtype;
begin
 select * into r from production_control.canonical_resource_v1 where singleton;
 if new.production_operation_mode='CERTIFICATION' or r.resource_class='CERTIFICATION'then
  c:=production_control.current_certification_context_v1();
  if new.production_operation_mode<>'CERTIFICATION'or r.resource_class<>'CERTIFICATION'or r.database_name<>current_database()
   or new.tournament_id is distinct from c->>'tournament_id'or new.source_revision->>'resource_id'is distinct from r.resource_id
   or new.source_revision->>'installation_id'is distinct from r.installation_id::text then
   raise exception using errcode='42501',message='CERTIFICATION_ODDS_JOB_RESOURCE_DENIED';end if;
  if tg_op='UPDATE'and (new.source_revision is distinct from old.source_revision or new.runtime_generation_id is distinct from old.runtime_generation_id
   or new.input_snapshot is distinct from old.input_snapshot or new.invocation_fingerprint is distinct from old.invocation_fingerprint
   or(old.status='SUCCEEDED'and(new.result_payload is distinct from old.result_payload or new.result_fingerprint is distinct from old.result_fingerprint)))then
   raise exception using errcode='55000',message='CERTIFICATION_ODDS_JOB_PROVENANCE_IMMUTABLE';end if;
  if tg_op='INSERT'and new.tournament_id<>'2026'then
   select runtime_generation_id into strict new.runtime_generation_id from production_control.future_annual_runtime_generations_v1
    where tournament_id=new.tournament_id and generation_status='ACTIVE'and authority_generation_id::text=c->>'authority_epoch_id';
  end if;
 end if;return new;
end;$$;


ALTER FUNCTION production_control.guard_certification_odds_job_v1() OWNER TO postgres;

--
-- Name: guard_future_unprepared_match_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_future_unprepared_match_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  catalog production_control.future_tournament_catalog_v1%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
begin
  if new.scoring_snapshot_id is not null then
    return new;
  end if;
  select value.* into catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = new.tournament_id;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = production_control.canonical_execution_resource_id_v1();
  if catalog.tournament_id is null
     or catalog.lifecycle not in (
       'DRAFT', 'CONFIGURING', 'READY_FOR_ACTIVATION'
     )
     or pointer.tournament_id = new.tournament_id
     or new.status <> 'UPCOMING'
     or not new.scoring_locked
     or new.match_revision <> 0
     or new.scored_holes <> 0
     or new.current_hole <> 0
     or new.holes_remaining <> 18
     or new.unresolved_mutations <> 0
     or new.scorecard_complete
     or new.finalized_at is not null
     or exists (select 1 from scoring_authority.hole_scores value
       where value.match_id = new.match_id)
     or exists (select 1 from scoring_authority.score_mutations value
       where value.match_id = new.match_id)
     or exists (select 1 from scoring_authority.scoring_permissions value
       where value.match_id = new.match_id and value.can_score)
     or exists (select 1 from scoring_authority.scoring_ingress_leases value
       where value.match_id = new.match_id
         and value.expires_at > pg_catalog.clock_timestamp()) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_UNPREPARED_MATCH_NOT_ALLOWED';
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.guard_future_unprepared_match_v1() OWNER TO postgres;

--
-- Name: guard_odds_snapshot_immutability(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_odds_snapshot_immutability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  authority_value text;
begin
  declare
    registered production_control.canonical_resource_v1%rowtype;
    context jsonb;
  begin
    select * into registered from production_control.canonical_resource_v1 where singleton;
    if registered.resource_class='CERTIFICATION'
      or old.resource_binding->>'resource_class'='CERTIFICATION' then
      -- This getter revalidates the private transaction marker and its original
      -- admitted request. A client JSON object or GUC is not an authority source.
      context:=production_control.current_certification_context_v1();
      if registered.resource_class is distinct from 'CERTIFICATION'
        or registered.database_name is distinct from current_database()
        or context->>'resource_class' is distinct from 'CERTIFICATION'
        or context->>'resource_id' is distinct from registered.resource_id
        or context->>'installation_id' is distinct from registered.installation_id::text
        or context->>'project_ref' is distinct from registered.project_ref
        or context->>'phase' is distinct from 'DIRECTOR'
        or context->>'tournament_id' is distinct from old.tournament_id
        or nullif(context->>'operation_request_id','') is null
        or old.publication_authority is distinct from 'SUPABASE'
        or old.resource_binding->>'contract_version' is distinct from 'certification-odds-publication-v1'
        or old.resource_binding->>'resource_class' is distinct from 'CERTIFICATION'
        or old.resource_binding->>'resource_id' is distinct from registered.resource_id
        or old.resource_binding->>'installation_id' is distinct from registered.installation_id::text
        or old.resource_binding->>'project_ref' is distinct from registered.project_ref
        or old.resource_binding->>'tournament_id' is distinct from old.tournament_id
        or old.resource_binding_fingerprint is distinct from
          production_control.odds_publication_v1_hash(old.resource_binding) then
        raise exception using errcode='42501',message='CERTIFICATION_ODDS_SNAPSHOT_RESOURCE_DENIED';
      end if;
      perform production_control.assert_certification_odds_actor_v1(
        jsonb_build_object('authorization',context->'authorization'),context);
      authority_value:='SUPABASE';
    else
      select odds_publication_authority into strict authority_value
      from production_control.resource_scope
      where scope_key = 'BAGGER_INV_PRODUCTION';
    end if;
  end;

  if new.id is distinct from old.id
     or new.tournament_id is distinct from old.tournament_id
     or new.milestone is distinct from old.milestone
     or new.phase_order is distinct from old.phase_order
     or new.publication_revision is distinct from old.publication_revision
     or new.published_at is distinct from old.published_at
     or new.published_payload is distinct from old.published_payload
     or new.payload_hash is distinct from old.payload_hash
     or new.source_fingerprint is distinct from old.source_fingerprint
     or new.engine_version is distinct from old.engine_version
     or new.engine_metadata is distinct from old.engine_metadata
     or new.created_at is distinct from old.created_at
     or new.logical_payload_hash is distinct from old.logical_payload_hash
     or new.settings_fingerprint is distinct from old.settings_fingerprint
     or new.ratings_fingerprint is distinct from old.ratings_fingerprint
     or new.pairing_fingerprint is distinct from old.pairing_fingerprint
     or new.deterministic_seed is distinct from old.deterministic_seed
     or new.publication_actor_id is distinct from old.publication_actor_id
     or new.authority_contract_version is distinct from old.authority_contract_version
     or new.publication_authority is distinct from old.publication_authority
     or new.publication_state_revision is distinct from old.publication_state_revision
     or new.source_calculation_job_id is distinct from old.source_calculation_job_id
     or new.source_calculation_revision is distinct from old.source_calculation_revision
     or new.published_by_auth_user_id is distinct from old.published_by_auth_user_id
     or new.published_by_player_id is distinct from old.published_by_player_id
     or new.authority_epoch_id is distinct from old.authority_epoch_id
     or new.resource_binding is distinct from old.resource_binding
     or new.resource_binding_fingerprint is distinct from old.resource_binding_fingerprint
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ODDS_PUBLISHED_SNAPSHOT_IMMUTABLE';
  end if;

  if authority_value = 'SUPABASE' and (
       new.google_publication_fingerprint is distinct from
         old.google_publication_fingerprint
       or new.google_publication_reference is distinct from
         old.google_publication_reference
       or new.publication_verified is distinct from old.publication_verified
       or new.imported_by is distinct from old.imported_by
       or new.imported_at is distinct from old.imported_at
       or new.mirror_status is distinct from old.mirror_status
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ODDS_GOOGLE_PUBLICATION_RETIRED';
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.guard_odds_snapshot_immutability() OWNER TO postgres;

--
-- Name: guard_production_odds_job_scope(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_production_odds_job_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
begin
  if new.production_operation_mode is distinct from old.production_operation_mode
     or new.production_deployment_commit is distinct from old.production_deployment_commit
     or new.production_candidate_hostname is distinct from old.production_candidate_hostname
     or new.source_revision->>'production_job_identity_contract'
          is distinct from old.source_revision->>'production_job_identity_contract'
     or new.source_revision->>'rehearsal_fixture_contract'
          is distinct from old.source_revision->>'rehearsal_fixture_contract'
     or new.source_revision->>'rehearsal_fixture_fingerprint'
          is distinct from old.source_revision->>'rehearsal_fixture_fingerprint'
     or new.source_revision->>'rehearsal_namespace'
          is distinct from old.source_revision->>'rehearsal_namespace' then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_ODDS_JOB_SCOPE_IMMUTABLE';
  end if;
  if old.production_operation_mode = 'STEP11_REHEARSAL'
     and new.publication_status in ('READY', 'PUBLISHED') then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_ODDS_REHEARSAL_PUBLICATION_FORBIDDEN';
  end if;
  return new;
end;
$$;


