--
-- Name: guard_scoring_admission_against_provider_fence(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_scoring_admission_against_provider_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  admission_attempt boolean;
begin
  admission_attempt := new.protocol_version = 'ADMISSION_V2' and (
    tg_op = 'INSERT'
    or (
      tg_op = 'UPDATE'
      and new.resolution_state = 'ADMITTED'
      and (
        new.lease_nonce_hash is distinct from old.lease_nonce_hash
        or new.expires_at is distinct from old.expires_at
      )
    )
  );
  if not admission_attempt then
    return new;
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  if exists (
    select 1
    from production_control.google_writer_provider_fences value
    where value.status in ('INSTALLING', 'ABORTING', 'INSTALLED', 'REMOVAL_AUTHORIZED')
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_PROVIDER_FENCE_ADMISSION_RESERVED';
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.guard_scoring_admission_against_provider_fence() OWNER TO postgres;

--
-- Name: guard_terminal_vercel_provider_attestation(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_terminal_vercel_provider_attestation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if old.status = 'ABANDONED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_ABANDONED_TERMINAL';
  end if;
  if tg_op = 'UPDATE' and old.status = 'BOUND'
     and new.status = 'ABANDONED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BOUND_ABANDON_FORBIDDEN';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.guard_terminal_vercel_provider_attestation() OWNER TO postgres;

--
-- Name: guard_terminal_vercel_provider_challenge(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.guard_terminal_vercel_provider_challenge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if old.status = 'ABANDONED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDONED_TERMINAL';
  end if;
  if tg_op = 'UPDATE'
     and old.status = 'ISSUED'
     and new.status = 'CONSUMED'
     and pg_catalog.clock_timestamp() > old.expires_at then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_EXPIRED';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


