--

CREATE FUNCTION production_control.handicap_v1_json_decimal(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'production_control'
    AS $_$
  select value is not null
    and (
      (pg_catalog.jsonb_typeof(value) = 'number'
        and value::text ~ '^-?(0|[1-9][0-9]*)(\.[0-9]+)?$')
      or
      (pg_catalog.jsonb_typeof(value) = 'string'
        and value#>>'{}' ~ '^-?(0|[1-9][0-9]*)(\.[0-9]+)?$')
    )
$_$;


