--
-- Name: handicap_v1_match_context(text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.handicap_v1_match_context(target_match_id text, target_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  match_value scoring_authority.matches%rowtype;
  snapshot_value scoring_authority.scoring_snapshots%rowtype;
  computed_entries jsonb;
  next_participant_configuration jsonb;
  next_team_configuration jsonb;
  team_1_playing numeric;
  team_2_playing numeric;
  team_1_strokes integer;
  team_2_strokes integer;
begin
  select value.* into strict match_value
  from scoring_authority.matches value
  where value.match_id = target_match_id and value.tournament_id = '2026';
  select value.* into strict snapshot_value
  from scoring_authority.scoring_snapshots value
  where value.snapshot_id = match_value.scoring_snapshot_id
    and value.match_id = match_value.match_id
    and value.tournament_id = match_value.tournament_id;

  with course_values as (
    select participant.match_id, participant.player_id,
      participant.team_side, participant.player_slot,
      entry.tournament_handicap,
      entry.tournament_handicap
        * (snapshot_value.slope::numeric / 113::numeric)
        + (snapshot_value.rating - snapshot_value.par::numeric)
        as course_handicap
    from scoring_authority.match_participants participant
    join scoring_authority.handicap_revision_entries entry
      on entry.revision_id = target_revision_id
     and entry.tournament_id = '2026'
     and entry.player_id = participant.player_id
    where participant.match_id = target_match_id
  ), calculated as (
    select course.*,
      case match_value.format
        when 'SC' then 0::numeric
        else pg_catalog.round(course.course_handicap, 0)
      end as playing_handicap,
      case match_value.format
        when 'BB' then pg_catalog.round(
          (course.course_handicap
            - pg_catalog.min(course.course_handicap) over ()) * 0.9,
          0
        )::integer
        when 'SI' then pg_catalog.round(
          course.course_handicap
            - pg_catalog.min(course.course_handicap) over (),
          0
        )::integer
        else 0::integer
      end as final_strokes
    from course_values course
  )
  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'match_id', calculated.match_id,
      'player_id', calculated.player_id,
      'team_side', calculated.team_side,
      'player_slot', calculated.player_slot,
      'tournament_handicap', calculated.tournament_handicap,
      'handicap_index', calculated.tournament_handicap,
      'course_handicap', calculated.course_handicap,
      'playing_handicap', calculated.playing_handicap,
      'final_strokes', calculated.final_strokes
    ) order by calculated.team_side, calculated.player_slot
  ) into strict computed_entries
  from calculated;

  select pg_catalog.jsonb_build_object(
    'team_1', coalesce(pg_catalog.jsonb_agg(
      coalesce((
        select original.value
        from pg_catalog.jsonb_array_elements(coalesce(
          snapshot_value.participant_configuration->'team_1', '[]'::jsonb
        )) original(value)
        where original.value->>'id' = calculated.value->>'player_id'
        limit 1
      ), '{}'::jsonb) || pg_catalog.jsonb_build_object(
        'id', calculated.value->>'player_id',
        'team', 1,
        'slot', (calculated.value->>'player_slot')::integer,
        'handicap_index', (calculated.value->>'handicap_index')::numeric,
        'course_handicap', (calculated.value->>'course_handicap')::numeric,
        'playing_handicap', (calculated.value->>'playing_handicap')::numeric,
        'final_strokes', (calculated.value->>'final_strokes')::integer,
        'tournament_handicap',
          (calculated.value->>'tournament_handicap')::numeric,
        'handicap_revision_id', target_revision_id
      ) order by (calculated.value->>'player_slot')::integer
    ) filter (where (calculated.value->>'team_side')::integer = 1),
      '[]'::jsonb),
    'team_2', coalesce(pg_catalog.jsonb_agg(
      coalesce((
        select original.value
        from pg_catalog.jsonb_array_elements(coalesce(
          snapshot_value.participant_configuration->'team_2', '[]'::jsonb
        )) original(value)
        where original.value->>'id' = calculated.value->>'player_id'
        limit 1
      ), '{}'::jsonb) || pg_catalog.jsonb_build_object(
        'id', calculated.value->>'player_id',
        'team', 2,
        'slot', (calculated.value->>'player_slot')::integer,
        'handicap_index', (calculated.value->>'handicap_index')::numeric,
        'course_handicap', (calculated.value->>'course_handicap')::numeric,
        'playing_handicap', (calculated.value->>'playing_handicap')::numeric,
        'final_strokes', (calculated.value->>'final_strokes')::integer,
        'tournament_handicap',
          (calculated.value->>'tournament_handicap')::numeric,
        'handicap_revision_id', target_revision_id
      ) order by (calculated.value->>'player_slot')::integer
    ) filter (where (calculated.value->>'team_side')::integer = 2),
      '[]'::jsonb),
    'all_ids', pg_catalog.jsonb_agg(
      calculated.value->>'player_id'
      order by (calculated.value->>'team_side')::integer,
        (calculated.value->>'player_slot')::integer
    ),
    'handicap_revision_id', target_revision_id,
    'handicap_context_contract', 'production-handicap-context-v1'
  ) into next_participant_configuration
  from pg_catalog.jsonb_array_elements(computed_entries) calculated(value);

  if match_value.format = 'SC' then
    select pg_catalog.round(
      pg_catalog.min((value->>'course_handicap')::numeric) * 0.35
        + pg_catalog.max((value->>'course_handicap')::numeric) * 0.15,
      0
    ) into team_1_playing
    from pg_catalog.jsonb_array_elements(computed_entries) calculated(value)
    where (value->>'team_side')::integer = 1;
    select pg_catalog.round(
      pg_catalog.min((value->>'course_handicap')::numeric) * 0.35
        + pg_catalog.max((value->>'course_handicap')::numeric) * 0.15,
      0
    ) into team_2_playing
    from pg_catalog.jsonb_array_elements(computed_entries) calculated(value)
    where (value->>'team_side')::integer = 2;
    team_1_strokes := (team_1_playing
      - least(team_1_playing, team_2_playing))::integer;
    team_2_strokes := (team_2_playing
      - least(team_1_playing, team_2_playing))::integer;
  else
    select pg_catalog.max((value->>'playing_handicap')::numeric),
      pg_catalog.max((value->>'final_strokes')::integer)
      into team_1_playing, team_1_strokes
    from pg_catalog.jsonb_array_elements(computed_entries) calculated(value)
    where (value->>'team_side')::integer = 1;
    select pg_catalog.max((value->>'playing_handicap')::numeric),
      pg_catalog.max((value->>'final_strokes')::integer)
      into team_2_playing, team_2_strokes
    from pg_catalog.jsonb_array_elements(computed_entries) calculated(value)
    where (value->>'team_side')::integer = 2;
  end if;

  next_team_configuration := snapshot_value.team_configuration
    || pg_catalog.jsonb_build_object(
      'team_1_handicap', team_1_playing,
      'team_2_handicap', team_2_playing,
      'team_1_playing_handicap', team_1_playing,
      'team_2_playing_handicap', team_2_playing,
      'team_1_strokes', team_1_strokes,
      'team_2_strokes', team_2_strokes,
      'handicap_revision_id', target_revision_id,
      'handicap_context_contract', 'production-handicap-context-v1'
    );

  return pg_catalog.jsonb_build_object(
    'participants', computed_entries,
    'participant_configuration', next_participant_configuration,
    'team_configuration', next_team_configuration,
    'team_1_playing_handicap', team_1_playing,
    'team_2_playing_handicap', team_2_playing,
    'team_1_strokes', team_1_strokes,
    'team_2_strokes', team_2_strokes
  );
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_HANDICAP_CONTEXT_INCOMPLETE';
end;
$$;


ALTER FUNCTION production_control.handicap_v1_match_context(target_match_id text, target_revision_id uuid) OWNER TO postgres;

--
-- Name: handicap_v1_match_is_unstarted(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.handicap_v1_match_is_unstarted(target_match_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
  select coalesce((
    select value.status = 'UPCOMING'
      and value.scoring_locked is false
      and value.scored_holes = 0
      and value.current_hole = 0
      and value.holes_remaining = 18
      and value.team_1_holes_won = 0
      and value.team_2_holes_won = 0
      and value.running_result = 'Scheduled'
      and value.result_winner = ''
      and value.clinched is false
      and value.scorecard_complete is false
      and value.unresolved_mutations = 0
      and value.finalized_at is null
      and not exists (
        select 1 from scoring_authority.hole_scores score
        where score.match_id = value.match_id
      )
      and not exists (
        select 1 from scoring_authority.score_mutations mutation
        where mutation.match_id = value.match_id
          and mutation.mutation_type in (
            'HOLE_SCORE', 'FINALIZE', 'REOPEN', 'MARK_LIVE'
          )
      )
    from scoring_authority.matches value
    where value.match_id = target_match_id
      and value.tournament_id = '2026'
  ), false)
$$;


ALTER FUNCTION production_control.handicap_v1_match_is_unstarted(target_match_id text) OWNER TO postgres;

--
-- Name: handicap_v1_revision_fingerprint(uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.handicap_v1_revision_fingerprint(target_revision_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
  select production_control.handicap_v1_hash(
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-handicap-revision-v1',
      'context_contract_version', revision.context_contract_version,
      'tournament_id', revision.tournament_id,
      'effective_date', revision.effective_date,
      'method', revision.method,
      'source_metadata', revision.source_metadata,
      'source_evidence_date', revision.source_evidence_date,
      'predecessor_revision', revision.predecessor_revision,
      'roster_fingerprint', revision.roster_fingerprint,
      'entries', production_control.handicap_v1_stored_entries(
        revision.revision_id
      )
    )
  )
  from scoring_authority.handicap_revisions revision
  where revision.revision_id = target_revision_id
$$;


ALTER FUNCTION production_control.handicap_v1_revision_fingerprint(target_revision_id uuid) OWNER TO postgres;

--
-- Name: handicap_v1_roster_fingerprint(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.handicap_v1_roster_fingerprint(target_tournament text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
  select production_control.handicap_v1_hash(
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'player_id', roster.player_id,
          'team_id', roster.team_id,
          'team_side', roster.team_side,
          'participation_status', roster.participation_status
        ) order by roster.player_id
      ),
      '[]'::jsonb
    )
  )
  from scoring_authority.tournament_players roster
  where roster.tournament_id = target_tournament
    and roster.participation_status = 'ACTIVE'
$$;


ALTER FUNCTION production_control.handicap_v1_roster_fingerprint(target_tournament text) OWNER TO postgres;

--
-- Name: handicap_v1_stored_entries(uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.handicap_v1_stored_entries(target_revision_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'player_id', entry.player_id,
        'tournament_handicap',
          pg_catalog.trim_scale(entry.tournament_handicap),
        'source_index', case when entry.source_index is null then null
          else pg_catalog.trim_scale(entry.source_index) end,
        'low_index', case when entry.low_index is null then null
          else pg_catalog.trim_scale(entry.low_index) end,
        'source_metadata', entry.source_metadata
      ) order by entry.player_id
    ),
    '[]'::jsonb
  )
  from scoring_authority.handicap_revision_entries entry
  where entry.revision_id = target_revision_id
$$;


ALTER FUNCTION production_control.handicap_v1_stored_entries(target_revision_id uuid) OWNER TO postgres;

--
-- Name: hybrid_handicap_v1(numeric, numeric); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.hybrid_handicap_v1(current_value numeric, low_value numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select pg_catalog.round((current_value + low_value) / 2::numeric, 1)
$$;


ALTER FUNCTION production_control.hybrid_handicap_v1(current_value numeric, low_value numeric) OWNER TO postgres;

--
-- Name: import_production_calcutta_configuration_v1_internal(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.import_production_calcutta_configuration_v1_internal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  tabs constant jsonb := '["Calcutta Purchases","Calcutta Ownership","Calcutta Point Structure","Calcutta Payout"]'::jsonb;
  registration jsonb;
  purchase jsonb;
  owner jsonb;
  not_configured boolean:=upper(input->>'validation_status')='NOT_CONFIGURED';
  purchase_count integer:=0;
  ownership_count integer:=0;
  total_market numeric:=0;
  ownership_total numeric;
  next_revision bigint;
  config_id uuid;
begin
  perform production_control.assert_projection_scope(input,'CALCUTTA_CONFIGURATION','calcutta-configuration-v1',tabs);
  if jsonb_typeof(input#>'{payload,purchases}')<>'array'
     or jsonb_typeof(input#>'{payload,ownership}')<>'array'
     or jsonb_typeof(input#>'{payload,point_structure}')<>'array'
     or jsonb_typeof(input#>'{payload,payout_structure}')<>'array'
     or jsonb_typeof(input#>'{payload,financial_contract}')<>'object'
     or (not_configured and (input#>>'{payload,status}'<>'NOT_CONFIGURED'
       or jsonb_array_length(input#>'{payload,purchases}')<>0
       or jsonb_array_length(input#>'{payload,ownership}')<>0))
     or (not not_configured and upper(input->>'validation_status')<>'VALID') then
    return jsonb_build_object('ok',false,'code','PRODUCTION_CALCUTTA_CONFIGURATION_INVALID');
  end if;
  if not not_configured then
    for purchase in select value from jsonb_array_elements(input#>'{payload,purchases}') loop
      if btrim(coalesce(purchase->>'player_id',''))=''
         or coalesce((purchase->>'purchase_price')::numeric,-1)<0
         or not exists(select 1 from scoring_authority.tournament_players tp
           where tp.tournament_id='2026' and tp.player_id=purchase->>'player_id'
             and tp.participation_status='ACTIVE')
         or (select count(*) from jsonb_array_elements(input#>'{payload,purchases}') p
           where p->>'player_id'=purchase->>'player_id')<>1 then
        return jsonb_build_object('ok',false,'code','PRODUCTION_CALCUTTA_PURCHASE_INVALID');
      end if;
      purchase_count:=purchase_count+1;
      total_market:=total_market+(purchase->>'purchase_price')::numeric;
      select coalesce(sum((o->>'ownership_fraction')::numeric),0) into ownership_total
      from jsonb_array_elements(input#>'{payload,ownership}') o
      where o->>'player_id'=purchase->>'player_id';
      if abs(ownership_total-1)>=0.000001 then
        return jsonb_build_object('ok',false,'code','PRODUCTION_CALCUTTA_OWNERSHIP_TOTAL_MISMATCH');
      end if;
    end loop;
    if purchase_count=0
       or abs(coalesce((input#>>'{payload,financial_contract,total_payout_fraction}')::numeric,-1)-1)>=0.000001
       or abs(total_market-coalesce((input#>>'{payload,financial_contract,total_market_value}')::numeric,-1))>=0.005 then
      return jsonb_build_object('ok',false,'code','PRODUCTION_CALCUTTA_FINANCIAL_CONSERVATION_FAILED');
    end if;
    for owner in select value from jsonb_array_elements(input#>'{payload,ownership}') loop
      if btrim(coalesce(owner->>'player_id',''))='' or btrim(coalesce(owner->>'owner_player_id',''))=''
         or coalesce((owner->>'ownership_fraction')::numeric,0)<=0
         or coalesce((owner->>'ownership_fraction')::numeric,0)>1
         or not exists(select 1 from scoring_authority.players p where p.player_id=owner->>'owner_player_id')
         or (select count(*) from jsonb_array_elements(input#>'{payload,ownership}') o
           where o->>'player_id'=owner->>'player_id' and o->>'owner_player_id'=owner->>'owner_player_id')<>1 then
        return jsonb_build_object('ok',false,'code','PRODUCTION_CALCUTTA_OWNERSHIP_INVALID');
      end if;
      ownership_count:=ownership_count+1;
    end loop;
  end if;
  registration:=production_control.register_projection_revision(input,'CALCUTTA_CONFIGURATION','calcutta-configuration-v1',tabs);
  if not coalesce((registration->>'changed')::boolean,false) then return registration; end if;
  update scoring_authority.calcutta_configurations set is_current=false,status='SUPERSEDED',superseded_at=now()
  where tournament_id='2026' and is_current;
  if not not_configured then
    select coalesce(max(configuration_revision),0)+1 into next_revision
    from scoring_authority.calcutta_configurations where tournament_id='2026';
    insert into scoring_authority.calcutta_configurations(
      tournament_id,tournament_year,configuration_revision,configuration_fingerprint,
      purchases,ownership,point_structure,payout_structure,financial_contract,
      source_workbook_id,imported_by
    ) values('2026',2026,next_revision,lower(input->>'payload_fingerprint'),
      input#>'{payload,purchases}',input#>'{payload,ownership}',input#>'{payload,point_structure}',
      input#>'{payload,payout_structure}',input#>'{payload,financial_contract}',
      input->>'source_workbook_id',input->>'requested_by') returning id into config_id;
  end if;
  insert into scoring_authority.calcutta_configuration_import_runs(
    tournament_id,source_workbook_id,configuration_fingerprint,status,purchase_count,
    ownership_count,total_market_value,requested_by
  ) values('2026',input->>'source_workbook_id',lower(input->>'payload_fingerprint'),'APPLIED',
    purchase_count,ownership_count,total_market,input->>'requested_by');
  return registration||jsonb_build_object('configuration_status',case when not_configured then 'NOT_CONFIGURED' else 'VALID' end,
    'configuration_id',config_id,'purchase_count',purchase_count,'ownership_count',ownership_count,
    'total_market_value',total_market,'recalculation_enqueued',false,'shadow_only',true);
exception when others then
  return jsonb_build_object('ok',false,'code','PRODUCTION_CALCUTTA_CONFIGURATION_IMPORT_FAILED');
end;
$$;


ALTER FUNCTION production_control.import_production_calcutta_configuration_v1_internal(input jsonb) OWNER TO postgres;

--
-- Name: import_production_net_skins_configuration_v1_internal(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.import_production_net_skins_configuration_v1_internal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  tabs constant jsonb := '["Net Skins"]'::jsonb;
  registration jsonb;
  round_value jsonb;
  entry_value jsonb;
  revision_number bigint;
  round_count integer:=0;
  entry_count integer:=0;
  not_configured boolean:=upper(input->>'validation_status')='NOT_CONFIGURED';
begin
  perform production_control.assert_projection_scope(input,'NET_SKINS_CONFIGURATION','net-skins-configuration-v1',tabs);
  if jsonb_typeof(input#>'{payload,rounds}')<>'array'
     or (not_configured and (input#>>'{payload,status}'<>'NOT_CONFIGURED'
       or jsonb_array_length(input#>'{payload,rounds}')<>0))
     or (not not_configured and (upper(input->>'validation_status')<>'VALID'
       or jsonb_array_length(input#>'{payload,rounds}')=0)) then
    return jsonb_build_object('ok',false,'code','PRODUCTION_NET_SKINS_CONFIGURATION_INVALID');
  end if;
  if not not_configured then
    for round_value in select value from jsonb_array_elements(input#>'{payload,rounds}') loop
      if coalesce((round_value->>'round_number')::integer,0)<=0
         or upper(btrim(coalesce(round_value->>'format',''))) not in ('BB','SC','SI')
         or lower(btrim(coalesce(round_value->>'configuration_fingerprint',''))) !~ '^[0-9a-f]{64}$'
         or jsonb_typeof(round_value->'entries')<>'array'
         or (upper(round_value->>'format')='SC' and upper(round_value->>'entry_type')<>'PAIRING')
         or (upper(round_value->>'format')<>'SC' and upper(round_value->>'entry_type')<>'INDIVIDUAL')
         or (round_value->>'buy_in_per_entry')::numeric<0
         or (round_value->>'expected_pot')::numeric<>(select count(*)*(round_value->>'buy_in_per_entry')::numeric
           from jsonb_array_elements(round_value->'entries') e where coalesce((e->>'eligible')::boolean,true)) then
        return jsonb_build_object('ok',false,'code','PRODUCTION_NET_SKINS_ROUND_INVALID');
      end if;
      for entry_value in select value from jsonb_array_elements(round_value->'entries') loop
        if btrim(coalesce(entry_value->>'entry_id',''))=''
           or btrim(coalesce(entry_value->>'player_id_1',''))=''
           or (entry_value->>'buy_in')::numeric<>(round_value->>'buy_in_per_entry')::numeric
           or not exists(select 1 from scoring_authority.tournament_players tp
             where tp.tournament_id='2026' and tp.player_id=entry_value->>'player_id_1'
               and tp.participation_status='ACTIVE')
           or (upper(round_value->>'format')='SC' and
             (btrim(coalesce(entry_value->>'player_id_2',''))='' or not exists(
               select 1 from scoring_authority.tournament_players tp where tp.tournament_id='2026'
                 and tp.player_id=entry_value->>'player_id_2' and tp.participation_status='ACTIVE'))) then
          return jsonb_build_object('ok',false,'code','PRODUCTION_NET_SKINS_ENTRY_INVALID');
        end if;
      end loop;
    end loop;
  end if;
  registration:=production_control.register_projection_revision(input,'NET_SKINS_CONFIGURATION','net-skins-configuration-v1',tabs);
  if not coalesce((registration->>'changed')::boolean,false) then return registration; end if;
  revision_number:=(registration->>'revision_number')::bigint;
  delete from scoring_authority.net_skins_configurations where tournament_id='2026';
  if not not_configured then
    for round_value in select value from jsonb_array_elements(input#>'{payload,rounds}') loop
      round_count:=round_count+1;
      insert into scoring_authority.net_skins_configurations(
        tournament_id,round_number,format,enabled,entry_type,buy_in_per_entry,expected_pot,
        completion_rule,payout_rounding,tie_rule,configuration_revision,configuration_fingerprint,
        source_workbook_id,imported_by
      ) values('2026',(round_value->>'round_number')::integer,upper(round_value->>'format'),
        coalesce((round_value->>'enabled')::boolean,true),upper(round_value->>'entry_type'),
        (round_value->>'buy_in_per_entry')::numeric,(round_value->>'expected_pot')::numeric,
        'ALL_ELIGIBLE_ENTRIES_18_HOLES_AND_REFERENCED_MATCHES_OFFICIAL','NONE','NO_SKIN_NO_CARRY',
        revision_number,lower(round_value->>'configuration_fingerprint'),input->>'source_workbook_id',input->>'requested_by');
      for entry_value in select value from jsonb_array_elements(round_value->'entries') loop
        entry_count:=entry_count+1;
        insert into scoring_authority.net_skins_configuration_entries(
          tournament_id,round_number,entry_id,match_number,format,player_id_1,player_id_2,
          team_handicap,buy_in,eligible,source_payload
        ) values('2026',(round_value->>'round_number')::integer,entry_value->>'entry_id',
          btrim(coalesce(entry_value->>'match_number','')),upper(round_value->>'format'),
          entry_value->>'player_id_1',nullif(btrim(coalesce(entry_value->>'player_id_2','')),''),
          nullif(entry_value->>'team_handicap','')::numeric,(entry_value->>'buy_in')::numeric,
          coalesce((entry_value->>'eligible')::boolean,true),coalesce(entry_value->'source_payload','{}'::jsonb));
      end loop;
    end loop;
  end if;
  insert into scoring_authority.net_skins_configuration_import_runs(
    tournament_id,source_workbook_id,configuration_fingerprint,status,round_count,entry_count,requested_by
  ) values('2026',input->>'source_workbook_id',lower(input->>'payload_fingerprint'),'APPLIED',
    round_count,entry_count,input->>'requested_by');
  return registration||jsonb_build_object('configuration_status',case when not_configured then 'NOT_CONFIGURED' else 'VALID' end,
    'round_count',round_count,'entry_count',entry_count,'recalculation_enqueued',false,'shadow_only',true);
exception when others then
  return jsonb_build_object('ok',false,'code','PRODUCTION_NET_SKINS_CONFIGURATION_IMPORT_FAILED');
end;
$_$;


ALTER FUNCTION production_control.import_production_net_skins_configuration_v1_internal(input jsonb) OWNER TO postgres;

--
-- Name: initialize_certification_ingress_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.initialize_certification_ingress_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare p production_control.current_tournament_pointer_v1%rowtype;
begin
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=new.resource_id;
 insert into production_control.certification_ingress_generations_v1(resource_id,tournament_id,authority_epoch_id,pointer_revision)
 values(new.resource_id,p.tournament_id,new.authority_epoch_id,p.pointer_revision);
 return new;
end;$$;


ALTER FUNCTION production_control.initialize_certification_ingress_v1() OWNER TO postgres;

--
-- Name: initialize_certification_resource_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.initialize_certification_resource_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
declare r production_control.canonical_resource_v1%rowtype;
 a production_control.certification_admission_v1%rowtype;
 epoch_id uuid:=(input->>'authority_epoch_id')::uuid;
 binding_id uuid:=(input->>'binding_id')::uuid;
begin
 if current_user<>pg_get_userbyid((select relowner from pg_class where oid='production_control.canonical_resource_v1'::regclass)) then
  raise exception using errcode='42501',message='CANONICAL_RESOURCE_OWNER_REQUIRED';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('canonical-resource-registration-v1',0));
 select * into strict r from production_control.canonical_resource_v1 where singleton for update;
 if r.resource_class<>'CERTIFICATION' or r.database_name<>current_database()
   or input->>'resource_id' is distinct from r.resource_id
   or exists(select 1 from production_control.resource_scope)
   or exists(select 1 from production_control.cutover_activation_state)
   or input->>'initial_tournament_id' is distinct from '2026'
   or input->>'governance_tournament_id' is distinct from '2026'
   or input->>'release_commit' !~ '^[0-9a-f]{40}$'
   or epoch_id is null or binding_id is null then
  raise exception using errcode='42501',message='CERTIFICATION_BOOTSTRAP_INVALID';
 end if;
 select * into a from production_control.certification_admission_v1 where resource_id=r.resource_id;
 if found then
  if a.binding_id=binding_id and a.authority_epoch_id=epoch_id
    and a.release_commit=input->>'release_commit' and a.git_branch=input->>'git_branch'
    and a.deployment_id=input->>'deployment_id' and a.deployment_origin=input->>'deployment_origin'
    and a.capabilities=array(select jsonb_array_elements_text(input->'capabilities')) then
   return jsonb_build_object('ok',true,'idempotent',true,'resource_id',r.resource_id,'binding_id',a.binding_id);
  end if;
  raise exception using errcode='40001',message='CERTIFICATION_BOOTSTRAP_CONFLICT';
 end if;
 if exists(select 1 from scoring_authority.tournaments)
   or exists(select 1 from production_control.current_tournament_pointer_v1)
   or exists(select 1 from scoring_authority.authority_epochs) then
  raise exception using errcode='55000',message='CERTIFICATION_BOOTSTRAP_REQUIRES_EMPTY_AUTHORITY';
 end if;
 insert into scoring_authority.tournaments(tournament_id,tournament_year,name,source_workbook_id,scoring_authority)
 values('2026',2026,'Synthetic canonical certification',r.provenance_id,'SUPABASE');
 insert into production_control.future_tournament_catalog_v1(tournament_id,tournament_year,contract_version,
   tournament_name,lifecycle,lifecycle_revision,setup_revision,creation_mode,source_manifest)
 values('2026',2026,'production-future-year-administration-v1','Synthetic canonical certification','ACTIVE',1,0,'EXISTING',
   jsonb_build_object('resource_class','CERTIFICATION','resource_id',r.resource_id,'provenance_id',r.provenance_id));
 insert into production_control.current_tournament_pointer_v1(scope_key,contract_version,tournament_id,tournament_year,pointer_revision,lifecycle_revision)
 values(r.resource_id,'certification-current-tournament-pointer-v1','2026',2026,1,1);
 insert into production_control.future_tournament_resources_v1(tournament_id,project_ref,project_url,source_workbook_id,
   resource_status,resource_revision,google_compatibility_policy)
 values('2026',r.project_ref,r.project_url,r.provenance_id,'CURRENT_RESOURCE_BOUND',1,'RETIRED');
 insert into scoring_authority.authority_epochs(epoch_id,tournament_id,epoch_type,status,authority_before,authority_after,
   reconciliation_fingerprint,google_checkpoints,supabase_match_revisions,deployment_commit,actor_id,reason,committed_at,boundary_mode)
 values(epoch_id,'2026','CERTIFICATION_INITIALIZATION','COMMITTED','SUPABASE','SUPABASE',
   production_control.tournament_setup_hash_v1(to_jsonb(r)-'created_at'),'{}','{}',input->>'release_commit',current_user,
   'Owner-installed synthetic Certification authority; no prior provider authority',clock_timestamp(),'CERTIFICATION_INGRESS_V1');
 insert into scoring_authority.ingress_gates(tournament_id,state,authority,active_epoch_id,unresolved_client_queues,updated_by,boundary_mode)
 values('2026','PAUSED','SUPABASE',epoch_id,0,current_user,'CERTIFICATION_INGRESS_V1');
 insert into production_control.certification_admission_v1(resource_id,binding_id,enabled,git_branch,deployment_class,
   release_commit,deployment_id,deployment_origin,governance_tournament_id,authority_epoch_id,
   activation_revision,admission_revision,capabilities)
 values(r.resource_id,binding_id,false,input->>'git_branch','preview',input->>'release_commit',input->>'deployment_id',
   input->>'deployment_origin','2026',epoch_id,1,1,array(select jsonb_array_elements_text(input->'capabilities')));
 insert into production_control.operation_audit_events(event_type,domain,actor,result,details)
 values('CERTIFICATION_AUTHORITY_INITIALIZED','RESOURCE',current_user,'SUCCEEDED',
   jsonb_build_object('resource_id',r.resource_id,'installation_id',r.installation_id,'binding_id',binding_id,
     'authority_epoch_id',epoch_id,'enabled',false,'ingress','PAUSED'));
 return jsonb_build_object('ok',true,'idempotent',false,'resource_id',r.resource_id,'binding_id',binding_id);
end;
$_$;


ALTER FUNCTION production_control.initialize_certification_resource_v1(input jsonb) OWNER TO postgres;

--
-- Name: google_writer_provider_fence_settlement_observations; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.google_writer_provider_fence_settlement_observations (
    observation_id uuid NOT NULL,
    fence_id uuid NOT NULL,
    stage text NOT NULL,
    observation_request_id uuid NOT NULL,
    request_fingerprint text NOT NULL,
    payload_hash text NOT NULL,
    prior_observation_id uuid,
    protection_records jsonb NOT NULL,
    protection_set_fingerprint text NOT NULL,
    provider_fingerprint text NOT NULL,
    acl_fingerprint text NOT NULL,
    canonical_value_fingerprint text NOT NULL,
    combined_value_fingerprint text NOT NULL,
    formula_fingerprint text NOT NULL,
    structural_canary_fingerprint text NOT NULL,
    permission_inventory_fingerprint text NOT NULL,
    legacy_role text NOT NULL,
    legacy_can_edit boolean NOT NULL,
    legacy_can_share boolean NOT NULL,
    legacy_edit_capability_fingerprint text NOT NULL,
    acl_transition_intent_fingerprint text NOT NULL,
    acl_transition_proof_fingerprint text NOT NULL,
    acl_transition_proof jsonb NOT NULL,
    provider_observed_at timestamp with time zone NOT NULL,
    activation_revision bigint NOT NULL,
    authority_generation_id uuid NOT NULL,
    admission_generation_id uuid NOT NULL,
    admission_revision bigint NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_id text NOT NULL,
    authenticated_actor_fingerprint text NOT NULL,
    CONSTRAINT google_writer_provider_fence_acl_transition_intent_finger_check CHECK ((acl_transition_intent_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_acl_transition_proof_fingerp_check CHECK ((acl_transition_proof_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_authenticated_actor_fingerp_check1 CHECK ((authenticated_actor_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_canonical_value_fingerprint_check1 CHECK ((canonical_value_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_legacy_edit_capability_finge_check CHECK ((legacy_edit_capability_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_permission_inventory_finger_check1 CHECK ((permission_inventory_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_s_combined_value_fingerprint_check CHECK ((combined_value_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_s_protection_set_fingerprint_check CHECK ((protection_set_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_settlem_acl_transition_proof_check CHECK ((jsonb_typeof(acl_transition_proof) = 'object'::text)),
    CONSTRAINT google_writer_provider_fence_settlem_provider_fingerprint_check CHECK ((provider_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_settleme_activation_revision_check CHECK ((activation_revision >= 0)),
    CONSTRAINT google_writer_provider_fence_settleme_formula_fingerprint_check CHECK ((formula_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_settleme_request_fingerprint_check CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_settlemen_admission_revision_check CHECK ((admission_revision >= 0)),
    CONSTRAINT google_writer_provider_fence_settlemen_protection_records_check CHECK ((protection_records = '[]'::jsonb)),
    CONSTRAINT google_writer_provider_fence_settlement__legacy_can_share_check CHECK ((NOT legacy_can_share)),
    CONSTRAINT google_writer_provider_fence_settlement_o_acl_fingerprint_check CHECK ((acl_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_settlement_o_legacy_can_edit_check CHECK ((NOT legacy_can_edit)),
    CONSTRAINT google_writer_provider_fence_settlement_obse_payload_hash_check CHECK ((payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_settlement_obser_legacy_role_check CHECK ((legacy_role = 'reader'::text)),
    CONSTRAINT google_writer_provider_fence_settlement_observat_actor_id_check CHECK (((btrim(actor_id) <> ''::text) AND (length(actor_id) <= 160))),
    CONSTRAINT google_writer_provider_fence_settlement_observation_stage_check CHECK ((stage = ANY (ARRAY['ACL_READER_CONFIRMED'::text, 'SETTLEMENT_READBACK_1'::text, 'SETTLEMENT_READBACK_2'::text]))),
    CONSTRAINT google_writer_provider_fence_settlement_observations_check CHECK ((((stage = 'ACL_READER_CONFIRMED'::text) AND (prior_observation_id IS NULL)) OR ((stage <> 'ACL_READER_CONFIRMED'::text) AND (prior_observation_id IS NOT NULL)))),
    CONSTRAINT google_writer_provider_fence_structural_canary_fingerpri_check1 CHECK ((structural_canary_fingerprint ~ '^[0-9a-f]{64}$'::text))
);


ALTER TABLE production_control.google_writer_provider_fence_settlement_observations OWNER TO postgres;

--
-- Name: insert_google_writer_provider_fence_settlement_observation(uuid, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.insert_google_writer_provider_fence_settlement_observation(target_fence_id uuid, target_stage text, input jsonb) RETURNS production_control.google_writer_provider_fence_settlement_observations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  prior
    production_control.google_writer_provider_fence_settlement_observations%rowtype;
  installed
    production_control.google_writer_provider_fence_settlement_observations%rowtype;
  existing
    production_control.google_writer_provider_fence_settlement_observations%rowtype;
  inserted
    production_control.google_writer_provider_fence_settlement_observations%rowtype;
  request_identifier uuid;
  prior_identifier uuid;
  empty_retired_protections jsonb := '[]'::jsonb;
  empty_retired_protections_fingerprint text :=
    production_control.structured_evidence_fingerprint('[]'::jsonb);
  install_dispatch record;
  observed_at_value timestamptz;
  captured_at_value timestamptz := pg_catalog.now();
  payload_hash_value text := production_control.cutover_payload_hash(input);
begin
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if target_stage not in (
       'ACL_READER_CONFIRMED',
       'SETTLEMENT_READBACK_1',
       'SETTLEMENT_READBACK_2'
     )
     or coalesce(input->>'observation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'install_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'quiesce_evidence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'provider_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'acl_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'canonical_value_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'combined_value_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'formula_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'structural_canary_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'permission_inventory_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or input->>'legacy_role' is distinct from 'reader'
     or input->'legacy_can_edit' is distinct from 'false'::jsonb
     or input->'legacy_can_share' is distinct from 'false'::jsonb
     or coalesce(input->>'legacy_edit_capability_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'acl_transition_intent_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'acl_transition_proof_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(input->'acl_transition_proof') is distinct from
       'object'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_INPUT_INVALID';
  end if;
  request_identifier := (input->>'observation_request_id')::uuid;
  -- Public settlement callers hold scoring_admission_lock_key() before entering
  -- this helper. Resolve the durable request identity under that same lock and
  -- before freshness checks: an exact lost-response replay remains recoverable
  -- after its observation ages, while every changed field is bound by the
  -- immutable request fingerprint and full canonical payload hash.
  select * into existing
  from production_control.google_writer_provider_fence_settlement_observations value
  where value.observation_request_id = request_identifier;
  if found then
    if existing.fence_id is distinct from target_fence_id
       or existing.stage is distinct from target_stage
       or existing.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or existing.payload_hash is distinct from payload_hash_value
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_IDEMPOTENCY_CONFLICT';
    end if;
    return existing;
  end if;

  observed_at_value := (input->>'provider_observed_at')::timestamptz;
  -- The 190-second DB gate carries only a ten-second margin over the required
  -- provider settlement interval. Limit snapshot transport age to five
  -- seconds so readback 1 still proves more than 180 seconds of provider-side
  -- stability. The same bound applies independently to every observation.
  if observed_at_value < captured_at_value - interval '5 seconds'
     or observed_at_value > captured_at_value + interval '30 seconds'
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_OBSERVATION_STALE';
  end if;
  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = target_fence_id
  for update;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into strict quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = fence.quiesce_evidence_id
  for update;
  select * into strict install_dispatch
  from production_control.google_writer_provider_fence_install_dispatches value
  where value.fence_id = fence.fence_id
    and value.outcome_status = 'TARGET_CONFIRMED'
  order by value.attempt desc
  limit 1
  for update;
  if fence.status is distinct from 'INSTALLING'
     or fence.install_request_id is distinct from
       (input->>'install_request_id')::uuid
     or fence.quiesce_evidence_id is distinct from
       (input->>'quiesce_evidence_id')::uuid
     or fence.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or fence.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or fence.actor_id is distinct from input->>'actor_id'
     or fence.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
     or quiesce.status is distinct from 'VERIFIED'
     or quiesce.purpose is distinct from fence.lifecycle_mode
     or quiesce.expires_at <= pg_catalog.clock_timestamp()
     or quiesce.owner_freeze_expires_at <= pg_catalog.clock_timestamp()
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or install_dispatch.outcome_status is distinct from 'TARGET_CONFIRMED'
     or install_dispatch.provider_mutation_class is distinct from
       'DRIVE_LEGACY_PERMISSION_WRITER_TO_READER_V1'
     or install_dispatch.source_role is distinct from 'writer'
     or install_dispatch.target_role is distinct from 'reader'
     or install_dispatch.transition_intent_fingerprint is distinct from
       pg_catalog.lower(input->>'acl_transition_intent_fingerprint')
     or install_dispatch.transition_proof_fingerprint is distinct from
       pg_catalog.lower(input->>'acl_transition_proof_fingerprint')
     or install_dispatch.transition_proof is distinct from
       input->'acl_transition_proof'
     or input->'acl_transition_proof'->>'schemaVersion' is distinct from
       'step12-production-google-drive-acl-transition-proof-v1'
     or input->'acl_transition_proof'->>'workbookId' is distinct from
       fence.source_workbook_id
     or input->'acl_transition_proof'->>'fenceId' is distinct from
       fence.fence_id::text
     or input->'acl_transition_proof'->>'installRequestId' is distinct from
       fence.install_request_id::text
     or input->'acl_transition_proof'->>'transitionPhase' is distinct from
       'INSTALL'
     or input->'acl_transition_proof'->>'providerMutationClass' is distinct from
       install_dispatch.provider_mutation_class
     or input->'acl_transition_proof'->>'priorRole' is distinct from 'writer'
     or input->'acl_transition_proof'->>'currentRole' is distinct from 'reader'
     or input->'acl_transition_proof'->'currentLegacyCanEdit' is distinct from
       'false'::jsonb
     or input->'acl_transition_proof'->'currentLegacyCanShare' is distinct from
       'false'::jsonb
     or input->'acl_transition_proof'->>'transitionFingerprint' is distinct from
       install_dispatch.transition_proof_fingerprint
     or pg_catalog.lower(input->>'canonical_value_fingerprint')
       is distinct from fence.baseline_canonical_value_fingerprint
     or pg_catalog.lower(input->>'combined_value_fingerprint')
       is distinct from fence.baseline_combined_value_fingerprint
     or pg_catalog.lower(input->>'formula_fingerprint') is distinct from
       fence.baseline_formula_fingerprint
     or observed_at_value < fence.installing_at
     or (fence.lifecycle_mode = 'CUTOVER' and (
       activation.state is distinct from 'GOOGLE_LEASE_ARMED'
       or resource.participant_identity_authority is distinct from 'SUPABASE'
       or resource.current_tournament_read_authority is distinct from 'SUPABASE'
       or gate.state is distinct from 'OPEN'
       or not gate.admission_protocol_enforced
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       activation.state is distinct from 'DORMANT'
       or resource.participant_identity_authority is distinct from 'PASSPORT'
       or resource.current_tournament_read_authority is distinct from 'GOOGLE'
       or gate.state is distinct from 'PAUSED'
       or gate.admission_protocol_enforced
     ))
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.active_google_writer_provider_fence_id is not null
     or resource.scoring_authority is distinct from 'GOOGLE'
     or (fence.lifecycle_mode = 'CUTOVER' and
       (not resource.public_supabase_reads_enabled or
        not resource.auth_user_creation_enabled))
     or (fence.lifecycle_mode = 'REHEARSAL' and
       (resource.public_supabase_reads_enabled or
        resource.auth_user_creation_enabled))
     or resource.scoring_ingress_enabled
     or resource.workers_enabled
     or gate.authority is distinct from 'GOOGLE'
     or gate.admission_state is distinct from 'OPEN'
     or gate.active_closure_id is not null
     or gate.external_fence_evidence_id is not null
     or gate.google_writer_provider_fence_id is not null
     or gate.google_writer_provider_verification_id is not null
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or (fence.lifecycle_mode = 'CUTOVER' and (
       gate.admission_deployment_id is distinct from input->>'deployment_id'
       or activation.expected_deployment_commit is distinct from
         pg_catalog.lower(input->>'deployment_commit')
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       input->>'deployment_id' is distinct from fence.candidate_deployment_id
       or pg_catalog.lower(input->>'deployment_commit') is distinct from
         fence.candidate_deployment_commit
     ))
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_SCOPE_DRIFT';
  end if;

  select * into installed
  from production_control.google_writer_provider_fence_settlement_observations value
  where value.fence_id = fence.fence_id
    and value.stage = 'ACL_READER_CONFIRMED'
  for update;

  if target_stage = 'ACL_READER_CONFIRMED' then
    if found or input->>'prior_observation_id' is not null then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_SEQUENCE_INVALID';
    end if;
    prior_identifier := null;
  else
    if not found
       or coalesce(input->>'prior_observation_id', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_SEQUENCE_INVALID';
    end if;
    prior_identifier := (input->>'prior_observation_id')::uuid;
    if target_stage = 'SETTLEMENT_READBACK_1' then
      prior := installed;
      if prior_identifier is distinct from installed.observation_id
         or captured_at_value < installed.recorded_at + interval '190 seconds'
      then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_WAIT_REQUIRED';
      end if;
    else
      select * into strict prior
      from production_control.google_writer_provider_fence_settlement_observations value
      where value.fence_id = fence.fence_id
        and value.stage = 'SETTLEMENT_READBACK_1'
      for update;
      if prior_identifier is distinct from prior.observation_id
         or captured_at_value < prior.recorded_at + interval '10 seconds'
         or observed_at_value < prior.recorded_at + interval '10 seconds'
      then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_WAIT_REQUIRED';
      end if;
    end if;
    if observed_at_value <= prior.provider_observed_at
       or observed_at_value <= installed.provider_observed_at
       or pg_catalog.lower(input->>'provider_fingerprint') is distinct from
         installed.provider_fingerprint
       or pg_catalog.lower(input->>'acl_fingerprint') is distinct from
         installed.acl_fingerprint
       or pg_catalog.lower(input->>'canonical_value_fingerprint')
         is distinct from installed.canonical_value_fingerprint
       or pg_catalog.lower(input->>'combined_value_fingerprint')
         is distinct from installed.combined_value_fingerprint
       or pg_catalog.lower(input->>'formula_fingerprint') is distinct from
         installed.formula_fingerprint
       or pg_catalog.lower(input->>'structural_canary_fingerprint')
         is distinct from installed.structural_canary_fingerprint
       or pg_catalog.lower(input->>'permission_inventory_fingerprint')
         is distinct from installed.permission_inventory_fingerprint
       or input->>'legacy_role' is distinct from installed.legacy_role
       or (input->>'legacy_can_edit')::boolean is distinct from
         installed.legacy_can_edit
       or (input->>'legacy_can_share')::boolean is distinct from
         installed.legacy_can_share
       or pg_catalog.lower(input->>'legacy_edit_capability_fingerprint')
         is distinct from installed.legacy_edit_capability_fingerprint
       or pg_catalog.lower(input->>'acl_transition_intent_fingerprint')
         is distinct from installed.acl_transition_intent_fingerprint
       or pg_catalog.lower(input->>'acl_transition_proof_fingerprint')
         is distinct from installed.acl_transition_proof_fingerprint
       or input->'acl_transition_proof' is distinct from
         installed.acl_transition_proof
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_DRIFT';
    end if;
  end if;

  insert into
    production_control.google_writer_provider_fence_settlement_observations (
      observation_id, fence_id, stage, observation_request_id,
      request_fingerprint, payload_hash, prior_observation_id,
      protection_records, protection_set_fingerprint, provider_fingerprint,
      acl_fingerprint, canonical_value_fingerprint,
      combined_value_fingerprint, formula_fingerprint,
      structural_canary_fingerprint, permission_inventory_fingerprint,
      legacy_role, legacy_can_edit, legacy_can_share,
      legacy_edit_capability_fingerprint,
      acl_transition_intent_fingerprint,
      acl_transition_proof_fingerprint, acl_transition_proof,
      provider_observed_at, activation_revision, authority_generation_id,
      admission_generation_id, admission_revision, recorded_at, actor_id,
      authenticated_actor_fingerprint
    ) values (
      extensions.gen_random_uuid(), fence.fence_id, target_stage,
      request_identifier, pg_catalog.lower(input->>'request_fingerprint'),
      payload_hash_value, prior_identifier, empty_retired_protections,
      empty_retired_protections_fingerprint,
      pg_catalog.lower(input->>'provider_fingerprint'),
      pg_catalog.lower(input->>'acl_fingerprint'),
      pg_catalog.lower(input->>'canonical_value_fingerprint'),
      pg_catalog.lower(input->>'combined_value_fingerprint'),
      pg_catalog.lower(input->>'formula_fingerprint'),
      pg_catalog.lower(input->>'structural_canary_fingerprint'),
      pg_catalog.lower(input->>'permission_inventory_fingerprint'),
      'reader', false, false,
      pg_catalog.lower(input->>'legacy_edit_capability_fingerprint'),
      pg_catalog.lower(input->>'acl_transition_intent_fingerprint'),
      pg_catalog.lower(input->>'acl_transition_proof_fingerprint'),
      input->'acl_transition_proof',
      observed_at_value,
      activation.activation_revision, activation.authority_generation_id,
      gate.admission_generation_id, gate.admission_revision,
      captured_at_value, pg_catalog.left(input->>'actor_id', 160),
      pg_catalog.lower(input->>'authenticated_actor_fingerprint')
    ) returning * into inserted;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result,
    details
  ) values (
    'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_' || target_stage,
    'SCORING_AUTHORITY', '2026', inserted.actor_id,
    inserted.request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'fence_id', fence.fence_id,
      'observation_id', inserted.observation_id,
      'stage', inserted.stage,
      'prior_observation_id', inserted.prior_observation_id,
      'provider_observed_at', inserted.provider_observed_at,
      'recorded_at', inserted.recorded_at,
      'acl_transition_proof_fingerprint',
        inserted.acl_transition_proof_fingerprint,
      'legacy_role', inserted.legacy_role,
      'legacy_can_edit', inserted.legacy_can_edit,
      'legacy_can_share', inserted.legacy_can_share,
      'structural_canary_fingerprint',
        inserted.structural_canary_fingerprint,
      'permission_inventory_fingerprint',
        inserted.permission_inventory_fingerprint,
      'admission_reservation_active', true
    )
  );
  return inserted;
end;
$_$;


ALTER FUNCTION production_control.insert_google_writer_provider_fence_settlement_observation(target_fence_id uuid, target_stage text, input jsonb) OWNER TO postgres;

--
-- Name: google_writer_provider_fence_verifications; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.google_writer_provider_fence_verifications (
    verification_id uuid NOT NULL,
    fence_id uuid NOT NULL,
    quiesce_evidence_id uuid NOT NULL,
    request_fingerprint text NOT NULL,
    payload_hash text NOT NULL,
    protection_records jsonb NOT NULL,
    protected_sheet_ids jsonb NOT NULL,
    protected_range_ids jsonb NOT NULL,
    protection_count integer NOT NULL,
    protection_set_fingerprint text NOT NULL,
    provider_fingerprint text NOT NULL,
    acl_fingerprint text NOT NULL,
    canonical_value_fingerprint text NOT NULL,
    combined_value_fingerprint text NOT NULL,
    formula_fingerprint text NOT NULL,
    structural_canary_fingerprint text NOT NULL,
    permission_inventory_fingerprint text NOT NULL,
    legacy_deployments_fenced boolean NOT NULL,
    legacy_google_credentials_fenced boolean NOT NULL,
    non_owner_manual_google_scoring_fenced boolean NOT NULL,
    owner_override_operationally_frozen boolean NOT NULL,
    recovery_only boolean DEFAULT false NOT NULL,
    captured_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    actor_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    acl_contract_version text,
    install_dispatch_id uuid,
    acl_transition_intent_fingerprint text,
    acl_transition_proof jsonb,
    acl_transition_proof_fingerprint text,
    legacy_role text,
    legacy_can_edit boolean,
    legacy_can_share boolean,
    legacy_edit_capability_fingerprint text,
    settlement_readback_2_observation_id uuid,
    global_writer_stop_active_at timestamp with time zone,
    CONSTRAINT google_writer_provider_fence__canonical_value_fingerprint_check CHECK ((canonical_value_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_legacy_google_credentials_fe_check CHECK (legacy_google_credentials_fenced),
    CONSTRAINT google_writer_provider_fence_non_owner_manual_google_scor_check CHECK (non_owner_manual_google_scoring_fenced),
    CONSTRAINT google_writer_provider_fence_owner_override_operationally_check CHECK (owner_override_operationally_frozen),
    CONSTRAINT google_writer_provider_fence_permission_inventory_fingerp_check CHECK ((permission_inventory_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_structural_canary_fingerprin_check CHECK ((structural_canary_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_v_combined_value_fingerprint_check CHECK ((combined_value_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_v_protection_set_fingerprint_check CHECK ((protection_set_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_ve_legacy_deployments_fenced_check CHECK (legacy_deployments_fenced),
    CONSTRAINT google_writer_provider_fence_verific_provider_fingerprint_check CHECK ((provider_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_verifica_formula_fingerprint_check CHECK ((formula_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_verifica_protected_range_ids_check CHECK ((jsonb_typeof(protected_range_ids) = 'array'::text)),
    CONSTRAINT google_writer_provider_fence_verifica_protected_sheet_ids_check CHECK ((jsonb_typeof(protected_sheet_ids) = 'array'::text)),
    CONSTRAINT google_writer_provider_fence_verifica_request_fingerprint_check CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_verificat_protection_records_check CHECK ((jsonb_typeof(protection_records) = 'array'::text)),
    CONSTRAINT google_writer_provider_fence_verification_acl_fingerprint_check CHECK ((acl_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT google_writer_provider_fence_verifications_check CHECK ((expires_at > captured_at)),
    CONSTRAINT google_writer_provider_fence_verifications_payload_hash_check CHECK ((payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT production_google_writer_provider_verification_2100_check CHECK (((expires_at > captured_at) AND (expires_at <= (captured_at + '00:35:00'::interval)))),
    CONSTRAINT production_google_writer_provider_verification_acl_v2_check CHECK ((((acl_contract_version IS NULL) AND (protection_count = 17) AND (install_dispatch_id IS NULL) AND (acl_transition_intent_fingerprint IS NULL) AND (acl_transition_proof IS NULL) AND (acl_transition_proof_fingerprint IS NULL) AND (legacy_role IS NULL) AND (legacy_can_edit IS NULL) AND (legacy_can_share IS NULL) AND (legacy_edit_capability_fingerprint IS NULL) AND (settlement_readback_2_observation_id IS NULL) AND (global_writer_stop_active_at IS NULL)) OR ((acl_contract_version = 'DRIVE_ACL_V2'::text) AND (protection_count = 0) AND (protection_records = '[]'::jsonb) AND (protected_sheet_ids = '[]'::jsonb) AND (protected_range_ids = '[]'::jsonb) AND (install_dispatch_id IS NOT NULL) AND (acl_transition_intent_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (jsonb_typeof(acl_transition_proof) = 'object'::text) AND (acl_transition_proof_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (legacy_role = 'reader'::text) AND (legacy_can_edit IS FALSE) AND (legacy_can_share IS FALSE) AND (legacy_edit_capability_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (settlement_readback_2_observation_id IS NOT NULL) AND (global_writer_stop_active_at IS NOT NULL))))
);


ALTER TABLE production_control.google_writer_provider_fence_verifications OWNER TO postgres;

--
-- Name: insert_google_writer_provider_fence_verification(uuid, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.insert_google_writer_provider_fence_verification(target_fence_id uuid, input jsonb) RETURNS production_control.google_writer_provider_fence_verifications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  fence production_control.google_writer_provider_fences%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  install_dispatch
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  readback_2
    production_control.google_writer_provider_fence_settlement_observations%rowtype;
  verification
    production_control.google_writer_provider_fence_verifications%rowtype;
  captured timestamptz := pg_catalog.clock_timestamp();
  verification_expiry timestamptz;
  empty_protections_fingerprint text :=
    production_control.structured_evidence_fingerprint('[]'::jsonb);
begin
  if coalesce(input->>'install_dispatch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'settlement_readback_2_observation_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_VERIFICATION_INPUT_INVALID';
  end if;

  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = target_fence_id
  for update;
  select * into strict quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = fence.quiesce_evidence_id
  for update;
  select * into strict install_dispatch
  from production_control.google_writer_provider_fence_install_dispatches value
  where value.dispatch_id = (input->>'install_dispatch_id')::uuid
    and value.fence_id = fence.fence_id
  for update;
  select * into strict readback_2
  from production_control.google_writer_provider_fence_settlement_observations value
  where value.observation_id =
      (input->>'settlement_readback_2_observation_id')::uuid
    and value.fence_id = fence.fence_id
    and value.stage = 'SETTLEMENT_READBACK_2'
  for update;

  verification_expiry := least(
    captured + interval '2100 seconds',
    quiesce.expires_at,
    quiesce.owner_freeze_expires_at
  );
  if fence.status is distinct from 'INSTALLING'
     or fence.actor_id is distinct from input->>'actor_id'
     or fence.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
     or quiesce.status is distinct from 'VERIFIED'
     or quiesce.purpose is distinct from fence.lifecycle_mode
     or quiesce.candidate_deployment_id is distinct from
       fence.candidate_deployment_id
     or quiesce.candidate_deployment_commit is distinct from
       fence.candidate_deployment_commit
     or verification_expiry <= captured
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or install_dispatch.outcome_status is distinct from 'TARGET_CONFIRMED'
     or install_dispatch.mutation_plan is distinct from
       'DRIVE_ACL_LEGACY_WRITER_TO_READER_V1'
     or install_dispatch.provider_mutation_class is distinct from
       'DRIVE_LEGACY_PERMISSION_WRITER_TO_READER_V1'
     or install_dispatch.source_role is distinct from 'writer'
     or install_dispatch.target_role is distinct from 'reader'
     or install_dispatch.transition_proof is null
     or install_dispatch.transition_proof_fingerprint is null
     or install_dispatch.transition_intent_fingerprint is distinct from
       readback_2.acl_transition_intent_fingerprint
     or install_dispatch.transition_proof_fingerprint is distinct from
       readback_2.acl_transition_proof_fingerprint
     or install_dispatch.transition_proof is distinct from
       readback_2.acl_transition_proof
     or install_dispatch.transition_proof->>'currentRole' is distinct from
       'reader'
     or install_dispatch.transition_proof->'currentLegacyCanEdit'
       is distinct from 'false'::jsonb
     or install_dispatch.transition_proof->'currentLegacyCanShare'
       is distinct from 'false'::jsonb
     or readback_2.legacy_role is distinct from 'reader'
     or readback_2.legacy_can_edit
     or readback_2.legacy_can_share
     or readback_2.protection_records is distinct from '[]'::jsonb
     or readback_2.protection_set_fingerprint is distinct from
       empty_protections_fingerprint
     or readback_2.canonical_value_fingerprint is distinct from
       fence.baseline_canonical_value_fingerprint
     or readback_2.combined_value_fingerprint is distinct from
       fence.baseline_combined_value_fingerprint
     or readback_2.formula_fingerprint is distinct from
       fence.baseline_formula_fingerprint
     or fence.global_writer_stop_active_at is null
     or readback_2.recorded_at < fence.global_writer_stop_active_at
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_VERIFICATION_NOT_CURRENT';
  end if;

  insert into production_control.google_writer_provider_fence_verifications (
    verification_id, fence_id, quiesce_evidence_id, request_fingerprint,
    payload_hash, protection_records, protected_sheet_ids,
    protected_range_ids, protection_count, protection_set_fingerprint,
    provider_fingerprint, acl_fingerprint, canonical_value_fingerprint,
    combined_value_fingerprint, formula_fingerprint,
    structural_canary_fingerprint, permission_inventory_fingerprint,
    legacy_deployments_fenced, legacy_google_credentials_fenced,
    non_owner_manual_google_scoring_fenced,
    owner_override_operationally_frozen, recovery_only,
    captured_at, expires_at, actor_id, acl_contract_version,
    install_dispatch_id, acl_transition_intent_fingerprint,
    acl_transition_proof, acl_transition_proof_fingerprint,
    legacy_role, legacy_can_edit, legacy_can_share,
    legacy_edit_capability_fingerprint,
    settlement_readback_2_observation_id, global_writer_stop_active_at
  ) values (
    extensions.gen_random_uuid(), fence.fence_id, quiesce.evidence_id,
    pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(input),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 0,
    empty_protections_fingerprint,
    readback_2.provider_fingerprint, readback_2.acl_fingerprint,
    readback_2.canonical_value_fingerprint,
    readback_2.combined_value_fingerprint, readback_2.formula_fingerprint,
    readback_2.structural_canary_fingerprint,
    readback_2.permission_inventory_fingerprint,
    true, true, true, true, false, captured, verification_expiry,
    pg_catalog.left(input->>'actor_id', 160), 'DRIVE_ACL_V2',
    install_dispatch.dispatch_id,
    install_dispatch.transition_intent_fingerprint,
    install_dispatch.transition_proof,
    install_dispatch.transition_proof_fingerprint,
    'reader', false, false, readback_2.legacy_edit_capability_fingerprint,
    readback_2.observation_id, fence.global_writer_stop_active_at
  ) returning * into verification;
  return verification;
end;
$_$;


ALTER FUNCTION production_control.insert_google_writer_provider_fence_verification(target_fence_id uuid, input jsonb) OWNER TO postgres;

--
-- Name: vercel_writer_critical_waf_observations; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.vercel_writer_critical_waf_observations (
    observation_id uuid NOT NULL,
    epoch_id uuid NOT NULL,
    provider_evidence_id uuid NOT NULL,
    provider_evidence_schema text NOT NULL,
    evidence_request_id uuid NOT NULL,
    transition_request_id uuid NOT NULL,
    evidence_stage text NOT NULL,
    record_request_id uuid NOT NULL,
    record_request_fingerprint text NOT NULL,
    record_payload_hash text NOT NULL,
    request_fingerprint text NOT NULL,
    evidence_fingerprint text NOT NULL,
    signer_key_fingerprint text NOT NULL,
    signer_key_version text NOT NULL,
    purpose text NOT NULL,
    transition_mode text NOT NULL,
    vercel_project_id text NOT NULL,
    vercel_team_id text NOT NULL,
    candidate_alias_origin text NOT NULL,
    candidate_immutable_origin text NOT NULL,
    candidate_deployment_id text NOT NULL,
    candidate_commit_sha text NOT NULL,
    candidate_deployment_target text NOT NULL,
    configuration_mode text NOT NULL,
    active_config_version text NOT NULL,
    active_config_etag text,
    provider_configuration_id text NOT NULL,
    provider_owner_id text NOT NULL,
    configuration_identity_fingerprint text NOT NULL,
    semantic_configuration jsonb NOT NULL,
    semantic_configuration_fingerprint text NOT NULL,
    ordered_rules_fingerprint text NOT NULL,
    custom_rule_count integer NOT NULL,
    baseline_configuration_version text,
    baseline_source_version_read_fingerprint text,
    source_version_read_fingerprint text NOT NULL,
    baseline_evidence_id uuid,
    critical_evidence_id uuid,
    baseline_semantic_fingerprint text NOT NULL,
    critical_semantic_fingerprint text,
    run_owned_rule_name text NOT NULL,
    run_owned_rule_nonce uuid NOT NULL,
    provider_assigned_rule_id text,
    run_owned_rule_fingerprint text NOT NULL,
    run_owned_insert_document_fingerprint text NOT NULL,
    run_owned_provider_rule_document_fingerprint text,
    run_owned_rule_precedence integer,
    critical_window_contract_fingerprint text,
    pending_draft_change_count integer NOT NULL,
    provider_observed_at timestamp with time zone NOT NULL,
    attested_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT production_vercel_writer_critical_waf_observation_shape_check CHECK (((attested_at = provider_observed_at) AND (expires_at = (attested_at + '00:35:00'::interval)) AND (candidate_deployment_target = 'PREVIEW'::text) AND (((purpose = 'REHEARSAL'::text) AND (transition_mode = 'REHEARSAL'::text)) OR ((purpose = 'CUTOVER'::text) AND (transition_mode = ANY (ARRAY['CUTOVER'::text, 'ROLLBACK'::text])))) AND (((evidence_stage = 'BASELINE_CAPTURE'::text) AND (baseline_configuration_version IS NULL) AND (baseline_source_version_read_fingerprint IS NULL) AND (baseline_evidence_id IS NULL) AND (critical_evidence_id IS NULL) AND (critical_semantic_fingerprint IS NULL) AND (provider_assigned_rule_id IS NULL) AND (run_owned_provider_rule_document_fingerprint IS NULL) AND (run_owned_rule_precedence IS NULL) AND (critical_window_contract_fingerprint IS NULL) AND (custom_rule_count = 0)) OR ((evidence_stage = ANY (ARRAY['CRITICAL_ACTIVE'::text, 'CRITICAL_REATTEST'::text])) AND (baseline_configuration_version IS NOT NULL) AND (baseline_source_version_read_fingerprint IS NOT NULL) AND (baseline_evidence_id IS NOT NULL) AND (provider_assigned_rule_id IS NOT NULL) AND (run_owned_rule_fingerprint IS NOT NULL) AND (run_owned_provider_rule_document_fingerprint IS NOT NULL) AND (run_owned_rule_precedence = 0) AND (critical_window_contract_fingerprint IS NOT NULL) AND (critical_semantic_fingerprint IS NOT NULL) AND (custom_rule_count = 1) AND (((evidence_stage = 'CRITICAL_ACTIVE'::text) AND (critical_evidence_id IS NULL)) OR ((evidence_stage = 'CRITICAL_REATTEST'::text) AND (critical_evidence_id IS NOT NULL)))) OR ((evidence_stage = 'BASELINE_RESTORED'::text) AND (baseline_configuration_version IS NOT NULL) AND (baseline_source_version_read_fingerprint IS NOT NULL) AND (baseline_evidence_id IS NOT NULL) AND (critical_evidence_id IS NOT NULL) AND (critical_semantic_fingerprint IS NOT NULL) AND (provider_assigned_rule_id IS NULL) AND (run_owned_provider_rule_document_fingerprint IS NULL) AND (run_owned_rule_precedence IS NULL) AND (critical_window_contract_fingerprint IS NULL) AND (custom_rule_count = 0))))),
    CONSTRAINT vercel_writer_critical_waf_o_baseline_configuration_versi_check CHECK (((baseline_configuration_version IS NULL) OR (baseline_configuration_version ~ '^[A-Za-z0-9_.:-]{1,160}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_o_baseline_semantic_fingerprin_check CHECK ((baseline_semantic_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_o_baseline_source_version_read_check CHECK (((baseline_source_version_read_fingerprint IS NULL) OR (baseline_source_version_read_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_o_configuration_identity_finge_check CHECK ((configuration_identity_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_o_critical_semantic_fingerprin_check CHECK (((critical_semantic_fingerprint IS NULL) OR (critical_semantic_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_o_critical_window_contract_fin_check CHECK (((critical_window_contract_fingerprint IS NULL) OR (critical_window_contract_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_o_run_owned_insert_document_fi_check CHECK ((run_owned_insert_document_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_o_run_owned_provider_rule_docu_check CHECK (((run_owned_provider_rule_document_fingerprint IS NULL) OR (run_owned_provider_rule_document_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_o_semantic_configuration_finge_check CHECK ((semantic_configuration_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_o_source_version_read_fingerpr_check CHECK ((source_version_read_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_ob_candidate_deployment_target_check CHECK ((candidate_deployment_target = 'PREVIEW'::text)),
    CONSTRAINT vercel_writer_critical_waf_obs_candidate_immutable_origin_check CHECK ((candidate_immutable_origin ~ '^https://[a-z0-9.-]+$'::text)),
    CONSTRAINT vercel_writer_critical_waf_obs_pending_draft_change_count_check CHECK ((pending_draft_change_count = 0)),
    CONSTRAINT vercel_writer_critical_waf_obs_record_request_fingerprint_check CHECK ((record_request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_obs_run_owned_rule_fingerprint_check CHECK ((run_owned_rule_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_obse_ordered_rules_fingerprint_check CHECK ((ordered_rules_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_obse_provider_assigned_rule_id_check CHECK (((provider_assigned_rule_id IS NULL) OR (provider_assigned_rule_id ~ '^[A-Za-z0-9_.:-]{3,160}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_obse_provider_configuration_id_check CHECK ((provider_configuration_id ~ '^[A-Za-z0-9_.:-]{1,160}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_obse_run_owned_rule_precedence_check CHECK (((run_owned_rule_precedence IS NULL) OR (run_owned_rule_precedence = 0))),
    CONSTRAINT vercel_writer_critical_waf_obser_provider_evidence_schema_check CHECK ((provider_evidence_schema = 'bagger-vercel-waf-provider-evidence-v1'::text)),
    CONSTRAINT vercel_writer_critical_waf_observ_candidate_deployment_id_check CHECK ((candidate_deployment_id ~ '^dpl_[A-Za-z0-9]{8,64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observa_candidate_alias_origin_check CHECK ((candidate_alias_origin ~ '^https://[a-z0-9.-]+$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observa_semantic_configuration_check CHECK ((jsonb_typeof(semantic_configuration) = 'object'::text)),
    CONSTRAINT vercel_writer_critical_waf_observa_signer_key_fingerprint_check CHECK ((signer_key_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observat_active_config_version_check CHECK ((active_config_version ~ '^[A-Za-z0-9_.:-]{1,160}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observati_candidate_commit_sha_check CHECK ((candidate_commit_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observati_evidence_fingerprint_check CHECK ((evidence_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observatio_record_payload_hash_check CHECK ((record_payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observatio_request_fingerprint_check CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observatio_run_owned_rule_name_check CHECK ((run_owned_rule_name ~ '^[A-Za-z0-9 _.,:/-]{8,160}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observation_active_config_etag_check CHECK (((active_config_etag IS NULL) OR ((btrim(active_config_etag) <> ''::text) AND (length(active_config_etag) <= 512)))),
    CONSTRAINT vercel_writer_critical_waf_observation_configuration_mode_check CHECK ((configuration_mode = ANY (ARRAY['BASELINE'::text, 'CRITICAL_WINDOW'::text]))),
    CONSTRAINT vercel_writer_critical_waf_observation_signer_key_version_check CHECK ((signer_key_version = 'STEP11_6_VERCEL_ATTESTER_V1'::text)),
    CONSTRAINT vercel_writer_critical_waf_observations_custom_rule_count_check CHECK ((custom_rule_count >= 0)),
    CONSTRAINT vercel_writer_critical_waf_observations_evidence_stage_check CHECK ((evidence_stage = ANY (ARRAY['BASELINE_CAPTURE'::text, 'CRITICAL_ACTIVE'::text, 'CRITICAL_REATTEST'::text, 'BASELINE_RESTORED'::text]))),
    CONSTRAINT vercel_writer_critical_waf_observations_provider_owner_id_check CHECK ((provider_owner_id ~ '^[A-Za-z0-9_.:-]{1,160}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_observations_purpose_check CHECK ((purpose = ANY (ARRAY['REHEARSAL'::text, 'CUTOVER'::text]))),
    CONSTRAINT vercel_writer_critical_waf_observations_transition_mode_check CHECK ((transition_mode = ANY (ARRAY['REHEARSAL'::text, 'CUTOVER'::text, 'ROLLBACK'::text]))),
    CONSTRAINT vercel_writer_critical_waf_observations_vercel_project_id_check CHECK ((vercel_project_id = 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'::text)),
    CONSTRAINT vercel_writer_critical_waf_observations_vercel_team_id_check CHECK ((vercel_team_id ~ '^team_[A-Za-z0-9]{8,80}$'::text))
);


ALTER TABLE production_control.vercel_writer_critical_waf_observations OWNER TO postgres;

--
-- Name: insert_vercel_writer_critical_waf_observation(uuid, jsonb, uuid, text, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.insert_vercel_writer_critical_waf_observation(target_epoch_id uuid, verified_evidence jsonb, target_record_request_id uuid, target_record_request_fingerprint text, target_record_payload_hash text, target_observation_id uuid DEFAULT NULL::uuid) RETURNS production_control.vercel_writer_critical_waf_observations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  reattestation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  prior production_control.vercel_writer_critical_waf_observations%rowtype;
  inserted production_control.vercel_writer_critical_waf_observations%rowtype;
  baseline_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  critical_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  observation_identifier uuid := coalesce(
    target_observation_id, extensions.gen_random_uuid()
  );
  stage_value text := pg_catalog.upper(
    coalesce(verified_evidence->>'stage', '')
  );
  evidence_identifier uuid;
  baseline_evidence_identifier uuid;
  critical_evidence_identifier uuid;
  provider_observed timestamptz;
  attested timestamptz;
  expires timestamptz;
begin
  if pg_catalog.jsonb_typeof(verified_evidence) is distinct from 'object'
     or (
       select pg_catalog.count(*)
       from pg_catalog.jsonb_object_keys(verified_evidence)
     ) <> 49
     or not (verified_evidence ?& array[
       'schemaVersion', 'evidenceId', 'evidenceRequestId', 'wafEpochId',
       'transitionRequestId', 'requestFingerprint', 'stage', 'purpose',
       'transitionMode',
       'vercelProjectId', 'vercelTeamId', 'candidateAliasOrigin',
       'candidateImmutableOrigin', 'candidateDeploymentId',
       'candidateCommitSha', 'candidateDeploymentTarget',
       'runOwnedRuleName', 'runOwnedRuleNonce',
       'runOwnedRuleFingerprint', 'runOwnedInsertDocumentFingerprint',
       'providerAssignedRuleId', 'baselineEvidenceId', 'criticalEvidenceId',
       'baselineConfigurationVersion',
       'baselineSourceVersionReadFingerprint',
       'configurationMode', 'configurationVersion', 'configurationEtag',
       'providerConfigurationId', 'providerOwnerId',
       'configurationIdentityFingerprint', 'semanticConfiguration',
       'semanticConfigurationFingerprint', 'orderedCustomRulesFingerprint',
       'baselineSemanticFingerprint', 'criticalSemanticFingerprint',
       'customRuleCount', 'runOwnedProviderRuleDocumentFingerprint',
       'runOwnedRulePrecedence', 'criticalWindowContractFingerprint',
       'pendingDraftChangeCount', 'providerObservedAt', 'attestedAt',
       'expiresAt', 'sourceVersionReadFingerprint', 'evidenceFingerprint',
       'signerKeyFingerprint',
       'signerKeyVersion', 'signatureVerified'
     ]::text[])
     or verified_evidence->>'schemaVersion' is distinct from
       'bagger-vercel-waf-provider-evidence-v1'
     or verified_evidence->'signatureVerified' is distinct from 'true'::jsonb
     or stage_value not in (
       'BASELINE_CAPTURE', 'CRITICAL_ACTIVE', 'CRITICAL_REATTEST',
       'BASELINE_RESTORED'
     )
     or pg_catalog.upper(coalesce(verified_evidence->>'transitionMode', ''))
       not in ('REHEARSAL', 'CUTOVER', 'ROLLBACK')
     or coalesce(verified_evidence->>'candidateDeploymentId', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(verified_evidence->>'candidateCommitSha', '')
       !~ '^[0-9a-f]{40}$'
     or verified_evidence->>'candidateDeploymentTarget' is distinct from
       'PREVIEW'
     or coalesce(verified_evidence->>'evidenceId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(verified_evidence->>'evidenceRequestId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(verified_evidence->>'wafEpochId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(verified_evidence->>'transitionRequestId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(verified_evidence->>'requestFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'evidenceFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'signerKeyFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or verified_evidence->>'signerKeyVersion' is distinct from
       'STEP11_6_VERCEL_ATTESTER_V1'
     or coalesce(verified_evidence->>'configurationIdentityFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'providerConfigurationId', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or coalesce(verified_evidence->>'providerOwnerId', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or coalesce(verified_evidence->>'semanticConfigurationFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'orderedCustomRulesFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'baselineSemanticFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'sourceVersionReadFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'runOwnedRuleFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'runOwnedInsertDocumentFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(verified_evidence->>'runOwnedRuleNonce', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.strpos(
       pg_catalog.lower(coalesce(verified_evidence->>'runOwnedRuleName', '')),
       pg_catalog.lower(verified_evidence->>'runOwnedRuleNonce')
     ) = 0
     or pg_catalog.jsonb_typeof(
       verified_evidence->'semanticConfiguration'
     ) is distinct from 'object'
     or (
       select pg_catalog.count(*)
       from pg_catalog.jsonb_object_keys(
         verified_evidence->'semanticConfiguration'
       )
     ) <> 7
     or not ((verified_evidence->'semanticConfiguration') ?& array[
       'schemaVersion', 'securityConfigurationKeys',
       'securityConfigurationKeysFingerprint', 'firewallEnabled', 'ips',
       'crs', 'orderedCustomRules'
     ]::text[])
     or coalesce(verified_evidence->>'providerObservedAt', '') = ''
     or coalesce(verified_evidence->>'attestedAt', '') = ''
     or coalesce(verified_evidence->>'expiresAt', '') = ''
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_EVIDENCE_INVALID';
  end if;

  evidence_identifier := (verified_evidence->>'evidenceId')::uuid;
  baseline_evidence_identifier :=
    nullif(verified_evidence->>'baselineEvidenceId', '')::uuid;
  critical_evidence_identifier :=
    nullif(verified_evidence->>'criticalEvidenceId', '')::uuid;
  provider_observed :=
    (verified_evidence->>'providerObservedAt')::timestamptz;
  attested := (verified_evidence->>'attestedAt')::timestamptz;
  expires := (verified_evidence->>'expiresAt')::timestamptz;

  select * into strict epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = target_epoch_id
  for update;
  select * into prior
  from production_control.vercel_writer_critical_waf_observations value
  where value.record_request_id = target_record_request_id;
  if found then
    if prior.epoch_id is distinct from target_epoch_id
       or prior.provider_evidence_id is distinct from evidence_identifier
       or prior.record_request_fingerprint is distinct from
         pg_catalog.lower(target_record_request_fingerprint)
       or prior.record_payload_hash is distinct from
         pg_catalog.lower(target_record_payload_hash)
       or prior.evidence_fingerprint is distinct from
         pg_catalog.lower(verified_evidence->>'evidenceFingerprint')
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_OBSERVATION_IDEMPOTENCY_CONFLICT';
    end if;
    return prior;
  end if;

  if (verified_evidence->>'wafEpochId')::uuid is distinct from epoch.epoch_id
     or verified_evidence->>'purpose' is distinct from epoch.purpose
     or verified_evidence->>'transitionMode' is distinct from
       epoch.transition_mode
     or verified_evidence->>'vercelProjectId' is distinct from
       epoch.vercel_project_id
     or verified_evidence->>'vercelTeamId' is distinct from epoch.vercel_team_id
     or pg_catalog.lower(verified_evidence->>'candidateAliasOrigin')
       is distinct from epoch.candidate_alias_origin
     or pg_catalog.lower(verified_evidence->>'candidateImmutableOrigin')
       is distinct from epoch.candidate_immutable_origin
     or verified_evidence->>'candidateDeploymentId' is distinct from
       epoch.candidate_deployment_id
     or pg_catalog.lower(verified_evidence->>'candidateCommitSha')
       is distinct from epoch.candidate_deployment_commit
     or verified_evidence->>'candidateDeploymentTarget' is distinct from
       epoch.candidate_deployment_target
     or verified_evidence->>'runOwnedRuleName' is distinct from
       epoch.run_owned_rule_name
     or verified_evidence->>'providerConfigurationId' is distinct from
       epoch.baseline_provider_configuration_id
     or verified_evidence->>'providerOwnerId' is distinct from
       epoch.baseline_provider_owner_id
     or (verified_evidence->>'runOwnedRuleNonce')::uuid is distinct from
       epoch.run_owned_rule_nonce
     or pg_catalog.lower(verified_evidence->>'runOwnedRuleFingerprint')
       is distinct from epoch.run_owned_rule_fingerprint
     or pg_catalog.lower(
       verified_evidence->>'runOwnedInsertDocumentFingerprint'
     ) is distinct from epoch.run_owned_insert_document_fingerprint
     or provider_observed is distinct from attested
     or provider_observed <
       pg_catalog.clock_timestamp() - interval '120 seconds'
     or provider_observed >
       pg_catalog.clock_timestamp() + interval '30 seconds'
     or expires is distinct from attested + interval '2100 seconds'
     or expires <= pg_catalog.clock_timestamp()
     or (verified_evidence->>'pendingDraftChangeCount')::integer <> 0
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_EVIDENCE_NOT_CURRENT';
  end if;

  select * into baseline_observation
  from production_control.vercel_writer_critical_waf_observations value
  where value.observation_id = epoch.baseline_observation_id;
  select * into critical_observation
  from production_control.vercel_writer_critical_waf_observations value
  where value.observation_id = epoch.critical_active_observation_id;

  if (stage_value = 'BASELINE_CAPTURE' and (
        epoch.status is distinct from 'ACTIVATION_PENDING'
        or baseline_evidence_identifier is not null
        or critical_evidence_identifier is not null
        or verified_evidence->>'baselineConfigurationVersion' is not null
        or verified_evidence->>'baselineSourceVersionReadFingerprint' is not null
        or verified_evidence->>'configurationMode' is distinct from 'BASELINE'
        or verified_evidence->>'providerAssignedRuleId' is not null
        or verified_evidence->>'criticalSemanticFingerprint' is not null
        or (verified_evidence->>'customRuleCount')::integer <> 0
        or verified_evidence->>'runOwnedProviderRuleDocumentFingerprint'
          is not null
        or verified_evidence->>'runOwnedRulePrecedence' is not null
        or pg_catalog.lower(
          verified_evidence->>'semanticConfigurationFingerprint'
        ) is distinct from epoch.baseline_semantic_configuration_fingerprint
        or pg_catalog.lower(
          verified_evidence->>'baselineSemanticFingerprint'
        ) is distinct from epoch.baseline_semantic_configuration_fingerprint
      ))
     or (stage_value = 'CRITICAL_ACTIVE' and (
        epoch.status is distinct from 'ACTIVATION_PENDING'
        or baseline_observation.observation_id is null
        or baseline_evidence_identifier is distinct from
          baseline_observation.provider_evidence_id
        or critical_evidence_identifier is not null
        or verified_evidence->>'baselineConfigurationVersion' is distinct from
          epoch.baseline_active_config_version
        or pg_catalog.lower(
          verified_evidence->>'baselineSourceVersionReadFingerprint'
        ) is distinct from epoch.baseline_source_version_read_fingerprint
        or pg_catalog.lower(
          verified_evidence->>'sourceVersionReadFingerprint'
        ) is distinct from epoch.baseline_source_version_read_fingerprint
        or verified_evidence->>'configurationMode' is distinct from
          'CRITICAL_WINDOW'
        or coalesce(verified_evidence->>'providerAssignedRuleId', '')
          !~ '^[A-Za-z0-9_.:-]{3,160}$'
        or verified_evidence->>'providerAssignedRuleId' is distinct from
          epoch.provider_assigned_rule_id
        or (verified_evidence->>'customRuleCount')::integer <> 1
        or coalesce(
          verified_evidence->>'runOwnedProviderRuleDocumentFingerprint', ''
        ) !~ '^[0-9a-f]{64}$'
        or (verified_evidence->>'runOwnedRulePrecedence')::integer <> 0
        or coalesce(
          verified_evidence->>'criticalWindowContractFingerprint', ''
        ) !~ '^[0-9a-f]{64}$'
        or pg_catalog.lower(
          verified_evidence->>'criticalSemanticFingerprint'
        ) is distinct from pg_catalog.lower(
          verified_evidence->>'semanticConfigurationFingerprint'
        )
      ))
     or (stage_value = 'CRITICAL_REATTEST' and (
        epoch.status not in ('FENCE_BOUND', 'RESTORE_PENDING')
        or baseline_observation.observation_id is null
        or critical_observation.observation_id is null
        or baseline_evidence_identifier is distinct from
          baseline_observation.provider_evidence_id
        or critical_evidence_identifier is distinct from
          critical_observation.provider_evidence_id
        or verified_evidence->>'baselineConfigurationVersion' is distinct from
          epoch.baseline_active_config_version
        or pg_catalog.lower(
          verified_evidence->>'baselineSourceVersionReadFingerprint'
        ) is distinct from epoch.baseline_source_version_read_fingerprint
        or pg_catalog.lower(
          verified_evidence->>'sourceVersionReadFingerprint'
        ) is distinct from epoch.baseline_source_version_read_fingerprint
        or verified_evidence->>'configurationMode' is distinct from
          'CRITICAL_WINDOW'
        or verified_evidence->>'providerAssignedRuleId' is distinct from
          epoch.provider_assigned_rule_id
        or (verified_evidence->>'customRuleCount')::integer <> 1
        or pg_catalog.lower(
          verified_evidence->>'semanticConfigurationFingerprint'
        ) is distinct from epoch.critical_semantic_configuration_fingerprint
        or pg_catalog.lower(
          verified_evidence->>'criticalSemanticFingerprint'
        ) is distinct from epoch.critical_semantic_configuration_fingerprint
      ))
     or (stage_value = 'BASELINE_RESTORED' and (
        epoch.status is distinct from 'RESTORE_PENDING'
        or baseline_observation.observation_id is null
        or critical_observation.observation_id is null
        or baseline_evidence_identifier is distinct from
          baseline_observation.provider_evidence_id
        or critical_evidence_identifier is distinct from
          critical_observation.provider_evidence_id
        or verified_evidence->>'baselineConfigurationVersion' is distinct from
          epoch.baseline_active_config_version
        or pg_catalog.lower(
          verified_evidence->>'baselineSourceVersionReadFingerprint'
        ) is distinct from epoch.baseline_source_version_read_fingerprint
        or pg_catalog.lower(
          verified_evidence->>'sourceVersionReadFingerprint'
        ) is distinct from epoch.baseline_source_version_read_fingerprint
        or verified_evidence->>'configurationMode' is distinct from 'BASELINE'
        or verified_evidence->>'providerAssignedRuleId' is not null
        or (verified_evidence->>'customRuleCount')::integer <> 0
        or verified_evidence->>'runOwnedProviderRuleDocumentFingerprint'
          is not null
        or verified_evidence->>'runOwnedRulePrecedence' is not null
        or pg_catalog.lower(
          verified_evidence->>'semanticConfigurationFingerprint'
        ) is distinct from epoch.baseline_semantic_configuration_fingerprint
        or pg_catalog.lower(
          verified_evidence->>'criticalSemanticFingerprint'
        ) is distinct from epoch.critical_semantic_configuration_fingerprint
      ))
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_EVIDENCE_SEMANTICS_MISMATCH';
  end if;

  insert into production_control.vercel_writer_critical_waf_observations (
    observation_id, epoch_id, provider_evidence_id, provider_evidence_schema,
    evidence_request_id, transition_request_id, evidence_stage,
    record_request_id, record_request_fingerprint, record_payload_hash,
    request_fingerprint, evidence_fingerprint, signer_key_fingerprint,
    signer_key_version, purpose, transition_mode,
    vercel_project_id, vercel_team_id,
    candidate_alias_origin, candidate_immutable_origin,
    candidate_deployment_id, candidate_commit_sha,
    candidate_deployment_target, configuration_mode,
    active_config_version, active_config_etag,
    provider_configuration_id, provider_owner_id,
    configuration_identity_fingerprint, semantic_configuration,
    semantic_configuration_fingerprint, ordered_rules_fingerprint,
    custom_rule_count, baseline_configuration_version,
    baseline_source_version_read_fingerprint,
    source_version_read_fingerprint, baseline_evidence_id,
    critical_evidence_id,
    baseline_semantic_fingerprint, critical_semantic_fingerprint,
    run_owned_rule_name, run_owned_rule_nonce, provider_assigned_rule_id,
    run_owned_rule_fingerprint, run_owned_insert_document_fingerprint,
    run_owned_provider_rule_document_fingerprint,
    run_owned_rule_precedence, critical_window_contract_fingerprint,
    pending_draft_change_count, provider_observed_at, attested_at, expires_at
  ) values (
    observation_identifier, epoch.epoch_id, evidence_identifier,
    verified_evidence->>'schemaVersion',
    (verified_evidence->>'evidenceRequestId')::uuid,
    (verified_evidence->>'transitionRequestId')::uuid, stage_value,
    target_record_request_id,
    pg_catalog.lower(target_record_request_fingerprint),
    pg_catalog.lower(target_record_payload_hash),
    pg_catalog.lower(verified_evidence->>'requestFingerprint'),
    pg_catalog.lower(verified_evidence->>'evidenceFingerprint'),
    pg_catalog.lower(verified_evidence->>'signerKeyFingerprint'),
    verified_evidence->>'signerKeyVersion', verified_evidence->>'purpose',
    verified_evidence->>'transitionMode',
    verified_evidence->>'vercelProjectId', verified_evidence->>'vercelTeamId',
    pg_catalog.lower(verified_evidence->>'candidateAliasOrigin'),
    pg_catalog.lower(verified_evidence->>'candidateImmutableOrigin'),
    verified_evidence->>'candidateDeploymentId',
    pg_catalog.lower(verified_evidence->>'candidateCommitSha'),
    verified_evidence->>'candidateDeploymentTarget',
    verified_evidence->>'configurationMode',
    verified_evidence->>'configurationVersion',
    nullif(verified_evidence->>'configurationEtag', ''),
    verified_evidence->>'providerConfigurationId',
    verified_evidence->>'providerOwnerId',
    pg_catalog.lower(
      verified_evidence->>'configurationIdentityFingerprint'
    ),
    verified_evidence->'semanticConfiguration',
    pg_catalog.lower(
      verified_evidence->>'semanticConfigurationFingerprint'
    ),
    pg_catalog.lower(verified_evidence->>'orderedCustomRulesFingerprint'),
    (verified_evidence->>'customRuleCount')::integer,
    nullif(verified_evidence->>'baselineConfigurationVersion', ''),
    nullif(pg_catalog.lower(
      verified_evidence->>'baselineSourceVersionReadFingerprint'
    ), ''),
    pg_catalog.lower(verified_evidence->>'sourceVersionReadFingerprint'),
    baseline_evidence_identifier, critical_evidence_identifier,
    pg_catalog.lower(verified_evidence->>'baselineSemanticFingerprint'),
    nullif(
      pg_catalog.lower(verified_evidence->>'criticalSemanticFingerprint'), ''
    ),
    verified_evidence->>'runOwnedRuleName',
    (verified_evidence->>'runOwnedRuleNonce')::uuid,
    nullif(verified_evidence->>'providerAssignedRuleId', ''),
    pg_catalog.lower(verified_evidence->>'runOwnedRuleFingerprint'),
    pg_catalog.lower(
      verified_evidence->>'runOwnedInsertDocumentFingerprint'
    ),
    nullif(pg_catalog.lower(
      verified_evidence->>'runOwnedProviderRuleDocumentFingerprint'
    ), ''),
    nullif(verified_evidence->>'runOwnedRulePrecedence', '')::integer,
    nullif(pg_catalog.lower(
      verified_evidence->>'criticalWindowContractFingerprint'
    ), ''),
    (verified_evidence->>'pendingDraftChangeCount')::integer,
    provider_observed, attested, expires
  ) returning * into inserted;
  return inserted;
end;
$_$;


ALTER FUNCTION production_control.insert_vercel_writer_critical_waf_observation(target_epoch_id uuid, verified_evidence jsonb, target_record_request_id uuid, target_record_request_fingerprint text, target_record_payload_hash text, target_observation_id uuid) OWNER TO postgres;

--
-- Name: inspect_expired_identity_recovery_v1(text, uuid, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.inspect_expired_identity_recovery_v1(target_player text, target_auth uuid, historical_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare u auth.users%rowtype; l participant_identity.user_player_links%rowtype;
 i participant_identity.participant_auth_identifiers%rowtype;
 c participant_identity.participant_identity_contacts%rowtype;
 a participant_identity.participant_auth_otp_attempts%rowtype;
 ph participant_identity.player_approved_phones_v1%rowtype;
 authority jsonb; state jsonb; email_hash text; completed boolean;
begin
 perform production_control.expired_identity_operator_guard_v1();
 if target_player not in ('HM01','NJ01') or target_player is null or target_auth is null or historical_request is null then
   raise exception 'EXPIRED_IDENTITY_TARGET_DENIED'; end if;
 select * into u from auth.users where id=target_auth;
 select * into l from participant_identity.user_player_links where auth_user_id=target_auth and player_id=target_player;
 select * into c from participant_identity.participant_identity_contacts where tournament_id='2026' and player_id=target_player;
 select * into i from participant_identity.participant_auth_identifiers where auth_user_id=target_auth and player_id=target_player
  and identifier_type='EMAIL' and status in ('VERIFICATION_PENDING','VERIFIED');
 select * into a from participant_identity.participant_auth_otp_attempts where request_id=historical_request;
 select * into ph from participant_identity.player_approved_phones_v1 where tournament_id='2026' and player_id=target_player;
 email_hash := encode(extensions.digest(c.email_normalized,'sha256'),'hex');
 if u.id is null or u.email_confirmed_at is null or u.deleted_at is not null
  or (u.banned_until is not null and u.banned_until>clock_timestamp())
  or coalesce(u.phone,'')<>'' or coalesce(u.phone_change,'')<>'' or u.phone_confirmed_at is not null
  or l.link_id is null or l.revoked_at is not null or l.status not in ('PENDING','ACTIVE')
  or i.identifier_id is null or i.revoked_at is not null
  or c.identity_active is distinct from true
  or lower(btrim(u.email)) is distinct from c.email_normalized
  or i.normalized_value_private is distinct from c.email_normalized
  or l.email_identity_hash is distinct from email_hash
  or u.raw_app_meta_data->>'player_id' is distinct from target_player
  or u.raw_app_meta_data->>'tournament_id' is distinct from '2026'
  or u.raw_app_meta_data->>'provisioning_scope' is distinct from 'production_controlled_first_login'
  or l.link_method is distinct from 'PRODUCTION_CONTROLLED_FIRST_LOGIN'
  or i.source_tournament_id is distinct from '2026'
  or i.source_configuration_revision is distinct from c.configuration_revision
  or ph.status is distinct from 'APPROVED' or ph.verified_at is not null
  or production_control.access_governance_global_status_v1(target_player) is distinct from 'ACTIVE'
 then raise exception 'EXPIRED_IDENTITY_CURRENT_AUTHORITY_DENIED'; end if;
 if not exists(select 1 from scoring_authority.tournament_players where tournament_id='2026' and player_id=target_player and participation_status='ACTIVE')
  or not exists(select 1 from participant_identity.identity_context_revisions r
   join participant_identity.identity_config_import_runs ir on ir.tournament_id=r.tournament_id
    and ir.configuration_revision=r.context_revision and ir.source_fingerprint=r.configuration_fingerprint
   join production_control.resource_scope rs on rs.scope_key='BAGGER_INV_PRODUCTION'
   where r.tournament_id='2026' and r.context_revision=c.configuration_revision and ir.status='APPROVED'
    and ir.approved_at is not null and c.source_workbook_id=rs.google_workbook_id)
  or not exists(select 1 from participant_identity.production_participant_enrollment_claims cl
   where cl.player_id=target_player and cl.auth_user_id=target_auth and cl.tournament_id='2026'
    and cl.status='CONSUMED' and cl.email_identity_hash=email_hash and cl.source_configuration_revision=c.configuration_revision)
  or exists(select 1 from participant_identity.account_deletion_requests_v1 where auth_user_id=target_auth)
  or exists(select 1 from participant_identity.tournament_roles where auth_user_id=target_auth and tournament_id='2026'
   and (not role_active or revoked_at is not null))
 then raise exception 'EXPIRED_IDENTITY_REVOKED_OR_STALE'; end if;
 -- Historical workflow binds provenance and the approved revision, never a new
 -- OTP success. Confirmation must predate review and follow this provisioning.
 if a.request_id is null or a.auth_user_id is distinct from target_auth or a.player_id is distinct from target_player
  or a.tournament_id is distinct from '2026' or a.verification_type is distinct from 'signup'
  or a.email_identity_hash is distinct from email_hash or a.status not in ('SENT','VERIFIED')
  or a.sent_at is null or a.requested_at>clock_timestamp()-interval '30 minutes'
  or u.email_confirmed_at<a.sent_at or u.email_confirmed_at>clock_timestamp()
 then raise exception 'EXPIRED_IDENTITY_HISTORY_DENIED'; end if;
 if (select count(*) from auth.users where lower(btrim(email))=c.email_normalized)<>1
  or exists(select 1 from auth.users where id<>target_auth and raw_app_meta_data->>'player_id'=target_player)
  or exists(select 1 from participant_identity.user_player_links where (auth_user_id=target_auth and player_id<>target_player)
   or (player_id=target_player and auth_user_id<>target_auth))
  or exists(select 1 from participant_identity.participant_identity_contacts where identity_active and email_normalized=c.email_normalized and player_id<>target_player)
  or exists(select 1 from participant_identity.participant_auth_identifiers where identifier_type='EMAIL'
   and normalized_value_private=c.email_normalized and (player_id<>target_player or auth_user_id<>target_auth))
  or exists(select 1 from participant_identity.player_approved_phones_v1 where status in ('APPROVED','VERIFIED')
   and phone_e164=ph.phone_e164 and player_id<>target_player)
  or exists(select 1 from participant_identity.participant_auth_identifiers where identifier_type='PHONE'
   and normalized_value_private=ph.phone_e164 and (player_id<>target_player or auth_user_id<>target_auth))
  or exists(select 1 from auth.users where id<>target_auth and
   (regexp_replace(coalesce(phone,''),'[^0-9]','','g')=regexp_replace(ph.phone_e164,'[^0-9]','','g')
    or regexp_replace(coalesce(phone_change,''),'[^0-9]','','g')=regexp_replace(ph.phone_e164,'[^0-9]','','g')))
 then raise exception 'EXPIRED_IDENTITY_COLLISION'; end if;
 completed := l.status='ACTIVE' and i.status='VERIFIED' and i.verified_at is not null
  and exists(select 1 from participant_identity.tournament_roles where tournament_id='2026' and auth_user_id=target_auth
   and role='PARTICIPANT' and role_active and revoked_at is null);
 if not completed and not(l.status='PENDING' and i.status='VERIFICATION_PENDING' and i.verified_at is null
   and a.status='SENT' and not exists(select 1 from participant_identity.tournament_roles where tournament_id='2026' and auth_user_id=target_auth))
 then raise exception 'EXPIRED_IDENTITY_NOT_INCOMPLETE'; end if;
 authority := jsonb_build_object('playerId',target_player,'authUserId',target_auth,'emailHash',email_hash,
  'historicalRequestId',historical_request,'linkId',l.link_id,'identifierId',i.identifier_id,
  'providerConfirmedAt',u.email_confirmed_at,'authCreatedAt',u.created_at,
  'contactHash',encode(extensions.digest(to_jsonb(c)::text,'sha256'),'hex'),
  'phoneHash',encode(extensions.digest(to_jsonb(ph)::text,'sha256'),'hex'),
  'contextHash',(select encode(extensions.digest(to_jsonb(r)::text,'sha256'),'hex') from participant_identity.identity_context_revisions r where tournament_id='2026'),
  'membershipHash',(select encode(extensions.digest(to_jsonb(t)::text,'sha256'),'hex') from scoring_authority.tournament_players t where tournament_id='2026' and player_id=target_player));
 state := jsonb_build_object('class','EXPIRED_PROVIDER_CONFIRMED_CERTIFICATION_PENDING','authority',authority,
  'state',case when completed then 'COMPLETE' else 'PENDING' end,
  'linkRevision',l.link_revision,'identifierRevision',i.revision);
 return state;
end $$;


ALTER FUNCTION production_control.inspect_expired_identity_recovery_v1(target_player text, target_auth uuid, historical_request uuid) OWNER TO postgres;

--
-- Name: install_certification_annual_reopened_generation_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.install_certification_annual_reopened_generation_v1(target_closure uuid, nextgen uuid, ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c production_control.scoring_admission_closures%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;e jsonb;
begin
 perform production_control.assert_certification_annual_cached_context_v1(ctx);
 if production_control.current_certification_context_v1() is distinct from ctx then
  raise exception using errcode='PT409',message='CANONICAL_RESOURCE_CONTEXT_STALE';end if;
 select * into strict c from production_control.scoring_admission_closures where closure_id=target_closure for update;
 select * into strict g from production_control.certification_ingress_generations_v1
  where resource_id=ctx->>'resource_id' and generation_id=c.admission_generation_id for update;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=g.resource_id for update;
 e:=production_control.certification_ingress_evidence_v1(g.resource_id,g.generation_id);
 if c.resource_class<>'CERTIFICATION' or c.certification_resource_id<>g.resource_id or c.status<>'REOPENED'
  or c.tournament_id<>p.tournament_id or g.tournament_id<>p.tournament_id or g.pointer_revision<>p.pointer_revision
  or g.authority_epoch_id::text is distinct from ctx->>'authority_epoch_id' or g.state<>'CLOSED'
  or nextgen is null or nextgen in(g.generation_id,g.authority_epoch_id)
  or not(e->>'drained')::boolean or not(e->>'fingerprint_matches')::boolean
  or not exists(select 1 from production_control.annual_scoring_transitions_v1 t
   join production_control.future_annual_runtime_generations_v1 f on f.runtime_generation_id=t.runtime_generation_id
   join production_control.future_tournament_catalog_v1 catalog on catalog.tournament_id=t.successor_tournament_id
   where t.resource_class='CERTIFICATION' and t.certification_resource_id=g.resource_id and t.predecessor_closure_id=c.closure_id
    and t.transition_status='ABORTED' and t.predecessor_tournament_id=p.tournament_id
    and t.expected_pointer_revision=p.pointer_revision and f.generation_status='ABORTED' and catalog.lifecycle='CONFIGURING') then
  raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_ABORT_NOT_SAFE';end if;
 if p.tournament_id<>'2026' and not exists(
  select 1 from production_control.annual_scoring_runtime_authorities_v1 a
  join production_control.future_annual_runtime_generations_v1 f using(runtime_generation_id)
  join participant_identity.future_tournament_identity_contexts_v1 i using(runtime_generation_id)
  join production_control.annual_side_game_runtime_certifications_v1 s using(runtime_generation_id)
  where a.tournament_id=p.tournament_id and a.resource_class='CERTIFICATION' and a.certification_resource_id=g.resource_id
   and a.authority_status='ACTIVE' and a.admission_state='OPEN' and a.admission_generation_id=nextgen
   and a.authority_generation_id=g.authority_epoch_id and a.pointer_revision=p.pointer_revision
   and f.generation_status='ACTIVE' and f.admission_generation_id=nextgen
   and i.status='CERTIFIED' and i.admission_generation_id=nextgen and s.admission_generation_id=nextgen
   and i.pointer_revision=p.pointer_revision and s.pointer_revision=p.pointer_revision) then
  raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_ABORT_REBIND_REQUIRED';end if;
 insert into production_control.certification_ingress_generations_v1(resource_id,generation_id,tournament_id,
  authority_epoch_id,pointer_revision,predecessor_generation_id)
 values(g.resource_id,nextgen,g.tournament_id,g.authority_epoch_id,g.pointer_revision,g.generation_id);
 update scoring_authority.ingress_gates set state='OPEN',admission_state='OPEN',admission_generation_id=nextgen,
  admission_revision=admission_revision+1,active_closure_id=null,updated_by=ctx#>>'{authorization,player_id}',updated_at=clock_timestamp()
 where tournament_id=p.tournament_id and authority='SUPABASE' and active_epoch_id=g.authority_epoch_id and state='PAUSED';
 if not found then raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_ABORT_NOT_SAFE';end if;
 update production_control.certification_admission_v1 set admission_revision=admission_revision+1
 where resource_id=g.resource_id and authority_epoch_id=g.authority_epoch_id
  and admission_revision=(ctx->>'admission_revision')::bigint;
 if not found then raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_ABORT_NOT_SAFE';end if;
 insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,result,details)
 values('CERTIFICATION_ANNUAL_ADMISSION_REOPENED','ANNUAL',g.tournament_id,ctx#>>'{authorization,player_id}','SUCCEEDED',
  jsonb_build_object('resource_id',g.resource_id,'closure_id',c.closure_id,'closed_generation_id',g.generation_id,
   'new_generation_id',nextgen,'authority_epoch_id',g.authority_epoch_id,'pointer_revision',g.pointer_revision,
   'closed_fingerprint',e->>'fingerprint','old_generation_reopened',false));
end;$$;


ALTER FUNCTION production_control.install_certification_annual_reopened_generation_v1(target_closure uuid, nextgen uuid, ctx jsonb) OWNER TO postgres;

--
-- Name: install_certification_annual_successor_v1(uuid, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.install_certification_annual_successor_v1(target_transition uuid, ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare t production_control.annual_scoring_transitions_v1%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;
 a production_control.annual_scoring_runtime_authorities_v1%rowtype;
 f production_control.future_annual_runtime_generations_v1%rowtype;
 c production_control.scoring_admission_closures%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;
 e jsonb;fingerprint text;
begin
 perform production_control.assert_certification_annual_cached_context_v1(ctx);
 select * into strict t from production_control.annual_scoring_transitions_v1 where transition_id=target_transition for update;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=ctx->>'resource_id' for update;
 select * into strict a from production_control.annual_scoring_runtime_authorities_v1 where runtime_generation_id=t.runtime_generation_id for update;
 select * into strict f from production_control.future_annual_runtime_generations_v1 where runtime_generation_id=t.runtime_generation_id for update;
 select * into strict c from production_control.scoring_admission_closures where closure_id=t.predecessor_closure_id for update;
 select * into strict g from production_control.certification_ingress_generations_v1
  where resource_id=ctx->>'resource_id' and generation_id=c.admission_generation_id for update;
 e:=production_control.certification_ingress_evidence_v1(g.resource_id,g.generation_id);
 if t.resource_class<>'CERTIFICATION' or t.certification_resource_id is distinct from ctx->>'resource_id'
  or t.transition_status<>'COMMITTED' or t.predecessor_tournament_id is distinct from ctx->>'current_tournament_id'
  or t.expected_pointer_revision::text is distinct from ctx->>'pointer_revision'
  or p.tournament_id<>t.successor_tournament_id or p.pointer_revision<>t.expected_pointer_revision+1
  or f.generation_status<>'ACTIVE' or f.tournament_id<>p.tournament_id or f.pointer_revision<>p.pointer_revision
  or f.authority_generation_id<>t.authority_generation_id or f.admission_generation_id<>t.admission_generation_id
  or a.resource_class<>'CERTIFICATION' or a.certification_resource_id<>g.resource_id
  or a.authority_status<>'ACTIVE' or a.admission_state<>'OPEN'
  or a.tournament_id<>p.tournament_id or a.pointer_revision<>p.pointer_revision or a.lifecycle_revision<>p.lifecycle_revision
  or a.authority_generation_id<>f.authority_generation_id or a.admission_generation_id<>f.admission_generation_id
  or a.predecessor_closure_id<>c.closure_id or a.predecessor_boundary_fingerprint<>t.predecessor_boundary_fingerprint
  or c.resource_class<>'CERTIFICATION' or c.certification_resource_id<>g.resource_id or c.status<>'CLOSED'
  or c.tournament_id<>g.tournament_id or c.authority_generation_id<>g.authority_epoch_id
  or c.closed_admission_revision<>g.revision or c.lease_high_watermark is distinct from g.high_watermark
  or c.lease_set_fingerprint is distinct from e->>'fingerprint'
  or g.state<>'CLOSED' or g.tournament_id<>t.predecessor_tournament_id
  or g.authority_epoch_id::text is distinct from ctx->>'authority_epoch_id'
  or not(e->>'drained')::boolean or not(e->>'fingerprint_matches')::boolean
  or not exists(select 1 from participant_identity.future_tournament_identity_contexts_v1 i
   where i.tournament_id=f.tournament_id and i.status='CERTIFIED' and i.runtime_generation_id=f.runtime_generation_id
    and i.authority_generation_id=f.authority_generation_id and i.admission_generation_id=f.admission_generation_id
    and i.pointer_revision=f.pointer_revision)
  or not exists(select 1 from production_control.annual_side_game_runtime_certifications_v1 s
   where s.runtime_generation_id=f.runtime_generation_id and s.admission_generation_id=f.admission_generation_id
    and s.authority_generation_id=f.authority_generation_id and s.pointer_revision=f.pointer_revision)
  or exists(select 1 from production_control.certification_ingress_generations_v1 x
   where x.resource_id=g.resource_id and x.state in('OPEN','CLOSING')) then
  raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_SUCCESSOR_INSTALL_CONFLICT';end if;
 fingerprint:=production_control.future_runtime_hash_v2(jsonb_build_object('resource_id',g.resource_id,
  'transition_id',t.transition_id,'predecessor_closure_id',c.closure_id,'predecessor_lease_fingerprint',e->>'fingerprint',
  'runtime_generation_id',f.runtime_generation_id,'authority_epoch_id',f.authority_generation_id,
  'admission_generation_id',f.admission_generation_id,'pointer',to_jsonb(p)));
 insert into scoring_authority.authority_epochs(epoch_id,tournament_id,epoch_type,status,authority_before,authority_after,
  reconciliation_fingerprint,google_checkpoints,supabase_match_revisions,deployment_commit,actor_id,reason,committed_at,boundary_mode)
 values(f.authority_generation_id,f.tournament_id,'CERTIFICATION_ANNUAL_TRANSITION','COMMITTED','SUPABASE','SUPABASE',
  fingerprint,'{}',production_control.current_match_revisions(f.tournament_id),ctx->>'release_commit',
  ctx#>>'{authorization,player_id}','Canonical Certification annual transition; no external provider authority',clock_timestamp(),'CERTIFICATION_INGRESS_V1');
 insert into production_control.certification_ingress_generations_v1(resource_id,generation_id,tournament_id,
  authority_epoch_id,pointer_revision,predecessor_generation_id)
 values(g.resource_id,f.admission_generation_id,f.tournament_id,f.authority_generation_id,f.pointer_revision,g.generation_id);
 insert into scoring_authority.ingress_gates(tournament_id,state,authority,active_epoch_id,unresolved_client_queues,
  updated_by,admission_generation_id,admission_state,admission_revision,boundary_mode)
 values(f.tournament_id,'OPEN','SUPABASE',f.authority_generation_id,0,ctx#>>'{authorization,player_id}',
  f.admission_generation_id,'OPEN',1,'CERTIFICATION_INGRESS_V1');
 -- Legacy Production protocol fields stay false/null, as on initial
 -- Certification authority. The resource-local durable generation above owns
 -- Certification enforcement; no Production provider evidence is fabricated.
 -- No helper that revalidates the old current context may run after this final
 -- admission update. Wrapper pops its exact original marker without rebinding.
 update production_control.certification_admission_v1 set authority_epoch_id=f.authority_generation_id,
  activation_revision=activation_revision+1,admission_revision=admission_revision+1
 where resource_id=g.resource_id and authority_epoch_id=g.authority_epoch_id
  and admission_revision=(ctx->>'admission_revision')::bigint;
 if not found then raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_SUCCESSOR_INSTALL_CONFLICT';end if;
 insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,result,details)
 values('CERTIFICATION_ANNUAL_GENERATION_INSTALLED','ANNUAL',f.tournament_id,ctx#>>'{authorization,player_id}','SUCCEEDED',
  jsonb_build_object('resource_id',g.resource_id,'transition_id',t.transition_id,'prior_generation_id',g.generation_id,
   'generation_id',f.admission_generation_id,'authority_epoch_id',f.authority_generation_id,
   'pointer_revision',f.pointer_revision,'source_fingerprint',fingerprint));
exception when no_data_found then raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_SUCCESSOR_INSTALL_CONFLICT';
end;$$;


