--
-- Name: legacy_course_adoption_holes_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.legacy_course_adoption_holes_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  value jsonb;
  result_value jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(input) is distinct from 'array'
     or jsonb_array_length(input) <> 18 then return null; end if;
  for value in select item from jsonb_array_elements(input) item loop
    if jsonb_typeof(value) is distinct from 'object'
       or coalesce(value->>'hole_number', '') !~ '^[0-9]+$'
       or coalesce(value->>'par', '') !~ '^[0-9]+$'
       or coalesce(value->>'stroke_index', '') !~ '^[0-9]+$'
       or not (value ? 'yardage')
       or (value->>'yardage' is not null
         and value->>'yardage' !~ '^[0-9]+$')
       or (value->>'hole_number')::integer not between 1 and 18
       or (value->>'par')::integer not between 3 and 6
       or (value->>'stroke_index')::integer not between 1 and 18
       or (value->>'yardage')::integer not between 1 and 999 then
      return null;
    end if;
    result_value := result_value || jsonb_build_array(jsonb_build_object(
      'hole_number', (value->>'hole_number')::integer,
      'par', (value->>'par')::integer,
      'stroke_index', (value->>'stroke_index')::integer,
      'yardage', (value->>'yardage')::integer
    ));
  end loop;
  if (select count(distinct item->>'hole_number') from jsonb_array_elements(result_value) item) <> 18
     or (select count(distinct item->>'stroke_index') from jsonb_array_elements(result_value) item) <> 18 then
    return null;
  end if;
  return (select jsonb_agg(item order by (item->>'hole_number')::integer)
    from jsonb_array_elements(result_value) item);
exception when invalid_text_representation or numeric_value_out_of_range then
  return null;
end;
$_$;


ALTER FUNCTION production_control.legacy_course_adoption_holes_v1(input jsonb) OWNER TO postgres;

--
-- Name: lock_certification_odds_source_v1(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.lock_certification_odds_source_v1(target text, context jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if context is distinct from production_control.current_certification_context_v1()
  or context->>'resource_class'is distinct from'CERTIFICATION'
  or context->>'tournament_id'is distinct from target then
  raise exception using errcode='42501',message='CERTIFICATION_ODDS_CONTEXT_REQUIRED';end if;
 if target='2026'then
  -- Initial setup has the legacy shared admission fence and these canonical
  -- authoring locks. Preserve its existing access -> setup -> match ordering.
  perform pg_advisory_xact_lock(hashtextextended('production-access-governance-v1:2026',0));
  perform pg_advisory_xact_lock(hashtextextended('production-tournament-setup-v1:2026',0));
 end if;
 perform 1 from scoring_authority.matches m where m.tournament_id=target order by m.match_id for share;
 perform 1 from scoring_authority.participant_home_presentations p where p.tournament_id=target for share;
end;$$;


ALTER FUNCTION production_control.lock_certification_odds_source_v1(target text, context jsonb) OWNER TO postgres;

--
-- Name: lock_net_skins_storylines_v1(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.lock_net_skins_storylines_v1(target text, input jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare current_tournament text; generation_id uuid; job_value scoring_authority.net_skins_v1_recalculation_jobs%rowtype;
 result_revision_value bigint;
begin
 -- The caller already validated runtime, receipt replay and input shape. Repeat
 -- the result trigger's current-tournament/admission boundary before any write.
 perform pg_advisory_xact_lock_shared(production_control.scoring_admission_lock_key());
 select tournament_id into strict current_tournament from production_control.current_tournament_pointer_v1
 where scope_key=production_control.canonical_execution_resource_id_v1();
 if target<>current_tournament then return; end if;
 if target='2026' then
  if not exists(select 1 from scoring_authority.ingress_gates where tournament_id=target and state='OPEN' and authority='SUPABASE') then
   raise exception using errcode='55000',message='PRODUCTION_ANNUAL_DERIVED_ADMISSION_CLOSED';
  end if;
 else
  select runtime_generation_id into generation_id from production_control.annual_scoring_runtime_authorities_v1
  where tournament_id=target and authority_status='ACTIVE' and admission_state='OPEN';
  if generation_id is null then raise exception using errcode='55000',message='PRODUCTION_ANNUAL_DERIVED_RUNTIME_REQUIRED'; end if;
 end if;
 perform 1 from scoring_authority.competition_recalculation_jobs
 where tournament_id=target and round_number=0 and engine_key='TOURNAMENT_STORYLINES' for update;
 if found then return; end if;
 -- Read only: taking a job/config lock here would recreate the inverse order.
 -- Invalid identity leaves the original completion guards to reject unchanged.
 select j.* into job_value from scoring_authority.net_skins_v1_recalculation_jobs j
 join scoring_authority.net_skins_v1_configuration_current c on c.tournament_id=j.tournament_id
 where j.job_id=(input->>'job_id')::uuid and j.tournament_id=target and j.status='RUNNING'
  and j.claim_token=(input->>'claim_token')::uuid and j.claimed_by=btrim(input->>'worker_id')
  and j.lease_expires_at>case when target='2026' then now() else clock_timestamp() end
  and j.configuration_revision=c.configuration_revision and c.state='CONFIGURED'
  and c.configuration_revision=(input->>'expected_configuration_revision')::bigint
  and (target='2026' or (j.runtime_generation_id=generation_id and generation_id=(input->>'expected_runtime_generation_id')::uuid));
 if not found then return; end if;
 select coalesce(max(result_revision),0)+1 into result_revision_value
 from scoring_authority.net_skins_v1_result_revisions where tournament_id=target and round_number=job_value.round_number;
 insert into scoring_authority.competition_recalculation_jobs(
  tournament_id,round_number,engine_key,status,requested_source_revision,requested_at,
  started_at,completed_at,last_error_code,last_error_safe,runtime_generation_id,claim_token,claimed_by,lease_expires_at,updated_at)
 values(target,0,'TOURNAMENT_STORYLINES','PENDING',jsonb_build_object(
  'reason','NET_SKINS_CURRENT_RESULT_CHANGED','revision',jsonb_build_object('roundNumber',job_value.round_number,
   'resultRevision',result_revision_value,'payloadHash',production_control.net_skins_v1_hash(input->'result_payload'),'isCurrent',true),
  'transactional',true),clock_timestamp(),null,null,null,null,generation_id,null,null,null,clock_timestamp())
 on conflict(tournament_id,round_number,engine_key) do nothing;
 perform 1 from scoring_authority.competition_recalculation_jobs
 where tournament_id=target and round_number=0 and engine_key='TOURNAMENT_STORYLINES' for update;
end;
$$;


ALTER FUNCTION production_control.lock_net_skins_storylines_v1(target text, input jsonb) OWNER TO postgres;

--
-- Name: lookup_annual_scoring_receipt_v1(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.lookup_annual_scoring_receipt_v1(operation_value text, input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  request_id uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash', ''
  )));
  computed_hash text := production_control.future_runtime_hash_v2(
    input - 'request_payload_hash'
  );
  receipt production_control.annual_scoring_transition_receipts_v1%rowtype;
begin
  begin request_id := (input->>'operation_request_id')::uuid;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ANNUAL_SCORING_OPERATION_REQUEST_INVALID';
  end;
  if declared_hash !~ '^[0-9a-f]{64}$'
     or declared_hash <> computed_hash then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ANNUAL_SCORING_PAYLOAD_HASH_INVALID';
  end if;
  select value.* into receipt
  from production_control.annual_scoring_transition_receipts_v1 value
  where value.operation = operation_value
    and value.operation_request_id = request_id;
  if receipt.operation_request_id is null then return null; end if;
  if receipt.request_payload_hash <> computed_hash then
    raise exception using errcode = '23505',
      message = 'PRODUCTION_ANNUAL_SCORING_IDEMPOTENCY_CONFLICT';
  end if;
  return receipt.response || pg_catalog.jsonb_build_object(
    'idempotent', true
  );
end;
$_$;


ALTER FUNCTION production_control.lookup_annual_scoring_receipt_v1(operation_value text, input jsonb) OWNER TO postgres;

--
-- Name: lookup_canonical_annual_scoring_receipt_v2(text, jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.lookup_canonical_annual_scoring_receipt_v2(operation_value text, input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare result jsonb;r production_control.annual_scoring_transition_receipts_v1%rowtype;
begin
 if context->>'resource_class'='PRODUCTION' then
  return production_control.lookup_annual_scoring_receipt_v1(operation_value,input);
 end if;
 if coalesce(input->>'request_payload_hash','')!~'^[0-9a-f]{64}$'
  or input->>'request_payload_hash' is distinct from production_control.future_runtime_hash_v2(input-'request_payload_hash') then
  raise exception using errcode='22023',message='PRODUCTION_ANNUAL_SCORING_PAYLOAD_HASH_INVALID';end if;
 -- No receipt-existence/payload-conflict oracle before origin is established.
 select * into r from production_control.annual_scoring_transition_receipts_v1
 where operation=operation_value and operation_request_id=(input->>'operation_request_id')::uuid;
 if not found then return null;end if;
 if r.certification_resource_id is distinct from context->>'resource_id'
  or r.certification_actor_player_id is distinct from context#>>'{authorization,player_id}'
  or r.certification_actor_auth_user_id::text is distinct from context#>>'{authorization,auth_user_id}'then
  return null;
 end if;
 result:=production_control.lookup_annual_scoring_receipt_v1(operation_value,input);
 return result;
end;$_$;


ALTER FUNCTION production_control.lookup_canonical_annual_scoring_receipt_v2(operation_value text, input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: lookup_cutover_receipt(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.lookup_cutover_receipt(requested_operation text, input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $_$
declare
  fingerprint text := lower(coalesce(input->>'request_fingerprint', ''));
  input_hash text := production_control.cutover_payload_hash(input);
  receipt production_control.cutover_operation_receipts%rowtype;
begin
  if fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_REQUEST_FINGERPRINT_INVALID';
  end if;
  select * into receipt
  from production_control.cutover_operation_receipts
  where request_fingerprint = fingerprint;
  if not found then return null; end if;
  if receipt.operation <> requested_operation or receipt.payload_hash <> input_hash then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_IDEMPOTENCY_CONFLICT';
  end if;
  return receipt.response || jsonb_build_object('idempotent', true);
end;
$_$;


ALTER FUNCTION production_control.lookup_cutover_receipt(requested_operation text, input jsonb) OWNER TO postgres;

--
-- Name: mark_certification_read_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mark_certification_read_v1(value jsonb, context jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 select value||jsonb_build_object('authoritative',true,'shadow_only',false,'google_foreground_requests',0,
 'fallback_used',false,'resource_class','CERTIFICATION','activation_revision',context->'activation_revision',
 'deployment_commit',context->>'release_commit')
$$;


ALTER FUNCTION production_control.mark_certification_read_v1(value jsonb, context jsonb) OWNER TO postgres;

--
-- Name: mark_cutover_read_response(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mark_cutover_read_response(response_value jsonb, required_phase text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
begin
  select * into strict activation from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';
  return coalesce(response_value, '{}'::jsonb) || jsonb_build_object(
    'authoritative', true, 'shadow_only', false,
    'google_foreground_requests', 0, 'fallback_used', false,
    'cutover_phase', activation.read_cutover_phase,
    'required_phase', upper(required_phase),
    'activation_revision', activation.activation_revision,
    'deployment_commit', activation.expected_deployment_commit,
    'first_supabase_canonical_write_observed',
      activation.first_supabase_write_observed_at is not null
  );
end;
$$;


ALTER FUNCTION production_control.mark_cutover_read_response(response_value jsonb, required_phase text) OWNER TO postgres;

--
-- Name: mark_projection_operation_response(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mark_projection_operation_response(response_value jsonb, expected_domain text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  resource production_control.resource_scope%rowtype;
begin
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  if not resource.public_supabase_reads_enabled then
    return response_value;
  end if;
  return production_control.mark_cutover_read_response(
    response_value,
    production_control.projection_required_phase(expected_domain)
  );
end;
$$;


ALTER FUNCTION production_control.mark_projection_operation_response(response_value jsonb, expected_domain text) OWNER TO postgres;

--
-- Name: mask_player_access_email_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mask_player_access_email_v1(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select case when pg_catalog.btrim(coalesce(value, '')) = '' then null
    else pg_catalog.left(pg_catalog.split_part(value, '@', 1), 1)
      || '***@'
      || pg_catalog.left(pg_catalog.split_part(value, '@', 2), 1)
      || '***.'
      || pg_catalog.reverse(pg_catalog.split_part(
        pg_catalog.reverse(pg_catalog.split_part(value, '@', 2)), '.', 1
      ))
    end
$$;


ALTER FUNCTION production_control.mask_player_access_email_v1(value text) OWNER TO postgres;

--
-- Name: mask_player_access_phone_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mask_player_access_phone_v1(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  select case when value ~ '^\+[1-9][0-9]{7,14}$'
    then '+••• ••• ••' || pg_catalog.right(value, 2)
    else null end
$_$;


ALTER FUNCTION production_control.mask_player_access_phone_v1(value text) OWNER TO postgres;

--
-- Name: match_resume_context_hash_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.match_resume_context_hash_v1(target_match_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
 select production_control.cutover_payload_hash(jsonb_build_object(
   'match_id', m.match_id, 'tournament_id', m.tournament_id,
   'round_number', m.round_number, 'format', m.format,
   'snapshot', to_jsonb(s),
   'participants', (select jsonb_agg(to_jsonb(p) order by p.team_side,p.player_slot)
     from scoring_authority.match_participants p where p.match_id=m.match_id),
   'holes', (select jsonb_agg(to_jsonb(h) order by h.hole_number)
     from scoring_authority.match_holes h where h.match_id=m.match_id),
   'approved_handicaps', (select jsonb_agg(to_jsonb(e) order by e.player_id)
     from scoring_authority.handicap_revision_entries e where e.revision_id=s.handicap_revision_id
       and e.player_id in(select p.player_id from scoring_authority.match_participants p where p.match_id=m.match_id)),
   'setup', (select jsonb_build_object('course_id',d.course_id,'tee_id',d.tee_id,
     'setup_revision',d.setup_revision,'prepared_setup_revision',d.prepared_setup_revision,
     'fingerprint',d.prepared_configuration_fingerprint)
     from scoring_authority.tournament_setup_match_details_v1 d where d.match_id=m.match_id)
 )) from scoring_authority.matches m join scoring_authority.scoring_snapshots s
 on s.snapshot_id=m.scoring_snapshot_id and s.match_id=m.match_id and s.tournament_id=m.tournament_id
 where m.match_id=target_match_id and m.tournament_id='2026'
$$;


ALTER FUNCTION production_control.match_resume_context_hash_v1(target_match_id text) OWNER TO postgres;

--
-- Name: match_scoring_context_readiness_v1(text, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.match_scoring_context_readiness_v1(target_match_id text, allow_scoring_activity boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  reasons jsonb := '[]'::jsonb;
  match_value scoring_authority.matches%rowtype;
  round_value scoring_authority.rounds%rowtype;
  detail_value scoring_authority.tournament_setup_match_details_v1%rowtype;
  assignment_value scoring_authority.tournament_setup_round_courses_v1%rowtype;
  course_value scoring_authority.tournament_setup_course_tees_v1%rowtype;
  snapshot_value scoring_authority.scoring_snapshots%rowtype;
  current_handicap uuid;
  holes_value jsonb;
  match_holes_value jsonb;
  context_value jsonb;
  current_participant_values jsonb;
  expected_count integer;
  participant_count integer;
begin
  select value.* into match_value
  from scoring_authority.matches value
  where value.tournament_id = '2026'
    and value.match_id = target_match_id;
  if match_value.match_id is null then
    return pg_catalog.jsonb_build_object(
      'ready', false,
      'contractVersion', 'production-match-scoring-readiness-v1',
      'matchId', target_match_id,
      'reasons', pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'MATCH_NOT_FOUND',
          'message', 'The canonical Production match does not exist.'
        )
      )
    );
  end if;

  select value.* into round_value
  from scoring_authority.rounds value
  where value.tournament_id = '2026'
    and value.round_number = match_value.round_number;
  if round_value.tournament_id is null
     or round_value.round_number not between 1 and 3
     or round_value.format not in ('BB', 'SC', 'SI')
     or round_value.format is distinct from match_value.format then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_CONFIGURATION_INVALID',
        'message', 'The match does not match its canonical round configuration.'
      )
    );
  end if;

  select value.* into snapshot_value
  from scoring_authority.scoring_snapshots value
  where value.snapshot_id = match_value.scoring_snapshot_id
    and value.tournament_id = '2026'
    and value.match_id = target_match_id;
  if snapshot_value.snapshot_id is null
     or snapshot_value.snapshot_revision is distinct from (
       select pg_catalog.max(candidate.snapshot_revision)
       from scoring_authority.scoring_snapshots candidate
       where candidate.match_id = target_match_id
     ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_SNAPSHOT_NOT_CURRENT',
        'message', 'The match needs its latest scoring snapshot prepared.'
      )
    );
  end if;

  select value.* into detail_value
  from scoring_authority.tournament_setup_match_details_v1 value
  where value.tournament_id = '2026'
    and value.match_id = target_match_id;
  if detail_value.match_id is not null then
    if detail_value.round_number is distinct from match_value.round_number
       or detail_value.prepared_setup_revision is distinct from
         detail_value.setup_revision
       or detail_value.prepared_configuration_fingerprint is null then
      reasons := reasons || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'SETUP_SNAPSHOT_STALE',
          'message', 'The match setup changed after its scoring snapshot was prepared.'
        )
      );
    end if;
    select value.* into assignment_value
    from scoring_authority.tournament_setup_round_courses_v1 value
    where value.tournament_id = '2026'
      and value.round_number = match_value.round_number;
    if assignment_value.tournament_id is null
       or assignment_value.course_id is distinct from detail_value.course_id
       or assignment_value.tee_id is distinct from detail_value.tee_id then
      reasons := reasons || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'ROUND_COURSE_ASSIGNMENT_INVALID',
          'message', 'The match course and tee do not match the round assignment.'
        )
      );
    end if;
    select value.* into course_value
    from scoring_authority.tournament_setup_course_tees_v1 value
    where value.tournament_id = '2026'
      and value.course_id = detail_value.course_id
      and value.tee_id = detail_value.tee_id;
    select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'hole_number', hole.hole_number,
      'par', hole.par,
      'stroke_index', hole.stroke_index,
      'yardage', hole.yardage
    ) order by hole.hole_number) into holes_value
    from scoring_authority.tournament_setup_course_holes_v1 hole
    where hole.tournament_id = '2026'
      and hole.course_id = detail_value.course_id
      and hole.tee_id = detail_value.tee_id;
  else
    -- Migration installation is inert. Existing certified snapshots remain the
    -- canonical setup source until a Director explicitly edits this match.
    course_value.tournament_id := '2026';
    course_value.course_id := snapshot_value.course_id;
    course_value.tee_id := snapshot_value.tee;
    course_value.rating := snapshot_value.rating;
    course_value.slope := snapshot_value.slope;
    course_value.par := snapshot_value.par;
    holes_value := snapshot_value.hole_definitions;
  end if;
  if course_value.tournament_id is null
     or course_value.rating is null
     or course_value.slope not between 55 and 155
     or course_value.par not between 54 and 90 then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'COURSE_CONFIGURATION_INVALID',
        'message', 'The match course and tee scoring facts are incomplete.'
      )
    );
  end if;
  if pg_catalog.jsonb_typeof(holes_value) is distinct from 'array'
     or pg_catalog.jsonb_array_length(coalesce(holes_value, '[]'::jsonb)) <> 18
     or (select pg_catalog.count(distinct (hole->>'hole_number')::integer)
       from pg_catalog.jsonb_array_elements(coalesce(holes_value, '[]'::jsonb)) hole)
       <> 18
     or (select pg_catalog.count(distinct (hole->>'stroke_index')::integer)
       from pg_catalog.jsonb_array_elements(coalesce(holes_value, '[]'::jsonb)) hole)
       <> 18
     or (select pg_catalog.sum((hole->>'par')::integer)
       from pg_catalog.jsonb_array_elements(coalesce(holes_value, '[]'::jsonb)) hole)
       is distinct from course_value.par then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'COURSE_HOLES_INCOMPLETE',
        'message', 'The course requires 18 complete, valid hole definitions.'
      )
    );
  end if;
  if snapshot_value.snapshot_id is not null and (
       snapshot_value.format is distinct from match_value.format
       or snapshot_value.handicap_allowance is distinct from
         round_value.handicap_allowance
       or snapshot_value.course_id is distinct from course_value.course_id
       or snapshot_value.tee is distinct from course_value.tee_id
       or snapshot_value.rating is distinct from course_value.rating
       or snapshot_value.slope is distinct from course_value.slope
       or snapshot_value.par is distinct from course_value.par
       or snapshot_value.hole_definitions is distinct from holes_value
     ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_SNAPSHOT_CONFIGURATION_STALE',
        'message', 'The scoring snapshot no longer matches the current setup facts.'
      )
    );
  end if;

  expected_count := case when match_value.format = 'SI' then 2 else 4 end;
  select pg_catalog.count(*)::integer into participant_count
  from scoring_authority.match_participants participant
  where participant.match_id = target_match_id;
  if participant_count <> expected_count
     or (select pg_catalog.count(distinct participant.player_id)
       from scoring_authority.match_participants participant
       where participant.match_id = target_match_id) <> expected_count
     or (select pg_catalog.count(*)
       from scoring_authority.match_participants participant
       where participant.match_id = target_match_id and participant.team_side = 1)
       <> expected_count / 2
     or (select pg_catalog.count(*)
       from scoring_authority.match_participants participant
       where participant.match_id = target_match_id and participant.team_side = 2)
       <> expected_count / 2 then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PAIRINGS_INCOMPLETE',
        'message', 'The match requires complete, unique Player pairings.'
      )
    );
  end if;
  if exists (
    select 1
    from scoring_authority.match_participants participant
    left join scoring_authority.tournament_players membership
      on membership.tournament_id = '2026'
     and membership.player_id = participant.player_id
    left join scoring_authority.teams team
      on team.tournament_id = membership.tournament_id
     and team.team_id = membership.team_id
     and team.team_side = membership.team_side
    where participant.match_id = target_match_id
      and (membership.player_id is null
        or membership.participation_status <> 'ACTIVE'
        or membership.team_side <> participant.team_side
        or team.team_id is null)
  ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PAIRING_TEAM_MEMBERSHIP_INVALID',
        'message', 'A paired Player does not have the required active team membership.'
      )
    );
  end if;
  if exists (
    select 1
    from scoring_authority.match_participants participant
    join scoring_authority.matches other_match
      on other_match.match_id = participant.match_id
     and other_match.tournament_id = '2026'
     and other_match.round_number = match_value.round_number
    where participant.player_id in (
      select current_participant.player_id
      from scoring_authority.match_participants current_participant
      where current_participant.match_id = target_match_id
    )
    group by participant.player_id
    having pg_catalog.count(*) > 1
  ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_DUPLICATE_PLAYER',
        'message', 'A paired Player appears more than once in this round.'
      )
    );
  end if;

  select value.revision_id into current_handicap
  from scoring_authority.handicap_revision_current value
  where value.tournament_id = '2026';
  if current_handicap is null
     or snapshot_value.handicap_revision_id is distinct from current_handicap
     or exists (
       select 1
       from scoring_authority.match_participants participant
       left join scoring_authority.handicap_revision_entries entry
         on entry.revision_id = current_handicap
        and entry.tournament_id = '2026'
        and entry.player_id = participant.player_id
       where participant.match_id = target_match_id
         and (entry.player_id is null
           or participant.handicap_revision_id is distinct from current_handicap)
     ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'HANDICAP_CONTEXT_NOT_CURRENT',
        'message', 'Every paired Player needs the current approved handicap context.'
      )
    );
  end if;

  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'hole_number', hole.hole_number,
    'par', hole.par,
    'stroke_index', hole.stroke_index,
    'yardage', hole.yardage
  ) order by hole.hole_number) into match_holes_value
  from scoring_authority.match_holes hole
  where hole.match_id = target_match_id
    and hole.snapshot_id = snapshot_value.snapshot_id;
  if match_holes_value is distinct from holes_value then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_HOLES_NOT_CURRENT',
        'message', 'The match hole scoring context is not current.'
      )
    );
  end if;
  if (select pg_catalog.count(*)
      from scoring_authority.scoring_permissions permission
      where permission.match_id = target_match_id) <> participant_count
     or exists (
       select 1
       from scoring_authority.match_participants participant
       left join scoring_authority.scoring_permissions permission
         on permission.match_id = participant.match_id
        and permission.player_id = participant.player_id
       where participant.match_id = target_match_id
         and (permission.player_id is null
           or permission.permission_revision <> match_value.permission_revision
           or (detail_value.match_id is not null and not (
              (permission.can_score and permission.revoked_at is null)
              or (not permission.can_score and permission.revoked_at is not null)
            ))
           or (detail_value.match_id is null
             and permission.can_score and permission.revoked_at is not null))
     )
     or exists (
       select 1
       from scoring_authority.scoring_permissions permission
       left join scoring_authority.match_participants participant
         on participant.match_id = permission.match_id
        and participant.player_id = permission.player_id
       where permission.match_id = target_match_id
         and participant.player_id is null
     )
     or (
       exists (
         select 1 from scoring_authority.scoring_permissions permission
         where permission.match_id = target_match_id and permission.can_score
       )
       and exists (
         select 1 from scoring_authority.scoring_permissions permission
         where permission.match_id = target_match_id and not permission.can_score
       )
     ) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_PERMISSION_COVERAGE_INVALID',
        'message', 'Scoring access records do not match the current pairings.'
      )
    );
  end if;
  if not allow_scoring_activity and (match_value.scored_holes <> 0
     or match_value.current_hole <> 0
     or match_value.holes_remaining <> 18
     or match_value.team_1_holes_won <> 0
     or match_value.team_2_holes_won <> 0
     or match_value.running_result <> 'Scheduled'
     or match_value.result_winner <> ''
     or match_value.clinched
     or match_value.scorecard_complete
     or match_value.finalized_at is not null
     or match_value.unresolved_mutations <> 0
     or exists (
       select 1 from scoring_authority.hole_scores score
       where score.match_id = target_match_id
     )
     or exists (
       select 1 from scoring_authority.score_mutations mutation
       where mutation.match_id = target_match_id
         and mutation.mutation_type in ('HOLE_SCORE', 'FINALIZE', 'REOPEN')
     )
     or exists (
       select 1 from scoring_authority.finalized_scorecard_snapshots final_value
       where final_value.match_id = target_match_id
     )
     or exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026'
         and lease.match_id = target_match_id
         and lease.expires_at > pg_catalog.clock_timestamp()
     )) then
    reasons := reasons || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'MATCH_ALREADY_HAS_SCORING_ACTIVITY',
        'message', 'The match already has scoring activity and cannot be started from setup.'
      )
    );
  end if;

  if pg_catalog.jsonb_array_length(reasons) = 0 then
    begin
      context_value := production_control.handicap_v1_match_context(
        target_match_id, current_handicap
      );
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'match_id', participant.match_id,
        'player_id', participant.player_id,
        'team_side', participant.team_side,
        'player_slot', participant.player_slot,
        'tournament_handicap', participant.tournament_handicap,
        'handicap_index', participant.handicap_index,
        'course_handicap', participant.course_handicap,
        'playing_handicap', participant.playing_handicap,
        'final_strokes', participant.final_strokes
      ) order by participant.team_side, participant.player_slot)
      into current_participant_values
      from scoring_authority.match_participants participant
      where participant.match_id = target_match_id;
      if current_participant_values is distinct from
           context_value->'participants' then
        reasons := reasons || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'SCORING_PARTICIPANT_HANDICAPS_STALE',
            'message', 'The paired Player handicap values must be refreshed.'
          )
        );
      end if;
      if snapshot_value.participant_configuration is distinct from
           context_value->'participant_configuration'
         or snapshot_value.team_configuration is distinct from
           context_value->'team_configuration' then
        reasons := reasons || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'SCORING_HANDICAP_PROJECTION_STALE',
            'message', 'The scoring handicap projection must be refreshed.'
          )
        );
      end if;
    exception when others then
      reasons := reasons || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'SCORING_HANDICAP_PROJECTION_INCOMPLETE',
          'message', 'The scoring handicap projection is incomplete.'
        )
      );
    end;
  end if;

  return pg_catalog.jsonb_build_object(
    'ready', pg_catalog.jsonb_array_length(reasons) = 0,
    'contractVersion', 'production-match-scoring-readiness-v1',
    'matchId', target_match_id,
    'source', case when detail_value.match_id is null
      then 'CERTIFIED_CANONICAL_SNAPSHOT'
      else 'TOURNAMENT_SETUP_V1' end,
    'reasons', reasons
  );
exception when others then
  return pg_catalog.jsonb_build_object(
    'ready', false,
    'contractVersion', 'production-match-scoring-readiness-v1',
    'matchId', target_match_id,
    'reasons', pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_READINESS_UNAVAILABLE',
        'message', 'Scoring readiness could not be verified safely.'
      )
    )
  );
end;
$$;


ALTER FUNCTION production_control.match_scoring_context_readiness_v1(target_match_id text, allow_scoring_activity boolean) OWNER TO postgres;

--
-- Name: materialize_future_annual_odds_inputs_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.materialize_future_annual_odds_inputs_v1(input jsonb, synchronization_response jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text := pg_catalog.btrim(coalesce(
    input->>'target_tournament_id', ''
  ));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  binding production_control.future_annual_projection_bindings_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  current_config scoring_authority.odds_input_configurations%rowtype;
  ratings_seed scoring_authority.odds_input_configurations%rowtype;
  projection jsonb;
  pairing_fingerprint_value text;
  next_revision bigint;
  next_bundle text;
  next_id uuid;
  diagnostics jsonb;
begin
  if pg_catalog.upper(pg_catalog.btrim(coalesce(input->>'domain', ''))) <>
       'PREDICTION_SETTINGS' then
    return synchronization_response;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'future-annual-odds-inputs:' || target, 0
    )
  );
  select value.* into strict binding
  from production_control.future_annual_projection_bindings_v1 value
  where value.tournament_id = target
    and value.domain = 'PREDICTION_SETTINGS'
    and value.certification_status = 'CERTIFIED' for update;
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target for update;
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into current_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target and value.is_current for update;
  if current_config.id is not null then
    ratings_seed := current_config;
  else
    select value.* into strict ratings_seed
    from scoring_authority.odds_input_configurations value
    where value.tournament_id = pointer.tournament_id
      and value.is_current
      and value.validation_status = 'VALID';
  end if;
  projection := binding.projection;
  pairing_fingerprint_value := production_control
    .annual_odds_pairing_fingerprint_v1(target);
  if target = pointer.tournament_id
     or catalog.tournament_year <= 2026
     or catalog.lifecycle not in (
       'DRAFT', 'CONFIGURING', 'READY_FOR_ACTIVATION'
     )
     or binding.source_workbook_id is distinct from
       resource.source_workbook_id
     or input->>'source_fingerprint' is distinct from
       binding.source_fingerprint
     or input->>'payload_fingerprint' is distinct from
       binding.payload_fingerprint
     or pg_catalog.upper(pg_catalog.btrim(coalesce(
       input->>'validation_status', ''
     ))) <> 'VALID'
     or pg_catalog.jsonb_typeof(projection->'settings') <> 'array'
     or pg_catalog.jsonb_array_length(projection->'settings') <> 30
     or pg_catalog.jsonb_typeof(projection->'canonical_settings') <>
       'object'
     or pg_catalog.jsonb_typeof(projection->'effective_settings') <>
       'object'
     or scoring_authority.jsonb_object_length(
       projection->'canonical_settings'
     ) <> 30
     or scoring_authority.jsonb_object_length(
       projection->'effective_settings'
     ) <> 30
     or pg_catalog.lower(pg_catalog.btrim(coalesce(
       projection->>'settings_fingerprint', ''
     ))) !~ '^[0-9a-f]{64}$'
     or pg_catalog.lower(pg_catalog.btrim(coalesce(
       projection->>'effective_settings_fingerprint', ''
     ))) !~ '^[0-9a-f]{64}$'
     or projection->>'settings_contract_version' is distinct from
       'prediction-settings-v1'
     or projection->>'source_tab' is distinct from 'Prediction Settings'
     or pg_catalog.jsonb_typeof(ratings_seed.historical_ratings) <>
       'object'
     or coalesce(ratings_seed.ratings_fingerprint, '') !~
       '^[0-9a-f]{64}$' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_PREDICTION_SETTINGS_INVALID';
  end if;

  -- An exact synchronization retry is a true no-op only when both the Google
  -- projection and the target setup/pairing context still match.
  if current_config.id is not null
     and current_config.source_fingerprint = binding.source_fingerprint
     and current_config.settings_fingerprint =
       pg_catalog.lower(projection->>'settings_fingerprint')
     and current_config.effective_settings_fingerprint =
       pg_catalog.lower(projection->>'effective_settings_fingerprint')
     and current_config.pairing_fingerprint = pairing_fingerprint_value
     and coalesce((current_config.validation_diagnostics->>
       'annualSetupRevision')::bigint, -1) = catalog.setup_revision then
    return synchronization_response || pg_catalog.jsonb_build_object(
      'configuration_id', current_config.id,
      'configuration_revision', current_config.configuration_revision,
      'bundle_fingerprint', current_config.bundle_fingerprint,
      'oddsInputsChanged', false,
      'idempotent', true
    );
  end if;

  select coalesce(pg_catalog.max(value.configuration_revision), 0) + 1
    into next_revision
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target;
  diagnostics := coalesce(input->'validation_diagnostics', '{}'::jsonb) ||
    pg_catalog.jsonb_build_object(
      'annualProjectionContract',
        'production-future-annual-projection-binding-v1',
      'annualProjectionBindingRevision', binding.binding_revision,
      'annualSetupRevision', catalog.setup_revision,
      'annualPairingFingerprintContract',
        'production-annual-odds-pairing-context-v1',
      'historicalRatingsSourceTournamentId', ratings_seed.tournament_id,
      'historicalRatingsSourceConfigurationId', ratings_seed.id,
      'historicalRatingsCarryForwardReviewed', true
    );
  next_bundle := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-annual-odds-input-bundle-v1',
      'tournamentId', target,
      'sourceFingerprint', binding.source_fingerprint,
      'settingsFingerprint',
        pg_catalog.lower(projection->>'settings_fingerprint'),
      'effectiveSettingsFingerprint',
        pg_catalog.lower(projection->>'effective_settings_fingerprint'),
      'ratingsFingerprint', ratings_seed.ratings_fingerprint,
      'pairingFingerprint', pairing_fingerprint_value,
      'configurationRevision', next_revision,
      'priorTargetConfigurationId', current_config.id
    )
  );
  update scoring_authority.odds_input_configurations set
    is_current = false,
    superseded_at = pg_catalog.clock_timestamp()
  where tournament_id = target and is_current;
  insert into scoring_authority.odds_input_configurations (
    tournament_id, configuration_revision, source_workbook_id,
    settings, historical_ratings, settings_fingerprint,
    ratings_fingerprint, pairing_fingerprint, bundle_fingerprint,
    is_current, imported_by, source_tab, source_fingerprint,
    canonical_settings, effective_settings,
    effective_settings_fingerprint, settings_contract_version,
    validation_status, validation_diagnostics, synchronized_at,
    previous_configuration_id
  ) values (
    target, next_revision, resource.source_workbook_id,
    projection->'settings', ratings_seed.historical_ratings,
    pg_catalog.lower(projection->>'settings_fingerprint'),
    ratings_seed.ratings_fingerprint, pairing_fingerprint_value,
    next_bundle, true, coalesce(nullif(pg_catalog.btrim(
      input->>'requested_by'
    ), ''), 'Production Director ' || actor_player),
    'Prediction Settings', binding.source_fingerprint,
    projection->'canonical_settings', projection->'effective_settings',
    pg_catalog.lower(projection->>'effective_settings_fingerprint'),
    'prediction-settings-v1', 'VALID', diagnostics,
    pg_catalog.clock_timestamp(), current_config.id
  ) returning id into next_id;
  insert into scoring_authority.odds_input_import_runs (
    tournament_id, bundle_fingerprint, status, requested_by
  ) values (
    target, next_bundle, 'APPLIED',
    coalesce(nullif(pg_catalog.btrim(input->>'requested_by'), ''),
      'Production Director ' || actor_player)
  );
  return synchronization_response || pg_catalog.jsonb_build_object(
    'changed', true,
    'configuration_id', next_id,
    'configuration_revision', next_revision,
    'bundle_fingerprint', next_bundle,
    'pairing_fingerprint', pairing_fingerprint_value,
    'oddsInputsChanged', true,
    'idempotent', false
  );
exception
  when no_data_found or unique_violation
    or invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_PREDICTION_SETTINGS_INVALID';
end;
$_$;


ALTER FUNCTION production_control.materialize_future_annual_odds_inputs_v1(input jsonb, synchronization_response jsonb) OWNER TO postgres;

--
-- Name: materialize_tournament_setup_legacy_match_v1(text, bigint, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.materialize_tournament_setup_legacy_match_v1(target_match_id text, next_revision bigint, actor_player text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  match_value scoring_authority.matches%rowtype;
  snapshot_value scoring_authority.scoring_snapshots%rowtype;
  presentation_value scoring_authority.game_center_presentations%rowtype;
  target_match_number integer;
  target_starting_hole integer;
  target_tee_time time without time zone;
  target_course_name text;
  target_course_location text;
  hole_count integer;
  stroke_count integer;
  hole_par integer;
  existing_hole_count integer;
  existing_round_course scoring_authority.tournament_setup_round_courses_v1%rowtype;
begin
  if exists (
    select 1 from scoring_authority.tournament_setup_match_details_v1 detail
    where detail.match_id = target_match_id
  ) then
    return false;
  end if;

  select value.* into strict match_value
  from scoring_authority.matches value
  where value.tournament_id = '2026' and value.match_id = target_match_id
  for update;
  select value.* into strict snapshot_value
  from scoring_authority.scoring_snapshots value
  where value.snapshot_id = match_value.scoring_snapshot_id
    and value.tournament_id = '2026'
    and value.match_id = target_match_id;
  select value.* into strict presentation_value
  from scoring_authority.game_center_presentations value
  where value.tournament_id = '2026' and value.match_id = target_match_id;

  begin
    target_match_number := coalesce(
      nullif(pg_catalog.btrim(presentation_value.display_match_number), '')::integer,
      nullif(pg_catalog.regexp_replace(target_match_id, '^.*-', ''), '')::integer
    );
    target_starting_hole := nullif(
      pg_catalog.btrim(presentation_value.starting_hole), ''
    )::integer;
    target_tee_time := case
      when nullif(pg_catalog.btrim(presentation_value.tee_time), '') is null
        then null
      else presentation_value.tee_time::time without time zone
    end;
  exception when others then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_LEGACY_MATCH_CONTEXT_INVALID';
  end;

  if snapshot_value.format is distinct from match_value.format
     or pg_catalog.btrim(coalesce(snapshot_value.course_id, '')) = ''
     or pg_catalog.btrim(coalesce(snapshot_value.tee, '')) = ''
     or snapshot_value.rating is null or snapshot_value.rating <= 0
     or snapshot_value.slope is null or snapshot_value.slope not between 55 and 155
     or snapshot_value.par not between 54 and 90
     or target_match_number not between 1 and 99
     or target_starting_hole not between 1 and 18
     or not exists (
       select 1 from scoring_authority.rounds round_value
       where round_value.tournament_id = '2026'
         and round_value.round_number = match_value.round_number
         and round_value.format = match_value.format
     )
     or pg_catalog.jsonb_typeof(snapshot_value.hole_definitions)
       is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_LEGACY_MATCH_CONTEXT_INVALID';
  end if;

  begin
    select pg_catalog.count(*)::integer,
      pg_catalog.count(distinct coalesce(
        hole->>'hole_number', hole->>'holeNumber', hole->>'number'
      ))::integer,
      pg_catalog.count(distinct coalesce(
        hole->>'stroke_index', hole->>'strokeIndex'
      ))::integer,
      pg_catalog.sum((hole->>'par')::integer)::integer
    into hole_count, existing_hole_count, stroke_count, hole_par
    from pg_catalog.jsonb_array_elements(snapshot_value.hole_definitions) hole;
  exception when others then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_LEGACY_MATCH_CONTEXT_INVALID';
  end;
  if hole_count <> 18 or existing_hole_count <> 18 or stroke_count <> 18
     or hole_par <> snapshot_value.par
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(snapshot_value.hole_definitions) hole
       where coalesce(hole->>'hole_number', hole->>'holeNumber', hole->>'number')::integer
           not between 1 and 18
          or (hole->>'par')::integer not between 3 and 6
          or coalesce(hole->>'stroke_index', hole->>'strokeIndex')::integer
            not between 1 and 18
          or (nullif(hole->>'yardage', '') is not null
            and (hole->>'yardage')::integer not between 1 and 999)
     ) then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_LEGACY_MATCH_CONTEXT_INVALID';
  end if;

  select coalesce(history_course.canonical_name,
      nullif(pg_catalog.btrim(presentation_value.course_name), '')),
    history_course.canonical_location
  into target_course_name, target_course_location
  from (select 1) seed
  left join scoring_authority.completed_history_course_identities history_course
    on history_course.course_id = snapshot_value.course_id;
  if pg_catalog.btrim(coalesce(target_course_name, '')) = '' then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_SETUP_LEGACY_MATCH_CONTEXT_INVALID';
  end if;

  insert into scoring_authority.tournament_setup_course_tees_v1 (
    tournament_id, course_id, tee_id, display_name, location,
    rating, slope, par, setup_revision, updated_by_player_id
  ) values (
    '2026', snapshot_value.course_id, snapshot_value.tee,
    target_course_name, target_course_location, snapshot_value.rating,
    snapshot_value.slope, snapshot_value.par, next_revision, actor_player
  ) on conflict (tournament_id, course_id, tee_id) do nothing;

  select pg_catalog.count(*)::integer into existing_hole_count
  from scoring_authority.tournament_setup_course_holes_v1 hole
  where hole.tournament_id = '2026'
    and hole.course_id = snapshot_value.course_id
    and hole.tee_id = snapshot_value.tee;
  if existing_hole_count = 0 then
    insert into scoring_authority.tournament_setup_course_holes_v1 (
      tournament_id, course_id, tee_id, hole_number, par, stroke_index,
      yardage, setup_revision
    )
    select '2026', snapshot_value.course_id, snapshot_value.tee,
      coalesce(hole->>'hole_number', hole->>'holeNumber', hole->>'number')::integer,
      (hole->>'par')::integer,
      coalesce(hole->>'stroke_index', hole->>'strokeIndex')::integer,
      nullif(hole->>'yardage', '')::integer,
      next_revision
    from pg_catalog.jsonb_array_elements(snapshot_value.hole_definitions) hole;
  elsif existing_hole_count <> 18 then
    raise exception using errcode = '55000',
      message = 'TOURNAMENT_SETUP_LEGACY_MATCH_CONTEXT_CONFLICT';
  end if;

  select value.* into existing_round_course
  from scoring_authority.tournament_setup_round_courses_v1 value
  where value.tournament_id = '2026'
    and value.round_number = match_value.round_number
  for update;
  if found and (
    existing_round_course.course_id is distinct from snapshot_value.course_id
    or existing_round_course.tee_id is distinct from snapshot_value.tee
  ) then
    raise exception using errcode = '55000',
      message = 'TOURNAMENT_SETUP_LEGACY_MATCH_CONTEXT_CONFLICT';
  elsif not found then
    insert into scoring_authority.tournament_setup_round_courses_v1 (
      tournament_id, round_number, course_id, tee_id, setup_revision,
      updated_by_player_id
    ) values (
      '2026', match_value.round_number, snapshot_value.course_id,
      snapshot_value.tee, next_revision, actor_player
    );
  end if;

  insert into scoring_authority.tournament_setup_match_details_v1 (
    match_id, tournament_id, round_number, match_number, course_id, tee_id,
    tee_time, starting_hole, setup_revision, prepared_setup_revision,
    prepared_configuration_fingerprint, updated_by_player_id
  ) values (
    target_match_id, '2026', match_value.round_number, target_match_number,
    snapshot_value.course_id, snapshot_value.tee, target_tee_time,
    target_starting_hole, next_revision, null, null, actor_player
  );
  return true;
exception when no_data_found then
  raise exception using errcode = '22023',
    message = 'TOURNAMENT_SETUP_LEGACY_MATCH_CONTEXT_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.materialize_tournament_setup_legacy_match_v1(target_match_id text, next_revision bigint, actor_player text) OWNER TO postgres;

--
-- Name: model_d_context_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.model_d_context_v1(context jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 select production_control.worker_supervisor_model_d_v1() and exists(
 select 1 from production_control.certification_model_d_profile_v1 d where d.singleton
 and context->>'resource_id'=d.resource_id and context->>'project_ref'=d.project_ref and context->>'resource_class'='CERTIFICATION');
$$;


ALTER FUNCTION production_control.model_d_context_v1(context jsonb) OWNER TO postgres;

--
-- Name: mutate_annual_calcutta_publication_v1(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mutate_annual_calcutta_publication_v1(input jsonb, publish_value boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  current_value scoring_authority.calcutta_v1_current%rowtype;
  publication_value scoring_authority.calcutta_v1_publication_revisions%rowtype;
  existing_response jsonb;
  response_value jsonb;
  job_value jsonb;
  operation_value text := case when publish_value
    then 'ANNUAL_CALCUTTA_V1_PUBLISH'
    else 'ANNUAL_CALCUTTA_V1_UNPUBLISH' end;
  desired_state text := case when publish_value
    then 'PUBLISHED' else 'UNPUBLISHED' end;
  request_fingerprint_value text := pg_catalog.lower(coalesce(
    input->>'request_fingerprint', ''
  ));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid := nullif(input#>>'{authorization,auth_user_id}', '')::uuid;
begin
  target := production_control.assert_annual_calcutta_runtime_v1(
    input, case when publish_value
      then 'publish_production_calcutta_v1'
      else 'unpublish_production_calcutta_v1' end
  );
  perform production_control.assert_future_production_scoring_actor_v1(
    input, target, true
  );
  existing_response := production_control.lookup_cutover_receipt(
    operation_value, input
  );
  if existing_response is not null then return existing_response; end if;
  if request_fingerprint_value !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_PUBLICATION_INPUT_INVALID';
  end if;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target and value.generation_status = 'ACTIVE';
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = target for update;
  if current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1)
     or current_value.configuration_fingerprint is distinct from
       nullif(input->>'expected_configuration_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REVISION_CONFLICT';
  end if;
  if current_value.auction_revision <>
       coalesce((input->>'expected_auction_revision')::bigint, -1)
     or current_value.auction_fingerprint is distinct from
       nullif(input->>'expected_auction_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_AUCTION_REVISION_CONFLICT';
  end if;
  if current_value.publication_revision <>
       coalesce((input->>'expected_publication_revision')::bigint, -1) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_PUBLICATION_REVISION_CONFLICT';
  end if;
  if publish_value and (
       current_value.state = 'NOT_CONFIGURED'
       or current_value.auction_revision = 0
       or current_value.auction_revision_id is null
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CALCUTTA_AUCTION_FACTS_REQUIRED';
  end if;
  if current_value.publication_state = desired_state then
    response_value := pg_catalog.jsonb_build_object(
      'ok', true,
      'code', case when publish_value
        then 'PRODUCTION_CALCUTTA_V1_ALREADY_PUBLISHED'
        else 'PRODUCTION_CALCUTTA_V1_ALREADY_UNPUBLISHED' end,
      'tournament_id', target,
      'runtime_generation_id', generation.runtime_generation_id,
      'state', current_value.state,
      'publication_state', desired_state,
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'publication_revision', current_value.publication_revision,
      'result_revision', nullif(current_value.result_revision, 0),
      'job', null, 'idempotent', true
    );
    perform production_control.store_cutover_receipt(
      operation_value, input, response_value
    );
    return response_value;
  end if;
  insert into scoring_authority.calcutta_v1_publication_revisions (
    tournament_id, publication_revision, configuration_revision,
    auction_revision, configuration_fingerprint, auction_fingerprint,
    publication_state, action, actor_player_id, actor_auth_user_id,
    request_fingerprint, request_payload_hash, published_at
  ) values (
    target, current_value.publication_revision + 1,
    current_value.configuration_revision, current_value.auction_revision,
    current_value.configuration_fingerprint,
    current_value.auction_fingerprint, desired_state,
    case when publish_value
      then 'DIRECTOR_PUBLISHED' else 'DIRECTOR_UNPUBLISHED' end,
    actor_player, actor_auth, request_fingerprint_value,
    production_control.calcutta_v1_hash(input),
    case when publish_value
      then pg_catalog.clock_timestamp() else null end
  ) returning * into publication_value;
  update scoring_authority.calcutta_v1_current set
    publication_revision_id = publication_value.publication_revision_id,
    publication_revision = publication_value.publication_revision,
    publication_state = desired_state,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = target;
  if publish_value then
    job_value := production_control.enqueue_annual_calcutta_v1(
      target, generation.runtime_generation_id,
      (input->>'expected_activation_revision')::bigint,
      'DIRECTOR_PUBLISHED', actor_player, false, null, null
    );
  else
    job_value := null;
  end if;
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = target;
  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    target, case when publish_value
      then 'PRODUCTION_CALCUTTA_V1_PUBLISHED'
      else 'PRODUCTION_CALCUTTA_V1_UNPUBLISHED' end,
    actor_player, pg_catalog.jsonb_build_object(
      'configuration_revision', current_value.configuration_revision,
      'auction_revision', current_value.auction_revision,
      'publication_revision', current_value.publication_revision,
      'result_revision', nullif(current_value.result_revision, 0),
      'publication_policy',
        'DIRECTOR_CONTROLLED_PARTICIPANT_FULL_MARKET',
      'state_preserved', current_value.state,
      'runtime_generation_id', generation.runtime_generation_id,
      'authority_changed', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    case when publish_value
      then 'PRODUCTION_CALCUTTA_V1_PUBLISHED'
      else 'PRODUCTION_CALCUTTA_V1_UNPUBLISHED' end,
    'CALCUTTA', target, actor_player, request_fingerprint_value,
    'SUCCEEDED', pg_catalog.jsonb_build_object(
      'configuration_revision', current_value.configuration_revision,
      'auction_revision', current_value.auction_revision,
      'publication_revision', current_value.publication_revision,
      'result_revision', nullif(current_value.result_revision, 0),
      'runtime_generation_id', generation.runtime_generation_id,
      'job_id', job_value->>'job_id'
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', case when publish_value
      then 'PRODUCTION_CALCUTTA_V1_PUBLISHED'
      else 'PRODUCTION_CALCUTTA_V1_UNPUBLISHED' end,
    'tournament_id', target,
    'runtime_generation_id', generation.runtime_generation_id,
    'state', current_value.state, 'publication_state', desired_state,
    'configuration_revision', current_value.configuration_revision,
    'configuration_fingerprint', current_value.configuration_fingerprint,
    'auction_revision', current_value.auction_revision,
    'auction_fingerprint', current_value.auction_fingerprint,
    'publication_revision', current_value.publication_revision,
    'result_revision', nullif(current_value.result_revision, 0),
    'job', job_value, 'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    operation_value, input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.mutate_annual_calcutta_publication_v1(input jsonb, publish_value boolean) OWNER TO postgres;

--
-- Name: mutate_late_r3_dispatch_v1(jsonb, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mutate_late_r3_dispatch_v1(input jsonb, round_save boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  action_value text:=upper(btrim(coalesce(input->>'operation',input->>'action','')));
  payload jsonb;
  row_value jsonb;
  target text;
  desired jsonb;
  current_pair jsonb;
  m scoring_authority.matches%rowtype;
  eligible text[]:='{}';
  initial text[]:='{}';
  evidence jsonb:='{}';
  prior_source jsonb;
  after_source jsonb;
  protected_before text;
  financial_before text;
  response jsonb;
  request_id uuid;
  existing_result scoring_authority.calcutta_v1_result_revisions%rowtype;
  code text;
begin
  if (not round_save and action_value not in('REPLACE_PAIRINGS','PREPARE_SCORING_CONTEXT'))
    or (round_save and input->>'round_number' is distinct from '3') then
    if round_save then return production_control.mutate_round_pairings_before_late_r3_v1(input); end if;
    return production_control.mutate_setup_before_late_r3_v1(input);
  end if;
  payload:=case when round_save then input->'matches'
    when action_value='REPLACE_PAIRINGS' then jsonb_build_array(coalesce(input->'pairings',input))
    else jsonb_build_array(coalesce(input->'scoring_context',input)) end;
  if not round_save and coalesce(payload#>>'{0,match_id}',payload#>>'{0,matchId}','') !~ '^2026-R3-([1-9]|1[0-2])$' then
    return production_control.mutate_setup_before_late_r3_v1(input);
  end if;
  if round_save then
    begin
      -- Admission is enforced by the public Production or isolated gateway before this private core.
    exception when others then
      get stacked diagnostics code=message_text;
      if code !~ '^TOURNAMENT_SETUP_[A-Z0-9_]+$' then code:='TOURNAMENT_SETUP_ROUND_OPERATION_FAILED'; end if;
      return jsonb_build_object('ok',false,'code',code,'matchId',null,'playerId',null);
    end;
  else
    -- Admission is enforced by the public Production or isolated gateway before this private core.
  end if;
  begin
  request_id:=(input->>'operation_request_id')::uuid;
  perform pg_advisory_xact_lock(hashtextextended('production-tournament-setup-v1:2026',0));
  -- Let the finalized RPC decide exact retry/conflict before any lifecycle work.
  if exists(select 1 from production_control.tournament_setup_operation_receipts_v1
    where tournament_id='2026' and action=action_value and operation_request_id=request_id) then
    if round_save then return production_control.mutate_round_pairings_before_late_r3_v1(input); end if;
    return production_control.mutate_setup_before_late_r3_v1(input);
  end if;
  -- Rare setup operation: NOWAIT, coordinated table locks avoid check/write
  -- races with non-cooperating legacy writers, including worker row claims.
  -- Ordinary participant SELECTs remain allowed. Busy writers cause rollback.
  lock table scoring_authority.matches,scoring_authority.match_participants,
    scoring_authority.scoring_snapshots,scoring_authority.hole_scores,
    scoring_authority.score_mutations,scoring_authority.score_revision_history,
    scoring_authority.scoring_permissions,scoring_authority.scoring_ingress_leases,
    scoring_authority.finalized_scorecard_snapshots,scoring_authority.rounds,
    scoring_authority.tournament_players,scoring_authority.handicap_revision_current,
    scoring_authority.handicap_revision_entries,scoring_authority.handicap_revisions,
    scoring_authority.handicap_match_refresh_events,
    scoring_authority.tournament_setup_match_details_v1,
    scoring_authority.tournament_setup_round_courses_v1,
    scoring_authority.tournament_setup_course_tees_v1,scoring_authority.tournament_setup_course_holes_v1,
    scoring_authority.calcutta_v1_current,scoring_authority.calcutta_v1_configuration_revisions,
    scoring_authority.calcutta_v1_auction_fact_revisions,scoring_authority.calcutta_v1_result_revisions,
    scoring_authority.calcutta_v1_publication_revisions,scoring_authority.calcutta_v1_recalculation_jobs,
    scoring_authority.net_skins_v1_configuration_current,scoring_authority.net_skins_v1_configuration_revisions,
    scoring_authority.net_skins_v1_result_revisions,scoring_authority.net_skins_v1_recalculation_jobs,
    scoring_authority.odds_publication_current,scoring_authority.odds_publication_public_pointer_v1,
    scoring_authority.odds_calculation_jobs
    in exclusive mode nowait;

  -- All R3 still future/unscored. Historical R3 results remain blocking, not
  -- just the current publication pointer. No financial job is cancelled.
  if exists(select 1 from scoring_authority.matches where tournament_id='2026' and round_number=3
      and not production_control.handicap_v1_match_is_unstarted(match_id))
    or exists(select 1 from scoring_authority.calcutta_v1_recalculation_jobs where tournament_id='2026' and status in('PENDING','RUNNING'))
    or exists(select 1 from scoring_authority.calcutta_v1_result_revisions where tournament_id='2026'
      and (engine_result_payload->'completedRounds') @> '[3]'::jsonb)
    or exists(select 1 from scoring_authority.net_skins_v1_result_revisions where tournament_id='2026' and round_number=3)
    or exists(select 1 from scoring_authority.finalized_scorecard_snapshots s
      join scoring_authority.matches history_match using(match_id) where history_match.tournament_id='2026' and history_match.round_number=3)
    or exists(select 1 from scoring_authority.score_revision_history s
      join scoring_authority.matches history_match using(match_id) where history_match.tournament_id='2026' and history_match.round_number=3)
  then
    if round_save then return production_control.mutate_round_pairings_before_late_r3_v1(input); end if;
    return production_control.mutate_setup_before_late_r3_v1(input);
  end if;

  prior_source:=production_control.calcutta_v1_source_revision('2026');
  financial_before:=production_control.late_r3_financial_fingerprint_v1();
  protected_before:=production_control.late_r3_consumed_fingerprint_v1();
  select * into existing_result from scoring_authority.calcutta_v1_result_revisions where tournament_id='2026' and is_current;
  if found and not exists(select 1 from scoring_authority.calcutta_v1_current c
    where tournament_id='2026' and configuration_revision_id=existing_result.configuration_revision_id
      and configuration_fingerprint=existing_result.configuration_fingerprint
      and auction_revision_id=existing_result.auction_revision_id
      and auction_fingerprint=existing_result.auction_fingerprint) then
    if round_save then return production_control.mutate_round_pairings_before_late_r3_v1(input); end if;
    return production_control.mutate_setup_before_late_r3_v1(input);
  end if;
  if existing_result.result_id is not null and existing_result.source_fingerprint<>production_control.calcutta_v1_hash(prior_source)
    and not production_control.late_r3_result_compatible_v1(existing_result.result_id,production_control.calcutta_v1_hash(prior_source)) then
    if round_save then return production_control.mutate_round_pairings_before_late_r3_v1(input); end if;
    return production_control.mutate_setup_before_late_r3_v1(input);
  end if;

  -- This loop precedes the 095 RPC and therefore precedes every DELETE.
  for row_value in select value from jsonb_array_elements(payload) loop
    target:=coalesce(row_value->>'match_id',row_value->>'matchId');
    select * into m from scoring_authority.matches where match_id=target and tournament_id='2026' and round_number=3 and format='SI';
    if not found then continue; end if;
    current_pair:=production_control.late_r3_pairing_v1(target);
    if action_value='PREPARE_SCORING_CONTEXT' then
      if exists(select 1 from production_control.late_r3_initialization_receipts_v1 receipt
        where match_id=target and pairing=current_pair
          and not exists(select 1 from production_control.tournament_setup_audit_events_v1 a
            where a.tournament_id='2026' and a.result='CHANGED' and a.next_revision>receipt.setup_revision
              and ((a.action='REPLACE_PAIRINGS' and a.target_id=target)
                or (a.action='REPLACE_ROUND_PAIRINGS' and a.safe_metadata->'changedMatches' ? target))))
      then eligible:=array_append(eligible,target); end if;
    else
      select coalesce(jsonb_agg(jsonb_build_object('player_id',upper(btrim(coalesce(value->>'player_id',value->>'playerId'))),
        'team_side',coalesce(value->>'team_side',value->>'teamSide')::integer,
        'player_slot',coalesce(value->>'player_slot',value->>'playerSlot')::integer)
        order by coalesce(value->>'team_side',value->>'teamSide')::integer,coalesce(value->>'player_slot',value->>'playerSlot')::integer),'[]')
        into desired from jsonb_array_elements(row_value->'participants');
      if current_pair='[]' and jsonb_array_length(desired)=2
        and not exists(select 1 from production_control.late_r3_initialization_receipts_v1 where match_id=target)
        and not exists(select 1 from production_control.tournament_setup_audit_events_v1
          where tournament_id='2026' and result='CHANGED' and
            ((action='REPLACE_PAIRINGS' and target_id=target)
              or (action='REPLACE_ROUND_PAIRINGS' and safe_metadata->'changedMatches' ? target)))
        and not exists(select 1 from scoring_authority.scoring_snapshots s where s.match_id=target
          and (coalesce(s.participant_configuration->'all_ids','[]')<>'[]'
            or coalesce(s.participant_configuration->'team_1','[]')<>'[]'
            or coalesce(s.participant_configuration->'team_2','[]')<>'[]'))
        and not exists(select 1 from scoring_authority.score_revision_history where match_id=target)
        and not exists(select 1 from scoring_authority.finalized_scorecard_snapshots where match_id=target)
      then
        initial:=array_append(initial,target);
        eligible:=array_append(eligible,target);
      end if;
    end if;
    evidence:=evidence||jsonb_build_object(target,jsonb_build_object('match',to_jsonb(m),'pairing',current_pair,'desired',desired));
  end loop;
  if cardinality(eligible)=0 then
    if round_save then return production_control.mutate_round_pairings_before_late_r3_v1(input); end if;
    return production_control.mutate_setup_before_late_r3_v1(input);
  end if;
  insert into production_control.late_r3_transactions_v1 values(txid_current(),request_id,action_value,eligible,initial,evidence,protected_before,prior_source,clock_timestamp());
  if round_save then response:=production_control.mutate_round_pairings_before_late_r3_v1(input);
  else response:=production_control.mutate_setup_before_late_r3_v1(input); end if;
  if not coalesce((response->>'ok')::boolean,false) then
    delete from production_control.late_r3_transactions_v1 where transaction_id=txid_current();
    return response;
  end if;
  if financial_before<>production_control.late_r3_financial_fingerprint_v1()
    or protected_before<>production_control.late_r3_consumed_fingerprint_v1() then
    raise exception 'TOURNAMENT_SETUP_LIFECYCLE_PRESERVATION_FAILED';
  end if;
  after_source:=production_control.calcutta_v1_source_revision('2026');
  -- Full global comparison: only the authorized R3 Match setup fields may vary.
  -- Every score, round status, policy, non-target Match and participant survives.
  if (prior_source-'matches') is distinct from (after_source-'matches')
    or (select jsonb_agg(value order by value->>'match_id') from jsonb_array_elements(prior_source->'matches')
      where not (value->>'match_id'=any(eligible))) is distinct from
      (select jsonb_agg(value order by value->>'match_id') from jsonb_array_elements(after_source->'matches')
      where not (value->>'match_id'=any(eligible))) then
    raise exception 'TOURNAMENT_SETUP_LIFECYCLE_SOURCE_CHANGED';
  end if;
  foreach target in array eligible loop
    if (select value-array['participants','match_revision','permission_revision','scoring_snapshot_id'] from jsonb_array_elements(prior_source->'matches') where value->>'match_id'=target)
      is distinct from (select value-array['participants','match_revision','permission_revision','scoring_snapshot_id'] from jsonb_array_elements(after_source->'matches') where value->>'match_id'=target) then
      raise exception 'TOURNAMENT_SETUP_LIFECYCLE_SOURCE_CHANGED';
    end if;
    if target=any(initial) then
      if production_control.late_r3_pairing_v1(target) is distinct from evidence#>array[target,'desired'] then
        raise exception 'TOURNAMENT_SETUP_LIFECYCLE_PAIRING_CHANGED';
      end if;
      insert into production_control.late_r3_initialization_receipts_v1
        (tournament_id,round_number,match_id,operation_request_id,setup_revision,pairing,pre_mutation_evidence,actor_player_id)
        values('2026',3,target,request_id,(response->>'revision')::bigint,
          production_control.late_r3_pairing_v1(target),evidence->target,input#>>'{authorization,player_id}');
    end if;
  end loop;
  if prior_source is distinct from after_source then
    insert into production_control.late_r3_calcutta_compatibility_v1
      (tournament_id,operation_request_id,operation,match_ids,source_before,source_after,
        source_before_fingerprint,source_after_fingerprint,result_id,original_result_source_fingerprint,
        consumed_fingerprint,financial_fingerprint)
      values('2026',request_id,action_value,eligible,prior_source,after_source,
        production_control.calcutta_v1_hash(prior_source),production_control.calcutta_v1_hash(after_source),
        existing_result.result_id,existing_result.source_fingerprint,protected_before,financial_before);
  end if;
  delete from production_control.late_r3_transactions_v1 where transaction_id=txid_current();
  return response;
exception when others then
  get stacked diagnostics code=message_text;
  if code !~ '^TOURNAMENT_SETUP_[A-Z0-9_]+$' then code:='TOURNAMENT_SETUP_LIFECYCLE_BLOCKED'; end if;
  return jsonb_build_object('ok',false,'code',code);
  end;
end;
$_$;


ALTER FUNCTION production_control.mutate_late_r3_dispatch_v1(input jsonb, round_save boolean) OWNER TO postgres;

--
-- Name: mutate_round_pairings_before_late_r3_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mutate_round_pairings_before_late_r3_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  actor text := input#>>'{authorization,player_id}';
  actor_auth uuid;
  request_id uuid;
  expected bigint;
  current_revision bigint;
  next_revision bigint;
  declared_hash text := input->>'request_payload_hash';
  database_hash text;
  receipt production_control.tournament_setup_operation_receipts_v1%rowtype;
  round_number_value integer;
  current_handicap uuid;
  match_value scoring_authority.matches%rowtype;
  row_value jsonb;
  player_value jsonb;
  canonical jsonb;
  changed_ids text[] := '{}';
  seen_players text[] := '{}';
  seen_slots text[];
  target text;
  player_id_value text;
  side_value integer;
  slot_value integer;
  required_count integer;
  roster_count integer;
  result_value jsonb;
  response_value jsonb;
  failure_code text;
begin
  -- Admission is enforced by the public Production or isolated gateway before this private core.
  if input->>'operation' is distinct from 'REPLACE_ROUND_PAIRINGS'
    or coalesce(input->>'expected_revision','') !~ '^[0-9]+$'
    or coalesce(input->>'round_number','') !~ '^[1-3]$'
    or coalesce(declared_hash,'') !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(input->'matches') is distinct from 'array'
    or jsonb_array_length(input->'matches') not between 1 and 12
    or input->>'actor_player_id' is distinct from actor
    or input->>'actor_auth_user_id' is distinct from input#>>'{authorization,auth_user_id}' then
    raise exception 'TOURNAMENT_SETUP_INPUT_INVALID';
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  if request_id is null then raise exception 'TOURNAMENT_SETUP_OPERATION_REQUEST_ID_REQUIRED'; end if;
  expected := (input->>'expected_revision')::bigint;
  round_number_value := (input->>'round_number')::integer;
  database_hash := production_control.tournament_setup_hash_v1(input-'request_payload_hash');
  -- Same lock as individual Setup mutations; idempotency is checked before CAS.
  perform pg_advisory_xact_lock(hashtextextended('production-tournament-setup-v1:2026',0));
  select * into receipt from production_control.tournament_setup_operation_receipts_v1
    where tournament_id='2026' and action='REPLACE_ROUND_PAIRINGS' and operation_request_id=request_id;
  if found then
    if receipt.database_request_payload_hash=database_hash and receipt.declared_request_payload_hash=declared_hash then
      return receipt.response || jsonb_build_object('idempotent',true);
    end if;
    raise exception 'TOURNAMENT_SETUP_IDEMPOTENCY_CONFLICT';
  end if;
  current_revision := production_control.tournament_setup_revision_v1('2026');
  if current_revision<>expected then raise exception 'TOURNAMENT_SETUP_REVISION_STALE'; end if;
  next_revision := current_revision+1;
  -- Hold the approved pointer and roster while validating and writing the set.
  select revision_id into strict current_handicap from scoring_authority.handicap_revision_current
    where tournament_id='2026' for share;
  if input->>'expected_handicap_revision_id' is distinct from current_handicap::text then
    raise exception 'TOURNAMENT_SETUP_HANDICAP_REVISION_STALE';
  end if;
  perform 1 from scoring_authority.tournament_players where tournament_id='2026' for share;
  select count(*) into roster_count from scoring_authority.tournament_players
    where tournament_id='2026' and participation_status='ACTIVE';
  if (select count(*) from scoring_authority.matches where tournament_id='2026'
      and round_number=round_number_value) <> jsonb_array_length(input->'matches')
    or (select count(distinct value->>'match_id') from jsonb_array_elements(input->'matches'))
       <> jsonb_array_length(input->'matches') then
    raise exception 'TOURNAMENT_SETUP_ROUND_MATCH_SET_INVALID';
  end if;

  -- Validate the complete desired round BEFORE any write. Cross-match swaps are
  -- checked against the desired set, not against obsolete assignments.
  for row_value in select value from jsonb_array_elements(input->'matches') order by value->>'match_id' loop
    target := row_value->>'match_id';
    player_id_value := null;
    select * into match_value from scoring_authority.matches where match_id=target
      and tournament_id='2026' and round_number=round_number_value for update;
    if not found then raise exception 'TOURNAMENT_SETUP_ROUND_MATCH_SET_INVALID'; end if;
    perform production_control.assert_tournament_setup_match_mutable_v1(target);
    if not exists(select 1 from scoring_authority.tournament_setup_match_details_v1 where match_id=target) then
      raise exception 'TOURNAMENT_SETUP_MATCH_DETAILS_REQUIRED';
    end if;
    if match_value.format not in ('BB','SC','SI') or row_value->>'format' is distinct from match_value.format then
      raise exception 'TOURNAMENT_SETUP_PAIRING_FORMAT_MISMATCH';
    end if;
    required_count := case when match_value.format='SI' then 2 else 4 end;
    if jsonb_typeof(row_value->'participants') is distinct from 'array'
      or jsonb_array_length(row_value->'participants')<>required_count then
      raise exception 'TOURNAMENT_SETUP_PAIRING_COUNT_INVALID';
    end if;
    seen_slots := '{}';
    for player_value in select value from jsonb_array_elements(row_value->'participants') loop
      player_id_value := player_value->>'player_id';
      side_value := (player_value->>'team_side')::integer;
      slot_value := (player_value->>'player_slot')::integer;
      if player_id_value is null or side_value is null or slot_value is null
        or side_value not in (1,2) or slot_value not between 1 and required_count/2
        or (side_value::text||':'||slot_value::text)=any(seen_slots) then
        raise exception 'TOURNAMENT_SETUP_PAIRING_STRUCTURE_INVALID';
      end if;
      if player_id_value=any(seen_players) then raise exception 'TOURNAMENT_SETUP_ROUND_DUPLICATE_PLAYER'; end if;
      seen_players := array_append(seen_players,player_id_value);
      seen_slots := array_append(seen_slots,side_value::text||':'||slot_value::text);
      if not exists(select 1 from scoring_authority.tournament_players where tournament_id='2026'
        and player_id=player_id_value and team_side=side_value and participation_status='ACTIVE') then
        raise exception 'TOURNAMENT_SETUP_PAIRING_ACTIVE_TEAM_MEMBERSHIP_REQUIRED';
      end if;
      if not exists(select 1 from scoring_authority.handicap_revision_entries where tournament_id='2026'
        and revision_id=current_handicap and player_id=player_id_value and tournament_handicap is not null) then
        raise exception 'TOURNAMENT_SETUP_PAIRING_APPROVED_HANDICAP_REQUIRED';
      end if;
    end loop;
    select coalesce(jsonb_agg(jsonb_build_object('player_id',player_id,'team_side',team_side,'player_slot',player_slot)
      order by team_side,player_slot),'[]') into canonical from scoring_authority.match_participants where match_id=target;
    select jsonb_agg(value order by (value->>'team_side')::integer,(value->>'player_slot')::integer)
      into result_value from jsonb_array_elements(row_value->'participants');
    if canonical is distinct from result_value then
      result_value := production_control.tournament_setup_dependency_codes_v1(null,null,round_number_value,target,'PAIRINGS');
      if jsonb_array_length(result_value)>0 then raise exception 'TOURNAMENT_SETUP_DEPENDENCY_BLOCKED'; end if;
      changed_ids := array_append(changed_ids,target);
    end if;
  end loop;
  if cardinality(seen_players)<>roster_count then raise exception 'TOURNAMENT_SETUP_ROUND_COVERAGE_INCOMPLETE'; end if;

  -- Remove only changed manifests so the shared single-match validator can
  -- accept cross-match exchanges. Any later failure rolls this entire function
  -- back, including deletions, pointer changes, audit, and receipt.
  delete from scoring_authority.match_participants where match_id=any(changed_ids);
  for row_value in select value from jsonb_array_elements(input->'matches') order by value->>'match_id' loop
    target := row_value->>'match_id';
    player_id_value := null;
    if target=any(changed_ids) then
      result_value := production_control.apply_tournament_setup_pairings_v1(row_value,next_revision,actor);
      if not coalesce((result_value->>'ok')::boolean,false) then
        raise exception using message=coalesce(result_value->>'code','TOURNAMENT_SETUP_OPERATION_FAILED');
      end if;
    end if;
  end loop;
  if cardinality(changed_ids)=0 then next_revision:=current_revision;
  else
    insert into production_control.tournament_setup_context_v1
      (tournament_id,contract_version,revision,updated_by_player_id,updated_by_auth_user_id)
      values('2026','production-tournament-setup-v1',next_revision,actor,actor_auth)
      on conflict(tournament_id) do update set revision=excluded.revision,
        updated_by_player_id=excluded.updated_by_player_id,updated_by_auth_user_id=excluded.updated_by_auth_user_id,
        updated_at=clock_timestamp();
  end if;
  response_value:=jsonb_build_object('ok',true,'code','TOURNAMENT_SETUP_UPDATED','action','REPLACE_ROUND_PAIRINGS',
    'revision',next_revision,'target','2026-R'||round_number_value,'idempotent',false,
    'changed',cardinality(changed_ids)>0,'changedMatches',to_jsonb(changed_ids),'snapshotPrepared',false,
    'scoringPermissionGranted',false,'scoringMutationCreated',false,'timestamp',clock_timestamp(),
    'readiness',production_control.tournament_setup_readiness_v1());
  insert into production_control.tournament_setup_audit_events_v1
    (tournament_id,action,target_kind,target_id,actor_player_id,actor_auth_user_id,operation_request_id,
      prior_revision,next_revision,result,safe_metadata)
    values('2026','REPLACE_ROUND_PAIRINGS','ROUND','2026-R'||round_number_value,actor,actor_auth,request_id,
      current_revision,next_revision,case when cardinality(changed_ids)>0 then 'CHANGED' else 'NO_CHANGE' end,
      jsonb_build_object('changedMatches',to_jsonb(changed_ids),'handicapRevisionId',current_handicap,
        'participantCount',cardinality(seen_players),'snapshotPrepared',false,'scoringPermissionGranted',false));
  insert into production_control.tournament_setup_operation_receipts_v1
    (tournament_id,action,operation_request_id,declared_request_payload_hash,database_request_payload_hash,
      actor_player_id,actor_auth_user_id,prior_revision,next_revision,response)
    values('2026','REPLACE_ROUND_PAIRINGS',request_id,declared_hash,database_hash,actor,actor_auth,
      current_revision,next_revision,response_value);
  return response_value;
exception when others then
  -- PL/pgSQL exception block rolls back every write before returning a failure.
  get stacked diagnostics failure_code=message_text;
  if failure_code !~ '^TOURNAMENT_SETUP_[A-Z0-9_]+$' then failure_code:='TOURNAMENT_SETUP_ROUND_OPERATION_FAILED'; end if;
  return jsonb_build_object('ok',false,'code',failure_code,'matchId',target,
    'playerId',case when player_id_value ~ '^[A-Z0-9_-]{1,64}$' then player_id_value else null end);
end;
$_$;


ALTER FUNCTION production_control.mutate_round_pairings_before_late_r3_v1(input jsonb) OWNER TO postgres;

--
-- Name: mutate_setup_before_late_r3_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.mutate_setup_before_late_r3_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  action_value text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'operation', input->>'action', ''
  )));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  operation_request uuid;
  expected_revision bigint;
  current_revision bigint;
  next_revision bigint;
  declared_hash text := pg_catalog.lower(coalesce(
    input->>'request_payload_hash', ''
  ));
  database_hash text;
  receipt production_control.tournament_setup_operation_receipts_v1%rowtype;
  result_value jsonb;
  response_value jsonb;
  changed_value boolean;
  target_kind text;
  target_id text;
  safe_metadata jsonb;
  warning_values jsonb;
begin
  -- Admission is enforced by the public Production or isolated gateway before this private core.
  if action_value not in (
       'UPDATE_TOURNAMENT', 'UPDATE_TEAM', 'ASSIGN_ROSTER_TEAM',
       'UPDATE_ROUND', 'UPSERT_COURSE', 'UPSERT_MATCH',
       'REPLACE_PAIRINGS', 'PREPARE_SCORING_CONTEXT'
     )
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_revision', '') !~ '^[0-9]+$'
     or (input ? 'actor_player_id' and pg_catalog.upper(pg_catalog.btrim(
       input->>'actor_player_id'
     )) is distinct from actor_player)
     or (input ? 'actor_auth_user_id' and pg_catalog.lower(pg_catalog.btrim(
       input->>'actor_auth_user_id'
     )) is distinct from pg_catalog.lower(pg_catalog.btrim(
       input#>>'{authorization,auth_user_id}'
     ))) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'TOURNAMENT_SETUP_INPUT_INVALID'
    );
  end if;
  begin
    actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
    operation_request := (input->>'operation_request_id')::uuid;
    expected_revision := (input->>'expected_revision')::bigint;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'TOURNAMENT_SETUP_INPUT_INVALID'
    );
  end;
  database_hash := production_control.tournament_setup_hash_v1(
    input - 'request_payload_hash'
  );
  select value.* into receipt
  from production_control.tournament_setup_operation_receipts_v1 value
  where value.tournament_id = '2026'
    and value.action = action_value
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.database_request_payload_hash = database_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'TOURNAMENT_SETUP_IDEMPOTENCY_CONFLICT'
    );
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-tournament-setup-v1:2026', 0
  ));
  select value.* into receipt
  from production_control.tournament_setup_operation_receipts_v1 value
  where value.tournament_id = '2026'
    and value.action = action_value
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.database_request_payload_hash = database_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'TOURNAMENT_SETUP_IDEMPOTENCY_CONFLICT'
    );
  end if;
  current_revision := production_control.tournament_setup_revision_v1('2026');
  if current_revision <> expected_revision then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'TOURNAMENT_SETUP_REVISION_STALE',
      'currentRevision', current_revision
    );
  end if;
  next_revision := current_revision + 1;
  case action_value
    when 'UPDATE_TOURNAMENT' then
      result_value := production_control.apply_tournament_setup_tournament_v1(
        input, next_revision, actor_player
      );
    when 'UPDATE_TEAM' then
      result_value := production_control.apply_tournament_setup_team_v1(
        input, next_revision, actor_player
      );
    when 'ASSIGN_ROSTER_TEAM' then
      result_value := production_control.apply_tournament_setup_membership_v1(
        input, next_revision, actor_player, actor_auth
      );
    when 'UPDATE_ROUND' then
      result_value := production_control.apply_tournament_setup_round_v1(
        input, next_revision, actor_player
      );
    when 'UPSERT_COURSE' then
      result_value := production_control.apply_tournament_setup_course_v1(
        input, next_revision, actor_player
      );
    when 'UPSERT_MATCH' then
      result_value := production_control.apply_tournament_setup_match_v1(
        input, next_revision, actor_player
      );
    when 'REPLACE_PAIRINGS' then
      result_value := production_control.apply_tournament_setup_pairings_v1(
        input, next_revision, actor_player
      );
    when 'PREPARE_SCORING_CONTEXT' then
      result_value :=
        production_control.apply_tournament_setup_scoring_context_v1(
          input, next_revision, actor_player
        );
  end case;
  if not coalesce((result_value->>'ok')::boolean, false) then
    return result_value || pg_catalog.jsonb_build_object(
      'revision', current_revision,
      'readiness', production_control.tournament_setup_readiness_v1()
    );
  end if;
  changed_value := coalesce((result_value->>'changed')::boolean, false);
  if changed_value then
    insert into production_control.tournament_setup_context_v1 (
      tournament_id, contract_version, revision,
      updated_by_player_id, updated_by_auth_user_id
    ) values (
      '2026', 'production-tournament-setup-v1', next_revision,
      actor_player, actor_auth
    ) on conflict (tournament_id) do update set
      contract_version = excluded.contract_version,
      revision = excluded.revision,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_by_auth_user_id = excluded.updated_by_auth_user_id,
      updated_at = pg_catalog.clock_timestamp();
  else
    next_revision := current_revision;
  end if;
  target_kind := result_value->>'targetKind';
  target_id := result_value->>'targetId';
  safe_metadata := coalesce(result_value->'safeMetadata', '{}'::jsonb);
  warning_values := coalesce(result_value->'warnings', '[]'::jsonb);
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', case when changed_value then 'TOURNAMENT_SETUP_UPDATED'
      else 'TOURNAMENT_SETUP_NO_CHANGE' end,
    'action', action_value,
    'changed', changed_value,
    'revision', next_revision,
    'idempotent', false,
    'target', target_id,
    'targetId', target_id,
    'snapshotPrepared', coalesce(
      (result_value->>'snapshotPrepared')::boolean, false
    ),
    'warnings', warning_values,
    'readiness', production_control.tournament_setup_readiness_v1(),
    'timestamp', pg_catalog.clock_timestamp(),
    'scoringPermissionGranted', false,
    'scoringMutationCreated', false
  );
  insert into production_control.tournament_setup_audit_events_v1 (
    tournament_id, action, target_kind, target_id,
    actor_player_id, actor_auth_user_id, operation_request_id,
    prior_revision, next_revision, result, safe_metadata
  ) values (
    '2026', action_value, target_kind, target_id,
    actor_player, actor_auth, operation_request,
    current_revision, next_revision,
    case when changed_value then 'CHANGED' else 'NO_CHANGE' end,
    safe_metadata || pg_catalog.jsonb_build_object(
      'warningCount', pg_catalog.jsonb_array_length(warning_values),
      'scoringPermissionGranted', false,
      'scoringMutationCreated', false
    )
  );
  insert into production_control.tournament_setup_operation_receipts_v1 (
    tournament_id, action, operation_request_id,
    declared_request_payload_hash, database_request_payload_hash,
    actor_player_id, actor_auth_user_id, prior_revision,
    next_revision, response
  ) values (
    '2026', action_value, operation_request,
    declared_hash, database_hash, actor_player, actor_auth,
    current_revision, next_revision, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.mutate_setup_before_late_r3_v1(input jsonb) OWNER TO postgres;

--
-- Name: native_calcutta_reader_v1(text, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.native_calcutta_reader_v1(player text, target text, observer uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if observer is not null then
   if nullif(btrim(player),'') is not null then return false; end if;
   return public.read_native_review_context_v1(observer,target)->>'ok'='true';
 end if;
 return nullif(btrim(player),'') is not null and exists(select 1 from scoring_authority.tournament_players m
  where m.tournament_id=target and m.player_id=player and m.participation_status='ACTIVE');
end;
$$;


ALTER FUNCTION production_control.native_calcutta_reader_v1(player text, target text, observer uuid) OWNER TO postgres;

--
-- Name: native_published_skins_labels_v1(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.native_published_skins_labels_v1(target text, engine jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare detail jsonb; labels jsonb := '[]'; players jsonb; team jsonb; course jsonb; tournament_name text;
begin
  if engine->>'calculationPolicy' is distinct from 'production-full-course-handicap-v1'
    or jsonb_typeof(engine->'fullNetDetail') is distinct from 'array' then return null; end if;
  select name into strict tournament_name from scoring_authority.tournaments where tournament_id=target;
  for detail in select value from jsonb_array_elements(engine->'fullNetDetail') loop
    if detail->>'policy' is distinct from 'production-full-course-handicap-v1'
      or detail->>'official' is distinct from 'true' then return null; end if;
    select jsonb_build_object('courseId',s.course_id,'name',nullif(g.course_name,''),'tee',s.tee)
      into course from scoring_authority.matches m
      join scoring_authority.scoring_snapshots s on s.snapshot_id=m.scoring_snapshot_id
        and s.match_id=m.match_id and s.tournament_id=target
      left join scoring_authority.game_center_presentations g on g.match_id=m.match_id and g.tournament_id=target
      where m.match_id=detail->>'matchId' and m.tournament_id=target and m.status='FINAL'
        and m.scorecard_complete and s.snapshot_id=detail->>'snapshotId';
    if course is null then return null; end if;
    select jsonb_agg(jsonb_build_object('playerId',p.player_id,'name',p.display_name) order by ids.ordinality)
      into players from jsonb_array_elements_text(detail->'playerIds') with ordinality ids(id,ordinality)
      join scoring_authority.match_participants mp on mp.match_id=detail->>'matchId' and mp.player_id=ids.id
      join scoring_authority.players p on p.player_id=mp.player_id;
    if jsonb_array_length(players) is distinct from jsonb_array_length(detail->'playerIds') then return null; end if;
    select jsonb_build_object('teamId',t.team_id,'name',t.name) into team
      from scoring_authority.teams t where t.tournament_id=target and t.team_side=(
        select min(mp.team_side) from scoring_authority.match_participants mp
        where mp.match_id=detail->>'matchId' and detail->'playerIds' ? mp.player_id
        having count(distinct mp.team_side)=1);
    if team is null then return null; end if;
    labels:=labels||jsonb_build_array(jsonb_build_object('entryId',detail->>'entryId',
      'matchId',detail->>'matchId','players',players,'team',team,'course',course));
  end loop;
  return jsonb_build_object('tournamentName',tournament_name,'entries',labels);
end;
$$;


ALTER FUNCTION production_control.native_published_skins_labels_v1(target text, engine jsonb) OWNER TO postgres;

--
-- Name: net_skins_entries_projection_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.net_skins_entries_projection_v1(target text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare rr record; saved production_control.net_skins_entry_revisions_v1%rowtype;
  field jsonb; rows jsonb; stale jsonb; result jsonb:='[]'; item jsonb; old jsonb; eligible integer;
begin
  for rr in select round_number,format from scoring_authority.rounds where tournament_id=target
    and format in('BB','SC','SI') order by round_number loop
    select * into saved from production_control.net_skins_entry_revisions_v1 where tournament_id=target
      and round_number=rr.round_number order by revision desc limit 1;
    field:=production_control.net_skins_entry_field_v1(target,rr.round_number); rows:='[]'; eligible:=0;
    for item in select value from jsonb_array_elements(field) loop
      select value into old from jsonb_array_elements(coalesce(saved.entries,'[]'))
        where value->>'key'=item->>'key' and value->>'bindingFingerprint'=item->>'bindingFingerprint';
      if saved.configured and old->>'entered'='true' then eligible:=eligible+1; end if;
      rows:=rows||jsonb_build_array(item||jsonb_build_object('entered',coalesce(saved.configured and old->>'entered'='true',false)));
    end loop;
    select coalesce(jsonb_agg(e),'[]') into stale from jsonb_array_elements(coalesce(saved.entries,'[]')) e
      where e->>'entered'='true' and not exists(select 1 from jsonb_array_elements(field) f
        where f->>'key'=e->>'key' and f->>'bindingFingerprint'=e->>'bindingFingerprint');
    result:=result||jsonb_build_array(jsonb_build_object('roundNumber',rr.round_number,'format',rr.format,
      'scope',case rr.format when 'SC' then 'PAIR' else 'PLAYER' end,'revision',coalesce(saved.revision,0),
      'configured',coalesce(saved.configured,false),'source','DIRECTOR_EXPLICIT_ROUND_ENTRY_V1',
      'savedAt',saved.created_at,'fieldFingerprint',production_control.tournament_setup_hash_v1(field),
      'entrants',rows,'staleEntries',stale,'enteredCount',eligible,
      'state',case when jsonb_array_length(stale)>0 then 'REVIEW_REQUIRED' when not coalesce(saved.configured,false)
        then 'NOT_CONFIGURED' when jsonb_array_length(field)=0 then 'WAITING_FOR_PAIRINGS' else 'ENTRIES_SAVED' end));
  end loop;
  return jsonb_build_object('contract','production-net-skins-entries-v1','tournamentId',target,'rounds',result);
end;
$$;


ALTER FUNCTION production_control.net_skins_entries_projection_v1(target text) OWNER TO postgres;

--
-- Name: net_skins_entry_field_v1(text, integer); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.net_skins_entry_field_v1(target text, rn integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
with candidates as (
  select m.match_id,m.round_number,coalesce(d.match_number,g.match_sort_order) match_number,m.format,p.team_side,
    case when m.format='SC' then 0 else p.player_slot end slot,
    jsonb_agg(p.player_id order by p.player_slot) ids,
    jsonb_agg(jsonb_build_object('id',p.player_id,'name',person.display_name) order by p.player_slot) players,
    min(tp.team_id) team_id,min(t.name) team_name,
    coalesce((select max(a.next_revision) from production_control.tournament_setup_audit_events_v1 a
      where a.tournament_id=target and a.result='CHANGED' and
      ((a.action='REPLACE_PAIRINGS' and a.target_id=m.match_id) or
       (a.action='REPLACE_ROUND_PAIRINGS' and a.safe_metadata->'changedMatches' ? m.match_id))),0) pairing_revision
  from scoring_authority.matches m join scoring_authority.match_participants p using(match_id)
  left join scoring_authority.tournament_setup_match_details_v1 d on d.match_id=m.match_id
  left join scoring_authority.game_center_presentations g on g.match_id=m.match_id
  join scoring_authority.tournament_players tp on tp.tournament_id=m.tournament_id and tp.player_id=p.player_id
    and tp.participation_status='ACTIVE' and tp.team_side=p.team_side
  join scoring_authority.players person on person.player_id=p.player_id
  join scoring_authority.teams t on t.tournament_id=tp.tournament_id and t.team_id=tp.team_id
  where m.tournament_id=target and m.round_number=rn and m.format in('BB','SC','SI')
    and m.format=(select format from scoring_authority.rounds where tournament_id=target and round_number=rn)
  group by m.match_id,m.round_number,d.match_number,g.match_sort_order,m.format,p.team_side,
    case when m.format='SC' then 0 else p.player_slot end
  having count(*)=case m.format when 'SC' then 2 else 1 end and count(distinct tp.team_id)=1
), items as (
  select match_number,team_side,slot,jsonb_build_object(
    'key',match_id||':'||team_side||':'||slot,'matchId',match_id,'matchNumber',match_number,
    'roundNumber',round_number,'format',format,'scope',case format when 'SC' then 'PAIR' else 'PLAYER' end,
    'playerIds',ids,'players',players,'teamId',team_id,'teamName',team_name,
    'bindingFingerprint',production_control.tournament_setup_hash_v1(jsonb_build_object(
      'tournament',target,'round',rn,'match',match_id,'format',format,'side',team_side,
      'players',ids,'team',team_id,'pairingRevision',pairing_revision))) item from candidates
)
select coalesce(jsonb_agg(item order by match_number,item->>'matchId',team_side,slot),'[]') from items;
$$;


ALTER FUNCTION production_control.net_skins_entry_field_v1(target text, rn integer) OWNER TO postgres;

