--
-- Name: normalized_google_writer_fence_protections(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.normalized_google_writer_fence_protections(input jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'sheetId', (value->>'sheetId')::bigint,
    'protectedRangeId', (value->>'protectedRangeId')::bigint,
    'description', value->>'description',
    'warningOnly', value->'warningOnly',
    'dedicatedRequestingUserCanEdit',
      value->'dedicatedRequestingUserCanEdit',
    'legacyRequestingUserCanEdit', value->'legacyRequestingUserCanEdit'
  ) order by (value->>'sheetId')::bigint), '[]'::jsonb)
  from pg_catalog.jsonb_array_elements(input) value
$$;


ALTER FUNCTION production_control.normalized_google_writer_fence_protections(input jsonb) OWNER TO postgres;

--
-- Name: normalized_vercel_alias_inventory(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.normalized_vercel_alias_inventory(input jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
    pg_catalog.lower(value->>0),
    value->>1,
    pg_catalog.lower(value->>2),
    case when value->3 = 'null'::jsonb then null
      else pg_catalog.lower(value->>3) end,
    case when value->4 = 'null'::jsonb then null
      else (value->>4)::integer end
  ) order by pg_catalog.lower(value->>0) collate "C"), '[]'::jsonb)
  from pg_catalog.jsonb_array_elements(input) value
$$;


ALTER FUNCTION production_control.normalized_vercel_alias_inventory(input jsonb) OWNER TO postgres;

--
-- Name: normalized_vercel_origin_inventory(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.normalized_vercel_origin_inventory(input jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
    value->>0,
    case when value->1 = 'null'::jsonb then null
      else pg_catalog.lower(value->>1) end,
    pg_catalog.lower(pg_catalog.rtrim(value->>2, '/')),
    value->>3,
    value->>4,
    value->>5
  ) order by (value->>0) collate "C",
    pg_catalog.lower(pg_catalog.rtrim(value->>2, '/'))), '[]'::jsonb)
  from pg_catalog.jsonb_array_elements(input) value
$$;


ALTER FUNCTION production_control.normalized_vercel_origin_inventory(input jsonb) OWNER TO postgres;

--
-- Name: normalized_vercel_probe_records(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.normalized_vercel_probe_records(input jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
    pg_catalog.lower(pg_catalog.rtrim(value->>0, '/')),
    value->>1,
    case when value->2 = 'null'::jsonb then null else value->>2 end,
    case when value->3 = 'null'::jsonb then null
      else pg_catalog.lower(value->>3) end,
    case when value->4 = 'null'::jsonb then null else value->>4 end,
    case when value->5 = 'null'::jsonb then null else value->>5 end,
    case when value->6 = 'null'::jsonb then null else value->>6 end,
    case when value->7 = 'null'::jsonb then null else (
      select coalesce(pg_catalog.jsonb_agg(capability #>> '{}'
        order by (capability #>> '{}') collate "C"), '[]'::jsonb)
      from pg_catalog.jsonb_array_elements(value->7) capability
    ) end,
    value->8,
    case when pg_catalog.jsonb_typeof(value->9) = 'array' then (
      select pg_catalog.jsonb_agg(pg_catalog.lower(proof #>> '{}') order by n)
      from pg_catalog.jsonb_array_elements(value->9)
        with ordinality proofs(proof, n)
    ) else value->9 end,
    value->>10
  ) order by pg_catalog.lower(pg_catalog.rtrim(value->>0, '/'))
      collate "C"),
  '[]'::jsonb)
  from pg_catalog.jsonb_array_elements(input) value
$$;


ALTER FUNCTION production_control.normalized_vercel_probe_records(input jsonb) OWNER TO postgres;

