-- Name: normalized_vercel_probe_scope(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.normalized_vercel_probe_scope(input jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
    value->0, value->1, value->2, value->3, value->4,
    value->5, value->6, value->7, value->8
  ) order by (value->>0) collate "C"), '[]'::jsonb)
  from pg_catalog.jsonb_array_elements(input) value
$$;


ALTER FUNCTION production_control.normalized_vercel_probe_scope(input jsonb) OWNER TO postgres;

--
-- Name: odds_publication_blocks_setup_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.odds_publication_blocks_setup_v1(target text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select
    exists (
      select 1
      from scoring_authority.odds_publication_public_pointer_v1 pointer
      where pointer.tournament_id = target
        and pointer.publication_state = 'PUBLISHED'
        and pointer.current_snapshot_id is not null
    )
    or exists (
      select 1 from scoring_authority.odds_calculation_jobs job
      where job.tournament_id = target
        and (
          job.status in ('PENDING', 'RUNNING', 'RETRYABLE')
          or (job.status = 'SUCCEEDED' and job.publication_status = 'READY')
        )
    )
$$;


ALTER FUNCTION production_control.odds_publication_blocks_setup_v1(target text) OWNER TO postgres;

--
-- Name: odds_publication_effective_revision_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.odds_publication_effective_revision_v1(snapshot jsonb, publication jsonb) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  explicit_revision text := coalesce(
    snapshot->>'publication_state_revision', ''
  );
  legacy_revision text := coalesce(snapshot->>'publication_revision', '');
begin
  if explicit_revision ~ '^[0-9]+$' then
    return explicit_revision::bigint;
  end if;
  if (not snapshot ? 'publication_state_revision'
        or pg_catalog.jsonb_typeof(snapshot->'publication_state_revision') =
          'null')
     and publication->>'adoption_kind' = 'LEGACY_GOOGLE_ADOPTED'
     and snapshot->>'authority_contract_version' =
       'legacy-google-published-odds-v1'
     and legacy_revision ~ '^[0-9]+$' then
    return legacy_revision::bigint;
  end if;
  return null;
exception when invalid_text_representation or numeric_value_out_of_range then
  return null;
end;
$_$;


ALTER FUNCTION production_control.odds_publication_effective_revision_v1(snapshot jsonb, publication jsonb) OWNER TO postgres;

