--
-- Name: prediction_settings_canonical_json_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.prediction_settings_canonical_json_v1(value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
declare
  value_type text := pg_catalog.jsonb_typeof(value);
  result_value text;
begin
  if value_type = 'object' then
    select '{' || coalesce(pg_catalog.string_agg(
      pg_catalog.to_jsonb(entry.key)::text || ':' ||
        production_control.prediction_settings_canonical_json_v1(entry.value),
      ',' order by entry.key collate "C"
    ), '') || '}'
      into result_value
    from pg_catalog.jsonb_each(value) entry;
    return result_value;
  elsif value_type = 'array' then
    select '[' || coalesce(pg_catalog.string_agg(
      production_control.prediction_settings_canonical_json_v1(entry.value),
      ',' order by entry.ordinality
    ), '') || ']'
      into result_value
    from pg_catalog.jsonb_array_elements(value) with ordinality entry;
    return result_value;
  elsif value_type = 'number' then
    return production_control.prediction_settings_json_number_v1(value);
  end if;
  return value::text;
end;
$$;


ALTER FUNCTION production_control.prediction_settings_canonical_json_v1(value jsonb) OWNER TO postgres;

--
-- Name: prediction_settings_hash_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.prediction_settings_hash_v1(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
  select pg_catalog.encode(extensions.digest(
    production_control.prediction_settings_canonical_json_v1(value),
    'sha256'
  ), 'hex')
$$;


