--
-- Name: read_annual_calcutta_v1(text, text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.read_annual_calcutta_v1(target text, participant_player text, observer_auth uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  started_at timestamptz := pg_catalog.clock_timestamp();
  current_value scoring_authority.calcutta_v1_current%rowtype;
  configuration_value scoring_authority.calcutta_v1_configuration_revisions%rowtype;
  auction_value scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  publication_value scoring_authority.calcutta_v1_publication_revisions%rowtype;
  result_value scoring_authority.calcutta_v1_result_revisions%rowtype;
  job_value scoring_authority.calcutta_v1_recalculation_jobs%rowtype;
  source_value jsonb;
  source_fingerprint text;
  completed_rounds integer[] := '{}'::integer[];
  market_value jsonb;
  participant_result jsonb;
  state_value text;
  result_fresh boolean := false;
  result_stale boolean := false;
  updating boolean := false;
  expose_result boolean := false;
begin
  if not production_control.native_calcutta_reader_v1(participant_player,target,observer_auth) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CALCUTTA_PARTICIPANT_RESOURCE_REQUIRED';
  end if;
  select value.* into current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = target;
  if current_value.tournament_id is null then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'data', pg_catalog.jsonb_build_object(
        'contract_version', 'production-calcutta-v1',
        'tournament_id', target, 'state', 'NOT_CONFIGURED',
        'publication_policy',
          'DIRECTOR_CONTROLLED_PARTICIPANT_FULL_MARKET',
        'publication_state', 'UNPUBLISHED', 'published', false,
        'currency_code', 'USD', 'configuration_revision', 0,
        'auction_revision', 0, 'publication_revision', 0,
        'result_revision', null, 'configuration_fingerprint', null,
        'auction_fingerprint', null, 'result_fingerprint', null,
        'revision', 'calcutta-v1:0:0:0:0:NOT_CONFIGURED:UNPUBLISHED',
        'freshness', pg_catalog.jsonb_build_object(
          'stale', false, 'updating', false, 'configured_at', null,
          'auction_recorded_at', null, 'published_at', null,
          'calculated_at', null, 'source_fingerprint', null
        ), 'market', null, 'result', null, 'query_ms', 0
      )
    );
  end if;
  select value.* into strict configuration_value
  from scoring_authority.calcutta_v1_configuration_revisions value
  where value.configuration_revision_id =
    current_value.configuration_revision_id
    and value.tournament_id = target;
  if current_value.auction_revision > 0 then
    select value.* into strict auction_value
    from scoring_authority.calcutta_v1_auction_fact_revisions value
    where value.auction_revision_id = current_value.auction_revision_id
      and value.tournament_id = target;
    source_value := production_control.calcutta_v1_source_revision(target);
    source_fingerprint := production_control.calcutta_v1_hash(source_value);
    completed_rounds :=
      production_control.calcutta_v1_completed_rounds(target);
    select value.* into result_value
    from scoring_authority.calcutta_v1_result_revisions value
    where value.tournament_id = target
      and value.configuration_revision = current_value.configuration_revision
      and value.configuration_fingerprint =
        current_value.configuration_fingerprint
      and value.auction_revision = current_value.auction_revision
      and value.auction_fingerprint = current_value.auction_fingerprint
      and value.is_current limit 1;
    result_fresh := result_value.result_id is not null
      and result_value.source_fingerprint = source_fingerprint;
    result_stale := result_value.result_id is not null
      and result_value.source_fingerprint <> source_fingerprint;
    select value.* into job_value
    from scoring_authority.calcutta_v1_recalculation_jobs value
    where value.tournament_id = target
      and value.configuration_revision = current_value.configuration_revision
      and value.configuration_fingerprint =
        current_value.configuration_fingerprint
      and value.auction_revision = current_value.auction_revision
      and value.auction_fingerprint = current_value.auction_fingerprint
      and value.source_fingerprint = source_fingerprint
    order by value.requested_at desc, value.job_id desc limit 1;
    updating := (job_value.job_id is not null
      and job_value.status in ('PENDING', 'RUNNING'))
      or exists (select 1 from scoring_authority.score_derived_intents_v1 intent
        where intent.tournament_id = target and intent.family = 'CALCUTTA'
          and intent.status in ('PENDING', 'RETRYABLE'));
  end if;
  if current_value.publication_revision > 0 then
    select value.* into strict publication_value
    from scoring_authority.calcutta_v1_publication_revisions value
    where value.publication_revision_id =
      current_value.publication_revision_id
      and value.tournament_id = target;
  end if;
  state_value := case
    when current_value.state = 'NOT_CONFIGURED' then 'NOT_CONFIGURED'
    when current_value.auction_revision = 0 then 'CONFIGURED'
    when result_fresh and result_value.result_state = 'OFFICIAL'
      then 'OFFICIAL'
    when result_fresh and pg_catalog.jsonb_array_length(
      result_value.engine_result_payload->'completedRounds'
    ) > 0 then 'IN_PROGRESS'
    when result_fresh then 'AUCTION_COMPLETE'
    when result_stale and updating
      and result_value.result_state = 'OFFICIAL'
      and not (3 = any(completed_rounds)) then 'UNAVAILABLE'
    when result_stale and updating
      and result_value.result_state = 'OFFICIAL' then 'OFFICIAL'
    when result_stale and updating and pg_catalog.jsonb_array_length(
      result_value.engine_result_payload->'completedRounds'
    ) > 0 then 'IN_PROGRESS'
    when result_stale and updating then 'AUCTION_COMPLETE'
    when result_stale then 'UNAVAILABLE'
    when job_value.job_id is not null and job_value.status = 'FAILED'
      then 'UNAVAILABLE'
    else 'AUCTION_COMPLETE' end;
  expose_result := current_value.publication_state = 'PUBLISHED'
    and result_value.result_id is not null and state_value <> 'UNAVAILABLE';
  if current_value.publication_state = 'PUBLISHED' then
    market_value := pg_catalog.jsonb_build_object(
      'pot', (auction_value.auction_manifest->>'pot')::numeric::text,
      'purchases', coalesce((
        select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'player', pg_catalog.jsonb_build_object(
            'player_id', purchase->>'player_id',
            'display_name', entrant.display_name
          ), 'purchase_price',
            (purchase->>'purchase_price')::numeric::text,
          'owners', coalesce((
            select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
              'player', pg_catalog.jsonb_build_object(
                'player_id', ownership->>'owner_player_id',
                'display_name', owner_player.display_name
              ), 'ownership_fraction',
                (ownership->>'ownership_fraction')::numeric::text
            ) order by ownership->>'owner_player_id'
            ) from pg_catalog.jsonb_array_elements(
              auction_value.auction_manifest->'ownership'
            ) ownership join scoring_authority.players owner_player
              on owner_player.player_id = ownership->>'owner_player_id'
            where ownership->>'player_id' = purchase->>'player_id'
          ), '[]'::jsonb)
        ) order by purchase->>'player_id')
        from pg_catalog.jsonb_array_elements(
          auction_value.auction_manifest->'purchases'
        ) purchase join scoring_authority.players entrant
          on entrant.player_id = purchase->>'player_id'
      ), '[]'::jsonb)
    );
  else market_value := null; end if;
  participant_result := case when expose_result then
    production_control.project_production_calcutta_v1_result(
      result_value.engine_result_payload
    ) else null end;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'data', pg_catalog.jsonb_build_object(
      'contract_version', 'production-calcutta-v1',
      'tournament_id', target, 'state', state_value,
      'publication_policy',
        'DIRECTOR_CONTROLLED_PARTICIPANT_FULL_MARKET',
      'publication_state', current_value.publication_state,
      'published', current_value.publication_state = 'PUBLISHED',
      'currency_code', 'USD',
      'configuration_revision', current_value.configuration_revision,
      'auction_revision', current_value.auction_revision,
      'publication_revision', current_value.publication_revision,
      'result_revision', case when result_value.result_id is null
        then null else result_value.result_revision end,
      'configuration_fingerprint', case when state_value = 'NOT_CONFIGURED'
        then null else current_value.configuration_fingerprint end,
      'auction_fingerprint', current_value.auction_fingerprint,
      'result_fingerprint', case when result_value.result_id is null
        then null else result_value.payload_hash end,
      'revision', pg_catalog.format(
        'calcutta-v1:%s:%s:%s:%s:%s:%s',
        current_value.configuration_revision, current_value.auction_revision,
        current_value.publication_revision,
        case when result_value.result_id is null
          then 0 else result_value.result_revision end,
        state_value, current_value.publication_state
      ),
      'freshness', pg_catalog.jsonb_build_object(
        'stale', result_stale, 'updating', updating,
        'configured_at', configuration_value.configured_at,
        'auction_recorded_at', auction_value.recorded_at,
        'published_at', case when current_value.publication_state = 'PUBLISHED'
          then publication_value.published_at else null end,
        'calculated_at', result_value.calculated_at,
        'source_fingerprint', source_fingerprint
      ), 'market', market_value, 'result', participant_result,
      'query_ms', pg_catalog.round(extract(epoch from
        (pg_catalog.clock_timestamp() - started_at)) * 1000, 3)
    )
  );
end;
$$;


ALTER FUNCTION production_control.read_annual_calcutta_v1(target text, participant_player text, observer_auth uuid) OWNER TO postgres;

--
-- Name: read_annual_net_skins_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.read_annual_net_skins_v1(target text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  revision_value scoring_authority.net_skins_v1_configuration_revisions%rowtype;
  job_value scoring_authority.net_skins_v1_recalculation_jobs%rowtype;
  result_value scoring_authority.net_skins_v1_result_revisions%rowtype;
  round_value jsonb;
  source_value jsonb;
  source_fingerprint text;
  source_fingerprints jsonb := '{}'::jsonb;
  entries_value jsonb;
  eligible_players jsonb;
  rounds_value jsonb := '[]'::jsonb;
  round_state text;
  top_state text;
  round_stale boolean;
  any_unavailable boolean := false;
  any_in_progress boolean := false;
  all_official boolean := true;
  max_result_revision bigint := 0;
  max_calculated_at timestamptz;
  max_published_at timestamptz;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select pointer_value.* into strict pointer
  from production_control.current_tournament_pointer_v1 pointer_value
  where pointer_value.scope_key = 'BAGGER_INV_PRODUCTION'
    and pointer_value.tournament_id = target;
  select generation_value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 generation_value
  where generation_value.tournament_id = pointer.tournament_id
    and generation_value.pointer_revision = pointer.pointer_revision
    and generation_value.generation_status = 'ACTIVE';
  if target = '2026' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_NET_SKINS_RUNTIME_REQUIRED';
  end if;

  select value.* into current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = target;
  if current_value.tournament_id is null
     or current_value.state = 'NOT_CONFIGURED' then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'data', pg_catalog.jsonb_build_object(
        'contract_version', 'production-net-skins-v1',
        'tournament_id', target, 'state', 'NOT_CONFIGURED',
        'publication_policy', 'OFFICIAL_ONLY',
        'configuration_revision', coalesce(
          current_value.configuration_revision, 0
        ), 'result_revision', null, 'configuration_fingerprint', null,
        'revision', pg_catalog.format(
          'net-skins-v1:%s:0:NOT_CONFIGURED',
          coalesce(current_value.configuration_revision, 0)
        ),
        'freshness', pg_catalog.jsonb_build_object(
          'stale', false, 'configured_at', null, 'calculated_at', null,
          'published_at', null, 'source_fingerprint', null
        ), 'rounds', '[]'::jsonb
      )
    );
  end if;
  select value.* into strict revision_value
  from scoring_authority.net_skins_v1_configuration_revisions value
  where value.configuration_revision_id =
    current_value.configuration_revision_id
    and value.tournament_id = target;
  if revision_value.authority_epoch_id is distinct from
       generation.authority_generation_id
     or revision_value.activation_revision <> pointer.pointer_revision then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_NET_SKINS_RUNTIME_REQUIRED';
  end if;

  for round_value in
    select value from pg_catalog.jsonb_array_elements(
      revision_value.configuration_manifest->'rounds'
    ) value order by (value->>'round_number')::integer
  loop
    source_value := production_control.net_skins_v1_round_source_revision(
      target, (round_value->>'round_number')::integer
    );
    source_fingerprint := production_control.net_skins_v1_hash(source_value);
    source_fingerprints := source_fingerprints ||
      pg_catalog.jsonb_build_object(
        round_value->>'round_number', source_fingerprint
      );
    job_value := null;
    select value.* into job_value
    from scoring_authority.net_skins_v1_recalculation_jobs value
    where value.tournament_id = target
      and value.runtime_generation_id = generation.runtime_generation_id
      and value.round_number = (round_value->>'round_number')::integer
      and value.configuration_revision = current_value.configuration_revision
    order by value.requested_at desc, value.job_id desc limit 1;
    result_value := null;
    select value.* into result_value
    from scoring_authority.net_skins_v1_result_revisions value
    join scoring_authority.net_skins_v1_recalculation_jobs result_job
      on result_job.job_id = value.job_id
     and result_job.tournament_id = value.tournament_id
     and result_job.runtime_generation_id = generation.runtime_generation_id
    where value.tournament_id = target
      and value.round_number = (round_value->>'round_number')::integer
      and value.configuration_revision = current_value.configuration_revision
      and value.is_current limit 1;
    if result_value.result_id is not null
       and result_value.result_state = 'OFFICIAL'
       and result_value.source_fingerprint = source_fingerprint then
      round_state := 'OFFICIAL'; round_stale := false;
    elsif job_value.job_id is not null
       and job_value.source_fingerprint = source_fingerprint
       and job_value.status = 'FAILED' then
      round_state := 'UNAVAILABLE'; round_stale := true;
    elsif job_value.job_id is not null
       and job_value.source_fingerprint = source_fingerprint
       and job_value.status in ('PENDING', 'RUNNING') then
      round_state := 'IN_PROGRESS'; round_stale := true;
    elsif result_value.result_id is not null
       and result_value.result_state = 'PROVISIONAL'
       and result_value.source_fingerprint = source_fingerprint then
      round_state := 'IN_PROGRESS'; round_stale := true;
    elsif exists (
      select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = target
        and match_value.round_number =
          (round_value->>'round_number')::integer
        and (match_value.status <> 'UPCOMING' or match_value.scored_holes > 0)
    ) then
      round_state := 'IN_PROGRESS'; round_stale := true;
    else
      round_state := 'CONFIGURED'; round_stale := false;
    end if;
    entries_value := coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'entry_id', entry->>'entry_id', 'entry_type', entry->>'entry_type',
        'match_id', entry->>'match_id', 'player_ids', entry->'player_ids'
      ) order by entry->>'entry_id')
      from pg_catalog.jsonb_array_elements(round_value->'entries') entry
      where coalesce((entry->>'eligible')::boolean, false)
    ), '[]'::jsonb);
    eligible_players := coalesce((
      select pg_catalog.jsonb_agg(player_id order by player_id)
      from (select distinct pg_catalog.jsonb_array_elements_text(
        entry->'player_ids'
      ) player_id from pg_catalog.jsonb_array_elements(
        round_value->'entries'
      ) entry where coalesce((entry->>'eligible')::boolean, false)) players
    ), '[]'::jsonb);
    any_unavailable := any_unavailable or round_state = 'UNAVAILABLE';
    any_in_progress := any_in_progress or round_state = 'IN_PROGRESS';
    all_official := all_official and round_state = 'OFFICIAL';
    max_result_revision := greatest(
      max_result_revision, coalesce(result_value.result_revision, 0)
    );
    max_calculated_at := case
      when result_value.calculated_at is not null and (
        max_calculated_at is null
        or result_value.calculated_at > max_calculated_at
      ) then result_value.calculated_at else max_calculated_at end;
    max_published_at := case
      when result_value.published_at is not null and (
        max_published_at is null or result_value.published_at > max_published_at
      ) then result_value.published_at else max_published_at end;
    rounds_value := rounds_value || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'round_id', round_value->>'round_id',
        'round_number', (round_value->>'round_number')::integer,
        'format', round_value->>'format',
        'entry_type', round_value->>'entry_type',
        'buy_in_per_entry', (round_value->>'buy_in_per_entry')::numeric,
        'eligible_entry_count', pg_catalog.jsonb_array_length(entries_value),
        'eligible_player_ids', eligible_players,
        'match_ids', round_value->'match_ids', 'entries', entries_value,
        'state', round_state,
        'configuration_revision', current_value.configuration_revision,
        'result_revision', case when result_value.result_id is null
          then null else result_value.result_revision end,
        'configuration_fingerprint',
          round_value->>'configuration_fingerprint',
        'freshness', pg_catalog.jsonb_build_object(
          'stale', round_stale, 'calculated_at', result_value.calculated_at,
          'published_at', case when round_state = 'OFFICIAL'
            then result_value.published_at else null end,
          'source_fingerprint', source_fingerprint
        ),
        'result_payload', case when round_state = 'OFFICIAL'
          then result_value.engine_result_payload || jsonb_build_object('participantLabels', production_control.native_published_skins_labels_v1(target,result_value.engine_result_payload)) else null end,
        'official_results', case when round_state = 'OFFICIAL'
          then result_value.public_result_payload else null end
      )
    );
  end loop;
  top_state := case when any_unavailable then 'UNAVAILABLE'
    when all_official and pg_catalog.jsonb_array_length(rounds_value) > 0
      then 'OFFICIAL'
    when any_in_progress or exists (
      select 1 from pg_catalog.jsonb_array_elements(rounds_value) value
      where value->>'state' = 'OFFICIAL'
    ) then 'IN_PROGRESS' else 'CONFIGURED' end;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'data', pg_catalog.jsonb_build_object(
      'contract_version', 'production-net-skins-v1',
      'tournament_id', target, 'state', top_state,
      'publication_policy', 'OFFICIAL_ONLY',
      'configuration_revision', current_value.configuration_revision,
      'result_revision', case when max_result_revision = 0
        then null else max_result_revision end,
      'configuration_fingerprint', revision_value.configuration_fingerprint,
      'revision', pg_catalog.format(
        'net-skins-v1:%s:%s:%s', current_value.configuration_revision,
        max_result_revision, top_state
      ),
      'freshness', pg_catalog.jsonb_build_object(
        'stale', any_unavailable or any_in_progress,
        'configured_at', revision_value.configured_at,
        'calculated_at', max_calculated_at,
        'published_at', max_published_at,
        'source_fingerprint',
          production_control.net_skins_v1_hash(source_fingerprints)
      ), 'rounds', rounds_value
    )
  );
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_NET_SKINS_RUNTIME_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.read_annual_net_skins_v1(target text) OWNER TO postgres;

--
-- Name: read_certification_future_match_control_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.read_certification_future_match_control_v1(input jsonb, context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare target text; matches_value jsonb;
begin
 perform production_control.assert_current_certification_future_context_v1(context);
 if context->>'phase' is distinct from 'DIRECTOR' then raise exception using errcode='42501',message='CERTIFICATION_FUTURE_CONTEXT_REQUIRED';end if;
 target:=production_control.assert_canonical_future_identity_runtime_v1(context);
 perform production_control.assert_canonical_future_scoring_actor_v1(input,target,true,context);
 select coalesce(jsonb_agg(jsonb_build_object('matchId',m.match_id,'round',m.round_number,'format',m.format,'status',m.status,
  'matchRevision',m.match_revision,'permissionRevision',m.permission_revision,
  'scorecardComplete',m.scorecard_complete,'unresolvedMutations',m.unresolved_mutations,
  'resultWinner',m.result_winner,'scoringLocked',m.scoring_locked,
  'scoringReady',coalesce((production_control.assert_future_production_match_scoring_ready_v1(m.match_id,target)->>'ready')::boolean,false),
  'permissionComplete',(select count(*) from scoring_authority.scoring_permissions p where p.match_id=m.match_id)=
   (select count(*) from scoring_authority.match_participants p where p.match_id=m.match_id)
   and exists(select 1 from scoring_authority.match_participants p where p.match_id=m.match_id),
  'accessState',case when not exists(select 1 from scoring_authority.scoring_permissions p where p.match_id=m.match_id and p.can_score and p.revoked_at is null) then 'REVOKED'
   when not exists(select 1 from scoring_authority.scoring_permissions p where p.match_id=m.match_id and (not p.can_score or p.revoked_at is not null or p.permission_revision<>m.permission_revision)) then 'ACTIVE' else 'MIXED' end)
  order by m.round_number,m.match_id),'[]') into matches_value from scoring_authority.matches m where m.tournament_id=target;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('tournament',jsonb_build_object('tournamentId',target),'matches',matches_value));
end;$$;


ALTER FUNCTION production_control.read_certification_future_match_control_v1(input jsonb, context jsonb) OWNER TO postgres;

--
-- Name: read_certification_score_recovery_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.read_certification_score_recovery_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare payload jsonb:=input->'payload'; original text; required_type text;
 l production_control.certification_ingress_leases_v1%rowtype;
 receipt scoring_authority.score_mutations%rowtype;
 recovery_input jsonb; director_read boolean:=input->>'operation_id'='SCORING.READ_DIRECTOR_OPERATION_STATUS';
begin
 if jsonb_typeof(payload) is distinct from 'object'
  or coalesce(payload->>'match_id','') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$'
  or coalesce(payload->>'mutation_key','') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'
  or payload->>'mutation_key' is distinct from input->>'operation_request_id'
  or exists(select 1 from jsonb_object_keys(payload) k where k not in('match_id','mutation_key','action','expected_match_revision')) then
  raise exception using errcode='22023',message='CERTIFICATION_OPERATION_RECOVERY_INPUT_REQUIRED';end if;
 if director_read then
  if input->>'phase' is distinct from 'DIRECTOR' or input#>>'{authorization,role}' is distinct from 'DIRECTOR'
   or payload->>'action' not in('finalize','reopen') or payload->>'action' is null then
   raise exception using errcode='42501',message='CERTIFICATION_OPERATION_RECOVERY_AUTHORIZATION_REQUIRED';end if;
  original:=case payload->>'action' when 'finalize' then 'SCORING.FINALIZE_MATCH' else 'SCORING.REOPEN_MATCH' end;
  required_type:=upper(payload->>'action');
 elsif input->>'operation_id'='SCORING.READ_MUTATION_STATUS' and input->>'phase'='READS' then
  original:='SCORING.SUBMIT_HOLE';required_type:='HOLE_SCORE';
 else raise exception using errcode='42501',message='CERTIFICATION_OPERATION_NOT_ADMITTED';end if;
 recovery_input:=input||jsonb_build_object('operation_id',original,'payload',jsonb_build_object('match_id',payload->>'match_id'));
 l:=production_control.certification_ingress_lookup_v1(recovery_input,false);
 if l.lease_id is not null and l.state='COMMITTED' and not coalesce((l.result->>'semantic_noop')::boolean,false) then
  select m.* into receipt from scoring_authority.score_mutations m
   join scoring_authority.matches mt using(match_id)
   where m.match_id=l.match_id and m.mutation_key=l.operation_request_id and mt.tournament_id=l.tournament_id
    and m.actor_id=l.actor_player_id and m.mutation_type=required_type
    and (director_read or m.originating_auth_user_id=l.actor_auth_user_id);
  if not found or receipt.result->>'ok' is distinct from 'true'
    or receipt.result->>'match_id' is distinct from l.match_id then
   raise exception using errcode='55000',message='CERTIFICATION_INGRESS_RECEIPT_CONTRADICTION';end if;
  if director_read then return jsonb_build_object('ok',true,'committed',true,'receipt',receipt.result||jsonb_build_object('idempotent',true));end if;
  if receipt.result->>'code' is distinct from 'ACCEPTED' then
   raise exception using errcode='55000',message='CERTIFICATION_INGRESS_RECEIPT_CONTRADICTION';end if;
  return jsonb_build_object('ok',true,'contract','score-mutation-recovery-v1','status','COMMITTED',
   'match_id',l.match_id,'mutation_key',l.operation_request_id,'result',receipt.result);
 end if;
 -- NOT_COMMITTED is an internal fenced ingress outcome. The established score
 -- recovery DTO remains conservative and does not acquire a new negative claim.
 if director_read then return jsonb_build_object('ok',true,'committed',false,'status','UNKNOWN');end if;
 return jsonb_build_object('ok',true,'contract','score-mutation-recovery-v1','status','UNKNOWN',
  'match_id',payload->>'match_id','mutation_key',payload->>'mutation_key');
end;$_$;


ALTER FUNCTION production_control.read_certification_score_recovery_v1(input jsonb) OWNER TO postgres;

--
-- Name: read_dormant_worker_status(text, text, text, text, text, text, text, integer); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.read_dormant_worker_status(requested_worker_name text, requested_project_ref text, requested_project_url text, requested_google_workbook_id text, requested_vercel_project text, requested_canonical_domain text, requested_tournament_id text, requested_tournament_year integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  scope_row production_control.resource_scope%rowtype;
  control_row production_control.worker_controls%rowtype;
  contract_row production_control.worker_contracts%rowtype;
  lifecycle_count bigint := 0;
  checkpoint_count bigint := 0;
begin
  perform production_control.assert_exact_worker_resource_scope(
    requested_worker_name,
    requested_project_ref,
    requested_project_url,
    requested_google_workbook_id,
    requested_vercel_project,
    requested_canonical_domain,
    requested_tournament_id,
    requested_tournament_year
  );

  select * into strict scope_row
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';

  select * into strict control_row
  from production_control.worker_controls
  where worker_name = requested_worker_name;

  select * into strict contract_row
  from production_control.worker_contracts
  where worker_name = requested_worker_name;

  case requested_worker_name
    when 'ODDS_CALCULATION' then
      select count(*) into lifecycle_count from scoring_authority.odds_calculation_jobs;
      select count(*) into checkpoint_count from scoring_authority.odds_calculation_checkpoints;
    when 'ODDS_GOOGLE_MIRROR' then
      select count(*) into lifecycle_count from scoring_authority.odds_google_mirror_jobs;
      select count(*) into checkpoint_count from scoring_authority.odds_published_snapshots;
    when 'SCORING_GOOGLE_OUTBOX' then
      select count(*) into lifecycle_count from scoring_authority.google_outbox_events;
      select count(*) into checkpoint_count from scoring_authority.google_match_checkpoints;
    when 'ROUND_SCORECARDS_ARCHIVE' then
      select count(*) into lifecycle_count from scoring_authority.scorecard_archive_jobs;
      select count(*) into checkpoint_count from scoring_authority.scorecard_archive_checkpoints;
    when 'GUIDE_SYNCHRONIZATION' then
      select count(*) into lifecycle_count from scoring_authority.guide_sync_runs;
      select count(*) into checkpoint_count from scoring_authority.guide_sync_controls;
    when 'PREDICTION_SETTINGS_SYNCHRONIZATION' then
      select count(*) into lifecycle_count from scoring_authority.odds_input_import_runs;
      select count(*) into checkpoint_count from scoring_authority.odds_input_configurations;
    when 'DRAFT_SYNCHRONIZATION' then
      select count(*) into lifecycle_count from scoring_authority.draft_revisions;
      select count(*) into checkpoint_count from scoring_authority.draft_current_revisions;
    when 'NET_SKINS_SYNCHRONIZATION' then
      select count(*) into lifecycle_count from scoring_authority.net_skins_configuration_import_runs;
      select count(*) into checkpoint_count from scoring_authority.net_skins_configurations;
    when 'CALCUTTA_SYNCHRONIZATION' then
      select count(*) into lifecycle_count from scoring_authority.calcutta_configuration_import_runs;
      select count(*) into checkpoint_count from scoring_authority.calcutta_configurations;
    when 'NET_SKINS_RECALCULATION' then
      select count(*) into lifecycle_count from scoring_authority.competition_recalculation_jobs where engine_key = 'NET_SKINS';
      select count(*) into checkpoint_count from scoring_authority.competition_derived_runs where engine_key = 'NET_SKINS';
    when 'CALCUTTA_RECALCULATION' then
      select count(*) into lifecycle_count from scoring_authority.competition_recalculation_jobs where engine_key = 'CALCUTTA';
      select count(*) into checkpoint_count from scoring_authority.competition_derived_runs where engine_key = 'CALCUTTA';
    when 'COMPETITION_DERIVED' then
      select count(*) into lifecycle_count from scoring_authority.competition_recalculation_jobs;
      select count(*) into checkpoint_count from scoring_authority.competition_derived_runs;
    when 'SCORING_AUTHORITY_TRANSITION' then
      select count(*) into lifecycle_count from scoring_authority.authority_epochs;
      select count(*) into checkpoint_count from scoring_authority.ingress_gates;
  end case;

  return jsonb_build_object(
    'state', 'DORMANT',
    'worker', control_row.worker_name,
    'domain', contract_row.domain,
    'operationKind', contract_row.operation_kind,
    'contractVersion', contract_row.contract_version,
    'globalWorkersEnabled', scope_row.workers_enabled,
    'workerEnabled', control_row.enabled,
    'operationAllowed', contract_row.operation_allowed,
    'schedulerInstalled', control_row.scheduler_installed or contract_row.scheduler_installed,
    'googleWritesEnabled', scope_row.google_writes_enabled,
    'googleWritesAllowed', control_row.google_writes_allowed,
    'scoringIngressEnabled', scope_row.scoring_ingress_enabled,
    'oddsPublicationEnabled', scope_row.odds_publication_enabled,
    'lifecycleCount', lifecycle_count,
    'checkpointCount', checkpoint_count,
    'fallbackUsed', false
  );
end;
$$;


ALTER FUNCTION production_control.read_dormant_worker_status(requested_worker_name text, requested_project_ref text, requested_project_url text, requested_google_workbook_id text, requested_vercel_project text, requested_canonical_domain text, requested_tournament_id text, requested_tournament_year integer) OWNER TO postgres;

--
-- Name: read_projection(jsonb, text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.read_projection(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
