 return production_control.canonical_projection_read_v1(input,expected_domain,expected_contract,expected_tabs,null);
end;
$$;


ALTER FUNCTION production_control.read_projection(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) OWNER TO postgres;

--
-- Name: read_score_mutation_status_v1(jsonb, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.read_score_mutation_status_v1(input jsonb, target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target_match text:=input->>'match_id';
  target_mutation text:=input->>'mutation_key';
  actor text:=input#>>'{authorization,player_id}';
  actor_auth uuid;
  result_value jsonb;
begin
  if target_match is null or target_match !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$'
     or target_mutation is null or target_mutation !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'
     or input#>>'{authorization,match_id}' is distinct from target_match
     or input#>>'{authorization,tournament_id}' is distinct from target_tournament then
    raise exception using errcode='22023',message='SCORE_RECOVERY_INVALID_REQUEST';
  end if;
  -- Revalidate identity/membership, not score permission. These existing actor
  -- checks include current verified Auth linkage and current Director entitlement
  -- when a trusted Director transport supplies that role.
  if target_tournament='2026' then
    perform production_control.assert_production_scoring_actor(input,false);
  else
    perform production_control.assert_future_production_scoring_actor_v1(input,target_tournament,false);
  end if;
  actor_auth:=(input#>>'{authorization,auth_user_id}')::uuid;
  select mutation.result into result_value
    from scoring_authority.score_mutations mutation
    join scoring_authority.matches match_value using(match_id)
    where mutation.match_id=target_match and mutation.mutation_key=target_mutation
      and match_value.tournament_id=target_tournament
      and mutation.mutation_type='HOLE_SCORE' and mutation.actor_id=actor
      and mutation.originating_auth_user_id=actor_auth;
  if result_value is null then
    -- Absence may mean inflight, rollback, legacy unbound receipt, semantic
    -- NO_CHANGE, or another owner. Never expose another actor's receipt/existence.
    return jsonb_build_object('ok',true,'contract','score-mutation-recovery-v1',
      'status','UNKNOWN','match_id',target_match,'mutation_key',target_mutation);
  end if;
  if result_value->>'code' is distinct from 'ACCEPTED'
     or result_value->>'match_id' is distinct from target_match
     or result_value->>'ok' is distinct from 'true' then
    raise exception using errcode='55000',message='SCORE_RECOVERY_RECEIPT_INVALID';
  end if;
  return jsonb_build_object('ok',true,'contract','score-mutation-recovery-v1',
    'status','COMMITTED','match_id',target_match,'mutation_key',target_mutation,
    'result',result_value);
end;
$_$;


ALTER FUNCTION production_control.read_score_mutation_status_v1(input jsonb, target_tournament text) OWNER TO postgres;

--
-- Name: read_tournament_setup_before_round_workspace_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.read_tournament_setup_before_round_workspace_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  tournament_value jsonb;
  teams_value jsonb;
  roster_value jsonb;
  available_players_value jsonb;
  rounds_value jsonb;
  courses_value jsonb;
  available_course_identities_value jsonb;
  matches_value jsonb;
  audit_value jsonb;
  dependencies_value jsonb;
  readiness_value jsonb;
  revision_value bigint;
begin
  -- Admission is enforced by the public Production or isolated gateway before this private core.
  if input->>'operation'
       is distinct from 'READ_PRODUCTION_TOURNAMENT_SETUP_V1' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_TOURNAMENT_SETUP_READ_INPUT_INVALID';
  end if;
  revision_value := production_control.tournament_setup_revision_v1('2026');

  select pg_catalog.jsonb_build_object(
    'id', tournament.tournament_id,
    'year', tournament.tournament_year,
    'name', tournament.name,
    'sourceWorkbookId', tournament.source_workbook_id,
    'destination', operational.destination,
    'startDate', operational.start_date,
    'endDate', operational.end_date,
    'timezone', operational.timezone,
    'status', 'UPCOMING',
    'statusEditable', false,
    'setupRevision', operational.setup_revision
  ) into tournament_value
  from scoring_authority.tournaments tournament
  left join scoring_authority.tournament_setup_operational_v1 operational
    on operational.tournament_id = tournament.tournament_id
  where tournament.tournament_id = '2026';

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'teamId', team.team_id,
    'teamSide', team.team_side,
    'name', team.name,
    'captainPlayerId', coalesce(detail.captain_player_id,
      nullif(team.source_payload->>'Captain', '')),
    'captainName', captain.display_name,
    'activeRosterCount', (
      select pg_catalog.count(*)::integer
      from scoring_authority.tournament_players membership
      where membership.tournament_id = team.tournament_id
        and membership.team_id = team.team_id
        and membership.participation_status = 'ACTIVE'
    ),
    'setupRevision', detail.setup_revision,
    'locked', exists (
      select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = team.tournament_id
        and not production_control.handicap_v1_match_is_unstarted(
          match_value.match_id
        )
    )
  ) order by team.team_side), '[]'::jsonb) into teams_value
  from scoring_authority.teams team
  left join scoring_authority.tournament_setup_team_details_v1 detail
    on detail.tournament_id = team.tournament_id
   and detail.team_id = team.team_id
  left join scoring_authority.players captain
    on captain.player_id = coalesce(detail.captain_player_id,
      nullif(team.source_payload->>'Captain', ''))
  where team.tournament_id = '2026';

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'playerId', membership.player_id,
    'displayName', player.display_name,
    'membershipStatus', membership.participation_status,
    'teamId', membership.team_id,
    'teamSide', membership.team_side,
    'teamName', team.name,
    'tournamentHandicap', membership.tournament_handicap,
    'handicapRevisionId', membership.handicap_revision_id,
    'pairedMatchCount', (
      select pg_catalog.count(*)::integer
      from scoring_authority.match_participants participant
      join scoring_authority.matches match_value
        on match_value.match_id = participant.match_id
       and match_value.tournament_id = membership.tournament_id
      where participant.player_id = membership.player_id
    ),
    'frozenMatchCount', (
      select pg_catalog.count(*)::integer
      from scoring_authority.match_participants participant
      join scoring_authority.matches match_value
        on match_value.match_id = participant.match_id
       and match_value.tournament_id = membership.tournament_id
      where participant.player_id = membership.player_id
        and not production_control.handicap_v1_match_is_unstarted(
          match_value.match_id
        )
    ),
    'canAssignTeam', not exists (
      select 1
      from scoring_authority.match_participants participant
      join scoring_authority.matches match_value
        on match_value.match_id = participant.match_id
       and match_value.tournament_id = membership.tournament_id
      where participant.player_id = membership.player_id
        and not production_control.handicap_v1_match_is_unstarted(
          match_value.match_id
        )
    ) and pg_catalog.jsonb_array_length(
      production_control.tournament_setup_dependency_codes_v1(
        membership.player_id, membership.team_id, null, null, 'ROSTER'
      )
    ) = 0,
    'blockers', production_control.tournament_setup_dependency_codes_v1(
      membership.player_id, membership.team_id, null, null, 'ROSTER'
    ),
    'readiness', pg_catalog.jsonb_build_object(
      'teamAssigned', team.team_id is not null,
      'handicapApproved', membership.handicap_revision_id is not null
        and membership.tournament_handicap is not null
    )
  ) order by team.team_side, player.display_name, membership.player_id),
    '[]'::jsonb) into roster_value
  from scoring_authority.tournament_players membership
  join scoring_authority.players player
    on player.player_id = membership.player_id
  left join scoring_authority.teams team
    on team.tournament_id = membership.tournament_id
   and team.team_id = membership.team_id
  where membership.tournament_id = '2026';

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'playerId', player.player_id,
    'displayName', player.display_name,
    'globalStatus', production_control.access_governance_global_status_v1(
      player.player_id
    )
  ) order by player.display_name, player.player_id), '[]'::jsonb)
  into available_players_value
  from scoring_authority.players player
  where production_control.access_governance_global_status_v1(player.player_id)
      = 'ACTIVE'
    and not exists (
      select 1 from scoring_authority.tournament_players membership
      where membership.tournament_id = '2026'
        and membership.player_id = player.player_id
    );

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'roundNumber', round_value.round_number,
    'name', round_value.name,
    'format', round_value.format,
    'handicapAllowance', round_value.handicap_allowance,
    'status', round_value.status,
    'teamSize', coalesce(detail.team_size,
      case when round_value.format = 'SI' then 1 else 2 end),
    'pointsAvailable', coalesce(detail.points_available,
      nullif(round_value.source_payload->>'Points Available', '')::numeric),
    'displayOrder', coalesce(detail.display_order, round_value.round_number),
    'courseId', assignment.course_id,
    'tee', assignment.tee_id,
    'matchCount', (
      select pg_catalog.count(*)::integer
      from scoring_authority.matches match_value
      where match_value.tournament_id = round_value.tournament_id
        and match_value.round_number = round_value.round_number
    ),
    'locked', exists (
      select 1 from scoring_authority.matches match_value
      where match_value.tournament_id = round_value.tournament_id
        and match_value.round_number = round_value.round_number
        and not production_control.handicap_v1_match_is_unstarted(
          match_value.match_id
        )
    ),
    'setupRevision', detail.setup_revision
  ) order by coalesce(detail.display_order, round_value.round_number)),
    '[]'::jsonb) into rounds_value
  from scoring_authority.rounds round_value
  left join scoring_authority.tournament_setup_round_details_v1 detail
    on detail.tournament_id = round_value.tournament_id
   and detail.round_number = round_value.round_number
  left join scoring_authority.tournament_setup_round_courses_v1 assignment
    on assignment.tournament_id = round_value.tournament_id
   and assignment.round_number = round_value.round_number
  where round_value.tournament_id = '2026';

  with candidates as (
    select course.tournament_id, course.course_id, course.tee_id,
      course.display_name, course.location, course.rating, course.slope,
      course.par, course.setup_revision,
      (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'holeNumber', hole.hole_number,
        'par', hole.par,
        'strokeIndex', hole.stroke_index,
        'yardage', hole.yardage
      ) order by hole.hole_number)
      from scoring_authority.tournament_setup_course_holes_v1 hole
      where hole.tournament_id = course.tournament_id
        and hole.course_id = course.course_id
        and hole.tee_id = course.tee_id) holes,
      true setup_managed
    from scoring_authority.tournament_setup_course_tees_v1 course
    where course.tournament_id = '2026'
    union all
    select existing.*
    from (
      select distinct on (snapshot.course_id, snapshot.tee)
        snapshot.tournament_id, snapshot.course_id, snapshot.tee,
        coalesce(identity_value.canonical_name, snapshot.course_id),
        identity_value.canonical_location, snapshot.rating, snapshot.slope,
        snapshot.par, null::bigint, snapshot.hole_definitions, false
      from scoring_authority.scoring_snapshots snapshot
      left join scoring_authority.completed_history_course_identities identity_value
        on identity_value.course_id = snapshot.course_id
      where snapshot.tournament_id = '2026'
        and not exists (
          select 1
          from scoring_authority.tournament_setup_course_tees_v1 managed
          where managed.tournament_id = snapshot.tournament_id
            and managed.course_id = snapshot.course_id
            and managed.tee_id = snapshot.tee
        )
      order by snapshot.course_id, snapshot.tee,
        snapshot.snapshot_revision desc
    ) existing
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'roundNumber', assigned_round.round_number,
    'courseId', course.course_id,
    'tee', course.tee_id,
    'name', course.display_name,
    'displayName', course.display_name,
    'location', course.location,
    'city', null,
    'state', null,
    'rating', course.rating,
    'slope', course.slope,
    'par', course.par,
    'holes', coalesce(course.holes, '[]'::jsonb),
    'holeCount', pg_catalog.jsonb_array_length(coalesce(
      course.holes, '[]'::jsonb
    )),
    'complete', pg_catalog.jsonb_array_length(coalesce(
      course.holes, '[]'::jsonb
    )) = 18,
    'roundNumbers', coalesce((
      select pg_catalog.jsonb_agg(assignment.round_number
        order by assignment.round_number)
      from scoring_authority.tournament_setup_round_courses_v1 assignment
      where assignment.tournament_id = course.tournament_id
        and assignment.course_id = course.course_id
        and assignment.tee_id = course.tee_id
    ), (
      select pg_catalog.jsonb_agg(round_number order by round_number)
      from (
        select distinct match_value.round_number
        from scoring_authority.matches match_value
        join scoring_authority.scoring_snapshots snapshot
          on snapshot.snapshot_id = match_value.scoring_snapshot_id
        where match_value.tournament_id = course.tournament_id
          and snapshot.course_id = course.course_id
          and snapshot.tee = course.tee_id
      ) existing_rounds
    ), '[]'::jsonb),
    'setupManaged', course.setup_managed,
    'setupRevision', course.setup_revision,
    'locked', exists (
      select 1
      from scoring_authority.matches match_value
      join scoring_authority.scoring_snapshots snapshot
        on snapshot.snapshot_id = match_value.scoring_snapshot_id
      where match_value.tournament_id = course.tournament_id
        and snapshot.course_id = course.course_id
        and snapshot.tee = course.tee_id
        and not production_control.handicap_v1_match_is_unstarted(
          match_value.match_id
        )
    )
  ) order by assigned_round.round_number, course.display_name, course.tee_id),
    '[]'::jsonb)
  into courses_value
  from candidates course
  cross join lateral (
    select distinct source.round_number
    from (
      select assignment.round_number
      from scoring_authority.tournament_setup_round_courses_v1 assignment
      where assignment.tournament_id = course.tournament_id
        and assignment.course_id = course.course_id
        and assignment.tee_id = course.tee_id
      union all
      select match_value.round_number
      from scoring_authority.matches match_value
      join scoring_authority.scoring_snapshots snapshot
        on snapshot.snapshot_id = match_value.scoring_snapshot_id
      where match_value.tournament_id = course.tournament_id
        and snapshot.course_id = course.course_id
        and snapshot.tee = course.tee_id
    ) source
  ) assigned_round;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'courseId', identity_value.course_id,
    'name', identity_value.canonical_name,
    'location', identity_value.canonical_location,
    'requiresTeeConfiguration', true,
    'requiresHoleConfiguration', true
  ) order by identity_value.canonical_name, identity_value.course_id),
    '[]'::jsonb)
  into available_course_identities_value
  from scoring_authority.completed_history_course_identities identity_value
  where not exists (
    select 1 from scoring_authority.tournament_setup_course_tees_v1 setup_course
    where setup_course.tournament_id = '2026'
      and setup_course.course_id = identity_value.course_id
  ) and not exists (
    select 1 from scoring_authority.scoring_snapshots snapshot
    where snapshot.tournament_id = '2026'
      and snapshot.course_id = identity_value.course_id
  );

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'matchId', match_value.match_id,
    'roundNumber', match_value.round_number,
    'matchNumber', coalesce(detail.match_number,
      nullif(pg_catalog.regexp_replace(match_value.match_id, '^.*-', ''), '')::integer),
    'format', match_value.format,
    'status', match_value.status,
    'scoringLocked', match_value.scoring_locked,
    'matchRevision', match_value.match_revision,
    'permissionRevision', match_value.permission_revision,
    'courseId', coalesce(detail.course_id, snapshot.course_id),
    'courseName', coalesce(course.display_name,
      history_course.canonical_name, snapshot.course_id),
    'tee', coalesce(detail.tee_id, snapshot.tee),
    'teeTime', coalesce(detail.tee_time::text, presentation.tee_time),
    'startingHole', coalesce(detail.starting_hole,
      nullif(presentation.starting_hole, '')::integer, 1),
    'participantCount', (
      select pg_catalog.count(*)::integer
      from scoring_authority.match_participants participant
      where participant.match_id = match_value.match_id
    ),
    'scoredHoles', match_value.scored_holes,
    'scoring_ready', coalesce(
      (scoring_readiness.value->>'ready')::boolean, false
    ),
    'scoring_readiness_code', case
      when coalesce((scoring_readiness.value->>'ready')::boolean, false)
        then 'PRODUCTION_MATCH_SCORING_READY'
      else 'PRODUCTION_MATCH_NOT_SCORING_READY'
    end,
    'scoring_readiness_reasons', coalesce(
      scoring_readiness.value->'reasons', '[]'::jsonb
    ),
    'participants', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'playerId', participant.player_id,
        'displayName', player.display_name,
        'teamSide', participant.team_side,
        'playerSlot', participant.player_slot,
        'tournamentHandicap', participant.tournament_handicap,
        'finalStrokes', participant.final_strokes
      ) order by participant.team_side, participant.player_slot)
      from scoring_authority.match_participants participant
      join scoring_authority.players player
        on player.player_id = participant.player_id
      where participant.match_id = match_value.match_id
    ), '[]'::jsonb),
    'prepared', detail.prepared_setup_revision is not null
      or (snapshot.snapshot_id is not null
        and pg_catalog.jsonb_array_length(snapshot.hole_definitions) = 18),
    'preparedSetupRevision', detail.prepared_setup_revision,
    'strictlyUnstarted', production_control.handicap_v1_match_is_unstarted(
      match_value.match_id
    ),
    'accessActive', exists (
      select 1 from scoring_authority.scoring_permissions permission
      where permission.match_id = match_value.match_id
        and permission.can_score and permission.revoked_at is null
    ),
    'locked', not production_control.handicap_v1_match_is_unstarted(
      match_value.match_id
    ),
    'blockers', case
      when not production_control.handicap_v1_match_is_unstarted(
        match_value.match_id
      ) then pg_catalog.jsonb_build_array(
        'Match setup is locked because scoring has started.'
      )
      else '[]'::jsonb end,
    'warnings', case
      when (select pg_catalog.count(*)
        from scoring_authority.match_participants participant
        where participant.match_id = match_value.match_id)
        <> (case when match_value.format = 'SI' then 2 else 4 end)
      then pg_catalog.jsonb_build_array('Complete the match pairings.')
      when snapshot.handicap_revision_id is null
      then pg_catalog.jsonb_build_array(
        'Prepare the scoring context with the current approved handicaps.'
      )
      else '[]'::jsonb end,
    'snapshot', pg_catalog.jsonb_build_object(
      'id', snapshot.snapshot_id,
      'snapshotId', snapshot.snapshot_id,
      'revision', snapshot.snapshot_revision,
      'prepared', detail.prepared_setup_revision is not null
        or (snapshot.snapshot_id is not null
          and pg_catalog.jsonb_typeof(snapshot.hole_definitions) = 'array'
          and pg_catalog.jsonb_array_length(snapshot.hole_definitions) = 18),
      'current', snapshot.snapshot_id = match_value.scoring_snapshot_id,
      'courseId', snapshot.course_id,
      'tee', snapshot.tee,
      'rating', snapshot.rating,
      'slope', snapshot.slope,
      'par', snapshot.par,
      'holeCount', case
        when pg_catalog.jsonb_typeof(snapshot.hole_definitions) = 'array'
          then pg_catalog.jsonb_array_length(snapshot.hole_definitions)
        else 0 end,
      'handicapRevisionId', snapshot.handicap_revision_id,
      'canonicalHash', snapshot.canonical_hash
    )
  ) order by match_value.round_number,
    coalesce(detail.match_number, 999), match_value.match_id), '[]'::jsonb)
  into matches_value
  from scoring_authority.matches match_value
  left join scoring_authority.tournament_setup_match_details_v1 detail
    on detail.match_id = match_value.match_id
  left join scoring_authority.scoring_snapshots snapshot
    on snapshot.snapshot_id = match_value.scoring_snapshot_id
  left join scoring_authority.tournament_setup_course_tees_v1 course
    on course.tournament_id = match_value.tournament_id
   and course.course_id = coalesce(detail.course_id, snapshot.course_id)
   and course.tee_id = coalesce(detail.tee_id, snapshot.tee)
  left join scoring_authority.completed_history_course_identities history_course
    on history_course.course_id = snapshot.course_id
  left join scoring_authority.game_center_presentations presentation
    on presentation.match_id = match_value.match_id
  left join lateral (
    select production_control.assert_production_match_scoring_ready_v1(
      match_value.match_id
    ) value
  ) scoring_readiness on true
  where match_value.tournament_id = '2026';

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'eventId', event.event_id,
    'action', event.action,
    'targetKind', event.target_kind,
    'targetId', event.target_id,
    'actorPlayerId', event.actor_player_id,
    'result', event.result,
    'revision', event.next_revision,
    'occurredAt', event.occurred_at
  ) order by event.occurred_at desc), '[]'::jsonb) into audit_value
  from (
    select item.*
    from production_control.tournament_setup_audit_events_v1 item
    where item.tournament_id = '2026'
    order by item.occurred_at desc, item.event_id
    limit 60
  ) event;

  readiness_value := production_control.tournament_setup_readiness_v1();
  select pg_catalog.jsonb_build_object(
    'oddsPublished', production_control.odds_publication_is_current_v1('2026'),
    'netSkinsConfigured', exists (
      select 1
      from scoring_authority.net_skins_v1_configuration_current current_value
      where current_value.tournament_id = '2026'
        and current_value.state = 'CONFIGURED'
    ),
    'calcuttaConfigured', exists (
      select 1 from scoring_authority.calcutta_v1_current current_value
      where current_value.tournament_id = '2026'
        and current_value.state <> 'NOT_CONFIGURED'
    ),
    'draftPickCount', (
      select pg_catalog.count(*)::integer
      from scoring_authority.draft_current_revisions current_value
      join scoring_authority.draft_pick_facts pick
        on pick.revision_id = current_value.revision_id
       and pick.tournament_id = current_value.tournament_id
      where current_value.tournament_id = '2026'
        and pick.pick_status = 'SELECTED'
    )
  ) into dependencies_value;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'data', pg_catalog.jsonb_build_object(
      'contractVersion', 'production-tournament-setup-v1',
      'tournamentId', '2026',
      'revision', revision_value,
      'actor', pg_catalog.jsonb_build_object(
        'playerId', input->>'actor_player_id',
        'owner', exists (
          select 1
          from production_control.tournament_owner_capabilities_v1 owner_value
          where owner_value.tournament_id = '2026'
            and owner_value.player_id = input->>'actor_player_id'
            and owner_value.auth_user_id = (input->>'actor_auth_user_id')::uuid
            and owner_value.status = 'ACTIVE'
        )
      ),
      'tournament', tournament_value,
      'teams', teams_value,
      'roster', roster_value,
      'availablePlayers', available_players_value,
      'rounds', rounds_value,
      'courses', courses_value,
      'availableCourseIdentities', available_course_identities_value,
      'matches', matches_value,
      'readiness', readiness_value,
      'dependencies', dependencies_value,
      'audit', audit_value,
      'capabilities', pg_catalog.jsonb_build_object(
        'update-tournament', true,
        'update-team', true,
        'assign-roster-team', true,
        'update-round', true,
        'upsert-course', true,
        'create-global-course', false,
        'upsert-match', true,
        'replace-pairings', true,
        'prepare-scoring-context', true,
        'activate-scoring-access', false,
        'change-operational-status', false
      ),
      'deferred', pg_catalog.jsonb_build_array(
        'GLOBAL_COURSE_ID_ALLOCATION_POLICY_REQUIRED',
        'TOURNAMENT_OPERATIONAL_STATUS_SEMANTICS_REQUIRED',
        'POST_START_SETUP_CORRECTION_FLOW_REQUIRED'
      )
    )
  );
end;
$$;


ALTER FUNCTION production_control.read_tournament_setup_before_round_workspace_v1(input jsonb) OWNER TO postgres;

--
-- Name: rebind_annual_side_game_admission_generation_v1(text, uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.rebind_annual_side_game_admission_generation_v1(target_tournament_id text, target_runtime_generation_id uuid, target_authority_generation_id uuid, prior_admission_generation_id uuid, target_admission_generation_id uuid, target_pointer_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  annual production_control.annual_scoring_runtime_authorities_v1%rowtype;
  identity_context
    participant_identity.future_tournament_identity_contexts_v1%rowtype;
  prior_certification
    production_control.annual_side_game_runtime_certifications_v1%rowtype;
  rebound jsonb;
begin
  perform production_control.assert_production_service_role();
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = case when exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION')
    then production_control.annual_resource_context_v2()->>'resource_id' else 'BAGGER_INV_PRODUCTION' end;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target_tournament_id
    and value.runtime_generation_id = target_runtime_generation_id;
  select value.* into strict annual
  from production_control.annual_scoring_runtime_authorities_v1 value
  where value.tournament_id = target_tournament_id
    and value.runtime_generation_id = target_runtime_generation_id;
  select value.* into strict identity_context
  from participant_identity.future_tournament_identity_contexts_v1 value
  where value.tournament_id = target_tournament_id;
  select value.* into strict prior_certification
  from production_control.annual_side_game_runtime_certifications_v1 value
  where value.runtime_generation_id = target_runtime_generation_id
    and value.admission_generation_id = prior_admission_generation_id;

  if target_tournament_id = '2026'
     or target_admission_generation_id = prior_admission_generation_id
     or pointer.tournament_id <> target_tournament_id
     or pointer.pointer_revision <> target_pointer_revision
     or generation.generation_status <> 'ACTIVE'
     or generation.pointer_revision <> target_pointer_revision
     or generation.authority_generation_id is distinct from
       target_authority_generation_id
     or generation.admission_generation_id is distinct from
       target_admission_generation_id
     or annual.authority_status <> 'ACTIVE'
     or annual.admission_state <> 'OPEN'
     or annual.authority_generation_id is distinct from
       target_authority_generation_id
     or annual.admission_generation_id is distinct from
       target_admission_generation_id
     or identity_context.status <> 'CERTIFIED'
     or identity_context.runtime_generation_id is distinct from
       target_runtime_generation_id
     or identity_context.authority_generation_id is distinct from
       target_authority_generation_id
     or identity_context.admission_generation_id is distinct from
       target_admission_generation_id
     or identity_context.pointer_revision <> target_pointer_revision
     or prior_certification.tournament_id <> target_tournament_id
     or prior_certification.authority_generation_id is distinct from
       target_authority_generation_id then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_ADMISSION_REBIND_REQUIRED';
  end if;

  rebound := production_control.ensure_annual_side_game_runtime_v1(
    target_tournament_id, target_runtime_generation_id,
    target_authority_generation_id, target_admission_generation_id, true
  );
  return rebound || pg_catalog.jsonb_build_object(
    'priorAdmissionGenerationId', prior_admission_generation_id,
    'admissionGenerationId', target_admission_generation_id,
    'rebound', true
  );
exception
  when no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_SIDE_GAME_ADMISSION_REBIND_REQUIRED';
end;
$$;


ALTER FUNCTION production_control.rebind_annual_side_game_admission_generation_v1(target_tournament_id text, target_runtime_generation_id uuid, target_authority_generation_id uuid, prior_admission_generation_id uuid, target_admission_generation_id uuid, target_pointer_revision bigint) OWNER TO postgres;

--
-- Name: rebind_certification_annual_abort_v1(uuid, jsonb, uuid, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.rebind_certification_annual_abort_v1(target_closure uuid, input jsonb, nextgen uuid, ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c production_control.scoring_admission_closures%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;
 a production_control.annual_scoring_runtime_authorities_v1%rowtype;
 f production_control.future_annual_runtime_generations_v1%rowtype;
begin
 perform production_control.assert_certification_annual_abort_drain_v1(target_closure,ctx);
 select * into strict c from production_control.scoring_admission_closures where closure_id=target_closure for update;
 select * into strict g from production_control.certification_ingress_generations_v1
  where resource_id=ctx->>'resource_id' and generation_id=c.admission_generation_id for update;
 if nextgen is null or nextgen in(g.generation_id,g.authority_epoch_id)
  or input->>'expected_certification_admission_generation_id' is distinct from g.generation_id::text
  or input->>'expected_certification_admission_revision' is distinct from g.revision::text
  or exists(select 1 from production_control.certification_ingress_generations_v1 where generation_id=nextgen) then
  raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_ABORT_NOT_SAFE';end if;
 if c.tournament_id<>'2026' then
  select * into strict a from production_control.annual_scoring_runtime_authorities_v1 where tournament_id=c.tournament_id for update;
  select * into strict f from production_control.future_annual_runtime_generations_v1 where runtime_generation_id=a.runtime_generation_id for update;
  if a.resource_class<>'CERTIFICATION' or a.certification_resource_id<>g.resource_id
   or a.active_closure_id is distinct from c.closure_id or a.authority_status not in('ACTIVE','CLOSED')
   or a.admission_state not in('CLOSING','CLOSED') or a.admission_generation_id<>g.generation_id
   or a.authority_generation_id<>g.authority_epoch_id or f.generation_status<>'ACTIVE'
   or f.admission_generation_id<>g.generation_id or f.authority_generation_id<>g.authority_epoch_id
   or input->>'expected_predecessor_runtime_generation_id' is distinct from f.runtime_generation_id::text
   or input->>'expected_predecessor_annual_authority_generation_id' is distinct from a.authority_generation_id::text
   or input->>'expected_predecessor_annual_admission_generation_id' is distinct from a.admission_generation_id::text
   or input->>'expected_predecessor_annual_admission_revision' is distinct from a.admission_revision::text then
   raise exception using errcode='40001',message='CERTIFICATION_ANNUAL_ABORT_NOT_SAFE';end if;
  update production_control.future_annual_runtime_generations_v1 set admission_generation_id=nextgen,
   runtime_revision=runtime_revision+1,updated_at=clock_timestamp() where runtime_generation_id=f.runtime_generation_id;
  perform production_control.rebind_future_participant_identity_admission_generation_v1(c.tournament_id,f.runtime_generation_id,
   f.authority_generation_id,g.generation_id,nextgen,g.pointer_revision);
  update production_control.annual_scoring_runtime_authorities_v1 set authority_status='ACTIVE',admission_state='OPEN',
   admission_generation_id=nextgen,admission_revision=admission_revision+1,active_closure_id=null,closed_at=null,
   updated_at=clock_timestamp() where runtime_generation_id=a.runtime_generation_id;
  perform production_control.rebind_annual_side_game_admission_generation_v1(c.tournament_id,f.runtime_generation_id,
   f.authority_generation_id,g.generation_id,nextgen,g.pointer_revision);
 end if;
 update production_control.scoring_admission_closures set status='REOPENED',reopened_at=clock_timestamp()
  where closure_id=c.closure_id;
 -- Certification admission, gate and pointer remain unchanged until the outer
 -- canonical abort has also marked its abandoned successor ABORTED/CONFIGURING.
end;$$;


ALTER FUNCTION production_control.rebind_certification_annual_abort_v1(target_closure uuid, input jsonb, nextgen uuid, ctx jsonb) OWNER TO postgres;

--
-- Name: rebind_certification_release_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.rebind_certification_release_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
declare r production_control.canonical_resource_v1%rowtype;
 a production_control.certification_admission_v1%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;
 gate scoring_authority.ingress_gates%rowtype;
 origin production_control.certification_initialization_origins_v1%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;
 gate_generation uuid; ingress_evidence jsonb;
 request_id uuid; request_hash text; previous jsonb; result jsonb;
begin
 if current_user<>pg_get_userbyid((select relowner from pg_class where oid='production_control.canonical_resource_v1'::regclass)) then
  raise exception using errcode='42501',message='CANONICAL_RESOURCE_OWNER_REQUIRED';end if;
 if jsonb_typeof(input) is distinct from 'object'
  or input->>'contract_version' is distinct from 'certification-release-rebind-v1'
  or coalesce(input->>'operation_request_id','') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  or coalesce(input->>'new_release_commit','') !~ '^[a-f0-9]{40}$'
  or coalesce(input->>'new_deployment_id','') !~ '^dpl_[A-Za-z0-9_-]{1,120}$'
  or coalesce(input->>'new_deployment_origin','') !~ '^https://[a-z0-9][a-z0-9-]{0,61}[a-z0-9]\.vercel\.app$'
  or input->>'deployment_class' is distinct from 'preview'
  or length(btrim(coalesce(input->>'reason','')))=0
  or exists(select 1 from jsonb_object_keys(input)k where k not in(
   'contract_version','operation_request_id','resource','expected_admission_revision',
   'expected_release_commit','expected_deployment_id','expected_deployment_origin',
   'expected_current_tournament_id','expected_pointer_revision','expected_authority_epoch_id',
   'expected_ingress_generation_id','deployment_class','new_release_commit','new_deployment_id','new_deployment_origin','reason'))then
  raise exception using errcode='22023',message='CERTIFICATION_RELEASE_INPUT_INVALID';end if;
 request_id:=(input->>'operation_request_id')::uuid;
 request_hash:=production_control.tournament_setup_hash_v1(input);
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 select * into strict r from production_control.canonical_resource_v1 where singleton for update;
 if r.resource_class<>'CERTIFICATION' or r.database_name<>current_database()
  or exists(select 1 from production_control.resource_scope)or exists(select 1 from production_control.cutover_activation_state)
  or input->'resource' is distinct from jsonb_build_object('resource_id',r.resource_id,'resource_class',r.resource_class,
   'installation_id',r.installation_id,'project_ref',r.project_ref,'project_url',r.project_url,
   'vercel_team_id',r.vercel_team_id,'vercel_project_id',r.vercel_project_id,
   'registration_revision',r.registration_revision,'manifest_digest',r.manifest_digest,
   'schema_contract',r.schema_contract,'schema_digest',r.schema_digest)then
  raise exception using errcode='42501',message='CERTIFICATION_RELEASE_RESOURCE_DENIED';end if;
 select e.details into previous from production_control.operation_audit_events e
  where e.event_type='CERTIFICATION_RELEASE_REBOUND' and e.details->>'resource_id'=r.resource_id
   and e.details->>'operation_request_id'=request_id::text;
 if found then
  if previous->>'request_hash' is distinct from request_hash then
   raise exception using errcode='40001',message='CERTIFICATION_RELEASE_IDEMPOTENCY_CONFLICT';end if;
  return previous->'receipt';
 end if;
 select * into strict a from production_control.certification_admission_v1 where resource_id=r.resource_id for update;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=r.resource_id for share;
 select * into strict gate from scoring_authority.ingress_gates where tournament_id=p.tournament_id for share;
 select * into strict origin from production_control.certification_initialization_origins_v1 where resource_id=r.resource_id;
 select * into strict g from production_control.certification_ingress_generations_v1
  where resource_id=r.resource_id and generation_id=(input->>'expected_ingress_generation_id')::uuid for share;
 if a.enabled then raise exception using errcode='55000',message='CERTIFICATION_RELEASE_ADMISSION_MUST_BE_DISABLED';end if;
 if input->>'expected_admission_revision' is distinct from a.admission_revision::text
  or input->>'expected_release_commit' is distinct from a.release_commit
  or input->>'expected_deployment_id' is distinct from a.deployment_id
  or input->>'expected_deployment_origin' is distinct from a.deployment_origin
  or input->>'expected_current_tournament_id' is distinct from p.tournament_id
  or input->>'expected_pointer_revision' is distinct from p.pointer_revision::text
  or input->>'expected_authority_epoch_id' is distinct from a.authority_epoch_id::text
  or g.tournament_id is distinct from p.tournament_id or g.pointer_revision is distinct from p.pointer_revision
  or g.authority_epoch_id is distinct from a.authority_epoch_id
  or gate.state<>'PAUSED' or gate.authority<>'SUPABASE' or gate.boundary_mode<>'CERTIFICATION_INGRESS_V1'
  or gate.active_epoch_id is distinct from a.authority_epoch_id
  or exists(select 1 from production_control.certification_ingress_generations_v1 child
    where child.resource_id=r.resource_id and child.predecessor_generation_id=g.generation_id)
  or exists(select 1 from production_control.certification_ingress_generations_v1 other
    where other.resource_id=r.resource_id and other.generation_id<>g.generation_id
      and other.state in('OPEN','CLOSING')) then
  raise exception using errcode='40001',message='CERTIFICATION_RELEASE_CONTEXT_STALE';end if;
 -- A real current gate binding always outranks the immutable initial origin,
 -- including a reopened initial tournament with the same pointer and epoch.
 select bound.generation_id into gate_generation
  from production_control.certification_ingress_generations_v1 bound
  where bound.resource_id=r.resource_id and bound.generation_id=gate.admission_generation_id
   and bound.tournament_id=p.tournament_id and bound.pointer_revision=p.pointer_revision
   and bound.authority_epoch_id=a.authority_epoch_id;
 if gate_generation is not null then
  if gate_generation<>g.generation_id then
   raise exception using errcode='40001',message='CERTIFICATION_RELEASE_CONTEXT_STALE';end if;
 else
  -- Only the unchanged legacy gate shape at the actual initialization origin
  -- may lack a Certification gate binding. No time/latest-row discovery.
  if gate.admission_contract_version is distinct from 'production-scoring-admission-v2'
   or gate.admission_protocol_enforced is distinct from false or gate.admission_revision is distinct from 0
   or exists(select 1 from production_control.certification_ingress_generations_v1 bound
    where bound.generation_id=gate.admission_generation_id)
   or origin.resource_id is distinct from r.resource_id or origin.resource_class is distinct from r.resource_class
   or origin.installation_id is distinct from r.installation_id or origin.database_name is distinct from r.database_name
   or origin.project_ref is distinct from r.project_ref or origin.project_url is distinct from r.project_url
   or origin.registration_revision is distinct from r.registration_revision
   or origin.registration_manifest_digest is distinct from r.manifest_digest
   or origin.schema_digest is distinct from r.schema_digest or origin.binding_id is distinct from a.binding_id
   or origin.initial_tournament_id is distinct from p.tournament_id
   or origin.initial_pointer_revision is distinct from p.pointer_revision
   or origin.authority_epoch_id is distinct from a.authority_epoch_id
   or origin.admission_generation_id is distinct from g.generation_id or g.predecessor_generation_id is not null
   or exists(select 1 from production_control.certification_ingress_generations_v1 other
    where other.resource_id=r.resource_id and other.generation_id<>g.generation_id
     and other.tournament_id=p.tournament_id and other.pointer_revision=p.pointer_revision
     and other.authority_epoch_id=a.authority_epoch_id) then
   raise exception using errcode='40001',message='CERTIFICATION_RELEASE_CONTEXT_STALE';end if;
 end if;
 if g.state='CLOSED' then
  ingress_evidence:=production_control.certification_ingress_evidence_v1(r.resource_id,g.generation_id);
  if ingress_evidence->>'drained' is distinct from 'true'
   or ingress_evidence->>'fingerprint_matches' is distinct from 'true'
   or ingress_evidence->>'captured_high_watermark' is distinct from g.high_watermark::text
   or ingress_evidence->>'captured_fingerprint' is distinct from g.lease_fingerprint
   or not exists(select 1 from production_control.scoring_admission_closures closed
    where closed.resource_class='CERTIFICATION' and closed.certification_resource_id=r.resource_id
     and closed.admission_generation_id=g.generation_id and closed.tournament_id=p.tournament_id
     and closed.authority_generation_id=a.authority_epoch_id and closed.authority='SUPABASE'
     and closed.closure_kind='SUPABASE_INGRESS' and closed.status='CLOSED'
     and closed.closed_admission_revision=g.revision and closed.closing_admission_revision=g.revision
     and closed.lease_high_watermark=g.high_watermark
     and closed.lease_set_fingerprint=g.lease_fingerprint
     and closed.lease_set_fingerprint=ingress_evidence->>'fingerprint') then
   raise exception using errcode='40001',message='CERTIFICATION_RELEASE_CLOSED_EVIDENCE_REQUIRED';end if;
 end if;
 --143 intentionally rejects cross-release execution/publication. Do not
 -- strand unfinished old-release work or adopt it into the new release.
 if exists(select 1 from scoring_authority.odds_calculation_jobs job
  where job.production_operation_mode='CERTIFICATION' and job.tournament_id=p.tournament_id
   and job.production_deployment_commit=a.release_commit
   and job.source_revision->>'resource_id'=r.resource_id
   and job.source_revision->>'installation_id'=r.installation_id::text
   and job.source_revision->>'certification_ingress_generation_id'=g.generation_id::text
   and job.source_revision->>'annual_authority_generation_id'=a.authority_epoch_id::text
   and job.source_revision->>'annual_pointer_revision'=p.pointer_revision::text
   and (job.status in('PENDING','RUNNING','RETRYABLE')
    or(job.status='SUCCEEDED' and job.publication_status='READY'))) then
  raise exception using errcode='55000',message='CERTIFICATION_RELEASE_ODDS_DRAIN_REQUIRED';end if;
 update production_control.certification_admission_v1 set release_commit=input->>'new_release_commit',
  deployment_id=input->>'new_deployment_id',deployment_origin=input->>'new_deployment_origin',
  admission_revision=admission_revision+1 where resource_id=r.resource_id;
 result:=jsonb_build_object('ok',true,'contract','certification-release-rebind-v1','resource_id',r.resource_id,
  'operation_request_id',request_id,'enabled',false,'admission_revision',a.admission_revision+1,
  'release_commit',input->>'new_release_commit','deployment_id',input->>'new_deployment_id',
  'deployment_origin',input->>'new_deployment_origin');
 insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,result,details)
 values('CERTIFICATION_RELEASE_REBOUND','RESOURCE',p.tournament_id,current_user,'SUCCEEDED',
  jsonb_build_object('resource_id',r.resource_id,'installation_id',r.installation_id,
   'operation_request_id',request_id,'request_hash',request_hash,'before_release_commit',a.release_commit,
   'before_deployment_id',a.deployment_id,'before_deployment_origin',a.deployment_origin,
   'before_admission_revision',a.admission_revision,'authority_epoch_id',a.authority_epoch_id,
   'pointer_revision',p.pointer_revision,'admission_generation_id',g.generation_id,
   'reason',input->>'reason','receipt',result));
 return result;
end;$_$;


ALTER FUNCTION production_control.rebind_certification_release_v1(input jsonb) OWNER TO postgres;

--
-- Name: rebind_future_participant_identity_admission_generation_v1(text, uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.rebind_future_participant_identity_admission_generation_v1(target_tournament_id text, expected_runtime_generation_id uuid, expected_authority_generation_id uuid, expected_old_admission_generation_id uuid, target_new_admission_generation_id uuid, expected_pointer_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  context participant_identity.future_tournament_identity_contexts_v1%rowtype;
  next_fingerprint text;
begin
  perform production_control.assert_production_service_role();
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = case when exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION')
    then production_control.annual_resource_context_v2()->>'resource_id' else 'BAGGER_INV_PRODUCTION' end;
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE'
  for update;
  select value.* into strict context
  from participant_identity.future_tournament_identity_contexts_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.status = 'CERTIFIED'
  for update;
  if pointer.tournament_year <= 2026
     or pointer.tournament_id <> pg_catalog.btrim(target_tournament_id)
     or pointer.pointer_revision <> expected_pointer_revision
     or generation.pointer_revision <> pointer.pointer_revision
     or generation.runtime_generation_id
       <> expected_runtime_generation_id
     or generation.authority_generation_id
       <> expected_authority_generation_id
     or generation.admission_generation_id
       <> target_new_admission_generation_id
     or target_new_admission_generation_id in (
       expected_runtime_generation_id, expected_authority_generation_id
     )
     or context.runtime_generation_id
       <> expected_runtime_generation_id
     or context.authority_generation_id
       <> expected_authority_generation_id
     or context.admission_generation_id
       <> expected_old_admission_generation_id
     or context.pointer_revision <> expected_pointer_revision then
    raise exception using errcode = '40001',
      message = 'FUTURE_PARTICIPANT_IDENTITY_ADMISSION_REBIND_STALE';
  end if;
  update participant_identity.future_tournament_identity_contexts_v1 set
    admission_generation_id = target_new_admission_generation_id,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = pointer.tournament_id;
  next_fingerprint := production_control
    .future_participant_identity_binding_fingerprint_v1(
      pointer.tournament_id
    );
  update participant_identity.future_tournament_identity_contexts_v1 set
    binding_fingerprint = next_fingerprint,
    updated_at = pg_catalog.clock_timestamp()
  where tournament_id = pointer.tournament_id;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, actor_name, safe_metadata
  ) values (
    'FUTURE_TOURNAMENT_IDENTITY_ADMISSION_REBOUND',
    pointer.tournament_id, 'future-runtime-admission-abort-v1',
    pg_catalog.jsonb_build_object(
      'pointerRevision', pointer.pointer_revision,
      'runtimeGenerationId', expected_runtime_generation_id,
      'authorityGenerationId', expected_authority_generation_id,
      'oldAdmissionGenerationId', expected_old_admission_generation_id,
      'newAdmissionGenerationId', target_new_admission_generation_id,
      'authUsersCreated', false,
      'rolesChanged', false
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'tournamentId', pointer.tournament_id,
    'pointerRevision', pointer.pointer_revision,
    'admissionGenerationId', target_new_admission_generation_id,
    'bindingFingerprint', next_fingerprint
  );
end;
$$;


ALTER FUNCTION production_control.rebind_future_participant_identity_admission_generation_v1(target_tournament_id text, expected_runtime_generation_id uuid, expected_authority_generation_id uuid, expected_old_admission_generation_id uuid, target_new_admission_generation_id uuid, expected_pointer_revision bigint) OWNER TO postgres;

--
-- Name: rebind_production_postcutover_application_release(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.rebind_production_postcutover_application_release(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing
    production_control.postcutover_application_release_rebindings%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  binding production_control.maintenance_deployment_capability_bindings%rowtype;
  rebound production_control.maintenance_runtime_deployment_rebindings%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  odds_config scoring_authority.odds_input_configurations%rowtype;
  odds_runtime production_control.odds_calculation_runtime%rowtype;
  runtime_observed_at timestamptz;
  runtime_manifest jsonb;
  runtime_fingerprint text;
  next_activation_revision bigint;
  next_admission_revision bigint;
  application_rebind_id uuid := extensions.gen_random_uuid();
  response_value jsonb;
  intent_input jsonb := input - 'runtime_observed_at';
begin
  -- The installed staged-release helper deliberately compares the request SHA
  -- to the prior binding. This operation proves the exact resources without
  -- that comparison, then fixes both the prior and replacement SHAs below. It
  -- also permits a lost-response replay after the replacement is authoritative.
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  perform production_control.assert_no_active_physical_writer_fence();
  if input->>'boundary_mode' is distinct from 'MAINTENANCE_WINDOW_V1'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or input->>'operation' is distinct from
       'REBIND_PRODUCTION_MAINTENANCE_PRECOMMIT_DEPLOYMENT'
     or input->>'runtime_binding_contract' is distinct from
       'production-maintenance-precommit-deployment-rebind-v2'
     or input->>'runtime_deployment_capability_contract' is distinct from
       'production-maintenance-single-deployment-capability-v1'
     or input->>'runtime_deployment_capability_ceiling' is distinct from
       'OBSERVATION'
     or input->>'deployment_commit' is distinct from
       '56ded61379e3308ab5c465ce186140550f3827a7'
     or input->>'runtime_deployment_commit' is distinct from
       '56ded61379e3308ab5c465ce186140550f3827a7'
     or coalesce(input->>'original_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or input->>'deployment_id' = input->>'original_deployment_id'
     or input->>'runtime_deployment_status' is distinct from 'READY'
     or input->>'runtime_readiness_evidence' is distinct from
       'LIVE_CANONICAL_PRODUCTION_ROUTE'
     or input->>'runtime_deployment_target' is distinct from 'PRODUCTION'
     or input->>'runtime_environment' is distinct from 'production'
     or input->>'runtime_vercel_project' is distinct from 'bagger-inv'
     or input->>'runtime_vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'runtime_vercel_team_id' is distinct from
       'team_kPw5zaib8uaQJALAwj4fWI6R'
     or input->>'runtime_canonical_hostname' is distinct from 'baggerinv.com'
     or coalesce(input->>'runtime_deployment_hostname', '')
       !~ '^[a-z0-9-]+\.vercel\.app$'
     or input->>'runtime_deployment_hostname' in (
       'bagger-inv-git-feature-mock-tour-b4f752-sandbagger-invitational.vercel.app',
       'bagger-inv.vercel.app'
     )
     or input->>'runtime_cutover_phase' is distinct from 'SCORING_COMMIT'
     or input->>'runtime_scoring_authority' is distinct from 'SUPABASE'
     or input->>'runtime_participant_identity_authority' is distinct from
       'SUPABASE'
     or input->'runtime_activation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_foundation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_public_supabase_reads_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_google_ingress_lease_gate_enabled'
       is distinct from 'true'::jsonb
     or input->'runtime_supabase_scoring_ingress_enabled'
       is distinct from 'true'::jsonb
     or input->'runtime_workers_enabled' is distinct from 'true'::jsonb
     or input->'runtime_google_mirror_enabled' is distinct from 'true'::jsonb
     or input->'runtime_scorecard_archive_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_outbox_worker_secret_configured' is distinct from
       'true'::jsonb
     or input->'runtime_archive_worker_secret_configured' is distinct from
       'true'::jsonb
     or input->'runtime_odds_calculation_enabled' is distinct from 'true'::jsonb
     or input->>'runtime_war_room_input_source' is distinct from 'SUPABASE'
     or input->>'runtime_prediction_settings_read_source' is distinct from
       'SUPABASE'
     or input->>'runtime_odds_calculation_input_source' is distinct from
       'SUPABASE'
     or coalesce(input->>'runtime_prediction_settings_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(
       input->>'runtime_prediction_settings_effective_fingerprint', ''
     ) !~ '^[0-9a-f]{64}$'
     or input->>'runtime_odds_publication_authority' is distinct from 'GOOGLE'
     or input->'runtime_supabase_odds_publication_enabled' is distinct from
       'false'::jsonb
     or input->'runtime_supabase_odds_google_mirror_enabled' is distinct from
       'false'::jsonb
     or pg_catalog.lower(coalesce(
       input->>'runtime_expected_authority_epoch', ''
     )) is distinct from pg_catalog.lower(
       input->>'expected_authority_generation'
     )
     or pg_catalog.lower(coalesce(
       input->>'runtime_expected_admission_generation', ''
     )) is distinct from pg_catalog.lower(
       input->>'expected_admission_generation'
     )
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_POSTCUTOVER_APPLICATION_RELEASE_INPUT_INVALID';
  end if;

  select value.* into existing
  from production_control.postcutover_application_release_rebindings value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if found then
    if existing.deployment_id is distinct from input->>'deployment_id'
       or existing.deployment_commit is distinct from input->>'deployment_commit'
       or existing.prior_deployment_id is distinct from
         input->>'original_deployment_id'
       or existing.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or existing.payload_hash is distinct from
         production_control.cutover_payload_hash(intent_input)
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_POSTCUTOVER_APPLICATION_RELEASE_ALREADY_USED';
    end if;
    return existing.response_value || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select value.* into existing
  from production_control.postcutover_application_release_rebindings value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if found then
    if existing.deployment_id is distinct from input->>'deployment_id'
       or existing.deployment_commit is distinct from input->>'deployment_commit'
       or existing.prior_deployment_id is distinct from
         input->>'original_deployment_id'
       or existing.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or existing.payload_hash is distinct from
         production_control.cutover_payload_hash(intent_input)
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_POSTCUTOVER_APPLICATION_RELEASE_ALREADY_USED';
    end if;
    return existing.response_value || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;

  runtime_observed_at := (input->>'runtime_observed_at')::timestamptz;
  if runtime_observed_at is null
     or runtime_observed_at > pg_catalog.now()
     or runtime_observed_at < pg_catalog.now() - interval '5 minutes'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_POSTCUTOVER_APPLICATION_RUNTIME_NOT_CURRENT';
  end if;

  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select value.* into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = gate.active_closure_id for update;
  select value.* into strict binding
  from production_control.maintenance_deployment_capability_bindings value
  where value.epoch_id = gate.active_epoch_id for update;
  select value.* into strict rebound
  from production_control.maintenance_runtime_deployment_rebindings value
  where value.rebind_id = binding.rebind_id for update;
  select value.* into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = gate.active_epoch_id for update;
  select value.* into strict odds_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = '2026' and value.is_current for update;
  select value.* into strict odds_runtime
  from production_control.odds_calculation_runtime value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  perform value.worker_name
  from production_control.worker_controls value
  where value.worker_name in (
    'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE', 'ODDS_CALCULATION'
  )
  order by value.worker_name for update;

  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.read_cutover_phase <> 'OBSERVATION'
     or activation.current_authority <> 'SUPABASE'
     or activation.maintenance_state <> 'NORMAL'
     or not activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.expected_deployment_commit is distinct from
       '7baf9b284d4784d7387f3e4fa876b9d47cd0a177'
     or activation.expected_vercel_project_id is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or activation.authority_generation_id is distinct from epoch.epoch_id
     or activation.staged_environment_delta_fingerprint_v2 is distinct from
       pg_catalog.lower(input->>'staged_environment_delta_fingerprint_v2')
     or resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.google_workbook_id <>
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_read_authority <> 'SUPABASE'
     or resource.scoring_authority <> 'SUPABASE'
     or resource.participant_identity_authority <> 'SUPABASE'
     or not resource.public_supabase_reads_enabled
     or not resource.scoring_ingress_enabled
     or not resource.workers_enabled
     or not resource.google_writes_enabled
     or resource.odds_publication_enabled
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'SUPABASE'
     or gate.state <> 'OPEN'
     or gate.admission_state <> 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or epoch.epoch_id is distinct from (input->>'epoch_id')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from
       input->>'original_deployment_id'
     or gate.active_closure_id is distinct from closure.closure_id
     or closure.closure_id is distinct from (input->>'closure_id')::uuid
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.closure_kind <> 'LEGACY_ADMISSION'
     or closure.authority <> 'GOOGLE'
     or closure.status <> 'CONSUMED'
     or closure.consumed_epoch_id is distinct from epoch.epoch_id
     or closure.deployment_id is distinct from input->>'original_deployment_id'
     or epoch.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or epoch.epoch_type <> 'CUTOVER'
     or epoch.status <> 'COMMITTED'
     or epoch.authority_before <> 'GOOGLE'
     or epoch.authority_after <> 'SUPABASE'
     or epoch.deployment_commit is distinct from
       '7baf9b284d4784d7387f3e4fa876b9d47cd0a177'
     or epoch.admission_closure_id is distinct from closure.closure_id
     or epoch.admission_generation_id is distinct from
       gate.admission_generation_id
     or binding.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or binding.contract_version <>
       'production-maintenance-single-deployment-capability-v1'
     or binding.capability_ceiling <> 'OBSERVATION'
     or binding.epoch_id is distinct from epoch.epoch_id
     or binding.deployment_id is distinct from input->>'original_deployment_id'
     or binding.deployment_commit is distinct from
       '7baf9b284d4784d7387f3e4fa876b9d47cd0a177'
     or binding.capability_fingerprint is distinct from pg_catalog.encode(
       extensions.digest(binding.capability_manifest::text, 'sha256'), 'hex'
     )
     or rebound.rebind_id is distinct from binding.rebind_id
     or rebound.epoch_id is distinct from epoch.epoch_id
     or rebound.rebound_deployment_id is distinct from
       input->>'original_deployment_id'
     or rebound.deployment_commit is distinct from
       '7baf9b284d4784d7387f3e4fa876b9d47cd0a177'
     or rebound.admission_generation_id is distinct from
       gate.admission_generation_id
     or odds_config.validation_status <> 'VALID'
     or pg_catalog.lower(odds_config.source_fingerprint) is distinct from
       pg_catalog.lower(
         input->>'runtime_prediction_settings_source_fingerprint'
       )
     or pg_catalog.lower(odds_config.effective_settings_fingerprint)
       is distinct from pg_catalog.lower(
         input->>'runtime_prediction_settings_effective_fingerprint'
       )
     or odds_config.source_fingerprint is distinct from
       binding.capability_manifest->>'prediction_settings_source_fingerprint'
     or odds_config.effective_settings_fingerprint is distinct from
       binding.capability_manifest->>
         'prediction_settings_effective_fingerprint'
     or not odds_runtime.enabled
     or odds_runtime.operation_mode <> 'PRODUCTION_CUTOVER'
     or odds_runtime.cutover_phase <> 'ODDS_WAR_ROOM'
     or odds_runtime.deployment_commit is distinct from
       '7baf9b284d4784d7387f3e4fa876b9d47cd0a177'
     or odds_runtime.activation_revision is distinct from
       activation.activation_revision
     or 3 <> (
       select pg_catalog.count(*)
       from production_control.worker_controls controls
       join production_control.worker_contracts contracts
         using (worker_name)
       where controls.worker_name in (
         'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE',
         'ODDS_CALCULATION'
       )
         and controls.enabled
         and not controls.scheduler_installed
         and contracts.operation_allowed
         and not contracts.scheduler_installed
         and not contracts.authoritative_write_allowed
         and (
           (controls.worker_name = 'ODDS_CALCULATION'
             and not controls.google_writes_allowed)
           or (controls.worker_name <> 'ODDS_CALCULATION'
             and controls.google_writes_allowed
             and contracts.requires_google_write)
         )
         and controls.metadata->>'deployment_commit' =
           '7baf9b284d4784d7387f3e4fa876b9d47cd0a177'
         and (
           controls.worker_name = 'ODDS_CALCULATION'
           or controls.metadata->>'activation_epoch_id' = epoch.epoch_id::text
         )
     )
     or exists (
       select 1
       from production_control.worker_controls controls
       where controls.worker_name not in (
         'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE',
         'ODDS_CALCULATION'
       )
         and (
           controls.enabled or controls.scheduler_installed
           or controls.google_writes_allowed
         )
     )
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     )
     or exists (
       select 1 from production_control.scoring_admission_closures value
       where value.tournament_id = '2026'
         and value.closure_kind = 'SUPABASE_INGRESS'
         and value.status in ('CLOSING', 'CLOSED')
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_POSTCUTOVER_APPLICATION_RELEASE_NOT_SAFE';
  end if;

  runtime_manifest := pg_catalog.jsonb_build_object(
    'domain', 'BAGGER_POSTCUTOVER_APPLICATION_RELEASE_REBIND_V1',
    'contract_version',
      'production-postcutover-application-release-rebind-v1',
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'prior_release_sha',
      '7baf9b284d4784d7387f3e4fa876b9d47cd0a177',
    'release_sha', '56ded61379e3308ab5c465ce186140550f3827a7',
    'prior_deployment_id', input->>'original_deployment_id',
    'deployment_id', input->>'deployment_id',
    'deployment_hostname', input->>'runtime_deployment_hostname',
    'deployment_status', 'READY',
    'readiness_evidence', 'LIVE_CANONICAL_PRODUCTION_ROUTE',
    'deployment_target', 'PRODUCTION',
    'runtime_environment', 'production',
    'vercel_project', 'bagger-inv',
    'vercel_project_id', 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'vercel_team_id', 'team_kPw5zaib8uaQJALAwj4fWI6R',
    'supabase_project_ref', 'ymqhhtxaywtqllynrmxe',
    'google_workbook_id',
      '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4',
    'tournament_id', '2026',
    'authority_epoch', epoch.epoch_id,
    'authority_generation', activation.authority_generation_id,
    'admission_generation', gate.admission_generation_id,
    'activation_revision_before', activation.activation_revision,
    'admission_revision_before', gate.admission_revision,
    'database_phase', 'OBSERVATION',
    'scoring_authority', 'SUPABASE',
    'participant_identity_authority', 'SUPABASE',
    'current_tournament_read_authority', 'SUPABASE',
    'maintenance_state', 'NORMAL',
    'scoring_ingress_enabled', true,
    'workers_enabled', true,
    'google_writes_enabled', true,
    'capability_contract', binding.contract_version,
    'capability_ceiling', binding.capability_ceiling,
    'outbox_worker_secret_configured', true,
    'archive_worker_secret_configured', true,
    'odds_calculation_enabled', true,
    'war_room_input_source', 'SUPABASE',
    'prediction_settings_read_source', 'SUPABASE',
    'odds_calculation_input_source', 'SUPABASE',
    'prediction_settings_source_fingerprint',
      pg_catalog.lower(odds_config.source_fingerprint),
    'prediction_settings_effective_fingerprint',
      pg_catalog.lower(odds_config.effective_settings_fingerprint),
    'odds_publication_authority', 'GOOGLE',
    'supabase_odds_publication_enabled', false,
    'supabase_odds_google_mirror_enabled', false,
    'pending_rollback_or_reconciliation', false
  );
  runtime_fingerprint := pg_catalog.encode(
    extensions.digest(runtime_manifest::text, 'sha256'), 'hex'
  );
  next_activation_revision := activation.activation_revision + 1;
  next_admission_revision := gate.admission_revision + 1;

  update production_control.cutover_activation_state
  set expected_deployment_commit =
        '56ded61379e3308ab5c465ce186140550f3827a7',
      activation_revision = next_activation_revision,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update scoring_authority.ingress_gates
  set admission_deployment_id = input->>'deployment_id',
      admission_revision = next_admission_revision,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026';
  update production_control.scoring_admission_closures
  set deployment_id = input->>'deployment_id',
      closed_admission_revision = next_admission_revision
  where closure_id = closure.closure_id;
  update scoring_authority.authority_epochs
  set deployment_commit =
        '56ded61379e3308ab5c465ce186140550f3827a7',
      closed_admission_revision = next_admission_revision
  where epoch_id = epoch.epoch_id;
  update production_control.worker_controls
  set last_verified_at = runtime_observed_at,
      metadata = metadata || pg_catalog.jsonb_build_object(
        'deployment_commit',
          '56ded61379e3308ab5c465ce186140550f3827a7',
        'deployment_id', input->>'deployment_id',
        'runtime_revision', case
          when worker_name = 'ODDS_CALCULATION'
            then pg_catalog.to_jsonb(odds_runtime.runtime_revision + 1)
          else metadata->'runtime_revision'
        end,
        'postcutover_application_rebind_id', application_rebind_id,
        'postcutover_application_rebound_at', pg_catalog.now()
      )
  where worker_name in (
    'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE', 'ODDS_CALCULATION'
  );
  update production_control.odds_calculation_runtime
  set deployment_commit =
        '56ded61379e3308ab5c465ce186140550f3827a7',
      activation_revision = next_activation_revision,
      runtime_revision = runtime_revision + 1,
      last_transition_request_fingerprint =
        pg_catalog.lower(input->>'request_fingerprint'),
      configured_by = pg_catalog.left(input->>'actor_id', 160),
      configured_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION';

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_POSTCUTOVER_APPLICATION_RELEASE_REBOUND',
    'application_rebind_id', application_rebind_id,
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'deployment_commit',
      '56ded61379e3308ab5c465ce186140550f3827a7',
    'original_deployment_id', input->>'original_deployment_id',
    'deployment_id', input->>'deployment_id',
    'activation_revision', next_activation_revision,
    'admission_revision', next_admission_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'capability_contract', binding.contract_version,
    'capability_ceiling', binding.capability_ceiling,
    'runtime_fingerprint', runtime_fingerprint,
    'cutover_phase', 'OBSERVATION',
    'authority', 'SUPABASE',
    'participant_identity_authority', 'SUPABASE',
    'maintenance_state', 'NORMAL',
    'ingress', 'OPEN',
    'workers_enabled', true,
    'idempotent', false
  );

  insert into production_control.postcutover_application_release_rebindings (
    application_rebind_id, scope_key, boundary_mode, contract_version,
    capability_binding_id, tournament_id, epoch_id,
    authority_generation_id, admission_generation_id,
    prior_deployment_id, prior_deployment_commit,
    deployment_id, deployment_commit, deployment_hostname,
    vercel_project_id, vercel_team_id,
    capability_contract, capability_ceiling,
    activation_revision_before, activation_revision_after,
    admission_revision_before, admission_revision_after,
    runtime_manifest, runtime_fingerprint, runtime_observed_at,
    request_fingerprint, payload_hash, actor_id, response_value
  ) values (
    application_rebind_id, 'BAGGER_INV_PRODUCTION',
    'MAINTENANCE_WINDOW_V1',
    'production-postcutover-application-release-rebind-v1',
    binding.capability_binding_id, '2026', epoch.epoch_id,
    activation.authority_generation_id, gate.admission_generation_id,
    input->>'original_deployment_id',
    '7baf9b284d4784d7387f3e4fa876b9d47cd0a177',
    input->>'deployment_id',
    '56ded61379e3308ab5c465ce186140550f3827a7',
    input->>'runtime_deployment_hostname',
    'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'team_kPw5zaib8uaQJALAwj4fWI6R',
    binding.contract_version, binding.capability_ceiling,
    activation.activation_revision, next_activation_revision,
    gate.admission_revision, next_admission_revision,
    runtime_manifest, runtime_fingerprint, runtime_observed_at,
    pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(intent_input),
    pg_catalog.left(input->>'actor_id', 160), response_value
  );

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'POSTCUTOVER_APPLICATION_RELEASE_REBOUND',
    pg_catalog.left(input->>'actor_id', 160),
    response_value - 'ok' - 'idempotent'
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_POSTCUTOVER_APPLICATION_RELEASE_REBOUND',
    'APPLICATION_RELEASE', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  perform production_control.store_cutover_receipt(
    'REBIND_POSTCUTOVER_APPLICATION_RELEASE', intent_input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.rebind_production_postcutover_application_release(input jsonb) OWNER TO postgres;

--
-- Name: rebind_production_postcutover_normal_release(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.rebind_production_postcutover_normal_release(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  baseline
    production_control.postcutover_application_release_rebindings%rowtype;
  head production_control.postcutover_normal_release_head%rowtype;
  predecessor
    production_control.postcutover_normal_release_rebindings%rowtype;
  existing production_control.postcutover_normal_release_rebindings%rowtype;
  authorized_intent
    production_control.postcutover_normal_release_intents%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  binding
    production_control.maintenance_deployment_capability_bindings%rowtype;
  odds_config scoring_authority.odds_input_configurations%rowtype;
  odds_runtime production_control.odds_calculation_runtime%rowtype;
  annual_context jsonb;
  authorization_manifest jsonb;
  target_sequence bigint;
  next_activation_revision bigint;
  next_admission_revision bigint;
  new_release_rebind_id uuid := extensions.gen_random_uuid();
  runtime_observed_at timestamptz;
  runtime_manifest jsonb;
  runtime_fingerprint text;
  response_value jsonb;
  intent_input jsonb := input - 'runtime_observed_at';
begin
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  if pointer.tournament_id = '2026' then
    return production_control
      .rebind_production_postcutover_normal_release_frozen_2026_v1(input);
  end if;

  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'boundary_mode' is distinct from 'MAINTENANCE_WINDOW_V1'
     or input->>'operation' is distinct from
       'REBIND_PRODUCTION_POSTCUTOVER_NORMAL_RELEASE'
     or input->>'contract_version' is distinct from
       'production-postcutover-normal-release-rebind-v1'
     or input->>'runtime_binding_contract' is distinct from
       'production-maintenance-precommit-deployment-rebind-v2'
     or coalesce(input->>'expected_predecessor_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'expected_predecessor_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or input->>'deployment_id' =
       input->>'expected_predecessor_deployment_id'
     or coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or input->>'runtime_deployment_status' is distinct from 'READY'
     or input->>'runtime_readiness_evidence' is distinct from
       'LIVE_CANONICAL_PRODUCTION_ROUTE'
     or input->>'runtime_deployment_target' is distinct from 'PRODUCTION'
     or input->>'runtime_environment' is distinct from 'production'
     or input->>'runtime_vercel_project' is distinct from 'bagger-inv'
     or input->>'runtime_vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'runtime_vercel_team_id' is distinct from
       'team_kPw5zaib8uaQJALAwj4fWI6R'
     or input->>'runtime_canonical_hostname' is distinct from 'baggerinv.com'
     or coalesce(input->>'runtime_deployment_hostname', '')
       !~ '^[a-z0-9-]+\.vercel\.app$'
     or input->>'runtime_deployment_hostname' ~ '-git-'
     or input->>'runtime_deployment_hostname' in (
       'bagger-inv-git-feature-mock-tour-b4f752-sandbagger-invitational.vercel.app',
       'bagger-inv.vercel.app'
     )
     or input->>'runtime_deployment_commit' is distinct from
       input->>'deployment_commit'
     or input->>'runtime_cutover_phase' is distinct from 'SCORING_COMMIT'
     or input->>'runtime_deployment_capability_contract' is distinct from
       'production-maintenance-single-deployment-capability-v1'
     or input->>'runtime_deployment_capability_ceiling' is distinct from
       'OBSERVATION'
     or input->>'runtime_scoring_authority' is distinct from 'SUPABASE'
     or input->>'runtime_participant_identity_authority' is distinct from
       'SUPABASE'
     or pg_catalog.lower(coalesce(
       input->>'runtime_expected_authority_epoch', ''
     )) is distinct from pg_catalog.lower(
       input->>'expected_authority_generation'
     )
     or pg_catalog.lower(coalesce(
       input->>'runtime_expected_admission_generation', ''
     )) is distinct from pg_catalog.lower(
       input->>'expected_admission_generation'
     )
     or input->'runtime_activation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_foundation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_public_supabase_reads_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_google_ingress_lease_gate_enabled'
       is distinct from 'false'::jsonb
     or input->'runtime_supabase_scoring_ingress_enabled'
       is distinct from 'true'::jsonb
     or input->'runtime_workers_enabled' is distinct from 'true'::jsonb
     or input->'runtime_google_mirror_enabled' is distinct from 'false'::jsonb
     or input->'runtime_scorecard_archive_enabled' is distinct from
       'false'::jsonb
     or input->'runtime_outbox_worker_secret_configured' is distinct from
       'false'::jsonb
     or input->'runtime_archive_worker_secret_configured' is distinct from
       'false'::jsonb
     or input->'runtime_odds_calculation_enabled' is distinct from
       'true'::jsonb
     or input->>'runtime_war_room_input_source' is distinct from 'SUPABASE'
     or input->>'runtime_prediction_settings_read_source' is distinct from
       'SUPABASE'
     or input->>'runtime_odds_calculation_input_source' is distinct from
       'SUPABASE'
     or coalesce(input->>'runtime_prediction_settings_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(
       input->>'runtime_prediction_settings_effective_fingerprint', ''
     ) !~ '^[0-9a-f]{64}$'
     or input->>'runtime_odds_publication_authority' is distinct from
       'SUPABASE'
     or input->'runtime_supabase_odds_publication_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_supabase_odds_google_mirror_enabled' is distinct from
       'false'::jsonb
     or (input ? 'expected_release_sequence' and (
       pg_catalog.jsonb_typeof(input->'expected_release_sequence')
         is distinct from 'number'
       or coalesce(input->>'expected_release_sequence', '') !~ '^[0-9]+$'
     )) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INPUT_INVALID';
  end if;

  perform production_control.bootstrap_postcutover_normal_release_baseline();
  select value.* into strict baseline
  from production_control.postcutover_application_release_rebindings value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict head
  from production_control.postcutover_normal_release_head value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict predecessor
  from production_control.postcutover_normal_release_rebindings value
  where value.release_rebind_id = head.release_rebind_id for update;

  select value.* into existing
  from production_control.postcutover_normal_release_rebindings value
  where value.request_fingerprint = pg_catalog.lower(
    input->>'request_fingerprint'
  );
  if found then
    if existing.release_kind <> 'NORMAL'
       or (input ? 'expected_release_sequence' and
         existing.release_sequence <>
           (input->>'expected_release_sequence')::bigint)
       or existing.predecessor_deployment_id is distinct from
         input->>'expected_predecessor_deployment_id'
       or existing.predecessor_deployment_commit is distinct from
         input->>'expected_predecessor_deployment_commit'
       or existing.deployment_id is distinct from input->>'deployment_id'
       or existing.deployment_commit is distinct from
         input->>'deployment_commit'
       or existing.payload_hash is distinct from
         production_control.cutover_payload_hash(intent_input) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_REQUEST_CONFLICT';
    end if;
    if head.release_rebind_id is distinct from existing.release_rebind_id
       or head.release_sequence <> existing.release_sequence
       or head.deployment_id <> existing.deployment_id
       or head.deployment_commit <> existing.deployment_commit then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_STALE_REPLAY';
    end if;
    return existing.response_value || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;

  target_sequence := head.release_sequence + 1;
  if (input ? 'expected_release_sequence' and
       (input->>'expected_release_sequence')::bigint <> target_sequence)
     or exists (
       select 1
       from production_control.postcutover_normal_release_rebindings value
       where value.deployment_id = input->>'deployment_id'
     ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_SEQUENCE_STALE';
  end if;

  select value.* into strict authorized_intent
  from production_control.postcutover_normal_release_intents value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
    and value.status = 'PENDING' for update;
  runtime_observed_at := (input->>'runtime_observed_at')::timestamptz;
  if runtime_observed_at is null
     or runtime_observed_at > pg_catalog.now()
     or runtime_observed_at < pg_catalog.now() - interval '5 minutes' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_RUNTIME_NOT_CURRENT';
  end if;

  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select value.* into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = gate.active_epoch_id for update;
  select value.* into strict binding
  from production_control.maintenance_deployment_capability_bindings value
  where value.capability_binding_id = predecessor.capability_binding_id
  for update;
  select value.* into strict odds_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = '2026' and value.is_current for update;
  select value.* into strict odds_runtime
  from production_control.odds_calculation_runtime value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  perform value.worker_name
  from production_control.worker_controls value
  where value.worker_name in (
    'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE', 'ODDS_CALCULATION'
  ) order by value.worker_name for update;

  annual_context :=
    production_control.postcutover_annual_release_context_v1();
  authorization_manifest :=
    production_control.postcutover_annual_release_manifest_v1(
      target_sequence, predecessor.release_rebind_id,
      head.deployment_id, head.deployment_commit,
      input->>'deployment_commit', activation.activation_revision,
      gate.admission_revision, epoch.epoch_id,
      activation.authority_generation_id, gate.admission_generation_id,
      binding.capability_binding_id, binding.contract_version,
      binding.capability_ceiling, annual_context
    );

  if head.release_sequence <> predecessor.release_sequence
     or head.deployment_id <> predecessor.deployment_id
     or head.deployment_commit <> predecessor.deployment_commit
     or authorized_intent.release_sequence <> target_sequence
     or authorized_intent.predecessor_release_rebind_id is distinct from
       predecessor.release_rebind_id
     or authorized_intent.predecessor_deployment_id <> head.deployment_id
     or authorized_intent.predecessor_deployment_commit <>
       head.deployment_commit
     or authorized_intent.target_deployment_commit <>
       input->>'deployment_commit'
     or authorized_intent.authorization_manifest is distinct from
       authorization_manifest
     or authorized_intent.authorization_fingerprint is distinct from
       pg_catalog.encode(extensions.digest(
         authorization_manifest::text, 'sha256'
       ), 'hex')
     or authorized_intent.expected_activation_revision <>
       head.activation_revision
     or authorized_intent.expected_admission_revision <>
       head.admission_revision
     or input->>'expected_predecessor_deployment_id' <> head.deployment_id
     or input->>'expected_predecessor_deployment_commit' <>
       head.deployment_commit
     or baseline.capability_binding_id is distinct from
       predecessor.capability_binding_id
     or activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.read_cutover_phase <> 'OBSERVATION'
     or activation.current_authority <> 'SUPABASE'
     or activation.maintenance_state <> 'NORMAL'
     or not activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.expected_deployment_commit <> head.deployment_commit
     or activation.activation_revision <>
       (input->>'expected_activation_revision')::bigint
     or activation.activation_revision <> head.activation_revision
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.google_workbook_id <>
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_read_authority <> 'SUPABASE'
     or resource.scoring_authority <> 'SUPABASE'
     or resource.participant_identity_authority <> 'SUPABASE'
     or resource.odds_publication_authority <> 'SUPABASE'
     or not resource.odds_publication_enabled
     or not resource.public_supabase_reads_enabled
     or not resource.scoring_ingress_enabled
     or not resource.workers_enabled
     or resource.google_writes_enabled
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'SUPABASE'
     or gate.state <> 'OPEN'
     or gate.admission_state <> 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or epoch.epoch_id is distinct from (input->>'epoch_id')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision <>
       (input->>'expected_admission_revision')::bigint
     or gate.admission_revision <> head.admission_revision
     or gate.admission_deployment_id <> head.deployment_id
     or gate.unresolved_client_queues <> 0
     or binding.contract_version <>
       'production-maintenance-single-deployment-capability-v1'
     or binding.capability_ceiling <> 'OBSERVATION'
     or binding.capability_fingerprint is distinct from pg_catalog.encode(
       extensions.digest(binding.capability_manifest::text, 'sha256'), 'hex'
     )
     or odds_config.validation_status <> 'VALID'
     or pg_catalog.lower(odds_config.source_fingerprint) is distinct from
       pg_catalog.lower(
         input->>'runtime_prediction_settings_source_fingerprint'
       )
     or pg_catalog.lower(odds_config.effective_settings_fingerprint)
       is distinct from pg_catalog.lower(
         input->>'runtime_prediction_settings_effective_fingerprint'
       )
     or not odds_runtime.enabled
     or odds_runtime.operation_mode <> 'PRODUCTION_CUTOVER'
     or odds_runtime.cutover_phase <> 'ODDS_WAR_ROOM'
     or odds_runtime.deployment_commit <> head.deployment_commit
     or odds_runtime.activation_revision <> activation.activation_revision
     or exists (
       select 1 from production_control.worker_controls controls
       where controls.worker_name in ('SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE')
         and (controls.enabled or controls.scheduler_installed or controls.google_writes_allowed)
     )
     or 1 <> (
       select pg_catalog.count(*)
       from production_control.worker_controls controls
       join production_control.worker_contracts contracts using (worker_name)
       where controls.worker_name = 'ODDS_CALCULATION'
         and not controls.google_writes_allowed
         and not contracts.requires_google_write
         and controls.enabled
         and not controls.scheduler_installed
         and contracts.operation_allowed
         and not contracts.scheduler_installed
         and not contracts.authoritative_write_allowed
         and controls.metadata->>'deployment_commit' = head.deployment_commit
         and controls.metadata->>'deployment_id' = head.deployment_id
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_NOT_SAFE';
  end if;
  perform production_control.assert_no_active_physical_writer_fence();

  runtime_manifest := pg_catalog.jsonb_build_object(
    'domain', 'BAGGER_POSTCUTOVER_ANNUAL_NORMAL_RELEASE_REBIND_V1',
    'contract_version', 'production-postcutover-normal-release-rebind-v1',
    'annual_context_contract',
      'production-annual-normal-release-context-v1',
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'release_sequence', target_sequence,
    'predecessor_release_sequence', head.release_sequence,
    'release_intent_id', authorized_intent.release_intent_id,
    'release_intent_fingerprint',
      authorized_intent.authorization_fingerprint,
    'predecessor_deployment_id', head.deployment_id,
    'predecessor_release_sha', head.deployment_commit,
    'deployment_id', input->>'deployment_id',
    'release_sha', input->>'deployment_commit',
    'deployment_hostname', input->>'runtime_deployment_hostname',
    'deployment_status', 'READY',
    'deployment_target', 'PRODUCTION',
    'runtime_environment', 'production',
    'vercel_project_id', 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'vercel_team_id', 'team_kPw5zaib8uaQJALAwj4fWI6R',
    'supabase_project_ref', 'ymqhhtxaywtqllynrmxe',
    'google_workbook_id',
      '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4',
    'platform_tournament_id', '2026',
    'authority_epoch', epoch.epoch_id,
    'authority_generation', activation.authority_generation_id,
    'admission_generation', gate.admission_generation_id,
    'activation_revision_before', activation.activation_revision,
    'admission_revision_before', gate.admission_revision,
    'database_phase', 'OBSERVATION',
    'scoring_authority', 'SUPABASE',
    'participant_identity_authority', 'SUPABASE',
    'current_tournament_read_authority', 'SUPABASE',
    'odds_publication_authority', 'SUPABASE',
    'capability_contract', binding.contract_version,
    'capability_ceiling', binding.capability_ceiling,
    'annual_runtime', annual_context,
    'google_runtime_contract', 'google-runtime-retired-v1',
    'google_writes_enabled', false,
    'pending_rollback_or_reconciliation', false
  );
  runtime_fingerprint := pg_catalog.encode(
    extensions.digest(runtime_manifest::text, 'sha256'), 'hex'
  );
  next_activation_revision := activation.activation_revision + 1;
  next_admission_revision := gate.admission_revision + 1;

  update production_control.cutover_activation_state
  set expected_deployment_commit = input->>'deployment_commit',
      activation_revision = next_activation_revision,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update scoring_authority.ingress_gates
  set admission_deployment_id = input->>'deployment_id',
      admission_revision = next_admission_revision,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026'
    and state = 'OPEN' and admission_state = 'CLOSED';
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_HEAD_ADVANCED';
  end if;
  update scoring_authority.authority_epochs
  set deployment_commit = input->>'deployment_commit',
      closed_admission_revision = next_admission_revision
  where epoch_id = epoch.epoch_id;
  update production_control.worker_controls
  set last_verified_at = runtime_observed_at,
      metadata = metadata || pg_catalog.jsonb_build_object(
        'deployment_commit', input->>'deployment_commit',
        'deployment_id', input->>'deployment_id',
        'runtime_revision', case
          when worker_name = 'ODDS_CALCULATION'
            then pg_catalog.to_jsonb(odds_runtime.runtime_revision + 1)
          else metadata->'runtime_revision'
        end,
        'postcutover_normal_release_sequence', target_sequence,
        'postcutover_normal_release_rebind_id', new_release_rebind_id,
        'postcutover_normal_release_rebound_at', pg_catalog.now()
      )
  where worker_name = 'ODDS_CALCULATION';
  update production_control.odds_calculation_runtime
  set deployment_commit = input->>'deployment_commit',
      activation_revision = next_activation_revision,
      runtime_revision = runtime_revision + 1,
      last_transition_request_fingerprint =
        pg_catalog.lower(input->>'request_fingerprint'),
      configured_by = pg_catalog.left(input->>'actor_id', 160),
      configured_at = pg_catalog.now(), updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION';

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_REBOUND',
    'release_rebind_id', new_release_rebind_id,
    'release_sequence', target_sequence,
    'predecessor_release_sequence', head.release_sequence,
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'deployment_commit', input->>'deployment_commit',
    'predecessor_deployment_id', head.deployment_id,
    'deployment_id', input->>'deployment_id',
    'activation_revision', next_activation_revision,
    'admission_revision', next_admission_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'capability_contract', binding.contract_version,
    'capability_ceiling', binding.capability_ceiling,
    'runtime_fingerprint', runtime_fingerprint,
    'current_tournament_id', annual_context->>'tournamentId',
    'runtime_generation_id', annual_context->>'runtimeGenerationId',
    'cutover_phase', 'OBSERVATION', 'authority', 'SUPABASE',
    'participant_identity_authority', 'SUPABASE',
    'maintenance_state', 'NORMAL', 'ingress', 'OPEN',
    'workers_enabled', true, 'idempotent', false
  );

  insert into production_control.postcutover_normal_release_rebindings (
    release_rebind_id, scope_key, boundary_mode, contract_version,
    release_kind, release_sequence, predecessor_release_sequence,
    baseline_application_rebind_id, predecessor_release_rebind_id,
    capability_binding_id, tournament_id, epoch_id,
    authority_generation_id, admission_generation_id,
    predecessor_deployment_id, predecessor_deployment_commit,
    deployment_id, deployment_commit, deployment_hostname,
    vercel_project_id, vercel_team_id,
    capability_contract, capability_ceiling,
    activation_revision_before, activation_revision_after,
    admission_revision_before, admission_revision_after,
    runtime_manifest, runtime_fingerprint, runtime_observed_at,
    request_fingerprint, payload_hash, actor_id, response_value
  ) values (
    new_release_rebind_id, 'BAGGER_INV_PRODUCTION',
    'MAINTENANCE_WINDOW_V1',
    'production-postcutover-normal-release-rebind-v1',
    'NORMAL', target_sequence, head.release_sequence,
    baseline.application_rebind_id, predecessor.release_rebind_id,
    predecessor.capability_binding_id, '2026', epoch.epoch_id,
    activation.authority_generation_id, gate.admission_generation_id,
    head.deployment_id, head.deployment_commit,
    input->>'deployment_id', input->>'deployment_commit',
    input->>'runtime_deployment_hostname',
    'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'team_kPw5zaib8uaQJALAwj4fWI6R',
    binding.contract_version, binding.capability_ceiling,
    activation.activation_revision, next_activation_revision,
    gate.admission_revision, next_admission_revision,
    runtime_manifest, runtime_fingerprint, runtime_observed_at,
    pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(intent_input),
    pg_catalog.left(input->>'actor_id', 160), response_value
  );
  update production_control.postcutover_normal_release_intents
  set status = 'CONSUMED',
      consumed_release_rebind_id = new_release_rebind_id,
      consumed_at = pg_catalog.now()
  where release_intent_id = authorized_intent.release_intent_id
    and status = 'PENDING';
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INTENT_ADVANCED';
  end if;
  update production_control.postcutover_normal_release_head
  set release_sequence = target_sequence,
      release_rebind_id = new_release_rebind_id,
      deployment_id = input->>'deployment_id',
      deployment_commit = input->>'deployment_commit',
      activation_revision = next_activation_revision,
      admission_revision = next_admission_revision,
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
    and production_control.postcutover_normal_release_head.release_rebind_id =
      predecessor.release_rebind_id;
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_HEAD_ADVANCED';
  end if;

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    annual_context->>'tournamentId',
    'POSTCUTOVER_NORMAL_RELEASE_REBOUND',
    pg_catalog.left(input->>'actor_id', 160),
    response_value - 'ok' - 'idempotent'
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_REBOUND',
    'APPLICATION_RELEASE', annual_context->>'tournamentId',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  perform production_control.store_cutover_receipt(
    'REBIND_POSTCUTOVER_NORMAL_RELEASE', intent_input, response_value
  );
  return response_value;
exception
  when no_data_found or too_many_rows or invalid_text_representation
    or numeric_value_out_of_range then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_NOT_SAFE';
end;
$_$;


ALTER FUNCTION production_control.rebind_production_postcutover_normal_release(input jsonb) OWNER TO postgres;

--
-- Name: rebind_production_postcutover_normal_release_frozen_2026_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.rebind_production_postcutover_normal_release_frozen_2026_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  baseline
    production_control.postcutover_application_release_rebindings%rowtype;
  head production_control.postcutover_normal_release_head%rowtype;
  predecessor
    production_control.postcutover_normal_release_rebindings%rowtype;
  existing production_control.postcutover_normal_release_rebindings%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  binding production_control.maintenance_deployment_capability_bindings%rowtype;
  rebound production_control.maintenance_runtime_deployment_rebindings%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  odds_config scoring_authority.odds_input_configurations%rowtype;
  odds_runtime production_control.odds_calculation_runtime%rowtype;
  authorized_intent
    production_control.postcutover_normal_release_intents%rowtype;
  target_sequence bigint;
  next_activation_revision bigint;
  next_admission_revision bigint;
  new_release_rebind_id uuid := extensions.gen_random_uuid();
  runtime_observed_at timestamptz;
  runtime_manifest jsonb;
  runtime_fingerprint text;
  response_value jsonb;
  intent_input jsonb := input - 'runtime_observed_at';
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'boundary_mode' is distinct from 'MAINTENANCE_WINDOW_V1'
     or input->>'operation' is distinct from
       'REBIND_PRODUCTION_POSTCUTOVER_NORMAL_RELEASE'
     or input->>'contract_version' is distinct from
       'production-postcutover-normal-release-rebind-v1'
     or input->>'runtime_binding_contract' is distinct from
       'production-maintenance-precommit-deployment-rebind-v2'
     or (
       input ? 'expected_release_sequence'
       and (
         pg_catalog.jsonb_typeof(input->'expected_release_sequence')
           is distinct from 'number'
         or input->>'expected_release_sequence' !~ '^[0-9]+$'
       )
     )
     or coalesce(input->>'expected_predecessor_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'expected_predecessor_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or input->>'deployment_id' =
       input->>'expected_predecessor_deployment_id'
     or coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or input->>'runtime_deployment_status' is distinct from 'READY'
     or input->>'runtime_readiness_evidence' is distinct from
       'LIVE_CANONICAL_PRODUCTION_ROUTE'
     or input->>'runtime_deployment_target' is distinct from 'PRODUCTION'
     or input->>'runtime_environment' is distinct from 'production'
     or input->>'runtime_vercel_project' is distinct from 'bagger-inv'
     or input->>'runtime_vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'runtime_vercel_team_id' is distinct from
       'team_kPw5zaib8uaQJALAwj4fWI6R'
     or input->>'runtime_canonical_hostname' is distinct from 'baggerinv.com'
     or coalesce(input->>'runtime_deployment_hostname', '')
       !~ '^[a-z0-9-]+\.vercel\.app$'
     or input->>'runtime_deployment_hostname' ~ '-git-'
     or input->>'runtime_deployment_hostname' in (
       'bagger-inv-git-feature-mock-tour-b4f752-sandbagger-invitational.vercel.app',
       'bagger-inv.vercel.app'
     )
     or input->>'runtime_deployment_commit' is distinct from
       input->>'deployment_commit'
     or input->>'runtime_cutover_phase' is distinct from 'SCORING_COMMIT'
     or input->>'runtime_deployment_capability_contract' is distinct from
       'production-maintenance-single-deployment-capability-v1'
     or input->>'runtime_deployment_capability_ceiling' is distinct from
       'OBSERVATION'
     or input->>'runtime_scoring_authority' is distinct from 'SUPABASE'
     or input->>'runtime_participant_identity_authority' is distinct from
       'SUPABASE'
     or pg_catalog.lower(coalesce(
       input->>'runtime_expected_authority_epoch', ''
     )) is distinct from pg_catalog.lower(
       input->>'expected_authority_generation'
     )
     or pg_catalog.lower(coalesce(
       input->>'runtime_expected_admission_generation', ''
     )) is distinct from pg_catalog.lower(
       input->>'expected_admission_generation'
     )
     or input->'runtime_activation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_foundation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_public_supabase_reads_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_google_ingress_lease_gate_enabled'
       is distinct from 'false'::jsonb
     or input->'runtime_supabase_scoring_ingress_enabled'
       is distinct from 'true'::jsonb
     or input->'runtime_workers_enabled' is distinct from 'true'::jsonb
     or input->'runtime_google_mirror_enabled' is distinct from 'false'::jsonb
     or input->'runtime_scorecard_archive_enabled' is distinct from
       'false'::jsonb
     or input->'runtime_outbox_worker_secret_configured' is distinct from
       'false'::jsonb
     or input->'runtime_archive_worker_secret_configured' is distinct from
       'false'::jsonb
     or input->'runtime_odds_calculation_enabled' is distinct from
       'true'::jsonb
     or input->>'runtime_war_room_input_source' is distinct from 'SUPABASE'
     or input->>'runtime_prediction_settings_read_source' is distinct from
       'SUPABASE'
     or input->>'runtime_odds_calculation_input_source' is distinct from
       'SUPABASE'
     or coalesce(input->>'runtime_prediction_settings_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(
       input->>'runtime_prediction_settings_effective_fingerprint', ''
     ) !~ '^[0-9a-f]{64}$'
     or input->>'runtime_odds_publication_authority' is distinct from 'SUPABASE'
     or input->'runtime_supabase_odds_publication_enabled' is distinct from 'true'::jsonb
     or input->'runtime_supabase_odds_google_mirror_enabled' is distinct from
       'false'::jsonb
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INPUT_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  perform production_control.bootstrap_postcutover_normal_release_baseline();

  select value.* into strict baseline
  from production_control.postcutover_application_release_rebindings value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict head
  from production_control.postcutover_normal_release_head value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict predecessor
  from production_control.postcutover_normal_release_rebindings value
  where value.release_rebind_id = head.release_rebind_id for update;

  select value.* into existing
  from production_control.postcutover_normal_release_rebindings value
  where value.request_fingerprint = pg_catalog.lower(
    input->>'request_fingerprint'
  );
  if found then
    if existing.release_kind <> 'NORMAL'
       or (
         input ? 'expected_release_sequence'
         and existing.release_sequence is distinct from
           (input->>'expected_release_sequence')::bigint
       )
       or existing.predecessor_deployment_id is distinct from
         input->>'expected_predecessor_deployment_id'
       or existing.predecessor_deployment_commit is distinct from
         input->>'expected_predecessor_deployment_commit'
       or existing.deployment_id is distinct from input->>'deployment_id'
       or existing.deployment_commit is distinct from input->>'deployment_commit'
       or existing.payload_hash is distinct from
         production_control.cutover_payload_hash(intent_input)
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_REQUEST_CONFLICT';
    end if;
    if head.release_rebind_id is distinct from existing.release_rebind_id
       or head.release_sequence is distinct from existing.release_sequence
       or head.deployment_id is distinct from existing.deployment_id
       or head.deployment_commit is distinct from existing.deployment_commit
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_STALE_REPLAY';
    end if;
    return existing.response_value || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;

  target_sequence := head.release_sequence + 1;
  if input ? 'expected_release_sequence'
     and (input->>'expected_release_sequence')::bigint <> target_sequence
  then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_SEQUENCE_STALE';
  end if;

  if exists (
    select 1
    from production_control.postcutover_normal_release_rebindings value
    where value.deployment_id = input->>'deployment_id'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_TARGET_ALREADY_USED';
  end if;

  select value.* into strict authorized_intent
  from production_control.postcutover_normal_release_intents value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
    and value.status = 'PENDING' for update;

  runtime_observed_at := (input->>'runtime_observed_at')::timestamptz;
  if runtime_observed_at is null
     or runtime_observed_at > pg_catalog.now()
     or runtime_observed_at < pg_catalog.now() - interval '5 minutes'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_RUNTIME_NOT_CURRENT';
  end if;

  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select value.* into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = gate.active_closure_id for update;
  select value.* into strict binding
  from production_control.maintenance_deployment_capability_bindings value
  where value.capability_binding_id = baseline.capability_binding_id for update;
  select value.* into strict rebound
  from production_control.maintenance_runtime_deployment_rebindings value
  where value.rebind_id = binding.rebind_id for update;
  select value.* into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = gate.active_epoch_id for update;
  select value.* into strict odds_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = '2026' and value.is_current for update;
  select value.* into strict odds_runtime
  from production_control.odds_calculation_runtime value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  perform value.worker_name
  from production_control.worker_controls value
  where value.worker_name in (
    'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE', 'ODDS_CALCULATION'
  ) order by value.worker_name for update;

  if head.release_sequence is distinct from predecessor.release_sequence
     or head.deployment_id is distinct from predecessor.deployment_id
     or head.deployment_commit is distinct from predecessor.deployment_commit
     or head.activation_revision is distinct from
       predecessor.activation_revision_after
     or head.admission_revision is distinct from
       predecessor.admission_revision_after
     or target_sequence is distinct from head.release_sequence + 1
     or authorized_intent.release_sequence is distinct from target_sequence
     or authorized_intent.predecessor_release_rebind_id is distinct from
       predecessor.release_rebind_id
     or authorized_intent.predecessor_deployment_id is distinct from
       head.deployment_id
     or authorized_intent.predecessor_deployment_commit is distinct from
       head.deployment_commit
     or authorized_intent.target_deployment_commit is distinct from
       input->>'deployment_commit'
     or authorized_intent.epoch_id is distinct from predecessor.epoch_id
     or authorized_intent.authority_generation_id is distinct from
       predecessor.authority_generation_id
     or authorized_intent.admission_generation_id is distinct from
       predecessor.admission_generation_id
     or authorized_intent.capability_binding_id is distinct from
       predecessor.capability_binding_id
     or authorized_intent.expected_activation_revision is distinct from
       head.activation_revision
     or authorized_intent.expected_admission_revision is distinct from
       head.admission_revision
     or authorized_intent.authorization_fingerprint is distinct from
       pg_catalog.encode(extensions.digest(
         authorized_intent.authorization_manifest::text, 'sha256'
       ), 'hex')
     or input->>'expected_predecessor_deployment_id' is distinct from
       head.deployment_id
     or input->>'expected_predecessor_deployment_commit' is distinct from
       head.deployment_commit
     or baseline.capability_binding_id is distinct from
       predecessor.capability_binding_id
     or baseline.epoch_id is distinct from predecessor.epoch_id
     or baseline.authority_generation_id is distinct from
       predecessor.authority_generation_id
     or baseline.admission_generation_id is distinct from
       predecessor.admission_generation_id
     or baseline.runtime_fingerprint is distinct from pg_catalog.encode(
       extensions.digest(baseline.runtime_manifest::text, 'sha256'), 'hex'
     )
     or predecessor.runtime_fingerprint is distinct from pg_catalog.encode(
       extensions.digest(predecessor.runtime_manifest::text, 'sha256'), 'hex'
     )
     or activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.read_cutover_phase <> 'OBSERVATION'
     or activation.current_authority <> 'SUPABASE'
     or activation.maintenance_state <> 'NORMAL'
     or not activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.expected_deployment_commit is distinct from
       head.deployment_commit
     or activation.expected_vercel_project_id is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.activation_revision is distinct from head.activation_revision
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or activation.authority_generation_id is distinct from epoch.epoch_id
     or resource.project_ref <> 'ymqhhtxaywtqllynrmxe'
     or resource.google_workbook_id <>
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or resource.current_tournament_id <> '2026'
     or resource.current_tournament_read_authority <> 'SUPABASE'
     or resource.scoring_authority <> 'SUPABASE'
     or resource.participant_identity_authority <> 'SUPABASE'
     or not resource.public_supabase_reads_enabled
     or not resource.scoring_ingress_enabled
     or not resource.workers_enabled
     or resource.google_writes_enabled
     or not resource.auth_user_creation_enabled
     or resource.odds_publication_authority is distinct from 'SUPABASE'
     or not resource.odds_publication_enabled
     or input->>'runtime_odds_publication_authority' is distinct from
       resource.odds_publication_authority
     or input->'runtime_supabase_odds_publication_enabled' is distinct from
       pg_catalog.to_jsonb(resource.odds_publication_enabled)
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'SUPABASE'
     or gate.state <> 'OPEN'
     or gate.admission_state <> 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or epoch.epoch_id is distinct from (input->>'epoch_id')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_revision is distinct from head.admission_revision
     or gate.admission_deployment_id is distinct from head.deployment_id
     or gate.unresolved_client_queues <> 0
     or gate.active_closure_id is distinct from closure.closure_id
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.closure_kind <> 'LEGACY_ADMISSION'
     or closure.authority <> 'GOOGLE'
     or closure.status <> 'CONSUMED'
     or closure.consumed_epoch_id is distinct from epoch.epoch_id
     or closure.deployment_id is distinct from head.deployment_id
     or closure.closed_admission_revision is distinct from
       head.admission_revision
     or epoch.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or epoch.epoch_type <> 'CUTOVER'
     or epoch.status <> 'COMMITTED'
     or epoch.authority_before <> 'GOOGLE'
     or epoch.authority_after <> 'SUPABASE'
     or epoch.deployment_commit is distinct from head.deployment_commit
     or epoch.admission_closure_id is distinct from closure.closure_id
     or epoch.admission_generation_id is distinct from
       gate.admission_generation_id
     or epoch.closed_admission_revision is distinct from
       head.admission_revision
     or binding.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or binding.contract_version <>
       'production-maintenance-single-deployment-capability-v1'
     or binding.capability_ceiling <> 'OBSERVATION'
     or binding.epoch_id is distinct from epoch.epoch_id
     or binding.capability_fingerprint is distinct from pg_catalog.encode(
       extensions.digest(binding.capability_manifest::text, 'sha256'), 'hex'
     )
     or rebound.rebind_id is distinct from binding.rebind_id
     or rebound.epoch_id is distinct from epoch.epoch_id
     or rebound.closure_id is distinct from closure.closure_id
     or rebound.admission_generation_id is distinct from
       gate.admission_generation_id
     or odds_config.validation_status <> 'VALID'
     or pg_catalog.lower(odds_config.source_fingerprint) is distinct from
       pg_catalog.lower(
         input->>'runtime_prediction_settings_source_fingerprint'
       )
     or pg_catalog.lower(odds_config.effective_settings_fingerprint)
       is distinct from pg_catalog.lower(
         input->>'runtime_prediction_settings_effective_fingerprint'
       )
     or odds_config.source_fingerprint is distinct from
       binding.capability_manifest->>'prediction_settings_source_fingerprint'
     or odds_config.effective_settings_fingerprint is distinct from
       binding.capability_manifest->>
         'prediction_settings_effective_fingerprint'
     or not odds_runtime.enabled
     or odds_runtime.operation_mode <> 'PRODUCTION_CUTOVER'
     or odds_runtime.cutover_phase <> 'ODDS_WAR_ROOM'
     or odds_runtime.deployment_commit is distinct from head.deployment_commit
     or odds_runtime.activation_revision is distinct from
       activation.activation_revision
     or exists (
       select 1 from production_control.worker_controls controls
       where controls.worker_name in ('SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE')
         and (controls.enabled or controls.scheduler_installed or controls.google_writes_allowed)
     )
     or 1 <> (
       select pg_catalog.count(*)
       from production_control.worker_controls controls
       join production_control.worker_contracts contracts using (worker_name)
       where controls.worker_name = 'ODDS_CALCULATION'
         and not controls.google_writes_allowed
         and not contracts.requires_google_write
         and controls.enabled
         and not controls.scheduler_installed
         and contracts.operation_allowed
         and not contracts.scheduler_installed
         and not contracts.authoritative_write_allowed
         and controls.metadata->>'deployment_commit' = head.deployment_commit
         and controls.metadata->>'deployment_id' = head.deployment_id
     )
     or exists (
       select 1 from production_control.worker_controls controls
       where controls.worker_name not in (
         'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE',
         'ODDS_CALCULATION'
       ) and (
         controls.enabled
         or controls.scheduler_installed
         or controls.google_writes_allowed
       )
     )
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     )
     or exists (
       select 1 from production_control.scoring_admission_closures value
       where value.tournament_id = '2026'
         and value.closure_kind = 'SUPABASE_INGRESS'
         and value.status in ('CLOSING', 'CLOSED')
     )
     or not exists (
       select 1 from scoring_authority.tournaments value
       where value.tournament_id = '2026'
         and value.scoring_authority = 'SUPABASE'
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_NOT_SAFE';
  end if;
  perform production_control.assert_no_active_physical_writer_fence();

  runtime_manifest := pg_catalog.jsonb_build_object(
    'domain', 'BAGGER_POSTCUTOVER_NORMAL_RELEASE_REBIND_V1',
    'contract_version', 'production-postcutover-normal-release-rebind-v1',
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'release_sequence', target_sequence,
    'predecessor_release_sequence', head.release_sequence,
    'release_intent_id', authorized_intent.release_intent_id,
    'release_intent_fingerprint',
      authorized_intent.authorization_fingerprint,
    'predecessor_deployment_id', head.deployment_id,
    'predecessor_release_sha', head.deployment_commit,
    'deployment_id', input->>'deployment_id',
    'release_sha', input->>'deployment_commit',
    'deployment_hostname', input->>'runtime_deployment_hostname',
    'deployment_status', 'READY',
    'readiness_evidence', 'LIVE_CANONICAL_PRODUCTION_ROUTE',
    'deployment_target', 'PRODUCTION',
    'runtime_environment', 'production',
    'vercel_project', 'bagger-inv',
    'vercel_project_id', 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'vercel_team_id', 'team_kPw5zaib8uaQJALAwj4fWI6R',
    'supabase_project_ref', 'ymqhhtxaywtqllynrmxe',
    'google_workbook_id',
      '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4',
    'tournament_id', '2026',
    'authority_epoch', epoch.epoch_id,
    'authority_generation', activation.authority_generation_id,
    'admission_generation', gate.admission_generation_id,
    'activation_revision_before', activation.activation_revision,
    'admission_revision_before', gate.admission_revision,
    'database_phase', 'OBSERVATION',
    'scoring_authority', 'SUPABASE',
    'participant_identity_authority', 'SUPABASE',
    'current_tournament_read_authority', 'SUPABASE',
    'maintenance_state', 'NORMAL',
    'scoring_ingress_enabled', true,
    'workers_enabled', true,
    'google_writes_enabled', false,
    'google_runtime_contract', 'google-runtime-retired-v1',
    'capability_contract', binding.contract_version,
    'capability_ceiling', binding.capability_ceiling,
    'outbox_worker_secret_configured', false,
    'archive_worker_secret_configured', false,
    'odds_calculation_enabled', true,
    'war_room_input_source', 'SUPABASE',
    'prediction_settings_read_source', 'SUPABASE',
    'odds_calculation_input_source', 'SUPABASE',
    'prediction_settings_source_fingerprint',
      pg_catalog.lower(odds_config.source_fingerprint),
    'prediction_settings_effective_fingerprint',
      pg_catalog.lower(odds_config.effective_settings_fingerprint),
    'odds_publication_authority', resource.odds_publication_authority,
    'supabase_odds_publication_enabled',
      resource.odds_publication_enabled,
    'supabase_odds_google_mirror_enabled', false,
    'pending_rollback_or_reconciliation', false
  );
  runtime_fingerprint := pg_catalog.encode(
    extensions.digest(runtime_manifest::text, 'sha256'), 'hex'
  );
  next_activation_revision := activation.activation_revision + 1;
  next_admission_revision := gate.admission_revision + 1;

  update production_control.cutover_activation_state
  set expected_deployment_commit = input->>'deployment_commit',
      activation_revision = next_activation_revision,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update scoring_authority.ingress_gates
  set admission_deployment_id = input->>'deployment_id',
      admission_revision = next_admission_revision,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026';
  update production_control.scoring_admission_closures
  set deployment_id = input->>'deployment_id',
      closed_admission_revision = next_admission_revision
  where closure_id = closure.closure_id;
  update scoring_authority.authority_epochs
  set deployment_commit = input->>'deployment_commit',
      closed_admission_revision = next_admission_revision
  where epoch_id = epoch.epoch_id;
  update production_control.worker_controls
  set last_verified_at = runtime_observed_at,
      metadata = metadata || pg_catalog.jsonb_build_object(
        'deployment_commit', input->>'deployment_commit',
        'deployment_id', input->>'deployment_id',
        'runtime_revision', case
          when worker_name = 'ODDS_CALCULATION'
            then pg_catalog.to_jsonb(odds_runtime.runtime_revision + 1)
          else metadata->'runtime_revision'
        end,
        'postcutover_normal_release_sequence', target_sequence,
        'postcutover_normal_release_rebind_id', new_release_rebind_id,
        'postcutover_normal_release_rebound_at', pg_catalog.now()
      )
  where worker_name = 'ODDS_CALCULATION';
  update production_control.odds_calculation_runtime
  set deployment_commit = input->>'deployment_commit',
      activation_revision = next_activation_revision,
      runtime_revision = runtime_revision + 1,
      last_transition_request_fingerprint =
        pg_catalog.lower(input->>'request_fingerprint'),
      configured_by = pg_catalog.left(input->>'actor_id', 160),
      configured_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION';

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_REBOUND',
    'release_rebind_id', new_release_rebind_id,
    'release_sequence', target_sequence,
    'predecessor_release_sequence', head.release_sequence,
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'deployment_commit', input->>'deployment_commit',
    'predecessor_deployment_id', head.deployment_id,
    'deployment_id', input->>'deployment_id',
    'activation_revision', next_activation_revision,
    'admission_revision', next_admission_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'capability_contract', binding.contract_version,
    'capability_ceiling', binding.capability_ceiling,
    'runtime_fingerprint', runtime_fingerprint,
    'cutover_phase', 'OBSERVATION',
    'authority', 'SUPABASE',
    'participant_identity_authority', 'SUPABASE',
    'maintenance_state', 'NORMAL',
    'ingress', 'OPEN',
    'workers_enabled', true,
    'idempotent', false
  );

  insert into production_control.postcutover_normal_release_rebindings (
    release_rebind_id, scope_key, boundary_mode, contract_version,
    release_kind, release_sequence, predecessor_release_sequence,
    baseline_application_rebind_id, predecessor_release_rebind_id,
    capability_binding_id, tournament_id, epoch_id,
    authority_generation_id, admission_generation_id,
    predecessor_deployment_id, predecessor_deployment_commit,
    deployment_id, deployment_commit, deployment_hostname,
    vercel_project_id, vercel_team_id,
    capability_contract, capability_ceiling,
    activation_revision_before, activation_revision_after,
    admission_revision_before, admission_revision_after,
    runtime_manifest, runtime_fingerprint, runtime_observed_at,
    request_fingerprint, payload_hash, actor_id, response_value
  ) values (
    new_release_rebind_id, 'BAGGER_INV_PRODUCTION',
    'MAINTENANCE_WINDOW_V1',
    'production-postcutover-normal-release-rebind-v1',
    'NORMAL', target_sequence, head.release_sequence,
    baseline.application_rebind_id, predecessor.release_rebind_id,
    baseline.capability_binding_id, '2026', epoch.epoch_id,
    activation.authority_generation_id, gate.admission_generation_id,
    head.deployment_id, head.deployment_commit,
    input->>'deployment_id', input->>'deployment_commit',
    input->>'runtime_deployment_hostname',
    'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'team_kPw5zaib8uaQJALAwj4fWI6R',
    binding.contract_version, binding.capability_ceiling,
    activation.activation_revision, next_activation_revision,
    gate.admission_revision, next_admission_revision,
    runtime_manifest, runtime_fingerprint, runtime_observed_at,
    pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(intent_input),
    pg_catalog.left(input->>'actor_id', 160), response_value
  );

  update production_control.postcutover_normal_release_intents
  set status = 'CONSUMED',
      consumed_release_rebind_id = new_release_rebind_id,
      consumed_at = pg_catalog.now()
  where release_intent_id = authorized_intent.release_intent_id
    and status = 'PENDING';
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INTENT_ADVANCED';
  end if;

  update production_control.postcutover_normal_release_head
  set release_sequence = target_sequence,
      release_rebind_id = new_release_rebind_id,
      deployment_id = input->>'deployment_id',
      deployment_commit = input->>'deployment_commit',
      activation_revision = next_activation_revision,
      admission_revision = next_admission_revision,
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
    and production_control.postcutover_normal_release_head.release_rebind_id =
      predecessor.release_rebind_id;
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_HEAD_ADVANCED';
  end if;

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'POSTCUTOVER_NORMAL_RELEASE_REBOUND',
    pg_catalog.left(input->>'actor_id', 160),
    response_value - 'ok' - 'idempotent'
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_REBOUND',
    'APPLICATION_RELEASE', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  perform production_control.store_cutover_receipt(
    'REBIND_POSTCUTOVER_NORMAL_RELEASE', intent_input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION production_control.rebind_production_postcutover_normal_release_frozen_2026_v1(input jsonb) OWNER TO postgres;

--
-- Name: record_certification_initialization_origin_v1(uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.record_certification_initialization_origin_v1(initial_generation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;
 i production_control.canonical_bootstrap_installation_v1%rowtype;
 a production_control.certification_admission_v1%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;
 e scoring_authority.authority_epochs%rowtype;
 g production_control.certification_ingress_generations_v1%rowtype;
 fingerprint text; admission_created_here boolean;
begin
 select * into strict g from production_control.certification_ingress_generations_v1 where generation_id=initial_generation;
 select * into strict r from production_control.canonical_resource_v1 where resource_id=g.resource_id;
 select * into strict i from production_control.canonical_bootstrap_installation_v1 where contract_version='bagger-canonical-bootstrap-v1';
 select * into strict a from production_control.certification_admission_v1 where resource_id=g.resource_id;
 select (value.xmin::text=pg_current_xact_id()::text) into strict admission_created_here
  from production_control.certification_admission_v1 value where resource_id=g.resource_id;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=g.resource_id;
 select * into strict e from scoring_authority.authority_epochs where epoch_id=g.authority_epoch_id;
 if r.resource_class<>'CERTIFICATION' or r.database_name<>current_database()
  or r.schema_digest is distinct from i.schema_sha256
  or a.authority_epoch_id<>e.epoch_id or a.governance_tournament_id<>'2026'
  or p.pointer_revision<>1 or p.tournament_id<>'2026' or p.tournament_year<>2026
  or g.pointer_revision<>p.pointer_revision or g.tournament_id<>p.tournament_id or g.predecessor_generation_id is not null
  or e.epoch_type<>'CERTIFICATION_INITIALIZATION' or e.status<>'COMMITTED'
  or e.authority_before<>'SUPABASE' or e.authority_after<>'SUPABASE' or e.tournament_id<>p.tournament_id
  or exists(select 1 from production_control.resource_scope) or exists(select 1 from production_control.cutover_activation_state)
  or not ((admission_created_here and not a.enabled) or exists(
   select 1 from production_control.operation_audit_events audit
   where audit.event_type='CERTIFICATION_AUTHORITY_INITIALIZED' and audit.result='SUCCEEDED'
    and audit.details->>'resource_id'=r.resource_id
    and audit.details->>'installation_id'=r.installation_id::text
    and audit.details->>'binding_id'=a.binding_id::text
    and audit.details->>'authority_epoch_id'=e.epoch_id::text
    and audit.details->>'enabled'='false' and audit.details->>'ingress'='PAUSED')) then
  raise exception using errcode='55000',message='CERTIFICATION_INITIALIZATION_RECEIPT_REQUIRED';end if;
 -- Registration-manifest authority and installation artifact manifest are
 -- intentionally distinct digests. Both are retained; neither substitutes for
 -- the other. Schema bytes must agree with the installed canonical receipt.
 fingerprint:=production_control.cutover_payload_hash(jsonb_build_object(
  'resource',to_jsonb(r)-'created_at','installation',to_jsonb(i),
  'authority_epoch_id',e.epoch_id,'admission_generation_id',g.generation_id,
  'initial_pointer',to_jsonb(p)-'updated_at','binding_id',a.binding_id));
 insert into production_control.certification_initialization_origins_v1(resource_id,installation_id,database_name,project_ref,project_url,
  registration_revision,installation_contract,registration_manifest_digest,installation_manifest_digest,schema_digest,static_data_digest,
  authority_epoch_id,admission_generation_id,initial_tournament_id,initial_pointer_revision,initial_lifecycle_revision,binding_id,
  initialization_fingerprint,created_by)
 values(r.resource_id,r.installation_id,r.database_name,r.project_ref,r.project_url,r.registration_revision,i.contract_version,
  r.manifest_digest,i.manifest_sha256,i.schema_sha256,i.static_data_sha256,e.epoch_id,g.generation_id,p.tournament_id,p.pointer_revision,
  p.lifecycle_revision,a.binding_id,fingerprint,current_user);
 insert into production_control.operation_audit_events(event_type,domain,actor,result,details)
 values('CERTIFICATION_INITIALIZATION_ORIGIN_RECORDED','RESOURCE',current_user,'SUCCEEDED',jsonb_build_object(
  'resource_id',r.resource_id,'installation_id',r.installation_id,'initialization_fingerprint',fingerprint,
  'authority_epoch_id',e.epoch_id,'admission_generation_id',g.generation_id,'installation_contract',i.contract_version,
  'registration_manifest_digest',r.manifest_digest,'installation_manifest_digest',i.manifest_sha256));
exception when no_data_found then raise exception using errcode='55000',message='CERTIFICATION_INITIALIZATION_RECEIPT_REQUIRED';
end;$$;


ALTER FUNCTION production_control.record_certification_initialization_origin_v1(initial_generation uuid) OWNER TO postgres;

--
-- Name: vercel_alias_inventory_fingerprint(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.vercel_alias_inventory_fingerprint(input jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select pg_catalog.encode(extensions.digest(
    ('[' || coalesce(pg_catalog.string_agg(
      '[' || pg_catalog.to_jsonb(pg_catalog.lower(value->>0))::text
      || ',' || pg_catalog.to_jsonb(value->>1)::text
      || ',' || pg_catalog.to_jsonb(pg_catalog.lower(value->>2))::text
      || ',' || case when value->3 = 'null'::jsonb then 'null'
        else pg_catalog.to_jsonb(pg_catalog.lower(value->>3))::text end
      || ',' || case when value->4 = 'null'::jsonb then 'null'
        else ((value->>4)::integer)::text end || ']',
      ',' order by pg_catalog.lower(value->>0) collate "C"
    ), '') || ']')::text,
    'sha256'
  ), 'hex')
  from pg_catalog.jsonb_array_elements(input) value
$$;


ALTER FUNCTION production_control.vercel_alias_inventory_fingerprint(input jsonb) OWNER TO postgres;

--
-- Name: vercel_provider_alias_captures; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.vercel_provider_alias_captures (
    alias_capture_id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    attestation_id uuid NOT NULL,
    stage text NOT NULL,
    alias_inventory_count integer NOT NULL,
    alias_inventory_fingerprint text NOT NULL,
    alias_inventory_records jsonb NOT NULL,
    alias_pagination_page_count integer NOT NULL,
    alias_pagination_fingerprint text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT production_vercel_provider_alias_capture_contract_check CHECK (((alias_inventory_count = jsonb_array_length(alias_inventory_records)) AND (alias_inventory_fingerprint = production_control.vercel_alias_inventory_fingerprint(alias_inventory_records)))),
    CONSTRAINT vercel_provider_alias_captur_alias_pagination_fingerprint_check CHECK ((alias_pagination_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_alias_capture_alias_inventory_fingerprint_check CHECK ((alias_inventory_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_alias_capture_alias_pagination_page_count_check CHECK ((alias_pagination_page_count >= 1)),
    CONSTRAINT vercel_provider_alias_captures_alias_inventory_count_check CHECK ((alias_inventory_count = 56)),
    CONSTRAINT vercel_provider_alias_captures_alias_inventory_records_check CHECK ((jsonb_typeof(alias_inventory_records) = 'array'::text)),
    CONSTRAINT vercel_provider_alias_captures_stage_check CHECK ((stage = ANY (ARRAY['BEGIN'::text, 'FINALIZE'::text])))
);


ALTER TABLE production_control.vercel_provider_alias_captures OWNER TO postgres;

--
-- Name: record_current_vercel_alias_capture(uuid, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.record_current_vercel_alias_capture(target_attestation_id uuid, provider_claim jsonb) RETURNS production_control.vercel_provider_alias_captures
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  attestation production_control.vercel_provider_attestations%rowtype;
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
  capture production_control.vercel_provider_alias_captures%rowtype;
begin
  if target_attestation_id is null
     or pg_catalog.jsonb_typeof(provider_claim) is distinct from 'object'
     or pg_catalog.jsonb_typeof(provider_claim->'alias_inventory_count')
       is distinct from 'number'
     or provider_claim->>'alias_inventory_count' is distinct from '56'
     or pg_catalog.jsonb_typeof(provider_claim->'alias_inventory_records')
       is distinct from 'array'
     or coalesce(provider_claim->>'alias_inventory_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(provider_claim->'alias_pagination_page_count')
       is distinct from 'number'
     or (provider_claim->>'alias_pagination_page_count')::integer < 1
     or coalesce(provider_claim->>'alias_pagination_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(provider_claim->>'candidate_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(provider_claim->>'candidate_immutable_origin', '')
       !~ '^https://[a-z0-9.-]+$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ALIAS_CAPTURE_INPUT_INVALID';
  end if;

  select * into strict attestation
  from production_control.vercel_provider_attestations value
  where value.attestation_id = target_attestation_id
  for update;
  select * into strict challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.challenge_id = attestation.challenge_id;

  if provider_claim->>'attestation_id' is distinct from
       attestation.attestation_id::text
     or provider_claim->>'attestation_fingerprint' is distinct from
       attestation.attestation_fingerprint
     or provider_claim->>'stage' is distinct from attestation.stage
     or provider_claim->>'candidate_deployment_id' is distinct from
       attestation.candidate_deployment_id
     or pg_catalog.lower(provider_claim->>'candidate_alias_origin') is distinct from
       challenge.candidate_alias_origin
     or pg_catalog.lower(provider_claim->>'candidate_immutable_origin') is distinct from
       challenge.candidate_immutable_origin then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ALIAS_CAPTURE_BINDING_MISMATCH';
  end if;
  perform production_control.assert_exact_vercel_alias_inventory(
    provider_claim->'alias_inventory_records',
    provider_claim->>'alias_inventory_fingerprint',
    attestation.candidate_deployment_id,
    challenge.candidate_alias_origin,
    challenge.candidate_immutable_origin,
    challenge.purpose
  );

  insert into production_control.vercel_provider_alias_captures (
    attestation_id, stage, alias_inventory_count,
    alias_inventory_fingerprint, alias_inventory_records,
    alias_pagination_page_count, alias_pagination_fingerprint
  ) values (
    attestation.attestation_id, attestation.stage, 56,
    provider_claim->>'alias_inventory_fingerprint',
    provider_claim->'alias_inventory_records',
    (provider_claim->>'alias_pagination_page_count')::integer,
    provider_claim->>'alias_pagination_fingerprint'
  ) on conflict (attestation_id) do nothing;

  select * into strict capture
  from production_control.vercel_provider_alias_captures value
  where value.attestation_id = attestation.attestation_id;
  if capture.stage is distinct from attestation.stage
     or capture.alias_inventory_count is distinct from 56
     or capture.alias_inventory_fingerprint is distinct from
       provider_claim->>'alias_inventory_fingerprint'
     or capture.alias_inventory_records is distinct from
       provider_claim->'alias_inventory_records'
     or capture.alias_pagination_page_count is distinct from
       (provider_claim->>'alias_pagination_page_count')::integer
     or capture.alias_pagination_fingerprint is distinct from
       provider_claim->>'alias_pagination_fingerprint' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ALIAS_CAPTURE_IDEMPOTENCY_CONFLICT';
  end if;
  return capture;
end;
$_$;


ALTER FUNCTION production_control.record_current_vercel_alias_capture(target_attestation_id uuid, provider_claim jsonb) OWNER TO postgres;

--
-- Name: vercel_origin_inventory_fingerprint(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.vercel_origin_inventory_fingerprint(input jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select pg_catalog.encode(extensions.digest(
    ('[' || coalesce(pg_catalog.string_agg(
      '[' || pg_catalog.to_jsonb(value->>0)::text
      || ',' || case when value->1 = 'null'::jsonb then 'null'
        else pg_catalog.to_jsonb(pg_catalog.lower(value->>1))::text end
      || ',' || pg_catalog.to_jsonb(
        pg_catalog.lower(pg_catalog.rtrim(value->>2, '/'))
      )::text
      || ',' || pg_catalog.to_jsonb(value->>3)::text
      || ',' || pg_catalog.to_jsonb(value->>4)::text
      || ',' || pg_catalog.to_jsonb(value->>5)::text || ']',
      ',' order by (value->>0) collate "C",
        pg_catalog.lower(pg_catalog.rtrim(value->>2, '/'))
    ), '') || ']')::text,
    'sha256'
  ), 'hex')
  from pg_catalog.jsonb_array_elements(input) value
$$;


