    CONSTRAINT vercel_provider_attestations_candidate_deployment_commit_check CHECK ((candidate_deployment_commit ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT vercel_provider_attestations_candidate_deployment_id_check CHECK ((candidate_deployment_id ~ '^dpl_[A-Za-z0-9]{8,64}$'::text)),
    CONSTRAINT vercel_provider_attestations_candidate_deployment_target_check CHECK ((candidate_deployment_target = ANY (ARRAY['PREVIEW'::text, 'PRODUCTION'::text]))),
    CONSTRAINT vercel_provider_attestations_challenge_request_fingerprin_check CHECK ((challenge_request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestations_check CHECK ((attestation_id <> challenge_id)),
    CONSTRAINT vercel_provider_attestations_live_origin_inventory_check CHECK ((jsonb_typeof(live_origin_inventory) = 'array'::text)),
    CONSTRAINT vercel_provider_attestations_live_origin_inventory_count_check CHECK ((live_origin_inventory_count >= 1141)),
    CONSTRAINT vercel_provider_attestations_live_origin_inventory_finger_check CHECK ((live_origin_inventory_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestations_purpose_check CHECK ((purpose = ANY (ARRAY['REHEARSAL'::text, 'CUTOVER'::text]))),
    CONSTRAINT vercel_provider_attestations_receipt_request_fingerprint_check CHECK (((receipt_request_fingerprint IS NULL) OR (receipt_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_provider_attestations_redacted_environment_scope_f_check CHECK ((redacted_environment_scope_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestations_request_fingerprint_check CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestations_routing_rule_config_version_check CHECK ((routing_rule_config_version ~ '^[A-Za-z0-9_.:-]{1,160}$'::text)),
    CONSTRAINT vercel_provider_attestations_routing_rule_etag_check CHECK (((routing_rule_etag IS NULL) OR ((btrim(routing_rule_etag) <> ''::text) AND (length(routing_rule_etag) <= 512)))),
    CONSTRAINT vercel_provider_attestations_routing_rule_fingerprint_check CHECK ((routing_rule_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestations_routing_rule_id_check CHECK ((routing_rule_id ~ '^[A-Za-z0-9_.:-]{3,160}$'::text)),
    CONSTRAINT vercel_provider_attestations_routing_rule_pending_draft_c_check CHECK ((routing_rule_pending_draft_change_count = 0)),
    CONSTRAINT vercel_provider_attestations_signature_verified_check CHECK (signature_verified),
    CONSTRAINT vercel_provider_attestations_signer_key_fingerprint_check CHECK ((signer_key_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_provider_attestations_signer_key_version_check CHECK ((signer_key_version = 'STEP11_6_VERCEL_ATTESTER_V1'::text)),
    CONSTRAINT vercel_provider_attestations_stage_check CHECK ((stage = ANY (ARRAY['BEGIN'::text, 'FINALIZE'::text]))),
    CONSTRAINT vercel_provider_attestations_status_check CHECK ((status = ANY (ARRAY['RESERVED'::text, 'BOUND'::text, 'ABANDONED'::text]))),
    CONSTRAINT vercel_provider_attestations_vercel_project_id_check CHECK ((vercel_project_id = 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'::text)),
    CONSTRAINT vercel_provider_attestations_vercel_team_id_check CHECK ((vercel_team_id ~ '^[A-Za-z0-9_.:-]{3,160}$'::text))
);


ALTER TABLE production_control.vercel_provider_attestations OWNER TO postgres;

--
-- Name: record_verified_vercel_provider_attestation(uuid, text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.record_verified_vercel_provider_attestation(target_evidence_id uuid, target_stage text, target_request_fingerprint text, input jsonb) RETURNS production_control.vercel_provider_attestations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
  begin_attestation production_control.vercel_provider_attestations%rowtype;
  reserved production_control.vercel_provider_attestations%rowtype;
  bound_at_value timestamptz := pg_catalog.now();
begin
  if target_stage not in ('BEGIN', 'FINALIZE')
     or target_request_fingerprint !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(input) is distinct from 'object'
     or not (input ?& array['attestation_id', 'attestation_fingerprint'])
     or (input - array['attestation_id', 'attestation_fingerprint'])
       is distinct from '{}'::jsonb
     or coalesce(input->>'attestation_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'attestation_fingerprint', '')
       !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BIND_INPUT_INVALID';
  end if;
  select * into strict evidence
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = target_evidence_id
  for update;
  select * into strict reserved
  from production_control.vercel_provider_attestations value
  where value.attestation_id = (input->>'attestation_id')::uuid
    and value.attestation_fingerprint = input->>'attestation_fingerprint'
    and value.evidence_request_id = evidence.evidence_request_id
    and value.stage = target_stage
  for update;
  select * into strict challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.challenge_id = reserved.challenge_id
  for update;

  if reserved.status = 'BOUND' then
    if reserved.evidence_id is distinct from evidence.evidence_id
       or reserved.receipt_request_fingerprint is distinct from
         target_request_fingerprint then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BIND_IDEMPOTENCY_CONFLICT';
    end if;
    return reserved;
  end if;

  if reserved.status = 'ABANDONED' or challenge.status = 'ABANDONED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_ABANDONED_TERMINAL';
  end if;

  if reserved.provider_observed_at < bound_at_value - interval '120 seconds'
     or reserved.provider_observed_at > bound_at_value + interval '30 seconds' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BIND_STALE';
  end if;

  if reserved.status is distinct from 'RESERVED'
     or reserved.binding_expires_at < bound_at_value
     or challenge.status is distinct from 'CONSUMED'
     or challenge.consumed_attestation_id is distinct from
       reserved.attestation_id
     or challenge.actor_id is distinct from evidence.actor_id
     or challenge.authenticated_actor_fingerprint is distinct from
       evidence.authenticated_actor_fingerprint
     or challenge.purpose is distinct from evidence.purpose
     or challenge.candidate_alias_origin is distinct from
       evidence.candidate_alias_origin
     or challenge.candidate_immutable_origin is distinct from
       evidence.candidate_immutable_origin
     or challenge.routing_rule_scope is distinct from evidence.routing_rule_scope
     or reserved.purpose is distinct from evidence.purpose
     or reserved.candidate_deployment_id is distinct from
       evidence.candidate_deployment_id
     or reserved.candidate_deployment_commit is distinct from
       evidence.candidate_deployment_commit
     or reserved.candidate_deployment_target is distinct from
       evidence.candidate_deployment_target
     or reserved.vercel_project_id is distinct from evidence.vercel_project_id
     or reserved.routing_rule_id is distinct from evidence.routing_rule_id
     or reserved.routing_rule_config_version is distinct from
       evidence.routing_rule_revision
     or reserved.live_origin_inventory is distinct from
       evidence.live_origin_inventory
     or reserved.live_origin_inventory_count is distinct from
       evidence.live_origin_inventory_count
     or reserved.live_origin_inventory_fingerprint is distinct from
       evidence.live_origin_inventory_fingerprint
     or reserved.provider_inventory_schema is distinct from
       evidence.provider_inventory_schema
     or reserved.retained_origin_inventory_count is distinct from
       evidence.origin_inventory_count
     or reserved.retained_origin_inventory_fingerprint is distinct from
       evidence.origin_inventory_fingerprint
     or reserved.retained_provider_inventory_count is distinct from
       evidence.retained_provider_inventory_count
     or reserved.retained_provider_inventory_fingerprint is distinct from
       evidence.retained_provider_inventory_fingerprint
     or reserved.live_provider_inventory_count is distinct from
       evidence.live_provider_inventory_count
     or reserved.live_provider_inventory_fingerprint is distinct from
       evidence.live_provider_inventory_fingerprint
     or reserved.routing_rule_all_method_fence_required_host_count is distinct from
       evidence.routing_rule_all_method_fence_required_host_count
     or reserved.routing_rule_all_method_fence_required_hosts_fingerprint
       is distinct from
         evidence.routing_rule_all_method_fence_required_hosts_fingerprint
     or reserved.routing_rule_all_method_fence_required_path_count is distinct from
       evidence.routing_rule_all_method_fence_required_path_count
     or reserved.routing_rule_all_method_fence_required_paths_fingerprint
       is distinct from
         evidence.routing_rule_all_method_fence_required_paths_fingerprint
     or reserved.credential_confinement_evidence_schema is distinct from
       evidence.credential_confinement_evidence_schema
     or reserved.credential_confinement_record_count is distinct from
       evidence.credential_confinement_record_count
     or reserved.credential_confinement_records_fingerprint is distinct from
       evidence.credential_confinement_records_fingerprint
     or reserved.credential_confinement_evidence_fingerprint is distinct from
       evidence.credential_confinement_evidence_fingerprint
     or (target_stage = 'BEGIN' and
       reserved.provider_observed_at > evidence.drain_started_at + interval '1 minute')
     or (target_stage = 'FINALIZE' and
       reserved.provider_observed_at <= evidence.drain_started_at) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BIND_SCOPE_MISMATCH';
  end if;

  if target_stage = 'FINALIZE' then
    select * into strict begin_attestation
    from production_control.vercel_provider_attestations value
    where value.evidence_id = evidence.evidence_id
      and value.stage = 'BEGIN'
      and value.status = 'BOUND';
    if begin_attestation.attestation_id = reserved.attestation_id
       or begin_attestation.challenge_id = reserved.challenge_id
       or begin_attestation.provider_observed_at >= reserved.provider_observed_at
       or begin_attestation.signer_key_fingerprint is distinct from
         reserved.signer_key_fingerprint
       or begin_attestation.signer_key_version is distinct from
         reserved.signer_key_version
       or begin_attestation.vercel_team_id is distinct from
         reserved.vercel_team_id
       or begin_attestation.routing_rule_etag is distinct from
         reserved.routing_rule_etag
       or begin_attestation.routing_rule_fingerprint is distinct from
         reserved.routing_rule_fingerprint
       or begin_attestation.provider_inventory_schema is distinct from
         reserved.provider_inventory_schema
       or begin_attestation.retained_origin_inventory_count is distinct from
         reserved.retained_origin_inventory_count
       or begin_attestation.retained_origin_inventory_fingerprint is distinct from
         reserved.retained_origin_inventory_fingerprint
       or begin_attestation.retained_provider_inventory_count is distinct from
         reserved.retained_provider_inventory_count
       or begin_attestation.retained_provider_inventory_fingerprint is distinct from
         reserved.retained_provider_inventory_fingerprint
       or begin_attestation.live_provider_inventory_count is distinct from
         reserved.live_provider_inventory_count
       or begin_attestation.live_provider_inventory_fingerprint is distinct from
         reserved.live_provider_inventory_fingerprint
       or begin_attestation.routing_rule_all_method_fence_required_host_count
         is distinct from
           reserved.routing_rule_all_method_fence_required_host_count
       or begin_attestation.routing_rule_all_method_fence_required_hosts_fingerprint
         is distinct from
           reserved.routing_rule_all_method_fence_required_hosts_fingerprint
       or begin_attestation.routing_rule_all_method_fence_required_path_count
         is distinct from
           reserved.routing_rule_all_method_fence_required_path_count
       or begin_attestation.routing_rule_all_method_fence_required_paths_fingerprint
         is distinct from
           reserved.routing_rule_all_method_fence_required_paths_fingerprint
       or begin_attestation.redacted_environment_scope_fingerprint
         is distinct from reserved.redacted_environment_scope_fingerprint
       or begin_attestation.credential_confinement_evidence_schema is distinct from
         reserved.credential_confinement_evidence_schema
       or begin_attestation.credential_confinement_record_count is distinct from
         reserved.credential_confinement_record_count
       or begin_attestation.credential_confinement_records_fingerprint
         is distinct from reserved.credential_confinement_records_fingerprint
       or begin_attestation.credential_confinement_evidence_fingerprint
         is distinct from reserved.credential_confinement_evidence_fingerprint then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BIND_FINALIZE_DRIFT';
    end if;
  end if;

  update production_control.vercel_provider_attestations
  set status = 'BOUND', evidence_id = evidence.evidence_id,
      receipt_request_fingerprint = target_request_fingerprint,
      bound_at = bound_at_value
  where attestation_id = reserved.attestation_id
  returning * into reserved;
  return reserved;
end;
$_$;


ALTER FUNCTION production_control.record_verified_vercel_provider_attestation(target_evidence_id uuid, target_stage text, target_request_fingerprint text, input jsonb) OWNER TO postgres;

--
-- Name: recover_derived_calcutta_activation_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.recover_derived_calcutta_activation_v1(target text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare current_value scoring_authority.calcutta_v1_current%rowtype;
 old_job scoring_authority.calcutta_v1_recalculation_jobs%rowtype; generation uuid; activation bigint;
 source_value text; replacement jsonb; total integer:=0;
begin
 select * into current_value from scoring_authority.calcutta_v1_current where tournament_id=target for update;
 if not found or current_value.configuration_revision=0 or current_value.auction_revision=0 then return 0; end if;
 activation:=production_control.canonical_execution_activation_revision_v1();
 if target<>'2026' then select runtime_generation_id into strict generation from production_control.annual_scoring_runtime_authorities_v1
  where tournament_id=target and authority_status='ACTIVE'; end if;
 -- Only one active Calcutta job exists for a tournament. The indexed probe avoids history.
 select * into old_job from scoring_authority.calcutta_v1_recalculation_jobs
 where tournament_id=target and status in('PENDING','RUNNING') and activation_revision<>activation
  and runtime_generation_id is not distinct from generation
  and (status='PENDING' or lease_expires_at<clock_timestamp())
  and configuration_revision=current_value.configuration_revision and configuration_fingerprint=current_value.configuration_fingerprint
  and auction_revision=current_value.auction_revision and auction_fingerprint=current_value.auction_fingerprint
 for update;
 if not found then return 0; end if;
 source_value:=production_control.calcutta_v1_hash(production_control.calcutta_v1_source_revision(target));
 if source_value is distinct from old_job.source_fingerprint then return 0; end if;
 update scoring_authority.calcutta_v1_recalculation_jobs set status='SUPERSEDED',claimed_by=null,claim_token=null,
  lease_expires_at=null,completed_at=clock_timestamp(),updated_at=clock_timestamp() where job_id=old_job.job_id;
 if target='2026' then replacement:=production_control.enqueue_score_calcutta_v1('COMPATIBLE_ACTIVATION_RECOVERY','score-derived-delivery-v1',false,null,null);
 else replacement:=production_control.enqueue_annual_calcutta_v1(target,generation,activation,
  'COMPATIBLE_ACTIVATION_RECOVERY','score-derived-delivery-v1',false,null,null); end if;
 insert into production_control.score_derived_delivery_attempts_v1(tournament_id,family,work_identity,cycle,attempt,
  transition,safe_code,runtime_generation_id,related_work_identity,originating_activation_revision)
 values(target,'CALCUTTA',old_job.job_id::text,old_job.delivery_cycle,old_job.delivery_attempts,'SUPERSEDED',
  'COMPATIBLE_ACTIVATION_REPLACEMENT',generation,replacement->>'job_id',old_job.activation_revision);
 return 1;
end;
$$;


ALTER FUNCTION production_control.recover_derived_calcutta_activation_v1(target text) OWNER TO postgres;

--
-- Name: register_certification_resource_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.register_certification_resource_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare existing production_control.canonical_resource_v1%rowtype; installed production_control.canonical_resource_v1%rowtype;
begin
  -- Invoker and table ACLs are deliberately used for owner-only installation.
  if current_user <> pg_get_userbyid((select relowner from pg_class where oid='production_control.canonical_resource_v1'::regclass)) then
    raise exception using errcode='42501',message='CANONICAL_RESOURCE_OWNER_REQUIRED';
  end if;
  if jsonb_typeof(input) is distinct from 'object'
    or input->>'resource_class' is distinct from 'CERTIFICATION'
    or input->>'schema_contract' is distinct from 'canonical-resource-v1'
    or exists(select 1 from production_control.resource_scope)
    or exists(select 1 from production_control.cutover_activation_state) then
    raise exception using errcode='42501',message='CERTIFICATION_REGISTRATION_REJECTED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('canonical-resource-registration-v1',0));
  select * into existing from production_control.canonical_resource_v1 where singleton for update;
  if found then
    if existing.resource_class<>'CERTIFICATION'
      or input->>'resource_id' is distinct from existing.resource_id
      or input->>'installation_id' is distinct from existing.installation_id::text
      or input->>'project_ref' is distinct from existing.project_ref
      or input->>'project_url' is distinct from existing.project_url
      or input->>'vercel_team_id' is distinct from existing.vercel_team_id
      or input->>'vercel_project_id' is distinct from existing.vercel_project_id
      or (input->>'registration_revision')::bigint is distinct from existing.registration_revision
      or input->>'manifest_digest' is distinct from existing.manifest_digest
      or input->>'schema_digest' is distinct from existing.schema_digest
      or current_database() is distinct from existing.database_name then
      raise exception using errcode='40001',message='CERTIFICATION_REGISTRATION_CONFLICT';
    end if;
    return to_jsonb(existing)-'created_at';
  end if;
  insert into production_control.canonical_resource_v1
    (resource_id,resource_class,installation_id,database_name,project_ref,project_url,
     vercel_team_id,vercel_project_id,registration_revision,manifest_digest,schema_contract,schema_digest,provenance_id)
  values(input->>'resource_id','CERTIFICATION',(input->>'installation_id')::uuid,current_database(),
    input->>'project_ref',input->>'project_url',input->>'vercel_team_id',input->>'vercel_project_id',
    (input->>'registration_revision')::bigint,input->>'manifest_digest',input->>'schema_contract',input->>'schema_digest',
    'urn:bagger:synthetic:'||(input->>'installation_id')) returning * into installed;
  insert into production_control.operation_audit_events(event_type,domain,actor,result,details)
  values('CERTIFICATION_RESOURCE_REGISTERED','RESOURCE',current_user,'SUCCEEDED',to_jsonb(installed)-'created_at');
  return to_jsonb(installed)-'created_at';
exception when invalid_text_representation or not_null_violation or check_violation then
  raise exception using errcode='22023',message='CERTIFICATION_REGISTRATION_INVALID';
end;
$$;


ALTER FUNCTION production_control.register_certification_resource_v1(input jsonb) OWNER TO postgres;

--
-- Name: register_expired_identity_recovery_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.register_expired_identity_recovery_v1(plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare observed jsonb; hash text; existing production_control.expired_identity_recovery_approvals_v1%rowtype;
begin
 perform production_control.expired_identity_operator_guard_v1();
 perform production_control.expired_identity_lock_v1();
 perform production_control.expired_identity_operator_guard_v1();
 perform production_control.assert_access_governance_owner_v1('2026',plan->>'actorPlayerId',(plan->>'actorAuthUserId')::uuid);
 if plan->>'contract' is distinct from 'expired-provider-confirmed-identity-recovery-v1'
  or plan->>'reasonCode' is distinct from 'OWNER_REVIEWED_INCOMPLETE_EMAIL_CERTIFICATION'
  or (plan->>'expiresAt')::timestamptz is null or (plan->>'expiresAt')::timestamptz<=clock_timestamp()
  or (plan->>'expiresAt')::timestamptz>clock_timestamp()+interval '15 minutes'
  or plan->>'approvalId' is null
  or (select count(*) from jsonb_object_keys(plan))<>10
 then raise exception 'EXPIRED_IDENTITY_REVIEW_REQUIRED'; end if;
 hash := encode(extensions.digest(plan::text,'sha256'),'hex');
 select * into existing from production_control.expired_identity_recovery_approvals_v1 where approval_id=(plan->>'approvalId')::uuid;
 if found then
   if existing.plan_hash<>hash then raise exception 'EXPIRED_IDENTITY_APPROVAL_CONFLICT'; end if;
   return jsonb_build_object('registered',true,'planHash',hash,'duplicate',true);
 end if;
 observed := production_control.inspect_expired_identity_recovery_v1(plan->>'playerId',(plan->>'authUserId')::uuid,(plan->>'historicalRequestId')::uuid);
 if observed->>'state'<>'PENDING' or observed is distinct from plan->'expectedState' then
  raise exception 'EXPIRED_IDENTITY_REVIEW_STALE'; end if;
 insert into production_control.expired_identity_recovery_approvals_v1
 (approval_id,target_auth_user_id,target_player_id,historical_request_id,actor_player_id,actor_auth_user_id,reason_code,expected_state,plan_hash,expires_at)
 values((plan->>'approvalId')::uuid,(plan->>'authUserId')::uuid,plan->>'playerId',(plan->>'historicalRequestId')::uuid,
 plan->>'actorPlayerId',(plan->>'actorAuthUserId')::uuid,plan->>'reasonCode',observed,hash,(plan->>'expiresAt')::timestamptz);
 return jsonb_build_object('registered',true,'planHash',hash,'duplicate',false);
end $$;


ALTER FUNCTION production_control.register_expired_identity_recovery_v1(plan jsonb) OWNER TO postgres;

--
-- Name: register_projection_revision(jsonb, text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.register_projection_revision(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  current_revision production_control.projection_revisions%rowtype;
  inserted_revision production_control.projection_revisions%rowtype;
  next_revision bigint;
  source_hash text := lower(btrim(input->>'source_fingerprint'));
  payload_hash text := lower(btrim(input->>'payload_fingerprint'));
  actor text := btrim(input->>'requested_by');
  existing_run production_control.import_runs%rowtype;
begin
  perform production_control.assert_projection_scope(input, expected_domain, expected_contract, expected_tabs);
  perform pg_advisory_xact_lock(hashtext('production-projection:' || expected_domain || ':2026'));

  select r.* into current_revision
  from production_control.projection_current c
  join production_control.projection_revisions r on r.revision_id = c.revision_id
  where c.domain = expected_domain and c.tournament_id = '2026'
  for update of c;

  if current_revision.revision_id is not null
     and current_revision.payload_fingerprint = payload_hash then
    if current_revision.source_fingerprint = source_hash then
      return jsonb_build_object(
        'ok', true, 'changed', false, 'duplicate', true,
        'revision_id', current_revision.revision_id,
        'revision_number', current_revision.revision_number,
        'source_fingerprint', source_hash,
        'payload_fingerprint', payload_hash,
        'validation_status', current_revision.validation_status
      );
    end if;
    -- A source-only change is recorded in the immutable import ledger but does
    -- not manufacture a duplicate effective projection revision.
    select * into existing_run from production_control.import_runs
    where domain = expected_domain and tournament_id = '2026' and tournament_year = 2026
      and source_workbook_id = input->>'source_workbook_id'
      and source_fingerprint = source_hash and payload_fingerprint = payload_hash;
    if existing_run.import_run_id is null then
      insert into production_control.import_runs (
        domain,tournament_id,tournament_year,source_workbook_id,source_fingerprint,
        payload_fingerprint,database_fingerprint,importer_contract,actor,status,
        previous_import_run_id,counts,completed_at
      ) values (
        expected_domain,'2026',2026,input->>'source_workbook_id',source_hash,
        payload_hash,payload_hash,expected_contract,actor,'DUPLICATE',
        (select import_run_id from production_control.import_runs
          where domain=expected_domain and tournament_id='2026'
          order by started_at desc limit 1),
        jsonb_build_object('effectiveRevisionReused',true),now()
      );
    end if;
    return jsonb_build_object(
      'ok', true, 'changed', false, 'duplicate', true,
      'source_changed_only', true,
      'revision_id', current_revision.revision_id,
      'revision_number', current_revision.revision_number,
      'source_fingerprint', source_hash,
      'payload_fingerprint', payload_hash,
      'validation_status', current_revision.validation_status
    );
  end if;

  if current_revision.revision_id is not null
     and current_revision.source_fingerprint = source_hash
     and current_revision.payload_fingerprint <> payload_hash then
    raise exception using errcode = '23514', message = 'PRODUCTION_SOURCE_PROJECTION_CONFLICT';
  end if;

  select coalesce(max(revision_number),0)+1 into next_revision
  from production_control.projection_revisions
  where domain = expected_domain and tournament_id = '2026';

  insert into production_control.projection_revisions (
    domain,tournament_id,tournament_year,revision_number,previous_revision_id,
    project_ref,project_url,source_workbook_id,source_tabs,contract_version,
    source_fingerprint,payload_fingerprint,source_payload,projection_payload,
    validation_status,validation_diagnostics,imported_by
  ) values (
    expected_domain,'2026',2026,next_revision,current_revision.revision_id,
    input->>'project_ref',input->>'project_url',input->>'source_workbook_id',
    input->'source_tabs',expected_contract,source_hash,payload_hash,
    input->'source_payload',input->'payload',upper(input->>'validation_status'),
    coalesce(input->'validation_diagnostics','{}'::jsonb),actor
  ) returning * into inserted_revision;

  insert into production_control.projection_current(domain,tournament_id,revision_id,advanced_by)
  values(expected_domain,'2026',inserted_revision.revision_id,actor)
  on conflict(domain,tournament_id) do update set
    revision_id=excluded.revision_id,advanced_by=excluded.advanced_by,advanced_at=now();

  insert into production_control.import_runs (
    domain,tournament_id,tournament_year,source_workbook_id,source_fingerprint,
    payload_fingerprint,database_fingerprint,importer_contract,actor,status,
    previous_import_run_id,counts,completed_at
  ) values (
    expected_domain,'2026',2026,input->>'source_workbook_id',source_hash,
    payload_hash,payload_hash,expected_contract,actor,'SUCCEEDED',
    (select import_run_id from production_control.import_runs
      where domain=expected_domain and tournament_id='2026'
      order by started_at desc limit 1),
    jsonb_build_object('revisionId',inserted_revision.revision_id,'revisionNumber',next_revision),now()
  );

  insert into production_control.operation_audit_events(
    event_type,domain,tournament_id,actor,request_fingerprint,result,details
  ) values (
    'PRODUCTION_SHADOW_PROJECTION_IMPORTED',expected_domain,'2026',actor,
    source_hash,'SUCCEEDED',jsonb_build_object(
      'revisionId',inserted_revision.revision_id,'revisionNumber',next_revision,
      'previousRevisionId',current_revision.revision_id,'payloadFingerprint',payload_hash,
      'validationStatus',inserted_revision.validation_status,'authorityChanged',false,
      'googleWrite',false,'publicReadEnabled',false
    )
  );

  return jsonb_build_object(
    'ok', true, 'changed', true, 'duplicate', false,
    'revision_id', inserted_revision.revision_id,
    'revision_number', inserted_revision.revision_number,
    'previous_revision_id', inserted_revision.previous_revision_id,
    'source_fingerprint', source_hash,
    'payload_fingerprint', payload_hash,
    'validation_status', inserted_revision.validation_status
  );
end;
$$;


ALTER FUNCTION production_control.register_projection_revision(input jsonb, expected_domain text, expected_contract text, expected_tabs jsonb) OWNER TO postgres;

