--
-- Name: reopen_certification_ingress_generation_v1(text, uuid, bigint); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.reopen_certification_ingress_generation_v1(target_resource_id text, prior_generation_id uuid, expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare old_generation production_control.certification_ingress_generations_v1%rowtype;g production_control.certification_ingress_generations_v1%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;a production_control.certification_admission_v1%rowtype;e jsonb;
begin
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 select * into strict old_generation from production_control.certification_ingress_generations_v1 where resource_id=target_resource_id and generation_id=prior_generation_id for update;
 if old_generation.revision<>expected_revision then raise exception using errcode='40001',message='CERTIFICATION_INGRESS_GENERATION_STALE';end if;
 select * into g from production_control.certification_ingress_generations_v1 where resource_id=target_resource_id and predecessor_generation_id=prior_generation_id;
 if found then return to_jsonb(g);end if;
 e:=production_control.close_certification_ingress_generation_v1(target_resource_id,prior_generation_id,expected_revision);
 if e->>'state'<>'CLOSED'or not(e->>'drained')::boolean then raise exception using errcode='55000',message='CERTIFICATION_INGRESS_UNRESOLVED';end if;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=target_resource_id for update;
 select * into strict a from production_control.certification_admission_v1 where resource_id=target_resource_id for update;
 insert into production_control.certification_ingress_generations_v1(resource_id,tournament_id,authority_epoch_id,pointer_revision,predecessor_generation_id)
 values(target_resource_id,p.tournament_id,a.authority_epoch_id,p.pointer_revision,prior_generation_id)returning * into g;
 update production_control.certification_admission_v1 set admission_revision=admission_revision+1 where resource_id=target_resource_id;
 return to_jsonb(g);
end;$$;


ALTER FUNCTION production_control.reopen_certification_ingress_generation_v1(target_resource_id text, prior_generation_id uuid, expected_revision bigint) OWNER TO postgres;

--
-- Name: request_dormant_worker_operation(text, text, text, text, jsonb, text, text, text, text, text, text, integer); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.request_dormant_worker_operation(requested_worker_name text, requested_action text, request_fingerprint text, expected_source_fingerprint text, expected_prior_revision jsonb, requested_project_ref text, requested_project_url text, requested_google_workbook_id text, requested_vercel_project text, requested_canonical_domain text, requested_tournament_id text, requested_tournament_year integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $_$
declare
  scope_row production_control.resource_scope%rowtype;
  control_row production_control.worker_controls%rowtype;
  contract_row production_control.worker_contracts%rowtype;
begin
  perform production_control.assert_exact_worker_resource_scope(
    requested_worker_name,
    requested_project_ref,
    requested_project_url,
    requested_google_workbook_id,
    requested_vercel_project,
    requested_canonical_domain,
    requested_tournament_id,
    requested_tournament_year
  );

  if request_fingerprint is null or request_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_WORKER_REQUEST_FINGERPRINT_INVALID';
  end if;
  if expected_source_fingerprint is not null and expected_source_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_WORKER_SOURCE_FINGERPRINT_INVALID';
  end if;
  if expected_prior_revision is null or jsonb_typeof(expected_prior_revision) <> 'object' then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_WORKER_PRIOR_REVISION_INVALID';
  end if;

  select * into strict scope_row
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict control_row
  from production_control.worker_controls
  where worker_name = requested_worker_name;
  select * into strict contract_row
  from production_control.worker_contracts
  where worker_name = requested_worker_name;

  if requested_action is null or not coalesce(contract_row.allowed_actions ? requested_action, false) then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_WORKER_ACTION_NOT_ALLOWED';
  end if;

  -- Every operational action consults both the global and per-worker controls.
  if not scope_row.workers_enabled or not control_row.enabled then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_WORKER_DISABLED';
  end if;
  if contract_row.requires_google_write
     and (not scope_row.google_writes_enabled or not control_row.google_writes_allowed) then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_GOOGLE_WRITES_DISABLED';
  end if;
  if contract_row.requires_odds_publication and not scope_row.odds_publication_enabled then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_ODDS_PUBLICATION_DISABLED';
  end if;
  if contract_row.domain = 'SCORING_AUTHORITY' and not scope_row.scoring_ingress_enabled then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_SCORING_INGRESS_DISABLED';
  end if;

  -- This foundation contract is intentionally not activatable in place. Even if
  -- a control row were corrupted, a reviewed activation migration is required.
  if not contract_row.operation_allowed then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_DORMANT_CONTRACT_REQUIRES_ACTIVATION_MIGRATION';
  end if;

  raise exception using errcode = 'P0001', message = 'PRODUCTION_DORMANT_CONTRACT_REQUIRES_ACTIVATION_MIGRATION';
end;
$_$;


ALTER FUNCTION production_control.request_dormant_worker_operation(requested_worker_name text, requested_action text, request_fingerprint text, expected_source_fingerprint text, expected_prior_revision jsonb, requested_project_ref text, requested_project_url text, requested_google_workbook_id text, requested_vercel_project text, requested_canonical_domain text, requested_tournament_id text, requested_tournament_year integer) OWNER TO postgres;

--
-- Name: require_certification_ingress_execution_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.require_certification_ingress_execution_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare l production_control.certification_ingress_leases_v1%rowtype;ctx jsonb;g production_control.certification_ingress_generations_v1%rowtype;
begin
 ctx:=production_control.current_certification_context_v1();
 select l0.* into strict l from production_control.certification_ingress_execution_v1 x
 join production_control.certification_ingress_leases_v1 l0 using(lease_id)
 where x.backend_pid=pg_backend_pid()and x.transaction_id=pg_current_xact_id()for update of l0;
 select * into strict g from production_control.certification_ingress_generations_v1 where resource_id=l.resource_id and generation_id=l.admission_generation_id for share;
 if g.state<>'OPEN'or l.state not in('ADMITTED','UNKNOWN')or l.resource_id is distinct from ctx->>'resource_id'
  or l.tournament_id is distinct from ctx->>'tournament_id'or l.authority_epoch_id::text is distinct from ctx->>'authority_epoch_id'
  or l.context_token is distinct from ctx->>'context_token'or l.operation_request_id is distinct from ctx->>'operation_request_id'
  or l.actor_auth_user_id::text is distinct from ctx#>>'{authorization,auth_user_id}'
  or l.actor_player_id is distinct from ctx#>>'{authorization,player_id}'then
  raise exception using errcode='42501',message='CERTIFICATION_INGRESS_EXECUTION_REQUIRED';end if;
 return to_jsonb(l)-array['result','admitted_at','expires_at','resolved_at'];
exception when no_data_found then raise exception using errcode='42501',message='CERTIFICATION_INGRESS_EXECUTION_REQUIRED';
end;$$;


ALTER FUNCTION production_control.require_certification_ingress_execution_v1() OWNER TO postgres;

--
-- Name: round_scoring_state_v1(integer); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.round_scoring_state_v1(target_round integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare m scoring_authority.matches%rowtype; matches jsonb:='[]'; manifest jsonb:='[]';
 initial jsonb; resume jsonb; perms jsonb; detail jsonb; item jsonb; authority jsonb;
 expected integer; pair_count integer; unique_count integer; roster_count integer; leases integer; active integer;
 open_reasons jsonb; resume_reasons jsonb; actions jsonb; failures jsonb; targets jsonb; op text; reason jsonb;
begin
 if target_round not between 1 and 3 or target_round is null then raise exception 'ROUND_SCOPE_INVALID';end if;
 expected:=case when target_round=3 then 12 else 6 end;
 select count(*),count(distinct p.player_id) into pair_count,unique_count from scoring_authority.match_participants p join scoring_authority.matches joined_match using(match_id) where joined_match.tournament_id='2026' and joined_match.round_number=target_round;
 select count(*) into roster_count from scoring_authority.tournament_players where tournament_id='2026' and participation_status='ACTIVE';
 authority:=jsonb_build_object('round',(select to_jsonb(r) from scoring_authority.rounds r where r.tournament_id='2026' and r.round_number=target_round),
 'setup',(select to_jsonb(s) from production_control.tournament_setup_context_v1 s where tournament_id='2026'),
 'handicap',(select to_jsonb(c) from scoring_authority.handicap_revision_current c where tournament_id='2026'),
 'handicapRevision',(select h.revision_number from scoring_authority.handicap_revision_current c join scoring_authority.handicap_revisions h using(revision_id) where c.tournament_id='2026'),
 'handicapEntries',(select jsonb_agg(to_jsonb(e) order by player_id) from scoring_authority.handicap_revision_entries e join scoring_authority.handicap_revision_current c using(revision_id) where c.tournament_id='2026'),
 'membership',(select jsonb_agg(to_jsonb(t) order by player_id) from scoring_authority.tournament_players t where tournament_id='2026'),
 'courses',(select jsonb_agg(to_jsonb(c) order by course_id,tee_id) from scoring_authority.tournament_setup_course_tees_v1 c where tournament_id='2026'),
 'courseHoles',(select jsonb_agg(to_jsonb(h) order by course_id,tee_id,hole_number) from scoring_authority.tournament_setup_course_holes_v1 h where tournament_id='2026'),
 'roundCourse',(select to_jsonb(c) from scoring_authority.tournament_setup_round_courses_v1 c where tournament_id='2026' and round_number=target_round));
 for m in select * from scoring_authority.matches where tournament_id='2026' and round_number=target_round order by match_id loop
 initial:=production_control.assert_production_match_scoring_ready_v1(m.match_id);
 resume:=case when m.status='LIVE' and m.scoring_locked then production_control.assert_production_match_resume_ready_v1(m.match_id) else null end;
 select coalesce(jsonb_agg(to_jsonb(p) order by player_id),'[]') into perms from scoring_authority.scoring_permissions p where match_id=m.match_id;
 select count(*) into active from scoring_authority.scoring_permissions where match_id=m.match_id and (can_score or revoked_at is null);
 select count(*) into leases from scoring_authority.scoring_ingress_leases where tournament_id='2026' and match_id=m.match_id and expires_at>clock_timestamp();
 select to_jsonb(d) into detail from scoring_authority.tournament_setup_match_details_v1 d where match_id=m.match_id;
 open_reasons:=coalesce(initial->'reasons','[]');
 if m.status<>'UPCOMING' then open_reasons:=open_reasons||jsonb_build_array(jsonb_build_object('code','MATCH_NOT_UPCOMING'));end if;
 if m.scoring_locked then open_reasons:=open_reasons||jsonb_build_array(jsonb_build_object('code','MATCH_LOCKED'));end if;
 if active>0 then open_reasons:=open_reasons||jsonb_build_array(jsonb_build_object('code','ACCESS_NOT_REVOKED'));end if;
 if leases>0 then open_reasons:=open_reasons||jsonb_build_array(jsonb_build_object('code','ACTIVE_SCORING_LEASE'));end if;
 if pair_count<>24 or unique_count<>24 or roster_count<>24 then open_reasons:=open_reasons||jsonb_build_array(jsonb_build_object('code','ROUND_PLAYER_COVERAGE_INVALID'));end if;
 resume_reasons:=coalesce(resume->'reasons','[]');
 item:=jsonb_build_object('matchId',m.match_id,'status',m.status,'locked',m.scoring_locked,'accessActive',active>0,'activeLeases',leases,
 'matchRevision',m.match_revision,'permissionRevision',m.permission_revision,'snapshotId',m.scoring_snapshot_id,
 'ready',coalesce((initial->>'ready')::boolean,false),'openReasons',open_reasons,'resumeReasons',resume_reasons,
 'resumeReady',coalesce((resume->>'ready')::boolean,false));
 matches:=matches||jsonb_build_array(item);
 manifest:=manifest||jsonb_build_array(jsonb_build_object('match',to_jsonb(m),'permissions',perms,'detail',detail,'activeLeases',leases,
 'snapshot',(select to_jsonb(s) from scoring_authority.scoring_snapshots s where snapshot_id=m.scoring_snapshot_id),
 'participants',(select jsonb_agg(to_jsonb(p) order by team_side,player_slot) from scoring_authority.match_participants p where match_id=m.match_id),
 'holes',(select jsonb_agg(to_jsonb(h) order by hole_number) from scoring_authority.match_holes h where match_id=m.match_id),
 'scores',(select jsonb_agg(to_jsonb(h) order by hole_number) from scoring_authority.hole_scores h where match_id=m.match_id),
 'history',(select jsonb_agg(to_jsonb(h) order by next_match_revision) from scoring_authority.score_revision_history h where match_id=m.match_id),
 'mutations',(select jsonb_agg(to_jsonb(h) order by next_match_revision,mutation_key) from scoring_authority.score_mutations h where match_id=m.match_id),
 'finals',(select jsonb_agg(to_jsonb(f) order by snapshot_id) from scoring_authority.finalized_scorecard_snapshots f where match_id=m.match_id)));
 end loop;
 actions:='{}';
 foreach op in array array['OPEN','LOCK','RESUME'] loop
 targets:='[]';failures:='[]';
 if op<>'LOCK' and jsonb_array_length(matches)<>expected then failures:=failures||jsonb_build_array(jsonb_build_object('matchId',null,'code','ROUND_MATCH_COUNT_INVALID'));end if;
 for item in select value from jsonb_array_elements(matches) loop
 if op='OPEN' or (item->>'status'='LIVE' and (op='LOCK' or (item->>'locked')::boolean)) then
 targets:=targets||jsonb_build_array(item->>'matchId');
 if op<>'LOCK' then
 for reason in select value from jsonb_array_elements(case op when 'OPEN' then item->'openReasons' else item->'resumeReasons' end) loop
 failures:=failures||jsonb_build_array(jsonb_build_object('matchId',item->>'matchId','code',reason->>'code'));end loop;
 if op='RESUME' and not (item->>'resumeReady')::boolean and jsonb_array_length(item->'resumeReasons')=0 then failures:=failures||jsonb_build_array(jsonb_build_object('matchId',item->>'matchId','code','RESUME_NOT_READY'));end if;
 end if;
 end if;
 end loop;
 if jsonb_array_length(targets)=0 then failures:=failures||jsonb_build_array(jsonb_build_object('matchId',null,'code','NO_APPLICABLE_MATCHES'));end if;
 actions:=actions||jsonb_build_object(op,jsonb_build_object('allowed',jsonb_array_length(failures)=0,'targets',targets,'failures',failures));
 end loop;
 return jsonb_build_object('round',target_round,'expectedMatches',expected,'format',authority#>>'{round,format}','handicapRevision',authority->'handicapRevision',
 'fingerprint',encode(extensions.digest(jsonb_build_object('authority',authority,'matches',manifest)::text,'sha256'),'hex'),
 'matches',matches,'actions',actions,'summary',jsonb_build_object('total',jsonb_array_length(matches),
 'ready',(select count(*) from jsonb_array_elements(matches) x where (x->>'ready')::boolean),
 'upcoming',(select count(*) from jsonb_array_elements(matches)x where x->>'status'='UPCOMING'),
 'live',(select count(*) from jsonb_array_elements(matches)x where x->>'status'='LIVE'),
 'final',(select count(*) from jsonb_array_elements(matches)x where x->>'status'='FINAL'),
 'accessActive',(select count(*) from jsonb_array_elements(matches)x where (x->>'accessActive')::boolean),
 'locked',(select count(*) from jsonb_array_elements(matches)x where (x->>'locked')::boolean),
 'activeLeases',(select coalesce(sum((x->>'activeLeases')::integer),0) from jsonb_array_elements(matches)x)));
end$$;


