CREATE FUNCTION production_control.scoring_lease_outcome_evidence_hash(target_lease_id uuid, target_request_fingerprint text, target_outcome text, target_provider_mutation_key text, target_provider_before_fingerprint text, target_provider_after_fingerprint text, target_provider_readback_fingerprint text, target_authority_generation uuid, target_admission_generation uuid, target_admission_revision bigint) RETURNS text
