--
-- Name: serialize_player_access_identity_claim_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.serialize_player_access_identity_claim_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'participant_identity'
    AS $$
declare
  current_revision bigint;
  pointer production_control.current_tournament_pointer_v1%rowtype;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-participant-identity-config-v1:2026', 0
  ));
  if new.status = 'PENDING' and new.tournament_id = '2026' then
    select value.context_revision into strict current_revision
    from participant_identity.identity_context_revisions value
    where value.tournament_id = '2026';
    if new.source_configuration_revision <> current_revision
       or not exists (
         select 1
         from participant_identity.participant_identity_contacts contact
         where contact.tournament_id = '2026'
           and contact.player_id = new.player_id
           and contact.identity_active
           and contact.configuration_revision = current_revision
       ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_PARTICIPANT_IDENTITY_CONFIGURATION_ADVANCED';
    end if;
  elsif new.status = 'PENDING' then
    perform pg_catalog.pg_advisory_xact_lock_shared(
      production_control.scoring_admission_lock_key()
    );
    select value.* into strict pointer
    from production_control.current_tournament_pointer_v1 value
    where value.scope_key = 'BAGGER_INV_PRODUCTION';
    if pointer.tournament_year <= 2026
       or new.tournament_id <> pointer.tournament_id
       or not exists (
         select 1
         from participant_identity.future_tournament_identity_contexts_v1
           context
         join participant_identity
           .future_tournament_participant_bindings_v1 binding
           on binding.tournament_id = context.tournament_id
          and binding.player_id = new.player_id
          and binding.contact_state = 'APPROVED'
          and binding.enrollment_state = 'NOT_ENROLLED'
          and binding.binding_revision = context.binding_revision
         join participant_identity.participant_identity_contacts contact
           on contact.tournament_id = context.tournament_id
          and contact.player_id = binding.player_id
          and contact.identity_active
          and contact.configuration_revision =
            new.source_configuration_revision
         join scoring_authority.tournament_players membership
           on membership.tournament_id = context.tournament_id
          and membership.player_id = binding.player_id
          and membership.participation_status = 'ACTIVE'
         where context.tournament_id = pointer.tournament_id
           and context.status = 'CERTIFIED'
           and context.pointer_revision = pointer.pointer_revision
       ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_PARTICIPANT_IDENTITY_CONFIGURATION_ADVANCED';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION production_control.serialize_player_access_identity_claim_v1() OWNER TO postgres;

--
-- Name: set_certification_admission_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.set_certification_admission_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;
 a production_control.certification_admission_v1%rowtype;
 p production_control.current_tournament_pointer_v1%rowtype;
 desired boolean;closed_verified boolean:=false;
 gate scoring_authority.ingress_gates%rowtype;
 origin production_control.certification_initialization_origins_v1%rowtype;
 closed_generation production_control.certification_ingress_generations_v1%rowtype;
 gate_generation uuid;ingress_evidence jsonb;
begin
 if current_user<>pg_get_userbyid((select relowner from pg_class where oid='production_control.canonical_resource_v1'::regclass)) then
  raise exception using errcode='42501',message='CANONICAL_RESOURCE_OWNER_REQUIRED';
 end if;
 if jsonb_typeof(input->'enabled') is distinct from 'boolean' or length(btrim(coalesce(input->>'reason','')))=0 then
  raise exception using errcode='22023',message='CERTIFICATION_ADMISSION_INPUT_INVALID';
 end if;
 desired:=(input->>'enabled')::boolean;
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 select * into strict r from production_control.canonical_resource_v1 where singleton for update;
 if r.resource_class<>'CERTIFICATION' or r.database_name<>current_database()
   or input->>'resource_id' is distinct from r.resource_id
   or exists(select 1 from production_control.resource_scope)
   or exists(select 1 from production_control.cutover_activation_state) then
  raise exception using errcode='42501',message='CERTIFICATION_ADMISSION_RESOURCE_DENIED';
 end if;
 select * into strict a from production_control.certification_admission_v1 where resource_id=r.resource_id for update;
 select * into strict p from production_control.current_tournament_pointer_v1 where scope_key=r.resource_id for update;
 if input->>'expected_admission_revision' is distinct from a.admission_revision::text then
  raise exception using errcode='40001',message='CERTIFICATION_ADMISSION_REVISION_STALE';
 end if;
 if not exists(select 1 from scoring_authority.ingress_gates g where g.tournament_id=p.tournament_id
   and g.authority='SUPABASE' and g.active_epoch_id=a.authority_epoch_id and g.unresolved_client_queues=0)
   or not exists(select 1 from scoring_authority.authority_epochs e where e.epoch_id=a.authority_epoch_id
     and e.status='COMMITTED' and e.authority_after='SUPABASE') then
  raise exception using errcode='55000',message='CERTIFICATION_ADMISSION_CANONICAL_AUTHORITY_REQUIRED';
 end if;
 if desired then
  select * into strict gate from scoring_authority.ingress_gates where tournament_id=p.tournament_id for update;
  select * into origin from production_control.certification_initialization_origins_v1 where resource_id=r.resource_id;
  select * into closed_generation from production_control.certification_ingress_generations_v1 value
   where value.resource_id=r.resource_id and value.generation_id=coalesce((
    select bound.generation_id from production_control.certification_ingress_generations_v1 bound
     where bound.resource_id=r.resource_id and bound.generation_id=gate.admission_generation_id
      and bound.tournament_id=p.tournament_id and bound.pointer_revision=p.pointer_revision
      and bound.authority_epoch_id=a.authority_epoch_id),origin.admission_generation_id);
  -- A malformed current CLOSED graph must not fall through to OPEN. Historical
  -- CLOSED predecessors with a legitimate successor do not control its gate.
  if closed_generation.state='CLOSED' or exists(select 1 from production_control.certification_ingress_generations_v1 foreign_bound
   where foreign_bound.generation_id=gate.admission_generation_id and foreign_bound.state='CLOSED')
   or exists(select 1 from production_control.certification_ingress_generations_v1 candidate
   where candidate.resource_id=r.resource_id and candidate.tournament_id=p.tournament_id
    and candidate.pointer_revision=p.pointer_revision and candidate.authority_epoch_id=a.authority_epoch_id
    and candidate.state='CLOSED' and not exists(select 1 from production_control.certification_ingress_generations_v1 child
     where child.resource_id=r.resource_id and child.predecessor_generation_id=candidate.generation_id)) then
   if origin.resource_id is null or closed_generation.state is distinct from 'CLOSED' or closed_generation.tournament_id is distinct from p.tournament_id
    or closed_generation.pointer_revision is distinct from p.pointer_revision or closed_generation.authority_epoch_id is distinct from a.authority_epoch_id
    or gate.state<>'PAUSED' or gate.authority<>'SUPABASE' or gate.boundary_mode<>'CERTIFICATION_INGRESS_V1'
    or gate.active_epoch_id is distinct from a.authority_epoch_id
    or exists(select 1 from production_control.certification_ingress_generations_v1 child
     where child.resource_id=r.resource_id and child.predecessor_generation_id=closed_generation.generation_id)
    or exists(select 1 from production_control.certification_ingress_generations_v1 other
     where other.resource_id=r.resource_id and other.generation_id<>closed_generation.generation_id and other.state in('OPEN','CLOSING'))then
    raise exception using errcode='40001',message='CERTIFICATION_ADMISSION_CLOSED_CONTEXT_STALE';end if;
 -- A real current gate binding always outranks the immutable initial origin,
 -- including a reopened initial tournament with the same pointer and epoch.
 select bound.generation_id into gate_generation
  from production_control.certification_ingress_generations_v1 bound
  where bound.resource_id=r.resource_id and bound.generation_id=gate.admission_generation_id
   and bound.tournament_id=p.tournament_id and bound.pointer_revision=p.pointer_revision
   and bound.authority_epoch_id=a.authority_epoch_id;
 if gate_generation is not null then
  if gate_generation<>closed_generation.generation_id then
   raise exception using errcode='40001',message='CERTIFICATION_ADMISSION_CLOSED_CONTEXT_STALE';end if;
 else
  -- Only the unchanged legacy gate shape at the actual initialization origin
  -- may lack a Certification gate binding. No time/latest-row discovery.
  if gate.admission_contract_version is distinct from 'production-scoring-admission-v2'
   or gate.admission_protocol_enforced is distinct from false or gate.admission_revision is distinct from 0
   or exists(select 1 from production_control.certification_ingress_generations_v1 bound
    where bound.generation_id=gate.admission_generation_id)
   or origin.resource_id is distinct from r.resource_id or origin.resource_class is distinct from r.resource_class
   or origin.installation_id is distinct from r.installation_id or origin.database_name is distinct from r.database_name
   or origin.project_ref is distinct from r.project_ref or origin.project_url is distinct from r.project_url
   or origin.registration_revision is distinct from r.registration_revision
   or origin.registration_manifest_digest is distinct from r.manifest_digest
   or origin.schema_digest is distinct from r.schema_digest or origin.binding_id is distinct from a.binding_id
   or origin.initial_tournament_id is distinct from p.tournament_id
   or origin.initial_pointer_revision is distinct from p.pointer_revision
   or origin.authority_epoch_id is distinct from a.authority_epoch_id
   or origin.admission_generation_id is distinct from closed_generation.generation_id or closed_generation.predecessor_generation_id is not null
   or exists(select 1 from production_control.certification_ingress_generations_v1 other
    where other.resource_id=r.resource_id and other.generation_id<>closed_generation.generation_id
     and other.tournament_id=p.tournament_id and other.pointer_revision=p.pointer_revision
     and other.authority_epoch_id=a.authority_epoch_id) then
   raise exception using errcode='40001',message='CERTIFICATION_ADMISSION_CLOSED_CONTEXT_STALE';end if;
 end if;
 if closed_generation.state='CLOSED' then
  ingress_evidence:=production_control.certification_ingress_evidence_v1(r.resource_id,closed_generation.generation_id);
  if ingress_evidence->>'drained' is distinct from 'true'
   or ingress_evidence->>'fingerprint_matches' is distinct from 'true'
   or ingress_evidence->>'captured_high_watermark' is distinct from closed_generation.high_watermark::text
   or ingress_evidence->>'captured_fingerprint' is distinct from closed_generation.lease_fingerprint
   or not exists(select 1 from production_control.scoring_admission_closures closed
    where closed.resource_class='CERTIFICATION' and closed.certification_resource_id=r.resource_id
     and closed.admission_generation_id=closed_generation.generation_id and closed.tournament_id=p.tournament_id
     and closed.authority_generation_id=a.authority_epoch_id and closed.authority='SUPABASE'
     and closed.closure_kind='SUPABASE_INGRESS' and closed.status='CLOSED'
     and closed.closed_admission_revision=closed_generation.revision and closed.closing_admission_revision=closed_generation.revision
     and closed.lease_high_watermark=closed_generation.high_watermark
     and closed.lease_set_fingerprint=closed_generation.lease_fingerprint
     and closed.lease_set_fingerprint=ingress_evidence->>'fingerprint') then
   raise exception using errcode='40001',message='CERTIFICATION_ADMISSION_CLOSED_EVIDENCE_REQUIRED';end if;
 end if;
   closed_verified:=true;
  end if;
 end if;
 update production_control.certification_admission_v1 set enabled=desired,admission_revision=admission_revision+1
 where resource_id=r.resource_id;
 update scoring_authority.ingress_gates set state=case when desired and not closed_verified then 'OPEN' else 'PAUSED' end,
   updated_by=current_user,updated_at=clock_timestamp() where tournament_id=p.tournament_id;
 insert into production_control.operation_audit_events(event_type,domain,actor,result,details)
 values('CERTIFICATION_ADMISSION_CHANGED','RESOURCE',current_user,'SUCCEEDED',
   jsonb_build_object('resource_id',r.resource_id,'installation_id',r.installation_id,'enabled',desired,
     'before_revision',a.admission_revision,'after_revision',a.admission_revision+1,'reason',input->>'reason'));
 return jsonb_build_object('ok',true,'enabled',desired,'admission_revision',a.admission_revision+1);
end;
$$;


ALTER FUNCTION production_control.set_certification_admission_v1(input jsonb) OWNER TO postgres;

--
-- Name: skins_source_before_full_net_v2(text, integer); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.skins_source_before_full_net_v2(target_tournament_id text, target_round_number integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'scoring_authority'
    AS $$
  select pg_catalog.jsonb_build_object(
    'tournament_id', target_tournament_id,
    'round_number', target_round_number,
    'matches', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'match_id', match_value.match_id,
          'format', match_value.format,
          'status', match_value.status,
          'match_revision', match_value.match_revision,
          'permission_revision', match_value.permission_revision,
          'scored_holes', match_value.scored_holes,
          'scorecard_complete', match_value.scorecard_complete,
          'result_winner', match_value.result_winner,
          'finalized_at', match_value.finalized_at,
          'scoring_snapshot_id', match_value.scoring_snapshot_id,
          'scoring_snapshot_hash', snapshot.canonical_hash,
          'participants', coalesce((
            select pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object(
                'player_id', participant.player_id,
                'team_side', participant.team_side,
                'player_slot', participant.player_slot,
                'playing_handicap', participant.playing_handicap,
                'final_strokes', participant.final_strokes
              ) order by participant.team_side, participant.player_slot,
                participant.player_id
            )
            from scoring_authority.match_participants participant
            where participant.match_id = match_value.match_id
          ), '[]'::jsonb)
        ) order by match_value.match_id
      )
      from scoring_authority.matches match_value
      join scoring_authority.scoring_snapshots snapshot
        on snapshot.snapshot_id = match_value.scoring_snapshot_id
      where match_value.tournament_id = target_tournament_id
        and match_value.round_number = target_round_number
    ), '[]'::jsonb),
    'holes', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'match_id', score.match_id,
          'hole_number', score.hole_number,
          'hole_revision', score.hole_revision,
          'team_1_gross_scores', score.team_1_gross_scores,
          'team_2_gross_scores', score.team_2_gross_scores,
          'team_1_strokes', score.team_1_strokes,
          'team_2_strokes', score.team_2_strokes,
          'team_1_net_score', score.team_1_net_score,
          'team_2_net_score', score.team_2_net_score,
          'hole_winner', score.hole_winner
        ) order by score.match_id, score.hole_number
      )
      from scoring_authority.hole_scores score
      join scoring_authority.matches match_value
        on match_value.match_id = score.match_id
      where match_value.tournament_id = target_tournament_id
        and match_value.round_number = target_round_number
    ), '[]'::jsonb)
  )
$$;


ALTER FUNCTION production_control.skins_source_before_full_net_v2(target_tournament_id text, target_round_number integer) OWNER TO postgres;

--
-- Name: stage_production_maintenance_release(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.stage_production_maintenance_release(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if input->>'maintenance_provenance_contract' =
       'production-maintenance-staging-provenance-v2'
  then
    return production_control.stage_production_maintenance_release_v2(input);
  end if;
  return production_control.stage_production_maintenance_release_v1(input);
end;
$$;


ALTER FUNCTION production_control.stage_production_maintenance_release(input jsonb) OWNER TO postgres;

--
-- Name: stage_production_maintenance_release_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.stage_production_maintenance_release_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  existing jsonb;
  provenance jsonb;
  response_value jsonb;
  stage_request_fingerprint text := pg_catalog.lower(
    coalesce(input->>'request_fingerprint', '')
  );
  stage_payload_hash text := production_control.cutover_payload_hash(input);
  certification_fingerprint text := pg_catalog.lower(
    coalesce(input->>'certification_fingerprint', '')
  );
  environment_fingerprint text := pg_catalog.lower(
    coalesce(input->>'environment_delta_fingerprint_v2', '')
  );
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  perform production_control.assert_no_active_physical_writer_fence();
  if input->>'boundary_mode' is distinct from 'MAINTENANCE_WINDOW_V1'
     or certification_fingerprint !~ '^[0-9a-f]{64}$'
     or environment_fingerprint !~ '^[0-9a-f]{64}$'
     or nullif(input->>'provider_fence_id', '') is not null
     or nullif(input->>'provider_fence_verification_id', '') is not null
     or nullif(input->>'quiesce_evidence_id', '') is not null
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_STAGE_INPUT_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;

  if activation.state = 'STAGED' then
    if activation.boundary_mode is distinct from 'MAINTENANCE_WINDOW_V1'
       or activation.activation_revision is distinct from
         (input->>'expected_activation_revision')::bigint + 1
       or activation.authority_generation_id is distinct from
         (input->>'expected_authority_generation')::uuid
       or activation.current_authority <> 'GOOGLE'
       or activation.read_cutover_phase <> 'STATIC_BACKEND'
       or activation.maintenance_state <> 'NORMAL'
       or activation.scoring_ingress_enabled
       or activation.active_transition_epoch_id is not null
       or activation.active_google_writer_provider_fence_id is not null
       or activation.active_google_writer_provider_verification_id is not null
       or activation.active_vercel_quiesce_evidence_id is not null
       or activation.first_supabase_write_possible_at is not null
       or activation.first_supabase_write_observed_at is not null
       or activation.first_supabase_mutation_key is not null
       or activation.first_supabase_match_id is not null
       or activation.first_supabase_match_revision is not null
       or resource.current_tournament_read_authority <> 'GOOGLE'
       or resource.scoring_authority <> 'GOOGLE'
       or resource.participant_identity_authority <> 'PASSPORT'
       or resource.public_supabase_reads_enabled
       or resource.scoring_ingress_enabled
       or resource.google_writes_enabled
       or resource.auth_user_creation_enabled
       or resource.odds_publication_enabled
       or resource.workers_enabled
       or gate.state <> 'PAUSED'
       or gate.authority <> 'GOOGLE'
       or gate.admission_state <> 'OPEN'
       or gate.admission_revision is distinct from
         (input->>'expected_admission_revision')::bigint
       or gate.admission_generation_id is distinct from
         (input->>'expected_admission_generation')::uuid
       or gate.unresolved_client_queues <> 0
       or gate.active_epoch_id is not null
       or gate.active_closure_id is not null
       or gate.external_fence_evidence_id is not null
       or gate.google_writer_provider_fence_id is not null
       or gate.google_writer_provider_verification_id is not null
       or exists (
         select 1 from scoring_authority.scoring_ingress_leases lease
         where lease.tournament_id = '2026'
           and (
             lease.status = 'ACTIVE'
             or lease.resolution_state in (
               'LEGACY_UNCLASSIFIED', 'ADMITTED', 'WRITE_STARTED',
               'AMBIGUOUS', 'PARTIAL_WRITE'
             )
           )
       )
       or exists (
         select 1 from scoring_authority.authority_epochs epoch
         where epoch.tournament_id = '2026'
           and epoch.status in ('PREPARED', 'COMMITTED')
       )
       or exists (
         select 1 from scoring_authority.google_outbox_events event
         where event.tournament_id = '2026'
       )
       or exists (
         select 1 from production_control.worker_controls worker
         where worker.enabled
            or worker.scheduler_installed
            or worker.google_writes_allowed
       )
       or exists (
         select 1 from production_control.worker_contracts contract
         where contract.operation_allowed
            or contract.scheduler_installed
            or contract.authoritative_write_allowed
       )
       or activation.staged_request_fingerprint is distinct from
         stage_request_fingerprint
       or activation.staged_payload_hash is distinct from stage_payload_hash
       or activation.staged_certification_fingerprint is distinct from
         certification_fingerprint
       or activation.staged_environment_delta_fingerprint_v2 is distinct from
         environment_fingerprint
       or activation.expected_deployment_commit is distinct from
         '6911c63cee6f6fe40c03a95bf7a7ba824be0d1fb'
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_STAGE_PROVENANCE_IMMUTABLE';
    end if;
    existing := production_control.lookup_cutover_receipt(
      'STAGE_RELEASE', input
    );
    if existing is null then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_STAGE_RECEIPT_REQUIRED';
    end if;
    return existing || pg_catalog.jsonb_build_object(
      'boundary_mode', 'MAINTENANCE_WINDOW_V1',
      'maintenance_state', 'NORMAL',
      'stage_request_fingerprint', stage_request_fingerprint,
      'stage_payload_hash', stage_payload_hash,
      'certification_fingerprint', certification_fingerprint,
      'environment_delta_fingerprint_v2', environment_fingerprint,
      'maintenance_provenance_contract',
        'production-maintenance-staging-provenance-v1'
    );
  end if;

  -- Hold the complete semantic projection and every state predicate stable
  -- until the base stage and provenance binding commit atomically.
  lock table
    production_control.import_runs,
    production_control.current_shadow_revisions,
    production_control.current_shadow_semantic_baselines,
    production_control.worker_controls,
    production_control.worker_contracts,
    scoring_authority.tournaments,
    scoring_authority.players,
    scoring_authority.teams,
    scoring_authority.tournament_players,
    scoring_authority.rounds,
    scoring_authority.scoring_snapshots,
    scoring_authority.matches,
    scoring_authority.match_participants,
    scoring_authority.scoring_permissions,
    scoring_authority.match_holes,
    scoring_authority.hole_scores,
    scoring_authority.google_match_checkpoints,
    scoring_authority.scoring_ingress_leases,
    scoring_authority.authority_epochs,
    scoring_authority.google_outbox_events
  in share mode;

  provenance :=
    production_control.production_maintenance_stage_provenance_v1(input);
  if provenance->>'certification_fingerprint' is distinct from
       certification_fingerprint
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_CERTIFICATION_FINGERPRINT_MISMATCH';
  end if;
  if provenance->>'environment_delta_fingerprint_v2' is distinct from
       environment_fingerprint
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_ENVIRONMENT_DELTA_MISMATCH';
  end if;

  response_value :=
    public.stage_production_cutover_release_pre_step11_6_rehearsal(input);
  update production_control.cutover_activation_state
  set boundary_mode = 'MAINTENANCE_WINDOW_V1',
      maintenance_state = 'NORMAL',
      maintenance_started_at = null,
      maintenance_ended_at = null,
      staged_request_fingerprint = stage_request_fingerprint,
      staged_payload_hash = stage_payload_hash,
      staged_certification_fingerprint = certification_fingerprint,
      staged_environment_delta_fingerprint_v2 = environment_fingerprint
  where scope_key = 'BAGGER_INV_PRODUCTION'
    and state = 'STAGED'
    and expected_deployment_commit =
      '6911c63cee6f6fe40c03a95bf7a7ba824be0d1fb';
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_STAGE_BINDING_FAILED';
  end if;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_MAINTENANCE_RELEASE_PROVENANCE_STAGED',
    'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    stage_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'boundary_mode', 'MAINTENANCE_WINDOW_V1',
      'deployment_commit',
        '6911c63cee6f6fe40c03a95bf7a7ba824be0d1fb',
      'maintenance_provenance_contract',
        provenance->>'maintenance_provenance_contract',
      'certification_fingerprint', certification_fingerprint,
      'environment_delta_fingerprint_v2', environment_fingerprint,
      'semantic_parity_contract',
        provenance->>'semantic_parity_contract',
      'semantic_payload_fingerprint',
        provenance->>'semantic_payload_fingerprint',
      'semantic_database_fingerprint',
        provenance->>'semantic_database_fingerprint',
      'unexplained_semantic_difference_count', 0,
      'activation_revision_before',
        provenance->'activation_revision',
      'authority_generation_id',
        provenance->'authority_generation_id',
      'admission_revision', provenance->'admission_revision',
      'admission_generation_id', provenance->'admission_generation_id',
      'first_supabase_canonical_write_possible', false,
      'first_supabase_canonical_write_observed', false
    )
  );

  return response_value || pg_catalog.jsonb_build_object(
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'maintenance_state', 'NORMAL',
    'stage_request_fingerprint', stage_request_fingerprint,
    'stage_payload_hash', stage_payload_hash,
    'certification_fingerprint', certification_fingerprint,
    'environment_delta_fingerprint_v2', environment_fingerprint,
    'maintenance_provenance_contract',
      provenance->>'maintenance_provenance_contract'
  );
end;
$_$;


ALTER FUNCTION production_control.stage_production_maintenance_release_v1(input jsonb) OWNER TO postgres;

--
-- Name: stage_production_maintenance_release_v2(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.stage_production_maintenance_release_v2(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  binding production_control.maintenance_release_candidates%rowtype;
  existing jsonb;
  provenance jsonb;
  response_value jsonb;
  stage_request_fingerprint text := pg_catalog.lower(
    coalesce(input->>'request_fingerprint', '')
  );
  stage_payload_hash text := production_control.cutover_payload_hash(input);
  certification_fingerprint text := pg_catalog.lower(
    coalesce(input->>'certification_fingerprint', '')
  );
