ALTER FUNCTION production_control.sync_future_google_writer_binding_v2() OWNER TO postgres;

--
-- Name: sync_future_google_writer_job_v2(text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.sync_future_google_writer_job_v2(target_tournament text, target_match text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target production_control.future_google_writer_targets_v2%rowtype;
  binding production_control.future_runtime_match_bindings_v2%rowtype;
  fingerprint_value text;
  eligible boolean := false;
begin
  select value.* into target
  from production_control.future_google_writer_targets_v2 value
  where value.tournament_id = target_tournament
    and value.contract_status = 'CERTIFIED';
  select value.* into binding
  from production_control.future_runtime_match_bindings_v2 value
  where value.tournament_id = target_tournament
    and value.match_id = target_match;
  eligible := target.tournament_id is not null
    and binding.match_id is not null
    and binding.runtime_state = 'PREPARED'
    and binding.configuration_fingerprint ~ '^[0-9a-f]{64}$';
  if eligible then
    fingerprint_value := production_control.future_runtime_hash_v2(
      pg_catalog.jsonb_build_object(
        'tournamentId', target_tournament, 'matchId', target_match,
        'writerGenerationId', target.writer_generation_id,
        'destinationWorkbookId', target.destination_workbook_id,
        'targetContractFingerprint', target.target_contract_fingerprint,
        'structuralSetupRevision', binding.structural_setup_revision,
        'runtimeRevision', binding.runtime_revision,
        'configurationFingerprint', binding.configuration_fingerprint
      )
    );
  end if;
  update production_control.future_match_google_compatibility_jobs_v1 value set
    writer_installed = eligible,
    writer_generation_id = case when eligible
      then target.writer_generation_id else value.writer_generation_id end,
    destination_workbook_id = case when eligible
      then target.destination_workbook_id else value.destination_workbook_id end,
    target_contract_fingerprint = case when eligible
      then target.target_contract_fingerprint
      else value.target_contract_fingerprint end,
    structural_fingerprint = case when eligible
      then fingerprint_value else null end,
    structural_runtime_revision = case when eligible
      then binding.runtime_revision else null end,
    status = case
      when value.status = 'NOT_REQUIRED' then 'NOT_REQUIRED'
      when not eligible then 'PROVISIONING_REQUIRED'
      when value.structural_fingerprint is distinct from fingerprint_value
        or value.writer_generation_id is distinct from target.writer_generation_id
        or value.destination_workbook_id
          is distinct from target.destination_workbook_id
        or value.target_contract_fingerprint
          is distinct from target.target_contract_fingerprint
        then 'PROVISIONING_REQUIRED'
      else value.status end,
    expected_manifest_fingerprint = case
      when eligible and value.structural_fingerprint = fingerprint_value
        and value.writer_generation_id = target.writer_generation_id
        and value.destination_workbook_id = target.destination_workbook_id
        and value.target_contract_fingerprint = target.target_contract_fingerprint
      then value.expected_manifest_fingerprint else null end,
    readback_fingerprint = case
      when eligible and value.structural_fingerprint = fingerprint_value
        and value.writer_generation_id = target.writer_generation_id
        and value.destination_workbook_id = target.destination_workbook_id
        and value.target_contract_fingerprint = target.target_contract_fingerprint
      then value.readback_fingerprint else null end,
    readback_checkpoint = case
      when eligible and value.structural_fingerprint = fingerprint_value
        and value.writer_generation_id = target.writer_generation_id
        and value.destination_workbook_id = target.destination_workbook_id
        and value.target_contract_fingerprint = target.target_contract_fingerprint
      then value.readback_checkpoint else null end,
    certified_at = case
      when eligible and value.structural_fingerprint = fingerprint_value
        and value.writer_generation_id = target.writer_generation_id
        and value.destination_workbook_id = target.destination_workbook_id
        and value.target_contract_fingerprint = target.target_contract_fingerprint
      then value.certified_at else null end,
    claim_token = null, claimed_by = null, lease_expires_at = null,
    available_at = pg_catalog.clock_timestamp(),
    safe_error_code = case when eligible then null
      else 'FUTURE_GOOGLE_WRITER_CONTRACT_NOT_READY' end,
    updated_at = pg_catalog.clock_timestamp()
  where value.tournament_id = target_tournament
    and value.match_id = target_match;
end;
$_$;


ALTER FUNCTION production_control.sync_future_google_writer_job_v2(target_tournament text, target_match text) OWNER TO postgres;

--
-- Name: sync_odds_publication_public_pointer_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.sync_odds_publication_public_pointer_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op = 'UPDATE'
     and new.publication_authority is not distinct from old.publication_authority
     and new.publication_state is not distinct from old.publication_state
     and new.current_snapshot_id is not distinct from old.current_snapshot_id
     and new.publication_revision is not distinct from old.publication_revision
  then
    return new;
  end if;

  insert into scoring_authority.odds_publication_public_pointer_v1 (
    tournament_id, contract_version, publication_state,
    current_snapshot_id, current_publication_revision,
    last_published_snapshot_id, last_publication_revision,
    pointer_revision, last_withdrawal_event_id, updated_at
  ) values (
    new.tournament_id, 'production-odds-publication-pointer-v1',
    case when new.publication_authority = 'SUPABASE'
              and new.publication_state = 'PUBLISHED'
         then 'PUBLISHED' else 'UNPUBLISHED' end,
    case when new.publication_authority = 'SUPABASE'
              and new.publication_state = 'PUBLISHED'
         then new.current_snapshot_id else null end,
    case when new.publication_authority = 'SUPABASE'
              and new.publication_state = 'PUBLISHED'
         then new.publication_revision else null end,
    case when new.publication_authority = 'SUPABASE'
              and new.publication_state = 'PUBLISHED'
         then new.current_snapshot_id else null end,
    case when new.publication_authority = 'SUPABASE'
              and new.publication_state = 'PUBLISHED'
         then new.publication_revision else 0 end,
    case when new.publication_authority = 'SUPABASE'
              and new.publication_state = 'PUBLISHED'
         then new.publication_revision else 0 end,
    null, pg_catalog.clock_timestamp()
  ) on conflict (tournament_id) do update set
    publication_state = excluded.publication_state,
    current_snapshot_id = excluded.current_snapshot_id,
    current_publication_revision = excluded.current_publication_revision,
    last_published_snapshot_id = excluded.last_published_snapshot_id,
    last_publication_revision = excluded.last_publication_revision,
    pointer_revision =
      scoring_authority.odds_publication_public_pointer_v1.pointer_revision + 1,
    last_withdrawal_event_id = null,
    updated_at = excluded.updated_at;
  return new;
end;
$$;


ALTER FUNCTION production_control.sync_odds_publication_public_pointer_v1() OWNER TO postgres;

--
-- Name: tournament_awards_archive_projection_v1(text, uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.tournament_awards_archive_projection_v1(target text, selected_revision uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'award_id',item.award_id::text,
    'award_type',item.award_id::text,
    'label',item.title,
    'recipient_kind',item.recipient_kind,
    'winner_player_id',item.winner_player_id,
    'winner_team_id',item.winner_team_id,
    'recipient_display',item.recipient_display,
    'source_payload',pg_catalog.jsonb_build_object(
      'description',item.description,
      'displayOrder',item.display_order,
      'source','SUPABASE_DIRECTOR'
    )
  ) order by item.display_order,item.award_id), '[]'::jsonb)
  from production_control.tournament_award_items_v1 item
  left join production_control.tournament_awards_current_v1 pointer
    on pointer.tournament_id=target
  where item.tournament_id=target
    and item.revision_id=coalesce(selected_revision,pointer.current_revision_id)
    and item.publication_state='PUBLISHED'
$$;


ALTER FUNCTION production_control.tournament_awards_archive_projection_v1(target text, selected_revision uuid) OWNER TO postgres;

