ALTER FUNCTION production_control.tournament_awards_hash_v1(value jsonb) OWNER TO postgres;

--
-- Name: tournament_awards_public_projection_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.tournament_awards_public_projection_v1(target text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
  select pg_catalog.jsonb_build_object(
    'tournamentId', target,
    'revision', coalesce(pointer.current_revision,0),
    'awards', coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'awardId',item.award_id,'title',item.title,
        'description',item.description,'displayOrder',item.display_order,
        'recipientKind',item.recipient_kind,
        'recipient',case item.recipient_kind
          when 'PLAYER' then pg_catalog.jsonb_build_object(
            'kind','PLAYER','id',player.player_id,'name',player.display_name,
            'slug',coalesce(profile.profile_slug,
              nullif(player.source_payload->>'Slug',''),''),
            'image',case when coalesce(
              player.source_payload->>'Photo Filename','')='' then '' else
              '/images/players/' || pg_catalog.regexp_replace(
                player.source_payload->>'Photo Filename',
                '\.(png|jpe?g|webp|avif)$','','i') || '.webp' end,
            'teamId',coalesce(membership.team_id,''),
            'teamName',coalesce(player_team.name,'')
          )
          when 'TEAM' then pg_catalog.jsonb_build_object(
            'kind','TEAM','id',winner_team.team_id,'name',winner_team.name,
            'image',coalesce(
              nullif(winner_team.source_payload->>'Team Logo',''),
              nullif(winner_team.source_payload->>'Logo Filename',''),'')
          )
          when 'TEXT' then pg_catalog.jsonb_build_object(
            'kind','TEXT','name',item.recipient_display
          )
          else pg_catalog.jsonb_build_object(
            'kind','UNAVAILABLE','name','Pending'
          ) end
      ) order by item.display_order,item.award_id)
      from production_control.tournament_award_items_v1 item
      left join scoring_authority.players player
        on player.player_id=item.winner_player_id
      left join production_control.player_governance_profiles_v1 profile
        on profile.player_id=player.player_id
      left join scoring_authority.tournament_players membership
        on membership.tournament_id=target
       and membership.player_id=player.player_id
      left join scoring_authority.teams player_team
        on player_team.tournament_id=membership.tournament_id
       and player_team.team_id=membership.team_id
      left join scoring_authority.teams winner_team
        on winner_team.tournament_id=target
       and winner_team.team_id=item.winner_team_id
      where item.revision_id=pointer.current_revision_id
        and item.publication_state='PUBLISHED'), '[]'::jsonb)
  )
  from (select target tournament_id) requested
  left join production_control.tournament_awards_current_v1 pointer
    on pointer.tournament_id=requested.tournament_id
$_$;


ALTER FUNCTION production_control.tournament_awards_public_projection_v1(target text) OWNER TO postgres;

--
-- Name: tournament_setup_dependency_codes_before_late_r3_v1(text, text, integer, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.tournament_setup_dependency_codes_before_late_r3_v1(target_player text DEFAULT NULL::text, target_team text DEFAULT NULL::text, target_round integer DEFAULT NULL::integer, target_match text DEFAULT NULL::text, change_kind text DEFAULT 'STRUCTURAL'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  codes jsonb := '[]'::jsonb;
  current_draft uuid;
  target_kind text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    change_kind, 'STRUCTURAL'
  )));
begin
  if target_kind <> 'TOURNAMENT_METADATA' and exists (
    select 1
    from scoring_authority.matches match_value
    where match_value.tournament_id = '2026'
      and (target_match is null or match_value.match_id = target_match)
      and (target_round is null or match_value.round_number = target_round)
      and (
        target_player is null or exists (
          select 1 from scoring_authority.match_participants participant
          where participant.match_id = match_value.match_id
            and participant.player_id = target_player
        )
      )
      and (
        target_team is null or exists (
          select 1
          from scoring_authority.match_participants participant
          join scoring_authority.tournament_players membership
            on membership.tournament_id = match_value.tournament_id
           and membership.player_id = participant.player_id
          where participant.match_id = match_value.match_id
            and membership.team_id = target_team
        )
      )
      and not production_control.handicap_v1_match_is_unstarted(
        match_value.match_id
      )
  ) then
    codes := codes || pg_catalog.jsonb_build_array('STARTED_MATCH_DEPENDENCY');
  end if;
  if target_kind <> 'TOURNAMENT_METADATA' and exists (
    select 1
    from scoring_authority.matches match_value
    where match_value.tournament_id = '2026'
      and (target_match is null or match_value.match_id = target_match)
      and (target_round is null or match_value.round_number = target_round)
      and (
        exists (
          select 1 from scoring_authority.scoring_permissions permission
          where permission.match_id = match_value.match_id
            and (permission.can_score or permission.revoked_at is null
              or permission.permission_revision
                <> match_value.permission_revision)
        ) or exists (
          select 1 from scoring_authority.scoring_ingress_leases lease
          where lease.tournament_id = '2026'
            and lease.match_id = match_value.match_id
            and lease.expires_at > pg_catalog.clock_timestamp()
        )
      )
  ) then
    codes := codes || pg_catalog.jsonb_build_array(
      'ACTIVE_SCORING_ACCESS_DEPENDENCY'
    );
  end if;

  select current_value.revision_id into current_draft
  from scoring_authority.draft_current_revisions current_value
  where current_value.tournament_id = '2026';
  if current_draft is not null and (
    (target_player is not null and exists (
      select 1 from scoring_authority.draft_pick_facts pick
      where pick.revision_id = current_draft
        and pick.tournament_id = '2026'
        and pick.player_id = target_player
        and pick.pick_status = 'SELECTED'
        and (target_team is null or pick.team_id is distinct from target_team)
    )) or
    (target_team is not null and target_kind = 'TEAM' and exists (
      select 1 from scoring_authority.draft_configuration_facts config
      where config.revision_id = current_draft
        and config.tournament_id = '2026'
        and target_team in (config.team_1_id, config.team_2_id)
    )) or
    (target_player is not null and target_kind = 'TEAM' and exists (
      select 1 from scoring_authority.draft_configuration_facts config
      where config.revision_id = current_draft
        and config.tournament_id = '2026'
        and target_player in (
          config.team_1_captain_player_id, config.team_2_captain_player_id
        )
    ))
  ) then
    codes := codes || pg_catalog.jsonb_build_array('DRAFT_DEPENDENCY');
  end if;

  if target_kind in (
       'ROSTER', 'ROUND', 'COURSE', 'MATCH', 'PAIRINGS', 'SCORING_CONTEXT'
     ) and exists (
    select 1
    from scoring_authority.net_skins_v1_configuration_current current_value
    join scoring_authority.net_skins_v1_configuration_revisions revision_value
      on revision_value.configuration_revision_id =
        current_value.configuration_revision_id
    where current_value.tournament_id = '2026'
      and current_value.state = 'CONFIGURED'
      and (
        target_round is null or exists (
          select 1
          from pg_catalog.jsonb_array_elements(coalesce(
            revision_value.configuration_manifest->'rounds', '[]'::jsonb
          )) round_value
          where (round_value->>'round_number')::integer = target_round
            and (target_match is null or target_match in (
              select pg_catalog.jsonb_array_elements_text(coalesce(
                round_value->'match_ids', '[]'::jsonb
              ))
            ))
        )
      )
  ) then
    codes := codes || pg_catalog.jsonb_build_array(
      'NET_SKINS_CONFIGURATION_DEPENDENCY'
    );
  end if;
  if target_kind in (
       'ROSTER', 'ROUND', 'COURSE', 'MATCH', 'PAIRINGS', 'SCORING_CONTEXT'
     ) and (
    exists (
      select 1 from scoring_authority.net_skins_v1_recalculation_jobs job
      where job.tournament_id = '2026'
        and job.status in ('PENDING', 'RUNNING')
        and (target_round is null or job.round_number = target_round)
    ) or exists (
      select 1 from scoring_authority.net_skins_v1_result_revisions result_value
      where result_value.tournament_id = '2026'
        and result_value.is_current
        and (target_round is null or result_value.round_number = target_round)
    )
  ) then
    codes := codes || pg_catalog.jsonb_build_array('NET_SKINS_RESULT_DEPENDENCY');
  end if;

  if target_kind in (
       'ROSTER', 'ROUND', 'COURSE', 'MATCH', 'PAIRINGS', 'SCORING_CONTEXT'
     ) and exists (
    select 1
    from scoring_authority.calcutta_v1_current current_value
    where current_value.tournament_id = '2026'
      and current_value.auction_revision > 0
      and (
        target_player is null
        or exists (
          select 1
          from scoring_authority.calcutta_v1_auction_fact_revisions auction
          cross join lateral pg_catalog.jsonb_array_elements(coalesce(
            auction.auction_manifest->'purchases', '[]'::jsonb
          )) purchase
          where auction.auction_revision_id = current_value.auction_revision_id
            and purchase->>'player_id' = target_player
        )
        or exists (
          select 1
          from scoring_authority.calcutta_v1_auction_fact_revisions auction
          cross join lateral pg_catalog.jsonb_array_elements(coalesce(
            auction.auction_manifest->'ownership', '[]'::jsonb
          )) owner_value
          where auction.auction_revision_id = current_value.auction_revision_id
            and owner_value->>'owner_player_id' = target_player
        )
      )
  ) then
    codes := codes || pg_catalog.jsonb_build_array('CALCUTTA_AUCTION_DEPENDENCY');
  end if;
  if target_kind in (
       'ROUND', 'COURSE', 'MATCH', 'PAIRINGS', 'SCORING_CONTEXT'
     ) and (
    exists (
      select 1 from scoring_authority.calcutta_v1_current current_value
      where current_value.tournament_id = '2026'
        and (current_value.publication_state = 'PUBLISHED'
          or current_value.result_revision > 0)
    ) or exists (
      select 1 from scoring_authority.calcutta_v1_recalculation_jobs job
      where job.tournament_id = '2026'
        and job.status in ('PENDING', 'RUNNING')
    )
  ) then
    codes := codes || pg_catalog.jsonb_build_array('CALCUTTA_RESULT_DEPENDENCY');
  end if;

  if target_kind in (
       'ROSTER', 'TEAM', 'ROUND', 'COURSE', 'MATCH', 'PAIRINGS',
       'SCORING_CONTEXT'
     ) and (
    production_control.odds_publication_blocks_setup_v1('2026')
  ) then
    codes := codes || pg_catalog.jsonb_build_array('ODDS_PUBLICATION_DEPENDENCY');
  end if;

  return coalesce((
    select pg_catalog.jsonb_agg(value order by value)
    from (
      select distinct item #>> '{}' as value
      from pg_catalog.jsonb_array_elements(codes) item
    ) deduplicated
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION production_control.tournament_setup_dependency_codes_before_late_r3_v1(target_player text, target_team text, target_round integer, target_match text, change_kind text) OWNER TO postgres;

--
-- Name: tournament_setup_dependency_codes_v1(text, text, integer, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.tournament_setup_dependency_codes_v1(target_player text DEFAULT NULL::text, target_team text DEFAULT NULL::text, target_round integer DEFAULT NULL::integer, target_match text DEFAULT NULL::text, change_kind text DEFAULT 'STRUCTURAL'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare codes jsonb;
begin
  codes:=production_control.tournament_setup_dependency_codes_before_late_r3_v1(
    target_player,target_team,target_round,target_match,change_kind);
  if target_player is null and target_team is null and target_round=3
    and change_kind in('PAIRINGS','SCORING_CONTEXT') and exists(
      select 1 from production_control.late_r3_transactions_v1 t
      where transaction_id=txid_current() and target_match=any(eligible_matches)
        and ((change_kind='PAIRINGS' and operation in('REPLACE_PAIRINGS','REPLACE_ROUND_PAIRINGS'))
          or (change_kind='SCORING_CONTEXT' and operation='PREPARE_SCORING_CONTEXT')))
  then
    select coalesce(jsonb_agg(value),'[]') into codes from jsonb_array_elements(codes)
      where value not in('"CALCUTTA_AUCTION_DEPENDENCY"'::jsonb,'"CALCUTTA_RESULT_DEPENDENCY"'::jsonb);
  end if;
  return codes;
end;
$$;


ALTER FUNCTION production_control.tournament_setup_dependency_codes_v1(target_player text, target_team text, target_round integer, target_match text, change_kind text) OWNER TO postgres;

--
-- Name: tournament_setup_hash_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.tournament_setup_hash_v1(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
  select pg_catalog.encode(extensions.digest(value::text, 'sha256'), 'hex')
$$;


ALTER FUNCTION production_control.tournament_setup_hash_v1(value jsonb) OWNER TO postgres;

--
-- Name: tournament_setup_readiness_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.tournament_setup_readiness_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  blockers jsonb := '[]'::jsonb;
  tournament_value scoring_authority.tournaments%rowtype;
  operational_value scoring_authority.tournament_setup_operational_v1%rowtype;
  active_roster integer := 0;
  handicap_covered integer := 0;
  team_count integer := 0;
  round_count integer := 0;
  match_count integer := 0;
  paired_count integer := 0;
  snapshot_ready_count integer := 0;
  started_count integer := 0;
  net_skins_ready boolean := false;
  net_skins_state text := 'NOT_READY';
  calcutta_state text := 'NOT_CONFIGURED';
  expected_matches integer := 0;
  value record;
begin
  select item.* into strict tournament_value
  from scoring_authority.tournaments item
  where item.tournament_id = '2026';
  select item.* into operational_value
  from scoring_authority.tournament_setup_operational_v1 item
  where item.tournament_id = '2026';

  if pg_catalog.btrim(coalesce(tournament_value.name, '')) = '' then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'TOURNAMENT_NAME_REQUIRED', 'section', 'tournament',
        'message', 'Tournament name is required.'
      )
    );
  end if;
  if operational_value.tournament_id is null then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'TOURNAMENT_OPERATIONAL_METADATA_NOT_STARTED',
        'section', 'tournament',
        'message', 'Tournament dates, destination, and timezone need review.'
      )
    );
  else
    if operational_value.start_date is null
       or operational_value.end_date is null then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'TOURNAMENT_DATES_REQUIRED', 'section', 'tournament',
          'message', 'Tournament start and end dates are required.'
        )
      );
    end if;
    if pg_catalog.btrim(coalesce(operational_value.destination, '')) = '' then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'TOURNAMENT_DESTINATION_REQUIRED', 'section', 'tournament',
          'message', 'Tournament destination is required.'
        )
      );
    end if;
    if pg_catalog.btrim(coalesce(operational_value.timezone, '')) = '' then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'TOURNAMENT_TIMEZONE_REQUIRED', 'section', 'tournament',
          'message', 'Tournament timezone is required.'
        )
      );
    end if;
  end if;

  select pg_catalog.count(*)::integer into team_count
  from scoring_authority.teams team
  where team.tournament_id = '2026';
  if team_count <> 2 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'TWO_TEAMS_REQUIRED', 'section', 'teams',
        'message', 'Exactly two tournament teams are required.',
        'currentCount', team_count
      )
    );
  end if;
  for value in
    select team.team_id, team.name, team.team_side,
      coalesce(detail.captain_player_id,
        nullif(team.source_payload->>'Captain', '')) captain_player_id
    from scoring_authority.teams team
    left join scoring_authority.tournament_setup_team_details_v1 detail
      on detail.tournament_id = team.tournament_id
     and detail.team_id = team.team_id
    where team.tournament_id = '2026'
    order by team.team_side
  loop
    if pg_catalog.btrim(coalesce(value.name, '')) = '' then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'TEAM_NAME_REQUIRED', 'section', 'teams',
          'target', value.team_id,
          'message', pg_catalog.format('%s needs a team name.', value.team_id)
        )
      );
    end if;
    if value.captain_player_id is null or not exists (
      select 1 from scoring_authority.tournament_players membership
      where membership.tournament_id = '2026'
        and membership.player_id = value.captain_player_id
        and membership.team_id = value.team_id
        and membership.participation_status = 'ACTIVE'
    ) then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'TEAM_CAPTAIN_REQUIRED', 'section', 'teams',
          'target', value.team_id,
          'message', pg_catalog.format(
            '%s needs an active roster captain.', value.name
          )
        )
      );
    end if;
  end loop;

  select pg_catalog.count(*)::integer into active_roster
  from scoring_authority.tournament_players membership
  where membership.tournament_id = '2026'
    and membership.participation_status = 'ACTIVE';
  if active_roster = 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ACTIVE_ROSTER_REQUIRED', 'section', 'roster',
        'message', 'Add active Players to the tournament roster.'
      )
    );
  end if;
  if active_roster > 0 and active_roster % 4 <> 0 then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROSTER_FORMAT_DIVISIBILITY_INVALID', 'section', 'roster',
        'message',
          'The active roster must divide evenly into Best Ball and Scramble matches.'
      )
    );
  end if;
  if exists (
    select 1 from scoring_authority.tournament_players membership
    left join scoring_authority.teams team
      on team.tournament_id = membership.tournament_id
     and team.team_id = membership.team_id
     and team.team_side = membership.team_side
    where membership.tournament_id = '2026'
      and membership.participation_status = 'ACTIVE'
      and team.team_id is null
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROSTER_TEAM_ASSIGNMENT_INVALID', 'section', 'roster',
        'message', 'Every active roster Player needs a valid team assignment.'
      )
    );
  end if;
  select pg_catalog.count(*)::integer into handicap_covered
  from scoring_authority.tournament_players membership
  join scoring_authority.handicap_revision_current current_value
    on current_value.tournament_id = membership.tournament_id
  join scoring_authority.handicap_revision_entries entry
    on entry.revision_id = current_value.revision_id
   and entry.tournament_id = membership.tournament_id
   and entry.player_id = membership.player_id
  where membership.tournament_id = '2026'
    and membership.participation_status = 'ACTIVE';
  if handicap_covered <> active_roster then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROSTER_HANDICAPS_INCOMPLETE', 'section', 'roster',
        'message', pg_catalog.format(
          '%s roster Players are missing an approved tournament handicap.',
          active_roster - handicap_covered
        ),
        'missingCount', active_roster - handicap_covered
      )
    );
  end if;

  select pg_catalog.count(*)::integer into round_count
  from scoring_authority.rounds round_value
  where round_value.tournament_id = '2026';
  for value in
    select expected.round_number, expected.format,
      round_value.format actual_format, round_value.name
    from (values (1, 'BB'), (2, 'SC'), (3, 'SI'))
      expected(round_number, format)
    left join scoring_authority.rounds round_value
      on round_value.tournament_id = '2026'
     and round_value.round_number = expected.round_number
  loop
    if value.actual_format is null then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'ROUND_REQUIRED', 'section', 'rounds',
          'target', pg_catalog.format('Round %s', value.round_number),
          'message', pg_catalog.format('Round %s is not configured.',
            value.round_number)
        )
      );
    elsif value.actual_format <> value.format then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'ROUND_FORMAT_INVALID', 'section', 'rounds',
          'target', pg_catalog.format('Round %s', value.round_number),
          'message', pg_catalog.format(
            'Round %s must use %s for the current tournament contract.',
            value.round_number, value.format
          )
        )
      );
    end if;
  end loop;

  if exists (
    select 1
    from scoring_authority.matches match_value
    join scoring_authority.scoring_snapshots snapshot
      on snapshot.snapshot_id = match_value.scoring_snapshot_id
    left join scoring_authority.tournament_setup_round_courses_v1 assignment
      on assignment.tournament_id = match_value.tournament_id
     and assignment.round_number = match_value.round_number
    where match_value.tournament_id = '2026'
      and (
        pg_catalog.jsonb_typeof(snapshot.hole_definitions) <> 'array'
        or pg_catalog.jsonb_array_length(snapshot.hole_definitions) <> 18
        or (select pg_catalog.sum((hole->>'par')::integer)
          from pg_catalog.jsonb_array_elements(snapshot.hole_definitions) hole)
          <> snapshot.par
        or (assignment.round_number is not null and (
          assignment.course_id <> snapshot.course_id
          or assignment.tee_id <> snapshot.tee
        ))
      )
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'COURSE_ROUND_CONTEXT_INVALID', 'section', 'courses',
        'message',
          'A match course, tee, or 18-hole definition does not match its round.'
      )
    );
  end if;
  if exists (
    select 1
    from scoring_authority.matches match_value
    join scoring_authority.tournament_setup_round_details_v1 round_detail
      on round_detail.tournament_id = match_value.tournament_id
     and round_detail.round_number = match_value.round_number
    left join scoring_authority.tournament_setup_match_details_v1 match_detail
      on match_detail.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
      and match_detail.match_id is null
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_MATCH_CONTEXT_REFRESH_REQUIRED',
        'section', 'matches',
        'message',
          'One or more matches need review after the round configuration changed.'
      )
    );
  end if;

  for value in
    select round_value.round_number, round_value.format,
      pg_catalog.count(match_value.match_id)::integer actual_matches,
      case round_value.format when 'SI' then active_roster / 2
        else active_roster / 4 end expected_count
    from scoring_authority.rounds round_value
    left join scoring_authority.matches match_value
      on match_value.tournament_id = round_value.tournament_id
     and match_value.round_number = round_value.round_number
    where round_value.tournament_id = '2026'
      and round_value.round_number in (1, 2, 3)
    group by round_value.round_number, round_value.format
    order by round_value.round_number
  loop
    expected_matches := expected_matches + value.expected_count;
    if value.actual_matches <> value.expected_count then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'ROUND_MATCH_COUNT_INCOMPLETE', 'section', 'matches',
          'target', pg_catalog.format('Round %s', value.round_number),
          'message', pg_catalog.format(
            'Round %s needs %s matches; %s are configured.',
            value.round_number, value.expected_count, value.actual_matches
          ),
          'expectedCount', value.expected_count,
          'actualCount', value.actual_matches
        )
      );
    end if;
  end loop;

  select pg_catalog.count(*)::integer into match_count
  from scoring_authority.matches match_value
  where match_value.tournament_id = '2026';
  if exists (
    select 1
    from scoring_authority.matches match_value
    join scoring_authority.rounds round_value
      on round_value.tournament_id = match_value.tournament_id
     and round_value.round_number = match_value.round_number
    where match_value.tournament_id = '2026'
      and match_value.format <> round_value.format
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'MATCH_ROUND_FORMAT_MISMATCH', 'section', 'matches',
        'message', 'A match format does not match its configured round.'
      )
    );
  end if;
  select pg_catalog.count(*)::integer into started_count
  from scoring_authority.matches match_value
  where match_value.tournament_id = '2026'
    and not production_control.handicap_v1_match_is_unstarted(
      match_value.match_id
    );

  for value in
    select match_value.match_id, match_value.round_number, match_value.format,
      pg_catalog.count(participant.player_id)::integer participant_count,
      pg_catalog.count(distinct participant.player_id)::integer unique_count,
      pg_catalog.count(*) filter (
        where participant.team_side = 1
      )::integer team_1_count,
      pg_catalog.count(*) filter (
        where participant.team_side = 2
      )::integer team_2_count
    from scoring_authority.matches match_value
    left join scoring_authority.match_participants participant
      on participant.match_id = match_value.match_id
    where match_value.tournament_id = '2026'
    group by match_value.match_id, match_value.round_number, match_value.format
    order by match_value.round_number, match_value.match_id
  loop
    if value.participant_count <> (case when value.format = 'SI' then 2 else 4 end)
       or value.unique_count <> value.participant_count
       or value.team_1_count <> (case when value.format = 'SI' then 1 else 2 end)
       or value.team_2_count <> (case when value.format = 'SI' then 1 else 2 end) then
      blockers := blockers || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'MATCH_PAIRINGS_INCOMPLETE', 'section', 'matches',
          'target', value.match_id,
          'message', pg_catalog.format('%s needs complete valid pairings.',
            value.match_id)
        )
      );
    else
      paired_count := paired_count + 1;
    end if;
  end loop;
  if exists (
    select 1
    from scoring_authority.match_participants participant
    join scoring_authority.matches match_value
      on match_value.match_id = participant.match_id
    left join scoring_authority.tournament_players membership
      on membership.tournament_id = match_value.tournament_id
     and membership.player_id = participant.player_id
    where match_value.tournament_id = '2026'
      and (membership.player_id is null
        or membership.participation_status <> 'ACTIVE'
        or membership.team_side <> participant.team_side)
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PAIRING_ROSTER_TEAM_MISMATCH', 'section', 'matches',
        'message', 'One or more pairings do not match the active roster teams.'
      )
    );
  end if;
  if exists (
    select 1
    from scoring_authority.match_participants participant
    join scoring_authority.matches match_value
      on match_value.match_id = participant.match_id
    where match_value.tournament_id = '2026'
    group by match_value.round_number, participant.player_id
    having pg_catalog.count(*) > 1
  ) then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'ROUND_DUPLICATE_PLAYER', 'section', 'matches',
        'message', 'A Player appears more than once in the same round.'
      )
    );
  end if;

  select pg_catalog.count(*)::integer into snapshot_ready_count
  from scoring_authority.matches match_value
  join scoring_authority.scoring_snapshots snapshot
    on snapshot.snapshot_id = match_value.scoring_snapshot_id
   and snapshot.match_id = match_value.match_id
   and snapshot.tournament_id = match_value.tournament_id
  join scoring_authority.handicap_revision_current current_handicap
    on current_handicap.tournament_id = match_value.tournament_id
   and current_handicap.revision_id = snapshot.handicap_revision_id
  left join scoring_authority.tournament_setup_match_details_v1 detail
    on detail.match_id = match_value.match_id
  where match_value.tournament_id = '2026'
    and snapshot.format = match_value.format
    and snapshot.rating is not null
    and snapshot.slope between 55 and 155
    and snapshot.par between 54 and 90
    and pg_catalog.jsonb_typeof(snapshot.hole_definitions) = 'array'
    and pg_catalog.jsonb_array_length(snapshot.hole_definitions) = 18
    and (select pg_catalog.count(*)
      from scoring_authority.match_holes hole
      where hole.match_id = match_value.match_id) = 18
    and (detail.match_id is null or (
      detail.prepared_setup_revision = detail.setup_revision
      and detail.prepared_configuration_fingerprint is not null
    ))
    and not exists (
      select 1 from scoring_authority.match_participants participant
      left join scoring_authority.handicap_revision_entries entry
        on entry.revision_id = current_handicap.revision_id
       and entry.player_id = participant.player_id
      where participant.match_id = match_value.match_id
        and (entry.player_id is null
          or participant.handicap_revision_id
            is distinct from current_handicap.revision_id)
    );
  if snapshot_ready_count <> match_count then
    blockers := blockers || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'SCORING_CONTEXT_INCOMPLETE', 'section', 'matches',
        'message', pg_catalog.format(
          '%s matches need a complete scoring context.',
          match_count - snapshot_ready_count
        ),
        'missingCount', match_count - snapshot_ready_count
      )
    );
  end if;

  begin
    perform production_control.build_production_net_skins_v1_manifest(
      array[1, 2, 3]::integer[]
    );
    net_skins_ready := true;
    net_skins_state := 'READY';
  exception when others then
    net_skins_ready := false;
    net_skins_state := 'NOT_READY';
  end;
  select coalesce(current_value.state, 'NOT_CONFIGURED') into calcutta_state
  from scoring_authority.calcutta_v1_current current_value
  where current_value.tournament_id = '2026';

  return pg_catalog.jsonb_build_object(
    'state', case when pg_catalog.jsonb_array_length(blockers) = 0
      then 'READY' else 'NEEDS_ATTENTION' end,
    'ready', pg_catalog.jsonb_array_length(blockers) = 0,
    'blockers', blockers,
    'messages', coalesce((
      select pg_catalog.jsonb_agg(blocker->>'message')
      from pg_catalog.jsonb_array_elements(blockers) blocker
    ), '[]'::jsonb),
    'summary', pg_catalog.jsonb_build_object(
      'activeRoster', active_roster,
      'handicapCovered', handicap_covered,
      'teams', team_count,
      'rounds', round_count,
      'expectedMatches', expected_matches,
      'matches', match_count,
      'pairedMatches', paired_count,
      'preparedScoringContexts', snapshot_ready_count,
      'startedMatches', started_count
    ),
    'sections', pg_catalog.jsonb_build_object(
      'tournament', production_control.tournament_setup_section_state_v1(
        blockers, 'tournament', operational_value.tournament_id is not null, false
      ),
      'teams', production_control.tournament_setup_section_state_v1(
        blockers, 'teams', team_count > 0, false
      ),
      'roster', production_control.tournament_setup_section_state_v1(
        blockers, 'roster', active_roster > 0, started_count > 0
      ),
      'rounds', production_control.tournament_setup_section_state_v1(
        blockers, 'rounds', round_count > 0, started_count > 0
      ),
      'courses', production_control.tournament_setup_section_state_v1(
        blockers, 'courses', match_count > 0, started_count > 0
      ),
      'matches', production_control.tournament_setup_section_state_v1(
        blockers, 'matches', match_count > 0, started_count > 0
      ),
      'scoringContext', production_control.tournament_setup_section_state_v1(
        blockers, 'matches', snapshot_ready_count > 0, started_count > 0
      )
    ),
    'sideGames', pg_catalog.jsonb_build_object(
      'netSkins', pg_catalog.jsonb_build_object(
        'ready', net_skins_ready, 'state', net_skins_state,
        'derivedFromCanonicalSetup', true
      ),
      'calcutta', pg_catalog.jsonb_build_object(
        'state', coalesce(calcutta_state, 'NOT_CONFIGURED'),
        'optional', true, 'blocksTournamentReadiness', false
      )
    )
  );
end;
$$;


ALTER FUNCTION production_control.tournament_setup_readiness_v1() OWNER TO postgres;

--
-- Name: tournament_setup_revision_v1(text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.tournament_setup_revision_v1(target_tournament text) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
  select coalesce((
    select value.revision
    from production_control.tournament_setup_context_v1 value
    where value.tournament_id = target_tournament
  ), 0)::bigint
$$;


ALTER FUNCTION production_control.tournament_setup_revision_v1(target_tournament text) OWNER TO postgres;

--
-- Name: tournament_setup_section_state_v1(jsonb, text, boolean, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.tournament_setup_section_state_v1(blockers jsonb, section_name text, source_present boolean, locked_state boolean DEFAULT false) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select case
    when locked_state then 'LOCKED'
    when not source_present then 'NOT_STARTED'
    when exists (
      select 1 from pg_catalog.jsonb_array_elements(coalesce(blockers, '[]'::jsonb))
        blocker
      where blocker->>'section' = section_name
    ) then 'NEEDS_ATTENTION'
    else 'COMPLETE'
  end
$$;


ALTER FUNCTION production_control.tournament_setup_section_state_v1(blockers jsonb, section_name text, source_present boolean, locked_state boolean) OWNER TO postgres;

--
-- Name: validate_annual_calcutta_v1_result(text, text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.validate_annual_calcutta_v1_result(target text, target_result_state text, engine_payload jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  current_value scoring_authority.calcutta_v1_current%rowtype;
  auction_value scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  golfer_value jsonb;
  portfolio_value jsonb;
  completed_rounds integer[];
  canonical_completed_rounds integer[];
  expected_entrant_count integer;
  expected_owner_count integer;
begin
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = target;
  select value.* into strict auction_value
  from scoring_authority.calcutta_v1_auction_fact_revisions value
  where value.auction_revision_id = current_value.auction_revision_id
    and value.tournament_id = target;
  if pg_catalog.jsonb_typeof(engine_payload) <> 'object'
     or not (engine_payload ?& array[
       'available', 'year', 'pot', 'completedRounds',
       'tournamentComplete', 'distributedPrizePool',
       'guaranteedDistributed', 'remainingPrizePool',
       'golfers', 'portfolios'
     ])
     or engine_payload->'available' = 'null'::jsonb
     or engine_payload->'year' = 'null'::jsonb
     or engine_payload->'pot' = 'null'::jsonb
     or engine_payload->'tournamentComplete' = 'null'::jsonb
     or pg_catalog.jsonb_typeof(engine_payload->'completedRounds') <> 'array'
     or pg_catalog.jsonb_typeof(engine_payload->'golfers') <> 'array'
     or pg_catalog.jsonb_typeof(engine_payload->'portfolios') <> 'array'
     or coalesce((engine_payload->>'year')::integer, 0) <> target::integer
     or (engine_payload->>'pot')::numeric < 0
     or (engine_payload->>'pot')::numeric <>
       (auction_value.auction_manifest->>'pot')::numeric
     or engine_payload::text ~*
       '"(email|auth_user_id|authUserId|phone|service_role|serviceRole|secret|credential)"[[:space:]]*:'
     or exists (
       select 1 from pg_catalog.jsonb_object_keys(engine_payload) key_value
       where not (key_value = any(array[
         'available', 'year', 'pot', 'distributedPrizePool',
         'guaranteedDistributed', 'remainingPrizePool',
         'completedRounds', 'tournamentComplete', 'golfers', 'portfolios',
         'storylines', 'hero', 'source'
       ]))
     ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_PAYLOAD_INVALID';
  end if;
  begin
    select pg_catalog.array_agg(value::integer order by value::integer)
      into completed_rounds
    from pg_catalog.jsonb_array_elements_text(
      engine_payload->'completedRounds'
    ) value;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_PAYLOAD_INVALID';
  end;
  if coalesce(pg_catalog.array_length(completed_rounds, 1), 0) <>
       coalesce((select pg_catalog.count(distinct value)
         from pg_catalog.unnest(completed_rounds) value), 0)
     or exists (
       select 1 from pg_catalog.unnest(coalesce(
         completed_rounds, '{}'::integer[]
       )) value where value not between 1 and 3
     ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_PAYLOAD_INVALID';
  end if;
  completed_rounds := coalesce(completed_rounds, '{}'::integer[]);
  canonical_completed_rounds :=
    production_control.calcutta_v1_completed_rounds(target);
  if completed_rounds is distinct from canonical_completed_rounds then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_COMPLETED_ROUNDS_CONFLICT';
  end if;
  expected_entrant_count := pg_catalog.jsonb_array_length(
    auction_value.auction_manifest->'purchases'
  );
  for golfer_value in select value from pg_catalog.jsonb_array_elements(
    engine_payload->'golfers'
  ) value loop
    if pg_catalog.jsonb_typeof(golfer_value) <> 'object'
       or pg_catalog.btrim(coalesce(golfer_value->>'playerId', '')) = ''
       or golfer_value#>>'{player,id}' is distinct from
         golfer_value->>'playerId'
       or pg_catalog.btrim(coalesce(
         golfer_value#>>'{player,name}', ''
       )) = ''
       or not exists (
         select 1 from pg_catalog.jsonb_array_elements(
           auction_value.auction_manifest->'purchases'
         ) purchase
         where purchase->>'player_id' = golfer_value->>'playerId'
       ) then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_RESULT_ENTRANT_INVALID';
    end if;
  end loop;
  if pg_catalog.jsonb_array_length(engine_payload->'golfers') <>
       expected_entrant_count
     or (select pg_catalog.count(distinct golfer->>'playerId')
       from pg_catalog.jsonb_array_elements(
         engine_payload->'golfers'
       ) golfer) <> expected_entrant_count then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_ENTRANT_INVALID';
  end if;
  select pg_catalog.count(distinct ownership->>'owner_player_id')
    into expected_owner_count
  from pg_catalog.jsonb_array_elements(
    auction_value.auction_manifest->'ownership'
  ) ownership;
  for portfolio_value in select value
    from pg_catalog.jsonb_array_elements(engine_payload->'portfolios') value
  loop
    if pg_catalog.jsonb_typeof(portfolio_value) <> 'object'
       or pg_catalog.btrim(coalesce(portfolio_value->>'ownerId', '')) = ''
       or portfolio_value#>>'{owner,id}' is distinct from
         portfolio_value->>'ownerId'
       or pg_catalog.btrim(coalesce(
         portfolio_value#>>'{owner,name}', ''
       )) = ''
       or not exists (
         select 1 from pg_catalog.jsonb_array_elements(
           auction_value.auction_manifest->'ownership'
         ) ownership
         where ownership->>'owner_player_id' =
           portfolio_value->>'ownerId'
       ) then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_RESULT_OWNER_INVALID';
    end if;
  end loop;
  if pg_catalog.jsonb_array_length(engine_payload->'portfolios') <>
       expected_owner_count
     or (select pg_catalog.count(distinct portfolio->>'ownerId')
       from pg_catalog.jsonb_array_elements(
         engine_payload->'portfolios'
       ) portfolio) <> expected_owner_count then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_OWNER_INVALID';
  end if;
  if target_result_state = 'OFFICIAL' then
    if coalesce((engine_payload->>'tournamentComplete')::boolean, false)
         is not true or not (3 = any(completed_rounds)) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_CALCUTTA_OFFICIAL_FINALIZATION_REQUIRED';
    end if;
  elsif target_result_state = 'PROVISIONAL' then
    if coalesce((engine_payload->>'tournamentComplete')::boolean, false)
         is true then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_RESULT_STATE_INVALID';
    end if;
  else
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_STATE_INVALID';
  end if;
  perform production_control.project_annual_calcutta_v1_result(
    target, engine_payload
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_PAYLOAD_INVALID';
end;
$$;


ALTER FUNCTION production_control.validate_annual_calcutta_v1_result(target text, target_result_state text, engine_payload jsonb) OWNER TO postgres;

--
-- Name: validate_draft_authoring_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.validate_draft_authoring_v1(target text, proposed_configuration jsonb, proposed_picks jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target_year integer;
  total_value integer;
  team_one text;
  team_two text;
  captain_one text;
  captain_two text;
  first_team text;
  status_value text;
  format_value text;
  date_value text;
  time_value text;
  time_zone_value text;
  canonical_config jsonb;
  normalized_picks jsonb := '[]'::jsonb;
  presentation_picks jsonb := '[]'::jsonb;
  presentation_seed_value jsonb;
  teams_value jsonb;
  issues jsonb := '[]'::jsonb;
  diagnostics jsonb := '[]'::jsonb;
  item jsonb;
  pick_value integer;
  round_value integer;
  within_value integer;
  team_value text;
  source_team_value text;
  player_value text;
  pick_status text;
  expected_team text;
  selected_players text[] := array[]::text[];
  seen_picks integer[] := array[]::integer[];
  player_name_value text;
  team_presentation jsonb;
  player_presentation jsonb;
  selected_at_value text;
  selected_by_value text;
  notes_value text;
begin
  if target !~ '^20[0-9]{2}$'
     or not exists (select 1 from scoring_authority.tournaments value
       where value.tournament_id = target
         and value.tournament_year = target::integer)
     or pg_catalog.jsonb_typeof(proposed_configuration) is distinct from 'object'
     or pg_catalog.jsonb_typeof(proposed_picks) is distinct from 'array' then
    return pg_catalog.jsonb_build_object(
      'pass', false,
      'issues', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'code', 'DRAFT_COMPLETE_PAYLOAD_REQUIRED'
      ))
    );
  end if;
  target_year := target::integer;
  begin
    total_value := (proposed_configuration->>'total_picks')::integer;
  exception when others then total_value := 0;
  end;
  team_one := pg_catalog.upper(pg_catalog.btrim(coalesce(
    proposed_configuration->>'team_1_id', '')));
  team_two := pg_catalog.upper(pg_catalog.btrim(coalesce(
    proposed_configuration->>'team_2_id', '')));
  captain_one := pg_catalog.upper(pg_catalog.btrim(coalesce(
    proposed_configuration->>'team_1_captain_player_id', '')));
  captain_two := pg_catalog.upper(pg_catalog.btrim(coalesce(
    proposed_configuration->>'team_2_captain_player_id', '')));
  first_team := pg_catalog.upper(pg_catalog.btrim(coalesce(
    proposed_configuration->>'first_pick_team_id', '')));
  status_value := pg_catalog.btrim(coalesce(
    proposed_configuration->>'status_mode', ''));
  format_value := pg_catalog.btrim(coalesce(
    proposed_configuration->>'format', ''));
  date_value := pg_catalog.btrim(coalesce(
    proposed_configuration->>'date', ''));
  time_value := pg_catalog.btrim(coalesce(
    proposed_configuration->>'time', ''));
  time_zone_value := pg_catalog.btrim(coalesce(
    proposed_configuration->>'time_zone', ''));

  if coalesce((proposed_configuration->>'year')::integer, 0) <> target_year then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_TOURNAMENT_MISMATCH'));
  end if;
  if total_value < 1 then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_TOTAL_PICKS_INVALID'));
  end if;
  if team_one = '' or team_two = '' or team_one = team_two
     or not exists (select 1 from scoring_authority.teams value
       where value.tournament_id = target and value.team_id = team_one)
     or not exists (select 1 from scoring_authority.teams value
       where value.tournament_id = target and value.team_id = team_two) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_TEAM_INVALID'));
  end if;
  if first_team = '' or first_team not in (team_one, team_two) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_FIRST_PICK_TEAM_INVALID'));
  end if;
  if pg_catalog.upper(status_value) not in (
       'AUTOMATIC','UNSCHEDULED','SCHEDULED','LIVE','COMPLETE'
     ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_STATUS_INVALID'));
  end if;
  if not production_control.draft_date_valid_v1(date_value) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_DATE_INVALID'));
  end if;
  if not production_control.draft_time_valid_v1(time_value) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_TIME_INVALID'));
  end if;
  if not production_control.draft_time_zone_valid_v1(time_zone_value) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_TIME_ZONE_INVALID'));
  end if;
  if captain_one <> '' and not exists (
       select 1 from scoring_authority.tournament_players value
       where value.tournament_id = target and value.player_id = captain_one
         and value.participation_status = 'ACTIVE'
     ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'DRAFT_CAPTAIN_INVALID', 'teamId', team_one));
  end if;
  if captain_two <> '' and not exists (
       select 1 from scoring_authority.tournament_players value
       where value.tournament_id = target and value.player_id = captain_two
         and value.participation_status = 'ACTIVE'
     ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'DRAFT_CAPTAIN_INVALID', 'teamId', team_two));
  end if;
  if captain_one <> '' and captain_one = captain_two then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_CAPTAINS_CONFLICT'));
  end if;
  if pg_catalog.jsonb_array_length(proposed_picks) <> total_value then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code', 'DRAFT_PICK_COUNT_MISMATCH'));
  end if;

  for item in
    select value from pg_catalog.jsonb_array_elements(proposed_picks)
    order by case when value->>'pick_number' ~ '^[0-9]+$'
      then (value->>'pick_number')::integer else 2147483647 end
  loop
    begin
      pick_value := (item->>'pick_number')::integer;
    exception when others then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('code','DRAFT_PICK_NUMBER_INVALID'));
      continue;
    end;
    round_value := ((pick_value - 1) / 2) + 1;
    within_value := pg_catalog.mod(pick_value - 1, 2) + 1;
    if pick_value = any(seen_picks) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code','DRAFT_PICK_NUMBER_DUPLICATE','pickNumber',pick_value));
    elsif pick_value < 1 or pick_value > total_value then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code','DRAFT_PICK_NUMBER_INVALID','pickNumber',pick_value));
    else
      seen_picks := pg_catalog.array_append(seen_picks, pick_value);
    end if;
    team_value := pg_catalog.upper(pg_catalog.btrim(coalesce(
      item->>'team_id', '')));
    source_team_value := team_value;
    player_value := pg_catalog.upper(pg_catalog.btrim(coalesce(
      item->>'player_id', '')));
    pick_status := case when player_value = '' then 'PENDING'
      else 'SELECTED' end;
    selected_at_value := pg_catalog.btrim(coalesce(item->>'selected_at',''));
    selected_by_value := pg_catalog.btrim(coalesce(item->>'selected_by',''));
    notes_value := pg_catalog.btrim(coalesce(item->>'notes',''));
    if pick_status not in ('PENDING','SELECTED')
       or (pick_status = 'PENDING' and player_value <> '')
       or (pick_status = 'SELECTED' and (player_value = '' or team_value = ''))
       or (team_value <> '' and team_value not in (team_one, team_two)) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code','DRAFT_PICK_STATUS_INVALID','pickNumber',pick_value));
    end if;
    if player_value <> '' then
      if player_value in (captain_one,captain_two) then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code','DRAFT_CAPTAIN_PICK_PROHIBITED',
            'pickNumber',pick_value,'playerId',player_value));
      end if;
      if player_value = any(selected_players) then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code','DRAFT_PLAYER_DUPLICATE','pickNumber',pick_value,
            'playerId',player_value));
      else
        selected_players := pg_catalog.array_append(
          selected_players, player_value);
      end if;
      if not exists (
        select 1 from scoring_authority.tournament_players value
        where value.tournament_id = target
          and value.player_id = player_value and value.team_id = team_value
          and value.participation_status = 'ACTIVE'
      ) then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code','DRAFT_PLAYER_TEAM_INVALID','pickNumber',pick_value,
            'playerId',player_value,'teamId',team_value));
      end if;
    end if;
    expected_team := case
      when pg_catalog.mod((pick_value - 1) / 2, 2) = 0 then
        case when pg_catalog.mod(pick_value - 1, 2) = 0
          then first_team
          else case when first_team = team_one then team_two else team_one end
        end
      else case when pg_catalog.mod(pick_value - 1, 2) = 0
          then case when first_team = team_one then team_two else team_one end
          else first_team end
      end;
    if player_value <> '' and pg_catalog.upper(format_value) = 'SNAKE'
       and team_value <> expected_team then
      diagnostics := diagnostics || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'category','DRAFT_SNAKE_TEAM_MISMATCH',
          'pickNumber',pick_value,'expectedTeamId',expected_team,
          'actualTeamId',team_value));
    end if;
    select value.display_name into player_name_value
    from scoring_authority.players value where value.player_id = player_value;
    team_presentation := case when team_value = '' then null else
      production_control.draft_team_presentation_v1(
        target, team_value, case when team_value = team_one
          then captain_one else captain_two end) end;
    player_presentation := case when player_value = '' then null else
      production_control.draft_player_presentation_v1(
        target, player_value) end;
    normalized_picks := normalized_picks || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'pick_number',pick_value,'round_number',round_value,
        'pick_within_round',within_value,
        'source_team_id',source_team_value,'team_id',team_value,
        'player_id',player_value,
        'player_name',coalesce(player_name_value,''),
        'selected_at',selected_at_value,'selected_by',selected_by_value,
        'status',pick_status,'notes',notes_value,
        'presentation',pg_catalog.jsonb_build_object(
          'team',team_presentation,'player',player_presentation)
      ));
    presentation_picks := presentation_picks || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'pickNumber',pick_value,'round',round_value,
        'pickWithinRound',within_value,'sourceTeamId',source_team_value,
        'teamId',team_value,'team',team_presentation,
        'playerId',player_value,'player',player_presentation,
        'selectedAt',selected_at_value,'selectedBy',selected_by_value,
        'status',pick_status,'notes',notes_value
      ));
  end loop;
  if pg_catalog.cardinality(seen_picks) <> total_value
     or exists (select 1 from pg_catalog.generate_series(1,total_value) value
       where not (value = any(seen_picks))) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code','DRAFT_PICK_SEQUENCE_INVALID'));
  end if;
  if pg_catalog.upper(status_value) = 'COMPLETE'
     and pg_catalog.cardinality(selected_players) <> total_value then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('code','DRAFT_COMPLETED_PICK_MISSING'));
  end if;

  canonical_config := pg_catalog.jsonb_build_object(
    'year',target_year,
    'name',coalesce(nullif(pg_catalog.btrim(
      proposed_configuration->>'name'),''), target || ' Sandbagger Draft'),
    'date',pg_catalog.btrim(coalesce(proposed_configuration->>'date','')),
    'time',pg_catalog.btrim(coalesce(proposed_configuration->>'time','')),
    'time_zone',pg_catalog.btrim(coalesce(
      proposed_configuration->>'time_zone','')),
    'location',pg_catalog.btrim(coalesce(
      proposed_configuration->>'location','')),
    'status_mode',status_value,
    'format',format_value,
    'total_picks',total_value,
    'team_1_id',team_one,'team_2_id',team_two,
    'team_1_captain_player_id',captain_one,
    'team_2_captain_player_id',captain_two,
    'first_pick_team_id',first_team,
    'notes',pg_catalog.btrim(coalesce(proposed_configuration->>'notes',''))
  );
  teams_value := pg_catalog.jsonb_build_array(
    production_control.draft_team_presentation_v1(
      target, team_one, captain_one),
    production_control.draft_team_presentation_v1(
      target, team_two, captain_two)
  );
  presentation_seed_value := pg_catalog.jsonb_build_object(
    'year',target_year,'name',canonical_config->>'name',
    'date',canonical_config->>'date','time',canonical_config->>'time',
    'timeZone',canonical_config->>'time_zone',
    'location',canonical_config->>'location',
    'statusMode',canonical_config->>'status_mode',
    'format',canonical_config->>'format',
    'totalDraftPicks',total_value,'firstPickTeamId',first_team,
    'firstPickSourceTeamId',first_team,
    'notes',canonical_config->>'notes','teams',teams_value,
    'picks',presentation_picks
  );
  return pg_catalog.jsonb_build_object(
    'pass',pg_catalog.jsonb_array_length(issues)=0,
    'issues',issues,
    'configuration',canonical_config,
    'picks',normalized_picks,
    'presentationSeed',presentation_seed_value,
    'configurationFingerprint',
      production_control.draft_authoring_hash_v1(canonical_config),
    'picksFingerprint',
      production_control.draft_authoring_hash_v1(normalized_picks),
    'payloadFingerprint',production_control.draft_authoring_hash_v1(
      pg_catalog.jsonb_build_object(
        'configuration',canonical_config,'picks',normalized_picks,
        'presentationSeed',presentation_seed_value
      )),
    'diagnostics',pg_catalog.jsonb_build_object(
      'selectedPicks',pg_catalog.cardinality(selected_players),
      'pendingPicks',total_value-pg_catalog.cardinality(selected_players),
      'corrections',diagnostics)
  );
exception when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'pass',false,
    'issues',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'code','DRAFT_INPUT_INVALID'))
  );
end;
$_$;


ALTER FUNCTION production_control.validate_draft_authoring_v1(target text, proposed_configuration jsonb, proposed_picks jsonb) OWNER TO postgres;

--
-- Name: validate_guide_authoring_v1(text, integer, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.validate_guide_authoring_v1(target text, target_year integer, proposed_authoring jsonb, proposed_projection jsonb, declared_authoring_fingerprint text DEFAULT NULL::text, declared_content_fingerprint text DEFAULT NULL::text, declared_projection_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare result jsonb; issues jsonb := '[]'; spec record; item jsonb; field_name text;
 overview_value jsonb; zone_value text; start_value text; end_value text;
begin
 result := production_control.validate_guide_draft_structure_v1(target,target_year,proposed_authoring,proposed_projection,declared_authoring_fingerprint,declared_content_fingerprint,declared_projection_hash);
 if not coalesce((result->>'pass')::boolean,false) then return result; end if;
 overview_value := proposed_authoring->'tournament';
 for spec in select * from (values
  ('Tournament Name','Name'),('Tournament Edition','Annual'),
  ('Tournament Dates','Dates'),('Destination','Location'),('Time Zone','Timezone')
 ) f(primary_field,alias_field) loop
  if coalesce(nullif(pg_catalog.btrim(overview_value->>spec.primary_field),''),nullif(pg_catalog.btrim(overview_value->>spec.alias_field),''),'')='' then
   issues:=issues||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code','GUIDE_PUBLICATION_INCOMPLETE','source','Tournaments','field',spec.primary_field,'message','Complete '||spec.primary_field||' before publication.'));
  end if;
 end loop;
 zone_value:=coalesce(nullif(pg_catalog.btrim(overview_value->>'Time Zone'),''),nullif(pg_catalog.btrim(overview_value->>'Timezone'),''));
 if zone_value is not null and not exists(select 1 from pg_catalog.pg_timezone_names where name=zone_value) then
  issues:=issues||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code','GUIDE_PUBLICATION_INCOMPLETE','source','Tournaments','field','Time Zone','message','Use a valid tournament timezone.'));
 end if;
 start_value:=nullif(pg_catalog.btrim(overview_value->>'Start Date'),'');
 end_value:=nullif(pg_catalog.btrim(overview_value->>'End Date'),'');
 for field_name in select unnest(array['Start Date','End Date']) loop
  if coalesce(overview_value->>field_name,'')<>'' and not production_control.guide_date_valid_v1(overview_value->>field_name,target_year) then
   issues:=issues||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code','GUIDE_PUBLICATION_INCOMPLETE','source','Tournaments','field',field_name,'message','Use a real date in the tournament year.'));
  end if;
 end loop;
 if (start_value is null) <> (end_value is null) or start_value > end_value then
  issues:=issues||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code','GUIDE_PUBLICATION_INCOMPLETE','source','Tournaments','field','Start Date / End Date','message','Supply both structured dates in chronological order, or leave both blank.'));
 end if;
 for spec in select * from (values
 ('overview',array['Section ID','Section Name','Section Slug','Description','Display Order'],false),
 ('schedule',array['Event ID','Event Date','Day Label','Start Time','Event Type','Title','Display Order'],true),
 ('timelineRows',array['Event Date','Start Time','Title','Sort Order'],false),
 ('ruleBook',array['Rule ID','Category','Title','Body','Display Order'],false),
 ('dining',array['Day','Meal','Location','Sort Order'],false),
 ('localGuide',array['Section','Title','Sort Order'],false),
 ('importantContacts',array['Category','Name','Sort Order'],false),
 ('courses',array['Course ID','Round','Format','Course'],true),
 ('tournamentRules',array['Round','Format','Points Available'],true),
 ('rounds',array['Format ID','Name','Team Size'],true)
 ) s(domain_key,required_fields,requires_content) loop
  if spec.requires_content and (case when pg_catalog.jsonb_typeof(proposed_projection->'content'->spec.domain_key)='array' then pg_catalog.jsonb_array_length(proposed_projection->'content'->spec.domain_key)=0 else true end) then
   issues:=issues||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code','GUIDE_PUBLICATION_INCOMPLETE','source',spec.domain_key,'message',case when spec.domain_key='schedule' then 'Guide Itinerary needs at least one published participant event.' else spec.domain_key||' has no complete published content.' end));
  end if;
  -- Validate every supplied row, including optional domains and private items.
  -- Absent optional content is valid; malformed existing content is not ignored.
  for item in select value from pg_catalog.jsonb_array_elements(proposed_authoring->spec.domain_key) loop
   foreach field_name in array spec.required_fields loop
    if pg_catalog.btrim(coalesce(nullif(item->>field_name,''),case when field_name='Course' then item->>'Course Name' end,''))='' then
     issues:=issues||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code','GUIDE_PUBLICATION_INCOMPLETE','source',spec.domain_key,'field',field_name,'message','Complete '||field_name||' before publication.'));
    end if;
   end loop;
  end loop;
  if spec.domain_key in ('overview','schedule','ruleBook') and pg_catalog.jsonb_typeof(proposed_projection->'content'->spec.domain_key)='array' then
   for item in select value from pg_catalog.jsonb_array_elements(proposed_projection->'content'->spec.domain_key) loop
    if pg_catalog.upper(coalesce(nullif(item->>'Status',''),case when pg_catalog.upper(item->>'Published') in ('TRUE','YES','1') then 'PUBLISHED' end,'')) <> 'PUBLISHED' then
     issues:=issues||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('code','GUIDE_PUBLICATION_INCOMPLETE','source',spec.domain_key,'message','Private item status cannot enter the public projection.'));
    end if;
   end loop;
  end if;
 end loop;
 return result||pg_catalog.jsonb_build_object('pass',pg_catalog.jsonb_array_length(issues)=0,'issues',issues,'diagnostics',(result->'diagnostics')||pg_catalog.jsonb_build_object('validated',pg_catalog.jsonb_array_length(issues)=0,'validationLevel','PUBLICATION','issueCount',pg_catalog.jsonb_array_length(issues)));
end;
$$;


ALTER FUNCTION production_control.validate_guide_authoring_v1(target text, target_year integer, proposed_authoring jsonb, proposed_projection jsonb, declared_authoring_fingerprint text, declared_content_fingerprint text, declared_projection_hash text) OWNER TO postgres;

--
-- Name: validate_guide_draft_structure_v1(text, integer, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.validate_guide_draft_structure_v1(target text, target_year integer, proposed_authoring jsonb, proposed_projection jsonb, declared_authoring_fingerprint text DEFAULT NULL::text, declared_content_fingerprint text DEFAULT NULL::text, declared_projection_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  issues jsonb := '[]'::jsonb;
  content_value jsonb;
  authoring_hash text;
  content_hash text;
  projection_hash text;
  domain_value record;
  item_value record;
  link_value record;
  date_value text;
  time_value text;
  round_text text;
  round_number_value integer;
  course_id_value text;
  status_value text;
begin
  if pg_catalog.jsonb_typeof(proposed_authoring) is distinct from 'object'
     or pg_catalog.jsonb_typeof(proposed_projection) is distinct from 'object'
     or proposed_projection->>'schemaVersion' is distinct from
       'guide-projection-v1'
     or pg_catalog.jsonb_typeof(proposed_projection->'content')
       is distinct from 'object' then
    return pg_catalog.jsonb_build_object(
      'pass', false,
      'issues', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'code', 'GUIDE_PROJECTION_SHAPE_INVALID',
        'message', 'The Guide projection shape is invalid.'))
    );
  end if;
  content_value := proposed_projection->'content';
  authoring_hash := production_control.guide_authoring_hash_v1(
    proposed_authoring);
  content_hash := production_control.guide_authoring_hash_v1(content_value);
  projection_hash := production_control.guide_authoring_hash_v1(
    proposed_projection);

  if pg_catalog.octet_length(proposed_authoring::text) > 1500000
     or pg_catalog.octet_length(proposed_projection::text) > 1500000 then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_CONTENT_TOO_LARGE',
        'message', 'The Guide exceeds the bounded authoring size.'));
  end if;
  if exists (select 1
    from production_control.guide_scalar_values_v1(proposed_authoring) value
    where pg_catalog.length(value) > 20000) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_CONTENT_TOO_LARGE',
        'message', 'A Guide field exceeds the bounded text size.'));
  end if;
  if declared_authoring_fingerprint is not null
     and pg_catalog.lower(declared_authoring_fingerprint) <> authoring_hash then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_AUTHORING_FINGERPRINT_MISMATCH',
        'message', 'The Guide authoring fingerprint did not match.'));
  end if;
  if declared_content_fingerprint is not null
     and pg_catalog.lower(declared_content_fingerprint) <> content_hash then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_CONTENT_FINGERPRINT_MISMATCH',
        'message', 'The Guide content fingerprint did not match.'));
  end if;
  if declared_projection_hash is not null
     and pg_catalog.lower(declared_projection_hash) <> projection_hash then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_PROJECTION_FINGERPRINT_MISMATCH',
        'message', 'The Guide projection fingerprint did not match.'));
  end if;

  if exists (
    select 1 from pg_catalog.jsonb_object_keys(proposed_authoring) key_value
    where key_value not in (
      'tournament','overview','schedule','timelineRows','ruleBook',
      'tournamentRules','rounds','dining','localGuide',
      'importantContacts','courses'
    )
  ) or exists (
    select 1 from pg_catalog.jsonb_object_keys(content_value) key_value
    where key_value not in (
      'tournament','tournamentIdentity','overview','schedule','timelineRows',
      'courses','ruleBook','tournamentRules','rounds','dining','localGuide',
      'importantContacts','headers'
    )
  ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_DOMAIN_NOT_ALLOWLISTED',
        'message', 'Only the certified Tournament Guide domains are allowed.'));
  end if;

  if pg_catalog.jsonb_typeof(proposed_authoring->'tournament')
       is distinct from 'object'
     or content_value#>>'{tournamentIdentity,id}' is distinct from target
     or coalesce(content_value#>>'{tournamentIdentity,year}', '')
       is distinct from target_year::text then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_TOURNAMENT_SCOPE_MISMATCH',
        'message', 'Guide content must match the selected tournament and year.'));
  end if;

  for domain_value in
    select key_value, proposed_authoring->key_value value
    from pg_catalog.unnest(array[
      'overview','schedule','timelineRows','ruleBook','tournamentRules',
      'rounds','dining','localGuide','importantContacts','courses'
    ]) key_value
  loop
    if pg_catalog.jsonb_typeof(domain_value.value) is distinct from 'array' then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_DOMAIN_SHAPE_INVALID',
          'domain', domain_value.key_value,
          'message', 'A Guide collection was not an array.'));
    elsif pg_catalog.jsonb_array_length(domain_value.value) > 500 then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_COLLECTION_TOO_LARGE',
          'domain', domain_value.key_value,
          'message', 'A Guide collection exceeds 500 items.'));
    elsif exists (
      select 1 from pg_catalog.jsonb_array_elements(domain_value.value) item
      where pg_catalog.jsonb_typeof(item) <> 'object'
        or pg_catalog.btrim(coalesce(item->>'itemId', '')) = ''
        or pg_catalog.length(item->>'itemId') > 160
        or item->>'itemId' !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,159}$'
    ) or exists (
      select 1
      from pg_catalog.jsonb_array_elements(domain_value.value) item
      group by pg_catalog.lower(pg_catalog.btrim(item->>'itemId'))
      having pg_catalog.count(*) > 1
    ) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_STABLE_ITEM_ID_INVALID',
          'domain', domain_value.key_value,
          'message', 'Each Guide item needs a unique stable item ID.'));
    end if;
  end loop;

  -- Hidden authoring IDs must never cross the participant projection boundary.
  if proposed_projection::text ~ '"itemId"[[:space:]]*:' then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_INTERNAL_ID_PROJECTED',
        'message', 'Internal Guide item IDs are not participant content.'));
  end if;

  -- Explicit stable source IDs retain their certified duplicate semantics.
  for domain_value in
    select * from (values
      ('overview','Section ID'),
      ('schedule','Event ID'),
      ('ruleBook','Rule ID'),
      ('rounds','Format ID')
    ) pair(domain_key, identity_key)
  loop
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        proposed_authoring->domain_value.domain_key) item
      group by pg_catalog.lower(pg_catalog.btrim(
        item->>domain_value.identity_key))
      having pg_catalog.btrim(min(item->>domain_value.identity_key)) = ''
        or pg_catalog.count(*) > 1
    ) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_STABLE_ID_DUPLICATE',
          'domain', domain_value.domain_key,
          'message', 'A certified Guide stable ID is missing or duplicated.'));
    end if;
  end loop;

  if exists (
    select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'overview') item
    group by pg_catalog.lower(pg_catalog.btrim(item->>'Section Slug'))
    having pg_catalog.btrim(min(item->>'Section Slug')) = ''
      or pg_catalog.count(*) > 1
  ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_SECTION_SLUG_DUPLICATE',
        'message', 'Guide section slugs must be present and unique.'));
  end if;

  -- Preserve the established composite duplicate keys alongside hidden IDs.
  if exists (select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'timelineRows') item
      group by pg_catalog.lower(pg_catalog.concat_ws(':', item->>'Event Date',
        item->>'Start Time', item->>'Title')) having pg_catalog.count(*) > 1)
    or exists (select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'tournamentRules') item
      group by pg_catalog.lower(pg_catalog.concat_ws(':', item->>'Round',
        item->>'Format')) having pg_catalog.count(*) > 1)
    or exists (select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'dining') item
      group by pg_catalog.lower(pg_catalog.concat_ws(':', item->>'Day',
        item->>'Meal')) having pg_catalog.count(*) > 1)
    or exists (select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'localGuide') item
      group by pg_catalog.lower(pg_catalog.concat_ws(':', item->>'Section',
        item->>'Title')) having pg_catalog.count(*) > 1)
    or exists (select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'importantContacts') item
      group by pg_catalog.lower(pg_catalog.concat_ws(':', item->>'Category',
        item->>'Name')) having pg_catalog.count(*) > 1)
    or exists (select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'courses') item
      group by pg_catalog.lower(pg_catalog.concat_ws(':', item->>'Course ID',
        item->>'Round')) having pg_catalog.count(*) > 1) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_LOGICAL_KEY_DUPLICATE',
        'message', 'A Guide logical item key is duplicated.'));
  end if;

  -- Publication status exists only for Sections, Itinerary, and Rule Book.
  for item_value in
    select item from pg_catalog.jsonb_array_elements(
      proposed_authoring->'overview') item
    union all select item from pg_catalog.jsonb_array_elements(
      proposed_authoring->'schedule') item
    union all select item from pg_catalog.jsonb_array_elements(
      proposed_authoring->'ruleBook') item
  loop
    status_value := pg_catalog.upper(pg_catalog.btrim(coalesce(
      item_value.item->>'Status', '')));
    if status_value <> '' and status_value not in (
      'PUBLISHED','DRAFT','UNPUBLISHED','CANCELLED','ARCHIVED'
    ) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_STATUS_INVALID',
          'message', 'An item uses an unsupported publication status.'));
    end if;
  end loop;

  for item_value in
    select item, 'Display Order' order_key from pg_catalog.jsonb_array_elements(
      proposed_authoring->'overview') item
    union all select item, 'Display Order' from pg_catalog.jsonb_array_elements(
      proposed_authoring->'schedule') item
    union all select item, 'Sort Order' from pg_catalog.jsonb_array_elements(
      proposed_authoring->'timelineRows') item
    union all select item, 'Display Order' from pg_catalog.jsonb_array_elements(
      proposed_authoring->'ruleBook') item
    union all select item, 'Sort Order' from pg_catalog.jsonb_array_elements(
      proposed_authoring->'dining') item
    union all select item, 'Sort Order' from pg_catalog.jsonb_array_elements(
      proposed_authoring->'localGuide') item
    union all select item, 'Sort Order' from pg_catalog.jsonb_array_elements(
      proposed_authoring->'importantContacts') item
  loop
    if pg_catalog.btrim(coalesce(item_value.item->>item_value.order_key, '')) = ''
       or item_value.item->>item_value.order_key !~ '^[0-9]+(?:\.[0-9]+)?$' then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_ORDER_INVALID',
          'message', 'Guide display and sort orders must be non-negative numbers.'));
    end if;
  end loop;

  for domain_value in select * from (values
    ('overview','Display Order'),('schedule','Display Order'),
    ('timelineRows','Sort Order'),('ruleBook','Display Order'),
    ('dining','Sort Order'),('localGuide','Sort Order'),('importantContacts','Sort Order')
  ) orders(key,order_key) loop
    if exists (select 1 from pg_catalog.jsonb_array_elements(proposed_authoring->domain_value.key) item
      group by case when item->>domain_value.order_key ~ '^[0-9]+(?:\.[0-9]+)?$' then (item->>domain_value.order_key)::numeric end
      having count(*)>1) then
      issues:=issues||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'code','GUIDE_ORDER_DUPLICATE','source',domain_value.key,'field',domain_value.order_key,
        'message','Use a distinct order for each item.'));
    end if;
  end loop;

  -- All stored content is plain/safe presentation material. React escaping is
  -- defense in depth, not the authoring sanitizer.
  if proposed_authoring::text ~* '<[[:space:]]*/?[[:space:]]*(script|style|iframe|object|embed|svg)'
     or proposed_authoring::text ~* 'on[a-z]+[[:space:]]*='
     or proposed_authoring::text ~* '(javascript|vbscript)[[:space:]]*:'
     or proposed_authoring::text ~* 'data[[:space:]]*:[[:space:]]*text/html' then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_UNSAFE_CONTENT',
        'message', 'Unsafe markup or a script-capable URL was rejected.'));
  end if;

  for link_value in
    select 'Website' key_value, item->>'Website' value, false asset
      from pg_catalog.jsonb_array_elements(proposed_authoring->'localGuide') item
    union all select 'Website', item->>'Website', false
      from pg_catalog.jsonb_array_elements(proposed_authoring->'importantContacts') item
    union all select 'Website', item->>'Website', false
      from pg_catalog.jsonb_array_elements(proposed_authoring->'courses') item
    union all select 'GPS Link', item->>'GPS Link', false
      from pg_catalog.jsonb_array_elements(proposed_authoring->'courses') item
    union all select 'Course Logo', item->>'Course Logo', true
      from pg_catalog.jsonb_array_elements(proposed_authoring->'courses') item
    union all select 'Course Profile Image', item->>'Course Profile Image', true
      from pg_catalog.jsonb_array_elements(proposed_authoring->'courses') item
    union all select 'Annual Image', proposed_authoring#>>'{tournament,Annual Image}', true
    union all select 'Hero Image', proposed_authoring#>>'{tournament,Hero Image}', true
    union all select 'Mobile Hero Image', proposed_authoring#>>'{tournament,Mobile Hero Image}', true
  loop
    if not production_control.guide_url_valid_v1(
      coalesce(link_value.value, ''), link_value.asset) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_URL_INVALID',
          'field', link_value.key_value,
          'message', 'A Guide URL or asset reference is invalid.'));
    end if;
  end loop;

  if exists (
    select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'importantContacts') item
    where pg_catalog.btrim(coalesce(item->>'Email', '')) <> ''
      and item->>'Email' !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_EMAIL_INVALID',
        'message', 'An Important Contact email address is invalid.'));
  end if;
  if exists (
    select 1 from (
      select item->>'Phone' phone from pg_catalog.jsonb_array_elements(
        proposed_authoring->'importantContacts') item
      union all select item->>'Phone' from pg_catalog.jsonb_array_elements(
        proposed_authoring->'localGuide') item
    ) phone_value
    where pg_catalog.btrim(coalesce(phone_value.phone, '')) <> ''
      and pg_catalog.length(pg_catalog.regexp_replace(
        phone_value.phone, '[^0-9]', '', 'g')) not between 7 and 15
  ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_PHONE_INVALID',
        'message', 'A Guide phone number is invalid.'));
  end if;
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'importantContacts') item
    where pg_catalog.upper(pg_catalog.btrim(coalesce(
        item->>'Visibility', item->>'Audience', ''))) in (
          'DIRECTOR','DIRECTORS','ADMIN','PRIVATE','INTERNAL'
        )
       or pg_catalog.lower(pg_catalog.btrim(coalesce(
         item->>'Sensitive', ''))) in ('true','yes','1')
  ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_CONTACT_NOT_PARTICIPANT_SAFE',
        'message', 'Private or Director-only contacts cannot enter the Guide.'));
  end if;

  for item_value in
    select item from pg_catalog.jsonb_array_elements(
      proposed_authoring->'schedule') item
    union all select item from pg_catalog.jsonb_array_elements(
      proposed_authoring->'timelineRows') item
  loop
    date_value := coalesce(item_value.item->>'Event Date', '');
    if date_value <> '' and not production_control.guide_date_valid_v1(date_value, target_year) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_DATE_INVALID',
          'message', 'A Guide event date is invalid for the selected year.'));
    end if;
    time_value := coalesce(item_value.item->>'Start Time', '');
    if not production_control.guide_time_valid_v1(time_value)
       or not production_control.guide_time_valid_v1(coalesce(
         item_value.item->>'End Time', '')) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_TIME_INVALID',
          'message', 'A Guide event time is invalid.'));
    end if;
  end loop;
  for item_value in
    select item from pg_catalog.jsonb_array_elements(
      proposed_authoring->'dining') item
  loop
    if not production_control.guide_time_valid_v1(coalesce(
         item_value.item->>'Start Time', ''))
       or not production_control.guide_time_valid_v1(coalesce(
         item_value.item->>'End Time', '')) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_TIME_INVALID',
          'message', 'A dining time is invalid.'));
    end if;
  end loop;

  -- Guide references validate canonical assignments; they never modify them.
  for item_value in
    select item from pg_catalog.jsonb_array_elements(
      proposed_authoring->'schedule') item
  loop
    round_text := pg_catalog.btrim(coalesce(item_value.item->>'Round ID', ''));
    if round_text <> '' then
      begin
        round_number_value := pg_catalog.regexp_replace(
          round_text, '[^0-9]', '', 'g')::integer;
      exception when others then
        round_number_value := null;
      end;
      if round_number_value is null or not exists (
        select 1 from scoring_authority.rounds round_value
        where round_value.tournament_id = target
          and round_value.round_number = round_number_value
      ) then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'GUIDE_ROUND_REFERENCE_INVALID',
            'message', 'An itinerary Round reference does not resolve.'));
      end if;
    end if;
    course_id_value := pg_catalog.btrim(coalesce(
      item_value.item->>'Course ID', ''));
    if course_id_value <> '' and not exists (
      select 1 from scoring_authority.tournament_setup_round_courses_v1 value
      where value.tournament_id = target
        and pg_catalog.upper(value.course_id) =
          pg_catalog.upper(course_id_value)
    ) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_COURSE_REFERENCE_INVALID',
          'message', 'An itinerary Course reference does not resolve.'));
    end if;
  end loop;

  for item_value in
    select item from pg_catalog.jsonb_array_elements(
      proposed_authoring->'courses') item
  loop
    course_id_value := pg_catalog.btrim(coalesce(
      item_value.item->>'Course ID', ''));
    begin
      round_number_value := pg_catalog.regexp_replace(coalesce(
        item_value.item->>'Round', ''), '[^0-9]', '', 'g')::integer;
    exception when others then
      round_number_value := null;
    end;
    if course_id_value = '' or round_number_value is null or not exists (
      select 1
      from scoring_authority.tournament_setup_round_courses_v1 assignment
      where assignment.tournament_id = target
        and assignment.round_number = round_number_value
        and pg_catalog.upper(assignment.course_id) =
          pg_catalog.upper(course_id_value)
    ) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_COURSE_REFERENCE_INVALID',
          'message', 'A Course presentation row does not match Tournament Setup.'));
    elsif exists (
      select 1
      from scoring_authority.tournament_setup_round_courses_v1 assignment
      join scoring_authority.tournament_setup_course_tees_v1 tee
        on tee.tournament_id = assignment.tournament_id
       and tee.course_id = assignment.course_id
       and tee.tee_id = assignment.tee_id
      join scoring_authority.rounds round_value
        on round_value.tournament_id = assignment.tournament_id
       and round_value.round_number = assignment.round_number
      where assignment.tournament_id = target
        and assignment.round_number = round_number_value
        and pg_catalog.upper(assignment.course_id) =
          pg_catalog.upper(course_id_value)
        and (
          (pg_catalog.btrim(coalesce(item_value.item->>'Format', '')) <> ''
            and pg_catalog.upper(item_value.item->>'Format') <>
              pg_catalog.upper(round_value.format))
          or (pg_catalog.btrim(coalesce(
                item_value.item->>'Tee Played', item_value.item->>'Tee', '')) <> ''
            and pg_catalog.upper(coalesce(
              item_value.item->>'Tee Played', item_value.item->>'Tee')) <>
              pg_catalog.upper(assignment.tee_id))
          or (pg_catalog.btrim(coalesce(item_value.item->>'Slope', '')) <> ''
            and item_value.item->>'Slope' ~ '^[0-9]+$'
            and (item_value.item->>'Slope')::integer <> tee.slope)
          or (pg_catalog.btrim(coalesce(item_value.item->>'Par', '')) <> ''
            and item_value.item->>'Par' ~ '^[0-9]+$'
            and (item_value.item->>'Par')::integer <> tee.par)
        )
    ) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'GUIDE_SCORING_FACT_CONFLICT',
          'message', 'Guide presentation conflicts with canonical scoring facts.'));
    end if;
  end loop;

  if exists (
    select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'tournamentRules') item
    where not exists (
      select 1 from scoring_authority.rounds round_value
      where round_value.tournament_id = target
        and round_value.round_number = pg_catalog.regexp_replace(
          coalesce(item->>'Round', ''), '[^0-9]', '', 'g')::integer
        and pg_catalog.upper(round_value.format) =
          pg_catalog.upper(pg_catalog.btrim(coalesce(item->>'Format', '')))
    )
  ) or exists (
    select 1 from pg_catalog.jsonb_array_elements(
      proposed_authoring->'rounds') item
    where not exists (
      select 1 from scoring_authority.rounds round_value
      where round_value.tournament_id = target
        and pg_catalog.upper(round_value.format) =
          pg_catalog.upper(pg_catalog.btrim(item->>'Format ID'))
    )
  ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'GUIDE_RULE_SCORING_CONFLICT',
        'message', 'Guide rule presentation conflicts with canonical rounds.'));
  end if;

  return pg_catalog.jsonb_build_object(
    'pass', pg_catalog.jsonb_array_length(issues) = 0,
    'issues', issues,
    'diagnostics', pg_catalog.jsonb_build_object(
      'validated', false,
      'structurallyValid', pg_catalog.jsonb_array_length(issues) = 0,
      'validationLevel', 'DRAFT',
      'issueCount', pg_catalog.jsonb_array_length(issues),
      'sourceTabs', production_control.guide_authoring_source_tabs_v1(),
      'domainCount', 11,
      'authoringItemCount',
        (select coalesce(pg_catalog.sum(pg_catalog.jsonb_array_length(
          proposed_authoring->key_value)), 0)::integer
         from pg_catalog.unnest(array[
           'overview','schedule','timelineRows','ruleBook','tournamentRules',
           'rounds','dining','localGuide','importantContacts','courses'
         ]) key_value)
    ),
    'authoringContent', proposed_authoring,
    'projectionPayload', proposed_projection,
    'authoringContentFingerprint', authoring_hash,
    'contentFingerprint', content_hash,
    'projectionPayloadHash', projection_hash
  );
exception when invalid_text_representation or numeric_value_out_of_range
  or division_by_zero then
  return pg_catalog.jsonb_build_object(
    'pass', false,
    'issues', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'code', 'GUIDE_FIELD_VALUE_INVALID',
      'message', 'A Guide field value could not be validated.'))
  );
end;
$_$;


ALTER FUNCTION production_control.validate_guide_draft_structure_v1(target text, target_year integer, proposed_authoring jsonb, proposed_projection jsonb, declared_authoring_fingerprint text, declared_content_fingerprint text, declared_projection_hash text) OWNER TO postgres;

--
-- Name: validate_handicap_revision_v1(uuid, bigint); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.validate_handicap_revision_v1(target_revision_id uuid, expected_predecessor bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  revision scoring_authority.handicap_revisions%rowtype;
  current_revision bigint := 0;
  active_count integer;
  entry_count integer;
  changed_players jsonb := '[]'::jsonb;
  unstarted_matches jsonb := '[]'::jsonb;
  started_matches jsonb := '[]'::jsonb;
  context_issues jsonb := '[]'::jsonb;
  issues jsonb := '[]'::jsonb;
  changed_count integer := 0;
  current_roster_hash text;
  actual_fingerprint text;
begin
  select value.* into revision
  from scoring_authority.handicap_revisions value
  where value.revision_id = target_revision_id
    and value.tournament_id = '2026';
  if not found then
    return pg_catalog.jsonb_build_object(
      'valid', false, 'code', 'HANDICAP_REVISION_NOT_FOUND',
      'changed_players', '[]'::jsonb,
      'unstarted_matches', '[]'::jsonb,
      'started_frozen_matches', '[]'::jsonb,
      'issues', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'code', 'HANDICAP_REVISION_NOT_FOUND',
        'message', 'The staged handicap revision does not exist.'
      )),
      'summary', pg_catalog.jsonb_build_object(
        'active_roster_count', 0, 'entry_count', 0,
        'changed_player_count', 0, 'unstarted_refresh_count', 0,
        'started_preserved_count', 0
      )
    );
  end if;

  select coalesce(value.revision_number, 0)
    into current_revision
  from scoring_authority.handicap_revision_current pointer
  join scoring_authority.handicap_revisions value
    on value.revision_id = pointer.revision_id
  where pointer.tournament_id = '2026';
  current_revision := coalesce(current_revision, 0);
  select pg_catalog.count(*) into active_count
  from scoring_authority.tournament_players value
  where value.tournament_id = '2026'
    and value.participation_status = 'ACTIVE';
  select pg_catalog.count(*) into entry_count
  from scoring_authority.handicap_revision_entries value
  where value.revision_id = target_revision_id;
  current_roster_hash :=
    production_control.handicap_v1_roster_fingerprint('2026');
  actual_fingerprint :=
    production_control.handicap_v1_revision_fingerprint(target_revision_id);

  if revision.status <> 'DRAFT' then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'HANDICAP_REVISION_NOT_DRAFT',
        'message', 'Only a draft handicap revision can be approved.'
      )
    );
  end if;
  if revision.predecessor_revision <> expected_predecessor
     or current_revision <> expected_predecessor then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'HANDICAP_PREDECESSOR_STALE',
        'message', 'The approved handicap predecessor changed.',
        'expected_predecessor_revision', expected_predecessor,
        'staged_predecessor_revision', revision.predecessor_revision,
        'current_revision', current_revision
      )
    );
  end if;
  if revision.roster_fingerprint <> current_roster_hash
     or active_count <> entry_count
     or exists (
       select 1
       from scoring_authority.tournament_players roster
       left join scoring_authority.handicap_revision_entries entry
         on entry.revision_id = target_revision_id
        and entry.tournament_id = roster.tournament_id
        and entry.player_id = roster.player_id
       where roster.tournament_id = '2026'
         and roster.participation_status = 'ACTIVE'
         and entry.player_id is null
     )
     or exists (
       select 1
       from scoring_authority.handicap_revision_entries entry
       left join scoring_authority.tournament_players roster
         on roster.tournament_id = entry.tournament_id
        and roster.player_id = entry.player_id
        and roster.participation_status = 'ACTIVE'
       where entry.revision_id = target_revision_id
         and roster.player_id is null
     ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'HANDICAP_ROSTER_CHANGED',
        'message', 'The active tournament roster no longer matches the draft.',
        'active_roster_count', active_count,
        'entry_count', entry_count
      )
    );
  end if;
  if actual_fingerprint is distinct from revision.canonical_fingerprint then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'HANDICAP_REVISION_FINGERPRINT_MISMATCH',
        'message', 'The immutable staged payload fingerprint does not match.'
      )
    );
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'player_id', entry.player_id,
      'display_name', player.display_name,
      'old_handicap', roster.tournament_handicap::text,
      'new_handicap', entry.tournament_handicap::text,
      'change', case
        when roster.tournament_handicap is null then null
        else (entry.tournament_handicap - roster.tournament_handicap)::text
      end
    ) order by player.display_name, entry.player_id
  ), '[]'::jsonb), pg_catalog.count(*)
  into changed_players, changed_count
  from scoring_authority.handicap_revision_entries entry
  join scoring_authority.tournament_players roster
    on roster.tournament_id = entry.tournament_id
   and roster.player_id = entry.player_id
  join scoring_authority.players player on player.player_id = entry.player_id
  where entry.revision_id = target_revision_id
    and roster.tournament_handicap is distinct from entry.tournament_handicap;

  if changed_count = 0 then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'HANDICAP_NO_CHANGES',
        'message',
          'The staged roster is identical to the approved handicap revision.'
      )
    );
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'match_id', match_value.match_id,
      'round_number', match_value.round_number,
      'format', match_value.format,
      'status', match_value.status,
      'scoring_locked', match_value.scoring_locked,
      'unresolved_mutations', match_value.unresolved_mutations,
      'affected_player_ids', (
        select pg_catalog.jsonb_agg(participant.player_id order by participant.player_id)
        from scoring_authority.match_participants participant
        join scoring_authority.handicap_revision_entries entry
          on entry.revision_id = target_revision_id
         and entry.player_id = participant.player_id
        join scoring_authority.tournament_players roster
          on roster.tournament_id = '2026'
         and roster.player_id = entry.player_id
        where participant.match_id = match_value.match_id
          and roster.tournament_handicap is distinct from entry.tournament_handicap
      ),
      'refresh_allowed', true
    ) order by match_value.round_number, match_value.match_id
  ), '[]'::jsonb) into unstarted_matches
  from scoring_authority.matches match_value
  where match_value.tournament_id = '2026'
    and production_control.handicap_v1_match_is_unstarted(
      match_value.match_id
    )
    and exists (
      select 1
      from scoring_authority.match_participants participant
      join scoring_authority.handicap_revision_entries entry
        on entry.revision_id = target_revision_id
       and entry.player_id = participant.player_id
      join scoring_authority.tournament_players roster
        on roster.tournament_id = '2026'
       and roster.player_id = entry.player_id
      where participant.match_id = match_value.match_id
        and roster.tournament_handicap is distinct from entry.tournament_handicap
    );

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'match_id', match_value.match_id,
      'round_number', match_value.round_number,
      'format', match_value.format,
      'status', match_value.status,
      'scoring_locked', match_value.scoring_locked,
      'scored_holes', match_value.scored_holes,
      'current_hole', match_value.current_hole,
      'unresolved_mutations', match_value.unresolved_mutations,
      'running_result', match_value.running_result,
      'clinched', match_value.clinched,
      'snapshot_preserved', true,
      'preservation_reason', case
        when match_value.scoring_locked then 'MATCH_SCORING_LOCKED'
        when match_value.unresolved_mutations <> 0
          then 'MATCH_HAS_UNRESOLVED_MUTATIONS'
        when match_value.status <> 'UPCOMING' then 'MATCH_STARTED'
        else 'MATCH_CONTEXT_FROZEN' end,
      'affected_player_ids', (
        select pg_catalog.jsonb_agg(participant.player_id order by participant.player_id)
        from scoring_authority.match_participants participant
        join scoring_authority.handicap_revision_entries entry
          on entry.revision_id = target_revision_id
         and entry.player_id = participant.player_id
        join scoring_authority.tournament_players roster
          on roster.tournament_id = '2026'
         and roster.player_id = entry.player_id
        where participant.match_id = match_value.match_id
          and roster.tournament_handicap is distinct from entry.tournament_handicap
      )
    ) order by match_value.round_number, match_value.match_id
  ), '[]'::jsonb) into started_matches
  from scoring_authority.matches match_value
  where match_value.tournament_id = '2026'
    and not production_control.handicap_v1_match_is_unstarted(
      match_value.match_id
    )
    and exists (
      select 1
      from scoring_authority.match_participants participant
      join scoring_authority.handicap_revision_entries entry
        on entry.revision_id = target_revision_id
       and entry.player_id = participant.player_id
      join scoring_authority.tournament_players roster
        on roster.tournament_id = '2026'
       and roster.player_id = entry.player_id
      where participant.match_id = match_value.match_id
        and roster.tournament_handicap is distinct from entry.tournament_handicap
    );

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'code', 'HANDICAP_MATCH_CONTEXT_INCOMPLETE',
      'message', 'An unstarted match lacks complete certified handicap context.',
      'match_id', candidate.match_id
    ) order by candidate.match_id
  ), '[]'::jsonb) into context_issues
  from (
    select match_value.match_id
    from scoring_authority.matches match_value
    left join scoring_authority.scoring_snapshots snapshot
      on snapshot.snapshot_id = match_value.scoring_snapshot_id
     and snapshot.match_id = match_value.match_id
     and snapshot.tournament_id = match_value.tournament_id
    where match_value.tournament_id = '2026'
      and production_control.handicap_v1_match_is_unstarted(
        match_value.match_id
      )
      and exists (
        select 1
        from scoring_authority.match_participants affected
        join scoring_authority.handicap_revision_entries entry
          on entry.revision_id = target_revision_id
         and entry.player_id = affected.player_id
        join scoring_authority.tournament_players roster
          on roster.tournament_id = '2026'
         and roster.player_id = entry.player_id
        where affected.match_id = match_value.match_id
          and roster.tournament_handicap is distinct from entry.tournament_handicap
      )
      and (
        snapshot.snapshot_id is null
        or snapshot.rating is null
        or snapshot.slope is null
        or snapshot.slope <= 0
        or snapshot.par is null
        or snapshot.format is distinct from match_value.format
        or match_value.format not in ('BB', 'SC', 'SI')
        or (select pg_catalog.count(*)
            from scoring_authority.match_participants participant
            where participant.match_id = match_value.match_id)
          <> case when match_value.format = 'SI' then 2 else 4 end
        or exists (
          select 1
          from pg_catalog.generate_series(1, 2) side(team_side)
          where (select pg_catalog.count(*)
            from scoring_authority.match_participants participant
            where participant.match_id = match_value.match_id
              and participant.team_side = side.team_side)
            <> case when match_value.format = 'SI' then 1 else 2 end
        )
        or exists (
          select 1
          from scoring_authority.match_participants participant
          left join scoring_authority.handicap_revision_entries entry
            on entry.revision_id = target_revision_id
           and entry.player_id = participant.player_id
          left join scoring_authority.tournament_players roster
            on roster.tournament_id = '2026'
           and roster.player_id = participant.player_id
           and roster.participation_status = 'ACTIVE'
          where participant.match_id = match_value.match_id
            and (entry.player_id is null or roster.player_id is null)
        )
      )
  ) candidate;
  issues := issues || context_issues;

  return pg_catalog.jsonb_build_object(
    'valid', pg_catalog.jsonb_array_length(issues) = 0,
    'code', case when pg_catalog.jsonb_array_length(issues) = 0
      then 'HANDICAP_REVISION_VALID'
      when issues @> '[{"code":"HANDICAP_PREDECESSOR_STALE"}]'::jsonb
        then 'HANDICAP_PREDECESSOR_STALE'
      when issues @> '[{"code":"HANDICAP_ROSTER_CHANGED"}]'::jsonb
        then 'HANDICAP_ROSTER_CHANGED'
      when issues @> '[{"code":"HANDICAP_NO_CHANGES"}]'::jsonb
        then 'HANDICAP_NO_CHANGES'
      else 'HANDICAP_CORRECTION_REQUIRED' end,
    'revision_id', revision.revision_id,
    'revision_number', revision.revision_number,
    'status', revision.status,
    'expected_predecessor_revision', expected_predecessor,
    'current_revision', current_revision,
    'canonical_fingerprint', revision.canonical_fingerprint,
    'changed_players', changed_players,
    'unstarted_matches', unstarted_matches,
    'started_frozen_matches', started_matches,
    'issues', issues,
    'summary', pg_catalog.jsonb_build_object(
      'active_roster_count', active_count,
      'entry_count', entry_count,
      'changed_player_count', changed_count,
      'unstarted_refresh_count', pg_catalog.jsonb_array_length(unstarted_matches),
      'started_preserved_count', pg_catalog.jsonb_array_length(started_matches)
    )
  );
end;
$$;


ALTER FUNCTION production_control.validate_handicap_revision_v1(target_revision_id uuid, expected_predecessor bigint) OWNER TO postgres;

--
-- Name: validate_prediction_settings_v1(jsonb, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.validate_prediction_settings_v1(proposed jsonb, predecessor jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  definition production_control.prediction_setting_definitions_v1%rowtype;
  setting_value jsonb;
  issues jsonb := '[]'::jsonb;
  effective jsonb;
  defaults jsonb;
  rows_value jsonb;
  changed jsonb;
  legacy_profile boolean := false;
begin
  if pg_catalog.jsonb_typeof(proposed) is distinct from 'object' then
    return pg_catalog.jsonb_build_object(
      'pass', false,
      'issues', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'code', 'PREDICTION_SETTINGS_COMPLETE_SCHEMA_REQUIRED'
      ))
    );
  end if;
  if (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(proposed))
       <> 30
     or exists (
       select 1 from pg_catalog.jsonb_object_keys(proposed) key_value
       where not exists (
         select 1
         from production_control.prediction_setting_definitions_v1 value
         where value.setting_key = key_value
       )
     ) then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PREDICTION_SETTINGS_COMPLETE_SCHEMA_REQUIRED'
      )
    );
  end if;
  for definition in
    select value.*
    from production_control.prediction_setting_definitions_v1 value
    order by value.sort_order
  loop
    if not (proposed ? definition.setting_key) then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'PREDICTION_SETTINGS_MISSING_SETTING',
          'key', definition.setting_key
        )
      );
      continue;
    end if;
    setting_value := proposed -> (definition.setting_key);
    if definition.value_type in ('number', 'integer') then
      if pg_catalog.jsonb_typeof(setting_value) <> 'number' then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'PREDICTION_SETTINGS_VALUE_TYPE_INVALID',
            'key', definition.setting_key,
            'expectedType', definition.value_type
          )
        );
      elsif definition.value_type = 'integer'
        and (setting_value#>>'{}')::numeric <>
          pg_catalog.trunc((setting_value#>>'{}')::numeric) then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'PREDICTION_SETTINGS_INTEGER_REQUIRED',
            'key', definition.setting_key
          )
        );
      elsif definition.minimum_value is not null
        and (setting_value#>>'{}')::numeric < definition.minimum_value then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'PREDICTION_SETTINGS_VALUE_BELOW_MINIMUM',
            'key', definition.setting_key,
            'minimum', definition.minimum_value
          )
        );
      elsif definition.maximum_value is not null
        and (setting_value#>>'{}')::numeric > definition.maximum_value then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'PREDICTION_SETTINGS_VALUE_ABOVE_MAXIMUM',
            'key', definition.setting_key,
            'maximum', definition.maximum_value
          )
        );
      end if;
    elsif definition.value_type = 'boolean' and
      pg_catalog.jsonb_typeof(setting_value) <> 'boolean' then
      issues := issues || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'code', 'PREDICTION_SETTINGS_VALUE_TYPE_INVALID',
          'key', definition.setting_key,
          'expectedType', 'boolean'
        )
      );
    elsif definition.value_type in ('enum', 'string') then
      if pg_catalog.jsonb_typeof(setting_value) <> 'string'
         or pg_catalog.btrim(setting_value#>>'{}') = '' then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'PREDICTION_SETTINGS_VALUE_TYPE_INVALID',
            'key', definition.setting_key,
            'expectedType', definition.value_type
          )
        );
      elsif definition.value_type = 'enum' and not exists (
        select 1
        from pg_catalog.jsonb_array_elements_text(
          definition.allowed_values
        ) allowed(value)
        where allowed.value = setting_value#>>'{}'
      ) then
        issues := issues || pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'code', 'PREDICTION_SETTINGS_ENUM_INVALID',
            'key', definition.setting_key,
            'allowedValues', definition.allowed_values
          )
        );
      end if;
    end if;
  end loop;
  select pg_catalog.jsonb_object_agg(value.setting_key, value.default_value)
    into defaults
  from production_control.prediction_setting_definitions_v1 value
  where value.legacy_recalibration_default;
  legacy_profile :=
    proposed->'Handicap Category Weight' = '15'::jsonb
    and proposed->'Player Category Weight' = '35'::jsonb
    and proposed->'Team Category Weight' = '30'::jsonb
    and proposed->'Opponent Category Weight' = '15'::jsonb
    and proposed->'Tournament Category Weight' = '5'::jsonb
    and proposed->'Better Player Handicap Difference' = '2'::jsonb
    and proposed->'Lesser Player Handicap Difference' = '2'::jsonb;
  effective := proposed || case when legacy_profile then defaults
    else '{}'::jsonb end;
  if pg_catalog.jsonb_typeof(effective->'Minimum Win Probability') = 'number'
     and pg_catalog.jsonb_typeof(effective->'Maximum Win Probability') = 'number'
     and (effective->>'Minimum Win Probability')::numeric >
       (effective->>'Maximum Win Probability')::numeric then
    issues := issues || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'code', 'PREDICTION_SETTINGS_PROBABILITY_BOUNDS_REVERSED'
      )
    );
  end if;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'Setting', value.setting_key,
    'Value', proposed -> (value.setting_key)
  ) order by value.sort_order) into rows_value
  from production_control.prediction_setting_definitions_v1 value;
  select coalesce(pg_catalog.jsonb_agg(value.setting_key order by value.sort_order),
    '[]'::jsonb) into changed
  from production_control.prediction_setting_definitions_v1 value
  where predecessor is null
    or predecessor -> (value.setting_key) is distinct from
      proposed -> (value.setting_key);
  return pg_catalog.jsonb_build_object(
    'pass', pg_catalog.jsonb_array_length(issues) = 0,
    'issues', issues,
    'canonicalSettings', proposed,
    'effectiveSettings', effective,
    'settingsRows', rows_value,
    'settingsFingerprint', production_control.prediction_settings_hash_v1(
      rows_value
    ),
    'effectiveSettingsFingerprint',
      production_control.prediction_settings_hash_v1(effective),
    'changedKeys', changed,
    'changedSettingCount', pg_catalog.jsonb_array_length(changed),
    'legacyRecalibrationProfile', legacy_profile
  );
exception when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'pass', false,
    'issues', pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'code', 'PREDICTION_SETTINGS_VALUE_TYPE_INVALID'
    ))
  );
end;
$$;


ALTER FUNCTION production_control.validate_prediction_settings_v1(proposed jsonb, predecessor jsonb) OWNER TO postgres;

--
-- Name: validate_production_calcutta_v1_result(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.validate_production_calcutta_v1_result(target_result_state text, engine_payload jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.calcutta_v1_current%rowtype;
  auction_value scoring_authority.calcutta_v1_auction_fact_revisions%rowtype;
  golfer_value jsonb;
  portfolio_value jsonb;
  completed_rounds integer[];
  canonical_completed_rounds integer[];
  expected_entrant_count integer;
  expected_owner_count integer;
begin
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026';
  select value.* into strict auction_value
  from scoring_authority.calcutta_v1_auction_fact_revisions value
  where value.auction_revision_id = current_value.auction_revision_id;

  if pg_catalog.jsonb_typeof(engine_payload) <> 'object'
     or not (engine_payload ?& array[
       'available', 'year', 'pot', 'completedRounds',
       'tournamentComplete', 'distributedPrizePool',
       'guaranteedDistributed', 'remainingPrizePool',
       'golfers', 'portfolios'
     ])
     or engine_payload->'available' = 'null'::jsonb
     or engine_payload->'year' = 'null'::jsonb
     or engine_payload->'pot' = 'null'::jsonb
     or engine_payload->'tournamentComplete' = 'null'::jsonb
     or pg_catalog.jsonb_typeof(engine_payload->'completedRounds') <> 'array'
     or pg_catalog.jsonb_typeof(engine_payload->'golfers') <> 'array'
     or pg_catalog.jsonb_typeof(engine_payload->'portfolios') <> 'array'
     or coalesce((engine_payload->>'year')::integer, 0) <> 2026
     or (engine_payload->>'pot')::numeric < 0
     or (engine_payload->>'pot')::numeric <>
       (auction_value.auction_manifest->>'pot')::numeric
     or engine_payload::text ~*
       '"(email|auth_user_id|authUserId|phone|service_role|serviceRole|secret|credential)"[[:space:]]*:'
     or exists (
       select 1 from pg_catalog.jsonb_object_keys(engine_payload) key_value
       where not (key_value = any(array[
         'available', 'year', 'pot', 'distributedPrizePool',
         'guaranteedDistributed', 'remainingPrizePool',
         'completedRounds', 'tournamentComplete', 'golfers', 'portfolios',
         'storylines', 'hero', 'source'
       ]))
     ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_PAYLOAD_INVALID';
  end if;

  begin
    select pg_catalog.array_agg(value::integer order by value::integer)
      into completed_rounds
    from pg_catalog.jsonb_array_elements_text(
      engine_payload->'completedRounds'
    ) value;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_PAYLOAD_INVALID';
  end;
  if coalesce(pg_catalog.array_length(completed_rounds, 1), 0) <>
       coalesce((
         select pg_catalog.count(distinct value)
         from pg_catalog.unnest(completed_rounds) value
       ), 0)
     or exists (
       select 1 from pg_catalog.unnest(coalesce(
         completed_rounds, '{}'::integer[]
       )) value where value not between 1 and 3
     ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_PAYLOAD_INVALID';
  end if;
  completed_rounds := coalesce(completed_rounds, '{}'::integer[]);
  canonical_completed_rounds :=
    production_control.calcutta_v1_completed_rounds();
  if completed_rounds is distinct from canonical_completed_rounds then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_COMPLETED_ROUNDS_CONFLICT';
  end if;

  expected_entrant_count := pg_catalog.jsonb_array_length(
    auction_value.auction_manifest->'purchases'
  );
  for golfer_value in
    select value from pg_catalog.jsonb_array_elements(
      engine_payload->'golfers'
    ) value
  loop
    if pg_catalog.jsonb_typeof(golfer_value) <> 'object'
       or pg_catalog.btrim(coalesce(golfer_value->>'playerId', '')) = ''
       or golfer_value#>>'{player,id}' is distinct from
         golfer_value->>'playerId'
       or pg_catalog.btrim(coalesce(
         golfer_value#>>'{player,name}', ''
       )) = ''
       or not exists (
         select 1 from pg_catalog.jsonb_array_elements(
           auction_value.auction_manifest->'purchases'
         ) purchase
         where purchase->>'player_id' = golfer_value->>'playerId'
       ) then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_RESULT_ENTRANT_INVALID';
    end if;
  end loop;
  if pg_catalog.jsonb_array_length(engine_payload->'golfers') <>
       expected_entrant_count
     or (
       select pg_catalog.count(distinct golfer->>'playerId')
       from pg_catalog.jsonb_array_elements(engine_payload->'golfers') golfer
     ) <> expected_entrant_count then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_ENTRANT_INVALID';
  end if;

  select pg_catalog.count(distinct ownership->>'owner_player_id')
    into expected_owner_count
  from pg_catalog.jsonb_array_elements(
    auction_value.auction_manifest->'ownership'
  ) ownership;
  for portfolio_value in
    select value from pg_catalog.jsonb_array_elements(
      engine_payload->'portfolios'
    ) value
  loop
    if pg_catalog.jsonb_typeof(portfolio_value) <> 'object'
       or pg_catalog.btrim(coalesce(portfolio_value->>'ownerId', '')) = ''
       or portfolio_value#>>'{owner,id}' is distinct from
         portfolio_value->>'ownerId'
       or pg_catalog.btrim(coalesce(
         portfolio_value#>>'{owner,name}', ''
       )) = ''
       or not exists (
         select 1 from pg_catalog.jsonb_array_elements(
           auction_value.auction_manifest->'ownership'
         ) ownership
         where ownership->>'owner_player_id' =
           portfolio_value->>'ownerId'
       ) then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_RESULT_OWNER_INVALID';
    end if;
  end loop;
  if pg_catalog.jsonb_array_length(engine_payload->'portfolios') <>
       expected_owner_count
     or (
       select pg_catalog.count(distinct portfolio->>'ownerId')
       from pg_catalog.jsonb_array_elements(
         engine_payload->'portfolios'
       ) portfolio
     ) <> expected_owner_count then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_OWNER_INVALID';
  end if;

  if target_result_state = 'OFFICIAL' then
    if coalesce((engine_payload->>'tournamentComplete')::boolean, false)
         is not true
       or not (3 = any(completed_rounds)) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_CALCUTTA_OFFICIAL_FINALIZATION_REQUIRED';
    end if;
  elsif target_result_state = 'PROVISIONAL' then
    if coalesce((engine_payload->>'tournamentComplete')::boolean, false)
         is true then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_RESULT_STATE_INVALID';
    end if;
  else
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_STATE_INVALID';
  end if;
  perform production_control.project_production_calcutta_v1_result(
    engine_payload
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_RESULT_PAYLOAD_INVALID';
end;
$$;


ALTER FUNCTION production_control.validate_production_calcutta_v1_result(target_result_state text, engine_payload jsonb) OWNER TO postgres;

--
-- Name: validate_tournament_awards_v1(text, jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.validate_tournament_awards_v1(target text, proposed jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  item jsonb;
  normalized jsonb := '[]'::jsonb;
  award_id_value uuid;
  title_value text;
  description_value text;
  publication_value text;
  recipient_value text;
  player_value text;
  team_value text;
  display_value text;
  order_value integer;
begin
  if pg_catalog.jsonb_typeof(proposed) is distinct from 'array'
     or pg_catalog.jsonb_array_length(proposed) > 100 then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_AWARDS_COLLECTION_INVALID';
  end if;
  for item in select value from pg_catalog.jsonb_array_elements(proposed)
  loop
    begin
      award_id_value := (item->>'award_id')::uuid;
      order_value := (item->>'display_order')::integer;
    exception when others then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_AWARDS_ITEM_INVALID';
    end;
    title_value := pg_catalog.btrim(coalesce(item->>'title', ''));
    description_value := pg_catalog.btrim(coalesce(
      item->>'description', ''
    ));
    publication_value := pg_catalog.upper(pg_catalog.btrim(coalesce(
      item->>'publication_state', ''
    )));
    recipient_value := pg_catalog.upper(pg_catalog.btrim(coalesce(
      item->>'recipient_kind', ''
    )));
    player_value := nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(
      item->>'winner_player_id', ''
    ))), '');
    team_value := nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(
      item->>'winner_team_id', ''
    ))), '');
    display_value := nullif(pg_catalog.btrim(coalesce(
      item->>'recipient_display', ''
    )), '');
    if title_value = '' or pg_catalog.length(title_value) > 160
       or pg_catalog.length(description_value) > 1000
       or title_value ~ '[<>{}]|[[:cntrl:]]'
       or description_value ~ '[<>{}]|[[:cntrl:]]'
       or (display_value is not null and (
         pg_catalog.length(display_value) > 160
         or display_value ~ '[<>{}]|[[:cntrl:]]'
       )) then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_AWARDS_UNSAFE_CONTENT';
    end if;
    if order_value not between 1 and 100 then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_AWARDS_DISPLAY_ORDER_INVALID';
    end if;
    if publication_value not in ('DRAFT', 'PUBLISHED', 'RETIRED')
       or recipient_value not in ('PLAYER', 'TEAM', 'TEXT', 'UNAVAILABLE') then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_AWARDS_ITEM_INVALID';
    end if;
    if recipient_value = 'PLAYER' then
      if player_value is null or team_value is not null
         or display_value is not null then
        raise exception using errcode = '22023',
          message = 'TOURNAMENT_AWARDS_PLAYER_INVALID';
      end if;
      if not exists (
        select 1 from scoring_authority.tournament_players membership
        where membership.tournament_id = target
          and membership.player_id = player_value
          and membership.participation_status = 'ACTIVE'
      ) then
        raise exception using errcode = '22023',
          message = 'TOURNAMENT_AWARDS_PLAYER_NOT_ACTIVE';
      end if;
    elsif recipient_value = 'TEAM' then
      if team_value is null or player_value is not null
         or display_value is not null
         or not exists (
           select 1 from scoring_authority.teams team
           where team.tournament_id = target and team.team_id = team_value
         ) then
        raise exception using errcode = '22023',
          message = 'TOURNAMENT_AWARDS_TEAM_NOT_FOUND';
      end if;
    elsif recipient_value = 'TEXT' then
      if display_value is null or player_value is not null
         or team_value is not null then
        raise exception using errcode = '22023',
          message = 'TOURNAMENT_AWARDS_TEXT_WINNER_INVALID';
      end if;
    elsif player_value is not null or team_value is not null
          or display_value is not null then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_AWARDS_PENDING_INVALID';
    end if;
    if publication_value = 'PUBLISHED'
       and recipient_value = 'UNAVAILABLE' then
      raise exception using errcode = '22023',
        message = 'TOURNAMENT_AWARDS_PENDING_PUBLICATION_INVALID';
    end if;
    normalized := normalized || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'award_id', award_id_value,
        'title', title_value,
        'description', description_value,
        'display_order', order_value,
        'publication_state', publication_value,
        'recipient_kind', recipient_value,
        'winner_player_id', player_value,
        'winner_team_id', team_value,
        'recipient_display', display_value
      )
    );
  end loop;
  if (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(
        normalized
      )) <> (select pg_catalog.count(distinct value->>'award_id')
        from pg_catalog.jsonb_array_elements(normalized) value)
     or (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(
        normalized
      )) <> (select pg_catalog.count(distinct value->>'display_order')
        from pg_catalog.jsonb_array_elements(normalized) value) then
    raise exception using errcode = '22023',
      message = 'TOURNAMENT_AWARDS_DUPLICATE_ID_OR_ORDER';
  end if;
  return coalesce((select pg_catalog.jsonb_agg(value order by
      (value->>'display_order')::integer, value->>'award_id')
    from pg_catalog.jsonb_array_elements(normalized) value), '[]'::jsonb);
end;
$$;


ALTER FUNCTION production_control.validate_tournament_awards_v1(target text, proposed jsonb) OWNER TO postgres;

--
-- Name: vercel_alias_recapture_response(uuid); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.vercel_alias_recapture_response(target_evidence_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  with captures as (
    select attestation.stage, attestation.attestation_id,
      attestation.attestation_fingerprint,
      attestation.provider_observed_at,
      capture.alias_inventory_count,
      capture.alias_inventory_fingerprint,
      capture.alias_pagination_page_count,
      capture.alias_pagination_fingerprint
    from production_control.vercel_provider_attestations attestation
    join production_control.vercel_provider_alias_captures capture
      on capture.attestation_id = attestation.attestation_id
    where attestation.evidence_id = target_evidence_id
      and attestation.status = 'BOUND'
  ), summary as (
    select pg_catalog.count(*)::integer as recapture_count,
      pg_catalog.max(alias_inventory_count) as alias_inventory_count,
      pg_catalog.max(alias_inventory_fingerprint)
        as alias_inventory_fingerprint,
      pg_catalog.max(alias_pagination_page_count)
        as alias_pagination_page_count,
      pg_catalog.max(alias_pagination_fingerprint)
        as alias_pagination_fingerprint,
      (pg_catalog.max(attestation_id::text) filter (where stage = 'BEGIN'))::uuid
        as begin_attestation_id,
      pg_catalog.max(attestation_fingerprint) filter (where stage = 'BEGIN')
        as begin_attestation_fingerprint,
      pg_catalog.max(provider_observed_at) filter (where stage = 'BEGIN')
        as begin_provider_observed_at,
      (pg_catalog.max(attestation_id::text) filter (where stage = 'FINALIZE'))::uuid
        as finalize_attestation_id,
      pg_catalog.max(attestation_fingerprint) filter (where stage = 'FINALIZE')
        as finalize_attestation_fingerprint,
      pg_catalog.max(provider_observed_at) filter (where stage = 'FINALIZE')
        as finalize_provider_observed_at
    from captures
  )
  select case when recapture_count = 0 then '{}'::jsonb
    else pg_catalog.jsonb_build_object(
      'alias_recapture_count', recapture_count,
      'alias_inventory_count', alias_inventory_count,
      'alias_inventory_fingerprint', alias_inventory_fingerprint,
      'alias_pagination_page_count', alias_pagination_page_count,
      'alias_pagination_fingerprint', alias_pagination_fingerprint,
      'begin_alias_attestation_id', begin_attestation_id,
      'begin_alias_attestation_fingerprint', begin_attestation_fingerprint,
      'begin_alias_provider_observed_at', begin_provider_observed_at,
      'finalize_alias_attestation_id', finalize_attestation_id,
      'finalize_alias_attestation_fingerprint', finalize_attestation_fingerprint,
      'finalize_alias_provider_observed_at', finalize_provider_observed_at
    ) end
  from summary
$$;


ALTER FUNCTION production_control.vercel_alias_recapture_response(target_evidence_id uuid) OWNER TO postgres;

--
-- Name: vercel_provider_attestation_challenge_response(production_control.vercel_provider_attestation_challenges, boolean); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.vercel_provider_attestation_challenge_response(value production_control.vercel_provider_attestation_challenges, was_idempotent boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select base.response
    || pg_catalog.jsonb_build_object(
      'routing_rule_hostname_operator',
        routing_audit.routing_rule_hostname_operator,
      'routing_rule_canonical_hostname',
        routing_audit.routing_rule_canonical_hostname,
      'routing_rule_earlier_active_bypass_rule_count',
        routing_audit.routing_rule_earlier_active_bypass_rule_count,
      'routing_rule_global_invocation_quiescence_proved',
        routing_audit.routing_rule_global_invocation_quiescence_proved,
      'routing_rule_candidate_control_host_count',
        routing_audit.routing_rule_candidate_control_host_count,
      'routing_rule_candidate_control_hosts_fingerprint',
        routing_audit.routing_rule_candidate_control_hosts_fingerprint,
      'routing_rule_canonical_apex_safe_method_count',
        routing_audit.routing_rule_canonical_apex_safe_method_count,
      'routing_rule_canonical_apex_safe_methods_fingerprint',
        routing_audit.routing_rule_canonical_apex_safe_methods_fingerprint,
      'routing_rule_canonical_apex_safe_method_writer_route_count',
        routing_audit.routing_rule_canonical_apex_safe_method_writer_route_count,
      'routing_rule_canonical_apex_safe_method_writer_routes_fingerprint',
        routing_audit.routing_rule_canonical_apex_safe_method_writer_routes_fingerprint
    )
    || case when pg_catalog.jsonb_typeof(
         base.response->'consumed_provider_attestation'
       ) = 'object'
      then pg_catalog.jsonb_build_object(
        'consumed_provider_attestation',
          base.response->'consumed_provider_attestation'
          || pg_catalog.jsonb_build_object(
            'routing_rule_hostname_operator',
              consumed_audit.routing_rule_hostname_operator,
            'routing_rule_canonical_hostname',
              consumed_audit.routing_rule_canonical_hostname,
            'routing_rule_earlier_active_bypass_rule_count',
              consumed_audit.routing_rule_earlier_active_bypass_rule_count,
            'routing_rule_global_invocation_quiescence_proved',
              consumed_audit.routing_rule_global_invocation_quiescence_proved,
            'routing_rule_candidate_control_host_count',
              consumed_audit.routing_rule_candidate_control_host_count,
            'routing_rule_candidate_control_hosts_fingerprint',
              consumed_audit.routing_rule_candidate_control_hosts_fingerprint,
            'routing_rule_canonical_apex_safe_method_count',
              consumed_audit.routing_rule_canonical_apex_safe_method_count,
            'routing_rule_canonical_apex_safe_methods_fingerprint',
              consumed_audit.routing_rule_canonical_apex_safe_methods_fingerprint,
            'routing_rule_canonical_apex_safe_method_writer_route_count',
              consumed_audit.routing_rule_canonical_apex_safe_method_writer_route_count,
            'routing_rule_canonical_apex_safe_method_writer_routes_fingerprint',
              consumed_audit.routing_rule_canonical_apex_safe_method_writer_routes_fingerprint,
            'alias_inventory_count', consumed_alias.alias_inventory_count,
            'alias_inventory_fingerprint',
              consumed_alias.alias_inventory_fingerprint,
            'alias_inventory_records', consumed_alias.alias_inventory_records,
            'alias_pagination_page_count',
              consumed_alias.alias_pagination_page_count,
            'alias_pagination_fingerprint',
              consumed_alias.alias_pagination_fingerprint
          )
      ) else '{}'::jsonb end
  from (
    select production_control.vercel_provider_challenge_response_v3_base(
      value, was_idempotent
    ) as response
  ) base
  left join production_control.vercel_provider_attestations consumed
    on consumed.attestation_id = value.consumed_attestation_id
  left join production_control.vercel_routing_rule_audit_bindings routing_audit
    on routing_audit.challenge_id = value.challenge_id
  left join production_control.vercel_routing_rule_audit_bindings consumed_audit
    on consumed_audit.attestation_id = consumed.attestation_id
  left join production_control.vercel_provider_alias_captures consumed_alias
    on consumed_alias.attestation_id = consumed.attestation_id
$$;


