    retirement_candidate_deployment_id text,
    retirement_candidate_deployment_commit text,
    retirement_reason text,
    retired_at timestamp with time zone,
    CONSTRAINT production_vercel_writer_critical_waf_epoch_state_check CHECK ((((status <> 'REJECTED_RETIRED'::text) AND (retirement_request_id IS NULL) AND (retirement_request_fingerprint IS NULL) AND (retirement_payload_hash IS NULL) AND (retirement_observation_id IS NULL) AND (retirement_evidence_fingerprint IS NULL) AND (retirement_candidate_deployment_id IS NULL) AND (retirement_candidate_deployment_commit IS NULL) AND (retirement_reason IS NULL) AND (retired_at IS NULL) AND (((status = 'ACTIVATION_PENDING'::text) AND (critical_active_observation_id IS NULL) AND (critical_semantic_configuration_fingerprint IS NULL) AND (critical_active_at IS NULL) AND (bound_fence_id IS NULL) AND (bound_quiesce_evidence_id IS NULL) AND (fence_bound_at IS NULL) AND (fence_bind_request_id IS NULL) AND (fence_bind_request_fingerprint IS NULL) AND (fence_bind_payload_hash IS NULL) AND (restore_pending_at IS NULL) AND (baseline_restored_at IS NULL) AND (baseline_restored_observation_id IS NULL)) OR ((status = 'ACTIVE_UNBOUND'::text) AND (critical_active_observation_id IS NOT NULL) AND (provider_assigned_rule_id IS NOT NULL) AND (critical_semantic_configuration_fingerprint IS NOT NULL) AND (critical_active_at IS NOT NULL) AND (bound_fence_id IS NULL) AND (bound_quiesce_evidence_id IS NULL) AND (fence_bound_at IS NULL) AND (fence_bind_request_id IS NULL) AND (fence_bind_request_fingerprint IS NULL) AND (fence_bind_payload_hash IS NULL) AND (restore_pending_at IS NULL) AND (baseline_restored_at IS NULL) AND (baseline_restored_observation_id IS NULL)) OR ((status = 'FENCE_BOUND'::text) AND (critical_active_observation_id IS NOT NULL) AND (provider_assigned_rule_id IS NOT NULL) AND (critical_semantic_configuration_fingerprint IS NOT NULL) AND (critical_active_at IS NOT NULL) AND (bound_fence_id IS NOT NULL) AND (bound_quiesce_evidence_id IS NOT NULL) AND (fence_bound_at IS NOT NULL) AND (fence_bind_request_id IS NOT NULL) AND (fence_bind_request_fingerprint IS NOT NULL) AND (fence_bind_payload_hash IS NOT NULL) AND (restore_pending_at IS NULL) AND (baseline_restored_at IS NULL) AND (baseline_restored_observation_id IS NULL)) OR ((status = 'RESTORE_PENDING'::text) AND (critical_active_observation_id IS NOT NULL) AND (provider_assigned_rule_id IS NOT NULL) AND (critical_semantic_configuration_fingerprint IS NOT NULL) AND (critical_active_at IS NOT NULL) AND (bound_fence_id IS NOT NULL) AND (bound_quiesce_evidence_id IS NOT NULL) AND (fence_bound_at IS NOT NULL) AND (fence_bind_request_id IS NOT NULL) AND (fence_bind_request_fingerprint IS NOT NULL) AND (fence_bind_payload_hash IS NOT NULL) AND (restore_pending_at IS NOT NULL) AND (baseline_restored_at IS NULL) AND (baseline_restored_observation_id IS NULL) AND (restore_request_id IS NOT NULL) AND (restore_request_fingerprint IS NOT NULL) AND (restore_payload_hash IS NOT NULL)) OR ((status = 'BASELINE_RESTORED'::text) AND (critical_active_observation_id IS NOT NULL) AND (provider_assigned_rule_id IS NOT NULL) AND (critical_semantic_configuration_fingerprint IS NOT NULL) AND (critical_active_at IS NOT NULL) AND (bound_fence_id IS NOT NULL) AND (bound_quiesce_evidence_id IS NOT NULL) AND (fence_bound_at IS NOT NULL) AND (fence_bind_request_id IS NOT NULL) AND (fence_bind_request_fingerprint IS NOT NULL) AND (fence_bind_payload_hash IS NOT NULL) AND (restore_pending_at IS NOT NULL) AND (baseline_restored_at IS NOT NULL) AND (baseline_restored_observation_id IS NOT NULL) AND (restore_request_id IS NOT NULL) AND (restore_request_fingerprint IS NOT NULL) AND (restore_payload_hash IS NOT NULL)))) OR ((status = 'REJECTED_RETIRED'::text) AND (critical_active_observation_id IS NULL) AND (provider_assigned_rule_id IS NULL) AND (critical_semantic_configuration_fingerprint IS NULL) AND (critical_active_at IS NULL) AND (bound_fence_id IS NULL) AND (bound_quiesce_evidence_id IS NULL) AND (fence_bound_at IS NULL) AND (fence_bind_request_id IS NULL) AND (fence_bind_request_fingerprint IS NULL) AND (fence_bind_payload_hash IS NULL) AND (restore_pending_at IS NULL) AND (baseline_restored_at IS NULL) AND (baseline_restored_observation_id IS NULL) AND (restore_request_id IS NULL) AND (restore_request_fingerprint IS NULL) AND (restore_payload_hash IS NULL) AND (retirement_request_id IS NOT NULL) AND (retirement_request_fingerprint IS NOT NULL) AND (retirement_payload_hash IS NOT NULL) AND (retirement_observation_id IS NOT NULL) AND (retirement_evidence_fingerprint IS NOT NULL) AND (retirement_candidate_deployment_id IS NOT NULL) AND (retirement_candidate_deployment_commit IS NOT NULL) AND (retirement_reason = 'PROVIDER_REJECTED_NO_MUTATION'::text) AND (retired_at IS NOT NULL)))),
    CONSTRAINT production_vercel_writer_critical_waf_epoch_target_check CHECK ((((purpose = 'REHEARSAL'::text) AND (transition_mode = 'REHEARSAL'::text) AND (candidate_deployment_target = 'PREVIEW'::text)) OR ((purpose = 'CUTOVER'::text) AND (transition_mode = ANY (ARRAY['CUTOVER'::text, 'ROLLBACK'::text])) AND (candidate_deployment_target = 'PREVIEW'::text)))),
    CONSTRAINT vercel_writer_critical_waf_e_authenticated_actor_fingerpr_check CHECK ((authenticated_actor_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_e_baseline_active_config_versi_check CHECK ((baseline_active_config_version ~ '^[A-Za-z0-9_.:-]{1,160}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_e_baseline_configuration_ident_check CHECK ((baseline_configuration_identity_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_e_baseline_ordered_rules_finge_check CHECK ((baseline_ordered_rules_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_e_baseline_provider_configurat_check CHECK ((baseline_provider_configuration_id ~ '^[A-Za-z0-9_.:-]{1,160}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_e_baseline_semantic_configurat_check CHECK ((baseline_semantic_configuration_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_e_baseline_source_version_read_check CHECK ((baseline_source_version_read_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_e_candidate_control_hosts_fing_check CHECK ((candidate_control_hosts_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_e_critical_semantic_configurat_check CHECK (((critical_semantic_configuration_fingerprint IS NULL) OR (critical_semantic_configuration_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_e_fence_bind_request_fingerpri_check CHECK (((fence_bind_request_fingerprint IS NULL) OR (fence_bind_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_e_retirement_candidate_deploy_check1 CHECK (((retirement_candidate_deployment_commit IS NULL) OR (retirement_candidate_deployment_commit ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_e_retirement_candidate_deploym_check CHECK (((retirement_candidate_deployment_id IS NULL) OR (retirement_candidate_deployment_id ~ '^dpl_[A-Za-z0-9]{8,64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_e_retirement_evidence_fingerpr_check CHECK (((retirement_evidence_fingerprint IS NULL) OR (retirement_evidence_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_e_retirement_request_fingerpri_check CHECK (((retirement_request_fingerprint IS NULL) OR (retirement_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_e_run_owned_insert_document_fi_check CHECK ((run_owned_insert_document_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_ep_baseline_active_config_etag_check CHECK (((baseline_active_config_etag IS NULL) OR ((btrim(baseline_active_config_etag) <> ''::text) AND (length(baseline_active_config_etag) <= 512)))),
    CONSTRAINT vercel_writer_critical_waf_ep_candidate_deployment_commit_check CHECK ((candidate_deployment_commit ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_ep_candidate_deployment_target_check CHECK ((candidate_deployment_target = 'PREVIEW'::text)),
    CONSTRAINT vercel_writer_critical_waf_ep_restore_request_fingerprint_check CHECK (((restore_request_fingerprint IS NULL) OR (restore_request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_epo_baseline_custom_rule_count_check CHECK ((baseline_custom_rule_count = 0)),
    CONSTRAINT vercel_writer_critical_waf_epo_baseline_provider_owner_id_check CHECK ((baseline_provider_owner_id ~ '^[A-Za-z0-9_.:-]{1,160}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_epo_candidate_immutable_origin_check CHECK ((candidate_immutable_origin ~ '^https://[a-z0-9.-]+$'::text)),
    CONSTRAINT vercel_writer_critical_waf_epo_run_owned_rule_fingerprint_check CHECK ((run_owned_rule_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_epoc_begin_request_fingerprint_check CHECK ((begin_request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_epoc_provider_assigned_rule_id_check CHECK (((provider_assigned_rule_id IS NULL) OR (provider_assigned_rule_id ~ '^[A-Za-z0-9_.:-]{3,160}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_epochs_actor_id_check CHECK (((btrim(actor_id) <> ''::text) AND (length(actor_id) <= 160))),
    CONSTRAINT vercel_writer_critical_waf_epochs_begin_payload_hash_check CHECK ((begin_payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_epochs_candidate_alias_origin_check CHECK ((candidate_alias_origin ~ '^https://[a-z0-9.-]+$'::text)),
    CONSTRAINT vercel_writer_critical_waf_epochs_candidate_deployment_id_check CHECK ((candidate_deployment_id ~ '^dpl_[A-Za-z0-9]{8,64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_epochs_fence_bind_payload_hash_check CHECK (((fence_bind_payload_hash IS NULL) OR (fence_bind_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_epochs_purpose_check CHECK ((purpose = ANY (ARRAY['REHEARSAL'::text, 'CUTOVER'::text]))),
    CONSTRAINT vercel_writer_critical_waf_epochs_restore_payload_hash_check CHECK (((restore_payload_hash IS NULL) OR (restore_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_epochs_retirement_payload_hash_check CHECK (((retirement_payload_hash IS NULL) OR (retirement_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_epochs_retirement_reason_check CHECK (((retirement_reason IS NULL) OR (retirement_reason = 'PROVIDER_REJECTED_NO_MUTATION'::text))),
    CONSTRAINT vercel_writer_critical_waf_epochs_run_owned_rule_name_check CHECK ((run_owned_rule_name ~ '^[A-Za-z0-9 _.,:/-]{8,160}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_epochs_status_check CHECK ((status = ANY (ARRAY['ACTIVATION_PENDING'::text, 'ACTIVE_UNBOUND'::text, 'FENCE_BOUND'::text, 'RESTORE_PENDING'::text, 'BASELINE_RESTORED'::text, 'REJECTED_RETIRED'::text]))),
    CONSTRAINT vercel_writer_critical_waf_epochs_transition_mode_check CHECK ((transition_mode = ANY (ARRAY['REHEARSAL'::text, 'CUTOVER'::text, 'ROLLBACK'::text]))),
    CONSTRAINT vercel_writer_critical_waf_epochs_vercel_project_id_check CHECK ((vercel_project_id = 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'::text)),
    CONSTRAINT vercel_writer_critical_waf_epochs_vercel_team_id_check CHECK ((vercel_team_id ~ '^[A-Za-z0-9_.:-]{3,160}$'::text))
);


