--
-- Name: worker_supervisor_scope_v1(); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.worker_supervisor_scope_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if production_control.worker_supervisor_model_d_v1() then
  if not exists(select 1 from production_control.worker_supervisor_v1 where singleton and engines=production_control.worker_supervisor_engines_v1()) or exists(select 1 from scoring_authority.odds_published_snapshots where not publication_verified) then raise exception using errcode='42501',message='SUPERVISOR_ENGINE_SCOPE_DENIED';end if;
  return;
 end if;
 -- Closed installed registry, never a message/client engine selector.
 if not exists(select 1 from production_control.worker_supervisor_v1 where singleton and
  engines=array['TEAM_MOMENTUM','TOURNAMENT_STORYLINES','TOURNAMENT_INTELLIGENCE','PROJECTION_EDITORIAL','CALCUTTA']::text[])
  or production_control.derived_final_recap_ready_v1('2026')
  -- Published non-Final Odds creates work for the existing Intelligence engines.
  -- This does not admit an Odds processor or FinalRecap to the Queue registry.
  or exists(select 1 from scoring_authority.odds_published_snapshots
   where not publication_verified or milestone='Final Results'
    or published_payload->>'phase'='Final Results') then
  raise exception using errcode='42501',message='SUPERVISOR_ENGINE_SCOPE_DENIED';end if;
end;$$;


ALTER FUNCTION production_control.worker_supervisor_scope_v1() OWNER TO postgres;

--
-- Name: worker_supervisor_status_v1(jsonb); Type: FUNCTION; Schema: production_control; Owner: postgres
--

CREATE FUNCTION production_control.worker_supervisor_status_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare s production_control.worker_supervisor_v1%rowtype;b jsonb;
begin
 perform production_control.worker_supervisor_owner_v1();b:=production_control.worker_supervisor_queue_binding_v2(input);
 select * into strict s from production_control.worker_supervisor_v1;
 return jsonb_build_object('ok',true,'state',s.state,'enabled',s.state='ENABLED'and not s.halt_latched and s.expires_at>clock_timestamp(),
 'engine_scope_contract',case when production_control.worker_supervisor_model_d_v1() then 'certification-model-d-execution-v1' else 'certification-queue-calcutta-scope-v1' end,'engines',to_jsonb(s.engines),
 'epoch',s.epoch,'revision',s.revision,'expiry',s.expires_at,'deployment',b->'deployment','slots',s.slots,'budget',s.budget,
 'reserved',(select count(*)from production_control.worker_supervisor_invocations_v1 where epoch=s.epoch and state='RESERVED'),
 'consumed',(select count(*)from production_control.worker_supervisor_invocations_v1 where epoch=s.epoch and started_at is not null),
 'remaining',(select count(*)from production_control.worker_supervisor_invocations_v1 where epoch=s.epoch and state='RESERVED'and expires_at>clock_timestamp()),
 'publication',(select jsonb_build_object('reserved',count(*)filter(where publication_state='RESERVED'),'unknown',count(*)filter(where publication_state='UNKNOWN'),
 'accepted',count(*)filter(where publication_state='ACCEPTED'),'delivered',count(*)filter(where publication_state='DELIVERED'),'cancelled',count(*)filter(where publication_state='CANCELLED'))
 from production_control.worker_supervisor_invocations_v1 where epoch=s.epoch),
 'schedule_installed',false,'delivery_certified',false,
 'last_invocation',s.last_invocation,'last_successful_tick',s.last_success,'consecutive_global_failures',s.tick_failures,
 'consecutive_invocation_failures',s.invocation_failures,'next_eligible_at',s.next_at,'reason',s.reason,'halt_latched',s.halt_latched,
 'last_halt_reason',s.last_halt_reason,'degraded',exists(select 1 from production_control.worker_supervisor_invocations_v1 where epoch=s.epoch and state='UNKNOWN'),
 'counts',production_control.worker_supervisor_counts_v1(),
 'global_faults',(select jsonb_build_object('plans',count(*),'remaining_uses',coalesce(sum(remaining_uses),0),
 'consumed_uses',coalesce(sum(initial_uses-remaining_uses-cancelled_uses),0),'cancelled_uses',coalesce(sum(cancelled_uses),0),'correction_required',coalesce(bool_or(corrected_at is null),false))
 from production_control.worker_supervisor_global_faults_v5 where epoch=s.epoch));
end;$$;


ALTER FUNCTION production_control.worker_supervisor_status_v1(input jsonb) OWNER TO postgres;

--
-- Name: scoring_runs; Type: TABLE; Schema: production_rehearsal; Owner: postgres
--

CREATE TABLE production_rehearsal.scoring_runs (
    run_id uuid NOT NULL,
    contract_version text NOT NULL,
    project_ref text NOT NULL,
    project_url text NOT NULL,
    source_workbook_id text NOT NULL,
    candidate_sha text NOT NULL,
    candidate_hostname text NOT NULL,
    run_token_hash text NOT NULL,
    actor_id text NOT NULL,
    director_authorization_id text NOT NULL,
    synthetic_tournament_id text NOT NULL,
    source_tournament_id text NOT NULL,
    source_tournament_year integer NOT NULL,
    source_match_id text NOT NULL,
    source_fingerprint text NOT NULL,
    frozen_fixture_fingerprint text NOT NULL,
    frozen_fixture jsonb NOT NULL,
    s3_fingerprint_before text NOT NULL,
    current_2026_fingerprint_before text NOT NULL,
    current_2026_fingerprint_after text,
    status text DEFAULT 'PREPARED'::text NOT NULL,
    rehearsal_authority text DEFAULT 'GOOGLE'::text NOT NULL,
    ingress_state text DEFAULT 'PAUSED'::text NOT NULL,
    unresolved_client_queues integer DEFAULT 0 NOT NULL,
    external_transport text DEFAULT 'VIRTUAL'::text NOT NULL,
    external_google_writes integer DEFAULT 0 NOT NULL,
    live_2026_writes integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT scoring_runs_candidate_hostname_check CHECK (((candidate_hostname ~ '^[a-z0-9-]+(?:\.[a-z0-9-]+)*\.vercel\.app$'::text) AND (candidate_hostname <> 'baggerinv.com'::text))),
    CONSTRAINT scoring_runs_candidate_sha_check CHECK ((candidate_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT scoring_runs_check CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '04:00:00'::interval)))),
    CONSTRAINT scoring_runs_check1 CHECK ((((status = 'ACTIVE'::text) AND (rehearsal_authority = 'SUPABASE'::text) AND (ingress_state = 'OPEN'::text)) OR (status <> 'ACTIVE'::text))),
    CONSTRAINT scoring_runs_check2 CHECK ((((status = ANY (ARRAY['ROLLED_BACK'::text, 'CLEANED'::text])) AND (rehearsal_authority = 'GOOGLE'::text) AND (ingress_state = 'PAUSED'::text)) OR (status <> ALL (ARRAY['ROLLED_BACK'::text, 'CLEANED'::text])))),
    CONSTRAINT scoring_runs_contract_version_check CHECK ((contract_version = 'production-step11-scoring-rehearsal-v1'::text)),
    CONSTRAINT scoring_runs_current_2026_fingerprint_after_check CHECK (((current_2026_fingerprint_after IS NULL) OR (current_2026_fingerprint_after ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT scoring_runs_current_2026_fingerprint_before_check CHECK ((current_2026_fingerprint_before ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT scoring_runs_external_google_writes_check CHECK ((external_google_writes = 0)),
    CONSTRAINT scoring_runs_external_transport_check CHECK ((external_transport = 'VIRTUAL'::text)),
    CONSTRAINT scoring_runs_frozen_fixture_check CHECK ((jsonb_typeof(frozen_fixture) = 'object'::text)),
    CONSTRAINT scoring_runs_frozen_fixture_fingerprint_check CHECK ((frozen_fixture_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT scoring_runs_ingress_state_check CHECK ((ingress_state = ANY (ARRAY['PAUSED'::text, 'OPEN'::text]))),
    CONSTRAINT scoring_runs_live_2026_writes_check CHECK ((live_2026_writes = 0)),
    CONSTRAINT scoring_runs_project_ref_check CHECK ((project_ref = 'ymqhhtxaywtqllynrmxe'::text)),
    CONSTRAINT scoring_runs_project_url_check CHECK ((project_url = 'https://ymqhhtxaywtqllynrmxe.supabase.co'::text)),
    CONSTRAINT scoring_runs_rehearsal_authority_check CHECK ((rehearsal_authority = ANY (ARRAY['GOOGLE'::text, 'SUPABASE'::text]))),
    CONSTRAINT scoring_runs_run_token_hash_check CHECK ((run_token_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT scoring_runs_s3_fingerprint_before_check CHECK ((s3_fingerprint_before ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT scoring_runs_source_fingerprint_check CHECK ((source_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT scoring_runs_source_tournament_id_check CHECK ((source_tournament_id <> '2026'::text)),
    CONSTRAINT scoring_runs_source_tournament_year_check CHECK (((source_tournament_year >= 2017) AND (source_tournament_year <= 2025))),
    CONSTRAINT scoring_runs_source_workbook_id_check CHECK ((source_workbook_id = '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'::text)),
    CONSTRAINT scoring_runs_status_check CHECK ((status = ANY (ARRAY['PREPARED'::text, 'ACTIVE'::text, 'ROLLED_BACK'::text, 'CLEANED'::text, 'ABORTED'::text, 'EXPIRED'::text]))),
    CONSTRAINT scoring_runs_synthetic_tournament_id_check CHECK (((synthetic_tournament_id ~ '^STEP11-[0-9A-F-]{16,}$'::text) AND (synthetic_tournament_id <> '2026'::text))),
    CONSTRAINT scoring_runs_unresolved_client_queues_check CHECK ((unresolved_client_queues >= 0))
);


ALTER TABLE production_rehearsal.scoring_runs OWNER TO postgres;

--
-- Name: assert_run(jsonb); Type: FUNCTION; Schema: production_rehearsal; Owner: postgres
--

CREATE FUNCTION production_rehearsal.assert_run(input jsonb) RETURNS production_rehearsal.scoring_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_rehearsal', 'production_control', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare
  run production_rehearsal.scoring_runs%rowtype;
  scope production_control.resource_scope%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_SERVICE_ROLE_REQUIRED';
  end if;
  scope := production_control.assert_current_shadow_v2_dormant();
  if upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref','')) <> scope.project_ref
     or btrim(coalesce(input->>'project_url','')) <> scope.project_url
     or btrim(coalesce(input->>'source_workbook_id','')) <> scope.google_workbook_id
     or btrim(coalesce(input->>'candidate_sha','')) !~ '^[0-9a-f]{40}$'
     or btrim(coalesce(input->>'candidate_hostname','')) !~ '^[a-z0-9-]+(?:\.[a-z0-9-]+)*\.vercel\.app$'
     or btrim(coalesce(input->>'candidate_hostname','')) = 'baggerinv.com'
     or btrim(coalesce(input->>'run_token','')) = '' then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_EXACT_RESOURCE_SCOPE_REQUIRED';
  end if;
  select * into strict run from production_rehearsal.scoring_runs value
  where value.run_id = (input->>'run_id')::uuid for update;
  if run.project_ref <> scope.project_ref
     or run.project_url <> scope.project_url
     or run.source_workbook_id <> scope.google_workbook_id
     or run.candidate_sha <> input->>'candidate_sha'
     or run.candidate_hostname <> input->>'candidate_hostname'
     or run.synthetic_tournament_id <> input->>'synthetic_tournament_id'
     or run.run_token_hash <> encode(extensions.digest(input->>'run_token','sha256'),'hex') then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_RUN_SCOPE_MISMATCH';
  end if;
  if run.expires_at <= now() then
    update production_rehearsal.scoring_runs set status = 'EXPIRED'
    where run_id = run.run_id and status not in ('CLEANED','ABORTED');
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_RUN_EXPIRED';
  end if;
  if run.synthetic_tournament_id = '2026'
     or run.external_transport <> 'VIRTUAL'
     or run.external_google_writes <> 0
     or run.live_2026_writes <> 0 then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_SAFETY_INVARIANT_FAILED';
  end if;
  return run;
end;
$_$;


ALTER FUNCTION production_rehearsal.assert_run(input jsonb) OWNER TO postgres;

--
-- Name: completed_source_fixture(text); Type: FUNCTION; Schema: production_rehearsal; Owner: postgres
--

CREATE FUNCTION production_rehearsal.completed_source_fixture(requested_match_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'scoring_authority', 'extensions', 'pg_temp'
    AS $$
declare
  fixture jsonb;
begin
  select jsonb_build_object(
    'sourceTournamentId', candidate.tournament_id,
    'sourceTournamentYear', candidate.tournament_year,
    'sourceMatchId', candidate.match_id,
    'sourceRevisionId', candidate.revision_id,
    'sourceRevisionNumber', candidate.revision_number,
    'sourceRevisionFingerprint', candidate.database_payload_fingerprint,
    'status', candidate.lifecycle,
    'format', candidate.format,
    'participantIds', candidate.participant_ids,
    'courseId', candidate.course_id,
    'tee', candidate.tee,
    'roundNumber', candidate.round_number
  )
  into fixture
  from (
    select
      current_revision.tournament_id,
      current_revision.tournament_year,
      revision.revision_id,
      revision.revision_number,
      revision.database_payload_fingerprint,
      completed_match.match_id,
      upper(completed_match.lifecycle) as lifecycle,
      upper(completed_match.format) as format,
      completed_match.round_number,
      course.course_id,
      course.tee,
      participants.participant_ids
    from scoring_authority.completed_history_current_revisions current_revision
    join scoring_authority.completed_history_revisions revision
      on revision.revision_id = current_revision.revision_id
     and revision.tournament_id = current_revision.tournament_id
     and revision.tournament_year = current_revision.tournament_year
     and revision.project_ref = current_revision.project_ref
     and revision.source_workbook_id = current_revision.source_workbook_id
    join scoring_authority.completed_history_tournament_facts tournament
      on tournament.revision_id = revision.revision_id
     and tournament.tournament_id = current_revision.tournament_id
     and tournament.tournament_year = current_revision.tournament_year
    join scoring_authority.completed_history_matches completed_match
      on completed_match.revision_id = revision.revision_id
     and completed_match.tournament_id = current_revision.tournament_id
    join scoring_authority.completed_history_course_appearances course
      on course.revision_id = revision.revision_id
     and course.tournament_id = current_revision.tournament_id
     and course.appearance_id = completed_match.course_appearance_id
    join lateral (
      select
        jsonb_agg(
          participant.player_id
          order by participant.team_side, participant.player_slot, participant.player_id
        ) as participant_ids,
        count(*) as participant_count
      from scoring_authority.completed_history_match_participants participant
      where participant.revision_id = revision.revision_id
        and participant.match_id = completed_match.match_id
        and btrim(participant.player_id) <> ''
    ) participants on participants.participant_count >= 2
    where current_revision.project_ref = 'ymqhhtxaywtqllynrmxe'
      and current_revision.source_workbook_id = '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
      and current_revision.tournament_year between 2017 and 2025
      and current_revision.tournament_id <> '2026'
      and upper(completed_match.lifecycle) = 'FINAL'
      and upper(completed_match.format) in ('BB', 'SC', 'SI')
      and (
        nullif(btrim(coalesce(requested_match_id, '')), '') is null
        or completed_match.match_id = btrim(requested_match_id)
      )
  ) candidate
  order by candidate.tournament_year desc, candidate.match_id
  limit 1;

  if fixture is null
     or jsonb_array_length(fixture->'participantIds') < 2 then
    raise exception using
      errcode = '42501',
      message = 'PRODUCTION_STEP11_COMPLETED_SOURCE_MATCH_REQUIRED';
  end if;

  return fixture;
end;
$$;


ALTER FUNCTION production_rehearsal.completed_source_fixture(requested_match_id text) OWNER TO postgres;

--
-- Name: current_2026_fingerprint(); Type: FUNCTION; Schema: production_rehearsal; Owner: postgres
--

CREATE FUNCTION production_rehearsal.current_2026_fingerprint() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'scoring_authority', 'extensions', 'pg_temp'
    AS $$
  select encode(extensions.digest(jsonb_build_object(
    'tournament', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.tournament_id)
      from scoring_authority.tournaments value where value.tournament_id = '2026'
    ), '[]'::jsonb),
    'teams', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.team_id)
      from scoring_authority.teams value where value.tournament_id = '2026'
    ), '[]'::jsonb),
    'players', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.player_id)
      from scoring_authority.tournament_players value where value.tournament_id = '2026'
    ), '[]'::jsonb),
    'rounds', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.round_number)
      from scoring_authority.rounds value where value.tournament_id = '2026'
    ), '[]'::jsonb),
    'matches', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.match_id)
      from scoring_authority.matches value where value.tournament_id = '2026'
    ), '[]'::jsonb),
    'holes', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.match_id, value.hole_number)
      from scoring_authority.hole_scores value
      join scoring_authority.matches match on match.match_id = value.match_id
      where match.tournament_id = '2026'
    ), '[]'::jsonb),
    'permissions', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.match_id, value.player_id)
      from scoring_authority.scoring_permissions value
      join scoring_authority.matches match on match.match_id = value.match_id
      where match.tournament_id = '2026'
    ), '[]'::jsonb),
    'outbox', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.created_at, value.id)
      from scoring_authority.google_outbox_events value where value.tournament_id = '2026'
    ), '[]'::jsonb),
    'archives', coalesce((
      select jsonb_agg(to_jsonb(value) order by value.match_id, value.snapshot_revision)
      from scoring_authority.finalized_scorecard_snapshots value where value.tournament_id = '2026'
    ), '[]'::jsonb)
  )::text, 'sha256'), 'hex')
$$;


ALTER FUNCTION production_rehearsal.current_2026_fingerprint() OWNER TO postgres;

--
-- Name: abandon_production_vercel_provider_attestation_challenge(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abandon_production_vercel_provider_attestation_challenge(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
  attestation production_control.vercel_provider_attestations%rowtype;
  abandon_request_identifier uuid;
  payload_hash text := production_control.cutover_payload_hash(input);
  abandoned_at_value timestamptz;
  abandonment_code_value text;
  expected_reason text;
  allowed_keys text[] := array[
    'environment', 'project_ref', 'project_url', 'source_workbook_id',
    'tournament_id', 'actor_id', 'authenticated_actor_fingerprint',
    'abandon_request_id', 'request_fingerprint', 'challenge_id',
    'challenge_request_id', 'operation_request_id', 'evidence_request_id',
    'stage', 'purpose', 'vercel_project_id', 'vercel_team_id',
    'candidate_deployment_id', 'candidate_deployment_commit',
    'candidate_deployment_target', 'candidate_alias_origin',
    'candidate_immutable_origin', 'routing_rule_id',
    'routing_rule_config_version', 'routing_rule_scope', 'abandonment_reason'
  ];
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if pg_catalog.jsonb_typeof(input) is distinct from 'object'
     or not (input ?& allowed_keys)
     or (input - allowed_keys) is distinct from '{}'::jsonb
     or coalesce(input->>'abandon_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'challenge_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'challenge_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.upper(coalesce(input->>'stage', ''))
       not in ('BEGIN', 'FINALIZE')
     or pg_catalog.upper(coalesce(input->>'purpose', ''))
       not in ('REHEARSAL', 'CUTOVER')
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or coalesce(input->>'vercel_team_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or input->>'candidate_deployment_target' not in ('PREVIEW', 'PRODUCTION')
     or coalesce(input->>'candidate_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_immutable_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'routing_rule_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_config_version', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or input->>'routing_rule_scope' is distinct from
       'PRODUCTION_GOOGLE_CANONICAL_WRITER_QUIESCE'
     or input->>'abandonment_reason' not in (
       'EXPIRED_UNCONSUMED_BEGIN_SUPERSEDED',
       'EXPIRED_UNCONSUMED_FINALIZE_SUPERSEDED',
       'EXPIRED_CONSUMED_UNBOUND_PROVIDER_ATTESTATION_SUPERSEDED'
     ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDON_INPUT_INVALID';
  end if;
  abandon_request_identifier := (input->>'abandon_request_id')::uuid;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.challenge_id = (input->>'challenge_id')::uuid
  for update;
  perform production_control.assert_vercel_provider_challenge_abandon_binding(
    challenge, input
  );
  if challenge.status = 'ABANDONED' then
    if challenge.abandon_request_id is distinct from abandon_request_identifier
       or challenge.abandon_request_fingerprint is distinct from
         input->>'request_fingerprint'
       or challenge.abandon_payload_hash is distinct from payload_hash
       or challenge.abandonment_reason is distinct from
         input->>'abandonment_reason' then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDON_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.vercel_provider_attestation_challenge_response(
      challenge, true
    ) || pg_catalog.jsonb_build_object(
      'abandon_eligible', false, 'abandonment_code', 'ABANDONED',
      'server_observed_at', pg_catalog.clock_timestamp()
    );
  end if;
  if challenge.consumed_attestation_id is not null then
    select * into strict attestation
    from production_control.vercel_provider_attestations value
    where value.attestation_id = challenge.consumed_attestation_id
    for update;
  end if;
  abandoned_at_value := pg_catalog.clock_timestamp();
  abandonment_code_value :=
    production_control.vercel_provider_challenge_abandonment_code(
      challenge, abandoned_at_value
    );
  expected_reason := case
    when abandonment_code_value = 'ELIGIBLE' and challenge.stage = 'BEGIN'
      then 'EXPIRED_UNCONSUMED_BEGIN_SUPERSEDED'
    when abandonment_code_value = 'ELIGIBLE' and challenge.stage = 'FINALIZE'
      then 'EXPIRED_UNCONSUMED_FINALIZE_SUPERSEDED'
    when abandonment_code_value = 'ELIGIBLE_CONSUMED_UNBOUND'
      then 'EXPIRED_CONSUMED_UNBOUND_PROVIDER_ATTESTATION_SUPERSEDED'
    else null
  end;
  if expected_reason is null then
    raise exception using errcode = '55000',
      message = case abandonment_code_value
        when 'NOT_EXPIRED' then
          'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_NOT_EXPIRED'
        when 'CONSUMED_UNBOUND_NOT_EXPIRED' then
          'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BINDING_NOT_EXPIRED'
        when 'BOUND' then
          'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BOUND_ABANDON_FORBIDDEN'
        else
          'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDON_PROGRESSION_CONFLICT'
      end;
  end if;
  if input->>'abandonment_reason' is distinct from expected_reason then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDON_REASON_MISMATCH';
  end if;
  if abandonment_code_value = 'ELIGIBLE_CONSUMED_UNBOUND' then
    update production_control.vercel_provider_attestations
    set status = 'ABANDONED', abandoned_at = abandoned_at_value
    where attestation_id = attestation.attestation_id and status = 'RESERVED'
      and evidence_id is null and receipt_request_fingerprint is null
      and bound_at is null
    returning * into strict attestation;
  end if;
  update production_control.vercel_provider_attestation_challenges
  set status = 'ABANDONED', abandon_request_id = abandon_request_identifier,
      abandon_request_fingerprint = input->>'request_fingerprint',
      abandon_payload_hash = payload_hash,
      abandonment_reason = expected_reason,
      abandoned_at = abandoned_at_value, updated_at = abandoned_at_value
  where challenge_id = challenge.challenge_id
    and status in ('ISSUED', 'CONSUMED')
  returning * into strict challenge;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDONED',
    'SCORING_AUTHORITY', '2026', challenge.actor_id,
    challenge.abandon_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'abandon_request_id', challenge.abandon_request_id,
      'challenge_id', challenge.challenge_id,
      'challenge_request_id', challenge.challenge_request_id,
      'operation_request_id', challenge.operation_request_id,
      'evidence_request_id', challenge.evidence_request_id,
      'consumed_attestation_id', challenge.consumed_attestation_id,
      'stage', challenge.stage, 'purpose', challenge.purpose,
      'candidate_deployment_id', challenge.candidate_deployment_id,
      'candidate_deployment_commit', challenge.candidate_deployment_commit,
      'candidate_deployment_target', challenge.candidate_deployment_target,
      'routing_rule_id', challenge.routing_rule_id,
      'routing_rule_config_version', challenge.routing_rule_config_version,
      'abandonment_reason', challenge.abandonment_reason,
      'abandoned_at', challenge.abandoned_at
    )
  );
  return production_control.vercel_provider_attestation_challenge_response(
    challenge, false
  ) || pg_catalog.jsonb_build_object(
    'abandon_eligible', false, 'abandonment_code', 'ABANDONED',
    'server_observed_at', abandoned_at_value
  );
end;
$_$;


ALTER FUNCTION public.abandon_production_vercel_provider_attestation_challenge(input jsonb) OWNER TO postgres;

