-- Name: abort_production_annual_scoring_transition_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_annual_scoring_transition_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
begin
 perform production_control.assert_annual_transition_platform_owner_v1(input);
 return production_control.canonical_abort_annual_scoring_transition_v2(input,jsonb_build_object('resource_class','PRODUCTION','resource_id','BAGGER_INV_PRODUCTION'));
end;$$;


ALTER FUNCTION public.abort_production_annual_scoring_transition_v1(input jsonb) OWNER TO postgres;

--
-- Name: abort_production_authority_epoch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_authority_epoch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if input->>'boundary_mode' = 'MAINTENANCE_WINDOW_V1' then
    return public.abort_production_maintenance_authority_epoch(input);
  end if;
  return public.abort_production_authority_epoch_provider_fence_v2(input);
end;
$$;


ALTER FUNCTION public.abort_production_authority_epoch(input jsonb) OWNER TO postgres;

--
-- Name: abort_production_authority_epoch_provider_fence_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_authority_epoch_provider_fence_v2(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  prior_legacy_closure production_control.scoring_admission_closures%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform production_control.assert_scoring_admission_optimistic_input(input, true);
  if coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'closure_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_AUTHORITY_ABORT_V2_INPUT_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_cutover_receipt(
    'ABORT_AUTHORITY_EPOCH', input
  );
  if existing is not null then return existing; end if;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = (input->>'epoch_id')::uuid
  for update;
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = (input->>'closure_id')::uuid
  for update;
  if epoch.epoch_type = 'ROLLBACK' then
    select * into strict prior_legacy_closure
    from production_control.scoring_admission_closures value
    where value.closure_id = closure.prior_legacy_closure_id
    for update;
  end if;
  if activation.activation_revision
       is distinct from (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id
       is distinct from (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id
       is distinct from (input->>'expected_admission_generation')::uuid
     or gate.admission_revision
       is distinct from (input->>'expected_admission_revision')::bigint
     or activation.active_transition_epoch_id is distinct from epoch.epoch_id
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or gate.active_closure_id is distinct from closure.closure_id
     or gate.external_fence_evidence_id
       is distinct from (input->>'external_fence_evidence_id')::uuid
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or activation.expected_deployment_commit
       is distinct from input->>'deployment_commit'
     or gate.state is distinct from 'PAUSED'
     or gate.admission_state is distinct from 'CLOSED'
     or closure.status is distinct from 'CLOSED'
     or epoch.status is distinct from 'PREPARED'
     or epoch.admission_closure_id is distinct from closure.closure_id
     or epoch.admission_generation_id
       is distinct from gate.admission_generation_id
     or epoch.closed_admission_revision
       is distinct from gate.admission_revision
     or epoch.external_fence_evidence_id
       is distinct from gate.external_fence_evidence_id
     or (epoch.epoch_type = 'CUTOVER' and (
       activation.state is distinct from 'CUTOVER_PREPARED'
       or activation.current_authority is distinct from 'GOOGLE'
       or activation.scoring_ingress_enabled
       or epoch.authority_before is distinct from 'GOOGLE'
     ))
     or (epoch.epoch_type = 'ROLLBACK' and (
       activation.state is distinct from 'ROLLBACK_PREPARED'
       or activation.current_authority is distinct from 'SUPABASE'
       or not activation.scoring_ingress_enabled
       or epoch.authority_before is distinct from 'SUPABASE'
       or closure.closure_kind is distinct from 'SUPABASE_INGRESS'
       or prior_legacy_closure.closure_kind is distinct from 'LEGACY_ADMISSION'
       or prior_legacy_closure.authority is distinct from 'GOOGLE'
     )) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_AUTHORITY_EPOCH_V2_NOT_ABORTABLE';
  end if;

  update scoring_authority.authority_epochs
  set status = 'ABORTED', aborted_at = pg_catalog.now(),
      reason = pg_catalog.left(coalesce(
        nullif(input->>'reason', ''), reason
      ), 500)
  where epoch_id = epoch.epoch_id;

  if epoch.authority_before = 'SUPABASE' then
    update production_control.scoring_admission_closures
    set status = 'REOPENED', reopened_at = pg_catalog.now()
    where closure_id = closure.closure_id;
    update scoring_authority.ingress_gates
    set state = 'OPEN', authority = 'SUPABASE',
        active_epoch_id = epoch.prior_active_epoch_id,
        admission_state = 'CLOSED',
        admission_revision = admission_revision + 1,
        active_closure_id = prior_legacy_closure.closure_id,
        external_fence_evidence_id =
          (input->>'external_fence_evidence_id')::uuid,
        unresolved_client_queues = 0,
        updated_by = input->>'actor_id', updated_at = pg_catalog.now()
    where tournament_id = '2026'
    returning * into gate;
  else
    -- A CUTOVER abort deliberately leaves legacy Google admission CLOSED.
    -- Only the separately audited Google-only reopen RPC may admit it again.
    update scoring_authority.ingress_gates
    set state = 'PAUSED', authority = 'GOOGLE',
        active_epoch_id = epoch.prior_active_epoch_id,
        admission_state = 'CLOSED',
        unresolved_client_queues = 0,
        updated_by = input->>'actor_id', updated_at = pg_catalog.now()
    where tournament_id = '2026'
    returning * into gate;
  end if;
  update production_control.cutover_activation_state
  set state = case when epoch.authority_before = 'GOOGLE'
        then 'GOOGLE_LEASE_ARMED' else 'SCORING_COMMITTED' end,
      activation_revision = activation_revision + 1,
      expected_source_fingerprint = epoch.prior_source_fingerprint,
      active_transition_epoch_id = null,
      updated_by = input->>'actor_id', updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
  returning * into activation;

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', epoch.epoch_type || '_EPOCH_ABORTED', input->>'actor_id',
    pg_catalog.jsonb_build_object(
      'epoch_id', epoch.epoch_id,
      'closure_id', closure.closure_id,
      'authority', epoch.authority_before,
      'admission_state', gate.admission_state,
      'legacy_google_automatically_reopened', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_AUTHORITY_EPOCH_V2_ABORTED', 'SCORING_AUTHORITY', '2026',
    input->>'actor_id', pg_catalog.lower(input->>'request_fingerprint'),
    'SUCCEEDED', pg_catalog.jsonb_build_object(
      'epoch_id', epoch.epoch_id,
      'closure_id', closure.closure_id,
      'authority', epoch.authority_before,
      'execution_gate', gate.state,
      'admission_state', gate.admission_state,
      'legacy_google_automatically_reopened', false
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_AUTHORITY_EPOCH_V2_ABORTED',
    'epoch_id', epoch.epoch_id,
    'closure_id', closure.closure_id,
    'authority', epoch.authority_before,
    'ingress', gate.state,
    'admission_state', gate.admission_state,
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'admission_revision', gate.admission_revision,
    'legacy_google_automatically_reopened', false,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'ABORT_AUTHORITY_EPOCH', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.abort_production_authority_epoch_provider_fence_v2(input jsonb) OWNER TO postgres;

--
-- Name: abort_production_google_writer_provider_fence_install(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_google_writer_provider_fence_install(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  install_dispatch
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  restore_dispatch
    production_control.google_writer_provider_fence_abort_dispatches%rowtype;
  restore_quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  prior production_control.google_writer_provider_fence_install_aborts%rowtype;
  abort_row production_control.google_writer_provider_fence_install_aborts%rowtype;
  abort_request uuid;
  payload_hash_value text := production_control.cutover_payload_hash(input);
  provider_observed timestamptz;
  next_generation uuid := extensions.gen_random_uuid();
  target_status text;
  response_code text;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'operation' is distinct from
       'ABORT_PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL'
     or coalesce(input->>'fence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'install_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'abort_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'restore_quiesce_evidence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or input->'provider_rollback_verified' is distinct from 'true'::jsonb
     or input->>'restored_legacy_role' is distinct from 'writer'
     or input->'restored_legacy_can_edit' is distinct from 'true'::jsonb
     or input->'restored_legacy_can_share' is distinct from 'true'::jsonb
     or input->'active_run_owned_protection_count' is distinct from '0'::jsonb
     or input->'removed_protected_range_ids' is distinct from '[]'::jsonb
     or coalesce(input->>'restored_provider_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'restored_acl_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'restored_canonical_value_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'restored_combined_value_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'restored_formula_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'restoration_evidence_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESTORE_EVIDENCE_REQUIRED';
  end if;
  abort_request := (input->>'abort_request_id')::uuid;
  provider_observed := (input->>'provider_observed_at')::timestamptz;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into prior
  from production_control.google_writer_provider_fence_install_aborts value
  where value.abort_request_id = abort_request;
  if found then
    if prior.fence_id is distinct from (input->>'fence_id')::uuid
       or prior.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or prior.payload_hash is distinct from payload_hash_value
       or prior.restoration_evidence_fingerprint is distinct from
         pg_catalog.lower(input->>'restoration_evidence_fingerprint')
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESTORE_IDEMPOTENCY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', case when prior.restore_dispatch_id is null
        then 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_ABORTED'
        else 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ACL_RESTORED_AND_REOPENED'
      end,
      'fence_id', prior.fence_id,
      'abort_id', prior.abort_id,
      'abort_request_id', prior.abort_request_id,
      'restore_dispatch_id', prior.restore_dispatch_id,
      'status', case when exists (
        select 1 from production_control.google_writer_provider_fences value
        where value.fence_id = prior.fence_id
          and value.status in (
            'ACL_RESTORED_WAF_ACTIVE', 'REHEARSAL_RESTORED', 'FAILED'
          )
      ) then (
        select value.status
        from production_control.google_writer_provider_fences value
        where value.fence_id = prior.fence_id
      ) else 'ABORTING' end,
      'admission_reservation_active', false,
      'admission_reservation_state', 'RELEASED',
      'critical_window_active', exists (
        select 1
        from production_control.google_writer_provider_fences fence_value
        join production_control.vercel_writer_critical_waf_epochs epoch
          on epoch.epoch_id = fence_value.critical_waf_epoch_id
        where fence_value.fence_id = prior.fence_id
          and epoch.status in ('FENCE_BOUND', 'RESTORE_PENDING')
      ),
      'provider_observed_at', prior.provider_observed_at,
      'aborted_at', prior.aborted_at,
      'idempotent', true
    );
  end if;

  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = (input->>'fence_id')::uuid
    and value.install_request_id = (input->>'install_request_id')::uuid
  for update;
  select * into strict install_dispatch
  from production_control.google_writer_provider_fence_install_dispatches value
  where value.fence_id = fence.fence_id
    and value.outcome_status = 'TARGET_CONFIRMED'
  order by value.attempt desc
  limit 1
  for update;
  select * into strict restore_dispatch
  from production_control.google_writer_provider_fence_abort_dispatches value
  where value.fence_id = fence.fence_id
    and value.outcome_status = 'TARGET_CONFIRMED'
  order by value.attempt desc
  limit 1
  for update;
  select * into strict restore_quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = fence.restore_quiesce_evidence_id
  for update;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  if gate.active_closure_id is not null then
    select * into strict closure
    from production_control.scoring_admission_closures value
    where value.closure_id = gate.active_closure_id
    for update;
  end if;
  if fence.status is distinct from 'ABORTING'
     or fence.abort_request_id is distinct from abort_request
     or fence.restore_quiesce_evidence_id is distinct from
       (input->>'restore_quiesce_evidence_id')::uuid
     or fence.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or fence.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or fence.actor_id is distinct from input->>'actor_id'
     or fence.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
     or restore_quiesce.status is distinct from 'VERIFIED'
     or restore_quiesce.purpose is distinct from fence.lifecycle_mode
     or restore_quiesce.expires_at <= pg_catalog.clock_timestamp()
     or restore_quiesce.owner_freeze_expires_at <= pg_catalog.clock_timestamp()
     or restore_quiesce.candidate_deployment_id is distinct from
       fence.candidate_deployment_id
     or restore_quiesce.candidate_deployment_commit is distinct from
       fence.candidate_deployment_commit
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = restore_quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or provider_observed < pg_catalog.clock_timestamp() - interval '5 seconds'
     or provider_observed > pg_catalog.clock_timestamp() + interval '30 seconds'
     or pg_catalog.lower(input->>'restored_provider_fingerprint') is distinct from
       fence.baseline_provider_fingerprint
     or pg_catalog.lower(input->>'restored_acl_fingerprint') is distinct from
       fence.baseline_acl_fingerprint
     or pg_catalog.lower(input->>'restored_canonical_value_fingerprint')
       is distinct from fence.baseline_canonical_value_fingerprint
     or pg_catalog.lower(input->>'restored_combined_value_fingerprint')
       is distinct from fence.baseline_combined_value_fingerprint
     or pg_catalog.lower(input->>'restored_formula_fingerprint')
       is distinct from fence.baseline_formula_fingerprint
     or pg_catalog.lower(input->>'restoration_evidence_fingerprint')
       is distinct from
         production_control.google_writer_provider_fence_abort_evidence_hash(
           fence.fence_id, input
         )
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or ((activation.first_supabase_write_possible_at is not null
          or activation.first_supabase_write_observed_at is not null) and not (
       fence.lifecycle_mode = 'CUTOVER'
       and fence.abort_origin_status in ('INSTALLED', 'REMOVAL_AUTHORIZED')
       and activation.state = 'ROLLED_BACK'
       and gate.admission_state = 'CLOSED'
       and closure.closure_id is not null
       and closure.status = 'CLOSED'
       and closure.authority = 'GOOGLE'
       and closure.reconciliation_fingerprint ~ '^[0-9a-f]{64}$'
     ))
     or activation.active_transition_epoch_id is not null
     or resource.scoring_authority is distinct from 'GOOGLE'
     or gate.authority is distinct from 'GOOGLE'
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     )
     or (fence.lifecycle_mode = 'CUTOVER' and
       fence.abort_origin_status = 'INSTALLING' and (
         activation.state is distinct from 'GOOGLE_LEASE_ARMED'
         or resource.participant_identity_authority is distinct from 'SUPABASE'
         or resource.current_tournament_read_authority is distinct from 'SUPABASE'
         or gate.state is distinct from 'OPEN'
         or gate.admission_state is distinct from 'OPEN'
         or not gate.admission_protocol_enforced
         or gate.active_closure_id is not null
         or activation.active_google_writer_provider_fence_id is not null
         or gate.google_writer_provider_fence_id is not null
       ))
     or (fence.lifecycle_mode = 'CUTOVER' and
       fence.abort_origin_status in ('INSTALLED', 'REMOVAL_AUTHORIZED') and (
         not (
           (activation.state = 'GOOGLE_LEASE_ARMED'
             and resource.participant_identity_authority = 'SUPABASE'
             and resource.current_tournament_read_authority = 'SUPABASE'
             and gate.state = 'OPEN' and gate.admission_state = 'OPEN'
             and gate.admission_protocol_enforced
             and gate.active_closure_id is null)
           or
           (activation.state in ('DORMANT', 'ROLLED_BACK')
             and resource.participant_identity_authority = 'PASSPORT'
             and resource.current_tournament_read_authority = 'GOOGLE'
             and gate.state = 'PAUSED' and gate.admission_state = 'CLOSED'
             and gate.admission_protocol_enforced
             and gate.active_closure_id is not null)
         )
         or activation.active_google_writer_provider_fence_id is distinct from
           fence.fence_id
         or gate.google_writer_provider_fence_id is distinct from fence.fence_id
       ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       fence.abort_origin_status not in ('INSTALLING', 'INSTALLED')
       or activation.state is distinct from 'DORMANT'
       or resource.participant_identity_authority is distinct from 'PASSPORT'
       or resource.current_tournament_read_authority is distinct from 'GOOGLE'
       or gate.state is distinct from 'PAUSED'
       or (fence.abort_origin_status = 'INSTALLING' and (
         gate.admission_state is distinct from 'OPEN'
         or gate.admission_protocol_enforced
         or gate.active_closure_id is not null
         or activation.active_google_writer_provider_fence_id is not null
         or gate.google_writer_provider_fence_id is not null
       ))
       or (fence.abort_origin_status = 'INSTALLED' and (
         gate.admission_state is distinct from 'CLOSED'
         or not gate.admission_protocol_enforced
         or gate.active_closure_id is null
         or activation.active_google_writer_provider_fence_id is distinct from
           fence.fence_id
         or gate.google_writer_provider_fence_id is distinct from fence.fence_id
       ))
     ))
     or restore_dispatch.outcome_status is distinct from 'TARGET_CONFIRMED'
       or restore_dispatch.target_role is distinct from 'writer'
       or restore_dispatch.transition_proof_fingerprint is distinct from
         fence.acl_writer_restore_transition_fingerprint
       or restore_dispatch.transition_proof is distinct from
         input->'restore_transition_proof'
       or restore_dispatch.transition_proof_fingerprint is distinct from
         pg_catalog.lower(input->>'restore_transition_proof_fingerprint')
       or restore_dispatch.transition_proof->'currentLegacyCanEdit'
         is distinct from 'true'::jsonb
       or restore_dispatch.transition_proof->'currentLegacyCanShare'
         is distinct from 'true'::jsonb
       or restore_dispatch.provider_observed_at > provider_observed
       or pg_catalog.clock_timestamp() <
         fence.restore_global_writer_stop_active_at + interval '1810 seconds'
     or install_dispatch.outcome_status is distinct from 'TARGET_CONFIRMED'
     or (gate.admission_state = 'CLOSED' and (
       closure.closure_id is null or closure.status is distinct from 'CLOSED'
       or closure.authority is distinct from 'GOOGLE'
     ))
     or gate.admission_state not in ('OPEN', 'CLOSED')
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESTORE_NOT_SAFE';
  end if;

  if gate.admission_state = 'CLOSED' then
    update production_control.scoring_admission_closures
    set status = 'REOPENED', reopened_at = pg_catalog.clock_timestamp()
    where closure_id = closure.closure_id;
    update scoring_authority.ingress_gates
    set state = case when fence.lifecycle_mode = 'REHEARSAL'
          then 'PAUSED' else 'OPEN' end,
        admission_state = 'OPEN',
        admission_protocol_enforced = case
          when activation.state in ('DORMANT', 'ROLLED_BACK') then false
          else admission_protocol_enforced end,
        admission_enforced_at = case when fence.lifecycle_mode = 'REHEARSAL'
          then null else admission_enforced_at end,
        admission_deployment_id = case when fence.lifecycle_mode = 'REHEARSAL'
          then null else admission_deployment_id end,
        legacy_lease_set_fingerprint = case
          when fence.lifecycle_mode = 'REHEARSAL' then null
          else legacy_lease_set_fingerprint end,
        admission_revision = admission_revision + 1,
        admission_generation_id = next_generation,
        admission_opened_at = case when fence.lifecycle_mode = 'REHEARSAL'
          then null else pg_catalog.clock_timestamp() end,
        active_closure_id = null, external_fence_evidence_id = null,
        google_writer_provider_fence_id = null,
        google_writer_provider_verification_id = null,
        unresolved_client_queues = 0,
        updated_by = pg_catalog.left(input->>'actor_id', 160),
        updated_at = pg_catalog.clock_timestamp()
    where tournament_id = '2026'
    returning * into gate;
    update production_control.cutover_activation_state
    set activation_revision = activation_revision + 1,
        active_google_writer_provider_fence_id = null,
        active_google_writer_provider_verification_id = null,
        active_vercel_quiesce_evidence_id = null,
        updated_by = pg_catalog.left(input->>'actor_id', 160),
        updated_at = pg_catalog.clock_timestamp()
    where scope_key = 'BAGGER_INV_PRODUCTION'
    returning * into activation;
  elsif (gate.google_writer_provider_fence_id is not null and
         gate.google_writer_provider_fence_id is distinct from fence.fence_id)
     or (activation.active_google_writer_provider_fence_id is not null and
         activation.active_google_writer_provider_fence_id is distinct from
           fence.fence_id) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESTORE_OPEN_POINTER_MISMATCH';
  else
    update scoring_authority.ingress_gates
    set google_writer_provider_fence_id = null,
        google_writer_provider_verification_id = null,
        updated_by = pg_catalog.left(input->>'actor_id', 160),
        updated_at = pg_catalog.clock_timestamp()
    where tournament_id = '2026'
    returning * into gate;
    update production_control.cutover_activation_state
    set active_google_writer_provider_fence_id = null,
        active_google_writer_provider_verification_id = null,
        active_vercel_quiesce_evidence_id = null,
        activation_revision = activation_revision + 1,
        updated_by = pg_catalog.left(input->>'actor_id', 160),
        updated_at = pg_catalog.clock_timestamp()
    where scope_key = 'BAGGER_INV_PRODUCTION'
    returning * into activation;
  end if;

  target_status := 'ACL_RESTORED_WAF_ACTIVE';
  response_code :=
    'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ACL_RESTORED_WAF_ACTIVE';
  insert into production_control.google_writer_provider_fence_install_aborts (
    abort_id, fence_id, abort_request_id, request_fingerprint, payload_hash,
    restoration_evidence_fingerprint, removed_protected_range_ids,
    active_run_owned_protection_count, restored_provider_fingerprint,
    restored_acl_fingerprint, restored_canonical_value_fingerprint,
    restored_combined_value_fingerprint, restored_formula_fingerprint,
    restore_dispatch_id, restore_quiesce_evidence_id,
    restored_legacy_role, restored_legacy_can_edit, restored_legacy_can_share,
    restore_transition_proof, restore_transition_proof_fingerprint,
    provider_observed_at, activation_revision, authority_generation_id,
    admission_generation_id, admission_revision, actor_id,
    authenticated_actor_fingerprint
  ) values (
    extensions.gen_random_uuid(), fence.fence_id, abort_request,
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
    pg_catalog.lower(input->>'restoration_evidence_fingerprint'), '[]'::jsonb,
    0, pg_catalog.lower(input->>'restored_provider_fingerprint'),
    pg_catalog.lower(input->>'restored_acl_fingerprint'),
    pg_catalog.lower(input->>'restored_canonical_value_fingerprint'),
    pg_catalog.lower(input->>'restored_combined_value_fingerprint'),
    pg_catalog.lower(input->>'restored_formula_fingerprint'),
    restore_dispatch.dispatch_id, restore_quiesce.evidence_id,
    'writer', true, true, restore_dispatch.transition_proof,
    restore_dispatch.transition_proof_fingerprint, provider_observed,
    activation.activation_revision, activation.authority_generation_id,
    gate.admission_generation_id, gate.admission_revision,
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'authenticated_actor_fingerprint')
  ) returning * into abort_row;

  update production_control.google_writer_provider_fences
  set status = target_status,
      failure_code = null,
      acl_restored_waf_active_at = pg_catalog.clock_timestamp(),
      rehearsal_restored_at = null,
      updated_at = pg_catalog.clock_timestamp()
  where fence_id = fence.fence_id;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result,
    details
  ) values (
    response_code, 'SCORING_AUTHORITY', '2026', abort_row.actor_id,
    abort_row.request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'fence_id', fence.fence_id,
      'abort_id', abort_row.abort_id,
      'restore_dispatch_id', abort_row.restore_dispatch_id,
      'restore_transition_proof_fingerprint',
        abort_row.restore_transition_proof_fingerprint,
      'restore_quiesce_evidence_id', abort_row.restore_quiesce_evidence_id,
      'restored_legacy_role', abort_row.restored_legacy_role,
      'restored_legacy_can_edit', abort_row.restored_legacy_can_edit,
      'restored_legacy_can_share', abort_row.restored_legacy_can_share,
      'admission_state', gate.admission_state,
      'admission_reservation_active', false,
      'critical_window_active', true,
      'baseline_restored', false
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'code', response_code,
    'fence_id', fence.fence_id,
    'abort_id', abort_row.abort_id,
    'abort_request_id', abort_row.abort_request_id,
    'restore_dispatch_id', abort_row.restore_dispatch_id,
    'status', target_status,
    'authority', activation.current_authority,
    'admission_state', gate.admission_state,
    'execution_gate', gate.state,
    'admission_reservation_active', false,
    'admission_reservation_state', 'RELEASED',
    'critical_window_active', true,
    'baseline_restored', false,
    'critical_waf_epoch_id', fence.critical_waf_epoch_id,
    'provider_observed_at', abort_row.provider_observed_at,
    'aborted_at', abort_row.aborted_at,
    'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.abort_production_google_writer_provider_fence_install(input jsonb) OWNER TO postgres;

--
-- Name: abort_production_maintenance_authority_epoch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_maintenance_authority_epoch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  next_generation uuid := extensions.gen_random_uuid();
  verified_at timestamptz;
  response_value jsonb;
begin
  perform production_control.assert_maintenance_common_input(input);
  if coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or coalesce(input->>'google_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_ABORT_INPUT_INVALID';
  end if;
  verified_at := (input->>'google_source_captured_at')::timestamptz;
  existing := production_control.lookup_cutover_receipt(
    'ABORT_MAINTENANCE_AUTHORITY_EPOCH', input
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select * into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = (input->>'epoch_id')::uuid for update;
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = epoch.admission_closure_id for update;
  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.maintenance_state <> 'SCORING_MAINTENANCE'
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.state <> 'CUTOVER_PREPARED'
     or activation.active_transition_epoch_id is distinct from epoch.epoch_id
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.state <> 'PAUSED' or gate.admission_state <> 'CLOSED'
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or gate.active_closure_id is distinct from closure.closure_id
     or epoch.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or epoch.status <> 'PREPARED' or epoch.epoch_type <> 'CUTOVER'
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.status <> 'CLOSED'
     or pg_catalog.lower(input->>'google_source_fingerprint')
       is distinct from closure.final_source_fingerprint
     or verified_at < epoch.created_at or verified_at > pg_catalog.now()
     or verified_at < pg_catalog.now() - interval '5 minutes' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_ABORT_NOT_SAFE';
  end if;
  update scoring_authority.authority_epochs
  set status = 'ABORTED', aborted_at = pg_catalog.now(),
      reason = pg_catalog.left(coalesce(input->>'reason', reason), 500)
  where epoch_id = epoch.epoch_id;
  update production_control.scoring_admission_closures
  set status = 'REOPENED', reopened_at = pg_catalog.now()
  where closure_id = closure.closure_id;
  update scoring_authority.ingress_gates
  set boundary_mode = 'MAINTENANCE_WINDOW_V1',
      state = 'OPEN', authority = 'GOOGLE', active_epoch_id = null,
      admission_state = 'OPEN', admission_revision = admission_revision + 1,
      admission_generation_id = next_generation,
      admission_opened_at = pg_catalog.now(), active_closure_id = null,
      external_fence_evidence_id = null,
      google_writer_provider_fence_id = null,
      google_writer_provider_verification_id = null,
      unresolved_client_queues = 0,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' returning * into gate;
  update production_control.cutover_activation_state
  set state = 'GOOGLE_LEASE_ARMED', maintenance_state = 'NORMAL',
      maintenance_ended_at = pg_catalog.now(),
      activation_revision = activation_revision + 1,
      active_transition_epoch_id = null,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION' returning * into activation;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_MAINTENANCE_AUTHORITY_EPOCH_ABORTED',
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'epoch_id', epoch.epoch_id, 'closure_id', closure.closure_id,
    'authority', 'GOOGLE', 'ingress', 'OPEN',
    'admission_state', 'OPEN', 'maintenance_state', 'NORMAL',
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'admission_revision', gate.admission_revision,
    'first_supabase_canonical_write_possible', false,
    'first_supabase_canonical_write_observed', false,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'ABORT_MAINTENANCE_AUTHORITY_EPOCH', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.abort_production_maintenance_authority_epoch(input jsonb) OWNER TO postgres;

--
-- Name: abort_production_precommit_release(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_precommit_release(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  existing jsonb;
  gate scoring_authority.ingress_gates%rowtype;
  response_value jsonb;
  was_enforced boolean;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  -- Fixed global order: Odds lock first, admission lock second.
  perform pg_catalog.pg_advisory_xact_lock(731102026031::bigint);
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_cutover_receipt(
    'ABORT_PRECOMMIT_RELEASE', input
  );
  if existing is not null then return existing; end if;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  was_enforced := gate.admission_protocol_enforced;
  if was_enforced and (
       gate.admission_state is distinct from 'OPEN'
       or gate.active_closure_id is not null
       or gate.external_fence_evidence_id is not null
       or production_control.scoring_admission_unresolved_count(
         gate.admission_generation_id
       ) <> 0
       or production_control.scoring_admission_legacy_blocker_count(
         gate.admission_enforced_at
       ) <> 0
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_PRECOMMIT_ABORT_ADMISSION_V2_UNRESOLVED';
  end if;

  response_value := public.abort_production_precommit_release_legacy_v1(input);
  if was_enforced then
    update scoring_authority.ingress_gates
    set admission_state = 'OPEN',
        admission_revision = admission_revision + 1,
        admission_generation_id = extensions.gen_random_uuid(),
        admission_protocol_enforced = false,
        admission_enforced_at = null,
        admission_opened_at = null,
        admission_deployment_id = null,
        legacy_lease_set_fingerprint = null,
        active_closure_id = null,
        external_fence_evidence_id = null,
        unresolved_client_queues = 0,
        updated_by = input->>'actor_id',
        updated_at = pg_catalog.now()
    where tournament_id = '2026';
  end if;
  return response_value;
end;
$$;


ALTER FUNCTION public.abort_production_precommit_release(input jsonb) OWNER TO postgres;

--
-- Name: abort_production_precommit_release_legacy_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_precommit_release_legacy_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'participant_identity', 'production_rehearsal'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  runtime production_control.odds_calculation_runtime%rowtype;
  prior_state text;
  expected_revision bigint;
  expected_generation uuid;
  active_lease_count integer;
  expired_lease_count integer;
  expired_shadow_claim_count integer;
  request_fingerprint_value text := lower(coalesce(input->>'request_fingerprint', ''));
  deployment_commit_value text := lower(coalesce(input->>'deployment_commit', ''));
  source_fingerprint_value text := lower(coalesce(input->>'source_fingerprint', ''));
  actor text := left(coalesce(input->>'actor_id', ''), 160);
  response_value jsonb;
begin
  -- A non-staged assertion is intentional: an identical retry must be able to
  -- replay its durable receipt after the first transaction reached DORMANT.
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  existing := production_control.lookup_cutover_receipt(
    'ABORT_PRECOMMIT_RELEASE', input
  );
  if existing is not null then return existing; end if;

  if input->>'contract_version'
       is distinct from 'production-cutover-activation-v1'
     or input->>'operation'
       is distinct from 'ABORT_PRODUCTION_PRECOMMIT_RELEASE'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'project_ref' is distinct from 'ymqhhtxaywtqllynrmxe'
     or input->>'project_url'
       is distinct from 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or input->>'source_workbook_id'
       is distinct from '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or input->>'tournament_id' is distinct from '2026'
     or jsonb_typeof(input->'tournament_year') is distinct from 'number'
     or input->>'tournament_year' <> '2026'
     or input->>'vercel_project' is distinct from 'bagger-inv'
     or input->>'vercel_project_id'
       is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'canonical_domain' is distinct from 'https://baggerinv.com'
     or deployment_commit_value !~ '^[0-9a-f]{40}$'
     or source_fingerprint_value !~ '^[0-9a-f]{64}$'
     or input ? 'candidate_hostname'
     or jsonb_typeof(input->'expected_activation_revision')
       is distinct from 'number'
     or input->>'expected_activation_revision' !~ '^[1-9][0-9]*$'
     or coalesce(input->>'expected_epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or request_fingerprint_value !~ '^[0-9a-f]{64}$'
     or actor = '' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_PRECOMMIT_ABORT_EXACT_INPUT_REQUIRED';
  end if;
  expected_revision := (input->>'expected_activation_revision')::bigint;
  expected_generation := (input->>'expected_epoch_id')::uuid;

  -- Enabled Odds operations hold the shared counterpart. Taking the exclusive
  -- lock waits for an in-flight operation and prevents a new one from passing
  -- its scope assertion while this release is cleared.
  perform pg_catalog.pg_advisory_xact_lock(731102026031::bigint);

  -- Authority/scoring operations take the activation row before their mutable
  -- dependants. Once held, no read, identity, lease-begin, or epoch transition
  -- can race the proof below. resource_scope is intentionally an MVCC read:
  -- the Odds runtime transition takes resource -> activation, so taking both
  -- rows here in the reverse order would create a lock-order inversion. A
  -- runtime transition that already holds resource must still obtain this
  -- activation row and will fail its optimistic revision after this commit.
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict runtime
  from production_control.odds_calculation_runtime
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;

  -- A concurrent identical abort may have completed while this transaction
  -- waited. Replay its receipt instead of treating DORMANT as a conflict.
  existing := production_control.lookup_cutover_receipt(
    'ABORT_PRECOMMIT_RELEASE', input
  );
  if existing is not null then return existing; end if;

  if activation.state not in ('STAGED', 'GOOGLE_LEASE_ARMED')
     or activation.activation_revision <> expected_revision
     or activation.authority_generation_id <> expected_generation
     or activation.expected_deployment_commit
       is distinct from deployment_commit_value
     or activation.expected_vercel_project_id
       is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or activation.expected_source_fingerprint
       is distinct from source_fingerprint_value then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_PRECOMMIT_ABORT_REVISION_CONFLICT';
  end if;
  prior_state := activation.state;

  -- Read rollback intentionally retains the certified source fingerprint.
  -- Accept only NULL (never activated) or the exact staged fingerprint; any
  -- other value is unexplained drift.
  if activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.read_cutover_phase <> 'STATIC_BACKEND'
     or (
       activation.read_source_fingerprint is not null
       and activation.read_source_fingerprint
         is distinct from activation.expected_source_fingerprint
     )
     or activation.public_reads_activated_at is not null
     or activation.active_transition_epoch_id is not null
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.first_supabase_mutation_key is not null
     or activation.first_supabase_match_id is not null
     or activation.first_supabase_match_revision is not null
     or exists (
       select 1 from scoring_authority.authority_epochs epoch
       where epoch.tournament_id = '2026' and epoch.status = 'PREPARED'
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PRECOMMIT_ABORT_PREWRITE_STATE_REQUIRED';
  end if;

  if resource.current_tournament_read_authority <> 'GOOGLE'
     or resource.scoring_authority <> 'GOOGLE'
     or resource.participant_identity_authority <> 'PASSPORT'
     or resource.public_supabase_reads_enabled
     or resource.scoring_ingress_enabled
     or resource.google_writes_enabled
     or resource.auth_user_creation_enabled
     or resource.workers_enabled
     or resource.odds_publication_enabled
     or exists (
       select 1 from production_control.worker_controls worker
       where worker.enabled or worker.scheduler_installed
         or worker.google_writes_allowed
     )
     or exists (
       select 1 from production_control.worker_contracts contract
       where contract.operation_allowed or contract.scheduler_installed
         or contract.authoritative_write_allowed
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PRECOMMIT_ABORT_DORMANT_AUTHORITY_REQUIRED';
  end if;

  if runtime.enabled
     or runtime.operation_mode <> 'DORMANT'
     or runtime.cutover_phase is not null
     or runtime.deployment_commit is not null
     or runtime.activation_revision is not null
     or runtime.candidate_hostname is not null then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PRECOMMIT_ABORT_ODDS_RUNTIME_DORMANT_REQUIRED';
  end if;

  -- complete_production_scoring_ingress takes lease -> gate. Lock every ACTIVE
  -- lease before taking the gate row so an already-running completion can
  -- finish and no gate/lease inversion is possible. New lease creation is
  -- already blocked by the activation row above.
  perform lease.lease_id
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = '2026' and lease.status = 'ACTIVE'
  order by lease.lease_id
  for update;

  -- A crashed caller may leave a lease row ACTIVE beyond its bounded expiry.
  -- Mark only those elapsed leases terminal; never cancel a live lease.
  update scoring_authority.scoring_ingress_leases
  set status = 'EXPIRED', completed_at = now()
  where tournament_id = '2026' and status = 'ACTIVE' and expires_at <= now();
  get diagnostics expired_lease_count = row_count;

  -- This claim type has an explicit EXPIRED terminal state and its claim RPC
  -- performs the same bounded transition. Other operational rows without an
  -- established expiry contract remain blockers and must use their audited
  -- owner cleanup workflow.
  update production_control.current_shadow_import_claims
  set status = 'EXPIRED'
  where tournament_id = '2026' and status = 'PENDING' and expires_at <= now();
  get diagnostics expired_shadow_claim_count = row_count;

  select count(*)::integer into active_lease_count
  from scoring_authority.scoring_ingress_leases
  where tournament_id = '2026' and status = 'ACTIVE' and expires_at > now();

  select * into strict gate
  from scoring_authority.ingress_gates
  where tournament_id = '2026'
  for update;
  if gate.authority <> 'GOOGLE'
     or gate.active_epoch_id is not null
     or (prior_state = 'STAGED' and gate.state <> 'PAUSED')
     or (prior_state = 'GOOGLE_LEASE_ARMED' and gate.state <> 'OPEN') then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PRECOMMIT_ABORT_PREWRITE_STATE_REQUIRED';
  end if;
  update scoring_authority.ingress_gates
  set unresolved_client_queues = active_lease_count, updated_at = now()
  where tournament_id = '2026';
  if active_lease_count <> 0 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_PRECOMMIT_ABORT_ACTIVE_GOOGLE_LEASES';
  end if;

  -- Wait for transactions that already own a modifying table lock, then hold
  -- their start surfaces stable until this abort commits.
  lock table scoring_authority.authority_epochs,
    scoring_authority.scoring_ingress_leases,
    scoring_authority.google_outbox_events,
    scoring_authority.scorecard_archive_jobs,
    scoring_authority.odds_calculation_jobs,
    scoring_authority.odds_google_mirror_jobs,
    scoring_authority.guide_sync_runs,
    production_control.import_runs,
    production_control.current_shadow_import_claims,
    participant_identity.production_participant_enrollment_claims,
    production_rehearsal.scoring_runs
  in share mode;

  if exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026' and lease.status = 'ACTIVE'
     )
     or exists (
       select 1 from scoring_authority.google_outbox_events event
       where event.tournament_id = '2026' and event.status <> 'DELIVERED'
     )
     or exists (
       select 1 from scoring_authority.scorecard_archive_jobs job
       where job.tournament_id = '2026'
         and job.status not in ('VERIFIED', 'SUPERSEDED')
     )
     or exists (
       select 1 from scoring_authority.odds_calculation_jobs job
       where job.tournament_id = '2026'
         and (job.status in ('PENDING', 'RUNNING', 'RETRYABLE')
           or job.publication_status in ('READY', 'PUBLISHED'))
     )
     or exists (
       select 1 from scoring_authority.odds_google_mirror_jobs job
       where job.tournament_id = '2026' and job.status in ('PENDING', 'RUNNING')
     )
     or exists (
       select 1 from scoring_authority.guide_sync_runs run
       where run.tournament_id = '2026' and run.status = 'CLAIMED'
     )
     or exists (
       select 1 from production_control.import_runs run
       where run.tournament_id = '2026' and run.status in ('PENDING', 'RUNNING')
     )
     or exists (
       select 1 from production_control.current_shadow_import_claims claim
       where claim.tournament_id = '2026' and claim.status = 'PENDING'
     )
     or exists (
       select 1
       from participant_identity.production_participant_enrollment_claims claim
       where claim.tournament_id = '2026'
         and claim.status in ('PENDING', 'CLEANUP_REQUIRED')
     )
     or exists (
       select 1 from production_rehearsal.scoring_runs run
       where run.status in ('PREPARED', 'ACTIVE')
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_PRECOMMIT_ABORT_PENDING_WORK';
  end if;

  -- This is the only state change: close the lease gate and forget the exact
  -- abandoned candidate. Canonical authority remains Google throughout.
  update scoring_authority.ingress_gates
  set state = 'PAUSED', authority = 'GOOGLE', active_epoch_id = null,
      unresolved_client_queues = 0,
      updated_by = actor, updated_at = now()
  where tournament_id = '2026';

  update production_control.cutover_activation_state
  set state = 'DORMANT',
      activation_revision = activation_revision + 1,
      expected_deployment_commit = null,
      expected_vercel_project_id = null,
      expected_source_fingerprint = null,
      active_transition_epoch_id = null,
      staged_by = null,
      staged_at = null,
      read_cutover_phase = 'STATIC_BACKEND',
      read_source_fingerprint = null,
      public_reads_activated_at = null,
      first_supabase_write_possible_at = null,
      first_supabase_write_observed_at = null,
      first_supabase_mutation_key = null,
      first_supabase_match_id = null,
      first_supabase_match_revision = null,
      updated_by = actor,
      updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
    and state = prior_state
    and activation_revision = expected_revision
  returning * into activation;
  if not found or activation.activation_revision <> expected_revision + 1 then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_PRECOMMIT_ABORT_REVISION_CONFLICT';
  end if;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_PRECOMMIT_RELEASE_ABORTED', 'SCORING_AUTHORITY', '2026',
    actor, request_fingerprint_value, 'SUCCEEDED',
    jsonb_build_object(
      'prior_state', prior_state,
      'state', 'DORMANT',
      'prior_activation_revision', expected_revision,
      'activation_revision', activation.activation_revision,
      'deployment_commit', deployment_commit_value,
      'source_fingerprint', source_fingerprint_value,
      'authority', 'GOOGLE',
      'participant_identity_authority', 'PASSPORT',
      'read_cutover_phase', 'STATIC_BACKEND',
      'google_lease_gate', 'PAUSED',
      'active_google_leases', 0,
      'expired_google_leases', expired_lease_count,
      'expired_shadow_import_claims', expired_shadow_claim_count,
      'first_supabase_canonical_write_possible', false,
      'first_supabase_canonical_write_observed', false,
      'staged_candidate_fields_cleared', true,
      'authority_generation_preserved', true,
      'no_automatic_fallback', true
    )
  );

  response_value := jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_PRECOMMIT_RELEASE_ABORTED',
    'prior_state', prior_state,
    'state', 'DORMANT',
    'activation_revision', activation.activation_revision,
    'epoch_id', activation.authority_generation_id,
    'authority', 'GOOGLE',
    'participant_identity_authority', 'PASSPORT',
    'read_cutover_phase', 'STATIC_BACKEND',
    'google_lease_gate', 'PAUSED',
    'active_google_leases', 0,
    'expired_google_leases', expired_lease_count,
    'expired_shadow_import_claims', expired_shadow_claim_count,
    'scoring_ingress_enabled', false,
    'public_supabase_reads_enabled', false,
    'workers_enabled', false,
    'publication_enabled', false,
    'mirror_enabled', false,
    'google_writes_enabled', false,
    'first_supabase_canonical_write_possible', false,
    'first_supabase_canonical_write_observed', false,
    'staged_candidate_fields_cleared', true,
    'authority_generation_preserved', true,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'ABORT_PRECOMMIT_RELEASE', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.abort_production_precommit_release_legacy_v1(input jsonb) OWNER TO postgres;

--
-- Name: abort_production_scoring_maintenance_preprepare(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_scoring_maintenance_preprepare(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  next_generation uuid := extensions.gen_random_uuid();
  aborted_at timestamptz;
  response_value jsonb;
begin
  perform production_control.assert_maintenance_common_input(input);
  existing := production_control.lookup_cutover_receipt(
    'ABORT_SCORING_MAINTENANCE_PREPREPARE', input
  );
  if existing is not null then return existing; end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  perform production_control.assert_no_active_physical_writer_fence();

  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;

  if gate.active_closure_id is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_PREPREPARE_ABORT_NOT_SAFE';
  end if;

  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = gate.active_closure_id for update;

  perform lease.lease_id
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = '2026'
    and (
      lease.protocol_version = 'LEGACY_V1'
      or lease.admission_generation_id = gate.admission_generation_id
    )
  order by lease.lease_id for update;

  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.maintenance_state <> 'SCORING_MAINTENANCE'
     or activation.state <> 'GOOGLE_LEASE_ARMED'
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.first_supabase_mutation_key is not null
     or activation.first_supabase_match_id is not null
     or activation.first_supabase_match_revision is not null
     or activation.active_transition_epoch_id is not null
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or resource.scoring_authority <> 'GOOGLE'
     or resource.scoring_ingress_enabled
     or resource.workers_enabled
     or resource.google_writes_enabled
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'GOOGLE'
     or gate.state <> 'PAUSED'
     or gate.admission_state not in ('CLOSING', 'CLOSED')
     or not gate.admission_protocol_enforced
     or gate.active_epoch_id is not null
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or gate.unresolved_client_queues <> 0
     or gate.external_fence_evidence_id is not null
     or gate.google_writer_provider_fence_id is not null
     or gate.google_writer_provider_verification_id is not null
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.closure_kind <> 'LEGACY_ADMISSION'
     or closure.prior_legacy_closure_id is not null
     or closure.authority <> 'GOOGLE'
     or closure.status is distinct from gate.admission_state
     or closure.authority_generation_id is distinct from
       activation.authority_generation_id
     or closure.admission_generation_id is distinct from
       gate.admission_generation_id
     or closure.deployment_id is distinct from gate.admission_deployment_id
     or closure.opening_admission_revision >= gate.admission_revision
     or closure.closing_admission_revision > gate.admission_revision
     or (
       closure.status = 'CLOSED'
       and closure.closed_admission_revision is distinct from
         gate.admission_revision
     )
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
     or exists (
       select 1
       from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026'
         and lease.protocol_version = 'ADMISSION_V2'
         and lease.admission_generation_id = gate.admission_generation_id
         and lease.admission_sequence > closure.lease_high_watermark
     )
     or exists (
       select 1
       from scoring_authority.authority_epochs epoch
       where epoch.tournament_id = '2026' and epoch.status = 'PREPARED'
     )
     or exists (
       select 1
       from scoring_authority.google_outbox_events event
       where event.tournament_id = '2026' and event.status <> 'DELIVERED'
     )
     or exists (
       select 1
       from scoring_authority.scorecard_archive_jobs job
       where job.tournament_id = '2026'
         and job.status not in ('VERIFIED', 'SUPERSEDED')
     )
     or exists (
       select 1
       from production_control.worker_controls controls
       where controls.enabled
     )
     or not exists (
       select 1
       from scoring_authority.tournaments tournament
       where tournament.tournament_id = '2026'
         and tournament.scoring_authority = 'GOOGLE'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_PREPREPARE_ABORT_NOT_SAFE';
  end if;

  aborted_at := pg_catalog.now();

  update production_control.scoring_admission_closures
  set status = 'REOPENED', reopened_at = aborted_at
  where closure_id = closure.closure_id;

  update scoring_authority.ingress_gates
  set boundary_mode = 'MAINTENANCE_WINDOW_V1',
      state = 'OPEN', authority = 'GOOGLE', active_epoch_id = null,
      admission_state = 'OPEN',
      admission_revision = admission_revision + 1,
      admission_generation_id = next_generation,
      admission_opened_at = aborted_at, active_closure_id = null,
      external_fence_evidence_id = null,
      google_writer_provider_fence_id = null,
      google_writer_provider_verification_id = null,
      unresolved_client_queues = 0,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = aborted_at
  where tournament_id = '2026' returning * into gate;

  update production_control.cutover_activation_state
  set state = 'GOOGLE_LEASE_ARMED', maintenance_state = 'NORMAL',
      maintenance_ended_at = aborted_at,
      activation_revision = activation_revision + 1,
      active_transition_epoch_id = null,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = aborted_at
  where scope_key = 'BAGGER_INV_PRODUCTION' returning * into activation;

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_SCORING_MAINTENANCE_PREPREPARE_ABORTED',
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'closure_id', closure.closure_id,
    'activation_state', activation.state,
    'authority', activation.current_authority,
    'maintenance_state', activation.maintenance_state,
    'execution_gate', gate.state,
    'admission_state', gate.admission_state,
    'scoring_ingress_enabled', activation.scoring_ingress_enabled,
    'workers_enabled', resource.workers_enabled,
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'admission_revision', gate.admission_revision,
    'first_supabase_canonical_write_possible', false,
    'first_supabase_canonical_write_observed', false,
    'idempotent', false
  );

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_SCORING_MAINTENANCE_PREPREPARE_ABORTED',
    'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );

  perform production_control.store_cutover_receipt(
    'ABORT_SCORING_MAINTENANCE_PREPREPARE', input, response_value
  );
  return response_value;
end;
$$;


ALTER FUNCTION public.abort_production_scoring_maintenance_preprepare(input jsonb) OWNER TO postgres;

--
-- Name: abort_production_staged_release(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.abort_production_staged_release(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'participant_identity', 'production_rehearsal'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  runtime production_control.odds_calculation_runtime%rowtype;
  expected_revision bigint;
  request_fingerprint_value text := coalesce(input->>'request_fingerprint', '');
  deployment_commit_value text := coalesce(input->>'deployment_commit', '');
  source_fingerprint_value text := coalesce(input->>'source_fingerprint', '');
  actor text := left(coalesce(input->>'actor_id', ''), 160);
  response_value jsonb;
begin
  -- The shared assertion proves the service-role JWT and the immutable
  -- Production project/workbook/tournament resource row. A non-staged lookup is
  -- intentional so an already-committed receipt can be replayed safely after
  -- the successful transition has made the activation row DORMANT.
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  existing := production_control.lookup_cutover_receipt(
    'ABORT_STAGED_RELEASE', input
  );
  if existing is not null then return existing; end if;

  if input->>'contract_version'
       is distinct from 'production-cutover-activation-v1'
     or input->>'operation'
       is distinct from 'ABORT_PRODUCTION_STAGED_RELEASE'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'project_ref' is distinct from 'ymqhhtxaywtqllynrmxe'
     or input->>'project_url'
       is distinct from 'https://ymqhhtxaywtqllynrmxe.supabase.co'
     or input->>'source_workbook_id'
       is distinct from '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or input->>'tournament_id' is distinct from '2026'
     or jsonb_typeof(input->'tournament_year') is distinct from 'number'
     or input->>'tournament_year' <> '2026'
     or input->>'vercel_project' is distinct from 'bagger-inv'
     or input->>'vercel_project_id'
       is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'canonical_domain' is distinct from 'https://baggerinv.com'
     or deployment_commit_value !~ '^[0-9a-f]{40}$'
     or source_fingerprint_value !~ '^[0-9a-f]{64}$'
     or input ? 'candidate_hostname'
     or jsonb_typeof(input->'expected_activation_revision')
       is distinct from 'number'
     or input->>'expected_activation_revision' !~ '^[1-9][0-9]*$'
     or request_fingerprint_value !~ '^[0-9a-f]{64}$'
     or actor = '' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_STAGED_RELEASE_ABORT_EXACT_INPUT_REQUIRED';
  end if;
  expected_revision := (input->>'expected_activation_revision')::bigint;

  -- Wait for every enabled Odds RPC transaction to finish, then prevent a new
  -- one from passing its shared scope lock until this abort commits.
  perform pg_catalog.pg_advisory_xact_lock(731102026031::bigint);

  -- Lock the activation boundary before inspecting every dependent control.
  -- All authority-changing RPCs take this row before their dependent state, so
  -- no later phase, epoch, worker, or ingress transition can race this abort.
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict gate
  from scoring_authority.ingress_gates
  where tournament_id = '2026'
  for update;
  select * into strict runtime
  from production_control.odds_calculation_runtime
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;

  -- Runtime disable and this activation-row lock prevent a new rehearsal
  -- request from starting. These table locks also wait for any transaction
  -- that passed its runtime check before disable and make the following
  -- pending-work proof stable until this abort commits.
  lock table scoring_authority.authority_epochs,
    scoring_authority.scoring_ingress_leases,
    scoring_authority.google_outbox_events,
    scoring_authority.scorecard_archive_jobs,
    scoring_authority.odds_calculation_jobs,
    scoring_authority.odds_google_mirror_jobs,
    scoring_authority.guide_sync_runs,
    production_control.import_runs,
    production_control.current_shadow_import_claims,
    participant_identity.production_participant_enrollment_claims,
    production_rehearsal.scoring_runs
  in share mode;

  -- A concurrent identical abort may have completed while this transaction
  -- waited for the activation row. Replay its durable receipt rather than
  -- treating the now-DORMANT state as a conflict.
  existing := production_control.lookup_cutover_receipt(
    'ABORT_STAGED_RELEASE', input
  );
  if existing is not null then return existing; end if;

  if activation.state <> 'STAGED'
     or activation.activation_revision <> expected_revision
     or activation.expected_deployment_commit
       is distinct from deployment_commit_value
     or activation.expected_vercel_project_id
       is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or activation.expected_source_fingerprint
       is distinct from source_fingerprint_value then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_STAGED_RELEASE_ABORT_REVISION_CONFLICT';
  end if;

  -- Read rollback intentionally retains the certified source fingerprint.
  -- Accept only NULL (never activated) or the exact staged fingerprint; any
  -- other value remains unexplained drift and fails closed.
  if activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.read_cutover_phase <> 'STATIC_BACKEND'
     or (
       activation.read_source_fingerprint is not null
       and activation.read_source_fingerprint
         is distinct from activation.expected_source_fingerprint
     )
     or activation.public_reads_activated_at is not null
     or activation.active_transition_epoch_id is not null
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.first_supabase_mutation_key is not null
     or activation.first_supabase_match_id is not null
     or activation.first_supabase_match_revision is not null
     or gate.state <> 'PAUSED'
     or gate.authority <> 'GOOGLE'
     or gate.active_epoch_id is not null
     or gate.unresolved_client_queues <> 0
     or exists (
       select 1 from scoring_authority.authority_epochs epoch
       where epoch.tournament_id = '2026' and epoch.status = 'PREPARED'
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STAGED_RELEASE_ABORT_PRECUTOVER_STATE_REQUIRED';
  end if;

  if resource.current_tournament_read_authority <> 'GOOGLE'
     or resource.scoring_authority <> 'GOOGLE'
     or resource.participant_identity_authority <> 'PASSPORT'
     or resource.public_supabase_reads_enabled
     or resource.scoring_ingress_enabled
     or resource.google_writes_enabled
     or resource.auth_user_creation_enabled
     or resource.workers_enabled
     or resource.odds_publication_enabled
     or exists (
       select 1 from production_control.worker_controls worker
       where worker.enabled or worker.scheduler_installed
         or worker.google_writes_allowed
     )
     or exists (
       select 1 from production_control.worker_contracts contract
       where contract.operation_allowed or contract.scheduler_installed
         or contract.authoritative_write_allowed
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STAGED_RELEASE_ABORT_DORMANT_AUTHORITY_REQUIRED';
  end if;

  if runtime.enabled
     or runtime.operation_mode <> 'DORMANT'
     or runtime.cutover_phase is not null
     or runtime.deployment_commit is not null
     or runtime.activation_revision is not null
     or runtime.candidate_hostname is not null then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STAGED_RELEASE_ABORT_ODDS_RUNTIME_DORMANT_REQUIRED';
  end if;

  -- Terminal history may remain, but nothing claimable, retryable, publishable,
  -- mirrorable, or awaiting cleanup may survive the staged-release abort.
  if exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026' and lease.status = 'ACTIVE'
     )
     or exists (
       select 1 from scoring_authority.google_outbox_events event
       where event.tournament_id = '2026' and event.status <> 'DELIVERED'
     )
     or exists (
       select 1 from scoring_authority.scorecard_archive_jobs job
       where job.tournament_id = '2026'
         and job.status not in ('VERIFIED', 'SUPERSEDED')
     )
     or exists (
       select 1 from scoring_authority.odds_calculation_jobs job
       where job.tournament_id = '2026'
         and (job.status in ('PENDING', 'RUNNING', 'RETRYABLE')
           or job.publication_status in ('READY', 'PUBLISHED'))
     )
     or exists (
       select 1 from scoring_authority.odds_google_mirror_jobs job
       where job.tournament_id = '2026' and job.status in ('PENDING', 'RUNNING')
     )
     or exists (
       select 1 from scoring_authority.guide_sync_runs run
       where run.tournament_id = '2026' and run.status = 'CLAIMED'
     )
     or exists (
       select 1 from production_control.import_runs run
       where run.tournament_id = '2026' and run.status in ('PENDING', 'RUNNING')
     )
     or exists (
       select 1 from production_control.current_shadow_import_claims claim
       where claim.tournament_id = '2026' and claim.status = 'PENDING'
     )
     or exists (
       select 1
       from participant_identity.production_participant_enrollment_claims claim
       where claim.tournament_id = '2026'
         and claim.status in ('PENDING', 'CLEANUP_REQUIRED')
     )
     or exists (
       select 1 from production_rehearsal.scoring_runs run
       where run.status in ('PREPARED', 'ACTIVE')
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_STAGED_RELEASE_ABORT_PENDING_WORK';
  end if;

  update production_control.cutover_activation_state
  set state = 'DORMANT',
      activation_revision = activation_revision + 1,
      expected_deployment_commit = null,
      expected_vercel_project_id = null,
      expected_source_fingerprint = null,
      active_transition_epoch_id = null,
      staged_by = null,
      staged_at = null,
      read_cutover_phase = 'STATIC_BACKEND',
      read_source_fingerprint = null,
      public_reads_activated_at = null,
      updated_by = actor,
      updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
    and state = 'STAGED'
    and activation_revision = expected_revision
  returning * into activation;
  if not found or activation.activation_revision <> expected_revision + 1 then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_STAGED_RELEASE_ABORT_REVISION_CONFLICT';
  end if;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_STAGED_RELEASE_ABORTED', 'SCORING_AUTHORITY', '2026',
    actor, request_fingerprint_value, 'SUCCEEDED',
    jsonb_build_object(
      'prior_state', 'STAGED',
      'state', 'DORMANT',
      'prior_activation_revision', expected_revision,
      'activation_revision', activation.activation_revision,
      'deployment_commit', deployment_commit_value,
      'source_fingerprint', source_fingerprint_value,
      'authority', 'GOOGLE',
      'read_cutover_phase', 'STATIC_BACKEND',
      'participant_identity_authority', 'PASSPORT',
      'scoring_ingress_enabled', false,
      'public_supabase_reads_enabled', false,
      'auth_user_creation_enabled', false,
      'workers_enabled', false,
      'odds_publication_enabled', false,
      'google_mirror_enabled', false,
      'google_writes_enabled', false,
      'first_supabase_canonical_write_possible', false,
      'first_supabase_canonical_write_observed', false,
      'active_or_prepared_epochs', 0,
      'pending_operational_work', 0,
      'staged_candidate_fields_cleared', true
    )
  );

  response_value := jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_STAGED_RELEASE_ABORTED',
    'state', 'DORMANT',
    'activation_revision', activation.activation_revision,
    'authority', 'GOOGLE',
    'read_cutover_phase', 'STATIC_BACKEND',
    'participant_identity_authority', 'PASSPORT',
    'scoring_ingress_enabled', false,
    'public_supabase_reads_enabled', false,
    'workers_enabled', false,
    'publication_enabled', false,
    'mirror_enabled', false,
    'google_writes_enabled', false,
    'first_supabase_canonical_write_possible', false,
    'first_supabase_canonical_write_observed', false,
    'staged_candidate_fields_cleared', true,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'ABORT_STAGED_RELEASE', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.abort_production_staged_release(input jsonb) OWNER TO postgres;

--
-- Name: activate_production_annual_scoring_transition_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.activate_production_annual_scoring_transition_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
begin
 perform production_control.assert_annual_transition_platform_owner_v1(input);
 return production_control.canonical_activate_annual_scoring_transition_v2(input,jsonb_build_object('resource_class','PRODUCTION','resource_id','BAGGER_INV_PRODUCTION'));
end;$$;


ALTER FUNCTION public.activate_production_annual_scoring_transition_v1(input jsonb) OWNER TO postgres;

--
-- Name: activate_production_participant_identity(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.activate_production_participant_identity(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $$
declare resource production_control.resource_scope%rowtype;
declare activation production_control.cutover_activation_state%rowtype;
declare existing jsonb;
declare response_value jsonb;
declare enrollment_inspection jsonb;
declare active_roster_count integer;
declare enrolled_count integer;
declare not_enrolled_count integer;
declare expected_revision bigint;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  existing := production_control.lookup_cutover_receipt(
    'ACTIVATE_PARTICIPANT_IDENTITY', input
  );
  if existing is not null then return existing; end if;
  if input->>'contract_version'
       is distinct from 'production-participant-identity-cutover-v2'
     or upper(coalesce(input->>'phase', '')) <> 'IDENTITY'
     or coalesce(input->>'actor_id', '') = '' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_IDENTITY_ACTIVATION_SCOPE_REQUIRED';
  end if;
  expected_revision := coalesce(
    (input->>'expected_activation_revision')::bigint, -1
  );
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION' for update;
  -- The activation-row lock serializes a concurrent replay. Re-check the
  -- receipt after acquiring it so the second caller returns the first result.
  existing := production_control.lookup_cutover_receipt(
    'ACTIVATE_PARTICIPANT_IDENTITY', input
  );
  if existing is not null then return existing; end if;
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION' for update;
  if activation.activation_revision <> expected_revision
     or activation.state = 'DORMANT'
     or activation.expected_deployment_commit
       is distinct from input->>'deployment_commit'
     or resource.scoring_authority <> 'GOOGLE'
     or resource.scoring_ingress_enabled then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_IDENTITY_ACTIVATION_STATE_MISMATCH';
  end if;

  enrollment_inspection := production_control
    .build_production_participant_identity_enrollment_inspection();
  active_roster_count := coalesce(
    (enrollment_inspection->>'activeRosterCount')::integer, 0
  );
  enrolled_count := coalesce(
    (enrollment_inspection->>'enrolledCount')::integer, 0
  );
  not_enrolled_count := coalesce(
    (enrollment_inspection->>'notEnrolledCount')::integer, 0
  );
  if resource.participant_identity_authority = 'SUPABASE'
     and resource.auth_user_creation_enabled then
    response_value := pg_catalog.jsonb_build_object(
      'ok', true,
      'authority', 'SUPABASE',
      'authUserCreationEnabled', true,
      'enrollmentPolicy', 'APPROVED_PARTIAL_ROSTER',
      'approvedParticipants', enrolled_count,
      'activeRosterCount', active_roster_count,
      'enrolledCount', enrolled_count,
      'notEnrolledCount', not_enrolled_count,
      'activeRosterParticipants', active_roster_count,
      'enrolledParticipants', enrolled_count,
      'notEnrolledParticipants', not_enrolled_count,
      'activationRevision', activation.activation_revision,
      'idempotent', true
    );
    perform production_control.store_cutover_receipt(
      'ACTIVATE_PARTICIPANT_IDENTITY', input, response_value
    );
    return response_value;
  end if;
  if resource.participant_identity_authority <> 'PASSPORT'
     or resource.auth_user_creation_enabled then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_IDENTITY_ACTIVATION_DRIFT';
  end if;
  if not coalesce(
    (enrollment_inspection->>'activationEligible')::boolean, false
  ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_IDENTITY_APPROVED_PARTIAL_ROSTER_REQUIRED';
  end if;

  update production_control.resource_scope set
    participant_identity_authority = 'SUPABASE',
    auth_user_creation_enabled = true,
    updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update production_control.cutover_activation_state set
    activation_revision = activation_revision + 1,
    updated_by = left(input->>'actor_id', 160),
    updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
  returning * into activation;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_PARTICIPANT_IDENTITY_ACTIVATED',
    'PARTICIPANT_IDENTITY', '2026',
    left(input->>'actor_id', 160),
    lower(input->>'request_fingerprint'), 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'authority', 'SUPABASE',
      'enrollmentPolicy', 'APPROVED_PARTIAL_ROSTER',
      'approvedParticipants', enrolled_count,
      'activeRosterCount', active_roster_count,
      'enrolledCount', enrolled_count,
      'notEnrolledCount', not_enrolled_count,
      'activeRosterParticipants', active_roster_count,
      'enrolledParticipants', enrolled_count,
      'notEnrolledParticipants', not_enrolled_count,
      'authUserCreationEnabled', true,
      'scoringAuthorityChanged', false,
      'activationRevision', activation.activation_revision,
      'cutoverState', activation.state
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'authority', 'SUPABASE',
    'enrollmentPolicy', 'APPROVED_PARTIAL_ROSTER',
    'approvedParticipants', enrolled_count,
    'activeRosterCount', active_roster_count,
    'enrolledCount', enrolled_count,
    'notEnrolledCount', not_enrolled_count,
    'activeRosterParticipants', active_roster_count,
    'enrolledParticipants', enrolled_count,
    'notEnrolledParticipants', not_enrolled_count,
    'authUserCreationEnabled', true,
    'activationRevision', activation.activation_revision,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'ACTIVATE_PARTICIPANT_IDENTITY', input, response_value
  );
  return response_value;
end;
$$;


ALTER FUNCTION public.activate_production_participant_identity(input jsonb) OWNER TO postgres;

--
-- Name: admin_link_auth_user_to_player(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_link_auth_user_to_player(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'scoring_authority', 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare user_id uuid := nullif(input->>'auth_user_id', '')::uuid;
declare target_player text := btrim(coalesce(input->>'player_id', ''));
declare target_tournament text := btrim(coalesce(input->>'tournament_id', ''));
declare actor text := btrim(coalesce(input->>'linked_by', ''));
declare contact participant_identity.participant_identity_contacts%rowtype;
declare auth_user auth.users%rowtype;
declare existing participant_identity.user_player_links%rowtype;
declare existing_identifier participant_identity.participant_auth_identifiers%rowtype;
declare inserted_id uuid;
declare identifier_status text;
begin
  if user_id is null or target_player = '' or target_tournament = '' or actor = '' then
    raise exception 'Complete link administration context is required.';
  end if;
  select * into auth_user from auth.users where id = user_id;
  if not found then raise exception 'Auth user does not exist.'; end if;
  select * into contact from participant_identity.participant_identity_contacts
    where tournament_id = target_tournament and player_id = target_player and identity_active;
  if not found then raise exception 'Approved active participant identity contact is required.'; end if;
  if lower(btrim(coalesce(auth_user.email, ''))) <> contact.email_normalized then
    raise exception 'Approved Auth user email does not match Participant Identity ownership.';
  end if;
  identifier_status := case when auth_user.email_confirmed_at is not null then 'VERIFIED' else 'ELIGIBLE' end;

  select * into existing from participant_identity.user_player_links
    where auth_user_id = user_id or (player_id = target_player and status in ('PENDING', 'ACTIVE', 'SUSPENDED')) limit 1;
  if found then
    if existing.auth_user_id <> user_id or existing.player_id <> target_player
      or existing.email_identity_hash <> encode(extensions.digest(contact.email_normalized::text, 'sha256'::text), 'hex') then
      raise exception 'Existing Auth user or Player link requires an explicit audited link-change operation.';
    end if;
    select * into existing_identifier
    from participant_identity.participant_auth_identifiers
    where player_id = target_player and identifier_type = 'EMAIL'
      and status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED');
    if found and (existing_identifier.auth_user_id <> user_id
      or existing_identifier.normalized_value_private <> contact.email_normalized) then
      raise exception 'Existing email identifier requires an explicit audited ownership change.';
    end if;
    if not found then
      insert into participant_identity.participant_auth_identifiers (
        player_id, auth_user_id, identifier_type, normalized_value_private, status,
        verified_at, verification_source, source_system, source_tournament_id,
        source_configuration_revision, created_by, updated_by
      ) values (
        target_player, user_id, 'EMAIL', contact.email_normalized, identifier_status,
        auth_user.email_confirmed_at,
        case when auth_user.email_confirmed_at is not null then 'SUPABASE_AUTH_EMAIL_CONFIRMED' else null end,
        'PARTICIPANT_IDENTITY_EMAIL_COMPATIBILITY', target_tournament,
        contact.configuration_revision, actor, actor
      );
    end if;
    return jsonb_build_object('ok', true, 'created', false, 'linkId', existing.link_id, 'status', existing.status);
  end if;

  insert into participant_identity.user_player_links (
    auth_user_id, player_id, status, link_method, email_identity_hash, linked_at, linked_by
  ) values (
    user_id, target_player, 'ACTIVE', 'DIRECTOR_APPROVED_EMAIL',
    encode(extensions.digest(contact.email_normalized::text, 'sha256'::text), 'hex'), now(), actor
  ) returning link_id into inserted_id;

  insert into participant_identity.participant_auth_identifiers (
    player_id, auth_user_id, identifier_type, normalized_value_private, status,
    verified_at, verification_source, source_system, source_tournament_id,
    source_configuration_revision, created_by, updated_by
  ) values (
    target_player, user_id, 'EMAIL', contact.email_normalized, identifier_status,
    auth_user.email_confirmed_at,
    case when auth_user.email_confirmed_at is not null then 'SUPABASE_AUTH_EMAIL_CONFIRMED' else null end,
    'PARTICIPANT_IDENTITY_EMAIL_COMPATIBILITY', target_tournament,
    contact.configuration_revision, actor, actor
  );

  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_name, link_revision, safe_metadata
  ) values (
    'AUTH_USER_LINKED', target_tournament, user_id, target_player, actor, 1,
    jsonb_build_object('emailIdentifierCreated', true, 'emailValueStoredInAudit', false)
  );
  return jsonb_build_object('ok', true, 'created', true, 'linkId', inserted_id, 'status', 'ACTIVE');
end;
$$;


ALTER FUNCTION public.admin_link_auth_user_to_player(input jsonb) OWNER TO postgres;

--
-- Name: admit_certification_operation_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admit_certification_operation_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare r production_control.canonical_resource_v1%rowtype;i jsonb;ctx jsonb;phase text;hash text;
 l production_control.certification_ingress_leases_v1%rowtype;g production_control.certification_ingress_generations_v1%rowtype;
 m scoring_authority.matches%rowtype;
begin
 r:=production_control.certification_ingress_recovery_resource_v1(input);
 i:=jsonb_build_object('operation_id',input->>'operation_id','operation_request_id',input->>'operation_request_id',
  'target_key',case when input->>'operation_id'like'SCORING.%'or input->>'operation_id'='DIRECTOR.MATCH_CONTROL'
  then'MATCH:'||(input#>>'{payload,match_id}')else'TOURNAMENT'end);
 if jsonb_typeof(input->'payload')is distinct from 'object'or input->'payload'?|array['resource','deployment','authorization','environment','project_ref','project_url',
 'actor_player_id','actor_auth_user_id','auth_user_id','role','context_token','expected_context_token','binding_id','resource_id','resource_class',
 'installation_id','release_commit','activation_revision','admission_revision','governance_tournament_id']
 or(input->'payload'?'player_id'and not coalesce(input->>'operation_id'='DIRECTOR.CLEAR_CALCUTTA_AUCTION'
  or(input->>'operation_id'='DIRECTOR.MUTATE_SETUP'and input#>>'{payload,action}'='assign-roster-team'),false))then
  raise exception using errcode='42501',message='CERTIFICATION_INGRESS_PAYLOAD_INVALID';end if;
 -- Match mutation keys share canonical receipt identity across all four families.
 -- Serialize their admission before any row exists; other families retain their
 -- existing operation-specific namespace.
 perform pg_advisory_xact_lock(hashtextextended(r.resource_id||':'||
  case when i->>'operation_id'in('SCORING.SUBMIT_HOLE','SCORING.FINALIZE_MATCH','SCORING.REOPEN_MATCH','DIRECTOR.MATCH_CONTROL')
   then 'MATCH_MUTATION'else i->>'operation_id'end||':'||(i->>'target_key')||':'||(i->>'operation_request_id'),19361));
 l:=production_control.certification_ingress_lookup_v1(input||jsonb_build_object('verify_request',true),true);
 if l.lease_id is not null then return production_control.certification_ingress_response_v1(l);end if;
 if coalesce((input->>'replay_only')::boolean,false)then
  return jsonb_build_object('ok',true,'contract','certification-ingress-v1','state','UNKNOWN','lease_id',null,'operation_request_id',i->>'operation_request_id');end if;
 phase:=production_control.certification_operation_phase_v1(input->>'operation_id',true);
 ctx:=production_control.push_certification_context_v1(input,phase,true);
 i:=production_control.certification_ingress_identity_v1(input);
 hash:=production_control.certification_ingress_request_hash_v1(input,i);
 if i->>'tournament_id'is distinct from ctx->>'tournament_id'then raise exception using errcode='42501',message='CERTIFICATION_INGRESS_TARGET_DENIED';end if;
 if(input#>>'{payload,tournament_id}'is not null and input#>>'{payload,tournament_id}'is distinct from ctx->>'tournament_id')
  or(input#>>'{payload,expected_epoch_id}'is not null and input#>>'{payload,expected_epoch_id}'is distinct from ctx->>'authority_epoch_id')
  or(input->>'operation_id'like'SCORING.%'and input#>>'{payload,mutation_key}'is distinct from input->>'operation_request_id')then
  raise exception using errcode='42501',message='CERTIFICATION_INGRESS_TARGET_DENIED';end if;
 select * into strict g from production_control.certification_ingress_generations_v1 where resource_id=r.resource_id and state='OPEN'for share;
 if g.tournament_id is distinct from ctx->>'tournament_id'or g.authority_epoch_id::text is distinct from ctx->>'authority_epoch_id'
  or g.pointer_revision::text is distinct from ctx->>'pointer_revision'then
  raise exception using errcode='40001',message='CERTIFICATION_INGRESS_GENERATION_STALE';end if;
 if i->>'match_id'is not null then
  select * into strict m from scoring_authority.matches where match_id=i->>'match_id'and tournament_id=g.tournament_id for share;
  if i->>'actor_role'='PLAYER'and not exists(select 1 from scoring_authority.scoring_permissions p
   where p.match_id=m.match_id and p.player_id=i->>'actor_player_id'and p.can_score and p.revoked_at is null
    and p.permission_revision=m.permission_revision
    and p.permission_revision::text=input#>>'{authorization,permission_revision}')then
   raise exception using errcode='42501',message='CERTIFICATION_INGRESS_PERMISSION_DENIED';end if;
 end if;
 if i->>'operation_id'in('SCORING.SUBMIT_HOLE','SCORING.FINALIZE_MATCH','SCORING.REOPEN_MATCH','DIRECTOR.MATCH_CONTROL')
  and exists(select 1 from production_control.certification_ingress_leases_v1 existing
   where existing.resource_id=r.resource_id and existing.target_key=i->>'target_key'
    and existing.operation_request_id=i->>'operation_request_id'and existing.operation_id<>i->>'operation_id'
    and existing.operation_id in('SCORING.SUBMIT_HOLE','SCORING.FINALIZE_MATCH','SCORING.REOPEN_MATCH','DIRECTOR.MATCH_CONTROL'))then
  raise exception using errcode='40001',message='CERTIFICATION_INGRESS_IDEMPOTENCY_CONFLICT';end if;
 l.resource_id:=r.resource_id;l.tournament_id:=g.tournament_id;l.operation_id:=i->>'operation_id';
 l.operation_request_id:=i->>'operation_request_id';l.match_id:=i->>'match_id';l.domain_action:=input#>>'{payload,action}';
 if production_control.certification_ingress_canonical_receipt_v1(l)is not null then
  raise exception using errcode='40001',message='CERTIFICATION_INGRESS_EXISTING_RECEIPT_REQUIRES_RECOVERY';end if;
 insert into production_control.certification_ingress_leases_v1(resource_id,admission_generation_id,tournament_id,authority_epoch_id,
 operation_id,operation_request_id,target_key,match_id,domain_action,actor_auth_user_id,actor_player_id,actor_role,request_hash,context_token,admission_context,predecessor_auction_revision)
 values(r.resource_id,g.generation_id,g.tournament_id,g.authority_epoch_id,i->>'operation_id',i->>'operation_request_id',i->>'target_key',
 i->>'match_id',input#>>'{payload,action}',(i->>'actor_auth_user_id')::uuid,i->>'actor_player_id',i->>'actor_role',hash,ctx->>'context_token',
  ctx-array['authorization','actor_auth_user_id','actor_player_id','resource','deployment'],case when i->>'operation_id'in('DIRECTOR.REPLACE_CALCUTTA_AUCTION','DIRECTOR.CLEAR_CALCUTTA_AUCTION')
   then(input#>>'{payload,expected_auction_revision}')::bigint else null end)returning * into l;
 insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
 values('CERTIFICATION_INGRESS_ADMITTED','CERTIFICATION',l.tournament_id,l.actor_player_id,hash,'SUCCEEDED',
 jsonb_build_object('resource_id',r.resource_id,'generation_id',g.generation_id,'lease_id',l.lease_id,'operation_id',l.operation_id,
 'operation_request_id',l.operation_request_id,'admission_sequence',l.admission_sequence));
 perform production_control.pop_certification_context_v1();return production_control.certification_ingress_response_v1(l);
exception when no_data_found then raise exception using errcode='55000',message='CERTIFICATION_INGRESS_AUTHORITY_UNAVAILABLE';
end;$$;


ALTER FUNCTION public.admit_certification_operation_v1(input jsonb) OWNER TO postgres;

--
-- Name: adopt_initial_production_owner_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.adopt_initial_production_owner_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority'
    AS $_$
declare
  database_owner text;
  claim_role text;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'actor_player_id', ''
  )));
  actor_auth uuid;
  operation_request uuid;
  expected_revision bigint;
  expected_entitlement_id uuid;
  expected_entitlement_event_id bigint;
  expected_entitlement_event_count bigint;
  actual_entitlement_event_id bigint;
  actual_entitlement_event_count bigint;
  current_revision bigint;
  next_revision bigint;
  declared_hash text := pg_catalog.lower(coalesce(
    input->>'request_payload_hash', ''
  ));
  database_hash text;
  receipt production_control.access_governance_operation_receipts_v1%rowtype;
  entitlement_value production_control.director_entitlements%rowtype;
  response_value jsonb;
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason', ''));
begin
  select pg_catalog.pg_get_userbyid(database_value.datdba)
    into strict database_owner
  from pg_catalog.pg_database database_value
  where database_value.datname = pg_catalog.current_database();
  claim_role := coalesce(
    nullif(pg_catalog.current_setting('request.jwt.claim.role', true), ''),
    nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb
      ->>'role'
  );
  if not pg_catalog.pg_has_role(
       session_user, database_owner, 'member'
     )
     or claim_role is not null then
    raise exception using errcode = '42501',
      message = 'ACCESS_GOVERNANCE_DATABASE_OWNER_SESSION_REQUIRED';
  end if;
  if input->>'contract_version' is distinct from
       'production-access-governance-v1'
     or input->>'environment' is distinct from 'PRODUCTION'
     or input->>'tournament_id' is distinct from '2026'
     or input->>'action' is distinct from 'INITIAL_OWNER_ADOPTION' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ACCESS_GOVERNANCE_SCOPE_REQUIRED';
  end if;
  perform
    production_control.assert_initial_owner_adoption_resource_scope_v1(input);
  perform production_control.assert_production_handicap_runtime();
  perform production_control.assert_access_governance_safe_reason_v1(
    reason_value
  );
  begin
    actor_auth := (input->>'actor_auth_user_id')::uuid;
    operation_request := (input->>'operation_request_id')::uuid;
    expected_revision := (input->>'expected_revision')::bigint;
    expected_entitlement_id := (input->>'expected_entitlement_id')::uuid;
    expected_entitlement_event_id :=
      (input->>'expected_entitlement_event_id')::bigint;
    expected_entitlement_event_count :=
      (input->>'expected_entitlement_event_count')::bigint;
  exception when others then
    raise exception using errcode = '22023',
      message = 'ACCESS_GOVERNANCE_INITIAL_OWNER_INPUT_INVALID';
  end;
  database_hash := production_control.access_governance_hash_v1(
    input - 'request_payload_hash'
  );
  if declared_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'ACCESS_GOVERNANCE_PAYLOAD_HASH_REQUIRED';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-access-governance-v1:2026', 0
  ));
  select value.* into receipt
  from production_control.access_governance_operation_receipts_v1 value
  where value.tournament_id = '2026'
    and value.operation = 'INITIAL_OWNER_ADOPTION'
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.database_request_payload_hash = database_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    raise exception using errcode = '40001',
      message = 'ACCESS_GOVERNANCE_IDEMPOTENCY_CONFLICT';
  end if;
  current_revision := production_control.access_governance_revision_v1('2026');
  if current_revision <> expected_revision then
    raise exception using errcode = '40001',
      message = 'ACCESS_GOVERNANCE_REVISION_STALE';
  end if;
  if exists (
    select 1
    from production_control.tournament_owner_capabilities_v1 owner_value
    where owner_value.tournament_id = '2026'
  ) then
    raise exception using errcode = '55000',
      message = 'ACCESS_GOVERNANCE_OWNER_ALREADY_ADOPTED';
  end if;
  if not exists (
    select 1 from scoring_authority.tournament_players membership
    where membership.tournament_id = '2026'
      and membership.player_id = actor_player
      and membership.participation_status = 'ACTIVE'
  ) or not exists (
    select 1
    from participant_identity.user_player_links link
    join auth.users auth_user on auth_user.id = link.auth_user_id
    where link.player_id = actor_player
      and link.auth_user_id = actor_auth
      and link.status = 'ACTIVE'
      and (auth_user.email_confirmed_at is not null
        or auth_user.phone_confirmed_at is not null)
      and exists (
        select 1
        from participant_identity.participant_auth_identifiers identifier
        where identifier.auth_user_id = link.auth_user_id
          and identifier.player_id = link.player_id
          and identifier.status = 'VERIFIED'
      )
  ) then
    raise exception using errcode = '55000',
      message = 'ACCESS_GOVERNANCE_OWNER_IDENTITY_NOT_READY';
  end if;
  select value.* into entitlement_value
  from production_control.director_entitlements value
  where value.tournament_id = '2026'
    and value.player_id = actor_player
    and value.auth_user_id = actor_auth
    and value.status = 'ACTIVE'
    and value.role = 'DIRECTOR';
  if not found then
    raise exception using errcode = '55000',
      message = 'ACCESS_GOVERNANCE_ACTIVE_DIRECTOR_REQUIRED';
  end if;
  select pg_catalog.count(*)::bigint, coalesce(pg_catalog.max(
      event.event_id
    ), 0)::bigint
    into actual_entitlement_event_count, actual_entitlement_event_id
  from production_control.director_entitlement_events event
  where event.entitlement_id = entitlement_value.entitlement_id;
  if entitlement_value.entitlement_id is distinct from expected_entitlement_id
     or actual_entitlement_event_id is distinct from
       expected_entitlement_event_id
     or actual_entitlement_event_count is distinct from
       expected_entitlement_event_count then
    raise exception using errcode = '40001',
      message = 'ACCESS_GOVERNANCE_ENTITLEMENT_EVIDENCE_STALE';
  end if;

  insert into production_control.tournament_owner_capabilities_v1 (
    tournament_id, player_id, auth_user_id, adopted_from_entitlement_id,
    adopted_entitlement_event_id, adopted_entitlement_event_count,
    status, capability_revision, adopted_by_player_id, adopted_at
  ) values (
    '2026', actor_player, actor_auth, entitlement_value.entitlement_id,
    actual_entitlement_event_id, actual_entitlement_event_count, 'ACTIVE', 1,
    actor_player, pg_catalog.clock_timestamp()
  );

  next_revision := current_revision + 1;
  insert into production_control.access_governance_context_v1 (
    tournament_id, revision, updated_by_player_id, updated_by_auth_user_id
  ) values (
    '2026', next_revision, actor_player, actor_auth
  ) on conflict (tournament_id) do update set
    revision = excluded.revision,
    updated_by_player_id = excluded.updated_by_player_id,
    updated_by_auth_user_id = excluded.updated_by_auth_user_id,
    updated_at = pg_catalog.clock_timestamp();
  insert into production_control.access_governance_audit_events_v1 (
    tournament_id, action, target_player_id, actor_player_id,
    prior_revision, next_revision, operation_request_id, result, safe_metadata
  ) values (
    '2026', 'OWNER_ADOPTED', actor_player, actor_player,
    current_revision, next_revision, operation_request, 'CHANGED',
    pg_catalog.jsonb_build_object(
      'capability', 'OWNER', 'reason', reason_value,
      'entitlement_event_count', actual_entitlement_event_count,
      'entitlement_evidence_bound', true,
      'membership_changed', false, 'identity_changed', false
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_ACCESS_GOVERNANCE_INITIAL_OWNER_ADOPTED',
    'playerId', actor_player,
    'revision', next_revision,
    'idempotent', false
  );
  insert into production_control.access_governance_operation_receipts_v1 (
    tournament_id, operation, operation_request_id,
    declared_request_payload_hash, database_request_payload_hash,
    actor_player_id, actor_auth_user_id, response
  ) values (
    '2026', 'INITIAL_OWNER_ADOPTION', operation_request,
    declared_hash, database_hash, actor_player, actor_auth, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.adopt_initial_production_owner_v1(input jsonb) OWNER TO postgres;

--
-- Name: adopt_production_future_google_destination_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.adopt_production_future_google_destination_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  receipt production_control.future_google_writer_certification_receipts_v1%rowtype;
  target_id text := pg_catalog.btrim(coalesce(
    input->>'target_tournament_id', ''
  ));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  operation_id uuid;
  expected_resource_revision bigint;
  expected_setup_revision bigint;
  database_hash text;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash', ''
  )));
  result_value jsonb;
begin
  perform production_control.assert_future_runtime_service_scope_v2(
    input, true, true
  );
  if input->>'action' is distinct from 'ADOPT_ANNUAL_GOOGLE_DESTINATION'
     or input ?| array[
       'destination_workbook_id', 'annual_destination_workbook_id',
       'target_workbook_id', 'writer_destination_workbook_id'
     ] then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_GOOGLE_DESTINATION_INPUT_INVALID';
  end if;
  begin
    actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
    operation_id := (input->>'operation_request_id')::uuid;
    expected_resource_revision :=
      (input->>'expected_resource_revision')::bigint;
    expected_setup_revision :=
      (input->>'expected_setup_revision')::bigint;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_GOOGLE_DESTINATION_INPUT_INVALID';
  end;
  if target_id !~ '^[0-9]{4}$' or target_id <= '2026'
     or expected_resource_revision <= 0 or expected_setup_revision < 0 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_GOOGLE_DESTINATION_INPUT_INVALID';
  end if;
  perform production_control.assert_access_governance_safe_reason_v1(
    input->>'reason'
  );
  database_hash := production_control.future_runtime_hash_v2(
    input - 'request_payload_hash'
  );
  if declared_hash !~ '^[0-9a-f]{64}$'
     or declared_hash <> database_hash then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_HASH_INVALID';
  end if;
  select value.* into receipt
  from production_control.future_google_writer_certification_receipts_v1 value
  where value.action = 'ADOPT_ANNUAL_GOOGLE_DESTINATION'
    and value.operation_request_id = operation_id;
  if receipt.receipt_id is not null then
    if receipt.database_request_payload_hash <> database_hash
       or receipt.declared_request_payload_hash <> declared_hash then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_IDEMPOTENCY_CONFLICT';
    end if;
    return receipt.response || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'annual-google-writer-certification:' || target_id, 0
    )
  );
  select value.* into receipt
  from production_control.future_google_writer_certification_receipts_v1 value
  where value.action = 'ADOPT_ANNUAL_GOOGLE_DESTINATION'
    and value.operation_request_id = operation_id;
  if receipt.receipt_id is not null then
    if receipt.database_request_payload_hash <> database_hash
       or receipt.declared_request_payload_hash <> declared_hash then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_IDEMPOTENCY_CONFLICT';
    end if;
    return receipt.response || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;
  select value.* into strict scope
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target_id
  for update;
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target_id
  for update;
  if pointer.tournament_id = target_id
     or catalog.lifecycle not in ('DRAFT', 'CONFIGURING')
     or catalog.setup_revision <> expected_setup_revision
     or resource.resource_revision <> expected_resource_revision
     or resource.resource_status <> 'ANNUAL_RESOURCE_REQUIRED'
     or resource.source_workbook_id is not null
     or resource.google_compatibility_policy <> 'PROVISIONING_REQUIRED'
     or resource.project_ref is distinct from scope.project_ref
     or resource.project_url is distinct from scope.project_url
     or exists (
       select 1 from production_control.future_runtime_promotions_v2 value
       where value.tournament_id = target_id
     ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_FUTURE_GOOGLE_DESTINATION_PREDECESSOR_INVALID';
  end if;
  update production_control.future_tournament_resources_v1 value set
    source_workbook_id = scope.google_workbook_id,
    resource_status = 'CURRENT_RESOURCE_BOUND',
    google_compatibility_policy = 'PROVISIONING_REQUIRED',
    resource_revision = resource.resource_revision + 1,
    updated_by_player_id = actor_player,
    updated_at = pg_catalog.clock_timestamp()
  where value.tournament_id = target_id;
  result_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_FUTURE_GOOGLE_DESTINATION_ADOPTED',
    'action', 'ADOPT_ANNUAL_GOOGLE_DESTINATION',
    'targetTournamentId', target_id,
    'destinationClass', 'CURRENT_CERTIFIED_PRODUCTION_WORKBOOK',
    'priorResourceRevision', resource.resource_revision,
    'resourceRevision', resource.resource_revision + 1,
    'setupRevision', catalog.setup_revision,
    'nonAuthoritative', true,
    'idempotent', false
  );
  insert into production_control.future_google_writer_certification_receipts_v1 (
    action, target_tournament_id, operation_request_id,
    declared_request_payload_hash, database_request_payload_hash,
    actor_player_id, actor_auth_user_id, prior_revision, next_revision,
    response
  ) values (
    'ADOPT_ANNUAL_GOOGLE_DESTINATION', target_id, operation_id,
    declared_hash, database_hash, actor_player, actor_auth,
    resource.resource_revision, resource.resource_revision + 1, result_value
  );
  insert into production_control.future_google_writer_certification_audit_v1 (
    action, target_tournament_id, actor_player_id, operation_request_id,
    prior_revision, next_revision, result, safe_metadata
  ) values (
    'ADOPT_ANNUAL_GOOGLE_DESTINATION', target_id, actor_player, operation_id,
    resource.resource_revision, resource.resource_revision + 1, 'CHANGED',
    pg_catalog.jsonb_build_object(
      'summary', 'Certified Production workbook adopted for future runtime',
      'destinationClass', 'CURRENT_CERTIFIED_PRODUCTION_WORKBOOK',
      'resourceRevision', resource.resource_revision + 1,
      'setupRevision', catalog.setup_revision,
      'nonAuthoritative', true
    )
  );
  return result_value;
exception when no_data_found then
  raise exception using errcode = '40001',
    message = 'PRODUCTION_FUTURE_GOOGLE_DESTINATION_PREDECESSOR_INVALID';
end;
$_$;


ALTER FUNCTION public.adopt_production_future_google_destination_v1(input jsonb) OWNER TO postgres;

--
-- Name: approve_participant_identity_configuration(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_participant_identity_configuration(run_id uuid, expected_fingerprint text, approved_by_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'scoring_authority', 'public', 'pg_temp'
    AS $$
declare current_run participant_identity.identity_config_import_runs%rowtype;
begin
  select * into current_run from participant_identity.identity_config_import_runs where identity_config_import_runs.run_id = approve_participant_identity_configuration.run_id for update;
  if not found then raise exception 'Identity configuration import was not found.'; end if;
  if current_run.status not in ('APPLIED', 'APPROVED') then raise exception 'Only a complete valid mapping can be approved.'; end if;
  if current_run.source_fingerprint <> lower(btrim(expected_fingerprint)) then raise exception 'Identity configuration changed before approval.'; end if;
  if btrim(coalesce(approved_by_name, '')) = '' then raise exception 'Director identity is required.'; end if;

  update participant_identity.identity_config_import_runs set
    status = 'APPROVED', approved_by = btrim(approved_by_name), approved_at = coalesce(approved_at, now()), updated_at = now()
  where identity_config_import_runs.run_id = approve_participant_identity_configuration.run_id;

  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, actor_name, request_id, configuration_revision, safe_metadata
  ) values (
    'IDENTITY_MAPPING_APPROVED', current_run.tournament_id, btrim(approved_by_name), current_run.run_id::text,
    current_run.configuration_revision, jsonb_build_object('fingerprint', current_run.source_fingerprint)
  );
  return jsonb_build_object('ok', true, 'runId', current_run.run_id, 'status', 'APPROVED',
    'fingerprint', current_run.source_fingerprint, 'approvedBy', btrim(approved_by_name));
end;
$$;


ALTER FUNCTION public.approve_participant_identity_configuration(run_id uuid, expected_fingerprint text, approved_by_name text) OWNER TO postgres;

--
-- Name: approve_production_director_identity_projection(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_production_director_identity_projection(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare scope production_control.resource_scope%rowtype;
declare current_run participant_identity.identity_config_import_runs%rowtype;
declare request_value jsonb;
declare expected_request jsonb;
declare request_text text := coalesce(input->>'request_canonical_json', '');
declare request_hash text := lower(btrim(coalesce(input->>'request_fingerprint', '')));
declare source_hash text := lower(btrim(coalesce(input->>'identity_source_fingerprint', '')));
declare current_source_hash text := lower(btrim(coalesce(input->>'current_shadow_source_fingerprint', '')));
declare email_hash text := lower(btrim(coalesce(input->>'email_identity_hash', '')));
declare approval_evidence_hash text := lower(btrim(coalesce(input->>'approval_evidence_fingerprint', '')));
declare target_player text := upper(btrim(coalesce(input->>'player_id', '')));
declare target_run uuid := nullif(btrim(coalesce(input->>'run_id', '')), '')::uuid;
declare approved_by_value text;
declare approved_at_value timestamptz;
begin
  scope := production_control.assert_production_director_identity_bootstrap();
  if upper(btrim(coalesce(input->>'environment', ''))) <> 'PRODUCTION'
    or btrim(coalesce(input->>'project_ref', '')) <> scope.project_ref
    or btrim(coalesce(input->>'project_url', '')) <> scope.project_url
    or btrim(coalesce(input->>'source_workbook_id', '')) <> scope.google_workbook_id
    or btrim(coalesce(input->>'tournament_id', '')) <> '2026'
    or coalesce((input->>'tournament_year')::integer, 0) <> 2026
    or btrim(coalesce(input->>'contract_version', '')) <> 'production-director-identity-bootstrap-v1'
    or btrim(coalesce(input->>'operation', '')) <> 'PRODUCTION_DIRECTOR_IDENTITY_APPROVAL'
    or btrim(coalesce(input->>'actor_id', '')) <> 'step10b-production-auth-bootstrap'
    or target_run is null
    or target_player !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
    or source_hash !~ '^[0-9a-f]{64}$'
    or current_source_hash !~ '^[0-9a-f]{64}$'
    or email_hash !~ '^[0-9a-f]{64}$'
    or approval_evidence_hash !~ '^[0-9a-f]{64}$'
    or request_hash !~ '^[0-9a-f]{64}$'
    or btrim(request_text) = '' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_APPROVAL_EXACT_SCOPE_REQUIRED';
  end if;
  begin
    request_value := request_text::jsonb;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_APPROVAL_EVIDENCE_INVALID';
  end;
  expected_request := jsonb_build_object(
    'actor_id', 'step10b-production-auth-bootstrap',
    'approval_evidence_fingerprint', approval_evidence_hash,
    'contract_version', 'production-director-identity-bootstrap-v1',
    'current_shadow_source_fingerprint', current_source_hash,
    'email_identity_hash', email_hash,
    'environment', 'PRODUCTION',
    'identity_source_fingerprint', source_hash,
    'operation', 'PRODUCTION_DIRECTOR_IDENTITY_APPROVAL',
    'player_id', target_player,
    'project_ref', scope.project_ref,
    'project_url', scope.project_url,
    'run_id', target_run::text,
    'source_workbook_id', scope.google_workbook_id,
    'tournament_id', '2026',
    'tournament_year', 2026
  );
  if request_value is distinct from expected_request
    or encode(extensions.digest(request_text, 'sha256'), 'hex') <> request_hash then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_APPROVAL_EVIDENCE_MISMATCH';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('production-director-identity-bootstrap-2026', 0));
  select value.* into current_run
  from participant_identity.identity_config_import_runs value
  where value.run_id = target_run for update;
  if not found
    or current_run.tournament_id <> '2026'
    or current_run.source_system <> 'PRODUCTION_OWNER_APPROVED_IDENTITY_EVIDENCE'
    or current_run.source_workbook_id <> scope.google_workbook_id
    or current_run.source_fingerprint <> source_hash
    or current_run.configuration_revision <= 0
    or current_run.status not in ('REVIEW_REQUIRED', 'APPROVED')
    or current_run.validation_report->>'contractVersion' <> 'production-director-identity-bootstrap-v1'
    or current_run.validation_report->>'scope' <> 'ONE_PRODUCTION_DIRECTOR_CANDIDATE'
    or current_run.validation_report->>'playerId' <> target_player
    or current_run.validation_report->>'emailIdentityHash' <> email_hash
    or current_run.validation_report->>'currentShadowSourceFingerprint' <> current_source_hash
    or current_run.validation_report->>'approvalEvidenceFingerprint' <> approval_evidence_hash then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_APPROVAL_BOUND_IMPORT_REQUIRED';
  end if;
  if not exists (
    select 1 from production_control.current_shadow_revisions revision
    where revision.tournament_id = '2026'
      and revision.source_workbook_id = scope.google_workbook_id
      and revision.source_fingerprint = current_source_hash
      and revision.import_run_id = (
        select latest.import_run_id
        from production_control.current_shadow_revisions latest
        where latest.tournament_id = '2026'
        order by latest.imported_at desc, latest.import_run_id desc
        limit 1
      )
  ) or not exists (
    select 1 from participant_identity.participant_identity_contacts contact
    join participant_identity.identity_context_revisions revision
      on revision.tournament_id = contact.tournament_id
      and revision.context_revision = contact.configuration_revision
      and revision.configuration_fingerprint = source_hash
    where contact.tournament_id = '2026'
      and contact.player_id = target_player
      and contact.configuration_revision = current_run.configuration_revision
      and contact.identity_active
      and contact.source_workbook_id = scope.google_workbook_id
      and encode(extensions.digest(contact.email_normalized, 'sha256'), 'hex') = email_hash
  ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_APPROVAL_SOURCE_ADVANCED';
  end if;

  approved_by_value := current_run.validation_report->>'approvedBy';
  approved_at_value := nullif(current_run.validation_report->>'approvedAt', '')::timestamptz;
  -- Older drafts of this migration did not persist these two safe approval
  -- fields. Derive them from the contact only when they match the exact run.
  if btrim(coalesce(approved_by_value, '')) = '' or approved_at_value is null then
    select contact.verified_by, contact.verified_at into approved_by_value, approved_at_value
    from participant_identity.participant_identity_contacts contact
    where contact.tournament_id = '2026' and contact.player_id = target_player
      and contact.configuration_revision = current_run.configuration_revision;
  end if;
  if btrim(coalesce(approved_by_value, '')) = '' or approved_at_value is null then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_OWNER_APPROVAL_REQUIRED';
  end if;

  if current_run.status = 'APPROVED' then
    if current_run.approved_by is distinct from approved_by_value
      or current_run.approved_at is distinct from approved_at_value then
      raise exception using errcode = 'P0001',
        message = 'PRODUCTION_DIRECTOR_IDENTITY_APPROVAL_DRIFT';
    end if;
    return jsonb_build_object('ok', true, 'runId', current_run.run_id,
      'status', 'APPROVED', 'configurationRevision', current_run.configuration_revision,
      'sourceFingerprint', source_hash, 'playerId', target_player,
      'duplicate', true, 'authUsersCreated', 0,
      'authoritativeIdentityChanged', false, 'googleWrite', false,
      'previewRpcUsed', false);
  end if;

  update participant_identity.identity_config_import_runs set
    status = 'APPROVED', approved_by = approved_by_value,
    approved_at = approved_at_value, updated_at = now()
  where run_id = current_run.run_id;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, player_id, actor_name, request_id,
    configuration_revision, safe_metadata
  ) values (
    'PRODUCTION_DIRECTOR_IDENTITY_APPROVED', '2026', target_player,
    approved_by_value, current_run.run_id::text, current_run.configuration_revision,
    jsonb_build_object('sourceFingerprint', source_hash,
      'approvalEvidenceFingerprint', approval_evidence_hash,
      'scope', 'ONE_PRODUCTION_DIRECTOR_CANDIDATE', 'rawEmailStoredInAudit', false,
      'authUsersCreated', 0, 'authoritativeIdentityChanged', false,
      'googleWrite', false, 'previewRpcUsed', false)
  );
  return jsonb_build_object('ok', true, 'runId', current_run.run_id,
    'status', 'APPROVED', 'configurationRevision', current_run.configuration_revision,
    'sourceFingerprint', source_hash, 'playerId', target_player,
    'duplicate', false, 'authUsersCreated', 0,
    'authoritativeIdentityChanged', false, 'googleWrite', false,
    'previewRpcUsed', false);
end;
$_$;


ALTER FUNCTION public.approve_production_director_identity_projection(input jsonb) OWNER TO postgres;

--
-- Name: approve_production_handicap_revision_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_production_handicap_revision_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    AS $_$
declare
  actor_player text := pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  ));
  actor_auth_user uuid := nullif(
    input#>>'{authorization,auth_user_id}', ''
  )::uuid;
  operation_request uuid;
  declared_hash text := pg_catalog.lower(coalesce(
    input->>'request_payload_hash', ''
  ));
  target_revision uuid;
  expected_predecessor bigint;
  confirmed_effective_date date;
  confirmed_changed_player_count integer;
  confirmed_affected_match_count integer;
  confirmed_unstarted_refresh_count integer;
  confirmed_started_preserved_count integer;
  current_revision bigint := 0;
  current_revision_id uuid;
  revision scoring_authority.handicap_revisions%rowtype;
  receipt scoring_authority.handicap_operation_receipts%rowtype;
  validation_value jsonb;
  database_request_hash text;
  approval_time timestamptz := pg_catalog.clock_timestamp();
  match_item jsonb;
  target_match text;
  match_value scoring_authority.matches%rowtype;
  snapshot_before scoring_authority.scoring_snapshots%rowtype;
  snapshot_after scoring_authority.scoring_snapshots%rowtype;
  participant_item jsonb;
  context_value jsonb;
  before_participants jsonb;
  after_participants jsonb;
  next_snapshot_revision bigint;
  next_snapshot_hash text;
  refreshed_match_ids jsonb := '[]'::jsonb;
  preserved_match_ids jsonb := '[]'::jsonb;
  audit_event_id_value uuid;
  receipt_id_value uuid := extensions.gen_random_uuid();
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_production_scoring_actor(input, true);
  perform production_control.assert_production_handicap_runtime();
  if input->>'operation' is distinct from
       'APPROVE_PRODUCTION_HANDICAP_REVISION_V1'
     or input->>'contract_version' is distinct from
       'production-handicap-revision-v1'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'revision_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or pg_catalog.jsonb_typeof(input->'expected_predecessor_revision')
       is distinct from 'number'
     or input->>'expected_predecessor_revision' !~ '^[0-9]+$'
     or pg_catalog.jsonb_typeof(input->'confirmation')
       is distinct from 'object'
     or pg_catalog.jsonb_typeof(input#>'{confirmation,effective_date}')
       is distinct from 'string'
     or input#>>'{confirmation,effective_date}'
       !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or pg_catalog.jsonb_typeof(
       input#>'{confirmation,changed_player_count}'
     ) is distinct from 'number'
     or input#>>'{confirmation,changed_player_count}' !~ '^[1-9][0-9]*$'
     or pg_catalog.jsonb_typeof(
       input#>'{confirmation,affected_match_count}'
     ) is distinct from 'number'
     or input#>>'{confirmation,affected_match_count}' !~ '^[0-9]+$'
     or pg_catalog.jsonb_typeof(
       input#>'{confirmation,unstarted_refresh_count}'
     ) is distinct from 'number'
     or input#>>'{confirmation,unstarted_refresh_count}' !~ '^[0-9]+$'
     or pg_catalog.jsonb_typeof(
       input#>'{confirmation,started_preserved_count}'
     ) is distinct from 'number'
     or input#>>'{confirmation,started_preserved_count}' !~ '^[0-9]+$' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_APPROVAL_INPUT_INVALID'
    );
  end if;
  begin
    operation_request := (input->>'operation_request_id')::uuid;
    target_revision := (input->>'revision_id')::uuid;
    expected_predecessor :=
      (input->>'expected_predecessor_revision')::bigint;
    confirmed_effective_date :=
      (input#>>'{confirmation,effective_date}')::date;
    confirmed_changed_player_count :=
      (input#>>'{confirmation,changed_player_count}')::integer;
    confirmed_affected_match_count :=
      (input#>>'{confirmation,affected_match_count}')::integer;
    confirmed_unstarted_refresh_count :=
      (input#>>'{confirmation,unstarted_refresh_count}')::integer;
    confirmed_started_preserved_count :=
      (input#>>'{confirmation,started_preserved_count}')::integer;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_APPROVAL_INPUT_INVALID'
    );
  end;

  database_request_hash := production_control.handicap_v1_hash(
    pg_catalog.jsonb_build_object(
      'operation', 'APPROVE',
      'operation_request_id', operation_request,
      'actor_player_id', actor_player,
      'actor_auth_user_id', actor_auth_user,
      'revision_id', target_revision,
      'expected_predecessor_revision', expected_predecessor,
      'confirmation', pg_catalog.jsonb_build_object(
        'effective_date', confirmed_effective_date,
        'changed_player_count', confirmed_changed_player_count,
        'affected_match_count', confirmed_affected_match_count,
        'unstarted_refresh_count', confirmed_unstarted_refresh_count,
        'started_preserved_count', confirmed_started_preserved_count
      )
    )
  );
  select value.* into receipt
  from scoring_authority.handicap_operation_receipts value
  where value.tournament_id = '2026'
    and value.operation = 'APPROVE'
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.request_payload_hash = database_request_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_IDEMPOTENCY_CONFLICT',
      'operation_request_id', operation_request
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('production-handicap-revision:2026', 0)
  );
  select value.* into receipt
  from scoring_authority.handicap_operation_receipts value
  where value.tournament_id = '2026'
    and value.operation = 'APPROVE'
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.request_payload_hash = database_request_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_IDEMPOTENCY_CONFLICT',
      'operation_request_id', operation_request
    );
  end if;
  -- Serialize against scoring mutations.  A scorer that commits first makes
  -- the match frozen; an approval that locks first refreshes before scoring.
  perform value.match_id
  from scoring_authority.matches value
  where value.tournament_id = '2026'
  order by value.match_id
  for update;

  select pointer.revision_number, pointer.revision_id
    into current_revision, current_revision_id
  from scoring_authority.handicap_revision_current pointer
  where pointer.tournament_id = '2026' for update;
  current_revision := coalesce(current_revision, 0);
  select value.* into revision
  from scoring_authority.handicap_revisions value
  where value.revision_id = target_revision
    and value.tournament_id = '2026' for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_REVISION_NOT_FOUND'
    );
  end if;

  validation_value := production_control.validate_handicap_revision_v1(
    target_revision, expected_predecessor
  );
  if coalesce(
    (validation_value->>'valid')::boolean, false
  ) is not true then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', validation_value->>'code',
      'validation', validation_value
    );
  end if;
  if revision.effective_date <> confirmed_effective_date
     or coalesce(
       (validation_value#>>'{summary,changed_player_count}')::integer, 0
     ) <> confirmed_changed_player_count
     or coalesce(
       (validation_value#>>'{summary,unstarted_refresh_count}')::integer, 0
     ) + coalesce(
       (validation_value#>>'{summary,started_preserved_count}')::integer, 0
     ) <> confirmed_affected_match_count
     or coalesce(
       (validation_value#>>'{summary,unstarted_refresh_count}')::integer, 0
     ) <> confirmed_unstarted_refresh_count
     or coalesce(
       (validation_value#>>'{summary,started_preserved_count}')::integer, 0
     ) <> confirmed_started_preserved_count then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'HANDICAP_APPROVAL_CONFIRMATION_MISMATCH',
      'confirmation', pg_catalog.jsonb_build_object(
        'effective_date', confirmed_effective_date,
        'changed_player_count', confirmed_changed_player_count,
        'affected_match_count', confirmed_affected_match_count,
        'unstarted_refresh_count', confirmed_unstarted_refresh_count,
        'started_preserved_count', confirmed_started_preserved_count
      ),
      'actual', pg_catalog.jsonb_build_object(
        'effective_date', revision.effective_date,
        'changed_player_count', coalesce(
          (validation_value#>>'{summary,changed_player_count}')::integer, 0
        ),
        'affected_match_count', coalesce(
          (validation_value#>>'{summary,unstarted_refresh_count}')::integer, 0
        ) + coalesce(
          (validation_value#>>'{summary,started_preserved_count}')::integer, 0
        ),
        'unstarted_refresh_count', coalesce(
          (validation_value#>>'{summary,unstarted_refresh_count}')::integer, 0
        ),
        'started_preserved_count', coalesce(
          (validation_value#>>'{summary,started_preserved_count}')::integer, 0
        )
      )
    );
  end if;
  if current_revision <> expected_predecessor
     or revision.predecessor_revision <> expected_predecessor
     or revision.predecessor_revision_id is distinct from current_revision_id
     or revision.status <> 'DRAFT' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_PREDECESSOR_STALE',
      'expected_predecessor_revision', expected_predecessor,
      'current_revision', current_revision
    );
  end if;

  select coalesce(pg_catalog.jsonb_agg(value->>'match_id'), '[]'::jsonb)
    into preserved_match_ids
  from pg_catalog.jsonb_array_elements(
    validation_value->'started_frozen_matches'
  ) item(value);

  if current_revision_id is not null then
    update scoring_authority.handicap_revisions
    set status = 'SUPERSEDED', superseded_at = approval_time
    where revision_id = current_revision_id and status = 'APPROVED';
    if not found then
      raise exception using errcode = '40001',
        message = 'HANDICAP_PREDECESSOR_STALE';
    end if;
  end if;
  update scoring_authority.handicap_revisions
  set status = 'APPROVED', approved_by = actor_player,
      approved_by_auth_user_id = actor_auth_user,
      approved_at = approval_time
  where revision_id = target_revision and status = 'DRAFT';
  if not found then
    raise exception using errcode = '40001',
      message = 'HANDICAP_PREDECESSOR_STALE';
  end if;

  update scoring_authority.tournament_players roster
  set tournament_handicap = entry.tournament_handicap,
      handicap_revision_id = target_revision,
      -- Preserve the established Supabase projection contract used by current
      -- server/native readers.  This changes only the existing Tournament
      -- Handicap JSON member; it does not enqueue or perform a Google write.
      source_payload = pg_catalog.jsonb_set(
        roster.source_payload,
        array['Tournament Handicap']::text[],
        pg_catalog.to_jsonb(entry.tournament_handicap),
        true
      ),
      updated_at = approval_time
  from scoring_authority.handicap_revision_entries entry
  where entry.revision_id = target_revision
    and entry.tournament_id = '2026'
    and roster.tournament_id = entry.tournament_id
    and roster.player_id = entry.player_id
    and roster.participation_status = 'ACTIVE';

  for match_item in
    select value from pg_catalog.jsonb_array_elements(
      validation_value->'unstarted_matches'
    ) item(value)
  loop
    target_match := match_item->>'match_id';
    if not production_control.handicap_v1_match_is_unstarted(target_match) then
      raise exception using errcode = '55000',
        message = 'HANDICAP_MATCH_BECAME_FROZEN';
    end if;
    select value.* into strict match_value
    from scoring_authority.matches value
    where value.match_id = target_match and value.tournament_id = '2026';
    select value.* into strict snapshot_before
    from scoring_authority.scoring_snapshots value
    where value.snapshot_id = match_value.scoring_snapshot_id
      and value.match_id = target_match
      and value.tournament_id = '2026' for update;
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(value) order by value.team_side, value.player_slot
    ), '[]'::jsonb) into before_participants
    from scoring_authority.match_participants value
    where value.match_id = target_match;

    context_value := production_control.handicap_v1_match_context(
      target_match, target_revision
    );
    for participant_item in
      select value from pg_catalog.jsonb_array_elements(
        context_value->'participants'
      ) item(value)
    loop
      update scoring_authority.match_participants
      set tournament_handicap =
            (participant_item->>'tournament_handicap')::numeric,
          handicap_index = (participant_item->>'handicap_index')::numeric,
          course_handicap =
            (participant_item->>'course_handicap')::numeric,
          playing_handicap =
            (participant_item->>'playing_handicap')::numeric,
          final_strokes = (participant_item->>'final_strokes')::integer,
          handicap_revision_id = target_revision
      where match_id = target_match
        and player_id = participant_item->>'player_id';
    end loop;

    next_snapshot_revision := snapshot_before.snapshot_revision + 1;
    next_snapshot_hash := production_control.handicap_v1_hash(
      pg_catalog.jsonb_build_object(
        'tournament_id', '2026',
        'tournament_year', 2026,
        'round_number', match_value.round_number,
        'match_id', match_value.match_id,
        'format', match_value.format,
        'scoring_rules_version', snapshot_before.scoring_rules_version,
        'handicap_allowance', snapshot_before.handicap_allowance,
        'course', pg_catalog.jsonb_build_object(
          'course_id', snapshot_before.course_id,
          'tee', snapshot_before.tee,
          'rating', snapshot_before.rating,
          'slope', snapshot_before.slope,
          'par', snapshot_before.par
        ),
        'holes', snapshot_before.hole_definitions,
        'participants', context_value->'participant_configuration',
        'teams', context_value->'team_configuration',
        'match_netting_baseline', snapshot_before.match_netting_baseline,
        'snapshot_revision', next_snapshot_revision,
        'effective_at', approval_time,
        'handicap_revision_id', target_revision,
        'handicap_context_contract', 'production-handicap-context-v1'
      )
    );
    update scoring_authority.scoring_snapshots
    set snapshot_revision = next_snapshot_revision,
        participant_configuration =
          context_value->'participant_configuration',
        team_configuration = context_value->'team_configuration',
        effective_at = approval_time,
        canonical_hash = next_snapshot_hash,
        handicap_revision_id = target_revision
    where snapshot_id = snapshot_before.snapshot_id
    returning * into strict snapshot_after;
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(value) order by value.team_side, value.player_slot
    ), '[]'::jsonb) into after_participants
    from scoring_authority.match_participants value
    where value.match_id = target_match;

    insert into scoring_authority.handicap_match_refresh_events (
      revision_id, tournament_id, match_id, previous_snapshot_revision,
      next_snapshot_revision, before_context, after_context, refreshed_at
    ) values (
      target_revision, '2026', target_match,
      snapshot_before.snapshot_revision, snapshot_after.snapshot_revision,
      pg_catalog.jsonb_build_object(
        'snapshot', pg_catalog.to_jsonb(snapshot_before),
        'participants', before_participants
      ),
      pg_catalog.jsonb_build_object(
        'snapshot', pg_catalog.to_jsonb(snapshot_after),
        'participants', after_participants
      ),
      approval_time
    );
    refreshed_match_ids := refreshed_match_ids
      || pg_catalog.jsonb_build_array(target_match);
  end loop;

  insert into scoring_authority.handicap_revision_current (
    tournament_id, revision_id, revision_number, updated_at
  ) values (
    '2026', target_revision, revision.revision_number, approval_time
  ) on conflict (tournament_id) do update set
    revision_id = excluded.revision_id,
    revision_number = excluded.revision_number,
    updated_at = excluded.updated_at;

  audit_event_id_value := extensions.gen_random_uuid();
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'HANDICAP_REVISION_APPROVED',
    'idempotent', false,
    'operation_request_id', operation_request,
    'revision_id', target_revision,
    'revision_number', revision.revision_number,
    'status', 'APPROVED',
    'effective_date', revision.effective_date,
    'canonical_fingerprint', revision.canonical_fingerprint,
    'approved_at', approval_time,
    'approved_by', actor_player,
    'refreshed_match_ids', refreshed_match_ids,
    'preserved_match_ids', preserved_match_ids,
    'refresh_count', pg_catalog.jsonb_array_length(refreshed_match_ids),
    'preserved_count', pg_catalog.jsonb_array_length(preserved_match_ids),
    'unstarted_refresh_count',
      pg_catalog.jsonb_array_length(refreshed_match_ids),
    'started_preserved_count',
      pg_catalog.jsonb_array_length(preserved_match_ids),
    'changed_player_count', coalesce(
      (validation_value#>>'{summary,changed_player_count}')::integer, 0
    ),
    'affected_match_count',
      pg_catalog.jsonb_array_length(refreshed_match_ids)
      + pg_catalog.jsonb_array_length(preserved_match_ids),
    'audit_event_id', audit_event_id_value,
    'request_payload_hash', declared_hash,
    'receipt', pg_catalog.jsonb_build_object(
      'receipt_id', receipt_id_value,
      'operation_request_id', operation_request,
      'request_payload_hash', declared_hash,
      'status', 'APPROVED',
      'approved_at', approval_time
    ),
    'validation', validation_value
  );
  insert into scoring_authority.handicap_audit_events (
    event_id, tournament_id, revision_id, action, actor_player_id,
    actor_auth_user_id, operation_request_id, request_payload_hash,
    canonical_fingerprint, before_state, after_state
  ) values (
    audit_event_id_value, '2026', target_revision, 'REVISION_APPROVED',
    actor_player, actor_auth_user, operation_request,
    database_request_hash, revision.canonical_fingerprint,
    pg_catalog.jsonb_build_object(
      'revision_number', current_revision,
      'revision_id', current_revision_id
    ),
    response_value - 'validation'
  );
  insert into scoring_authority.handicap_operation_receipts (
    receipt_id, tournament_id, operation, operation_request_id,
    declared_request_payload_hash, request_payload_hash,
    actor_player_id, actor_auth_user_id, response
  ) values (
    receipt_id_value, '2026', 'APPROVE', operation_request, declared_hash,
    database_request_hash, actor_player, actor_auth_user, response_value
  );
  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'HANDICAP_REVISION_APPROVED', actor_player,
    response_value - 'validation'
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_HANDICAP_REVISION_APPROVED', 'HANDICAP_CONFIGURATION',
    '2026', actor_player, database_request_hash, 'SUCCEEDED',
    response_value - 'validation'
  );
  return response_value;
exception
  when numeric_value_out_of_range then
    raise exception using errcode = '55000',
      message = 'HANDICAP_DERIVED_STROKES_OUT_OF_RANGE';
end;
$_$;


ALTER FUNCTION public.approve_production_handicap_revision_v1(input jsonb) OWNER TO postgres;

--
-- Name: arm_production_google_ingress_lease_gate(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.arm_production_google_ingress_lease_gate(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  next_admission_generation uuid := extensions.gen_random_uuid();
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform production_control.assert_scoring_admission_optimistic_input(input, false);
  existing := production_control.lookup_cutover_receipt('ARM_GOOGLE_LEASE_GATE', input);
  if existing is not null then return existing; end if;
  if coalesce(input->>'actor_id', '') = ''
     or coalesce(input->>'deployment_id', '') !~ '^dpl_[A-Za-z0-9]{8,64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_LEASE_GATE_V2_INPUT_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_cutover_receipt(
    'ARM_GOOGLE_LEASE_GATE', input
  );
  if existing is not null then return existing; end if;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  if activation.activation_revision
       is distinct from (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id
       is distinct from (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id
       is distinct from (input->>'expected_admission_generation')::uuid
     or gate.admission_revision
       is distinct from (input->>'expected_admission_revision')::bigint
     or activation.state <> 'STAGED'
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or gate.authority <> 'GOOGLE'
     or gate.active_epoch_id is not null
     or gate.active_closure_id is not null
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
     or exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026' and lease.status = 'ACTIVE'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_LEASE_GATE_V2_NOT_ARMABLE';
  end if;
  update scoring_authority.ingress_gates
  set state = 'OPEN', admission_state = 'OPEN',
      admission_revision = admission_revision + 1,
      admission_generation_id = next_admission_generation,
      admission_protocol_enforced = true,
      admission_enforced_at = pg_catalog.now(),
      admission_opened_at = pg_catalog.now(),
      admission_deployment_id = input->>'deployment_id',
      legacy_lease_set_fingerprint =
        production_control.scoring_admission_legacy_set_fingerprint(),
      active_epoch_id = null, active_closure_id = null,
      external_fence_evidence_id = null,
      unresolved_client_queues = 0,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026'
  returning * into gate;
  update production_control.cutover_activation_state
  set state = 'GOOGLE_LEASE_ARMED', activation_revision = activation_revision + 1,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
  returning * into activation;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_GOOGLE_INGRESS_LEASE_GATE_V2_ARMED', 'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'authority_generation_id', activation.authority_generation_id,
      'admission_generation_id', gate.admission_generation_id,
      'admission_revision', gate.admission_revision,
      'deployment_id', gate.admission_deployment_id,
      'database_centrally_enforced_external_google', false
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_GOOGLE_LEASE_GATE_V2_ARMED',
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'admission_revision', gate.admission_revision,
    'authority', 'GOOGLE', 'execution_gate', gate.state,
    'admission_state', gate.admission_state,
    'external_fence_evidence_id', null,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt('ARM_GOOGLE_LEASE_GATE', input, response_value);
  return response_value;
end;
$_$;


ALTER FUNCTION public.arm_production_google_ingress_lease_gate(input jsonb) OWNER TO postgres;

