--
-- Name: authorize_participant_phone_enrollment_verification(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_participant_phone_enrollment_verification(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'scoring_authority', 'public', 'auth', 'pg_temp'
    AS $$
declare target_attempt uuid := nullif(input->>'attempt_id', '')::uuid;
declare actor_auth_user uuid := nullif(input->>'actor_auth_user_id', '')::uuid;
declare attempt participant_identity.participant_phone_otp_attempts%rowtype;
declare identifier participant_identity.participant_auth_identifiers%rowtype;
declare email_identifier participant_identity.participant_auth_identifiers%rowtype;
declare auth_user auth.users%rowtype;
begin
  select * into attempt from participant_identity.participant_phone_otp_attempts
  where attempt_id = target_attempt
    and auth_user_id = actor_auth_user
    and requested_by_auth_user_id = actor_auth_user
  for update;
  if not found then return jsonb_build_object('ok', false, 'allowed', false, 'code', 'PHONE_OTP_SESSION_REQUIRED'); end if;
  if attempt.status = 'VERIFIED' then return jsonb_build_object('ok', true, 'allowed', false, 'code', 'PHONE_OTP_REPLAY'); end if;
  if attempt.status <> 'SENT' then return jsonb_build_object('ok', true, 'allowed', false, 'code', 'PHONE_OTP_STALE'); end if;
  if attempt.expires_at <= now() then
    update participant_identity.participant_phone_otp_attempts set status = 'EXPIRED', safe_reason = 'ATTEMPT_EXPIRED', updated_at = now()
    where attempt_id = target_attempt;
    update participant_identity.participant_auth_identifiers set status = 'ELIGIBLE', updated_at = now()
    where identifier_id = attempt.identifier_id and status = 'VERIFICATION_PENDING';
    return jsonb_build_object('ok', true, 'allowed', false, 'code', 'PHONE_OTP_INVALID_OR_EXPIRED');
  end if;
  select * into identifier from participant_identity.participant_auth_identifiers
  where identifier_id = attempt.identifier_id for update;
  select * into email_identifier from participant_identity.participant_auth_identifiers
  where player_id = attempt.player_id and auth_user_id = attempt.auth_user_id
    and identifier_type = 'EMAIL' and status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED');
  select * into auth_user from auth.users where id = attempt.auth_user_id;
  if identifier.identifier_id is null or identifier.status <> 'VERIFICATION_PENDING'
     or identifier.revision <> attempt.identifier_revision
     or identifier.player_id <> attempt.player_id or identifier.auth_user_id <> attempt.auth_user_id
     or email_identifier.identifier_id is null
     or lower(btrim(coalesce(auth_user.email, ''))) <> email_identifier.normalized_value_private
     or nullif(btrim(coalesce(auth_user.phone, '')), '') is not null
     or auth_user.phone_confirmed_at is not null
     or participant_identity.canonical_auth_phone(nullif(auth_user.phone_change, ''))
       is distinct from participant_identity.canonical_auth_phone(identifier.normalized_value_private)
     or not exists (select 1 from participant_identity.user_player_links link
       where link.player_id = attempt.player_id and link.auth_user_id = attempt.auth_user_id and link.status = 'ACTIVE')
     or not exists (select 1 from scoring_authority.tournament_players membership
       where membership.tournament_id = attempt.tournament_id and membership.player_id = attempt.player_id
         and membership.participation_status = 'ACTIVE')
     or exists (select 1 from auth.users other_user where other_user.id <> attempt.auth_user_id
       and (participant_identity.canonical_auth_phone(nullif(other_user.phone, ''))
         = participant_identity.canonical_auth_phone(identifier.normalized_value_private)
         or participant_identity.canonical_auth_phone(nullif(other_user.phone_change, ''))
         = participant_identity.canonical_auth_phone(identifier.normalized_value_private))) then
    update participant_identity.participant_phone_otp_attempts set status = 'CANCELLED', safe_reason = 'AUTHORITY_MISMATCH', updated_at = now()
    where attempt_id = target_attempt;
    update participant_identity.participant_auth_identifiers set status = 'ELIGIBLE', updated_at = now()
    where identifier_id = attempt.identifier_id and status = 'VERIFICATION_PENDING';
    return jsonb_build_object('ok', true, 'allowed', false, 'code', 'PHONE_OTP_AUTH_MISMATCH');
  end if;
  return jsonb_build_object('ok', true, 'allowed', true, 'code', 'PHONE_OTP_VERIFY_ALLOWED',
    'attemptId', attempt.attempt_id, 'tournamentId', attempt.tournament_id,
    'playerId', attempt.player_id, 'authUserId', attempt.auth_user_id,
    'phoneE164', identifier.normalized_value_private,
    'emailNormalized', email_identifier.normalized_value_private,
    'expiresAt', attempt.expires_at);
end;
$$;


ALTER FUNCTION public.authorize_participant_phone_enrollment_verification(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_auth_candidate_otp_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_auth_candidate_otp_request(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'participant_identity', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare normalized text := lower(btrim(coalesce(input->>'email', '')));
declare client_hash text := lower(btrim(coalesce(input->>'client_request_hash', '')));
declare email_hash text := encode(extensions.digest(normalized::text, 'sha256'::text), 'hex');
declare candidate participant_identity.production_auth_candidates%rowtype;
declare request uuid := extensions.gen_random_uuid();
declare allowed boolean := false;
declare reason text := 'NOT_ELIGIBLE';
declare selected_verification_type text := 'email';
begin
  perform production_control.assert_production_auth_candidate_rpc();
  if client_hash !~ '^[0-9a-f]{64}$' then raise exception 'A hashed request identity is required.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    least('client:' || client_hash, 'email:' || email_hash), 0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    greatest('client:' || client_hash, 'email:' || email_hash), 0
  ));
  if (select count(*) from participant_identity.participant_auth_otp_attempts
      where client_request_hash = client_hash and requested_at > now() - interval '15 minutes') >= 5
    or (select count(*) from participant_identity.participant_auth_otp_attempts
      where email_identity_hash = email_hash and requested_at > now() - interval '15 minutes') >= 3 then
    return jsonb_build_object('ok', true, 'allowed', false, 'requestId', request,
      'email', null, 'authUserId', null, 'playerId', null, 'verificationType', null);
  end if;
  select c.* into candidate from participant_identity.production_auth_candidates c
  join participant_identity.participant_identity_contacts approved_contact
    on approved_contact.tournament_id = c.tournament_id and approved_contact.player_id = c.player_id
  join participant_identity.user_player_links link
    on link.auth_user_id = c.auth_user_id and link.player_id = c.player_id
    and ((c.status = 'PREPARED' and link.status = 'PENDING')
      or (c.status = 'VERIFIED' and link.status = 'ACTIVE'))
  join participant_identity.participant_auth_identifiers identifier
    on identifier.auth_user_id = c.auth_user_id and identifier.player_id = c.player_id
    and identifier.identifier_type = 'EMAIL'
    and identifier.normalized_value_private = approved_contact.email_normalized
    and ((c.status = 'PREPARED' and identifier.status = 'VERIFICATION_PENDING')
      or (c.status = 'VERIFIED' and identifier.status = 'VERIFIED'))
  join auth.users auth_user
    on auth_user.id = c.auth_user_id
    and ((c.status = 'PREPARED' and auth_user.email_confirmed_at is null)
      or (c.status = 'VERIFIED' and auth_user.email_confirmed_at is not null))
  where c.tournament_id = '2026' and c.status in ('PREPARED', 'VERIFIED')
    and approved_contact.identity_active and approved_contact.email_normalized = normalized
  for update of c;
  if found then
    selected_verification_type := case candidate.status
      when 'PREPARED' then 'signup'
      when 'VERIFIED' then 'email'
    end;
    if exists (select 1 from participant_identity.participant_auth_otp_attempts
      where player_id = candidate.player_id and status in ('AUTHORIZED', 'SENT')
        and requested_at > now() - interval '60 seconds') then reason := 'COOLDOWN';
    elsif (select count(*) from participant_identity.participant_auth_otp_attempts
      where player_id = candidate.player_id and requested_at > now() - interval '15 minutes') >= 3
      or (select count(*) from participant_identity.participant_auth_otp_attempts
        where client_request_hash = client_hash and requested_at > now() - interval '15 minutes') >= 5
      then reason := 'RATE_LIMIT';
    else allowed := true; reason := 'APPROVED'; end if;
  end if;
  insert into participant_identity.participant_auth_otp_attempts (
    request_id, tournament_id, player_id, auth_user_id, email_identity_hash,
    client_request_hash, status, safe_reason, verification_type
  ) values (
    request, candidate.tournament_id, candidate.player_id, candidate.auth_user_id,
    email_hash, client_hash, case when allowed then 'AUTHORIZED' else 'REJECTED' end,
    reason, selected_verification_type
  );
  return jsonb_build_object('ok', true, 'allowed', allowed, 'requestId', request,
    'email', case when allowed then normalized else null end,
    'authUserId', case when allowed then candidate.auth_user_id else null end,
    'playerId', case when allowed then candidate.player_id else null end,
    'verificationType', case when allowed then selected_verification_type else null end);
end;
$_$;


ALTER FUNCTION public.authorize_production_auth_candidate_otp_request(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_auth_candidate_otp_verification(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_auth_candidate_otp_verification(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'participant_identity', 'auth', 'extensions', 'pg_temp'
    AS $$
declare request uuid := nullif(input->>'request_id', '')::uuid;
declare email_hash text := lower(btrim(coalesce(input->>'email_identity_hash', '')));
declare attempt participant_identity.participant_auth_otp_attempts%rowtype;
begin
  perform production_control.assert_production_auth_candidate_rpc();
  select otp.* into attempt
  from participant_identity.participant_auth_otp_attempts otp
  join participant_identity.production_auth_candidates candidate
    on candidate.tournament_id = otp.tournament_id
    and candidate.player_id = otp.player_id
    and candidate.auth_user_id = otp.auth_user_id
    and ((candidate.status = 'PREPARED' and otp.verification_type = 'signup')
      or (candidate.status = 'VERIFIED' and otp.verification_type = 'email'))
  join participant_identity.user_player_links link
    on link.auth_user_id = otp.auth_user_id and link.player_id = otp.player_id
    and ((candidate.status = 'PREPARED' and link.status = 'PENDING')
      or (candidate.status = 'VERIFIED' and link.status = 'ACTIVE'))
  join participant_identity.participant_auth_identifiers identifier
    on identifier.auth_user_id = otp.auth_user_id and identifier.player_id = otp.player_id
    and identifier.identifier_type = 'EMAIL'
    and ((candidate.status = 'PREPARED' and identifier.status = 'VERIFICATION_PENDING')
      or (candidate.status = 'VERIFIED' and identifier.status = 'VERIFIED'))
    and encode(extensions.digest(identifier.normalized_value_private::text, 'sha256'), 'hex') = email_hash
  where otp.request_id = request and otp.status = 'SENT'
    and otp.email_identity_hash = email_hash
    and otp.sent_at > now() - interval '15 minutes';
  if not found then return jsonb_build_object('ok', true, 'allowed', false); end if;
  return jsonb_build_object('ok', true, 'allowed', true, 'authUserId', attempt.auth_user_id,
    'playerId', attempt.player_id, 'tournamentId', attempt.tournament_id,
    'verificationType', attempt.verification_type);
end;
$$;


ALTER FUNCTION public.authorize_production_auth_candidate_otp_verification(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_current_match_access_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_current_match_access_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  target_tournament text;
begin
  -- Annual pointer transitions take the exclusive counterpart of this lock.
  -- Holding it through the decision closes the server-resolver/RPC race.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';

  -- These values are overwritten by the trusted server translator. Repeating
  -- them here makes a stale resolver or a direct wrong-target service call
  -- fail before any tournament-scoped fact is read.
  if input->>'target_tournament_id' is distinct from pointer.tournament_id
     or input->>'expected_current_tournament_id'
       is distinct from pointer.tournament_id
     or coalesce((input->>'expected_pointer_revision')::bigint, -1)
       <> pointer.pointer_revision then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CURRENT_MATCH_AUTHORIZATION_POINTER_STALE';
  end if;

  if pointer.tournament_id = '2026' then
    perform production_control.assert_frozen_2026_current_read_v1();
    if pointer.tournament_year <> 2026 then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_CURRENT_MATCH_AUTHORIZATION_RUNTIME_REQUIRED';
    end if;
    target_tournament := pointer.tournament_id;
  else
    target_tournament :=
      production_control.assert_annual_current_read_v1(input);
    if target_tournament is distinct from pointer.tournament_id then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_CURRENT_MATCH_AUTHORIZATION_POINTER_STALE';
    end if;
  end if;

  return scoring_authority.match_access_decision(
    target_tournament,
    pg_catalog.btrim(coalesce(input->>'target_player_id', '')),
    pg_catalog.btrim(coalesce(input->>'target_match_id', '')),
    pg_catalog.upper(pg_catalog.btrim(coalesce(
      input->>'requested_action', ''
    )))
  );
exception
  when invalid_text_representation or numeric_value_out_of_range
    or no_data_found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CURRENT_MATCH_AUTHORIZATION_RUNTIME_REQUIRED';
end;
$$;


ALTER FUNCTION public.authorize_production_current_match_access_v1(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_future_participant_otp_request_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_future_participant_otp_request_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target_id text;
  normalized text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'email', ''
  )));
  client_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'client_request_hash', ''
  )));
  email_hash text := encode(extensions.digest(normalized::text, 'sha256'),
    'hex');
  request_value uuid := extensions.gen_random_uuid();
  contact participant_identity.participant_identity_contacts%rowtype;
  binding participant_identity.future_tournament_participant_bindings_v1%rowtype;
  link participant_identity.user_player_links%rowtype;
  identifier participant_identity.participant_auth_identifiers%rowtype;
  auth_user auth.users%rowtype;
  claim participant_identity.production_participant_enrollment_claims%rowtype;
  selected_type text := 'email';
  reason text := 'NOT_ELIGIBLE';
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  if client_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_AUTH_HASHED_REQUEST_REQUIRED';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    least('client:' || client_hash, 'email:' || email_hash), 0
  ));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    greatest('client:' || client_hash, 'email:' || email_hash), 0
  ));
  if (select pg_catalog.count(*)
      from participant_identity.participant_auth_otp_attempts attempt
      where attempt.client_request_hash = client_hash
        and attempt.requested_at > pg_catalog.clock_timestamp()
          - interval '15 minutes') >= 5
     or (select pg_catalog.count(*)
      from participant_identity.participant_auth_otp_attempts attempt
      where attempt.email_identity_hash = email_hash
        and attempt.requested_at > pg_catalog.clock_timestamp()
          - interval '15 minutes') >= 3 then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'allowed', false, 'requestId', request_value,
      'email', null, 'playerId', null, 'provisioningRequired', false,
      'tournamentId', target_id
    );
  end if;

  select contact_value.*
  into contact
  from participant_identity.participant_identity_contacts contact_value
  join participant_identity.future_tournament_participant_bindings_v1
    binding_value
    on binding_value.tournament_id = contact_value.tournament_id
   and binding_value.player_id = contact_value.player_id
   and binding_value.contact_state = 'APPROVED'
  join scoring_authority.tournament_players membership
    on membership.tournament_id = contact_value.tournament_id
   and membership.player_id = contact_value.player_id
   and membership.participation_status = 'ACTIVE'
  where contact_value.tournament_id = target_id
    and contact_value.identity_active
    and contact_value.email_normalized = normalized;
  if found then
    select value.* into strict binding
    from participant_identity.future_tournament_participant_bindings_v1 value
    where value.tournament_id = target_id
      and value.player_id = contact.player_id
      and value.contact_state = 'APPROVED'
    for update;
    select value.* into link
    from participant_identity.user_player_links value
    where value.player_id = contact.player_id
      and value.status in ('PENDING', 'ACTIVE', 'SUSPENDED')
    for update;
    if found then
      select value.* into identifier
      from participant_identity.participant_auth_identifiers value
      where value.player_id = contact.player_id
        and value.auth_user_id = link.auth_user_id
        and value.identifier_type = 'EMAIL'
        and value.status in ('VERIFICATION_PENDING', 'VERIFIED')
      for update;
      select value.* into auth_user
      from auth.users value where value.id = link.auth_user_id;
      if identifier.identifier_id is null
         or identifier.normalized_value_private is distinct from normalized
         or pg_catalog.lower(pg_catalog.btrim(coalesce(auth_user.email, '')))
           is distinct from normalized then
        contact := null;
      elsif link.status = 'ACTIVE'
        and link.revoked_at is null
        and identifier.status = 'VERIFIED'
        and identifier.revoked_at is null
        and auth_user.email_confirmed_at is not null then
        reason := 'APPROVED';
        selected_type := 'email';
        if binding.enrollment_state = 'NOT_ENROLLED' then
          perform production_control.enroll_future_participant_identity_link_v1(
            target_id, contact.player_id, link.auth_user_id
          );
        end if;
      elsif link.status = 'PENDING'
        and identifier.status = 'VERIFICATION_PENDING'
        and auth_user.email_confirmed_at is null
        and auth_user.raw_app_meta_data->>'provisioning_scope'
          = 'production_controlled_first_login'
        and auth_user.raw_app_meta_data->>'player_id' = contact.player_id
        and auth_user.raw_app_meta_data->>'tournament_id' = target_id then
        reason := 'APPROVED';
        selected_type := 'signup';
      else
        contact := null;
      end if;
    else
      if exists (
        select 1 from auth.users value
        where pg_catalog.lower(pg_catalog.btrim(coalesce(value.email, '')))
          = normalized
      ) or exists (
        select 1
        from participant_identity.participant_auth_identifiers value
        where value.normalized_value_private = normalized
          and value.status in (
            'ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED'
          )
      ) then
        contact := null;
      else
        select value.* into claim
        from participant_identity.production_participant_enrollment_claims
          value
        where value.email_identity_hash = email_hash
          and value.status = 'PENDING'
        for update;
        if found and (
          claim.tournament_id <> target_id
          or claim.player_id <> contact.player_id
          or claim.source_configuration_revision
            <> contact.configuration_revision
        ) then
          raise exception using errcode = '42501',
            message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_CLAIM_COLLISION';
        end if;
        if not found then
          insert into participant_identity
            .production_participant_enrollment_claims (
              tournament_id, player_id, email_identity_hash,
              client_request_hash, source_configuration_revision
            ) values (
              target_id, contact.player_id, email_hash, client_hash,
              contact.configuration_revision
            ) returning * into claim;
          insert into participant_identity.identity_audit_events (
            event_type, tournament_id, player_id, actor_name,
            request_id, safe_metadata
          ) values (
            'FUTURE_TOURNAMENT_PARTICIPANT_FIRST_LOGIN_CLAIMED',
            target_id, contact.player_id,
            'future-runtime-controlled-first-login-v1',
            claim.claim_id::text,
            pg_catalog.jsonb_build_object(
              'rawIdentifierStoredInAudit', false,
              'authUserCreated', false
            )
          );
        elsif claim.expires_at <= pg_catalog.clock_timestamp() then
          update participant_identity.production_participant_enrollment_claims
          set expires_at = pg_catalog.clock_timestamp() + interval '10 minutes',
            client_request_hash = client_hash,
            updated_at = pg_catalog.clock_timestamp()
          where claim_id = claim.claim_id
          returning * into claim;
        end if;
        return pg_catalog.jsonb_build_object(
          'ok', true, 'allowed', false,
          'provisioningRequired', true,
          'claimId', claim.claim_id,
          'email', normalized,
          'playerId', contact.player_id,
          'tournamentId', target_id,
          'recoveryAuthUserId', null
        );
      end if;
    end if;
  end if;

  if contact.player_id is null or reason <> 'APPROVED' then
    insert into participant_identity.participant_auth_otp_attempts (
      request_id, email_identity_hash, client_request_hash,
      status, safe_reason, verification_type
    ) values (
      request_value, email_hash, client_hash,
      'REJECTED', 'NOT_ELIGIBLE', 'email'
    );
    return pg_catalog.jsonb_build_object(
      'ok', true, 'allowed', false, 'requestId', request_value,
      'email', null, 'authUserId', null, 'playerId', null,
      'verificationType', null, 'provisioningRequired', false,
      'tournamentId', target_id
    );
  end if;
  if exists (
    select 1
    from participant_identity.participant_auth_otp_attempts attempt
    where attempt.player_id = contact.player_id
      and attempt.status in ('AUTHORIZED', 'SENT')
      and attempt.requested_at > pg_catalog.clock_timestamp()
        - interval '60 seconds'
  ) then
    reason := 'COOLDOWN';
  end if;
  insert into participant_identity.participant_auth_otp_attempts (
    request_id, tournament_id, player_id, auth_user_id,
    email_identity_hash, client_request_hash, status, safe_reason,
    verification_type
  ) values (
    request_value, target_id, contact.player_id, link.auth_user_id,
    email_hash, client_hash,
    case when reason = 'APPROVED' then 'AUTHORIZED' else 'REJECTED' end,
    reason, selected_type
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'allowed', reason = 'APPROVED',
    'requestId', request_value,
    'email', case when reason = 'APPROVED' then normalized else null end,
    'authUserId', case when reason = 'APPROVED'
      then link.auth_user_id else null end,
    'playerId', case when reason = 'APPROVED'
      then contact.player_id else null end,
    'tournamentId', target_id,
    'verificationType', case when reason = 'APPROVED'
      then selected_type else null end,
    'provisioningRequired', false
  );
end;
$_$;


ALTER FUNCTION public.authorize_production_future_participant_otp_request_v1(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_future_participant_otp_verification_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_future_participant_otp_verification_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  attempt participant_identity.participant_auth_otp_attempts%rowtype;
  request_value uuid := nullif(input->>'request_id', '')::uuid;
  email_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'email_identity_hash', ''
  )));
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  select otp.* into attempt
  from participant_identity.participant_auth_otp_attempts otp
  join participant_identity.future_tournament_participant_bindings_v1 binding
    on binding.tournament_id = otp.tournament_id
   and binding.player_id = otp.player_id
   and binding.contact_state = 'APPROVED'
  join scoring_authority.tournament_players membership
    on membership.tournament_id = otp.tournament_id
   and membership.player_id = otp.player_id
   and membership.participation_status = 'ACTIVE'
  join participant_identity.participant_identity_contacts contact
    on contact.tournament_id = otp.tournament_id
   and contact.player_id = otp.player_id
   and contact.identity_active
   and encode(extensions.digest(
     contact.email_normalized::text, 'sha256'
   ), 'hex') = email_hash
  join participant_identity.user_player_links link
    on link.auth_user_id = otp.auth_user_id
   and link.player_id = otp.player_id
   and link.status in ('PENDING', 'ACTIVE')
   and link.revoked_at is null
  join participant_identity.participant_auth_identifiers identifier
    on identifier.auth_user_id = otp.auth_user_id
   and identifier.player_id = otp.player_id
   and identifier.identifier_type = 'EMAIL'
   and identifier.status in ('VERIFICATION_PENDING', 'VERIFIED')
   and identifier.revoked_at is null
   and identifier.normalized_value_private = contact.email_normalized
   and encode(extensions.digest(
     identifier.normalized_value_private::text, 'sha256'
   ), 'hex') = email_hash
  join auth.users auth_user
    on auth_user.id = otp.auth_user_id
   and pg_catalog.lower(pg_catalog.btrim(coalesce(auth_user.email, '')))
     = contact.email_normalized
  where otp.request_id = request_value
    and otp.tournament_id = target_id
    and otp.status = 'SENT'
    and otp.email_identity_hash = email_hash
    and otp.sent_at > pg_catalog.clock_timestamp() - interval '15 minutes'
    and (
      (otp.verification_type = 'email'
        and binding.enrollment_state = 'ENROLLED'
        and link.status = 'ACTIVE'
        and identifier.status = 'VERIFIED'
        and auth_user.email_confirmed_at is not null)
      or
      (otp.verification_type = 'signup'
        and binding.enrollment_state = 'NOT_ENROLLED'
        and link.status = 'PENDING'
        and identifier.status = 'VERIFICATION_PENDING'
        and auth_user.email_confirmed_at is null
        and auth_user.raw_app_meta_data->>'provisioning_scope'
          = 'production_controlled_first_login'
        and auth_user.raw_app_meta_data->>'player_id' = otp.player_id
        and auth_user.raw_app_meta_data->>'tournament_id' = target_id)
    );
  if not found then
    return pg_catalog.jsonb_build_object('ok', true, 'allowed', false);
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'allowed', true,
    'authUserId', attempt.auth_user_id,
    'playerId', attempt.player_id,
    'tournamentId', attempt.tournament_id,
    'verificationType', attempt.verification_type
  );
end;
$$;


ALTER FUNCTION public.authorize_production_future_participant_otp_verification_v1(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_google_writer_provider_fence_removal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_google_writer_provider_fence_removal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  raise exception using errcode = '55000',
    message = 'PRODUCTION_GOOGLE_WRITER_PROTECTED_RANGE_REMOVAL_RETIRED';
end;
$$;


ALTER FUNCTION public.authorize_production_google_writer_provider_fence_removal(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_participant_otp_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_participant_otp_request(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare resource production_control.resource_scope%rowtype;
declare normalized text := lower(btrim(coalesce(input->>'email', '')));
declare client_hash text := lower(btrim(coalesce(input->>'client_request_hash', '')));
declare email_hash text := encode(extensions.digest(normalized::text, 'sha256'), 'hex');
declare contact participant_identity.participant_identity_contacts%rowtype;
declare link participant_identity.user_player_links%rowtype;
declare identifier participant_identity.participant_auth_identifiers%rowtype;
declare auth_user auth.users%rowtype;
declare claim participant_identity.production_participant_enrollment_claims%rowtype;
declare request uuid := extensions.gen_random_uuid();
declare selected_type text := 'email';
declare reason text := 'NOT_ELIGIBLE';
begin
  resource := production_control.assert_production_participant_identity_cutover();
  if client_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'PRODUCTION_AUTH_HASHED_REQUEST_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(least('client:' || client_hash, 'email:' || email_hash), 0));
  perform pg_advisory_xact_lock(hashtextextended(greatest('client:' || client_hash, 'email:' || email_hash), 0));
  if (select count(*) from participant_identity.participant_auth_otp_attempts
      where client_request_hash = client_hash and requested_at > now() - interval '15 minutes') >= 5
     or (select count(*) from participant_identity.participant_auth_otp_attempts
      where email_identity_hash = email_hash and requested_at > now() - interval '15 minutes') >= 3 then
    return jsonb_build_object('ok', true, 'allowed', false, 'requestId', request,
      'email', null, 'playerId', null, 'provisioningRequired', false);
  end if;

  select approved.* into contact
  from participant_identity.participant_identity_contacts approved
  join scoring_authority.tournament_players membership
    on membership.tournament_id = approved.tournament_id and membership.player_id = approved.player_id
    and membership.participation_status = 'ACTIVE'
  join participant_identity.identity_context_revisions current_revision
    on current_revision.tournament_id = approved.tournament_id
    and current_revision.context_revision = approved.configuration_revision
  join participant_identity.identity_config_import_runs import_run
    on import_run.tournament_id = approved.tournament_id
    and import_run.configuration_revision = approved.configuration_revision
    and import_run.source_fingerprint = current_revision.configuration_fingerprint
    and import_run.status = 'APPROVED' and import_run.approved_at is not null
  where approved.tournament_id = '2026' and approved.identity_active
    and approved.source_workbook_id = resource.google_workbook_id
    and approved.email_normalized = normalized
    and split_part(approved.email_normalized, '@', 2)
      !~* '(^|\.)(example\.(com|net|org)|invalid|test|localhost)$';

  if found then
    select * into link from participant_identity.user_player_links
      where player_id = contact.player_id and status in ('PENDING', 'ACTIVE', 'SUSPENDED') for update;
    if found then
      select * into identifier from participant_identity.participant_auth_identifiers
        where player_id = contact.player_id and auth_user_id = link.auth_user_id
          and identifier_type = 'EMAIL'
          and status in ('VERIFICATION_PENDING', 'VERIFIED') for update;
      select * into auth_user from auth.users where id = link.auth_user_id;
      if not found or identifier.normalized_value_private is distinct from normalized
         or lower(btrim(coalesce(auth_user.email, ''))) is distinct from normalized
         or auth_user.raw_app_meta_data->>'player_id' is distinct from contact.player_id
         or auth_user.raw_app_meta_data->>'tournament_id' is distinct from '2026'
         or auth_user.raw_app_meta_data->>'provisioning_scope' not in (
           'production_controlled_first_login', 'production_shadow_director_certification'
         ) then
        contact := null;
      elsif link.status = 'ACTIVE' and identifier.status = 'VERIFIED'
        and auth_user.email_confirmed_at is not null then
        selected_type := 'email'; reason := 'APPROVED';
      elsif link.status = 'PENDING' and identifier.status = 'VERIFICATION_PENDING'
        and auth_user.email_confirmed_at is null then
        selected_type := 'signup'; reason := 'APPROVED';
      else
        contact := null;
      end if;
    else
      -- A pre-existing Auth email or a link/identifier owned by another Player
      -- is a collision, never an invitation to attach by display name/email.
      if exists (select 1 from auth.users where lower(btrim(coalesce(email, ''))) = normalized)
         or exists (select 1 from participant_identity.user_player_links
           where auth_user_id in (select id from auth.users where lower(btrim(coalesce(email, ''))) = normalized))
         or exists (select 1 from participant_identity.participant_auth_identifiers
           where normalized_value_private = normalized and status in ('ELIGIBLE','VERIFICATION_PENDING','VERIFIED')) then
        contact := null;
      else
        select * into claim from participant_identity.production_participant_enrollment_claims
          where email_identity_hash = email_hash and status = 'PENDING' for update;
        if found and (claim.player_id <> contact.player_id
          or claim.source_configuration_revision <> contact.configuration_revision) then
          raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_CLAIM_COLLISION';
        end if;
        if not found then
          insert into participant_identity.production_participant_enrollment_claims (
            tournament_id, player_id, email_identity_hash, client_request_hash,
            source_configuration_revision
          ) values ('2026', contact.player_id, email_hash, client_hash, contact.configuration_revision)
          returning * into claim;
          insert into participant_identity.identity_audit_events (
            event_type, tournament_id, player_id, actor_name, request_id, safe_metadata
          ) values (
            'PRODUCTION_PARTICIPANT_FIRST_LOGIN_CLAIMED', '2026', contact.player_id,
            'production-controlled-first-login', claim.claim_id::text,
            jsonb_build_object('rawIdentifierStoredInAudit', false, 'authUserCreated', false)
          );
        elsif claim.expires_at <= now() then
          update participant_identity.production_participant_enrollment_claims set
            expires_at = now() + interval '10 minutes', client_request_hash = client_hash, updated_at = now()
          where claim_id = claim.claim_id returning * into claim;
        end if;
        return jsonb_build_object('ok', true, 'allowed', false,
          'provisioningRequired', true, 'claimId', claim.claim_id,
          'email', normalized, 'playerId', contact.player_id,
          'recoveryAuthUserId', null);
      end if;
    end if;
  end if;

  if contact is null or reason <> 'APPROVED' then
    insert into participant_identity.participant_auth_otp_attempts (
      request_id, email_identity_hash, client_request_hash, status, safe_reason, verification_type
    ) values (request, email_hash, client_hash, 'REJECTED', 'NOT_ELIGIBLE', 'email');
    return jsonb_build_object('ok', true, 'allowed', false, 'requestId', request,
      'email', null, 'authUserId', null, 'playerId', null,
      'verificationType', null, 'provisioningRequired', false);
  end if;

  if exists (select 1 from participant_identity.participant_auth_otp_attempts
    where player_id = contact.player_id and status in ('AUTHORIZED','SENT')
      and requested_at > now() - interval '60 seconds') then
    reason := 'COOLDOWN';
  end if;
  insert into participant_identity.participant_auth_otp_attempts (
    request_id, tournament_id, player_id, auth_user_id, email_identity_hash,
    client_request_hash, status, safe_reason, verification_type
  ) values (
    request, '2026', contact.player_id, link.auth_user_id, email_hash, client_hash,
    case when reason = 'APPROVED' then 'AUTHORIZED' else 'REJECTED' end,
    reason, selected_type
  );
  return jsonb_build_object('ok', true, 'allowed', reason = 'APPROVED',
    'requestId', request, 'email', case when reason = 'APPROVED' then normalized else null end,
    'authUserId', case when reason = 'APPROVED' then link.auth_user_id else null end,
    'playerId', case when reason = 'APPROVED' then contact.player_id else null end,
    'verificationType', case when reason = 'APPROVED' then selected_type else null end,
    'provisioningRequired', false);
end;
$_$;


ALTER FUNCTION public.authorize_production_participant_otp_request(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_participant_otp_verification(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_participant_otp_verification(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth', 'extensions', 'pg_temp'
    AS $$
declare request uuid := nullif(input->>'request_id', '')::uuid;
declare email_hash text := lower(btrim(coalesce(input->>'email_identity_hash', '')));
declare attempt participant_identity.participant_auth_otp_attempts%rowtype;
begin
  perform production_control.assert_production_participant_identity_cutover();
  select otp.* into attempt from participant_identity.participant_auth_otp_attempts otp
  join participant_identity.user_player_links link
    on link.auth_user_id = otp.auth_user_id and link.player_id = otp.player_id
    and link.status in ('PENDING','ACTIVE')
  join participant_identity.participant_auth_identifiers identifier
    on identifier.auth_user_id = otp.auth_user_id and identifier.player_id = otp.player_id
    and identifier.identifier_type = 'EMAIL'
    and identifier.status in ('VERIFICATION_PENDING','VERIFIED')
    and encode(extensions.digest(identifier.normalized_value_private::text, 'sha256'), 'hex') = email_hash
  where otp.request_id = request and otp.status = 'SENT'
    and otp.email_identity_hash = email_hash and otp.sent_at > now() - interval '15 minutes';
  if not found then return jsonb_build_object('ok', true, 'allowed', false); end if;
  return jsonb_build_object('ok', true, 'allowed', true,
    'authUserId', attempt.auth_user_id, 'playerId', attempt.player_id,
    'tournamentId', attempt.tournament_id, 'verificationType', attempt.verification_type);
end;
$$;


ALTER FUNCTION public.authorize_production_participant_otp_verification(input jsonb) OWNER TO postgres;

--
-- Name: authorize_production_step11_odds_service_bridge(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.authorize_production_step11_odds_service_bridge(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth', 'extensions'
    AS $_$
declare
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  runtime production_control.odds_calculation_runtime%rowtype;
  worker_contract production_control.worker_contracts%rowtype;
  director_user_id uuid;
  entitlement_revision_value bigint;
  identity_matches integer;
  candidate_hostname_value text := lower(btrim(coalesce(input->>'candidate_hostname', '')));
  deployment_commit_value text := lower(btrim(coalesce(input->>'deployment_commit', '')));
  source_fingerprint_value text := lower(btrim(coalesce(input->>'source_fingerprint', '')));
  request_fingerprint_value text := lower(btrim(coalesce(input->>'request_fingerprint', '')));
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STEP11_ODDS_SERVICE_ROLE_REQUIRED';
  end if;

  -- This bridge must also authorize the initial STAGE and ENABLE operations,
  -- so it proves the exact resource tuple without requiring an already-staged
  -- release or enabled worker. The state-specific checks below bind DORMANT or
  -- STAGED to the exact candidate and allow no authority transition.
  perform production_control.assert_exact_cutover_resource_scope(input, false);

  if input->>'contract_version'
       is distinct from 'production-step11-odds-service-authorization-v1'
     or input->>'operation'
       is distinct from 'AUTHORIZE_PRODUCTION_STEP11_ODDS_SERVICE_BRIDGE'
     or input->>'operation_mode' is distinct from 'STEP11_REHEARSAL'
     or input->>'expected_director_player_id' is distinct from 'CB01'
     or input->>'required_role' is distinct from 'DIRECTOR'
     or input->'request_token_verified' is distinct from 'true'::jsonb
     or input->'service_authorization_enabled' is distinct from 'true'::jsonb
     or input->'live_production_authorization' is distinct from 'false'::jsonb
     or input->'publication_created' is distinct from 'false'::jsonb
     or input->'mirror_created' is distinct from 'false'::jsonb
     or coalesce((input->>'external_google_writes')::integer, -1) <> 0
     or request_fingerprint_value !~ '^[0-9a-f]{64}$'
     or deployment_commit_value !~ '^[0-9a-f]{40}$'
     or source_fingerprint_value !~ '^[0-9a-f]{64}$'
     or input->>'vercel_project_id'
       is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'canonical_domain' is distinct from 'https://baggerinv.com'
     or coalesce((input->>'tournament_year')::integer, 0) <> 2026
     or input->>'worker_name' is distinct from 'ODDS_CALCULATION'
     or candidate_hostname_value
       !~ '^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.vercel\.app$'
     or candidate_hostname_value in (
       'baggerinv.com', 'www.baggerinv.com', 'bagger-inv.vercel.app'
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STEP11_ODDS_SERVICE_EXACT_SCOPE_REQUIRED';
  end if;

  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict runtime
  from production_control.odds_calculation_runtime
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict worker_contract
  from production_control.worker_contracts
  where worker_name = 'ODDS_CALCULATION';

  if resource.current_tournament_read_authority <> 'GOOGLE'
     or resource.scoring_authority <> 'GOOGLE'
     or resource.participant_identity_authority <> 'PASSPORT'
     or resource.public_supabase_reads_enabled
     or resource.scoring_ingress_enabled
     or resource.google_writes_enabled
     or resource.auth_user_creation_enabled
     or resource.odds_publication_enabled
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.state not in ('DORMANT', 'STAGED')
     or worker_contract.scope_key <> 'BAGGER_INV_PRODUCTION'
     or worker_contract.domain <> 'CHAMPIONSHIP_ODDS_CALCULATION'
     or worker_contract.operation_kind <> 'DURABLE_CALCULATION'
     or worker_contract.requires_google_read
     or worker_contract.requires_google_write
     or worker_contract.requires_odds_publication
     or worker_contract.scheduler_installed
     or worker_contract.authoritative_write_allowed
     or exists (
       select 1
       from production_control.worker_controls worker
       where worker.worker_name <> 'ODDS_CALCULATION'
         and (worker.enabled or worker.scheduler_installed or worker.google_writes_allowed)
     )
     or exists (
       select 1
       from production_control.worker_controls worker
       where worker.worker_name in ('ODDS_CALCULATION', 'ODDS_GOOGLE_MIRROR')
         and worker.google_writes_allowed
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STEP11_ODDS_SERVICE_LIVE_AUTHORITY_FORBIDDEN';
  end if;

  if activation.state = 'DORMANT' then
    if activation.expected_deployment_commit is not null
       or activation.expected_source_fingerprint is not null
       or runtime.enabled
       or runtime.operation_mode <> 'DORMANT'
       or runtime.deployment_commit is not null
       or runtime.activation_revision is not null
       or runtime.candidate_hostname is not null
       or worker_contract.operation_allowed
       or resource.workers_enabled
       or exists (
         select 1 from production_control.worker_controls worker
         where worker.enabled or worker.scheduler_installed or worker.google_writes_allowed
       ) then
      raise exception using errcode = '42501',
        message = 'PRODUCTION_STEP11_ODDS_SERVICE_DORMANT_STATE_REQUIRED';
    end if;
  elsif activation.expected_deployment_commit is distinct from deployment_commit_value
     or activation.expected_vercel_project_id
       is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or activation.expected_source_fingerprint is distinct from source_fingerprint_value
     or not (
       (
         not runtime.enabled
         and runtime.operation_mode = 'DORMANT'
         and runtime.deployment_commit is null
         and runtime.activation_revision is null
         and runtime.candidate_hostname is null
         and not worker_contract.operation_allowed
         and not resource.workers_enabled
         and not exists (
           select 1 from production_control.worker_controls worker
           where worker.enabled or worker.scheduler_installed or worker.google_writes_allowed
         )
       )
       or
       (
         runtime.enabled
         and runtime.operation_mode = 'STEP11_REHEARSAL'
         and runtime.deployment_commit = deployment_commit_value
         and runtime.activation_revision = activation.activation_revision
         and lower(runtime.candidate_hostname) = candidate_hostname_value
         and worker_contract.operation_allowed
         and resource.workers_enabled
         and exists (
           select 1 from production_control.worker_controls worker
           where worker.worker_name = 'ODDS_CALCULATION'
             and worker.enabled and not worker.scheduler_installed
             and not worker.google_writes_allowed
         )
       )
     ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STEP11_ODDS_SERVICE_STAGED_STATE_REQUIRED';
  end if;

  -- All physical identity records must resolve to one and only one confirmed
  -- CB01 Director. No caller-provided Auth UUID or email participates in the
  -- lookup, so the service caller cannot choose another identity.
  select count(*) into identity_matches
  from participant_identity.production_auth_candidates candidate
  join auth.users auth_user
    on auth_user.id = candidate.auth_user_id
   and auth_user.email_confirmed_at is not null
   and auth_user.raw_app_meta_data->>'provisioning_scope'
     = 'production_shadow_director_certification'
   and auth_user.raw_app_meta_data->>'player_id' = 'CB01'
   and auth_user.raw_app_meta_data->>'tournament_id' = '2026'
   and encode(extensions.digest(
     lower(btrim(coalesce(auth_user.email, '')))::text, 'sha256'
   ), 'hex') = candidate.email_identity_hash
  join participant_identity.user_player_links player_link
    on player_link.auth_user_id = candidate.auth_user_id
   and player_link.player_id = candidate.player_id
   and player_link.email_identity_hash = candidate.email_identity_hash
   and player_link.status = 'ACTIVE'
  join participant_identity.participant_auth_identifiers identifier
    on identifier.auth_user_id = candidate.auth_user_id
   and identifier.player_id = candidate.player_id
   and identifier.identifier_type = 'EMAIL'
   and identifier.status = 'VERIFIED'
   and identifier.verified_at is not null
   and encode(extensions.digest(
     identifier.normalized_value_private::text, 'sha256'
   ), 'hex') = candidate.email_identity_hash
  join production_control.director_entitlements entitlement
    on entitlement.auth_user_id = candidate.auth_user_id
   and entitlement.tournament_id = candidate.tournament_id
   and entitlement.player_id = candidate.player_id
   and entitlement.role = 'DIRECTOR'
   and entitlement.status = 'ACTIVE'
   and entitlement.revoked_at is null
  join participant_identity.tournament_roles tournament_role
    on tournament_role.auth_user_id = candidate.auth_user_id
   and tournament_role.tournament_id = candidate.tournament_id
   and tournament_role.role = 'DIRECTOR'
   and tournament_role.role_active
   and tournament_role.revoked_at is null
  join scoring_authority.tournament_players membership
    on membership.tournament_id = candidate.tournament_id
   and membership.player_id = candidate.player_id
   and membership.participation_status = 'ACTIVE'
  where candidate.tournament_id = '2026'
    and candidate.player_id = 'CB01'
    and candidate.project_ref = 'ymqhhtxaywtqllynrmxe'
    and candidate.source_workbook_id
      = '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
    and candidate.status = 'VERIFIED'
    and candidate.verified_at is not null;

  if identity_matches <> 1
     or (select count(*) from participant_identity.production_auth_candidates
         where tournament_id = '2026' and status = 'VERIFIED') <> 1
     or (select count(*) from participant_identity.user_player_links
         where player_id = 'CB01' and status = 'ACTIVE') <> 1
     or (select count(*) from participant_identity.participant_auth_identifiers
         where player_id = 'CB01' and identifier_type = 'EMAIL'
           and status = 'VERIFIED' and verified_at is not null) <> 1
     or (select count(*) from production_control.director_entitlements
         where tournament_id = '2026' and role = 'DIRECTOR'
           and status = 'ACTIVE' and revoked_at is null) <> 1
     or (select count(*) from participant_identity.tournament_roles
         where tournament_id = '2026' and role = 'DIRECTOR'
           and role_active and revoked_at is null) <> 1 then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STEP11_ODDS_SINGLE_CONFIRMED_CB01_DIRECTOR_REQUIRED';
  end if;

  select candidate.auth_user_id,
    coalesce((select max(event.event_id)
      from production_control.director_entitlement_events event
      where event.entitlement_id = entitlement.entitlement_id), 0)
  into strict director_user_id, entitlement_revision_value
  from participant_identity.production_auth_candidates candidate
  join production_control.director_entitlements entitlement
    on entitlement.auth_user_id = candidate.auth_user_id
   and entitlement.tournament_id = candidate.tournament_id
   and entitlement.player_id = candidate.player_id
   and entitlement.role = 'DIRECTOR'
   and entitlement.status = 'ACTIVE'
  where candidate.tournament_id = '2026'
    and candidate.player_id = 'CB01'
    and candidate.status = 'VERIFIED';

  if director_user_id is null or entitlement_revision_value < 1 then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_STEP11_ODDS_DIRECTOR_ENTITLEMENT_REVISION_REQUIRED';
  end if;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_STEP11_ODDS_SERVICE_AUTHORIZED',
    'CHAMPIONSHIP_ODDS_CALCULATION', '2026',
    'step11-odds-service-bridge:CB01', request_fingerprint_value, 'AUTHORIZED',
    jsonb_build_object(
      'contract_version', 'production-step11-odds-service-authorization-v1',
      'operation_mode', 'STEP11_REHEARSAL',
      'deployment_commit', deployment_commit_value,
      'candidate_hostname', candidate_hostname_value,
      'director_player_id', 'CB01',
      'role', 'DIRECTOR',
      'entitlement_revision', entitlement_revision_value,
      'activation_revision', activation.activation_revision,
      'runtime_activation_revision', runtime.activation_revision,
      'runtime_enabled', runtime.enabled,
      'runtime_operation_mode', runtime.operation_mode,
      'worker_contract_operation_allowed', worker_contract.operation_allowed,
      'worker_contract_scheduler_installed', worker_contract.scheduler_installed,
      'worker_contract_authoritative_write_allowed',
        worker_contract.authoritative_write_allowed,
      'auth_user_id_stored', false,
      'request_token_stored', false,
      'live_production_authorization', false,
      'publication_created', false,
      'mirror_created', false,
      'external_google_writes', 0
    )
  );

  return jsonb_build_object(
    'ok', true,
    'active', true,
    'contractVersion', 'production-step11-odds-service-authorization-v1',
    'operationMode', 'STEP11_REHEARSAL',
    'tournamentId', '2026',
    'directorPlayerId', 'CB01',
    'role', 'DIRECTOR',
    'entitlementRevision', entitlement_revision_value,
    'activationRevision', activation.activation_revision,
    'runtimeActivationRevision', runtime.activation_revision,
    'runtimeEnabled', runtime.enabled,
    'runtimeOperationMode', runtime.operation_mode,
    'workerContractOperationAllowed', worker_contract.operation_allowed,
    'workerContractSchedulerInstalled', worker_contract.scheduler_installed,
    'workerContractAuthoritativeWriteAllowed',
      worker_contract.authoritative_write_allowed,
    'auditRecorded', true,
    'publicationCreated', false,
    'mirrorCreated', false,
    'externalGoogleWrites', 0
  );
end;
$_$;


ALTER FUNCTION public.authorize_production_step11_odds_service_bridge(input jsonb) OWNER TO postgres;

--
-- Name: begin_abort_production_google_writer_provider_fence_install(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_abort_production_google_writer_provider_fence_install(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  dispatch
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  restore_quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  waf_epoch
    production_control.vercel_writer_critical_waf_epochs%rowtype;
  restore_waf_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  prior_status text;
  request_identifier uuid;
  payload_hash_value text := production_control.cutover_payload_hash(input);
  quiescence_not_before timestamptz;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'operation' is distinct from
       'BEGIN_ABORT_PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL'
     or coalesce(input->>'fence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'install_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'abort_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'restore_quiesce_evidence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_BEGIN_INPUT_INVALID';
  end if;
  request_identifier := (input->>'abort_request_id')::uuid;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = (input->>'fence_id')::uuid
    and value.install_request_id = (input->>'install_request_id')::uuid
  for update;
  if fence.status in ('ABORTING', 'FAILED') then
    if fence.abort_request_id is distinct from request_identifier
       or fence.abort_begin_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or fence.abort_begin_payload_hash is distinct from payload_hash_value
       or fence.restore_quiesce_evidence_id is distinct from
         (input->>'restore_quiesce_evidence_id')::uuid
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_BEGIN_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.google_writer_provider_fence_response(fence, true);
  end if;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into dispatch
  from production_control.google_writer_provider_fence_install_dispatches value
  where value.fence_id = fence.fence_id
  order by value.attempt desc
  limit 1
  for update;
  select * into strict restore_quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id =
    (input->>'restore_quiesce_evidence_id')::uuid
  for update;
  select * into strict waf_epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = fence.critical_waf_epoch_id
  for update;
  select * into strict restore_waf_observation
  from production_control.vercel_writer_critical_waf_observations value
  where value.observation_id = restore_quiesce.critical_waf_observation_id
    and value.epoch_id = waf_epoch.epoch_id;
  prior_status := fence.status;
  quiescence_not_before :=
    waf_epoch.critical_active_at + interval '1810 seconds';
  if fence.status not in ('INSTALLING', 'INSTALLED', 'REMOVAL_AUTHORIZED')
     or dispatch.dispatch_id is null
     or dispatch.outcome_status is distinct from 'TARGET_CONFIRMED'
     or restore_quiesce.status is distinct from 'VERIFIED'
     or restore_quiesce.critical_waf_epoch_id is distinct from
       waf_epoch.epoch_id
     or restore_quiesce.critical_waf_quiesce_stage is distinct from
       'RESTORE_REATTEST'
     or restore_waf_observation.expires_at <=
       pg_catalog.clock_timestamp()
     or waf_epoch.status is distinct from 'FENCE_BOUND'
     or waf_epoch.bound_fence_id is distinct from fence.fence_id
     or waf_epoch.bound_quiesce_evidence_id is null
     or (waf_epoch.transition_mode <> 'ROLLBACK' and
       waf_epoch.bound_quiesce_evidence_id is distinct from
         fence.quiesce_evidence_id)
     or (waf_epoch.transition_mode = 'ROLLBACK' and
       waf_epoch.bound_quiesce_evidence_id = fence.quiesce_evidence_id)
     or restore_waf_observation.evidence_stage is distinct from
       'CRITICAL_REATTEST'
     or waf_epoch.latest_critical_reattest_observation_id is distinct from
       restore_waf_observation.observation_id
     or restore_quiesce.purpose is distinct from fence.lifecycle_mode
     or (fence.lifecycle_mode = 'REHEARSAL' and
       waf_epoch.transition_mode is distinct from 'REHEARSAL')
     or (fence.lifecycle_mode = 'CUTOVER' and
       activation.state = 'ROLLED_BACK' and
       waf_epoch.transition_mode is distinct from 'ROLLBACK')
     or (fence.lifecycle_mode = 'CUTOVER' and
       activation.state <> 'ROLLED_BACK' and
       waf_epoch.transition_mode is distinct from 'CUTOVER')
     or restore_quiesce.candidate_deployment_id is distinct from
       fence.candidate_deployment_id
     or restore_quiesce.candidate_deployment_commit is distinct from
       fence.candidate_deployment_commit
     or restore_quiesce.expires_at <= pg_catalog.clock_timestamp()
     or restore_quiesce.owner_freeze_expires_at <= pg_catalog.clock_timestamp()
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = restore_quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or fence.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or fence.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or fence.actor_id is distinct from input->>'actor_id'
     or fence.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or (fence.lifecycle_mode = 'CUTOVER' and (
       gate.admission_deployment_id is distinct from input->>'deployment_id'
       or activation.expected_deployment_commit is distinct from
         pg_catalog.lower(input->>'deployment_commit')
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       input->>'deployment_id' is distinct from fence.candidate_deployment_id
       or pg_catalog.lower(input->>'deployment_commit') is distinct from
         fence.candidate_deployment_commit
     ))
     or (fence.lifecycle_mode = 'CUTOVER' and fence.status = 'INSTALLING' and (
       activation.state is distinct from 'GOOGLE_LEASE_ARMED'
       or resource.participant_identity_authority is distinct from 'SUPABASE'
       or resource.current_tournament_read_authority is distinct from 'SUPABASE'
       or gate.state is distinct from 'OPEN'
       or not gate.admission_protocol_enforced
       or activation.active_google_writer_provider_fence_id is not null
       or activation.active_google_writer_provider_verification_id is not null
       or gate.google_writer_provider_fence_id is not null
       or gate.google_writer_provider_verification_id is not null
     ))
     or (fence.lifecycle_mode = 'CUTOVER' and
       fence.status in ('INSTALLED', 'REMOVAL_AUTHORIZED') and (
       not (
         (activation.state = 'GOOGLE_LEASE_ARMED'
           and resource.participant_identity_authority = 'SUPABASE'
           and resource.current_tournament_read_authority = 'SUPABASE'
           and gate.state = 'OPEN' and gate.admission_state = 'OPEN'
           and gate.admission_protocol_enforced
           and gate.active_closure_id is null)
         or
         (activation.state in ('DORMANT', 'ROLLED_BACK')
           and resource.participant_identity_authority = 'PASSPORT'
           and resource.current_tournament_read_authority = 'GOOGLE'
           and gate.state = 'PAUSED' and gate.admission_state = 'CLOSED'
           and gate.admission_protocol_enforced
           and gate.active_closure_id is not null)
       )
       or activation.active_google_writer_provider_fence_id is distinct from
         fence.fence_id
       or gate.google_writer_provider_fence_id is distinct from fence.fence_id
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       fence.status not in ('INSTALLING', 'INSTALLED')
       or activation.state is distinct from 'DORMANT'
       or resource.participant_identity_authority is distinct from 'PASSPORT'
       or resource.current_tournament_read_authority is distinct from 'GOOGLE'
       or gate.state is distinct from 'PAUSED'
       or (fence.status = 'INSTALLING' and (
         gate.admission_state is distinct from 'OPEN'
         or gate.admission_protocol_enforced
         or gate.active_closure_id is not null
       ))
       or (fence.status = 'INSTALLED' and (
         gate.admission_state is distinct from 'CLOSED'
         or not gate.admission_protocol_enforced
         or gate.active_closure_id is null
         or activation.active_google_writer_provider_fence_id is distinct from
           fence.fence_id
         or gate.google_writer_provider_fence_id is distinct from fence.fence_id
       ))
     ))
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or ((activation.first_supabase_write_possible_at is not null
          or activation.first_supabase_write_observed_at is not null) and not (
       fence.lifecycle_mode = 'CUTOVER'
       and fence.status in ('INSTALLED', 'REMOVAL_AUTHORIZED')
       and activation.state = 'ROLLED_BACK'
       and gate.admission_state = 'CLOSED'
       and gate.active_closure_id is not null
     ))
     or activation.active_transition_epoch_id is not null
     or resource.scoring_authority is distinct from 'GOOGLE'
     or gate.authority is distinct from 'GOOGLE'
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_BEGIN_NOT_SAFE';
  end if;
  update production_control.google_writer_provider_fences
  set status = 'ABORTING',
      abort_origin_status = prior_status,
      abort_request_id = request_identifier,
      abort_begin_request_fingerprint =
        pg_catalog.lower(input->>'request_fingerprint'),
      abort_begin_payload_hash = payload_hash_value,
      abort_requested_at = pg_catalog.now(),
      abort_provider_quiescence_not_before = quiescence_not_before,
      restore_quiesce_evidence_id = restore_quiesce.evidence_id,
      restore_global_writer_stop_active_at =
        waf_epoch.critical_active_at,
      updated_at = pg_catalog.now()
  where fence_id = fence.fence_id
  returning * into fence;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result,
    details
  ) values (
    'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_ABORT_RESERVED',
    'SCORING_AUTHORITY', '2026', fence.actor_id,
    fence.abort_begin_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'fence_id', fence.fence_id,
      'abort_request_id', fence.abort_request_id,
      'prior_status', prior_status,
      'new_status', 'ABORTING',
      'install_dispatch_id', dispatch.dispatch_id,
      'provider_quiescence_not_before',
        fence.abort_provider_quiescence_not_before,
      'restore_quiesce_evidence_id', fence.restore_quiesce_evidence_id,
      'critical_waf_epoch_id', fence.critical_waf_epoch_id,
      'restore_global_writer_stop_active_at',
        fence.restore_global_writer_stop_active_at,
      'admission_reservation_active', true
    )
  );
  return production_control.google_writer_provider_fence_response(fence, false);
end;
$_$;


ALTER FUNCTION public.begin_abort_production_google_writer_provider_fence_install(input jsonb) OWNER TO postgres;

--
-- Name: begin_participant_phone_public_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_participant_phone_public_request(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'public', 'pg_temp'
    AS $_$
declare client_hash text := lower(btrim(coalesce(input->>'client_fingerprint', '')));
declare identifier_hash text := lower(btrim(coalesce(input->>'identifier_fingerprint', '')));
declare recent_client integer := 0;
declare recent_identifier integer := 0;
declare cooldown_seconds integer := 0;
declare allowed_value boolean := false;
begin
  if client_hash !~ '^[0-9a-f]{64}$' or identifier_hash !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'allowed', false, 'code', 'PHONE_OTP_CONTEXT_INVALID');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('participant-phone-public:' || client_hash, 0));
  delete from participant_identity.participant_auth_public_rate_events
  where occurred_at < now() - interval '30 days';
  select greatest(0, ceil(extract(epoch from ((max(occurred_at) + interval '60 seconds') - now())))::integer)
    into cooldown_seconds
  from participant_identity.participant_auth_public_rate_events
  where outcome = 'REQUEST_ACCEPTED'
    and (client_fingerprint = client_hash or identifier_fingerprint = identifier_hash)
    and occurred_at > now() - interval '60 seconds';
  select count(*) into recent_client
  from participant_identity.participant_auth_public_rate_events
  where client_fingerprint = client_hash and outcome = 'REQUEST_ACCEPTED'
    and occurred_at > now() - interval '1 hour';
  select count(*) into recent_identifier
  from participant_identity.participant_auth_public_rate_events
  where identifier_fingerprint = identifier_hash and outcome = 'REQUEST_ACCEPTED'
    and occurred_at > now() - interval '1 hour';
  allowed_value := cooldown_seconds = 0 and recent_client < 6 and recent_identifier < 3;
  insert into participant_identity.participant_auth_public_rate_events (
    auth_method, client_fingerprint, identifier_fingerprint, outcome
  ) values (
    'PHONE', client_hash, identifier_hash,
    case when allowed_value then 'REQUEST_ACCEPTED' else 'RATE_LIMITED' end
  );
  return jsonb_build_object(
    'ok', true, 'allowed', allowed_value,
    'code', case when allowed_value then 'PHONE_LOGIN_PUBLIC_REQUEST_ALLOWED'
      when cooldown_seconds > 0 then 'PHONE_OTP_COOLDOWN' else 'PHONE_OTP_RATE_LIMITED' end,
    'retryAfterSeconds', cooldown_seconds,
    'limits', jsonb_build_object('cooldownSeconds', 60, 'identifierPerHour', 3, 'clientPerHour', 6)
  );
end;
$_$;


ALTER FUNCTION public.begin_participant_phone_public_request(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_google_writer_fence_rehearsal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_google_writer_fence_rehearsal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  rehearsal production_control.google_writer_fence_rehearsals%rowtype;
  run_identifier uuid := extensions.gen_random_uuid();
  request_identifier uuid;
  request_hash text := production_control.cutover_payload_hash(input);
  canonical_sheet_fingerprint text :=
    production_control.structured_evidence_fingerprint(
      production_control.expected_google_writer_fence_sheet_ids()
    );
  candidate_commit text := pg_catalog.lower(
    coalesce(input->>'candidate_deployment_commit', '')
  );
  candidate_deployment text := coalesce(input->>'candidate_deployment_id', '');
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if coalesce(input->>'rehearsal_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or candidate_deployment !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or candidate_commit !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'quiesce_evidence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or input->>'vercel_project_id'
       is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'dedicated_google_service_account' is distinct from
       'sbi-production-workbook@sandbagger-invitational.iam.gserviceaccount.com'
     or pg_catalog.jsonb_typeof(input->'expected_activation_revision')
       is distinct from 'number'
     or input->>'expected_activation_revision' !~ '^[0-9]+$'
     or coalesce(input->>'expected_authority_generation', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'expected_admission_generation', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.jsonb_typeof(input->'expected_admission_revision')
       is distinct from 'number'
     or input->>'expected_admission_revision' !~ '^[0-9]+$'
     or coalesce(input->>'baseline_provider_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'baseline_protected_ranges_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'baseline_canonical_value_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_FENCE_REHEARSAL_BEGIN_INPUT_INVALID';
  end if;
  request_identifier := (input->>'rehearsal_request_id')::uuid;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );

  select * into rehearsal
  from production_control.google_writer_fence_rehearsals value
  where value.rehearsal_request_id = request_identifier;
  if found then
    if rehearsal.begin_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or rehearsal.begin_payload_hash is distinct from request_hash
       or rehearsal.candidate_deployment_id is distinct from candidate_deployment
       or rehearsal.candidate_deployment_commit is distinct from candidate_commit then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_FENCE_REHEARSAL_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.google_writer_fence_rehearsal_response(
      rehearsal, true
    );
  end if;

  select * into rehearsal
  from production_control.google_writer_fence_rehearsals value
  where value.candidate_deployment_id = candidate_deployment
    and value.candidate_deployment_commit = candidate_commit;
  if found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_FENCE_REHEARSAL_CANDIDATE_ALREADY_USED';
  end if;
  perform production_control.assert_no_unrestored_google_writer_fence_rehearsal();

  select * into strict quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = (input->>'quiesce_evidence_id')::uuid;
  if quiesce.purpose is distinct from 'REHEARSAL'
     or quiesce.status is distinct from 'VERIFIED'
     or quiesce.expires_at <= pg_catalog.now() + interval '5 minutes'
     or quiesce.owner_freeze_expires_at <=
       pg_catalog.now() + interval '5 minutes'
     or quiesce.candidate_deployment_id is distinct from candidate_deployment
     or quiesce.candidate_deployment_commit is distinct from candidate_commit
     or quiesce.vercel_project_id is distinct from input->>'vercel_project_id'
     or quiesce.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_FENCE_REHEARSAL_QUIESCE_REQUIRED';
  end if;

  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  perform 1
  from production_control.worker_controls value
  order by value.worker_name
  for update;

  if activation.state is distinct from 'DORMANT'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or resource.project_ref is distinct from input->>'project_ref'
     or resource.google_workbook_id is distinct from input->>'source_workbook_id'
     or resource.current_tournament_id is distinct from input->>'tournament_id'
     or resource.current_tournament_read_authority is distinct from 'GOOGLE'
     or resource.scoring_authority is distinct from 'GOOGLE'
     or resource.participant_identity_authority is distinct from 'PASSPORT'
     or resource.public_supabase_reads_enabled
     or resource.scoring_ingress_enabled
     or resource.google_writes_enabled
     or resource.workers_enabled
     or resource.auth_user_creation_enabled
     or gate.state is distinct from 'PAUSED'
     or gate.authority is distinct from 'GOOGLE'
     or gate.admission_state is distinct from 'OPEN'
     or gate.admission_protocol_enforced
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.active_closure_id is not null
     or gate.external_fence_evidence_id is not null
     or exists (
       select 1 from production_control.worker_controls value
       where value.enabled or value.scheduler_installed
         or value.google_writes_allowed
     )
     or exists (
       select 1 from scoring_authority.scoring_ingress_leases value
       where value.tournament_id = '2026'
         and (
           value.status = 'ACTIVE'
           or value.resolution_state in (
             'LEGACY_UNCLASSIFIED', 'ADMITTED', 'WRITE_STARTED',
             'AMBIGUOUS', 'PARTIAL_WRITE'
           )
         )
     )
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_FENCE_REHEARSAL_START_STATE_INVALID';
  end if;

  insert into production_control.google_writer_fence_rehearsals (
    run_id, rehearsal_request_id, begin_request_fingerprint,
    begin_payload_hash, quiesce_evidence_id, candidate_deployment_id,
    candidate_deployment_commit, vercel_project_id, project_ref,
    source_workbook_id, tournament_id, dedicated_google_service_account,
    activation_revision, authority_generation_id, admission_generation_id,
    admission_revision, baseline_provider_fingerprint,
    baseline_protected_ranges_fingerprint,
    baseline_canonical_value_fingerprint, writer_scope_fingerprint,
    edge_quiesce_fingerprint, origin_matrix_fingerprint,
    owner_principal_fingerprint, canonical_sheet_union_fingerprint,
    owner_override_operationally_frozen, owner_acknowledged_at,
    owner_freeze_expires_at,
    protection_description_prefix, actor_id
  ) values (
    run_identifier, request_identifier,
    pg_catalog.lower(input->>'request_fingerprint'), request_hash,
    quiesce.evidence_id,
    candidate_deployment, candidate_commit, input->>'vercel_project_id',
    input->>'project_ref', input->>'source_workbook_id', input->>'tournament_id',
    input->>'dedicated_google_service_account', activation.activation_revision,
    activation.authority_generation_id, gate.admission_generation_id,
    gate.admission_revision,
    pg_catalog.lower(input->>'baseline_provider_fingerprint'),
    pg_catalog.lower(input->>'baseline_protected_ranges_fingerprint'),
    pg_catalog.lower(input->>'baseline_canonical_value_fingerprint'),
    canonical_sheet_fingerprint,
    quiesce.deployment_scope_fingerprint,
    quiesce.origin_inventory_fingerprint,
    quiesce.owner_principal_fingerprint,
    canonical_sheet_fingerprint,
    quiesce.owner_override_operationally_frozen,
    quiesce.owner_acknowledged_at, quiesce.owner_freeze_expires_at,
    'STEP11_6_WRITER_FENCE_REHEARSAL:' || run_identifier::text,
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into rehearsal;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_GOOGLE_WRITER_FENCE_REHEARSAL_STARTED',
    'SCORING_AUTHORITY', '2026', rehearsal.actor_id,
    rehearsal.begin_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'run_id', rehearsal.run_id,
      'candidate_deployment_id', rehearsal.candidate_deployment_id,
      'candidate_deployment_commit', rehearsal.candidate_deployment_commit,
      'activation_revision', rehearsal.activation_revision,
      'authority_generation_id', rehearsal.authority_generation_id,
      'admission_generation_id', rehearsal.admission_generation_id,
      'admission_revision', rehearsal.admission_revision,
      'protection_description_prefix',
        rehearsal.protection_description_prefix,
      'authority_changed', false,
      'google_value_written', false
    )
  );

  return production_control.google_writer_fence_rehearsal_response(
    rehearsal, false
  );
end;
$_$;


ALTER FUNCTION public.begin_production_google_writer_fence_rehearsal(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_google_writer_provider_fence_abort_dispatch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_google_writer_provider_fence_abort_dispatch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  dispatch
    production_control.google_writer_provider_fence_abort_dispatches%rowtype;
  latest
    production_control.google_writer_provider_fence_abort_dispatches%rowtype;
  restore_quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  payload_hash_value text := production_control.cutover_payload_hash(input);
  remaining_dispatch_budget_ms bigint;
  next_attempt integer := 1;
  dispatch_issued_at timestamptz := pg_catalog.clock_timestamp();
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'operation' is distinct from
       'BEGIN_PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_DISPATCH'
     or coalesce(input->>'fence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'install_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'abort_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'dispatch_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or input->>'mutation_plan' is distinct from
       'DRIVE_ACL_LEGACY_READER_TO_WRITER_V1'
     or input->>'provider_mutation_class' is distinct from
       'DRIVE_LEGACY_PERMISSION_READER_TO_WRITER_V1'
     or input->>'source_role' is distinct from 'reader'
     or input->>'target_role' is distinct from 'writer'
     or pg_catalog.jsonb_typeof(input->'transition_intent') is distinct from
       'object'
     or (select pg_catalog.count(*)
         from pg_catalog.jsonb_object_keys(input->'transition_intent')) <> 32
     or input->'transition_intent'->>'schemaVersion' is distinct from
       'step12-production-google-drive-acl-transition-intent-v1'
     or input->'transition_intent'->>'workbookId' is distinct from
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or input->'transition_intent'->>'fenceId' is distinct from
       pg_catalog.lower(input->>'fence_id')
     or input->'transition_intent'->>'installRequestId' is distinct from
       pg_catalog.lower(input->>'install_request_id')
     or input->'transition_intent'->>'providerMutationClass' is distinct from
       input->>'provider_mutation_class'
     or input->'transition_intent'->>'sourceRole' is distinct from 'reader'
     or input->'transition_intent'->>'targetRole' is distinct from 'writer'
     or input->'transition_intent'->>'permissionManagementScope' is distinct from
       'https://www.googleapis.com/auth/drive.file'
     or input->'transition_intent'->'priorLegacyCanEdit' is distinct from
       'false'::jsonb
     or input->'transition_intent'->'priorLegacyCanShare' is distinct from
       'false'::jsonb
     or input->'transition_intent'->'expectedTargetLegacyCanEdit' is distinct from
       'true'::jsonb
     or input->'transition_intent'->'expectedTargetLegacyCanShare' is distinct from
       'true'::jsonb
     or input->'transition_intent'->>'transitionIntentFingerprint' is distinct from
       pg_catalog.lower(input->>'transition_intent_fingerprint')
     or production_control.google_drive_acl_transition_intent_fingerprint_v1(
       (input->'transition_intent') - 'transitionIntentFingerprint'
     ) is distinct from pg_catalog.lower(input->>'transition_intent_fingerprint')
     or coalesce(input->>'transition_intent_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'provider_preflight_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or input->>'provider_preflight_position' is distinct from 'SOURCE'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_DISPATCH_INPUT_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into dispatch
  from production_control.google_writer_provider_fence_abort_dispatches value
  where value.dispatch_request_id = (input->>'dispatch_request_id')::uuid
  for update;
  if found then
    if dispatch.fence_id is distinct from (input->>'fence_id')::uuid
       or dispatch.abort_request_id is distinct from
         (input->>'abort_request_id')::uuid
       or dispatch.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or dispatch.payload_hash is distinct from payload_hash_value
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_DISPATCH_IDEMPOTENCY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_DISPATCH_ISSUED',
      'fence_id', dispatch.fence_id,
      'install_request_id', pg_catalog.lower(input->>'install_request_id'),
      'dispatch_id', dispatch.dispatch_id,
      'dispatch_request_id', dispatch.dispatch_request_id,
      'abort_request_id', dispatch.abort_request_id,
      'attempt', dispatch.attempt,
      'mutation_plan', dispatch.mutation_plan,
      'provider_mutation_class', dispatch.provider_mutation_class,
      'source_role', dispatch.source_role,
      'target_role', dispatch.target_role,
      'transition_intent_fingerprint', dispatch.transition_intent_fingerprint,
      'provider_preflight_fingerprint', dispatch.provider_preflight_fingerprint,
      'provider_preflight_position', dispatch.provider_preflight_position,
      'status', dispatch.outcome_status,
      'issued_at', dispatch.issued_at,
      'expires_at', dispatch.expires_at,
      'remaining_dispatch_budget_ms', greatest(0,
        pg_catalog.floor(extract(epoch from (
          dispatch.expires_at - pg_catalog.clock_timestamp()
        )) * 1000)::bigint),
      'dispatch_usable', false,
      'replay_usable', false,
      'idempotent', true
    );
  end if;
  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = (input->>'fence_id')::uuid
    and value.install_request_id = (input->>'install_request_id')::uuid
  for update;
  select * into latest
  from production_control.google_writer_provider_fence_abort_dispatches value
  where value.fence_id = fence.fence_id
  order by value.attempt desc
  limit 1
  for update;
  if found then
    -- A delayed reader-to-writer PATCH could otherwise commit after a later
    -- forward fence and silently reopen the legacy writer.  There is no Drive
    -- terminality bound, so UNKNOWN/SOURCE never authorizes redispatch or
    -- reservation release.  Exact target recovery settles this same dispatch.
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_RECOVERY_REDISPATCH_FORBIDDEN';
  end if;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into strict restore_quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = fence.restore_quiesce_evidence_id
  for update;
  if fence.status is distinct from 'ABORTING'
     or fence.abort_request_id is distinct from
       (input->>'abort_request_id')::uuid
     or fence.acl_reader_confirmed_at is null
     or pg_catalog.clock_timestamp() < fence.abort_provider_quiescence_not_before
     or fence.restore_global_writer_stop_active_at is null
     or pg_catalog.clock_timestamp() <
       fence.restore_global_writer_stop_active_at + interval '1810 seconds'
     or restore_quiesce.status is distinct from 'VERIFIED'
     or restore_quiesce.purpose is distinct from fence.lifecycle_mode
     or restore_quiesce.candidate_deployment_id is distinct from
       fence.candidate_deployment_id
     or restore_quiesce.candidate_deployment_commit is distinct from
       fence.candidate_deployment_commit
     or restore_quiesce.expires_at <= pg_catalog.clock_timestamp()
     or restore_quiesce.owner_freeze_expires_at <= pg_catalog.clock_timestamp()
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = restore_quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or fence.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or fence.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or fence.actor_id is distinct from input->>'actor_id'
     or fence.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or (fence.lifecycle_mode = 'CUTOVER' and (
       gate.admission_deployment_id is distinct from input->>'deployment_id'
       or activation.expected_deployment_commit is distinct from
         pg_catalog.lower(input->>'deployment_commit')
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       input->>'deployment_id' is distinct from fence.candidate_deployment_id
       or pg_catalog.lower(input->>'deployment_commit') is distinct from
         fence.candidate_deployment_commit
     ))
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or ((activation.first_supabase_write_possible_at is not null
          or activation.first_supabase_write_observed_at is not null) and not (
       fence.lifecycle_mode = 'CUTOVER'
       and fence.abort_origin_status in ('INSTALLED', 'REMOVAL_AUTHORIZED')
       and activation.state = 'ROLLED_BACK'
       and gate.admission_state = 'CLOSED'
       and gate.active_closure_id is not null
     ))
     or activation.active_transition_epoch_id is not null
     or resource.scoring_authority is distinct from 'GOOGLE'
     or gate.authority is distinct from 'GOOGLE'
     or (fence.lifecycle_mode = 'CUTOVER' and
       fence.abort_origin_status = 'INSTALLING' and (
         activation.state is distinct from 'GOOGLE_LEASE_ARMED'
         or resource.participant_identity_authority is distinct from 'SUPABASE'
         or resource.current_tournament_read_authority is distinct from 'SUPABASE'
         or gate.state is distinct from 'OPEN'
         or gate.admission_state is distinct from 'OPEN'
         or not gate.admission_protocol_enforced
         or gate.active_closure_id is not null
         or activation.active_google_writer_provider_fence_id is not null
         or gate.google_writer_provider_fence_id is not null
       ))
     or (fence.lifecycle_mode = 'CUTOVER' and
       fence.abort_origin_status in ('INSTALLED', 'REMOVAL_AUTHORIZED') and (
         not (
           (activation.state = 'GOOGLE_LEASE_ARMED'
             and resource.participant_identity_authority = 'SUPABASE'
             and resource.current_tournament_read_authority = 'SUPABASE'
             and gate.state = 'OPEN' and gate.admission_state = 'OPEN'
             and gate.admission_protocol_enforced
             and gate.active_closure_id is null)
           or
           (activation.state in ('DORMANT', 'ROLLED_BACK')
             and resource.participant_identity_authority = 'PASSPORT'
             and resource.current_tournament_read_authority = 'GOOGLE'
             and gate.state = 'PAUSED' and gate.admission_state = 'CLOSED'
             and gate.admission_protocol_enforced
             and gate.active_closure_id is not null)
         )
         or activation.active_google_writer_provider_fence_id is distinct from
           fence.fence_id
         or gate.google_writer_provider_fence_id is distinct from fence.fence_id
       ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       fence.abort_origin_status not in ('INSTALLING', 'INSTALLED')
       or activation.state is distinct from 'DORMANT'
       or resource.participant_identity_authority is distinct from 'PASSPORT'
       or resource.current_tournament_read_authority is distinct from 'GOOGLE'
       or gate.state is distinct from 'PAUSED'
       or (fence.abort_origin_status = 'INSTALLING' and (
         gate.admission_state is distinct from 'OPEN'
         or gate.admission_protocol_enforced
         or gate.active_closure_id is not null
         or activation.active_google_writer_provider_fence_id is not null
         or gate.google_writer_provider_fence_id is not null
       ))
       or (fence.abort_origin_status = 'INSTALLED' and (
         gate.admission_state is distinct from 'CLOSED'
         or not gate.admission_protocol_enforced
         or gate.active_closure_id is null
         or activation.active_google_writer_provider_fence_id is distinct from
           fence.fence_id
         or gate.google_writer_provider_fence_id is distinct from fence.fence_id
       ))
     ))
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_DISPATCH_NOT_SAFE';
  end if;
  insert into production_control.google_writer_provider_fence_abort_dispatches (
    dispatch_id, fence_id, abort_request_id, dispatch_request_id,
    restore_quiesce_evidence_id, attempt,
    mutation_plan, provider_mutation_class, source_role, target_role,
    transition_intent, transition_intent_fingerprint,
    provider_preflight_fingerprint, provider_preflight_position,
    request_fingerprint, payload_hash,
    activation_revision, authority_generation_id, admission_generation_id,
    admission_revision, actor_id, authenticated_actor_fingerprint,
    issued_at, expires_at
  ) values (
    extensions.gen_random_uuid(), fence.fence_id, fence.abort_request_id,
    (input->>'dispatch_request_id')::uuid, restore_quiesce.evidence_id,
    next_attempt, input->>'mutation_plan',
    input->>'provider_mutation_class', input->>'source_role',
    input->>'target_role', input->'transition_intent',
    pg_catalog.lower(input->>'transition_intent_fingerprint'),
    pg_catalog.lower(input->>'provider_preflight_fingerprint'),
    'SOURCE',
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
    activation.activation_revision, activation.authority_generation_id,
    gate.admission_generation_id, gate.admission_revision,
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'authenticated_actor_fingerprint'),
    dispatch_issued_at, dispatch_issued_at + interval '15 seconds'
  ) returning * into dispatch;
  remaining_dispatch_budget_ms := greatest(0,
    pg_catalog.floor(extract(epoch from (
      dispatch.expires_at - pg_catalog.clock_timestamp()
    )) * 1000)::bigint);
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result,
    details
  ) values (
    'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_DISPATCH_ISSUED',
    'SCORING_AUTHORITY', '2026', dispatch.actor_id,
    dispatch.request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'fence_id', dispatch.fence_id,
      'dispatch_id', dispatch.dispatch_id,
      'dispatch_request_id', dispatch.dispatch_request_id,
      'abort_request_id', dispatch.abort_request_id,
      'attempt', dispatch.attempt,
      'mutation_plan', dispatch.mutation_plan,
      'provider_mutation_class', dispatch.provider_mutation_class,
      'transition_intent_fingerprint',
        dispatch.transition_intent_fingerprint,
      'restore_quiesce_evidence_id', dispatch.restore_quiesce_evidence_id,
      'issued_at', dispatch.issued_at,
      'expires_at', dispatch.expires_at,
      'admission_reservation_active', true
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ABORT_DISPATCH_ISSUED',
    'fence_id', dispatch.fence_id,
    'install_request_id', fence.install_request_id,
    'dispatch_id', dispatch.dispatch_id,
    'dispatch_request_id', dispatch.dispatch_request_id,
    'abort_request_id', dispatch.abort_request_id,
    'attempt', dispatch.attempt,
    'mutation_plan', dispatch.mutation_plan,
    'provider_mutation_class', dispatch.provider_mutation_class,
    'source_role', dispatch.source_role,
    'target_role', dispatch.target_role,
    'transition_intent_fingerprint', dispatch.transition_intent_fingerprint,
    'provider_preflight_fingerprint', dispatch.provider_preflight_fingerprint,
    'provider_preflight_position', dispatch.provider_preflight_position,
    'status', dispatch.outcome_status,
    'issued_at', dispatch.issued_at,
    'expires_at', dispatch.expires_at,
    'remaining_dispatch_budget_ms', remaining_dispatch_budget_ms,
    'dispatch_usable', remaining_dispatch_budget_ms > 0,
    'replay_usable', remaining_dispatch_budget_ms > 0,
    'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.begin_production_google_writer_provider_fence_abort_dispatch(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_google_writer_provider_fence_install(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_google_writer_provider_fence_install(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  waf_epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  waf_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  request_identifier uuid;
  fence_identifier uuid := extensions.gen_random_uuid();
  payload_hash_value text := production_control.cutover_payload_hash(input);
  lifecycle text := pg_catalog.upper(coalesce(input->>'lifecycle_mode', ''));
  empty_sheet_union_fingerprint text :=
    production_control.structured_evidence_fingerprint('[]'::jsonb);
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'operation' is distinct from
       'BEGIN_PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL'
     or lifecycle not in ('CUTOVER', 'REHEARSAL')
     or coalesce(input->>'install_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'quiesce_evidence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'critical_waf_epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '') !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'dedicated_principal_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'legacy_credential_generation_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'baseline_provider_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'baseline_acl_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'baseline_canonical_value_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'baseline_formula_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'baseline_combined_value_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'writer_scope_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or pg_catalog.lower(coalesce(input->>'canonical_sheet_union_fingerprint', ''))
       is distinct from empty_sheet_union_fingerprint
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_BEGIN_INPUT_INVALID';
  end if;
  request_identifier := (input->>'install_request_id')::uuid;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into fence
  from production_control.google_writer_provider_fences value
  where value.install_request_id = request_identifier
  for update;
  if found then
    if fence.begin_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or fence.begin_payload_hash is distinct from payload_hash_value
       or fence.lifecycle_mode is distinct from lifecycle
       or fence.candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or fence.candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or fence.critical_waf_epoch_id is distinct from
         (input->>'critical_waf_epoch_id')::uuid
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_BEGIN_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.google_writer_provider_fence_response(fence, true);
  end if;
  select * into strict quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = (input->>'quiesce_evidence_id')::uuid
  for update;
  select * into strict waf_epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = (input->>'critical_waf_epoch_id')::uuid
  for update;
  select * into strict waf_observation
  from production_control.vercel_writer_critical_waf_observations value
  where value.observation_id = quiesce.critical_waf_observation_id
    and value.epoch_id = waf_epoch.epoch_id;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  if quiesce.status is distinct from 'VERIFIED'
     or quiesce.critical_waf_epoch_id is distinct from waf_epoch.epoch_id
     or quiesce.critical_waf_quiesce_stage is distinct from 'INSTALL'
     or waf_epoch.status is distinct from 'ACTIVE_UNBOUND'
     or waf_epoch.bound_fence_id is not null
     or waf_epoch.bound_quiesce_evidence_id is not null
     or waf_epoch.critical_active_observation_id is distinct from
       waf_observation.observation_id
     or waf_observation.evidence_stage is distinct from 'CRITICAL_ACTIVE'
     or waf_observation.expires_at <= pg_catalog.clock_timestamp()
     or quiesce.purpose is distinct from lifecycle
     or quiesce.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or quiesce.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or quiesce.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
     or quiesce.expires_at <= pg_catalog.clock_timestamp() + interval '205 seconds'
     or quiesce.owner_freeze_expires_at <=
       pg_catalog.clock_timestamp() + interval '205 seconds'
     or not exists (
       select 1 from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or (lifecycle = 'CUTOVER' and (
       gate.admission_deployment_id is distinct from input->>'deployment_id'
       or activation.expected_deployment_commit is distinct from
         pg_catalog.lower(input->>'deployment_commit')
     ))
     or (lifecycle = 'REHEARSAL' and (
       input->>'deployment_id' is distinct from input->>'candidate_deployment_id'
       or pg_catalog.lower(input->>'deployment_commit') is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
     ))
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.active_transition_epoch_id is not null
     or activation.active_google_writer_provider_fence_id is not null
     or resource.scoring_authority is distinct from 'GOOGLE'
     or resource.scoring_ingress_enabled or resource.workers_enabled
     or gate.authority is distinct from 'GOOGLE'
     or gate.admission_state is distinct from 'OPEN'
     or gate.active_closure_id is not null
     or gate.external_fence_evidence_id is not null
     or gate.google_writer_provider_fence_id is not null
     or gate.google_writer_provider_verification_id is not null
     or (lifecycle = 'CUTOVER' and (
       activation.state is distinct from 'GOOGLE_LEASE_ARMED'
       or resource.participant_identity_authority is distinct from 'SUPABASE'
       or resource.current_tournament_read_authority is distinct from 'SUPABASE'
       or gate.state is distinct from 'OPEN'
       or not gate.admission_protocol_enforced
     ))
     or (lifecycle = 'REHEARSAL' and (
       activation.state is distinct from 'DORMANT'
       or resource.participant_identity_authority is distinct from 'PASSPORT'
       or resource.current_tournament_read_authority is distinct from 'GOOGLE'
       or gate.state is distinct from 'PAUSED'
       or gate.admission_protocol_enforced
       or resource.public_supabase_reads_enabled
       or resource.auth_user_creation_enabled
     ))
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_BEGIN_STATE_INVALID';
  end if;
  insert into production_control.google_writer_provider_fences (
    fence_id, install_request_id, begin_request_fingerprint,
    begin_payload_hash, quiesce_evidence_id, candidate_deployment_id,
    candidate_deployment_commit, source_workbook_id,
    dedicated_principal_fingerprint,
    legacy_credential_generation_fingerprint,
    baseline_provider_fingerprint, baseline_acl_fingerprint,
    baseline_canonical_value_fingerprint, baseline_formula_fingerprint,
    baseline_combined_value_fingerprint, writer_scope_fingerprint,
    canonical_sheet_union_fingerprint, protection_description_prefix,
    actor_id, authenticated_actor_fingerprint, lifecycle_mode,
    critical_waf_epoch_id, global_writer_stop_active_at
  ) values (
    fence_identifier, request_identifier,
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
    quiesce.evidence_id, input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    input->>'source_workbook_id',
    pg_catalog.lower(input->>'dedicated_principal_fingerprint'),
    pg_catalog.lower(input->>'legacy_credential_generation_fingerprint'),
    pg_catalog.lower(input->>'baseline_provider_fingerprint'),
    pg_catalog.lower(input->>'baseline_acl_fingerprint'),
    pg_catalog.lower(input->>'baseline_canonical_value_fingerprint'),
    pg_catalog.lower(input->>'baseline_formula_fingerprint'),
    pg_catalog.lower(input->>'baseline_combined_value_fingerprint'),
    pg_catalog.lower(input->>'writer_scope_fingerprint'),
    empty_sheet_union_fingerprint,
    -- This legacy column remains an inert compatibility key for historical
    -- provider-fence rows.  The executable fence kind is carried by the
    -- DRIVE_ACL_V2 verification/dispatch contract below; retaining the exact
    -- predecessor prefix avoids weakening or replacing its table constraint.
    'STEP12_GOOGLE_WRITER_PROVIDER_FENCE:' || fence_identifier::text,
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'authenticated_actor_fingerprint'), lifecycle,
    waf_epoch.epoch_id, waf_epoch.critical_active_at
  ) returning * into fence;
  update production_control.vercel_writer_critical_waf_epochs
  set status = 'FENCE_BOUND',
      bound_fence_id = fence.fence_id,
      bound_quiesce_evidence_id = quiesce.evidence_id,
      fence_bind_request_id = fence.install_request_id,
      fence_bind_request_fingerprint = fence.begin_request_fingerprint,
      fence_bind_payload_hash = fence.begin_payload_hash,
      fence_bound_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp()
  where epoch_id = waf_epoch.epoch_id
    and status = 'ACTIVE_UNBOUND'
    and bound_fence_id is null
    and bound_quiesce_evidence_id is null
  returning * into waf_epoch;
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_WAF_EPOCH_BIND_RACE';
  end if;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result,
    details
  ) values (
    'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_' || lifecycle || '_STARTED',
    'SCORING_AUTHORITY', '2026', fence.actor_id,
    fence.begin_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'fence_id', fence.fence_id,
      'install_request_id', fence.install_request_id,
      'lifecycle_mode', fence.lifecycle_mode,
      'quiesce_evidence_id', fence.quiesce_evidence_id,
      'critical_waf_epoch_id', fence.critical_waf_epoch_id,
      'critical_waf_active_observation_id',
        waf_epoch.critical_active_observation_id,
      'global_writer_stop_active_at', fence.global_writer_stop_active_at,
      'admission_reservation_active', true,
      'protection_mutation_count', 0
    )
  );
  return production_control.google_writer_provider_fence_response(fence, false);
end;
$_$;


ALTER FUNCTION public.begin_production_google_writer_provider_fence_install(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_google_writer_provider_fence_install_dispatch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_google_writer_provider_fence_install_dispatch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  prior
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  latest
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  inserted
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  waf_epoch
    production_control.vercel_writer_critical_waf_epochs%rowtype;
  request_identifier uuid;
  payload_hash_value text := production_control.cutover_payload_hash(input);
  remaining_dispatch_budget_ms bigint;
  next_attempt integer := 1;
  dispatch_issued_at timestamptz := pg_catalog.clock_timestamp();
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'operation' is distinct from
       'BEGIN_PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_DISPATCH'
     or coalesce(input->>'fence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'install_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'dispatch_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'quiesce_evidence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or input->>'mutation_plan' is distinct from
       'DRIVE_ACL_LEGACY_WRITER_TO_READER_V1'
     or input->>'provider_mutation_class' is distinct from
       'DRIVE_LEGACY_PERMISSION_WRITER_TO_READER_V1'
     or input->>'source_role' is distinct from 'writer'
     or input->>'target_role' is distinct from 'reader'
     or pg_catalog.jsonb_typeof(input->'transition_intent') is distinct from
       'object'
     or (select pg_catalog.count(*)
         from pg_catalog.jsonb_object_keys(input->'transition_intent')) <> 32
     or input->'transition_intent'->>'schemaVersion' is distinct from
       'step12-production-google-drive-acl-transition-intent-v1'
     or input->'transition_intent'->>'workbookId' is distinct from
       '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4'
     or input->'transition_intent'->>'fenceId' is distinct from
       pg_catalog.lower(input->>'fence_id')
     or input->'transition_intent'->>'installRequestId' is distinct from
       pg_catalog.lower(input->>'install_request_id')
     or input->'transition_intent'->>'providerMutationClass' is distinct from
       input->>'provider_mutation_class'
     or input->'transition_intent'->>'sourceRole' is distinct from 'writer'
     or input->'transition_intent'->>'targetRole' is distinct from 'reader'
     or input->'transition_intent'->>'permissionManagementScope' is distinct from
       'https://www.googleapis.com/auth/drive.file'
     or input->'transition_intent'->'priorLegacyCanEdit' is distinct from
       'true'::jsonb
     or input->'transition_intent'->'priorLegacyCanShare' is distinct from
       'true'::jsonb
     or input->'transition_intent'->'expectedTargetLegacyCanEdit' is distinct from
       'false'::jsonb
     or input->'transition_intent'->'expectedTargetLegacyCanShare' is distinct from
       'false'::jsonb
     or input->'transition_intent'->>'transitionIntentFingerprint' is distinct from
       pg_catalog.lower(input->>'transition_intent_fingerprint')
     or production_control.google_drive_acl_transition_intent_fingerprint_v1(
       (input->'transition_intent') - 'transitionIntentFingerprint'
     ) is distinct from pg_catalog.lower(input->>'transition_intent_fingerprint')
     or coalesce(input->>'transition_intent_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'provider_preflight_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or input->>'provider_preflight_position' is distinct from 'SOURCE'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_DISPATCH_INPUT_INVALID';
  end if;
  request_identifier := (input->>'dispatch_request_id')::uuid;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into prior
  from production_control.google_writer_provider_fence_install_dispatches value
  where value.dispatch_request_id = request_identifier;
  if found then
    if prior.fence_id is distinct from (input->>'fence_id')::uuid
       or prior.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or prior.payload_hash is distinct from payload_hash_value
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_DISPATCH_IDEMPOTENCY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_DISPATCH_ISSUED',
      'fence_id', prior.fence_id,
      'install_request_id', pg_catalog.lower(input->>'install_request_id'),
      'dispatch_id', prior.dispatch_id,
      'dispatch_request_id', prior.dispatch_request_id,
      'attempt', prior.attempt,
      'mutation_plan', prior.mutation_plan,
      'provider_mutation_class', prior.provider_mutation_class,
      'source_role', prior.source_role,
      'target_role', prior.target_role,
      'transition_intent_fingerprint', prior.transition_intent_fingerprint,
      'provider_preflight_fingerprint', prior.provider_preflight_fingerprint,
      'provider_preflight_position', prior.provider_preflight_position,
      'status', prior.outcome_status,
      'issued_at', prior.issued_at,
      'expires_at', prior.expires_at,
      'remaining_dispatch_budget_ms', greatest(0,
        pg_catalog.floor(extract(epoch from (
          prior.expires_at - pg_catalog.clock_timestamp()
        )) * 1000)::bigint),
      'dispatch_usable', false,
      'replay_usable', false,
      'idempotent', true
    );
  end if;

  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = (input->>'fence_id')::uuid
    and value.install_request_id = (input->>'install_request_id')::uuid
  for update;
  select * into latest
  from production_control.google_writer_provider_fence_install_dispatches value
  where value.fence_id = fence.fence_id
  order by value.attempt desc
  limit 1
  for update;
  if found then
    -- Drive permissions.update has no provider-certified late-commit ceiling.
    -- Even a same-direction retry after a SOURCE readback could overlap a
    -- delayed first PATCH and defeat the exact non-impact chronology.  A
    -- TARGET readback settles the existing dispatch through the result RPC;
    -- every non-target/unknown outcome remains reservation-holding and needs
    -- owner/provider intervention rather than a second PATCH.
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_RECOVERY_REDISPATCH_FORBIDDEN';
  end if;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into strict quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = fence.quiesce_evidence_id
  for update;
  select * into strict waf_epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = fence.critical_waf_epoch_id
  for update;
  if fence.status is distinct from 'INSTALLING'
     or fence.quiesce_evidence_id is distinct from
       (input->>'quiesce_evidence_id')::uuid
     or fence.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or fence.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or fence.actor_id is distinct from input->>'actor_id'
     or fence.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
     or quiesce.status is distinct from 'VERIFIED'
     or quiesce.purpose is distinct from fence.lifecycle_mode
     or waf_epoch.status is distinct from 'FENCE_BOUND'
     or waf_epoch.bound_fence_id is distinct from fence.fence_id
     or waf_epoch.bound_quiesce_evidence_id is distinct from
       quiesce.evidence_id
     or waf_epoch.critical_active_at is null
     or quiesce.expires_at <= pg_catalog.clock_timestamp()
     or quiesce.owner_freeze_expires_at <= pg_catalog.clock_timestamp()
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or exists (
       select 1
       from production_control.google_writer_provider_fence_settlement_observations value
       where value.fence_id = fence.fence_id
     )
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or (fence.lifecycle_mode = 'CUTOVER' and (
       gate.admission_deployment_id is distinct from input->>'deployment_id'
       or activation.expected_deployment_commit is distinct from
         pg_catalog.lower(input->>'deployment_commit')
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       input->>'deployment_id' is distinct from fence.candidate_deployment_id
       or pg_catalog.lower(input->>'deployment_commit') is distinct from
         fence.candidate_deployment_commit
     ))
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.active_transition_epoch_id is not null
     or activation.active_google_writer_provider_fence_id is not null
     or activation.active_google_writer_provider_verification_id is not null
     or resource.scoring_authority is distinct from 'GOOGLE'
     or gate.authority is distinct from 'GOOGLE'
     or gate.admission_state is distinct from 'OPEN'
     or (fence.lifecycle_mode = 'CUTOVER' and (
       activation.state is distinct from 'GOOGLE_LEASE_ARMED'
       or resource.participant_identity_authority is distinct from 'SUPABASE'
       or resource.current_tournament_read_authority is distinct from 'SUPABASE'
       or gate.state is distinct from 'OPEN'
       or not gate.admission_protocol_enforced
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       activation.state is distinct from 'DORMANT'
       or resource.participant_identity_authority is distinct from 'PASSPORT'
       or resource.current_tournament_read_authority is distinct from 'GOOGLE'
       or gate.state is distinct from 'PAUSED'
       or gate.admission_protocol_enforced
     ))
     or gate.active_closure_id is not null
     or gate.external_fence_evidence_id is not null
     or gate.google_writer_provider_fence_id is not null
     or gate.google_writer_provider_verification_id is not null
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_DISPATCH_NOT_SAFE';
  end if;

  if fence.global_writer_stop_active_at is null then
    update production_control.google_writer_provider_fences
    set global_writer_stop_active_at = waf_epoch.critical_active_at,
        updated_at = pg_catalog.clock_timestamp()
    where fence_id = fence.fence_id
    returning * into fence;
  elsif fence.global_writer_stop_active_at is distinct from
      waf_epoch.critical_active_at then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_GLOBAL_STOP_MISMATCH';
  end if;

  insert into production_control.google_writer_provider_fence_install_dispatches (
    dispatch_id, fence_id, dispatch_request_id, attempt, mutation_plan,
    provider_mutation_class, source_role, target_role, transition_intent,
    transition_intent_fingerprint, provider_preflight_fingerprint,
    provider_preflight_position,
    request_fingerprint,
    payload_hash, activation_revision, authority_generation_id,
    admission_generation_id, admission_revision, actor_id,
    authenticated_actor_fingerprint, issued_at, expires_at
  ) values (
    extensions.gen_random_uuid(), fence.fence_id, request_identifier,
    next_attempt,
    input->>'mutation_plan',
    input->>'provider_mutation_class', input->>'source_role',
    input->>'target_role', input->'transition_intent',
    pg_catalog.lower(input->>'transition_intent_fingerprint'),
    pg_catalog.lower(input->>'provider_preflight_fingerprint'),
    'SOURCE',
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
    activation.activation_revision, activation.authority_generation_id,
    gate.admission_generation_id, gate.admission_revision,
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'authenticated_actor_fingerprint'),
    dispatch_issued_at, dispatch_issued_at + interval '15 seconds'
  ) returning * into inserted;
  remaining_dispatch_budget_ms := greatest(0,
    pg_catalog.floor(extract(epoch from (
      inserted.expires_at - pg_catalog.clock_timestamp()
    )) * 1000)::bigint);
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result,
    details
  ) values (
    'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_DISPATCH_ISSUED',
    'SCORING_AUTHORITY', '2026', inserted.actor_id,
    inserted.request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'fence_id', inserted.fence_id,
      'dispatch_id', inserted.dispatch_id,
      'dispatch_request_id', inserted.dispatch_request_id,
      'attempt', inserted.attempt,
      'mutation_plan', inserted.mutation_plan,
      'provider_mutation_class', inserted.provider_mutation_class,
      'source_role', inserted.source_role,
      'target_role', inserted.target_role,
      'transition_intent_fingerprint',
        inserted.transition_intent_fingerprint,
      'provider_preflight_fingerprint',
        inserted.provider_preflight_fingerprint,
      'issued_at', inserted.issued_at,
      'expires_at', inserted.expires_at,
      'global_writer_stop_active_at', fence.global_writer_stop_active_at,
      'admission_reservation_active', true
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_INSTALL_DISPATCH_ISSUED',
    'fence_id', inserted.fence_id,
    'install_request_id', fence.install_request_id,
    'dispatch_id', inserted.dispatch_id,
    'dispatch_request_id', inserted.dispatch_request_id,
    'attempt', inserted.attempt,
    'mutation_plan', inserted.mutation_plan,
    'provider_mutation_class', inserted.provider_mutation_class,
    'source_role', inserted.source_role,
    'target_role', inserted.target_role,
    'transition_intent_fingerprint', inserted.transition_intent_fingerprint,
    'provider_preflight_fingerprint', inserted.provider_preflight_fingerprint,
    'provider_preflight_position', inserted.provider_preflight_position,
    'status', inserted.outcome_status,
    'issued_at', inserted.issued_at,
    'expires_at', inserted.expires_at,
    'remaining_dispatch_budget_ms', remaining_dispatch_budget_ms,
    'dispatch_usable', remaining_dispatch_budget_ms > 0,
    'replay_usable', remaining_dispatch_budget_ms > 0,
    'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.begin_production_google_writer_provider_fence_install_dispatch(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_scoring_ingress(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_scoring_ingress(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  return public.begin_production_scoring_ingress_v3(input);
end;
$$;


ALTER FUNCTION public.begin_production_scoring_ingress(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_scoring_ingress_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_scoring_ingress_v2(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  prior scoring_authority.scoring_ingress_leases%rowtype;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  expected_authority text := pg_catalog.upper(coalesce(input->>'expected_authority', ''));
  operation_request uuid;
  nonce_value text := pg_catalog.lower(coalesce(input->>'lease_nonce', ''));
  active_count integer;
  replay_nonce_rotated boolean := false;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform production_control.assert_scoring_admission_optimistic_input(input, false);
  if expected_authority <> 'GOOGLE'
     or input->>'writer_intent' is distinct from 'CANONICAL_LEGACY'
     or coalesce(input->>'operation', '') !~ '^[A-Z0-9:_-]{3,100}$'
     or coalesce(input->>'match_id', '') = ''
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or nonce_value !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or coalesce(input->>'deployment_id', '') !~ '^dpl_[A-Za-z0-9]{8,64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_INGRESS_V2_REQUEST_INVALID';
  end if;
  operation_request := (input->>'operation_request_id')::uuid;

  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for share;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into prior
  from scoring_authority.scoring_ingress_leases value
  where value.tournament_id = '2026'
    and value.protocol_version = 'ADMISSION_V2'
    and value.operation_request_id = operation_request
  for update;
  if found then
    if prior.request_payload_hash is distinct from
         production_control.scoring_admission_begin_payload_hash(input) then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_SCORING_INGRESS_V2_IDEMPOTENCY_CONFLICT';
    end if;
    if prior.authority is distinct from 'GOOGLE'
       or prior.authority_generation_id
         is distinct from (input->>'expected_authority_generation')::uuid
       or prior.admission_generation_id
         is distinct from (input->>'expected_admission_generation')::uuid
       or prior.admission_revision
         is distinct from (input->>'expected_admission_revision')::bigint
       or prior.admitted_activation_revision
         is distinct from (input->>'expected_activation_revision')::bigint
       or prior.deployment_commit is distinct from input->>'deployment_commit'
       or activation.authority_generation_id
         is distinct from prior.authority_generation_id
       or gate.admission_generation_id
         is distinct from prior.admission_generation_id
       or gate.admission_deployment_id is distinct from input->>'deployment_id'
       or activation.expected_deployment_commit
         is distinct from input->>'deployment_commit'
       or not gate.admission_protocol_enforced
       or gate.authority is distinct from 'GOOGLE'
       or activation.current_authority is distinct from 'GOOGLE'
       or activation.state is distinct from 'GOOGLE_LEASE_ARMED'
       or activation.scoring_ingress_enabled then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_SCORING_ADMISSION_V2_REPLAY_BOUNDARY_CHANGED';
    end if;
    if gate.admission_state = 'OPEN' then
      if gate.state is distinct from 'OPEN'
         or gate.active_closure_id is not null
         or gate.admission_revision is distinct from prior.admission_revision
         or activation.activation_revision
           is distinct from prior.admitted_activation_revision then
        raise exception using errcode = '40001',
          message = 'PRODUCTION_SCORING_ADMISSION_V2_REPLAY_BOUNDARY_CHANGED';
      end if;
    elsif gate.admission_state = 'CLOSING' then
      select * into strict closure
      from production_control.scoring_admission_closures value
      where value.closure_id = gate.active_closure_id
      for share;
      if gate.state is distinct from 'PAUSED'
         or closure.status is distinct from 'CLOSING'
         or closure.closure_kind is distinct from 'LEGACY_ADMISSION'
         or closure.authority is distinct from 'GOOGLE'
         or closure.authority_generation_id
           is distinct from prior.authority_generation_id
         or closure.admission_generation_id
           is distinct from prior.admission_generation_id
         or prior.close_fence_id is distinct from closure.closure_id
         or prior.admission_sequence > closure.lease_high_watermark then
        raise exception using errcode = '40001',
          message = 'PRODUCTION_SCORING_ADMISSION_V2_REPLAY_BOUNDARY_CHANGED';
      end if;
    else
      raise exception using errcode = '40001',
        message = 'PRODUCTION_SCORING_ADMISSION_V2_REPLAY_BOUNDARY_CHANGED';
    end if;
    if prior.resolution_state = 'ADMITTED' then
      update scoring_authority.scoring_ingress_leases
      set lease_nonce_hash = pg_catalog.encode(
            extensions.digest(nonce_value, 'sha256'), 'hex'
          ),
          expires_at = pg_catalog.now() + pg_catalog.make_interval(
            secs => greatest(30, least(
              coalesce((input->>'lease_seconds')::integer, 180), 300
            ))
          )
      where lease_id = prior.lease_id
      returning * into prior;
      replay_nonce_rotated := true;
      insert into production_control.operation_audit_events (
        event_type, domain, tournament_id, actor, request_fingerprint,
        result, details
      ) values (
        'PRODUCTION_SCORING_LEASE_V2_BEGIN_REPLAY',
        'SCORING_AUTHORITY', '2026', prior.actor_id,
        pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
        pg_catalog.jsonb_build_object(
          'lease_id', prior.lease_id,
          'operation_request_id', prior.operation_request_id,
          'resolution_state', prior.resolution_state,
          'lease_nonce_rotated', true,
          'replay_usable', true,
          'expires_at', prior.expires_at
        )
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'lease_id', prior.lease_id,
      'operation_request_id', prior.operation_request_id,
      'authority', prior.authority,
      'authority_generation_id', prior.authority_generation_id,
      'admission_generation_id', prior.admission_generation_id,
      'admission_revision', prior.admission_revision,
      'writer_intent', prior.writer_intent,
      'resolution_state', prior.resolution_state,
      'lease_nonce_rotated', replay_nonce_rotated,
      'replay_usable', replay_nonce_rotated,
      'idempotent', true
    );
  end if;

  if activation.activation_revision
       is distinct from (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id
       is distinct from (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id
       is distinct from (input->>'expected_admission_generation')::uuid
     or gate.admission_revision
       is distinct from (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or activation.expected_deployment_commit is distinct from input->>'deployment_commit'
     or gate.state <> 'OPEN' or gate.admission_state <> 'OPEN'
     or gate.active_closure_id is not null
     or not gate.admission_protocol_enforced
     or gate.authority <> expected_authority
     or activation.current_authority <> expected_authority
     or activation.state <> 'GOOGLE_LEASE_ARMED'
     or activation.scoring_ingress_enabled
     or not exists (
       select 1 from scoring_authority.matches match_value
       where match_value.tournament_id = '2026'
         and match_value.match_id = input->>'match_id'
     ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_SCORING_ADMISSION_V2_BOUNDARY_MISMATCH';
  end if;

  insert into scoring_authority.scoring_ingress_leases (
    tournament_id, match_id, authority, actor_id, created_at, expires_at,
    operation, authority_generation_id, deployment_commit, request_fingerprint,
    status, protocol_version, admission_sequence, admission_generation_id,
    admission_revision, admitted_activation_revision, lease_nonce_hash,
    writer_intent, operation_request_id, request_payload_hash, resolution_state
  ) values (
    '2026', input->>'match_id', expected_authority,
    pg_catalog.left(coalesce(nullif(input->>'actor_id', ''),
      'Authorized Production scorer'), 160),
    pg_catalog.now(), pg_catalog.now() + pg_catalog.make_interval(
      secs => greatest(30, least(
        coalesce((input->>'lease_seconds')::integer, 180), 300
      ))
    ),
    input->>'operation', activation.authority_generation_id,
    activation.expected_deployment_commit,
    pg_catalog.lower(input->>'request_fingerprint'), 'ACTIVE', 'ADMISSION_V2',
    pg_catalog.nextval('production_control.scoring_admission_lease_sequence'),
    gate.admission_generation_id, gate.admission_revision,
    activation.activation_revision,
    pg_catalog.encode(extensions.digest(nonce_value, 'sha256'), 'hex'),
    'CANONICAL_LEGACY', operation_request,
    production_control.scoring_admission_begin_payload_hash(input), 'ADMITTED'
  ) returning * into lease;
  select production_control.scoring_admission_unresolved_count(
    gate.admission_generation_id
  ) into active_count;
  update scoring_authority.ingress_gates
  set unresolved_client_queues = active_count, updated_at = pg_catalog.now()
  where tournament_id = '2026';
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_SCORING_LEASE_V2_ADMITTED', 'SCORING_AUTHORITY', '2026',
    lease.actor_id, lease.request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'lease_id', lease.lease_id,
      'admission_sequence', lease.admission_sequence,
      'match_id', lease.match_id,
      'operation', lease.operation,
      'operation_request_id', lease.operation_request_id,
      'writer_intent', lease.writer_intent,
      'authority_generation_id', lease.authority_generation_id,
      'admission_generation_id', lease.admission_generation_id,
      'admission_revision', lease.admission_revision,
      'expires_at', lease.expires_at
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_SCORING_LEASE_V2_ADMITTED',
    'lease_id', lease.lease_id,
    'operation_request_id', lease.operation_request_id,
    'authority', lease.authority,
    'authority_generation_id', lease.authority_generation_id,
    'admission_generation_id', lease.admission_generation_id,
    'admission_revision', lease.admission_revision,
    'writer_intent', lease.writer_intent,
    'resolution_state', lease.resolution_state,
    'lease_nonce_rotated', false, 'replay_usable', true,
    'active_or_unresolved_leases', active_count, 'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.begin_production_scoring_ingress_v2(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_scoring_ingress_v3(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_scoring_ingress_v3(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  response_value jsonb;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  operation_request uuid;
  expected_provider_principal text;
  remaining_dispatch_ms bigint;
begin
  if coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_INGRESS_V3_REQUEST_INVALID';
  end if;
  operation_request := (input->>'operation_request_id')::uuid;
  expected_provider_principal :=
    pg_catalog.lower(input->>'expected_provider_principal_fingerprint');
  if coalesce(expected_provider_principal, '') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_INGRESS_V3_PROVIDER_PRINCIPAL_REQUIRED';
  end if;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for share;
  if gate.provider_principal_fingerprint is distinct from
       expected_provider_principal
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_INGRESS_V3_PROVIDER_PRINCIPAL_MISMATCH';
  end if;
  response_value := public.begin_production_scoring_ingress_v2(input);
  if coalesce(response_value->>'lease_id', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_INGRESS_V3_RECEIPT_MISMATCH';
  end if;
  select * into lease
  from scoring_authority.scoring_ingress_leases value
  where value.tournament_id = '2026'
    and value.protocol_version = 'ADMISSION_V2'
    and value.operation_request_id = operation_request
    and value.lease_id = (response_value->>'lease_id')::uuid
  for update;
  if not found
     or lease.request_payload_hash is distinct from
       production_control.scoring_admission_begin_payload_hash(input)
     or lease.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or lease.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or lease.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or lease.admitted_activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or lease.writer_intent is distinct from 'CANONICAL_LEGACY'
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_INGRESS_V3_RECEIPT_MISMATCH';
  end if;
  if lease.provider_credential_class is null
     and lease.provider_principal_fingerprint is null then
    update scoring_authority.scoring_ingress_leases
    set provider_credential_class = 'LEGACY_PROVIDER_FENCEABLE',
        provider_principal_fingerprint = expected_provider_principal
    where lease_id = lease.lease_id
    returning * into lease;
  elsif lease.provider_credential_class is distinct from
      'LEGACY_PROVIDER_FENCEABLE'
     or lease.provider_principal_fingerprint is distinct from
       expected_provider_principal then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_INGRESS_V3_CREDENTIAL_OR_PRINCIPAL_MISMATCH';
  end if;
  perform production_control.assert_production_scoring_lease_nonce(
    lease, input->>'lease_nonce'
  );
  remaining_dispatch_ms := greatest(
    0::bigint,
    pg_catalog.floor(extract(epoch from (
      lease.expires_at - pg_catalog.clock_timestamp()
    )) * 1000)::bigint
  );
  return response_value || pg_catalog.jsonb_build_object(
    'contract_version', 'ADMISSION_V3',
    'expires_at', lease.expires_at,
    'remaining_dispatch_ms', remaining_dispatch_ms,
    'lease_nonce', pg_catalog.lower(input->>'lease_nonce'),
    'operation_request_id', lease.operation_request_id,
    'provider_credential_class', lease.provider_credential_class,
    'provider_principal_fingerprint', lease.provider_principal_fingerprint,
    'provider_dispatch_must_begin_before_expires_at', true,
    'replay_usable',
      coalesce((response_value->>'replay_usable')::boolean, false)
      and lease.resolution_state = 'ADMITTED'
      and remaining_dispatch_ms > 0
  );
end;
$_$;


ALTER FUNCTION public.begin_production_scoring_ingress_v3(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_scoring_maintenance(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_scoring_maintenance(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  high_watermark bigint;
  unresolved_count integer;
  response_value jsonb;
begin
  perform production_control.assert_maintenance_common_input(input);
  perform production_control.assert_no_active_physical_writer_fence();
  if coalesce(input->>'start_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_START_FINGERPRINT_REQUIRED';
  end if;
  existing := production_control.lookup_cutover_receipt(
    'BEGIN_SCORING_MAINTENANCE', input
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.maintenance_state <> 'NORMAL'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or activation.state <> 'GOOGLE_LEASE_ARMED'
     or activation.read_cutover_phase <> 'CURRENT_READS'
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.first_supabase_mutation_key is not null
     or activation.first_supabase_match_id is not null
     or activation.first_supabase_match_revision is not null
     or resource.scoring_authority <> 'GOOGLE'
     or resource.scoring_ingress_enabled
     or resource.workers_enabled
     or gate.authority <> 'GOOGLE'
     or gate.state <> 'OPEN'
     or gate.admission_state <> 'OPEN'
     or not gate.admission_protocol_enforced
     or gate.active_closure_id is not null
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or exists (
       select 1 from production_control.worker_controls value
       where value.enabled
     )
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_NOT_ENTERABLE';
  end if;
  select coalesce(pg_catalog.max(lease.admission_sequence), 0)
  into high_watermark
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = '2026'
    and lease.protocol_version = 'ADMISSION_V2'
    and lease.admission_generation_id = gate.admission_generation_id;
  insert into production_control.scoring_admission_closures (
    boundary_mode, closure_kind, prior_legacy_closure_id,
    tournament_id, authority, authority_generation_id,
    admission_generation_id, deployment_id,
    opening_admission_revision, closing_admission_revision,
    lease_high_watermark, start_source_fingerprint,
    external_fence_evidence_id, google_writer_provider_fence_id,
    google_writer_provider_verification_id, close_request_fingerprint,
    close_payload_hash, actor_id
  ) values (
    'MAINTENANCE_WINDOW_V1', 'LEGACY_ADMISSION', null,
    '2026', 'GOOGLE', activation.authority_generation_id,
    gate.admission_generation_id, gate.admission_deployment_id,
    gate.admission_revision, gate.admission_revision + 1,
    high_watermark, pg_catalog.lower(input->>'start_source_fingerprint'),
    null, null, null, pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(input),
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into closure;
  update scoring_authority.scoring_ingress_leases
  set close_fence_id = closure.closure_id
  where tournament_id = '2026'
    and protocol_version = 'ADMISSION_V2'
    and admission_generation_id = gate.admission_generation_id
    and resolution_state in (
      'ADMITTED', 'WRITE_STARTED', 'AMBIGUOUS', 'PARTIAL_WRITE'
    );
  unresolved_count :=
    production_control.scoring_admission_unresolved_count(
      gate.admission_generation_id
    ) + production_control.scoring_admission_legacy_blocker_count(
      gate.admission_enforced_at
    );
  update scoring_authority.ingress_gates
  set boundary_mode = 'MAINTENANCE_WINDOW_V1',
      state = 'PAUSED', admission_state = 'CLOSING',
      admission_revision = closure.closing_admission_revision,
      active_closure_id = closure.closure_id,
      external_fence_evidence_id = null,
      google_writer_provider_fence_id = null,
      google_writer_provider_verification_id = null,
      unresolved_client_queues = unresolved_count,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' returning * into gate;
  update production_control.cutover_activation_state
  set maintenance_state = 'SCORING_MAINTENANCE',
      maintenance_started_at = pg_catalog.now(), maintenance_ended_at = null,
      activation_revision = activation_revision + 1,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION' returning * into activation;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_SCORING_MAINTENANCE_ENTERED', 'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'boundary_mode', 'MAINTENANCE_WINDOW_V1',
      'closure_id', closure.closure_id,
      'lease_high_watermark', high_watermark,
      'active_or_unresolved_leases', unresolved_count,
      'canonical_authority', 'GOOGLE',
      'supabase_ingress_enabled', false
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_SCORING_MAINTENANCE_ENTERED',
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'maintenance_state', activation.maintenance_state,
    'closure_id', closure.closure_id,
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'admission_revision', gate.admission_revision,
    'execution_gate', gate.state, 'admission_state', gate.admission_state,
    'active_or_unresolved_leases', unresolved_count,
    'first_supabase_canonical_write_possible', false,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'BEGIN_SCORING_MAINTENANCE', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.begin_production_scoring_maintenance(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_step11_scoring_rehearsal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_step11_scoring_rehearsal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_rehearsal', 'production_control', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  run_id_value uuid := (input->>'run_id')::uuid;
  synthetic_id text := btrim(coalesce(input->>'synthetic_tournament_id',''));
  source_year integer := coalesce((input->>'source_tournament_year')::integer,0);
  source_tournament text := btrim(coalesce(input->>'source_tournament_id',''));
  source_match text := btrim(coalesce(input->>'source_match_id',''));
  candidate_sha_value text := lower(btrim(coalesce(input->>'candidate_sha','')));
  current_fingerprint text;
  authorization_at timestamptz;
  database_fixture jsonb;
  database_fixture_fingerprint text;
  existing_run production_rehearsal.scoring_runs%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_SERVICE_ROLE_REQUIRED';
  end if;
  scope := production_control.assert_current_shadow_v2_dormant();
  begin authorization_at := (input#>>'{director_authorization,authorized_at}')::timestamptz;
  exception when others then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_DIRECTOR_AUTHORIZATION_REQUIRED';
  end;
  if upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or input->>'project_ref' <> scope.project_ref
     or input->>'project_url' <> scope.project_url
     or input->>'source_workbook_id' <> scope.google_workbook_id
     or input->>'contract_version' <> 'production-step11-scoring-rehearsal-v1'
     or candidate_sha_value !~ '^[0-9a-f]{40}$'
     or lower(input->>'runtime_candidate_sha') <> candidate_sha_value
     or btrim(coalesce(input->>'candidate_hostname','')) !~ '^[a-z0-9-]+(?:\.[a-z0-9-]+)*\.vercel\.app$'
     or synthetic_id !~ '^STEP11-[0-9A-F-]{16,}$'
     or synthetic_id = '2026'
     or source_tournament = '2026'
     or source_year not between 2017 and 2025
     or input->>'s3_fingerprint' !~ '^[0-9a-f]{64}$'
     or input->>'expected_current_2026_fingerprint' !~ '^[0-9a-f]{64}$'
     or input->>'source_fingerprint' !~ '^[0-9a-f]{64}$'
     or input->>'frozen_fixture_fingerprint' !~ '^[0-9a-f]{64}$'
     or btrim(coalesce(input->>'run_token','')) = ''
     or jsonb_typeof(input->'frozen_fixture') <> 'object'
     or input#>>'{frozen_fixture,sourceTournamentId}' <> source_tournament
     or coalesce((input#>>'{frozen_fixture,sourceTournamentYear}')::integer,0) <> source_year
     or input#>>'{frozen_fixture,sourceMatchId}' <> source_match
     or encode(extensions.digest((input->'frozen_fixture')::text,'sha256'),'hex')
        <> input->>'frozen_fixture_fingerprint'
     or coalesce((input#>>'{director_authorization,authorized}')::boolean,false) is not true
     or input#>>'{director_authorization,scope}' <> 'PRODUCTION_STEP11_SCORING_REHEARSAL'
     or input#>>'{director_authorization,actor_id}' <> input->>'actor_id'
     or length(btrim(coalesce(input#>>'{director_authorization,authorization_id}',''))) < 8
     or authorization_at < now() - interval '15 minutes'
     or authorization_at > now() + interval '1 minute' then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_REHEARSAL_SCOPE_REQUIRED';
  end if;
  if not exists (
    select 1
    from production_control.director_entitlements entitlement
    join participant_identity.user_player_links link
      on link.auth_user_id = entitlement.auth_user_id
     and link.player_id = entitlement.player_id
     and link.status = 'ACTIVE'
    join participant_identity.tournament_roles role
      on role.auth_user_id = entitlement.auth_user_id
     and role.tournament_id = entitlement.tournament_id
     and role.role = 'DIRECTOR'
     and role.role_active
    where entitlement.tournament_id = '2026'
      and entitlement.player_id = input->>'actor_id'
      and entitlement.status = 'ACTIVE'
  ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_ACTIVE_DIRECTOR_REQUIRED';
  end if;
  database_fixture := production_rehearsal.completed_source_fixture(source_match);
  if database_fixture->>'sourceTournamentId' <> source_tournament
     or coalesce((database_fixture->>'sourceTournamentYear')::integer, 0) <> source_year
     or database_fixture->>'sourceMatchId' <> source_match then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_COMPLETED_SOURCE_MATCH_REQUIRED';
  end if;
  database_fixture_fingerprint := encode(extensions.digest(database_fixture::text, 'sha256'), 'hex');
  if input->'frozen_fixture' <> database_fixture
     or input->>'frozen_fixture_fingerprint' <> database_fixture_fingerprint
     or input->>'source_fingerprint' <> database_fixture_fingerprint then
    raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_SOURCE_FIXTURE_MISMATCH';
  end if;
  current_fingerprint := production_rehearsal.current_2026_fingerprint();
  if current_fingerprint <> input->>'expected_current_2026_fingerprint' then
    raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_CURRENT_2026_FINGERPRINT_MISMATCH';
  end if;
  select * into existing_run from production_rehearsal.scoring_runs value
  where value.run_id = run_id_value;
  if found then
    if existing_run.run_token_hash <> encode(extensions.digest(input->>'run_token','sha256'),'hex')
       or existing_run.candidate_sha <> candidate_sha_value
       or existing_run.candidate_hostname <> input->>'candidate_hostname'
       or existing_run.synthetic_tournament_id <> synthetic_id
       or existing_run.frozen_fixture_fingerprint <> database_fixture_fingerprint
       or existing_run.s3_fingerprint_before <> input->>'s3_fingerprint'
       or existing_run.current_2026_fingerprint_before <> current_fingerprint then
      raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_RUN_SCOPE_MISMATCH';
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'runId',existing_run.run_id,
      'syntheticTournamentId',existing_run.synthetic_tournament_id,
      'status',existing_run.status,'authority',existing_run.rehearsal_authority,
      'ingress',existing_run.ingress_state,'externalTransport','VIRTUAL',
      'externalGoogleWrites',0,'live2026Writes',0,
      'current2026Fingerprint',current_fingerprint);
  end if;
  insert into production_rehearsal.scoring_runs (
    run_id, contract_version, project_ref, project_url, source_workbook_id,
    candidate_sha, candidate_hostname, run_token_hash, actor_id,
    director_authorization_id, synthetic_tournament_id, source_tournament_id,
    source_tournament_year, source_match_id, source_fingerprint,
    frozen_fixture_fingerprint, frozen_fixture,
    s3_fingerprint_before, current_2026_fingerprint_before, expires_at
  ) values (
    run_id_value, 'production-step11-scoring-rehearsal-v1', scope.project_ref,
    scope.project_url, scope.google_workbook_id, candidate_sha_value,
    input->>'candidate_hostname', encode(extensions.digest(input->>'run_token','sha256'),'hex'),
    input->>'actor_id', input#>>'{director_authorization,authorization_id}', synthetic_id,
    source_tournament, source_year, source_match, input->>'source_fingerprint',
    input->>'frozen_fixture_fingerprint', input->'frozen_fixture',
    input->>'s3_fingerprint', current_fingerprint,
    least((input->>'expires_at')::timestamptz, now() + interval '4 hours')
  );
  insert into production_rehearsal.evidence_events (
    run_id, event_type, evidence, evidence_fingerprint
  ) values (
    run_id_value, 'RUN_PREPARED',
    jsonb_build_object('syntheticTournamentId',synthetic_id,'sourceTournamentId',source_tournament,
      'sourceMatchId',source_match,'candidateSha',candidate_sha_value,'externalGoogleWrites',0,
      'live2026Writes',0,'authority','GOOGLE','ingress','PAUSED'),
    encode(extensions.digest(concat_ws(E'\n', run_id_value::text, synthetic_id,
      source_match, candidate_sha_value, current_fingerprint),'sha256'),'hex')
  );
  return jsonb_build_object('ok',true,'runId',run_id_value,
    'syntheticTournamentId',synthetic_id,'authority','GOOGLE','ingress','PAUSED',
    'externalTransport','VIRTUAL','externalGoogleWrites',0,'live2026Writes',0,
    'current2026Fingerprint',current_fingerprint);
end;
$_$;


ALTER FUNCTION public.begin_production_step11_scoring_rehearsal(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_supabase_rollback_maintenance(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_supabase_rollback_maintenance(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  prior_closure production_control.scoring_admission_closures%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  high_watermark bigint;
  response_value jsonb;
begin
  perform production_control.assert_maintenance_common_input(input);
  existing := production_control.lookup_cutover_receipt(
    'BEGIN_SUPABASE_ROLLBACK_MAINTENANCE', input
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select * into strict prior_closure
  from production_control.scoring_admission_closures value
  where value.closure_id = gate.active_closure_id for update;
  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.authority <> 'SUPABASE'
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.state not in ('OPEN', 'PAUSED')
     or gate.admission_state <> 'CLOSED'
     or prior_closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or prior_closure.closure_kind <> 'LEGACY_ADMISSION'
     or prior_closure.status <> 'CONSUMED'
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SUPABASE_ROLLBACK_MAINTENANCE_NOT_ENTERABLE';
  end if;
  select coalesce(pg_catalog.max(lease.admission_sequence), 0)
  into high_watermark
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = '2026'
    and lease.admission_generation_id = gate.admission_generation_id;
  insert into production_control.scoring_admission_closures (
    boundary_mode, closure_kind, prior_legacy_closure_id,
    tournament_id, authority, authority_generation_id,
    admission_generation_id, deployment_id,
    opening_admission_revision, closing_admission_revision,
    lease_high_watermark, start_source_fingerprint,
    external_fence_evidence_id, google_writer_provider_fence_id,
    google_writer_provider_verification_id, close_request_fingerprint,
    close_payload_hash, actor_id
  ) values (
    'MAINTENANCE_WINDOW_V1', 'SUPABASE_INGRESS', prior_closure.closure_id,
    '2026', 'SUPABASE', activation.authority_generation_id,
    gate.admission_generation_id, gate.admission_deployment_id,
    gate.admission_revision, gate.admission_revision + 1,
    high_watermark, activation.expected_source_fingerprint,
    null, null, null, pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(input),
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into closure;
  update scoring_authority.ingress_gates
  set boundary_mode = 'MAINTENANCE_WINDOW_V1', state = 'PAUSED',
      admission_state = 'CLOSING',
      admission_revision = closure.closing_admission_revision,
      active_closure_id = closure.closure_id,
      external_fence_evidence_id = null,
      google_writer_provider_fence_id = null,
      google_writer_provider_verification_id = null,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' returning * into gate;
  update production_control.resource_scope
  set scoring_ingress_enabled = false, updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update production_control.cutover_activation_state
  set maintenance_state = 'SCORING_MAINTENANCE',
      maintenance_started_at = case when maintenance_state = 'NORMAL'
        then pg_catalog.now() else maintenance_started_at end,
      maintenance_ended_at = null, scoring_ingress_enabled = false,
      activation_revision = activation_revision + 1,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION' returning * into activation;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_SUPABASE_ROLLBACK_MAINTENANCE_ENTERED',
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'maintenance_state', 'SCORING_MAINTENANCE',
    'closure_id', closure.closure_id,
    'prior_legacy_closure_id', prior_closure.closure_id,
    'authority', 'SUPABASE', 'ingress', 'PAUSED',
    'admission_state', 'CLOSING',
    'activation_revision', activation.activation_revision,
    'admission_revision', gate.admission_revision,
    'first_supabase_canonical_write_possible',
      activation.first_supabase_write_possible_at is not null,
    'first_supabase_canonical_write_observed',
      activation.first_supabase_write_observed_at is not null,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'BEGIN_SUPABASE_ROLLBACK_MAINTENANCE', input, response_value
  );
  return response_value;
end;
$$;


ALTER FUNCTION public.begin_production_supabase_rollback_maintenance(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_vercel_writer_critical_waf_dispatch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_vercel_writer_critical_waf_dispatch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  prior production_control.vercel_writer_critical_waf_dispatches%rowtype;
  inserted production_control.vercel_writer_critical_waf_dispatches%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  reattestation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  request_identifier uuid;
  step_value text := pg_catalog.upper(coalesce(input->>'dispatch_step', ''));
  now_value timestamptz := pg_catalog.clock_timestamp();
  payload_hash_value text := production_control.cutover_payload_hash(input);
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if input->>'operation' is distinct from
       'BEGIN_PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH'
     or coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'dispatch_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'transition_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or step_value not in (
       'CRITICAL_RULE_INSERT', 'CRITICAL_DRAFT_ACTIVATE',
       'BASELINE_VERSION_ACTIVATE'
     )
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'provider_intent_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH_INPUT_INVALID';
  end if;
  request_identifier := (input->>'dispatch_request_id')::uuid;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into prior
  from production_control.vercel_writer_critical_waf_dispatches value
  where value.dispatch_request_id = request_identifier
  for update;
  if found then
    if prior.epoch_id is distinct from (input->>'epoch_id')::uuid
       or prior.dispatch_step is distinct from step_value
       or prior.transition_request_id is distinct from
         (input->>'transition_request_id')::uuid
       or prior.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or prior.payload_hash is distinct from payload_hash_value
       or prior.provider_intent_fingerprint is distinct from
         pg_catalog.lower(input->>'provider_intent_fingerprint')
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH_IDEMPOTENCY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'contract_version', 'CRITICAL_WINDOW_WAF_V1',
      'epoch_id', prior.epoch_id, 'dispatch_id', prior.dispatch_id,
      'dispatch_request_id', prior.dispatch_request_id,
      'transition_request_id', prior.transition_request_id,
      'dispatch_step', prior.dispatch_step,
      'request_fingerprint', prior.request_fingerprint,
      'provider_intent_fingerprint', prior.provider_intent_fingerprint,
      'transition_mode', (
        select value.transition_mode
        from production_control.vercel_writer_critical_waf_epochs value
        where value.epoch_id = prior.epoch_id
      ),
      'status', prior.status,
      'dispatch_usable', false, 'replay_usable', false,
      'remaining_dispatch_budget_ms', 0, 'idempotent', true
    );
  end if;
  select * into strict epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = (input->>'epoch_id')::uuid
  for update;
  if epoch.actor_id is distinct from input->>'actor_id'
     or epoch.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH_ACTOR_MISMATCH';
  end if;
  if (step_value = 'CRITICAL_RULE_INSERT' and (
        epoch.status is distinct from 'ACTIVATION_PENDING'
        or exists (
          select 1
          from production_control.vercel_writer_critical_waf_dispatches value
          where value.epoch_id = epoch.epoch_id
            and value.dispatch_step = 'CRITICAL_RULE_INSERT'
        )
      ))
     or (step_value = 'CRITICAL_DRAFT_ACTIVATE' and (
        epoch.status is distinct from 'ACTIVATION_PENDING'
        or epoch.provider_assigned_rule_id is null
        or not exists (
          select 1
          from production_control.vercel_writer_critical_waf_dispatches value
          where value.epoch_id = epoch.epoch_id
            and value.dispatch_step = 'CRITICAL_RULE_INSERT'
            and value.status = 'TARGET_CONFIRMED'
        )
      ))
     or (step_value = 'BASELINE_VERSION_ACTIVATE' and (
        epoch.status is distinct from 'FENCE_BOUND'
        or coalesce(input->>'restore_request_id', '')
          !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
        or coalesce(input->>'restore_request_fingerprint', '')
          !~ '^[0-9a-f]{64}$'
      ))
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH_STATE_INVALID';
  end if;
  if step_value = 'BASELINE_VERSION_ACTIVATE' then
    select * into strict fence
    from production_control.google_writer_provider_fences value
    where value.fence_id = epoch.bound_fence_id
    for update;
    select * into strict reattestation
    from production_control.vercel_writer_critical_waf_observations value
    where value.observation_id = epoch.latest_critical_reattest_observation_id
      and value.epoch_id = epoch.epoch_id;
    select * into strict activation
    from production_control.cutover_activation_state value
    where value.scope_key = 'BAGGER_INV_PRODUCTION'
    for update;
    select * into strict resource
    from production_control.resource_scope value
    where value.scope_key = 'BAGGER_INV_PRODUCTION'
    for update;
    select * into strict gate
    from scoring_authority.ingress_gates value
    where value.tournament_id = '2026'
    for update;
    if reattestation.evidence_stage is distinct from 'CRITICAL_REATTEST'
       or reattestation.expires_at <= pg_catalog.clock_timestamp()
       or (epoch.transition_mode = 'REHEARSAL' and (
         fence.status is distinct from 'ACL_RESTORED_WAF_ACTIVE'
         or activation.state is distinct from 'DORMANT'
         or activation.current_authority is distinct from 'GOOGLE'
         or activation.scoring_ingress_enabled
         or resource.scoring_authority is distinct from 'GOOGLE'
         or gate.state is distinct from 'PAUSED'
         or gate.authority is distinct from 'GOOGLE'
         or gate.admission_state is distinct from 'OPEN'
         or gate.admission_protocol_enforced
       ))
       or (epoch.transition_mode = 'CUTOVER' and (
         fence.status is distinct from 'INSTALLED'
         or activation.state is distinct from 'SCORING_COMMITTED'
         or activation.current_authority is distinct from 'SUPABASE'
         or not activation.scoring_ingress_enabled
         or resource.scoring_authority is distinct from 'SUPABASE'
         or gate.state is distinct from 'OPEN'
         or gate.authority is distinct from 'SUPABASE'
         or gate.admission_state is distinct from 'CLOSED'
         or not gate.admission_protocol_enforced
       ))
       or (epoch.transition_mode = 'ROLLBACK' and (
         fence.status is distinct from 'ACL_RESTORED_WAF_ACTIVE'
         or fence.lifecycle_mode is distinct from 'CUTOVER'
         or activation.current_authority is distinct from 'GOOGLE'
         or activation.scoring_ingress_enabled
         or resource.scoring_authority is distinct from 'GOOGLE'
         or gate.state is distinct from 'PAUSED'
         or gate.authority is distinct from 'GOOGLE'
         or gate.admission_state is distinct from 'OPEN'
         or gate.admission_protocol_enforced
       ))
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_BASELINE_RESTORE_NOT_SAFE';
    end if;
    update production_control.vercel_writer_critical_waf_epochs
    set status = 'RESTORE_PENDING',
        restore_pending_at = now_value,
        restore_request_id = (input->>'restore_request_id')::uuid,
        restore_request_fingerprint =
          pg_catalog.lower(input->>'restore_request_fingerprint'),
        restore_payload_hash = payload_hash_value,
        updated_at = now_value
    where epoch_id = epoch.epoch_id
    returning * into epoch;
  end if;
  insert into production_control.vercel_writer_critical_waf_dispatches (
    dispatch_id, epoch_id, dispatch_request_id, transition_request_id,
    dispatch_step, attempt,
    status, request_fingerprint, payload_hash, provider_intent_fingerprint,
    claimed_at, claim_expires_at, actor_id,
    authenticated_actor_fingerprint
  ) values (
    extensions.gen_random_uuid(), epoch.epoch_id, request_identifier,
    (input->>'transition_request_id')::uuid, step_value, 1, 'RESERVED',
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
    pg_catalog.lower(input->>'provider_intent_fingerprint'), now_value,
    now_value + interval '15 seconds',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'authenticated_actor_fingerprint')
  ) returning * into inserted;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'contract_version', 'CRITICAL_WINDOW_WAF_V1',
    'epoch_id', inserted.epoch_id, 'dispatch_id', inserted.dispatch_id,
    'dispatch_request_id', inserted.dispatch_request_id,
    'transition_request_id', inserted.transition_request_id,
    'dispatch_step', inserted.dispatch_step,
    'request_fingerprint', inserted.request_fingerprint,
    'transition_mode', epoch.transition_mode,
    'status', inserted.status,
    'provider_intent_fingerprint', inserted.provider_intent_fingerprint,
    'dispatch_usable', true, 'replay_usable', true,
    'remaining_dispatch_budget_ms', 15000, 'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.begin_production_vercel_writer_critical_waf_dispatch(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_vercel_writer_critical_waf_epoch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_vercel_writer_critical_waf_epoch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  prior production_control.vercel_writer_critical_waf_epochs%rowtype;
  epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  baseline_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  baseline_evidence jsonb := input->'baseline_waf_evidence';
  baseline_observation_identifier uuid := extensions.gen_random_uuid();
  epoch_identifier uuid;
  epoch_request uuid;
  observation_request uuid;
  baseline_transition_request uuid;
  baseline_evidence_request uuid;
  baseline_evidence_identifier uuid;
  purpose_value text := pg_catalog.upper(coalesce(input->>'purpose', ''));
  transition_mode_value text := pg_catalog.upper(
    coalesce(input->>'transition_mode', '')
  );
  payload_hash_value text := production_control.cutover_payload_hash(input);
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if input->>'operation' is distinct from
       'BEGIN_PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_EPOCH'
     or coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'epoch_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'baseline_observation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.jsonb_typeof(baseline_evidence) is distinct from 'object'
     or coalesce(baseline_evidence->>'transitionRequestId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(baseline_evidence->>'evidenceRequestId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(baseline_evidence->>'evidenceId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or purpose_value not in ('REHEARSAL', 'CUTOVER')
     or transition_mode_value not in ('REHEARSAL', 'CUTOVER', 'ROLLBACK')
     or (purpose_value = 'REHEARSAL' and
       transition_mode_value <> 'REHEARSAL')
     or (purpose_value = 'CUTOVER' and
       transition_mode_value not in ('CUTOVER', 'ROLLBACK'))
     or input->>'candidate_deployment_target' is distinct from 'PREVIEW'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'candidate_control_hosts_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_EPOCH_INPUT_INVALID';
  end if;
  epoch_identifier := (input->>'epoch_id')::uuid;
  epoch_request := (input->>'epoch_request_id')::uuid;
  observation_request := (input->>'baseline_observation_request_id')::uuid;
  baseline_transition_request :=
    (baseline_evidence->>'transitionRequestId')::uuid;
  baseline_evidence_request :=
    (baseline_evidence->>'evidenceRequestId')::uuid;
  baseline_evidence_identifier := (baseline_evidence->>'evidenceId')::uuid;
  if (
       select pg_catalog.count(distinct identifier)
       from pg_catalog.unnest(array[
         epoch_identifier, epoch_request, observation_request,
         baseline_transition_request, baseline_evidence_request,
         baseline_evidence_identifier
       ]) identifier
     ) <> 6
     or baseline_evidence->>'stage' is distinct from 'BASELINE_CAPTURE'
     or baseline_evidence->>'wafEpochId' is distinct from epoch_identifier::text
     or baseline_evidence->>'purpose' is distinct from purpose_value
     or baseline_evidence->>'transitionMode' is distinct from
       transition_mode_value
     or baseline_evidence->>'candidateAliasOrigin' is distinct from
       pg_catalog.lower(input->>'candidate_alias_origin')
     or baseline_evidence->>'candidateImmutableOrigin' is distinct from
       pg_catalog.lower(input->>'candidate_immutable_origin')
     or baseline_evidence->>'candidateDeploymentId' is distinct from
       input->>'candidate_deployment_id'
     or pg_catalog.lower(baseline_evidence->>'candidateCommitSha') is distinct
       from pg_catalog.lower(input->>'candidate_deployment_commit')
     or baseline_evidence->>'candidateDeploymentTarget' is distinct from
       pg_catalog.upper(input->>'candidate_deployment_target')
     or baseline_evidence->>'configurationMode' is distinct from 'BASELINE'
     or baseline_evidence->>'providerAssignedRuleId' is not null
     or baseline_evidence->>'baselineEvidenceId' is not null
     or baseline_evidence->>'criticalEvidenceId' is not null
     or (baseline_evidence->>'customRuleCount')::integer <> 0
     or (baseline_evidence->>'pendingDraftChangeCount')::integer <> 0
     or baseline_evidence->>'semanticConfigurationFingerprint' is distinct from
       baseline_evidence->>'baselineSemanticFingerprint'
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_BASELINE_SCOPE_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into prior
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_request_id = epoch_request
     or value.epoch_id = epoch_identifier
  for update;
  if found then
    if prior.epoch_id is distinct from epoch_identifier
       or prior.epoch_request_id is distinct from epoch_request
       or prior.baseline_transition_request_id is distinct from
         baseline_transition_request
       or prior.begin_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or prior.begin_payload_hash is distinct from payload_hash_value
       or prior.purpose is distinct from purpose_value
       or prior.transition_mode is distinct from transition_mode_value
       or prior.baseline_observation_id is distinct from (
         select value.observation_id
         from production_control.vercel_writer_critical_waf_observations value
         where value.provider_evidence_id =
           (baseline_evidence->>'evidenceId')::uuid
       )
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_EPOCH_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.vercel_writer_critical_waf_epoch_response(
      prior, true
    );
  end if;

  insert into production_control.vercel_writer_critical_waf_epochs (
    epoch_id, epoch_request_id, baseline_transition_request_id,
    purpose, transition_mode, status,
    begin_request_fingerprint, begin_payload_hash, vercel_project_id,
    vercel_team_id, candidate_deployment_id, candidate_deployment_commit,
    candidate_deployment_target, candidate_alias_origin,
    candidate_immutable_origin, candidate_control_hosts_fingerprint,
    baseline_active_config_version, baseline_active_config_etag,
    baseline_provider_configuration_id, baseline_provider_owner_id,
    baseline_configuration_identity_fingerprint,
    baseline_source_version_read_fingerprint,
    baseline_semantic_configuration_fingerprint,
    baseline_ordered_rules_fingerprint, baseline_custom_rule_count,
    run_owned_rule_name, run_owned_rule_nonce, provider_assigned_rule_id,
    run_owned_rule_fingerprint, run_owned_insert_document_fingerprint,
    critical_semantic_configuration_fingerprint, baseline_observation_id,
    actor_id, authenticated_actor_fingerprint
  ) values (
    epoch_identifier, epoch_request,
    baseline_transition_request,
    purpose_value, transition_mode_value,
    'ACTIVATION_PENDING',
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
    baseline_evidence->>'vercelProjectId',
    baseline_evidence->>'vercelTeamId',
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    pg_catalog.upper(input->>'candidate_deployment_target'),
    pg_catalog.lower(input->>'candidate_alias_origin'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    pg_catalog.lower(input->>'candidate_control_hosts_fingerprint'),
    baseline_evidence->>'configurationVersion',
    nullif(baseline_evidence->>'configurationEtag', ''),
    baseline_evidence->>'providerConfigurationId',
    baseline_evidence->>'providerOwnerId',
    pg_catalog.lower(
      baseline_evidence->>'configurationIdentityFingerprint'
    ),
    pg_catalog.lower(
      baseline_evidence->>'sourceVersionReadFingerprint'
    ),
    pg_catalog.lower(
      baseline_evidence->>'semanticConfigurationFingerprint'
    ),
    pg_catalog.lower(baseline_evidence->>'orderedCustomRulesFingerprint'),
    (baseline_evidence->>'customRuleCount')::integer,
    baseline_evidence->>'runOwnedRuleName',
    (baseline_evidence->>'runOwnedRuleNonce')::uuid, null,
    pg_catalog.lower(baseline_evidence->>'runOwnedRuleFingerprint'),
    pg_catalog.lower(
      baseline_evidence->>'runOwnedInsertDocumentFingerprint'
    ),
    null, baseline_observation_identifier,
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'authenticated_actor_fingerprint')
  ) returning * into epoch;

  baseline_observation :=
    production_control.insert_vercel_writer_critical_waf_observation(
      epoch.epoch_id, baseline_evidence, observation_request,
      pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
      baseline_observation_identifier
    );
  if baseline_observation.observation_id is distinct from
       epoch.baseline_observation_id
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_BASELINE_RECORD_RACE';
  end if;
  return production_control.vercel_writer_critical_waf_epoch_response(
    epoch, false
  );
end;
$_$;


ALTER FUNCTION public.begin_production_vercel_writer_critical_waf_epoch(input jsonb) OWNER TO postgres;

--
-- Name: begin_production_vercel_writer_quiesce_evidence(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_production_vercel_writer_quiesce_evidence(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  response_value jsonb;
  routing_audit jsonb;
  alias_recaptures jsonb;
  v3_input jsonb;
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
  waf_epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  waf_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  was_idempotent boolean;
begin
  perform production_control.assert_exact_vercel_routing_rule_audit(input);
  if pg_catalog.jsonb_typeof(input->'owner_freeze_ttl_seconds') is distinct from
       'number'
     or input->>'owner_freeze_ttl_seconds' is distinct from '2100'
     or pg_catalog.upper(coalesce(input->>'purpose', '')) not in (
       'REHEARSAL', 'CUTOVER'
     )
     or (
       pg_catalog.upper(input->>'purpose') = 'REHEARSAL'
       and input->>'owner_freeze_confirmation' is distinct from
         'I CONFIRM GOOGLE OWNER WRITES ARE FROZEN FOR THIS REHEARSAL'
     )
     or (
       pg_catalog.upper(input->>'purpose') = 'CUTOVER'
       and input->>'owner_freeze_confirmation' is distinct from
         'I CONFIRM GOOGLE OWNER WRITES ARE FROZEN FOR THIS PRODUCTION CUTOVER'
     )
     or coalesce(input->>'critical_waf_epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'critical_waf_observation_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or input->>'critical_waf_quiesce_stage' not in (
       'INSTALL', 'RESTORE_REATTEST'
     )
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_OWNER_FREEZE_V4_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict waf_epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = (input->>'critical_waf_epoch_id')::uuid
  for update;
  select * into strict waf_observation
  from production_control.vercel_writer_critical_waf_observations value
  where value.observation_id = (input->>'critical_waf_observation_id')::uuid
    and value.epoch_id = waf_epoch.epoch_id;
  if waf_epoch.purpose is distinct from
       pg_catalog.upper(input->>'purpose')
     or waf_epoch.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or waf_epoch.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or waf_observation.expires_at <= pg_catalog.clock_timestamp()
     or (input->>'critical_waf_quiesce_stage' = 'INSTALL' and (
       waf_epoch.status is distinct from 'ACTIVE_UNBOUND'
       or waf_epoch.critical_active_observation_id is distinct from
         waf_observation.observation_id
       or waf_observation.evidence_stage is distinct from 'CRITICAL_ACTIVE'
     ))
     or (input->>'critical_waf_quiesce_stage' = 'RESTORE_REATTEST' and (
       waf_epoch.status is distinct from 'FENCE_BOUND'
       or waf_observation.evidence_stage is distinct from 'CRITICAL_REATTEST'
       or waf_epoch.latest_critical_reattest_observation_id is distinct from
         waf_observation.observation_id
     ))
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_CRITICAL_WAF_NOT_ACTIVE';
  end if;
  v3_input := input - array[
    'routing_rule_global_invocation_quiescence_proved',
    'routing_rule_candidate_control_host_count',
    'routing_rule_candidate_control_hosts_fingerprint',
    'routing_rule_canonical_apex_safe_method_count',
    'routing_rule_canonical_apex_safe_methods_fingerprint',
    'routing_rule_canonical_apex_safe_method_writer_route_count',
    'routing_rule_canonical_apex_safe_method_writer_routes_fingerprint',
    'critical_waf_epoch_id', 'critical_waf_observation_id',
    'critical_waf_quiesce_stage'
  ];
  -- The immutable v3 base continues to validate its historical 1800-second
  -- request epoch.  The v4 wrapper owns the only exact 2100-second contract
  -- and extends only the newly returned v4 evidence row in this transaction;
  -- historical v3/v2 rows are never reinterpreted or rewritten.
  v3_input := pg_catalog.jsonb_set(
    v3_input, '{owner_freeze_ttl_seconds}', '1800'::jsonb, true
  );
  response_value :=
    public.begin_vercel_writer_quiesce_v4_candidate_base(v3_input);
  was_idempotent := coalesce(
    (response_value->>'idempotent')::boolean, false
  );
  update production_control.vercel_writer_quiesce_evidence value
  set owner_freeze_expires_at =
        value.owner_acknowledged_at + interval '2100 seconds',
      critical_waf_epoch_id = coalesce(
        value.critical_waf_epoch_id, waf_epoch.epoch_id
      ),
      critical_waf_observation_id = coalesce(
        value.critical_waf_observation_id, waf_observation.observation_id
      ),
      critical_waf_quiesce_stage = coalesce(
        value.critical_waf_quiesce_stage,
        input->>'critical_waf_quiesce_stage'
      ),
      updated_at = greatest(value.updated_at, pg_catalog.clock_timestamp())
  where value.evidence_id = (response_value->>'evidence_id')::uuid
    and value.owner_freeze_expires_at =
      value.owner_acknowledged_at + interval '1800 seconds'
  returning * into evidence;
  if not found then
    select * into strict evidence
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_id = (response_value->>'evidence_id')::uuid;
  end if;
  if evidence.owner_freeze_expires_at is distinct from
       evidence.owner_acknowledged_at + interval '2100 seconds'
     or evidence.critical_waf_epoch_id is distinct from waf_epoch.epoch_id
     or evidence.critical_waf_observation_id is distinct from
       waf_observation.observation_id
     or evidence.critical_waf_quiesce_stage is distinct from
       input->>'critical_waf_quiesce_stage'
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_OWNER_FREEZE_V4_MISMATCH';
  end if;
  routing_audit :=
    production_control.bind_current_vercel_routing_rule_audit(
      'QUIESCE', (response_value->>'evidence_id')::uuid, true, input
    );
  alias_recaptures := production_control.assert_current_vercel_alias_recaptures(
    (response_value->>'evidence_id')::uuid, 1
  );
  return production_control.vercel_quiesce_response(
    evidence, was_idempotent
  ) || routing_audit || alias_recaptures;
end;
$_$;


ALTER FUNCTION public.begin_production_vercel_writer_quiesce_evidence(input jsonb) OWNER TO postgres;

--
-- Name: begin_vercel_writer_quiesce_v3_base(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_vercel_writer_quiesce_v3_base(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  prior production_control.vercel_writer_quiesce_evidence%rowtype;
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
  provider_attestation
    production_control.vercel_provider_attestations%rowtype;
  request_identifier uuid;
  prior_identifier uuid;
  evidence_identifier uuid := extensions.gen_random_uuid();
  payload_hash text := production_control.cutover_payload_hash(input);
  normalized_inventory jsonb;
  normalized_live_inventory jsonb;
  normalized_probes jsonb;
  purpose_value text := pg_catalog.upper(coalesce(input->>'purpose', ''));
  freeze_ttl_seconds integer;
  begin_time timestamptz := pg_catalog.now();
  owner_acknowledged timestamptz := begin_time;
  owner_freeze_expires timestamptz;
  probe_scope_fingerprint text;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or input->>'candidate_deployment_target' not in ('PREVIEW', 'PRODUCTION')
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or purpose_value not in ('REHEARSAL', 'CUTOVER')
     or coalesce(input->>'candidate_credential_generation', '')
       !~ '^[A-Z0-9_:-]{3,120}$'
     or coalesce(input->>'main_branch_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_immutable_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or coalesce(input->>'routing_rule_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_revision', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or input->>'routing_rule_scope' is distinct from
       'PRODUCTION_GOOGLE_CANONICAL_WRITER_QUIESCE'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'owner_principal_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or input->>'owner_override_operationally_frozen' is distinct from 'true'
     or pg_catalog.jsonb_typeof(input->'provider_attestation')
       is distinct from 'object'
     or pg_catalog.jsonb_typeof(input->'live_origin_inventory')
       is distinct from 'array'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or pg_catalog.jsonb_typeof(input->'owner_freeze_ttl_seconds')
       is distinct from 'number'
     or coalesce(input->>'owner_freeze_ttl_seconds', '') !~ '^[0-9]+$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_BEGIN_INPUT_INVALID';
  end if;
  perform production_control.assert_current_provider_inventory_v3(
    input, false, true
  );
  request_identifier := (input->>'evidence_request_id')::uuid;
  prior_identifier := nullif(input->>'prior_evidence_id', '')::uuid;
  freeze_ttl_seconds := (input->>'owner_freeze_ttl_seconds')::integer;
  if freeze_ttl_seconds <> 1800 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_OWNER_FREEZE_INVALID';
  end if;
  if (purpose_value = 'REHEARSAL'
       and input->>'candidate_deployment_target' <> 'PREVIEW')
     or (purpose_value = 'CUTOVER'
       and input->>'candidate_deployment_target' <> 'PRODUCTION') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_CANDIDATE_TARGET_MISMATCH';
  end if;
  owner_freeze_expires := begin_time
    + freeze_ttl_seconds * interval '1 second';
  perform production_control.assert_exact_vercel_origin_inventory(
    input->'origin_inventory'
  );
  perform production_control.assert_exact_vercel_live_inventory(
    input->'origin_inventory', input->'live_origin_inventory',
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    input->>'candidate_deployment_target'
  );
  perform production_control.assert_exact_vercel_probe_records(
    input->'first_probe_records', input->'live_origin_inventory',
    pg_catalog.lower(input->>'main_branch_alias_origin'),
    pg_catalog.lower(input->>'candidate_alias_origin'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    input->>'candidate_deployment_target',
    input->>'candidate_credential_generation'
  );
  normalized_inventory := production_control.normalized_vercel_origin_inventory(
    input->'origin_inventory'
  );
  normalized_live_inventory :=
    production_control.normalized_vercel_origin_inventory(
      input->'live_origin_inventory'
    );
  normalized_probes := production_control.normalized_vercel_probe_records(
    input->'first_probe_records'
  );
  if (input->>'live_provider_inventory_count')::integer is distinct from
       pg_catalog.jsonb_array_length(normalized_live_inventory) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_PROVIDER_INVENTORY_MISMATCH';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(normalized_probes) probe
    where (probe->>10)::timestamptz < begin_time - interval '5 minutes'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_FIRST_PROBE_STALE';
  end if;
  probe_scope_fingerprint := production_control.structured_evidence_fingerprint(
    production_control.normalized_vercel_probe_scope(normalized_probes)
  );

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into evidence
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_request_id = request_identifier;
  if found then
    if evidence.begin_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or evidence.begin_payload_hash is distinct from payload_hash
       or evidence.candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or evidence.candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or evidence.candidate_deployment_target is distinct from
         input->>'candidate_deployment_target'
       or evidence.purpose is distinct from purpose_value then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.vercel_quiesce_response(evidence, true);
  end if;
  if prior_identifier is not null then
    select * into strict prior
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_id = prior_identifier;
    if prior.status is distinct from 'VERIFIED'
       or prior.purpose is distinct from purpose_value
       or prior.candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or prior.candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or prior.candidate_deployment_target is distinct from
         input->>'candidate_deployment_target'
       or prior.vercel_project_id is distinct from input->>'vercel_project_id'
       or prior.routing_rule_id is distinct from input->>'routing_rule_id'
       or prior.routing_rule_revision is distinct from
         input->>'routing_rule_revision'
       or prior.routing_rule_scope is distinct from input->>'routing_rule_scope'
       or prior.candidate_credential_generation is distinct from
         input->>'candidate_credential_generation'
       or prior.main_branch_alias_origin is distinct from
         pg_catalog.lower(input->>'main_branch_alias_origin')
       or prior.candidate_alias_origin is distinct from
         pg_catalog.lower(input->>'candidate_alias_origin')
       or prior.candidate_immutable_origin is distinct from
         pg_catalog.lower(input->>'candidate_immutable_origin')
       or prior.owner_principal_fingerprint is distinct from
         pg_catalog.lower(input->>'owner_principal_fingerprint')
       or prior.provider_inventory_schema is distinct from
         input->>'provider_inventory_schema'
       or prior.retained_provider_inventory_count is distinct from
         (input->>'retained_provider_inventory_count')::integer
       or prior.retained_provider_inventory_fingerprint is distinct from
         input->>'retained_provider_inventory_fingerprint'
       or prior.live_provider_inventory_count is distinct from
         (input->>'live_provider_inventory_count')::integer
       or prior.live_provider_inventory_fingerprint is distinct from
         input->>'live_provider_inventory_fingerprint'
       or prior.routing_rule_all_method_fence_required_host_count is distinct from
         (input->>'routing_rule_all_method_fence_required_host_count')::integer
       or prior.routing_rule_all_method_fence_required_hosts_fingerprint
         is distinct from
           input->>'routing_rule_all_method_fence_required_hosts_fingerprint'
       or prior.routing_rule_all_method_fence_required_path_count is distinct from
         (input->>'routing_rule_all_method_fence_required_path_count')::integer
       or prior.routing_rule_all_method_fence_required_paths_fingerprint
         is distinct from
           input->>'routing_rule_all_method_fence_required_paths_fingerprint'
       or prior.credential_confinement_evidence_schema is distinct from
         input->>'credential_confinement_evidence_schema'
       or prior.credential_confinement_record_count is distinct from
         (input->>'credential_confinement_record_count')::integer
       or prior.credential_confinement_records_fingerprint is distinct from
         input->>'credential_confinement_records_fingerprint'
       or prior.credential_confinement_evidence_fingerprint is distinct from
         input->>'credential_confinement_evidence_fingerprint'
       or prior.origin_inventory_fingerprint is distinct from
         production_control.vercel_origin_inventory_fingerprint(
           normalized_inventory
         )
       or exists (
         select value
         from pg_catalog.jsonb_array_elements(
           prior.live_origin_inventory
         ) value
         except
         select value
         from pg_catalog.jsonb_array_elements(
           normalized_live_inventory
         ) value
       ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_REFRESH_SCOPE_MISMATCH';
    end if;
  end if;

  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  if (purpose_value = 'REHEARSAL' and (
       prior_identifier is not null
       or activation.state is distinct from 'DORMANT'
       or activation.current_authority is distinct from 'GOOGLE'
       or activation.scoring_ingress_enabled
       or activation.first_supabase_write_possible_at is not null
       or activation.first_supabase_write_observed_at is not null
       or activation.active_google_writer_provider_fence_id is not null
       or activation.active_google_writer_provider_verification_id is not null
       or activation.active_vercel_quiesce_evidence_id is not null
       or resource.scoring_authority is distinct from 'GOOGLE'
       or resource.participant_identity_authority is distinct from 'PASSPORT'
       or resource.current_tournament_read_authority is distinct from 'GOOGLE'
       or resource.public_supabase_reads_enabled
       or resource.auth_user_creation_enabled
       or resource.scoring_ingress_enabled or resource.workers_enabled
       or gate.state is distinct from 'PAUSED'
       or gate.authority is distinct from 'GOOGLE'
       or gate.admission_state is distinct from 'OPEN'
       or gate.admission_protocol_enforced
       or gate.active_closure_id is not null
       or gate.external_fence_evidence_id is not null
       or gate.google_writer_provider_fence_id is not null
       or gate.google_writer_provider_verification_id is not null
       or exists (
         select 1 from production_control.worker_controls value
         where value.enabled or value.google_writes_allowed
       )
       or exists (
         select 1 from scoring_authority.scoring_ingress_leases value
         where value.tournament_id = '2026'
           and (value.status = 'ACTIVE' or value.resolution_state in (
             'LEGACY_UNCLASSIFIED', 'ADMITTED', 'WRITE_STARTED',
             'AMBIGUOUS', 'PARTIAL_WRITE'
           ))
       )
     ))
     or (purpose_value = 'CUTOVER' and prior_identifier is null and (
       activation.state is distinct from 'GOOGLE_LEASE_ARMED'
       or activation.read_cutover_phase is distinct from 'CURRENT_READS'
       or activation.current_authority is distinct from 'GOOGLE'
       or activation.scoring_ingress_enabled
       or activation.first_supabase_write_possible_at is not null
       or activation.first_supabase_write_observed_at is not null
       or activation.active_google_writer_provider_fence_id is not null
       or activation.active_google_writer_provider_verification_id is not null
       or activation.active_vercel_quiesce_evidence_id is not null
       or resource.scoring_authority is distinct from 'GOOGLE'
       or resource.participant_identity_authority is distinct from 'SUPABASE'
       or resource.current_tournament_read_authority is distinct from 'SUPABASE'
       or not resource.public_supabase_reads_enabled
       or not resource.auth_user_creation_enabled
       or resource.scoring_ingress_enabled or resource.workers_enabled
       or gate.state is distinct from 'OPEN'
       or gate.authority is distinct from 'GOOGLE'
       or gate.admission_state is distinct from 'OPEN'
       or not gate.admission_protocol_enforced
       or gate.active_closure_id is not null
       or gate.external_fence_evidence_id is not null
       or gate.google_writer_provider_fence_id is not null
       or gate.google_writer_provider_verification_id is not null
       or exists (
         select 1 from production_control.worker_controls value
         where value.enabled or value.google_writes_allowed
       )
     ))
     or (purpose_value = 'CUTOVER' and prior_identifier is not null and (
       activation.active_google_writer_provider_fence_id is null
       or activation.active_google_writer_provider_verification_id is null
       or activation.active_vercel_quiesce_evidence_id is distinct from
         prior_identifier
       or not exists (
         select 1
         from production_control.google_writer_provider_fences fence
         where fence.fence_id =
             activation.active_google_writer_provider_fence_id
           and fence.status = 'INSTALLED'
           and fence.active_verification_id =
             activation.active_google_writer_provider_verification_id
           and fence.quiesce_evidence_id = prior_identifier
           and fence.candidate_deployment_id =
             input->>'candidate_deployment_id'
           and fence.candidate_deployment_commit =
             pg_catalog.lower(input->>'candidate_deployment_commit')
       )
       or gate.google_writer_provider_fence_id is distinct from
         activation.active_google_writer_provider_fence_id
       or gate.google_writer_provider_verification_id is distinct from
         activation.active_google_writer_provider_verification_id
       or not (
         (
           activation.state in ('GOOGLE_LEASE_ARMED', 'CUTOVER_PREPARED')
           and activation.read_cutover_phase = 'CURRENT_READS'
           and activation.current_authority = 'GOOGLE'
           and not activation.scoring_ingress_enabled
           and activation.first_supabase_write_possible_at is null
           and activation.first_supabase_write_observed_at is null
           and resource.scoring_authority = 'GOOGLE'
           and resource.participant_identity_authority = 'SUPABASE'
           and resource.current_tournament_read_authority = 'SUPABASE'
           and resource.public_supabase_reads_enabled
           and resource.auth_user_creation_enabled
           and not resource.scoring_ingress_enabled
           and not resource.workers_enabled
           and gate.authority = 'GOOGLE'
           and gate.admission_protocol_enforced
           and (
             (activation.state = 'GOOGLE_LEASE_ARMED'
               and gate.state = 'OPEN' and gate.admission_state = 'OPEN'
               and gate.active_closure_id is null)
             or (gate.state = 'PAUSED'
               and gate.admission_state in ('CLOSING', 'CLOSED')
               and exists (
                 select 1
                 from production_control.scoring_admission_closures closure
                 where closure.closure_id = gate.active_closure_id
                   and closure.closure_kind = 'LEGACY_ADMISSION'
                   and closure.authority = 'GOOGLE'
                   and closure.status in ('CLOSING', 'CLOSED')
               ))
           )
         )
         or (
           activation.state in ('SCORING_COMMITTED', 'ROLLBACK_PREPARED')
           and activation.read_cutover_phase = 'CURRENT_READS'
           and activation.current_authority = 'SUPABASE'
           and activation.scoring_ingress_enabled
           and activation.first_supabase_write_possible_at is not null
           and resource.scoring_authority = 'SUPABASE'
           and resource.participant_identity_authority = 'SUPABASE'
           and resource.current_tournament_read_authority = 'SUPABASE'
           and resource.public_supabase_reads_enabled
           and resource.auth_user_creation_enabled
           and resource.scoring_ingress_enabled
           and gate.authority = 'SUPABASE'
           and gate.admission_state = 'CLOSED'
           and gate.admission_protocol_enforced
           and (
             (activation.state = 'SCORING_COMMITTED'
               and gate.state = 'OPEN'
               and exists (
                 select 1
                 from production_control.scoring_admission_closures closure
                 where closure.closure_id = gate.active_closure_id
                   and closure.closure_kind = 'LEGACY_ADMISSION'
                   and closure.authority = 'GOOGLE'
                   and closure.status = 'CONSUMED'
               ))
             or (gate.state = 'PAUSED'
               and exists (
                 select 1
                 from production_control.scoring_admission_closures closure
                 where closure.closure_id = gate.active_closure_id
                   and closure.closure_kind = 'SUPABASE_INGRESS'
                   and closure.authority = 'SUPABASE'
                   and closure.status in ('CLOSING', 'CLOSED')
               ))
           )
         )
         or (
           activation.state in ('DORMANT', 'ROLLED_BACK')
           and activation.current_authority = 'GOOGLE'
           and not activation.scoring_ingress_enabled
           and activation.active_transition_epoch_id is null
           and resource.scoring_authority = 'GOOGLE'
           and resource.participant_identity_authority = 'PASSPORT'
           and resource.current_tournament_read_authority = 'GOOGLE'
           and not resource.public_supabase_reads_enabled
           and not resource.auth_user_creation_enabled
           and not resource.scoring_ingress_enabled
           and not resource.workers_enabled
           and gate.state = 'PAUSED'
           and gate.authority = 'GOOGLE'
           and gate.admission_state = 'OPEN'
           and not gate.admission_protocol_enforced
           and gate.active_closure_id is null
           and gate.external_fence_evidence_id is null
         )
       )
     )) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_START_STATE_INVALID';
  end if;

  insert into production_control.vercel_writer_quiesce_evidence (
    evidence_id, prior_evidence_id, evidence_request_id,
    begin_request_fingerprint, begin_payload_hash, purpose, vercel_project_id,
    routing_rule_id, routing_rule_revision, routing_rule_scope,
    candidate_deployment_id, candidate_deployment_commit,
    candidate_deployment_target, candidate_credential_generation,
    main_branch_alias_origin,
    candidate_alias_origin, candidate_immutable_origin,
    origin_inventory, origin_inventory_count, origin_inventory_fingerprint,
    live_origin_inventory, live_origin_inventory_count,
    live_origin_inventory_fingerprint,
    first_probe_records, first_probe_fingerprint, probe_scope_fingerprint,
    credential_generation_fingerprint,
    provider_inventory_schema,
    retained_provider_inventory_count, retained_provider_inventory_fingerprint,
    live_provider_inventory_count, live_provider_inventory_fingerprint,
    routing_rule_all_method_fence_required_host_count,
    routing_rule_all_method_fence_required_hosts_fingerprint,
    routing_rule_all_method_fence_required_path_count,
    routing_rule_all_method_fence_required_paths_fingerprint,
    credential_confinement_evidence_schema,
    credential_confinement_record_count,
    credential_confinement_records_fingerprint,
    credential_confinement_evidence_fingerprint,
    authenticated_actor_fingerprint,
    owner_principal_fingerprint, owner_override_operationally_frozen,
    owner_acknowledged_at, owner_freeze_expires_at, actor_id
  ) values (
    evidence_identifier, prior_identifier, request_identifier,
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash,
    purpose_value,
    input->>'vercel_project_id', input->>'routing_rule_id',
    input->>'routing_rule_revision', input->>'routing_rule_scope',
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    input->>'candidate_deployment_target',
    input->>'candidate_credential_generation',
    pg_catalog.lower(input->>'main_branch_alias_origin'),
    pg_catalog.lower(input->>'candidate_alias_origin'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    normalized_inventory, pg_catalog.jsonb_array_length(normalized_inventory),
    production_control.vercel_origin_inventory_fingerprint(normalized_inventory),
    normalized_live_inventory,
    pg_catalog.jsonb_array_length(normalized_live_inventory),
    production_control.vercel_origin_inventory_fingerprint(
      normalized_live_inventory
    ),
    normalized_probes,
    production_control.structured_evidence_fingerprint(normalized_probes),
    probe_scope_fingerprint,
    production_control.structured_evidence_fingerprint(
      pg_catalog.jsonb_build_object(
        'origin_inventory_fingerprint',
          production_control.vercel_origin_inventory_fingerprint(
            normalized_inventory
          ),
        'live_origin_inventory_fingerprint',
          production_control.vercel_origin_inventory_fingerprint(
            normalized_live_inventory
          ),
        'provider_inventory_schema', input->>'provider_inventory_schema',
        'retained_provider_inventory_fingerprint',
          input->>'retained_provider_inventory_fingerprint',
        'live_provider_inventory_fingerprint',
          input->>'live_provider_inventory_fingerprint',
        'routing_rule_all_method_fence_required_host_count',
          input->'routing_rule_all_method_fence_required_host_count',
        'routing_rule_all_method_fence_required_hosts_fingerprint',
          input->>'routing_rule_all_method_fence_required_hosts_fingerprint',
        'routing_rule_all_method_fence_required_path_count',
          input->'routing_rule_all_method_fence_required_path_count',
        'routing_rule_all_method_fence_required_paths_fingerprint',
          input->>'routing_rule_all_method_fence_required_paths_fingerprint',
        'production_target_capabilities',
          '["LEGACY_GOOGLE_SERVICE_ACCOUNT_V0","PRODUCTION_WORKBOOK_SELECTOR"]'::jsonb,
        'project_preview_capabilities',
          '["LEGACY_GOOGLE_SERVICE_ACCOUNT_V0","POTENTIAL_DEDICATED_PRODUCTION_GOOGLE_SERVICE_ACCOUNT_V1","POTENTIAL_PRODUCTION_WORKBOOK_SELECTOR"]'::jsonb,
        'candidate_credential_generation',
          input->>'candidate_credential_generation'
      )
    ),
    input->>'provider_inventory_schema',
    (input->>'retained_provider_inventory_count')::integer,
    input->>'retained_provider_inventory_fingerprint',
    (input->>'live_provider_inventory_count')::integer,
    input->>'live_provider_inventory_fingerprint',
    (input->>'routing_rule_all_method_fence_required_host_count')::integer,
    input->>'routing_rule_all_method_fence_required_hosts_fingerprint',
    (input->>'routing_rule_all_method_fence_required_path_count')::integer,
    input->>'routing_rule_all_method_fence_required_paths_fingerprint',
    input->>'credential_confinement_evidence_schema',
    (input->>'credential_confinement_record_count')::integer,
    input->>'credential_confinement_records_fingerprint',
    input->>'credential_confinement_evidence_fingerprint',
    pg_catalog.lower(input->>'authenticated_actor_fingerprint'),
    pg_catalog.lower(input->>'owner_principal_fingerprint'), true,
    owner_acknowledged, owner_freeze_expires,
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into evidence;

  provider_attestation :=
    production_control.record_verified_vercel_provider_attestation(
      evidence.evidence_id, 'BEGIN', evidence.begin_request_fingerprint,
      input->'provider_attestation'
    );

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_VERCEL_WRITER_QUIESCE_DRAIN_STARTED',
    'SCORING_AUTHORITY', '2026', evidence.actor_id,
    evidence.begin_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'evidence_id', evidence.evidence_id,
      'purpose', evidence.purpose,
      'candidate_deployment_id', evidence.candidate_deployment_id,
      'candidate_deployment_commit', evidence.candidate_deployment_commit,
      'routing_rule_id', evidence.routing_rule_id,
      'routing_rule_revision', evidence.routing_rule_revision,
      'provider_attestation_id', provider_attestation.attestation_id,
      'provider_attestation_fingerprint',
        provider_attestation.attestation_fingerprint,
      'provider_attestation_signer_key_fingerprint',
        provider_attestation.signer_key_fingerprint,
      'provider_attestation_signer_key_version',
        provider_attestation.signer_key_version,
      'vercel_team_id', provider_attestation.vercel_team_id,
      'live_origin_inventory_count',
        provider_attestation.live_origin_inventory_count,
      'live_origin_inventory_fingerprint',
        provider_attestation.live_origin_inventory_fingerprint,
      'redacted_environment_scope_fingerprint',
        provider_attestation.redacted_environment_scope_fingerprint,
      'origin_inventory_count', evidence.origin_inventory_count,
      'origin_inventory_fingerprint', evidence.origin_inventory_fingerprint,
      'provider_inventory_schema', evidence.provider_inventory_schema,
      'retained_provider_inventory_fingerprint',
        evidence.retained_provider_inventory_fingerprint,
      'live_provider_inventory_fingerprint',
        evidence.live_provider_inventory_fingerprint,
      'first_probe_fingerprint', evidence.first_probe_fingerprint,
      'drain_started_at', evidence.drain_started_at
    )
  );
  return production_control.vercel_quiesce_response(evidence, false);
end;
$_$;


ALTER FUNCTION public.begin_vercel_writer_quiesce_v3_base(input jsonb) OWNER TO postgres;

--
-- Name: begin_vercel_writer_quiesce_v4_candidate_base(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.begin_vercel_writer_quiesce_v4_candidate_base(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  prior production_control.vercel_writer_quiesce_evidence%rowtype;
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
  provider_attestation
    production_control.vercel_provider_attestations%rowtype;
  request_identifier uuid;
  prior_identifier uuid;
  evidence_identifier uuid := extensions.gen_random_uuid();
  payload_hash text := production_control.cutover_payload_hash(input);
  normalized_inventory jsonb;
  normalized_live_inventory jsonb;
  normalized_probes jsonb;
  purpose_value text := pg_catalog.upper(coalesce(input->>'purpose', ''));
  freeze_ttl_seconds integer;
  begin_time timestamptz := pg_catalog.now();
  owner_acknowledged timestamptz := begin_time;
  owner_freeze_expires timestamptz;
  probe_scope_fingerprint text;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or input->>'candidate_deployment_target' not in ('PREVIEW', 'PRODUCTION')
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or purpose_value not in ('REHEARSAL', 'CUTOVER')
     or coalesce(input->>'candidate_credential_generation', '')
       !~ '^[A-Z0-9_:-]{3,120}$'
     or coalesce(input->>'main_branch_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_immutable_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or coalesce(input->>'routing_rule_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_revision', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or input->>'routing_rule_scope' is distinct from
       'PRODUCTION_GOOGLE_CANONICAL_WRITER_QUIESCE'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'owner_principal_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or input->>'owner_override_operationally_frozen' is distinct from 'true'
     or pg_catalog.jsonb_typeof(input->'provider_attestation')
       is distinct from 'object'
     or pg_catalog.jsonb_typeof(input->'live_origin_inventory')
       is distinct from 'array'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or pg_catalog.jsonb_typeof(input->'owner_freeze_ttl_seconds')
       is distinct from 'number'
     or coalesce(input->>'owner_freeze_ttl_seconds', '') !~ '^[0-9]+$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_BEGIN_INPUT_INVALID';
  end if;
  perform production_control.assert_current_provider_inventory_v3(
    input, false, true
  );
  request_identifier := (input->>'evidence_request_id')::uuid;
  prior_identifier := nullif(input->>'prior_evidence_id', '')::uuid;
  freeze_ttl_seconds := (input->>'owner_freeze_ttl_seconds')::integer;
  if freeze_ttl_seconds <> 1800 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_OWNER_FREEZE_INVALID';
  end if;
  if (purpose_value = 'REHEARSAL'
       and input->>'candidate_deployment_target' <> 'PREVIEW')
     or (purpose_value = 'CUTOVER'
       and input->>'candidate_deployment_target' <> 'PREVIEW') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_CANDIDATE_TARGET_MISMATCH';
  end if;
  owner_freeze_expires := begin_time
    + freeze_ttl_seconds * interval '1 second';
  perform production_control.assert_exact_vercel_origin_inventory(
    input->'origin_inventory'
  );
  perform production_control.assert_exact_vercel_live_inventory(
    input->'origin_inventory', input->'live_origin_inventory',
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    input->>'candidate_deployment_target'
  );
  perform production_control.assert_exact_vercel_probe_records(
    input->'first_probe_records', input->'live_origin_inventory',
    pg_catalog.lower(input->>'main_branch_alias_origin'),
    pg_catalog.lower(input->>'candidate_alias_origin'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    input->>'candidate_deployment_target',
    input->>'candidate_credential_generation'
  );
  normalized_inventory := production_control.normalized_vercel_origin_inventory(
    input->'origin_inventory'
  );
  normalized_live_inventory :=
    production_control.normalized_vercel_origin_inventory(
      input->'live_origin_inventory'
    );
  normalized_probes := production_control.normalized_vercel_probe_records(
    input->'first_probe_records'
  );
  if (input->>'live_provider_inventory_count')::integer is distinct from
       pg_catalog.jsonb_array_length(normalized_live_inventory) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_PROVIDER_INVENTORY_MISMATCH';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(normalized_probes) probe
    where (probe->>10)::timestamptz < begin_time - interval '5 minutes'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_FIRST_PROBE_STALE';
  end if;
  probe_scope_fingerprint := production_control.structured_evidence_fingerprint(
    production_control.normalized_vercel_probe_scope(normalized_probes)
  );

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into evidence
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_request_id = request_identifier;
  if found then
    if evidence.begin_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or evidence.begin_payload_hash is distinct from payload_hash
       or evidence.candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or evidence.candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or evidence.candidate_deployment_target is distinct from
         input->>'candidate_deployment_target'
       or evidence.purpose is distinct from purpose_value then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.vercel_quiesce_response(evidence, true);
  end if;
  if prior_identifier is not null then
    select * into strict prior
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_id = prior_identifier;
    if prior.status is distinct from 'VERIFIED'
       or prior.purpose is distinct from purpose_value
       or prior.candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or prior.candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or prior.candidate_deployment_target is distinct from
         input->>'candidate_deployment_target'
       or prior.vercel_project_id is distinct from input->>'vercel_project_id'
       or prior.routing_rule_id is distinct from input->>'routing_rule_id'
       or prior.routing_rule_revision is distinct from
         input->>'routing_rule_revision'
       or prior.routing_rule_scope is distinct from input->>'routing_rule_scope'
       or prior.candidate_credential_generation is distinct from
         input->>'candidate_credential_generation'
       or prior.main_branch_alias_origin is distinct from
         pg_catalog.lower(input->>'main_branch_alias_origin')
       or prior.candidate_alias_origin is distinct from
         pg_catalog.lower(input->>'candidate_alias_origin')
       or prior.candidate_immutable_origin is distinct from
         pg_catalog.lower(input->>'candidate_immutable_origin')
       or prior.owner_principal_fingerprint is distinct from
         pg_catalog.lower(input->>'owner_principal_fingerprint')
       or prior.provider_inventory_schema is distinct from
         input->>'provider_inventory_schema'
       or prior.retained_provider_inventory_count is distinct from
         (input->>'retained_provider_inventory_count')::integer
       or prior.retained_provider_inventory_fingerprint is distinct from
         input->>'retained_provider_inventory_fingerprint'
       or prior.live_provider_inventory_count is distinct from
         (input->>'live_provider_inventory_count')::integer
       or prior.live_provider_inventory_fingerprint is distinct from
         input->>'live_provider_inventory_fingerprint'
       or prior.routing_rule_all_method_fence_required_host_count is distinct from
         (input->>'routing_rule_all_method_fence_required_host_count')::integer
       or prior.routing_rule_all_method_fence_required_hosts_fingerprint
         is distinct from
           input->>'routing_rule_all_method_fence_required_hosts_fingerprint'
       or prior.routing_rule_all_method_fence_required_path_count is distinct from
         (input->>'routing_rule_all_method_fence_required_path_count')::integer
       or prior.routing_rule_all_method_fence_required_paths_fingerprint
         is distinct from
           input->>'routing_rule_all_method_fence_required_paths_fingerprint'
       or prior.credential_confinement_evidence_schema is distinct from
         input->>'credential_confinement_evidence_schema'
       or prior.credential_confinement_record_count is distinct from
         (input->>'credential_confinement_record_count')::integer
       or prior.credential_confinement_records_fingerprint is distinct from
         input->>'credential_confinement_records_fingerprint'
       or prior.credential_confinement_evidence_fingerprint is distinct from
         input->>'credential_confinement_evidence_fingerprint'
       or prior.origin_inventory_fingerprint is distinct from
         production_control.vercel_origin_inventory_fingerprint(
           normalized_inventory
         )
       or exists (
         select value
         from pg_catalog.jsonb_array_elements(
           prior.live_origin_inventory
         ) value
         except
         select value
         from pg_catalog.jsonb_array_elements(
           normalized_live_inventory
         ) value
       ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_REFRESH_SCOPE_MISMATCH';
    end if;
  end if;

  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  if (purpose_value = 'REHEARSAL' and (
       prior_identifier is not null
       or activation.state is distinct from 'DORMANT'
       or activation.current_authority is distinct from 'GOOGLE'
       or activation.scoring_ingress_enabled
       or activation.first_supabase_write_possible_at is not null
       or activation.first_supabase_write_observed_at is not null
       or activation.active_google_writer_provider_fence_id is not null
       or activation.active_google_writer_provider_verification_id is not null
       or activation.active_vercel_quiesce_evidence_id is not null
       or resource.scoring_authority is distinct from 'GOOGLE'
       or resource.participant_identity_authority is distinct from 'PASSPORT'
       or resource.current_tournament_read_authority is distinct from 'GOOGLE'
       or resource.public_supabase_reads_enabled
       or resource.auth_user_creation_enabled
       or resource.scoring_ingress_enabled or resource.workers_enabled
       or gate.state is distinct from 'PAUSED'
       or gate.authority is distinct from 'GOOGLE'
       or gate.admission_state is distinct from 'OPEN'
       or gate.admission_protocol_enforced
       or gate.active_closure_id is not null
       or gate.external_fence_evidence_id is not null
       or gate.google_writer_provider_fence_id is not null
       or gate.google_writer_provider_verification_id is not null
       or exists (
         select 1 from production_control.worker_controls value
         where value.enabled or value.google_writes_allowed
       )
       or exists (
         select 1 from scoring_authority.scoring_ingress_leases value
         where value.tournament_id = '2026'
           and (value.status = 'ACTIVE' or value.resolution_state in (
             'LEGACY_UNCLASSIFIED', 'ADMITTED', 'WRITE_STARTED',
             'AMBIGUOUS', 'PARTIAL_WRITE'
           ))
       )
     ))
     or (purpose_value = 'CUTOVER' and prior_identifier is null and (
       activation.state is distinct from 'GOOGLE_LEASE_ARMED'
       or activation.read_cutover_phase is distinct from 'CURRENT_READS'
       or activation.current_authority is distinct from 'GOOGLE'
       or activation.scoring_ingress_enabled
       or activation.first_supabase_write_possible_at is not null
       or activation.first_supabase_write_observed_at is not null
       or activation.active_google_writer_provider_fence_id is not null
       or activation.active_google_writer_provider_verification_id is not null
       or activation.active_vercel_quiesce_evidence_id is not null
       or resource.scoring_authority is distinct from 'GOOGLE'
       or resource.participant_identity_authority is distinct from 'SUPABASE'
       or resource.current_tournament_read_authority is distinct from 'SUPABASE'
       or not resource.public_supabase_reads_enabled
       or not resource.auth_user_creation_enabled
       or resource.scoring_ingress_enabled or resource.workers_enabled
       or gate.state is distinct from 'OPEN'
       or gate.authority is distinct from 'GOOGLE'
       or gate.admission_state is distinct from 'OPEN'
       or not gate.admission_protocol_enforced
       or gate.active_closure_id is not null
       or gate.external_fence_evidence_id is not null
       or gate.google_writer_provider_fence_id is not null
       or gate.google_writer_provider_verification_id is not null
       or exists (
         select 1 from production_control.worker_controls value
         where value.enabled or value.google_writes_allowed
       )
     ))
     or (purpose_value = 'CUTOVER' and prior_identifier is not null and (
       activation.active_google_writer_provider_fence_id is null
       or activation.active_google_writer_provider_verification_id is null
       or activation.active_vercel_quiesce_evidence_id is distinct from
         prior_identifier
       or not exists (
         select 1
         from production_control.google_writer_provider_fences fence
         where fence.fence_id =
             activation.active_google_writer_provider_fence_id
           and fence.status = 'INSTALLED'
           and fence.active_verification_id =
             activation.active_google_writer_provider_verification_id
           and fence.quiesce_evidence_id = prior_identifier
           and fence.candidate_deployment_id =
             input->>'candidate_deployment_id'
           and fence.candidate_deployment_commit =
             pg_catalog.lower(input->>'candidate_deployment_commit')
       )
       or gate.google_writer_provider_fence_id is distinct from
         activation.active_google_writer_provider_fence_id
       or gate.google_writer_provider_verification_id is distinct from
         activation.active_google_writer_provider_verification_id
       or not (
         (
           activation.state in ('GOOGLE_LEASE_ARMED', 'CUTOVER_PREPARED')
           and activation.read_cutover_phase = 'CURRENT_READS'
           and activation.current_authority = 'GOOGLE'
           and not activation.scoring_ingress_enabled
           and activation.first_supabase_write_possible_at is null
           and activation.first_supabase_write_observed_at is null
           and resource.scoring_authority = 'GOOGLE'
           and resource.participant_identity_authority = 'SUPABASE'
           and resource.current_tournament_read_authority = 'SUPABASE'
           and resource.public_supabase_reads_enabled
           and resource.auth_user_creation_enabled
           and not resource.scoring_ingress_enabled
           and not resource.workers_enabled
           and gate.authority = 'GOOGLE'
           and gate.admission_protocol_enforced
           and (
             (activation.state = 'GOOGLE_LEASE_ARMED'
               and gate.state = 'OPEN' and gate.admission_state = 'OPEN'
               and gate.active_closure_id is null)
             or (gate.state = 'PAUSED'
               and gate.admission_state in ('CLOSING', 'CLOSED')
               and exists (
                 select 1
                 from production_control.scoring_admission_closures closure
                 where closure.closure_id = gate.active_closure_id
                   and closure.closure_kind = 'LEGACY_ADMISSION'
                   and closure.authority = 'GOOGLE'
                   and closure.status in ('CLOSING', 'CLOSED')
               ))
           )
         )
         or (
           activation.state in ('SCORING_COMMITTED', 'ROLLBACK_PREPARED')
           and activation.read_cutover_phase = 'CURRENT_READS'
           and activation.current_authority = 'SUPABASE'
           and activation.scoring_ingress_enabled
           and activation.first_supabase_write_possible_at is not null
           and resource.scoring_authority = 'SUPABASE'
           and resource.participant_identity_authority = 'SUPABASE'
           and resource.current_tournament_read_authority = 'SUPABASE'
           and resource.public_supabase_reads_enabled
           and resource.auth_user_creation_enabled
           and resource.scoring_ingress_enabled
           and gate.authority = 'SUPABASE'
           and gate.admission_state = 'CLOSED'
           and gate.admission_protocol_enforced
           and (
             (activation.state = 'SCORING_COMMITTED'
               and gate.state = 'OPEN'
               and exists (
                 select 1
                 from production_control.scoring_admission_closures closure
                 where closure.closure_id = gate.active_closure_id
                   and closure.closure_kind = 'LEGACY_ADMISSION'
                   and closure.authority = 'GOOGLE'
                   and closure.status = 'CONSUMED'
               ))
             or (gate.state = 'PAUSED'
               and exists (
                 select 1
                 from production_control.scoring_admission_closures closure
                 where closure.closure_id = gate.active_closure_id
                   and closure.closure_kind = 'SUPABASE_INGRESS'
                   and closure.authority = 'SUPABASE'
                   and closure.status in ('CLOSING', 'CLOSED')
               ))
           )
         )
         or (
           activation.state in ('DORMANT', 'ROLLED_BACK')
           and activation.current_authority = 'GOOGLE'
           and not activation.scoring_ingress_enabled
           and activation.active_transition_epoch_id is null
           and resource.scoring_authority = 'GOOGLE'
           and resource.participant_identity_authority = 'PASSPORT'
           and resource.current_tournament_read_authority = 'GOOGLE'
           and not resource.public_supabase_reads_enabled
           and not resource.auth_user_creation_enabled
           and not resource.scoring_ingress_enabled
           and not resource.workers_enabled
           and gate.state = 'PAUSED'
           and gate.authority = 'GOOGLE'
           and gate.admission_state = 'OPEN'
           and not gate.admission_protocol_enforced
           and gate.active_closure_id is null
           and gate.external_fence_evidence_id is null
         )
       )
     )) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_START_STATE_INVALID';
  end if;

  insert into production_control.vercel_writer_quiesce_evidence (
    evidence_id, prior_evidence_id, evidence_request_id,
    begin_request_fingerprint, begin_payload_hash, purpose, vercel_project_id,
    routing_rule_id, routing_rule_revision, routing_rule_scope,
    candidate_deployment_id, candidate_deployment_commit,
    candidate_deployment_target, candidate_credential_generation,
    main_branch_alias_origin,
    candidate_alias_origin, candidate_immutable_origin,
    origin_inventory, origin_inventory_count, origin_inventory_fingerprint,
    live_origin_inventory, live_origin_inventory_count,
    live_origin_inventory_fingerprint,
    first_probe_records, first_probe_fingerprint, probe_scope_fingerprint,
    credential_generation_fingerprint,
    provider_inventory_schema,
    retained_provider_inventory_count, retained_provider_inventory_fingerprint,
    live_provider_inventory_count, live_provider_inventory_fingerprint,
    routing_rule_all_method_fence_required_host_count,
    routing_rule_all_method_fence_required_hosts_fingerprint,
    routing_rule_all_method_fence_required_path_count,
    routing_rule_all_method_fence_required_paths_fingerprint,
    credential_confinement_evidence_schema,
    credential_confinement_record_count,
    credential_confinement_records_fingerprint,
    credential_confinement_evidence_fingerprint,
    authenticated_actor_fingerprint,
    owner_principal_fingerprint, owner_override_operationally_frozen,
    owner_acknowledged_at, owner_freeze_expires_at, actor_id
  ) values (
    evidence_identifier, prior_identifier, request_identifier,
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash,
    purpose_value,
    input->>'vercel_project_id', input->>'routing_rule_id',
    input->>'routing_rule_revision', input->>'routing_rule_scope',
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    input->>'candidate_deployment_target',
    input->>'candidate_credential_generation',
    pg_catalog.lower(input->>'main_branch_alias_origin'),
    pg_catalog.lower(input->>'candidate_alias_origin'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    normalized_inventory, pg_catalog.jsonb_array_length(normalized_inventory),
    production_control.vercel_origin_inventory_fingerprint(normalized_inventory),
    normalized_live_inventory,
    pg_catalog.jsonb_array_length(normalized_live_inventory),
    production_control.vercel_origin_inventory_fingerprint(
      normalized_live_inventory
    ),
    normalized_probes,
    production_control.structured_evidence_fingerprint(normalized_probes),
    probe_scope_fingerprint,
    production_control.structured_evidence_fingerprint(
      pg_catalog.jsonb_build_object(
        'origin_inventory_fingerprint',
          production_control.vercel_origin_inventory_fingerprint(
            normalized_inventory
          ),
        'live_origin_inventory_fingerprint',
          production_control.vercel_origin_inventory_fingerprint(
            normalized_live_inventory
          ),
        'provider_inventory_schema', input->>'provider_inventory_schema',
        'retained_provider_inventory_fingerprint',
          input->>'retained_provider_inventory_fingerprint',
        'live_provider_inventory_fingerprint',
          input->>'live_provider_inventory_fingerprint',
        'routing_rule_all_method_fence_required_host_count',
          input->'routing_rule_all_method_fence_required_host_count',
        'routing_rule_all_method_fence_required_hosts_fingerprint',
          input->>'routing_rule_all_method_fence_required_hosts_fingerprint',
        'routing_rule_all_method_fence_required_path_count',
          input->'routing_rule_all_method_fence_required_path_count',
        'routing_rule_all_method_fence_required_paths_fingerprint',
          input->>'routing_rule_all_method_fence_required_paths_fingerprint',
        'production_target_capabilities',
          '["LEGACY_GOOGLE_SERVICE_ACCOUNT_V0","PRODUCTION_WORKBOOK_SELECTOR"]'::jsonb,
        'project_preview_capabilities',
          '["LEGACY_GOOGLE_SERVICE_ACCOUNT_V0","POTENTIAL_DEDICATED_PRODUCTION_GOOGLE_SERVICE_ACCOUNT_V1","POTENTIAL_PRODUCTION_WORKBOOK_SELECTOR"]'::jsonb,
        'candidate_credential_generation',
          input->>'candidate_credential_generation'
      )
    ),
    input->>'provider_inventory_schema',
    (input->>'retained_provider_inventory_count')::integer,
    input->>'retained_provider_inventory_fingerprint',
    (input->>'live_provider_inventory_count')::integer,
    input->>'live_provider_inventory_fingerprint',
    (input->>'routing_rule_all_method_fence_required_host_count')::integer,
    input->>'routing_rule_all_method_fence_required_hosts_fingerprint',
    (input->>'routing_rule_all_method_fence_required_path_count')::integer,
    input->>'routing_rule_all_method_fence_required_paths_fingerprint',
    input->>'credential_confinement_evidence_schema',
    (input->>'credential_confinement_record_count')::integer,
    input->>'credential_confinement_records_fingerprint',
    input->>'credential_confinement_evidence_fingerprint',
    pg_catalog.lower(input->>'authenticated_actor_fingerprint'),
    pg_catalog.lower(input->>'owner_principal_fingerprint'), true,
    owner_acknowledged, owner_freeze_expires,
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into evidence;

  provider_attestation :=
    production_control.record_verified_vercel_provider_attestation(
      evidence.evidence_id, 'BEGIN', evidence.begin_request_fingerprint,
      input->'provider_attestation'
    );

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_VERCEL_WRITER_QUIESCE_DRAIN_STARTED',
    'SCORING_AUTHORITY', '2026', evidence.actor_id,
    evidence.begin_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'evidence_id', evidence.evidence_id,
      'purpose', evidence.purpose,
      'candidate_deployment_id', evidence.candidate_deployment_id,
      'candidate_deployment_commit', evidence.candidate_deployment_commit,
      'routing_rule_id', evidence.routing_rule_id,
      'routing_rule_revision', evidence.routing_rule_revision,
      'provider_attestation_id', provider_attestation.attestation_id,
      'provider_attestation_fingerprint',
        provider_attestation.attestation_fingerprint,
      'provider_attestation_signer_key_fingerprint',
        provider_attestation.signer_key_fingerprint,
      'provider_attestation_signer_key_version',
        provider_attestation.signer_key_version,
      'vercel_team_id', provider_attestation.vercel_team_id,
      'live_origin_inventory_count',
        provider_attestation.live_origin_inventory_count,
      'live_origin_inventory_fingerprint',
        provider_attestation.live_origin_inventory_fingerprint,
      'redacted_environment_scope_fingerprint',
        provider_attestation.redacted_environment_scope_fingerprint,
      'origin_inventory_count', evidence.origin_inventory_count,
      'origin_inventory_fingerprint', evidence.origin_inventory_fingerprint,
      'provider_inventory_schema', evidence.provider_inventory_schema,
      'retained_provider_inventory_fingerprint',
        evidence.retained_provider_inventory_fingerprint,
      'live_provider_inventory_fingerprint',
        evidence.live_provider_inventory_fingerprint,
      'first_probe_fingerprint', evidence.first_probe_fingerprint,
      'drain_started_at', evidence.drain_started_at
    )
  );
  return production_control.vercel_quiesce_response(evidence, false);
end;
$_$;


ALTER FUNCTION public.begin_vercel_writer_quiesce_v4_candidate_base(input jsonb) OWNER TO postgres;

--
-- Name: bind_production_google_writer_provider_fence_rollback_waf_epoch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bind_production_google_writer_provider_fence_rollback_waf_epoch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  prior_epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  install_dispatch
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  bind_request uuid;
  payload_hash_value text := production_control.cutover_payload_hash(input);
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'operation' is distinct from
       'BIND_PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ROLLBACK_WAF_EPOCH'
     or coalesce(input->>'fence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'critical_waf_epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'quiesce_evidence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'bind_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_ROLLBACK_WAF_BIND_INPUT_INVALID';
  end if;
  bind_request := (input->>'bind_request_id')::uuid;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = (input->>'fence_id')::uuid
  for update;
  select * into strict epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = (input->>'critical_waf_epoch_id')::uuid
  for update;
  if epoch.status = 'FENCE_BOUND' then
    if epoch.transition_mode is distinct from 'ROLLBACK'
       or epoch.bound_fence_id is distinct from fence.fence_id
       or epoch.bound_quiesce_evidence_id is distinct from
         (input->>'quiesce_evidence_id')::uuid
       or epoch.fence_bind_request_id is distinct from bind_request
       or epoch.fence_bind_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or epoch.fence_bind_payload_hash is distinct from payload_hash_value
       or fence.critical_waf_epoch_id is distinct from epoch.epoch_id
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_ROLLBACK_WAF_BIND_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.google_writer_provider_fence_response(
      fence, true
    ) || production_control.vercel_writer_critical_waf_epoch_response(
      epoch, true
    );
  end if;
  select * into strict prior_epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = fence.critical_waf_epoch_id
  for update;
  select * into strict quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = (input->>'quiesce_evidence_id')::uuid
  for update;
  select * into strict observation
  from production_control.vercel_writer_critical_waf_observations value
  where value.observation_id = quiesce.critical_waf_observation_id
    and value.epoch_id = epoch.epoch_id;
  select * into strict install_dispatch
  from production_control.google_writer_provider_fence_install_dispatches value
  where value.fence_id = fence.fence_id
    and value.outcome_status = 'TARGET_CONFIRMED'
  order by value.attempt desc
  limit 1
  for update;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = gate.active_closure_id
  for update;

  if fence.lifecycle_mode is distinct from 'CUTOVER'
     or fence.status is distinct from 'INSTALLED'
     or fence.active_verification_id is null
     or fence.acl_reader_confirmed_at is null
     or fence.acl_writer_restored_at is not null
     or install_dispatch.transition_proof->>'currentRole' is distinct from
       'reader'
     or install_dispatch.transition_proof->'currentLegacyCanEdit'
       is distinct from 'false'::jsonb
     or install_dispatch.transition_proof->'currentLegacyCanShare'
       is distinct from 'false'::jsonb
     or prior_epoch.status is distinct from 'BASELINE_RESTORED'
     or prior_epoch.bound_fence_id is distinct from fence.fence_id
     or fence.baseline_waf_restored_observation_id is distinct from
       prior_epoch.baseline_restored_observation_id
     or epoch.status is distinct from 'ACTIVE_UNBOUND'
     or epoch.purpose is distinct from 'CUTOVER'
     or epoch.transition_mode is distinct from 'ROLLBACK'
     or epoch.candidate_deployment_target is distinct from 'PREVIEW'
     or epoch.candidate_deployment_id is distinct from
       fence.candidate_deployment_id
     or epoch.candidate_deployment_commit is distinct from
       fence.candidate_deployment_commit
     or epoch.actor_id is distinct from fence.actor_id
     or epoch.authenticated_actor_fingerprint is distinct from
       fence.authenticated_actor_fingerprint
     or epoch.actor_id is distinct from input->>'actor_id'
     or epoch.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
     or epoch.critical_active_observation_id is distinct from
       observation.observation_id
     or observation.evidence_stage is distinct from 'CRITICAL_ACTIVE'
     or observation.expires_at <= pg_catalog.clock_timestamp()
     or quiesce.status is distinct from 'VERIFIED'
     or quiesce.purpose is distinct from 'CUTOVER'
     or quiesce.critical_waf_epoch_id is distinct from epoch.epoch_id
     or quiesce.critical_waf_quiesce_stage is distinct from 'INSTALL'
     or quiesce.candidate_deployment_id is distinct from
       epoch.candidate_deployment_id
     or quiesce.candidate_deployment_commit is distinct from
       epoch.candidate_deployment_commit
     or quiesce.expires_at <= pg_catalog.clock_timestamp()
     or quiesce.owner_freeze_expires_at <= pg_catalog.clock_timestamp()
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or activation.state is distinct from 'ROLLED_BACK'
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.active_transition_epoch_id is not null
     or activation.active_google_writer_provider_fence_id is distinct from
       fence.fence_id
     or resource.scoring_authority is distinct from 'GOOGLE'
     or resource.scoring_ingress_enabled
     or resource.participant_identity_authority is distinct from 'PASSPORT'
     or resource.current_tournament_read_authority is distinct from 'GOOGLE'
     or gate.state is distinct from 'PAUSED'
     or gate.authority is distinct from 'GOOGLE'
     or gate.admission_state is distinct from 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.google_writer_provider_fence_id is distinct from fence.fence_id
     or gate.active_closure_id is distinct from closure.closure_id
     or closure.status is distinct from 'CLOSED'
     or closure.authority is distinct from 'GOOGLE'
     or closure.reconciliation_fingerprint !~ '^[0-9a-f]{64}$'
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
     or exists (
       select 1 from scoring_authority.authority_epochs value
       where value.tournament_id = '2026' and value.status = 'PREPARED'
     )
     or exists (
       select 1 from scoring_authority.google_outbox_events value
       where value.tournament_id = '2026' and value.status <> 'DELIVERED'
     )
     or exists (
       select 1 from scoring_authority.scorecard_archive_jobs value
       where value.tournament_id = '2026'
         and value.status not in ('VERIFIED', 'SUPERSEDED')
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_ROLLBACK_WAF_BIND_NOT_SAFE';
  end if;

  update production_control.vercel_writer_critical_waf_epochs
  set status = 'FENCE_BOUND',
      bound_fence_id = fence.fence_id,
      bound_quiesce_evidence_id = quiesce.evidence_id,
      fence_bind_request_id = bind_request,
      fence_bind_request_fingerprint =
        pg_catalog.lower(input->>'request_fingerprint'),
      fence_bind_payload_hash = payload_hash_value,
      fence_bound_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp()
  where epoch_id = epoch.epoch_id
    and status = 'ACTIVE_UNBOUND'
    and bound_fence_id is null
    and bound_quiesce_evidence_id is null
  returning * into epoch;
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_ROLLBACK_WAF_BIND_RACE';
  end if;
  update production_control.google_writer_provider_fences
  set critical_waf_epoch_id = epoch.epoch_id,
      global_writer_stop_active_at = epoch.critical_active_at,
      restore_quiesce_evidence_id = null,
      restore_global_writer_stop_active_at = null,
      baseline_waf_restored_observation_id = null,
      updated_at = pg_catalog.clock_timestamp()
  where fence_id = fence.fence_id
    and status = 'INSTALLED'
  returning * into fence;
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_ROLLBACK_WAF_FENCE_BIND_RACE';
  end if;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result,
    details
  ) values (
    'PRODUCTION_GOOGLE_WRITER_ROLLBACK_CRITICAL_WAF_BOUND',
    'SCORING_AUTHORITY', '2026', fence.actor_id,
    epoch.fence_bind_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'fence_id', fence.fence_id,
      'critical_waf_epoch_id', epoch.epoch_id,
      'prior_critical_waf_epoch_id', prior_epoch.epoch_id,
      'quiesce_evidence_id', quiesce.evidence_id,
      'critical_active_at', epoch.critical_active_at,
      'admission_state', gate.admission_state,
      'admission_reservation_active', true
    )
  );
  return production_control.google_writer_provider_fence_response(
    fence, false
  ) || production_control.vercel_writer_critical_waf_epoch_response(
    epoch, false
  );
end;
$_$;


ALTER FUNCTION public.bind_production_google_writer_provider_fence_rollback_waf_epoch(input jsonb) OWNER TO postgres;

--
-- Name: bootstrap_import_production_current_tournament_shadow(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bootstrap_import_production_current_tournament_shadow(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  claim_result jsonb;
  claim_id_value text;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_SERVICE_ROLE_REQUIRED';
  end if;
  -- Claim and import share one database transaction. A failed import rolls
  -- back the claim, so the approved bootstrap cannot expire between calls or
  -- be stranded by a transport interruption. A successful claim is consumed
  -- once; exact repeats return the existing certified import.
  claim_result := public.claim_production_current_tournament_shadow_import(input);
  claim_id_value := btrim(coalesce(claim_result->>'claim_id',''));
  if claim_id_value = '' then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_CLAIM_REQUIRED';
  end if;
  return public.import_production_current_tournament_shadow(
    input || jsonb_build_object('claim_id', claim_id_value)
  );
end;
$$;


ALTER FUNCTION public.bootstrap_import_production_current_tournament_shadow(input jsonb) OWNER TO postgres;

--
-- Name: bootstrap_production_odds_input_configuration(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bootstrap_production_odds_input_configuration(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  claim production_control.odds_input_bootstrap_claims%rowtype;
  config scoring_authority.odds_input_configurations%rowtype;
  request_text text := coalesce(input->>'request_canonical_json','');
  source_text text := coalesce(input->>'source_canonical_json','');
  payload_text text := coalesce(input->>'payload_canonical_json','');
  settings_text text := coalesce(input->>'settings_canonical_json','');
  effective_settings_text text := coalesce(input->>'effective_settings_canonical_json','');
  ratings_text text := coalesce(input->>'ratings_canonical_json','');
  pairing_text text := coalesce(input->>'pairing_canonical_json','');
  bundle_text text := coalesce(input->>'bundle_canonical_json','');
  request_value jsonb;
  source_value jsonb;
  payload_value jsonb;
  settings_value jsonb;
  effective_settings_value jsonb;
  ratings_value jsonb;
  pairing_value jsonb;
  bundle_value jsonb;
  expected_request jsonb;
  expected_bundle jsonb;
  database_pairing jsonb;
  request_fingerprint_value text := lower(btrim(coalesce(input->>'request_fingerprint','')));
  source_fingerprint_value text := lower(btrim(coalesce(input->>'source_fingerprint','')));
  payload_fingerprint_value text := lower(btrim(coalesce(input->>'payload_fingerprint','')));
  bundle_fingerprint_value text := lower(btrim(coalesce(input#>>'{payload,bundle_fingerprint}','')));
  settings_fingerprint_value text := lower(btrim(coalesce(input#>>'{payload,settings_fingerprint}','')));
  effective_settings_fingerprint_value text := lower(btrim(coalesce(input#>>'{payload,effective_settings_fingerprint}','')));
  ratings_fingerprint_value text := lower(btrim(coalesce(input#>>'{payload,ratings_fingerprint}','')));
  pairing_fingerprint_value text := lower(btrim(coalesce(input#>>'{payload,pairing_fingerprint}','')));
  pre_calculation_job_count bigint;
  pre_published_snapshot_count bigint;
  pre_mirror_job_count bigint;
  pre_active_worker_flag_count bigint;
begin
  scope := production_control.assert_current_shadow_v2_dormant();
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ODDS_INPUT_BOOTSTRAP_SERVICE_ROLE_REQUIRED';
  end if;
  select count(*) into pre_calculation_job_count
  from scoring_authority.odds_calculation_jobs;
  select count(*) into pre_published_snapshot_count
  from scoring_authority.odds_published_snapshots;
  select count(*) into pre_mirror_job_count
  from scoring_authority.odds_google_mirror_jobs;
  select count(*) into pre_active_worker_flag_count
  from production_control.worker_controls
  where enabled or scheduler_installed or google_writes_allowed;
  if upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref','')) <> scope.project_ref
     or btrim(coalesce(input->>'project_url','')) <> scope.project_url
     or btrim(coalesce(input->>'source_workbook_id','')) <> scope.google_workbook_id
     or btrim(coalesce(input->>'tournament_id','')) <> '2026'
     or coalesce((input->>'tournament_year')::integer,0) <> 2026
     or upper(btrim(coalesce(input->>'operation',''))) <> 'ODDS_INPUT_CONFIGURATION_BOOTSTRAP'
     or btrim(coalesce(input->>'actor_id','')) <> 'step10b-production-shadow-bootstrap'
     or btrim(coalesce(input->>'bootstrap_contract_version','')) <> 'production-odds-input-bootstrap-v1'
     or request_fingerprint_value !~ '^[0-9a-f]{64}$'
     or source_fingerprint_value !~ '^[0-9a-f]{64}$'
     or payload_fingerprint_value !~ '^[0-9a-f]{64}$'
     or bundle_fingerprint_value !~ '^[0-9a-f]{64}$'
     or settings_fingerprint_value !~ '^[0-9a-f]{64}$'
     or effective_settings_fingerprint_value !~ '^[0-9a-f]{64}$'
     or ratings_fingerprint_value !~ '^[0-9a-f]{64}$'
     or pairing_fingerprint_value !~ '^[0-9a-f]{64}$'
     or btrim(request_text) = '' or btrim(source_text) = ''
     or btrim(payload_text) = '' or btrim(settings_text) = ''
     or btrim(effective_settings_text) = '' or btrim(ratings_text) = ''
     or btrim(pairing_text) = '' or btrim(bundle_text) = '' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_ODDS_INPUT_BOOTSTRAP_SCOPE_REQUIRED';
  end if;

  begin
    request_value := request_text::jsonb;
    source_value := source_text::jsonb;
    payload_value := payload_text::jsonb;
    settings_value := settings_text::jsonb;
    effective_settings_value := effective_settings_text::jsonb;
    ratings_value := ratings_text::jsonb;
    pairing_value := pairing_text::jsonb;
    bundle_value := bundle_text::jsonb;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_INPUT_CANONICAL_EVIDENCE_INVALID';
  end;

  expected_request := jsonb_build_object(
    'actor_id','step10b-production-shadow-bootstrap',
    'bootstrap_contract_version','production-odds-input-bootstrap-v1',
    'environment','PRODUCTION',
    'operation','ODDS_INPUT_CONFIGURATION_BOOTSTRAP',
    'payload_fingerprint',payload_fingerprint_value,
    'project_ref',scope.project_ref,
    'project_url',scope.project_url,
    'source_fingerprint',source_fingerprint_value,
    'source_workbook_id',scope.google_workbook_id,
    'tournament_id','2026',
    'tournament_year',2026
  );
  expected_bundle := jsonb_build_object(
    'configuration_revision',1,
    'effective_settings_fingerprint',effective_settings_fingerprint_value,
    'pairing_fingerprint',pairing_fingerprint_value,
    'ratings_contract_version','sandbagger-ratings-existing-engine-v1',
    'ratings_fingerprint',ratings_fingerprint_value,
    'settings_fingerprint',settings_fingerprint_value,
    'source_fingerprint',source_fingerprint_value,
    'tournament_id','2026'
  );

  if request_value is distinct from expected_request
     or source_value is distinct from input->'source_evidence'
     or payload_value is distinct from input->'payload'
     or settings_value is distinct from input#>'{payload,settings}'
     or effective_settings_value is distinct from input#>'{payload,effective_settings}'
     or ratings_value is distinct from input#>'{payload,historical_ratings}'
     or pairing_value is distinct from input#>'{source_evidence,current_pairing_sequence}'
     or bundle_value is distinct from expected_bundle
     or encode(extensions.digest(request_text,'sha256'),'hex') <> request_fingerprint_value
     or encode(extensions.digest(source_text,'sha256'),'hex') <> source_fingerprint_value
     or encode(extensions.digest(payload_text,'sha256'),'hex') <> payload_fingerprint_value
     or encode(extensions.digest(settings_text,'sha256'),'hex') <> settings_fingerprint_value
     or encode(extensions.digest(effective_settings_text,'sha256'),'hex') <> effective_settings_fingerprint_value
     or encode(extensions.digest(ratings_text,'sha256'),'hex') <> ratings_fingerprint_value
     or encode(extensions.digest(pairing_text,'sha256'),'hex') <> pairing_fingerprint_value
     or encode(extensions.digest(bundle_text,'sha256'),'hex') <> bundle_fingerprint_value then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_INPUT_CANONICAL_EVIDENCE_MISMATCH';
  end if;

  if jsonb_typeof(payload_value->'settings') <> 'array'
     or jsonb_array_length(payload_value->'settings') < 30
     or jsonb_typeof(payload_value->'canonical_settings') <> 'object'
     or scoring_authority.jsonb_object_length(payload_value->'canonical_settings') <> 30
     or jsonb_typeof(payload_value->'effective_settings') <> 'object'
     or scoring_authority.jsonb_object_length(payload_value->'effective_settings') <> 30
     or jsonb_typeof(payload_value->'historical_ratings') <> 'object'
     or scoring_authority.jsonb_object_length(payload_value->'historical_ratings') <> 41
     or payload_value->>'settings_contract_version' <> 'prediction-settings-v1'
     or payload_value->>'ratings_contract_version' <> 'sandbagger-ratings-existing-engine-v1'
     or payload_value->>'pairing_contract_version' <> 'production-current-pairing-sequence-v1'
     or payload_value->>'validation_status' <> 'VALID'
     or source_value->>'source_workbook_id' <> scope.google_workbook_id
     or jsonb_typeof(source_value->'completed_history') <> 'array'
     or jsonb_array_length(source_value->'completed_history') <> 9
     or jsonb_typeof(source_value->'current_tournament') <> 'object'
     or jsonb_typeof(source_value->'prediction_settings') <> 'object'
     or jsonb_typeof(source_value->'player_editorial') <> 'object'
     or jsonb_typeof(source_value->'ratings_engine') <> 'object'
     or source_value#>>'{ratings_engine,contract_version}' <> 'sandbagger-ratings-existing-engine-v1'
     or lower(btrim(coalesce(source_value#>>'{ratings_engine,source_sha256}',''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(source_value#>>'{ratings_engine,canonical_history_fingerprint}',''))) !~ '^[0-9a-f]{64}$'
     or coalesce((source_value#>>'{ratings_engine,start_rating}')::integer,0) <> 1500
     or coalesce((source_value#>>'{ratings_engine,k_factor}')::integer,0) <> 24
     or source_value#>'{ratings_engine,categories}' <> '[
       {"id":"OVERALL","format":null},
       {"id":"BB","format":"BB"},
       {"id":"SC","format":"SC"},
       {"id":"SI","format":"SI"}
     ]'::jsonb
     or source_value#>>'{current_tournament,import_contract_version}' <> 'production-current-shadow-v2'
     or source_value#>>'{prediction_settings,contract_version}' <> 'prediction-settings-v1'
     or source_value#>>'{player_editorial,contract_version}' <> 'player-public-profile-v1' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_INPUT_COMPLETE_CONTRACT_REQUIRED';
  end if;

  if (select jsonb_agg((value->>'year')::integer order by ordinal)
      from jsonb_array_elements(source_value->'completed_history') with ordinality history(value,ordinal))
      <> '[2017,2018,2019,2020,2021,2022,2023,2024,2025]'::jsonb
     or exists (
       select 1
       from jsonb_array_elements(source_value->'completed_history') evidence
       where not exists (
         select 1
         from scoring_authority.completed_history_current_revisions pointer
         join scoring_authority.completed_history_revisions revision
           on revision.revision_id = pointer.revision_id
         where pointer.tournament_year = (evidence->>'year')::integer
           and pointer.tournament_id = evidence->>'year'
           and pointer.project_ref = scope.project_ref
           and pointer.source_workbook_id = scope.google_workbook_id
           and revision.source_fingerprint = lower(evidence->>'source_fingerprint')
           and revision.payload_fingerprint = lower(evidence->>'payload_fingerprint')
           and revision.correction_set_version = evidence->>'correction_registry_version'
       )
     ) then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_INPUT_HISTORY_REVISION_MISMATCH';
  end if;

  if not exists (
    select 1
    from production_control.current_shadow_revisions revision
    where revision.tournament_id = '2026'
      and revision.source_workbook_id = scope.google_workbook_id
      and revision.source_fingerprint = source_value#>>'{current_tournament,source_fingerprint}'
      and revision.payload_fingerprint = source_value#>>'{current_tournament,payload_fingerprint}'
  ) then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_INPUT_CURRENT_REVISION_MISMATCH';
  end if;
  if not exists (
    select 1
    from production_control.projection_current pointer
    join production_control.projection_revisions revision
      on revision.revision_id = pointer.revision_id
    where pointer.domain = 'PLAYER_EDITORIAL'
      and pointer.tournament_id = '2026'
      and revision.source_fingerprint = source_value#>>'{player_editorial,source_fingerprint}'
      and revision.payload_fingerprint = source_value#>>'{player_editorial,payload_fingerprint}'
      and revision.source_workbook_id = scope.google_workbook_id
  ) then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_INPUT_PLAYER_PROJECTION_MISMATCH';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'match_id', match.match_id,
    'round_number', match.round_number,
    'format', upper(match.format),
    'status', upper(match.status),
    'course_id', snapshot.course_id,
    'tee', snapshot.tee,
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'player_id', participant.player_id,
        'team_side', participant.team_side,
        'player_slot', participant.player_slot
      ) order by participant.team_side, participant.player_slot, participant.player_id)
      from scoring_authority.match_participants participant
      where participant.match_id = match.match_id
    ), '[]'::jsonb)
  ) order by match.round_number, match.match_id), '[]'::jsonb)
  into database_pairing
  from scoring_authority.matches match
  join scoring_authority.scoring_snapshots snapshot
    on snapshot.snapshot_id = match.scoring_snapshot_id
  where match.tournament_id = '2026';
  if database_pairing is distinct from pairing_value
     or jsonb_array_length(database_pairing) <> 24 then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_INPUT_PAIRING_REVISION_MISMATCH';
  end if;

  if exists (
    select 1 from jsonb_object_keys(ratings_value) as rating_key(player_id)
    where not exists (
      select 1 from scoring_authority.players player
      where player.player_id = rating_key.player_id
    )
  ) or exists (
    select 1 from scoring_authority.players player
    where not ratings_value ? player.player_id
  ) then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_INPUT_RATINGS_IDENTITY_MISMATCH';
  end if;

  perform pg_advisory_xact_lock(hashtext('step10b-production-odds-input-bootstrap'));
  select * into claim
  from production_control.odds_input_bootstrap_claims value
  where value.bootstrap_key = 'STEP10B_PRODUCTION_ODDS_INPUT_V1'
  for update;
  if claim.bootstrap_key is not null then
    if claim.operation <> 'ODDS_INPUT_CONFIGURATION_BOOTSTRAP'
       or claim.actor <> 'step10b-production-shadow-bootstrap'
       or claim.bootstrap_contract <> 'production-odds-input-bootstrap-v1'
       or claim.request_fingerprint <> request_fingerprint_value
       or claim.source_fingerprint <> source_fingerprint_value
       or claim.payload_fingerprint <> payload_fingerprint_value
       or claim.bundle_fingerprint <> bundle_fingerprint_value then
      raise exception using errcode = '42501',
        message = 'PRODUCTION_ODDS_INPUT_BOOTSTRAP_ALREADY_USED';
    end if;
    select * into strict config
    from scoring_authority.odds_input_configurations value
    where value.id = claim.configuration_id;
    if config.bundle_fingerprint <> bundle_fingerprint_value then
      raise exception using errcode = '23514',
        message = 'PRODUCTION_ODDS_INPUT_BOOTSTRAP_STATE_DIVERGED';
    end if;
    return jsonb_build_object(
      'ok',true,'changed',false,'duplicate',true,
      'configuration_id',config.id,'configuration_revision',config.configuration_revision,
      'bundle_fingerprint',config.bundle_fingerprint,
      'settings_fingerprint',config.settings_fingerprint,
      'effective_settings_fingerprint',config.effective_settings_fingerprint,
      'ratings_fingerprint',config.ratings_fingerprint,
      'pairing_fingerprint',config.pairing_fingerprint,
      'superseded',not config.is_current,
      'shadow_only',true,'calculation_performed',false,'publication_created',false,
      'google_write',false,'worker_enabled',false,'authority_changed',false
    );
  end if;

  if exists (select 1 from scoring_authority.odds_input_configurations)
     or exists (select 1 from scoring_authority.odds_input_import_runs) then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_INPUT_BOOTSTRAP_EMPTY_STATE_REQUIRED';
  end if;

  insert into scoring_authority.odds_input_configurations(
    tournament_id,configuration_revision,source_workbook_id,settings,historical_ratings,
    settings_fingerprint,ratings_fingerprint,pairing_fingerprint,bundle_fingerprint,is_current,
    imported_by,source_tab,source_fingerprint,canonical_settings,effective_settings,
    effective_settings_fingerprint,settings_contract_version,validation_status,
    validation_diagnostics,synchronized_at,previous_configuration_id
  ) values (
    '2026',1,scope.google_workbook_id,payload_value->'settings',payload_value->'historical_ratings',
    settings_fingerprint_value,ratings_fingerprint_value,pairing_fingerprint_value,
    bundle_fingerprint_value,true,'step10b-production-shadow-bootstrap','Prediction Settings',
    source_fingerprint_value,payload_value->'canonical_settings',payload_value->'effective_settings',
    effective_settings_fingerprint_value,'prediction-settings-v1','VALID',
    jsonb_build_object(
      'bootstrapContract','production-odds-input-bootstrap-v1',
      'ratingsContract','sandbagger-ratings-existing-engine-v1',
      'pairingContract','production-current-pairing-sequence-v1',
      'sourceEvidence',source_value,
      'payloadFingerprint',payload_fingerprint_value,
      'requestFingerprint',request_fingerprint_value,
      'shadowOnly',true,
      'calculationPerformed',false,
      'publicationCreated',false,
      'googleWrite',false,
      'authorityChanged',false
    ),now(),null
  ) returning * into config;

  insert into scoring_authority.odds_input_import_runs(
    tournament_id,bundle_fingerprint,status,requested_by
  ) values ('2026',bundle_fingerprint_value,'APPLIED','step10b-production-shadow-bootstrap');
  insert into production_control.odds_input_bootstrap_claims(
    bootstrap_key,tournament_id,operation,actor,bootstrap_contract,
    request_fingerprint,source_fingerprint,payload_fingerprint,bundle_fingerprint,
    configuration_id
  ) values (
    'STEP10B_PRODUCTION_ODDS_INPUT_V1','2026','ODDS_INPUT_CONFIGURATION_BOOTSTRAP',
    'step10b-production-shadow-bootstrap','production-odds-input-bootstrap-v1',
    request_fingerprint_value,source_fingerprint_value,payload_fingerprint_value,
    bundle_fingerprint_value,config.id
  );
  insert into production_control.operation_audit_events(
    event_type,domain,tournament_id,actor,request_fingerprint,result,details
  ) values (
    'PRODUCTION_ODDS_INPUT_BOOTSTRAPPED','ODDS_INPUT_CONFIGURATION','2026',
    'step10b-production-shadow-bootstrap',request_fingerprint_value,'SUCCEEDED',
    jsonb_build_object(
      'configurationId',config.id,'configurationRevision',1,
      'bundleFingerprint',bundle_fingerprint_value,
      'sourceFingerprint',source_fingerprint_value,
      'payloadFingerprint',payload_fingerprint_value,
      'settingsFingerprint',settings_fingerprint_value,
      'effectiveSettingsFingerprint',effective_settings_fingerprint_value,
      'ratingsFingerprint',ratings_fingerprint_value,
      'pairingFingerprint',pairing_fingerprint_value,
      'serviceRoleOnly',true,'singleUse',true,'shadowOnly',true,
      'calculationPerformed',false,'publicationCreated',false,
      'googleWrite',false,'workerEnabled',false,'authorityChanged',false
    )
  );

  if (select count(*) from scoring_authority.odds_calculation_jobs) <> pre_calculation_job_count
     or (select count(*) from scoring_authority.odds_published_snapshots) <> pre_published_snapshot_count
     or (select count(*) from scoring_authority.odds_google_mirror_jobs) <> pre_mirror_job_count
     or (select count(*) from production_control.worker_controls
         where enabled or scheduler_installed or google_writes_allowed) <> pre_active_worker_flag_count then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_ODDS_INPUT_BOOTSTRAP_CREATED_OPERATIONAL_WORK';
  end if;

  return jsonb_build_object(
    'ok',true,'changed',true,'duplicate',false,
    'configuration_id',config.id,'configuration_revision',config.configuration_revision,
    'bundle_fingerprint',config.bundle_fingerprint,
    'settings_fingerprint',config.settings_fingerprint,
    'effective_settings_fingerprint',config.effective_settings_fingerprint,
    'ratings_fingerprint',config.ratings_fingerprint,
    'pairing_fingerprint',config.pairing_fingerprint,
    'calculation_jobs_before_after',jsonb_build_array(
      pre_calculation_job_count,(select count(*) from scoring_authority.odds_calculation_jobs)),
    'published_snapshots_before_after',jsonb_build_array(
      pre_published_snapshot_count,(select count(*) from scoring_authority.odds_published_snapshots)),
    'mirror_jobs_before_after',jsonb_build_array(
      pre_mirror_job_count,(select count(*) from scoring_authority.odds_google_mirror_jobs)),
    'shadow_only',true,'calculation_performed',false,'publication_created',false,
    'google_write',false,'worker_enabled',false,'authority_changed',false
  );
end;
$_$;


ALTER FUNCTION public.bootstrap_production_odds_input_configuration(input jsonb) OWNER TO postgres;

--
-- Name: cancel_participant_phone_login(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_participant_phone_login(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'public', 'pg_temp'
    AS $$
declare target_attempt uuid := nullif(input->>'attempt_id', '')::uuid;
declare expected_auth_user uuid := nullif(input->>'auth_user_id', '')::uuid;
declare changed integer := 0;
begin
  if target_attempt is null or expected_auth_user is null then
    return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_CONTEXT_INVALID');
  end if;
  update participant_identity.participant_phone_otp_attempts set
    status = 'CANCELLED', safe_reason = 'PARTICIPANT_CHANGED_AUTH_METHOD', updated_at = now()
  where attempt_id = target_attempt and auth_user_id = expected_auth_user
    and status in ('REQUESTING', 'SENT');
  get diagnostics changed = row_count;
  return jsonb_build_object('ok', true, 'cancelled', changed = 1);
end;
$$;


ALTER FUNCTION public.cancel_participant_phone_login(input jsonb) OWNER TO postgres;

--
-- Name: certify_production_future_google_writer_target_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.certify_production_future_google_writer_target_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  resource production_control.future_tournament_resources_v1%rowtype;
  promotion production_control.future_runtime_promotions_v2%rowtype;
  writer production_control.future_google_writer_generations_v2%rowtype;
  target production_control.future_google_writer_targets_v2%rowtype;
  receipt production_control.future_google_writer_certification_receipts_v1%rowtype;
  target_id text := pg_catalog.btrim(coalesce(
    input->>'target_tournament_id', ''
  ));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  operation_id uuid;
  expected_resource_revision bigint;
  expected_setup_revision bigint;
  expected_promotion_revision bigint;
  implementation_fingerprint text;
  writer_generation_id_value uuid;
  resource_fingerprint text;
  target_fingerprint text;
  database_hash text;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash', ''
  )));
  result_value jsonb;
  changed_value boolean := true;
  attempts_before bigint;
  attempts_after bigint;
  jobs_bound integer;
  job record;
begin
  perform production_control.assert_future_runtime_service_scope_v2(
    input, true, true
  );
  if input->>'action'
       is distinct from 'CERTIFY_ANNUAL_GOOGLE_WRITER_TARGET'
     or input ?| array[
       'destination_workbook_id', 'annual_destination_workbook_id',
       'target_workbook_id', 'writer_destination_workbook_id'
     ] then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_INPUT_INVALID';
  end if;
  begin
    actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
    operation_id := (input->>'operation_request_id')::uuid;
    expected_resource_revision :=
      (input->>'expected_resource_revision')::bigint;
    expected_setup_revision :=
      (input->>'expected_setup_revision')::bigint;
    expected_promotion_revision :=
      (input->>'expected_promotion_revision')::bigint;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_INPUT_INVALID';
  end;
  if target_id !~ '^[0-9]{4}$' or target_id <= '2026'
     or expected_resource_revision <= 0 or expected_setup_revision <= 0
     or expected_promotion_revision <= 0 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_INPUT_INVALID';
  end if;
  perform production_control.assert_access_governance_safe_reason_v1(
    input->>'reason'
  );
  database_hash := production_control.future_runtime_hash_v2(
    input - 'request_payload_hash'
  );
  if declared_hash !~ '^[0-9a-f]{64}$'
     or declared_hash <> database_hash then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_HASH_INVALID';
  end if;
  select value.* into receipt
  from production_control.future_google_writer_certification_receipts_v1 value
  where value.action = 'CERTIFY_ANNUAL_GOOGLE_WRITER_TARGET'
    and value.operation_request_id = operation_id;
  if receipt.receipt_id is not null then
    if receipt.database_request_payload_hash <> database_hash
       or receipt.declared_request_payload_hash <> declared_hash then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_IDEMPOTENCY_CONFLICT';
    end if;
    return receipt.response || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'annual-google-writer-certification:' || target_id, 0
    )
  );
  select value.* into receipt
  from production_control.future_google_writer_certification_receipts_v1 value
  where value.action = 'CERTIFY_ANNUAL_GOOGLE_WRITER_TARGET'
    and value.operation_request_id = operation_id;
  if receipt.receipt_id is not null then
    if receipt.database_request_payload_hash <> database_hash
       or receipt.declared_request_payload_hash <> declared_hash then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_IDEMPOTENCY_CONFLICT';
    end if;
    return receipt.response || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;
  select value.* into strict scope
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = target_id
  for update;
  select value.* into strict resource
  from production_control.future_tournament_resources_v1 value
  where value.tournament_id = target_id
  for update;
  select value.* into strict promotion
  from production_control.future_runtime_promotions_v2 value
  where value.tournament_id = target_id
  for update;
  if pointer.tournament_id = target_id
     or catalog.lifecycle <> 'CONFIGURING'
     or catalog.setup_revision <> expected_setup_revision
     or resource.resource_revision <> expected_resource_revision
     or resource.resource_status <> 'CURRENT_RESOURCE_BOUND'
     or resource.source_workbook_id is distinct from scope.google_workbook_id
     or resource.google_compatibility_policy <> 'PROVISIONING_REQUIRED'
     or resource.project_ref is distinct from scope.project_ref
     or resource.project_url is distinct from scope.project_url
     or promotion.promotion_revision <> expected_promotion_revision
     or promotion.source_setup_revision <> expected_setup_revision
     or promotion.runtime_status <> 'PROMOTED'
     or exists (
       select 1
       from production_control.future_match_google_compatibility_jobs_v1 value
       where value.tournament_id = target_id
         and (value.status = 'PROCESSING' or value.claim_token is not null
           or value.claimed_by is not null or value.lease_expires_at is not null)
     ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_PREDECESSOR_INVALID';
  end if;
  implementation_fingerprint := production_control
    .future_google_writer_implementation_fingerprint_v2();
  writer_generation_id_value := production_control
    .future_google_writer_generation_id_v2(
      scope.google_workbook_id, implementation_fingerprint
    );
  resource_fingerprint := production_control
    .future_google_writer_resource_fingerprint_v1(target_id);
  target_fingerprint := production_control.future_runtime_hash_v2(
    pg_catalog.jsonb_build_object(
      'contractVersion',
        'production-annual-google-writer-certification-v1',
      'writerContractVersion',
        'production-future-google-match-provisioning-v2',
      'targetTournamentId', target_id,
      'tournamentYear', catalog.tournament_year,
      'setupRevision', catalog.setup_revision,
      'promotionRevision', promotion.promotion_revision,
      'promotedManifestFingerprint',
        promotion.promoted_manifest_fingerprint,
      'resourceRevision', resource.resource_revision,
      'resourceBindingFingerprint', resource_fingerprint,
      'writerGenerationId', writer_generation_id_value,
      'implementationFingerprint', implementation_fingerprint,
      'requiredArtifacts', pg_catalog.jsonb_build_array(
        'LIVE_MATCHES_ROW', 'MATCHES_ROW'
      ),
      'nonAuthoritative', true,
      'rollbackAllowed', false
    )
  );
  insert into production_control.future_google_writer_generations_v2 (
    writer_generation_id, contract_version, destination_workbook_id,
    implementation_fingerprint, certification_status
  ) values (
    writer_generation_id_value,
    'production-future-google-match-provisioning-v2',
    scope.google_workbook_id, implementation_fingerprint, 'CERTIFIED'
  ) on conflict (destination_workbook_id) where
    certification_status = 'CERTIFIED' do nothing;
  select value.* into strict writer
  from production_control.future_google_writer_generations_v2 value
  where value.destination_workbook_id = scope.google_workbook_id
    and value.certification_status = 'CERTIFIED';
  if writer.writer_generation_id is distinct from writer_generation_id_value
     or writer.contract_version is distinct from
       'production-future-google-match-provisioning-v2'
     or writer.implementation_fingerprint is distinct from
       implementation_fingerprint then
    raise exception using errcode = '23505',
      message = 'PRODUCTION_FUTURE_GOOGLE_WRITER_GENERATION_CONFLICT';
  end if;
  select value.* into target
  from production_control.future_google_writer_targets_v2 value
  where value.tournament_id = target_id;
  if target.tournament_id is null then
    insert into production_control.future_google_writer_targets_v2 (
      tournament_id, writer_generation_id, destination_workbook_id,
      target_contract_fingerprint, contract_status,
      certification_contract_version, resource_revision,
      promotion_revision, source_setup_revision,
      promoted_manifest_fingerprint, resource_binding_fingerprint
    ) values (
      target_id, writer_generation_id_value, scope.google_workbook_id,
      target_fingerprint, 'CERTIFIED',
      'production-annual-google-writer-certification-v1',
      resource.resource_revision, promotion.promotion_revision,
      promotion.source_setup_revision,
      promotion.promoted_manifest_fingerprint, resource_fingerprint
    );
  elsif target.writer_generation_id is distinct from writer_generation_id_value
     or target.destination_workbook_id is distinct from
       scope.google_workbook_id
     or target.target_contract_fingerprint is distinct from target_fingerprint
     or target.contract_status <> 'CERTIFIED'
     or target.certification_contract_version is distinct from
       'production-annual-google-writer-certification-v1'
     or target.resource_revision <> resource.resource_revision
     or target.promotion_revision <> promotion.promotion_revision
     or target.source_setup_revision <> promotion.source_setup_revision
     or target.promoted_manifest_fingerprint is distinct from
       promotion.promoted_manifest_fingerprint
     or target.resource_binding_fingerprint is distinct from
       resource_fingerprint then
    raise exception using errcode = '23505',
      message = 'PRODUCTION_FUTURE_GOOGLE_WRITER_TARGET_CONFLICT';
  else
    changed_value := false;
  end if;
  select coalesce(pg_catalog.sum(value.attempts), 0) into attempts_before
  from production_control.future_match_google_compatibility_jobs_v1 value
  where value.tournament_id = target_id;
  for job in
    select value.match_id
    from production_control.future_match_google_compatibility_jobs_v1 value
    where value.tournament_id = target_id
    order by value.match_id
  loop
    perform production_control.sync_future_google_writer_job_v2(
      target_id, job.match_id
    );
  end loop;
  select coalesce(pg_catalog.sum(value.attempts), 0),
    pg_catalog.count(*) filter (where value.writer_installed)
      into attempts_after, jobs_bound
  from production_control.future_match_google_compatibility_jobs_v1 value
  where value.tournament_id = target_id;
  if attempts_after <> attempts_before or exists (
    select 1
    from production_control.future_match_google_compatibility_jobs_v1 value
    where value.tournament_id = target_id
      and (value.status = 'PROCESSING' or value.claim_token is not null
        or value.claimed_by is not null or value.lease_expires_at is not null)
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_CLAIM_FORBIDDEN';
  end if;
  -- Recompute the installed implementation and the complete live target
  -- attestation after every binding update, before persisting the immutable
  -- success receipt. A changed function/ACL/trigger/resource cannot be
  -- certified by a hash sampled only at the start of this transaction.
  perform production_control
    .assert_future_google_writer_live_implementation_v2(target_id);
  result_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_FUTURE_GOOGLE_WRITER_TARGET_CERTIFIED',
    'action', 'CERTIFY_ANNUAL_GOOGLE_WRITER_TARGET',
    'targetTournamentId', target_id,
    'writerGenerationId', writer_generation_id_value,
    'implementationFingerprint', implementation_fingerprint,
    'targetContractFingerprint', target_fingerprint,
    'resourceBindingFingerprint', resource_fingerprint,
    'resourceRevision', resource.resource_revision,
    'promotionRevision', promotion.promotion_revision,
    'setupRevision', promotion.source_setup_revision,
    'jobsBound', jobs_bound,
    'jobsClaimed', 0,
    'googleWrites', 0,
    'nonAuthoritative', true,
    'idempotent', not changed_value
  );
  insert into production_control.future_google_writer_certification_receipts_v1 (
    action, target_tournament_id, operation_request_id,
    declared_request_payload_hash, database_request_payload_hash,
    actor_player_id, actor_auth_user_id, prior_revision, next_revision,
    response
  ) values (
    'CERTIFY_ANNUAL_GOOGLE_WRITER_TARGET', target_id, operation_id,
    declared_hash, database_hash, actor_player, actor_auth,
    promotion.promotion_revision, promotion.promotion_revision, result_value
  );
  insert into production_control.future_google_writer_certification_audit_v1 (
    action, target_tournament_id, actor_player_id, operation_request_id,
    prior_revision, next_revision, result, safe_metadata
  ) values (
    'CERTIFY_ANNUAL_GOOGLE_WRITER_TARGET', target_id, actor_player,
    operation_id, promotion.promotion_revision, promotion.promotion_revision,
    case when changed_value then 'CHANGED' else 'NO_CHANGE' end,
    pg_catalog.jsonb_build_object(
      'summary', 'Future Google compatibility writer target certified',
      'resourceRevision', resource.resource_revision,
      'promotionRevision', promotion.promotion_revision,
      'setupRevision', promotion.source_setup_revision,
      'jobsBound', jobs_bound,
      'jobsClaimed', 0,
      'googleWrites', 0,
      'nonAuthoritative', true
    )
  );
  return result_value;
exception when no_data_found then
  raise exception using errcode = '40001',
    message = 'PRODUCTION_FUTURE_GOOGLE_CERTIFICATION_PREDECESSOR_INVALID';
end;
$_$;


ALTER FUNCTION public.certify_production_future_google_writer_target_v1(input jsonb) OWNER TO postgres;

--
-- Name: checkpoint_production_odds_calculation_job(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.checkpoint_production_odds_calculation_job(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    AS $_$
declare
  job text := lower(coalesce(input->>'job_id', ''));
  claim uuid := nullif(input->>'claim_token', '')::uuid;
  progress integer := coalesce((input->>'completed_iterations')::integer, 0);
  checkpoint_hash_value text := lower(coalesce(input->>'checkpoint_hash', ''));
  retained scoring_authority.odds_calculation_jobs%rowtype;
  existing_checkpoint scoring_authority.odds_calculation_checkpoints%rowtype;
  next_sequence integer;
  canonical_value jsonb;
begin
  perform production_control.assert_production_odds_calculation_scope(input, true);
  if job !~ '^[0-9a-f]{64}$' or claim is null
     or checkpoint_hash_value !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(input->'checkpoint_payload') <> 'object'
     or coalesce(input->>'checkpoint_canonical_json', '') = '' then
    raise exception using errcode = '22023',
      message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_CHECKPOINT_REQUIRED';
  end if;
  begin
    canonical_value := (input->>'checkpoint_canonical_json')::jsonb;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_CANONICAL_JSON_INVALID';
  end;
  if canonical_value is distinct from input->'checkpoint_payload'
     or encode(extensions.digest(input->>'checkpoint_canonical_json', 'sha256'), 'hex')
          <> checkpoint_hash_value then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_CHECKPOINT_FINGERPRINT_MISMATCH';
  end if;

  select * into retained from scoring_authority.odds_calculation_jobs
  where job_id = job for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_JOB_NOT_FOUND');
  end if;
  perform production_control.assert_production_odds_retained_job_scope(
    input, to_jsonb(retained)
  );
  if retained.status <> 'RUNNING'
     or retained.claim_token is distinct from claim
     or retained.lease_expires_at <= now() then
    return jsonb_build_object(
      'ok', false, 'code', 'ODDS_CALCULATION_CLAIM_STALE',
      'retryable', false
    );
  end if;
  if progress < retained.completed_iterations or progress > retained.total_iterations then
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_PROGRESS_INVALID');
  end if;
  if progress = retained.completed_iterations then
    if retained.checkpoint_hash = checkpoint_hash_value then
      return jsonb_build_object(
        'ok', true, 'duplicate', true,
        'checkpoint_count', retained.checkpoint_count,
        'completed_iterations', retained.completed_iterations
      );
    end if;
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_CHECKPOINT_CONFLICT');
  end if;

  select * into existing_checkpoint
  from scoring_authority.odds_calculation_checkpoints
  where job_id = job and completed_iterations = progress;
  if found then
    if existing_checkpoint.checkpoint_hash = checkpoint_hash_value then
      return jsonb_build_object(
        'ok', true, 'duplicate', true,
        'checkpoint_count', retained.checkpoint_count,
        'completed_iterations', progress
      );
    end if;
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_CHECKPOINT_CONFLICT');
  end if;

  next_sequence := retained.checkpoint_count + 1;
  insert into scoring_authority.odds_calculation_checkpoints (
    job_id, checkpoint_sequence, completed_iterations,
    checkpoint_contract_version, checkpoint_payload, checkpoint_hash,
    attempt_number, resource_metrics
  ) values (
    job, next_sequence, progress, retained.checkpoint_contract_version,
    input->'checkpoint_payload', checkpoint_hash_value,
    retained.attempt_count, coalesce(input->'resource_metrics', '{}'::jsonb)
  );
  update scoring_authority.odds_calculation_jobs
  set completed_iterations = progress,
      checkpoint_payload = input->'checkpoint_payload',
      checkpoint_hash = checkpoint_hash_value,
      checkpoint_count = next_sequence,
      resource_metrics = coalesce(input->'resource_metrics', resource_metrics),
      lease_expires_at = now() + interval '12 minutes', updated_at = now()
  where job_id = job;
  return jsonb_build_object(
    'ok', true, 'duplicate', false, 'completed_iterations', progress,
    'total_iterations', retained.total_iterations,
    'checkpoint_count', next_sequence,
    'publication_created', false, 'mirror_created', false
  );
end;
$_$;


ALTER FUNCTION public.checkpoint_production_odds_calculation_job(input jsonb) OWNER TO postgres;

--
-- Name: claim_competition_derived_jobs(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_competition_derived_jobs(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  legacy_input jsonb;
  result_value jsonb;
begin
  perform production_control.assert_frozen_2026_derived_worker_v1(input);
  if btrim(coalesce(input->>'worker_id', '')) <> '' then
    perform production_control.flush_score_derived_intents_v1('2026', 'COMPETITION', 8);
  end if;
  legacy_input := input || pg_catalog.jsonb_build_object(
    'environment', 'PREVIEW', 'tournament_id', '2026'
  );
  if pg_catalog.to_regprocedure(
       'public.claim_competition_derived_jobs_frozen_2026_installed_v1(jsonb)'
     ) is not null then
    execute $installed$select public
      .claim_competition_derived_jobs_frozen_2026_installed_v1($1)
    $installed$ into strict result_value using legacy_input;
    return result_value;
  end if;
  return production_control
    .frozen_2026_claim_competition_derived_jobs_v1(legacy_input);
end;
$_$;


ALTER FUNCTION public.claim_competition_derived_jobs(input jsonb) OWNER TO postgres;

