--
-- Name: claim_production_odds_calculation_job(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_production_odds_calculation_job(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    AS $_$
declare
  job text := lower(coalesce(input->>'job_id', ''));
  retained scoring_authority.odds_calculation_jobs%rowtype;
  config scoring_authority.odds_input_configurations%rowtype;
begin
  perform production_control.assert_production_odds_calculation_scope(input, true);
  if job !~ '^[0-9a-f]{64}$' or coalesce(input->>'worker_id', '') = '' then
    raise exception using errcode = '22023',
      message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_CLAIM_REQUIRED';
  end if;
  select * into retained from scoring_authority.odds_calculation_jobs
  where job_id = job for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_JOB_NOT_FOUND');
  end if;
  perform production_control.assert_production_odds_retained_job_scope(
    input, to_jsonb(retained)
  );

  config := production_control.current_production_odds_inputs(
    input || jsonb_build_object(
      'input_configuration_id', retained.input_configuration_id,
      'configuration_revision', retained.source_revision->>'configuration_revision',
      'settings_fingerprint', retained.settings_fingerprint,
      'effective_settings_fingerprint', retained.effective_settings_fingerprint,
      'input_bundle_fingerprint', retained.input_bundle_fingerprint,
      'source_revision', retained.source_revision
    )
  );
  if retained.input_configuration_id <> config.id
     or retained.input_bundle_fingerprint <> config.bundle_fingerprint then
    update scoring_authority.odds_calculation_jobs
    set status = 'SUPERSEDED', publication_status = 'STALE',
        superseded_at = now(), claim_token = null, lease_expires_at = null,
        last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
        last_error_safe = 'Canonical Production calculation inputs advanced.',
        updated_at = now()
    where job_id = job;
    return jsonb_build_object(
      'ok', false, 'code', 'ODDS_CALCULATION_JOB_SUPERSEDED',
      'retryable', false
    );
  end if;

  if retained.status = 'SUCCEEDED' then
    return jsonb_build_object(
      'ok', true, 'deliver', false, 'completed', true,
      'job', to_jsonb(retained) - 'claim_token'
    );
  end if;
  if retained.status in ('SUPERSEDED', 'FAILED') then
    return jsonb_build_object(
      'ok', false, 'code', 'ODDS_CALCULATION_JOB_' || retained.status,
      'retryable', false
    );
  end if;
  if retained.status = 'RUNNING' and retained.lease_expires_at > now() then
    return jsonb_build_object(
      'ok', true, 'deliver', false, 'in_progress', true,
      'job', to_jsonb(retained) - 'input_snapshot' - 'checkpoint_payload'
        - 'result_payload' - 'claim_token'
    );
  end if;

  update scoring_authority.odds_calculation_jobs
  set status = 'RUNNING', attempt_count = attempt_count + 1,
      claim_token = extensions.gen_random_uuid(),
      lease_owner = left(input->>'worker_id', 180),
      lease_expires_at = now() + interval '12 minutes',
      started_at = coalesce(started_at, now()), updated_at = now(),
      last_error_code = null, last_error_safe = null
  where job_id = job returning * into retained;
  return jsonb_build_object(
    'ok', true, 'deliver', true, 'job', to_jsonb(retained),
    'publication_created', false, 'mirror_created', false
  );
exception when sqlstate 'P0001' then
  if sqlerrm = 'PRODUCTION_ODDS_INPUT_REVISION_STALE' then
    update scoring_authority.odds_calculation_jobs
    set status = 'SUPERSEDED', publication_status = 'STALE',
        superseded_at = now(), claim_token = null, lease_expires_at = null,
        last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
        last_error_safe = 'Canonical Production calculation inputs advanced.',
        updated_at = now()
    where job_id = job and status in ('PENDING', 'RUNNING', 'RETRYABLE', 'SUCCEEDED')
      and production_operation_mode = input->>'operation_mode'
      and production_deployment_commit = input->>'deployment_commit'
      and production_candidate_hostname is not distinct from
        nullif(input->>'candidate_hostname', '');
    return jsonb_build_object(
      'ok', false, 'code', 'ODDS_CALCULATION_JOB_SUPERSEDED',
      'retryable', false
    );
  end if;
  raise;
end;
$_$;


ALTER FUNCTION public.claim_production_odds_calculation_job(input jsonb) OWNER TO postgres;

--
-- Name: claim_production_scorecard_archive_job(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_production_scorecard_archive_job(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    AS $$
declare
  job_row scoring_authority.scorecard_archive_jobs%rowtype;
  worker text := left(coalesce(nullif(input->>'worker_id', ''), ''), 160);
  token uuid := extensions.gen_random_uuid();
  lease integer := greatest(15, least(coalesce((input->>'lease_seconds')::integer, 60), 300));
begin
  perform production_control.assert_production_scoring_runtime(input, 'ROUND_SCORECARDS_ARCHIVE');
  if worker = '' then return jsonb_build_object('ok', false, 'code', 'WORKER_ID_REQUIRED'); end if;
  update scoring_authority.scorecard_archive_jobs older set
    status = 'SUPERSEDED', lease_expires_at = null, claimed_by = null,
    claim_token = null, updated_at = now()
  where older.tournament_id = '2026'
    and older.status in ('PENDING', 'RETRYABLE', 'PROCESSING')
    and (older.status <> 'PROCESSING' or older.lease_expires_at < now())
    and exists (select 1 from scoring_authority.scorecard_archive_jobs newer
      where newer.match_id = older.match_id and newer.match_revision > older.match_revision
        and newer.status in ('PENDING', 'RETRYABLE', 'PROCESSING', 'VERIFIED'));
  select * into job_row from scoring_authority.scorecard_archive_jobs job
  where job.tournament_id = '2026'
    and (job.status in ('PENDING', 'RETRYABLE')
      or (job.status = 'PROCESSING' and job.lease_expires_at < now()))
    and job.available_at <= now()
    and not exists (select 1 from scoring_authority.scorecard_archive_jobs newer
      where newer.match_id = job.match_id and newer.match_revision > job.match_revision
        and newer.status in ('PENDING', 'RETRYABLE', 'PROCESSING', 'VERIFIED'))
  order by job.available_at, job.created_at, job.match_id
  for update skip locked limit 1;
  if not found then return jsonb_build_object('ok', true, 'job', null); end if;
  update scoring_authority.scorecard_archive_jobs set
    status = 'PROCESSING', attempts = attempts + 1, claimed_by = worker,
    claim_token = token, lease_expires_at = now() + make_interval(secs => lease),
    updated_at = now()
  where job_id = job_row.job_id returning * into job_row;
  return jsonb_build_object(
    'ok', true,
    'job', to_jsonb(job_row) || jsonb_build_object('id', job_row.job_id),
    'snapshot', (select to_jsonb(snapshot) from scoring_authority.finalized_scorecard_snapshots snapshot
      where snapshot.snapshot_id = job_row.snapshot_id),
    'checkpoint', (select to_jsonb(checkpoint) from scoring_authority.scorecard_archive_checkpoints checkpoint
      where checkpoint.match_id = job_row.match_id)
  );
end;
$$;


ALTER FUNCTION public.claim_production_scorecard_archive_job(input jsonb) OWNER TO postgres;

--
-- Name: clear_disabled_net_skins_operational_state(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clear_disabled_net_skins_operational_state(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  target_tournament text := btrim(coalesce(target_tournament_id, ''));
  jobs_removed integer := 0;
  snapshots_retired integer := 0;
begin
  if target_tournament = '' then return jsonb_build_object('ok', false, 'code', 'TOURNAMENT_REQUIRED'); end if;
  delete from scoring_authority.competition_recalculation_jobs j
  using scoring_authority.net_skins_configurations c
  where j.tournament_id = target_tournament and j.engine_key = 'NET_SKINS'
    and c.tournament_id = j.tournament_id and c.round_number = j.round_number and not c.enabled;
  get diagnostics jobs_removed = row_count;
  update scoring_authority.competition_derived_snapshots s set is_current = false
  from scoring_authority.net_skins_configurations c
  where s.tournament_id = target_tournament and s.engine_key = 'NET_SKINS' and s.is_current
    and c.tournament_id = s.tournament_id and c.round_number = s.round_number and not c.enabled;
  get diagnostics snapshots_retired = row_count;
  return jsonb_build_object('ok', true, 'jobs_removed', jobs_removed, 'snapshots_retired', snapshots_retired);
end;
$$;


ALTER FUNCTION public.clear_disabled_net_skins_operational_state(target_tournament_id text) OWNER TO postgres;

--
-- Name: clear_production_calcutta_v1_auction_entry(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.clear_production_calcutta_v1_auction_entry(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$begin
  perform production_control.assert_production_service_role();
  perform production_control.assert_production_calcutta_v1_runtime(input);
  if input->>'contract_version' is distinct from 'production-calcutta-v1'
     or input->>'expected_tournament_id' is distinct from '2026'
     or (select tournament_id from production_control.current_tournament_pointer_v1
         where scope_key='BAGGER_INV_PRODUCTION') is distinct from '2026' then
    raise exception using errcode='42501', message='PRODUCTION_CALCUTTA_CLEAR_SCOPE_DENIED';
  end if;
  perform production_control.assert_production_scoring_actor(input, true);
  return production_control.canonical_calcutta_clear_core_v1(input,null);
end;$$;


