--
-- Name: complete_participant_phone_enrollment(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_participant_phone_enrollment(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'scoring_authority', 'public', 'auth', 'pg_temp'
    AS $$
declare target_attempt uuid := nullif(input->>'attempt_id', '')::uuid;
declare actor_auth_user uuid := nullif(input->>'actor_auth_user_id', '')::uuid;
declare returned_auth_user uuid := nullif(input->>'returned_auth_user_id', '')::uuid;
declare duration_value integer := greatest(0, coalesce((input->>'duration_ms')::integer, 0));
declare attempt participant_identity.participant_phone_otp_attempts%rowtype;
declare identifier participant_identity.participant_auth_identifiers%rowtype;
declare email_identifier participant_identity.participant_auth_identifiers%rowtype;
declare auth_user auth.users%rowtype;
begin
  select * into attempt from participant_identity.participant_phone_otp_attempts
  where attempt_id = target_attempt and auth_user_id = actor_auth_user and requested_by_auth_user_id = actor_auth_user
  for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_SESSION_REQUIRED'); end if;
  if attempt.status = 'VERIFIED' then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_REPLAY'); end if;
  if attempt.status <> 'SENT' or attempt.expires_at <= now() then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_STALE'); end if;
  if returned_auth_user is null or returned_auth_user <> attempt.auth_user_id then
    update participant_identity.participant_phone_otp_attempts set status = 'UUID_MISMATCH', safe_reason = 'PHONE_OTP_AUTH_MISMATCH', updated_at = now()
    where attempt_id = target_attempt;
    update participant_identity.participant_auth_identifiers set status = 'ELIGIBLE', updated_at = now()
    where identifier_id = attempt.identifier_id and status = 'VERIFICATION_PENDING';
    return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_AUTH_MISMATCH');
  end if;
  select * into identifier from participant_identity.participant_auth_identifiers where identifier_id = attempt.identifier_id for update;
  select * into email_identifier from participant_identity.participant_auth_identifiers
  where player_id = attempt.player_id and auth_user_id = attempt.auth_user_id
    and identifier_type = 'EMAIL' and status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED');
  select * into auth_user from auth.users where id = attempt.auth_user_id;
  if identifier.identifier_id is null or identifier.status <> 'VERIFICATION_PENDING'
     or identifier.revision <> attempt.identifier_revision
     or identifier.player_id <> attempt.player_id or identifier.auth_user_id <> attempt.auth_user_id
     or email_identifier.identifier_id is null
     or lower(btrim(coalesce(auth_user.email, ''))) <> email_identifier.normalized_value_private
     or participant_identity.canonical_auth_phone(nullif(auth_user.phone, ''))
       is distinct from participant_identity.canonical_auth_phone(identifier.normalized_value_private)
     or auth_user.phone_confirmed_at is null
     or nullif(btrim(coalesce(auth_user.phone_change, '')), '') is not null
     or not exists (select 1 from participant_identity.user_player_links link
       where link.player_id = attempt.player_id and link.auth_user_id = attempt.auth_user_id and link.status = 'ACTIVE')
     or (select count(*) from auth.identities identity where identity.user_id = attempt.auth_user_id and identity.provider = 'phone') <> 1
     or exists (select 1 from auth.users other_user where other_user.id <> attempt.auth_user_id
       and (participant_identity.canonical_auth_phone(nullif(other_user.phone, ''))
         = participant_identity.canonical_auth_phone(identifier.normalized_value_private)
         or participant_identity.canonical_auth_phone(nullif(other_user.phone_change, ''))
         = participant_identity.canonical_auth_phone(identifier.normalized_value_private))) then
    return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_AUTH_MISMATCH');
  end if;
  update participant_identity.participant_phone_otp_attempts set status = 'VERIFIED',
    safe_reason = 'SAME_AUTH_USER_PHONE_CHANGE_VERIFIED', verification_duration_ms = duration_value,
    verified_at = now(), used_at = now(), updated_at = now()
  where attempt_id = target_attempt and status = 'SENT';
  if not found then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_REPLAY'); end if;
  update participant_identity.participant_auth_identifiers set status = 'VERIFIED', verified_at = now(),
    verification_source = 'SUPABASE_AUTH_TWILIO_VERIFY', updated_by = 'SUPABASE_AUTH_PHONE_CHANGE', updated_at = now()
  where identifier_id = attempt.identifier_id and revision = attempt.identifier_revision and status = 'VERIFICATION_PENDING';
  if not found then raise exception 'Phone ownership changed during verification.'; end if;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_id, actor_name,
    request_id, safe_metadata
  ) values (
    'PHONE_ENROLLMENT_VERIFIED', attempt.tournament_id, attempt.auth_user_id,
    attempt.player_id, attempt.player_id, 'Authenticated participant', attempt.attempt_id::text,
    jsonb_build_object('method', 'AUTHENTICATED_PHONE_CHANGE', 'returnedAuthUserMatch', true,
      'playerIdUnchanged', true, 'emailPreserved', true, 'durationMs', duration_value,
      'rawPhoneLogged', false, 'otpLogged', false)
  );
  return jsonb_build_object('ok', true, 'status', 'VERIFIED', 'sameAuthUser', true,
    'playerId', attempt.player_id, 'emailPreserved', true, 'activeLink', true);
end;
$$;


ALTER FUNCTION public.complete_participant_phone_enrollment(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_auth_candidate_preprovision(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_auth_candidate_preprovision(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $$
declare scope production_control.resource_scope%rowtype;
declare claim participant_identity.production_auth_preprovision_claims%rowtype;
declare target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
declare auth_user auth.users%rowtype;
declare current_contact participant_identity.participant_identity_contacts%rowtype;
declare current_candidate participant_identity.production_auth_candidates%rowtype;
declare current_link participant_identity.user_player_links%rowtype;
declare current_identifier participant_identity.participant_auth_identifiers%rowtype;
declare link_id_value uuid;
begin
  scope := production_control.assert_production_auth_candidate_rpc();
  if btrim(coalesce(input->>'project_ref', '')) <> scope.project_ref
    or btrim(coalesce(input->>'project_url', '')) <> scope.project_url
    or btrim(coalesce(input->>'source_workbook_id', '')) <> scope.google_workbook_id
    or btrim(coalesce(input->>'tournament_id', '')) <> '2026'
    or target_user is null then
    raise exception using errcode = '42501', message = 'PRODUCTION_AUTH_PREPROVISION_EXACT_SCOPE_REQUIRED';
  end if;
  select * into claim from participant_identity.production_auth_preprovision_claims
  where claim_id = nullif(input->>'claim_id', '')::uuid for update;
  if not found or claim.bootstrap_key <> 'STEP10B_PRODUCTION_DIRECTOR_AUTH'
    or claim.tournament_id <> '2026' or claim.project_ref <> scope.project_ref
    or claim.source_workbook_id <> scope.google_workbook_id then
    raise exception using errcode = '42501', message = 'PRODUCTION_AUTH_PREPROVISION_CLAIM_REQUIRED';
  end if;
  if claim.auth_user_id is not null and claim.auth_user_id is distinct from target_user then
    raise exception using errcode = '42501', message = 'PRODUCTION_AUTH_PREPROVISION_CLAIM_USER_MISMATCH';
  end if;
  select * into auth_user from auth.users where id = target_user;
  if not found
    or encode(extensions.digest(lower(btrim(coalesce(auth_user.email, '')))::text, 'sha256'), 'hex')
      is distinct from claim.email_identity_hash
    or auth_user.raw_app_meta_data->>'provisioning_scope'
      is distinct from 'production_shadow_director_certification'
    or auth_user.raw_app_meta_data->>'player_id' is distinct from claim.player_id
    or auth_user.raw_app_meta_data->>'tournament_id' is distinct from '2026'
    or (select count(*) from auth.users) <> 1 then
    raise exception using errcode = '42501', message = 'PRODUCTION_AUTH_PREPROVISION_AUTH_IDENTITY_MISMATCH';
  end if;

  if claim.status = 'CONSUMED' then
    if claim.auth_user_id <> target_user
      or not exists (select 1 from participant_identity.production_auth_candidates
        where tournament_id = '2026' and auth_user_id = target_user and player_id = claim.player_id)
      or not exists (select 1 from participant_identity.user_player_links
        where auth_user_id = target_user and player_id = claim.player_id
          and status = case when exists (
            select 1 from participant_identity.production_auth_candidates
            where tournament_id = '2026' and auth_user_id = target_user and status = 'VERIFIED'
          ) then 'ACTIVE' else 'PENDING' end) then
      raise exception using errcode = 'P0001', message = 'PRODUCTION_AUTH_PREPROVISION_CONSUMED_DRIFT';
    end if;
    return jsonb_build_object('ok', true, 'status', 'PREPARED', 'duplicate', true,
      'claimId', claim.claim_id, 'authUserId', target_user, 'playerId', claim.player_id);
  end if;
  if claim.status not in ('PENDING', 'CLEANUP_REQUIRED')
    or (claim.status = 'PENDING' and claim.expires_at <= now()) then
    raise exception using errcode = '42501', message = 'PRODUCTION_AUTH_PREPROVISION_CLAIM_INACTIVE';
  end if;

  -- Revalidate both source boundaries after Auth user creation. A claim may not
  -- finalize against a tournament or identity projection that advanced while
  -- the external Auth operation was in flight.
  if not exists (
    select 1 from production_control.current_shadow_revisions revision
    where revision.tournament_id = '2026'
      and revision.source_workbook_id = scope.google_workbook_id
      and revision.source_fingerprint = claim.source_fingerprint
      and revision.import_run_id = (
        select latest.import_run_id
        from production_control.current_shadow_revisions latest
        where latest.tournament_id = '2026'
        order by latest.imported_at desc, latest.import_run_id desc
        limit 1
      )
  ) or not exists (
    select 1 from scoring_authority.tournament_players
    where tournament_id = '2026' and player_id = claim.player_id
      and participation_status = 'ACTIVE'
  ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_AUTH_PREPROVISION_SOURCE_ADVANCED';
  end if;

  select * into current_contact from participant_identity.participant_identity_contacts
  where tournament_id = '2026' and player_id = claim.player_id for update;
  if not found
    or not current_contact.identity_active
    or current_contact.source_workbook_id is distinct from scope.google_workbook_id
    or encode(extensions.digest(current_contact.email_normalized::text, 'sha256'), 'hex')
      is distinct from claim.email_identity_hash
    or not exists (
      select 1
      from participant_identity.identity_context_revisions context_revision
      join participant_identity.identity_config_import_runs import_run
        on import_run.tournament_id = context_revision.tournament_id
        and import_run.configuration_revision = context_revision.context_revision
        and import_run.source_fingerprint = context_revision.configuration_fingerprint
        and import_run.status = 'APPROVED'
        and import_run.approved_at is not null
      where context_revision.tournament_id = '2026'
        and context_revision.context_revision = current_contact.configuration_revision
        and context_revision.configuration_fingerprint = claim.identity_source_fingerprint
    ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_AUTH_PREPROVISION_APPROVED_IDENTITY_REQUIRED';
  end if;

  select * into current_candidate from participant_identity.production_auth_candidates
  where tournament_id = '2026' for update;
  if found then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_AUTH_PREPROVISION_CANDIDATE_STATE_DRIFT';
  end if;
  insert into participant_identity.production_auth_candidates (
    tournament_id, player_id, auth_user_id, email_identity_hash,
    source_fingerprint, identity_source_fingerprint, source_workbook_id, project_ref, status,
    certification_revision, prepared_by
  ) values (
    '2026', claim.player_id, target_user, claim.email_identity_hash,
    claim.source_fingerprint, claim.identity_source_fingerprint, scope.google_workbook_id,
    scope.project_ref, 'PREPARED', 1, claim.requested_by
  );

  select * into current_link from participant_identity.user_player_links
  where auth_user_id = target_user
    or (player_id = claim.player_id and status in ('PENDING', 'ACTIVE', 'SUSPENDED'))
  limit 1 for update;
  if found and (current_link.auth_user_id <> target_user or current_link.player_id <> claim.player_id
    or current_link.email_identity_hash <> claim.email_identity_hash) then
    raise exception 'Existing Auth user or Player link requires an explicit audited link-change operation.';
  end if;
  if found then
    update participant_identity.user_player_links set status = 'PENDING', linked_at = null,
      linked_by = claim.requested_by, revoked_at = null, revoked_by = null, revoke_reason = null,
      link_revision = link_revision + 1, updated_at = now()
    where link_id = current_link.link_id returning link_id into link_id_value;
  else
    insert into participant_identity.user_player_links (
      auth_user_id, player_id, status, link_method, email_identity_hash, linked_at, linked_by
    ) values (
      target_user, claim.player_id, 'PENDING', 'PRODUCTION_CANDIDATE_PREPROVISION',
      claim.email_identity_hash, null, claim.requested_by
    ) returning link_id into link_id_value;
  end if;

  select * into current_identifier from participant_identity.participant_auth_identifiers
  where (auth_user_id = target_user or player_id = claim.player_id)
    and identifier_type = 'EMAIL'
    and status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
  limit 1 for update;
  if found and (current_identifier.auth_user_id <> target_user
    or current_identifier.player_id <> claim.player_id
    or encode(extensions.digest(current_identifier.normalized_value_private::text, 'sha256'), 'hex') <> claim.email_identity_hash) then
    raise exception 'Existing email identifier requires an explicit audited ownership change.';
  end if;
  if not found then
    insert into participant_identity.participant_auth_identifiers (
      player_id, auth_user_id, identifier_type, normalized_value_private, status,
      verification_source, source_system, source_tournament_id,
      source_configuration_revision, created_by, updated_by
    ) values (
      claim.player_id, target_user, 'EMAIL', lower(btrim(auth_user.email)), 'VERIFICATION_PENDING',
      null, 'PRODUCTION_DIRECTOR_AUTH_CERTIFICATION', '2026', current_contact.configuration_revision,
      claim.requested_by, claim.requested_by
    );
  end if;

  update participant_identity.production_auth_preprovision_claims set
    status = 'CONSUMED', auth_user_id = target_user, consumed_at = now(),
    cancelled_at = null, cleanup_reason = null, updated_at = now()
  where claim_id = claim.claim_id;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_name, safe_metadata
  ) values (
    'PRODUCTION_AUTH_CANDIDATE_PREPARED', '2026', target_user, claim.player_id, claim.requested_by,
    jsonb_build_object('sourceFingerprint', claim.source_fingerprint, 'emailValueStored', false,
      'projectRef', scope.project_ref, 'claimId', claim.claim_id,
      'linkId', link_id_value, 'authoritativeIdentityChanged', false)
  );
  return jsonb_build_object('ok', true, 'status', 'PREPARED', 'duplicate', false,
    'claimId', claim.claim_id, 'playerId', claim.player_id,
    'authUserId', target_user, 'emailStoredInResponse', false);
end;
$$;


ALTER FUNCTION public.complete_production_auth_candidate_preprovision(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_calcutta_v1_recalculation(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_calcutta_v1_recalculation(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$begin return production_control.canonical_complete_calcutta_v1_recalculation_core_v2(input,null); end;$$;


ALTER FUNCTION public.complete_production_calcutta_v1_recalculation(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_future_google_compatibility_job_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_future_google_compatibility_job_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  job production_control.future_match_google_compatibility_jobs_v1%rowtype;
begin
  perform production_control.assert_future_compatibility_worker_v1(input);
  select value.* into strict job
  from production_control.future_match_google_compatibility_jobs_v1 value
  where value.job_id = (input->>'job_id')::uuid
    and value.tournament_id = input->>'target_tournament_id'
  for update;
  if job.status = 'CERTIFIED' then
    if job.readback_fingerprint is distinct from input->>'readback_fingerprint'
       or job.expected_manifest_fingerprint
         is distinct from input->>'expected_manifest_fingerprint' then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_FUTURE_COMPATIBILITY_COMPLETION_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'status', 'CERTIFIED', 'idempotent', true
    );
  end if;
  if job.status <> 'PROCESSING'
     or job.claim_token is distinct from (input->>'claim_token')::uuid
     or job.lease_expires_at <= pg_catalog.clock_timestamp()
     or input->>'expected_manifest_fingerprint'
       is distinct from job.expected_manifest_fingerprint
     or input->>'readback_fingerprint' !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(input->'readback_checkpoint') <> 'object'
     or coalesce((input#>>'{readback_checkpoint,liveMatchVerified}')::boolean,
       false) is not true
     or coalesce((input#>>'{readback_checkpoint,archiveMatchVerified}')::boolean,
       false) is not true then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_FUTURE_COMPATIBILITY_COMPLETION_STALE';
  end if;
  update production_control.future_match_google_compatibility_jobs_v1 value set
    status = 'CERTIFIED', readback_fingerprint = input->>'readback_fingerprint',
    readback_checkpoint = input->'readback_checkpoint',
    certified_at = pg_catalog.clock_timestamp(), claim_token = null,
    claimed_by = null, lease_expires_at = null, safe_error_code = null,
    updated_at = pg_catalog.clock_timestamp()
  where value.job_id = job.job_id;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'status', 'CERTIFIED', 'jobId', job.job_id,
    'matchId', job.match_id, 'readbackFingerprint',
      input->>'readback_fingerprint', 'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.complete_production_future_google_compatibility_job_v1(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_future_match_google_compatibility_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_future_match_google_compatibility_v1(input jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select public.complete_production_future_google_compatibility_job_v1(input)
$$;


ALTER FUNCTION public.complete_production_future_match_google_compatibility_v1(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_future_match_google_compatibility_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_future_match_google_compatibility_v2(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target_id text;
  job production_control.future_match_google_compatibility_jobs_v1%rowtype;
  current_manifest_fingerprint text;
begin
  target_id := production_control.assert_future_google_writer_v2(input, true);
  select value.* into strict job
  from production_control.future_match_google_compatibility_jobs_v1 value
  where value.job_id = (input->>'job_id')::uuid
    and value.tournament_id = target_id
    and value.writer_generation_id =
      (input->>'expected_writer_generation_id')::uuid
    and value.destination_workbook_id = input->>'destination_workbook_id'
    and value.target_contract_fingerprint =
      input->>'expected_target_contract_fingerprint'
  for update;
  current_manifest_fingerprint := production_control.future_runtime_hash_v2(
    production_control.future_google_match_manifest_v2(job.match_id)
  );
  if job.status = 'CERTIFIED' then
    if job.expected_manifest_fingerprint
         is distinct from input->>'expected_manifest_fingerprint'
       or current_manifest_fingerprint
         is distinct from input->>'expected_manifest_fingerprint'
       or job.readback_fingerprint
         is distinct from input->>'readback_fingerprint'
       or job.readback_checkpoint is distinct from input->'readback_checkpoint'
       or job.structural_fingerprint
         is distinct from input->>'expected_structural_fingerprint' then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_FUTURE_COMPATIBILITY_COMPLETION_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'status', 'CERTIFIED', 'idempotent', true,
      'jobId', job.job_id, 'matchId', job.match_id
    );
  end if;
  if job.status <> 'PROCESSING' or not job.writer_installed
     or job.claim_token is distinct from (input->>'claim_token')::uuid
     or job.lease_expires_at <= pg_catalog.clock_timestamp()
     or job.expected_manifest_fingerprint
       is distinct from input->>'expected_manifest_fingerprint'
     or current_manifest_fingerprint
       is distinct from input->>'expected_manifest_fingerprint'
     or job.structural_fingerprint
       is distinct from input->>'expected_structural_fingerprint'
     or input->>'readback_fingerprint' !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(input->'readback_checkpoint') <> 'object'
     or coalesce((input#>>'{readback_checkpoint,liveMatchVerified}')::boolean,
       false) is not true
     or coalesce((input#>>'{readback_checkpoint,archiveMatchVerified}')::boolean,
       false) is not true
     or input#>>'{readback_checkpoint,writerGenerationId}'
       is distinct from job.writer_generation_id::text
     or input#>>'{readback_checkpoint,destinationWorkbookId}'
       is distinct from job.destination_workbook_id
     or input#>>'{readback_checkpoint,targetContractFingerprint}'
       is distinct from job.target_contract_fingerprint
     or input#>>'{readback_checkpoint,structuralFingerprint}'
       is distinct from job.structural_fingerprint
     or coalesce((input#>>'{readback_checkpoint,runtimeRevision}')::bigint, -1)
       <> job.structural_runtime_revision then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_FUTURE_COMPATIBILITY_COMPLETION_STALE';
  end if;
  update production_control.future_match_google_compatibility_jobs_v1 value set
    status = 'CERTIFIED', readback_fingerprint = input->>'readback_fingerprint',
    readback_checkpoint = input->'readback_checkpoint',
    certified_at = pg_catalog.clock_timestamp(), claim_token = null,
    claimed_by = null, lease_expires_at = null, safe_error_code = null,
    updated_at = pg_catalog.clock_timestamp()
  where value.job_id = job.job_id;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'status', 'CERTIFIED', 'jobId', job.job_id,
    'matchId', job.match_id, 'readbackFingerprint',
      input->>'readback_fingerprint', 'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.complete_production_future_match_google_compatibility_v2(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_future_participant_first_login_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_future_participant_first_login_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  claim participant_identity.production_participant_enrollment_claims%rowtype;
  auth_user auth.users%rowtype;
  target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
  contact participant_identity.participant_identity_contacts%rowtype;
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  select value.* into claim
  from participant_identity.production_participant_enrollment_claims value
  where value.claim_id = nullif(input->>'claim_id', '')::uuid
  for update;
  if not found or claim.tournament_id <> target_id
     or target_user is null then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_CLAIM_REQUIRED';
  end if;
  if claim.status = 'CONSUMED' then
    if claim.auth_user_id <> target_user or not exists (
      select 1
      from participant_identity.user_player_links link
      where link.auth_user_id = target_user
        and link.player_id = claim.player_id
        and link.status = 'PENDING'
    ) then
      raise exception using errcode = '42501',
        message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_DRIFT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'playerId', claim.player_id,
      'authUserId', target_user, 'tournamentId', target_id,
      'idempotent', true
    );
  end if;
  if claim.status <> 'PENDING'
     or claim.expires_at <= pg_catalog.clock_timestamp() then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_CLAIM_INACTIVE';
  end if;
  select value.* into auth_user
  from auth.users value where value.id = target_user;
  if not found or auth_user.email_confirmed_at is not null
     or encode(extensions.digest(pg_catalog.lower(pg_catalog.btrim(coalesce(
       auth_user.email, ''
     )))::text, 'sha256'), 'hex') <> claim.email_identity_hash
     or auth_user.raw_app_meta_data->>'provisioning_scope'
       <> 'production_controlled_first_login'
     or auth_user.raw_app_meta_data->>'player_id' <> claim.player_id
     or auth_user.raw_app_meta_data->>'tournament_id' <> target_id
     or (select pg_catalog.count(*) from auth.users value
       where pg_catalog.lower(pg_catalog.btrim(coalesce(value.email, '')))
         = pg_catalog.lower(pg_catalog.btrim(auth_user.email))) <> 1 then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PARTICIPANT_AUTH_USER_SCOPE_MISMATCH';
  end if;
  select contact_value.* into contact
  from participant_identity.participant_identity_contacts contact_value
  join participant_identity.future_tournament_participant_bindings_v1 binding
    on binding.tournament_id = contact_value.tournament_id
   and binding.player_id = contact_value.player_id
   and binding.contact_state = 'APPROVED'
   and binding.enrollment_state = 'NOT_ENROLLED'
  join scoring_authority.tournament_players membership
    on membership.tournament_id = contact_value.tournament_id
   and membership.player_id = contact_value.player_id
   and membership.participation_status = 'ACTIVE'
  where contact_value.tournament_id = target_id
    and contact_value.player_id = claim.player_id
    and contact_value.identity_active
    and contact_value.configuration_revision =
      claim.source_configuration_revision
    and encode(extensions.digest(contact_value.email_normalized::text,
      'sha256'), 'hex') = claim.email_identity_hash;
  if not found or exists (
      select 1 from participant_identity.user_player_links value
      where value.auth_user_id = target_user
        or (value.player_id = claim.player_id
          and value.status in ('PENDING', 'ACTIVE', 'SUSPENDED'))
    ) or exists (
      select 1
      from participant_identity.participant_auth_identifiers value
      where value.normalized_value_private = contact.email_normalized
        and value.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
    ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PARTICIPANT_IDENTITY_COLLISION';
  end if;
  insert into participant_identity.user_player_links (
    auth_user_id, player_id, status, link_method,
    email_identity_hash, linked_by
  ) values (
    target_user, claim.player_id, 'PENDING',
    'PRODUCTION_CONTROLLED_FIRST_LOGIN', claim.email_identity_hash,
    'future-runtime-controlled-first-login-v1'
  );
  insert into participant_identity.participant_auth_identifiers (
    player_id, auth_user_id, identifier_type,
    normalized_value_private, status, source_system,
    source_tournament_id, source_configuration_revision,
    created_by, updated_by
  ) values (
    claim.player_id, target_user, 'EMAIL', contact.email_normalized,
    'VERIFICATION_PENDING', 'PRODUCTION_APPROVED_PARTICIPANT_IDENTITY',
    target_id, contact.configuration_revision,
    'future-runtime-controlled-first-login-v1',
    'future-runtime-controlled-first-login-v1'
  );
  update participant_identity.production_participant_enrollment_claims set
    status = 'CONSUMED', auth_user_id = target_user,
    consumed_at = pg_catalog.clock_timestamp(),
    updated_at = pg_catalog.clock_timestamp()
  where claim_id = claim.claim_id;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id,
    actor_name, request_id, safe_metadata
  ) values (
    'FUTURE_TOURNAMENT_PARTICIPANT_AUTH_USER_PREPARED', target_id,
    target_user, claim.player_id,
    'future-runtime-controlled-first-login-v1', claim.claim_id::text,
    pg_catalog.jsonb_build_object(
      'rawIdentifierStoredInAudit', false,
      'emailConfirmed', false,
      'participantAuthorityChanged', false
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'playerId', claim.player_id,
    'authUserId', target_user, 'tournamentId', target_id,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION public.complete_production_future_participant_first_login_v1(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_google_outbox(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_google_outbox(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  event_row scoring_authority.google_outbox_events%rowtype;
  checkpoint_row scoring_authority.google_match_checkpoints%rowtype;
  worker text := left(coalesce(nullif(input->>'worker_id', ''), ''), 160);
begin
  perform production_control.assert_production_scoring_runtime(input, 'SCORING_GOOGLE_OUTBOX');
  select * into event_row from scoring_authority.google_outbox_events
    where id = nullif(input->>'event_id', '')::uuid and tournament_id = '2026' for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'EVENT_NOT_FOUND'); end if;
  select * into checkpoint_row from scoring_authority.google_match_checkpoints
    where match_id = event_row.match_id for update;
  if event_row.status = 'DELIVERED' then
    return jsonb_build_object('ok', true, 'idempotent', true, 'checkpoint', to_jsonb(checkpoint_row));
  end if;
  if event_row.status <> 'PROCESSING' or worker = '' or event_row.claimed_by <> worker
     or event_row.lease_expires_at < now() then
    return jsonb_build_object('ok', false, 'code', 'OUTBOX_CLAIM_STALE');
  end if;
  if event_row.match_revision <> checkpoint_row.last_supabase_match_revision + 1 then
    return jsonb_build_object('ok', false, 'code', 'CHECKPOINT_ORDER_CONFLICT',
      'current_revision', checkpoint_row.last_supabase_match_revision);
  end if;
  if coalesce(input->>'verified_fingerprint', '') !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'code', 'OUTBOX_READBACK_FINGERPRINT_REQUIRED');
  end if;
  update scoring_authority.google_outbox_events set
    status = 'DELIVERED', delivered_at = now(), lease_expires_at = null,
    claimed_by = null, last_error_code = null, last_error_safe = null
  where id = event_row.id;
  update scoring_authority.google_match_checkpoints set
    last_supabase_match_revision = event_row.match_revision,
    google_match_updated_at = nullif(input->>'google_match_updated_at', '')::timestamptz,
    google_match_revision = coalesce((input->>'google_match_revision')::bigint, google_match_revision),
    google_hole_revisions = case when event_row.hole_number is null then google_hole_revisions
      else google_hole_revisions || jsonb_build_object(event_row.hole_number::text,
        coalesce((input->>'google_hole_revision')::bigint, event_row.hole_revision)) end,
    last_outbox_event_id = event_row.id,
    verified_fingerprint = input->>'verified_fingerprint',
    verified_at = now(), updated_at = now()
  where match_id = event_row.match_id returning * into checkpoint_row;
  return jsonb_build_object('ok', true, 'idempotent', false, 'checkpoint', to_jsonb(checkpoint_row));
end;
$_$;


ALTER FUNCTION public.complete_production_google_outbox(input jsonb) OWNER TO postgres;

