--
-- Name: complete_production_odds_calculation_job(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_odds_calculation_job(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    AS $_$
declare
  job text := lower(coalesce(input->>'job_id', ''));
  claim uuid := nullif(input->>'claim_token', '')::uuid;
  result_hash text := lower(coalesce(input->>'result_fingerprint', ''));
  retained scoring_authority.odds_calculation_jobs%rowtype;
  config scoring_authority.odds_input_configurations%rowtype;
  canonical_value jsonb;
  completion_publication_status text := case
    when input->>'operation_mode' = 'STEP11_REHEARSAL' then 'REHEARSAL_ONLY'
    else 'READY'
  end;
begin
  perform production_control.assert_production_odds_calculation_scope(input, true);
  if job !~ '^[0-9a-f]{64}$' or claim is null
     or result_hash !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(input->'result_payload') <> 'object'
     or jsonb_typeof(input->'result_fingerprint_payload') <> 'object'
     or coalesce(input->>'result_canonical_json', '') = '' then
    raise exception using errcode = '22023',
      message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_RESULT_REQUIRED';
  end if;
  begin
    canonical_value := (input->>'result_canonical_json')::jsonb;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_CANONICAL_JSON_INVALID';
  end;
  if canonical_value is distinct from input->'result_fingerprint_payload'
     or input->'result_fingerprint_payload'
          is distinct from (input->'result_payload') - 'publishedAt'
     or encode(extensions.digest(input->>'result_canonical_json', 'sha256'), 'hex')
          <> result_hash then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_RESULT_FINGERPRINT_MISMATCH';
  end if;

  select * into retained from scoring_authority.odds_calculation_jobs
  where job_id = job for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_JOB_NOT_FOUND');
  end if;
  perform production_control.assert_production_odds_retained_job_scope(
    input, to_jsonb(retained)
  );

  config := production_control.current_production_odds_inputs(
    input || jsonb_build_object(
      'input_configuration_id', retained.input_configuration_id,
      'configuration_revision', retained.source_revision->>'configuration_revision',
      'settings_fingerprint', retained.settings_fingerprint,
      'effective_settings_fingerprint', retained.effective_settings_fingerprint,
      'input_bundle_fingerprint', retained.input_bundle_fingerprint,
      'source_revision', retained.source_revision
    )
  );
  if retained.input_configuration_id <> config.id
     or retained.input_bundle_fingerprint <> config.bundle_fingerprint then
    update scoring_authority.odds_calculation_jobs
    set status = 'SUPERSEDED', publication_status = 'STALE',
        superseded_at = now(), claim_token = null, lease_owner = null,
        lease_expires_at = null,
        last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
        last_error_safe = 'Canonical Production calculation inputs advanced.',
        updated_at = now()
    where job_id = job;
    return jsonb_build_object(
      'ok', false, 'code', 'ODDS_CALCULATION_JOB_SUPERSEDED',
      'retryable', false, 'publication_created', false, 'mirror_created', false
    );
  end if;
  if retained.status = 'SUCCEEDED' then
    if retained.result_fingerprint = result_hash
       and retained.publication_status = completion_publication_status then
      return jsonb_build_object(
        'ok', true, 'duplicate', true, 'job_id', job,
        'result_fingerprint', result_hash,
        'publication_status', retained.publication_status,
        'publication_eligible', input->>'operation_mode' = 'PRODUCTION_CUTOVER',
        'publication_created', false, 'mirror_created', false
      );
    end if;
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_RESULT_CONFLICT');
  end if;
  if retained.status <> 'RUNNING'
     or retained.claim_token is distinct from claim
     or retained.lease_expires_at <= now() then
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_CLAIM_STALE');
  end if;
  if retained.completed_iterations <> retained.total_iterations then
    return jsonb_build_object('ok', false, 'code', 'ODDS_CALCULATION_INCOMPLETE');
  end if;

  update scoring_authority.odds_calculation_jobs
  set status = 'SUCCEEDED',
      publication_status = completion_publication_status,
      publication_reference = '{}'::jsonb,
      result_payload = input->'result_payload',
      result_fingerprint = result_hash,
      output_payload_bytes = greatest(
        0, coalesce((input->>'output_payload_bytes')::integer, 0)
      ),
      resource_metrics = coalesce(input->'resource_metrics', resource_metrics),
      claim_token = null, lease_owner = null, lease_expires_at = null,
      completed_at = now(), updated_at = now(),
      last_error_code = null, last_error_safe = null
  where job_id = job returning * into retained;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    case when input->>'operation_mode' = 'STEP11_REHEARSAL'
      then 'PRODUCTION_ODDS_REHEARSAL_CALCULATION_SUCCEEDED'
      else 'PRODUCTION_ODDS_CALCULATION_SUCCEEDED' end,
    'CHAMPIONSHIP_ODDS_CALCULATION', '2026', retained.requested_by,
    job, 'SUCCEEDED', jsonb_build_object(
      'job_id', job, 'phase', retained.phase,
      'iterations', retained.total_iterations,
      'result_fingerprint', result_hash,
      'checkpoint_count', retained.checkpoint_count,
      'attempt_count', retained.attempt_count,
      'operation_mode', retained.production_operation_mode,
      'calculation_completed', true,
      'publication_status', retained.publication_status,
      'publication_eligible', retained.production_operation_mode = 'PRODUCTION_CUTOVER',
      'publication_created', false, 'mirror_created', false
    )
  );
  return jsonb_build_object(
    'ok', true, 'duplicate', false, 'job_id', job,
    'result_fingerprint', result_hash,
    'checkpoint_count', retained.checkpoint_count,
    'attempt_count', retained.attempt_count,
    'publication_status', retained.publication_status,
    'publication_eligible', retained.production_operation_mode = 'PRODUCTION_CUTOVER',
    'publication_created', false, 'mirror_created', false
  );
exception when sqlstate 'P0001' then
  if sqlerrm = 'PRODUCTION_ODDS_INPUT_REVISION_STALE' then
    update scoring_authority.odds_calculation_jobs
    set status = 'SUPERSEDED', publication_status = 'STALE',
        superseded_at = now(), claim_token = null, lease_owner = null,
        lease_expires_at = null,
        last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
        last_error_safe = 'Canonical Production calculation inputs advanced.',
        updated_at = now()
    where job_id = job and status in ('PENDING', 'RUNNING', 'RETRYABLE', 'SUCCEEDED')
      and production_operation_mode = input->>'operation_mode'
      and production_deployment_commit = input->>'deployment_commit'
      and production_candidate_hostname is not distinct from
        nullif(input->>'candidate_hostname', '');
    return jsonb_build_object(
      'ok', false, 'code', 'ODDS_CALCULATION_JOB_SUPERSEDED',
      'retryable', false, 'publication_created', false, 'mirror_created', false
    );
  end if;
  raise;
end;
$_$;


ALTER FUNCTION public.complete_production_odds_calculation_job(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_participant_first_login(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_participant_first_login(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $$
declare resource production_control.resource_scope%rowtype;
declare claim participant_identity.production_participant_enrollment_claims%rowtype;
declare auth_user auth.users%rowtype;
declare target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
declare contact participant_identity.participant_identity_contacts%rowtype;
begin
  resource := production_control.assert_production_participant_identity_cutover();
  select * into claim from participant_identity.production_participant_enrollment_claims
    where claim_id = nullif(input->>'claim_id', '')::uuid for update;
  if not found or claim.tournament_id <> '2026' or target_user is null then
    raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_CLAIM_REQUIRED';
  end if;
  if claim.status = 'CONSUMED' then
    if claim.auth_user_id <> target_user or not exists (
      select 1 from participant_identity.user_player_links
      where auth_user_id = target_user and player_id = claim.player_id and status = 'PENDING'
    ) then raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_DRIFT'; end if;
    return jsonb_build_object('ok', true, 'playerId', claim.player_id,
      'authUserId', target_user, 'idempotent', true);
  end if;
  if claim.status <> 'PENDING' or claim.expires_at <= now() then
    raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_CLAIM_INACTIVE';
  end if;
  select * into auth_user from auth.users where id = target_user;
  if not found or auth_user.email_confirmed_at is not null
     or encode(extensions.digest(lower(btrim(coalesce(auth_user.email, '')))::text, 'sha256'), 'hex')
       <> claim.email_identity_hash
     or auth_user.raw_app_meta_data->>'provisioning_scope' <> 'production_controlled_first_login'
     or auth_user.raw_app_meta_data->>'player_id' <> claim.player_id
     or auth_user.raw_app_meta_data->>'tournament_id' <> '2026'
     or (select count(*) from auth.users
       where lower(btrim(coalesce(email, ''))) = lower(btrim(auth_user.email))) <> 1 then
    raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_AUTH_USER_SCOPE_MISMATCH';
  end if;
  select * into contact from participant_identity.participant_identity_contacts
    where tournament_id = '2026' and player_id = claim.player_id and identity_active
      and configuration_revision = claim.source_configuration_revision
      and source_workbook_id = resource.google_workbook_id
      and encode(extensions.digest(email_normalized::text, 'sha256'), 'hex') = claim.email_identity_hash;
  if not found or exists (select 1 from participant_identity.user_player_links
      where auth_user_id = target_user or (player_id = claim.player_id and status in ('PENDING','ACTIVE','SUSPENDED')))
     or exists (select 1 from participant_identity.participant_auth_identifiers
      where normalized_value_private = contact.email_normalized
        and status in ('ELIGIBLE','VERIFICATION_PENDING','VERIFIED')) then
    raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_IDENTITY_COLLISION';
  end if;
  insert into participant_identity.user_player_links (
    auth_user_id, player_id, status, link_method, email_identity_hash, linked_by
  ) values (
    target_user, claim.player_id, 'PENDING', 'PRODUCTION_CONTROLLED_FIRST_LOGIN',
    claim.email_identity_hash, 'production-controlled-first-login'
  );
  insert into participant_identity.participant_auth_identifiers (
    player_id, auth_user_id, identifier_type, normalized_value_private, status,
    source_system, source_tournament_id, source_configuration_revision, created_by, updated_by
  ) values (
    claim.player_id, target_user, 'EMAIL', contact.email_normalized, 'VERIFICATION_PENDING',
    'PRODUCTION_APPROVED_PARTICIPANT_IDENTITY', '2026', contact.configuration_revision,
    'production-controlled-first-login', 'production-controlled-first-login'
  );
  update participant_identity.production_participant_enrollment_claims set
    status = 'CONSUMED', auth_user_id = target_user, consumed_at = now(), updated_at = now()
  where claim_id = claim.claim_id;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_name, request_id, safe_metadata
  ) values (
    'PRODUCTION_PARTICIPANT_AUTH_USER_PREPARED', '2026', target_user, claim.player_id,
    'production-controlled-first-login', claim.claim_id::text,
    jsonb_build_object('rawIdentifierStoredInAudit', false, 'emailConfirmed', false,
      'participantAuthorityChanged', false)
  );
  return jsonb_build_object('ok', true, 'playerId', claim.player_id,
    'authUserId', target_user, 'idempotent', false);
end;
$$;


ALTER FUNCTION public.complete_production_participant_first_login(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_scorecard_archive_job(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_scorecard_archive_job(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  job_row scoring_authority.scorecard_archive_jobs%rowtype;
  match_row scoring_authority.matches%rowtype;
  snapshot_row scoring_authority.finalized_scorecard_snapshots%rowtype;
  newer_job scoring_authority.scorecard_archive_jobs%rowtype;
  requested_status text := upper(coalesce(input->>'verified_status', ''));
begin
  perform production_control.assert_production_scoring_runtime(input, 'ROUND_SCORECARDS_ARCHIVE');
  select * into job_row from scoring_authority.scorecard_archive_jobs
    where job_id = nullif(input->>'job_id', '')::uuid and tournament_id = '2026' for update;
  if not found or job_row.status <> 'PROCESSING'
     or job_row.claim_token <> nullif(input->>'claim_token', '')::uuid
     or job_row.claimed_by <> left(coalesce(input->>'worker_id', ''), 160)
     or job_row.lease_expires_at < now() then
    return jsonb_build_object('ok', false, 'code', 'ARCHIVE_CLAIM_STALE');
  end if;
  select * into newer_job from scoring_authority.scorecard_archive_jobs
    where match_id = job_row.match_id and match_revision > job_row.match_revision
    order by match_revision desc limit 1;
  if found then
    update scoring_authority.scorecard_archive_jobs set
      status = 'SUPERSEDED', claim_token = null, claimed_by = null,
      lease_expires_at = null, updated_at = now() where job_id = job_row.job_id;
    update scoring_authority.scorecard_archive_jobs set
      status = 'RETRYABLE', available_at = now(), verified_at = null, updated_at = now()
      where job_id = newer_job.job_id and status in ('VERIFIED', 'PENDING', 'RETRYABLE');
    return jsonb_build_object('ok', false, 'code', 'ARCHIVE_STALE_WORKER_REQUEUED');
  end if;
  select * into match_row from scoring_authority.matches where match_id = job_row.match_id;
  select * into snapshot_row from scoring_authority.finalized_scorecard_snapshots where snapshot_id = job_row.snapshot_id;
  if snapshot_row.snapshot_id is null
     or coalesce(input->>'source_fingerprint', '') <> job_row.source_fingerprint
     or coalesce(input->>'archive_payload_hash', '') <> job_row.archive_payload_hash
     or coalesce((input->>'snapshot_revision')::bigint, -1) <> job_row.snapshot_revision
     or coalesce((input->>'finalized_match_revision')::bigint, -1) <> job_row.match_revision
     or coalesce(input->>'google_readback_hash', '') !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(coalesce(input->'expected_logical_identities', 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(input->'google_row_numbers', 'null'::jsonb)) <> 'array' then
    return jsonb_build_object('ok', false, 'code', 'ARCHIVE_CHECKPOINT_PAYLOAD_INVALID');
  end if;
  if (job_row.event_type = 'SCORECARD_ARCHIVE_UPSERT'
      and (match_row.status <> 'FINAL' or snapshot_row.state <> 'CURRENT' or requested_status <> 'VERIFIED'))
     or (job_row.event_type = 'SCORECARD_ARCHIVE_INVALIDATE'
      and (match_row.status = 'FINAL' or requested_status <> 'INVALIDATED')) then
    update scoring_authority.scorecard_archive_jobs set
      status = 'SUPERSEDED', claim_token = null, claimed_by = null,
      lease_expires_at = null, updated_at = now() where job_id = job_row.job_id;
    return jsonb_build_object('ok', false, 'code', 'ARCHIVE_LIFECYCLE_SUPERSEDED');
  end if;
  update scoring_authority.scorecard_archive_jobs set
    status = 'VERIFIED', verified_at = now(), claim_token = null, claimed_by = null,
    lease_expires_at = null, last_error_code = null, last_error_safe = null, updated_at = now()
  where job_id = job_row.job_id;
  insert into scoring_authority.scorecard_archive_checkpoints (
    match_id, tournament_id, current_snapshot_id, finalized_snapshot_revision,
    finalized_match_revision, source_fingerprint, archive_payload_hash,
    expected_logical_identities, google_row_numbers, google_readback_hash,
    status, last_job_id, last_error_code, last_error_safe, verified_at
  ) values (
    job_row.match_id, '2026', job_row.snapshot_id, job_row.snapshot_revision,
    job_row.match_revision, job_row.source_fingerprint, job_row.archive_payload_hash,
    input->'expected_logical_identities', input->'google_row_numbers', input->>'google_readback_hash',
    requested_status, job_row.job_id, null, null, now()
  ) on conflict (match_id) do update set
    tournament_id = excluded.tournament_id,
    current_snapshot_id = excluded.current_snapshot_id,
    finalized_snapshot_revision = excluded.finalized_snapshot_revision,
    finalized_match_revision = excluded.finalized_match_revision,
    source_fingerprint = excluded.source_fingerprint,
    archive_payload_hash = excluded.archive_payload_hash,
    expected_logical_identities = excluded.expected_logical_identities,
    google_row_numbers = excluded.google_row_numbers,
    google_readback_hash = excluded.google_readback_hash,
    status = excluded.status, last_job_id = excluded.last_job_id,
    last_error_code = null, last_error_safe = null,
    verified_at = excluded.verified_at, updated_at = now();
  return jsonb_build_object('ok', true, 'checkpoint',
    (select to_jsonb(checkpoint) from scoring_authority.scorecard_archive_checkpoints checkpoint
      where checkpoint.match_id = job_row.match_id));
end;
$_$;


ALTER FUNCTION public.complete_production_scorecard_archive_job(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_scoring_ingress(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_scoring_ingress(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  unresolved_count integer;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for share;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into lease
  from scoring_authority.scoring_ingress_leases value
  where value.lease_id = (input->>'lease_id')::uuid
  for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'code', 'PRODUCTION_SCORING_LEASE_NOT_FOUND_IDEMPOTENT',
      'idempotent', true
    );
  end if;
  if lease.protocol_version = 'ADMISSION_V2'
     and lease.resolution_state in ('ADMITTED', 'WRITE_STARTED') then
    update scoring_authority.scoring_ingress_leases
    set resolution_state = 'AMBIGUOUS', status = 'ACTIVE',
        outcome_reported_at = pg_catalog.now(), completed_at = null,
        last_error_code = 'LEGACY_COMPLETION_WITHOUT_OUTCOME_EVIDENCE'
    where lease_id = lease.lease_id
    returning * into lease;
  elsif lease.protocol_version = 'LEGACY_V1' and lease.status = 'ACTIVE' then
    -- Deliberately do not mark a legacy lease completed. It remains an explicit
    -- legacy blocker until a fresh provider boundary accounts for it.
    perform 1;
  end if;
  unresolved_count := production_control.scoring_admission_unresolved_count(
    gate.admission_generation_id
  ) + production_control.scoring_admission_legacy_blocker_count(
    gate.admission_enforced_at
  );
  update scoring_authority.ingress_gates
  set unresolved_client_queues = unresolved_count, updated_at = pg_catalog.now()
  where tournament_id = '2026';
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_SCORING_LEGACY_COMPLETION_AMBIGUOUS', 'SCORING_AUTHORITY', '2026',
    lease.actor_id, lease.request_fingerprint, 'BLOCKED',
    pg_catalog.jsonb_build_object(
      'lease_id', lease.lease_id,
      'protocol_version', lease.protocol_version,
      'resolution_state', lease.resolution_state,
      'active_or_unresolved_leases', unresolved_count
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_SCORING_LEGACY_COMPLETION_AMBIGUOUS',
    'lease_id', lease.lease_id,
    'resolution_state', case when lease.protocol_version = 'ADMISSION_V2'
      then 'AMBIGUOUS' else 'LEGACY_UNCLASSIFIED' end,
    'active_or_unresolved_leases', unresolved_count,
    'requires_reconciliation', true, 'idempotent', false
  );
end;
$$;


ALTER FUNCTION public.complete_production_scoring_ingress(input jsonb) OWNER TO postgres;

--
-- Name: complete_production_step11_scoring_rehearsal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_production_step11_scoring_rehearsal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_rehearsal', 'production_control', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  run production_rehearsal.scoring_runs%rowtype;
  evidence jsonb := input->'reconciliation';
  current_fingerprint text;
  existing_certification production_rehearsal.cleanup_certifications%rowtype;
begin
  run := production_rehearsal.assert_run(input);
  if run.status = 'CLEANED' then
    select * into strict existing_certification
    from production_rehearsal.cleanup_certifications value where value.run_id = run.run_id;
    if input->>'s3_fingerprint_after' <> existing_certification.s3_fingerprint_after
       or evidence->>'finalSupabaseFingerprint' <> existing_certification.synthetic_final_fingerprint
       or coalesce((evidence->>'duplicates')::integer,-1) <> 0
       or coalesce((evidence->>'unresolved')::integer,-1) <> 0
       or coalesce((evidence->>'lost')::integer,-1) <> 0 then
      raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_CLEANUP_CERTIFICATION_CONFLICT';
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'runId',run.run_id,
      'status','CLEANED','current2026Unchanged',true,'s3Unchanged',true,
      'externalGoogleWrites',0,'live2026Writes',0,'finalAuthority','GOOGLE');
  end if;
  if run.status <> 'ROLLED_BACK' or run.rehearsal_authority <> 'GOOGLE'
     or run.ingress_state <> 'PAUSED' then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_ROLLBACK_REQUIRED';
  end if;
  current_fingerprint := production_rehearsal.current_2026_fingerprint();
  if current_fingerprint <> run.current_2026_fingerprint_before
     or input->>'s3_fingerprint_after' <> run.s3_fingerprint_before
     or coalesce((evidence->>'duplicates')::integer,-1) <> 0
     or coalesce((evidence->>'unresolved')::integer,-1) <> 0
     or coalesce((evidence->>'lost')::integer,-1) <> 0
     or evidence->>'finalAuthorityState' <> 'GOOGLE'
     or evidence->>'finalSupabaseFingerprint' <> evidence->>'finalRollbackTargetFingerprint'
     or coalesce((evidence->>'externalGoogleWrites')::integer,-1) <> 0
     or coalesce((evidence->>'live2026Writes')::integer,-1) <> 0 then
    raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_CLEANUP_CERTIFICATION_FAILED';
  end if;
  insert into production_rehearsal.cleanup_certifications (
    run_id, synthetic_tournament_id, synthetic_final_fingerprint,
    s3_fingerprint_before, s3_fingerprint_after,
    current_2026_fingerprint_before, current_2026_fingerprint_after,
    supabase_authoritative_writes, already_mirrored, reconciled_writes,
    duplicate_writes, unresolved_writes, lost_writes, final_authority,
    external_google_writes, live_2026_writes, certified_by
  ) values (
    run.run_id, run.synthetic_tournament_id, evidence->>'finalSupabaseFingerprint',
    run.s3_fingerprint_before, input->>'s3_fingerprint_after',
    run.current_2026_fingerprint_before, current_fingerprint,
    (evidence->>'supabaseAuthoritativeWrites')::integer,
    (evidence->>'alreadyRepresentedInMirror')::integer,
    (evidence->>'successfullyReconciled')::integer, 0, 0, 0, 'GOOGLE', 0, 0,
    input->>'actor_id'
  );
  update production_rehearsal.scoring_runs set status='CLEANED',
    current_2026_fingerprint_after=current_fingerprint, completed_at=now()
  where run_id=run.run_id;
  return jsonb_build_object('ok',true,'runId',run.run_id,'status','CLEANED',
    'current2026Unchanged',true,'s3Unchanged',true,
    'externalGoogleWrites',0,'live2026Writes',0,'finalAuthority','GOOGLE');
end;
$$;


ALTER FUNCTION public.complete_production_step11_scoring_rehearsal(input jsonb) OWNER TO postgres;

--
-- Name: configure_production_calcutta_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_production_calcutta_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  current_value scoring_authority.calcutta_v1_current%rowtype;
  configuration_value scoring_authority.calcutta_v1_configuration_revisions%rowtype;
  publication_value scoring_authority.calcutta_v1_publication_revisions%rowtype;
  existing_response jsonb;
  response_value jsonb;
  manifest_value jsonb;
  configuration_fingerprint_value text;
  resource_fingerprint_value text;
  request_fingerprint_value text := pg_catalog.lower(
    coalesce(input->>'request_fingerprint', '')
  );
  payload_hash_value text := production_control.calcutta_v1_hash(input);
  actor_player text := pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  ));
  actor_auth_user uuid := nullif(
    input#>>'{authorization,auth_user_id}', ''
  )::uuid;
begin
  perform production_control.assert_production_calcutta_v1_runtime(input);
  perform production_control.assert_production_scoring_actor(input, true);
  existing_response := production_control.lookup_cutover_receipt(
    'CALCUTTA_V1_CONFIGURE', input
  );
  if existing_response is not null then return existing_response; end if;
  if request_fingerprint_value !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_INPUT_INVALID';
  end if;

  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026'
  for update;

  if current_value.configuration_revision <>
       coalesce((input->>'expected_configuration_revision')::bigint, -1)
     or (
       current_value.configuration_fingerprint is distinct from
         nullif(input->>'expected_configuration_fingerprint', '')
       and not (
         current_value.state = 'NOT_CONFIGURED'
         and current_value.configuration_revision = 1
         and current_value.auction_revision = 0
         and current_value.publication_revision = 0
         and nullif(input->>'expected_configuration_fingerprint', '') is null
       )
     ) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_CONFIGURATION_REVISION_CONFLICT';
  end if;
  if current_value.auction_revision <>
       coalesce((input->>'expected_auction_revision')::bigint, -1)
     or current_value.auction_fingerprint is distinct from
       nullif(input->>'expected_auction_fingerprint', '') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_AUCTION_REVISION_CONFLICT';
  end if;
  if current_value.publication_revision <>
       coalesce((input->>'expected_publication_revision')::bigint, -1) then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_PUBLICATION_REVISION_CONFLICT';
  end if;

  manifest_value :=
    production_control.build_production_calcutta_v1_configuration(input);
  configuration_fingerprint_value :=
    production_control.calcutta_v1_hash(manifest_value);
  resource_fingerprint_value := production_control.calcutta_v1_hash(
    pg_catalog.jsonb_build_object(
      'contract_version', 'production-calcutta-v1',
      'environment', 'PRODUCTION',
      'project_ref', resource.project_ref,
      'project_url', resource.project_url,
      'source_workbook_id', resource.google_workbook_id,
      'tournament_id', resource.current_tournament_id,
      'vercel_project_id', input->>'vercel_project_id',
      'vercel_team_id', input->>'vercel_team_id',
      'vercel_environment', 'production',
      'deployment_commit', activation.expected_deployment_commit,
      'authority_epoch_id', activation.authority_generation_id,
      'activation_revision', activation.activation_revision
    )
  );

  insert into scoring_authority.calcutta_v1_configuration_revisions (
    tournament_id, configuration_revision, contract_version, state,
    configuration_manifest, configuration_fingerprint,
    resource_fingerprint, activation_revision, authority_epoch_id,
    configured_by_player_id, configured_by_auth_user_id,
    request_fingerprint, request_payload_hash, configured_at
  ) values (
    '2026', current_value.configuration_revision + 1,
    'production-calcutta-v1', 'CONFIGURED', manifest_value,
    configuration_fingerprint_value, resource_fingerprint_value,
    activation.activation_revision, activation.authority_generation_id,
    actor_player, actor_auth_user, request_fingerprint_value,
    payload_hash_value, pg_catalog.now()
  ) returning * into configuration_value;

  insert into scoring_authority.calcutta_v1_publication_revisions (
    tournament_id, publication_revision, configuration_revision,
    auction_revision, configuration_fingerprint, auction_fingerprint,
    publication_state, action, actor_player_id, actor_auth_user_id,
    request_fingerprint, request_payload_hash, published_at
  ) values (
    '2026', current_value.publication_revision + 1,
    configuration_value.configuration_revision,
    current_value.auction_revision, configuration_fingerprint_value,
    current_value.auction_fingerprint, 'UNPUBLISHED',
    'CONFIGURATION_REPLACED', actor_player, actor_auth_user,
    production_control.calcutta_v1_hash(pg_catalog.jsonb_build_object(
      'operation', 'CONFIGURATION_REPLACED',
      'request_fingerprint', request_fingerprint_value
    )), payload_hash_value, null
  ) returning * into publication_value;

  update scoring_authority.calcutta_v1_recalculation_jobs
  set status = 'SUPERSEDED', claimed_by = null, claim_token = null,
      lease_expires_at = null, completed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' and status in ('PENDING', 'RUNNING');
  update scoring_authority.calcutta_v1_result_revisions
  set is_current = false, superseded_at = pg_catalog.now()
  where tournament_id = '2026' and is_current;

  update scoring_authority.calcutta_v1_current
  set configuration_revision_id = configuration_value.configuration_revision_id,
      configuration_revision = configuration_value.configuration_revision,
      configuration_fingerprint = configuration_fingerprint_value,
      publication_revision_id = publication_value.publication_revision_id,
      publication_revision = publication_value.publication_revision,
      publication_state = 'UNPUBLISHED',
      state = case when current_value.auction_revision > 0
        then 'AUCTION_COMPLETE' else 'CONFIGURED' end,
      result_revision = 0,
      updated_at = pg_catalog.now()
  where tournament_id = '2026';

  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'PRODUCTION_CALCUTTA_V1_CONFIGURED', actor_player,
    pg_catalog.jsonb_build_object(
      'configuration_revision', configuration_value.configuration_revision,
      'configuration_fingerprint', configuration_fingerprint_value,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'publication_revision', publication_value.publication_revision,
      'publication_state', 'UNPUBLISHED',
      'payout_rounding', 'NONE',
      'authority_changed', false
    )
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_CALCUTTA_V1_CONFIGURED', 'CALCUTTA', '2026',
    actor_player, request_fingerprint_value, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'configuration_revision', configuration_value.configuration_revision,
      'configuration_fingerprint', configuration_fingerprint_value,
      'auction_revision', current_value.auction_revision,
      'publication_revision', publication_value.publication_revision,
      'publication_state', 'UNPUBLISHED'
    )
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_CALCUTTA_V1_CONFIGURED',
    'state', case when current_value.auction_revision > 0
      then 'AUCTION_COMPLETE' else 'CONFIGURED' end,
    'publication_state', 'UNPUBLISHED',
    'configuration_revision', configuration_value.configuration_revision,
    'configuration_fingerprint', configuration_fingerprint_value,
    'auction_revision', current_value.auction_revision,
    'auction_fingerprint', current_value.auction_fingerprint,
    'publication_revision', publication_value.publication_revision,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'CALCUTTA_V1_CONFIGURE', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.configure_production_calcutta_v1(input jsonb) OWNER TO postgres;

