--
-- Name: configure_production_odds_calculation_runtime(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.configure_production_odds_calculation_runtime(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  resource production_control.resource_scope%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  runtime production_control.odds_calculation_runtime%rowtype;
  requested_enabled boolean;
  expected_runtime_enabled boolean;
  expected_runtime_revision bigint;
  previous_runtime_revision bigint;
  previous_runtime_enabled boolean;
  request_fingerprint_value text := lower(coalesce(input->>'request_fingerprint', ''));
  mode text := upper(coalesce(input->>'operation_mode', ''));
  phase text := upper(coalesce(input->>'cutover_phase', ''));
  actor text := left(coalesce(nullif(input->>'actor_id', ''), ''), 160);
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);

  if jsonb_typeof(input->'enabled') <> 'boolean'
     or jsonb_typeof(input->'expected_runtime_enabled') <> 'boolean'
     or jsonb_typeof(input->'expected_runtime_revision') <> 'number'
     or (input->>'expected_runtime_revision') !~ '^(0|[1-9][0-9]*)$'
     or jsonb_typeof(input->'expected_activation_revision') <> 'number'
     or (input->>'expected_activation_revision') !~ '^(0|[1-9][0-9]*)$'
     or request_fingerprint_value !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_ODDS_RUNTIME_TRANSITION_EXPECTATION_REQUIRED';
  end if;

  requested_enabled := (input->>'enabled')::boolean;
  expected_runtime_enabled := (input->>'expected_runtime_enabled')::boolean;
  expected_runtime_revision := (input->>'expected_runtime_revision')::bigint;

  if input->>'vercel_project_id'
       is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'canonical_domain' is distinct from 'https://baggerinv.com'
     or coalesce((input->>'tournament_year')::integer, 0) <> 2026
     or input->>'worker_name' is distinct from 'ODDS_CALCULATION'
     or actor = ''
     or (
       mode = 'STEP11_REHEARSAL'
       and input->>'operation' is distinct from case when requested_enabled
         then 'ENABLE_STEP11_ODDS_REHEARSAL_RUNTIME'
         else 'DISABLE_STEP11_ODDS_REHEARSAL_RUNTIME'
       end
     ) then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_ODDS_EXACT_SCOPE_REQUIRED';
  end if;

  -- Preserve the established lock order, then lock the runtime nonce itself.
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict runtime
  from production_control.odds_calculation_runtime
  where scope_key = 'BAGGER_INV_PRODUCTION' for update;

  if activation.activation_revision
       <> (input->>'expected_activation_revision')::bigint then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_ACTIVATION_REVISION_CONFLICT';
  end if;
  if runtime.runtime_revision <> expected_runtime_revision
     or runtime.enabled is distinct from expected_runtime_enabled then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ODDS_RUNTIME_TRANSITION_CONFLICT';
  end if;

  previous_runtime_revision := runtime.runtime_revision;
  previous_runtime_enabled := runtime.enabled;

  if requested_enabled then
    perform production_control.assert_production_odds_calculation_scope(input, false);
    update production_control.odds_calculation_runtime
    set enabled = true, operation_mode = mode, cutover_phase = phase,
        deployment_commit = activation.expected_deployment_commit,
        activation_revision = activation.activation_revision,
        candidate_hostname = nullif(input->>'candidate_hostname', ''),
        configured_by = actor, configured_at = now(), updated_at = now(),
        runtime_revision = runtime_revision + 1,
        last_transition_request_fingerprint = request_fingerprint_value
    where scope_key = 'BAGGER_INV_PRODUCTION'
      and runtime_revision = expected_runtime_revision
      and enabled is not distinct from expected_runtime_enabled
    returning * into runtime;
  else
    if not runtime.enabled
       or runtime.operation_mode <> mode
       or runtime.activation_revision is distinct from activation.activation_revision then
      raise exception using errcode = '40001',
        message = 'PRODUCTION_ODDS_RUNTIME_DISABLE_STATE_CONFLICT';
    end if;
    update production_control.odds_calculation_runtime
    set enabled = false, operation_mode = 'DORMANT', cutover_phase = null,
        deployment_commit = null, activation_revision = null,
        candidate_hostname = null, configured_by = actor,
        configured_at = now(), updated_at = now(),
        runtime_revision = runtime_revision + 1,
        last_transition_request_fingerprint = request_fingerprint_value
    where scope_key = 'BAGGER_INV_PRODUCTION'
      and runtime_revision = expected_runtime_revision
      and enabled is not distinct from expected_runtime_enabled
    returning * into runtime;
  end if;

  if not found or runtime.runtime_revision <> previous_runtime_revision + 1 then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_ODDS_RUNTIME_TRANSITION_CONFLICT';
  end if;

  update production_control.worker_controls
  set enabled = requested_enabled, scheduler_installed = false,
      google_writes_allowed = false, last_verified_at = now(),
      metadata = metadata || jsonb_build_object(
        'contract_version', runtime.contract_version,
        'operation_mode', runtime.operation_mode,
        'cutover_phase', runtime.cutover_phase,
        'deployment_commit', runtime.deployment_commit,
        'runtime_revision', runtime.runtime_revision,
        'configured_by', actor,
        'configured_at', now(),
        'publication_separate', true,
        'google_mirror_separate', true
      )
  where worker_name = 'ODDS_CALCULATION';
  update production_control.worker_contracts
  set operation_allowed = requested_enabled, scheduler_installed = false,
      authoritative_write_allowed = false
  where worker_name = 'ODDS_CALCULATION';
  update production_control.resource_scope
  set workers_enabled = exists (
    select 1 from production_control.worker_controls where enabled
  )
  where scope_key = 'BAGGER_INV_PRODUCTION';

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    case when requested_enabled
      then 'PRODUCTION_ODDS_CALCULATION_WORKER_ENABLED'
      else 'PRODUCTION_ODDS_CALCULATION_WORKER_DISABLED' end,
    'CHAMPIONSHIP_ODDS_CALCULATION', '2026', actor,
    request_fingerprint_value, 'SUCCEEDED',
    jsonb_build_object(
      'enabled', requested_enabled, 'operation_mode', runtime.operation_mode,
      'cutover_phase', runtime.cutover_phase, 'scheduler_installed', false,
      'previous_runtime_revision', previous_runtime_revision,
      'runtime_revision', runtime.runtime_revision,
      'previous_runtime_enabled', previous_runtime_enabled,
      'authoritative_write_allowed', false, 'google_writes_allowed', false,
      'publication_created', false, 'mirror_created', false
    )
  );
  return jsonb_build_object(
    'ok', true, 'enabled', runtime.enabled,
    'operation_mode', runtime.operation_mode,
    'cutover_phase', runtime.cutover_phase,
    'deployment_commit', runtime.deployment_commit,
    'previous_runtime_revision', previous_runtime_revision,
    'runtime_revision', runtime.runtime_revision,
    'previous_runtime_enabled', previous_runtime_enabled,
    'scheduler_installed', false, 'authoritative_write_allowed', false,
    'publication_created', false, 'mirror_created', false
  );
end;
$_$;


ALTER FUNCTION public.configure_production_odds_calculation_runtime(input jsonb) OWNER TO postgres;

--
-- Name: consume_production_vercel_provider_attestation_challenge(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_production_vercel_provider_attestation_challenge(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  provider_claim jsonb := input->'provider_attestation';
  v3_input jsonb;
  response_value jsonb;
  routing_audit jsonb;
  alias_capture production_control.vercel_provider_alias_captures%rowtype;
begin
  perform production_control.assert_exact_vercel_routing_rule_audit(
    provider_claim
  );
  v3_input := pg_catalog.jsonb_set(
    input,
    '{provider_attestation}',
    provider_claim - array[
      'routing_rule_hostname_operator',
      'routing_rule_canonical_hostname',
      'routing_rule_earlier_active_bypass_rule_count',
      'routing_rule_global_invocation_quiescence_proved',
      'routing_rule_candidate_control_host_count',
      'routing_rule_candidate_control_hosts_fingerprint',
      'routing_rule_canonical_apex_safe_method_count',
      'routing_rule_canonical_apex_safe_methods_fingerprint',
      'routing_rule_canonical_apex_safe_method_writer_route_count',
      'routing_rule_canonical_apex_safe_method_writer_routes_fingerprint',
      'candidate_alias_origin',
      'candidate_immutable_origin',
      'alias_inventory_count',
      'alias_inventory_fingerprint',
      'alias_inventory_records',
      'alias_pagination_page_count',
      'alias_pagination_fingerprint'
    ],
    true
  );
  response_value :=
    public.consume_vercel_provider_attestation_v3_base(v3_input);
  routing_audit :=
    production_control.bind_current_vercel_routing_rule_audit(
      'ATTESTATION', (response_value->>'attestation_id')::uuid, true,
      provider_claim
    );
  alias_capture := production_control.record_current_vercel_alias_capture(
    (response_value->>'attestation_id')::uuid, provider_claim
  );
  return response_value || routing_audit || pg_catalog.jsonb_build_object(
    'alias_inventory_count', alias_capture.alias_inventory_count,
    'alias_inventory_fingerprint', alias_capture.alias_inventory_fingerprint,
    'alias_inventory_records', alias_capture.alias_inventory_records,
    'alias_pagination_page_count', alias_capture.alias_pagination_page_count,
    'alias_pagination_fingerprint', alias_capture.alias_pagination_fingerprint
  );
end;
$$;


ALTER FUNCTION public.consume_production_vercel_provider_attestation_challenge(input jsonb) OWNER TO postgres;

--
-- Name: consume_vercel_provider_attestation_v3_base(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.consume_vercel_provider_attestation_v3_base(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
  begin_attestation production_control.vercel_provider_attestations%rowtype;
  reserved production_control.vercel_provider_attestations%rowtype;
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
  consume_request_identifier uuid;
  observed_at_value timestamptz;
  reserved_at_value timestamptz := pg_catalog.now();
  payload_hash text := production_control.cutover_payload_hash(input);
  normalized_live_inventory jsonb;
  live_inventory_fingerprint text;
  provider_claim jsonb := input->'provider_attestation';
  allowed_provider_keys text[] := array[
    'attestation_id', 'attestation_fingerprint',
    'signer_key_fingerprint', 'signer_key_version', 'stage', 'purpose',
    'challenge_id', 'challenge_request_fingerprint', 'operation_request_id',
    'request_fingerprint', 'signature_verified', 'vercel_project_id',
    'vercel_team_id', 'candidate_deployment_id',
    'candidate_deployment_commit', 'candidate_deployment_target',
    'routing_rule_id', 'routing_rule_config_version', 'routing_rule_etag',
    'routing_rule_fingerprint', 'routing_rule_pending_draft_change_count',
    'live_origin_inventory_count',
    'live_origin_inventory_fingerprint',
    'provider_inventory_schema',
    'retained_origin_inventory_count',
    'retained_origin_inventory_fingerprint',
    'retained_provider_inventory_count',
    'retained_provider_inventory_fingerprint',
    'live_provider_inventory_count',
    'live_provider_inventory_fingerprint',
    'routing_rule_all_method_fence_required_host_count',
    'routing_rule_all_method_fence_required_hosts_fingerprint',
    'routing_rule_all_method_fence_required_path_count',
    'routing_rule_all_method_fence_required_paths_fingerprint',
    'redacted_environment_scope_fingerprint',
    'credential_confinement_evidence_schema',
    'credential_confinement_record_count',
    'credential_confinement_records_fingerprint',
    'credential_confinement_evidence_fingerprint', 'provider_observed_at'
  ];
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if coalesce(input->>'consume_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'challenge_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'challenge_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.upper(coalesce(input->>'purpose', ''))
       not in ('REHEARSAL', 'CUTOVER')
     or pg_catalog.upper(coalesce(input->>'stage', ''))
       not in ('BEGIN', 'FINALIZE')
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or pg_catalog.jsonb_typeof(input->'origin_inventory')
       is distinct from 'array'
     or pg_catalog.jsonb_typeof(input->'live_origin_inventory')
       is distinct from 'array'
     or pg_catalog.jsonb_typeof(provider_claim) is distinct from 'object'
     or not (provider_claim ?& allowed_provider_keys)
     or (provider_claim - allowed_provider_keys) is distinct from '{}'::jsonb
     or coalesce(provider_claim->>'attestation_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(provider_claim->>'attestation_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(provider_claim->>'signer_key_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or provider_claim->>'signer_key_version' is distinct from
       'STEP11_6_VERCEL_ATTESTER_V1'
     or provider_claim->>'signature_verified' is distinct from 'true'
     or coalesce(provider_claim->>'request_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(provider_claim->>'routing_rule_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(
       provider_claim->'routing_rule_pending_draft_change_count'
     ) is distinct from 'number'
     or provider_claim->>'routing_rule_pending_draft_change_count'
       is distinct from '0'
     or coalesce(provider_claim->>'live_origin_inventory_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(provider_claim->>'redacted_environment_scope_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(
       provider_claim->'live_origin_inventory_count'
     ) is distinct from 'number'
     or coalesce(provider_claim->>'live_origin_inventory_count', '')
       !~ '^[0-9]+$'
     or coalesce(provider_claim->>'provider_observed_at', '') = ''
     or (provider_claim->>'routing_rule_etag' is not null and (
       pg_catalog.btrim(provider_claim->>'routing_rule_etag') = ''
       or pg_catalog.length(provider_claim->>'routing_rule_etag') > 512
     )) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CONSUME_INPUT_INVALID';
  end if;
  perform production_control.assert_current_provider_inventory_v3(
    provider_claim, true, true
  );

  consume_request_identifier := (input->>'consume_request_id')::uuid;
  observed_at_value := (provider_claim->>'provider_observed_at')::timestamptz;
  perform production_control.assert_exact_vercel_origin_inventory(
    input->'origin_inventory'
  );

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.challenge_id = (input->>'challenge_id')::uuid
    and value.challenge_request_id = (input->>'challenge_request_id')::uuid
    and value.operation_request_id = (input->>'operation_request_id')::uuid
    and value.evidence_request_id = (input->>'evidence_request_id')::uuid
    and value.stage = pg_catalog.upper(input->>'stage')
  for update;

  if challenge.status = 'CONSUMED' then
    select * into strict reserved
    from production_control.vercel_provider_attestations value
    where value.attestation_id = challenge.consumed_attestation_id;
    if challenge.consume_request_id is distinct from consume_request_identifier
       or challenge.consume_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or challenge.consume_payload_hash is distinct from payload_hash
       or reserved.attestation_id is distinct from
         (provider_claim->>'attestation_id')::uuid
       or reserved.attestation_fingerprint is distinct from
         provider_claim->>'attestation_fingerprint' then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CONSUME_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.vercel_provider_attestation_response(
      reserved, true
    );
  end if;
  if challenge.status = 'ABANDONED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDONED_TERMINAL';
  end if;

  if challenge.expires_at < reserved_at_value then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_EXPIRED';
  end if;
  if challenge.purpose is distinct from
       pg_catalog.upper(input->>'purpose')
     or challenge.candidate_deployment_id is distinct from
       provider_claim->>'candidate_deployment_id'
     or challenge.candidate_deployment_commit is distinct from
       pg_catalog.lower(provider_claim->>'candidate_deployment_commit')
     or challenge.candidate_deployment_target is distinct from
       provider_claim->>'candidate_deployment_target'
     or challenge.authenticated_actor_fingerprint is distinct from
       input->>'authenticated_actor_fingerprint'
     or challenge.actor_id is distinct from
       pg_catalog.left(input->>'actor_id', 160)
     or challenge.vercel_project_id is distinct from
       provider_claim->>'vercel_project_id'
     or challenge.vercel_team_id is distinct from
       provider_claim->>'vercel_team_id'
     or challenge.routing_rule_id is distinct from
       provider_claim->>'routing_rule_id'
     or challenge.routing_rule_config_version is distinct from
       provider_claim->>'routing_rule_config_version'
     or challenge.challenge_id is distinct from
       (provider_claim->>'challenge_id')::uuid
     or challenge.challenge_request_fingerprint is distinct from
       provider_claim->>'challenge_request_fingerprint'
     or challenge.operation_request_id is distinct from
       (provider_claim->>'operation_request_id')::uuid
     or challenge.stage is distinct from provider_claim->>'stage'
     or challenge.purpose is distinct from provider_claim->>'purpose'
     or provider_claim->>'candidate_deployment_id' is distinct from
       input->>'candidate_deployment_id'
     or pg_catalog.lower(provider_claim->>'candidate_deployment_commit')
       is distinct from pg_catalog.lower(input->>'candidate_deployment_commit')
     or provider_claim->>'candidate_deployment_target' is distinct from
       input->>'candidate_deployment_target' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_MISMATCH';
  end if;
  if observed_at_value < reserved_at_value - interval '120 seconds'
     or observed_at_value > reserved_at_value + interval '30 seconds' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_STALE';
  end if;

  perform production_control.assert_exact_vercel_live_inventory(
    input->'origin_inventory', input->'live_origin_inventory',
    challenge.candidate_deployment_id,
    challenge.candidate_deployment_commit,
    challenge.candidate_immutable_origin,
    challenge.candidate_deployment_target
  );
  normalized_live_inventory :=
    production_control.normalized_vercel_origin_inventory(
      input->'live_origin_inventory'
    );
  live_inventory_fingerprint :=
    production_control.vercel_origin_inventory_fingerprint(
      normalized_live_inventory
    );
  if (provider_claim->>'live_origin_inventory_count')::integer is distinct from
       pg_catalog.jsonb_array_length(normalized_live_inventory)
     or (provider_claim->>'live_provider_inventory_count')::integer
       is distinct from pg_catalog.jsonb_array_length(normalized_live_inventory)
     or provider_claim->>'live_origin_inventory_fingerprint' is distinct from
       live_inventory_fingerprint then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_LIVE_INVENTORY_MISMATCH';
  end if;

  if challenge.stage = 'FINALIZE' then
    select * into strict evidence
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_request_id = challenge.evidence_request_id
    for update;
    select * into strict begin_attestation
    from production_control.vercel_provider_attestations value
    where value.evidence_request_id = challenge.evidence_request_id
      and value.stage = 'BEGIN'
      and value.status = 'BOUND';
    if evidence.status is distinct from 'DRAINING'
       or observed_at_value <= evidence.drain_started_at
       or begin_attestation.attestation_id =
         (provider_claim->>'attestation_id')::uuid
       or begin_attestation.challenge_id = challenge.challenge_id
       or begin_attestation.signer_key_fingerprint is distinct from
         provider_claim->>'signer_key_fingerprint'
       or begin_attestation.signer_key_version is distinct from
         provider_claim->>'signer_key_version'
       or begin_attestation.vercel_project_id is distinct from
         provider_claim->>'vercel_project_id'
       or begin_attestation.vercel_team_id is distinct from
         provider_claim->>'vercel_team_id'
       or begin_attestation.candidate_deployment_id is distinct from
         provider_claim->>'candidate_deployment_id'
       or begin_attestation.candidate_deployment_commit is distinct from
         pg_catalog.lower(provider_claim->>'candidate_deployment_commit')
       or begin_attestation.candidate_deployment_target is distinct from
         provider_claim->>'candidate_deployment_target'
       or begin_attestation.routing_rule_id is distinct from
         provider_claim->>'routing_rule_id'
       or begin_attestation.routing_rule_config_version is distinct from
         provider_claim->>'routing_rule_config_version'
       or begin_attestation.routing_rule_etag is distinct from
         provider_claim->>'routing_rule_etag'
       or begin_attestation.routing_rule_fingerprint is distinct from
         provider_claim->>'routing_rule_fingerprint'
       or begin_attestation.routing_rule_pending_draft_change_count is distinct from
         (provider_claim->>'routing_rule_pending_draft_change_count')::integer
       or begin_attestation.live_origin_inventory is distinct from
         normalized_live_inventory
       or begin_attestation.live_origin_inventory_fingerprint is distinct from
         live_inventory_fingerprint
       or begin_attestation.provider_inventory_schema is distinct from
         provider_claim->>'provider_inventory_schema'
       or begin_attestation.retained_origin_inventory_count is distinct from
         (provider_claim->>'retained_origin_inventory_count')::integer
       or begin_attestation.retained_origin_inventory_fingerprint is distinct from
         provider_claim->>'retained_origin_inventory_fingerprint'
       or begin_attestation.retained_provider_inventory_count is distinct from
         (provider_claim->>'retained_provider_inventory_count')::integer
       or begin_attestation.retained_provider_inventory_fingerprint is distinct from
         provider_claim->>'retained_provider_inventory_fingerprint'
       or begin_attestation.live_provider_inventory_count is distinct from
         (provider_claim->>'live_provider_inventory_count')::integer
       or begin_attestation.live_provider_inventory_fingerprint is distinct from
         provider_claim->>'live_provider_inventory_fingerprint'
       or begin_attestation.routing_rule_all_method_fence_required_host_count
         is distinct from
           (provider_claim->>'routing_rule_all_method_fence_required_host_count')::integer
       or begin_attestation.routing_rule_all_method_fence_required_hosts_fingerprint
         is distinct from
           provider_claim->>'routing_rule_all_method_fence_required_hosts_fingerprint'
       or begin_attestation.routing_rule_all_method_fence_required_path_count
         is distinct from
           (provider_claim->>'routing_rule_all_method_fence_required_path_count')::integer
       or begin_attestation.routing_rule_all_method_fence_required_paths_fingerprint
         is distinct from
           provider_claim->>'routing_rule_all_method_fence_required_paths_fingerprint'
       or begin_attestation.redacted_environment_scope_fingerprint
         is distinct from
           provider_claim->>'redacted_environment_scope_fingerprint'
       or begin_attestation.credential_confinement_evidence_schema is distinct from
         provider_claim->>'credential_confinement_evidence_schema'
       or begin_attestation.credential_confinement_record_count is distinct from
         (provider_claim->>'credential_confinement_record_count')::integer
       or begin_attestation.credential_confinement_records_fingerprint
         is distinct from
           provider_claim->>'credential_confinement_records_fingerprint'
       or begin_attestation.credential_confinement_evidence_fingerprint
         is distinct from
           provider_claim->>'credential_confinement_evidence_fingerprint' then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_FINALIZE_DRIFT';
    end if;
  end if;

  if exists (
    select 1 from production_control.vercel_provider_attestation_challenges value
    where value.consume_request_id = consume_request_identifier
  ) or exists (
    select 1 from production_control.vercel_provider_attestations value
    where value.attestation_id = (provider_claim->>'attestation_id')::uuid
       or value.attestation_fingerprint =
         provider_claim->>'attestation_fingerprint'
       or value.challenge_id = challenge.challenge_id
       or value.challenge_request_fingerprint =
         provider_claim->>'challenge_request_fingerprint'
       or value.request_fingerprint = provider_claim->>'request_fingerprint'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_REUSED';
  end if;

  insert into production_control.vercel_provider_attestations (
    attestation_id, status, stage, purpose, attestation_fingerprint,
    signer_key_fingerprint, signer_key_version, challenge_id,
    challenge_request_fingerprint, operation_request_id,
    evidence_request_id, request_fingerprint, signature_verified,
    vercel_project_id, vercel_team_id, candidate_deployment_id,
    candidate_deployment_commit, candidate_deployment_target,
    routing_rule_id, routing_rule_config_version, routing_rule_etag,
    routing_rule_fingerprint, routing_rule_pending_draft_change_count,
    live_origin_inventory_count,
    live_origin_inventory_fingerprint, live_origin_inventory,
    provider_inventory_schema,
    retained_origin_inventory_count, retained_origin_inventory_fingerprint,
    retained_provider_inventory_count, retained_provider_inventory_fingerprint,
    live_provider_inventory_count, live_provider_inventory_fingerprint,
    routing_rule_all_method_fence_required_host_count,
    routing_rule_all_method_fence_required_hosts_fingerprint,
    routing_rule_all_method_fence_required_path_count,
    routing_rule_all_method_fence_required_paths_fingerprint,
    redacted_environment_scope_fingerprint,
    credential_confinement_evidence_schema,
    credential_confinement_record_count,
    credential_confinement_records_fingerprint,
    credential_confinement_evidence_fingerprint,
    provider_observed_at,
    binding_expires_at, recorded_at
  ) values (
    (provider_claim->>'attestation_id')::uuid, 'RESERVED', challenge.stage,
    challenge.purpose, provider_claim->>'attestation_fingerprint',
    provider_claim->>'signer_key_fingerprint',
    provider_claim->>'signer_key_version', challenge.challenge_id,
    provider_claim->>'challenge_request_fingerprint',
    challenge.operation_request_id, challenge.evidence_request_id,
    provider_claim->>'request_fingerprint', true,
    provider_claim->>'vercel_project_id', provider_claim->>'vercel_team_id',
    provider_claim->>'candidate_deployment_id',
    pg_catalog.lower(provider_claim->>'candidate_deployment_commit'),
    provider_claim->>'candidate_deployment_target',
    provider_claim->>'routing_rule_id',
    provider_claim->>'routing_rule_config_version',
    provider_claim->>'routing_rule_etag',
    provider_claim->>'routing_rule_fingerprint',
    (provider_claim->>'routing_rule_pending_draft_change_count')::integer,
    (provider_claim->>'live_origin_inventory_count')::integer,
    live_inventory_fingerprint, normalized_live_inventory,
    provider_claim->>'provider_inventory_schema',
    (provider_claim->>'retained_origin_inventory_count')::integer,
    provider_claim->>'retained_origin_inventory_fingerprint',
    (provider_claim->>'retained_provider_inventory_count')::integer,
    provider_claim->>'retained_provider_inventory_fingerprint',
    (provider_claim->>'live_provider_inventory_count')::integer,
    provider_claim->>'live_provider_inventory_fingerprint',
    (provider_claim->>'routing_rule_all_method_fence_required_host_count')::integer,
    provider_claim->>'routing_rule_all_method_fence_required_hosts_fingerprint',
    (provider_claim->>'routing_rule_all_method_fence_required_path_count')::integer,
    provider_claim->>'routing_rule_all_method_fence_required_paths_fingerprint',
    provider_claim->>'redacted_environment_scope_fingerprint',
    provider_claim->>'credential_confinement_evidence_schema',
    (provider_claim->>'credential_confinement_record_count')::integer,
    provider_claim->>'credential_confinement_records_fingerprint',
    provider_claim->>'credential_confinement_evidence_fingerprint',
    observed_at_value, reserved_at_value + interval '30 minutes',
    reserved_at_value
  ) returning * into reserved;

  update production_control.vercel_provider_attestation_challenges
  set status = 'CONSUMED', consumed_at = reserved_at_value,
      consumed_attestation_id = reserved.attestation_id,
      consume_request_id = consume_request_identifier,
      consume_request_fingerprint = pg_catalog.lower(input->>'request_fingerprint'),
      consume_payload_hash = payload_hash, updated_at = reserved_at_value
  where challenge_id = challenge.challenge_id
  returning * into challenge;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_RESERVED',
    'SCORING_AUTHORITY', '2026', challenge.actor_id,
    challenge.consume_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'attestation_id', reserved.attestation_id,
      'attestation_fingerprint', reserved.attestation_fingerprint,
      'challenge_id', challenge.challenge_id,
      'operation_request_id', challenge.operation_request_id,
      'evidence_request_id', challenge.evidence_request_id,
      'stage', challenge.stage, 'purpose', challenge.purpose,
      'candidate_deployment_id', challenge.candidate_deployment_id,
      'candidate_deployment_target', challenge.candidate_deployment_target,
      'live_origin_inventory_count', reserved.live_origin_inventory_count,
      'live_origin_inventory_fingerprint',
        reserved.live_origin_inventory_fingerprint,
      'provider_inventory_schema', reserved.provider_inventory_schema,
      'retained_provider_inventory_fingerprint',
        reserved.retained_provider_inventory_fingerprint,
      'live_provider_inventory_fingerprint',
        reserved.live_provider_inventory_fingerprint,
      'binding_expires_at', reserved.binding_expires_at
    )
  );
  return production_control.vercel_provider_attestation_response(
    reserved, false
  );
end;
$_$;


ALTER FUNCTION public.consume_vercel_provider_attestation_v3_base(input jsonb) OWNER TO postgres;

--
-- Name: copy_previous_production_guide_as_draft_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copy_previous_production_guide_as_draft_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text;
  target_year integer;
  source_target text := pg_catalog.btrim(coalesce(
    input->>'source_tournament_id',''));
  source_year integer;
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}','')));
  actor_auth uuid;
  request_id uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash','')));
  expected_revision bigint;
  expected_revision_id_text text := pg_catalog.lower(pg_catalog.btrim(
    coalesce(input->>'expected_published_revision_id','')));
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason',''));
  database_hash text;
  prior_receipt jsonb;
  annual_pointer production_control.current_tournament_pointer_v1%rowtype;
  source_value jsonb;
  current_value jsonb;
  copied_authoring jsonb;
  copied_projection jsonb;
  validation jsonb;
  draft_id_value uuid;
  response_value jsonb;
begin
  target := production_control.assert_guide_authoring_v1(input);
  target_year := target::integer;
  begin source_year := (input->>'source_tournament_year')::integer;
  exception when others then source_year := 0; end;
  if input->>'operation' is distinct from
       'COPY_PREVIOUS_PRODUCTION_GUIDE_AS_DRAFT_V1'
     or coalesce(input->>'operation_request_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_published_revision','') !~ '^[0-9]+$'
     or source_target !~ '^20[0-9]{2}$'
     or source_target<>source_year::text
     or source_year<>target_year-1
     or reason_value='' or pg_catalog.length(reason_value)>500 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_COPY_INPUT_INVALID');
  end if;
  select value.* into strict annual_pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key='BAGGER_INV_PRODUCTION';
  if target_year<=annual_pointer.tournament_year then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_COPY_FUTURE_TARGET_REQUIRED');
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  expected_revision := (input->>'expected_published_revision')::bigint;
  database_hash := production_control.guide_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation','COPY_PREVIOUS','tournamentId',target,
      'sourceTournamentId',source_target,'sourceTournamentYear',source_year,
      'actorPlayerId',actor_player,'actorAuthUserId',actor_auth,
      'expectedPublishedRevision',expected_revision,
      'expectedPublishedRevisionId',expected_revision_id_text,
      'reason',reason_value));
  prior_receipt := production_control.guide_operation_receipt_v1(
    target,'COPY_PREVIOUS',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-guide-authoring:'||target,0));
  prior_receipt := production_control.guide_operation_receipt_v1(
    target,'COPY_PREVIOUS',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  if exists (select 1
    from production_control.guide_authoring_drafts_v1 value
    where value.tournament_id=target and value.state in ('DRAFT','VALIDATED'))
  then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_OPEN_DRAFT_EXISTS');
  end if;
  source_value := production_control.guide_current_publication_v1(source_target);
  current_value := production_control.guide_current_publication_v1(target);
  if source_value->'projectionPayload' is null
     or (source_value->>'revision')::bigint=0 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_COPY_SOURCE_REQUIRED');
  end if;
  if (current_value->>'revision')::bigint<>expected_revision
     or (expected_revision_id_text<>'' and expected_revision_id_text
       is distinct from pg_catalog.lower(coalesce(
         current_value->>'revisionId',''))) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_PREDECESSOR_STALE',
      'currentRevision',(current_value->>'revision')::bigint);
  end if;
  copied_authoring := production_control.guide_clone_authoring_v1(
    source_value->'authoringContent',target,target_year);
  copied_projection := production_control.guide_projection_from_clone_v1(
    copied_authoring,source_value->'projectionPayload',target,target_year);
  validation := production_control.validate_guide_draft_structure_v1(
    target,target_year,copied_authoring,copied_projection);
  if validation->>'authoringContentFingerprint' is null
     or validation->>'contentFingerprint' is null
     or validation->>'projectionPayloadHash' is null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','GUIDE_COPY_TARGET_VALIDATION_FAILED',
      'issues',validation->'issues');
  end if;
  insert into production_control.guide_authoring_drafts_v1 (
    tournament_id,tournament_year,draft_version,state,authoring_kind,
    expected_published_revision,expected_published_revision_id,
    source_tournament_id,source_tournament_year,source_revision,
    source_revision_id,authoring_content,projection_payload,
    authoring_content_fingerprint,content_fingerprint,
    projection_payload_hash,canonical_reference_fingerprint,
    validation_diagnostics,reason,created_by_player_id,created_by_auth_user_id
  ) values (
    target,target_year,1,'DRAFT','COPIED_PREVIOUS',expected_revision,
    nullif(expected_revision_id_text,'')::uuid,source_target,source_year,
    (source_value->>'revision')::bigint,
    nullif(source_value->>'revisionId','')::uuid,
    validation->'authoringContent',validation->'projectionPayload',
    validation->>'authoringContentFingerprint',
    validation->>'contentFingerprint',validation->>'projectionPayloadHash',
    production_control.guide_canonical_reference_fingerprint_v1(target),
    (validation->'diagnostics')||pg_catalog.jsonb_build_object(
      'validated',false,'requiresReview',true,
      'sourceTournamentId',source_target,
      'issues',coalesce(validation->'issues','[]'::jsonb),
      'datesAndTimesCopied',false,'contactsCopied',false,
      'publicationStateCopied',false,'auditCopied',false),
    reason_value,actor_player,actor_auth
  ) returning draft_id into draft_id_value;
  response_value := pg_catalog.jsonb_build_object(
    'ok',true,'code','GUIDE_PREVIOUS_GUIDE_COPIED','idempotent',false,
    'tournamentId',target,'sourceTournamentId',source_target,
    'sourceRevision',(source_value->>'revision')::bigint,
    'draftId',draft_id_value,'draftVersion',1,'state','DRAFT',
    'requiresReview',true,'madeCurrent',false,
    'authoringContent',validation->'authoringContent',
    'preview',validation->'projectionPayload',
    'projectionPayload',validation->'projectionPayload');
  insert into production_control.guide_authoring_audit_events_v1 (
    tournament_id,draft_id,action,actor_player_id,actor_auth_user_id,summary
  ) values (
    target,draft_id_value,'PREVIOUS_GUIDE_COPIED',actor_player,actor_auth,
    pg_catalog.jsonb_build_object(
      'draftVersion',1,'sourceTournamentId',source_target,
      'sourceRevision',(source_value->>'revision')::bigint,
      'requiresReview',true,'contactsCopied',false,'madeCurrent',false));
  insert into production_control.operation_audit_events (
    event_type,domain,tournament_id,actor,request_fingerprint,result,details
  ) values (
    'PRODUCTION_GUIDE_PREVIOUS_COPIED','GUIDE',target,actor_player,null,
    'SUCCEEDED',pg_catalog.jsonb_build_object(
      'source_tournament_id',source_target,'requires_review',true,
      'made_current',false));
  insert into production_control.guide_authoring_operation_receipts_v1 (
    tournament_id,operation,operation_request_id,
    declared_request_payload_hash,request_payload_hash,
    actor_player_id,actor_auth_user_id,response
  ) values (
    target,'COPY_PREVIOUS',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value);
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_COPY_SOURCE_OR_RESOURCE_REQUIRED');
when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_COPY_INPUT_INVALID');
when unique_violation then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','GUIDE_OPERATION_CONFLICT');
end;
$_$;


ALTER FUNCTION public.copy_previous_production_guide_as_draft_v1(input jsonb) OWNER TO postgres;

--
-- Name: copy_production_draft_setup_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copy_production_draft_setup_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text;
  source_target text := pg_catalog.btrim(coalesce(
    input->>'source_tournament_id',''));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}','')));
  actor_auth uuid;
  request_id uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash','')));
  expected_value bigint;
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason',''));
  database_hash text;
  prior_receipt jsonb;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  source_revision scoring_authority.draft_revisions%rowtype;
  target_revision scoring_authority.draft_revisions%rowtype;
  source_config jsonb;
  copied_config jsonb;
  copied_picks jsonb;
  validation jsonb;
  next_draft_revision bigint;
  draft_id_value uuid;
  response_value jsonb;
  team_one text;
  team_two text;
  first_team text;
  captain_one text;
  captain_two text;
  total_value integer;
  format_value text;
  mutability jsonb;
begin
  target := production_control.assert_draft_authoring_v1(input);
  if input->>'operation' is distinct from 'COPY_PRODUCTION_DRAFT_SETUP_V1'
     or coalesce(input->>'operation_request_id','')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_revision','') !~ '^[0-9]+$'
     or source_target !~ '^20[0-9]{2}$'
     or reason_value='' or pg_catalog.length(reason_value)>500 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_INPUT_INVALID');
  end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key='BAGGER_INV_PRODUCTION';
  if target=pointer.tournament_id
     or source_target::integer<>target::integer-1 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_COPY_PREVIOUS_YEAR_REQUIRED');
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  expected_value := (input->>'expected_revision')::bigint;
  database_hash := production_control.draft_authoring_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation','COPY_PREVIOUS','tournamentId',target,
      'sourceTournamentId',source_target,
      'actorPlayerId',actor_player,'actorAuthUserId',actor_auth,
      'expectedRevision',expected_value,'reason',reason_value));
  prior_receipt := production_control.draft_operation_receipt_v1(
    target,'COPY_PREVIOUS',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-draft-authoring:'||target,0));
  prior_receipt := production_control.draft_operation_receipt_v1(
    target,'COPY_PREVIOUS',request_id,declared_hash,database_hash);
  if prior_receipt is not null then return prior_receipt; end if;
  mutability := production_control.draft_mutability_v1(target);
  if not coalesce((mutability->>'editable')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_CORRECTION_REQUIRED','mutability',mutability);
  end if;
  select revision.* into strict source_revision
  from scoring_authority.draft_current_revisions current_value
  join scoring_authority.draft_revisions revision
    on revision.revision_id=current_value.revision_id
  where current_value.tournament_id=source_target;
  select revision.* into target_revision
  from scoring_authority.draft_current_revisions current_value
  join scoring_authority.draft_revisions revision
    on revision.revision_id=current_value.revision_id
  where current_value.tournament_id=target for update of current_value;
  if coalesce(target_revision.revision_number,0)<>expected_value then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_PREDECESSOR_STALE',
      'currentRevision',coalesce(target_revision.revision_number,0));
  end if;
  source_config:=source_revision.configuration;
  team_one:=pg_catalog.upper(pg_catalog.btrim(source_config->>'team_1_id'));
  team_two:=pg_catalog.upper(pg_catalog.btrim(source_config->>'team_2_id'));
  first_team:=pg_catalog.upper(pg_catalog.btrim(
    source_config->>'first_pick_team_id'));
  captain_one:=pg_catalog.upper(pg_catalog.btrim(coalesce(
    source_config->>'team_1_captain_player_id','')));
  captain_two:=pg_catalog.upper(pg_catalog.btrim(coalesce(
    source_config->>'team_2_captain_player_id','')));
  if captain_one<>'' and not exists (
    select 1 from scoring_authority.tournament_players value
    where value.tournament_id=target and value.player_id=captain_one
      and value.participation_status='ACTIVE'
  ) then captain_one:=''; end if;
  if captain_two<>'' and not exists (
    select 1 from scoring_authority.tournament_players value
    where value.tournament_id=target and value.player_id=captain_two
      and value.participation_status='ACTIVE'
  ) then captain_two:=''; end if;
  total_value:=(source_config->>'total_picks')::integer;
  format_value:=coalesce(source_config->>'format','');
  copied_config:=pg_catalog.jsonb_build_object(
    'year',target::integer,'name',target||' Sandbagger Draft',
    'date','','time','',
    'time_zone',coalesce(source_config->>'time_zone',''),
    'location',coalesce(source_config->>'location',''),
    'status_mode','Automatic','format',format_value,
    'total_picks',total_value,'team_1_id',team_one,'team_2_id',team_two,
    'team_1_captain_player_id',captain_one,
    'team_2_captain_player_id',captain_two,
    'first_pick_team_id',first_team,
    'notes',coalesce(source_config->>'notes',''));
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'pick_number',number_value,
    'team_id',case when pg_catalog.upper(format_value)='SNAKE' then
      case when pg_catalog.mod((number_value-1)/2,2)=0 then
        case when pg_catalog.mod(number_value-1,2)=0 then first_team
          else case when first_team=team_one then team_two else team_one end end
      else case when pg_catalog.mod(number_value-1,2)=0 then
          case when first_team=team_one then team_two else team_one end
        else first_team end end
      else '' end,
    'player_id','','selected_at','','selected_by','','notes',''
  ) order by number_value) into copied_picks
  from pg_catalog.generate_series(1,total_value) number_value;
  validation:=production_control.validate_draft_authoring_v1(
    target,copied_config,copied_picks);
  if not coalesce((validation->>'pass')::boolean,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','DRAFT_COPY_TARGET_VALIDATION_FAILED',
      'issues',validation->'issues');
  end if;
  update production_control.draft_authoring_drafts_v1 set state='SUPERSEDED'
  where tournament_id=target and state in ('STAGED','VALIDATED');
  select coalesce(pg_catalog.max(value.draft_revision),0)+1
    into next_draft_revision
  from production_control.draft_authoring_drafts_v1 value
  where value.tournament_id=target;
  insert into production_control.draft_authoring_drafts_v1 (
    tournament_id,draft_revision,state,authoring_kind,expected_revision,
    predecessor_revision_id,source_tournament_id,source_revision_id,
    configuration,picks,presentation_seed,configuration_fingerprint,
    picks_fingerprint,payload_fingerprint,validation_diagnostics,reason,
    created_by_player_id,created_by_auth_user_id
  ) values (
    target,next_draft_revision,'STAGED','COPIED_PREVIOUS',expected_value,
    target_revision.revision_id,source_target,source_revision.revision_id,
    validation->'configuration',validation->'picks',
    validation->'presentationSeed',validation->>'configurationFingerprint',
    validation->>'picksFingerprint',validation->>'payloadFingerprint',
    (validation->'diagnostics')||pg_catalog.jsonb_build_object(
      'sourceTournamentId',source_target,
      'sourceRevision',source_revision.revision_number,
      'setupOnly',true,'selectedPlayersCopied',false,
      'selectionTimestampsCopied',false,'auditCopied',false),
    reason_value,actor_player,actor_auth
  ) returning draft_id into draft_id_value;
  response_value:=pg_catalog.jsonb_build_object(
    'ok',true,'code','DRAFT_PREVIOUS_SETUP_COPIED','idempotent',false,
    'tournamentId',target,'sourceTournamentId',source_target,
    'sourceRevision',source_revision.revision_number,
    'draftId',draft_id_value,'draftRevision',next_draft_revision,
    'state','STAGED','requiresReview',true,'madeCurrent',false,
    'configuration',validation->'configuration','picks',validation->'picks',
    'selectedPlayersCopied',false,'selectionTimestampsCopied',false);
  insert into production_control.draft_authoring_audit_events_v1 (
    tournament_id,draft_id,action,actor_player_id,actor_auth_user_id,
    operation_request_id,summary
  ) values (
    target,draft_id_value,'PREVIOUS_SETUP_COPIED',actor_player,actor_auth,
    request_id,pg_catalog.jsonb_build_object(
      'draftRevision',next_draft_revision,
      'sourceTournamentId',source_target,
      'sourceRevision',source_revision.revision_number,
      'setupOnly',true,'selectedPlayersCopied',false,'madeCurrent',false));
  insert into production_control.operation_audit_events (
    event_type,domain,tournament_id,actor,request_fingerprint,result,details
  ) values (
    'PRODUCTION_DRAFT_PREVIOUS_SETUP_COPIED','DRAFT',target,actor_player,null,
    'SUCCEEDED',pg_catalog.jsonb_build_object(
      'draft_revision',next_draft_revision,
      'source_tournament_id',source_target,
      'setup_only',true,'selected_players_copied',false,'made_current',false));
  insert into production_control.draft_operation_receipts_v1 (
    tournament_id,operation,operation_request_id,
    declared_request_payload_hash,request_payload_hash,
    actor_player_id,actor_auth_user_id,response
  ) values (
    target,'COPY_PREVIOUS',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value);
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','DRAFT_COPY_SOURCE_REQUIRED');
when invalid_text_representation or numeric_value_out_of_range then
  return pg_catalog.jsonb_build_object(
    'ok',false,'code','DRAFT_INPUT_INVALID');
end;
$_$;


ALTER FUNCTION public.copy_production_draft_setup_v1(input jsonb) OWNER TO postgres;

--
-- Name: copy_production_prediction_settings_draft_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.copy_production_prediction_settings_draft_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text;
  source_target text := pg_catalog.btrim(coalesce(
    input->>'source_tournament_id', ''
  ));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  )));
  actor_auth uuid;
  request_id uuid;
  declared_hash text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    input->>'request_payload_hash', ''
  )));
  expected_revision bigint;
  database_hash text;
  prior_receipt jsonb;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  source_config scoring_authority.odds_input_configurations%rowtype;
  target_config scoring_authority.odds_input_configurations%rowtype;
  validation jsonb;
  next_draft_revision bigint;
  draft_id_value uuid;
  response_value jsonb;
  reason_value text := pg_catalog.btrim(coalesce(input->>'reason', ''));
begin
  target := production_control.assert_prediction_settings_authoring_v1(input);
  if input->>'operation' is distinct from
       'COPY_PRODUCTION_PREDICTION_SETTINGS_DRAFT_V1'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_configuration_revision', '')
       !~ '^[0-9]+$'
     or source_target !~ '^20[0-9]{2}$'
     or reason_value = '' or pg_catalog.length(reason_value) > 500 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_INPUT_INVALID'
    );
  end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if target = pointer.tournament_id
     or source_target <> pointer.tournament_id then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'PREDICTION_SETTINGS_COPY_SOURCE_NOT_PREVIOUS_CURRENT'
    );
  end if;
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  request_id := (input->>'operation_request_id')::uuid;
  expected_revision := (input->>'expected_configuration_revision')::bigint;
  database_hash := production_control.prediction_settings_hash_v1(
    pg_catalog.jsonb_build_object(
      'operation', 'COPY_PREVIOUS', 'tournamentId', target,
      'sourceTournamentId', source_target,
      'actorPlayerId', actor_player, 'actorAuthUserId', actor_auth,
      'expectedConfigurationRevision', expected_revision,
      'reason', reason_value
    )
  );
  prior_receipt := production_control.prediction_settings_receipt_v1(
    target, 'COPY_PREVIOUS', request_id, declared_hash, database_hash
  );
  if prior_receipt is not null then return prior_receipt; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-prediction-settings:' || target, 0
  ));
  prior_receipt := production_control.prediction_settings_receipt_v1(
    target, 'COPY_PREVIOUS', request_id, declared_hash, database_hash
  );
  if prior_receipt is not null then return prior_receipt; end if;
  select value.* into strict source_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = source_target
    and value.is_current and value.validation_status = 'VALID';
  select value.* into target_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = target and value.is_current for update;
  if coalesce(target_config.configuration_revision, 0) <> expected_revision then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_PREDECESSOR_STALE'
    );
  end if;
  validation := production_control.validate_prediction_settings_v1(
    source_config.canonical_settings, target_config.canonical_settings
  );
  if not coalesce((validation->>'pass')::boolean, false) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_VALIDATION_FAILED',
      'issues', validation->'issues'
    );
  end if;
  if coalesce((validation->>'changedSettingCount')::integer, 0) = 0 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PREDICTION_SETTINGS_NO_CHANGES'
    );
  end if;
  update production_control.prediction_settings_drafts_v1 set
    state = 'SUPERSEDED'
  where tournament_id = target and state in ('STAGED', 'VALIDATED');
  select coalesce(pg_catalog.max(value.draft_revision), 0) + 1
    into next_draft_revision
  from production_control.prediction_settings_drafts_v1 value
  where value.tournament_id = target;
  insert into production_control.prediction_settings_drafts_v1 (
    tournament_id, draft_revision, state, authoring_kind,
    expected_configuration_revision, predecessor_configuration_id,
    source_tournament_id, source_configuration_id,
    canonical_settings, effective_settings, settings_fingerprint,
    effective_settings_fingerprint, changed_keys,
    validation_diagnostics, reason, created_by_player_id,
    created_by_auth_user_id
  ) values (
    target, next_draft_revision, 'STAGED', 'COPIED_PREVIOUS',
    expected_revision, target_config.id, source_target, source_config.id,
    validation->'canonicalSettings', validation->'effectiveSettings',
    validation->>'settingsFingerprint',
    validation->>'effectiveSettingsFingerprint',
    validation->'changedKeys',
    pg_catalog.jsonb_build_object(
      'contractVersion', 'production-prediction-settings-authoring-v1',
      'settingsContractVersion', 'prediction-settings-v1',
      'copiedValuesOnly', true,
      'sourceTournamentId', source_target,
      'sourceConfigurationRevision', source_config.configuration_revision,
      'jobsCopied', false,
      'snapshotsCopied', false,
      'publicationCopied', false,
      'auditCopied', false
    ),
    reason_value, actor_player, actor_auth
  ) returning draft_id into draft_id_value;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PREDICTION_SETTINGS_PREVIOUS_CONFIGURATION_COPIED',
    'idempotent', false,
    'tournamentId', target,
    'sourceTournamentId', source_target,
    'draftId', draft_id_value,
    'draftRevision', next_draft_revision,
    'state', 'STAGED',
    'requiresReview', true,
    'madeCurrent', false,
    'jobsCopied', false,
    'snapshotsCopied', false,
    'publicationCopied', false
  );
  insert into production_control.prediction_settings_audit_events_v1 (
    tournament_id, draft_id, action, actor_player_id,
    actor_auth_user_id, operation_request_id, request_payload_hash, summary
  ) values (
    target, draft_id_value, 'PREVIOUS_CONFIGURATION_COPIED',
    actor_player, actor_auth, request_id, database_hash,
    pg_catalog.jsonb_build_object(
      'draftRevision', next_draft_revision,
      'sourceTournamentId', source_target,
      'sourceConfigurationRevision', source_config.configuration_revision,
      'copiedValuesOnly', true,
      'madeCurrent', false
    )
  );
  insert into production_control.prediction_settings_operation_receipts_v1 (
    tournament_id, operation, operation_request_id,
    declared_request_payload_hash, request_payload_hash,
    actor_player_id, actor_auth_user_id, response
  ) values (
    target, 'COPY_PREVIOUS', request_id, declared_hash, database_hash,
    actor_player, actor_auth, response_value
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_PREDICTION_SETTINGS_PREVIOUS_CONFIGURATION_COPIED',
    'PREDICTION_SETTINGS', target, actor_player, database_hash,
    'SUCCEEDED', pg_catalog.jsonb_build_object(
      'draft_revision', next_draft_revision,
      'source_tournament_id', source_target,
      'source_configuration_revision', source_config.configuration_revision,
      'copied_values_only', true,
      'made_current', false
    )
  );
  return response_value;
exception when no_data_found then
  return pg_catalog.jsonb_build_object(
    'ok', false, 'code', 'PREDICTION_SETTINGS_COPY_SOURCE_REQUIRED'
  );
end;
$_$;


ALTER FUNCTION public.copy_production_prediction_settings_draft_v1(input jsonb) OWNER TO postgres;

