--
-- Name: fail_production_odds_calculation_job(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_production_odds_calculation_job(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  job text := lower(coalesce(input->>'job_id', ''));
  claim uuid := nullif(input->>'claim_token', '')::uuid;
  retryable boolean := coalesce((input->>'retryable')::boolean, true);
  retained scoring_authority.odds_calculation_jobs%rowtype;
begin
  perform production_control.assert_production_odds_calculation_scope(input, true);
  if job !~ '^[0-9a-f]{64}$' or claim is null then
    raise exception using errcode = '22023',
      message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_FAILURE_REQUIRED';
  end if;
  select * into retained from scoring_authority.odds_calculation_jobs
  where job_id = job for update;
  if not found then
    return jsonb_build_object(
      'ok', true, 'marked', false, 'stale_claim', true,
      'publication_created', false, 'mirror_created', false
    );
  end if;
  perform production_control.assert_production_odds_retained_job_scope(
    input, to_jsonb(retained)
  );
  if retained.status <> 'RUNNING' or retained.claim_token is distinct from claim then
    return jsonb_build_object(
      'ok', true, 'marked', false, 'stale_claim', true,
      'publication_created', false, 'mirror_created', false
    );
  end if;
  update scoring_authority.odds_calculation_jobs
  set status = case when retryable then 'RETRYABLE' else 'FAILED' end,
      claim_token = null, lease_owner = null, lease_expires_at = null,
      last_error_code = left(coalesce(
        nullif(input->>'error_code', ''), 'ODDS_CALCULATION_FAILED'
      ), 120),
      last_error_safe = left(coalesce(
        nullif(input->>'error_safe', ''),
        'Championship calculation stopped safely.'
      ), 400),
      completed_at = case when retryable then completed_at else now() end,
      updated_at = now()
  where job_id = job
  returning * into retained;
  return jsonb_build_object(
    'ok', true, 'marked', true, 'retryable', retryable,
    'status', retained.status,
    'completed_iterations', retained.completed_iterations,
    'checkpoint_count', retained.checkpoint_count,
    'publication_created', false, 'mirror_created', false
  );
end;
$_$;


ALTER FUNCTION public.fail_production_odds_calculation_job(input jsonb) OWNER TO postgres;

--
-- Name: fail_production_scorecard_archive_job(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_production_scorecard_archive_job(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  job_row scoring_authority.scorecard_archive_jobs%rowtype;
  delay_seconds integer := greatest(2, least(coalesce((input->>'retry_after_seconds')::integer, 30), 3600));
  blocked boolean := coalesce((input->>'block')::boolean, false);
begin
  perform production_control.assert_production_scoring_runtime(input, 'ROUND_SCORECARDS_ARCHIVE');
  select * into job_row from scoring_authority.scorecard_archive_jobs
    where job_id = nullif(input->>'job_id', '')::uuid and tournament_id = '2026' for update;
  if not found or job_row.status <> 'PROCESSING'
     or job_row.claim_token <> nullif(input->>'claim_token', '')::uuid
     or job_row.claimed_by <> left(coalesce(input->>'worker_id', ''), 160)
     or job_row.lease_expires_at < now() then
    return jsonb_build_object('ok', false, 'code', 'ARCHIVE_CLAIM_STALE');
  end if;
  update scoring_authority.scorecard_archive_jobs set
    status = case when blocked then 'BLOCKED' else 'RETRYABLE' end,
    available_at = now() + make_interval(secs => delay_seconds), lease_expires_at = null,
    claimed_by = null, claim_token = null,
    last_error_code = left(coalesce(input->>'error_code', 'ARCHIVE_DELIVERY_FAILED'), 120),
    last_error_safe = left(coalesce(input->>'error_safe', 'Round Scorecards archive delivery failed.'), 500),
    updated_at = now()
  where job_id = job_row.job_id;
  update scoring_authority.scorecard_archive_checkpoints set
    status = 'FAILED', last_job_id = job_row.job_id,
    last_error_code = left(coalesce(input->>'error_code', 'ARCHIVE_DELIVERY_FAILED'), 120),
    last_error_safe = left(coalesce(input->>'error_safe', 'Round Scorecards archive delivery failed.'), 500),
    updated_at = now()
  where match_id = job_row.match_id and finalized_match_revision <= job_row.match_revision;
  return jsonb_build_object('ok', true,
    'status', case when blocked then 'BLOCKED' else 'RETRYABLE' end);
end;
$$;


ALTER FUNCTION public.fail_production_scorecard_archive_job(input jsonb) OWNER TO postgres;

