--
-- Name: future_production_fail_google_outbox_pre_generation_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.future_production_fail_google_outbox_pre_generation_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_tournament text;
  worker text := pg_catalog.left(coalesce(nullif(input->>'worker_id', ''), ''), 160);
  delay_seconds integer := greatest(1, least(coalesce((input->>'retry_after_seconds')::integer, 1), 300));
  updated_count integer;
begin
  target_tournament := production_control.assert_future_production_scoring_runtime_v1(input, 'SCORING_GOOGLE_OUTBOX');
  update scoring_authority.google_outbox_events set
    status = case when coalesce((input->>'block')::boolean, false) then 'BLOCKED' else 'RETRYABLE' end,
    available_at = pg_catalog.now() + pg_catalog.make_interval(secs => delay_seconds),
    lease_expires_at = null, claimed_by = null,
    last_error_code = pg_catalog.left(coalesce(input->>'error_code', 'DELIVERY_FAILED'), 80),
    last_error_safe = pg_catalog.left(coalesce(input->>'error_safe', 'Google mirror delivery will retry.'), 240)
  where id = nullif(input->>'event_id', '')::uuid and tournament_id = target_tournament
    and status = 'PROCESSING' and claimed_by = worker and lease_expires_at >= pg_catalog.now();
  get diagnostics updated_count = row_count;
  if updated_count <> 1 then return pg_catalog.jsonb_build_object('ok', false, 'code', 'OUTBOX_CLAIM_STALE'); end if;
  return pg_catalog.jsonb_build_object('ok', true,
    'status', case when coalesce((input->>'block')::boolean, false) then 'BLOCKED' else 'RETRYABLE' end);
end;
$$;


ALTER FUNCTION public.future_production_fail_google_outbox_pre_generation_v1(input jsonb) OWNER TO postgres;

--
-- Name: future_production_fail_google_outbox_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.future_production_fail_google_outbox_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform production_control.assert_future_production_scoring_runtime_v1(
    input, 'SCORING_GOOGLE_OUTBOX'
  );
  if not exists (
    select 1 from scoring_authority.google_outbox_events value
    where value.id = nullif(input->>'event_id', '')::uuid
      and value.runtime_generation_id =
        (input->>'expected_runtime_generation_id')::uuid
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'EVENT_NOT_FOUND'
    );
  end if;
  return public.future_production_fail_google_outbox_pre_generation_v1(input);
end;
$$;


