--
-- Name: import_production_completed_history_year(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_completed_history_year(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions', 'pg_temp'
    AS $_$
declare
  production_project constant text := 'ymqhhtxaywtqllynrmxe';
  historical_source constant text := '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4';
  environment_value text := upper(btrim(coalesce(input->>'environment', '')));
  project_value text := btrim(coalesce(input->>'project_ref', ''));
  source_workbook text := btrim(coalesce(input->>'source_workbook_id', ''));
  actor text := btrim(coalesce(input->>'actor_id', ''));
  authorization_value jsonb := input->'director_authorization';
  authorization_id text := btrim(coalesce(input #>> '{director_authorization,authorization_id}', ''));
  authorization_time timestamptz;
  target_year integer;
  target_tournament text := btrim(coalesce(input->>'tournament_id', ''));
  source_fingerprint_value text := lower(btrim(coalesce(input->>'source_fingerprint', '')));
  payload_fingerprint_value text := lower(btrim(coalesce(input->>'payload_fingerprint', '')));
  payload_body jsonb := input->'payload';
  tournament_value jsonb;
  expected_source_fingerprint text := lower(btrim(coalesce(input #>> '{correction,expected_source_fingerprint}', '')));
  correction_reason_value text := btrim(coalesce(input #>> '{correction,reason}', ''));
  validation jsonb;
  current_revision scoring_authority.completed_history_revisions%rowtype;
  previous_revision_id_value uuid;
  revision_id_value uuid := gen_random_uuid();
  import_run_id_value uuid := gen_random_uuid();
  revision_number_value bigint := 1;
  operation_value text := 'INITIAL_IMPORT';
  database_payload_fingerprint_value text;
  request_fingerprint_value text;
  canonical_counts_value jsonb;
  certification_value jsonb;
  item jsonb;
  previous_control_import_run_id_value uuid;
begin
  if not exists (
    select 1
    from production_control.resource_scope resource
    join production_control.tournament_scopes scope
      on scope.source_workbook_id = resource.google_workbook_id
     and scope.tournament_id = target_tournament
     and scope.tournament_year::text = target_tournament
    where resource.scope_key = 'BAGGER_INV_PRODUCTION'
      and resource.project_ref = production_project
      and resource.google_workbook_id = historical_source
      and resource.current_tournament_read_authority = 'GOOGLE'
      and resource.scoring_authority = 'GOOGLE'
      and resource.participant_identity_authority = 'PASSPORT'
      and not resource.public_supabase_reads_enabled
      and not resource.scoring_ingress_enabled
      and not resource.google_writes_enabled
      and not resource.auth_user_creation_enabled
      and not resource.odds_publication_enabled
      and not resource.workers_enabled
      and scope.scope_kind = 'COMPLETED_HISTORY'
      and scope.active_for_shadow_import
  ) then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_FOUNDATION_SCOPE_NOT_READY');
  end if;
  if environment_value <> 'PRODUCTION'
     or project_value <> production_project
     or source_workbook <> historical_source then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_COMPLETED_HISTORY_SCOPE_REQUIRED');
  end if;
  if jsonb_typeof(authorization_value) <> 'object'
     or coalesce((authorization_value->>'authorized')::boolean, false) is not true
     or authorization_value->>'scope' <> 'PRODUCTION_COMPLETED_HISTORY_SHADOW_IMPORT'
     or authorization_value->>'actor_id' <> actor
     or length(authorization_id) < 8 then
    return jsonb_build_object('ok', false, 'code', 'DIRECTOR_HISTORY_IMPORT_AUTHORIZATION_REQUIRED');
  end if;
  begin
    authorization_time := (authorization_value->>'authorized_at')::timestamptz;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'DIRECTOR_HISTORY_IMPORT_AUTHORIZATION_REQUIRED');
  end;
  if authorization_time < now() - interval '15 minutes'
     or authorization_time > now() + interval '1 minute' then
    return jsonb_build_object('ok', false, 'code', 'DIRECTOR_HISTORY_IMPORT_AUTHORIZATION_EXPIRED');
  end if;
  begin target_year := (input->>'tournament_year')::integer;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'HISTORICAL_YEAR_REQUIRED');
  end;
  if actor = ''
     or target_year not between 2017 and 2025
     or target_tournament <> target_year::text
     or source_fingerprint_value !~ '^[0-9a-f]{64}$'
     or payload_fingerprint_value !~ '^[0-9a-f]{64}$'
     or btrim(coalesce(input->>'import_contract_version', '')) = ''
     or btrim(coalesce(input->>'correction_set_version', '')) = ''
     or btrim(coalesce(input->>'importer_version', '')) = ''
     or jsonb_typeof(coalesce(input->'source_counts', '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(input->'certification', '{}'::jsonb)) <> 'object' then
    return jsonb_build_object('ok', false, 'code', 'COMPLETED_HISTORY_PROVENANCE_REQUIRED');
  end if;

  validation := scoring_authority.validate_completed_history_payload(input);
  if coalesce((validation->>'ok')::boolean, false) is not true then
    return validation;
  end if;
  if exists (
    select 1
    from jsonb_array_elements(payload_body->'courses') incoming
    join scoring_authority.completed_history_course_identities existing
      on existing.course_id = incoming->>'course_id'
    where (
      lower(btrim(existing.canonical_name))
        <> lower(btrim(coalesce(incoming->>'canonical_name', '')))
      or lower(btrim(coalesce(existing.canonical_location, '')))
        <> lower(btrim(coalesce(incoming->>'canonical_location', '')))
    )
      and (expected_source_fingerprint = '' or length(correction_reason_value) < 10)
  ) then
    return jsonb_build_object('ok', false, 'code', 'HISTORICAL_COURSE_IDENTITY_CONFLICT');
  end if;
  canonical_counts_value := validation->'counts';
  certification_value := coalesce(input->'certification', '{}'::jsonb) || jsonb_build_object(
    'database_validated', true,
    'final_score_reconciled', true,
    'champion_reconciled', true,
    'participant_structure_reconciled', true,
    'missing_scorecards_are_not_zeroes', true,
    'derived_team_1_points', validation->'derived_team_1_points',
    'derived_team_2_points', validation->'derived_team_2_points'
  );
  tournament_value := payload_body->'tournament';

  perform pg_advisory_xact_lock(hashtext('production-completed-history-' || target_year::text));
  select import_run_id into previous_control_import_run_id_value
  from production_control.import_runs
  where domain = 'COMPLETED_HISTORY'
    and tournament_id = target_tournament
    and tournament_year = target_year
    and source_workbook_id = historical_source
    and status = 'SUCCEEDED'
  order by completed_at desc nulls last, started_at desc
  limit 1;
  select revision.* into current_revision
  from scoring_authority.completed_history_current_revisions current_pointer
  join scoring_authority.completed_history_revisions revision
    on revision.revision_id = current_pointer.revision_id
  where current_pointer.tournament_year = target_year
  for update of current_pointer;

  database_payload_fingerprint_value := encode(
    extensions.digest(payload_body::text, 'sha256'), 'hex'
  );
  request_fingerprint_value := encode(
    extensions.digest((input - 'director_authorization' - 'correction')::text, 'sha256'), 'hex'
  );

  if current_revision.revision_id is not null then
    if current_revision.source_fingerprint = source_fingerprint_value
       and current_revision.payload_fingerprint = payload_fingerprint_value
       and current_revision.database_payload_fingerprint = database_payload_fingerprint_value then
      return jsonb_build_object(
        'ok', true, 'changed', false, 'duplicate', true,
        'tournament_id', target_tournament, 'tournament_year', target_year,
        'revision_id', current_revision.revision_id,
        'revision_number', current_revision.revision_number,
        'source_fingerprint', current_revision.source_fingerprint,
        'payload_fingerprint', current_revision.payload_fingerprint,
        'database_payload_fingerprint', current_revision.database_payload_fingerprint,
        'canonical_counts', current_revision.canonical_counts,
        'certification', current_revision.certification
      );
    end if;
    if expected_source_fingerprint <> current_revision.source_fingerprint
       or length(correction_reason_value) < 10 then
      return jsonb_build_object(
        'ok', false, 'code', 'HISTORICAL_RECONCILIATION_REQUIRED',
        'current_revision_id', current_revision.revision_id,
        'current_source_fingerprint', current_revision.source_fingerprint,
        'incoming_source_fingerprint', source_fingerprint_value,
        'current_payload_fingerprint', current_revision.payload_fingerprint,
        'incoming_payload_fingerprint', payload_fingerprint_value
      );
    end if;
    operation_value := 'CORRECTION';
    previous_revision_id_value := current_revision.revision_id;
    revision_number_value := current_revision.revision_number + 1;
  elsif target_year > 2017 and not exists (
    select 1 from scoring_authority.completed_history_current_revisions
    where tournament_year = target_year - 1
  ) then
    return jsonb_build_object(
      'ok', false, 'code', 'PRIOR_HISTORY_YEAR_NOT_CERTIFIED',
      'required_year', target_year - 1
    );
  end if;

  -- A transaction-local capability is required by every new-table trigger.
  -- It is set only after Production/project/source/Director checks and validation.
  perform set_config('scoring_authority.completed_history_import', 'on', true);
  if exists (
    select 1 from scoring_authority.tournaments
    where tournament_year = target_year and tournament_id <> target_tournament
  ) then
    raise exception using errcode = '23505', message = 'HISTORICAL_TOURNAMENT_IDENTITY_CONFLICT';
  end if;

  insert into scoring_authority.tournaments (
    tournament_id, tournament_year, name, source_workbook_id, scoring_authority,
    imported_at, created_at, updated_at
  ) values (
    target_tournament, target_year, tournament_value->>'name', historical_source,
    'GOOGLE', now(), now(), now()
  )
  on conflict (tournament_id) do update set
    name = excluded.name,
    source_workbook_id = excluded.source_workbook_id,
    scoring_authority = 'GOOGLE',
    imported_at = now(), updated_at = now();

  for item in select value from jsonb_array_elements(payload_body->'players') loop
    insert into scoring_authority.players (player_id, display_name, source_payload)
    values (
      item->>'player_id', item->>'display_name',
      coalesce(item->'source_payload', '{}'::jsonb)
        || jsonb_build_object('completed_history_last_seen_year', target_year)
    )
    on conflict (player_id) do update set
      source_payload = scoring_authority.players.source_payload
        || coalesce(excluded.source_payload, '{}'::jsonb)
        || jsonb_build_object('completed_history_last_seen_year', target_year),
      updated_at = now();
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'courses') loop
    insert into scoring_authority.completed_history_course_identities (
      course_id, canonical_name, canonical_location, first_seen_year, identity_payload
    ) values (
      item->>'course_id', item->>'canonical_name', nullif(item->>'canonical_location', ''),
      target_year, coalesce(item->'identity_payload', '{}'::jsonb)
    ) on conflict (course_id) do update set
      canonical_name = excluded.canonical_name,
      canonical_location = excluded.canonical_location,
      identity_payload = scoring_authority.completed_history_course_identities.identity_payload
        || excluded.identity_payload
    where expected_source_fingerprint <> '' and length(correction_reason_value) >= 10;
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'teams') loop
    insert into scoring_authority.teams (
      tournament_id, team_id, team_side, name, source_payload
    ) values (
      target_tournament, item->>'team_id', (item->>'team_side')::integer,
      item->>'name', coalesce(item->'source_payload', '{}'::jsonb)
    )
    on conflict (tournament_id, team_id) do update set
      team_side = excluded.team_side, name = excluded.name,
      source_payload = excluded.source_payload;
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'roster') loop
    insert into scoring_authority.tournament_players (
      tournament_id, player_id, team_id, team_side, participation_status,
      source_roster_key, source_payload
    ) values (
      target_tournament, item->>'player_id', item->>'team_id',
      (item->>'team_side')::integer,
      coalesce(item->>'participation_status', 'ACTIVE'),
      item->>'source_roster_key', coalesce(item->'source_payload', '{}'::jsonb)
    )
    on conflict (tournament_id, player_id) do update set
      team_id = excluded.team_id, team_side = excluded.team_side,
      participation_status = excluded.participation_status,
      source_roster_key = excluded.source_roster_key,
      source_payload = excluded.source_payload, updated_at = now();
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'rounds') loop
    insert into scoring_authority.rounds (
      tournament_id, round_number, format, name, handicap_allowance, status, source_payload
    ) values (
      target_tournament, (item->>'round_number')::integer, item->>'format',
      coalesce(nullif(item->>'name', ''), 'Round ' || (item->>'round_number')),
      nullif(item->>'handicap_allowance', '')::numeric, 'FINAL',
      coalesce(item->'source_payload', '{}'::jsonb)
    )
    on conflict (tournament_id, round_number) do update set
      format = excluded.format, name = excluded.name,
      handicap_allowance = excluded.handicap_allowance, status = 'FINAL',
      source_payload = excluded.source_payload;
  end loop;

  insert into scoring_authority.completed_history_revisions (
    revision_id, project_ref, source_workbook_id, tournament_id, tournament_year,
    revision_number, source_fingerprint, payload_fingerprint,
    database_payload_fingerprint, import_contract_version, correction_set_version,
    importer_version, source_counts, canonical_counts, certification, operation,
    previous_revision_id, correction_reason, imported_by
  ) values (
    revision_id_value, production_project, historical_source, target_tournament, target_year,
    revision_number_value, source_fingerprint_value, payload_fingerprint_value,
    database_payload_fingerprint_value, input->>'import_contract_version',
    input->>'correction_set_version', input->>'importer_version',
    coalesce(input->'source_counts', '{}'::jsonb), canonical_counts_value,
    certification_value, operation_value, previous_revision_id_value,
    case when operation_value = 'CORRECTION' then correction_reason_value else null end,
    actor
  );

  insert into scoring_authority.completed_history_tournament_facts (
    revision_id, tournament_id, tournament_year, start_date, end_date, destination,
    timezone, lifecycle, score_availability, official_team_1_points,
    official_team_2_points, total_awarded_points, expected_configured_points,
    champion_team_side, champion_team_id, team_size, source_payload
  ) values (
    revision_id_value, target_tournament, target_year,
    nullif(tournament_value->>'start_date', '')::date,
    nullif(tournament_value->>'end_date', '')::date,
    nullif(tournament_value->>'destination', ''), nullif(tournament_value->>'timezone', ''),
    'FINAL', tournament_value->>'score_availability',
    nullif(tournament_value->>'official_team_1_points', '')::numeric,
    nullif(tournament_value->>'official_team_2_points', '')::numeric,
    nullif(tournament_value->>'total_awarded_points', '')::numeric,
    nullif(tournament_value->>'expected_configured_points', '')::numeric,
    (tournament_value->>'champion_team_side')::integer,
    tournament_value->>'champion_team_id',
    nullif(tournament_value->>'team_size', '')::integer,
    coalesce(tournament_value->'source_payload', '{}'::jsonb)
  );

  for item in select value from jsonb_array_elements(payload_body->'teams') loop
    insert into scoring_authority.completed_history_team_facts (
      revision_id, tournament_id, team_id, team_side, name, captain_player_id,
      logo_key, presentation_identity, source_payload
    ) values (
      revision_id_value, target_tournament, item->>'team_id',
      (item->>'team_side')::integer, item->>'name',
      nullif(item->>'captain_player_id', ''), nullif(item->>'logo_key', ''),
      coalesce(item->'presentation_identity', '{}'::jsonb),
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'roster') loop
    insert into scoring_authority.completed_history_roster_facts (
      revision_id, tournament_id, player_id, display_name, team_id, team_side,
      participation_status, is_captain, is_governor, tournament_handicap, source_roster_key, source_payload
    ) values (
      revision_id_value, target_tournament, item->>'player_id',
      coalesce(nullif(item->>'display_name', ''), (
        select p.display_name from scoring_authority.players p where p.player_id = item->>'player_id'
      )), item->>'team_id', (item->>'team_side')::integer,
      coalesce(item->>'participation_status', 'ACTIVE'),
      coalesce((item->>'is_captain')::boolean, false),
      (item->>'is_governor')::boolean,
      nullif(item->>'tournament_handicap', '')::numeric,
      item->>'source_roster_key',
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'rounds') loop
    insert into scoring_authority.completed_history_round_facts (
      revision_id, tournament_id, round_number, format, name, team_size,
      points_per_match, handicap_allowance, course_appearance_id,
      scoring_semantics, source_payload
    ) values (
      revision_id_value, target_tournament, (item->>'round_number')::integer,
      item->>'format', coalesce(nullif(item->>'name', ''), 'Round ' || (item->>'round_number')),
      (item->>'team_size')::integer, nullif(item->>'points_per_match', '')::numeric,
      nullif(item->>'handicap_allowance', '')::numeric,
      nullif(item->>'course_appearance_id', ''),
      coalesce(item->'scoring_semantics', '{}'::jsonb),
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'course_appearances') loop
    insert into scoring_authority.completed_history_course_appearances (
      revision_id, tournament_id, appearance_id, round_number, course_id,
      source_course_id, display_name, location, tee, rating, slope, yardage,
      par, hole_definitions, source_payload
    ) values (
      revision_id_value, target_tournament, item->>'appearance_id',
      (item->>'round_number')::integer, item->>'course_id', item->>'source_course_id',
      item->>'display_name', nullif(item->>'location', ''), nullif(item->>'tee', ''),
      nullif(item->>'rating', '')::numeric, nullif(item->>'slope', '')::integer,
      nullif(item->>'yardage', '')::integer, nullif(item->>'par', '')::integer,
      coalesce(item->'hole_definitions', '[]'::jsonb),
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'matches') loop
    insert into scoring_authority.completed_history_matches (
      revision_id, tournament_id, match_id, round_number, format,
      course_appearance_id, lifecycle, completion_state, scorecard_coverage,
      result, result_winner, team_1_points, team_2_points, points_available,
      points_availability, source_match_key, source_payload
    ) values (
      revision_id_value, target_tournament, item->>'match_id',
      (item->>'round_number')::integer, item->>'format', item->>'course_appearance_id',
      'FINAL', item->>'completion_state', item->>'scorecard_coverage',
      item->>'result', item->>'result_winner',
      nullif(item->>'team_1_points', '')::numeric,
      nullif(item->>'team_2_points', '')::numeric,
      nullif(item->>'points_available', '')::numeric,
      item->>'points_availability', item->>'source_match_key',
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'match_participants') loop
    insert into scoring_authority.completed_history_match_participants (
      revision_id, match_id, player_id, team_side, player_slot,
      tournament_handicap, applied_handicap, applied_strokes, source_payload
    ) values (
      revision_id_value, item->>'match_id', item->>'player_id',
      (item->>'team_side')::integer, (item->>'player_slot')::integer,
      nullif(item->>'tournament_handicap', '')::numeric,
      nullif(item->>'applied_handicap', '')::numeric,
      nullif(item->>'applied_strokes', '')::numeric,
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'scorecards') loop
    insert into scoring_authority.completed_history_scorecards (
      revision_id, scorecard_id, match_id, entity_kind, player_id, team_side,
      player_slot, coverage_status, recorded_holes, hole_values, score_semantics,
      source_payload
    ) values (
      revision_id_value, item->>'scorecard_id', item->>'match_id',
      item->>'entity_kind', nullif(item->>'player_id', ''),
      nullif(item->>'team_side', '')::integer, nullif(item->>'player_slot', '')::integer,
      item->>'coverage_status', (item->>'recorded_holes')::integer,
      coalesce(item->'hole_values', '[]'::jsonb),
      coalesce(item->'score_semantics', '{}'::jsonb),
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'awards') loop
    insert into scoring_authority.completed_history_awards (
      revision_id, tournament_id, award_id, award_type, label, recipient_kind,
      winner_player_id, winner_team_id, recipient_display, source_payload
    ) values (
      revision_id_value, target_tournament, item->>'award_id', item->>'award_type',
      item->>'label', item->>'recipient_kind', nullif(item->>'winner_player_id', ''),
      nullif(item->>'winner_team_id', ''), nullif(item->>'recipient_display', ''),
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'record_eligibility') loop
    insert into scoring_authority.completed_history_record_eligibility (
      revision_id, match_id, player_id, is_record_eligible, reason_code, source_payload
    ) values (
      revision_id_value, item->>'match_id', item->>'player_id',
      (item->>'is_record_eligible')::boolean, item->>'reason_code',
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  for item in select value from jsonb_array_elements(payload_body->'corrections') loop
    insert into scoring_authority.completed_history_correction_applications (
      revision_id, correction_id, category, description, evidence, source_payload
    ) values (
      revision_id_value, item->>'correction_id', item->>'category',
      item->>'description', coalesce(item->'evidence', '{}'::jsonb),
      coalesce(item->'source_payload', '{}'::jsonb)
    );
  end loop;

  insert into scoring_authority.completed_history_import_runs (
    import_run_id, revision_id, tournament_id, tournament_year, operation,
    status, source_fingerprint, payload_fingerprint, request_fingerprint,
    actor_id, metadata
  ) values (
    import_run_id_value, revision_id_value, target_tournament, target_year,
    operation_value, 'SUCCEEDED', source_fingerprint_value,
    payload_fingerprint_value, request_fingerprint_value, actor,
    jsonb_build_object(
      'project_ref', production_project, 'source_workbook_id', historical_source,
      'director_authorization_id', authorization_id,
      'import_contract_version', input->>'import_contract_version',
      'correction_set_version', input->>'correction_set_version',
      'importer_version', input->>'importer_version'
    )
  );

  insert into scoring_authority.completed_history_current_revisions (
    tournament_id, tournament_year, revision_id, project_ref,
    source_workbook_id, advanced_by, advanced_at
  ) values (
    target_tournament, target_year, revision_id_value, production_project,
    historical_source, actor, now()
  )
  on conflict (tournament_id) do update set
    revision_id = excluded.revision_id, project_ref = excluded.project_ref,
    source_workbook_id = excluded.source_workbook_id,
    advanced_by = excluded.advanced_by, advanced_at = excluded.advanced_at;

  insert into production_control.import_runs (
    import_run_id, domain, tournament_id, tournament_year, source_workbook_id,
    source_fingerprint, payload_fingerprint, database_fingerprint,
    importer_contract, correction_registry_version, actor, status,
    previous_import_run_id, counts, started_at, completed_at
  ) values (
    import_run_id_value, 'COMPLETED_HISTORY', target_tournament, target_year, historical_source,
    source_fingerprint_value, payload_fingerprint_value, database_payload_fingerprint_value,
    input->>'import_contract_version', input->>'correction_set_version', actor,
    'SUCCEEDED', previous_control_import_run_id_value, canonical_counts_value, now(), now()
  );

  insert into scoring_authority.audit_events (tournament_id, action, actor_id, metadata)
  values (
    target_tournament,
    case when operation_value = 'INITIAL_IMPORT'
      then 'COMPLETED_HISTORY_YEAR_CERTIFIED'
      else 'COMPLETED_HISTORY_YEAR_CORRECTED' end,
    actor,
    jsonb_build_object(
      'revisionId', revision_id_value, 'revisionNumber', revision_number_value,
      'sourceFingerprint', source_fingerprint_value,
      'payloadFingerprint', payload_fingerprint_value,
      'databasePayloadFingerprint', database_payload_fingerprint_value,
      'operation', operation_value, 'canonicalCounts', canonical_counts_value,
      'directorAuthorizationId', authorization_id,
      'correctionReason', case when operation_value = 'CORRECTION'
        then correction_reason_value else null end
    )
  );

  return jsonb_build_object(
    'ok', true, 'changed', true, 'duplicate', false,
    'operation', operation_value, 'tournament_id', target_tournament,
    'tournament_year', target_year, 'revision_id', revision_id_value,
    'revision_number', revision_number_value, 'import_run_id', import_run_id_value,
    'source_fingerprint', source_fingerprint_value,
    'payload_fingerprint', payload_fingerprint_value,
    'database_payload_fingerprint', database_payload_fingerprint_value,
    'canonical_counts', canonical_counts_value, 'certification', certification_value
  );
end;
$_$;


ALTER FUNCTION public.import_production_completed_history_year(input jsonb) OWNER TO postgres;

--
-- Name: import_production_current_tournament_shadow(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_current_tournament_shadow(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  claim production_control.current_shadow_import_claims%rowtype;
  existing_run production_control.import_runs%rowtype;
  current_projection jsonb;
  request_value jsonb;
  expected_request jsonb;
  source_value jsonb;
  payload_value jsonb;
  request_text text := coalesce(input->>'request_canonical_json','');
  payload_body jsonb := input->'payload';
  source_text text := coalesce(input->>'source_canonical_json','');
  payload_text text := coalesce(input->>'payload_canonical_json','');
  operation_value text := upper(btrim(coalesce(input->>'operation','')));
  actor_value text := btrim(coalesce(input->>'actor_id',''));
  request_fingerprint_value text := lower(btrim(coalesce(input->>'request_fingerprint','')));
  source_fingerprint_value text := lower(btrim(coalesce(input->>'source_fingerprint','')));
  payload_fingerprint_value text := lower(btrim(coalesce(input->>'payload_fingerprint','')));
  database_fingerprint_value text;
  tournament_run_id uuid := extensions.gen_random_uuid();
  scoring_run_id uuid := extensions.gen_random_uuid();
  previous_tournament_run_id uuid;
  previous_scoring_run_id uuid;
  item jsonb;
  counts_value jsonb;
  expected_match_count integer;
  operational_trigger_count integer;
begin
  scope := production_control.assert_current_shadow_v2_dormant();
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_SERVICE_ROLE_REQUIRED';
  end if;
  if upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref','')) <> scope.project_ref
     or btrim(coalesce(input->>'project_url','')) <> scope.project_url
     or btrim(coalesce(input->>'source_workbook_id','')) <> scope.google_workbook_id
     or btrim(coalesce(input->>'tournament_id','')) <> '2026'
     or coalesce((input->>'tournament_year')::integer, 0) <> 2026
     or btrim(coalesce(input->>'import_contract_version','')) <> 'production-current-shadow-v2'
     or operation_value <> 'CURRENT_TOURNAMENT_SHADOW_IMPORT'
     or actor_value <> 'step10b-production-shadow-bootstrap'
     or request_fingerprint_value !~ '^[0-9a-f]{64}$'
     or source_fingerprint_value !~ '^[0-9a-f]{64}$'
     or payload_fingerprint_value !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(input->'source_payload') <> 'object'
     or jsonb_typeof(payload_body) <> 'object'
     or btrim(request_text) = '' or btrim(source_text) = '' or btrim(payload_text) = '' then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_V2_SCOPE_REQUIRED';
  end if;

  begin
    select * into claim
    from production_control.current_shadow_import_claims value
    where value.claim_id = (input->>'claim_id')::uuid
    for update;
  exception when others then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_CLAIM_REQUIRED';
  end;
  if claim.claim_id is null or claim.status not in ('PENDING','CONSUMED')
     or (claim.status = 'PENDING' and claim.expires_at <= now())
     or (claim.status = 'CONSUMED' and claim.import_run_id is null)
     or claim.tournament_id <> '2026'
     or claim.bootstrap_key <> 'STEP10B_CURRENT_SHADOW_V2'
     or claim.operation <> operation_value
     or claim.actor <> actor_value
     or claim.request_fingerprint <> request_fingerprint_value
     or claim.source_fingerprint <> source_fingerprint_value
     or claim.payload_fingerprint <> payload_fingerprint_value
     or claim.import_contract <> 'production-current-shadow-v2'
  then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_CLAIM_INVALID';
  end if;

  begin
    request_value := request_text::jsonb;
    source_value := source_text::jsonb;
    payload_value := payload_text::jsonb;
  exception when others then
    raise exception using errcode = '22023', message = 'PRODUCTION_CURRENT_SHADOW_CANONICAL_JSON_INVALID';
  end;
  expected_request := jsonb_build_object(
    'actor_id', 'step10b-production-shadow-bootstrap',
    'environment', 'PRODUCTION',
    'import_contract_version', 'production-current-shadow-v2',
    'operation', 'CURRENT_TOURNAMENT_SHADOW_IMPORT',
    'payload_fingerprint', payload_fingerprint_value,
    'project_ref', scope.project_ref,
    'project_url', scope.project_url,
    'source_fingerprint', source_fingerprint_value,
    'source_workbook_id', scope.google_workbook_id,
    'tournament_id', '2026',
    'tournament_year', 2026
  );
  if request_value is distinct from expected_request
     or encode(extensions.digest(request_text,'sha256'),'hex') <> request_fingerprint_value
     or source_value is distinct from input->'source_payload'
     or payload_value is distinct from payload_body
     or encode(extensions.digest(source_text,'sha256'),'hex') <> source_fingerprint_value
     or encode(extensions.digest(payload_text,'sha256'),'hex') <> payload_fingerprint_value then
    raise exception using errcode = '22023', message = 'PRODUCTION_CURRENT_SHADOW_CANONICAL_EVIDENCE_MISMATCH';
  end if;
  if source_value->>'source_workbook_id' <> scope.google_workbook_id
     or source_value->>'tournament_id' <> '2026'
     or coalesce((source_value->>'tournament_year')::integer,0) <> 2026
     or jsonb_typeof(source_value->'sheets') <> 'array'
     or (select jsonb_agg(value->>'sheet' order by ordinal)
         from jsonb_array_elements(source_value->'sheets') with ordinality sheet(value,ordinal))
        <> '["Tournaments","Live Tournaments","Players","Handicaps","Team Names","Rounds","Tournament Rules","Courses","Course Holes","Live Matches","Matches","Live Hole Scores","Match Update Log","Admin Audit Log"]'::jsonb then
    raise exception using errcode = '22023', message = 'PRODUCTION_CURRENT_SHADOW_SOURCE_CONTRACT_REQUIRED';
  end if;

  if upper(btrim(coalesce(payload_body->>'environment',''))) <> 'PRODUCTION'
     or payload_body->>'source_workbook_id' <> scope.google_workbook_id
     or payload_body#>>'{tournament,tournament_id}' <> '2026'
     or coalesce((payload_body#>>'{tournament,tournament_year}')::integer, 0) <> 2026
     or upper(btrim(coalesce(payload_body#>>'{tournament,lifecycle}',''))) not in ('UPCOMING','SCHEDULED')
     or coalesce((payload_body#>>'{tournament,team_1_score}')::numeric, 0) <> 0
     or coalesce((payload_body#>>'{tournament,team_2_score}')::numeric, 0) <> 0
     or jsonb_typeof(payload_body->'rules') <> 'array'
     or jsonb_array_length(payload_body->'rules') <> 3
     or (select count(distinct (rule->>'round_number')::integer)
         from jsonb_array_elements(payload_body->'rules') rule) <> 3
     or exists (
       select 1 from jsonb_array_elements(payload_body->'rules') rule
       where (rule->>'round_number')::integer not in (1,2,3)
          or upper(rule->>'format') <> case (rule->>'round_number')::integer
            when 1 then 'BB' when 2 then 'SC' when 3 then 'SI' end
     )
     or payload_body#>>'{pairing_contract,contract_version}' <> 'production-current-pairing-state-v1'
     or upper(btrim(coalesce(payload_body#>>'{pairing_contract,state}',''))) not in ('PENDING','PARTIAL','COMPLETE')
     or coalesce((payload_body#>>'{pairing_contract,no_pairings_inferred}')::boolean, false) is not true
     or payload_body#>>'{identity_reconciliation,join_key}' <> 'Player ID'
     or coalesce((payload_body#>>'{identity_reconciliation,historical_appearances_inferred}')::boolean, true)
     or jsonb_array_length(coalesce(payload_body#>'{identity_reconciliation,unresolved_current_only_ids}','[]'::jsonb)) <> 0
     or payload_body#>>'{shadow_safety,direction}' <> 'PRODUCTION_GOOGLE_TO_PRODUCTION_SUPABASE'
     or upper(btrim(coalesce(payload_body#>>'{shadow_safety,scoring_authority}',''))) <> 'GOOGLE'
     or coalesce((payload_body#>>'{shadow_safety,authoritative}')::boolean, true)
     or coalesce((payload_body#>>'{shadow_safety,scoring_ingress_enabled}')::boolean, true)
     or coalesce((payload_body#>>'{shadow_safety,google_outbox_enabled}')::boolean, true)
     or coalesce((payload_body#>>'{shadow_safety,scorecard_archive_enabled}')::boolean, true)
     or coalesce((payload_body#>>'{shadow_safety,google_mirror_enabled}')::boolean, true)
     or coalesce((payload_body#>>'{shadow_safety,participant_scoring_enabled}')::boolean, true)
     or coalesce((payload_body#>>'{shadow_safety,public_reads_enabled}')::boolean, true) then
    raise exception using errcode = '22023', message = 'PRODUCTION_CURRENT_SHADOW_PRE_TOURNAMENT_CONTRACT_REQUIRED';
  end if;

  if exists (
      select 1 from jsonb_array_elements(payload_body#>'{pairing_contract,matches}') value
      where value->>'state' = 'INVALID'
         or coalesce((value#>>'{activity,active}')::boolean, false)
         or coalesce((value#>>'{activity,scored}')::boolean, false)
         or coalesce((value#>>'{activity,access_active}')::boolean, false)
         or coalesce((value#>>'{activity,scoring_locked}')::boolean, false)
         or coalesce((value#>>'{activity,finalized}')::boolean, false)
    )
     or exists (
       select 1 from jsonb_array_elements(coalesce(payload_body->'matches','[]'::jsonb)) value
       where upper(coalesce(value->>'status','')) <> 'UPCOMING'
          or coalesce((value->>'scoring_locked')::boolean, false)
          or coalesce((value->>'scored_holes')::integer, 0) <> 0
          or coalesce((value->>'current_hole')::integer, 0) <> 0
          or coalesce((value->>'scorecard_complete')::boolean, false)
          or btrim(coalesce(value->>'finalized_at','')) <> ''
     )
     or jsonb_array_length(coalesce(payload_body->'hole_scores','[]'::jsonb)) <> 0
     or exists (
       select 1 from jsonb_array_elements(coalesce(payload_body->'permissions','[]'::jsonb)) value
       where coalesce((value->>'can_score')::boolean, false)
     ) then
    raise exception using errcode = '22023', message = 'PRODUCTION_CURRENT_SHADOW_ACTIVITY_PROHIBITED';
  end if;

  expected_match_count := jsonb_array_length(coalesce(payload_body->'matches','[]'::jsonb));
  if expected_match_count <> 24
     or jsonb_array_length(coalesce(payload_body->'players','[]'::jsonb)) <> 41
     or jsonb_array_length(coalesce(payload_body->'tournament_players','[]'::jsonb)) <> 24
     or jsonb_array_length(coalesce(payload_body->'teams','[]'::jsonb)) <> 2
     or jsonb_array_length(coalesce(payload_body->'rounds','[]'::jsonb)) <> 3
     or jsonb_array_length(coalesce(payload_body->'snapshots','[]'::jsonb)) <> expected_match_count
     or jsonb_array_length(coalesce(payload_body->'match_holes','[]'::jsonb)) <> expected_match_count * 18
     or jsonb_array_length(coalesce(payload_body->'permissions','[]'::jsonb))
        <> jsonb_array_length(coalesce(payload_body->'match_participants','[]'::jsonb))
     or (select count(distinct value->>'match_id') from jsonb_array_elements(payload_body->'matches') value)
        <> expected_match_count
     or jsonb_array_length(coalesce(payload_body#>'{pairing_contract,matches}','[]'::jsonb)) <> expected_match_count
     or (select count(*) from jsonb_array_elements(payload_body#>'{pairing_contract,matches}') pairing,
          lateral jsonb_array_elements(coalesce(pairing->'supplied_slots','[]'::jsonb)) supplied)
        <> jsonb_array_length(coalesce(payload_body->'match_participants','[]'::jsonb))
     or exists (
       select 1
       from jsonb_array_elements(payload_body#>'{pairing_contract,matches}') pairing,
         lateral jsonb_array_elements(coalesce(pairing->'supplied_slots','[]'::jsonb)) supplied
       where not exists (
         select 1 from jsonb_array_elements(payload_body->'match_participants') participant
         where participant->>'match_id' = pairing->>'match_id'
           and participant->>'player_id' = supplied->>'player_id'
           and (participant->>'team_side')::integer =
             substring(supplied->>'field' from '^Team ([12])')::integer
           and (participant->>'player_slot')::integer =
             substring(supplied->>'field' from 'Player ([12])$')::integer
       )
     )
     or exists (
       select 1 from jsonb_array_elements(payload_body->'match_participants') participant
       where not exists (
         select 1
         from jsonb_array_elements(payload_body#>'{pairing_contract,matches}') pairing,
           lateral jsonb_array_elements(coalesce(pairing->'supplied_slots','[]'::jsonb)) supplied
         where pairing->>'match_id' = participant->>'match_id'
           and supplied->>'player_id' = participant->>'player_id'
           and substring(supplied->>'field' from '^Team ([12])')::integer =
             (participant->>'team_side')::integer
           and substring(supplied->>'field' from 'Player ([12])$')::integer =
             (participant->>'player_slot')::integer
       )
     )
     or exists (
       select required.player_id
       from (values ('CM01'),('JK02'),('PN01')) required(player_id)
       where not exists (
         select 1 from jsonb_array_elements(coalesce(payload_body->'players','[]'::jsonb)) player
         where player->>'player_id' = required.player_id
       ) or not exists (
         select 1 from jsonb_array_elements(coalesce(payload_body->'tournament_players','[]'::jsonb)) roster
         where roster->>'player_id' = required.player_id
       )
     ) then
    raise exception using errcode = '22023', message = 'PRODUCTION_CURRENT_SHADOW_PAYLOAD_INCOMPLETE';
  end if;

  select count(*) into operational_trigger_count
  from pg_catalog.pg_trigger trigger_value
  where trigger_value.tgname in (
    'net_skins_hole_score_recalculation', 'tournament_storylines_score_change',
    'calcutta_official_match_change', 'capture_scorecard_archive_transition',
    'net_skins_match_lifecycle_recalculation', 'tournament_derived_match_change',
    'odds_google_mirror_supersession', 'tournament_storylines_net_skins_change'
  ) and trigger_value.tgenabled <> 'D';
  if operational_trigger_count > 0 then
    raise exception using errcode = '42501', message = 'PRODUCTION_OPERATIONAL_TRIGGER_MUST_REMAIN_DISABLED';
  end if;
  if exists (select 1 from scoring_authority.google_outbox_events where tournament_id = '2026')
     or exists (select 1 from scoring_authority.score_mutations mutation join scoring_authority.matches match_value using (match_id) where match_value.tournament_id = '2026')
     or exists (select 1 from scoring_authority.authority_epochs where tournament_id = '2026')
     or exists (select 1 from scoring_authority.scoring_ingress_leases where tournament_id = '2026')
     or exists (select 1 from scoring_authority.scorecard_archive_jobs where tournament_id = '2026')
     or exists (select 1 from scoring_authority.odds_google_mirror_jobs where tournament_id = '2026') then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_AUTHORITATIVE_ACTIVITY_PRESENT';
  end if;
  if exists (select 1 from auth.users)
     or exists (select 1 from production_control.director_entitlements where tournament_id = '2026')
     or exists (select 1 from participant_identity.participant_identity_contacts where tournament_id = '2026')
     or exists (select 1 from participant_identity.participant_auth_otp_attempts where tournament_id = '2026')
     or exists (select 1 from participant_identity.participant_auth_identifiers where source_tournament_id = '2026')
     or exists (
       select 1 from participant_identity.user_player_links link
       join scoring_authority.tournament_players player on player.player_id = link.player_id
       where player.tournament_id = '2026'
     ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_IDENTITY_ACTIVITY_PRESENT';
  end if;

  perform pg_advisory_xact_lock(hashtext('production-current-shadow-v2-2026'));
  select * into existing_run from production_control.import_runs run
  where run.domain = 'CURRENT_SCORING_SHADOW'
    and run.tournament_id = '2026'
    and run.tournament_year = 2026
    and run.source_workbook_id = scope.google_workbook_id
    and run.source_fingerprint = source_fingerprint_value
    and run.payload_fingerprint = payload_fingerprint_value
    and run.status = 'SUCCEEDED'
  order by run.completed_at desc limit 1;
  if claim.status = 'CONSUMED' and (
    existing_run.import_run_id is null or claim.import_run_id <> existing_run.import_run_id
  ) then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_CURRENT_SHADOW_CONSUMED_CLAIM_DRIFT';
  end if;
  if existing_run.import_run_id is not null then
    current_projection := production_control.current_tournament_shadow_projection('2026');
    database_fingerprint_value := encode(extensions.digest(current_projection::text,'sha256'),'hex');
    if database_fingerprint_value <> existing_run.database_fingerprint then
      raise exception using errcode = 'P0001', message = 'PRODUCTION_CURRENT_SHADOW_DRIFT_DETECTED';
    end if;
    update production_control.current_shadow_import_claims
    set status = 'CONSUMED', consumed_at = now(), import_run_id = existing_run.import_run_id
    where claim_id = claim.claim_id;
    return jsonb_build_object('ok',true,'changed',false,'duplicate',true,
      'import_run_id',existing_run.import_run_id,'database_fingerprint',database_fingerprint_value,
      'authority','GOOGLE','scoring_ingress','DISABLED','google_write',false);
  end if;

  select import_run_id into previous_tournament_run_id
  from production_control.import_runs
  where domain = 'CURRENT_TOURNAMENT' and tournament_id = '2026' and status = 'SUCCEEDED'
  order by completed_at desc nulls last limit 1;
  select import_run_id into previous_scoring_run_id
  from production_control.import_runs
  where domain = 'CURRENT_SCORING_SHADOW' and tournament_id = '2026' and status = 'SUCCEEDED'
  order by completed_at desc nulls last limit 1;

  delete from scoring_authority.matches where tournament_id = '2026';
  delete from scoring_authority.scoring_snapshots where tournament_id = '2026';
  delete from scoring_authority.ingress_gates where tournament_id = '2026';
  delete from scoring_authority.tournament_players where tournament_id = '2026';
  delete from scoring_authority.rounds where tournament_id = '2026';
  delete from scoring_authority.teams where tournament_id = '2026';

  insert into scoring_authority.tournaments (
    tournament_id,tournament_year,name,source_workbook_id,scoring_authority,imported_at,updated_at
  ) values (
    '2026',2026,payload_body#>>'{tournament,name}',scope.google_workbook_id,'GOOGLE',now(),now()
  ) on conflict (tournament_id) do update set
    tournament_year=excluded.tournament_year,name=excluded.name,
    source_workbook_id=excluded.source_workbook_id,scoring_authority='GOOGLE',
    imported_at=now(),updated_at=now();

  for item in select value from jsonb_array_elements(payload_body->'players') loop
    insert into scoring_authority.players (player_id,display_name,source_payload)
    values (item->>'player_id',item->>'display_name',coalesce(item->'source_payload','{}'::jsonb))
    on conflict (player_id) do update set display_name=excluded.display_name,
      source_payload=scoring_authority.players.source_payload || excluded.source_payload,
      updated_at=now();
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'teams') loop
    insert into scoring_authority.teams (tournament_id,team_id,team_side,name,source_payload)
    values ('2026',item->>'team_id',(item->>'team_side')::integer,item->>'name',coalesce(item->'source_payload','{}'::jsonb))
    on conflict (tournament_id,team_id) do update set team_side=excluded.team_side,
      name=excluded.name,source_payload=excluded.source_payload;
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'tournament_players') loop
    insert into scoring_authority.tournament_players (
      tournament_id,player_id,team_id,team_side,participation_status,source_roster_key,source_payload
    ) values ('2026',item->>'player_id',item->>'team_id',(item->>'team_side')::integer,
      coalesce(item->>'participation_status','ACTIVE'),item->>'source_roster_key',coalesce(item->'source_payload','{}'::jsonb));
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'rounds') loop
    insert into scoring_authority.rounds (
      tournament_id,round_number,format,name,handicap_allowance,status,source_payload
    ) values ('2026',(item->>'round_number')::integer,item->>'format',item->>'name',
      nullif(item->>'handicap_allowance','')::numeric,coalesce(item->>'status','UPCOMING'),coalesce(item->'source_payload','{}'::jsonb))
    on conflict (tournament_id,round_number) do update set format=excluded.format,name=excluded.name,
      handicap_allowance=excluded.handicap_allowance,status=excluded.status,source_payload=excluded.source_payload;
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'snapshots') loop
    insert into scoring_authority.scoring_snapshots (
      snapshot_id,tournament_id,match_id,snapshot_revision,scoring_rules_version,format,
      handicap_allowance,course_id,tee,rating,slope,par,match_netting_baseline,
      hole_definitions,participant_configuration,team_configuration,effective_at,canonical_hash
    ) values (item->>'snapshot_id','2026',item->>'match_id',(item->>'snapshot_revision')::bigint,
      item->>'scoring_rules_version',item->>'format',nullif(item->>'handicap_allowance','')::numeric,
      item->>'course_id',item->>'tee',nullif(item->>'rating','')::numeric,
      nullif(item->>'slope','')::integer,(item->>'par')::integer,item->>'match_netting_baseline',
      item->'hole_definitions',item->'participant_configuration',item->'team_configuration',
      nullif(item->>'effective_at','')::timestamptz,item->>'canonical_hash');
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'matches') loop
    insert into scoring_authority.matches (
      match_id,tournament_id,round_number,format,scoring_snapshot_id,status,scoring_locked,
      permission_revision,match_revision,source_google_revision,scored_holes,current_hole,
      holes_remaining,team_1_holes_won,team_2_holes_won,running_result,result_winner,
      clinched,scorecard_complete,unresolved_mutations,source_google_updated_at,authority_updated_at,finalized_at
    ) values (item->>'match_id','2026',(item->>'round_number')::integer,item->>'format',item->>'scoring_snapshot_id',
      'UPCOMING',false,coalesce((item->>'permission_revision')::bigint,1),coalesce((item->>'match_revision')::bigint,0),
      coalesce((item->>'source_google_revision')::bigint,0),0,0,18,0,0,
      coalesce(item->>'running_result','Scheduled'),'',false,false,0,
      nullif(item->>'source_google_updated_at','')::timestamptz,
      coalesce(nullif(item->>'authority_updated_at','')::timestamptz,now()),null);
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'match_participants') loop
    insert into scoring_authority.match_participants (
      match_id,player_id,team_side,player_slot,handicap_index,course_handicap,playing_handicap,final_strokes
    ) values (item->>'match_id',item->>'player_id',(item->>'team_side')::integer,(item->>'player_slot')::integer,
      nullif(item->>'handicap_index','')::numeric,nullif(item->>'course_handicap','')::numeric,
      coalesce((item->>'playing_handicap')::numeric,0),coalesce((item->>'final_strokes')::integer,0));
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'permissions') loop
    insert into scoring_authority.scoring_permissions (match_id,player_id,can_score,permission_revision,revoked_at)
    values (item->>'match_id',item->>'player_id',false,coalesce((item->>'permission_revision')::bigint,1),null);
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'match_holes') loop
    insert into scoring_authority.match_holes (match_id,hole_number,snapshot_id,stroke_index,par,yardage)
    values (item->>'match_id',(item->>'hole_number')::integer,item->>'snapshot_id',
      (item->>'stroke_index')::integer,(item->>'par')::integer,nullif(item->>'yardage','')::integer);
  end loop;
  for item in select value from jsonb_array_elements(payload_body->'checkpoints') loop
    insert into scoring_authority.google_match_checkpoints (
      match_id,last_supabase_match_revision,google_match_updated_at,google_match_revision,
      google_hole_revisions,verified_fingerprint,verified_at
    ) values (item->>'match_id',(item->>'last_supabase_match_revision')::bigint,
      nullif(item->>'google_match_updated_at','')::timestamptz,
      coalesce((item->>'google_match_revision')::bigint,0),coalesce(item->'google_hole_revisions','{}'::jsonb),
      item->>'verified_fingerprint',now());
  end loop;
  insert into scoring_authority.ingress_gates (
    tournament_id,state,authority,active_epoch_id,unresolved_client_queues,updated_by
  ) values ('2026','PAUSED','GOOGLE',null,0,claim.actor);

  if exists (select 1 from scoring_authority.google_outbox_events where tournament_id = '2026')
     or exists (select 1 from scoring_authority.scorecard_archive_jobs where tournament_id = '2026')
     or exists (select 1 from scoring_authority.odds_google_mirror_jobs where tournament_id = '2026') then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_SHADOW_IMPORT_CREATED_DELIVERY_WORK';
  end if;

  counts_value := jsonb_build_object(
    'players',jsonb_array_length(payload_body->'players'),
    'tournament_players',jsonb_array_length(payload_body->'tournament_players'),
    'teams',jsonb_array_length(payload_body->'teams'),
    'rounds',jsonb_array_length(payload_body->'rounds'),
    'snapshots',jsonb_array_length(payload_body->'snapshots'),
    'matches',jsonb_array_length(payload_body->'matches'),
    'match_participants',jsonb_array_length(payload_body->'match_participants'),
    'permissions',jsonb_array_length(payload_body->'permissions'),
    'match_holes',jsonb_array_length(payload_body->'match_holes'),
    'hole_scores',0,'checkpoints',jsonb_array_length(payload_body->'checkpoints'),
    'pairing_state',payload_body#>>'{pairing_contract,state}'
  );
  current_projection := production_control.current_tournament_shadow_projection('2026');
  database_fingerprint_value := encode(extensions.digest(current_projection::text,'sha256'),'hex');

  insert into production_control.import_runs (
    import_run_id,domain,tournament_id,tournament_year,source_workbook_id,
    source_fingerprint,payload_fingerprint,database_fingerprint,importer_contract,
    actor,status,previous_import_run_id,counts,started_at,completed_at
  ) values (tournament_run_id,'CURRENT_TOURNAMENT','2026',2026,scope.google_workbook_id,
    source_fingerprint_value,payload_fingerprint_value,database_fingerprint_value,
    'production-current-shadow-v2',claim.actor,'SUCCEEDED',previous_tournament_run_id,counts_value,now(),now());
  insert into production_control.import_runs (
    import_run_id,domain,tournament_id,tournament_year,source_workbook_id,
    source_fingerprint,payload_fingerprint,database_fingerprint,importer_contract,
    actor,status,previous_import_run_id,counts,started_at,completed_at
  ) values (scoring_run_id,'CURRENT_SCORING_SHADOW','2026',2026,scope.google_workbook_id,
    source_fingerprint_value,payload_fingerprint_value,database_fingerprint_value,
    'production-current-shadow-v2',claim.actor,'SUCCEEDED',previous_scoring_run_id,counts_value,now(),now());

  insert into production_control.current_shadow_revisions (
    import_run_id,tournament_id,tournament_year,source_workbook_id,source_fingerprint,
    payload_fingerprint,pairing_state,current_context,tournament_rules,
    identity_reconciliation,shadow_safety,source_payload,imported_by
  ) values (scoring_run_id,'2026',2026,scope.google_workbook_id,source_fingerprint_value,
    payload_fingerprint_value,payload_body#>>'{pairing_contract,state}',payload_body->'tournament',
    payload_body->'rules',payload_body->'identity_reconciliation',payload_body->'shadow_safety',
    input->'source_payload',claim.actor);

  update production_control.current_shadow_import_claims
  set status='CONSUMED',consumed_at=now(),import_run_id=scoring_run_id
  where claim_id=claim.claim_id;
  insert into production_control.operation_audit_events (
    event_type,domain,tournament_id,actor,request_fingerprint,result,details
  ) values ('CURRENT_SHADOW_IMPORTED','CURRENT_TOURNAMENT','2026',claim.actor,
    claim.request_fingerprint,'SUCCEEDED',jsonb_build_object(
      'currentTournamentImportRunId',tournament_run_id,'currentScoringImportRunId',scoring_run_id,
      'claimId',claim.claim_id,'pairingState',payload_body#>>'{pairing_contract,state}',
      'counts',counts_value,'authority','GOOGLE','ingress','PAUSED','googleWrite',false,
      'outbox',false,'archive',false,'mirror',false,'singleUseBootstrap',true));

  return jsonb_build_object('ok',true,'changed',true,'duplicate',false,
    'current_tournament_import_run_id',tournament_run_id,
    'current_scoring_import_run_id',scoring_run_id,'source_fingerprint',source_fingerprint_value,
    'payload_fingerprint',payload_fingerprint_value,'database_fingerprint',database_fingerprint_value,
    'counts',counts_value,'pairing_state',payload_body#>>'{pairing_contract,state}',
    'authority','GOOGLE','scoring_ingress','DISABLED','google_write',false,
    'outbox_events',0,'archive_jobs',0,'mirror_jobs',0);
end;
$_$;


ALTER FUNCTION public.import_production_current_tournament_shadow(input jsonb) OWNER TO postgres;

--
-- Name: import_production_director_identity_projection(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_director_identity_projection(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare scope production_control.resource_scope%rowtype;
declare existing_run participant_identity.identity_config_import_runs%rowtype;
declare source_value jsonb;
declare payload_value jsonb;
declare request_value jsonb;
declare expected_source jsonb;
declare expected_payload jsonb;
declare expected_request jsonb;
declare source_text text := coalesce(input->>'source_canonical_json', '');
declare payload_text text := coalesce(input->>'payload_canonical_json', '');
declare request_text text := coalesce(input->>'request_canonical_json', '');
declare source_hash text := lower(btrim(coalesce(input->>'source_fingerprint', '')));
declare payload_hash text := lower(btrim(coalesce(input->>'payload_fingerprint', '')));
declare request_hash text := lower(btrim(coalesce(input->>'request_fingerprint', '')));
declare current_source_hash text := lower(btrim(coalesce(input->>'current_shadow_source_fingerprint', '')));
declare email_hash text := lower(btrim(coalesce(input->>'email_identity_hash', '')));
declare target_player text := upper(btrim(coalesce(input->>'player_id', '')));
declare normalized_email text;
declare approved_by_value text;
declare approved_at_value timestamptz;
declare approved_at_text text;
declare evidence_reference text;
declare evidence_reference_hash text;
declare approval_evidence_hash text;
declare current_shadow production_control.current_shadow_revisions%rowtype;
declare active_roster_count integer;
declare next_revision bigint;
declare run_id_value uuid := extensions.gen_random_uuid();
begin
  scope := production_control.assert_production_director_identity_bootstrap();
  if upper(btrim(coalesce(input->>'environment', ''))) <> 'PRODUCTION'
    or btrim(coalesce(input->>'project_ref', '')) <> scope.project_ref
    or btrim(coalesce(input->>'project_url', '')) <> scope.project_url
    or btrim(coalesce(input->>'source_workbook_id', '')) <> scope.google_workbook_id
    or btrim(coalesce(input->>'tournament_id', '')) <> '2026'
    or coalesce((input->>'tournament_year')::integer, 0) <> 2026
    or btrim(coalesce(input->>'contract_version', '')) <> 'production-director-identity-bootstrap-v1'
    or btrim(coalesce(input->>'operation', '')) <> 'PRODUCTION_DIRECTOR_IDENTITY_IMPORT'
    or btrim(coalesce(input->>'actor_id', '')) <> 'step10b-production-auth-bootstrap'
    or target_player !~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'
    or source_hash !~ '^[0-9a-f]{64}$'
    or payload_hash !~ '^[0-9a-f]{64}$'
    or request_hash !~ '^[0-9a-f]{64}$'
    or current_source_hash !~ '^[0-9a-f]{64}$'
    or email_hash !~ '^[0-9a-f]{64}$'
    or btrim(source_text) = '' or btrim(payload_text) = '' or btrim(request_text) = '' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_EXACT_SCOPE_REQUIRED';
  end if;

  begin
    source_value := source_text::jsonb;
    payload_value := payload_text::jsonb;
    request_value := request_text::jsonb;
    approved_at_text := btrim(coalesce(payload_value#>>'{approval,approved_at}', ''));
    approved_at_value := approved_at_text::timestamptz;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_EVIDENCE_INVALID';
  end;

  normalized_email := lower(btrim(coalesce(payload_value#>>'{contact,email_normalized}', '')));
  approved_by_value := btrim(coalesce(payload_value#>>'{approval,approved_by}', ''));
  evidence_reference := btrim(coalesce(source_value#>>'{approval,evidence_reference}', ''));
  evidence_reference_hash := lower(btrim(coalesce(payload_value#>>'{approval,evidence_reference_hash}', '')));
  approval_evidence_hash := lower(btrim(coalesce(payload_value#>>'{approval,evidence_fingerprint}', '')));
  if normalized_email !~* '^[A-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$'::text collate "C"
    or approved_by_value = '' or length(approved_by_value) > 160
    or approved_by_value ~ E'[\r\n]'
    or approved_at_value > now() + interval '1 minute'
    or evidence_reference = '' or length(evidence_reference) > 240
    or evidence_reference ~ E'[\r\n]'
    or evidence_reference_hash !~ '^[0-9a-f]{64}$'
    or approval_evidence_hash !~ '^[0-9a-f]{64}$'
    or encode(extensions.digest(evidence_reference, 'sha256'), 'hex') <> evidence_reference_hash
    or encode(extensions.digest(concat_ws(E'\n', approved_at_text, approved_by_value,
      evidence_reference_hash, target_player), 'sha256'), 'hex') <> approval_evidence_hash
    or encode(extensions.digest(normalized_email, 'sha256'), 'hex') <> email_hash then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_APPROVED_EVIDENCE_REQUIRED';
  end if;

  expected_source := jsonb_build_object(
    'approval', jsonb_build_object(
      'approved_at', approved_at_text,
      'approved_by', approved_by_value,
      'evidence_kind', 'PRODUCTION_OWNER_APPROVED_DIRECTOR_IDENTITY',
      'evidence_reference', evidence_reference
    ),
    'contact', jsonb_build_object(
      'email_normalized', normalized_email,
      'identity_active', true,
      'player_id', target_player
    ),
    'current_shadow_source_fingerprint', current_source_hash,
    'environment', 'PRODUCTION',
    'project_ref', scope.project_ref,
    'project_url', scope.project_url,
    'source_workbook_id', scope.google_workbook_id,
    'tournament_id', '2026',
    'tournament_year', 2026
  );
  expected_payload := jsonb_build_object(
    'approval', jsonb_build_object(
      'approved_at', approved_at_text,
      'approved_by', approved_by_value,
      'evidence_fingerprint', approval_evidence_hash,
      'evidence_kind', 'PRODUCTION_OWNER_APPROVED_DIRECTOR_IDENTITY',
      'evidence_reference_hash', evidence_reference_hash
    ),
    'contact', jsonb_build_object(
      'email', normalized_email,
      'email_identity_hash', email_hash,
      'email_normalized', normalized_email,
      'identity_active', true,
      'player_id', target_player
    ),
    'current_shadow_source_fingerprint', current_source_hash
  );
  expected_request := jsonb_build_object(
    'actor_id', 'step10b-production-auth-bootstrap',
    'contract_version', 'production-director-identity-bootstrap-v1',
    'current_shadow_source_fingerprint', current_source_hash,
    'email_identity_hash', email_hash,
    'environment', 'PRODUCTION',
    'operation', 'PRODUCTION_DIRECTOR_IDENTITY_IMPORT',
    'payload_fingerprint', payload_hash,
    'player_id', target_player,
    'project_ref', scope.project_ref,
    'project_url', scope.project_url,
    'source_fingerprint', source_hash,
    'source_workbook_id', scope.google_workbook_id,
    'tournament_id', '2026',
    'tournament_year', 2026
  );
  if source_value is distinct from expected_source
    or payload_value is distinct from expected_payload
    or input->'payload' is distinct from expected_payload
    or request_value is distinct from expected_request
    or encode(extensions.digest(source_text, 'sha256'), 'hex') <> source_hash
    or encode(extensions.digest(payload_text, 'sha256'), 'hex') <> payload_hash
    or encode(extensions.digest(request_text, 'sha256'), 'hex') <> request_hash then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_EVIDENCE_MISMATCH';
  end if;

  select value.* into current_shadow
  from production_control.current_shadow_revisions value
  where value.tournament_id = '2026'
  order by value.imported_at desc, value.import_run_id desc
  limit 1;
  if current_shadow.import_run_id is null
    or current_shadow.source_workbook_id <> scope.google_workbook_id
    or current_shadow.source_fingerprint <> current_source_hash then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_CURRENT_SHADOW_REQUIRED';
  end if;
  if not exists (
    select 1 from scoring_authority.tournament_players membership
    where membership.tournament_id = '2026'
      and membership.player_id = target_player
      and membership.participation_status = 'ACTIVE'
  ) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_ACTIVE_PLAYER_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('production-director-identity-bootstrap-2026', 0));
  select value.* into existing_run
  from participant_identity.identity_config_import_runs value
  where value.tournament_id = '2026'
    and value.source_system = 'PRODUCTION_OWNER_APPROVED_IDENTITY_EVIDENCE'
    and value.source_workbook_id = scope.google_workbook_id
    and value.source_fingerprint = source_hash
  order by value.requested_at desc
  limit 1 for update;
  if found then
    if existing_run.configuration_revision <= 0
      or existing_run.status not in ('REVIEW_REQUIRED', 'APPROVED')
      or existing_run.validation_report->>'contractVersion' <> 'production-director-identity-bootstrap-v1'
      or existing_run.validation_report->>'scope' <> 'ONE_PRODUCTION_DIRECTOR_CANDIDATE'
      or existing_run.validation_report->>'playerId' <> target_player
      or existing_run.validation_report->>'emailIdentityHash' <> email_hash
      or existing_run.validation_report->>'payloadFingerprint' <> payload_hash
      or existing_run.validation_report->>'currentShadowSourceFingerprint' <> current_source_hash
      or existing_run.validation_report->>'approvalEvidenceFingerprint' <> approval_evidence_hash
      or (select count(*) from participant_identity.identity_config_import_runs
          where tournament_id = '2026') <> 1
      or (select count(*) from participant_identity.participant_identity_contacts
          where tournament_id = '2026') <> 1
      or not exists (
        select 1 from participant_identity.participant_identity_contacts contact
        join participant_identity.identity_context_revisions revision
          on revision.tournament_id = contact.tournament_id
          and revision.context_revision = contact.configuration_revision
          and revision.configuration_fingerprint = source_hash
        where contact.tournament_id = '2026'
          and contact.player_id = target_player
          and contact.configuration_revision = existing_run.configuration_revision
          and contact.identity_active
          and contact.source_workbook_id = scope.google_workbook_id
          and encode(extensions.digest(contact.email_normalized, 'sha256'), 'hex') = email_hash
      ) then
      raise exception using errcode = 'P0001',
        message = 'PRODUCTION_DIRECTOR_IDENTITY_DUPLICATE_DRIFT';
    end if;
    return jsonb_build_object('ok', true, 'runId', existing_run.run_id,
      'status', existing_run.status, 'configurationRevision', existing_run.configuration_revision,
      'sourceFingerprint', source_hash, 'payloadFingerprint', payload_hash,
      'playerId', target_player, 'duplicate', true, 'contactsImported', 1,
      'authUsersCreated', 0, 'authoritativeIdentityChanged', false,
      'googleWrite', false, 'previewRpcUsed', false);
  end if;

  if exists (select 1 from participant_identity.identity_config_import_runs where tournament_id = '2026')
    or exists (select 1 from participant_identity.participant_identity_contacts where tournament_id = '2026')
    or exists (select 1 from participant_identity.identity_context_revisions where tournament_id = '2026')
    or exists (select 1 from participant_identity.production_auth_candidates where tournament_id = '2026')
    or exists (select 1 from participant_identity.production_auth_preprovision_claims)
    or exists (select 1 from participant_identity.user_player_links)
    or exists (select 1 from participant_identity.participant_auth_identifiers)
    or exists (select 1 from participant_identity.participant_auth_otp_attempts)
    or exists (select 1 from auth.users) then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_CLEAN_FOUNDATION_REQUIRED';
  end if;

  select count(*) into active_roster_count
  from scoring_authority.tournament_players
  where tournament_id = '2026' and participation_status = 'ACTIVE';
  if active_roster_count < 1 then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_DIRECTOR_IDENTITY_ACTIVE_ROSTER_REQUIRED';
  end if;
  next_revision := 1;

  insert into participant_identity.identity_config_import_runs (
    run_id, tournament_id, source_system, source_workbook_id, source_fingerprint,
    configuration_revision, status, roster_count, received_count, valid_count,
    missing_count, duplicate_count, malformed_count, shared_count, inactive_count,
    unknown_player_count, mapping_conflict_count, validation_report, requested_by
  ) values (
    run_id_value, '2026', 'PRODUCTION_OWNER_APPROVED_IDENTITY_EVIDENCE',
    scope.google_workbook_id, source_hash, next_revision, 'REVIEW_REQUIRED',
    active_roster_count, 1, 1, greatest(active_roster_count - 1, 0), 0, 0, 0, 0, 0, 0,
    jsonb_build_object(
      'contractVersion', 'production-director-identity-bootstrap-v1',
      'scope', 'ONE_PRODUCTION_DIRECTOR_CANDIDATE',
      'boundedCandidateValid', true, 'fullRosterProjection', false,
      'explicitOwnerApprovalRequired', true,
      'playerId', target_player, 'emailIdentityHash', email_hash,
      'sourceFingerprint', source_hash, 'payloadFingerprint', payload_hash,
      'currentShadowSourceFingerprint', current_source_hash,
      'approvalEvidenceFingerprint', approval_evidence_hash,
      'evidenceReferenceHash', evidence_reference_hash,
      'approvedBy', approved_by_value, 'approvedAt', approved_at_text,
      'rawEmailStoredInValidationReport', false,
      'authUsersCreated', 0, 'googleWrite', false, 'previewRpcUsed', false
    ),
    'step10b-production-auth-bootstrap'
  );

  insert into participant_identity.participant_identity_contacts (
    tournament_id, player_id, email, email_normalized, identity_active,
    configuration_revision, verified_by, verified_at, source_system,
    source_workbook_id, source_updated_at
  ) values (
    '2026', target_player, normalized_email, normalized_email, true,
    next_revision, approved_by_value, approved_at_value,
    'PRODUCTION_OWNER_APPROVED_IDENTITY_EVIDENCE', scope.google_workbook_id,
    approved_at_value
  );
  insert into participant_identity.identity_context_revisions (
    tournament_id, context_revision, configuration_fingerprint, updated_by
  ) values ('2026', next_revision, source_hash, 'step10b-production-auth-bootstrap');
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, player_id, actor_name, request_id,
    configuration_revision, safe_metadata
  ) values (
    'PRODUCTION_DIRECTOR_IDENTITY_IMPORTED', '2026', target_player,
    'step10b-production-auth-bootstrap', run_id_value::text, next_revision,
    jsonb_build_object('sourceFingerprint', source_hash, 'payloadFingerprint', payload_hash,
      'approvalEvidenceFingerprint', approval_evidence_hash,
      'scope', 'ONE_PRODUCTION_DIRECTOR_CANDIDATE', 'rawEmailStoredInAudit', false,
      'authUsersCreated', 0, 'authoritativeIdentityChanged', false,
      'googleWrite', false, 'previewRpcUsed', false)
  );
  return jsonb_build_object('ok', true, 'runId', run_id_value,
    'status', 'REVIEW_REQUIRED', 'configurationRevision', next_revision,
    'sourceFingerprint', source_hash, 'payloadFingerprint', payload_hash,
    'playerId', target_player, 'duplicate', false, 'contactsImported', 1,
    'authUsersCreated', 0, 'authoritativeIdentityChanged', false,
    'googleWrite', false, 'previewRpcUsed', false);
end;
$_$;


ALTER FUNCTION public.import_production_director_identity_projection(input jsonb) OWNER TO postgres;

--
-- Name: import_production_draft_projection(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_draft_projection(input jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $_$
  select production_control.mark_projection_operation_response(
    public.import_production_draft_projection_dormant_internal($1), 'DRAFT'
  )
$_$;


ALTER FUNCTION public.import_production_draft_projection(input jsonb) OWNER TO postgres;

--
-- Name: import_production_draft_projection_dormant_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_draft_projection_dormant_internal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  tabs constant jsonb := '["Draft Settings","Draft Picks"]'::jsonb;
  registration jsonb;
  draft jsonb;
  pick jsonb;
  target text;
  target_year integer;
  current_revision scoring_authority.draft_revisions%rowtype;
  inserted_revision scoring_authority.draft_revisions%rowtype;
  next_revision bigint;
  operation_value text;
  correction text;
  pick_count integer;
  distinct_pick_count integer;
  selected_count integer;
  distinct_player_count integer;
  minimum_pick integer;
  maximum_pick integer;
  results jsonb := '[]'::jsonb;
begin
  perform production_control.assert_projection_scope(input,'DRAFT','draft-projection-v1',tabs);
  if upper(input->>'validation_status')<>'VALID'
     or jsonb_typeof(input#>'{payload,drafts}')<>'array'
     or jsonb_array_length(input#>'{payload,drafts}')=0 then
    return jsonb_build_object('ok',false,'code','COMPLETE_VALID_PRODUCTION_DRAFT_PROJECTION_REQUIRED');
  end if;
  -- Validate the complete batch before registering or writing any revision.
  for draft in select value from jsonb_array_elements(input#>'{payload,drafts}') loop
    target:=btrim(coalesce(draft->>'tournament_id',''));
    target_year:=coalesce((draft->>'tournament_year')::integer,0);
    if target<>target_year::text or target_year not between 2017 and 2026
       or lower(btrim(coalesce(draft->>'source_fingerprint',''))) !~ '^[0-9a-f]{64}$'
       or lower(btrim(coalesce(draft->>'configuration_fingerprint',''))) !~ '^[0-9a-f]{64}$'
       or lower(btrim(coalesce(draft->>'picks_fingerprint',''))) !~ '^[0-9a-f]{64}$'
       or lower(btrim(coalesce(draft->>'payload_fingerprint',''))) !~ '^[0-9a-f]{64}$'
       or upper(btrim(coalesce(draft->>'validation_status',''))) <> 'VALID'
       or jsonb_typeof(draft->'validation_diagnostics')<>'object'
       or jsonb_typeof(draft->'source_settings')<>'object'
       or jsonb_typeof(draft->'source_picks')<>'array'
       or jsonb_typeof(draft->'configuration')<>'object'
       or jsonb_typeof(draft->'picks')<>'array'
       or jsonb_typeof(draft->'presentation_seed')<>'object'
       or not exists(select 1 from scoring_authority.tournaments t
         where t.tournament_id=target and t.tournament_year=target_year
           and t.source_workbook_id=input->>'source_workbook_id') then
      return jsonb_build_object('ok',false,'code','PRODUCTION_DRAFT_REVISION_INVALID','year',target_year);
    end if;
    pick_count:=jsonb_array_length(draft->'picks');
    if pick_count=0 or pick_count<>coalesce((draft#>>'{configuration,total_picks}')::integer,0)
       or not exists(select 1 from scoring_authority.teams where tournament_id=target and team_id=draft#>>'{configuration,team_1_id}')
       or not exists(select 1 from scoring_authority.teams where tournament_id=target and team_id=draft#>>'{configuration,team_2_id}')
       or not exists(select 1 from scoring_authority.teams where tournament_id=target and team_id=draft#>>'{configuration,first_pick_team_id}') then
      return jsonb_build_object('ok',false,'code','PRODUCTION_DRAFT_CONFIGURATION_INVALID','year',target_year);
    end if;
    select count(distinct (value->>'pick_number')::integer),min((value->>'pick_number')::integer),
      max((value->>'pick_number')::integer),
      count(*) filter(where nullif(value->>'player_id','') is not null),
      count(distinct nullif(value->>'player_id','')) filter(where nullif(value->>'player_id','') is not null)
    into distinct_pick_count,minimum_pick,maximum_pick,selected_count,distinct_player_count
    from jsonb_array_elements(draft->'picks');
    if distinct_pick_count<>pick_count or minimum_pick<>1 or maximum_pick<>pick_count
       or selected_count<>distinct_player_count then
      return jsonb_build_object('ok',false,'code','PRODUCTION_DRAFT_PICK_ORDER_INVALID','year',target_year);
    end if;
    for pick in select value from jsonb_array_elements(draft->'picks') loop
      if (pick->>'round_number')::integer<>(((pick->>'pick_number')::integer-1)/2)+1
         or (pick->>'pick_within_round')::integer<>mod((pick->>'pick_number')::integer-1,2)+1
         or upper(btrim(coalesce(pick->>'status',''))) not in ('PENDING','SELECTED')
         or (upper(btrim(coalesce(pick->>'status','')))='PENDING' and nullif(pick->>'player_id','') is not null)
         or (upper(btrim(coalesce(pick->>'status','')))='SELECTED' and
           (nullif(pick->>'player_id','') is null or nullif(pick->>'team_id','') is null))
         or (nullif(pick->>'player_id','') is not null and not exists(
           select 1 from scoring_authority.tournament_players tp
           where tp.tournament_id=target and tp.player_id=pick->>'player_id' and tp.team_id=pick->>'team_id')) then
        return jsonb_build_object('ok',false,'code','PRODUCTION_DRAFT_PICK_INVALID','year',target_year,'pick',pick->>'pick_number');
      end if;
    end loop;
  end loop;

  registration:=production_control.register_projection_revision(input,'DRAFT','draft-projection-v1',tabs);
  if not coalesce((registration->>'changed')::boolean,false) then return registration; end if;
  perform set_config('scoring_authority.draft_projection_import','on',true);
  for draft in select value from jsonb_array_elements(input#>'{payload,drafts}') loop
    current_revision:=null;
    target:=draft->>'tournament_id'; target_year:=(draft->>'tournament_year')::integer;
    perform pg_advisory_xact_lock(hashtext('production-draft-projection:'||target));
    select r.* into current_revision from scoring_authority.draft_current_revisions c
    join scoring_authority.draft_revisions r on r.revision_id=c.revision_id
    where c.tournament_id=target for update of c;
    if current_revision.revision_id is not null and current_revision.payload_fingerprint=draft->>'payload_fingerprint' then
      results:=results||jsonb_build_array(jsonb_build_object('year',target_year,'changed',false,
        'revision_id',current_revision.revision_id,'revision_number',current_revision.revision_number));
      continue;
    end if;
    if current_revision.revision_id is null then operation_value:='INITIAL_IMPORT'; correction:=null;
    elsif target_year<2026 then
      correction:=nullif(btrim(coalesce(draft->>'correction_reason','')),'');
      if correction is null or length(correction)<10 then
        raise exception using errcode='23514',message='PRODUCTION_DRAFT_HISTORICAL_CORRECTION_REASON_REQUIRED';
      end if;
      operation_value:='HISTORICAL_CORRECTION';
    else operation_value:='CURRENT_SYNC'; correction:=null; end if;
    select coalesce(max(revision_number),0)+1 into next_revision
    from scoring_authority.draft_revisions where tournament_id=target;
    insert into scoring_authority.draft_revisions(
      project_ref,source_workbook_id,source_tabs,tournament_id,tournament_year,revision_number,
      previous_revision_id,source_fingerprint,configuration_fingerprint,picks_fingerprint,payload_fingerprint,
      contract_version,validation_status,validation_diagnostics,source_settings,source_picks,
      configuration,presentation_seed,operation,correction_reason,synchronized_by
    ) values(
      input->>'project_ref',input->>'source_workbook_id',tabs,target,target_year,next_revision,
      current_revision.revision_id,lower(draft->>'source_fingerprint'),lower(draft->>'configuration_fingerprint'),
      lower(draft->>'picks_fingerprint'),lower(draft->>'payload_fingerprint'),'draft-projection-v1','VALID',
      draft->'validation_diagnostics',draft->'source_settings',draft->'source_picks',draft->'configuration',
      draft->'presentation_seed',operation_value,correction,input->>'requested_by'
    ) returning * into inserted_revision;
    insert into scoring_authority.draft_configuration_facts(
      revision_id,tournament_id,tournament_year,draft_name,draft_date,draft_time,time_zone,location,
      status_mode,draft_format,total_picks,team_1_id,team_2_id,team_1_captain_player_id,
      team_2_captain_player_id,first_pick_team_id,notes
    ) values(
      inserted_revision.revision_id,target,target_year,draft#>>'{configuration,name}',
      nullif(draft#>>'{configuration,date}',''),nullif(draft#>>'{configuration,time}',''),
      nullif(draft#>>'{configuration,time_zone}',''),nullif(draft#>>'{configuration,location}',''),
      nullif(draft#>>'{configuration,status_mode}',''),nullif(draft#>>'{configuration,format}',''),
      (draft#>>'{configuration,total_picks}')::integer,draft#>>'{configuration,team_1_id}',
      draft#>>'{configuration,team_2_id}',nullif(draft#>>'{configuration,team_1_captain_player_id}',''),
      nullif(draft#>>'{configuration,team_2_captain_player_id}',''),
      draft#>>'{configuration,first_pick_team_id}',nullif(draft#>>'{configuration,notes}',''));
    insert into scoring_authority.draft_pick_facts(
      revision_id,tournament_id,tournament_year,pick_number,round_number,pick_within_round,
      source_team_id,team_id,player_id,player_name_snapshot,selected_at_source,selected_by_source,
      pick_status,notes,presentation_snapshot
    ) select inserted_revision.revision_id,target,target_year,(value->>'pick_number')::integer,
      (value->>'round_number')::integer,(value->>'pick_within_round')::integer,
      nullif(value->>'source_team_id',''),nullif(value->>'team_id',''),nullif(value->>'player_id',''),
      nullif(value->>'player_name',''),nullif(value->>'selected_at',''),nullif(value->>'selected_by',''),
      upper(value->>'status'),nullif(value->>'notes',''),coalesce(value->'presentation','{}'::jsonb)
    from jsonb_array_elements(draft->'picks');
    insert into scoring_authority.draft_current_revisions(tournament_id,tournament_year,revision_id,advanced_by)
    values(target,target_year,inserted_revision.revision_id,input->>'requested_by')
    on conflict(tournament_id) do update set tournament_year=excluded.tournament_year,
      revision_id=excluded.revision_id,advanced_by=excluded.advanced_by,advanced_at=now();
    results:=results||jsonb_build_array(jsonb_build_object('year',target_year,'changed',true,
      'operation',operation_value,'revision_id',inserted_revision.revision_id,
      'revision_number',inserted_revision.revision_number,'previous_revision_id',current_revision.revision_id));
  end loop;
  return registration||jsonb_build_object('drafts',results,'draft_count',jsonb_array_length(results),'shadow_only',true);
exception when others then
  return jsonb_build_object('ok',false,'code','PRODUCTION_DRAFT_PROJECTION_IMPORT_FAILED');
end;
$_$;


ALTER FUNCTION public.import_production_draft_projection_dormant_internal(input jsonb) OWNER TO postgres;

--
-- Name: import_production_guide_projection(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_guide_projection(input jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $_$
  select production_control.mark_projection_operation_response(
    public.import_production_guide_projection_dormant_internal($1), 'GUIDE'
  )
$_$;


ALTER FUNCTION public.import_production_guide_projection(input jsonb) OWNER TO postgres;

--
-- Name: import_production_guide_projection_dormant_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_guide_projection_dormant_internal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  tabs constant jsonb := '["Tournaments","Guide Sections","Tournament Itinerary","Tournament Timeline","Rule Book","Tournament Rules","Rounds","Dining","Local Guide","Important Contacts","Courses"]'::jsonb;
  registration jsonb;
  source_text text := coalesce(input->>'source_canonical_json','');
  content_text text := coalesce(input->>'content_canonical_json','');
  payload_text text := coalesce(input->>'payload_canonical_json','');
  source_value jsonb;
  content_value jsonb;
  payload_value jsonb;
  guide_revision_id uuid;
  revision_number bigint;
begin
  perform production_control.assert_projection_scope(input,'GUIDE','guide-projection-v1',tabs);
  if upper(input->>'validation_status') <> 'VALID'
     or btrim(source_text)='' or btrim(content_text)='' or btrim(payload_text)='' then
    return jsonb_build_object('ok',false,'code','VALIDATED_PRODUCTION_GUIDE_PROJECTION_REQUIRED');
  end if;
  begin
    source_value := source_text::jsonb;
    content_value := content_text::jsonb;
    payload_value := payload_text::jsonb;
  exception when invalid_text_representation then
    return jsonb_build_object('ok',false,'code','PRODUCTION_GUIDE_CANONICAL_JSON_INVALID');
  end;
  if jsonb_typeof(source_value)<>'object' or jsonb_typeof(content_value)<>'object'
     or jsonb_typeof(payload_value)<>'object'
     or source_value->>'tournamentId'<>'2026'
     or content_value#>>'{tournamentIdentity,id}'<>'2026'
     or coalesce((content_value#>>'{tournamentIdentity,year}')::integer,0)<>2026
     or payload_value<>input->'payload'
     or payload_value->>'schemaVersion'<>'guide-projection-v1'
     or payload_value->'content'<>content_value
     or encode(extensions.digest(source_text,'sha256'),'hex')<>lower(input->>'source_fingerprint')
     or encode(extensions.digest(content_text,'sha256'),'hex')<>lower(btrim(input->>'content_fingerprint'))
     or encode(extensions.digest(payload_text,'sha256'),'hex')<>lower(input->>'payload_fingerprint') then
    return jsonb_build_object('ok',false,'code','PRODUCTION_GUIDE_PROJECTION_HASH_MISMATCH');
  end if;
  if not exists(select 1 from scoring_authority.tournaments
    where tournament_id='2026' and tournament_year=2026
      and source_workbook_id=input->>'source_workbook_id') then
    return jsonb_build_object('ok',false,'code','PRODUCTION_GUIDE_TOURNAMENT_REQUIRED');
  end if;

  registration := production_control.register_projection_revision(input,'GUIDE','guide-projection-v1',tabs);
  if not coalesce((registration->>'changed')::boolean,false) then return registration; end if;
  revision_number := (registration->>'revision_number')::bigint;
  insert into scoring_authority.guide_content_revisions(
    tournament_id,projection_revision,source_workbook_id,content_fingerprint,
    source_workbook_fingerprint,payload_hash,source_canonical_json,content_canonical_json,
    payload_canonical_json,content_payload,validation_status,source_metadata,
    source_sync_sequence,trigger_type,imported_by
  ) values(
    '2026',revision_number,input->>'source_workbook_id',lower(input->>'content_fingerprint'),
    lower(input->>'source_fingerprint'),lower(input->>'payload_fingerprint'),source_text,
    content_text,payload_text,input->'payload','VALID',coalesce(input->'source_metadata','{}'::jsonb),
    revision_number,case when revision_number=1 then 'INITIAL' else 'MANUAL' end,input->>'requested_by'
  ) returning revision_id into guide_revision_id;
  insert into scoring_authority.guide_projection_current(
    tournament_id,source_workbook_id,revision_id,publication_sequence,source_sync_sequence
  ) values('2026',input->>'source_workbook_id',guide_revision_id,revision_number,revision_number)
  on conflict(tournament_id) do update set source_workbook_id=excluded.source_workbook_id,
    revision_id=excluded.revision_id,publication_sequence=excluded.publication_sequence,
    source_sync_sequence=excluded.source_sync_sequence,published_at=now(),last_verified_at=now();
  return registration || jsonb_build_object('guide_revision_id',guide_revision_id,
    'content_fingerprint',lower(input->>'content_fingerprint'),'shadow_only',true);
exception when others then
  return jsonb_build_object('ok',false,'code','PRODUCTION_GUIDE_PROJECTION_IMPORT_FAILED');
end;
$$;


ALTER FUNCTION public.import_production_guide_projection_dormant_internal(input jsonb) OWNER TO postgres;

