ALTER FUNCTION public.import_production_prediction_settings(input jsonb) OWNER TO postgres;

--
-- Name: import_production_prediction_settings_dormant_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_prediction_settings_dormant_internal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  tabs constant jsonb := '["Prediction Settings"]'::jsonb;
  registration jsonb;
  payload jsonb := input->'payload';
  current_config scoring_authority.odds_input_configurations%rowtype;
  next_revision bigint;
  next_bundle text;
  config_id uuid;
begin
  perform production_control.assert_projection_scope(input,'PREDICTION_SETTINGS','prediction-settings-v1',tabs);
  if upper(input->>'validation_status')<>'VALID'
     or jsonb_typeof(payload->'settings')<>'array'
     or jsonb_typeof(payload->'canonical_settings')<>'object'
     or jsonb_typeof(payload->'effective_settings')<>'object'
     or scoring_authority.jsonb_object_length(payload->'canonical_settings')<>30
     or scoring_authority.jsonb_object_length(payload->'effective_settings')<>30
     or lower(btrim(coalesce(payload->>'settings_fingerprint',''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(payload->>'effective_settings_fingerprint',''))) !~ '^[0-9a-f]{64}$'
     or coalesce(payload->>'settings_contract_version','')<>'prediction-settings-v1'
     or coalesce(payload->>'source_tab','')<>'Prediction Settings' then
    return jsonb_build_object('ok',false,'code','COMPLETE_VALID_PRODUCTION_PREDICTION_SETTINGS_REQUIRED');
  end if;
  select * into current_config from scoring_authority.odds_input_configurations
  where tournament_id='2026' and is_current for update;
  if current_config.id is null then
    return jsonb_build_object('ok',false,'code','PRODUCTION_ODDS_INPUT_CONFIGURATION_REQUIRED');
  end if;
  registration := production_control.register_projection_revision(input,'PREDICTION_SETTINGS','prediction-settings-v1',tabs);
  if not coalesce((registration->>'changed')::boolean,false) then return registration; end if;
  select coalesce(max(configuration_revision),0)+1 into next_revision
  from scoring_authority.odds_input_configurations where tournament_id='2026';
  next_bundle := encode(extensions.digest(jsonb_build_object(
    'tournament_id','2026','source_fingerprint',lower(input->>'source_fingerprint'),
    'effective_settings_fingerprint',lower(payload->>'effective_settings_fingerprint'),
    'ratings_fingerprint',current_config.ratings_fingerprint,
    'pairing_fingerprint',current_config.pairing_fingerprint,
    'previous_configuration_id',current_config.id,'configuration_revision',next_revision
  )::text,'sha256'),'hex');
  update scoring_authority.odds_input_configurations set is_current=false,superseded_at=now()
  where tournament_id='2026' and is_current;
  insert into scoring_authority.odds_input_configurations(
    tournament_id,configuration_revision,source_workbook_id,settings,historical_ratings,
    settings_fingerprint,ratings_fingerprint,pairing_fingerprint,bundle_fingerprint,is_current,
    imported_by,source_tab,source_fingerprint,canonical_settings,effective_settings,
    effective_settings_fingerprint,settings_contract_version,validation_status,
    validation_diagnostics,synchronized_at,previous_configuration_id
  ) values(
    '2026',next_revision,input->>'source_workbook_id',payload->'settings',current_config.historical_ratings,
    lower(payload->>'settings_fingerprint'),current_config.ratings_fingerprint,current_config.pairing_fingerprint,
    next_bundle,true,input->>'requested_by','Prediction Settings',lower(input->>'source_fingerprint'),
    payload->'canonical_settings',payload->'effective_settings',
    lower(payload->>'effective_settings_fingerprint'),'prediction-settings-v1','VALID',
    coalesce(input->'validation_diagnostics','{}'::jsonb),now(),current_config.id
  ) returning id into config_id;
  insert into scoring_authority.odds_input_import_runs(tournament_id,bundle_fingerprint,status,requested_by)
  values('2026',next_bundle,'APPLIED',input->>'requested_by');
  return registration || jsonb_build_object('configuration_id',config_id,
    'configuration_revision',next_revision,'bundle_fingerprint',next_bundle,
    'effective_settings_fingerprint',lower(payload->>'effective_settings_fingerprint'),'shadow_only',true);
exception when others then
  return jsonb_build_object('ok',false,'code','PRODUCTION_PREDICTION_SETTINGS_IMPORT_FAILED');
end;
$_$;


ALTER FUNCTION public.import_production_prediction_settings_dormant_internal(input jsonb) OWNER TO postgres;

--
-- Name: import_production_presentation_shadow_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_presentation_shadow_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  current_run production_control.import_runs%rowtype;
  current_revision production_control.presentation_shadow_revisions%rowtype;
  inserted_revision production_control.presentation_shadow_revisions%rowtype;
  source_text text := coalesce(input->>'source_canonical_json', '');
  payload_text text := coalesce(input->>'payload_canonical_json', '');
  request_text text := coalesce(input->>'request_canonical_json', '');
  source_value jsonb;
  payload_value jsonb;
  request_value jsonb;
  expected_request jsonb;
  rows_value jsonb;
  home_value jsonb;
  item jsonb;
  current_database_fingerprint text;
  database_projection jsonb;
  database_fingerprint_value text;
  next_revision bigint;
  counts_value jsonb;
begin
  scope := production_control.assert_production_presentation_shadow_scope(input);
  perform pg_advisory_xact_lock(hashtext('production-presentation-shadow:2026'));

  begin
    source_value := source_text::jsonb;
    payload_value := payload_text::jsonb;
    request_value := request_text::jsonb;
  exception when others then
    raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_CANONICAL_JSON_INVALID';
  end;
  expected_request := jsonb_build_object(
    'environment', 'PRODUCTION',
    'project_ref', scope.project_ref,
    'project_url', scope.project_url,
    'source_workbook_id', scope.google_workbook_id,
    'tournament_id', '2026',
    'tournament_year', 2026,
    'operation', 'PRODUCTION_PRESENTATION_SHADOW_IMPORT',
    'contract_version', 'production-presentation-shadow-v1',
    'requested_by', btrim(input->>'requested_by'),
    'current_shadow_import_run_id', btrim(input->>'current_shadow_import_run_id'),
    'current_shadow_source_fingerprint', lower(btrim(input->>'current_shadow_source_fingerprint')),
    'current_shadow_database_fingerprint', lower(btrim(input->>'current_shadow_database_fingerprint')),
    'source_fingerprint', lower(btrim(input->>'source_fingerprint')),
    'payload_fingerprint', lower(btrim(input->>'payload_fingerprint'))
  );
  if source_value is distinct from input->'source_payload'
     or payload_value is distinct from input->'payload'
     or request_value is distinct from expected_request
     or encode(extensions.digest(source_text, 'sha256'), 'hex') <> lower(btrim(input->>'source_fingerprint'))
     or encode(extensions.digest(payload_text, 'sha256'), 'hex') <> lower(btrim(input->>'payload_fingerprint'))
     or encode(extensions.digest(request_text, 'sha256'), 'hex') <> lower(btrim(input->>'request_fingerprint')) then
    raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_CANONICAL_EVIDENCE_MISMATCH';
  end if;
  if source_value#>>'{source_workbook_id}' <> scope.google_workbook_id
     or source_value#>>'{tournament_id}' <> '2026'
     or source_value#>>'{tournament_year}' <> '2026'
     or source_value#>>'{current_shadow,import_run_id}' <> btrim(input->>'current_shadow_import_run_id')
     or source_value#>>'{current_shadow,source_fingerprint}' <> lower(btrim(input->>'current_shadow_source_fingerprint'))
     or source_value#>>'{current_shadow,database_fingerprint}' <> lower(btrim(input->>'current_shadow_database_fingerprint'))
     or jsonb_typeof(source_value->'sheets') <> 'array'
     or jsonb_array_length(source_value->'sheets') <> 14
     or (select jsonb_agg(sheet_value->'sheet') from jsonb_array_elements(source_value->'sheets') sheet_value)
        <> input->'source_tabs' then
    raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_SOURCE_PROVENANCE_MISMATCH';
  end if;

  select run.* into current_run
  from production_control.import_runs run
  where run.domain = 'CURRENT_SCORING_SHADOW'
    and run.tournament_id = '2026'
    and run.tournament_year = 2026
    and run.source_workbook_id = scope.google_workbook_id
    and run.status = 'SUCCEEDED'
  order by run.completed_at desc
  limit 1;
  if current_run.import_run_id is null
     or current_run.import_run_id::text <> btrim(input->>'current_shadow_import_run_id')
     or current_run.source_fingerprint <> lower(btrim(input->>'current_shadow_source_fingerprint'))
     or current_run.database_fingerprint <> lower(btrim(input->>'current_shadow_database_fingerprint')) then
    raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_CURRENT_SHADOW_REVISION_MISMATCH';
  end if;
  current_database_fingerprint := encode(extensions.digest(
    production_control.current_tournament_shadow_projection('2026')::text,
    'sha256'
  ), 'hex');
  if current_database_fingerprint <> current_run.database_fingerprint then
    raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_CURRENT_SHADOW_DRIFT';
  end if;

  rows_value := payload_value->'game_center_rows';
  home_value := payload_value->'participant_home_presentation';
  if jsonb_typeof(rows_value) <> 'array'
     or jsonb_typeof(home_value) <> 'object'
     or jsonb_array_length(rows_value) <> 24
     or jsonb_typeof(coalesce(home_value#>'{timeline,events}', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(home_value->'netSkinsByPlayer', '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(home_value->'leaderboardsPlayers', '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(home_value->'tournamentMatchDisplay', '{}'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_COMPLETE_PAYLOAD_REQUIRED';
  end if;
  if (select count(distinct btrim(row_value->>'match_id')) from jsonb_array_elements(rows_value) row_value) <> 24
     or (
       select count(*)
       from jsonb_array_elements(source_value->'sheets') source_sheet
       cross join lateral jsonb_array_elements(source_sheet->'records') source_match
       where source_sheet->>'sheet' = 'Live Matches'
     ) <> 24
     or exists (
       select 1 from scoring_authority.matches match_value
       where match_value.tournament_id = '2026'
         and not exists (
           select 1 from jsonb_array_elements(rows_value) row_value
           where btrim(row_value->>'match_id') = match_value.match_id
         )
     )
     or exists (
       select 1 from jsonb_array_elements(rows_value) row_value
       where btrim(coalesce(row_value->>'tournament_id', '')) <> '2026'
          or btrim(coalesce(row_value->>'course_name', '')) = ''
          or btrim(coalesce(row_value->>'display_match_number', '')) !~ '^[1-9][0-9]*$'
          or coalesce((row_value->>'match_sort_order')::integer, 0) <= 0
          or (row_value->>'match_sort_order')::integer <> (row_value->>'display_match_number')::integer
          or not exists (
            select 1 from scoring_authority.matches match_value
            where match_value.match_id = btrim(row_value->>'match_id')
              and match_value.tournament_id = '2026'
          )
          or not exists (
            select 1
            from jsonb_array_elements(source_value->'sheets') source_sheet
            cross join lateral jsonb_array_elements(source_sheet->'records') source_match
            join scoring_authority.matches match_value
              on match_value.match_id = btrim(row_value->>'match_id')
             and match_value.tournament_id = '2026'
            where source_sheet->>'sheet' = 'Live Matches'
              and btrim(source_match->>'Match ID') = btrim(row_value->>'match_id')
              and btrim(coalesce(source_match->>'Match', '')) ~ '^[1-9][0-9]*$'
              and (source_match->>'Match')::integer = (row_value->>'display_match_number')::integer
              and btrim(coalesce(source_match->>'Round', '')) ~ '^[1-9][0-9]*$'
              and (source_match->>'Round')::integer = match_value.round_number
          )
     )
     or exists (
       select 1
       from jsonb_array_elements(rows_value) left_row
       join scoring_authority.matches left_match on left_match.match_id = btrim(left_row->>'match_id')
       join jsonb_array_elements(rows_value) right_row
         on left_row->>'match_id' < right_row->>'match_id'
       join scoring_authority.matches right_match on right_match.match_id = btrim(right_row->>'match_id')
       where left_match.round_number = right_match.round_number
         and (left_row->>'match_sort_order')::integer = (right_row->>'match_sort_order')::integer
     ) then
    raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_COMPLETE_NUMERIC_MATCH_SET_REQUIRED';
  end if;

  select revision.* into current_revision
  from production_control.presentation_shadow_current pointer
  join production_control.presentation_shadow_revisions revision using (revision_id)
  where pointer.tournament_id = '2026'
  for update of pointer;
  if current_revision.revision_id is not null
     and current_revision.current_shadow_import_run_id = current_run.import_run_id
     and current_revision.source_fingerprint = lower(btrim(input->>'source_fingerprint'))
     and current_revision.payload_fingerprint = lower(btrim(input->>'payload_fingerprint')) then
    database_projection := production_control.production_presentation_shadow_projection('2026');
    database_fingerprint_value := encode(extensions.digest(database_projection::text, 'sha256'), 'hex');
    if database_projection is distinct from payload_value
       or database_fingerprint_value <> current_revision.database_fingerprint then
      raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_DUPLICATE_READBACK_DRIFT';
    end if;
    return jsonb_build_object(
      'ok', true, 'changed', false, 'duplicate', true, 'shadow_only', true,
      'authoritative', false, 'revision_id', current_revision.revision_id,
      'revision_number', current_revision.revision_number,
      'source_fingerprint', current_revision.source_fingerprint,
      'payload_fingerprint', current_revision.payload_fingerprint,
      'database_fingerprint', database_fingerprint_value,
      'counts', current_revision.counts,
      'authority', 'GOOGLE', 'scoring_ingress', 'DISABLED',
      'google_write', false, 'outbox_events', 0, 'archive_jobs', 0, 'mirror_jobs', 0
    );
  end if;

  delete from scoring_authority.game_center_presentations presentation
  where presentation.tournament_id = '2026'
    and not exists (
      select 1 from jsonb_array_elements(rows_value) row_value
      where btrim(row_value->>'match_id') = presentation.match_id
    );
  for item in select value from jsonb_array_elements(rows_value) loop
    insert into scoring_authority.game_center_presentations (
      match_id, tournament_id, course_name, course_logo, course_yardage,
      tee_time, starting_hole, display_match_number, match_sort_order,
      team_1_logo, team_1_primary_color, team_1_secondary_color,
      team_2_logo, team_2_primary_color, team_2_secondary_color,
      tournament_location, tournament_logo, tournament_status, tournament_time_zone,
      source_workbook_id, source_updated_at, source_payload_hash, imported_by,
      imported_at, updated_at
    ) values (
      btrim(item->>'match_id'), '2026',
      btrim(coalesce(item->>'course_name', '')), btrim(coalesce(item->>'course_logo', '')),
      btrim(coalesce(item->>'course_yardage', '')), btrim(coalesce(item->>'tee_time', '')),
      btrim(coalesce(item->>'starting_hole', '')), btrim(item->>'display_match_number'),
      (item->>'match_sort_order')::integer,
      btrim(coalesce(item->>'team_1_logo', '')), btrim(coalesce(item->>'team_1_primary_color', '')),
      btrim(coalesce(item->>'team_1_secondary_color', '')), btrim(coalesce(item->>'team_2_logo', '')),
      btrim(coalesce(item->>'team_2_primary_color', '')), btrim(coalesce(item->>'team_2_secondary_color', '')),
      btrim(coalesce(item->>'tournament_location', '')), btrim(coalesce(item->>'tournament_logo', '')),
      btrim(coalesce(item->>'tournament_status', '')),
      coalesce(nullif(btrim(coalesce(item->>'tournament_time_zone', '')), ''), 'America/Chicago'),
      scope.google_workbook_id, nullif(btrim(coalesce(item->>'source_updated_at', '')), '')::timestamptz,
      encode(extensions.digest(item::text, 'sha256'), 'hex'), btrim(input->>'requested_by'), now(), now()
    ) on conflict (match_id) do update set
      tournament_id = excluded.tournament_id,
      course_name = excluded.course_name, course_logo = excluded.course_logo,
      course_yardage = excluded.course_yardage, tee_time = excluded.tee_time,
      starting_hole = excluded.starting_hole, display_match_number = excluded.display_match_number,
      match_sort_order = excluded.match_sort_order,
      team_1_logo = excluded.team_1_logo, team_1_primary_color = excluded.team_1_primary_color,
      team_1_secondary_color = excluded.team_1_secondary_color,
      team_2_logo = excluded.team_2_logo, team_2_primary_color = excluded.team_2_primary_color,
      team_2_secondary_color = excluded.team_2_secondary_color,
      tournament_location = excluded.tournament_location, tournament_logo = excluded.tournament_logo,
      tournament_status = excluded.tournament_status, tournament_time_zone = excluded.tournament_time_zone,
      source_workbook_id = excluded.source_workbook_id, source_updated_at = excluded.source_updated_at,
      source_payload_hash = excluded.source_payload_hash, imported_by = excluded.imported_by,
      imported_at = now(), updated_at = now();
  end loop;

  insert into scoring_authority.participant_home_presentations (
    tournament_id, presentation, source_workbook_id, source_fingerprint,
    imported_by, imported_at, updated_at
  ) values (
    '2026', home_value, scope.google_workbook_id,
    lower(btrim(input->>'source_fingerprint')), btrim(input->>'requested_by'), now(), now()
  ) on conflict (tournament_id) do update set
    presentation = excluded.presentation,
    source_workbook_id = excluded.source_workbook_id,
    source_fingerprint = excluded.source_fingerprint,
    imported_by = excluded.imported_by,
    imported_at = now(), updated_at = now();

  database_projection := production_control.production_presentation_shadow_projection('2026');
  if database_projection is distinct from payload_value then
    raise exception using errcode = '22023', message = 'PRODUCTION_PRESENTATION_READBACK_MISMATCH';
  end if;
  if exists (select 1 from scoring_authority.google_outbox_events where tournament_id = '2026')
     or exists (select 1 from scoring_authority.scorecard_archive_jobs where tournament_id = '2026')
     or exists (select 1 from scoring_authority.odds_google_mirror_jobs where tournament_id = '2026') then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_PRESENTATION_IMPORT_CREATED_DELIVERY_WORK';
  end if;
  database_fingerprint_value := encode(extensions.digest(database_projection::text, 'sha256'), 'hex');
  counts_value := jsonb_build_object(
    'game_center_presentations', jsonb_array_length(rows_value),
    'participant_home_presentations', 1,
    'round_1', (
      select count(*) from jsonb_array_elements(rows_value) row_value
      join scoring_authority.matches match_value on match_value.match_id = btrim(row_value->>'match_id')
      where match_value.round_number = 1
    ),
    'round_2', (
      select count(*) from jsonb_array_elements(rows_value) row_value
      join scoring_authority.matches match_value on match_value.match_id = btrim(row_value->>'match_id')
      where match_value.round_number = 2
    ),
    'round_3', (
      select count(*) from jsonb_array_elements(rows_value) row_value
      join scoring_authority.matches match_value on match_value.match_id = btrim(row_value->>'match_id')
      where match_value.round_number = 3
    )
  );
  next_revision := coalesce(current_revision.revision_number, 0) + 1;
  insert into production_control.presentation_shadow_revisions (
    tournament_id, tournament_year, revision_number, previous_revision_id,
    current_shadow_import_run_id, project_ref, project_url, source_workbook_id,
    source_tabs, contract_version, request_fingerprint, source_fingerprint,
    payload_fingerprint, current_shadow_source_fingerprint,
    current_shadow_database_fingerprint, database_fingerprint,
    source_payload, projection_payload, counts, imported_by
  ) values (
    '2026', 2026, next_revision, current_revision.revision_id,
    current_run.import_run_id, scope.project_ref, scope.project_url, scope.google_workbook_id,
    input->'source_tabs', 'production-presentation-shadow-v1',
    lower(btrim(input->>'request_fingerprint')), lower(btrim(input->>'source_fingerprint')),
    lower(btrim(input->>'payload_fingerprint')), current_run.source_fingerprint,
    current_run.database_fingerprint, database_fingerprint_value,
    source_value, payload_value, counts_value, btrim(input->>'requested_by')
  ) returning * into inserted_revision;
  insert into production_control.presentation_shadow_current (tournament_id, revision_id, advanced_at)
  values ('2026', inserted_revision.revision_id, now())
  on conflict (tournament_id) do update set
    revision_id = excluded.revision_id, advanced_at = excluded.advanced_at;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_PRESENTATION_SHADOW_IMPORTED', 'CURRENT_TOURNAMENT', '2026',
    btrim(input->>'requested_by'), lower(btrim(input->>'request_fingerprint')), 'SUCCEEDED',
    jsonb_build_object(
      'revisionId', inserted_revision.revision_id, 'revisionNumber', next_revision,
      'currentShadowImportRunId', current_run.import_run_id, 'counts', counts_value,
      'shadowOnly', true, 'authoritative', false, 'authority', 'GOOGLE',
      'scoringIngress', 'DISABLED', 'googleWrite', false,
      'outbox', false, 'archive', false, 'mirror', false
    )
  );
  return jsonb_build_object(
    'ok', true, 'changed', true, 'duplicate', false, 'shadow_only', true,
    'authoritative', false, 'revision_id', inserted_revision.revision_id,
    'revision_number', inserted_revision.revision_number,
    'current_shadow_import_run_id', current_run.import_run_id,
    'source_fingerprint', inserted_revision.source_fingerprint,
    'payload_fingerprint', inserted_revision.payload_fingerprint,
    'database_fingerprint', inserted_revision.database_fingerprint,
    'counts', counts_value, 'authority', 'GOOGLE', 'scoring_ingress', 'DISABLED',
    'google_write', false, 'outbox_events', 0, 'archive_jobs', 0, 'mirror_jobs', 0
  );
end;
$_$;


ALTER FUNCTION public.import_production_presentation_shadow_v1(input jsonb) OWNER TO postgres;

--
-- Name: import_production_published_odds(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_published_odds(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $$
declare
  resource production_control.resource_scope%rowtype;
begin
  perform production_control.assert_production_service_role();
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  if resource.odds_publication_authority <> 'GOOGLE'
     or resource.odds_publication_enabled then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ODDS_GOOGLE_PUBLICATION_RETIRED';
  end if;
  return public.import_production_published_odds_google_authority_v1(input);
end;
$$;


ALTER FUNCTION public.import_production_published_odds(input jsonb) OWNER TO postgres;

--
-- Name: import_production_published_odds_dormant_internal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_published_odds_dormant_internal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'production_control', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  tabs constant jsonb := '["Odds Control","Odds Snapshots","Odds Team Results","Odds Player Results"]'::jsonb;
  registration jsonb;
  item jsonb;
  milestone_value text;
  current_milestone text := btrim(coalesce(input#>>'{payload,current_official_milestone}',''));
  item_published_at timestamptz;
  payload_published_at timestamptz;
  snapshot_id uuid;
  current_snapshot_id uuid;
  next_revision bigint;
  snapshot_count integer;
  error_state text;
  error_constraint text;
begin
  perform production_control.assert_projection_scope(input,'PUBLISHED_ODDS','published-odds-v1',tabs);
  if upper(input->>'validation_status') <> 'VALID'
     or current_milestone not in ('Pre-Tournament','After Round 1','After Round 2','Round 3 Pairings Announced','Final Results')
     or jsonb_typeof(input#>'{payload,snapshots}') <> 'array'
     or jsonb_array_length(input#>'{payload,snapshots}') = 0 then
    return jsonb_build_object('ok',false,'code','COMPLETE_PRODUCTION_PUBLISHED_ODDS_REQUIRED');
  end if;
  snapshot_count := jsonb_array_length(input#>'{payload,snapshots}');
  if (select count(distinct value->>'milestone') from jsonb_array_elements(input#>'{payload,snapshots}')) <> snapshot_count
     or not exists(select 1 from jsonb_array_elements(input#>'{payload,snapshots}') s where s->>'milestone'=current_milestone) then
    return jsonb_build_object('ok',false,'code','PRODUCTION_PUBLISHED_ODDS_MILESTONE_INVALID');
  end if;

  for item in select value from jsonb_array_elements(input#>'{payload,snapshots}') loop
    milestone_value := btrim(coalesce(item->>'milestone',''));
    if milestone_value not in ('Pre-Tournament','After Round 1','After Round 2','Round 3 Pairings Announced','Final Results')
       or coalesce((item->>'phase_order')::integer,-1) <>
          array_position(array['Pre-Tournament','After Round 1','After Round 2','Round 3 Pairings Announced','Final Results'],milestone_value)-1
       or coalesce((item#>>'{published_payload,year}')::integer,0) <> 2026
       or item#>>'{published_payload,phase}' <> milestone_value
       or jsonb_typeof(item#>'{published_payload,teams}') <> 'array'
       or jsonb_array_length(item#>'{published_payload,teams}') = 0
       or jsonb_typeof(item#>'{published_payload,players}') <> 'array'
       or jsonb_array_length(item#>'{published_payload,players}') = 0
       or lower(btrim(coalesce(item->>'payload_hash',''))) !~ '^[0-9a-f]{64}$'
       or lower(btrim(coalesce(item->>'google_publication_fingerprint',''))) !~ '^[0-9a-f]{64}$'
       or coalesce((item->>'publication_verified')::boolean,false) is not true then
      return jsonb_build_object('ok',false,'code','PRODUCTION_PUBLISHED_ODDS_SNAPSHOT_INVALID','milestone',milestone_value);
    end if;
    begin
      item_published_at := (item->>'published_at')::timestamptz;
      payload_published_at := (item#>>'{published_payload,publishedAt}')::timestamptz;
    exception when others then
      return jsonb_build_object('ok',false,'code','PRODUCTION_PUBLISHED_ODDS_TIMESTAMP_INVALID');
    end;
    if item_published_at is null or payload_published_at is null or item_published_at <> payload_published_at then
      return jsonb_build_object('ok',false,'code','PRODUCTION_PUBLISHED_ODDS_TIMESTAMP_MISMATCH');
    end if;
  end loop;

  registration := production_control.register_projection_revision(input,'PUBLISHED_ODDS','published-odds-v1',tabs);
  if not coalesce((registration->>'changed')::boolean,false) then return registration; end if;

  for item in select value from jsonb_array_elements(input#>'{payload,snapshots}')
    order by (value->>'phase_order')::integer loop
    milestone_value := item->>'milestone';
    snapshot_id := null;
    select s.id into snapshot_id
    from scoring_authority.odds_published_snapshots s
    where s.tournament_id = '2026'
      and s.milestone = item->>'milestone'
      and s.published_at = (item->>'published_at')::timestamptz
      and s.payload_hash = lower(item->>'payload_hash');
    if snapshot_id is null then
      select coalesce(max(s.publication_revision),0)+1 into next_revision
      from scoring_authority.odds_published_snapshots s
      where s.tournament_id = '2026' and s.milestone = item->>'milestone';
      insert into scoring_authority.odds_published_snapshots(
        tournament_id,milestone,phase_order,publication_revision,published_at,published_payload,
        payload_hash,source_fingerprint,engine_version,engine_metadata,
        google_publication_fingerprint,google_publication_reference,is_current_for_milestone,
        is_current_official,publication_verified,imported_by,logical_payload_hash,
        settings_fingerprint,ratings_fingerprint,pairing_fingerprint,deterministic_seed,
        publication_actor_id,mirror_status
      ) values(
        '2026',milestone_value,(item->>'phase_order')::integer,next_revision,
        (item->>'published_at')::timestamptz,item->'published_payload',lower(item->>'payload_hash'),
        nullif(lower(btrim(coalesce(item->>'source_fingerprint',''))),''),
        nullif(btrim(coalesce(item->>'engine_version','')),''),coalesce(item->'engine_metadata','{}'::jsonb),
        lower(item->>'google_publication_fingerprint'),coalesce(item->'google_publication_reference','{}'::jsonb),
        false,false,true,input->>'requested_by',
        nullif(lower(btrim(coalesce(item->>'logical_payload_hash',''))),''),
        nullif(lower(btrim(coalesce(item->>'settings_fingerprint',''))),''),
        nullif(lower(btrim(coalesce(item->>'ratings_fingerprint',''))),''),
        nullif(lower(btrim(coalesce(item->>'pairing_fingerprint',''))),''),
        nullif(btrim(coalesce(item->>'deterministic_seed','')),''),
        nullif(btrim(coalesce(item->>'publication_actor_id','')),''),'VERIFIED_GOOGLE_IMPORT'
      ) returning id into snapshot_id;
    end if;
    update scoring_authority.odds_published_snapshots s set is_current_for_milestone=false
    where s.tournament_id='2026' and s.milestone=item->>'milestone'
      and s.id<>snapshot_id and s.is_current_for_milestone;
    update scoring_authority.odds_published_snapshots s
    set is_current_for_milestone=true where s.id=snapshot_id;
    if milestone_value=current_milestone then current_snapshot_id:=snapshot_id; end if;
  end loop;

  update scoring_authority.odds_published_snapshots s set is_current_official=false
  where s.tournament_id='2026' and s.is_current_official and s.id<>current_snapshot_id;
  update scoring_authority.odds_published_snapshots s
  set is_current_official=true where s.id=current_snapshot_id;
  insert into scoring_authority.odds_snapshot_import_runs(
    tournament_id,source_workbook_id,import_fingerprint,current_official_milestone,status,snapshot_count,requested_by
  ) values('2026',input->>'source_workbook_id',lower(input->>'payload_fingerprint'),current_milestone,
    'APPLIED',snapshot_count,input->>'requested_by');
  return registration || jsonb_build_object(
    'snapshot_count',snapshot_count,
    'current_official_milestone',current_milestone,
    'current_snapshot_id',current_snapshot_id,
    'values_recalculated',false,
    'publication_created',false,
    'mirror_job_created',false,
    'shadow_only',true
  );
exception when others then
  get stacked diagnostics error_state = returned_sqlstate, error_constraint = constraint_name;
  return jsonb_build_object(
    'ok',false,
    'code','PRODUCTION_PUBLISHED_ODDS_IMPORT_FAILED',
    'failure_class',case
      when error_state='42702' then 'AMBIGUOUS_REFERENCE'
      when error_state like '23%' then 'DATA_CONSTRAINT'
      else 'DATABASE_OPERATION'
    end,
    'sqlstate',error_state,
    'constraint',nullif(error_constraint,'')
  );
end;
$_$;


ALTER FUNCTION public.import_production_published_odds_dormant_internal(input jsonb) OWNER TO postgres;

--
-- Name: import_production_published_odds_google_authority_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_production_published_odds_google_authority_v1(input jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $_$
  select production_control.mark_projection_operation_response(
    public.import_production_published_odds_dormant_internal($1), 'PUBLISHED_ODDS'
  )
$_$;


ALTER FUNCTION public.import_production_published_odds_google_authority_v1(input jsonb) OWNER TO postgres;

--
-- Name: initiate_account_deletion_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initiate_account_deletion_v1(target_auth_user_id uuid, operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare row_value participant_identity.account_deletion_requests_v1%rowtype;
declare next_status text;
begin
  perform production_control.assert_production_service_role();
  if target_auth_user_id is null or operation_id is null then
    raise exception using errcode = '22023', message = 'ACCOUNT_DELETION_INVALID_REQUEST';
  end if;
  perform 1 from auth.users where id = target_auth_user_id for update;
  if not found then raise exception using errcode = '42501', message = 'ACCOUNT_DELETION_AUTH_REQUIRED'; end if;
  perform participant_identity.lock_deletion_governance_v1();
  if not exists (select 1 from participant_identity.user_player_links
      where auth_user_id = target_auth_user_id)
    and not exists (select 1 from participant_identity.review_access_v1
      where auth_user_id = target_auth_user_id) then
    raise exception using errcode = '42501', message = 'ACCOUNT_DELETION_CANONICAL_ACCOUNT_REQUIRED';
  end if;
  select * into row_value from participant_identity.account_deletion_requests_v1 where request_id = operation_id;
  if found and row_value.auth_user_id is distinct from target_auth_user_id then
    raise exception using errcode = '42501', message = 'ACCOUNT_DELETION_REQUEST_OWNER_MISMATCH';
  end if;
  next_status := participant_identity.account_deletion_status_v1(target_auth_user_id);
  insert into participant_identity.account_deletion_requests_v1(request_id, auth_user_id, status)
    values (operation_id, target_auth_user_id, next_status)
    on conflict (auth_user_id) do update set status = excluded.status, updated_at = clock_timestamp()
    returning * into row_value;
  return jsonb_build_object('requestId', row_value.request_id, 'status', row_value.status, 'completed', false);
end;
$$;


ALTER FUNCTION public.initiate_account_deletion_v1(target_auth_user_id uuid, operation_id uuid) OWNER TO postgres;

--
-- Name: inspect_participant_auth_identifier_foundation(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_participant_auth_identifier_foundation(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'participant_identity', 'scoring_authority', 'public', 'auth', 'pg_temp'
    AS $_$
declare target_tournament text := btrim(coalesce(target_tournament_id, ''));
declare result jsonb;
begin
  if target_tournament = '' then
    return jsonb_build_object('ok', false, 'code', 'TOURNAMENT_REQUIRED');
  end if;

  with roster as (
    select membership.player_id, link.auth_user_id
    from scoring_authority.tournament_players membership
    left join participant_identity.user_player_links link
      on link.player_id = membership.player_id
     and link.status = 'ACTIVE'
    where membership.tournament_id = target_tournament
      and membership.participation_status = 'ACTIVE'
  ), readiness as (
    select
      roster.player_id,
      roster.auth_user_id,
      email_identifier.identifier_id as email_identifier_id,
      phone_identifier.identifier_id as phone_identifier_id,
      phone_identifier.status as phone_status,
      case
        when phone_identifier.identifier_id is null then false
        when phone_identifier.auth_user_id <> roster.auth_user_id then true
        when exists (
          select 1 from auth.users other_user
          where other_user.id <> roster.auth_user_id
            and (
              other_user.phone = phone_identifier.normalized_value_private
              or other_user.phone_change = phone_identifier.normalized_value_private
            )
        ) then true
        else false
      end as auth_user_mismatch
    from roster
    left join lateral (
      select identifier.identifier_id
      from participant_identity.participant_auth_identifiers identifier
      where identifier.player_id = roster.player_id
        and identifier.auth_user_id = roster.auth_user_id
        and identifier.identifier_type = 'EMAIL'
        and identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
      limit 1
    ) email_identifier on true
    left join lateral (
      select identifier.*
      from participant_identity.participant_auth_identifiers identifier
      where identifier.player_id = roster.player_id
        and identifier.identifier_type = 'PHONE'
        and identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
      order by identifier.updated_at desc
      limit 1
    ) phone_identifier on true
  )
  select jsonb_build_object(
    'ok', true,
    'tournamentId', target_tournament,
    'eligiblePlayers', count(*),
    'authLinkedPlayers', count(*) filter (where auth_user_id is not null),
    'emailOwnership', count(*) filter (where email_identifier_id is not null),
    'emailBackfillMismatches', count(*) filter (
      where auth_user_id is not null and email_identifier_id is null
    ),
    'phoneConfigured', count(*) filter (where phone_identifier_id is not null),
    'phoneEligibleUnverified', count(*) filter (where phone_status = 'ELIGIBLE'),
    'phoneVerificationPending', count(*) filter (where phone_status = 'VERIFICATION_PENDING'),
    'phoneVerified', count(*) filter (where phone_status = 'VERIFIED'),
    'phoneRevoked', (
      select count(*)
      from participant_identity.participant_auth_identifiers identifier
      join roster current_roster on current_roster.player_id = identifier.player_id
      where identifier.identifier_type = 'PHONE' and identifier.status = 'REVOKED'
    ),
    'duplicatePhone', (
      select count(*) from (
        select identifier.normalized_value_private
        from participant_identity.participant_auth_identifiers identifier
        where identifier.identifier_type = 'PHONE'
          and identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
        group by identifier.normalized_value_private
        having count(*) > 1
      ) duplicates
    ),
    'invalidPhone', (
      select count(*)
      from participant_identity.participant_auth_identifiers identifier
      where identifier.identifier_type = 'PHONE'
        and identifier.normalized_value_private !~ '^\+[1-9][0-9]{7,14}$'::text collate "C"
    ),
    'authUserMismatch', count(*) filter (where auth_user_mismatch),
    'playerLinkParity', count(*) filter (
      where auth_user_id is not null and email_identifier_id is null
    ) = 0
  ) into result
  from readiness;
  return result;
end;
$_$;


ALTER FUNCTION public.inspect_participant_auth_identifier_foundation(target_tournament_id text) OWNER TO postgres;

--
-- Name: inspect_participant_auth_phone_link_alignment(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_participant_auth_phone_link_alignment(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'participant_identity', 'scoring_authority', 'public', 'auth', 'pg_temp'
    AS $$
declare target_tournament text := btrim(coalesce(target_tournament_id, ''));
declare result jsonb;
begin
  if target_tournament = '' then
    return jsonb_build_object('ok', false, 'code', 'TOURNAMENT_REQUIRED');
  end if;

  with phone_rows as (
    select
      phone_identifier.player_id,
      phone_identifier.status as phone_status,
      link.auth_user_id as link_auth_user_id,
      email_identifier.auth_user_id as email_auth_user_id,
      phone_identifier.auth_user_id as phone_auth_user_id,
      auth_user.phone as auth_phone,
      auth_user.phone_change as auth_phone_change,
      phone_identifier.normalized_value_private as phone_e164,
      exists (
        select 1 from auth.users other_user
        where other_user.id <> link.auth_user_id
          and (
            other_user.phone = phone_identifier.normalized_value_private
            or other_user.phone_change = phone_identifier.normalized_value_private
          )
      ) as other_auth_collision
    from participant_identity.participant_auth_identifiers phone_identifier
    join scoring_authority.tournament_players membership
      on membership.tournament_id = target_tournament
     and membership.player_id = phone_identifier.player_id
     and membership.participation_status = 'ACTIVE'
    left join participant_identity.user_player_links link
      on link.player_id = phone_identifier.player_id
     and link.status = 'ACTIVE'
    left join participant_identity.participant_auth_identifiers email_identifier
      on email_identifier.player_id = phone_identifier.player_id
     and email_identifier.identifier_type = 'EMAIL'
     and email_identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
    left join auth.users auth_user on auth_user.id = link.auth_user_id
    where phone_identifier.identifier_type = 'PHONE'
      and phone_identifier.status in ('ELIGIBLE', 'VERIFICATION_PENDING', 'VERIFIED')
  )
  select jsonb_build_object(
    'ok', true,
    'configuredPhoneCount', count(*),
    'mismatchCount', count(*) filter (
      where link_auth_user_id is null
        or email_auth_user_id is distinct from link_auth_user_id
        or phone_auth_user_id is distinct from link_auth_user_id
    ),
    'rows', coalesce(jsonb_agg(jsonb_build_object(
      'playerId', player_id,
      'phoneStatus', phone_status,
      'playerIdMatch', link_auth_user_id is not null,
      'linkAuthLabel', case when link_auth_user_id is null then 'NONE' else 'AUTH-UID-A' end,
      'emailAuthLabel', case
        when email_auth_user_id is null then 'NONE'
        when email_auth_user_id = link_auth_user_id then 'AUTH-UID-A'
        else 'AUTH-UID-OTHER'
      end,
      'phoneAuthLabel', case
        when phone_auth_user_id is null then 'NONE'
        when phone_auth_user_id = link_auth_user_id then 'AUTH-UID-A'
        else 'AUTH-UID-OTHER'
      end,
      'emailAuthUserMatch', email_auth_user_id = link_auth_user_id,
      'phoneAuthUserMatch', phone_auth_user_id = link_auth_user_id,
      'otherAuthUserCollision', other_auth_collision,
      'expectedAuthPhoneState', case
        when nullif(btrim(coalesce(auth_phone, '')), '') is null then 'UNSET'
        when auth_phone = phone_e164 then 'MATCH'
        else 'CONFLICT'
      end,
      'expectedAuthPhoneChangeState', case
        when nullif(btrim(coalesce(auth_phone_change, '')), '') is null then 'UNSET'
        when auth_phone_change = phone_e164 then 'MATCH'
        else 'CONFLICT'
      end
    ) order by player_id), '[]'::jsonb)
  ) into result
  from phone_rows;
  return result;
end;
$$;


ALTER FUNCTION public.inspect_participant_auth_phone_link_alignment(target_tournament_id text) OWNER TO postgres;

--
-- Name: inspect_participant_identity_tournament_resolution(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_participant_identity_tournament_resolution(target_auth_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'participant_identity', 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare link_row participant_identity.user_player_links%rowtype;
declare selected_tournament text;
declare candidates jsonb;
begin
  select * into link_row
  from participant_identity.user_player_links
  where auth_user_id = target_auth_user_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'ACTIVE_USER_PLAYER_LINK_REQUIRED'); end if;

  selected_tournament := participant_identity.resolve_approved_participant_tournament(target_auth_user_id);
  select coalesce(jsonb_agg(jsonb_build_object(
    'tournamentId', tournament.tournament_id,
    'tournamentYear', tournament.tournament_year,
    'tournamentName', tournament.name,
    'membershipStatus', membership.participation_status,
    'approvedIdentityConfiguration', contact.tournament_id is not null and exists (
      select 1
      from participant_identity.identity_config_import_runs run
      join participant_identity.identity_context_revisions revision
        on revision.tournament_id = run.tournament_id
       and revision.configuration_fingerprint = run.source_fingerprint
      where run.tournament_id = tournament.tournament_id and run.status = 'APPROVED'
    ),
    'selected', tournament.tournament_id = selected_tournament
  ) order by tournament.tournament_year, tournament.tournament_id), '[]'::jsonb)
  into candidates
  from scoring_authority.tournament_players membership
  join scoring_authority.tournaments tournament
    on tournament.tournament_id = membership.tournament_id
  left join participant_identity.participant_identity_contacts contact
    on contact.tournament_id = membership.tournament_id
   and contact.player_id = membership.player_id
   and contact.identity_active
   and link_row.email_identity_hash = encode(extensions.digest(contact.email_normalized::text, 'sha256'::text), 'hex')
  where membership.player_id = link_row.player_id
    and membership.participation_status = 'ACTIVE';

  return jsonb_build_object(
    'ok', selected_tournament is not null,
    'code', case when selected_tournament is null then 'APPROVED_TOURNAMENT_CONTEXT_REQUIRED' else 'RESOLVED' end,
    'playerId', link_row.player_id,
    'selectedTournamentId', selected_tournament,
    'candidates', candidates
  );
end;
$$;


ALTER FUNCTION public.inspect_participant_identity_tournament_resolution(target_auth_user_id uuid) OWNER TO postgres;

--
-- Name: inspect_production_calcutta_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_calcutta_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  current_value scoring_authority.calcutta_v1_current%rowtype;
  result_value scoring_authority.calcutta_v1_result_revisions%rowtype;
  revision_value text;
begin
  perform production_control.assert_production_service_role();
  perform production_control.assert_production_cutover_read_scope(
    input, 'OBSERVATION'
  );
  if pg_catalog.upper(coalesce(input->>'environment', '')) <> 'PRODUCTION'
     or input->>'tournament_id' is distinct from '2026' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CALCUTTA_RESOURCE_ASSERTION_FAILED';
  end if;

  select value.* into strict current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = '2026';
  if current_value.auction_revision > 0 then
    select value.* into result_value
    from scoring_authority.calcutta_v1_result_revisions value
    where value.tournament_id = '2026'
      and value.configuration_revision = current_value.configuration_revision
      and value.configuration_fingerprint =
        current_value.configuration_fingerprint
      and value.auction_revision = current_value.auction_revision
      and value.auction_fingerprint = current_value.auction_fingerprint
      and value.is_current
    limit 1;
  end if;
  revision_value := pg_catalog.format(
    'calcutta-v1:%s:%s:%s:%s:%s:%s',
    current_value.configuration_revision,
    current_value.auction_revision,
    current_value.publication_revision,
    case when result_value.result_id is null
      then 0 else result_value.result_revision end,
    current_value.state, current_value.publication_state
  );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'data', pg_catalog.jsonb_build_object(
      'contract_version', 'production-calcutta-v1',
      'tournament_id', '2026',
      'state', current_value.state,
      'publication_policy',
        'DIRECTOR_CONTROLLED_PARTICIPANT_FULL_MARKET',
      'publication_state', current_value.publication_state,
      'published', current_value.publication_state = 'PUBLISHED',
      'configuration_revision', current_value.configuration_revision,
      'configuration_fingerprint', current_value.configuration_fingerprint,
      'auction_revision', current_value.auction_revision,
      'auction_fingerprint', current_value.auction_fingerprint,
      'publication_revision', current_value.publication_revision,
      'result_revision', case when result_value.result_id is null
        then null else result_value.result_revision end,
      'result_fingerprint', case when result_value.result_id is null
        then null else result_value.payload_hash end,
      'revision', revision_value
    )
  );
end;
$$;


ALTER FUNCTION public.inspect_production_calcutta_v1(input jsonb) OWNER TO postgres;

--
-- Name: inspect_production_candidate_read_security(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_candidate_read_security() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'scoring_authority', 'production_control', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'ok',
      not has_function_privilege('anon', 'public.read_production_candidate_current_view(jsonb)', 'execute')
      and not has_function_privilege('authenticated', 'public.read_production_candidate_current_view(jsonb)', 'execute')
      and has_function_privilege('service_role', 'public.read_production_candidate_current_view(jsonb)', 'execute')
      and not has_function_privilege('anon', 'public.read_production_candidate_completed_history(jsonb)', 'execute')
      and not has_function_privilege('authenticated', 'public.read_production_candidate_completed_history(jsonb)', 'execute')
      and has_function_privilege('service_role', 'public.read_production_candidate_completed_history(jsonb)', 'execute'),
    'anon_current_execute', has_function_privilege('anon', 'public.read_production_candidate_current_view(jsonb)', 'execute'),
    'authenticated_current_execute', has_function_privilege('authenticated', 'public.read_production_candidate_current_view(jsonb)', 'execute'),
    'service_current_execute', has_function_privilege('service_role', 'public.read_production_candidate_current_view(jsonb)', 'execute'),
    'anon_history_execute', has_function_privilege('anon', 'public.read_production_candidate_completed_history(jsonb)', 'execute'),
    'authenticated_history_execute', has_function_privilege('authenticated', 'public.read_production_candidate_completed_history(jsonb)', 'execute'),
    'service_history_execute', has_function_privilege('service_role', 'public.read_production_candidate_completed_history(jsonb)', 'execute'),
    'public_scoring_table_select', has_table_privilege('anon', 'scoring_authority.matches', 'select')
  );
$$;


ALTER FUNCTION public.inspect_production_candidate_read_security() OWNER TO postgres;

--
-- Name: inspect_production_cutover_authority(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_cutover_authority(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';
  select * into strict gate
  from scoring_authority.ingress_gates
  where tournament_id = '2026';

  return jsonb_build_object(
    'ok', true,
    'contract_version', activation.contract_version,
    'state', activation.state,
    'activation_revision', activation.activation_revision,
    'deployment_commit', activation.expected_deployment_commit,
    'source_fingerprint', activation.expected_source_fingerprint,
    'authority_generation_id', activation.authority_generation_id,
    'authority', activation.current_authority,
    'gate', jsonb_build_object(
      'state', gate.state, 'authority', gate.authority,
      'active_epoch_id', gate.active_epoch_id,
      'unresolved_client_queues', gate.unresolved_client_queues
    ),
    'first_canonical_write_boundary', jsonb_build_object(
      'possible', activation.first_supabase_write_possible_at is not null
        and activation.current_authority = 'SUPABASE',
      'possible_at', activation.first_supabase_write_possible_at,
      'observed', activation.first_supabase_write_observed_at is not null,
      'observed_at', activation.first_supabase_write_observed_at,
      'mutation_key', activation.first_supabase_mutation_key,
      'match_id', activation.first_supabase_match_id,
      'match_revision', activation.first_supabase_match_revision
    ),
    'resource_flags', jsonb_build_object(
      'current_tournament_read_authority', resource.current_tournament_read_authority,
      'scoring_authority', resource.scoring_authority,
      'participant_identity_authority', resource.participant_identity_authority,
      'public_supabase_reads_enabled', resource.public_supabase_reads_enabled,
      'scoring_ingress_enabled', resource.scoring_ingress_enabled,
      'google_writes_enabled', resource.google_writes_enabled,
      'workers_enabled', resource.workers_enabled,
      'odds_publication_enabled', resource.odds_publication_enabled
    ),
    'workers', (
      select coalesce(jsonb_object_agg(worker_name, jsonb_build_object(
        'enabled', enabled,
        'scheduler_installed', scheduler_installed,
        'google_writes_allowed', google_writes_allowed
      ) order by worker_name), '{}'::jsonb)
      from production_control.worker_controls
    ),
    'supabase_match_revisions', production_control.current_match_revisions('2026'),
    'google_checkpoints', production_control.current_google_checkpoints('2026'),
    'active_leases', (
      select count(*) from scoring_authority.scoring_ingress_leases
      where tournament_id = '2026' and status = 'ACTIVE' and expires_at > now()
    ),
    'no_automatic_fallback', true
  );
end;
$$;


ALTER FUNCTION public.inspect_production_cutover_authority(input jsonb) OWNER TO postgres;

