CREATE FUNCTION public.inspect_production_shadow_import_security() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'project_ref', (select project_ref from production_control.resource_scope where scope_key = 'BAGGER_INV_PRODUCTION'),
    'workbook_id', (select google_workbook_id from production_control.resource_scope where scope_key = 'BAGGER_INV_PRODUCTION'),
    'public_reads_enabled', (select public_supabase_reads_enabled from production_control.resource_scope where scope_key = 'BAGGER_INV_PRODUCTION'),
    'scoring_ingress_enabled', (select scoring_ingress_enabled from production_control.resource_scope where scope_key = 'BAGGER_INV_PRODUCTION'),
    'google_writes_enabled', (select google_writes_enabled from production_control.resource_scope where scope_key = 'BAGGER_INV_PRODUCTION'),
    'auth_user_creation_enabled', (select auth_user_creation_enabled from production_control.resource_scope where scope_key = 'BAGGER_INV_PRODUCTION'),
    'workers_enabled', (select workers_enabled from production_control.resource_scope where scope_key = 'BAGGER_INV_PRODUCTION'),
    'active_worker_controls', (select count(*) from production_control.worker_controls where enabled or scheduler_installed or google_writes_allowed),
    'operational_triggers_enabled', (
      select count(*) from pg_catalog.pg_trigger trigger_value
      where trigger_value.tgname in (
        'net_skins_hole_score_recalculation', 'tournament_storylines_score_change',
        'calcutta_official_match_change', 'capture_scorecard_archive_transition',
        'net_skins_match_lifecycle_recalculation', 'tournament_derived_match_change',
        'odds_google_mirror_supersession', 'tournament_storylines_net_skins_change'
      ) and trigger_value.tgenabled <> 'D'
    ),
    'outbox_events', (select count(*) from scoring_authority.google_outbox_events),
    'auth_users', (select count(*) from auth.users),
    'privileges', jsonb_build_object(
      'anon_history_import', has_function_privilege('anon', 'public.import_production_completed_history_year(jsonb)', 'execute'),
      'authenticated_history_import', has_function_privilege('authenticated', 'public.import_production_completed_history_year(jsonb)', 'execute'),
      'service_history_import', has_function_privilege('service_role', 'public.import_production_completed_history_year(jsonb)', 'execute'),
      'anon_current_import', has_function_privilege('anon', 'public.import_production_current_tournament_shadow(jsonb)', 'execute'),
      'authenticated_current_import', has_function_privilege('authenticated', 'public.import_production_current_tournament_shadow(jsonb)', 'execute'),
      'service_current_import', has_function_privilege('service_role', 'public.import_production_current_tournament_shadow(jsonb)', 'execute')
    )
  );
$$;


ALTER FUNCTION public.inspect_production_shadow_import_security() OWNER TO postgres;

--
-- Name: inspect_production_step11_scoring_rehearsal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_step11_scoring_rehearsal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_rehearsal', 'production_control', 'auth', 'extensions', 'pg_temp'
    AS $_$
declare
  scope production_control.resource_scope%rowtype;
  fixture jsonb;
  fixture_fingerprint text;
  director_player_id text := btrim(coalesce(input->>'actor_id',''));
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_SERVICE_ROLE_REQUIRED';
  end if;
  scope := production_control.assert_current_shadow_v2_dormant();
  if upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or input->>'project_ref' <> scope.project_ref
     or input->>'project_url' <> scope.project_url
     or input->>'source_workbook_id' <> scope.google_workbook_id
     or lower(btrim(coalesce(input->>'candidate_sha',''))) !~ '^[0-9a-f]{40}$'
     or btrim(coalesce(input->>'candidate_hostname','')) !~ '^[a-z0-9-]+(?:\.[a-z0-9-]+)*\.vercel\.app$'
     or btrim(coalesce(input->>'candidate_hostname','')) = 'baggerinv.com'
     or director_player_id = '' then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_EXACT_RESOURCE_SCOPE_REQUIRED';
  end if;
  if not exists (
    select 1
    from production_control.director_entitlements entitlement
    join participant_identity.user_player_links link
      on link.auth_user_id = entitlement.auth_user_id
     and link.player_id = entitlement.player_id
     and link.status = 'ACTIVE'
    join participant_identity.tournament_roles role
      on role.auth_user_id = entitlement.auth_user_id
     and role.tournament_id = entitlement.tournament_id
     and role.role = 'DIRECTOR'
     and role.role_active
    where entitlement.tournament_id = '2026'
      and entitlement.player_id = director_player_id
      and entitlement.status = 'ACTIVE'
  ) then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_ACTIVE_DIRECTOR_REQUIRED';
  end if;
  fixture := production_rehearsal.completed_source_fixture(input->>'source_match_id');
  fixture_fingerprint := encode(extensions.digest(fixture::text, 'sha256'), 'hex');
  return jsonb_build_object(
    'ok', true,
    'actorId', director_player_id,
    'current2026Fingerprint', production_rehearsal.current_2026_fingerprint(),
    'fixture', fixture,
    'fixtureFingerprint', fixture_fingerprint,
    'sourceFingerprint', fixture_fingerprint,
    'externalTransport', 'VIRTUAL',
    'externalGoogleWrites', 0,
    'live2026Writes', 0
  );
end;
$_$;


ALTER FUNCTION public.inspect_production_step11_scoring_rehearsal(input jsonb) OWNER TO postgres;

--
-- Name: inspect_production_vercel_provider_attestation_challenge(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_vercel_provider_attestation_challenge(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.upper(coalesce(input->>'stage', ''))
       not in ('BEGIN', 'FINALIZE')
     or pg_catalog.upper(coalesce(input->>'purpose', ''))
       not in ('REHEARSAL', 'CUTOVER')
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or input->>'candidate_deployment_target' not in ('PREVIEW', 'PRODUCTION')
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = '' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_INSPECT_INPUT_INVALID';
  end if;
  select * into challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.operation_request_id = (input->>'operation_request_id')::uuid
    and value.evidence_request_id = (input->>'evidence_request_id')::uuid
    and value.stage = pg_catalog.upper(input->>'stage');
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'found', false,
      'code', 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_NOT_FOUND',
      'operation_request_id', input->>'operation_request_id',
      'evidence_request_id', input->>'evidence_request_id',
      'stage', pg_catalog.upper(input->>'stage'), 'idempotent', true
    );
  end if;
  if (nullif(input->>'challenge_id', '') is not null
       and challenge.challenge_id is distinct from
         (input->>'challenge_id')::uuid)
     or challenge.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or challenge.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or challenge.purpose is distinct from pg_catalog.upper(input->>'purpose')
     or challenge.candidate_deployment_target is distinct from
       input->>'candidate_deployment_target'
     or challenge.authenticated_actor_fingerprint is distinct from
       input->>'authenticated_actor_fingerprint'
     or challenge.actor_id is distinct from
       pg_catalog.left(input->>'actor_id', 160) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_OWNERSHIP_MISMATCH';
  end if;
  return production_control.vercel_provider_attestation_challenge_response(
    challenge, true
  );
end;
$_$;


ALTER FUNCTION public.inspect_production_vercel_provider_attestation_challenge(input jsonb) OWNER TO postgres;

--
-- Name: inspect_production_vercel_provider_attestation_challenge_abando(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_vercel_provider_attestation_challenge_abando(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
  server_observed_at_value timestamptz;
  abandonment_code_value text;
  abandon_eligible_value boolean := false;
  allowed_keys text[] := array[
    'environment', 'project_ref', 'project_url', 'source_workbook_id',
    'tournament_id', 'actor_id', 'authenticated_actor_fingerprint',
    'challenge_id', 'challenge_request_id', 'operation_request_id',
    'evidence_request_id', 'stage', 'purpose', 'vercel_project_id',
    'vercel_team_id', 'candidate_deployment_id',
    'candidate_deployment_commit', 'candidate_deployment_target',
    'candidate_alias_origin', 'candidate_immutable_origin', 'routing_rule_id',
    'routing_rule_config_version', 'routing_rule_scope'
  ];
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if pg_catalog.jsonb_typeof(input) is distinct from 'object'
     or not (input ?& allowed_keys)
     or (input - allowed_keys) is distinct from '{}'::jsonb
     or coalesce(input->>'challenge_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'challenge_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or input->>'stage' is distinct from 'BEGIN'
     or pg_catalog.upper(coalesce(input->>'purpose', ''))
       not in ('REHEARSAL', 'CUTOVER')
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or coalesce(input->>'vercel_team_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or input->>'candidate_deployment_target' not in ('PREVIEW', 'PRODUCTION')
     or coalesce(input->>'candidate_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_immutable_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'routing_rule_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_config_version', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or input->>'routing_rule_scope' is distinct from
       'PRODUCTION_GOOGLE_CANONICAL_WRITER_QUIESCE' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDON_INSPECT_INPUT_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.challenge_id = (input->>'challenge_id')::uuid
  for update;

  if challenge.challenge_request_id is distinct from
       (input->>'challenge_request_id')::uuid
     or challenge.operation_request_id is distinct from
       (input->>'operation_request_id')::uuid
     or challenge.evidence_request_id is distinct from
       (input->>'evidence_request_id')::uuid
     or challenge.stage is distinct from 'BEGIN'
     or challenge.purpose is distinct from pg_catalog.upper(input->>'purpose')
     or challenge.authenticated_actor_fingerprint is distinct from
       input->>'authenticated_actor_fingerprint'
     or challenge.actor_id is distinct from
       pg_catalog.left(input->>'actor_id', 160)
     or challenge.vercel_project_id is distinct from
       input->>'vercel_project_id'
     or challenge.vercel_team_id is distinct from input->>'vercel_team_id'
     or challenge.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or challenge.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or challenge.candidate_deployment_target is distinct from
       input->>'candidate_deployment_target'
     or challenge.candidate_alias_origin is distinct from
       pg_catalog.lower(input->>'candidate_alias_origin')
     or challenge.candidate_immutable_origin is distinct from
       pg_catalog.lower(input->>'candidate_immutable_origin')
     or challenge.routing_rule_id is distinct from input->>'routing_rule_id'
     or challenge.routing_rule_config_version is distinct from
       input->>'routing_rule_config_version'
     or challenge.routing_rule_scope is distinct from
       input->>'routing_rule_scope' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDON_BINDING_MISMATCH';
  end if;

  server_observed_at_value := pg_catalog.clock_timestamp();
  if challenge.status = 'ABANDONED' then
    abandonment_code_value := 'ABANDONED';
  elsif challenge.status = 'CONSUMED' then
    abandonment_code_value := 'CONSUMED';
  elsif production_control.vercel_provider_challenge_has_abandonment_progression(
      challenge
    ) then
    abandonment_code_value := 'PROGRESSION_CONFLICT';
  elsif server_observed_at_value <= challenge.expires_at then
    abandonment_code_value := 'NOT_EXPIRED';
  else
    abandonment_code_value := 'ELIGIBLE';
    abandon_eligible_value := true;
  end if;

  return production_control.vercel_provider_attestation_challenge_response(
    challenge, true
  ) || pg_catalog.jsonb_build_object(
    'abandon_eligible', abandon_eligible_value,
    'abandonment_code', abandonment_code_value,
    'server_observed_at', server_observed_at_value
  );
end;
$_$;


ALTER FUNCTION public.inspect_production_vercel_provider_attestation_challenge_abando(input jsonb) OWNER TO postgres;

--
-- Name: inspect_production_vercel_provider_challenge_abandonment(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_vercel_provider_challenge_abandonment(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
  attestation production_control.vercel_provider_attestations%rowtype;
  observed_at_value timestamptz;
  abandonment_code_value text;
  allowed_keys text[] := array[
    'environment', 'project_ref', 'project_url', 'source_workbook_id',
    'tournament_id', 'actor_id', 'authenticated_actor_fingerprint',
    'challenge_id', 'challenge_request_id', 'operation_request_id',
    'evidence_request_id', 'stage', 'purpose', 'vercel_project_id',
    'vercel_team_id', 'candidate_deployment_id',
    'candidate_deployment_commit', 'candidate_deployment_target',
    'candidate_alias_origin', 'candidate_immutable_origin', 'routing_rule_id',
    'routing_rule_config_version', 'routing_rule_scope'
  ];
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if pg_catalog.jsonb_typeof(input) is distinct from 'object'
     or not (input ?& allowed_keys)
     or (input - allowed_keys) is distinct from '{}'::jsonb
     or coalesce(input->>'challenge_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'challenge_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.upper(coalesce(input->>'stage', ''))
       not in ('BEGIN', 'FINALIZE')
     or pg_catalog.upper(coalesce(input->>'purpose', ''))
       not in ('REHEARSAL', 'CUTOVER')
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or coalesce(input->>'vercel_team_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or input->>'candidate_deployment_target' not in ('PREVIEW', 'PRODUCTION')
     or coalesce(input->>'candidate_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_immutable_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'routing_rule_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_config_version', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or input->>'routing_rule_scope' is distinct from
       'PRODUCTION_GOOGLE_CANONICAL_WRITER_QUIESCE' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ABANDON_INSPECT_INPUT_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.challenge_id = (input->>'challenge_id')::uuid
  for update;
  perform production_control.assert_vercel_provider_challenge_abandon_binding(
    challenge, input
  );
  if challenge.consumed_attestation_id is not null then
    select * into strict attestation
    from production_control.vercel_provider_attestations value
    where value.attestation_id = challenge.consumed_attestation_id
    for update;
  end if;
  observed_at_value := pg_catalog.clock_timestamp();
  abandonment_code_value :=
    production_control.vercel_provider_challenge_abandonment_code(
      challenge, observed_at_value
    );
  return production_control.vercel_provider_attestation_challenge_response(
    challenge, true
  ) || pg_catalog.jsonb_build_object(
    'abandon_eligible', abandonment_code_value in (
      'ELIGIBLE', 'ELIGIBLE_CONSUMED_UNBOUND'
    ),
    'abandonment_code', abandonment_code_value,
    'server_observed_at', observed_at_value
  );
end;
$_$;


ALTER FUNCTION public.inspect_production_vercel_provider_challenge_abandonment(input jsonb) OWNER TO postgres;

--
-- Name: inspect_production_vercel_writer_critical_waf_epoch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_vercel_writer_critical_waf_epoch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  dispatch production_control.vercel_writer_critical_waf_dispatches%rowtype;
  dispatch_result
    production_control.vercel_writer_critical_waf_dispatch_results%rowtype;
  active_epoch_count bigint;
  retired_epoch_count bigint;
  dispatch_count bigint;
  dispatch_result_count bigint;
  expected_epoch_id uuid;
  expected_retirement_request_id uuid;
  required_recovery_keys text[] := array[
    'environment', 'project_ref', 'project_url', 'source_workbook_id',
    'tournament_id', 'operation', 'vercel_project_id', 'expected_status',
    'expected_purpose', 'expected_transition_mode'
  ];
  allowed_recovery_keys text[] := array[
    'environment', 'project_ref', 'project_url', 'source_workbook_id',
    'tournament_id', 'operation', 'vercel_project_id', 'expected_status',
    'expected_purpose', 'expected_transition_mode', 'expected_epoch_id',
    'retirement_request_id'
  ];
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);

  -- Preserve the pre-043 exact inspector contract and response verbatim.
  if input->>'operation' =
       'INSPECT_PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_EPOCH'
  then
    if input->>'operation' is distinct from
         'INSPECT_PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_EPOCH'
       or coalesce(input->>'epoch_id', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(input->>'candidate_deployment_id', '')
         !~ '^dpl_[A-Za-z0-9]{8,64}$'
       or coalesce(input->>'candidate_deployment_commit', '')
         !~ '^[0-9a-f]{40}$'
    then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_INSPECT_INPUT_INVALID';
    end if;
    select * into epoch
    from production_control.vercel_writer_critical_waf_epochs value
    where value.epoch_id = (input->>'epoch_id')::uuid;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'found', false,
        'contract_version', 'CRITICAL_WINDOW_WAF_V1',
        'epoch_id', (input->>'epoch_id')::uuid
      );
    end if;
    if epoch.candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or epoch.candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or epoch.candidate_deployment_target is distinct from 'PREVIEW'
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_INSPECT_SCOPE_MISMATCH';
    end if;
    return pg_catalog.jsonb_build_object('found', true) ||
      production_control.vercel_writer_critical_waf_epoch_response(epoch, true);
  end if;

  if pg_catalog.jsonb_typeof(input) is distinct from 'object'
     or not (input ?& required_recovery_keys)
     or (input - allowed_recovery_keys) is distinct from '{}'::jsonb
     or input->>'operation' is distinct from
       'RECOVER_PRODUCTION_VERCEL_WRITER_REJECTED_WAF_EPOCH'
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'expected_purpose' is distinct from 'REHEARSAL'
     or input->>'expected_transition_mode' is distinct from 'REHEARSAL'
     or input->>'expected_status' is null
     or input->>'expected_status' not in (
       'ACTIVATION_PENDING', 'ACTIVATION_PENDING_OR_REJECTED_RETIRED'
     )
     or (input->>'expected_epoch_id' is not null
       and input->>'expected_epoch_id'
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$')
     or (input->>'retirement_request_id' is not null
       and input->>'retirement_request_id'
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$')
     or (input->>'retirement_request_id' is not null
       and input->>'expected_epoch_id' is null)
     or (input->>'expected_status' =
         'ACTIVATION_PENDING_OR_REJECTED_RETIRED'
       and (input->>'expected_epoch_id' is null
         or input->>'retirement_request_id' is null))
     or (input->>'expected_status' = 'ACTIVATION_PENDING'
       and input->>'retirement_request_id' is not null)
  then
    raise exception using errcode = '22023',
      message = 'STEP11_6_VERCEL_WAF_RECOVERY_INPUT_INVALID';
  end if;

  expected_epoch_id := nullif(input->>'expected_epoch_id', '')::uuid;
  expected_retirement_request_id :=
    nullif(input->>'retirement_request_id', '')::uuid;

  -- Serialize discovery with begin/retire lifecycle operations. This is a
  -- read-only shared lock and does not change authority or epoch state.
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );

  select pg_catalog.count(*) into active_epoch_count
  from production_control.vercel_writer_critical_waf_epochs value
  where value.status = 'ACTIVATION_PENDING'
    and value.purpose = 'REHEARSAL'
    and value.transition_mode = 'REHEARSAL'
    and value.vercel_project_id = 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU';

  if active_epoch_count > 1 then
    raise exception using errcode = '55000',
      message = 'STEP11_6_VERCEL_WAF_RECOVERY_CONFLICT';
  end if;

  if active_epoch_count = 1 then
    select * into strict epoch
    from production_control.vercel_writer_critical_waf_epochs value
    where value.status = 'ACTIVATION_PENDING'
      and value.purpose = 'REHEARSAL'
      and value.transition_mode = 'REHEARSAL'
      and value.vercel_project_id = 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU';

    if expected_epoch_id is not null
       and epoch.epoch_id is distinct from expected_epoch_id
    then
      raise exception using errcode = '55000',
        message = 'STEP11_6_VERCEL_WAF_RECOVERY_EPOCH_MISMATCH';
    end if;
  elsif expected_epoch_id is not null
        and expected_retirement_request_id is not null
  then
    select pg_catalog.count(*) into retired_epoch_count
    from production_control.vercel_writer_critical_waf_epochs value
    where value.epoch_id = expected_epoch_id
      and value.status = 'REJECTED_RETIRED'
      and value.purpose = 'REHEARSAL'
      and value.transition_mode = 'REHEARSAL'
      and value.vercel_project_id = 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
      and value.retirement_request_id = expected_retirement_request_id
      and value.retirement_reason = 'PROVIDER_REJECTED_NO_MUTATION'
      and value.retired_at is not null;

    if retired_epoch_count > 1 then
      raise exception using errcode = '55000',
        message = 'STEP11_6_VERCEL_WAF_RECOVERY_CONFLICT';
    elsif retired_epoch_count = 1 then
      select * into strict epoch
      from production_control.vercel_writer_critical_waf_epochs value
      where value.epoch_id = expected_epoch_id
        and value.status = 'REJECTED_RETIRED'
        and value.purpose = 'REHEARSAL'
        and value.transition_mode = 'REHEARSAL'
        and value.vercel_project_id = 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
        and value.retirement_request_id = expected_retirement_request_id
        and value.retirement_reason = 'PROVIDER_REJECTED_NO_MUTATION'
        and value.retired_at is not null;
    end if;
  end if;

  if epoch.epoch_id is null then
    raise exception using errcode = '55000',
      message = 'STEP11_6_VERCEL_WAF_RECOVERY_NOT_FOUND';
  end if;

  if epoch.candidate_deployment_target is distinct from 'PREVIEW'
     or epoch.critical_active_observation_id is not null
     or epoch.provider_assigned_rule_id is not null
     or epoch.bound_fence_id is not null
     or epoch.bound_quiesce_evidence_id is not null
  then
    raise exception using errcode = '55000',
      message = 'STEP11_6_VERCEL_WAF_RECOVERY_SCOPE_INVALID';
  end if;

  select pg_catalog.count(*) into dispatch_count
  from production_control.vercel_writer_critical_waf_dispatches value
  where value.epoch_id = epoch.epoch_id;
  if dispatch_count is distinct from 1::bigint then
    raise exception using errcode = '55000',
      message = 'STEP11_6_VERCEL_WAF_RECOVERY_DISPATCH_INVALID';
  end if;
  select * into strict dispatch
  from production_control.vercel_writer_critical_waf_dispatches value
  where value.epoch_id = epoch.epoch_id;

  if dispatch.dispatch_step is distinct from 'CRITICAL_RULE_INSERT'
     or dispatch.status is distinct from 'PROVIDER_REJECTED'
     or dispatch.provider_dispatch_started_at is null
     or dispatch.provider_dispatch_result_id is null
     or dispatch.provider_result_observation_id is not null
     or dispatch.provider_result_fingerprint is null
     or dispatch.provider_observed_at is null
     or dispatch.recorded_at is null
  then
    raise exception using errcode = '55000',
      message = 'STEP11_6_VERCEL_WAF_RECOVERY_DISPATCH_INVALID';
  end if;

  select pg_catalog.count(*) into dispatch_result_count
  from production_control.vercel_writer_critical_waf_dispatch_results value
  where value.dispatch_id = dispatch.dispatch_id;
  if dispatch_result_count is distinct from 1::bigint then
    raise exception using errcode = '55000',
      message = 'STEP11_6_VERCEL_WAF_RECOVERY_RESULT_INVALID';
  end if;
  select * into strict dispatch_result
  from production_control.vercel_writer_critical_waf_dispatch_results value
  where value.dispatch_id = dispatch.dispatch_id;

  if dispatch_result.result_id is distinct from
       dispatch.provider_dispatch_result_id
     or dispatch_result.epoch_id is distinct from epoch.epoch_id
     or dispatch_result.dispatch_step is distinct from 'CRITICAL_RULE_INSERT'
     or dispatch_result.outcome_status is distinct from 'PROVIDER_REJECTED'
     or not dispatch_result.provider_response_observed
     or dispatch_result.provider_response_status is null
     or dispatch_result.provider_response_status not between 400 and 599
     or dispatch_result.provider_response_fingerprint is null
     or dispatch_result.provider_readback_fingerprint is not null
     or dispatch_result.provider_assigned_rule_id is not null
     or dispatch_result.purpose is distinct from 'REHEARSAL'
     or dispatch_result.transition_mode is distinct from 'REHEARSAL'
     or dispatch_result.vercel_project_id is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or dispatch_result.vercel_team_id is distinct from epoch.vercel_team_id
     or dispatch_result.candidate_alias_origin is distinct from
       epoch.candidate_alias_origin
     or dispatch_result.candidate_immutable_origin is distinct from
       epoch.candidate_immutable_origin
     or dispatch_result.candidate_deployment_id is distinct from
       epoch.candidate_deployment_id
     or dispatch_result.candidate_commit_sha is distinct from
       epoch.candidate_deployment_commit
     or dispatch_result.candidate_deployment_target is distinct from 'PREVIEW'
     or dispatch_result.run_owned_rule_name is distinct from
       epoch.run_owned_rule_name
     or dispatch_result.run_owned_rule_nonce is distinct from
       epoch.run_owned_rule_nonce
     or dispatch_result.run_owned_rule_fingerprint is distinct from
       epoch.run_owned_rule_fingerprint
     or dispatch_result.run_owned_insert_document_fingerprint is distinct from
       epoch.run_owned_insert_document_fingerprint
     or dispatch_result.baseline_configuration_version is distinct from
       epoch.baseline_active_config_version
     or dispatch_result.baseline_configuration_etag is distinct from
       epoch.baseline_active_config_etag
     or dispatch_result.baseline_configuration_identity_fingerprint
       is distinct from epoch.baseline_configuration_identity_fingerprint
     or dispatch_result.baseline_semantic_configuration_fingerprint
       is distinct from epoch.baseline_semantic_configuration_fingerprint
     or dispatch_result.baseline_ordered_rules_fingerprint is distinct from
       epoch.baseline_ordered_rules_fingerprint
     or dispatch_result.baseline_source_version_read_fingerprint
       is distinct from epoch.baseline_source_version_read_fingerprint
  then
    raise exception using errcode = '55000',
      message = 'STEP11_6_VERCEL_WAF_RECOVERY_RESULT_INVALID';
  end if;

  return pg_catalog.jsonb_build_object(
      'ok', true,
      'epoch_id', epoch.epoch_id,
      'status', epoch.status,
      'purpose', epoch.purpose,
      'transition_mode', epoch.transition_mode,
      'vercel_project_id', epoch.vercel_project_id,
      'vercel_team_id', epoch.vercel_team_id,
      'candidate_deployment_id', epoch.candidate_deployment_id,
      'candidate_deployment_commit', epoch.candidate_deployment_commit,
      'candidate_deployment_target', epoch.candidate_deployment_target,
      'candidate_alias_origin', epoch.candidate_alias_origin,
      'candidate_immutable_origin', epoch.candidate_immutable_origin,
      'candidate_control_hosts_fingerprint',
        epoch.candidate_control_hosts_fingerprint,
      'run_owned_rule_name', epoch.run_owned_rule_name,
      'run_owned_rule_nonce', epoch.run_owned_rule_nonce,
      'run_owned_rule_fingerprint', epoch.run_owned_rule_fingerprint,
      'run_owned_insert_document_fingerprint',
        epoch.run_owned_insert_document_fingerprint,
      'retirement_request_id', epoch.retirement_request_id,
      'retirement_candidate_deployment_id',
        epoch.retirement_candidate_deployment_id,
      'retirement_candidate_deployment_commit',
        epoch.retirement_candidate_deployment_commit,
      'retirement_reason', epoch.retirement_reason,
      'retired_at', epoch.retired_at,
      'rejected_dispatch_id', dispatch.dispatch_id,
      'rejected_dispatch_result_id', dispatch_result.result_id,
      'provider_response_status', dispatch_result.provider_response_status
    );
end;
$_$;


ALTER FUNCTION public.inspect_production_vercel_writer_critical_waf_epoch(input jsonb) OWNER TO postgres;

--
-- Name: inspect_production_vercel_writer_quiesce_evidence(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inspect_production_vercel_writer_quiesce_evidence(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_INSPECT_INPUT_INVALID';
  end if;
  select * into evidence
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_request_id = (input->>'evidence_request_id')::uuid;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'found', false,
      'code', 'PRODUCTION_VERCEL_WRITER_QUIESCE_NOT_FOUND',
      'evidence_request_id', input->>'evidence_request_id',
      'idempotent', true
    );
  end if;
  if (nullif(input->>'evidence_id', '') is not null
     and evidence.evidence_id is distinct from (input->>'evidence_id')::uuid)
     or evidence.candidate_deployment_id is distinct from
       input->>'candidate_deployment_id'
     or evidence.candidate_deployment_commit is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_QUIESCE_OWNERSHIP_MISMATCH';
  end if;
  return production_control.vercel_quiesce_response(evidence, true);
end;
$_$;


ALTER FUNCTION public.inspect_production_vercel_writer_quiesce_evidence(input jsonb) OWNER TO postgres;

--
-- Name: intelligence_claim_is_current(text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.intelligence_claim_is_current(target_tournament text, target_engine text, target_claim timestamp with time zone) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'pg_temp'
    AS $$
  select exists(select 1 from scoring_authority.competition_recalculation_jobs j where j.tournament_id=target_tournament
    and j.round_number=0 and j.engine_key=target_engine and j.status='RUNNING' and j.started_at=target_claim)
$$;


ALTER FUNCTION public.intelligence_claim_is_current(target_tournament text, target_engine text, target_claim timestamp with time zone) OWNER TO postgres;

--
-- Name: issue_production_vercel_provider_attestation_challenge(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_production_vercel_provider_attestation_challenge(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  response_value jsonb;
  routing_audit jsonb;
  v3_input jsonb;
begin
  perform production_control.assert_exact_vercel_routing_rule_audit(input);
  v3_input := input - array[
    'routing_rule_global_invocation_quiescence_proved',
    'routing_rule_candidate_control_host_count',
    'routing_rule_candidate_control_hosts_fingerprint',
    'routing_rule_canonical_apex_safe_method_count',
    'routing_rule_canonical_apex_safe_methods_fingerprint',
    'routing_rule_canonical_apex_safe_method_writer_route_count',
    'routing_rule_canonical_apex_safe_method_writer_routes_fingerprint'
  ];
  response_value :=
    public.issue_vercel_provider_attestation_v4_candidate_base(v3_input);
  routing_audit :=
    production_control.bind_current_vercel_routing_rule_audit(
      'CHALLENGE', (response_value->>'challenge_id')::uuid, true, input
    );
  return response_value || routing_audit;
end;
$$;


ALTER FUNCTION public.issue_production_vercel_provider_attestation_challenge(input jsonb) OWNER TO postgres;

--
-- Name: issue_vercel_provider_attestation_v3_base(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_vercel_provider_attestation_v3_base(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
  begin_challenge
    production_control.vercel_provider_attestation_challenges%rowtype;
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
  challenge_identifier uuid := extensions.gen_random_uuid();
  challenge_request_identifier uuid;
  operation_request_identifier uuid;
  evidence_request_identifier uuid;
  stage_value text := pg_catalog.upper(coalesce(input->>'stage', ''));
  purpose_value text := pg_catalog.upper(coalesce(input->>'purpose', ''));
  payload_hash text := production_control.cutover_payload_hash(input);
  issued_time timestamptz := pg_catalog.now();
  expiry_time timestamptz := issued_time + interval '120 seconds';
  binding_fingerprint text;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if coalesce(input->>'challenge_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or stage_value not in ('BEGIN', 'FINALIZE')
     or purpose_value not in ('REHEARSAL', 'CUTOVER')
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or input->>'candidate_deployment_target' not in ('PREVIEW', 'PRODUCTION')
     or coalesce(input->>'candidate_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_immutable_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or coalesce(input->>'vercel_team_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_config_version', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or input->>'routing_rule_scope' is distinct from
       'PRODUCTION_GOOGLE_CANONICAL_WRITER_QUIESCE'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_INPUT_INVALID';
  end if;
  if (purpose_value = 'REHEARSAL'
       and input->>'candidate_deployment_target' <> 'PREVIEW')
     or (purpose_value = 'CUTOVER'
       and input->>'candidate_deployment_target' <> 'PRODUCTION') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_TARGET_MISMATCH';
  end if;
  challenge_request_identifier := (input->>'challenge_request_id')::uuid;
  operation_request_identifier := (input->>'operation_request_id')::uuid;
  evidence_request_identifier := (input->>'evidence_request_id')::uuid;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.challenge_request_id = challenge_request_identifier;
  if found then
    if challenge.issue_request_fingerprint is distinct from
         input->>'request_fingerprint'
       or challenge.issue_payload_hash is distinct from payload_hash
       or challenge.operation_request_id is distinct from
         operation_request_identifier
       or challenge.evidence_request_id is distinct from
         evidence_request_identifier
       or challenge.stage is distinct from stage_value then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.vercel_provider_attestation_challenge_response(
      challenge, true
    );
  end if;
  if exists (
    select 1 from production_control.vercel_provider_attestation_challenges value
    where (value.operation_request_id = operation_request_identifier
        or value.evidence_request_id = evidence_request_identifier)
      and value.stage = stage_value
      and value.status <> 'ABANDONED'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ALREADY_ISSUED';
  end if;

  if stage_value = 'BEGIN' then
    if exists (
      select 1 from production_control.vercel_writer_quiesce_evidence value
      where value.evidence_request_id = evidence_request_identifier
    ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BEGIN_ALREADY_BOUND';
    end if;
  else
    select * into strict evidence
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_request_id = evidence_request_identifier
    for update;
    select * into strict begin_challenge
    from production_control.vercel_provider_attestation_challenges value
    where value.evidence_request_id = evidence_request_identifier
      and value.stage = 'BEGIN' and value.status = 'CONSUMED';
    if evidence.status is distinct from 'DRAINING'
       or evidence.purpose is distinct from purpose_value
       or begin_challenge.operation_request_id = operation_request_identifier
       or not exists (
         select 1
         from production_control.vercel_provider_attestations attestation
         where attestation.attestation_id =
             begin_challenge.consumed_attestation_id
           and attestation.evidence_id = evidence.evidence_id
           and attestation.evidence_request_id = evidence_request_identifier
           and attestation.stage = 'BEGIN'
           and attestation.status = 'BOUND'
       )
       or begin_challenge.purpose is distinct from purpose_value
       or begin_challenge.authenticated_actor_fingerprint is distinct from
         input->>'authenticated_actor_fingerprint'
       or begin_challenge.actor_id is distinct from input->>'actor_id'
       or begin_challenge.vercel_project_id is distinct from
         input->>'vercel_project_id'
       or begin_challenge.vercel_team_id is distinct from
         input->>'vercel_team_id'
       or begin_challenge.candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or begin_challenge.candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or begin_challenge.candidate_deployment_target is distinct from
         input->>'candidate_deployment_target'
       or begin_challenge.candidate_alias_origin is distinct from
         pg_catalog.lower(input->>'candidate_alias_origin')
       or begin_challenge.candidate_immutable_origin is distinct from
         pg_catalog.lower(input->>'candidate_immutable_origin')
       or begin_challenge.routing_rule_id is distinct from
         input->>'routing_rule_id'
       or begin_challenge.routing_rule_config_version is distinct from
         input->>'routing_rule_config_version'
       or begin_challenge.routing_rule_scope is distinct from
         input->>'routing_rule_scope' then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_FINALIZE_SCOPE_DRIFT';
    end if;
  end if;

  binding_fingerprint := production_control.structured_evidence_fingerprint(
    pg_catalog.jsonb_build_object(
      'challengeId', challenge_identifier,
      'operationRequestId', operation_request_identifier,
      'evidenceRequestId', evidence_request_identifier,
      'stage', stage_value, 'purpose', purpose_value,
      'vercelProjectId', input->>'vercel_project_id',
      'vercelTeamId', input->>'vercel_team_id',
      'candidateDeploymentId', input->>'candidate_deployment_id',
      'candidateDeploymentCommit',
        pg_catalog.lower(input->>'candidate_deployment_commit'),
      'candidateDeploymentTarget', input->>'candidate_deployment_target',
      'candidateAliasOrigin', pg_catalog.lower(input->>'candidate_alias_origin'),
      'candidateImmutableOrigin',
        pg_catalog.lower(input->>'candidate_immutable_origin'),
      'routingRuleId', input->>'routing_rule_id',
      'routingRuleConfigVersion', input->>'routing_rule_config_version',
      'routingRuleScope', input->>'routing_rule_scope',
      'issuedAt', issued_time, 'expiresAt', expiry_time
    )
  );
  insert into production_control.vercel_provider_attestation_challenges (
    challenge_id, challenge_request_id, operation_request_id,
    evidence_request_id, stage, purpose,
    issue_request_fingerprint, issue_payload_hash,
    challenge_request_fingerprint, authenticated_actor_fingerprint,
    vercel_project_id, vercel_team_id,
    candidate_deployment_id, candidate_deployment_commit,
    candidate_deployment_target, candidate_alias_origin,
    candidate_immutable_origin, routing_rule_id, routing_rule_config_version,
    routing_rule_scope, actor_id, issued_at, expires_at
  ) values (
    challenge_identifier, challenge_request_identifier,
    operation_request_identifier, evidence_request_identifier,
    stage_value, purpose_value,
    input->>'request_fingerprint', payload_hash, binding_fingerprint,
    input->>'authenticated_actor_fingerprint',
    input->>'vercel_project_id', input->>'vercel_team_id',
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    input->>'candidate_deployment_target',
    pg_catalog.lower(input->>'candidate_alias_origin'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    input->>'routing_rule_id', input->>'routing_rule_config_version',
    input->>'routing_rule_scope', input->>'actor_id', issued_time, expiry_time
  ) returning * into challenge;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ISSUED',
    'SCORING_AUTHORITY', '2026', challenge.actor_id,
    challenge.issue_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'challenge_id', challenge.challenge_id,
      'operation_request_id', challenge.operation_request_id,
      'evidence_request_id', challenge.evidence_request_id,
      'stage', challenge.stage, 'purpose', challenge.purpose,
      'candidate_deployment_id', challenge.candidate_deployment_id,
      'candidate_deployment_target', challenge.candidate_deployment_target,
      'challenge_request_fingerprint',
        challenge.challenge_request_fingerprint,
      'expires_at', challenge.expires_at
    )
  );
  return production_control.vercel_provider_attestation_challenge_response(
    challenge, false
  );
end;
$_$;


ALTER FUNCTION public.issue_vercel_provider_attestation_v3_base(input jsonb) OWNER TO postgres;

--
-- Name: issue_vercel_provider_attestation_v4_candidate_base(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_vercel_provider_attestation_v4_candidate_base(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  challenge production_control.vercel_provider_attestation_challenges%rowtype;
  begin_challenge
    production_control.vercel_provider_attestation_challenges%rowtype;
  evidence production_control.vercel_writer_quiesce_evidence%rowtype;
  challenge_identifier uuid := extensions.gen_random_uuid();
  challenge_request_identifier uuid;
  operation_request_identifier uuid;
  evidence_request_identifier uuid;
  stage_value text := pg_catalog.upper(coalesce(input->>'stage', ''));
  purpose_value text := pg_catalog.upper(coalesce(input->>'purpose', ''));
  payload_hash text := production_control.cutover_payload_hash(input);
  issued_time timestamptz := pg_catalog.now();
  expiry_time timestamptz := issued_time + interval '120 seconds';
  binding_fingerprint text;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if coalesce(input->>'challenge_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'evidence_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or stage_value not in ('BEGIN', 'FINALIZE')
     or purpose_value not in ('REHEARSAL', 'CUTOVER')
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or input->>'candidate_deployment_target' not in ('PREVIEW', 'PRODUCTION')
     or coalesce(input->>'candidate_alias_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(input->>'candidate_immutable_origin', '')
       !~ '^https://[a-z0-9.-]+$'
     or input->>'vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or coalesce(input->>'vercel_team_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_id', '')
       !~ '^[A-Za-z0-9_.:-]{3,160}$'
     or coalesce(input->>'routing_rule_config_version', '')
       !~ '^[A-Za-z0-9_.:-]{1,160}$'
     or input->>'routing_rule_scope' is distinct from
       'PRODUCTION_GOOGLE_CANONICAL_WRITER_QUIESCE'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_INPUT_INVALID';
  end if;
  if (purpose_value = 'REHEARSAL'
       and input->>'candidate_deployment_target' <> 'PREVIEW')
     or (purpose_value = 'CUTOVER'
       and input->>'candidate_deployment_target' <> 'PREVIEW') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_TARGET_MISMATCH';
  end if;
  challenge_request_identifier := (input->>'challenge_request_id')::uuid;
  operation_request_identifier := (input->>'operation_request_id')::uuid;
  evidence_request_identifier := (input->>'evidence_request_id')::uuid;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into challenge
  from production_control.vercel_provider_attestation_challenges value
  where value.challenge_request_id = challenge_request_identifier;
  if found then
    if challenge.issue_request_fingerprint is distinct from
         input->>'request_fingerprint'
       or challenge.issue_payload_hash is distinct from payload_hash
       or challenge.operation_request_id is distinct from
         operation_request_identifier
       or challenge.evidence_request_id is distinct from
         evidence_request_identifier
       or challenge.stage is distinct from stage_value then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.vercel_provider_attestation_challenge_response(
      challenge, true
    );
  end if;
  if exists (
    select 1 from production_control.vercel_provider_attestation_challenges value
    where (value.operation_request_id = operation_request_identifier
        or value.evidence_request_id = evidence_request_identifier)
      and value.stage = stage_value
      and value.status <> 'ABANDONED'
  ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ALREADY_ISSUED';
  end if;

  if stage_value = 'BEGIN' then
    if exists (
      select 1 from production_control.vercel_writer_quiesce_evidence value
      where value.evidence_request_id = evidence_request_identifier
    ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_BEGIN_ALREADY_BOUND';
    end if;
  else
    select * into strict evidence
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_request_id = evidence_request_identifier
    for update;
    select * into strict begin_challenge
    from production_control.vercel_provider_attestation_challenges value
    where value.evidence_request_id = evidence_request_identifier
      and value.stage = 'BEGIN' and value.status = 'CONSUMED';
    if evidence.status is distinct from 'DRAINING'
       or evidence.purpose is distinct from purpose_value
       or begin_challenge.operation_request_id = operation_request_identifier
       or not exists (
         select 1
         from production_control.vercel_provider_attestations attestation
         where attestation.attestation_id =
             begin_challenge.consumed_attestation_id
           and attestation.evidence_id = evidence.evidence_id
           and attestation.evidence_request_id = evidence_request_identifier
           and attestation.stage = 'BEGIN'
           and attestation.status = 'BOUND'
       )
       or begin_challenge.purpose is distinct from purpose_value
       or begin_challenge.authenticated_actor_fingerprint is distinct from
         input->>'authenticated_actor_fingerprint'
       or begin_challenge.actor_id is distinct from input->>'actor_id'
       or begin_challenge.vercel_project_id is distinct from
         input->>'vercel_project_id'
       or begin_challenge.vercel_team_id is distinct from
         input->>'vercel_team_id'
       or begin_challenge.candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or begin_challenge.candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or begin_challenge.candidate_deployment_target is distinct from
         input->>'candidate_deployment_target'
       or begin_challenge.candidate_alias_origin is distinct from
         pg_catalog.lower(input->>'candidate_alias_origin')
       or begin_challenge.candidate_immutable_origin is distinct from
         pg_catalog.lower(input->>'candidate_immutable_origin')
       or begin_challenge.routing_rule_id is distinct from
         input->>'routing_rule_id'
       or begin_challenge.routing_rule_config_version is distinct from
         input->>'routing_rule_config_version'
       or begin_challenge.routing_rule_scope is distinct from
         input->>'routing_rule_scope' then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_FINALIZE_SCOPE_DRIFT';
    end if;
  end if;

  binding_fingerprint := production_control.structured_evidence_fingerprint(
    pg_catalog.jsonb_build_object(
      'challengeId', challenge_identifier,
      'operationRequestId', operation_request_identifier,
      'evidenceRequestId', evidence_request_identifier,
      'stage', stage_value, 'purpose', purpose_value,
      'vercelProjectId', input->>'vercel_project_id',
      'vercelTeamId', input->>'vercel_team_id',
      'candidateDeploymentId', input->>'candidate_deployment_id',
      'candidateDeploymentCommit',
        pg_catalog.lower(input->>'candidate_deployment_commit'),
      'candidateDeploymentTarget', input->>'candidate_deployment_target',
      'candidateAliasOrigin', pg_catalog.lower(input->>'candidate_alias_origin'),
      'candidateImmutableOrigin',
        pg_catalog.lower(input->>'candidate_immutable_origin'),
      'routingRuleId', input->>'routing_rule_id',
      'routingRuleConfigVersion', input->>'routing_rule_config_version',
      'routingRuleScope', input->>'routing_rule_scope',
      'issuedAt', issued_time, 'expiresAt', expiry_time
    )
  );
  insert into production_control.vercel_provider_attestation_challenges (
    challenge_id, challenge_request_id, operation_request_id,
    evidence_request_id, stage, purpose,
    issue_request_fingerprint, issue_payload_hash,
    challenge_request_fingerprint, authenticated_actor_fingerprint,
    vercel_project_id, vercel_team_id,
    candidate_deployment_id, candidate_deployment_commit,
    candidate_deployment_target, candidate_alias_origin,
    candidate_immutable_origin, routing_rule_id, routing_rule_config_version,
    routing_rule_scope, actor_id, issued_at, expires_at
  ) values (
    challenge_identifier, challenge_request_identifier,
    operation_request_identifier, evidence_request_identifier,
    stage_value, purpose_value,
    input->>'request_fingerprint', payload_hash, binding_fingerprint,
    input->>'authenticated_actor_fingerprint',
    input->>'vercel_project_id', input->>'vercel_team_id',
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'),
    input->>'candidate_deployment_target',
    pg_catalog.lower(input->>'candidate_alias_origin'),
    pg_catalog.lower(input->>'candidate_immutable_origin'),
    input->>'routing_rule_id', input->>'routing_rule_config_version',
    input->>'routing_rule_scope', input->>'actor_id', issued_time, expiry_time
  ) returning * into challenge;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_VERCEL_PROVIDER_ATTESTATION_CHALLENGE_ISSUED',
    'SCORING_AUTHORITY', '2026', challenge.actor_id,
    challenge.issue_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'challenge_id', challenge.challenge_id,
      'operation_request_id', challenge.operation_request_id,
      'evidence_request_id', challenge.evidence_request_id,
      'stage', challenge.stage, 'purpose', challenge.purpose,
      'candidate_deployment_id', challenge.candidate_deployment_id,
      'candidate_deployment_target', challenge.candidate_deployment_target,
      'challenge_request_fingerprint',
        challenge.challenge_request_fingerprint,
      'expires_at', challenge.expires_at
    )
  );
  return production_control.vercel_provider_attestation_challenge_response(
    challenge, false
  );
end;
$_$;


ALTER FUNCTION public.issue_vercel_provider_attestation_v4_candidate_base(input jsonb) OWNER TO postgres;

--
-- Name: mark_certification_ingress_unknown_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_certification_ingress_unknown_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare l production_control.certification_ingress_leases_v1%rowtype;
begin
 l:=production_control.certification_ingress_lookup_v1(input,true);
 if l.lease_id is null then return public.read_certification_ingress_status_v1(input);end if;
 if l.state='ADMITTED'then update production_control.certification_ingress_leases_v1 set state='UNKNOWN'where lease_id=l.lease_id returning * into l;end if;
 return production_control.certification_ingress_response_v1(l);
end;$$;


ALTER FUNCTION public.mark_certification_ingress_unknown_v1(input jsonb) OWNER TO postgres;

--
-- Name: mark_competition_derived_job_failed(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_competition_derived_job_failed(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  legacy_input jsonb;
  result_value jsonb;
begin
  perform production_control.assert_frozen_2026_derived_worker_v1(input);
  legacy_input := input || pg_catalog.jsonb_build_object(
    'environment', 'PREVIEW', 'tournament_id', '2026'
  );
  if pg_catalog.to_regprocedure(
       'public.mark_competition_derived_job_failed_frozen_2026_installed_v1(jsonb)'
     ) is not null then
    execute $installed$select public
      .mark_competition_derived_job_failed_frozen_2026_installed_v1($1)
    $installed$ into strict result_value using legacy_input;
    return result_value;
  end if;
  return production_control
    .frozen_2026_mark_competition_derived_job_failed_v1(legacy_input);
end;
$_$;


ALTER FUNCTION public.mark_competition_derived_job_failed(input jsonb) OWNER TO postgres;

--
-- Name: mark_production_scoring_ingress_write_started(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_production_scoring_ingress_write_started(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  unresolved_count integer;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  existing := production_control.lookup_cutover_receipt(
    'MARK_SCORING_INGRESS_WRITE_STARTED', input
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for share;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into lease
  from scoring_authority.scoring_ingress_leases value
  where value.lease_id = (input->>'lease_id')::uuid
  for update;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'PRODUCTION_SCORING_LEASE_V3_NOT_FOUND';
  end if;
  perform production_control.assert_production_scoring_lease_nonce(
    lease, input->>'lease_nonce'
  );
  existing := production_control.lookup_cutover_receipt(
    'MARK_SCORING_INGRESS_WRITE_STARTED', input
  );
  if existing is not null then return existing; end if;
  if lease.admitted_activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.activation_revision < lease.admitted_activation_revision
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or lease.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or lease.authority_generation_id is distinct from
       activation.authority_generation_id
     or lease.admission_generation_id is distinct from
       gate.admission_generation_id
     or lease.admission_revision > gate.admission_revision
     or gate.admission_state not in ('OPEN', 'CLOSING')
     or not gate.admission_protocol_enforced
     or exists (
       select 1
       from production_control.google_writer_provider_fences value
       where value.status in ('INSTALLING', 'ABORTING', 'INSTALLED', 'REMOVAL_AUTHORIZED')
     )
  then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_SCORING_LEASE_V3_BOUNDARY_CHANGED';
  end if;
  if lease.resolution_state = 'WRITE_STARTED' then
    response_value := pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_SCORING_WRITE_ALREADY_STARTED',
      'lease_id', lease.lease_id,
      'write_started_at', lease.write_started_at,
      'expires_at', lease.expires_at,
      'provider_credential_class', lease.provider_credential_class,
      'resolution_state', lease.resolution_state,
      'idempotent', true
    );
    perform production_control.store_cutover_receipt(
      'MARK_SCORING_INGRESS_WRITE_STARTED', input, response_value
    );
    return response_value;
  end if;
  if lease.resolution_state <> 'ADMITTED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_LEASE_V3_NOT_STARTABLE';
  end if;
  if lease.expires_at <= pg_catalog.now() then
    if lease.provider_credential_class = 'LEGACY_PROVIDER_FENCEABLE' then
      update scoring_authority.scoring_ingress_leases
      set resolution_state = 'PROVEN_NO_WRITE',
          status = 'COMPLETED',
          completed_at = pg_catalog.now(),
          outcome_reported_at = pg_catalog.now(),
          resolved_at = pg_catalog.now(),
          resolved_by = 'DATABASE_EXPIRY_V3',
          last_error_code = 'LEASE_EXPIRED_BEFORE_PROVIDER_DISPATCH'
      where lease_id = lease.lease_id
      returning * into lease;
      response_value := pg_catalog.jsonb_build_object(
        'ok', false,
        'code', 'PRODUCTION_SCORING_LEASE_EXPIRED_PROVEN_NO_WRITE',
        'lease_id', lease.lease_id,
        'expires_at', lease.expires_at,
        'provider_credential_class', lease.provider_credential_class,
        'resolution_state', lease.resolution_state,
        'requires_reconciliation', false,
        'idempotent', false
      );
    else
      update scoring_authority.scoring_ingress_leases
      set resolution_state = 'AMBIGUOUS',
          outcome_reported_at = pg_catalog.now(),
          last_error_code = 'LEASE_EXPIRED_BEFORE_WRITE_START'
      where lease_id = lease.lease_id
      returning * into lease;
      response_value := pg_catalog.jsonb_build_object(
        'ok', false,
        'code', 'PRODUCTION_SCORING_LEASE_EXPIRED_AMBIGUOUS',
        'lease_id', lease.lease_id,
        'expires_at', lease.expires_at,
        'provider_credential_class', lease.provider_credential_class,
        'resolution_state', lease.resolution_state,
        'requires_reconciliation', true,
        'idempotent', false
      );
    end if;
  else
    update scoring_authority.scoring_ingress_leases
    set resolution_state = 'WRITE_STARTED',
        write_started_at = pg_catalog.now()
    where lease_id = lease.lease_id
    returning * into lease;
    response_value := pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_SCORING_WRITE_STARTED',
      'lease_id', lease.lease_id,
      'write_started_at', lease.write_started_at,
      'expires_at', lease.expires_at,
      'provider_credential_class', lease.provider_credential_class,
      'resolution_state', lease.resolution_state,
      'idempotent', false
    );
  end if;
  unresolved_count := production_control.scoring_admission_unresolved_count(
    gate.admission_generation_id
  );
  update scoring_authority.ingress_gates
  set unresolved_client_queues = unresolved_count,
      updated_at = pg_catalog.now()
  where tournament_id = '2026';
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    case response_value->>'resolution_state'
      when 'WRITE_STARTED' then 'PRODUCTION_SCORING_LEASE_WRITE_STARTED'
      when 'PROVEN_NO_WRITE'
        then 'PRODUCTION_SCORING_LEASE_EXPIRED_PROVEN_NO_WRITE'
      else 'PRODUCTION_SCORING_LEASE_EXPIRED_AMBIGUOUS'
    end,
    'SCORING_AUTHORITY', '2026', lease.actor_id,
    pg_catalog.lower(input->>'request_fingerprint'),
    case when response_value->>'resolution_state' in (
      'WRITE_STARTED', 'PROVEN_NO_WRITE'
    ) then 'SUCCEEDED' else 'BLOCKED' end,
    pg_catalog.jsonb_build_object(
      'lease_id', lease.lease_id,
      'admission_generation_id', lease.admission_generation_id,
      'provider_credential_class', lease.provider_credential_class,
      'expires_at', lease.expires_at,
      'resolution_state', response_value->>'resolution_state'
    )
  );
  perform production_control.store_cutover_receipt(
    'MARK_SCORING_INGRESS_WRITE_STARTED', input, response_value
  );
  return response_value;
end;
$$;


ALTER FUNCTION public.mark_production_scoring_ingress_write_started(input jsonb) OWNER TO postgres;

--
-- Name: mark_production_scoring_ingress_write_started_v3(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_production_scoring_ingress_write_started_v3(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  response_value jsonb;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  expected_provider_principal text;
  remaining_dispatch_ms bigint;
begin
  if coalesce(input->>'lease_id', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or coalesce(input->>'lease_nonce', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_WRITE_STARTED_V3_REQUEST_INVALID';
  end if;

  expected_provider_principal :=
    pg_catalog.lower(input->>'expected_provider_principal_fingerprint');
  if coalesce(expected_provider_principal, '') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_WRITE_STARTED_V3_PROVIDER_PRINCIPAL_REQUIRED';
  end if;

  response_value := public.mark_production_scoring_ingress_write_started(input);

  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for share;

  select * into lease
  from scoring_authority.scoring_ingress_leases value
  where value.tournament_id = '2026'
    and value.protocol_version = 'ADMISSION_V2'
    and value.lease_id = (input->>'lease_id')::uuid
  for share;

  if found then
    perform production_control.assert_production_scoring_lease_nonce(
      lease, input->>'lease_nonce'
    );
  end if;

  if not found
     or lease.provider_credential_class is distinct from
       'LEGACY_PROVIDER_FENCEABLE'
     or lease.provider_principal_fingerprint is distinct from
       expected_provider_principal
     or gate.provider_principal_fingerprint is distinct from
       expected_provider_principal
     or response_value->>'lease_id' is distinct from lease.lease_id::text
     or response_value->>'resolution_state' is distinct from
       lease.resolution_state
     or response_value->>'expires_at' is distinct from
       pg_catalog.to_jsonb(lease.expires_at)#>>'{}'
     or response_value->>'provider_credential_class' is distinct from
       lease.provider_credential_class
     or lease.operation_request_id is distinct from
       (input->>'operation_request_id')::uuid
     or lease.resolution_state not in ('WRITE_STARTED', 'PROVEN_NO_WRITE')
     or (
       lease.resolution_state = 'WRITE_STARTED'
       and (
         lease.write_started_at is null
         or response_value->>'write_started_at' is distinct from
           pg_catalog.to_jsonb(lease.write_started_at)#>>'{}'
       )
     )
     or (
       lease.resolution_state = 'PROVEN_NO_WRITE'
       and (
         lease.write_started_at is not null
         or lease.last_error_code is distinct from
           'LEASE_EXPIRED_BEFORE_PROVIDER_DISPATCH'
       )
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_WRITE_STARTED_V3_RECEIPT_MISMATCH';
  end if;

  -- Recompute from the authoritative row after every MARK attempt, including
  -- receipt replay. A lost response retried after expiry therefore returns a
  -- zero window and cannot authorize a delayed provider dispatch.
  remaining_dispatch_ms := greatest(
    0::bigint,
    pg_catalog.floor(extract(epoch from (
      lease.expires_at - pg_catalog.clock_timestamp()
    )) * 1000)::bigint
  );

  return response_value || pg_catalog.jsonb_build_object(
    'contract_version', 'ADMISSION_V3',
    'lease_id', lease.lease_id,
    'lease_nonce', pg_catalog.lower(input->>'lease_nonce'),
    'operation_request_id', lease.operation_request_id,
    'expires_at', lease.expires_at,
    'remaining_dispatch_ms', remaining_dispatch_ms,
    'provider_credential_class', lease.provider_credential_class,
    'provider_principal_fingerprint', lease.provider_principal_fingerprint,
    'provider_dispatch_must_begin_before_expires_at', true,
    'resolution_state', lease.resolution_state,
    'write_started_at', lease.write_started_at
  );
end;
$_$;


ALTER FUNCTION public.mark_production_scoring_ingress_write_started_v3(input jsonb) OWNER TO postgres;

--
-- Name: mark_production_vercel_writer_critical_waf_dispatch_started(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_production_vercel_writer_critical_waf_dispatch_started(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  dispatch production_control.vercel_writer_critical_waf_dispatches%rowtype;
  remaining_ms integer;
begin
  if input->>'operation' is distinct from
       'MARK_PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH_STARTED'
     or coalesce(input->>'dispatch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'dispatch_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'transition_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_MARK_INPUT_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict dispatch
  from production_control.vercel_writer_critical_waf_dispatches value
  where value.dispatch_id = (input->>'dispatch_id')::uuid
    and value.dispatch_request_id = (input->>'dispatch_request_id')::uuid
    and value.transition_request_id = (input->>'transition_request_id')::uuid
  for update;
  if dispatch.status is distinct from 'RESERVED'
     or dispatch.request_fingerprint is distinct from
       pg_catalog.lower(input->>'request_fingerprint')
     or dispatch.claim_expires_at <= pg_catalog.clock_timestamp()
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH_NOT_USABLE';
  end if;
  update production_control.vercel_writer_critical_waf_dispatches
  set status = 'PROVIDER_MUTATING',
      provider_dispatch_started_at = pg_catalog.clock_timestamp(),
      updated_at = pg_catalog.clock_timestamp()
  where dispatch_id = dispatch.dispatch_id
  returning * into dispatch;
  remaining_ms := greatest(0, pg_catalog.floor(extract(epoch from (
    dispatch.claim_expires_at - pg_catalog.clock_timestamp()
  )) * 1000)::integer);
  if remaining_ms <= 0 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH_EXPIRED';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'contract_version', 'CRITICAL_WINDOW_WAF_V1',
    'epoch_id', dispatch.epoch_id, 'dispatch_id', dispatch.dispatch_id,
    'dispatch_request_id', dispatch.dispatch_request_id,
    'transition_request_id', dispatch.transition_request_id,
    'dispatch_step', dispatch.dispatch_step,
    'provider_intent_fingerprint', dispatch.provider_intent_fingerprint,
    'status', dispatch.status,
    'remaining_dispatch_budget_ms', least(12000, remaining_ms),
    'dispatch_usable', true, 'replay_usable', false
  );
end;
$_$;


ALTER FUNCTION public.mark_production_vercel_writer_critical_waf_dispatch_started(input jsonb) OWNER TO postgres;

--
-- Name: mutate_certification_annual_transition_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_certification_annual_transition_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare ctx jsonb;command jsonb;result jsonb;action text:=input->>'operation_id';
begin
 perform production_control.assert_production_service_role();
 if action is null or action not in('ANNUAL.PREPARE','ANNUAL.CLOSE','ANNUAL.DRAIN','ANNUAL.ACTIVATE','ANNUAL.ABORT')then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_FORBIDDEN';end if;
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 ctx:=production_control.push_certification_context_v1(input,'ANNUAL',true);
 command:=production_control.certification_annual_transition_command_v1(input,ctx);
 case action
 when 'ANNUAL.PREPARE' then result:=production_control.canonical_prepare_annual_scoring_transition_v2(command,ctx);
 when 'ANNUAL.CLOSE' then result:=production_control.canonical_close_annual_scoring_transition_v2(command,ctx);
 when 'ANNUAL.DRAIN' then result:=production_control.canonical_drain_annual_scoring_transition_v2(command,ctx);
 when 'ANNUAL.ACTIVATE' then result:=production_control.canonical_activate_annual_scoring_transition_v2(command,ctx);
 when 'ANNUAL.ABORT' then result:=production_control.canonical_abort_annual_scoring_transition_v2(command,ctx);
 else raise exception using errcode='42501',message='CERTIFICATION_OPERATION_FORBIDDEN';end case;
 perform production_control.pop_certification_context_v1();return result;
end;$$;


ALTER FUNCTION public.mutate_certification_annual_transition_v1(input jsonb) OWNER TO postgres;

--
-- Name: mutate_certification_future_authoring_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_certification_future_authoring_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare context jsonb; resource production_control.canonical_resource_v1%rowtype;
 payload jsonb:=input->'payload'; command jsonb; result jsonb; op text:=input->>'operation_id';
 contract_value text; legacy_operation text; target_id text;
begin
 if jsonb_typeof(payload) is distinct from 'object' or payload ?| array[
  'authorization','environment','contract_version','resource','deployment','actor_player_id','actor_auth_user_id',
  'project_ref','project_url','source_workbook_id','tournament_id','tournament_year','operation_request_id',
  'resource_id','resource_class','installation_id','governance_tournament_id','expected_context_token','operation',
  'ingress','lease_id','admission_generation_id','request_hash'] then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_AUTHORITY_FIELD_REJECTED'; end if;
 if op='ANNUAL.RUNTIME' then
  if upper(btrim(coalesce(payload->>'action',''))) not in (
    'ASSIGN_FUTURE_COURSE','PROMOTE_RUNTIME_STRUCTURE','STAGE_HANDICAPS','APPROVE_HANDICAPS',
    'CONFIGURE_MATCH','REPLACE_PAIRINGS','PREPARE_SCORING_CONTEXT','GRANT_FUTURE_DIRECTOR','MARK_READY_FOR_ACTIVATION') then
   raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_ACTION_DENIED'; end if;
  contract_value:='production-future-runtime-activation-v2';
 else
  case op

  when 'ANNUAL.GUIDE_CREATE' then contract_value:='production-guide-authoring-v1';legacy_operation:='CREATE_PRODUCTION_GUIDE_DRAFT_V1';

  when 'ANNUAL.GUIDE_VALIDATE' then contract_value:='production-guide-authoring-v1';legacy_operation:='VALIDATE_PRODUCTION_GUIDE_DRAFT_V1';

  when 'ANNUAL.GUIDE_PUBLISH' then contract_value:='production-guide-authoring-v1';legacy_operation:='PUBLISH_PRODUCTION_GUIDE_DRAFT_V1';

  when 'ANNUAL.DRAFT_STAGE' then contract_value:='production-draft-authoring-v1';legacy_operation:='STAGE_PRODUCTION_DRAFT_REVISION_V1';

  when 'ANNUAL.DRAFT_VALIDATE' then contract_value:='production-draft-authoring-v1';legacy_operation:='VALIDATE_PRODUCTION_DRAFT_REVISION_V1';

  when 'ANNUAL.DRAFT_COMMIT' then contract_value:='production-draft-authoring-v1';legacy_operation:='COMMIT_PRODUCTION_DRAFT_REVISION_V1';

  when 'ANNUAL.PREDICTION_STAGE' then contract_value:='production-prediction-settings-authoring-v1';legacy_operation:='STAGE_PRODUCTION_PREDICTION_SETTINGS_REVISION_V1';

  when 'ANNUAL.PREDICTION_VALIDATE' then contract_value:='production-prediction-settings-authoring-v1';legacy_operation:='VALIDATE_PRODUCTION_PREDICTION_SETTINGS_REVISION_V1';

  when 'ANNUAL.PREDICTION_COMMIT' then contract_value:='production-prediction-settings-authoring-v1';legacy_operation:='COMMIT_PRODUCTION_PREDICTION_SETTINGS_REVISION_V1';

  else raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_ACTION_DENIED';end case;
 end if;
 -- The fence is acquired first; nested readiness/certificate work must not upgrade shared locks.
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 context:=production_control.push_certification_context_v1(input,'ANNUAL',true);
 select * into strict resource from production_control.canonical_resource_v1 where singleton;
 target_id:=btrim(coalesce(payload->>'target_tournament_id',''));
 if payload ? 'target_tournament_year' and payload->>'target_tournament_year' is distinct from target_id then
  raise exception using errcode='22023',message='CERTIFICATION_FUTURE_TARGET_YEAR_INVALID';end if;
 if target_id !~ '^20[0-9]{2}$' or target_id::integer <= (context->>'current_tournament_year')::integer
   or not exists(select 1 from production_control.future_tournament_catalog_v1 c
     join production_control.future_tournament_resources_v1 r using(tournament_id)
     where c.tournament_id=target_id and c.tournament_year=target_id::integer
       and c.lifecycle in('DRAFT','CONFIGURING','READY_FOR_ACTIVATION')
       and r.project_ref=resource.project_ref and r.project_url=resource.project_url
       and r.source_workbook_id=resource.provenance_id) then
  raise exception using errcode='42501',message='CERTIFICATION_FUTURE_TARGET_REQUIRED';end if;
 command:=payload||jsonb_build_object('contract_version',contract_value,'environment','CERTIFICATION',
  'project_ref',resource.project_ref,'project_url',resource.project_url,'source_workbook_id',resource.provenance_id,
  'tournament_id',context->>'current_tournament_id','tournament_year',(context->>'current_tournament_year')::integer,
  'authorization',context->'authorization','operation_request_id',input->>'operation_request_id');
 if legacy_operation is not null then command:=command||jsonb_build_object('operation',legacy_operation);end if;
 -- Domain-authoring hashes stay unchanged. Runtime hashes cover the canonical server-bound command.
 if op='ANNUAL.RUNTIME' then
  command:=(command-'request_payload_hash')||jsonb_build_object('request_payload_hash',
    production_control.future_runtime_hash_v2(command-'request_payload_hash'));
 end if;
 case op

 when 'ANNUAL.RUNTIME' then result:=production_control.canonical_mutate_future_runtime_resource_v2(command,context);

 when 'ANNUAL.GUIDE_CREATE' then result:=production_control.canonical_create_guide_draft_resource_v2(command,context);

 when 'ANNUAL.GUIDE_VALIDATE' then result:=production_control.canonical_validate_guide_draft_resource_v2(command,context);

 when 'ANNUAL.GUIDE_PUBLISH' then result:=production_control.canonical_publish_guide_draft_resource_v2(command,context);

 when 'ANNUAL.DRAFT_STAGE' then result:=production_control.canonical_stage_draft_revision_resource_v2(command,context);

 when 'ANNUAL.DRAFT_VALIDATE' then result:=production_control.canonical_validate_draft_revision_resource_v2(command,context);

 when 'ANNUAL.DRAFT_COMMIT' then result:=production_control.canonical_commit_draft_revision_resource_v2(command,context);

 when 'ANNUAL.PREDICTION_STAGE' then result:=production_control.canonical_stage_prediction_settings_revision_resource_v2(command,context);

 when 'ANNUAL.PREDICTION_VALIDATE' then result:=production_control.canonical_validate_prediction_settings_revision_resource_v2(command,context);

 when 'ANNUAL.PREDICTION_COMMIT' then result:=production_control.canonical_commit_prediction_settings_revision_resource_v2(command,context);

 else raise exception using errcode='42501',message='CERTIFICATION_ANNUAL_ACTION_DENIED';end case;
 if coalesce((result->>'ok')::boolean,false) and not coalesce((result->>'idempotent')::boolean,false) then
  insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
  values('CERTIFICATION_ANNUAL_AUTHORING','ANNUAL',target_id,context#>>'{authorization,player_id}',
   production_control.future_year_hash_v1(payload),'SUCCEEDED',jsonb_build_object('resource_class','CERTIFICATION',
    'resource_id',context->>'resource_id','installation_id',context->>'installation_id','binding_id',context->>'binding_id',
    'context_token',context->>'context_token','operation_request_id',input->>'operation_request_id','operation_id',op,
    'release_commit',context->>'release_commit','admission_revision',context->'admission_revision',
    'actor_auth_user_id',context#>>'{authorization,auth_user_id}','receipt',result));
 end if;
 perform production_control.pop_certification_context_v1();return result;
end;
$_$;


ALTER FUNCTION public.mutate_certification_future_authoring_v1(input jsonb) OWNER TO postgres;

--
-- Name: mutate_certification_future_year_administration_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_certification_future_year_administration_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare context jsonb; result jsonb;
begin
 context:=production_control.push_certification_context_v1(input,'ANNUAL',true);
 result:=production_control.dispatch_certification_annual_v1(input,context,true);
 perform production_control.pop_certification_context_v1();return result;
end;
$$;


ALTER FUNCTION public.mutate_certification_future_year_administration_v1(input jsonb) OWNER TO postgres;

--
-- Name: mutate_production_access_governance_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_production_access_governance_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'scoring_authority'
    AS $_$
declare
  action_value text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'action', ''
  )));
  actor_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'actor_player_id', ''
  )));
  actor_auth uuid;
  target_player text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'player_id', ''
  )));
  operation_request uuid;
  expected_revision bigint;
  expected_profile_revision bigint := 0;
  expected_membership_revision bigint := 0;
  result_profile_revision bigint := 0;
  result_membership_revision bigint := 0;
  current_revision bigint;
  next_revision bigint;
  declared_hash text := pg_catalog.lower(coalesce(
    input->>'request_payload_hash', ''
  ));
  database_hash text;
  receipt production_control.access_governance_operation_receipts_v1%rowtype;
  response_value jsonb;
  changed_value boolean := false;
  role_changed boolean := false;
  audit_action text;
  metadata_value jsonb := '{}'::jsonb;
  target_status text;
  dependency_value jsonb;
  first_name_value text;
  last_name_value text;
  display_name_value text;
  player_prefix text;
  player_ordinal integer;
  slug_value text;
  target_auth uuid;
  entitlement_value production_control.director_entitlements%rowtype;
  reason_value text := pg_catalog.regexp_replace(
    pg_catalog.btrim(coalesce(input->>'reason', '')),
    '[[:space:]]+', ' ', 'g'
  );
begin
  perform production_control.assert_access_governance_runtime_v1(input);
  if action_value not in (
       'CREATE_PLAYER', 'SET_GLOBAL_STATUS', 'WITHDRAW_MEMBERSHIP',
       'REACTIVATE_MEMBERSHIP', 'GRANT_DIRECTOR', 'REVOKE_DIRECTOR'
     )
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'expected_revision', '') !~ '^[0-9]+$' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACCESS_GOVERNANCE_INPUT_INVALID'
    );
  end if;
  if action_value = 'SET_GLOBAL_STATUS'
     and coalesce(input->>'expected_profile_revision', '') !~ '^[0-9]+$' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACCESS_GOVERNANCE_PROFILE_REVISION_REQUIRED'
    );
  end if;
  if action_value in ('WITHDRAW_MEMBERSHIP', 'REACTIVATE_MEMBERSHIP')
     and coalesce(input->>'expected_membership_revision', '')
       !~ '^[0-9]+$' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACCESS_GOVERNANCE_MEMBERSHIP_REVISION_REQUIRED'
    );
  end if;
  begin
    actor_auth := (input->>'actor_auth_user_id')::uuid;
    operation_request := (input->>'operation_request_id')::uuid;
    expected_revision := (input->>'expected_revision')::bigint;
    if action_value = 'SET_GLOBAL_STATUS' then
      if coalesce(input->>'expected_profile_revision', '') !~ '^[0-9]+$' then
        raise exception using errcode = '22023',
          message = 'ACCESS_GOVERNANCE_PROFILE_REVISION_REQUIRED';
      end if;
      expected_profile_revision :=
        (input->>'expected_profile_revision')::bigint;
    end if;
    if action_value in ('WITHDRAW_MEMBERSHIP', 'REACTIVATE_MEMBERSHIP') then
      if coalesce(input->>'expected_membership_revision', '') !~ '^[0-9]+$' then
        raise exception using errcode = '22023',
          message = 'ACCESS_GOVERNANCE_MEMBERSHIP_REVISION_REQUIRED';
      end if;
      expected_membership_revision :=
        (input->>'expected_membership_revision')::bigint;
    end if;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACCESS_GOVERNANCE_INPUT_INVALID'
    );
  end;
  database_hash := production_control.access_governance_hash_v1(
    input - 'request_payload_hash'
  );
  select value.* into receipt
  from production_control.access_governance_operation_receipts_v1 value
  where value.tournament_id = '2026'
    and value.operation = action_value
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.database_request_payload_hash = database_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACCESS_GOVERNANCE_IDEMPOTENCY_CONFLICT'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'production-access-governance-v1:2026', 0
  ));
  select value.* into receipt
  from production_control.access_governance_operation_receipts_v1 value
  where value.tournament_id = '2026'
    and value.operation = action_value
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.database_request_payload_hash = database_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACCESS_GOVERNANCE_IDEMPOTENCY_CONFLICT'
    );
  end if;

  current_revision := production_control.access_governance_revision_v1('2026');
  if current_revision <> expected_revision then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'ACCESS_GOVERNANCE_REVISION_STALE',
      'currentRevision', current_revision
    );
  end if;

  begin
    if action_value = 'CREATE_PLAYER' then
      first_name_value := pg_catalog.regexp_replace(
        pg_catalog.btrim(coalesce(input->>'first_name', '')),
        '[[:space:]]+', ' ', 'g'
      );
      last_name_value := pg_catalog.regexp_replace(
        pg_catalog.btrim(coalesce(input->>'last_name', '')),
        '[[:space:]]+', ' ', 'g'
      );
      display_name_value := pg_catalog.regexp_replace(
        pg_catalog.btrim(coalesce(
          input->>'display_name', first_name_value || ' ' || last_name_value
        )), '[[:space:]]+', ' ', 'g'
      );
      target_status := pg_catalog.upper(pg_catalog.btrim(coalesce(
        input->>'global_status', 'ACTIVE'
      )));
      if pg_catalog.length(first_name_value) not between 1 and 80
         or pg_catalog.length(last_name_value) not between 1 and 80
         or first_name_value !~
           '^[A-Za-z]([A-Za-z.'' -]*[A-Za-z.])?$'
         or last_name_value !~
           '^[A-Za-z]([A-Za-z.'' -]*[A-Za-z.])?$'
         or pg_catalog.length(display_name_value) not between 2 and 160
         or display_name_value ~ '[[:cntrl:]<>{}]'
         or target_status not in ('ACTIVE', 'ALUMNI') then
        raise exception using errcode = '22023',
          message = 'ACCESS_GOVERNANCE_PLAYER_INPUT_INVALID';
      end if;
      if exists (
        select 1 from scoring_authority.players player
        where pg_catalog.lower(pg_catalog.btrim(player.display_name)) =
          pg_catalog.lower(display_name_value)
           or (
             pg_catalog.lower(pg_catalog.btrim(coalesce(
               player.source_payload->>'First', ''
             ))) = pg_catalog.lower(first_name_value)
             and pg_catalog.lower(pg_catalog.btrim(coalesce(
               player.source_payload->>'Last', ''
             ))) = pg_catalog.lower(last_name_value)
           )
      ) or exists (
        select 1
        from production_control.player_governance_profiles_v1 profile
        where pg_catalog.lower(pg_catalog.btrim(coalesce(
          profile.first_name, ''
        ))) = pg_catalog.lower(first_name_value)
          and pg_catalog.lower(pg_catalog.btrim(coalesce(
            profile.last_name, ''
          ))) = pg_catalog.lower(last_name_value)
      ) then
        raise exception using errcode = '23505',
          message = 'ACCESS_GOVERNANCE_PLAYER_IDENTITY_COLLISION';
      end if;
      player_prefix := pg_catalog.upper(
        pg_catalog.left(first_name_value, 1) ||
        pg_catalog.left(last_name_value, 1)
      );
      if player_prefix !~ '^[A-Z]{2}$' then
        raise exception using errcode = '22023',
          message = 'ACCESS_GOVERNANCE_PLAYER_ID_PREFIX_INVALID';
      end if;
      perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'production-player-id-v1:' || player_prefix, 0
      ));
      select coalesce(pg_catalog.max(
        pg_catalog.substr(player.player_id, 3)::integer
      ), 0) + 1 into player_ordinal
      from scoring_authority.players player
      where player.player_id ~ ('^' || player_prefix || '[0-9]{2}$');
      if player_ordinal > 99 then
        raise exception using errcode = '54000',
          message = 'ACCESS_GOVERNANCE_PLAYER_ID_SPACE_EXHAUSTED';
      end if;
      target_player := player_prefix || pg_catalog.lpad(
        player_ordinal::text, 2, '0'
      );
      slug_value := pg_catalog.lower(pg_catalog.btrim(coalesce(
        input->>'slug', ''
      )));
      if pg_catalog.length(slug_value) not between 2 and 120
         or slug_value !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then
        raise exception using errcode = '22023',
          message = 'ACCESS_GOVERNANCE_PLAYER_SLUG_INVALID';
      end if;
      if exists (
        select 1 from scoring_authority.players player
        where pg_catalog.lower(coalesce(player.source_payload->>'Slug', '')) =
          slug_value
      ) or exists (
        select 1
        from production_control.player_governance_profiles_v1 profile
        where pg_catalog.lower(coalesce(profile.profile_slug, '')) = slug_value
      ) then
        raise exception using errcode = '23505',
          message = 'ACCESS_GOVERNANCE_PLAYER_SLUG_COLLISION';
      end if;
      insert into scoring_authority.players (
        player_id, display_name, source_payload
      ) values (
        target_player, display_name_value,
        pg_catalog.jsonb_build_object(
          'Player ID', target_player,
          'First', first_name_value,
          'Last', last_name_value,
          'Display Name', display_name_value,
          'Slug', slug_value,
          'Active', case when target_status = 'ACTIVE' then 'TRUE' else 'FALSE' end,
          'Governance Contract', 'production-access-governance-v1'
        )
      );
      insert into production_control.player_governance_profiles_v1 (
        player_id, first_name, last_name, profile_slug, global_status,
        profile_revision, created_by_player_id, updated_by_player_id
      ) values (
        target_player, first_name_value, last_name_value, slug_value,
        target_status, 1, actor_player, actor_player
      );
      changed_value := true;
      audit_action := 'PLAYER_CREATED';
      metadata_value := pg_catalog.jsonb_build_object(
        'global_status', target_status,
        'membership_created', false,
        'auth_user_created', false,
        'team_assigned', false
      );
    else
      if target_player = '' or not exists (
        select 1 from scoring_authority.players player
        where player.player_id = target_player
      ) then
        raise exception using errcode = '22023',
          message = 'ACCESS_GOVERNANCE_PLAYER_ID_REQUIRED';
      end if;
      if action_value = 'SET_GLOBAL_STATUS' then
        result_profile_revision := production_control
          .access_governance_profile_revision_v1(target_player);
        if result_profile_revision <> expected_profile_revision then
          return pg_catalog.jsonb_build_object(
            'ok', false, 'code', 'ACCESS_GOVERNANCE_PROFILE_REVISION_STALE',
            'playerId', target_player,
            'currentProfileRevision', result_profile_revision,
            'revision', current_revision
          );
        end if;
        target_status := pg_catalog.upper(pg_catalog.btrim(coalesce(
          input->>'global_status', ''
        )));
        if target_status not in ('ACTIVE', 'ALUMNI') then
          raise exception using errcode = '22023',
            message = 'ACCESS_GOVERNANCE_GLOBAL_STATUS_INVALID';
        end if;
        if target_status = 'ALUMNI' and exists (
          select 1 from scoring_authority.tournament_players membership
          where membership.tournament_id = '2026'
            and membership.player_id = target_player
            and membership.participation_status = 'ACTIVE'
        ) then
          raise exception using errcode = '55000',
            message = 'ACCESS_GOVERNANCE_ACTIVE_MEMBERSHIP_BLOCKS_ALUMNI';
        end if;
        changed_value :=
          production_control.access_governance_global_status_v1(target_player)
          is distinct from target_status;
        if changed_value then
          insert into production_control.player_governance_profiles_v1 (
            player_id, global_status, profile_revision,
            created_by_player_id, updated_by_player_id
          ) values (
            target_player, target_status, 1, actor_player, actor_player
          ) on conflict (player_id) do update set
            global_status = excluded.global_status,
            profile_revision = production_control
              .player_governance_profiles_v1.profile_revision + 1,
            updated_by_player_id = excluded.updated_by_player_id,
            updated_at = pg_catalog.clock_timestamp();
          result_profile_revision := expected_profile_revision + 1;
        end if;
        audit_action := 'GLOBAL_STATUS_CHANGED';
        metadata_value := pg_catalog.jsonb_build_object(
          'global_status', target_status,
          'membership_changed', false,
          'history_preserved', true
        );
      elsif action_value = 'WITHDRAW_MEMBERSHIP' then
        perform production_control.assert_access_governance_safe_reason_v1(
          reason_value
        );
        result_membership_revision := production_control
          .access_governance_membership_revision_v1('2026', target_player);
        if result_membership_revision <> expected_membership_revision then
          return pg_catalog.jsonb_build_object(
            'ok', false,
            'code', 'ACCESS_GOVERNANCE_MEMBERSHIP_REVISION_STALE',
            'playerId', target_player,
            'currentMembershipRevision', result_membership_revision,
            'revision', current_revision
          );
        end if;
        if not exists (
          select 1 from scoring_authority.tournament_players membership
          where membership.tournament_id = '2026'
            and membership.player_id = target_player
            and membership.participation_status = 'ACTIVE'
        ) then
          raise exception using errcode = '55000',
            message = 'ACCESS_GOVERNANCE_ACTIVE_MEMBERSHIP_REQUIRED';
        end if;
        dependency_value := production_control
          .access_governance_membership_dependencies_v1(target_player);
        if pg_catalog.jsonb_array_length(
          dependency_value->'hardBlockers'
        ) > 0 then
          return pg_catalog.jsonb_build_object(
            'ok', false,
            'code', 'ACCESS_GOVERNANCE_MEMBERSHIP_DEPENDENCY_BLOCKED',
            'playerId', target_player,
            'readiness', dependency_value,
            'revision', current_revision
          );
        end if;
        update scoring_authority.tournament_players set
          participation_status = 'WITHDRAWN',
          updated_at = pg_catalog.clock_timestamp()
        where tournament_id = '2026' and player_id = target_player
          and participation_status = 'ACTIVE';
        changed_value := found;
        if changed_value then
          result_membership_revision := expected_membership_revision + 1;
          insert into production_control
            .access_governance_membership_revisions_v1 (
              tournament_id, player_id, membership_revision,
              participation_status, updated_by_player_id,
              updated_by_auth_user_id
            ) values (
              '2026', target_player, result_membership_revision,
              'WITHDRAWN', actor_player, actor_auth
            ) on conflict (tournament_id, player_id) do update set
              membership_revision = excluded.membership_revision,
              participation_status = excluded.participation_status,
              updated_by_player_id = excluded.updated_by_player_id,
              updated_by_auth_user_id = excluded.updated_by_auth_user_id,
              updated_at = pg_catalog.clock_timestamp();
        end if;
        audit_action := 'MEMBERSHIP_WITHDRAWN';
        metadata_value := pg_catalog.jsonb_build_object(
          'membership_status', 'WITHDRAWN',
          'pairings_changed', false,
          'handicap_changed', false,
          'auth_link_changed', false,
          'reason_provided', true,
          'warnings', dependency_value->'warnings'
        );
      elsif action_value = 'REACTIVATE_MEMBERSHIP' then
        perform production_control.assert_access_governance_safe_reason_v1(
          reason_value
        );
        result_membership_revision := production_control
          .access_governance_membership_revision_v1('2026', target_player);
        if result_membership_revision <> expected_membership_revision then
          return pg_catalog.jsonb_build_object(
            'ok', false,
            'code', 'ACCESS_GOVERNANCE_MEMBERSHIP_REVISION_STALE',
            'playerId', target_player,
            'currentMembershipRevision', result_membership_revision,
            'revision', current_revision
          );
        end if;
        if production_control.access_governance_global_status_v1(target_player)
             <> 'ACTIVE' then
          raise exception using errcode = '55000',
            message = 'ACCESS_GOVERNANCE_ACTIVE_GLOBAL_PLAYER_REQUIRED';
        end if;
        if not exists (
          select 1 from scoring_authority.tournament_players membership
          where membership.tournament_id = '2026'
            and membership.player_id = target_player
            and membership.participation_status in ('WITHDRAWN', 'INACTIVE')
        ) then
          raise exception using errcode = '55000',
            message = 'ACCESS_GOVERNANCE_INACTIVE_MEMBERSHIP_REQUIRED';
        end if;
        update scoring_authority.tournament_players set
          participation_status = 'ACTIVE',
          updated_at = pg_catalog.clock_timestamp()
        where tournament_id = '2026' and player_id = target_player
          and participation_status in ('WITHDRAWN', 'INACTIVE');
        changed_value := found;
        if changed_value then
          result_membership_revision := expected_membership_revision + 1;
          insert into production_control
            .access_governance_membership_revisions_v1 (
              tournament_id, player_id, membership_revision,
              participation_status, updated_by_player_id,
              updated_by_auth_user_id
            ) values (
              '2026', target_player, result_membership_revision,
              'ACTIVE', actor_player, actor_auth
            ) on conflict (tournament_id, player_id) do update set
              membership_revision = excluded.membership_revision,
              participation_status = excluded.participation_status,
              updated_by_player_id = excluded.updated_by_player_id,
              updated_by_auth_user_id = excluded.updated_by_auth_user_id,
              updated_at = pg_catalog.clock_timestamp();
        end if;
        dependency_value := production_control
          .access_governance_membership_dependencies_v1(target_player);
        audit_action := 'MEMBERSHIP_REACTIVATED';
        metadata_value := pg_catalog.jsonb_build_object(
          'membership_status', 'ACTIVE',
          'team_changed', false,
          'handicap_changed', false,
          'auth_link_changed', false,
          'reason_provided', true,
          'warnings', dependency_value->'warnings'
        );
      else
        perform production_control.assert_access_governance_owner_v1(
          '2026', actor_player, actor_auth
        );
        perform production_control.assert_access_governance_safe_reason_v1(
          reason_value
        );
        if input->'confirmed' is distinct from 'true'::jsonb then
          raise exception using errcode = '22023',
            message = 'ACCESS_GOVERNANCE_CONFIRMATION_REQUIRED';
        end if;
        if action_value = 'GRANT_DIRECTOR' then
          if not exists (
            select 1 from scoring_authority.tournament_players membership
            where membership.tournament_id = '2026'
              and membership.player_id = target_player
              and membership.participation_status = 'ACTIVE'
          ) then
            raise exception using errcode = '55000',
              message = 'ACCESS_GOVERNANCE_ACTIVE_MEMBERSHIP_REQUIRED';
          end if;
          if exists (
            select 1
            from production_control.tournament_owner_capabilities_v1 owner_value
            where owner_value.tournament_id = '2026'
              and owner_value.player_id = target_player
              and owner_value.status = 'ACTIVE'
          ) then
            raise exception using errcode = '55000',
              message = 'ACCESS_GOVERNANCE_TARGET_ALREADY_OWNER';
          end if;
          select link.auth_user_id into target_auth
          from participant_identity.user_player_links link
          join auth.users auth_user on auth_user.id = link.auth_user_id
          where link.player_id = target_player
            and link.status = 'ACTIVE'
            and (auth_user.email_confirmed_at is not null
              or auth_user.phone_confirmed_at is not null)
            and exists (
              select 1
              from participant_identity.participant_auth_identifiers identifier
              where identifier.auth_user_id = link.auth_user_id
                and identifier.player_id = link.player_id
                and identifier.status = 'VERIFIED'
            )
          order by link.link_revision desc limit 1;
          if target_auth is null then
            raise exception using errcode = '55000',
              message = 'ACCESS_GOVERNANCE_LINKED_AUTH_REQUIRED';
          end if;
          select value.* into entitlement_value
          from production_control.director_entitlements value
          where value.tournament_id = '2026'
            and value.auth_user_id = target_auth;
          if found and (
            entitlement_value.player_id is distinct from target_player
            or entitlement_value.role <> 'DIRECTOR'
          ) then
            raise exception using errcode = '55000',
              message = 'ACCESS_GOVERNANCE_ENTITLEMENT_IDENTITY_CONFLICT';
          end if;
          changed_value := not found
            or entitlement_value.status <> 'ACTIVE'
            or entitlement_value.role <> 'DIRECTOR'
            or entitlement_value.player_id is distinct from target_player;
          if changed_value then
            insert into production_control.director_entitlements (
              auth_user_id, tournament_id, player_id, role, status,
              granted_by, granted_at, revoked_at
            ) values (
              target_auth, '2026', target_player, 'DIRECTOR', 'ACTIVE',
              actor_player, pg_catalog.clock_timestamp(), null
            ) on conflict (auth_user_id, tournament_id) do update set
              player_id = excluded.player_id,
              role = 'DIRECTOR', status = 'ACTIVE',
              granted_by = excluded.granted_by,
              granted_at = excluded.granted_at,
              revoked_at = null;
            select value.* into strict entitlement_value
            from production_control.director_entitlements value
            where value.tournament_id = '2026'
              and value.auth_user_id = target_auth;
            insert into production_control.director_entitlement_events (
              entitlement_id, action, actor, reason
            ) values (
              entitlement_value.entitlement_id, 'GRANTED',
              actor_player, reason_value
            );
          end if;
          role_changed := not exists (
            select 1 from participant_identity.tournament_roles role_value
            where role_value.tournament_id = '2026'
              and role_value.auth_user_id = target_auth
              and role_value.role = 'DIRECTOR'
              and role_value.role_active
              and role_value.revoked_at is null
          );
          insert into participant_identity.tournament_roles (
            tournament_id, auth_user_id, role, role_active, role_revision,
            granted_at, granted_by, revoked_at, revoked_by
          ) values (
            '2026', target_auth, 'DIRECTOR', true, 1,
            pg_catalog.clock_timestamp(), actor_player, null, null
          ) on conflict (tournament_id, auth_user_id, role) do update set
            role_active = true,
            role_revision = participant_identity
              .tournament_roles.role_revision + case
                when participant_identity.tournament_roles.role_active
                  and participant_identity.tournament_roles.revoked_at is null
                then 0 else 1 end,
            granted_at = case
              when participant_identity.tournament_roles.role_active
                and participant_identity.tournament_roles.revoked_at is null
              then participant_identity.tournament_roles.granted_at
              else pg_catalog.clock_timestamp() end,
            granted_by = case
              when participant_identity.tournament_roles.role_active
                and participant_identity.tournament_roles.revoked_at is null
              then participant_identity.tournament_roles.granted_by
              else actor_player end,
            revoked_at = null, revoked_by = null,
            updated_at = case
              when participant_identity.tournament_roles.role_active
                and participant_identity.tournament_roles.revoked_at is null
              then participant_identity.tournament_roles.updated_at
              else pg_catalog.clock_timestamp() end;
          changed_value := changed_value or role_changed;
          audit_action := 'DIRECTOR_GRANTED';
          metadata_value := pg_catalog.jsonb_build_object(
            'role', 'DIRECTOR', 'reason', reason_value,
            'identity_changed', false, 'membership_changed', false
          );
        else
          if target_player = actor_player then
            raise exception using errcode = '55000',
              message = 'ACCESS_GOVERNANCE_SELF_REVOKE_BLOCKED';
          end if;
          if exists (
            select 1
            from production_control.tournament_owner_capabilities_v1 owner_value
            where owner_value.tournament_id = '2026'
              and owner_value.player_id = target_player
              and owner_value.status = 'ACTIVE'
          ) then
            raise exception using errcode = '55000',
              message = 'ACCESS_GOVERNANCE_OWNER_REVOKE_BLOCKED';
          end if;
          select value.* into entitlement_value
          from participant_identity.user_player_links target_link
          join production_control.director_entitlements value
            on value.tournament_id = '2026'
           and value.player_id = target_link.player_id
           and value.auth_user_id = target_link.auth_user_id
           and value.role = 'DIRECTOR'
          where target_link.player_id = target_player
            and target_link.status = 'ACTIVE'
            and target_link.revoked_at is null;
          if not found or entitlement_value.status = 'REVOKED' then
            changed_value := false;
          else
            if not exists (
              select 1
              from production_control.director_entitlements other_value
              join scoring_authority.tournament_players other_membership
                on other_membership.tournament_id = other_value.tournament_id
               and other_membership.player_id = other_value.player_id
               and other_membership.participation_status = 'ACTIVE'
              join participant_identity.user_player_links other_link
                on other_link.auth_user_id = other_value.auth_user_id
               and other_link.player_id = other_value.player_id
               and other_link.status = 'ACTIVE'
              join auth.users other_auth
                on other_auth.id = other_link.auth_user_id
              join participant_identity.tournament_roles other_role
                on other_role.tournament_id = other_value.tournament_id
               and other_role.auth_user_id = other_value.auth_user_id
               and other_role.role = 'DIRECTOR'
               and other_role.role_active
               and other_role.revoked_at is null
              where other_value.tournament_id = '2026'
                and other_value.status = 'ACTIVE'
                and other_value.entitlement_id <>
                  entitlement_value.entitlement_id
                and (other_auth.email_confirmed_at is not null
                  or other_auth.phone_confirmed_at is not null)
            ) then
              raise exception using errcode = '55000',
                message = 'ACCESS_GOVERNANCE_FINAL_ADMIN_PROTECTED';
            end if;
            update production_control.director_entitlements set
              status = 'REVOKED', revoked_at = pg_catalog.clock_timestamp()
            where entitlement_id = entitlement_value.entitlement_id
              and status = 'ACTIVE' and role = 'DIRECTOR';
            changed_value := found;
            if changed_value then
              insert into production_control.director_entitlement_events (
                entitlement_id, action, actor, reason
              ) values (
                entitlement_value.entitlement_id, 'REVOKED',
                actor_player, reason_value
              );
            end if;
          end if;
          update participant_identity.tournament_roles set
            role_active = false,
            role_revision = role_revision + 1,
            revoked_at = pg_catalog.clock_timestamp(),
            revoked_by = actor_player,
            updated_at = pg_catalog.clock_timestamp()
          where tournament_id = '2026'
            and auth_user_id = entitlement_value.auth_user_id
            and role = 'DIRECTOR' and role_active;
          changed_value := changed_value or found;
          audit_action := 'DIRECTOR_REVOKED';
          metadata_value := pg_catalog.jsonb_build_object(
            'role', 'DIRECTOR', 'reason', reason_value,
            'identity_changed', false, 'membership_changed', false
          );
        end if;
      end if;
    end if;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', case
        when sqlerrm ~ '^ACCESS_GOVERNANCE_[A-Z0-9_]+$' then sqlerrm
        else 'ACCESS_GOVERNANCE_OPERATION_FAILED' end
    );
  end;

  next_revision := current_revision + case when changed_value then 1 else 0 end;
  if changed_value then
    insert into production_control.access_governance_context_v1 (
      tournament_id, revision, updated_by_player_id, updated_by_auth_user_id
    ) values (
      '2026', next_revision, actor_player, actor_auth
    ) on conflict (tournament_id) do update set
      revision = excluded.revision,
      updated_by_player_id = excluded.updated_by_player_id,
      updated_by_auth_user_id = excluded.updated_by_auth_user_id,
      updated_at = pg_catalog.clock_timestamp();
  end if;

  result_profile_revision := production_control
    .access_governance_profile_revision_v1(target_player);
  result_membership_revision := production_control
    .access_governance_membership_revision_v1('2026', target_player);

  insert into production_control.access_governance_audit_events_v1 (
    tournament_id, action, target_player_id, actor_player_id,
    prior_revision, next_revision, operation_request_id, result,
    profile_revision, membership_revision, safe_metadata
  ) values (
    '2026', audit_action, target_player, actor_player,
    current_revision, next_revision, operation_request,
    case when changed_value then 'CHANGED' else 'NO_CHANGE' end,
    result_profile_revision, result_membership_revision, metadata_value
  );

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_ACCESS_GOVERNANCE_' || action_value ||
      case when changed_value then '_COMPLETED' else '_NO_CHANGE' end,
    'action', action_value,
    'playerId', target_player,
    'changed', changed_value,
    'revision', next_revision,
    'profileRevision', result_profile_revision,
    'membershipRevision', result_membership_revision,
    'idempotent', false,
    'membershipCreated', false,
    'teamChanged', false,
    'authUserCreated', false
  );
  if action_value in ('WITHDRAW_MEMBERSHIP', 'REACTIVATE_MEMBERSHIP') then
    response_value := response_value || pg_catalog.jsonb_build_object(
      'readiness', production_control
        .access_governance_membership_dependencies_v1(target_player)
    );
  end if;
  insert into production_control.access_governance_operation_receipts_v1 (
    tournament_id, operation, operation_request_id,
    declared_request_payload_hash, database_request_payload_hash,
    actor_player_id, actor_auth_user_id, response
  ) values (
    '2026', action_value, operation_request, declared_hash, database_hash,
    actor_player, actor_auth, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.mutate_production_access_governance_v1(input jsonb) OWNER TO postgres;

--
-- Name: mutate_production_future_runtime_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_production_future_runtime_v2(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if upper(btrim(coalesce(input->>'action',''))) not in (
  'ADD_GLOBAL_COURSE','CONFIGURE_GLOBAL_COURSE_CONTEXT','ASSIGN_FUTURE_COURSE','PROMOTE_RUNTIME_STRUCTURE',
  'STAGE_HANDICAPS','APPROVE_HANDICAPS','CONFIGURE_MATCH','REPLACE_PAIRINGS','PREPARE_SCORING_CONTEXT',
  'GRANT_FUTURE_DIRECTOR','MARK_READY_FOR_ACTIVATION','ACTIVATE_TOURNAMENT','CLOSE_TOURNAMENT','PREPARE_ARCHIVE_PLAN') then
  raise exception using errcode='22023',message='PRODUCTION_FUTURE_RUNTIME_ACTION_INVALID';end if;
 perform production_control.assert_future_runtime_service_scope_v2(input,true,upper(btrim(coalesce(input->>'action',''))) in (
  'ADD_GLOBAL_COURSE','CONFIGURE_GLOBAL_COURSE_CONTEXT','PROMOTE_RUNTIME_STRUCTURE','GRANT_FUTURE_DIRECTOR',
  'MARK_READY_FOR_ACTIVATION','ACTIVATE_TOURNAMENT','CLOSE_TOURNAMENT','PREPARE_ARCHIVE_PLAN'));
 return production_control.canonical_mutate_future_runtime_resource_v2(input,production_control.annual_resource_context_v2());
end;
$$;


ALTER FUNCTION public.mutate_production_future_runtime_v2(input jsonb) OWNER TO postgres;

