-- Name: mutate_production_tournament_setup_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mutate_production_tournament_setup_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
 perform production_control.assert_tournament_setup_runtime_v1(input);
 return production_control.mutate_late_r3_dispatch_v1(input,false);
end;
