--
-- Name: read_calcutta_configuration_view(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_calcutta_configuration_view(target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  started_at timestamptz := clock_timestamp();
  target_tournament text := btrim(coalesce(target_tournament_id, ''));
  tournament_value jsonb;
  configuration_value jsonb;
begin
  if target_tournament = '' then return jsonb_build_object('ok', false, 'code', 'TOURNAMENT_REQUIRED'); end if;
  select to_jsonb(t) into tournament_value from scoring_authority.tournaments t where t.tournament_id = target_tournament;
  if tournament_value is null then return jsonb_build_object('ok', false, 'code', 'TOURNAMENT_NOT_FOUND'); end if;
  select to_jsonb(c) - 'source_workbook_id' into configuration_value
  from scoring_authority.calcutta_configurations c
  where c.tournament_id = target_tournament and c.is_current and c.status = 'APPROVED';
  if configuration_value is null then return jsonb_build_object('ok', false, 'code', 'CALCUTTA_CONFIGURATION_REQUIRED'); end if;
  return jsonb_build_object('ok', true, 'data', jsonb_build_object(
    'tournament', tournament_value, 'configuration', configuration_value,
    'query_ms', round(extract(epoch from (clock_timestamp() - started_at)) * 1000, 3)
  ));
end;
$$;


ALTER FUNCTION public.read_calcutta_configuration_view(target_tournament_id text) OWNER TO postgres;

--
-- Name: read_certification_annual_transition_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_certification_annual_transition_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $$
declare ctx jsonb;result jsonb;command jsonb;action text:=input->>'operation_id';
begin
 perform production_control.assert_production_service_role();
 if action is null or action not in('ANNUAL.READINESS','ANNUAL.STATUS')then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_FORBIDDEN';end if;
 perform pg_advisory_xact_lock(production_control.scoring_admission_lock_key());
 ctx:=production_control.push_certification_context_v1(input,'ANNUAL',false);
 command:=production_control.certification_annual_transition_command_v1(input,ctx);
 if action='ANNUAL.READINESS' then
  result:=production_control.annual_scoring_transition_readiness_v1(command->>'target_tournament_id');
 else
  if input->>'status_operation' is null or input->>'status_operation' not in('PREPARE','CLOSE','DRAIN','ACTIVATE','ABORT')then
   raise exception using errcode='42501',message='CERTIFICATION_OPERATION_FORBIDDEN';end if;
  result:=production_control.lookup_canonical_annual_scoring_receipt_v2(input->>'status_operation',command,ctx);
  result:=case when result is null then jsonb_build_object('ok',true,'status','UNKNOWN')
   else jsonb_build_object('ok',true,'status','COMMITTED','receipt',result)end;
 end if;
 perform production_control.pop_certification_context_v1();return result;
end;$$;


ALTER FUNCTION public.read_certification_annual_transition_v1(input jsonb) OWNER TO postgres;

--
-- Name: read_certification_director_recovery_material_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_certification_director_recovery_material_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare l production_control.certification_ingress_leases_v1%rowtype; result jsonb;
begin
 if input->>'operation_id' not in('DIRECTOR.MUTATE_SETUP','DIRECTOR.MUTATE_PAIRINGS','DIRECTOR.MATCH_CONTROL',
   'DIRECTOR.SAVE_NET_SKINS_ENTRIES','DIRECTOR.CONFIGURE_NET_SKINS','DIRECTOR.PUBLISH_CALCUTTA','DIRECTOR.REPLACE_CALCUTTA_AUCTION','DIRECTOR.CLEAR_CALCUTTA_AUCTION')
  or input->>'operation_id' is null or input#>>'{authorization,role}' is distinct from 'DIRECTOR'
  or input->>'phase' is distinct from 'DIRECTOR' or jsonb_typeof(input->'payload') is distinct from 'object'
  or exists(select 1 from jsonb_object_keys(input->'payload') k where k<>'match_id')
  or(input->>'operation_id'<>'DIRECTOR.MATCH_CONTROL' and input->'payload'<>'{}'::jsonb) then
  raise exception using errcode='42501',message='CERTIFICATION_OPERATION_RECOVERY_AUTHORIZATION_REQUIRED';end if;
 l:=production_control.certification_ingress_lookup_v1(input,false);
 if l.lease_id is null then
  return jsonb_build_object('ok',true,'contract','certification-ingress-v1','state','UNKNOWN','lease_id',null,
   'operation_request_id',input->>'operation_request_id');end if;
 -- The136 reader independently checks terminal/canonical receipt consistency.
 result:=public.read_certification_ingress_status_v1(input);
 result:=result||jsonb_build_object('admission_context',l.admission_context);
 if l.operation_id in('DIRECTOR.REPLACE_CALCUTTA_AUCTION','DIRECTOR.CLEAR_CALCUTTA_AUCTION') then
  if l.predecessor_auction_revision is null then
   raise exception using errcode='55000',message='CERTIFICATION_OPERATION_RECOVERY_PROVENANCE_REQUIRED';end if;
  result:=result||jsonb_build_object('predecessor_projection',production_control.director_calcutta_management_projection_v1(
   l.tournament_id,l.predecessor_auction_revision));
 end if;
 return result;
end;$$;


ALTER FUNCTION public.read_certification_director_recovery_material_v1(input jsonb) OWNER TO postgres;

