--
-- Name: read_production_candidate_completed_history(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_production_candidate_completed_history(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
  mode_value text := upper(btrim(coalesce(input->>'mode', input->>'scope', 'YEARS')));
  target_year integer;
  revision_value uuid;
  result_value jsonb;
begin
  scope := production_control.assert_candidate_read_scope(input);
  if mode_value = 'YEARS' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'tournament_id', revision.tournament_id,
      'tournament_year', revision.tournament_year,
      'revision_id', revision.revision_id,
      'revision_number', revision.revision_number,
      'source_fingerprint', revision.source_fingerprint,
      'payload_fingerprint', revision.payload_fingerprint,
      'import_contract_version', revision.import_contract_version,
      'correction_set_version', revision.correction_set_version,
      'importer_version', revision.importer_version,
      'certified_at', revision.certified_at,
      'canonical_counts', revision.canonical_counts,
      'certification', revision.certification,
      'tournament', jsonb_build_object(
        'name', tournament.name, 'start_date', fact.start_date, 'end_date', fact.end_date,
        'destination', fact.destination, 'lifecycle', fact.lifecycle,
        'score_availability', fact.score_availability,
        'official_team_1_points', fact.official_team_1_points,
        'official_team_2_points', fact.official_team_2_points,
        'total_awarded_points', fact.total_awarded_points,
        'champion_team_side', fact.champion_team_side,
        'champion_team_id', fact.champion_team_id
      )
    ) order by revision.tournament_year), '[]'::jsonb)
    into result_value
    from scoring_authority.completed_history_current_revisions current_pointer
    join scoring_authority.completed_history_revisions revision on revision.revision_id = current_pointer.revision_id
    join scoring_authority.tournaments tournament on tournament.tournament_id = revision.tournament_id
    join scoring_authority.completed_history_tournament_facts fact on fact.revision_id = revision.revision_id
    where revision.project_ref = scope.project_ref and revision.source_workbook_id = scope.google_workbook_id;
  elsif mode_value = 'YEAR' then
    begin target_year := coalesce(input->>'tournament_year', input->>'year')::integer;
    exception when others then return jsonb_build_object('ok', false, 'code', 'HISTORICAL_YEAR_REQUIRED'); end;
    if target_year not between 2017 and 2025 then
      return jsonb_build_object('ok', false, 'code', 'HISTORICAL_YEAR_REQUIRED');
    end if;
    select current_pointer.revision_id into revision_value
    from scoring_authority.completed_history_current_revisions current_pointer
    join scoring_authority.completed_history_revisions revision on revision.revision_id = current_pointer.revision_id
    where current_pointer.tournament_year = target_year
      and revision.project_ref = scope.project_ref and revision.source_workbook_id = scope.google_workbook_id;
    if revision_value is null then return jsonb_build_object('ok', false, 'code', 'HISTORICAL_YEAR_NOT_CERTIFIED'); end if;
    select jsonb_build_object(
      'revision', to_jsonb(revision),
      'tournament', to_jsonb(tournament) || to_jsonb(fact),
      'players', coalesce((
        select jsonb_agg(jsonb_build_object('player_id', player.player_id, 'display_name', player.display_name) order by player.player_id)
        from scoring_authority.completed_history_roster_facts roster
        join scoring_authority.players player on player.player_id = roster.player_id
        where roster.revision_id = revision_value
      ), '[]'::jsonb),
      'teams', coalesce((
        select jsonb_agg(to_jsonb(team_fact) order by team_fact.team_side)
        from scoring_authority.completed_history_team_facts team_fact where team_fact.revision_id = revision_value
      ), '[]'::jsonb),
      'roster', coalesce((
        select jsonb_agg(to_jsonb(roster) order by roster.team_side, roster.display_name, roster.player_id)
        from scoring_authority.completed_history_roster_facts roster where roster.revision_id = revision_value
      ), '[]'::jsonb),
      'rounds', coalesce((
        select jsonb_agg(to_jsonb(round_fact) order by round_fact.round_number)
        from scoring_authority.completed_history_round_facts round_fact where round_fact.revision_id = revision_value
      ), '[]'::jsonb),
      'courses', coalesce((
        select jsonb_agg(jsonb_build_object('course_id', course.course_id,
          'canonical_name', course.canonical_name, 'canonical_location', course.canonical_location) order by course.course_id)
        from (select distinct appearance.course_id from scoring_authority.completed_history_course_appearances appearance
          where appearance.revision_id = revision_value) year_course
        join scoring_authority.completed_history_course_identities course on course.course_id = year_course.course_id
      ), '[]'::jsonb),
      'course_appearances', coalesce((
        select jsonb_agg(to_jsonb(appearance) || jsonb_build_object(
          'canonical_name', course.canonical_name, 'canonical_location', course.canonical_location) order by appearance.round_number)
        from scoring_authority.completed_history_course_appearances appearance
        join scoring_authority.completed_history_course_identities course on course.course_id = appearance.course_id
        where appearance.revision_id = revision_value
      ), '[]'::jsonb),
      'matches', coalesce((
        select jsonb_agg(to_jsonb(match_value) order by match_value.round_number, match_value.match_id)
        from scoring_authority.completed_history_matches match_value where match_value.revision_id = revision_value
      ), '[]'::jsonb),
      'match_participants', coalesce((
        select jsonb_agg(to_jsonb(participant) order by participant.match_id, participant.team_side, participant.player_slot)
        from scoring_authority.completed_history_match_participants participant where participant.revision_id = revision_value
      ), '[]'::jsonb),
      'scorecards', coalesce((
        select jsonb_agg(to_jsonb(scorecard) order by scorecard.match_id, scorecard.scorecard_id)
        from scoring_authority.completed_history_scorecards scorecard where scorecard.revision_id = revision_value
      ), '[]'::jsonb),
      'awards', coalesce((
        select jsonb_agg(to_jsonb(award) order by award.award_type, award.award_id)
        from scoring_authority.completed_history_awards award where award.revision_id = revision_value
      ), '[]'::jsonb),
      'record_eligibility', coalesce((
        select jsonb_agg(to_jsonb(eligibility) order by eligibility.match_id, eligibility.player_id)
        from scoring_authority.completed_history_record_eligibility eligibility where eligibility.revision_id = revision_value
      ), '[]'::jsonb),
      'corrections', coalesce((
        select jsonb_agg(to_jsonb(correction) order by correction.correction_id)
        from scoring_authority.completed_history_correction_applications correction where correction.revision_id = revision_value
      ), '[]'::jsonb)
    ) into result_value
    from scoring_authority.completed_history_revisions revision
    join scoring_authority.tournaments tournament on tournament.tournament_id = revision.tournament_id
    join scoring_authority.completed_history_tournament_facts fact on fact.revision_id = revision.revision_id
    where revision.revision_id = revision_value;
  else
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_CANDIDATE_HISTORY_MODE_NOT_ALLOWED');
  end if;
  return jsonb_build_object('ok', true, 'data', result_value,
    'google_foreground_requests', 0, 'fallback_used', false, 'shadow_only', true);
end;
$$;


ALTER FUNCTION public.read_production_candidate_completed_history(input jsonb) OWNER TO postgres;

--
-- Name: read_production_candidate_current_view(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_production_candidate_current_view(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'participant_identity', 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
  surface text := upper(btrim(coalesce(input->>'surface', '')));
  player_id_value text := btrim(coalesce(input->>'player_id', ''));
  match_id_value text := btrim(coalesce(input->>'match_id', ''));
  engine_keys_value text[];
  current_value jsonb;
  finalized_value jsonb;
begin
  scope := production_control.assert_candidate_read_scope(input);
  if surface in ('TOURNAMENT_LIVE', 'LEADERBOARDS') then
    return public.read_leaderboards_core_view('2026');
  elsif surface = 'HISTORY_2026' then
    -- Reuse the bounded current-state view, but add only the immutable current
    -- finalized snapshots required by the History adapter.  The JavaScript
    -- adapter translates `snapshot` to `scoring_snapshot` and copies the
    -- already-bounded hole definitions; no calculation or mutation occurs.
    current_value := public.read_leaderboards_core_view('2026');
    if not coalesce((current_value->>'ok')::boolean, false) then return current_value; end if;
    select coalesce(jsonb_agg(jsonb_build_object(
      'tournament_id', finalized.tournament_id,
      'match_id', finalized.match_id,
      'snapshot_revision', finalized.snapshot_revision,
      'state', finalized.state,
      'match_revision', finalized.match_revision,
      'scoring_snapshot_id', finalized.scoring_snapshot_id,
      'scoring_snapshot_revision', finalized.scoring_snapshot_revision,
      'source_fingerprint', finalized.source_fingerprint,
      'payload_hash', finalized.payload_hash,
      'payload', finalized.payload,
      'finalized_at', finalized.finalized_at
    ) order by finalized.match_id), '[]'::jsonb)
    into finalized_value
    from scoring_authority.finalized_scorecard_snapshots finalized
    join scoring_authority.matches match_value on match_value.match_id = finalized.match_id
    where finalized.tournament_id = '2026'
      and finalized.state = 'CURRENT'
      and match_value.status = 'FINAL'
      and finalized.match_revision = match_value.match_revision
      and finalized.scoring_snapshot_id = match_value.scoring_snapshot_id;
    return jsonb_set(
      jsonb_set(current_value, '{data,schema_version}', '"production-2026-history-shadow-v1"'::jsonb, true),
      '{data,finalized_snapshots}', finalized_value, true
    );
  elsif surface = 'PARTICIPANT_HOME' then
    if player_id_value = '' then return jsonb_build_object('ok', false, 'code', 'PLAYER_ID_REQUIRED'); end if;
    return public.read_participant_home_view('2026', player_id_value);
  elsif surface = 'MY_MATCH' then
    if player_id_value = '' then return jsonb_build_object('ok', false, 'code', 'PLAYER_ID_REQUIRED'); end if;
    return public.read_my_match_view('2026', player_id_value);
  elsif surface = 'GAME_CENTER' then
    if match_id_value = '' or not exists (
      select 1 from scoring_authority.matches match_value
      where match_value.match_id = match_id_value and match_value.tournament_id = '2026'
    ) then return jsonb_build_object('ok', false, 'code', 'PRODUCTION_MATCH_NOT_FOUND'); end if;
    return public.read_game_center_view(match_id_value);
  elsif surface = 'MATCH_AUTHORIZATION' then
    return public.read_match_authorization_matrix('2026');
  elsif surface = 'NET_SKINS_INPUT' then
    return public.read_net_skins_input_view('2026');
  elsif surface = 'NET_SKINS_RESULT' then
    return public.read_net_skins_result_view('2026');
  elsif surface = 'CALCUTTA_CONFIGURATION' then
    return public.read_calcutta_configuration_view('2026');
  elsif surface = 'PUBLISHED_ODDS' then
    return public.read_published_odds_view('2026', scope.google_workbook_id);
  elsif surface = 'ODDS_INPUT' then
    return public.read_championship_odds_inputs('2026');
  elsif surface = 'PARTICIPANT_IDENTITY' then
    if player_id_value = '' then return jsonb_build_object('ok', false, 'code', 'PLAYER_ID_REQUIRED'); end if;
    return public.read_participant_identity_context('2026', player_id_value);
  elsif surface = 'COMPETITION_DERIVED' then
    if jsonb_typeof(input->'engine_keys') <> 'array' then
      return jsonb_build_object('ok', false, 'code', 'ENGINE_KEYS_REQUIRED');
    end if;
    select array_agg(value) into engine_keys_value
    from jsonb_array_elements_text(input->'engine_keys') value;
    if engine_keys_value is null or cardinality(engine_keys_value) = 0 or exists (
      select 1 from unnest(engine_keys_value) value
      where value not in (
        'TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES', 'CALCUTTA',
        'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL', 'TOURNAMENT_FINAL_RECAP'
      )
    ) then return jsonb_build_object('ok', false, 'code', 'ENGINE_KEYS_INVALID'); end if;
    return public.read_competition_derived_state('2026', engine_keys_value);
  end if;
  return jsonb_build_object('ok', false, 'code', 'PRODUCTION_CANDIDATE_SURFACE_NOT_ALLOWED');
end;
$$;


ALTER FUNCTION public.read_production_candidate_current_view(input jsonb) OWNER TO postgres;

--
-- Name: read_production_completed_history_shadow(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_production_completed_history_shadow(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions', 'pg_temp'
    AS $$
declare
  production_project constant text := 'ymqhhtxaywtqllynrmxe';
  production_workbook constant text := '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4';
  target_year integer;
  target_tournament text;
  mode_value text := upper(btrim(coalesce(input->>'mode', 'YEAR')));
  revision_value scoring_authority.completed_history_revisions%rowtype;
  actual_counts jsonb;
  expected_counts jsonb;
  readback_fingerprint text;
  parity boolean;
begin
  if upper(btrim(coalesce(input->>'environment', ''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref', '')) <> production_project
     or btrim(coalesce(input->>'source_workbook_id', '')) <> production_workbook then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_COMPLETED_HISTORY_SCOPE_REQUIRED');
  end if;

  if mode_value = 'YEARS' then
    return jsonb_build_object(
      'ok', true,
      'mode', mode_value,
      'years', coalesce((
        select jsonb_agg(jsonb_build_object(
          'tournament_id', revision.tournament_id,
          'tournament_year', revision.tournament_year,
          'revision_id', revision.revision_id,
          'revision_number', revision.revision_number,
          'source_fingerprint', revision.source_fingerprint,
          'payload_fingerprint', revision.payload_fingerprint,
          'database_payload_fingerprint', revision.database_payload_fingerprint,
          'canonical_counts', revision.canonical_counts,
          'correction_set_version', revision.correction_set_version,
          'certified_at', revision.certified_at
        ) order by revision.tournament_year)
        from scoring_authority.completed_history_current_revisions current_pointer
        join scoring_authority.completed_history_revisions revision
          on revision.revision_id = current_pointer.revision_id
        where revision.project_ref = production_project
          and revision.source_workbook_id = production_workbook
      ), '[]'::jsonb)
    );
  end if;
  if mode_value <> 'YEAR' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_COMPLETED_HISTORY_READ_MODE');
  end if;
  begin
    target_year := (input->>'tournament_year')::integer;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'HISTORICAL_YEAR_REQUIRED');
  end;
  target_tournament := btrim(coalesce(input->>'tournament_id', target_year::text));
  if target_year not between 2017 and 2025 or target_tournament <> target_year::text
     or not exists (
       select 1 from production_control.tournament_scopes scope
       where scope.tournament_id = target_tournament
         and scope.tournament_year = target_year
         and scope.source_workbook_id = production_workbook
         and scope.scope_kind = 'COMPLETED_HISTORY'
     ) then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_COMPLETED_HISTORY_YEAR_NOT_ALLOWED');
  end if;

  select revision.* into revision_value
  from scoring_authority.completed_history_current_revisions current_pointer
  join scoring_authority.completed_history_revisions revision
    on revision.revision_id = current_pointer.revision_id
  where current_pointer.tournament_id = target_tournament
    and current_pointer.tournament_year = target_year
    and revision.project_ref = production_project
    and revision.source_workbook_id = production_workbook;
  if revision_value.revision_id is null then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_COMPLETED_HISTORY_YEAR_NOT_IMPORTED');
  end if;

  actual_counts := jsonb_build_object(
    'teams', (select count(*) from scoring_authority.completed_history_team_facts where revision_id = revision_value.revision_id),
    'players', (select count(distinct player_id) from scoring_authority.completed_history_roster_facts where revision_id = revision_value.revision_id),
    'roster', (select count(*) from scoring_authority.completed_history_roster_facts where revision_id = revision_value.revision_id),
    'rounds', (select count(*) from scoring_authority.completed_history_round_facts where revision_id = revision_value.revision_id),
    'courses', (select count(distinct course_id) from scoring_authority.completed_history_course_appearances where revision_id = revision_value.revision_id),
    'course_appearances', (select count(*) from scoring_authority.completed_history_course_appearances where revision_id = revision_value.revision_id),
    'matches', (select count(*) from scoring_authority.completed_history_matches where revision_id = revision_value.revision_id),
    'match_participants', (select count(*) from scoring_authority.completed_history_match_participants where revision_id = revision_value.revision_id),
    'scorecards', (select count(*) from scoring_authority.completed_history_scorecards where revision_id = revision_value.revision_id),
    'complete_scorecards', (select count(*) from scoring_authority.completed_history_scorecards where revision_id = revision_value.revision_id and coverage_status = 'COMPLETE'),
    'partial_scorecards', (select count(*) from scoring_authority.completed_history_scorecards where revision_id = revision_value.revision_id and coverage_status = 'PARTIAL'),
    'unavailable_scorecards', (select count(*) from scoring_authority.completed_history_scorecards where revision_id = revision_value.revision_id and coverage_status = 'UNAVAILABLE'),
    'recorded_hole_rows', (select coalesce(sum(recorded_holes), 0) from scoring_authority.completed_history_scorecards where revision_id = revision_value.revision_id),
    'awards', (select count(*) from scoring_authority.completed_history_awards where revision_id = revision_value.revision_id),
    'record_eligibility', (select count(*) from scoring_authority.completed_history_record_eligibility where revision_id = revision_value.revision_id),
    'record_exclusions', (select count(*) from scoring_authority.completed_history_record_eligibility where revision_id = revision_value.revision_id and not is_record_eligible),
    'corrections', (select count(*) from scoring_authority.completed_history_correction_applications where revision_id = revision_value.revision_id)
  );
  expected_counts := revision_value.canonical_counts;
  parity := not exists (
    select 1
    from jsonb_each_text(expected_counts) expected
    where actual_counts ? expected.key
      and actual_counts->>expected.key <> expected.value
  );
  readback_fingerprint := encode(extensions.digest(jsonb_build_object(
    'revision_id', revision_value.revision_id,
    'source_fingerprint', revision_value.source_fingerprint,
    'payload_fingerprint', revision_value.payload_fingerprint,
    'actual_counts', actual_counts
  )::text, 'sha256'), 'hex');
  return jsonb_build_object(
    'ok', true,
    'mode', mode_value,
    'tournament_id', target_tournament,
    'tournament_year', target_year,
    'revision', to_jsonb(revision_value),
    'expected_counts', expected_counts,
    'actual_counts', actual_counts,
    'parity', parity,
    'readback_fingerprint', readback_fingerprint,
    'import_run', (
      select to_jsonb(run)
      from production_control.import_runs run
      where run.domain = 'COMPLETED_HISTORY'
        and run.tournament_id = target_tournament
        and run.tournament_year = target_year
        and run.status = 'SUCCEEDED'
      order by run.completed_at desc
      limit 1
    )
  );
end;
$$;


ALTER FUNCTION public.read_production_completed_history_shadow(input jsonb) OWNER TO postgres;

--
-- Name: read_production_current_shadow_v2_revision(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_production_current_shadow_v2_revision(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
  revision production_control.current_shadow_revisions%rowtype;
begin
  scope := production_control.assert_current_shadow_v2_dormant();
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_SERVICE_ROLE_REQUIRED';
  end if;
  if upper(btrim(coalesce(input->>'environment',''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref','')) <> scope.project_ref
     or btrim(coalesce(input->>'project_url','')) <> scope.project_url
     or btrim(coalesce(input->>'source_workbook_id','')) <> scope.google_workbook_id
     or btrim(coalesce(input->>'tournament_id','')) <> '2026' then
    raise exception using errcode = '42501', message = 'PRODUCTION_CURRENT_SHADOW_V2_SCOPE_REQUIRED';
  end if;
  select value.* into revision
  from production_control.current_shadow_revisions value
  where value.tournament_id='2026'
  order by value.imported_at desc limit 1;
  if revision.import_run_id is null then
    return jsonb_build_object('ok',false,'code','PRODUCTION_CURRENT_SHADOW_NOT_IMPORTED');
  end if;
  return jsonb_build_object('ok',true,'revision',to_jsonb(revision)-'source_payload',
    'source_sheet_count',jsonb_array_length(revision.source_payload->'sheets'),
    'authority','GOOGLE','scoring_ingress','DISABLED','google_write',false);
end;
$$;


ALTER FUNCTION public.read_production_current_shadow_v2_revision(input jsonb) OWNER TO postgres;

--
-- Name: read_production_current_tournament_runtime_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_production_current_tournament_runtime_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  scope production_control.resource_scope%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  catalog production_control.future_tournament_catalog_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
begin
  begin
    perform production_control.assert_production_service_role();
  exception when others then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CURRENT_TOURNAMENT_SERVICE_ROLE_REQUIRED';
  end;
  if input->>'contract_version'
       is distinct from 'production-current-tournament-runtime-v1'
     or input->>'environment' is distinct from 'PRODUCTION' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CURRENT_TOURNAMENT_SCOPE_REQUIRED';
  end if;
  select value.* into strict scope from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if input->>'project_ref' is distinct from scope.project_ref
     or input->>'project_url' is distinct from scope.project_url
     or input->>'source_workbook_id' is distinct from scope.google_workbook_id then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CURRENT_TOURNAMENT_EXACT_RESOURCE_REQUIRED';
  end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict catalog
  from production_control.future_tournament_catalog_v1 value
  where value.tournament_id = pointer.tournament_id;
  if catalog.lifecycle <> 'ACTIVE'
     or catalog.lifecycle_revision <> pointer.lifecycle_revision then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CURRENT_TOURNAMENT_POINTER_NOT_ACTIVE';
  end if;
  select value.* into generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = pointer.tournament_id
    and value.generation_status = 'ACTIVE';
  -- The represented 2026 pointer predates annual generations.  It remains
  -- valid under the frozen Step-12 authority contracts.  Every later pointer
  -- must have an active annual runtime generation.
  if pointer.tournament_id <> '2026'
     and generation.runtime_generation_id is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_CURRENT_TOURNAMENT_RUNTIME_GENERATION_REQUIRED';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'contractVersion', 'production-current-tournament-runtime-v1',
    'tournamentId', pointer.tournament_id,
    'tournamentYear', pointer.tournament_year,
    'lifecycle', catalog.lifecycle,
    'pointerRevision', pointer.pointer_revision,
    'lifecycleRevision', catalog.lifecycle_revision,
    'runtimeGenerationId', generation.runtime_generation_id,
    'runtimeRevision', generation.runtime_revision,
    'authorityGenerationId', generation.authority_generation_id,
    'admissionGenerationId', generation.admission_generation_id,
    'status', case when pointer.tournament_id = '2026'
      then 'FROZEN_2026_RUNTIME' else generation.generation_status end
  );
end;
$$;


ALTER FUNCTION public.read_production_current_tournament_runtime_v1(input jsonb) OWNER TO postgres;

--
-- Name: read_production_current_tournament_shadow(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_production_current_tournament_shadow(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions', 'pg_temp'
    AS $_$
declare
  production_project constant text := 'ymqhhtxaywtqllynrmxe';
  production_url constant text :=
    'https://ymqhhtxaywtqllynrmxe.supabase.co';
  production_workbook constant text :=
    '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4';
  target_tournament constant text := '2026';
  semantic_contract constant text :=
    'production-current-shadow-semantic-parity-v1';
  mode_value text := upper(btrim(coalesce(input->>'mode', 'DIAGNOSTICS')));
  provided_semantic_fingerprint text := pg_catalog.lower(
    pg_catalog.btrim(coalesce(input->>'semantic_payload_fingerprint', ''))
  );
  provided_semantic_canonical_json text :=
    coalesce(input->>'semantic_payload_canonical_json', '');
  provided_semantic_projection jsonb;
  legacy_projection jsonb;
  semantic_projection_value jsonb;
  latest_run production_control.import_runs%rowtype;
  baseline production_control.current_shadow_semantic_baselines%rowtype;
  counts_value jsonb;
  actual_counts jsonb;
  actual_section_fingerprints jsonb;
  semantic_difference_sections jsonb;
  google_supabase_difference_sections jsonb;
  legacy_fingerprint text;
  semantic_fingerprint_value text;
  semantic_payload_parity boolean;
  semantic_database_parity boolean;
  parity boolean;
begin
  if upper(btrim(coalesce(input->>'environment', ''))) <> 'PRODUCTION'
     or btrim(coalesce(input->>'project_ref', '')) <> production_project
     or btrim(coalesce(input->>'project_url', production_url)) <>
       production_url
     or btrim(coalesce(input->>'source_workbook_id', '')) <>
       production_workbook
     or btrim(coalesce(input->>'tournament_id', '')) <> target_tournament
     or btrim(coalesce(input->>'tournament_year', '')) <> '2026'
     or not exists (
       select 1 from production_control.resource_scope resource
       where resource.scope_key = 'BAGGER_INV_PRODUCTION'
         and resource.project_ref = production_project
         and resource.project_url = production_url
         and resource.google_workbook_id = production_workbook
         and resource.current_tournament_read_authority = 'GOOGLE'
         and resource.scoring_authority = 'GOOGLE'
         and resource.participant_identity_authority = 'PASSPORT'
         and not resource.public_supabase_reads_enabled
         and not resource.scoring_ingress_enabled
         and not resource.google_writes_enabled
         and not resource.auth_user_creation_enabled
         and not resource.odds_publication_enabled
         and not resource.workers_enabled
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'PRODUCTION_CURRENT_SHADOW_SCOPE_REQUIRED'
    );
  end if;
  if mode_value not in ('DIAGNOSTICS', 'CURRENT_STATE') then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'INVALID_CURRENT_SHADOW_READ_MODE'
    );
  end if;
  if input->>'semantic_parity_contract' is distinct from semantic_contract
     or provided_semantic_fingerprint !~ '^[0-9a-f]{64}$'
     or provided_semantic_canonical_json = ''
     or pg_catalog.encode(extensions.digest(
       provided_semantic_canonical_json,
       'sha256'
     ), 'hex') <> provided_semantic_fingerprint then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'PRODUCTION_CURRENT_SHADOW_SEMANTIC_FINGERPRINT_REQUIRED',
      'semantic_parity_contract', semantic_contract
    );
  end if;
  begin
    provided_semantic_projection := provided_semantic_canonical_json::jsonb;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'PRODUCTION_CURRENT_SHADOW_SEMANTIC_FINGERPRINT_REQUIRED',
      'semantic_parity_contract', semantic_contract
    );
  end;
  if pg_catalog.jsonb_typeof(provided_semantic_projection) <> 'object'
     or provided_semantic_projection->>'contract_version' is distinct from
       semantic_contract then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'PRODUCTION_CURRENT_SHADOW_SEMANTIC_FINGERPRINT_REQUIRED',
      'semantic_parity_contract', semantic_contract
    );
  end if;

  select run.* into latest_run
  from production_control.import_runs run
  where run.domain = 'CURRENT_SCORING_SHADOW'
    and run.tournament_id = target_tournament
    and run.tournament_year = 2026
    and run.source_workbook_id = production_workbook
    and run.status = 'SUCCEEDED'
  order by run.completed_at desc
  limit 1;
  if latest_run.import_run_id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'PRODUCTION_CURRENT_SHADOW_NOT_IMPORTED'
    );
  end if;

  select value.* into baseline
  from production_control.current_shadow_semantic_baselines value
  where value.import_run_id = latest_run.import_run_id
    and value.contract_version = semantic_contract;
  if baseline.baseline_id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'PRODUCTION_CURRENT_SHADOW_SEMANTIC_BASELINE_REQUIRED'
    );
  end if;

  legacy_projection :=
    production_control.current_tournament_shadow_projection(
      target_tournament
    );
  legacy_fingerprint := pg_catalog.encode(
    extensions.digest(legacy_projection::text, 'sha256'), 'hex'
  );
  semantic_projection_value :=
    production_control.current_tournament_shadow_semantic_projection_v1(
      target_tournament
    );
  semantic_fingerprint_value := pg_catalog.encode(
    extensions.digest(semantic_projection_value::text, 'sha256'), 'hex'
  );
  select pg_catalog.jsonb_object_agg(
    entry.key,
    pg_catalog.encode(extensions.digest(entry.value::text, 'sha256'), 'hex')
    order by entry.key
  ) into actual_section_fingerprints
  from pg_catalog.jsonb_each(semantic_projection_value) entry;
  select coalesce(pg_catalog.jsonb_agg(value.key order by value.key), '[]'::jsonb)
  into semantic_difference_sections
  from (
    select key
    from pg_catalog.jsonb_object_keys(
      baseline.section_fingerprints || actual_section_fingerprints
    ) as keys(key)
    where baseline.section_fingerprints->>key is distinct from
      actual_section_fingerprints->>key
  ) value;
  select coalesce(pg_catalog.jsonb_agg(value.key order by value.key), '[]'::jsonb)
  into google_supabase_difference_sections
  from (
    select key
    from pg_catalog.jsonb_object_keys(
      provided_semantic_projection || semantic_projection_value
    ) as keys(key)
    where provided_semantic_projection->key is distinct from
      semantic_projection_value->key
  ) value;

  counts_value := latest_run.counts;
  actual_counts := pg_catalog.jsonb_build_object(
    'players', (
      select pg_catalog.count(*) from scoring_authority.players
    ),
    'tournament_players', (
      select pg_catalog.count(*)
      from scoring_authority.tournament_players
      where tournament_id = target_tournament
    ),
    'teams', (
      select pg_catalog.count(*) from scoring_authority.teams
      where tournament_id = target_tournament
    ),
    'rounds', (
      select pg_catalog.count(*) from scoring_authority.rounds
      where tournament_id = target_tournament
    ),
    'snapshots', (
      select pg_catalog.count(*) from scoring_authority.scoring_snapshots
      where tournament_id = target_tournament
    ),
    'matches', (
      select pg_catalog.count(*) from scoring_authority.matches
      where tournament_id = target_tournament
    ),
    'match_participants', (
      select pg_catalog.count(*)
      from scoring_authority.match_participants participant
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ),
    'permissions', (
      select pg_catalog.count(*)
      from scoring_authority.scoring_permissions permission
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ),
    'match_holes', (
      select pg_catalog.count(*)
      from scoring_authority.match_holes hole
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ),
    'hole_scores', (
      select pg_catalog.count(*)
      from scoring_authority.hole_scores score
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    ),
    'checkpoints', (
      select pg_catalog.count(*)
      from scoring_authority.google_match_checkpoints checkpoint
      join scoring_authority.matches match_value using (match_id)
      where match_value.tournament_id = target_tournament
    )
  );
  semantic_payload_parity :=
    baseline.expected_payload_semantic_fingerprint =
      provided_semantic_fingerprint
    and provided_semantic_projection = semantic_projection_value
    and google_supabase_difference_sections = '[]'::jsonb;
  semantic_database_parity := baseline.semantic_database_fingerprint =
      semantic_fingerprint_value
    and baseline.semantic_projection = semantic_projection_value
    and semantic_difference_sections = '[]'::jsonb
    and not exists (
      select 1 from pg_catalog.jsonb_each_text(actual_counts) actual
      where counts_value ? actual.key
        and counts_value->>actual.key <> actual.value
    );
  parity := semantic_payload_parity and semantic_database_parity;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'mode', mode_value,
    'tournament_id', target_tournament,
    'tournament_year', 2026,
    'source_fingerprint', latest_run.source_fingerprint,
    'payload_fingerprint_contract', semantic_contract,
    'payload_fingerprint', provided_semantic_fingerprint,
    'expected_payload_fingerprint',
      baseline.expected_payload_semantic_fingerprint,
    'actual_payload_fingerprint', provided_semantic_fingerprint,
    'semantic_parity_contract', semantic_contract,
    'expected_semantic_payload_fingerprint',
      baseline.expected_payload_semantic_fingerprint,
    'provided_semantic_payload_fingerprint',
      provided_semantic_fingerprint,
    'semantic_payload_parity', semantic_payload_parity,
    'google_supabase_difference_sections',
      google_supabase_difference_sections,
    'database_fingerprint_contract', semantic_contract,
    'expected_database_fingerprint',
      baseline.semantic_database_fingerprint,
    'actual_database_fingerprint', semantic_fingerprint_value,
    'semantic_expected_database_fingerprint',
      baseline.semantic_database_fingerprint,
    'semantic_actual_database_fingerprint', semantic_fingerprint_value,
    'semantic_difference_sections', semantic_difference_sections,
    'semantic_database_parity', semantic_database_parity,
    'legacy_payload_fingerprint', latest_run.payload_fingerprint,
    'legacy_expected_database_fingerprint',
      latest_run.database_fingerprint,
    'legacy_actual_database_fingerprint', legacy_fingerprint,
    'legacy_parity', latest_run.database_fingerprint = legacy_fingerprint,
    'expected_counts', counts_value,
    'actual_counts', actual_counts,
    'parity', parity,
    'semantic_parity', parity,
    'authority', 'GOOGLE',
    'ingress', (
      select to_jsonb(gate) from scoring_authority.ingress_gates gate
      where gate.tournament_id = target_tournament
    ),
    'outbox_count', (
      select pg_catalog.count(*)
      from scoring_authority.google_outbox_events
      where tournament_id = target_tournament
    ),
    'worker_controls_enabled', (
      select pg_catalog.count(*)
      from production_control.worker_controls
      where enabled or scheduler_installed or google_writes_allowed
    ),
    'import_run', to_jsonb(latest_run),
    'data', case when mode_value = 'CURRENT_STATE'
      then legacy_projection else null end,
    'semantic_data', case when mode_value = 'CURRENT_STATE'
      then semantic_projection_value else null end
  );
end;
$_$;


ALTER FUNCTION public.read_production_current_tournament_shadow(input jsonb) OWNER TO postgres;

