--
-- Name: rebind_production_maintenance_precommit_deployment(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rebind_production_maintenance_precommit_deployment(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  head production_control.postcutover_normal_release_head%rowtype;
  predecessor
    production_control.postcutover_normal_release_rebindings%rowtype;
  intent production_control.postcutover_normal_release_intents%rowtype;
  replay production_control.postcutover_normal_release_rebindings%rowtype;
  normalized jsonb;
begin
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into head
  from production_control.postcutover_normal_release_head value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';

  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or activation.read_cutover_phase <> 'OBSERVATION'
     or head.release_rebind_id is null
  then
    return public
      .rebind_production_maintenance_precommit_deployment_pre_normal_release(
        input
      );
  end if;

  select value.* into replay
  from production_control.postcutover_normal_release_rebindings value
  where value.release_kind = 'NORMAL'
    and value.request_fingerprint = pg_catalog.lower(
      input->>'request_fingerprint'
    );
  if found then
    normalized := input || pg_catalog.jsonb_build_object(
      'operation', 'REBIND_PRODUCTION_POSTCUTOVER_NORMAL_RELEASE',
      'contract_version',
        'production-postcutover-normal-release-rebind-v1',
      'expected_predecessor_deployment_id',
        replay.predecessor_deployment_id,
      'expected_predecessor_deployment_commit',
        replay.predecessor_deployment_commit,
      'expected_release_sequence', replay.release_sequence
    );
    return production_control.rebind_production_postcutover_normal_release(
      normalized
    );
  end if;

  select value.* into intent
  from production_control.postcutover_normal_release_intents value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
    and value.status = 'PENDING';
  if found then
    normalized := input || pg_catalog.jsonb_build_object(
      'operation', 'REBIND_PRODUCTION_POSTCUTOVER_NORMAL_RELEASE',
      'contract_version',
        'production-postcutover-normal-release-rebind-v1',
      'expected_predecessor_deployment_id',
        input->>'original_deployment_id',
      'expected_predecessor_deployment_commit',
        intent.predecessor_deployment_commit,
      'expected_release_sequence', intent.release_sequence
    );
    return production_control.rebind_production_postcutover_normal_release(
      normalized
    );
  end if;

  select value.* into strict predecessor
  from production_control.postcutover_normal_release_rebindings value
  where value.release_rebind_id = head.release_rebind_id;
  if predecessor.release_kind = 'BASELINE_053'
     and input->>'deployment_id' is not distinct from head.deployment_id
     and input->>'deployment_commit' is not distinct from
       head.deployment_commit
  then
    return public
      .rebind_production_maintenance_precommit_deployment_pre_normal_release(
        input
      );
  end if;

  raise exception using errcode = '55000',
    message = 'PRODUCTION_POSTCUTOVER_NORMAL_RELEASE_INTENT_REQUIRED';
end;
$$;


ALTER FUNCTION public.rebind_production_maintenance_precommit_deployment(input jsonb) OWNER TO postgres;

--
-- Name: rebind_production_maintenance_precommit_deployment_pre_applicat(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rebind_production_maintenance_precommit_deployment_pre_applicat(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  prior production_control.maintenance_deployment_capability_bindings%rowtype;
  created production_control.maintenance_deployment_capability_bindings%rowtype;
  odds_config scoring_authority.odds_input_configurations%rowtype;
  capability_manifest jsonb;
  capability_fingerprint text;
  runtime_observed_at timestamptz;
  legacy_input jsonb;
  legacy_response jsonb;
  response_value jsonb;
  intent_input jsonb := input - 'runtime_observed_at';
begin
  perform production_control.assert_maintenance_common_input(input);
  perform production_control.assert_no_active_physical_writer_fence();
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  if input->>'operation' is distinct from
       'REBIND_PRODUCTION_MAINTENANCE_PRECOMMIT_DEPLOYMENT'
     or input->>'runtime_binding_contract' is distinct from
       'production-maintenance-precommit-deployment-rebind-v2'
     or input->>'runtime_deployment_capability_contract' is distinct from
       'production-maintenance-single-deployment-capability-v1'
     or input->>'runtime_deployment_capability_ceiling' is distinct from
       'OBSERVATION'
     or input->>'runtime_cutover_phase' is distinct from 'SCORING_COMMIT'
     or input->>'runtime_deployment_status' is distinct from 'READY'
     or input->>'runtime_readiness_evidence' is distinct from
       'LIVE_CANONICAL_PRODUCTION_ROUTE'
     or input->>'runtime_deployment_target' is distinct from 'PRODUCTION'
     or input->>'runtime_environment' is distinct from 'production'
     or input->>'runtime_vercel_project' is distinct from 'bagger-inv'
     or input->>'runtime_vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'runtime_vercel_team_id' is distinct from
       'team_kPw5zaib8uaQJALAwj4fWI6R'
     or input->>'runtime_canonical_hostname' is distinct from 'baggerinv.com'
     or input->>'runtime_scoring_authority' is distinct from 'SUPABASE'
     or input->>'runtime_participant_identity_authority' is distinct from
       'SUPABASE'
     or input->'runtime_activation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_foundation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_public_supabase_reads_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_google_ingress_lease_gate_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_supabase_scoring_ingress_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_workers_enabled' is distinct from 'true'::jsonb
     or input->'runtime_google_mirror_enabled' is distinct from 'true'::jsonb
     or input->'runtime_scorecard_archive_enabled' is distinct from
       'true'::jsonb
     or input->'runtime_outbox_worker_secret_configured' is distinct from
       'true'::jsonb
     or input->'runtime_archive_worker_secret_configured' is distinct from
       'true'::jsonb
     or input->'runtime_odds_calculation_enabled' is distinct from
       'true'::jsonb
     or input->>'runtime_war_room_input_source' is distinct from 'SUPABASE'
     or input->>'runtime_prediction_settings_read_source' is distinct from
       'SUPABASE'
     or input->>'runtime_odds_calculation_input_source' is distinct from
       'SUPABASE'
     or coalesce(input->>'runtime_prediction_settings_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(
       input->>'runtime_prediction_settings_effective_fingerprint', ''
     ) !~ '^[0-9a-f]{64}$'
     or input->>'runtime_odds_publication_authority' is distinct from 'GOOGLE'
     or input->'runtime_supabase_odds_publication_enabled' is distinct from
       'false'::jsonb
     or input->'runtime_supabase_odds_google_mirror_enabled' is distinct from
       'false'::jsonb
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_CAPABILITY_ATTESTATION_INVALID';
  end if;

  select value.* into strict odds_config
  from scoring_authority.odds_input_configurations value
  where value.tournament_id = '2026' and value.is_current;
  if odds_config.validation_status <> 'VALID'
     or pg_catalog.lower(
       input->>'runtime_prediction_settings_source_fingerprint'
     ) is distinct from pg_catalog.lower(odds_config.source_fingerprint)
     or pg_catalog.lower(
       input->>'runtime_prediction_settings_effective_fingerprint'
     ) is distinct from pg_catalog.lower(
       odds_config.effective_settings_fingerprint
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_PREDICTION_SETTINGS_BINDING_REQUIRED';
  end if;

  capability_manifest := pg_catalog.jsonb_build_object(
    'domain', 'BAGGER_MAINTENANCE_SINGLE_DEPLOYMENT_CAPABILITY_V1',
    'contract_version',
      'production-maintenance-single-deployment-capability-v1',
    'capability_ceiling', 'OBSERVATION',
    'base_cutover_phase', 'SCORING_COMMIT',
    'release_sha', pg_catalog.lower(input->>'deployment_commit'),
    'deployment_id', input->>'deployment_id',
    'deployment_hostname', input->>'runtime_deployment_hostname',
    'deployment_status', 'READY',
    'deployment_target', 'PRODUCTION',
    'runtime_environment', 'production',
    'vercel_project', 'bagger-inv',
    'vercel_project_id', 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'vercel_team_id', 'team_kPw5zaib8uaQJALAwj4fWI6R',
    'supabase_project_ref', 'ymqhhtxaywtqllynrmxe',
    'google_workbook_id',
      '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4',
    'tournament_id', '2026',
    'prepared_authority_epoch', pg_catalog.lower(input->>'epoch_id'),
    'authority_generation',
      pg_catalog.lower(input->>'expected_authority_generation'),
    'admission_generation',
      pg_catalog.lower(input->>'expected_admission_generation'),
    'expected_activation_revision',
      (input->>'expected_activation_revision')::bigint,
    'expected_admission_revision',
      (input->>'expected_admission_revision')::bigint,
    'scoring_authority', 'SUPABASE',
    'participant_identity_authority', 'SUPABASE',
    'public_supabase_reads_enabled', true,
    'supabase_scoring_ingress_capability', true,
    'workers_capability', true,
    'scoring_google_mirror_capability', true,
    'round_scorecards_archive_capability', true,
    'outbox_worker_secret_configured', true,
    'archive_worker_secret_configured', true,
    'odds_calculation_capability', true,
    'war_room_input_source', 'SUPABASE',
    'prediction_settings_read_source', 'SUPABASE',
    'odds_calculation_input_source', 'SUPABASE',
    'prediction_settings_source_fingerprint', pg_catalog.lower(
      input->>'runtime_prediction_settings_source_fingerprint'
    ),
    'prediction_settings_effective_fingerprint', pg_catalog.lower(
      input->>'runtime_prediction_settings_effective_fingerprint'
    ),
    'odds_publication_authority', 'GOOGLE',
    'supabase_odds_publication_enabled', false,
    'supabase_odds_google_mirror_enabled', false,
    'database_phase_authoritative', true,
    'database_worker_controls_authoritative', true,
    'database_odds_runtime_authoritative', true,
    'postcommit_redeployment_allowed', false
  );
  capability_fingerprint := pg_catalog.encode(
    extensions.digest(capability_manifest::text, 'sha256'), 'hex'
  );

  select value.* into prior
  from production_control.maintenance_deployment_capability_bindings value
  where value.epoch_id = (input->>'epoch_id')::uuid;
  if found then
    if prior.deployment_id is distinct from input->>'deployment_id'
       or prior.deployment_commit is distinct from
         pg_catalog.lower(input->>'deployment_commit')
       or prior.capability_manifest is distinct from capability_manifest
       or prior.capability_fingerprint is distinct from capability_fingerprint
       or prior.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or prior.payload_hash is distinct from
         production_control.cutover_payload_hash(intent_input)
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_CAPABILITY_ALREADY_BOUND';
    end if;
    return prior.response_value || pg_catalog.jsonb_build_object(
      'idempotent', true
    );
  end if;

  runtime_observed_at := (input->>'runtime_observed_at')::timestamptz;
  if runtime_observed_at is null
     or runtime_observed_at > pg_catalog.now()
     or runtime_observed_at < pg_catalog.now() - interval '5 minutes'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_PRECOMMIT_RUNTIME_NOT_CURRENT';
  end if;

  legacy_input := input || pg_catalog.jsonb_build_object(
    'runtime_binding_contract',
      'production-maintenance-precommit-deployment-rebind-v1',
    'runtime_workers_enabled', false,
    'runtime_google_mirror_enabled', false,
    'runtime_scorecard_archive_enabled', false
  );
  legacy_response :=
    public.rebind_production_maintenance_precommit_deployment_v1(legacy_input);
  response_value := legacy_response || pg_catalog.jsonb_build_object(
    'runtime_binding_contract',
      'production-maintenance-precommit-deployment-rebind-v2',
    'deployment_capability_contract',
      'production-maintenance-single-deployment-capability-v1',
    'deployment_capability_ceiling', 'OBSERVATION',
    'capability_fingerprint', capability_fingerprint,
    'capabilities_dormant', true,
    'workers_enabled', false,
    'odds_runtime_enabled', false,
    'idempotent', false
  );

  insert into production_control.maintenance_deployment_capability_bindings (
    rebind_id, boundary_mode, contract_version, capability_ceiling,
    tournament_id, epoch_id, deployment_id, deployment_commit,
    capability_manifest, capability_fingerprint, runtime_observed_at,
    request_fingerprint, payload_hash, actor_id, response_value
  ) values (
    (legacy_response->>'rebind_id')::uuid,
    'MAINTENANCE_WINDOW_V1',
    'production-maintenance-single-deployment-capability-v1',
    'OBSERVATION', '2026', (input->>'epoch_id')::uuid,
    input->>'deployment_id', pg_catalog.lower(input->>'deployment_commit'),
    capability_manifest, capability_fingerprint, runtime_observed_at,
    pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(intent_input),
    pg_catalog.left(input->>'actor_id', 160), response_value
  ) returning * into created;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_MAINTENANCE_SINGLE_DEPLOYMENT_CAPABILITY_BOUND',
    'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.rebind_production_maintenance_precommit_deployment_pre_applicat(input jsonb) OWNER TO postgres;

--
-- Name: rebind_production_maintenance_precommit_deployment_pre_normal_r(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rebind_production_maintenance_precommit_deployment_pre_normal_r(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
begin
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if activation.boundary_mode = 'MAINTENANCE_WINDOW_V1'
     and activation.state = 'SCORING_COMMITTED'
     and activation.current_authority = 'SUPABASE'
     and activation.read_cutover_phase = 'OBSERVATION'
  then
    return production_control
      .rebind_production_postcutover_application_release(input);
  end if;
  return public
    .rebind_production_maintenance_precommit_deployment_pre_application_release(
      input
    );
end;
$$;


ALTER FUNCTION public.rebind_production_maintenance_precommit_deployment_pre_normal_r(input jsonb) OWNER TO postgres;

--
-- Name: rebind_production_maintenance_precommit_deployment_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rebind_production_maintenance_precommit_deployment_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  binding production_control.maintenance_release_candidates%rowtype;
  prior_rebind
    production_control.maintenance_runtime_deployment_rebindings%rowtype;
  rebind
    production_control.maintenance_runtime_deployment_rebindings%rowtype;
  runtime_observed_at timestamptz;
  intent_input jsonb := input - 'runtime_observed_at';
  runtime_manifest jsonb;
  runtime_fingerprint text;
  next_activation_revision bigint;
  next_admission_revision bigint;
  response_value jsonb;
begin
  perform production_control.assert_maintenance_common_input(input);
  perform production_control.assert_no_active_physical_writer_fence();
  if input->>'operation' is distinct from
       'REBIND_PRODUCTION_MAINTENANCE_PRECOMMIT_DEPLOYMENT'
     or coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or coalesce(input->>'closure_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or coalesce(input->>'original_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or input->>'deployment_id' = input->>'original_deployment_id'
     or input->>'runtime_binding_contract' is distinct from
       'production-maintenance-precommit-deployment-rebind-v1'
     or input->>'runtime_deployment_status' is distinct from 'READY'
     or input->>'runtime_readiness_evidence' is distinct from
       'LIVE_CANONICAL_PRODUCTION_ROUTE'
     or input->>'runtime_deployment_target' is distinct from 'PRODUCTION'
     or input->>'runtime_environment' is distinct from 'production'
     or input->>'runtime_vercel_project' is distinct from 'bagger-inv'
     or input->>'runtime_vercel_project_id' is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or input->>'runtime_vercel_team_id' is distinct from
       'team_kPw5zaib8uaQJALAwj4fWI6R'
     or input->>'runtime_canonical_hostname' is distinct from 'baggerinv.com'
     or coalesce(input->>'runtime_deployment_hostname', '')
       !~ '^[a-z0-9-]+\.vercel\.app$'
     or input->>'runtime_cutover_phase' is distinct from 'SCORING_COMMIT'
     or input->>'runtime_scoring_authority' is distinct from 'SUPABASE'
     or input->>'runtime_participant_identity_authority' is distinct from
       'SUPABASE'
     or input->'runtime_activation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_foundation_enabled' is distinct from 'true'::jsonb
     or input->'runtime_google_ingress_lease_gate_enabled'
       is distinct from 'true'::jsonb
     or input->'runtime_supabase_scoring_ingress_enabled'
       is distinct from 'true'::jsonb
     or input->'runtime_workers_enabled' is distinct from 'false'::jsonb
     or input->'runtime_google_mirror_enabled' is distinct from 'false'::jsonb
     or input->'runtime_scorecard_archive_enabled'
       is distinct from 'false'::jsonb
     or pg_catalog.lower(coalesce(
       input->>'runtime_deployment_commit', ''
     )) is distinct from input->>'deployment_commit'
     or pg_catalog.lower(coalesce(
       input->>'runtime_expected_authority_epoch', ''
     )) is distinct from pg_catalog.lower(input->>'epoch_id')
     or pg_catalog.lower(coalesce(
       input->>'runtime_expected_admission_generation', ''
     )) is distinct from pg_catalog.lower(
       input->>'expected_admission_generation'
     )
     or coalesce(input->>'staged_environment_delta_fingerprint_v2', '')
       !~ '^[0-9a-f]{64}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_PRECOMMIT_REBIND_INPUT_INVALID';
  end if;
  existing := production_control.lookup_cutover_receipt(
    'REBIND_MAINTENANCE_PRECOMMIT_DEPLOYMENT', intent_input
  );
  if existing is not null then
    return existing || pg_catalog.jsonb_build_object('idempotent', true);
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_cutover_receipt(
    'REBIND_MAINTENANCE_PRECOMMIT_DEPLOYMENT', intent_input
  );
  if existing is not null then
    return existing || pg_catalog.jsonb_build_object('idempotent', true);
  end if;
  runtime_observed_at :=
    (input->>'runtime_observed_at')::timestamptz;
  if runtime_observed_at is null
     or runtime_observed_at > pg_catalog.now()
     or runtime_observed_at < pg_catalog.now() - interval '5 minutes'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_PRECOMMIT_RUNTIME_NOT_CURRENT';
  end if;

  runtime_manifest := pg_catalog.jsonb_build_object(
    'domain', 'BAGGER_MAINTENANCE_PRECOMMIT_DEPLOYMENT_REBIND_V1',
    'contract_version',
      'production-maintenance-precommit-deployment-rebind-v1',
    'release_sha', pg_catalog.lower(input->>'deployment_commit'),
    'original_deployment_id', input->>'original_deployment_id',
    'replacement_deployment_id', input->>'deployment_id',
    'replacement_deployment_status', 'READY',
    'readiness_evidence', 'LIVE_CANONICAL_PRODUCTION_ROUTE',
    'deployment_target', 'PRODUCTION',
    'runtime_environment', 'production',
    'deployment_hostname', input->>'runtime_deployment_hostname',
    'canonical_hostname', 'baggerinv.com',
    'vercel_project', 'bagger-inv',
    'vercel_project_id', 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    'vercel_team_id', 'team_kPw5zaib8uaQJALAwj4fWI6R',
    'supabase_project_ref', 'ymqhhtxaywtqllynrmxe',
    'supabase_project_url', 'https://ymqhhtxaywtqllynrmxe.supabase.co',
    'google_workbook_id',
      '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4',
    'tournament_id', '2026',
    'cutover_phase', 'SCORING_COMMIT',
    'scoring_authority', 'SUPABASE',
    'participant_identity_authority', 'SUPABASE',
    'prepared_authority_epoch', pg_catalog.lower(input->>'epoch_id'),
    'current_google_authority_generation',
      pg_catalog.lower(input->>'expected_authority_generation'),
    'admission_generation',
      pg_catalog.lower(input->>'expected_admission_generation'),
    'expected_activation_revision',
      (input->>'expected_activation_revision')::bigint,
    'expected_admission_revision',
      (input->>'expected_admission_revision')::bigint,
    'activation_enabled', true,
    'foundation_enabled', true,
    'google_ingress_lease_gate_enabled', true,
    'supabase_scoring_ingress_enabled', true,
    'workers_enabled', false,
    'google_mirror_enabled', false,
    'scorecard_archive_enabled', false,
    'staged_environment_delta_fingerprint_v2',
      pg_catalog.lower(input->>'staged_environment_delta_fingerprint_v2')
  );
  runtime_fingerprint := pg_catalog.encode(
    extensions.digest(runtime_manifest::text, 'sha256'), 'hex'
  );

  select value.* into prior_rebind
  from production_control.maintenance_runtime_deployment_rebindings value
  where value.epoch_id = (input->>'epoch_id')::uuid
  for update;
  if found then
    if prior_rebind.prior_deployment_id is distinct from
         input->>'original_deployment_id'
       or prior_rebind.rebound_deployment_id is distinct from
         input->>'deployment_id'
       or prior_rebind.deployment_commit is distinct from
         input->>'deployment_commit'
       or prior_rebind.activation_revision_before is distinct from
         (input->>'expected_activation_revision')::bigint
       or prior_rebind.admission_revision_before is distinct from
         (input->>'expected_admission_revision')::bigint
       or prior_rebind.authority_generation_id is distinct from
         (input->>'expected_authority_generation')::uuid
       or prior_rebind.admission_generation_id is distinct from
         (input->>'expected_admission_generation')::uuid
       or prior_rebind.runtime_binding_manifest is distinct from
         runtime_manifest
       or prior_rebind.runtime_binding_fingerprint is distinct from
         runtime_fingerprint
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_PRECOMMIT_REBIND_ALREADY_USED';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_MAINTENANCE_PRECOMMIT_DEPLOYMENT_REBOUND',
      'rebind_id', prior_rebind.rebind_id,
      'epoch_id', prior_rebind.epoch_id,
      'closure_id', prior_rebind.closure_id,
      'deployment_commit', prior_rebind.deployment_commit,
      'original_deployment_id', prior_rebind.prior_deployment_id,
      'deployment_id', prior_rebind.rebound_deployment_id,
      'activation_revision', prior_rebind.activation_revision_after,
      'admission_revision', prior_rebind.admission_revision_after,
      'authority_generation_id', prior_rebind.authority_generation_id,
      'admission_generation_id', prior_rebind.admission_generation_id,
      'runtime_binding_fingerprint',
        prior_rebind.runtime_binding_fingerprint,
      'authority', 'GOOGLE',
      'maintenance_state', 'SCORING_MAINTENANCE',
      'ingress', 'PAUSED',
      'first_supabase_canonical_write_possible', false,
      'first_supabase_canonical_write_observed', false,
      'idempotent', true
    );
  end if;

  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select value.* into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = (input->>'closure_id')::uuid for update;
  select value.* into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = (input->>'epoch_id')::uuid for update;
  select value.* into strict binding
  from production_control.maintenance_release_candidates value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
    and value.release_sha = activation.expected_deployment_commit;

  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.state <> 'CUTOVER_PREPARED'
     or activation.maintenance_state <> 'SCORING_MAINTENANCE'
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.read_cutover_phase <> 'SCORING_PREPARE'
     or activation.active_transition_epoch_id is distinct from epoch.epoch_id
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or activation.expected_vercel_project_id is distinct from
       'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or activation.staged_environment_delta_fingerprint_v2 is distinct from
       pg_catalog.lower(input->>'staged_environment_delta_fingerprint_v2')
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.first_supabase_mutation_key is not null
     or activation.first_supabase_match_id is not null
     or activation.first_supabase_match_revision is not null
     or resource.current_tournament_read_authority <> 'SUPABASE'
     or resource.scoring_authority <> 'GOOGLE'
     or resource.participant_identity_authority <> 'SUPABASE'
     or resource.scoring_ingress_enabled
     or resource.workers_enabled
     or resource.google_writes_enabled
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'GOOGLE'
     or gate.state <> 'PAUSED'
     or gate.admission_state <> 'CLOSED'
     or not gate.admission_protocol_enforced
     or gate.unresolved_client_queues <> 0
     or gate.admission_deployment_id is distinct from
       input->>'original_deployment_id'
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or gate.active_closure_id is distinct from closure.closure_id
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.closure_kind <> 'LEGACY_ADMISSION'
     or closure.authority <> 'GOOGLE'
     or closure.status <> 'CLOSED'
     or closure.deployment_id is distinct from
       input->>'original_deployment_id'
     or closure.authority_generation_id is distinct from
       activation.authority_generation_id
     or closure.admission_generation_id is distinct from
       gate.admission_generation_id
     or closure.closed_admission_revision is distinct from
       gate.admission_revision
     or closure.final_source_fingerprint is distinct from
       closure.supabase_shadow_fingerprint
     or closure.unexplained_difference_count <> 0
     or epoch.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or epoch.status <> 'PREPARED'
     or epoch.epoch_type <> 'CUTOVER'
     or epoch.authority_before <> 'GOOGLE'
     or epoch.authority_after <> 'SUPABASE'
     or epoch.deployment_commit is distinct from
       activation.expected_deployment_commit
     or epoch.admission_closure_id is distinct from closure.closure_id
     or epoch.admission_generation_id is distinct from
       gate.admission_generation_id
     or epoch.closed_admission_revision is distinct from
       gate.admission_revision
     or epoch.closure_boundary_fingerprint is distinct from
       closure.lease_set_fingerprint
     or epoch.source_fingerprint is distinct from
       closure.final_source_fingerprint
     or epoch.supabase_shadow_fingerprint is distinct from
       closure.supabase_shadow_fingerprint
     or epoch.reconciliation_fingerprint is distinct from
       closure.reconciliation_fingerprint
     or epoch.supabase_match_revisions is distinct from
       production_control.current_match_revisions('2026')
     or epoch.google_checkpoints is distinct from
       production_control.current_google_checkpoints('2026')
     or binding.candidate_deployment_id is null
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or production_control.scoring_admission_legacy_blocker_count(
       gate.admission_enforced_at
     ) <> 0
     or exists (
       select 1 from scoring_authority.scoring_ingress_leases lease
       where lease.tournament_id = '2026'
         and lease.protocol_version = 'ADMISSION_V2'
         and lease.admission_generation_id = gate.admission_generation_id
         and lease.admission_sequence > closure.lease_high_watermark
     )
     or exists (
       select 1 from scoring_authority.google_outbox_events event
       where event.tournament_id = '2026' and event.status <> 'DELIVERED'
     )
     or exists (
       select 1 from scoring_authority.scorecard_archive_jobs job
       where job.tournament_id = '2026'
         and job.status not in ('VERIFIED', 'SUPERSEDED')
     )
     or exists (
       select 1 from production_control.worker_controls worker
       where worker.enabled or worker.scheduler_installed
          or worker.google_writes_allowed
     )
     or exists (
       select 1 from production_control.worker_contracts contract
       where contract.operation_allowed or contract.scheduler_installed
          or contract.authoritative_write_allowed
     )
     or exists (
       select 1 from scoring_authority.authority_epochs other_epoch
       where other_epoch.tournament_id = '2026'
         and other_epoch.status = 'PREPARED'
         and other_epoch.epoch_id <> epoch.epoch_id
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_PRECOMMIT_REBIND_NOT_SAFE';
  end if;

  next_activation_revision := activation.activation_revision + 1;
  next_admission_revision := gate.admission_revision + 1;
  update scoring_authority.ingress_gates
  set admission_deployment_id = input->>'deployment_id',
      admission_revision = next_admission_revision,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' returning * into gate;
  update production_control.scoring_admission_closures
  set deployment_id = input->>'deployment_id',
      closed_admission_revision = next_admission_revision
  where closure_id = closure.closure_id returning * into closure;
  update scoring_authority.authority_epochs
  set closed_admission_revision = next_admission_revision
  where epoch_id = epoch.epoch_id returning * into epoch;
  update production_control.cutover_activation_state
  set activation_revision = next_activation_revision,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION' returning * into activation;

  insert into production_control.maintenance_runtime_deployment_rebindings (
    boundary_mode, tournament_id, epoch_id, closure_id,
    deployment_commit, prior_deployment_id, rebound_deployment_id,
    activation_revision_before, activation_revision_after,
    admission_revision_before, admission_revision_after,
    authority_generation_id, admission_generation_id,
    staged_environment_delta_fingerprint_v2,
    runtime_binding_contract, runtime_binding_manifest,
    runtime_binding_fingerprint, runtime_observed_at,
    request_fingerprint, payload_hash, actor_id
  ) values (
    'MAINTENANCE_WINDOW_V1', '2026', epoch.epoch_id, closure.closure_id,
    input->>'deployment_commit', input->>'original_deployment_id',
    input->>'deployment_id',
    (input->>'expected_activation_revision')::bigint,
    next_activation_revision,
    (input->>'expected_admission_revision')::bigint,
    next_admission_revision,
    activation.authority_generation_id, gate.admission_generation_id,
    pg_catalog.lower(input->>'staged_environment_delta_fingerprint_v2'),
    'production-maintenance-precommit-deployment-rebind-v1',
    runtime_manifest, runtime_fingerprint, runtime_observed_at,
    pg_catalog.lower(input->>'request_fingerprint'),
    production_control.cutover_payload_hash(intent_input),
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into rebind;

  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_MAINTENANCE_PRECOMMIT_DEPLOYMENT_REBOUND',
    'rebind_id', rebind.rebind_id,
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'epoch_id', epoch.epoch_id,
    'closure_id', closure.closure_id,
    'deployment_commit', rebind.deployment_commit,
    'original_deployment_id', rebind.prior_deployment_id,
    'deployment_id', rebind.rebound_deployment_id,
    'activation_revision', activation.activation_revision,
    'admission_revision', gate.admission_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'runtime_binding_fingerprint', runtime_fingerprint,
    'authority', 'GOOGLE',
    'maintenance_state', 'SCORING_MAINTENANCE',
    'ingress', 'PAUSED',
    'workers_enabled', false,
    'first_supabase_canonical_write_possible', false,
    'first_supabase_canonical_write_observed', false,
    'idempotent', false
  );
  insert into scoring_authority.audit_events (
    tournament_id, action, actor_id, metadata
  ) values (
    '2026', 'MAINTENANCE_PRECOMMIT_DEPLOYMENT_REBOUND',
    pg_catalog.left(input->>'actor_id', 160),
    response_value - 'ok' - 'idempotent'
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_MAINTENANCE_PRECOMMIT_DEPLOYMENT_REBOUND',
    'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  perform production_control.store_cutover_receipt(
    'REBIND_MAINTENANCE_PRECOMMIT_DEPLOYMENT', intent_input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.rebind_production_maintenance_precommit_deployment_v1(input jsonb) OWNER TO postgres;

--
-- Name: rebind_production_postcutover_normal_release(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rebind_production_postcutover_normal_release(input jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select production_control.rebind_production_postcutover_normal_release(input)
$$;


ALTER FUNCTION public.rebind_production_postcutover_normal_release(input jsonb) OWNER TO postgres;

--
-- Name: record_participant_phone_enrollment_failure(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_participant_phone_enrollment_failure(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'public', 'pg_temp'
    AS $$
declare target_attempt uuid := nullif(input->>'attempt_id', '')::uuid;
declare actor_auth_user uuid := nullif(input->>'actor_auth_user_id', '')::uuid;
declare reason_value text := upper(btrim(coalesce(input->>'safe_reason', 'PHONE_OTP_INVALID_OR_EXPIRED')));
declare duration_value integer := greatest(0, coalesce((input->>'duration_ms')::integer, 0));
declare attempt participant_identity.participant_phone_otp_attempts%rowtype;
declare next_failures integer;
declare next_status text;
begin
  select * into attempt from participant_identity.participant_phone_otp_attempts
  where attempt_id = target_attempt and auth_user_id = actor_auth_user and requested_by_auth_user_id = actor_auth_user
  for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_SESSION_REQUIRED'); end if;
  if attempt.status = 'VERIFIED' then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_REPLAY'); end if;
  if attempt.status <> 'SENT' then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_STALE'); end if;
  next_failures := least(5, attempt.verify_failure_count + case when reason_value = 'PHONE_OTP_PROVIDER_UNAVAILABLE' then 0 else 1 end);
  next_status := case
    when reason_value = 'PHONE_OTP_AUTH_MISMATCH' then 'UUID_MISMATCH'
    when reason_value = 'PHONE_OTP_INVALID_OR_EXPIRED' and attempt.expires_at <= now() then 'EXPIRED'
    when next_failures >= 5 then 'VERIFY_LOCKED'
    else 'SENT'
  end;
  update participant_identity.participant_phone_otp_attempts set status = next_status,
    safe_reason = reason_value, verify_failure_count = next_failures,
    verification_duration_ms = duration_value, updated_at = now()
  where attempt_id = target_attempt;
  if next_status in ('UUID_MISMATCH', 'EXPIRED', 'VERIFY_LOCKED') then
    update participant_identity.participant_auth_identifiers set status = 'ELIGIBLE', updated_at = now()
    where identifier_id = attempt.identifier_id and status = 'VERIFICATION_PENDING';
  end if;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_id, actor_name, request_id, safe_metadata
  ) values (
    case when reason_value = 'PHONE_OTP_AUTH_MISMATCH' then 'PHONE_ENROLLMENT_UUID_MISMATCH' else 'PHONE_ENROLLMENT_VERIFY_FAILED' end,
    attempt.tournament_id, attempt.auth_user_id, attempt.player_id, attempt.player_id,
    'Authenticated participant', attempt.attempt_id::text,
    jsonb_build_object('safeReason', reason_value, 'attemptStatus', next_status,
      'verifyFailureCount', next_failures, 'durationMs', duration_value,
      'rawPhoneLogged', false, 'otpLogged', false)
  );
  return jsonb_build_object('ok', true, 'status', next_status, 'verifyFailureCount', next_failures);
end;
$$;


ALTER FUNCTION public.record_participant_phone_enrollment_failure(input jsonb) OWNER TO postgres;

--
-- Name: record_participant_phone_enrollment_send(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_participant_phone_enrollment_send(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'public', 'auth', 'pg_temp'
    AS $_$
declare target_attempt uuid := nullif(input->>'attempt_id', '')::uuid;
declare actor_auth_user uuid := nullif(input->>'actor_auth_user_id', '')::uuid;
declare returned_auth_user uuid := nullif(input->>'returned_auth_user_id', '')::uuid;
declare succeeded boolean := coalesce((input->>'succeeded')::boolean, false);
declare provider_called_value boolean := coalesce((input->>'provider_called')::boolean, false);
declare pending_phone_matches boolean := coalesce((input->>'pending_phone_matches')::boolean, false);
declare pending_phone_source text := upper(btrim(coalesce(input->>'pending_phone_source', '')));
declare reason_value text := upper(btrim(coalesce(input->>'safe_reason', 'PHONE_OTP_SEND_FAILED')));
declare duration_value integer := greatest(0, coalesce((input->>'duration_ms')::integer, 0));
declare attempt participant_identity.participant_phone_otp_attempts%rowtype;
declare identifier participant_identity.participant_auth_identifiers%rowtype;
declare auth_user auth.users%rowtype;
begin
  if reason_value !~ '^[A-Z0-9_]+$' then reason_value := 'PHONE_OTP_SEND_FAILED'; end if;
  if pending_phone_source not in (
    'UPDATE_USER_NEW_PHONE', 'UPDATE_USER_PHONE_CHANGE',
    'ADMIN_USER_NEW_PHONE', 'ADMIN_USER_PHONE_CHANGE'
  ) then
    pending_phone_matches := false;
    pending_phone_source := 'NONE';
  end if;

  select * into attempt from participant_identity.participant_phone_otp_attempts
  where attempt_id = target_attempt
    and auth_user_id = actor_auth_user
    and requested_by_auth_user_id = actor_auth_user
  for update;
  if not found or attempt.status <> 'REQUESTING' then
    return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_STALE');
  end if;

  select * into identifier from participant_identity.participant_auth_identifiers
  where identifier_id = attempt.identifier_id for update;
  select * into auth_user from auth.users where id = attempt.auth_user_id;

  if succeeded and returned_auth_user is distinct from attempt.auth_user_id then
    succeeded := false;
    reason_value := 'PHONE_OTP_AUTH_MISMATCH';
  elsif succeeded and (
    identifier.identifier_id is null
    or identifier.player_id <> attempt.player_id
    or identifier.auth_user_id <> attempt.auth_user_id
    or identifier.revision <> attempt.identifier_revision
    or identifier.status not in ('ELIGIBLE', 'VERIFICATION_PENDING')
  ) then
    succeeded := false;
    reason_value := 'PHONE_OTP_ENROLLMENT_START_FAILED';
  elsif succeeded and (
    nullif(btrim(coalesce(auth_user.phone, '')), '') is not null
    or auth_user.phone_confirmed_at is not null
    or (
      nullif(btrim(coalesce(auth_user.phone_change, '')), '') is not null
      and participant_identity.canonical_auth_phone(auth_user.phone_change)
        <> participant_identity.canonical_auth_phone(identifier.normalized_value_private)
    )
    or (
      not pending_phone_matches
      and participant_identity.canonical_auth_phone(nullif(auth_user.phone_change, ''))
        is distinct from participant_identity.canonical_auth_phone(identifier.normalized_value_private)
    )
  ) then
    succeeded := false;
    reason_value := 'PHONE_OTP_PENDING_STATE_MISMATCH';
  elsif succeeded and exists (
    select 1 from auth.users other_user where other_user.id <> attempt.auth_user_id
      and (participant_identity.canonical_auth_phone(nullif(other_user.phone, ''))
        = participant_identity.canonical_auth_phone(identifier.normalized_value_private)
        or participant_identity.canonical_auth_phone(nullif(other_user.phone_change, ''))
        = participant_identity.canonical_auth_phone(identifier.normalized_value_private))
  ) then
    succeeded := false;
    reason_value := 'PHONE_OTP_AUTH_COLLISION';
  end if;

  update participant_identity.participant_phone_otp_attempts set
    status = case when succeeded then 'SENT' else 'SEND_FAILED' end,
    safe_reason = case when succeeded then 'PHONE_CHANGE_VERIFICATION_PENDING' else reason_value end,
    provider_called = provider_called_value,
    provider_requested_at = case when provider_called_value then now() else null end,
    sent_at = case when succeeded then now() else null end,
    request_duration_ms = duration_value, updated_at = now()
  where attempt_id = target_attempt;

  update participant_identity.participant_auth_identifiers set
    status = case when succeeded then 'VERIFICATION_PENDING' else 'ELIGIBLE' end,
    updated_by = 'SUPABASE_AUTH_PHONE_CHANGE', updated_at = now()
  where identifier_id = attempt.identifier_id
    and revision = attempt.identifier_revision
    and status in ('ELIGIBLE', 'VERIFICATION_PENDING');

  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_id, actor_name,
    request_id, safe_metadata
  ) values (
    case when succeeded then 'PHONE_ENROLLMENT_CODE_SENT' else 'PHONE_ENROLLMENT_SEND_FAILED' end,
    attempt.tournament_id, attempt.auth_user_id, attempt.player_id, attempt.player_id,
    'Authenticated participant', attempt.attempt_id::text,
    jsonb_build_object(
      'method', 'AUTHENTICATED_PHONE_CHANGE',
      'providerCalled', provider_called_value,
      'safeReason', case when succeeded then 'PHONE_CHANGE_VERIFICATION_PENDING' else reason_value end,
      'pendingPhoneSource', pending_phone_source,
      'pendingPhoneNormalized', pending_phone_matches,
      'returnedAuthUserMatch', returned_auth_user = attempt.auth_user_id,
      'durationMs', duration_value,
      'rawPhoneLogged', false,
      'otpLogged', false
    )
  );

  return jsonb_build_object(
    'ok', succeeded,
    'code', case when succeeded then 'PHONE_OTP_VERIFICATION_PENDING' else reason_value end,
    'status', case when succeeded then 'VERIFICATION_PENDING' else 'SEND_FAILED' end,
    'expiresAt', attempt.expires_at,
    'sameAuthUser', succeeded and returned_auth_user = attempt.auth_user_id,
    'phoneRepresentationNormalized', succeeded and pending_phone_matches
  );
end;
$_$;


ALTER FUNCTION public.record_participant_phone_enrollment_send(input jsonb) OWNER TO postgres;

--
-- Name: record_participant_phone_login_failure(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_participant_phone_login_failure(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'participant_identity', 'public', 'pg_temp'
    AS $_$
declare target_attempt uuid := nullif(input->>'attempt_id', '')::uuid;
declare expected_auth_user uuid := nullif(input->>'auth_user_id', '')::uuid;
declare reason_value text := upper(btrim(coalesce(input->>'safe_reason', 'PHONE_LOGIN_VERIFY_FAILED')));
declare duration_value integer := greatest(0, coalesce((input->>'duration_ms')::integer, 0));
declare attempt participant_identity.participant_phone_otp_attempts%rowtype;
declare next_failures integer;
declare next_status text;
begin
  if reason_value !~ '^[A-Z0-9_]+$' then reason_value := 'PHONE_LOGIN_VERIFY_FAILED'; end if;
  select * into attempt from participant_identity.participant_phone_otp_attempts current_attempt
  where current_attempt.attempt_id = target_attempt
    and current_attempt.auth_user_id = expected_auth_user for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_STALE'); end if;
  if attempt.status = 'VERIFIED' then return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_REPLAY'); end if;
  if attempt.status <> 'SENT' or attempt.safe_reason <> 'PHONE_LOGIN_CODE_SENT' then
    return jsonb_build_object('ok', false, 'code', 'PHONE_OTP_STALE');
  end if;
  next_failures := least(5, attempt.verify_failure_count + case when reason_value = 'PHONE_OTP_PROVIDER_UNAVAILABLE' then 0 else 1 end);
  next_status := case
    when reason_value = 'PHONE_OTP_AUTH_MISMATCH' then 'UUID_MISMATCH'
    when reason_value in ('PHONE_LOGIN_SESSION_FAILED', 'PHONE_LOGIN_PASSPORT_MISSING') then 'CANCELLED'
    when attempt.expires_at <= now() then 'EXPIRED'
    when next_failures >= 5 then 'VERIFY_LOCKED'
    else 'SENT'
  end;
  update participant_identity.participant_phone_otp_attempts set
    status = next_status, safe_reason = case when next_status = 'SENT' then 'PHONE_LOGIN_CODE_SENT' else reason_value end,
    verify_failure_count = next_failures, verification_duration_ms = duration_value, updated_at = now()
  where attempt_id = target_attempt;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_id, actor_name,
    request_id, safe_metadata
  ) values (
    case when reason_value = 'PHONE_OTP_AUTH_MISMATCH' then 'PHONE_LOGIN_UUID_MISMATCH' else 'PHONE_LOGIN_VERIFY_FAILED' end,
    attempt.tournament_id, attempt.auth_user_id, attempt.player_id, attempt.player_id,
    'Controlled signed-out participant', attempt.attempt_id::text,
    jsonb_build_object('safeReason', reason_value, 'attemptStatus', next_status,
      'verifyFailureCount', next_failures, 'unexpectedSessionTerminated', reason_value = 'PHONE_OTP_AUTH_MISMATCH',
      'ownershipMutated', false, 'rawPhoneLogged', false, 'otpLogged', false)
  );
  return jsonb_build_object('ok', true, 'status', next_status, 'verifyFailureCount', next_failures);
end;
$_$;


ALTER FUNCTION public.record_participant_phone_login_failure(input jsonb) OWNER TO postgres;

--
-- Name: record_production_auth_candidate_logout(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_auth_candidate_logout(target_auth_user_id uuid, target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'public', 'pg_temp'
    AS $$
declare candidate participant_identity.production_auth_candidates%rowtype;
begin
  perform production_control.assert_production_auth_candidate_rpc();
  if btrim(coalesce(target_tournament_id, '')) <> '2026' then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_SCOPE_INVALID');
  end if;
  select * into candidate from participant_identity.production_auth_candidates
  where tournament_id = '2026' and auth_user_id = target_auth_user_id and status = 'VERIFIED';
  if found then insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_name, safe_metadata
  ) values ('PRODUCTION_AUTH_LOGOUT', candidate.tournament_id, candidate.auth_user_id,
    candidate.player_id, 'step10b-production-auth-candidate',
    jsonb_build_object('sessionTokenStored', false)); end if;
  return jsonb_build_object('ok', true, 'recorded', found);
end;
$$;


ALTER FUNCTION public.record_production_auth_candidate_logout(target_auth_user_id uuid, target_tournament_id text) OWNER TO postgres;

--
-- Name: record_production_auth_candidate_otp_delivery(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_auth_candidate_otp_delivery(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'participant_identity', 'pg_temp'
    AS $$
declare request uuid := nullif(input->>'request_id', '')::uuid;
declare succeeded boolean := coalesce((input->>'succeeded')::boolean, false);
declare requested_reason text := upper(btrim(coalesce(input->>'safe_reason', 'AUTH_EMAIL_SEND_FAILED')));
begin
  perform production_control.assert_production_auth_candidate_rpc();
  if requested_reason not in (
    'AUTH_CAPTCHA_REJECTED', 'AUTH_SUPABASE_RATE_LIMITED',
    'AUTH_SMTP_PROVIDER_RATE_LIMITED', 'AUTH_EMAIL_RATE_LIMITED_UNKNOWN_SOURCE',
    'AUTH_EMAIL_CONFIGURATION_FAILED', 'AUTH_SMTP_PROVIDER_REJECTED',
    'AUTH_EMAIL_SERVICE_UNAVAILABLE', 'AUTH_EMAIL_SEND_FAILED'
  ) then
    requested_reason := 'AUTH_EMAIL_SEND_FAILED';
  end if;
  update participant_identity.participant_auth_otp_attempts set
    status = case when succeeded then 'SENT' else 'DELIVERY_FAILED' end,
    safe_reason = case when succeeded then 'DELIVERY_ACCEPTED' else requested_reason end,
    request_duration_ms = greatest(0, coalesce((input->>'duration_ms')::integer, 0)),
    sent_at = case when succeeded then now() else sent_at end, updated_at = now()
  where request_id = request and status = 'AUTHORIZED';
  if not found then raise exception 'OTP request is not in an authorized delivery state.'; end if;
  return jsonb_build_object('ok', true, 'requestId', request,
    'status', case when succeeded then 'SENT' else 'DELIVERY_FAILED' end);
end;
$$;


ALTER FUNCTION public.record_production_auth_candidate_otp_delivery(input jsonb) OWNER TO postgres;

--
-- Name: record_production_auth_candidate_otp_verification(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_auth_candidate_otp_verification(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth', 'pg_temp'
    AS $$
declare request uuid := nullif(input->>'request_id', '')::uuid;
declare user_id uuid := nullif(input->>'auth_user_id', '')::uuid;
declare succeeded boolean := coalesce((input->>'succeeded')::boolean, false);
declare attempt participant_identity.participant_auth_otp_attempts%rowtype;
begin
  perform production_control.assert_production_auth_candidate_rpc();
  if succeeded then
    return production_control.certify_production_auth_candidate_otp(
      request, user_id, greatest(0, coalesce((input->>'duration_ms')::integer, 0)), false
    );
  end if;
  select * into attempt from participant_identity.participant_auth_otp_attempts
  where request_id = request for update;
  if not found then raise exception 'OTP request was not found.'; end if;
  if attempt.status = 'VERIFICATION_FAILED' then
    return jsonb_build_object('ok', true, 'status', 'VERIFICATION_FAILED', 'duplicate', true);
  end if;
  if attempt.status <> 'SENT' then raise exception 'OTP request is not awaiting verification.'; end if;
  update participant_identity.participant_auth_otp_attempts set
    status = 'VERIFICATION_FAILED', safe_reason = 'INVALID_OR_EXPIRED_CODE',
    verification_duration_ms = greatest(0, coalesce((input->>'duration_ms')::integer, 0)),
    updated_at = now()
  where request_id = request;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_name, request_id, safe_metadata
  ) values (
    'PRODUCTION_AUTH_VERIFY_FAILED', attempt.tournament_id, attempt.auth_user_id,
    attempt.player_id, 'step10b-production-auth-certification', request::text,
    jsonb_build_object('result', 'FAILED', 'otpStored', false, 'identityAuthorityChanged', false)
  );
  return jsonb_build_object('ok', true, 'status', 'VERIFICATION_FAILED', 'duplicate', false);
end;
$$;


ALTER FUNCTION public.record_production_auth_candidate_otp_verification(input jsonb) OWNER TO postgres;

--
-- Name: record_production_auth_candidate_preprovision_cleanup(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_auth_candidate_preprovision_cleanup(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth', 'pg_temp'
    AS $$
declare scope production_control.resource_scope%rowtype;
declare claim participant_identity.production_auth_preprovision_claims%rowtype;
declare target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
declare cleanup_succeeded boolean := coalesce((input->>'cleanup_succeeded')::boolean, false);
declare safe_reason text := upper(btrim(coalesce(input->>'safe_reason', 'AUTH_CANDIDATE_FINALIZATION_FAILED')));
begin
  scope := production_control.assert_production_auth_candidate_rpc();
  if safe_reason not in ('AUTH_USER_CREATION_FAILED', 'AUTH_USER_DELETE_CONFIRMED',
    'AUTH_USER_DELETE_FAILED', 'AUTH_CANDIDATE_FINALIZATION_FAILED') then
    safe_reason := 'AUTH_CANDIDATE_FINALIZATION_FAILED';
  end if;
  select * into claim from participant_identity.production_auth_preprovision_claims
  where claim_id = nullif(input->>'claim_id', '')::uuid for update;
  if not found or claim.project_ref <> scope.project_ref or claim.source_workbook_id <> scope.google_workbook_id
    or claim.status = 'CONSUMED' then
    raise exception using errcode = '42501', message = 'PRODUCTION_AUTH_PREPROVISION_CLEANUP_CLAIM_REQUIRED';
  end if;
  if cleanup_succeeded then
    if exists (select 1 from auth.users) then
      raise exception using errcode = '42501', message = 'PRODUCTION_AUTH_PREPROVISION_AUTH_USER_STILL_PRESENT';
    end if;
    update participant_identity.production_auth_preprovision_claims set
      status = 'CANCELLED', auth_user_id = null, cancelled_at = now(),
      cleanup_reason = safe_reason, updated_at = now()
    where claim_id = claim.claim_id;
  else
    if target_user is null or not exists (select 1 from auth.users where id = target_user) then
      raise exception using errcode = '42501', message = 'PRODUCTION_AUTH_PREPROVISION_CLEANUP_USER_REQUIRED';
    end if;
    update participant_identity.production_auth_preprovision_claims set
      status = 'CLEANUP_REQUIRED', auth_user_id = target_user,
      cleanup_reason = safe_reason, updated_at = now()
    where claim_id = claim.claim_id;
  end if;
  insert into participant_identity.identity_audit_events (
    event_type, tournament_id, auth_user_id, player_id, actor_name, request_id, safe_metadata
  ) values (
    case when cleanup_succeeded then 'PRODUCTION_AUTH_PREPROVISION_CLEANED'
      else 'PRODUCTION_AUTH_PREPROVISION_CLEANUP_REQUIRED' end,
    '2026', target_user, claim.player_id, claim.requested_by, claim.claim_id::text,
    jsonb_build_object('cleanupSucceeded', cleanup_succeeded, 'safeReason', safe_reason,
      'identityAuthorityChanged', false)
  );
  return jsonb_build_object('ok', true,
    'status', case when cleanup_succeeded then 'CANCELLED' else 'CLEANUP_REQUIRED' end);
end;
$$;


ALTER FUNCTION public.record_production_auth_candidate_preprovision_cleanup(input jsonb) OWNER TO postgres;

--
-- Name: record_production_bulk_manual_handicap_source_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_bulk_manual_handicap_source_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text; actor_player text; actor_auth uuid; request_id uuid;
  declared_hash text; database_hash text; expected_preview text;
  prior production_control.handicap_source_operation_receipts_v1%rowtype;
  preview_value jsonb; entry_value jsonb; player_value text;
  identity_value uuid; pointer_value production_control.handicap_source_current_v1%rowtype;
  observation_value uuid; event_value uuid; evidence_hash text;
  current_value numeric; low_value numeric; low_date_value date;
  result_rows jsonb:='[]'::jsonb; response_value jsonb;
begin
  target:=production_control.assert_handicap_source_runtime_v1(input);
  actor_player:=pg_catalog.upper(pg_catalog.btrim(input#>>'{authorization,player_id}'));
  actor_auth:=(input#>>'{authorization,auth_user_id}')::uuid;
  declared_hash:=pg_catalog.lower(pg_catalog.btrim(coalesce(input->>'request_payload_hash','')));
  expected_preview:=pg_catalog.lower(pg_catalog.btrim(coalesce(input->>'expected_preview_fingerprint','')));
  if input->>'operation' is distinct from 'RECORD_PRODUCTION_BULK_MANUAL_HANDICAP_SOURCE_V1'
     or input->>'entry_mode' is distinct from 'BULK_IMPORT'
     or coalesce(input->>'operation_request_id','') !~ '^[0-9a-fA-F-]{36}$'
     or expected_preview !~ '^[0-9a-f]{64}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(input->'entries') is distinct from 'array' then
    raise exception using errcode='22023',message='PRODUCTION_HANDICAP_SOURCE_BULK_INPUT_INVALID';
  end if;
  request_id:=(input->>'operation_request_id')::uuid;
  database_hash:=production_control.handicap_source_hash_v1(pg_catalog.jsonb_build_object(
    'operation','RECORD_BULK_MANUAL_OBSERVATIONS','entryMode','BULK_IMPORT',
    'expectedPreviewFingerprint',expected_preview,'entries',input->'entries',
    'actorPlayerId',actor_player,'actorAuthUserId',actor_auth
  ));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('production-handicap-source-bulk:'||target,0));
  select value.* into prior from production_control.handicap_source_operation_receipts_v1 value
    where value.tournament_id=target and value.operation_request_id=request_id;
  if found then
    if prior.declared_request_payload_hash=declared_hash and prior.database_request_payload_hash=database_hash then
      return prior.response||pg_catalog.jsonb_build_object('idempotent',true);
    end if;
    raise exception using errcode='23505',message='PRODUCTION_HANDICAP_SOURCE_IDEMPOTENCY_CONFLICT';
  end if;
  for player_value in
    select pg_catalog.upper(entry->>'player_id') from pg_catalog.jsonb_array_elements(input->'entries') entry
    order by pg_catalog.upper(entry->>'player_id')
  loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('production-handicap-source:'||target||':'||player_value,0));
  end loop;
  preview_value:=production_control.preview_bulk_manual_handicap_source_v1(target,input->'entries');
  if coalesce((preview_value->>'ready')::boolean,false) is not true then
    raise exception using errcode='22023',message='PRODUCTION_HANDICAP_SOURCE_BULK_VALIDATION_FAILED';
  end if;
  if preview_value->>'previewFingerprint' is distinct from expected_preview then
    raise exception using errcode='40001',message='PRODUCTION_HANDICAP_SOURCE_BULK_PREVIEW_STALE';
  end if;

  for entry_value in
    select value from pg_catalog.jsonb_array_elements(preview_value->'entries') entries(value)
    order by value->>'player_id'
  loop
    player_value:=entry_value->>'player_id';
    current_value:=(entry_value->>'current_index')::numeric;
    low_value:=(entry_value->>'low_index')::numeric;
    low_date_value:=(entry_value->>'low_index_date')::date;
    select identity_id into strict identity_value
      from production_control.player_external_identities_v1
      where player_id=player_value and provider='GHIN' and status='VERIFIED' for share;
    select value.* into pointer_value from production_control.handicap_source_current_v1 value
      where value.tournament_id=target and value.player_id=player_value and value.provider='GHIN' for update;
    observation_value:=extensions.gen_random_uuid();
    event_value:=extensions.gen_random_uuid();
    evidence_hash:=production_control.handicap_source_hash_v1(pg_catalog.jsonb_build_object(
      'provider','GHIN','identityId',identity_value,'playerId',player_value,
      'currentIndex',current_value,'lowIndex',low_value,'lowIndexDate',low_date_value,
      'provenance','DIRECTOR_MANUAL','entryMode','BULK_IMPORT'
    ));
    insert into production_control.handicap_source_observations_v1(
      observation_id,tournament_id,player_id,identity_id,provider,current_index,low_index,
      low_index_date,provenance,status,source_evidence_fingerprint,
      created_by_player_id,created_by_auth_user_id
    ) values (
      observation_value,target,player_value,identity_value,'GHIN',current_value,low_value,
      low_date_value,'DIRECTOR_MANUAL','ACCEPTED',evidence_hash,actor_player,actor_auth
    );
    insert into production_control.handicap_source_current_v1(
      tournament_id,player_id,provider,observation_id,pointer_revision,source_status,
      updated_by_player_id,updated_by_auth_user_id
    ) values (
      target,player_value,'GHIN',observation_value,coalesce(pointer_value.pointer_revision,0)+1,
      'CURRENT',actor_player,actor_auth
    ) on conflict(tournament_id,player_id,provider) do update set
      observation_id=excluded.observation_id,pointer_revision=excluded.pointer_revision,
      source_status='CURRENT',updated_by_player_id=excluded.updated_by_player_id,
      updated_by_auth_user_id=excluded.updated_by_auth_user_id,
      updated_at=pg_catalog.clock_timestamp();
    insert into production_control.handicap_source_audit_events_v1(
      event_id,tournament_id,action,player_id,identity_id,observation_id,
      actor_player_id,actor_auth_user_id,operation_request_id,before_state,after_state
    ) values (
      event_value,target,'MANUAL_SOURCE_RECORDED',player_value,identity_value,observation_value,
      actor_player,actor_auth,request_id,
      case when pointer_value.observation_id is null then '{}'::jsonb else pg_catalog.jsonb_build_object(
        'observationId',pointer_value.observation_id,'pointerRevision',pointer_value.pointer_revision
      ) end,
      pg_catalog.jsonb_build_object(
        'observationId',observation_value,'pointerRevision',coalesce(pointer_value.pointer_revision,0)+1,
        'evidenceFingerprint',evidence_hash,'entryMode','BULK_IMPORT'
      )
    );
    result_rows:=result_rows||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'playerId',player_value,'observationId',observation_value,
      'pointerRevision',coalesce(pointer_value.pointer_revision,0)+1,
      'currentIndex',current_value::text,'lowIndex',low_value::text,
      'lowIndexDate',low_date_value,'hybrid',production_control.hybrid_handicap_v1(current_value,low_value)::text
    ));
  end loop;
  response_value:=pg_catalog.jsonb_build_object(
    'ok',true,'code','PRODUCTION_HANDICAP_SOURCE_BULK_RECORDED','idempotent',false,
    'entryMode','BULK_IMPORT','recordedCount',pg_catalog.jsonb_array_length(result_rows),
    'rows',result_rows,'sourceFingerprint',production_control.handicap_source_set_fingerprint_v1(target)
  );
  perform production_control.handicap_source_receipt_v1(
    target,'RECORD_BULK_MANUAL_OBSERVATIONS',request_id,declared_hash,database_hash,
    actor_player,actor_auth,response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.record_production_bulk_manual_handicap_source_v1(input jsonb) OWNER TO postgres;

--
-- Name: record_production_future_participant_first_login_cleanup_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_future_participant_first_login_cleanup_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  claim participant_identity.production_participant_enrollment_claims%rowtype;
  target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
  reason text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'safe_reason', 'AUTH_USER_PROVISIONING_FAILED'
  )));
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  if reason not in (
    'AUTH_USER_PROVISIONING_FAILED', 'AUTH_USER_DELETE_CONFIRMED',
    'AUTH_USER_DELETE_FAILED'
  ) then
    reason := 'AUTH_USER_PROVISIONING_FAILED';
  end if;
  select value.* into claim
  from participant_identity.production_participant_enrollment_claims value
  where value.claim_id = nullif(input->>'claim_id', '')::uuid
    and value.tournament_id = target_id
  for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'recorded', false
    );
  end if;
  if claim.status = 'CONSUMED' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_ALREADY_CONSUMED';
  end if;
  update participant_identity.production_participant_enrollment_claims set
    status = case when reason = 'AUTH_USER_DELETE_FAILED'
      then 'CLEANUP_REQUIRED' else 'CANCELLED' end,
    auth_user_id = case when reason = 'AUTH_USER_DELETE_FAILED'
      then target_user else null end,
    cleanup_reason = reason,
    cancelled_at = case when reason = 'AUTH_USER_DELETE_FAILED'
      then null else pg_catalog.clock_timestamp() end,
    updated_at = pg_catalog.clock_timestamp()
  where claim_id = claim.claim_id;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'recorded', true,
    'cleanupRequired', reason = 'AUTH_USER_DELETE_FAILED'
  );
end;
$$;


ALTER FUNCTION public.record_production_future_participant_first_login_cleanup_v1(input jsonb) OWNER TO postgres;

--
-- Name: record_production_future_participant_logout_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_future_participant_logout_v1(target_auth_user_id uuid, target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  target_player text;
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  if pg_catalog.btrim(coalesce(target_tournament_id, '')) <> target_id then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'PRODUCTION_AUTH_SCOPE_INVALID'
    );
  end if;
  select eligibility.player_id into target_player
  from production_control.future_participant_identity_eligibility_v1(
    target_id
  ) eligibility
  where eligibility.auth_user_id = target_auth_user_id
    and eligibility.runtime_eligible;
  if found then
    insert into participant_identity.identity_audit_events (
      event_type, tournament_id, auth_user_id, player_id,
      actor_name, safe_metadata
    ) values (
      'FUTURE_TOURNAMENT_PARTICIPANT_AUTH_LOGOUT', target_id,
      target_auth_user_id, target_player,
      'future-runtime-participant-auth-v1',
      pg_catalog.jsonb_build_object('sessionTokenStored', false)
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'recorded', found
  );
end;
$$;


ALTER FUNCTION public.record_production_future_participant_logout_v1(target_auth_user_id uuid, target_tournament_id text) OWNER TO postgres;

--
-- Name: record_production_future_participant_otp_delivery_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_future_participant_otp_delivery_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  request_value uuid := nullif(input->>'request_id', '')::uuid;
  succeeded boolean := coalesce((input->>'succeeded')::boolean, false);
  requested_reason text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    input->>'safe_reason', 'AUTH_EMAIL_SEND_FAILED'
  )));
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  if requested_reason not in (
    'AUTH_CAPTCHA_REJECTED', 'AUTH_SUPABASE_RATE_LIMITED',
    'AUTH_SMTP_PROVIDER_RATE_LIMITED',
    'AUTH_EMAIL_RATE_LIMITED_UNKNOWN_SOURCE',
    'AUTH_EMAIL_CONFIGURATION_FAILED', 'AUTH_SMTP_PROVIDER_REJECTED',
    'AUTH_EMAIL_SERVICE_UNAVAILABLE', 'AUTH_EMAIL_SEND_FAILED'
  ) then
    requested_reason := 'AUTH_EMAIL_SEND_FAILED';
  end if;
  update participant_identity.participant_auth_otp_attempts set
    status = case when succeeded then 'SENT' else 'DELIVERY_FAILED' end,
    safe_reason = case when succeeded
      then 'DELIVERY_ACCEPTED' else requested_reason end,
    request_duration_ms = greatest(0, coalesce(
      (input->>'duration_ms')::integer, 0
    )),
    sent_at = case when succeeded
      then pg_catalog.clock_timestamp() else sent_at end,
    updated_at = pg_catalog.clock_timestamp()
  where request_id = request_value
    and tournament_id = target_id
    and status = 'AUTHORIZED';
  if not found then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_PARTICIPANT_OTP_NOT_AUTHORIZED';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'requestId', request_value,
    'status', case when succeeded then 'SENT' else 'DELIVERY_FAILED' end
  );
end;
$$;


ALTER FUNCTION public.record_production_future_participant_otp_delivery_v1(input jsonb) OWNER TO postgres;

--
-- Name: record_production_future_participant_otp_verification_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_future_participant_otp_verification_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  request_value uuid := nullif(input->>'request_id', '')::uuid;
  target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  if coalesce((input->>'succeeded')::boolean, false) then
    return production_control
      .certify_production_future_participant_otp_v1(
        request_value, target_user,
        greatest(0, coalesce(
          (input->>'duration_ms')::integer, 0
        )), false
      );
  end if;
  update participant_identity.participant_auth_otp_attempts set
    status = 'VERIFICATION_FAILED',
    safe_reason = 'INVALID_OR_EXPIRED_CODE',
    verification_duration_ms = greatest(0, coalesce(
      (input->>'duration_ms')::integer, 0
    )),
    updated_at = pg_catalog.clock_timestamp()
  where request_id = request_value
    and tournament_id = target_id
    and status = 'SENT';
  return pg_catalog.jsonb_build_object(
    'ok', true, 'status', 'VERIFICATION_FAILED'
  );
end;
$$;


ALTER FUNCTION public.record_production_future_participant_otp_verification_v1(input jsonb) OWNER TO postgres;

--
-- Name: record_production_google_writer_acl_dispatch_result(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_google_writer_acl_dispatch_result(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  direction_value text := pg_catalog.upper(coalesce(input->>'direction', ''));
  outcome_value text := pg_catalog.upper(coalesce(input->>'outcome_status', ''));
  fence production_control.google_writer_provider_fences%rowtype;
  install_dispatch
    production_control.google_writer_provider_fence_install_dispatches%rowtype;
  restore_dispatch
    production_control.google_writer_provider_fence_abort_dispatches%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  existing
    production_control.google_writer_provider_fence_acl_dispatch_results%rowtype;
  inserted
    production_control.google_writer_provider_fence_acl_dispatch_results%rowtype;
  payload_hash_value text := production_control.cutover_payload_hash(input);
  result_request_identifier uuid;
  proof_value jsonb := input->'transition_proof';
  proof_fingerprint text := pg_catalog.lower(
    coalesce(input->>'transition_proof_fingerprint', '')
  );
  provider_observed timestamptz;
  expected_mutation_class text;
  expected_source_role text;
  expected_target_role text;
  selected_dispatch_id uuid;
  current_outcome text;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'operation' is distinct from
       'RECORD_PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_ACL_DISPATCH_RESULT'
     or direction_value not in ('INSTALL', 'RESTORE')
     or outcome_value not in ('TARGET_CONFIRMED', 'OUTCOME_UNKNOWN')
     or coalesce(input->>'fence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'install_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'dispatch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'result_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or (outcome_value = 'OUTCOME_UNKNOWN' and proof_value is not null)
     or (outcome_value <> 'OUTCOME_UNKNOWN' and (
       pg_catalog.jsonb_typeof(proof_value) is distinct from 'object'
       or (select pg_catalog.count(*)
           from pg_catalog.jsonb_object_keys(proof_value)) <> 29
       or proof_fingerprint !~ '^[0-9a-f]{64}$'
       or proof_value->>'transitionFingerprint' is distinct from
         proof_fingerprint
       or production_control.google_drive_acl_transition_proof_fingerprint_v1(
         proof_value - 'transitionFingerprint'
       ) is distinct from proof_fingerprint
     ))
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESULT_INPUT_INVALID';
  end if;
  result_request_identifier := (input->>'result_request_id')::uuid;
  if nullif(input->>'provider_observed_at', '') is not null then
    provider_observed := (input->>'provider_observed_at')::timestamptz;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into existing
  from production_control.google_writer_provider_fence_acl_dispatch_results value
  where value.result_request_id = result_request_identifier;
  if found then
    if existing.fence_id is distinct from (input->>'fence_id')::uuid
       or existing.direction is distinct from direction_value
       or existing.outcome_status is distinct from outcome_value
       or existing.request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or existing.payload_hash is distinct from payload_hash_value
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESULT_IDEMPOTENCY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'code', 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_' ||
        direction_value || '_' || existing.outcome_status,
      'fence_id', existing.fence_id,
      'result_id', existing.result_id,
      'result_request_id', existing.result_request_id,
      'direction', existing.direction,
      'outcome_status', existing.outcome_status,
      'transition_proof_fingerprint',
        existing.transition_proof_fingerprint,
      'provider_observed_at', existing.provider_observed_at,
      'recorded_at', existing.recorded_at,
      'admission_reservation_active', true,
      'idempotent', true
    );
  end if;

  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = (input->>'fence_id')::uuid
    and value.install_request_id = (input->>'install_request_id')::uuid
  for update;
  if fence.actor_id is distinct from input->>'actor_id'
     or fence.authenticated_actor_fingerprint is distinct from
       pg_catalog.lower(input->>'authenticated_actor_fingerprint')
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESULT_OWNERSHIP_MISMATCH';
  end if;

  if direction_value = 'INSTALL' then
    select * into strict install_dispatch
    from production_control.google_writer_provider_fence_install_dispatches value
    where value.fence_id = fence.fence_id
      and value.dispatch_id = (input->>'dispatch_id')::uuid
    for update;
    selected_dispatch_id := install_dispatch.dispatch_id;
    current_outcome := install_dispatch.outcome_status;
    expected_mutation_class :=
      'DRIVE_LEGACY_PERMISSION_WRITER_TO_READER_V1';
    expected_source_role := 'writer';
    expected_target_role := 'reader';
    select * into strict quiesce
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_id = fence.quiesce_evidence_id
    for update;
    if fence.status is distinct from 'INSTALLING'
       or install_dispatch.provider_mutation_class is distinct from
         expected_mutation_class
       or install_dispatch.source_role is distinct from expected_source_role
       or install_dispatch.target_role is distinct from expected_target_role
       or current_outcome not in ('PROVIDER_MUTATING', 'OUTCOME_UNKNOWN')
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_INSTALL_RESULT_NOT_SETTLEABLE';
    end if;
  else
    select * into strict restore_dispatch
    from production_control.google_writer_provider_fence_abort_dispatches value
    where value.fence_id = fence.fence_id
      and value.dispatch_id = (input->>'dispatch_id')::uuid
    for update;
    selected_dispatch_id := restore_dispatch.dispatch_id;
    current_outcome := restore_dispatch.outcome_status;
    expected_mutation_class :=
      'DRIVE_LEGACY_PERMISSION_READER_TO_WRITER_V1';
    expected_source_role := 'reader';
    expected_target_role := 'writer';
    select * into strict quiesce
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_id = fence.restore_quiesce_evidence_id
    for update;
    if fence.status is distinct from 'ABORTING'
       or restore_dispatch.restore_quiesce_evidence_id is distinct from
         fence.restore_quiesce_evidence_id
       or restore_dispatch.provider_mutation_class is distinct from
         expected_mutation_class
       or restore_dispatch.source_role is distinct from expected_source_role
       or restore_dispatch.target_role is distinct from expected_target_role
       or current_outcome not in ('PROVIDER_MUTATING', 'OUTCOME_UNKNOWN')
       or pg_catalog.clock_timestamp() <
         fence.restore_global_writer_stop_active_at + interval '1810 seconds'
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESTORE_RESULT_NOT_SETTLEABLE';
    end if;
  end if;

  if quiesce.status is distinct from 'VERIFIED'
     or quiesce.purpose is distinct from fence.lifecycle_mode
     or quiesce.candidate_deployment_id is distinct from
       fence.candidate_deployment_id
     or quiesce.candidate_deployment_commit is distinct from
       fence.candidate_deployment_commit
     or quiesce.expires_at <= pg_catalog.clock_timestamp()
     or quiesce.owner_freeze_expires_at <= pg_catalog.clock_timestamp()
     or not exists (
       select 1
       from production_control.vercel_routing_rule_audit_bindings audit
       where audit.quiesce_evidence_id = quiesce.evidence_id
         and audit.routing_rule_global_invocation_quiescence_proved
         and audit.routing_rule_candidate_control_host_count = 2
         and audit.routing_rule_canonical_apex_safe_method_count = 3
         and audit.routing_rule_canonical_apex_safe_method_writer_route_count = 10
     )
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESULT_WAF_EVIDENCE_STALE';
  end if;

  if outcome_value <> 'OUTCOME_UNKNOWN' then
    if provider_observed is null
       or provider_observed < pg_catalog.clock_timestamp() - interval '5 seconds'
       or provider_observed > pg_catalog.clock_timestamp() + interval '30 seconds'
       or proof_value->>'workbookId' is distinct from fence.source_workbook_id
       or proof_value->>'fenceId' is distinct from fence.fence_id::text
       or proof_value->>'installRequestId' is distinct from
         fence.install_request_id::text
       or proof_value->>'providerMutationClass' is distinct from
         expected_mutation_class
       or proof_value->>'permissionManagementScope' is distinct from
         'https://www.googleapis.com/auth/drive.file'
       or coalesce(proof_value->>'legacyPermissionFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'legacyPrincipalFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'priorPermissionInventoryFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'currentPermissionInventoryFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'permissionIdentityFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'sharingCapabilityFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'dedicatedDriveIdentityFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'legacyDriveIdentityFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'priorAclFingerprint', '') !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'currentAclFingerprint', '') !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'priorLegacyEditCapabilityFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(proof_value->>'currentLegacyEditCapabilityFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or proof_value->'dedicatedCanShare' is distinct from 'true'::jsonb
       or proof_value->'writersCanShare' is distinct from 'true'::jsonb
       or proof_value->>'priorRole' is distinct from expected_source_role
       or proof_value->>'currentRole' is distinct from expected_target_role
       or proof_value->>'transitionIntentFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent_fingerprint
         else restore_dispatch.transition_intent_fingerprint end)
       or proof_value->>'legacyPermissionFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'legacyPermissionFingerprint'
         else restore_dispatch.transition_intent->>'legacyPermissionFingerprint' end)
       or proof_value->>'legacyPrincipalFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'legacyPrincipalFingerprint'
         else restore_dispatch.transition_intent->>'legacyPrincipalFingerprint' end)
       or proof_value->>'permissionIdentityFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'permissionIdentityFingerprint'
         else restore_dispatch.transition_intent->>'permissionIdentityFingerprint' end)
       or proof_value->>'sharingCapabilityFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'sharingCapabilityFingerprint'
         else restore_dispatch.transition_intent->>'sharingCapabilityFingerprint' end)
       or proof_value->>'dedicatedDriveIdentityFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'dedicatedDriveIdentityFingerprint'
         else restore_dispatch.transition_intent->>'dedicatedDriveIdentityFingerprint' end)
       or proof_value->>'legacyDriveIdentityFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'legacyDriveIdentityFingerprint'
         else restore_dispatch.transition_intent->>'legacyDriveIdentityFingerprint' end)
       or proof_value->>'priorPermissionInventoryFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'priorPermissionInventoryFingerprint'
         else restore_dispatch.transition_intent->>'priorPermissionInventoryFingerprint' end)
       or proof_value->>'currentPermissionInventoryFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'expectedTargetPermissionInventoryFingerprint'
         else restore_dispatch.transition_intent->>'expectedTargetPermissionInventoryFingerprint' end)
       or proof_value->>'priorAclFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'priorAclFingerprint'
         else restore_dispatch.transition_intent->>'priorAclFingerprint' end)
       or proof_value->>'priorLegacyEditCapabilityFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'priorLegacyEditCapabilityFingerprint'
         else restore_dispatch.transition_intent->>'priorLegacyEditCapabilityFingerprint' end)
       or proof_value->>'currentLegacyEditCapabilityFingerprint' is distinct from (case
         when direction_value = 'INSTALL'
           then install_dispatch.transition_intent->>'expectedTargetLegacyEditCapabilityFingerprint'
         else restore_dispatch.transition_intent->>'expectedTargetLegacyEditCapabilityFingerprint' end)
       or proof_value->>'schemaVersion' is distinct from
         'step12-production-google-drive-acl-transition-proof-v1'
       or proof_value->>'transitionPhase' is distinct from (case
         when direction_value = 'INSTALL' then 'INSTALL' else 'ABORT' end)
       or proof_value->'priorLegacyCanEdit' is distinct from
         (case when direction_value = 'INSTALL'
           then 'true'::jsonb else 'false'::jsonb end)
       or proof_value->'priorLegacyCanShare' is distinct from
         (case when direction_value = 'INSTALL'
           then 'true'::jsonb else 'false'::jsonb end)
       or proof_value->'currentLegacyCanEdit' is distinct from
         (case when direction_value = 'INSTALL'
           then 'false'::jsonb else 'true'::jsonb end)
       or proof_value->'currentLegacyCanShare' is distinct from
         (case when direction_value = 'INSTALL'
           then 'false'::jsonb else 'true'::jsonb end)
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_RESULT_PROOF_INVALID';
    end if;
  end if;

  insert into production_control.google_writer_provider_fence_acl_dispatch_results (
    result_id, result_request_id, fence_id, direction,
    install_dispatch_id, abort_dispatch_id, outcome_status,
    transition_proof, transition_proof_fingerprint, provider_observed_at,
    request_fingerprint, payload_hash, actor_id,
    authenticated_actor_fingerprint
  ) values (
    extensions.gen_random_uuid(), result_request_identifier, fence.fence_id,
    direction_value,
    case when direction_value = 'INSTALL' then selected_dispatch_id else null end,
    case when direction_value = 'RESTORE' then selected_dispatch_id else null end,
    outcome_value, proof_value,
    nullif(proof_fingerprint, ''), provider_observed,
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'authenticated_actor_fingerprint')
  ) returning * into inserted;

  if direction_value = 'INSTALL' then
    update production_control.google_writer_provider_fence_install_dispatches
    set outcome_status = outcome_value,
        transition_proof = proof_value,
        transition_proof_fingerprint = nullif(proof_fingerprint, ''),
        provider_observed_at = provider_observed,
        target_confirmed_at = case when outcome_value = 'TARGET_CONFIRMED'
          then pg_catalog.clock_timestamp() else null end,
        result_request_id = inserted.result_request_id,
        result_request_fingerprint = inserted.request_fingerprint,
        result_payload_hash = inserted.payload_hash,
        result_recorded_at = inserted.recorded_at
    where dispatch_id = selected_dispatch_id;
    if outcome_value = 'TARGET_CONFIRMED' then
      update production_control.google_writer_provider_fences
      set acl_reader_confirmed_at = inserted.recorded_at,
          acl_reader_transition_fingerprint = proof_fingerprint,
          updated_at = pg_catalog.clock_timestamp()
      where fence_id = fence.fence_id;
    end if;
  else
    update production_control.google_writer_provider_fence_abort_dispatches
    set outcome_status = outcome_value,
        transition_proof = proof_value,
        transition_proof_fingerprint = nullif(proof_fingerprint, ''),
        provider_observed_at = provider_observed,
        target_confirmed_at = case when outcome_value = 'TARGET_CONFIRMED'
          then pg_catalog.clock_timestamp() else null end,
        result_request_id = inserted.result_request_id,
        result_request_fingerprint = inserted.request_fingerprint,
        result_payload_hash = inserted.payload_hash,
        result_recorded_at = inserted.recorded_at
    where dispatch_id = selected_dispatch_id;
    if outcome_value = 'TARGET_CONFIRMED' then
      update production_control.google_writer_provider_fences
      set acl_writer_restored_at = inserted.recorded_at,
          acl_writer_restore_transition_fingerprint = proof_fingerprint,
          updated_at = pg_catalog.clock_timestamp()
      where fence_id = fence.fence_id;
    end if;
  end if;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result,
    details
  ) values (
    'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_' || direction_value || '_' ||
      outcome_value,
    'SCORING_AUTHORITY', '2026', inserted.actor_id,
    inserted.request_fingerprint,
    case when outcome_value = 'TARGET_CONFIRMED'
      then 'SUCCEEDED' else 'UNKNOWN' end,
    pg_catalog.jsonb_build_object(
      'fence_id', fence.fence_id,
      'dispatch_id', selected_dispatch_id,
      'result_id', inserted.result_id,
      'direction', direction_value,
      'outcome_status', outcome_value,
      'transition_proof_fingerprint', inserted.transition_proof_fingerprint,
      'provider_observed_at', inserted.provider_observed_at,
      'admission_reservation_active', true
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_GOOGLE_WRITER_PROVIDER_ACL_' || direction_value ||
      '_' || outcome_value,
    'fence_id', fence.fence_id,
    'result_id', inserted.result_id,
    'result_request_id', inserted.result_request_id,
    'direction', direction_value,
    'outcome_status', outcome_value,
    'transition_proof_fingerprint', inserted.transition_proof_fingerprint,
    'provider_observed_at', inserted.provider_observed_at,
    'recorded_at', inserted.recorded_at,
    'admission_reservation_active', true,
    'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.record_production_google_writer_acl_dispatch_result(input jsonb) OWNER TO postgres;

--
-- Name: record_production_google_writer_provider_fence_settlement(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_google_writer_provider_fence_settlement(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  stage_value text := pg_catalog.upper(coalesce(input->>'stage', ''));
  observation
    production_control.google_writer_provider_fence_settlement_observations%rowtype;
  next_eligible timestamptz;
  was_idempotent boolean;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if input->>'operation' is distinct from
       'RECORD_PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_SETTLEMENT'
     or stage_value not in (
       'ACL_READER_CONFIRMED', 'SETTLEMENT_READBACK_1'
     )
     or coalesce(input->>'fence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_GOOGLE_WRITER_PROVIDER_SETTLEMENT_INPUT_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select exists (
    select 1
    from production_control.google_writer_provider_fence_settlement_observations
    where observation_request_id =
      (input->>'observation_request_id')::uuid
  ) into was_idempotent;
  observation :=
    production_control.insert_google_writer_provider_fence_settlement_observation(
      (input->>'fence_id')::uuid, stage_value, input
    );
  next_eligible := case observation.stage
    when 'ACL_READER_CONFIRMED'
      then observation.recorded_at + interval '190 seconds'
    else observation.recorded_at + interval '10 seconds'
  end;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_GOOGLE_WRITER_PROVIDER_FENCE_' || observation.stage,
    'fence_id', observation.fence_id,
    'observation_id', observation.observation_id,
    'observation_request_id', observation.observation_request_id,
    'stage', observation.stage,
    'prior_observation_id', observation.prior_observation_id,
    'provider_observed_at', observation.provider_observed_at,
    'recorded_at', observation.recorded_at,
    'activation_revision', observation.activation_revision,
    'authority_generation_id', observation.authority_generation_id,
    'admission_generation_id', observation.admission_generation_id,
    'admission_revision', observation.admission_revision,
    'next_stage_eligible_at', next_eligible,
    'required_wait_seconds', case observation.stage
      when 'ACL_READER_CONFIRMED' then 190 else 10 end,
    'remaining_wait_seconds', greatest(
      0, pg_catalog.ceil(extract(epoch from
        (next_eligible - pg_catalog.now())))::integer
    ),
    'protection_set_fingerprint', observation.protection_set_fingerprint,
    'structural_canary_fingerprint',
      observation.structural_canary_fingerprint,
    'permission_inventory_fingerprint',
      observation.permission_inventory_fingerprint,
    'admission_reservation_active', true,
    'idempotent', was_idempotent
  );
end;
$_$;


ALTER FUNCTION public.record_production_google_writer_provider_fence_settlement(input jsonb) OWNER TO postgres;

--
-- Name: record_production_manual_handicap_source_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_manual_handicap_source_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text; actor_player text; actor_auth uuid; request_id uuid; declared_hash text; database_hash text;
  player_value text; identity_value uuid; expected_pointer bigint; current_value numeric; low_value numeric; low_date_value date;
  active_identity production_control.player_external_identities_v1%rowtype; source_pointer production_control.handicap_source_current_v1%rowtype;
  prior production_control.handicap_source_operation_receipts_v1%rowtype; observation_value uuid:=extensions.gen_random_uuid(); event_value uuid:=extensions.gen_random_uuid(); evidence_hash text; response_value jsonb;
begin
  target:=production_control.assert_handicap_source_runtime_v1(input); actor_player:=pg_catalog.upper(pg_catalog.btrim(input#>>'{authorization,player_id}')); actor_auth:=(input#>>'{authorization,auth_user_id}')::uuid; declared_hash:=pg_catalog.lower(pg_catalog.btrim(coalesce(input->>'request_payload_hash','')));
  if input->>'operation' is distinct from 'RECORD_PRODUCTION_MANUAL_HANDICAP_SOURCE_V1' or coalesce(input->>'operation_request_id','') !~ '^[0-9a-fA-F-]{36}$' or coalesce(input->>'expected_identity_id','') !~ '^[0-9a-fA-F-]{36}$' or coalesce(input->>'expected_pointer_revision','') !~ '^[0-9]+$' or coalesce(input->>'current_index','') !~ '^-?[0-9]+(\.[0-9]+)?$' or coalesce(input->>'low_index','') !~ '^-?[0-9]+(\.[0-9]+)?$' or coalesce(input->>'low_index_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or input->>'provenance' is distinct from 'DIRECTOR_MANUAL' or declared_hash !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='PRODUCTION_HANDICAP_SOURCE_INPUT_INVALID'; end if;
  request_id:=(input->>'operation_request_id')::uuid; player_value:=pg_catalog.upper(input->>'player_id'); identity_value:=(input->>'expected_identity_id')::uuid; expected_pointer:=(input->>'expected_pointer_revision')::bigint; current_value:=(input->>'current_index')::numeric; low_value:=(input->>'low_index')::numeric; low_date_value:=(input->>'low_index_date')::date;
  database_hash:=production_control.handicap_source_hash_v1(pg_catalog.jsonb_build_object('operation','RECORD_MANUAL_OBSERVATION','playerId',player_value,'identityId',identity_value,'expectedPointerRevision',expected_pointer,'currentIndex',current_value,'lowIndex',low_value,'lowIndexDate',low_date_value,'actorPlayerId',actor_player,'actorAuthUserId',actor_auth));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('production-handicap-source:'||target||':'||player_value,0));
  select value.* into prior from production_control.handicap_source_operation_receipts_v1 value where value.tournament_id=target and value.operation_request_id=request_id;
  if found then if prior.declared_request_payload_hash=declared_hash and prior.database_request_payload_hash=database_hash then return prior.response||pg_catalog.jsonb_build_object('idempotent',true); end if; raise exception using errcode='23505',message='PRODUCTION_HANDICAP_SOURCE_IDEMPOTENCY_CONFLICT'; end if;
  select value.* into active_identity from production_control.player_external_identities_v1 value where value.identity_id=identity_value and value.player_id=player_value and value.provider='GHIN' and value.status='VERIFIED' for share;
  if active_identity.identity_id is null then raise exception using errcode='40001',message='PRODUCTION_GHIN_IDENTITY_STALE'; end if;
  select value.* into source_pointer from production_control.handicap_source_current_v1 value where value.tournament_id=target and value.player_id=player_value and value.provider='GHIN' for update;
  if coalesce(source_pointer.pointer_revision,0) <> expected_pointer then raise exception using errcode='40001',message='PRODUCTION_HANDICAP_SOURCE_PREDECESSOR_STALE'; end if;
  evidence_hash:=production_control.handicap_source_hash_v1(pg_catalog.jsonb_build_object('provider','GHIN','identityId',identity_value,'playerId',player_value,'currentIndex',current_value,'lowIndex',low_value,'lowIndexDate',low_date_value,'provenance','DIRECTOR_MANUAL'));
  insert into production_control.handicap_source_observations_v1(observation_id,tournament_id,player_id,identity_id,provider,current_index,low_index,low_index_date,provenance,status,source_evidence_fingerprint,created_by_player_id,created_by_auth_user_id)
  values(observation_value,target,player_value,identity_value,'GHIN',current_value,low_value,low_date_value,'DIRECTOR_MANUAL','ACCEPTED',evidence_hash,actor_player,actor_auth);
  insert into production_control.handicap_source_current_v1(tournament_id,player_id,provider,observation_id,pointer_revision,source_status,updated_by_player_id,updated_by_auth_user_id)
  values(target,player_value,'GHIN',observation_value,expected_pointer+1,'CURRENT',actor_player,actor_auth)
  on conflict(tournament_id,player_id,provider) do update set observation_id=excluded.observation_id,pointer_revision=excluded.pointer_revision,source_status='CURRENT',updated_by_player_id=excluded.updated_by_player_id,updated_by_auth_user_id=excluded.updated_by_auth_user_id,updated_at=pg_catalog.clock_timestamp();
  response_value:=pg_catalog.jsonb_build_object('ok',true,'code','PRODUCTION_HANDICAP_SOURCE_RECORDED','idempotent',false,'playerId',player_value,'observationId',observation_value,'pointerRevision',expected_pointer+1,'currentIndex',current_value::text,'lowIndex',low_value::text,'lowIndexDate',low_date_value,'hybrid',production_control.hybrid_handicap_v1(current_value,low_value)::text,'provenance','DIRECTOR_MANUAL','eventId',event_value);
  insert into production_control.handicap_source_audit_events_v1(event_id,tournament_id,action,player_id,identity_id,observation_id,actor_player_id,actor_auth_user_id,operation_request_id,before_state,after_state) values(event_value,target,'MANUAL_SOURCE_RECORDED',player_value,identity_value,observation_value,actor_player,actor_auth,request_id,case when source_pointer.observation_id is null then '{}'::jsonb else pg_catalog.jsonb_build_object('observationId',source_pointer.observation_id,'pointerRevision',source_pointer.pointer_revision) end,pg_catalog.jsonb_build_object('observationId',observation_value,'pointerRevision',expected_pointer+1,'evidenceFingerprint',evidence_hash));
  perform production_control.handicap_source_receipt_v1(target,'RECORD_MANUAL_OBSERVATION',request_id,declared_hash,database_hash,actor_player,actor_auth,response_value); return response_value;
end;
$_$;


ALTER FUNCTION public.record_production_manual_handicap_source_v1(input jsonb) OWNER TO postgres;

--
-- Name: record_production_participant_first_login_cleanup(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_participant_first_login_cleanup(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth', 'pg_temp'
    AS $$
declare claim participant_identity.production_participant_enrollment_claims%rowtype;
declare target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
declare reason text := upper(btrim(coalesce(input->>'safe_reason', 'AUTH_USER_PROVISIONING_FAILED')));
begin
  perform production_control.assert_production_participant_identity_cutover();
  if reason not in ('AUTH_USER_PROVISIONING_FAILED','AUTH_USER_DELETE_CONFIRMED','AUTH_USER_DELETE_FAILED') then
    reason := 'AUTH_USER_PROVISIONING_FAILED';
  end if;
  select * into claim from participant_identity.production_participant_enrollment_claims
    where claim_id = nullif(input->>'claim_id', '')::uuid for update;
  if not found then return jsonb_build_object('ok', true, 'recorded', false); end if;
  if claim.status = 'CONSUMED' then
    raise exception using errcode = '42501', message = 'PRODUCTION_PARTICIPANT_ENROLLMENT_ALREADY_CONSUMED';
  end if;
  update participant_identity.production_participant_enrollment_claims set
    status = case when reason = 'AUTH_USER_DELETE_FAILED' then 'CLEANUP_REQUIRED' else 'CANCELLED' end,
    auth_user_id = case when reason = 'AUTH_USER_DELETE_FAILED' then target_user else null end,
    cleanup_reason = reason, cancelled_at = case when reason = 'AUTH_USER_DELETE_FAILED' then null else now() end,
    updated_at = now()
  where claim_id = claim.claim_id;
  return jsonb_build_object('ok', true, 'recorded', true,
    'cleanupRequired', reason = 'AUTH_USER_DELETE_FAILED');
end;
$$;


ALTER FUNCTION public.record_production_participant_first_login_cleanup(input jsonb) OWNER TO postgres;

--
-- Name: record_production_participant_logout(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_participant_logout(target_auth_user_id uuid, target_tournament_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'pg_temp'
    AS $$
declare target_player text;
begin
  perform production_control.assert_production_participant_identity_cutover();
  if btrim(coalesce(target_tournament_id, '')) <> '2026' then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_SCOPE_INVALID');
  end if;
  select player_id into target_player from participant_identity.user_player_links
    where auth_user_id = target_auth_user_id and status = 'ACTIVE';
  if found then
    insert into participant_identity.identity_audit_events (
      event_type, tournament_id, auth_user_id, player_id, actor_name, safe_metadata
    ) values ('PRODUCTION_PARTICIPANT_AUTH_LOGOUT', '2026', target_auth_user_id,
      target_player, 'production-participant-auth', jsonb_build_object('sessionTokenStored', false));
  end if;
  return jsonb_build_object('ok', true, 'recorded', found);
end;
$$;


ALTER FUNCTION public.record_production_participant_logout(target_auth_user_id uuid, target_tournament_id text) OWNER TO postgres;

--
-- Name: record_production_participant_otp_delivery(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_participant_otp_delivery(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'pg_temp'
    AS $$
declare request uuid := nullif(input->>'request_id', '')::uuid;
declare succeeded boolean := coalesce((input->>'succeeded')::boolean, false);
declare requested_reason text := upper(btrim(coalesce(input->>'safe_reason', 'AUTH_EMAIL_SEND_FAILED')));
begin
  perform production_control.assert_production_participant_identity_cutover();
  if requested_reason not in (
    'AUTH_CAPTCHA_REJECTED','AUTH_SUPABASE_RATE_LIMITED','AUTH_SMTP_PROVIDER_RATE_LIMITED',
    'AUTH_EMAIL_RATE_LIMITED_UNKNOWN_SOURCE','AUTH_EMAIL_CONFIGURATION_FAILED',
    'AUTH_SMTP_PROVIDER_REJECTED','AUTH_EMAIL_SERVICE_UNAVAILABLE','AUTH_EMAIL_SEND_FAILED'
  ) then requested_reason := 'AUTH_EMAIL_SEND_FAILED'; end if;
  update participant_identity.participant_auth_otp_attempts set
    status = case when succeeded then 'SENT' else 'DELIVERY_FAILED' end,
    safe_reason = case when succeeded then 'DELIVERY_ACCEPTED' else requested_reason end,
    request_duration_ms = greatest(0, coalesce((input->>'duration_ms')::integer, 0)),
    sent_at = case when succeeded then now() else sent_at end, updated_at = now()
  where request_id = request and status = 'AUTHORIZED';
  if not found then raise exception using errcode = 'P0001', message = 'PRODUCTION_PARTICIPANT_OTP_NOT_AUTHORIZED'; end if;
  return jsonb_build_object('ok', true, 'requestId', request,
    'status', case when succeeded then 'SENT' else 'DELIVERY_FAILED' end);
end;
$$;


ALTER FUNCTION public.record_production_participant_otp_delivery(input jsonb) OWNER TO postgres;

--
-- Name: record_production_participant_otp_verification(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_participant_otp_verification(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'pg_temp'
    AS $$
declare request uuid := nullif(input->>'request_id', '')::uuid;
declare target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
declare succeeded boolean := coalesce((input->>'succeeded')::boolean, false);
begin
  perform production_control.assert_production_participant_identity_cutover();
  if succeeded then
    return production_control.certify_production_participant_otp(
      request, target_user, greatest(0, coalesce((input->>'duration_ms')::integer, 0)), false);
  end if;
  update participant_identity.participant_auth_otp_attempts set
    status = 'VERIFICATION_FAILED', safe_reason = 'INVALID_OR_EXPIRED_CODE',
    verification_duration_ms = greatest(0, coalesce((input->>'duration_ms')::integer, 0)), updated_at = now()
  where request_id = request and status = 'SENT';
  return jsonb_build_object('ok', true, 'status', 'VERIFICATION_FAILED');
end;
$$;


ALTER FUNCTION public.record_production_participant_otp_verification(input jsonb) OWNER TO postgres;

--
-- Name: record_production_scoring_external_fence_evidence(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_scoring_external_fence_evidence(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  verification
    production_control.google_writer_provider_fence_verifications%rowtype;
  evidence production_control.scoring_external_fence_evidence%rowtype;
  captured timestamptz := pg_catalog.clock_timestamp();
  legacy_fingerprint text;
  legacy_count integer;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  if input->>'operation' is distinct from
       'RECORD_PRODUCTION_SCORING_EXTERNAL_FENCE_EVIDENCE'
     or coalesce(input->>'provider_fence_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'provider_fence_verification_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_EXTERNAL_ACL_FENCE_EXACT_EVIDENCE_REQUIRED';
  end if;
  existing := production_control.lookup_cutover_receipt(
    'RECORD_SCORING_EXTERNAL_FENCE_EVIDENCE', input
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  existing := production_control.lookup_cutover_receipt(
    'RECORD_SCORING_EXTERNAL_FENCE_EVIDENCE', input
  );
  if existing is not null then return existing; end if;
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into strict fence
  from production_control.google_writer_provider_fences value
  where value.fence_id = (input->>'provider_fence_id')::uuid
  for update;
  select * into strict verification
  from production_control.google_writer_provider_fence_verifications value
  where value.verification_id =
      (input->>'provider_fence_verification_id')::uuid
    and value.fence_id = fence.fence_id;
  select * into strict quiesce
  from production_control.vercel_writer_quiesce_evidence value
  where value.evidence_id = verification.quiesce_evidence_id;
  perform production_control.assert_current_google_writer_provider_fence(
    fence.fence_id, verification.verification_id,
    pg_catalog.lower(input->>'deployment_commit'), true
  );
  if activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or (fence.lifecycle_mode = 'CUTOVER' and (
       gate.admission_deployment_id is distinct from input->>'deployment_id'
       or activation.expected_deployment_commit is distinct from
         pg_catalog.lower(input->>'deployment_commit')
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       input->>'deployment_id' is distinct from fence.candidate_deployment_id
       or pg_catalog.lower(input->>'deployment_commit') is distinct from
         fence.candidate_deployment_commit
     ))
     or activation.active_google_writer_provider_fence_id is distinct from
       fence.fence_id
     or activation.active_google_writer_provider_verification_id is distinct from
       verification.verification_id
     or activation.active_vercel_quiesce_evidence_id is distinct from
       quiesce.evidence_id
     or gate.google_writer_provider_fence_id is distinct from fence.fence_id
     or gate.google_writer_provider_verification_id is distinct from
       verification.verification_id
     or gate.admission_state is distinct from 'OPEN'
     or (fence.lifecycle_mode = 'CUTOVER' and (
       activation.state is distinct from 'GOOGLE_LEASE_ARMED'
       or gate.state is distinct from 'OPEN'
       or not gate.admission_protocol_enforced
     ))
     or (fence.lifecycle_mode = 'REHEARSAL' and (
       activation.state is distinct from 'DORMANT'
       or gate.state is distinct from 'PAUSED'
       or gate.admission_protocol_enforced
     ))
  then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_SCORING_EXTERNAL_ACL_FENCE_REVISION_CONFLICT';
  end if;

  legacy_fingerprint :=
    production_control.scoring_admission_legacy_set_fingerprint();
  select pg_catalog.count(*)::integer into legacy_count
  from scoring_authority.scoring_ingress_leases lease
  where lease.tournament_id = '2026'
    and lease.protocol_version = 'LEGACY_V1';
  insert into production_control.scoring_external_fence_evidence (
    request_fingerprint, deployment_commit, deployment_id,
    vercel_project_id, source_workbook_id,
    provider_evidence_fingerprint, deployment_scope_fingerprint,
    google_credential_scope_fingerprint, writer_coverage_fingerprint,
    legacy_lease_set_fingerprint, legacy_lease_count,
    legacy_deployments_fenced, legacy_google_credentials_fenced,
    non_owner_manual_google_scoring_fenced,
    owner_override_operationally_frozen,
    captured_at, expires_at, actor_id, quiesce_evidence_id,
    provider_fence_id, provider_fence_verification_id
  ) values (
    pg_catalog.lower(input->>'request_fingerprint'),
    pg_catalog.lower(input->>'deployment_commit'), input->>'deployment_id',
    'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU',
    '1umqPxiQxN9_jwmsD7IcVTzqxPmMycYLlrY_gm31l5U4',
    production_control.structured_evidence_fingerprint(
      pg_catalog.jsonb_build_object(
        'contractVersion', verification.acl_contract_version,
        'fenceId', fence.fence_id,
        'installDispatchId', verification.install_dispatch_id,
        'aclTransitionProofFingerprint',
          verification.acl_transition_proof_fingerprint,
        'providerFingerprint', verification.provider_fingerprint,
        'aclFingerprint', verification.acl_fingerprint,
        'legacyEditCapabilityFingerprint',
          verification.legacy_edit_capability_fingerprint
      )
    ),
    quiesce.deployment_scope_fingerprint,
    fence.legacy_credential_generation_fingerprint,
    verification.acl_transition_proof_fingerprint,
    legacy_fingerprint, legacy_count, true, true, true, true,
    captured, least(captured + interval '2100 seconds',
      verification.expires_at, quiesce.expires_at,
      quiesce.owner_freeze_expires_at),
    pg_catalog.left(input->>'actor_id', 160), quiesce.evidence_id,
    fence.fence_id, verification.verification_id
  ) returning * into evidence;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_SCORING_EXTERNAL_ACL_FENCE_EVIDENCE_RECORDED',
    'evidence_id', evidence.evidence_id,
    'deployment_id', evidence.deployment_id,
    'deployment_commit', evidence.deployment_commit,
    'captured_at', evidence.captured_at,
    'expires_at', evidence.expires_at,
    'provider_fence_id', evidence.provider_fence_id,
    'provider_fence_verification_id', evidence.provider_fence_verification_id,
    'quiesce_evidence_id', evidence.quiesce_evidence_id,
    'external_google_writer_fence_centrally_enforced', true,
    'acl_contract_version', 'DRIVE_ACL_V2',
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'RECORD_SCORING_EXTERNAL_FENCE_EVIDENCE', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.record_production_scoring_external_fence_evidence(input jsonb) OWNER TO postgres;

--
-- Name: record_production_step11_scoring_rehearsal_evidence(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_step11_scoring_rehearsal_evidence(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_rehearsal', 'production_control', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  run production_rehearsal.scoring_runs%rowtype;
  existing_event production_rehearsal.evidence_events%rowtype;
  event_type_value text := upper(btrim(coalesce(input->>'event_type','')));
  evidence_value jsonb := input->'evidence';
  evidence_hash text;
  affected_rows integer;
begin
  run := production_rehearsal.assert_run(input);
  evidence_hash := encode(extensions.digest(evidence_value::text,'sha256'),'hex');
  if jsonb_typeof(evidence_value) <> 'object'
     or (nullif(btrim(coalesce(input->>'evidence_fingerprint','')),'') is not null
       and lower(btrim(input->>'evidence_fingerprint')) <> evidence_hash)
     or coalesce((evidence_value->>'externalGoogleWrites')::integer,0) <> 0
     or coalesce((evidence_value->>'live2026Writes')::integer,0) <> 0 then
    raise exception using errcode = '22023', message = 'PRODUCTION_STEP11_EVIDENCE_INVALID';
  end if;
  if event_type_value in ('AUTHORITY_EPOCH_COMMITTED','MATCH_MARKED_LIVE','SCORING_LOCKED',
      'SCORING_UNLOCKED','SCORING_ACCESS_ENABLED','SCORING_ACCESS_REVOKED',
      'HOLE_SCORE_UPSERTED','MATCH_FINALIZED','MATCH_REOPENED')
     and run.synthetic_tournament_id <> evidence_value->>'tournamentId' then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_SYNTHETIC_TARGET_REQUIRED';
  end if;
  select * into existing_event
  from production_rehearsal.evidence_events value
  where value.run_id = run.run_id
    and value.event_type = event_type_value
    and value.mutation_key = coalesce(nullif(input->>'mutation_key',''),'');
  if found then
    if existing_event.evidence_fingerprint <> evidence_hash
       or existing_event.evidence <> evidence_value then
      raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_EVIDENCE_IDEMPOTENCY_CONFLICT';
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'runId',run.run_id,
      'eventType',event_type_value,'externalGoogleWrites',0,'live2026Writes',0);
  end if;
  if event_type_value = 'AUTHORITY_EPOCH_PREPARED'
     and (run.status <> 'PREPARED' or run.rehearsal_authority <> 'GOOGLE'
       or run.ingress_state <> 'PAUSED') then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_EPOCH_PREPARE_STATE_REQUIRED';
  elsif event_type_value = 'AUTHORITY_EPOCH_COMMITTED'
     and (run.status <> 'PREPARED' or run.rehearsal_authority <> 'GOOGLE'
       or run.ingress_state <> 'PAUSED'
       or not exists (
         select 1 from production_rehearsal.evidence_events prior
         where prior.run_id = run.run_id
           and prior.event_type = 'AUTHORITY_EPOCH_PREPARED'
           and prior.mutation_key = coalesce(nullif(input->>'mutation_key',''),'')
       )) then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_EPOCH_COMMIT_STATE_REQUIRED';
  elsif event_type_value in ('MATCH_MARKED_LIVE','SCORING_LOCKED','SCORING_UNLOCKED',
      'SCORING_ACCESS_ENABLED','SCORING_ACCESS_REVOKED','HOLE_SCORE_UPSERTED',
      'MATCH_FINALIZED','MATCH_REOPENED','MIRROR_CLAIMED','MIRROR_RETRYABLE',
      'MIRROR_CHECKPOINTED','ARCHIVE_CLAIMED','ARCHIVE_RETRYABLE','ARCHIVE_CHECKPOINTED')
     and (run.status <> 'ACTIVE' or run.rehearsal_authority <> 'SUPABASE'
       or run.ingress_state <> 'OPEN') then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_ACTIVE_REHEARSAL_REQUIRED';
  elsif event_type_value = 'ROLLBACK_RECONCILED'
     and (run.status <> 'ACTIVE' or run.rehearsal_authority <> 'SUPABASE'
       or run.ingress_state <> 'OPEN') then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_ACTIVE_ROLLBACK_REQUIRED';
  elsif event_type_value = 'CLEANUP_CERTIFIED'
     and (run.status <> 'ROLLED_BACK' or run.rehearsal_authority <> 'GOOGLE'
       or run.ingress_state <> 'PAUSED') then
    raise exception using errcode = '42501', message = 'PRODUCTION_STEP11_ROLLBACK_REQUIRED';
  end if;
  insert into production_rehearsal.evidence_events (
    run_id, event_type, mutation_key, evidence, evidence_fingerprint
  ) values (
    run.run_id, event_type_value, coalesce(nullif(input->>'mutation_key',''),''), evidence_value, evidence_hash
  ) on conflict (run_id, event_type, mutation_key) do nothing;
  get diagnostics affected_rows = row_count;
  if affected_rows = 0 then
    select * into strict existing_event
    from production_rehearsal.evidence_events value
    where value.run_id = run.run_id
      and value.event_type = event_type_value
      and value.mutation_key = coalesce(nullif(input->>'mutation_key',''),'');
    if existing_event.evidence_fingerprint <> evidence_hash
       or existing_event.evidence <> evidence_value then
      raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_EVIDENCE_IDEMPOTENCY_CONFLICT';
    end if;
    return jsonb_build_object('ok',true,'idempotent',true,'runId',run.run_id,
      'eventType',event_type_value,'externalGoogleWrites',0,'live2026Writes',0);
  end if;
  if event_type_value = 'AUTHORITY_EPOCH_COMMITTED' then
    update production_rehearsal.scoring_runs set status='ACTIVE',
      rehearsal_authority='SUPABASE', ingress_state='OPEN'
    where run_id=run.run_id and status='PREPARED' and rehearsal_authority='GOOGLE'
      and ingress_state='PAUSED' and unresolved_client_queues=0;
    get diagnostics affected_rows = row_count;
    if affected_rows <> 1 then
      raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_EPOCH_COMMIT_FAILED';
    end if;
  elsif event_type_value = 'ROLLBACK_RECONCILED' then
    if coalesce((evidence_value->>'unresolved')::integer,-1) <> 0
       or coalesce((evidence_value->>'duplicates')::integer,-1) <> 0
       or coalesce((evidence_value->>'lost')::integer,-1) <> 0
       or evidence_value->>'finalAuthorityState' <> 'GOOGLE'
       or evidence_value->>'finalSupabaseFingerprint'
          <> evidence_value->>'finalRollbackTargetFingerprint' then
      raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_ROLLBACK_RECONCILIATION_FAILED';
    end if;
    update production_rehearsal.scoring_runs set status='ROLLED_BACK',
      rehearsal_authority='GOOGLE', ingress_state='PAUSED'
    where run_id=run.run_id and status='ACTIVE';
    get diagnostics affected_rows = row_count;
    if affected_rows <> 1 then
      raise exception using errcode = '40001', message = 'PRODUCTION_STEP11_ROLLBACK_COMMIT_FAILED';
    end if;
  end if;
  return jsonb_build_object('ok',true,'runId',run.run_id,'eventType',event_type_value,
    'externalGoogleWrites',0,'live2026Writes',0);
end;
$$;


ALTER FUNCTION public.record_production_step11_scoring_rehearsal_evidence(input jsonb) OWNER TO postgres;

--
-- Name: record_production_vercel_writer_critical_waf_dispatch_result(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_vercel_writer_critical_waf_dispatch_result(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  dispatch production_control.vercel_writer_critical_waf_dispatches%rowtype;
  epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  observation production_control.vercel_writer_critical_waf_observations%rowtype;
  baseline_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  signed_result production_control.vercel_writer_critical_waf_dispatch_results%rowtype;
  prior_signed_result
    production_control.vercel_writer_critical_waf_dispatch_results%rowtype;
  verified_dispatch_result jsonb := input->'verified_dispatch_result';
  verified_waf_evidence jsonb := input->'verified_waf_evidence';
  outcome_value text;
  result_fingerprint_value text;
  expected_stage text;
  payload_hash_value text := production_control.cutover_payload_hash(input);
  provider_observed timestamptz;
  attested timestamptz;
  expires timestamptz;
begin
  if input->>'operation' is distinct from
       'RECORD_PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_DISPATCH_RESULT'
     or coalesce(input->>'dispatch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or (
       pg_catalog.jsonb_typeof(verified_dispatch_result) is distinct from
         'object'
       and pg_catalog.jsonb_typeof(verified_waf_evidence) is distinct from
         'object'
     )
     or (
       pg_catalog.jsonb_typeof(verified_dispatch_result) = 'object'
       and pg_catalog.jsonb_typeof(verified_waf_evidence) = 'object'
     )
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_RESULT_INPUT_INVALID';
  end if;

  if pg_catalog.jsonb_typeof(verified_dispatch_result) = 'object' then
    if (
       select pg_catalog.count(*)
         from pg_catalog.jsonb_object_keys(verified_dispatch_result)
       ) <> 56
       or not (verified_dispatch_result ?& array[
         'schemaVersion', 'dispatchResultId', 'dispatchId',
         'dispatchRequestId', 'dispatchStep', 'wafEpochId',
         'transitionRequestId', 'requestFingerprint', 'purpose',
         'transitionMode',
         'projectId', 'teamId', 'candidateAliasOrigin',
         'candidateImmutableOrigin', 'candidateDeploymentId',
         'candidateCommitSha', 'candidateDeploymentTarget',
         'baselineEvidenceId',
         'baselineConfigurationVersion', 'baselineConfigurationEtag',
         'baselineConfigurationIdentityFingerprint',
         'baselineSemanticFingerprint',
         'baselineOrderedCustomRulesFingerprint',
         'baselineSourceVersionReadFingerprint', 'providerIntentFingerprint',
         'runOwnedRuleName', 'runOwnedRuleNonce', 'runOwnedRuleFingerprint',
         'runOwnedInsertDocumentFingerprint', 'outcomeStatus',
         'providerResponseObserved', 'providerResponseStatus',
         'providerResponseFingerprint',
         'providerReadbackFingerprint',
         'activeSemanticConfiguration',
         'activeSemanticConfigurationFingerprint', 'activeCustomRuleCount',
         'activePendingDraftPresent', 'draftSemanticConfiguration',
         'draftSemanticConfigurationFingerprint',
         'draftOrderedCustomRulesFingerprint', 'draftConfigurationVersion',
         'draftConfigurationIdentityFingerprint', 'draftCustomRuleCount',
         'pendingDraftChangeCount', 'providerAssignedRuleId',
         'runOwnedProviderRuleDocumentFingerprint',
         'runOwnedRulePrecedence', 'criticalWindowContractFingerprint',
         'providerObservedAt', 'attestedAt', 'expiresAt',
         'evidenceFingerprint', 'signerKeyFingerprint', 'signerKeyVersion',
         'signatureVerified'
       ]::text[])
       or verified_dispatch_result->>'schemaVersion' is distinct from
         'bagger-vercel-waf-rule-insert-dispatch-result-v3'
       or verified_dispatch_result->'signatureVerified' is distinct from
         'true'::jsonb
       or coalesce(verified_dispatch_result->>'dispatchResultId', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(verified_dispatch_result->>'dispatchId', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(verified_dispatch_result->>'dispatchRequestId', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(verified_dispatch_result->>'wafEpochId', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(verified_dispatch_result->>'transitionRequestId', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or verified_dispatch_result->>'dispatchStep' not in (
         'CRITICAL_RULE_INSERT', 'CRITICAL_DRAFT_ACTIVATE',
         'BASELINE_VERSION_ACTIVATE'
       )
       or pg_catalog.upper(coalesce(
         verified_dispatch_result->>'transitionMode', ''
       )) not in ('REHEARSAL', 'CUTOVER', 'ROLLBACK')
       or coalesce(verified_dispatch_result->>'candidateDeploymentId', '')
         !~ '^dpl_[A-Za-z0-9]{8,64}$'
       or coalesce(verified_dispatch_result->>'candidateCommitSha', '')
         !~ '^[0-9a-f]{40}$'
       or verified_dispatch_result->>'candidateDeploymentTarget' is distinct
         from 'PREVIEW'
       or verified_dispatch_result->>'outcomeStatus' not in (
         'TARGET_CONFIRMED', 'OUTCOME_UNKNOWN', 'PROVIDER_REJECTED'
       )
       or pg_catalog.jsonb_typeof(
         verified_dispatch_result->'providerResponseObserved'
       ) is distinct from 'boolean'
       or (verified_dispatch_result->>'outcomeStatus' = 'PROVIDER_REJECTED'
         and (verified_dispatch_result->'providerResponseObserved'
               is distinct from 'true'::jsonb
           or pg_catalog.jsonb_typeof(
           verified_dispatch_result->'providerResponseStatus'
         ) is distinct from 'number'
           or coalesce(
           verified_dispatch_result->>'providerResponseStatus', ''
         ) !~ '^[45][0-9]{2}$'))
       or (verified_dispatch_result->>'outcomeStatus' <>
             'PROVIDER_REJECTED'
         and verified_dispatch_result->'providerResponseStatus' is distinct
           from 'null'::jsonb)
       or (verified_dispatch_result->>'outcomeStatus' = 'OUTCOME_UNKNOWN'
         and verified_dispatch_result->'providerResponseObserved'
           is distinct from 'false'::jsonb)
       or coalesce(verified_dispatch_result->>'requestFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(verified_dispatch_result->>'evidenceFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(verified_dispatch_result->>'signerKeyFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or verified_dispatch_result->>'signerKeyVersion' is distinct from
         'STEP11_6_VERCEL_ATTESTER_V1'
       or coalesce(verified_dispatch_result->>'providerIntentFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(verified_dispatch_result->>'runOwnedRuleFingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(
         verified_dispatch_result->>'runOwnedInsertDocumentFingerprint', ''
       ) !~ '^[0-9a-f]{64}$'
       or coalesce(
         verified_dispatch_result->>'baselineSemanticFingerprint', ''
       ) !~ '^[0-9a-f]{64}$'
       or coalesce(
         verified_dispatch_result->>'baselineOrderedCustomRulesFingerprint', ''
       ) !~ '^[0-9a-f]{64}$'
       or coalesce(
         verified_dispatch_result->>'baselineSourceVersionReadFingerprint', ''
       ) !~ '^[0-9a-f]{64}$'
       or coalesce(verified_dispatch_result->>'providerObservedAt', '') = ''
       or coalesce(verified_dispatch_result->>'attestedAt', '') = ''
       or coalesce(verified_dispatch_result->>'expiresAt', '') = ''
    then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_SIGNED_RESULT_INVALID';
    end if;
    outcome_value := verified_dispatch_result->>'outcomeStatus';
    result_fingerprint_value :=
      pg_catalog.lower(verified_dispatch_result->>'evidenceFingerprint');
    provider_observed :=
      (verified_dispatch_result->>'providerObservedAt')::timestamptz;
    attested := (verified_dispatch_result->>'attestedAt')::timestamptz;
    expires := (verified_dispatch_result->>'expiresAt')::timestamptz;
  else
    outcome_value := 'TARGET_CONFIRMED';
    result_fingerprint_value :=
      pg_catalog.lower(verified_waf_evidence->>'evidenceFingerprint');
    provider_observed :=
      (verified_waf_evidence->>'providerObservedAt')::timestamptz;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict dispatch
  from production_control.vercel_writer_critical_waf_dispatches value
  where value.dispatch_id = (input->>'dispatch_id')::uuid
  for update;
  select * into strict epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = dispatch.epoch_id
  for update;
  select * into strict baseline_observation
  from production_control.vercel_writer_critical_waf_observations value
  where value.observation_id = epoch.baseline_observation_id;

  if pg_catalog.jsonb_typeof(verified_dispatch_result) = 'object' then
    if (verified_dispatch_result->>'dispatchId')::uuid is distinct from
         dispatch.dispatch_id
       or (verified_dispatch_result->>'dispatchRequestId')::uuid is distinct
         from dispatch.dispatch_request_id
       or verified_dispatch_result->>'dispatchStep' is distinct from
         dispatch.dispatch_step
       or (verified_dispatch_result->>'wafEpochId')::uuid is distinct from
         epoch.epoch_id
       or (verified_dispatch_result->>'transitionRequestId')::uuid is distinct
         from dispatch.transition_request_id
       or verified_dispatch_result->>'purpose' is distinct from epoch.purpose
       or verified_dispatch_result->>'transitionMode' is distinct from
         epoch.transition_mode
       or verified_dispatch_result->>'projectId' is distinct from
         epoch.vercel_project_id
       or verified_dispatch_result->>'teamId' is distinct from
         epoch.vercel_team_id
       or pg_catalog.lower(
         verified_dispatch_result->>'candidateAliasOrigin'
       ) is distinct from epoch.candidate_alias_origin
       or pg_catalog.lower(
         verified_dispatch_result->>'candidateImmutableOrigin'
       ) is distinct from epoch.candidate_immutable_origin
       or verified_dispatch_result->>'candidateDeploymentId' is distinct from
         epoch.candidate_deployment_id
       or pg_catalog.lower(verified_dispatch_result->>'candidateCommitSha')
         is distinct from epoch.candidate_deployment_commit
       or verified_dispatch_result->>'candidateDeploymentTarget' is distinct
         from epoch.candidate_deployment_target
       or (verified_dispatch_result->>'baselineEvidenceId')::uuid is distinct
         from baseline_observation.provider_evidence_id
       or verified_dispatch_result->>'baselineConfigurationVersion'
         is distinct from epoch.baseline_active_config_version
       or nullif(verified_dispatch_result->>'baselineConfigurationEtag', '')
         is distinct from epoch.baseline_active_config_etag
       or pg_catalog.lower(
         verified_dispatch_result->>'baselineConfigurationIdentityFingerprint'
       ) is distinct from epoch.baseline_configuration_identity_fingerprint
       or pg_catalog.lower(
         verified_dispatch_result->>'baselineSemanticFingerprint'
       ) is distinct from epoch.baseline_semantic_configuration_fingerprint
       or pg_catalog.lower(
         verified_dispatch_result->>'baselineOrderedCustomRulesFingerprint'
       ) is distinct from epoch.baseline_ordered_rules_fingerprint
       or pg_catalog.lower(
         verified_dispatch_result->>'baselineSourceVersionReadFingerprint'
       ) is distinct from epoch.baseline_source_version_read_fingerprint
       or pg_catalog.lower(
         verified_dispatch_result->>'providerIntentFingerprint'
       ) is distinct from dispatch.provider_intent_fingerprint
       or verified_dispatch_result->>'runOwnedRuleName' is distinct from
         epoch.run_owned_rule_name
       or (verified_dispatch_result->>'runOwnedRuleNonce')::uuid is distinct
         from epoch.run_owned_rule_nonce
       or pg_catalog.lower(
         verified_dispatch_result->>'runOwnedRuleFingerprint'
       ) is distinct from epoch.run_owned_rule_fingerprint
       or pg_catalog.lower(
         verified_dispatch_result->>'runOwnedInsertDocumentFingerprint'
       ) is distinct from epoch.run_owned_insert_document_fingerprint
       or provider_observed is distinct from attested
       or provider_observed <
         pg_catalog.clock_timestamp() - interval '120 seconds'
       or provider_observed >
         pg_catalog.clock_timestamp() + interval '30 seconds'
       or expires is distinct from attested + interval '2100 seconds'
       or expires <= pg_catalog.clock_timestamp()
       or (outcome_value = 'TARGET_CONFIRMED' and (
         dispatch.dispatch_step is distinct from 'CRITICAL_RULE_INSERT'
         or (verified_dispatch_result->'providerResponseObserved' =
               'true'::jsonb
           and coalesce(
             verified_dispatch_result->>'providerResponseFingerprint', ''
           ) !~ '^[0-9a-f]{64}$')
         or (verified_dispatch_result->'providerResponseObserved' =
               'false'::jsonb
           and verified_dispatch_result->'providerResponseFingerprint'
             is distinct from 'null'::jsonb)
         or coalesce(
           verified_dispatch_result->>'providerReadbackFingerprint', ''
         ) !~ '^[0-9a-f]{64}$'
         or pg_catalog.jsonb_typeof(
           verified_dispatch_result->'activeSemanticConfiguration'
         ) is distinct from 'object'
         or (
           select pg_catalog.count(*)
           from pg_catalog.jsonb_object_keys(
             verified_dispatch_result->'activeSemanticConfiguration'
           )
         ) <> 7
         or not ((verified_dispatch_result->'activeSemanticConfiguration')
           ?& array[
             'schemaVersion', 'securityConfigurationKeys',
             'securityConfigurationKeysFingerprint', 'firewallEnabled',
             'ips', 'crs', 'orderedCustomRules'
           ]::text[])
         or pg_catalog.lower(
           verified_dispatch_result->>'activeSemanticConfigurationFingerprint'
         ) is distinct from epoch.baseline_semantic_configuration_fingerprint
         or (verified_dispatch_result->>'activeCustomRuleCount')::integer <> 0
         or (verified_dispatch_result->>'activePendingDraftPresent')::boolean
         or pg_catalog.jsonb_typeof(
           verified_dispatch_result->'draftSemanticConfiguration'
         ) is distinct from 'object'
         or (
           select pg_catalog.count(*)
           from pg_catalog.jsonb_object_keys(
             verified_dispatch_result->'draftSemanticConfiguration'
           )
         ) <> 7
         or not ((verified_dispatch_result->'draftSemanticConfiguration')
           ?& array[
             'schemaVersion', 'securityConfigurationKeys',
             'securityConfigurationKeysFingerprint', 'firewallEnabled',
             'ips', 'crs', 'orderedCustomRules'
           ]::text[])
         or coalesce(
           verified_dispatch_result->>'draftSemanticConfigurationFingerprint',
           ''
         ) !~ '^[0-9a-f]{64}$'
         or coalesce(
           verified_dispatch_result->>'draftOrderedCustomRulesFingerprint', ''
         ) !~ '^[0-9a-f]{64}$'
         or verified_dispatch_result->>'draftConfigurationVersion'
           is distinct from 'DRAFT'
         or coalesce(
           verified_dispatch_result
             ->>'draftConfigurationIdentityFingerprint', ''
         ) !~ '^[0-9a-f]{64}$'
         or (verified_dispatch_result->>'draftCustomRuleCount')::integer <> 1
         or (verified_dispatch_result->>'pendingDraftChangeCount')::integer <> 1
         or coalesce(
           verified_dispatch_result->>'providerAssignedRuleId', ''
         ) !~ '^[A-Za-z0-9_.:-]{3,160}$'
         or coalesce(
           verified_dispatch_result
             ->>'runOwnedProviderRuleDocumentFingerprint', ''
         ) !~ '^[0-9a-f]{64}$'
         or (verified_dispatch_result->>'runOwnedRulePrecedence')::integer <> 0
         or coalesce(
           verified_dispatch_result->>'criticalWindowContractFingerprint', ''
         ) !~ '^[0-9a-f]{64}$'
       ))
       or (outcome_value = 'OUTCOME_UNKNOWN' and
         verified_dispatch_result->'providerResponseFingerprint' is distinct
           from 'null'::jsonb)
       or (outcome_value = 'PROVIDER_REJECTED' and coalesce(
         verified_dispatch_result->>'providerResponseFingerprint', ''
       ) !~ '^[0-9a-f]{64}$')
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_SIGNED_RESULT_SCOPE_MISMATCH';
    end if;

    select * into prior_signed_result
    from production_control.vercel_writer_critical_waf_dispatch_results value
    where value.result_evidence_id =
      (verified_dispatch_result->>'dispatchResultId')::uuid;
    if found then
      if prior_signed_result.dispatch_id is distinct from dispatch.dispatch_id
         or prior_signed_result.outcome_status is distinct from outcome_value
         or prior_signed_result.evidence_fingerprint is distinct from
           result_fingerprint_value
      then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_SIGNED_RESULT_IDEMPOTENCY_CONFLICT';
      end if;
      signed_result := prior_signed_result;
    else
      insert into production_control.vercel_writer_critical_waf_dispatch_results (
        result_id, dispatch_id, epoch_id, provider_result_schema,
        outcome_status, dispatch_step, result_evidence_id,
        dispatch_request_id, transition_request_id,
        signed_request_fingerprint, evidence_fingerprint,
        signer_key_fingerprint, signer_key_version, purpose, transition_mode,
        vercel_project_id, vercel_team_id, candidate_alias_origin,
        candidate_immutable_origin, candidate_deployment_id,
        candidate_commit_sha, candidate_deployment_target,
        baseline_evidence_id,
        baseline_configuration_version, baseline_configuration_etag,
        baseline_configuration_identity_fingerprint,
        baseline_semantic_configuration_fingerprint,
        baseline_ordered_rules_fingerprint,
        baseline_source_version_read_fingerprint, provider_intent_fingerprint,
        provider_response_observed, provider_response_status,
        provider_response_fingerprint, provider_readback_fingerprint,
        active_semantic_configuration,
        active_semantic_configuration_fingerprint, active_custom_rule_count,
        active_pending_draft_present, draft_semantic_configuration,
        draft_semantic_configuration_fingerprint,
        draft_ordered_rules_fingerprint, draft_configuration_version,
        draft_configuration_identity_fingerprint, draft_custom_rule_count,
        pending_draft_change_count, run_owned_rule_name,
        run_owned_rule_nonce, provider_assigned_rule_id,
        run_owned_rule_fingerprint, run_owned_insert_document_fingerprint,
        run_owned_provider_rule_document_fingerprint,
        run_owned_rule_precedence, critical_window_contract_fingerprint,
        provider_observed_at, attested_at, expires_at
      ) values (
        extensions.gen_random_uuid(), dispatch.dispatch_id, epoch.epoch_id,
        verified_dispatch_result->>'schemaVersion', outcome_value,
        dispatch.dispatch_step,
        (verified_dispatch_result->>'dispatchResultId')::uuid,
        dispatch.dispatch_request_id, dispatch.transition_request_id,
        pg_catalog.lower(verified_dispatch_result->>'requestFingerprint'),
        result_fingerprint_value,
        pg_catalog.lower(verified_dispatch_result->>'signerKeyFingerprint'),
        verified_dispatch_result->>'signerKeyVersion', epoch.purpose,
        epoch.transition_mode,
        epoch.vercel_project_id, epoch.vercel_team_id,
        epoch.candidate_alias_origin, epoch.candidate_immutable_origin,
        epoch.candidate_deployment_id, epoch.candidate_deployment_commit,
        epoch.candidate_deployment_target,
        baseline_observation.provider_evidence_id,
        epoch.baseline_active_config_version,
        epoch.baseline_active_config_etag,
        epoch.baseline_configuration_identity_fingerprint,
        epoch.baseline_semantic_configuration_fingerprint,
        epoch.baseline_ordered_rules_fingerprint,
        epoch.baseline_source_version_read_fingerprint,
        dispatch.provider_intent_fingerprint,
        (verified_dispatch_result->>'providerResponseObserved')::boolean,
        nullif(
          verified_dispatch_result->>'providerResponseStatus', ''
        )::integer,
        nullif(pg_catalog.lower(
          verified_dispatch_result->>'providerResponseFingerprint'
        ), ''),
        nullif(pg_catalog.lower(
          verified_dispatch_result->>'providerReadbackFingerprint'
        ), ''),
        case when pg_catalog.jsonb_typeof(
          verified_dispatch_result->'activeSemanticConfiguration'
        ) = 'object'
          then verified_dispatch_result->'activeSemanticConfiguration'
          else null end,
        nullif(pg_catalog.lower(
          verified_dispatch_result->>'activeSemanticConfigurationFingerprint'
        ), ''),
        nullif(
          verified_dispatch_result->>'activeCustomRuleCount', ''
        )::integer,
        nullif(
          verified_dispatch_result->>'activePendingDraftPresent', ''
        )::boolean,
        case when pg_catalog.jsonb_typeof(
          verified_dispatch_result->'draftSemanticConfiguration'
        ) = 'object'
          then verified_dispatch_result->'draftSemanticConfiguration'
          else null end,
        nullif(pg_catalog.lower(
          verified_dispatch_result->>'draftSemanticConfigurationFingerprint'
        ), ''),
        nullif(pg_catalog.lower(
          verified_dispatch_result->>'draftOrderedCustomRulesFingerprint'
        ), ''),
        nullif(verified_dispatch_result->>'draftConfigurationVersion', ''),
        nullif(pg_catalog.lower(
          verified_dispatch_result
            ->>'draftConfigurationIdentityFingerprint'
        ), ''),
        nullif(
          verified_dispatch_result->>'draftCustomRuleCount', ''
        )::integer,
        nullif(
          verified_dispatch_result->>'pendingDraftChangeCount', ''
        )::integer,
        epoch.run_owned_rule_name, epoch.run_owned_rule_nonce,
        nullif(verified_dispatch_result->>'providerAssignedRuleId', ''),
        epoch.run_owned_rule_fingerprint,
        epoch.run_owned_insert_document_fingerprint,
        nullif(pg_catalog.lower(
          verified_dispatch_result
            ->>'runOwnedProviderRuleDocumentFingerprint'
        ), ''),
        nullif(
          verified_dispatch_result->>'runOwnedRulePrecedence', ''
        )::integer,
        nullif(pg_catalog.lower(
          verified_dispatch_result->>'criticalWindowContractFingerprint'
        ), ''),
        provider_observed, attested, expires
      ) returning * into signed_result;
    end if;
  end if;

  if dispatch.status in (
    'TARGET_CONFIRMED', 'OUTCOME_UNKNOWN', 'PROVIDER_REJECTED'
  ) then
    if dispatch.status = outcome_value
       and dispatch.provider_result_fingerprint = result_fingerprint_value
    then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'contract_version', 'CRITICAL_WINDOW_WAF_V1',
        'epoch_id', epoch.epoch_id, 'dispatch_id', dispatch.dispatch_id,
        'dispatch_request_id', dispatch.dispatch_request_id,
        'transition_request_id', dispatch.transition_request_id,
        'dispatch_step', dispatch.dispatch_step,
        'transition_mode', epoch.transition_mode,
        'outcome_status', dispatch.status,
        'provider_result_observation_id',
          dispatch.provider_result_observation_id,
        'provider_dispatch_result_id', dispatch.provider_dispatch_result_id,
        'status', epoch.status, 'idempotent', true
      );
    end if;
    if dispatch.status is distinct from 'OUTCOME_UNKNOWN'
       or outcome_value is distinct from 'TARGET_CONFIRMED'
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_RESULT_CONFLICT';
    end if;
  elsif dispatch.status is distinct from 'PROVIDER_MUTATING' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_RESULT_NOT_RECORDABLE';
  end if;

  if outcome_value = 'OUTCOME_UNKNOWN' then
    if signed_result.result_id is null then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_UNKNOWN_PROOF_REQUIRED';
    end if;
    update production_control.vercel_writer_critical_waf_dispatches
    set status = 'OUTCOME_UNKNOWN',
        provider_dispatch_result_id = signed_result.result_id,
        provider_result_fingerprint = result_fingerprint_value,
        provider_observed_at = provider_observed,
        recorded_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    where dispatch_id = dispatch.dispatch_id
    returning * into dispatch;
  elsif outcome_value = 'PROVIDER_REJECTED' then
    if signed_result.result_id is null
       or signed_result.outcome_status is distinct from 'PROVIDER_REJECTED'
       or not signed_result.provider_response_observed
       or signed_result.provider_response_status not between 400 and 599
       or signed_result.provider_response_fingerprint is null
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_REJECTION_PROOF_REQUIRED';
    end if;
    update production_control.vercel_writer_critical_waf_dispatches
    set status = 'PROVIDER_REJECTED',
        provider_dispatch_result_id = signed_result.result_id,
        provider_result_fingerprint = result_fingerprint_value,
        provider_observed_at = provider_observed,
        recorded_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    where dispatch_id = dispatch.dispatch_id
    returning * into dispatch;
  elsif dispatch.dispatch_step = 'CRITICAL_RULE_INSERT' then
    if signed_result.result_id is null
       or signed_result.outcome_status is distinct from 'TARGET_CONFIRMED'
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_RULE_INSERT_TARGET_REQUIRED';
    end if;
    update production_control.vercel_writer_critical_waf_epochs
    set provider_assigned_rule_id = signed_result.provider_assigned_rule_id,
        updated_at = pg_catalog.clock_timestamp()
    where epoch_id = epoch.epoch_id
      and status = 'ACTIVATION_PENDING'
      and provider_assigned_rule_id is null
    returning * into epoch;
    if not found then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_RULE_ID_CAPTURE_RACE';
    end if;
    update production_control.vercel_writer_critical_waf_dispatches
    set status = 'TARGET_CONFIRMED',
        provider_dispatch_result_id = signed_result.result_id,
        provider_result_fingerprint = result_fingerprint_value,
        provider_observed_at = provider_observed,
        recorded_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    where dispatch_id = dispatch.dispatch_id
    returning * into dispatch;
  else
    if pg_catalog.jsonb_typeof(verified_waf_evidence) is distinct from 'object'
       or coalesce(input->>'observation_request_id', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or verified_waf_evidence->>'transitionRequestId' is distinct from
         dispatch.transition_request_id::text
    then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_TARGET_EVIDENCE_REQUIRED';
    end if;
    expected_stage := case dispatch.dispatch_step
      when 'CRITICAL_DRAFT_ACTIVATE' then 'CRITICAL_ACTIVE'
      when 'BASELINE_VERSION_ACTIVATE' then 'BASELINE_RESTORED'
      else null end;
    observation :=
      production_control.insert_vercel_writer_critical_waf_observation(
        epoch.epoch_id, verified_waf_evidence,
        (input->>'observation_request_id')::uuid,
        pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value
      );
    if observation.evidence_stage is distinct from expected_stage then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_RESULT_STAGE_MISMATCH';
    end if;
    update production_control.vercel_writer_critical_waf_dispatches
    set status = 'TARGET_CONFIRMED',
        provider_result_observation_id = observation.observation_id,
        provider_dispatch_result_id = null,
        provider_result_fingerprint = result_fingerprint_value,
        provider_observed_at = observation.provider_observed_at,
        recorded_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
    where dispatch_id = dispatch.dispatch_id
    returning * into dispatch;

    if dispatch.dispatch_step = 'CRITICAL_DRAFT_ACTIVATE' then
      update production_control.vercel_writer_critical_waf_epochs
      set status = 'ACTIVE_UNBOUND',
          critical_active_observation_id = observation.observation_id,
          latest_critical_reattest_observation_id = observation.observation_id,
          critical_semantic_configuration_fingerprint =
            observation.semantic_configuration_fingerprint,
          critical_active_at = observation.provider_observed_at,
          updated_at = pg_catalog.clock_timestamp()
      where epoch_id = epoch.epoch_id
        and status = 'ACTIVATION_PENDING'
      returning * into epoch;
    else
      update production_control.vercel_writer_critical_waf_epochs
      set status = 'BASELINE_RESTORED',
          baseline_restored_observation_id = observation.observation_id,
          baseline_restored_at = observation.provider_observed_at,
          updated_at = pg_catalog.clock_timestamp()
      where epoch_id = epoch.epoch_id
        and status = 'RESTORE_PENDING'
      returning * into epoch;
    end if;
    if epoch.epoch_id is null then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_RESULT_STATE_RACE';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true, 'contract_version', 'CRITICAL_WINDOW_WAF_V1',
    'epoch_id', epoch.epoch_id, 'dispatch_id', dispatch.dispatch_id,
    'dispatch_request_id', dispatch.dispatch_request_id,
    'transition_request_id', dispatch.transition_request_id,
    'dispatch_step', dispatch.dispatch_step,
    'transition_mode', epoch.transition_mode,
    'outcome_status', dispatch.status,
    'provider_result_observation_id', dispatch.provider_result_observation_id,
    'provider_dispatch_result_id', dispatch.provider_dispatch_result_id,
    'provider_result_fingerprint', dispatch.provider_result_fingerprint,
    'provider_observed_at', dispatch.provider_observed_at,
    'status', epoch.status,
    'critical_window_active', epoch.status in (
      'ACTIVE_UNBOUND', 'FENCE_BOUND', 'RESTORE_PENDING'
    ),
    'baseline_restored', epoch.status = 'BASELINE_RESTORED',
    'idempotent', false
  );
end;
$_$;


ALTER FUNCTION public.record_production_vercel_writer_critical_waf_dispatch_result(input jsonb) OWNER TO postgres;

--
-- Name: record_production_vercel_writer_critical_waf_reattestation(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_production_vercel_writer_critical_waf_reattestation(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  observation production_control.vercel_writer_critical_waf_observations%rowtype;
  verified_evidence jsonb := input->'verified_waf_evidence';
begin
  if input->>'operation' is distinct from
       'RECORD_PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_REATTESTATION'
     or coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or pg_catalog.jsonb_typeof(verified_evidence) is distinct from 'object'
     or coalesce(input->>'observation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_REATTEST_INPUT_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = (input->>'epoch_id')::uuid
  for update;
  if epoch.status is distinct from 'FENCE_BOUND' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_REATTEST_STATE_INVALID';
  end if;
  observation :=
    production_control.insert_vercel_writer_critical_waf_observation(
      epoch.epoch_id, verified_evidence,
      (input->>'observation_request_id')::uuid,
      pg_catalog.lower(input->>'request_fingerprint'),
      production_control.cutover_payload_hash(input)
    );
  if observation.evidence_stage is distinct from 'CRITICAL_REATTEST' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_CRITICAL_WAF_REATTEST_STAGE_INVALID';
  end if;
  update production_control.vercel_writer_critical_waf_epochs
  set latest_critical_reattest_observation_id = observation.observation_id,
      updated_at = pg_catalog.clock_timestamp()
  where epoch_id = epoch.epoch_id
  returning * into epoch;
  return production_control.vercel_writer_critical_waf_epoch_response(
    epoch, false
  ) || pg_catalog.jsonb_build_object(
    'critical_reattest_observation_id', observation.observation_id,
    'provider_observed_at', observation.provider_observed_at,
    'expires_at', observation.expires_at
  );
end;
$_$;


ALTER FUNCTION public.record_production_vercel_writer_critical_waf_reattestation(input jsonb) OWNER TO postgres;

--
-- Name: recover_production_auth_candidate_otp_verification(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recover_production_auth_candidate_otp_verification(target_request_id uuid, target_auth_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth', 'pg_temp'
    AS $$
declare candidate participant_identity.production_auth_candidates%rowtype;
declare attempt participant_identity.participant_auth_otp_attempts%rowtype;
begin
  perform production_control.assert_production_auth_candidate_rpc();
  if target_request_id is null or target_auth_user_id is null then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_RECOVERY_EXACT_REQUEST_REQUIRED');
  end if;
  select * into attempt from participant_identity.participant_auth_otp_attempts
  where request_id = target_request_id and tournament_id = '2026'
    and auth_user_id = target_auth_user_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_RECOVERY_ATTEMPT_NOT_FOUND');
  end if;
  select * into candidate from participant_identity.production_auth_candidates
  where tournament_id = attempt.tournament_id and auth_user_id = target_auth_user_id
    and player_id = attempt.player_id and status in ('PREPARED', 'VERIFIED') for update;
  if not found or attempt.status not in ('SENT', 'VERIFIED')
    or (attempt.status = 'SENT' and attempt.sent_at <= now() - interval '30 minutes')
    or not exists (select 1 from auth.users
      where id = target_auth_user_id and email_confirmed_at is not null) then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_RECOVERY_NOT_ELIGIBLE');
  end if;
  if attempt.status = 'SENT' and exists (
    select 1 from participant_identity.participant_auth_otp_attempts newer
    where newer.tournament_id = attempt.tournament_id
      and newer.auth_user_id = attempt.auth_user_id
      and newer.player_id = attempt.player_id
      and newer.status in ('SENT', 'VERIFIED')
      and (newer.requested_at > attempt.requested_at
        or (newer.requested_at = attempt.requested_at
          and newer.request_id::text > attempt.request_id::text))
  ) then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_AUTH_RECOVERY_ATTEMPT_SUPERSEDED');
  end if;
  return production_control.certify_production_auth_candidate_otp(
    target_request_id, target_auth_user_id, 0, true
  );
end;
$$;


ALTER FUNCTION public.recover_production_auth_candidate_otp_verification(target_request_id uuid, target_auth_user_id uuid) OWNER TO postgres;

--
-- Name: recover_production_future_participant_otp_verification_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recover_production_future_participant_otp_verification_v1(target_request_id uuid, target_auth_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
begin
  target_id := production_control
    .assert_future_participant_identity_runtime_v1();
  if not exists (
    select 1
    from participant_identity.participant_auth_otp_attempts value
    where value.request_id = target_request_id
      and value.auth_user_id = target_auth_user_id
      and value.tournament_id = target_id
      and value.status in ('SENT', 'VERIFIED')
      and value.requested_at > pg_catalog.clock_timestamp()
        - interval '30 minutes'
  ) or not exists (
    select 1 from auth.users value
    where value.id = target_auth_user_id
      and value.email_confirmed_at is not null
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'code', 'PRODUCTION_PARTICIPANT_AUTH_RECOVERY_NOT_ELIGIBLE'
    );
  end if;
  return production_control
    .certify_production_future_participant_otp_v1(
      target_request_id, target_auth_user_id, 0, true
    );
end;
$$;


ALTER FUNCTION public.recover_production_future_participant_otp_verification_v1(target_request_id uuid, target_auth_user_id uuid) OWNER TO postgres;

--
-- Name: recover_production_participant_otp_verification(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recover_production_participant_otp_verification(target_request_id uuid, target_auth_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'auth', 'pg_temp'
    AS $$
begin
  perform production_control.assert_production_participant_identity_cutover();
  if not exists (select 1 from participant_identity.participant_auth_otp_attempts
      where request_id = target_request_id and auth_user_id = target_auth_user_id
        and status in ('SENT','VERIFIED') and requested_at > now() - interval '30 minutes')
     or not exists (select 1 from auth.users where id = target_auth_user_id and email_confirmed_at is not null) then
    return jsonb_build_object('ok', false, 'code', 'PRODUCTION_PARTICIPANT_AUTH_RECOVERY_NOT_ELIGIBLE');
  end if;
  return production_control.certify_production_participant_otp(
    target_request_id, target_auth_user_id, 0, true);
end;
$$;


