--
-- Name: report_production_scoring_ingress_outcome(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_production_scoring_ingress_outcome(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  response_value jsonb;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  expected_provider_principal text;
begin
  if coalesce(input->>'lease_id', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or coalesce(input->>'lease_nonce', '')
       !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_OUTCOME_V3_REQUEST_INVALID';
  end if;
  expected_provider_principal :=
    pg_catalog.lower(input->>'expected_provider_principal_fingerprint');
  if coalesce(expected_provider_principal, '') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_OUTCOME_V3_PROVIDER_PRINCIPAL_REQUIRED';
  end if;

  response_value :=
    public.report_production_scoring_ingress_outcome_v2_base(input);

  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for share;
  select * into lease
  from scoring_authority.scoring_ingress_leases value
  where value.tournament_id = '2026'
    and value.protocol_version = 'ADMISSION_V2'
    and value.lease_id = (input->>'lease_id')::uuid
  for share;
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_OUTCOME_V3_RECEIPT_MISMATCH';
  end if;
  perform production_control.assert_production_scoring_lease_nonce(
    lease, input->>'lease_nonce'
  );
  if lease.operation_request_id is distinct from
       (input->>'operation_request_id')::uuid
     or lease.provider_credential_class is distinct from
       'LEGACY_PROVIDER_FENCEABLE'
     or lease.provider_principal_fingerprint is distinct from
       expected_provider_principal
     or gate.provider_principal_fingerprint is distinct from
       expected_provider_principal
     or response_value->>'lease_id' is distinct from lease.lease_id::text
     or response_value->>'resolution_state' is distinct from
       lease.resolution_state
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_OUTCOME_V3_RECEIPT_MISMATCH';
  end if;
  return response_value || pg_catalog.jsonb_build_object(
    'contract_version', 'ADMISSION_V3',
    'lease_id', lease.lease_id,
    'lease_nonce', pg_catalog.lower(input->>'lease_nonce'),
    'operation_request_id', lease.operation_request_id,
    'provider_credential_class', lease.provider_credential_class,
    'provider_principal_fingerprint', lease.provider_principal_fingerprint
  );
end;
$_$;


ALTER FUNCTION public.report_production_scoring_ingress_outcome(input jsonb) OWNER TO postgres;

--
-- Name: report_production_scoring_ingress_outcome_v2_base(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_production_scoring_ingress_outcome_v2_base(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  requested_outcome text := pg_catalog.upper(coalesce(input->>'outcome_state', ''));
  unresolved_count integer;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform production_control.assert_scoring_admission_optimistic_input(input, false);
  existing := production_control.lookup_cutover_receipt(
    'REPORT_SCORING_INGRESS_OUTCOME', input
  );
  if existing is not null then return existing; end if;
  if requested_outcome not in (
       'CONFIRMED_WRITE', 'PROVEN_NO_WRITE', 'AMBIGUOUS', 'PARTIAL_WRITE'
     )
     or coalesce(input->>'outcome_evidence_fingerprint', '')
       !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_LEASE_OUTCOME_EVIDENCE_REQUIRED';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for share;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into lease
  from scoring_authority.scoring_ingress_leases value
  where value.lease_id = (input->>'lease_id')::uuid
  for update;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'PRODUCTION_SCORING_LEASE_V2_NOT_FOUND';
  end if;
  perform production_control.assert_production_scoring_lease_nonce(
    lease, input->>'lease_nonce'
  );
  existing := production_control.lookup_cutover_receipt(
    'REPORT_SCORING_INGRESS_OUTCOME', input
  );
  if existing is not null then return existing; end if;
  if lease.admitted_activation_revision
       is distinct from (input->>'expected_activation_revision')::bigint
     or activation.activation_revision < lease.admitted_activation_revision
     or activation.authority_generation_id
       is distinct from (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id
       is distinct from (input->>'expected_admission_generation')::uuid
     or lease.admission_revision
       is distinct from (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or activation.expected_deployment_commit is distinct from input->>'deployment_commit'
     or lease.authority_generation_id is distinct from activation.authority_generation_id
     or lease.admission_generation_id is distinct from gate.admission_generation_id
     or gate.admission_state not in ('OPEN', 'CLOSING')
     or not gate.admission_protocol_enforced then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_SCORING_LEASE_V2_BOUNDARY_CHANGED';
  end if;
  if lease.resolution_state in (
    'CONFIRMED_WRITE', 'PROVEN_NO_WRITE', 'RESOLVED_WRITE', 'RESOLVED_NO_WRITE'
  ) then
    if lease.resolution_state <> requested_outcome then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_SCORING_LEASE_OUTCOME_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'lease_id', lease.lease_id,
      'resolution_state', lease.resolution_state, 'idempotent', true
    );
  end if;
  if requested_outcome = 'PROVEN_NO_WRITE'
     and (lease.resolution_state <> 'ADMITTED' or lease.write_started_at is not null) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_NO_WRITE_RECONCILIATION_REQUIRED';
  end if;
  if requested_outcome in ('CONFIRMED_WRITE', 'AMBIGUOUS', 'PARTIAL_WRITE')
     and lease.resolution_state <> 'WRITE_STARTED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_WRITE_START_EVIDENCE_REQUIRED';
  end if;
  if requested_outcome = 'CONFIRMED_WRITE'
     and (
       coalesce(input->>'provider_mutation_key', '') = ''
       or coalesce(input->>'provider_before_fingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(input->>'provider_after_fingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or coalesce(input->>'provider_readback_fingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or input->>'provider_after_fingerprint'
         is distinct from input->>'provider_readback_fingerprint'
     ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_CONFIRMED_WRITE_READBACK_REQUIRED';
  end if;
  if pg_catalog.lower(input->>'outcome_evidence_fingerprint')
       is distinct from production_control.scoring_lease_outcome_evidence_hash(
         lease.lease_id,
         lease.request_fingerprint,
         requested_outcome,
         input->>'provider_mutation_key',
         input->>'provider_before_fingerprint',
         input->>'provider_after_fingerprint',
         input->>'provider_readback_fingerprint',
         lease.authority_generation_id,
         lease.admission_generation_id,
         lease.admission_revision
       ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_LEASE_OUTCOME_EVIDENCE_HASH_MISMATCH';
  end if;

  update scoring_authority.scoring_ingress_leases
  set resolution_state = requested_outcome,
      status = case when requested_outcome in ('CONFIRMED_WRITE', 'PROVEN_NO_WRITE')
        then 'COMPLETED' else 'ACTIVE' end,
      completed_at = case when requested_outcome in ('CONFIRMED_WRITE', 'PROVEN_NO_WRITE')
        then pg_catalog.now() else null end,
      outcome_reported_at = pg_catalog.now(),
      provider_mutation_key = nullif(input->>'provider_mutation_key', ''),
      provider_before_fingerprint = nullif(
        pg_catalog.lower(input->>'provider_before_fingerprint'), ''
      ),
      provider_after_fingerprint = nullif(
        pg_catalog.lower(input->>'provider_after_fingerprint'), ''
      ),
      provider_readback_fingerprint = nullif(
        pg_catalog.lower(input->>'provider_readback_fingerprint'), ''
      ),
      outcome_evidence_fingerprint = pg_catalog.lower(
        input->>'outcome_evidence_fingerprint'
      ),
      resolved_at = case when requested_outcome in ('CONFIRMED_WRITE', 'PROVEN_NO_WRITE')
        then pg_catalog.now() else null end,
      resolved_by = case when requested_outcome in ('CONFIRMED_WRITE', 'PROVEN_NO_WRITE')
        then pg_catalog.left(input->>'actor_id', 160) else null end,
      last_error_code = nullif(
        pg_catalog.left(input->>'error_code', 120), ''
      )
  where lease_id = lease.lease_id
  returning * into lease;
  unresolved_count := production_control.scoring_admission_unresolved_count(
    gate.admission_generation_id
  );
  update scoring_authority.ingress_gates
  set unresolved_client_queues = unresolved_count, updated_at = pg_catalog.now()
  where tournament_id = '2026';
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_SCORING_LEASE_' || requested_outcome,
    'SCORING_AUTHORITY', '2026', pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'),
    case when requested_outcome in ('AMBIGUOUS', 'PARTIAL_WRITE')
      then 'BLOCKED' else 'SUCCEEDED' end,
    pg_catalog.jsonb_build_object(
      'lease_id', lease.lease_id,
      'resolution_state', lease.resolution_state,
      'provider_readback_fingerprint', lease.provider_readback_fingerprint,
      'outcome_evidence_fingerprint', lease.outcome_evidence_fingerprint,
      'active_or_unresolved_leases', unresolved_count
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_SCORING_LEASE_OUTCOME_RECORDED',
    'lease_id', lease.lease_id,
    'resolution_state', lease.resolution_state,
    'active_or_unresolved_leases', unresolved_count,
    'requires_reconciliation', lease.resolution_state in ('AMBIGUOUS', 'PARTIAL_WRITE'),
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'REPORT_SCORING_INGRESS_OUTCOME', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.report_production_scoring_ingress_outcome_v2_base(input jsonb) OWNER TO postgres;

--
-- Name: request_competition_derived_recalculation(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_competition_derived_recalculation(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  legacy_input jsonb;
  result_value jsonb;
begin
  perform production_control.assert_frozen_2026_derived_worker_v1(input);
  legacy_input := input || pg_catalog.jsonb_build_object(
    'environment', 'PREVIEW', 'tournament_id', '2026'
  );
  if pg_catalog.to_regprocedure(
       'public.request_competition_derived_recalculation_frozen_2026_installed_v1(jsonb)'
     ) is not null then
    execute $installed$select public
      .request_competition_derived_recalculation_frozen_2026_installed_v1($1)
    $installed$ into strict result_value using legacy_input;
    return result_value;
  end if;
  return production_control
    .frozen_2026_request_competition_derived_recalculation_v1(legacy_input);
end;
$_$;


ALTER FUNCTION public.request_competition_derived_recalculation(input jsonb) OWNER TO postgres;

--
-- Name: request_production_odds_calculation_job(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_production_odds_calculation_job(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority', 'extensions'
    AS $_$
declare
  config scoring_authority.odds_input_configurations%rowtype;
  existing scoring_authority.odds_calculation_jobs%rowtype;
  inserted scoring_authority.odds_calculation_jobs%rowtype;
  job text := lower(coalesce(input->>'job_id', ''));
  input_hash text := lower(coalesce(input->>'input_fingerprint', ''));
  checkpoint_hash_value text := lower(coalesce(input->>'checkpoint_hash', ''));
  invocation_value jsonb;
  input_snapshot_value jsonb;
  checkpoint_value jsonb;
  superseded_count integer := 0;
begin
  perform production_control.assert_production_odds_calculation_scope(input, true);
  perform production_control.assert_production_odds_request_identity(input);
  config := production_control.current_production_odds_inputs(input);

  if job !~ '^[0-9a-f]{64}$'
     or job <> lower(coalesce(input->>'invocation_fingerprint', ''))
     or input_hash !~ '^[0-9a-f]{64}$'
     or checkpoint_hash_value !~ '^[0-9a-f]{64}$'
     or input->>'tournament_id' <> '2026'
     or input->>'phase' not in (
       'Pre-Tournament', 'After Round 1', 'After Round 2',
       'Round 3 Pairings Announced', 'Final Results'
     )
     or coalesce((input->>'total_iterations')::integer, 0)
          not in (10000, 25000, 50000, 100000)
     or coalesce(input->>'engine_version', '') = ''
     or coalesce(input->>'publication_contract_version', '') = ''
     or coalesce(input->>'checkpoint_contract_version', '') = ''
     or coalesce(input->>'deterministic_seed', '') = ''
     or coalesce(input->>'requested_by', '') = ''
     or coalesce(input->>'output_timestamp', '') = ''
     or jsonb_typeof(input->'input_snapshot') <> 'object'
     or jsonb_typeof(input->'checkpoint_payload') <> 'object'
     or jsonb_typeof(input->'source_revision') <> 'object'
     or coalesce(input->>'invocation_canonical_json', '') = ''
     or coalesce(input->>'input_snapshot_canonical_json', '') = ''
     or coalesce(input->>'checkpoint_canonical_json', '') = '' then
    raise exception using errcode = '22023',
      message = 'COMPLETE_PRODUCTION_ODDS_CALCULATION_JOB_REQUIRED';
  end if;

  begin
    invocation_value := (input->>'invocation_canonical_json')::jsonb;
    input_snapshot_value := (input->>'input_snapshot_canonical_json')::jsonb;
    checkpoint_value := (input->>'checkpoint_canonical_json')::jsonb;
  exception when others then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_ODDS_CANONICAL_JSON_INVALID';
  end;
  if input_snapshot_value is distinct from input->'input_snapshot'
     or checkpoint_value is distinct from input->'checkpoint_payload'
     or encode(extensions.digest(input->>'input_snapshot_canonical_json', 'sha256'), 'hex')
          <> input_hash
     or encode(extensions.digest(input->>'checkpoint_canonical_json', 'sha256'), 'hex')
          <> checkpoint_hash_value
     or encode(extensions.digest(input->>'invocation_canonical_json', 'sha256'), 'hex')
          <> job
     or invocation_value->>'tournamentId' <> '2026'
     or invocation_value->>'phase' is distinct from input->>'phase'
     or coalesce((invocation_value->>'iterations')::integer, 0)
          <> (input->>'total_iterations')::integer
     or invocation_value->>'inputFingerprint' is distinct from input_hash
     or invocation_value->>'settingsFingerprint'
          is distinct from config.settings_fingerprint
     or input#>>'{input_snapshot,metadata,settingsFingerprint}'
          is distinct from config.settings_fingerprint
     or input#>>'{input_snapshot,sheets,tournaments,0,Tournament ID}'
          is distinct from '2026' then
    raise exception using errcode = '23514',
      message = 'PRODUCTION_ODDS_DETERMINISTIC_IDENTITY_MISMATCH';
  end if;

  perform pg_advisory_xact_lock(hashtext('production-odds-job:' || job));
  select * into existing
  from scoring_authority.odds_calculation_jobs
  where job_id = job for update;
  if found then
    perform production_control.assert_production_odds_retained_job_scope(
      input, to_jsonb(existing)
    );
    if existing.input_fingerprint <> input_hash
       or existing.input_configuration_id <> config.id
       or existing.input_bundle_fingerprint <> config.bundle_fingerprint
       or existing.total_iterations <> (input->>'total_iterations')::integer then
      raise exception using errcode = '23505',
        message = 'PRODUCTION_ODDS_CALCULATION_JOB_IDENTITY_CONFLICT';
    end if;
    return jsonb_build_object(
      'ok', true, 'changed', false, 'duplicate', true,
      'job', to_jsonb(existing) - 'input_snapshot' - 'checkpoint_payload'
        - 'result_payload' - 'claim_token',
      'publication_created', false, 'mirror_created', false
    );
  end if;

  insert into scoring_authority.odds_calculation_jobs (
    job_id, tournament_id, phase, total_iterations, engine_version,
    publication_contract_version, checkpoint_contract_version,
    deterministic_seed, input_fingerprint, settings_fingerprint,
    invocation_fingerprint, source_revision, input_snapshot,
    checkpoint_payload, checkpoint_hash, requested_by, output_timestamp,
    resource_metrics, input_configuration_id, effective_settings_fingerprint,
    input_bundle_fingerprint, production_operation_mode,
    production_deployment_commit, production_candidate_hostname,
    publication_status, publication_reference
  ) values (
    job, '2026', input->>'phase', (input->>'total_iterations')::integer,
    input->>'engine_version', input->>'publication_contract_version',
    input->>'checkpoint_contract_version', input->>'deterministic_seed',
    input_hash, config.settings_fingerprint, job, input->'source_revision',
    input->'input_snapshot', input->'checkpoint_payload', checkpoint_hash_value,
    left(input->>'requested_by', 180), (input->>'output_timestamp')::timestamptz,
    coalesce(input->'resource_metrics', '{}'::jsonb), config.id,
    config.effective_settings_fingerprint, config.bundle_fingerprint,
    input->>'operation_mode', input->>'deployment_commit',
    nullif(input->>'candidate_hostname', ''), 'NOT_REQUESTED', '{}'::jsonb
  ) returning * into inserted;

  update scoring_authority.odds_calculation_jobs
  set status = 'SUPERSEDED', publication_status = 'STALE',
      superseded_by = job, superseded_at = now(), claim_token = null,
      lease_expires_at = null,
      last_error_code = 'ODDS_CALCULATION_SOURCE_ADVANCED',
      last_error_safe = 'Canonical Production calculation inputs advanced.',
      updated_at = now()
  where job_id <> job and tournament_id = '2026' and phase = input->>'phase'
    and production_operation_mode = input->>'operation_mode'
    and production_deployment_commit = input->>'deployment_commit'
    and production_candidate_hostname is not distinct from
      nullif(input->>'candidate_hostname', '')
    and input_bundle_fingerprint is distinct from config.bundle_fingerprint
    and status in ('PENDING', 'RUNNING', 'RETRYABLE', 'SUCCEEDED')
    and publication_status <> 'PUBLISHED';
  get diagnostics superseded_count = row_count;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_ODDS_CALCULATION_REQUESTED',
    'CHAMPIONSHIP_ODDS_CALCULATION', '2026',
    left(input->>'requested_by', 160), job, 'SUCCEEDED',
    jsonb_build_object(
      'job_id', job, 'phase', input->>'phase',
      'iterations', (input->>'total_iterations')::integer,
      'input_fingerprint', input_hash,
      'settings_fingerprint', config.settings_fingerprint,
      'effective_settings_fingerprint', config.effective_settings_fingerprint,
      'input_bundle_fingerprint', config.bundle_fingerprint,
      'operation_mode', input->>'operation_mode',
      'deployment_commit', input->>'deployment_commit',
      'candidate_hostname', nullif(input->>'candidate_hostname', ''),
      'superseded_jobs', superseded_count,
      'publication_created', false, 'mirror_created', false
    )
  );
  return jsonb_build_object(
    'ok', true, 'changed', true, 'duplicate', false,
    'superseded_jobs', superseded_count,
    'job', to_jsonb(inserted) - 'input_snapshot' - 'checkpoint_payload'
      - 'result_payload' - 'claim_token',
    'publication_created', false, 'mirror_created', false
  );
end;
$_$;


ALTER FUNCTION public.request_production_odds_calculation_job(input jsonb) OWNER TO postgres;

