--
-- Name: resolve_certification_ingress_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_certification_ingress_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare l production_control.certification_ingress_leases_v1%rowtype;
begin
 l:=production_control.certification_ingress_lookup_v1(input,true);
 if l.lease_id is null then return public.read_certification_ingress_status_v1(input);end if;
 if l.state in('ADMITTED','UNKNOWN')then
  if production_control.certification_ingress_canonical_receipt_v1(l)is not null then
   raise exception using errcode='55000',message='CERTIFICATION_INGRESS_RECEIPT_CONTRADICTION';end if;
  -- Same row lock held throughout canonical execution. No committed execution
  -- can be present without its atomic terminal state. Fencing is irreversible.
  update production_control.certification_ingress_leases_v1 set state='NOT_COMMITTED',resolved_at=clock_timestamp(),
   result=jsonb_build_object('ok',false,'code','CERTIFICATION_INGRESS_NOT_COMMITTED','operation_request_id',l.operation_request_id)
   where lease_id=l.lease_id returning * into l;
  insert into production_control.operation_audit_events(event_type,domain,tournament_id,actor,request_fingerprint,result,details)
  values('CERTIFICATION_INGRESS_RESOLVED','CERTIFICATION',l.tournament_id,l.actor_player_id,l.request_hash,'SUCCEEDED',
   jsonb_build_object('resource_id',l.resource_id,'generation_id',l.admission_generation_id,'lease_id',l.lease_id,
    'operation_request_id',l.operation_request_id,'state','NOT_COMMITTED'));
 end if;
 return production_control.certification_ingress_response_v1(l);
end;$$;


ALTER FUNCTION public.resolve_certification_ingress_v1(input jsonb) OWNER TO postgres;

--
-- Name: resolve_production_calcutta_postcommit_match_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_production_calcutta_postcommit_match_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  pointer production_control.current_tournament_pointer_v1%rowtype;
  target_match text := pg_catalog.btrim(coalesce(input->>'match_id', ''));
  target_tournament text;
begin
  if target_match = '' or pg_catalog.length(target_match) > 120 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_MATCH_REQUIRED';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.tournament_id into strict target_tournament
  from scoring_authority.matches value
  where value.match_id = target_match;
  if pointer.tournament_id <> '2026'
     or target_tournament <> '2026' then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CALCUTTA_MATCH_TOURNAMENT_MISMATCH';
  end if;
  perform production_control.assert_production_calcutta_v1_runtime(input);
  return pg_catalog.jsonb_build_object(
    'ok', true, 'tournament_id', target_tournament,
    'match_id', target_match, 'runtime_generation_id', null,
    'pointer_revision', pointer.pointer_revision
  );
exception
  when no_data_found then
    raise exception using errcode = '42501',
      message = 'PRODUCTION_CALCUTTA_MATCH_TOURNAMENT_MISMATCH';
end;
$$;


ALTER FUNCTION public.resolve_production_calcutta_postcommit_match_v1(input jsonb) OWNER TO postgres;

--
-- Name: resolve_production_future_match_google_compatibility_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_production_future_match_google_compatibility_v2(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_id text;
  target production_control.future_google_writer_targets_v2%rowtype;
  writer production_control.future_google_writer_generations_v2%rowtype;
begin
  target_id := production_control.assert_future_google_writer_v2(input, false);
  select value.* into strict target
  from production_control.future_google_writer_targets_v2 value
  where value.tournament_id = target_id and value.contract_status = 'CERTIFIED';
  select value.* into strict writer
  from production_control.future_google_writer_generations_v2 value
  where value.writer_generation_id = target.writer_generation_id;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'contractVersion', writer.contract_version,
    'targetTournamentId', target_id,
    'writerGenerationId', writer.writer_generation_id,
    'destinationWorkbookId', target.destination_workbook_id,
    'targetContractFingerprint', target.target_contract_fingerprint,
    'implementationFingerprint', writer.implementation_fingerprint,
    'nonAuthoritative', true, 'rollbackAllowed', false
  );
end;
$$;


ALTER FUNCTION public.resolve_production_future_match_google_compatibility_v2(input jsonb) OWNER TO postgres;

--
-- Name: resolve_production_legacy_scoring_ingress(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_production_legacy_scoring_ingress(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  requested_resolution text := pg_catalog.upper(
    coalesce(input->>'resolution', '')
  );
  evidence_id uuid;
  blockers integer;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform production_control.assert_scoring_admission_optimistic_input(input, true);
  if requested_resolution not in ('WRITE', 'NO_WRITE')
     or coalesce(input->>'provider_readback_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'resolution_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or (requested_resolution = 'WRITE'
       and pg_catalog.btrim(coalesce(
         input->>'provider_mutation_key', ''
       )) = '') then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_LEGACY_SCORING_RESOLUTION_EVIDENCE_REQUIRED';
  end if;
  evidence_id := (input->>'external_fence_evidence_id')::uuid;

  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for share;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into lease
  from scoring_authority.scoring_ingress_leases value
  where value.lease_id = (input->>'lease_id')::uuid
  for update;
  if not found
     or lease.protocol_version is distinct from 'LEGACY_V1'
     or lease.resolution_state is distinct from 'LEGACY_UNCLASSIFIED' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_LEGACY_SCORING_LEASE_NOT_RESOLVABLE';
  end if;
  existing := production_control.lookup_cutover_receipt(
    'RESOLVE_LEGACY_SCORING_INGRESS', input
  );
  if existing is not null then return existing; end if;
  perform production_control.assert_current_external_scoring_fence(
    evidence_id, activation.expected_deployment_commit
  );
  if activation.activation_revision
       is distinct from (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id
       is distinct from (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id
       is distinct from (input->>'expected_admission_generation')::uuid
     or gate.admission_revision
       is distinct from (input->>'expected_admission_revision')::bigint
     or activation.expected_deployment_commit
       is distinct from input->>'deployment_commit'
     or (gate.admission_protocol_enforced and gate.admission_deployment_id
       is distinct from input->>'deployment_id')
     or activation.current_authority is distinct from 'GOOGLE'
     or gate.authority is distinct from 'GOOGLE'
     or gate.admission_state not in ('OPEN', 'CLOSING') then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_LEGACY_SCORING_RESOLUTION_BOUNDARY_CHANGED';
  end if;
  if pg_catalog.lower(input->>'resolution_fingerprint') is distinct from
    production_control.scoring_legacy_resolution_evidence_hash(
      lease.lease_id,
      pg_catalog.lower(input->>'request_fingerprint'),
      requested_resolution,
      pg_catalog.lower(input->>'provider_readback_fingerprint'),
      evidence_id,
      input->>'actor_id'
    ) then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_LEGACY_SCORING_RESOLUTION_HASH_MISMATCH';
  end if;

  update scoring_authority.scoring_ingress_leases
  set resolution_state = case when requested_resolution = 'WRITE'
        then 'RESOLVED_WRITE' else 'RESOLVED_NO_WRITE' end,
      status = 'COMPLETED', completed_at = pg_catalog.now(),
      outcome_reported_at = pg_catalog.now(),
      provider_mutation_key = nullif(
        input->>'provider_mutation_key', ''
      ),
      provider_readback_fingerprint = pg_catalog.lower(
        input->>'provider_readback_fingerprint'
      ),
      resolution_fingerprint = pg_catalog.lower(
        input->>'resolution_fingerprint'
      ),
      resolved_at = pg_catalog.now(),
      resolved_by = input->>'actor_id',
      last_error_code = null
  where lease_id = lease.lease_id
  returning * into lease;
  blockers := production_control.scoring_admission_legacy_blocker_count(
    gate.admission_enforced_at
  );
  update scoring_authority.ingress_gates
  set unresolved_client_queues =
        production_control.scoring_admission_unresolved_count(
          gate.admission_generation_id
        ) + blockers,
      updated_at = pg_catalog.now()
  where tournament_id = '2026';
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_LEGACY_SCORING_LEASE_RESOLVED', 'SCORING_AUTHORITY', '2026',
    input->>'actor_id', pg_catalog.lower(input->>'request_fingerprint'),
    'SUCCEEDED', pg_catalog.jsonb_build_object(
      'lease_id', lease.lease_id,
      'resolution_state', lease.resolution_state,
      'provider_readback_fingerprint', lease.provider_readback_fingerprint,
      'resolution_fingerprint', lease.resolution_fingerprint,
      'external_fence_evidence_id', evidence_id,
      'legacy_unclassified_remaining', blockers
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_LEGACY_SCORING_LEASE_RESOLVED',
    'lease_id', lease.lease_id,
    'resolution_state', lease.resolution_state,
    'legacy_unclassified_remaining', blockers,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'RESOLVE_LEGACY_SCORING_INGRESS', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.resolve_production_legacy_scoring_ingress(input jsonb) OWNER TO postgres;

--
-- Name: resolve_production_scoring_ingress_ambiguity(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_production_scoring_ingress_ambiguity(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  lease scoring_authority.scoring_ingress_leases%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  evidence production_control.scoring_external_fence_evidence%rowtype;
  fence production_control.google_writer_provider_fences%rowtype;
  verification
    production_control.google_writer_provider_fence_verifications%rowtype;
  quiesce production_control.vercel_writer_quiesce_evidence%rowtype;
  requested_resolution text := pg_catalog.upper(
    coalesce(input->>'resolution', '')
  );
  readback_observed timestamptz;
  requires_fenced_no_write_proof boolean;
  unresolved_count integer;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  perform production_control.assert_scoring_admission_optimistic_input(
    input, false
  );
  existing := production_control.lookup_cutover_receipt(
    'RESOLVE_SCORING_INGRESS_AMBIGUITY', input
  );
  if existing is not null then return existing; end if;
  if requested_resolution not in ('WRITE', 'NO_WRITE')
     or coalesce(input->>'resolution_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'provider_readback_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'actor_id', '') = ''
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SCORING_AMBIGUITY_RESOLUTION_EVIDENCE_REQUIRED';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for share;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into lease
  from scoring_authority.scoring_ingress_leases value
  where value.lease_id = (input->>'lease_id')::uuid
  for update;
  if not found then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_AMBIGUITY_NOT_RESOLVABLE';
  end if;
  existing := production_control.lookup_cutover_receipt(
    'RESOLVE_SCORING_INGRESS_AMBIGUITY', input
  );
  if existing is not null then return existing; end if;
  if lease.resolution_state not in ('AMBIGUOUS', 'PARTIAL_WRITE') then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_AMBIGUITY_NOT_RESOLVABLE';
  end if;
  if lease.resolution_state = 'PARTIAL_WRITE'
     and requested_resolution = 'NO_WRITE' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SCORING_PARTIAL_WRITE_REPAIR_REQUIRED';
  end if;
  if activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or lease.admission_generation_id is distinct from
       gate.admission_generation_id
     or gate.admission_state not in ('OPEN', 'CLOSING')
  then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_SCORING_AMBIGUITY_BOUNDARY_CHANGED';
  end if;

  requires_fenced_no_write_proof := requested_resolution = 'NO_WRITE'
    and lease.write_started_at is not null;
  if requires_fenced_no_write_proof then
    if coalesce(input->>'closure_id', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(input->>'external_fence_evidence_id', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(input->>'quiesce_evidence_id', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(input->>'provider_fence_id', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(input->>'provider_fence_verification_id', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
       or coalesce(input->>'provider_before_fingerprint', '')
         !~ '^[0-9a-f]{64}$'
       or input->'provider_readback_stable' is distinct from 'true'::jsonb
       or pg_catalog.lower(input->>'provider_before_fingerprint')
         is distinct from
           pg_catalog.lower(input->>'provider_readback_fingerprint')
    then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_SCORING_WRITE_STARTED_NO_WRITE_FENCE_PROOF_REQUIRED';
    end if;
    readback_observed :=
      (input->>'provider_readback_observed_at')::timestamptz;
    select * into strict closure
    from production_control.scoring_admission_closures value
    where value.closure_id = (input->>'closure_id')::uuid;
    select * into strict evidence
    from production_control.scoring_external_fence_evidence value
    where value.evidence_id =
      (input->>'external_fence_evidence_id')::uuid;
    select * into strict fence
    from production_control.google_writer_provider_fences value
    where value.fence_id = (input->>'provider_fence_id')::uuid;
    select * into strict verification
    from production_control.google_writer_provider_fence_verifications value
    where value.verification_id =
        (input->>'provider_fence_verification_id')::uuid
      and value.fence_id = fence.fence_id;
    select * into strict quiesce
    from production_control.vercel_writer_quiesce_evidence value
    where value.evidence_id = (input->>'quiesce_evidence_id')::uuid;
    perform production_control.assert_current_external_scoring_fence(
      evidence.evidence_id, activation.expected_deployment_commit
    );
    perform production_control.assert_current_google_writer_provider_fence(
      fence.fence_id, verification.verification_id,
      activation.expected_deployment_commit, true
    );
    if activation.current_authority is distinct from 'GOOGLE'
       or activation.scoring_ingress_enabled
       or activation.active_transition_epoch_id is not null
       or activation.active_google_writer_provider_fence_id is distinct from
         fence.fence_id
       or activation.active_google_writer_provider_verification_id is distinct from
         verification.verification_id
       or activation.active_vercel_quiesce_evidence_id is distinct from
         quiesce.evidence_id
       or gate.state is distinct from 'PAUSED'
       or gate.authority is distinct from 'GOOGLE'
       or gate.admission_state is distinct from 'CLOSING'
       or gate.active_closure_id is distinct from closure.closure_id
       or gate.external_fence_evidence_id is distinct from evidence.evidence_id
       or gate.google_writer_provider_fence_id is distinct from fence.fence_id
       or gate.google_writer_provider_verification_id is distinct from
         verification.verification_id
       or closure.status is distinct from 'CLOSING'
       or closure.closure_kind is distinct from 'LEGACY_ADMISSION'
       or closure.authority is distinct from 'GOOGLE'
       or closure.authority_generation_id is distinct from
         activation.authority_generation_id
       or closure.admission_generation_id is distinct from
         gate.admission_generation_id
       or lease.close_fence_id is distinct from closure.closure_id
       or lease.admission_sequence > closure.lease_high_watermark
       or evidence.provider_fence_id is distinct from fence.fence_id
       or evidence.provider_fence_verification_id is distinct from
         verification.verification_id
       or evidence.quiesce_evidence_id is distinct from quiesce.evidence_id
       or fence.quiesce_evidence_id is distinct from quiesce.evidence_id
       or verification.quiesce_evidence_id is distinct from quiesce.evidence_id
       or readback_observed < greatest(
         fence.installed_at,
         verification.captured_at,
         evidence.captured_at,
         closure.closing_at
       )
       or readback_observed < pg_catalog.now() - interval '5 minutes'
       or readback_observed > pg_catalog.now() + interval '30 seconds'
       or pg_catalog.lower(input->>'resolution_fingerprint') is distinct from
         production_control.scoring_write_started_no_write_evidence_hash(
           lease.lease_id, input
         )
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_SCORING_WRITE_STARTED_NO_WRITE_FENCE_PROOF_INVALID';
    end if;
  end if;

  update scoring_authority.scoring_ingress_leases
  set resolution_state = case when requested_resolution = 'WRITE'
        then 'RESOLVED_WRITE' else 'RESOLVED_NO_WRITE' end,
      status = 'COMPLETED',
      completed_at = pg_catalog.now(),
      provider_before_fingerprint = case
        when requires_fenced_no_write_proof then
          pg_catalog.lower(input->>'provider_before_fingerprint')
        else provider_before_fingerprint
      end,
      provider_readback_fingerprint = pg_catalog.lower(
        input->>'provider_readback_fingerprint'
      ),
      resolution_fingerprint = pg_catalog.lower(
        input->>'resolution_fingerprint'
      ),
      resolved_at = pg_catalog.now(),
      resolved_by = pg_catalog.left(input->>'actor_id', 160)
  where lease_id = lease.lease_id
  returning * into lease;
  unresolved_count := production_control.scoring_admission_unresolved_count(
    gate.admission_generation_id
  );
  update scoring_authority.ingress_gates
  set unresolved_client_queues = unresolved_count,
      updated_at = pg_catalog.now()
  where tournament_id = '2026';
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_SCORING_LEASE_AMBIGUITY_RESOLVED',
    'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'lease_id', lease.lease_id,
      'resolution_state', lease.resolution_state,
      'write_started_at', lease.write_started_at,
      'fenced_no_write_proof_required', requires_fenced_no_write_proof,
      'provider_readback_fingerprint', lease.provider_readback_fingerprint,
      'resolution_fingerprint', lease.resolution_fingerprint,
      'closure_id', case when requires_fenced_no_write_proof
        then closure.closure_id else null end,
      'external_fence_evidence_id', case
        when requires_fenced_no_write_proof then evidence.evidence_id
        else null end,
      'active_or_unresolved_leases', unresolved_count
    )
  );
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'PRODUCTION_SCORING_LEASE_AMBIGUITY_RESOLVED',
    'lease_id', lease.lease_id,
    'resolution_state', lease.resolution_state,
    'fenced_no_write_proof_required', requires_fenced_no_write_proof,
    'active_or_unresolved_leases', unresolved_count,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'RESOLVE_SCORING_INGRESS_AMBIGUITY', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.resolve_production_scoring_ingress_ambiguity(input jsonb) OWNER TO postgres;

--
-- Name: resume_production_google_scoring_after_maintenance_rollback(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resume_production_google_scoring_after_maintenance_rollback(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  next_generation uuid := extensions.gen_random_uuid();
  captured_at timestamptz;
  response_value jsonb;
begin
  perform production_control.assert_maintenance_common_input(input);
  captured_at := (input->>'google_source_captured_at')::timestamptz;
  existing := production_control.lookup_cutover_receipt(
    'RESUME_GOOGLE_AFTER_MAINTENANCE_ROLLBACK', input
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  perform production_control.assert_maintenance_google_reopen_safe(input);
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = gate.active_closure_id for update;
  if activation.state <> 'ROLLED_BACK'
     or activation.maintenance_state <> 'SCORING_MAINTENANCE'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_state <> 'CLOSED'
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.closure_kind <> 'LEGACY_ADMISSION'
     or closure.status <> 'CLOSED'
     or coalesce(input->>'google_source_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.lower(input->>'google_source_fingerprint') is distinct from
       closure.final_source_fingerprint
     or captured_at < closure.closed_at or captured_at > pg_catalog.now()
     or captured_at < pg_catalog.now() - interval '5 minutes' then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_GOOGLE_NOT_RESUMABLE';
  end if;
  update production_control.scoring_admission_closures
  set status = 'REOPENED', reopened_at = pg_catalog.now()
  where closure_id = closure.closure_id;
  update scoring_authority.ingress_gates
  set state = 'OPEN', admission_state = 'OPEN',
      admission_revision = admission_revision + 1,
      admission_generation_id = next_generation,
      admission_opened_at = pg_catalog.now(), active_closure_id = null,
      external_fence_evidence_id = null,
      google_writer_provider_fence_id = null,
      google_writer_provider_verification_id = null,
      unresolved_client_queues = 0,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where tournament_id = '2026' returning * into gate;
  update production_control.cutover_activation_state
  set state = 'GOOGLE_LEASE_ARMED', maintenance_state = 'NORMAL',
      maintenance_ended_at = pg_catalog.now(),
      activation_revision = activation_revision + 1,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = pg_catalog.now()
  where scope_key = 'BAGGER_INV_PRODUCTION' returning * into activation;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_GOOGLE_SCORING_RESUMED_AFTER_ROLLBACK',
    'authority', 'GOOGLE', 'ingress', 'OPEN',
    'admission_state', 'OPEN', 'maintenance_state', 'NORMAL',
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'admission_revision', gate.admission_revision,
    'first_supabase_canonical_write_observed',
      activation.first_supabase_write_observed_at is not null,
    'reconciliation_complete',
      activation.first_supabase_write_observed_at is null
      or input->>'reconciliation_complete' = 'true',
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'RESUME_GOOGLE_AFTER_MAINTENANCE_ROLLBACK', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.resume_production_google_scoring_after_maintenance_rollback(input jsonb) OWNER TO postgres;

--
-- Name: resume_production_supabase_scoring(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resume_production_supabase_scoring(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  resumed_at timestamptz;
  response_value jsonb;
begin
  perform production_control.assert_maintenance_common_input(input);
  if coalesce(input->>'runtime_verification_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'configuration_fingerprint', '')
       !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_SUPABASE_SCORING_RESUME_EVIDENCE_INVALID';
  end if;
  existing := production_control.lookup_cutover_receipt(
    'RESUME_SUPABASE_SCORING', input
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select * into strict epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = (input->>'epoch_id')::uuid for update;
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = epoch.admission_closure_id for update;
  if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or activation.maintenance_state <> 'SCORING_MAINTENANCE'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.expected_deployment_commit is distinct from
       input->>'deployment_commit'
     or activation.authority_generation_id is distinct from epoch.epoch_id
     or (input->>'expected_authority_generation')::uuid is distinct from
       epoch.epoch_id
     or resource.scoring_authority <> 'SUPABASE'
     or resource.scoring_ingress_enabled or resource.workers_enabled
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'SUPABASE' or gate.state <> 'PAUSED'
     or gate.admission_state <> 'CLOSED'
     or gate.active_epoch_id is distinct from epoch.epoch_id
     or gate.active_closure_id is distinct from closure.closure_id
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.admission_deployment_id is distinct from input->>'deployment_id'
     or not gate.admission_protocol_enforced
     or gate.unresolved_client_queues <> 0
     or epoch.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or epoch.status <> 'COMMITTED' or epoch.epoch_type <> 'CUTOVER'
     or epoch.authority_after <> 'SUPABASE'
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.status <> 'CONSUMED'
     or pg_catalog.lower(input->>'configuration_fingerprint') is distinct from
       activation.staged_environment_delta_fingerprint_v2
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or exists (
       select 1 from production_control.worker_controls value
       where value.enabled
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_SUPABASE_SCORING_NOT_RESUMABLE';
  end if;
  resumed_at := pg_catalog.now();
  update scoring_authority.ingress_gates
  set state = 'OPEN', admission_revision = admission_revision + 1,
      unresolved_client_queues = 0,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = resumed_at
  where tournament_id = '2026' returning * into gate;
  update production_control.resource_scope
  set scoring_ingress_enabled = true, updated_at = resumed_at
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update production_control.cutover_activation_state
  set maintenance_state = 'NORMAL', maintenance_ended_at = resumed_at,
      scoring_ingress_enabled = true,
      first_supabase_write_possible_at = resumed_at,
      activation_revision = activation_revision + 1,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = resumed_at
  where scope_key = 'BAGGER_INV_PRODUCTION' returning * into activation;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_SUPABASE_SCORING_RESUMED',
    'boundary_mode', 'MAINTENANCE_WINDOW_V1',
    'maintenance_state', 'NORMAL',
    'epoch_id', epoch.epoch_id, 'authority', 'SUPABASE',
    'ingress', 'OPEN', 'admission_state', 'CLOSED',
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'admission_revision', gate.admission_revision,
    'first_supabase_canonical_write_possible', true,
    'first_supabase_canonical_write_possible_at', resumed_at,
    'first_supabase_canonical_write_observed', false,
    'runtime_verification_fingerprint',
      pg_catalog.lower(input->>'runtime_verification_fingerprint'),
    'configuration_fingerprint',
      pg_catalog.lower(input->>'configuration_fingerprint'),
    'idempotent', false
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'FIRST_SUPABASE_CANONICAL_WRITE_POSSIBLE',
    'SCORING_AUTHORITY', '2026',
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.lower(input->>'request_fingerprint'), 'SUCCEEDED',
    response_value - 'ok' - 'idempotent'
  );
  perform production_control.store_cutover_receipt(
    'RESUME_SUPABASE_SCORING', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.resume_production_supabase_scoring(input jsonb) OWNER TO postgres;

--
-- Name: retire_production_player_ghin_identity_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retire_production_player_ghin_identity_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text; actor_player text; actor_auth uuid; request_id uuid; declared_hash text; database_hash text;
  player_value text; expected_value uuid; current_value production_control.player_external_identities_v1%rowtype;
  prior production_control.handicap_source_operation_receipts_v1%rowtype; response_value jsonb; event_value uuid := extensions.gen_random_uuid();
begin
  target := production_control.assert_handicap_source_runtime_v1(input); actor_player:=pg_catalog.upper(pg_catalog.btrim(input#>>'{authorization,player_id}')); actor_auth:=(input#>>'{authorization,auth_user_id}')::uuid;
  declared_hash:=pg_catalog.lower(pg_catalog.btrim(coalesce(input->>'request_payload_hash','')));
  if input->>'operation' is distinct from 'RETIRE_PRODUCTION_PLAYER_GHIN_IDENTITY_V1' or coalesce(input->>'operation_request_id','') !~ '^[0-9a-fA-F-]{36}$' or coalesce(input->>'expected_identity_id','') !~ '^[0-9a-fA-F-]{36}$' or coalesce((input->>'retirement_confirmed')::boolean,false) is not true or declared_hash !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='PRODUCTION_GHIN_IDENTITY_RETIREMENT_INPUT_INVALID'; end if;
  request_id:=(input->>'operation_request_id')::uuid; player_value:=pg_catalog.upper(input->>'player_id'); expected_value:=(input->>'expected_identity_id')::uuid;
  database_hash:=production_control.handicap_source_hash_v1(pg_catalog.jsonb_build_object('operation','RETIRE_IDENTITY','playerId',player_value,'expectedIdentityId',expected_value,'actorPlayerId',actor_player,'actorAuthUserId',actor_auth));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('production-ghin-identity:'||player_value,0));
  select value.* into prior from production_control.handicap_source_operation_receipts_v1 value where value.tournament_id=target and value.operation_request_id=request_id;
  if found then if prior.declared_request_payload_hash=declared_hash and prior.database_request_payload_hash=database_hash then return prior.response||pg_catalog.jsonb_build_object('idempotent',true); end if; raise exception using errcode='23505',message='PRODUCTION_HANDICAP_SOURCE_IDEMPOTENCY_CONFLICT'; end if;
  select value.* into current_value from production_control.player_external_identities_v1 value where value.player_id=player_value and value.provider='GHIN' and value.status='VERIFIED' for update;
  if current_value.identity_id is distinct from expected_value then raise exception using errcode='40001',message='PRODUCTION_GHIN_IDENTITY_STALE'; end if;
  update production_control.player_external_identities_v1 set status='RETIRED',retired_at=pg_catalog.clock_timestamp(),retired_by_player_id=actor_player,retired_by_auth_user_id=actor_auth where identity_id=expected_value;
  delete from production_control.handicap_source_current_v1 where tournament_id=target and player_id=player_value and provider='GHIN';
  response_value:=pg_catalog.jsonb_build_object('ok',true,'code','PRODUCTION_GHIN_IDENTITY_RETIRED','idempotent',false,'playerId',player_value,'identityId',expected_value,'eventId',event_value);
  insert into production_control.handicap_source_audit_events_v1(event_id,tournament_id,action,player_id,identity_id,actor_player_id,actor_auth_user_id,operation_request_id,before_state,after_state) values(event_value,target,'GHIN_IDENTITY_RETIRED',player_value,expected_value,actor_player,actor_auth,request_id,pg_catalog.jsonb_build_object('identityId',expected_value,'status','VERIFIED'),pg_catalog.jsonb_build_object('identityId',expected_value,'status','RETIRED'));
  perform production_control.handicap_source_receipt_v1(target,'RETIRE_IDENTITY',request_id,declared_hash,database_hash,actor_player,actor_auth,response_value); return response_value;
end;
$_$;


ALTER FUNCTION public.retire_production_player_ghin_identity_v1(input jsonb) OWNER TO postgres;

--
-- Name: retire_production_vercel_writer_rejected_waf_epoch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retire_production_vercel_writer_rejected_waf_epoch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  epoch production_control.vercel_writer_critical_waf_epochs%rowtype;
  dispatch production_control.vercel_writer_critical_waf_dispatches%rowtype;
  dispatch_result
    production_control.vercel_writer_critical_waf_dispatch_results%rowtype;
  prior_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  inserted_observation
    production_control.vercel_writer_critical_waf_observations%rowtype;
  evidence jsonb := input->'verified_waf_evidence';
  retirement_request uuid;
  observation_request uuid;
  evidence_identifier uuid;
  evidence_request uuid;
  payload_hash_value text := production_control.cutover_payload_hash(input);
  provider_observed timestamptz;
  attested timestamptz;
  expires timestamptz;
  retired_at_value timestamptz;
  allowed_keys text[] := array[
    'environment', 'project_ref', 'project_url', 'source_workbook_id',
    'tournament_id', 'actor_id', 'authenticated_actor_fingerprint',
    'operation', 'epoch_id', 'retirement_request_id',
    'fresh_baseline_observation_request_id', 'request_fingerprint',
    'candidate_deployment_id', 'candidate_deployment_commit',
    'verified_waf_evidence'
  ];
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if pg_catalog.jsonb_typeof(input) is distinct from 'object'
     or not (input ?& allowed_keys)
     or (input - allowed_keys) is distinct from '{}'::jsonb
     or input->>'operation' is distinct from
       'RETIRE_PRODUCTION_VERCEL_WRITER_REJECTED_WAF_EPOCH'
     or coalesce(input->>'epoch_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'retirement_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'fresh_baseline_observation_request_id', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(input->>'request_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(input->>'candidate_deployment_id', '')
       !~ '^dpl_[A-Za-z0-9]{8,64}$'
     or coalesce(input->>'candidate_deployment_commit', '')
       !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'authenticated_actor_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.btrim(coalesce(input->>'actor_id', '')) = ''
     or pg_catalog.length(input->>'actor_id') > 160
     or pg_catalog.jsonb_typeof(evidence) is distinct from 'object'
     or (
       select pg_catalog.count(*)
       from pg_catalog.jsonb_object_keys(evidence)
     ) <> 49
     or not (evidence ?& array[
       'schemaVersion', 'evidenceId', 'evidenceRequestId', 'wafEpochId',
       'transitionRequestId', 'requestFingerprint', 'stage', 'purpose',
       'transitionMode', 'vercelProjectId', 'vercelTeamId',
       'candidateAliasOrigin', 'candidateImmutableOrigin',
       'candidateDeploymentId', 'candidateCommitSha',
       'candidateDeploymentTarget', 'runOwnedRuleName', 'runOwnedRuleNonce',
       'runOwnedRuleFingerprint', 'runOwnedInsertDocumentFingerprint',
       'providerAssignedRuleId', 'baselineEvidenceId', 'criticalEvidenceId',
       'baselineConfigurationVersion',
       'baselineSourceVersionReadFingerprint', 'configurationMode',
       'configurationVersion', 'configurationEtag',
       'providerConfigurationId', 'providerOwnerId',
       'configurationIdentityFingerprint', 'semanticConfiguration',
       'semanticConfigurationFingerprint', 'orderedCustomRulesFingerprint',
       'baselineSemanticFingerprint', 'criticalSemanticFingerprint',
       'customRuleCount', 'runOwnedProviderRuleDocumentFingerprint',
       'runOwnedRulePrecedence', 'criticalWindowContractFingerprint',
       'pendingDraftChangeCount', 'providerObservedAt', 'attestedAt',
       'expiresAt', 'sourceVersionReadFingerprint', 'evidenceFingerprint',
       'signerKeyFingerprint', 'signerKeyVersion', 'signatureVerified'
     ]::text[])
     or evidence->>'schemaVersion' is distinct from
       'bagger-vercel-waf-provider-evidence-v1'
     or evidence->'signatureVerified' is distinct from 'true'::jsonb
     or evidence->>'signerKeyVersion' is distinct from
       'STEP11_6_VERCEL_ATTESTER_V1'
     or evidence->>'stage' is distinct from 'BASELINE_CAPTURE'
     or evidence->>'configurationMode' is distinct from 'BASELINE'
     or evidence->>'candidateDeploymentTarget' is distinct from 'PREVIEW'
     or evidence->>'candidateDeploymentId' is distinct from
       input->>'candidate_deployment_id'
     or pg_catalog.lower(evidence->>'candidateCommitSha') is distinct from
       pg_catalog.lower(input->>'candidate_deployment_commit')
     or coalesce(evidence->>'candidateAliasOrigin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(evidence->>'candidateImmutableOrigin', '')
       !~ '^https://[a-z0-9.-]+$'
     or coalesce(evidence->>'evidenceId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(evidence->>'evidenceRequestId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(evidence->>'transitionRequestId', '')
       !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(evidence->>'requestFingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(evidence->>'evidenceFingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(evidence->>'signerKeyFingerprint', '') !~ '^[0-9a-f]{64}$'
     or coalesce(evidence->>'configurationIdentityFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(evidence->>'semanticConfigurationFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(evidence->>'orderedCustomRulesFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(evidence->>'baselineSemanticFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce(evidence->>'sourceVersionReadFingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(evidence->'semanticConfiguration')
       is distinct from 'object'
     or (
       select pg_catalog.count(*)
       from pg_catalog.jsonb_object_keys(evidence->'semanticConfiguration')
     ) <> 7
     or not ((evidence->'semanticConfiguration') ?& array[
       'schemaVersion', 'securityConfigurationKeys',
       'securityConfigurationKeysFingerprint', 'firewallEnabled', 'ips',
       'crs', 'orderedCustomRules'
     ]::text[])
     or evidence->'semanticConfiguration'->'firewallEnabled'
       is distinct from 'true'::jsonb
     or pg_catalog.jsonb_typeof(
       evidence->'semanticConfiguration'->'orderedCustomRules'
     ) is distinct from 'array'
     or pg_catalog.jsonb_array_length(
       evidence->'semanticConfiguration'->'orderedCustomRules'
     ) <> 0
     or evidence->>'providerAssignedRuleId' is not null
     or evidence->>'baselineEvidenceId' is not null
     or evidence->>'criticalEvidenceId' is not null
     or evidence->>'baselineConfigurationVersion' is not null
     or evidence->>'baselineSourceVersionReadFingerprint' is not null
     or evidence->>'criticalSemanticFingerprint' is not null
     or evidence->>'runOwnedProviderRuleDocumentFingerprint' is not null
     or evidence->>'runOwnedRulePrecedence' is not null
     or evidence->>'criticalWindowContractFingerprint' is not null
     or coalesce(evidence->>'customRuleCount', '') !~ '^0$'
     or coalesce(evidence->>'pendingDraftChangeCount', '') !~ '^0$'
  then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_VERCEL_WRITER_REJECTED_WAF_RETIREMENT_INPUT_INVALID';
  end if;

  retirement_request := (input->>'retirement_request_id')::uuid;
  observation_request :=
    (input->>'fresh_baseline_observation_request_id')::uuid;
  evidence_identifier := (evidence->>'evidenceId')::uuid;
  evidence_request := (evidence->>'evidenceRequestId')::uuid;
  if evidence->>'wafEpochId' is distinct from input->>'epoch_id'
     or (evidence->>'transitionRequestId')::uuid is distinct from
       retirement_request
     or (
       select pg_catalog.count(distinct identifier)
       from pg_catalog.unnest(array[
         retirement_request, observation_request,
         evidence_identifier, evidence_request
       ]) identifier
     ) <> 4
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_REJECTED_WAF_RETIREMENT_IDENTITY_INVALID';
  end if;

  provider_observed := (evidence->>'providerObservedAt')::timestamptz;
  attested := (evidence->>'attestedAt')::timestamptz;
  expires := (evidence->>'expiresAt')::timestamptz;

  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026'
  for update;
  select * into strict epoch
  from production_control.vercel_writer_critical_waf_epochs value
  where value.epoch_id = (input->>'epoch_id')::uuid
  for update;

  -- Every call, including a lost-response retry, must carry a fresh signed
  -- readback of the exact baseline. The durable request identity and evidence
  -- IDs remain stable across a retry; time-bound signature/fingerprint fields
  -- may be refreshed without creating a second observation or audit event.
  if epoch.status not in ('ACTIVATION_PENDING', 'REJECTED_RETIRED')
     or epoch.critical_active_observation_id is not null
     or epoch.provider_assigned_rule_id is not null
     or epoch.bound_fence_id is not null
     or epoch.bound_quiesce_evidence_id is not null
     or evidence->>'purpose' is distinct from epoch.purpose
     or evidence->>'transitionMode' is distinct from epoch.transition_mode
     or evidence->>'vercelProjectId' is distinct from epoch.vercel_project_id
     or evidence->>'vercelTeamId' is distinct from epoch.vercel_team_id
     or evidence->>'runOwnedRuleName' is distinct from epoch.run_owned_rule_name
     or (evidence->>'runOwnedRuleNonce')::uuid is distinct from
       epoch.run_owned_rule_nonce
     or pg_catalog.lower(evidence->>'runOwnedRuleFingerprint') is distinct from
       epoch.run_owned_rule_fingerprint
     or pg_catalog.lower(
       evidence->>'runOwnedInsertDocumentFingerprint'
     ) is distinct from epoch.run_owned_insert_document_fingerprint
     or evidence->>'configurationVersion' is distinct from
       epoch.baseline_active_config_version
     or nullif(evidence->>'configurationEtag', '') is distinct from
       epoch.baseline_active_config_etag
     or evidence->>'providerConfigurationId' is distinct from
       epoch.baseline_provider_configuration_id
     or evidence->>'providerOwnerId' is distinct from
       epoch.baseline_provider_owner_id
     or pg_catalog.lower(
       evidence->>'configurationIdentityFingerprint'
     ) is distinct from epoch.baseline_configuration_identity_fingerprint
     or pg_catalog.lower(
       evidence->>'sourceVersionReadFingerprint'
     ) is distinct from epoch.baseline_source_version_read_fingerprint
     or pg_catalog.lower(
       evidence->>'semanticConfigurationFingerprint'
     ) is distinct from epoch.baseline_semantic_configuration_fingerprint
     or pg_catalog.lower(
       evidence->>'baselineSemanticFingerprint'
     ) is distinct from epoch.baseline_semantic_configuration_fingerprint
     or pg_catalog.lower(
       evidence->>'orderedCustomRulesFingerprint'
     ) is distinct from epoch.baseline_ordered_rules_fingerprint
     or provider_observed is distinct from attested
     or provider_observed < pg_catalog.clock_timestamp() - interval '120 seconds'
     or provider_observed > pg_catalog.clock_timestamp() + interval '30 seconds'
     or expires is distinct from attested + interval '2100 seconds'
     or expires <= pg_catalog.clock_timestamp()
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_REJECTED_WAF_RETIREMENT_BASELINE_INVALID';
  end if;

  select * into prior_observation
  from production_control.vercel_writer_critical_waf_observations value
  where value.observation_id = epoch.retirement_observation_id;
  if epoch.status = 'REJECTED_RETIRED' then
    if epoch.retirement_request_id is distinct from retirement_request
       or epoch.retirement_request_fingerprint is distinct from
         pg_catalog.lower(input->>'request_fingerprint')
       or epoch.retirement_candidate_deployment_id is distinct from
         input->>'candidate_deployment_id'
       or epoch.retirement_candidate_deployment_commit is distinct from
         pg_catalog.lower(input->>'candidate_deployment_commit')
       or epoch.retirement_reason is distinct from
         'PROVIDER_REJECTED_NO_MUTATION'
       or prior_observation.observation_id is null
       or prior_observation.record_request_id is distinct from
         observation_request
       or prior_observation.provider_evidence_id is distinct from
         evidence_identifier
       or prior_observation.evidence_request_id is distinct from
         evidence_request
       or prior_observation.evidence_fingerprint is distinct from
         epoch.retirement_evidence_fingerprint
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_VERCEL_WRITER_REJECTED_WAF_RETIREMENT_IDEMPOTENCY_CONFLICT';
    end if;
    return production_control.vercel_writer_critical_waf_epoch_response(
      epoch, true
    ) || pg_catalog.jsonb_build_object(
      'retirement_request_id', epoch.retirement_request_id,
      'retirement_observation_id', epoch.retirement_observation_id,
      'retirement_evidence_fingerprint',
        epoch.retirement_evidence_fingerprint,
      'retirement_reason', epoch.retirement_reason,
      'retired_at', epoch.retired_at,
      'provider_mutation_performed', false
    );
  end if;

  if epoch.retirement_request_id is not null
     or activation.state is distinct from 'DORMANT'
     or activation.current_authority is distinct from 'GOOGLE'
     or activation.scoring_ingress_enabled
     or activation.first_supabase_write_possible_at is not null
     or activation.first_supabase_write_observed_at is not null
     or activation.active_transition_epoch_id is not null
     or activation.active_google_writer_provider_fence_id is not null
     or activation.active_google_writer_provider_verification_id is not null
     or activation.active_vercel_quiesce_evidence_id is not null
     or resource.scoring_authority is distinct from 'GOOGLE'
     or resource.participant_identity_authority is distinct from 'PASSPORT'
     or resource.scoring_ingress_enabled
     or resource.workers_enabled
     or gate.state is distinct from 'PAUSED'
     or gate.authority is distinct from 'GOOGLE'
     or gate.admission_state is distinct from 'OPEN'
     or gate.admission_protocol_enforced
     or gate.active_closure_id is not null
     or gate.external_fence_evidence_id is not null
     or gate.google_writer_provider_fence_id is not null
     or gate.google_writer_provider_verification_id is not null
     or exists (
       select 1
       from production_control.worker_controls value
       where value.enabled or value.google_writes_allowed
     )
     or exists (select 1 from scoring_authority.score_mutations)
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_REJECTED_WAF_RETIREMENT_STATE_INVALID';
  end if;

  select * into dispatch
  from production_control.vercel_writer_critical_waf_dispatches value
  where value.epoch_id = epoch.epoch_id
  for update;
  if not found
     or dispatch.dispatch_step is distinct from 'CRITICAL_RULE_INSERT'
     or dispatch.status is distinct from 'PROVIDER_REJECTED'
     or dispatch.provider_dispatch_started_at is null
     or dispatch.provider_dispatch_result_id is null
     or dispatch.provider_result_observation_id is not null
     or dispatch.provider_result_fingerprint is null
     or dispatch.provider_observed_at is null
     or dispatch.recorded_at is null
     or (
       select pg_catalog.count(*)
       from production_control.vercel_writer_critical_waf_dispatches value
       where value.epoch_id = epoch.epoch_id
     ) <> 1
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_REJECTED_WAF_RETIREMENT_DISPATCH_INVALID';
  end if;

  select * into strict dispatch_result
  from production_control.vercel_writer_critical_waf_dispatch_results value
  where value.result_id = dispatch.provider_dispatch_result_id;
  if dispatch_result.dispatch_id is distinct from dispatch.dispatch_id
     or dispatch_result.epoch_id is distinct from epoch.epoch_id
     or dispatch_result.dispatch_step is distinct from 'CRITICAL_RULE_INSERT'
     or dispatch_result.outcome_status is distinct from 'PROVIDER_REJECTED'
     or not dispatch_result.provider_response_observed
     or dispatch_result.provider_response_status not between 400 and 599
     or dispatch_result.provider_response_fingerprint is null
     or dispatch_result.provider_readback_fingerprint is not null
     or dispatch_result.active_semantic_configuration is not null
     or dispatch_result.active_semantic_configuration_fingerprint is not null
     or dispatch_result.active_custom_rule_count is not null
     or dispatch_result.active_pending_draft_present is not null
     or dispatch_result.draft_semantic_configuration is not null
     or dispatch_result.draft_semantic_configuration_fingerprint is not null
     or dispatch_result.draft_ordered_rules_fingerprint is not null
     or dispatch_result.draft_configuration_version is not null
     or dispatch_result.draft_configuration_identity_fingerprint is not null
     or dispatch_result.draft_custom_rule_count is not null
     or dispatch_result.pending_draft_change_count is not null
     or dispatch_result.provider_assigned_rule_id is not null
     or dispatch_result.run_owned_provider_rule_document_fingerprint is not null
     or dispatch_result.run_owned_rule_precedence is not null
     or dispatch_result.critical_window_contract_fingerprint is not null
     or (
       select pg_catalog.count(*)
       from production_control.vercel_writer_critical_waf_dispatch_results value
       where value.dispatch_id = dispatch.dispatch_id
     ) <> 1
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_VERCEL_WRITER_REJECTED_WAF_RETIREMENT_RESULT_INVALID';
  end if;

  insert into production_control.vercel_writer_critical_waf_observations (
    observation_id, epoch_id, provider_evidence_id, provider_evidence_schema,
    evidence_request_id, transition_request_id, evidence_stage,
    record_request_id, record_request_fingerprint, record_payload_hash,
    request_fingerprint, evidence_fingerprint, signer_key_fingerprint,
    signer_key_version, purpose, transition_mode,
    vercel_project_id, vercel_team_id,
    candidate_alias_origin, candidate_immutable_origin,
    candidate_deployment_id, candidate_commit_sha,
    candidate_deployment_target, configuration_mode,
    active_config_version, active_config_etag,
    provider_configuration_id, provider_owner_id,
    configuration_identity_fingerprint, semantic_configuration,
    semantic_configuration_fingerprint, ordered_rules_fingerprint,
    custom_rule_count, baseline_configuration_version,
    baseline_source_version_read_fingerprint,
    source_version_read_fingerprint, baseline_evidence_id,
    critical_evidence_id, baseline_semantic_fingerprint,
    critical_semantic_fingerprint, run_owned_rule_name, run_owned_rule_nonce,
    provider_assigned_rule_id, run_owned_rule_fingerprint,
    run_owned_insert_document_fingerprint,
    run_owned_provider_rule_document_fingerprint,
    run_owned_rule_precedence, critical_window_contract_fingerprint,
    pending_draft_change_count, provider_observed_at, attested_at, expires_at
  ) values (
    extensions.gen_random_uuid(), epoch.epoch_id, evidence_identifier,
    evidence->>'schemaVersion', evidence_request, retirement_request,
    'BASELINE_CAPTURE', observation_request,
    pg_catalog.lower(input->>'request_fingerprint'), payload_hash_value,
    pg_catalog.lower(evidence->>'requestFingerprint'),
    pg_catalog.lower(evidence->>'evidenceFingerprint'),
    pg_catalog.lower(evidence->>'signerKeyFingerprint'),
    evidence->>'signerKeyVersion', epoch.purpose, epoch.transition_mode,
    epoch.vercel_project_id, epoch.vercel_team_id,
    pg_catalog.lower(evidence->>'candidateAliasOrigin'),
    pg_catalog.lower(evidence->>'candidateImmutableOrigin'),
    input->>'candidate_deployment_id',
    pg_catalog.lower(input->>'candidate_deployment_commit'), 'PREVIEW',
    'BASELINE', evidence->>'configurationVersion',
    nullif(evidence->>'configurationEtag', ''),
    evidence->>'providerConfigurationId', evidence->>'providerOwnerId',
    pg_catalog.lower(evidence->>'configurationIdentityFingerprint'),
    evidence->'semanticConfiguration',
    pg_catalog.lower(evidence->>'semanticConfigurationFingerprint'),
    pg_catalog.lower(evidence->>'orderedCustomRulesFingerprint'), 0,
    null, null,
    pg_catalog.lower(evidence->>'sourceVersionReadFingerprint'),
    null, null,
    pg_catalog.lower(evidence->>'baselineSemanticFingerprint'), null,
    epoch.run_owned_rule_name, epoch.run_owned_rule_nonce, null,
    epoch.run_owned_rule_fingerprint,
    epoch.run_owned_insert_document_fingerprint,
    null, null, null, 0, provider_observed, attested, expires
  ) returning * into inserted_observation;

  retired_at_value := pg_catalog.clock_timestamp();
  update production_control.vercel_writer_critical_waf_epochs
  set status = 'REJECTED_RETIRED',
      retirement_request_id = retirement_request,
      retirement_request_fingerprint =
        pg_catalog.lower(input->>'request_fingerprint'),
      retirement_payload_hash = payload_hash_value,
      retirement_observation_id = inserted_observation.observation_id,
      retirement_evidence_fingerprint =
        inserted_observation.evidence_fingerprint,
      retirement_candidate_deployment_id = input->>'candidate_deployment_id',
      retirement_candidate_deployment_commit =
        pg_catalog.lower(input->>'candidate_deployment_commit'),
      retirement_reason = 'PROVIDER_REJECTED_NO_MUTATION',
      retired_at = retired_at_value,
      updated_at = retired_at_value
  where epoch_id = epoch.epoch_id
    and status = 'ACTIVATION_PENDING'
    and retirement_request_id is null
  returning * into strict epoch;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor,
    request_fingerprint, result, details
  ) values (
    'PRODUCTION_VERCEL_WRITER_REJECTED_WAF_EPOCH_RETIRED',
    'SCORING_AUTHORITY', '2026', pg_catalog.left(input->>'actor_id', 160),
    epoch.retirement_request_fingerprint, 'SUCCEEDED',
    pg_catalog.jsonb_build_object(
      'epoch_id', epoch.epoch_id,
      'retirement_request_id', epoch.retirement_request_id,
      'retirement_observation_id', epoch.retirement_observation_id,
      'retirement_evidence_fingerprint',
        epoch.retirement_evidence_fingerprint,
      'retirement_candidate_deployment_id',
        epoch.retirement_candidate_deployment_id,
      'retirement_candidate_deployment_commit',
        epoch.retirement_candidate_deployment_commit,
      'retirement_reason', epoch.retirement_reason,
      'rejected_dispatch_id', dispatch.dispatch_id,
      'rejected_dispatch_result_id', dispatch_result.result_id,
      'provider_response_status', dispatch_result.provider_response_status,
      'provider_mutation_performed', false,
      'retired_at', epoch.retired_at
    )
  );

  return production_control.vercel_writer_critical_waf_epoch_response(
    epoch, false
  ) || pg_catalog.jsonb_build_object(
    'retirement_request_id', epoch.retirement_request_id,
    'retirement_observation_id', epoch.retirement_observation_id,
    'retirement_evidence_fingerprint', epoch.retirement_evidence_fingerprint,
    'retirement_reason', epoch.retirement_reason,
    'retired_at', epoch.retired_at,
    'provider_mutation_performed', false
  );
end;
$_$;


ALTER FUNCTION public.retire_production_vercel_writer_rejected_waf_epoch(input jsonb) OWNER TO postgres;

--
-- Name: revoke_production_director_entitlement(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.revoke_production_director_entitlement(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'public', 'pg_temp'
    AS $$
declare target_user uuid := nullif(input->>'auth_user_id', '')::uuid;
declare actor constant text := 'step10b-production-director-certification';
declare reason text := upper(btrim(coalesce(input->>'reason', 'CONTROLLED_REVOCATION')));
declare scope production_control.resource_scope%rowtype;
declare current production_control.director_entitlements%rowtype;
declare event_revision bigint;
begin
  scope := production_control.assert_production_auth_candidate_rpc();
  if btrim(coalesce(input->>'tournament_id', '')) <> '2026' or target_user is null
    or btrim(coalesce(input->>'project_ref', '')) <> scope.project_ref then
    raise exception 'Exact Production Director revocation context is required.';
  end if;
  if reason not in ('CONTROLLED_REVOCATION', 'CERTIFICATION_CLEANUP', 'SECURITY_RESPONSE') then
    raise exception using errcode = '22023', message = 'PRODUCTION_DIRECTOR_REVOCATION_REASON_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'production-director-entitlement:2026:' || target_user::text, 0
  ));
  select * into current from production_control.director_entitlements
  where auth_user_id = target_user and tournament_id = '2026' for update;
  if not found or current.status = 'REVOKED' then
    return jsonb_build_object('ok', true, 'changed', false, 'active', false);
  end if;
  update production_control.director_entitlements set
    status = 'REVOKED', revoked_at = now()
  where auth_user_id = target_user and tournament_id = '2026';
  update participant_identity.tournament_roles set
    role_active = false, role_revision = role_revision + 1, revoked_at = now(),
    revoked_by = actor, updated_at = now()
  where auth_user_id = target_user and tournament_id = '2026' and role = 'DIRECTOR';
  insert into production_control.director_entitlement_events (
    entitlement_id, action, actor, reason
  ) values (current.entitlement_id, 'REVOKED', actor, reason)
  returning event_id into event_revision;
  return jsonb_build_object('ok', true, 'changed', true, 'active', false,
    'revision', event_revision, 'entitlementId', current.entitlement_id);
end;
$$;


ALTER FUNCTION public.revoke_production_director_entitlement(input jsonb) OWNER TO postgres;

--
-- Name: rollback_production_maintenance_authority_epoch(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rollback_production_maintenance_authority_epoch(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  closure production_control.scoring_admission_closures%rowtype;
  legacy_closure production_control.scoring_admission_closures%rowtype;
  prior_epoch scoring_authority.authority_epochs%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  next_generation uuid := extensions.gen_random_uuid();
  boundary_at timestamptz;
  response_value jsonb;
begin
  perform production_control.assert_maintenance_common_input(input);
  if coalesce(input->>'reconciliation_fingerprint', '')
       !~ '^[0-9a-f]{64}$'
     or coalesce((input->>'lost_write_count')::integer, -1) <> 0
     or coalesce((input->>'duplicate_write_count')::integer, -1) <> 0
     or coalesce((input->>'unresolved_write_count')::integer, -1) <> 0 then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_MAINTENANCE_ROLLBACK_INPUT_INVALID';
  end if;
  existing := production_control.lookup_cutover_receipt(
    'ROLLBACK_MAINTENANCE_AUTHORITY_EPOCH', input
  );
  if existing is not null then return existing; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    production_control.scoring_admission_lock_key()
  );
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION' for update;
  select * into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026' for update;
  select * into strict closure
  from production_control.scoring_admission_closures value
  where value.closure_id = (input->>'closure_id')::uuid for update;
  select * into strict prior_epoch
  from scoring_authority.authority_epochs value
  where value.epoch_id = gate.active_epoch_id for update;
  if activation.current_authority <> 'SUPABASE'
     or activation.scoring_ingress_enabled
     or activation.maintenance_state <> 'SCORING_MAINTENANCE'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.activation_revision is distinct from
       (input->>'expected_activation_revision')::bigint
     or activation.authority_generation_id is distinct from
       (input->>'expected_authority_generation')::uuid
     or gate.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or gate.authority <> 'SUPABASE' or gate.state <> 'PAUSED'
     or gate.admission_state <> 'CLOSED'
     or gate.admission_generation_id is distinct from
       (input->>'expected_admission_generation')::uuid
     or gate.admission_revision is distinct from
       (input->>'expected_admission_revision')::bigint
     or gate.active_closure_id is distinct from closure.closure_id
     or closure.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or closure.closure_kind <> 'SUPABASE_INGRESS'
     or closure.authority <> 'SUPABASE' or closure.status <> 'CLOSED'
     or closure.final_source_fingerprint is distinct from
       closure.supabase_shadow_fingerprint
     or closure.reconciliation_fingerprint is distinct from
       pg_catalog.lower(input->>'reconciliation_fingerprint')
     or prior_epoch.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
     or prior_epoch.status <> 'COMMITTED'
     or prior_epoch.authority_after <> 'SUPABASE'
     or (activation.first_supabase_write_observed_at is not null
       and input->>'reconciliation_complete' is distinct from 'true')
     or production_control.scoring_admission_unresolved_count(
       gate.admission_generation_id
     ) <> 0
     or exists (
       select 1 from scoring_authority.google_outbox_events event
       where event.tournament_id = '2026' and event.status <> 'DELIVERED'
     )
     or exists (
       select 1 from scoring_authority.scorecard_archive_jobs job
       where job.tournament_id = '2026'
         and job.status not in ('VERIFIED', 'SUPERSEDED')
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_ROLLBACK_NOT_SAFE';
  end if;
  boundary_at := pg_catalog.now();
  insert into scoring_authority.authority_epochs (
    tournament_id, epoch_type, status, authority_before, authority_after,
    reconciliation_fingerprint, google_checkpoints, supabase_match_revisions,
    deployment_commit, actor_id, reason, request_fingerprint,
    source_fingerprint, prepared_activation_revision, prior_active_epoch_id,
    admission_closure_id, admission_generation_id,
    closed_admission_revision, closure_boundary_fingerprint,
    prior_source_fingerprint, external_fence_evidence_id,
    google_writer_provider_fence_id,
    google_writer_provider_verification_id, boundary_mode,
    supabase_shadow_fingerprint, commit_source_fingerprint,
    commit_source_verified_at, committed_at
  ) values (
    '2026', 'ROLLBACK', 'COMMITTED', 'SUPABASE', 'GOOGLE',
    closure.reconciliation_fingerprint, closure.google_checkpoints,
    closure.supabase_match_revisions, activation.expected_deployment_commit,
    pg_catalog.left(input->>'actor_id', 160),
    pg_catalog.left(coalesce(input->>'reason', ''), 500),
    pg_catalog.lower(input->>'request_fingerprint'),
    closure.final_source_fingerprint, activation.activation_revision,
    prior_epoch.epoch_id, closure.closure_id,
    gate.admission_generation_id, gate.admission_revision,
    closure.lease_set_fingerprint, prior_epoch.source_fingerprint,
    null, null, null, 'MAINTENANCE_WINDOW_V1',
    closure.supabase_shadow_fingerprint, closure.final_source_fingerprint,
    boundary_at, boundary_at
  ) returning * into epoch;
  update production_control.scoring_admission_closures
  set status = 'CONSUMED', consumed_at = boundary_at,
      consumed_epoch_id = epoch.epoch_id
  where closure_id = closure.closure_id;
  insert into production_control.scoring_admission_closures (
    boundary_mode, closure_kind, prior_legacy_closure_id,
    tournament_id, authority, authority_generation_id,
    admission_generation_id, deployment_id, status,
    opening_admission_revision, closing_admission_revision,
    closed_admission_revision, lease_high_watermark,
    start_source_fingerprint, first_source_fingerprint,
    first_source_captured_at, second_source_captured_at,
    final_source_fingerprint, supabase_shadow_fingerprint,
    unexplained_difference_count, reconciliation_fingerprint,
    lease_set_fingerprint, supabase_match_revisions, google_checkpoints,
    external_fence_evidence_id, google_writer_provider_fence_id,
    google_writer_provider_verification_id, close_request_fingerprint,
    close_payload_hash, closing_at, closed_at, actor_id
  ) values (
    'MAINTENANCE_WINDOW_V1', 'LEGACY_ADMISSION', null,
    '2026', 'GOOGLE', epoch.epoch_id, next_generation,
    gate.admission_deployment_id, 'CLOSED',
    gate.admission_revision, gate.admission_revision + 1,
    gate.admission_revision + 1, 0,
    closure.final_source_fingerprint, closure.final_source_fingerprint,
    boundary_at, boundary_at, closure.final_source_fingerprint,
    closure.final_source_fingerprint, 0,
    closure.reconciliation_fingerprint,
    production_control.scoring_admission_lease_set_fingerprint(
      next_generation
    ), closure.supabase_match_revisions, closure.google_checkpoints,
    null, null, null,
    pg_catalog.encode(extensions.digest(
      (pg_catalog.lower(input->>'request_fingerprint') || ':google-closed')::text,
      'sha256'
    ), 'hex'),
    production_control.cutover_payload_hash(input), boundary_at, boundary_at,
    pg_catalog.left(input->>'actor_id', 160)
  ) returning * into legacy_closure;
  update scoring_authority.tournaments
  set scoring_authority = 'GOOGLE', updated_at = boundary_at
  where tournament_id = '2026';
  update scoring_authority.ingress_gates
  set boundary_mode = 'MAINTENANCE_WINDOW_V1', state = 'PAUSED',
      authority = 'GOOGLE', active_epoch_id = epoch.epoch_id,
      admission_state = 'CLOSED',
      admission_revision = legacy_closure.closed_admission_revision,
      admission_generation_id = next_generation,
      active_closure_id = legacy_closure.closure_id,
      external_fence_evidence_id = null,
      google_writer_provider_fence_id = null,
      google_writer_provider_verification_id = null,
      unresolved_client_queues = 0,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = boundary_at
  where tournament_id = '2026' returning * into gate;
  update production_control.resource_scope
  set scoring_authority = 'GOOGLE', scoring_ingress_enabled = false,
      workers_enabled = false, google_writes_enabled = false,
      updated_at = boundary_at
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update production_control.cutover_activation_state
  set state = 'ROLLED_BACK', activation_revision = activation_revision + 1,
      current_authority = 'GOOGLE', scoring_ingress_enabled = false,
      authority_generation_id = epoch.epoch_id,
      active_transition_epoch_id = null,
      updated_by = pg_catalog.left(input->>'actor_id', 160),
      updated_at = boundary_at
  where scope_key = 'BAGGER_INV_PRODUCTION' returning * into activation;
  response_value := pg_catalog.jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_MAINTENANCE_AUTHORITY_ROLLED_BACK_PAUSED',
    'epoch_id', epoch.epoch_id,
    'closure_id', legacy_closure.closure_id,
    'authority', 'GOOGLE', 'ingress', 'PAUSED',
    'admission_state', 'CLOSED',
    'maintenance_state', 'SCORING_MAINTENANCE',
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'admission_generation_id', gate.admission_generation_id,
    'admission_revision', gate.admission_revision,
    'first_supabase_canonical_write_observed',
      activation.first_supabase_write_observed_at is not null,
    'reconciliation_required',
      activation.first_supabase_write_observed_at is not null,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt(
    'ROLLBACK_MAINTENANCE_AUTHORITY_EPOCH', input, response_value
  );
  return response_value;
end;
$_$;


ALTER FUNCTION public.rollback_production_maintenance_authority_epoch(input jsonb) OWNER TO postgres;

--
-- Name: rollback_production_participant_identity(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rollback_production_participant_identity(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'participant_identity', 'pg_temp'
    AS $$
declare resource production_control.resource_scope%rowtype;
declare activation production_control.cutover_activation_state%rowtype;
declare existing jsonb;
declare response_value jsonb;
declare expected_revision bigint;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  existing := production_control.lookup_cutover_receipt('ROLLBACK_PARTICIPANT_IDENTITY', input);
  if existing is not null then return existing; end if;
  if input->>'contract_version' is distinct from 'production-participant-identity-cutover-v1'
     or input->>'operation' is distinct from 'ROLLBACK_PARTICIPANT_IDENTITY'
     or coalesce(input->>'actor_id', '') = '' then
    raise exception using errcode = '42501', message = 'PRODUCTION_IDENTITY_ROLLBACK_SCOPE_REQUIRED';
  end if;
  expected_revision := coalesce((input->>'expected_activation_revision')::bigint, -1);
  select * into strict activation from production_control.cutover_activation_state
    where scope_key = 'BAGGER_INV_PRODUCTION' for update;
  existing := production_control.lookup_cutover_receipt('ROLLBACK_PARTICIPANT_IDENTITY', input);
  if existing is not null then return existing; end if;
  select * into strict resource from production_control.resource_scope
    where scope_key = 'BAGGER_INV_PRODUCTION' for update;
  if activation.activation_revision <> expected_revision
     or activation.state = 'DORMANT'
     or activation.expected_deployment_commit is distinct from input->>'deployment_commit' then
    raise exception using errcode = '42501', message = 'PRODUCTION_IDENTITY_ROLLBACK_STATE_MISMATCH';
  end if;
  if resource.participant_identity_authority = 'PASSPORT' and not resource.auth_user_creation_enabled then
    response_value := jsonb_build_object('ok', true, 'authority', 'PASSPORT',
      'authUserCreationEnabled', false,
      'activationRevision', activation.activation_revision, 'idempotent', true);
    perform production_control.store_cutover_receipt(
      'ROLLBACK_PARTICIPANT_IDENTITY', input, response_value);
    return response_value;
  end if;
  if resource.participant_identity_authority <> 'SUPABASE'
     or not resource.auth_user_creation_enabled then
    raise exception using errcode = '42501', message = 'PRODUCTION_IDENTITY_ROLLBACK_DRIFT';
  end if;
  update production_control.resource_scope set
    participant_identity_authority = 'PASSPORT', auth_user_creation_enabled = false,
    updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update production_control.cutover_activation_state set
    activation_revision = activation_revision + 1,
    updated_by = left(input->>'actor_id', 160), updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
  returning * into activation;
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_PARTICIPANT_IDENTITY_ROLLED_BACK', 'PARTICIPANT_IDENTITY', '2026',
    left(input->>'actor_id', 160), lower(input->>'request_fingerprint'), 'SUCCEEDED',
    jsonb_build_object('authority', 'PASSPORT', 'authUserCreationEnabled', false,
      'authUsersDeleted', 0, 'auditPreserved', true,
      'activationRevision', activation.activation_revision,
      'cutoverState', activation.state)
  );
  response_value := jsonb_build_object('ok', true, 'authority', 'PASSPORT',
    'authUserCreationEnabled', false,
    'activationRevision', activation.activation_revision, 'idempotent', false);
  perform production_control.store_cutover_receipt(
    'ROLLBACK_PARTICIPANT_IDENTITY', input, response_value);
  return response_value;
end;
$$;


ALTER FUNCTION public.rollback_production_participant_identity(input jsonb) OWNER TO postgres;

