--
-- Name: set_production_cutover_read_state(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_production_cutover_read_state(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  gate scoring_authority.ingress_gates%rowtype;
  epoch scoring_authority.authority_epochs%rowtype;
  odds_runtime production_control.odds_calculation_runtime%rowtype;
  target_phase text := pg_catalog.upper(coalesce(input->>'target_phase', ''));
  requested_mode text := pg_catalog.upper(coalesce(input->>'mode', ''));
  capability_bound boolean := false;
  capability_claimed boolean :=
    pg_catalog.btrim(coalesce(
      input->>'deployment_capability_contract', ''
    )) <> '' or pg_catalog.btrim(coalesce(
      input->>'deployment_capability_ceiling', ''
    )) <> '';
  capability_required boolean := false;
  prior_activation_revision bigint;
  response_value jsonb;
begin
  existing := production_control.lookup_cutover_receipt(
    'SET_READ_STATE', input
  );
  if existing is not null then
    return existing;
  end if;
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict gate
  from scoring_authority.ingress_gates value
  where value.tournament_id = '2026';
  capability_bound := exists (
    select 1
    from production_control.maintenance_deployment_capability_bindings value
    where value.epoch_id = gate.active_epoch_id
  );
  capability_required :=
    activation.boundary_mode = 'MAINTENANCE_WINDOW_V1'
    and requested_mode = 'ACTIVATE'
    and production_control.cutover_phase_rank(target_phase)
      >= production_control.cutover_phase_rank('SCORING_COMMIT');
  if capability_bound or capability_claimed or capability_required then
    if activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1' then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_MAINTENANCE_RUNTIME_CAPABILITY_REQUIRED';
    end if;
    perform production_control.assert_production_maintenance_runtime_capability(
      input, case when requested_mode = 'ACTIVATE'
        then target_phase else activation.read_cutover_phase end
    );
  end if;
  if capability_bound and requested_mode = 'ACTIVATE' then
    prior_activation_revision := activation.activation_revision;
    response_value :=
      public.set_production_cutover_read_state_pre_capability(input);
    select value.* into strict activation
    from production_control.cutover_activation_state value
    where value.scope_key = 'BAGGER_INV_PRODUCTION';
    select value.* into strict resource
    from production_control.resource_scope value
    where value.scope_key = 'BAGGER_INV_PRODUCTION';
    select value.* into strict gate
    from scoring_authority.ingress_gates value
    where value.tournament_id = '2026';
    if target_phase = 'SCORING_COMMIT' then
      select value.* into strict epoch
      from scoring_authority.authority_epochs value
      where value.epoch_id = gate.active_epoch_id;
      if activation.read_cutover_phase <> 'SCORING_COMMIT'
         or activation.state <> 'CUTOVER_PREPARED'
         or activation.current_authority <> 'GOOGLE'
         or activation.maintenance_state <> 'SCORING_MAINTENANCE'
         or activation.scoring_ingress_enabled
         or gate.state <> 'PAUSED'
         or epoch.status <> 'PREPARED'
      then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_SCORING_COMMIT_PHASE_PRECONDITION_REQUIRED';
      end if;
    elsif target_phase = 'WORKERS' then
      if activation.read_cutover_phase <> 'WORKERS'
         or activation.state <> 'SCORING_COMMITTED'
         or activation.current_authority <> 'SUPABASE'
         or activation.maintenance_state <> 'NORMAL'
         or not activation.scoring_ingress_enabled
         or resource.scoring_authority <> 'SUPABASE'
         or not resource.scoring_ingress_enabled
         or gate.authority <> 'SUPABASE'
         or gate.state <> 'OPEN'
      then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_WORKERS_PHASE_PRECONDITION_REQUIRED';
      end if;
    elsif target_phase = 'ODDS_WAR_ROOM' then
      if activation.read_cutover_phase <> 'ODDS_WAR_ROOM'
         or not resource.workers_enabled
         or not resource.google_writes_enabled
         or 2 <> (
           select pg_catalog.count(*)
           from production_control.worker_controls controls
           join production_control.worker_contracts contracts
             using (worker_name)
           where controls.worker_name in (
             'SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE'
           )
             and controls.enabled and controls.google_writes_allowed
             and contracts.operation_allowed
             and contracts.requires_google_write
             and not contracts.authoritative_write_allowed
             and controls.metadata->>'activation_epoch_id' =
               activation.authority_generation_id::text
             and controls.metadata->>'deployment_commit' =
               activation.expected_deployment_commit
         )
      then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_ODDS_WORKER_PRECONDITION_REQUIRED';
      end if;
    elsif target_phase = 'OBSERVATION' then
      select value.* into strict odds_runtime
      from production_control.odds_calculation_runtime value
      where value.scope_key = 'BAGGER_INV_PRODUCTION';
      if activation.read_cutover_phase <> 'OBSERVATION'
         or not odds_runtime.enabled
         or odds_runtime.operation_mode <> 'PRODUCTION_CUTOVER'
         or odds_runtime.cutover_phase <> 'ODDS_WAR_ROOM'
         or odds_runtime.deployment_commit is distinct from
           activation.expected_deployment_commit
         or odds_runtime.activation_revision is distinct from
           prior_activation_revision
      then
        raise exception using errcode = '55000',
          message = 'PRODUCTION_OBSERVATION_ODDS_RUNTIME_REQUIRED';
      end if;
    end if;
    return response_value;
  end if;
  return public.set_production_cutover_read_state_pre_capability(input);
end;
$$;


ALTER FUNCTION public.set_production_cutover_read_state(input jsonb) OWNER TO postgres;

--
-- Name: set_production_cutover_read_state_pre_capability(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_production_cutover_read_state_pre_capability(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  requested_mode text := upper(coalesce(input->>'mode', ''));
  prior_phase text := upper(coalesce(input->>'expected_prior_phase', ''));
  target_phase text := upper(coalesce(input->>'target_phase', ''));
  prior_rank integer;
  target_rank integer;
  public_reads boolean;
  current_reads boolean;
  scoring_before text;
  identity_before text;
  ingress_before boolean;
  google_writes_before boolean;
  workers_before boolean;
  odds_publication_before boolean;
  first_write_before timestamptz;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  existing := production_control.lookup_cutover_receipt('SET_READ_STATE', input);
  if existing is not null then return existing; end if;

  if coalesce(input->>'actor_id', '') = ''
     or requested_mode not in ('ACTIVATE', 'ROLLBACK')
     or coalesce(input->>'source_fingerprint', '') !~ '^[0-9a-f]{64}$'
     or production_control.cutover_phase_rank(prior_phase) < 0
     or production_control.cutover_phase_rank(target_phase) < 0 then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_READ_STATE_INPUT_INVALID';
  end if;

  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;

  prior_rank := production_control.cutover_phase_rank(activation.read_cutover_phase);
  target_rank := production_control.cutover_phase_rank(target_phase);
  if activation.activation_revision <> coalesce((input->>'expected_activation_revision')::bigint, -1)
     or activation.read_cutover_phase <> prior_phase
     or activation.expected_source_fingerprint is null
     or lower(input->>'source_fingerprint') <> activation.expected_source_fingerprint
     or (requested_mode = 'ACTIVATE' and target_rank <> prior_rank + 1)
     or (requested_mode = 'ROLLBACK' and target_rank >= prior_rank) then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_READ_STATE_PRECONDITION_FAILED';
  end if;

  scoring_before := resource.scoring_authority;
  identity_before := resource.participant_identity_authority;
  ingress_before := resource.scoring_ingress_enabled;
  google_writes_before := resource.google_writes_enabled;
  workers_before := resource.workers_enabled;
  odds_publication_before := resource.odds_publication_enabled;
  first_write_before := activation.first_supabase_write_observed_at;
  if requested_mode = 'ROLLBACK' and (
       (target_rank < production_control.cutover_phase_rank('IDENTITY')
         and identity_before = 'SUPABASE')
       or (target_rank < production_control.cutover_phase_rank('SCORING_COMMIT')
         and scoring_before = 'SUPABASE')
       or (target_rank < production_control.cutover_phase_rank('WORKERS')
         and (workers_before or google_writes_before))
     ) then
    raise exception using errcode = 'P0001',
      message = 'PRODUCTION_READ_ROLLBACK_REQUIRES_DEPENDENT_AUTHORITY_ROLLBACK';
  end if;
  public_reads := target_rank >= production_control.cutover_phase_rank('READ_CUTOVER');
  current_reads := target_rank >= production_control.cutover_phase_rank('CURRENT_READS');

  update production_control.resource_scope
  set public_supabase_reads_enabled = public_reads,
      current_tournament_read_authority = case when current_reads then 'SUPABASE' else 'GOOGLE' end
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update production_control.cutover_activation_state
  set read_cutover_phase = target_phase,
      read_source_fingerprint = lower(input->>'source_fingerprint'),
      public_reads_activated_at = case
        when public_reads and public_reads_activated_at is null then now()
        when not public_reads then null else public_reads_activated_at end,
      activation_revision = activation_revision + 1,
      updated_by = left(input->>'actor_id', 160), updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
  returning * into activation;
  select * into strict resource from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION';

  if resource.scoring_authority <> scoring_before
     or resource.participant_identity_authority <> identity_before
     or resource.scoring_ingress_enabled <> ingress_before
     or resource.google_writes_enabled <> google_writes_before
     or resource.workers_enabled <> workers_before
     or resource.odds_publication_enabled <> odds_publication_before
     or activation.first_supabase_write_observed_at is distinct from first_write_before then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_READ_STATE_AUTHORITY_SIDE_EFFECT';
  end if;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    case when requested_mode = 'ACTIVATE'
      then 'PRODUCTION_SUPABASE_READ_PHASE_ACTIVATED'
      else 'PRODUCTION_SUPABASE_READ_PHASE_ROLLED_BACK' end,
    'APPLICATION_READS', '2026', left(input->>'actor_id', 160),
    lower(input->>'request_fingerprint'), 'SUCCEEDED',
    jsonb_build_object(
      'prior_phase', prior_phase, 'target_phase', target_phase,
      'public_supabase_reads_enabled', resource.public_supabase_reads_enabled,
      'current_tournament_read_authority', resource.current_tournament_read_authority,
      'scoring_authority_unchanged', resource.scoring_authority,
      'participant_identity_authority_unchanged', resource.participant_identity_authority,
      'scoring_ingress_unchanged', resource.scoring_ingress_enabled,
      'google_writes_unchanged', resource.google_writes_enabled,
      'workers_unchanged', resource.workers_enabled,
      'odds_publication_unchanged', resource.odds_publication_enabled,
      'first_supabase_canonical_write_observed',
        activation.first_supabase_write_observed_at is not null,
      'source_fingerprint', activation.read_source_fingerprint
    )
  );

  response_value := jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_READ_STATE_UPDATED',
    'mode', requested_mode, 'prior_phase', prior_phase,
    'phase', target_phase, 'activation_revision', activation.activation_revision,
    'public_supabase_reads_enabled', resource.public_supabase_reads_enabled,
    'current_tournament_read_authority', resource.current_tournament_read_authority,
    'scoring_authority', resource.scoring_authority,
    'participant_identity_authority', resource.participant_identity_authority,
    'scoring_ingress_enabled', resource.scoring_ingress_enabled,
    'first_supabase_canonical_write_observed',
      activation.first_supabase_write_observed_at is not null,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt('SET_READ_STATE', input, response_value);
  return response_value;
end;
$_$;


ALTER FUNCTION public.set_production_cutover_read_state_pre_capability(input jsonb) OWNER TO postgres;

--
-- Name: set_production_cutover_worker_state(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_production_cutover_worker_state(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  activation production_control.cutover_activation_state%rowtype;
  requested_enabled boolean := coalesce((input->>'enabled')::boolean, false);
  capability_claimed boolean :=
    pg_catalog.btrim(coalesce(
      input->>'deployment_capability_contract', ''
    )) <> '' or pg_catalog.btrim(coalesce(
      input->>'deployment_capability_ceiling', ''
    )) <> '';
begin
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if capability_claimed
     and activation.boundary_mode <> 'MAINTENANCE_WINDOW_V1'
  then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_MAINTENANCE_RUNTIME_CAPABILITY_REQUIRED';
  end if;
  if activation.boundary_mode = 'MAINTENANCE_WINDOW_V1'
     and requested_enabled
  then
    if production_control.cutover_phase_rank(activation.read_cutover_phase)
         < production_control.cutover_phase_rank('WORKERS')
    then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_CUTOVER_WORKERS_PHASE_REQUIRED';
    end if;
    perform production_control.assert_production_maintenance_runtime_capability(
      input, 'WORKERS'
    );
  end if;
  return public.set_production_cutover_worker_state_pre_capability(input);
end;
$$;


ALTER FUNCTION public.set_production_cutover_worker_state(input jsonb) OWNER TO postgres;

--
-- Name: set_production_cutover_worker_state_pre_capability(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_production_cutover_worker_state_pre_capability(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  worker text := upper(coalesce(input->>'worker_name', ''));
  requested_enabled boolean;
  active_workers integer;
  active_google_writers integer;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, true);
  existing := production_control.lookup_cutover_receipt('SET_WORKER_STATE', input);
  if existing is not null then return existing; end if;

  if coalesce(input->>'actor_id', '') = ''
     or worker not in ('SCORING_GOOGLE_OUTBOX', 'ROUND_SCORECARDS_ARCHIVE')
     or input->>'enabled' is null then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_CUTOVER_WORKER_NOT_ALLOWED';
  end if;
  requested_enabled := (input->>'enabled')::boolean;

  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  if activation.activation_revision <> coalesce((input->>'expected_activation_revision')::bigint, -1)
     or activation.authority_generation_id <> nullif(input->>'expected_epoch_id', '')::uuid
     or activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or not activation.scoring_ingress_enabled then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_CUTOVER_WORKER_AUTHORITY_REQUIRED';
  end if;
  if requested_enabled and input->>'google_service_account_email'
       is distinct from activation.expected_google_service_account then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_DEDICATED_GOOGLE_SERVICE_ACCOUNT_REQUIRED';
  end if;

  update production_control.worker_controls
  set enabled = requested_enabled,
      google_writes_allowed = requested_enabled,
      scheduler_installed = false,
      last_verified_at = now(),
      metadata = metadata || jsonb_build_object(
        'activation_epoch_id', activation.authority_generation_id,
        'deployment_commit', activation.expected_deployment_commit,
        'google_service_account', case when requested_enabled
          then activation.expected_google_service_account else null end,
        'configured_by', left(input->>'actor_id', 160),
        'configured_at', now()
      )
  where worker_name = worker;
  if not found then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_CUTOVER_WORKER_CONTRACT_MISSING';
  end if;
  update production_control.worker_contracts
  set operation_allowed = requested_enabled,
      scheduler_installed = false,
      authoritative_write_allowed = false
  where worker_name = worker;

  if worker = 'ROUND_SCORECARDS_ARCHIVE' then
    -- Finalize/Reopen own the only archive-transition path through their
    -- explicit, atomic snapshot helpers. Worker activation must never enable
    -- the legacy table trigger or one lifecycle mutation could enqueue the
    -- same transition twice.
    execute 'alter table scoring_authority.matches disable trigger capture_scorecard_archive_transition';
  end if;

  select count(*)::integer into active_workers
  from production_control.worker_controls
  where enabled;
  select count(*)::integer into active_google_writers
  from production_control.worker_controls
  where enabled and google_writes_allowed;
  update production_control.resource_scope
  set workers_enabled = active_workers > 0,
      google_writes_enabled = active_google_writers > 0
  where scope_key = 'BAGGER_INV_PRODUCTION';
  update production_control.cutover_activation_state
  set activation_revision = activation_revision + 1,
      updated_by = left(input->>'actor_id', 160), updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
  returning * into activation;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    case when requested_enabled then 'PRODUCTION_CUTOVER_WORKER_ENABLED'
      else 'PRODUCTION_CUTOVER_WORKER_DISABLED' end,
    'SCORING_AUTHORITY', '2026', left(input->>'actor_id', 160),
    lower(input->>'request_fingerprint'), 'SUCCEEDED',
    jsonb_build_object(
      'worker', worker, 'enabled', requested_enabled,
      'google_writes_allowed', requested_enabled,
      'authoritative_write_allowed', false,
      'scheduler_installed', false,
      'epoch_id', activation.authority_generation_id
    )
  );

  response_value := jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_CUTOVER_WORKER_STATE_UPDATED',
    'worker', worker, 'enabled', requested_enabled,
    'authoritative_write_allowed', false,
    'workers_enabled', active_workers > 0,
    'google_writes_enabled', active_google_writers > 0,
    'activation_revision', activation.activation_revision,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt('SET_WORKER_STATE', input, response_value);
  return response_value;
end;
$$;


ALTER FUNCTION public.set_production_cutover_worker_state_pre_capability(input jsonb) OWNER TO postgres;

--
-- Name: set_production_player_ghin_identity_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_production_player_ghin_identity_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text; actor_player text; actor_auth uuid; request_id uuid; declared_hash text;
  database_hash text; player_value text; external_value text; expected_value uuid;
  current_value production_control.player_external_identities_v1%rowtype;
  prior production_control.handicap_source_operation_receipts_v1%rowtype;
  identity_value uuid; response_value jsonb; event_value uuid := extensions.gen_random_uuid();
begin
  target := production_control.assert_handicap_source_runtime_v1(input);
  actor_player := pg_catalog.upper(pg_catalog.btrim(input#>>'{authorization,player_id}'));
  actor_auth := (input#>>'{authorization,auth_user_id}')::uuid;
  declared_hash := pg_catalog.lower(pg_catalog.btrim(coalesce(input->>'request_payload_hash', '')));
  if input->>'operation' is distinct from 'SET_PRODUCTION_PLAYER_GHIN_IDENTITY_V1'
     or coalesce(input->>'operation_request_id','') !~ '^[0-9a-fA-F-]{36}$'
     or coalesce(input->>'player_id','') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$'
     or coalesce(input->>'external_identifier','') !~ '^[0-9]{5,12}$'
     or declared_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'PRODUCTION_GHIN_IDENTITY_INPUT_INVALID';
  end if;
  request_id := (input->>'operation_request_id')::uuid;
  player_value := pg_catalog.upper(input->>'player_id'); external_value := input->>'external_identifier';
  expected_value := nullif(input->>'expected_identity_id','')::uuid;
  database_hash := production_control.handicap_source_hash_v1(pg_catalog.jsonb_build_object(
    'operation','SET_IDENTITY','playerId',player_value,'externalIdentifier',external_value,
    'expectedIdentityId',expected_value,'replaceConfirmed',coalesce((input->>'replace_confirmed')::boolean,false),
    'actorPlayerId',actor_player,'actorAuthUserId',actor_auth
  ));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('production-ghin-identity:' || player_value, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('production-ghin-external:GHIN:' || external_value, 0));
  select value.* into prior from production_control.handicap_source_operation_receipts_v1 value where value.tournament_id=target and value.operation_request_id=request_id;
  if found then
    if prior.declared_request_payload_hash=declared_hash and prior.database_request_payload_hash=database_hash then return prior.response || pg_catalog.jsonb_build_object('idempotent',true); end if;
    raise exception using errcode='23505', message='PRODUCTION_HANDICAP_SOURCE_IDEMPOTENCY_CONFLICT';
  end if;
  if not exists(select 1 from scoring_authority.tournament_players roster where roster.tournament_id=target and roster.player_id=player_value and roster.participation_status='ACTIVE') then
    raise exception using errcode='22023', message='PRODUCTION_HANDICAP_SOURCE_PLAYER_NOT_ACTIVE';
  end if;
  if exists(select 1 from production_control.player_external_identities_v1 value where value.provider='GHIN' and value.external_identifier=external_value and value.status='VERIFIED' and value.player_id<>player_value) then
    raise exception using errcode='23505', message='PRODUCTION_GHIN_IDENTITY_ALREADY_ASSIGNED';
  end if;
  select value.* into current_value from production_control.player_external_identities_v1 value where value.player_id=player_value and value.provider='GHIN' and value.status='VERIFIED' for update;
  if current_value.identity_id is distinct from expected_value then raise exception using errcode='40001', message='PRODUCTION_GHIN_IDENTITY_STALE'; end if;
  if current_value.identity_id is not null then
    if coalesce((input->>'replace_confirmed')::boolean,false) is not true then raise exception using errcode='22023', message='PRODUCTION_GHIN_IDENTITY_REPLACEMENT_CONFIRMATION_REQUIRED'; end if;
    update production_control.player_external_identities_v1 set status='RETIRED',retired_at=pg_catalog.clock_timestamp(),retired_by_player_id=actor_player,retired_by_auth_user_id=actor_auth where identity_id=current_value.identity_id;
    delete from production_control.handicap_source_current_v1 where tournament_id=target and player_id=player_value and provider='GHIN';
  end if;
  insert into production_control.player_external_identities_v1(player_id,provider,external_identifier,status,verified_at,verified_by_player_id,verified_by_auth_user_id,verification_source)
  values(player_value,'GHIN',external_value,'VERIFIED',pg_catalog.clock_timestamp(),actor_player,actor_auth,'DIRECTOR_CONFIRMED') returning identity_id into identity_value;
  response_value := pg_catalog.jsonb_build_object('ok',true,'code','PRODUCTION_GHIN_IDENTITY_VERIFIED','idempotent',false,'playerId',player_value,'identityId',identity_value,'maskedGhinNumber','••••'||pg_catalog.right(external_value,4),'sourceEvidenceCleared',current_value.identity_id is not null,'eventId',event_value);
  insert into production_control.handicap_source_audit_events_v1(event_id,tournament_id,action,player_id,identity_id,actor_player_id,actor_auth_user_id,operation_request_id,before_state,after_state)
  values(event_value,target,'GHIN_IDENTITY_VERIFIED',player_value,identity_value,actor_player,actor_auth,request_id,
    case when current_value.identity_id is null then '{}'::jsonb else pg_catalog.jsonb_build_object('identityId',current_value.identity_id,'status','VERIFIED') end,
    pg_catalog.jsonb_build_object('identityId',identity_value,'status','VERIFIED'));
  perform production_control.handicap_source_receipt_v1(target,'SET_IDENTITY',request_id,declared_hash,database_hash,actor_player,actor_auth,response_value);
  return response_value;
end;
$_$;


ALTER FUNCTION public.set_production_player_ghin_identity_v1(input jsonb) OWNER TO postgres;

--
-- Name: stage_production_cutover_release(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_production_cutover_release(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if input->>'boundary_mode' = 'MAINTENANCE_WINDOW_V1' then
    return production_control.stage_production_maintenance_release(input);
  end if;
  return public.stage_production_cutover_release_provider_fence_v2(input);
end;
$$;


ALTER FUNCTION public.stage_production_cutover_release(input jsonb) OWNER TO postgres;

--
-- Name: stage_production_cutover_release_pre_step11_6_provenance(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_production_cutover_release_pre_step11_6_provenance(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  if nullif(input->>'provider_fence_id', '') is not null
     or nullif(input->>'provider_fence_verification_id', '') is not null
     or nullif(input->>'quiesce_evidence_id', '') is not null
     or exists (
       select 1
       from production_control.cutover_activation_state value
       where value.scope_key = 'BAGGER_INV_PRODUCTION'
         and (
           value.active_google_writer_provider_fence_id is not null
           or value.active_google_writer_provider_verification_id is not null
           or value.active_vercel_quiesce_evidence_id is not null
         )
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_STAGE_REQUIRES_NO_ACTIVE_PROVIDER_FENCE';
  end if;
  perform production_control.assert_no_unrestored_google_writer_fence_rehearsal();
  perform production_control.assert_certified_google_writer_fence_rehearsal(
    pg_catalog.lower(coalesce(input->>'deployment_commit', ''))
  );
  return public.stage_production_cutover_release_pre_step11_6_rehearsal(input);
end;
$$;


ALTER FUNCTION public.stage_production_cutover_release_pre_step11_6_provenance(input jsonb) OWNER TO postgres;

--
-- Name: stage_production_cutover_release_pre_step11_6_rehearsal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_production_cutover_release_pre_step11_6_rehearsal(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  existing jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  expected_revision bigint;
  response_value jsonb;
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  existing := production_control.lookup_cutover_receipt('STAGE_RELEASE', input);
  if existing is not null then return existing; end if;

  if coalesce(input->>'actor_id', '') = ''
     or input->>'contract_version' is distinct from 'production-cutover-activation-v1'
     or input->>'vercel_project' is distinct from 'bagger-inv'
     or input->>'canonical_domain' is distinct from 'https://baggerinv.com'
     or coalesce((input->>'tournament_year')::integer, 0) <> 2026
     or input->>'vercel_project_id'
        is distinct from 'prj_FxJYIEzMe74rp0yKqRFAQzSKf3lU'
     or coalesce(input->>'deployment_commit', '') !~ '^[0-9a-f]{40}$'
     or coalesce(input->>'source_fingerprint', '') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_RELEASE_CONFIGURATION_INVALID';
  end if;

  expected_revision := coalesce((input->>'expected_activation_revision')::bigint, -1);
  select * into strict activation
  from production_control.cutover_activation_state
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  select * into strict resource
  from production_control.resource_scope
  where scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  if activation.activation_revision <> expected_revision then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_ACTIVATION_REVISION_CONFLICT';
  end if;
  if activation.state not in ('DORMANT', 'STAGED', 'ROLLED_BACK')
     or activation.current_authority <> 'GOOGLE'
     or activation.scoring_ingress_enabled
     or resource.scoring_authority <> 'GOOGLE'
     or resource.scoring_ingress_enabled
     or resource.google_writes_enabled
     or exists (
       select 1 from production_control.worker_controls
       where enabled or google_writes_allowed
     ) then
    raise exception using errcode = 'P0001', message = 'PRODUCTION_RELEASE_CANNOT_BE_RESTAGED';
  end if;

  update production_control.cutover_activation_state
  set state = 'STAGED', activation_revision = activation_revision + 1,
      expected_deployment_commit = lower(input->>'deployment_commit'),
      expected_vercel_project_id = input->>'vercel_project_id',
      expected_source_fingerprint = lower(input->>'source_fingerprint'),
      staged_by = left(input->>'actor_id', 160), staged_at = now(),
      updated_by = left(input->>'actor_id', 160), updated_at = now()
  where scope_key = 'BAGGER_INV_PRODUCTION'
  returning * into activation;

  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint, result, details
  ) values (
    'PRODUCTION_CUTOVER_RELEASE_STAGED', 'SCORING_AUTHORITY', '2026',
    left(input->>'actor_id', 160), lower(input->>'request_fingerprint'), 'SUCCEEDED',
    jsonb_build_object(
      'activation_revision', activation.activation_revision,
      'deployment_commit', activation.expected_deployment_commit,
      'source_fingerprint', activation.expected_source_fingerprint,
      'authority_changed', false,
      'scoring_ingress_enabled', false,
      'workers_enabled', false
    )
  );

  response_value := jsonb_build_object(
    'ok', true, 'code', 'PRODUCTION_RELEASE_STAGED',
    'state', activation.state,
    'activation_revision', activation.activation_revision,
    'authority_generation_id', activation.authority_generation_id,
    'authority', activation.current_authority,
    'scoring_ingress_enabled', activation.scoring_ingress_enabled,
    'idempotent', false
  );
  perform production_control.store_cutover_receipt('STAGE_RELEASE', input, response_value);
  return response_value;
end;
$_$;


ALTER FUNCTION public.stage_production_cutover_release_pre_step11_6_rehearsal(input jsonb) OWNER TO postgres;

--
-- Name: stage_production_cutover_release_provider_fence_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_production_cutover_release_provider_fence_v2(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  response_value jsonb;
  affected_rows integer;
  activation production_control.cutover_activation_state%rowtype;
  stage_request_fingerprint text := pg_catalog.lower(
    coalesce(input->>'request_fingerprint', '')
  );
  stage_payload_hash text;
  certification_fingerprint text := pg_catalog.lower(
    coalesce(input->>'certification_fingerprint', '')
  );
  environment_delta_fingerprint_v2 text := pg_catalog.lower(
    coalesce(input->>'environment_delta_fingerprint_v2', '')
  );
begin
  if stage_request_fingerprint !~ '^[0-9a-f]{64}$'
     or certification_fingerprint !~ '^[0-9a-f]{64}$'
     or environment_delta_fingerprint_v2 !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_STAGE_PROVENANCE_INVALID';
  end if;
  stage_payload_hash := production_control.cutover_payload_hash(input);

  -- Serialize provenance selection before the predecessor can restage. A
  -- second, differently certified STAGE_RELEASE must not overwrite the first
  -- authoritative binding. Exact replay remains valid for lost responses.
  -- ROLLED_BACK is the one deliberate replacement boundary: its retained
  -- provenance remains available for cleanup/audit, while the predecessor's
  -- explicit restage transition may bind a newly recertified release.
  select * into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION'
  for update;
  if activation.staged_request_fingerprint is not null
     or activation.staged_payload_hash is not null
     or activation.staged_certification_fingerprint is not null
     or activation.staged_environment_delta_fingerprint_v2 is not null then
    if activation.state <> 'ROLLED_BACK' and (
       activation.staged_request_fingerprint
         is distinct from stage_request_fingerprint
       or activation.staged_payload_hash is distinct from stage_payload_hash
       or activation.staged_certification_fingerprint
         is distinct from certification_fingerprint
       or activation.staged_environment_delta_fingerprint_v2
         is distinct from environment_delta_fingerprint_v2) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_STAGE_PROVENANCE_IMMUTABLE';
    end if;
  end if;

  -- The predecessor performs the complete resource, rehearsal, state,
  -- idempotency, revision and authority checks and stores the durable receipt.
  -- This wrapper remains in the same transaction, so a lost response cannot
  -- commit the stage without also committing these exact provenance claims.
  response_value :=
    public.stage_production_cutover_release_pre_step11_6_provenance(input);

  if coalesce((response_value->>'idempotent')::boolean, false) then
    if activation.staged_request_fingerprint
         is distinct from stage_request_fingerprint
       or activation.staged_payload_hash is distinct from stage_payload_hash
       or activation.staged_certification_fingerprint
         is distinct from certification_fingerprint
       or activation.staged_environment_delta_fingerprint_v2
         is distinct from environment_delta_fingerprint_v2 then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_STAGE_PROVENANCE_REPLAY_MISMATCH';
    end if;
    return response_value || pg_catalog.jsonb_build_object(
      'stage_request_fingerprint', stage_request_fingerprint,
      'stage_payload_hash', stage_payload_hash,
      'certification_fingerprint', certification_fingerprint,
      'environment_delta_fingerprint_v2',
        environment_delta_fingerprint_v2
    );
  end if;

  update production_control.cutover_activation_state
  set staged_request_fingerprint = stage_request_fingerprint,
      staged_payload_hash = stage_payload_hash,
      staged_certification_fingerprint = certification_fingerprint,
      staged_environment_delta_fingerprint_v2 =
        environment_delta_fingerprint_v2
  where scope_key = 'BAGGER_INV_PRODUCTION'
    and state = 'STAGED'
    and expected_deployment_commit = pg_catalog.lower(
      input->>'deployment_commit'
    );
  get diagnostics affected_rows = row_count;
  if affected_rows <> 1 then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_STAGE_PROVENANCE_BINDING_FAILED';
  end if;

  return response_value || pg_catalog.jsonb_build_object(
    'stage_request_fingerprint', stage_request_fingerprint,
    'stage_payload_hash', stage_payload_hash,
    'certification_fingerprint', certification_fingerprint,
    'environment_delta_fingerprint_v2', environment_delta_fingerprint_v2
  );
end;
$_$;


ALTER FUNCTION public.stage_production_cutover_release_provider_fence_v2(input jsonb) OWNER TO postgres;

