--
-- Name: stage_production_handicap_revision_from_hybrid_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_production_handicap_revision_from_hybrid_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  target text; actor_player text; actor_auth uuid; request_id uuid; declared_hash text; database_hash text;
  expected_revision bigint; expected_source text; effective_date_value date; current_source text; roster_count integer; source_count integer;
  canonical_entries jsonb; inner_input jsonb; inner_hash text; result_value jsonb; response_value jsonb;
  prior production_control.handicap_source_operation_receipts_v1%rowtype; event_value uuid:=extensions.gen_random_uuid();
begin
  target:=production_control.assert_handicap_source_runtime_v1(input); actor_player:=pg_catalog.upper(pg_catalog.btrim(input#>>'{authorization,player_id}')); actor_auth:=(input#>>'{authorization,auth_user_id}')::uuid; declared_hash:=pg_catalog.lower(pg_catalog.btrim(coalesce(input->>'request_payload_hash','')));
  if input->>'operation' is distinct from 'STAGE_PRODUCTION_HANDICAP_REVISION_FROM_HYBRID_V1' or coalesce(input->>'operation_request_id','') !~ '^[0-9a-fA-F-]{36}$' or coalesce(input->>'expected_predecessor_revision','') !~ '^[0-9]+$' or coalesce(input->>'expected_source_fingerprint','') !~ '^[0-9a-f]{64}$' or coalesce(input->>'effective_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or pg_catalog.jsonb_typeof(input->'entries') is distinct from 'array' or declared_hash !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='PRODUCTION_HANDICAP_SOURCE_DRAFT_INPUT_INVALID'; end if;
  request_id:=(input->>'operation_request_id')::uuid; expected_revision:=(input->>'expected_predecessor_revision')::bigint; expected_source:=input->>'expected_source_fingerprint'; effective_date_value:=(input->>'effective_date')::date;
  database_hash:=production_control.handicap_source_hash_v1(pg_catalog.jsonb_build_object('operation','STAGE_HYBRID_DRAFT','expectedRevision',expected_revision,'expectedSourceFingerprint',expected_source,'effectiveDate',effective_date_value,'entries',input->'entries','actorPlayerId',actor_player,'actorAuthUserId',actor_auth));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('production-handicap-source-stage:'||target,0));
  select value.* into prior from production_control.handicap_source_operation_receipts_v1 value where value.tournament_id=target and value.operation_request_id=request_id;
  if found then if prior.declared_request_payload_hash=declared_hash and prior.database_request_payload_hash=database_hash then return prior.response||pg_catalog.jsonb_build_object('idempotent',true); end if; raise exception using errcode='23505',message='PRODUCTION_HANDICAP_SOURCE_IDEMPOTENCY_CONFLICT'; end if;
  current_source:=production_control.handicap_source_set_fingerprint_v1(target);
  if current_source is distinct from expected_source then raise exception using errcode='40001',message='PRODUCTION_HANDICAP_SOURCE_FINGERPRINT_STALE'; end if;
  select pg_catalog.count(*)::integer into roster_count from scoring_authority.tournament_players value where value.tournament_id=target and value.participation_status='ACTIVE';
  select pg_catalog.count(*)::integer into source_count from scoring_authority.tournament_players roster join production_control.player_external_identities_v1 identity_value on identity_value.player_id=roster.player_id and identity_value.provider='GHIN' and identity_value.status='VERIFIED' join production_control.handicap_source_current_v1 source_pointer on source_pointer.tournament_id=target and source_pointer.player_id=roster.player_id and source_pointer.provider='GHIN' and source_pointer.source_status='CURRENT' join production_control.handicap_source_observations_v1 observation on observation.observation_id=source_pointer.observation_id and observation.identity_id=identity_value.identity_id where roster.tournament_id=target and roster.participation_status='ACTIVE';
  if roster_count=0 or source_count<>roster_count or pg_catalog.jsonb_array_length(input->'entries')<>roster_count then raise exception using errcode='22023',message='PRODUCTION_HANDICAP_SOURCE_INCOMPLETE_ROSTER'; end if;
  if exists(select 1 from scoring_authority.tournament_players roster left join pg_catalog.jsonb_array_elements(input->'entries') proposed on proposed->>'player_id'=roster.player_id where roster.tournament_id=target and roster.participation_status='ACTIVE' and (proposed is null or coalesce(proposed->>'tournament_handicap','') !~ '^-?[0-9]+(\.[0-9]+)?$')) then raise exception using errcode='22023',message='PRODUCTION_HANDICAP_SOURCE_INCOMPLETE_ROSTER'; end if;
  select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'player_id',roster.player_id,
    'tournament_handicap',(proposed->>'tournament_handicap')::numeric,
    'source_index',observation.current_index,
    'low_index',observation.low_index,
    'source_metadata',pg_catalog.jsonb_build_object(
      'source','HYBRID_HANDICAP','provider','GHIN','provenance',observation.provenance,
      'identity_id',identity_value.identity_id,'observation_id',observation.observation_id,
      'source_evidence_fingerprint',observation.source_evidence_fingerprint,
      'hybrid_handicap',observation.hybrid_handicap,
      'manual_tournament_handicap_override',(proposed->>'tournament_handicap')::numeric is distinct from observation.hybrid_handicap
    )
  ) order by roster.player_id) into canonical_entries
  from scoring_authority.tournament_players roster
  join pg_catalog.jsonb_array_elements(input->'entries') proposed on proposed->>'player_id'=roster.player_id
  join production_control.player_external_identities_v1 identity_value on identity_value.player_id=roster.player_id and identity_value.provider='GHIN' and identity_value.status='VERIFIED'
  join production_control.handicap_source_current_v1 source_pointer on source_pointer.tournament_id=target and source_pointer.player_id=roster.player_id and source_pointer.provider='GHIN' and source_pointer.source_status='CURRENT'
  join production_control.handicap_source_observations_v1 observation on observation.observation_id=source_pointer.observation_id and observation.identity_id=identity_value.identity_id
  where roster.tournament_id=target and roster.participation_status='ACTIVE';
  inner_input := input || pg_catalog.jsonb_build_object(
    'contract_version','production-handicap-revision-v1','operation','STAGE_PRODUCTION_HANDICAP_REVISION_V1',
    'expected_predecessor_revision',expected_revision,'effective_date',effective_date_value,
    'method','DIRECTOR_HYBRID_HANDICAP_REVIEW','source_metadata',pg_catalog.jsonb_build_object(
      'entry_mode','PRODUCTION_DIRECTOR_HYBRID','hybrid_formula','round((current_hi + low_hi) / 2, 1)',
      'source_set_fingerprint',current_source,'approval_required',true
    ),'source_evidence_date',null,'entries',canonical_entries
  );
  inner_hash:=production_control.handicap_v1_hash(pg_catalog.jsonb_build_object(
    'operation','STAGE','operation_request_id',request_id,'actor_player_id',actor_player,'actor_auth_user_id',actor_auth,
    'expected_predecessor_revision',expected_revision,'effective_date',effective_date_value,
    'method','DIRECTOR_HYBRID_HANDICAP_REVIEW','source_metadata',inner_input->'source_metadata',
    'source_evidence_date',null,'entries',canonical_entries
  ));
  inner_input:=inner_input||pg_catalog.jsonb_build_object('request_payload_hash',inner_hash);
  result_value:=public.stage_production_handicap_revision_v1(inner_input);
  if result_value->>'ok' is distinct from 'true' then return result_value; end if;
  response_value:=result_value||pg_catalog.jsonb_build_object('code','PRODUCTION_HYBRID_HANDICAP_DRAFT_STAGED','idempotent',false,'sourceFingerprint',current_source,'autoApproved',false,'eventId',event_value);
  insert into production_control.handicap_source_audit_events_v1(event_id,tournament_id,action,handicap_revision_id,actor_player_id,actor_auth_user_id,operation_request_id,before_state,after_state)
  values(event_value,target,'HYBRID_DRAFT_STAGED',(result_value->>'revision_id')::uuid,actor_player,actor_auth,request_id,pg_catalog.jsonb_build_object('approvedRevision',expected_revision,'sourceFingerprint',current_source),pg_catalog.jsonb_build_object('draftRevisionId',result_value->>'revision_id','draftRevision',result_value->>'revision_number','status','DRAFT'));
  perform production_control.handicap_source_receipt_v1(target,'STAGE_HYBRID_DRAFT',request_id,declared_hash,database_hash,actor_player,actor_auth,response_value); return response_value;
end;
$_$;


ALTER FUNCTION public.stage_production_handicap_revision_from_hybrid_v1(input jsonb) OWNER TO postgres;

--
-- Name: stage_production_handicap_revision_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_production_handicap_revision_v1(input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $_$
declare
  actor_player text := pg_catalog.btrim(coalesce(
    input#>>'{authorization,player_id}', ''
  ));
  actor_auth_user uuid := nullif(
    input#>>'{authorization,auth_user_id}', ''
  )::uuid;
  operation_request uuid;
  declared_hash text := pg_catalog.lower(coalesce(
    input->>'request_payload_hash', ''
  ));
  expected_predecessor bigint;
  current_revision bigint := 0;
  predecessor_id uuid;
  effective_date_value date;
  source_evidence_date_value date;
  method_value text := pg_catalog.btrim(coalesce(
    input->>'method', ''
  ));
  source_metadata_value jsonb := coalesce(
    input->'source_metadata', '{}'::jsonb
  );
  active_count integer;
  next_revision bigint;
  revision_id_value uuid;
  roster_hash text;
  canonical_entries jsonb;
  canonical_payload jsonb;
  canonical_hash text;
  database_request_hash text;
  receipt scoring_authority.handicap_operation_receipts%rowtype;
  validation_value jsonb;
  response_value jsonb;
  audit_event_id_value uuid;
  receipt_id_value uuid := extensions.gen_random_uuid();
begin
  perform production_control.assert_exact_cutover_resource_scope(input, false);
  perform production_control.assert_production_scoring_actor(input, true);
  perform production_control.assert_production_handicap_runtime();

  if input->>'operation' is distinct from
       'STAGE_PRODUCTION_HANDICAP_REVISION_V1'
     or input->>'contract_version' is distinct from
       'production-handicap-revision-v1'
     or pg_catalog.jsonb_typeof(input->'operation_request_id')
       is distinct from 'string'
     or coalesce(input->>'operation_request_id', '')
       !~ '^[0-9a-fA-F-]{36}$'
     or declared_hash !~ '^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(input->'expected_predecessor_revision')
       is distinct from 'number'
     or input->>'expected_predecessor_revision' !~ '^[0-9]+$'
     or pg_catalog.jsonb_typeof(input->'effective_date')
       is distinct from 'string'
     or input->>'effective_date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or method_value = ''
     or pg_catalog.length(method_value) > 160
     or pg_catalog.jsonb_typeof(source_metadata_value) <> 'object'
     or (
       input ? 'source_evidence_date'
       and input->'source_evidence_date' <> 'null'::jsonb
       and (
         pg_catalog.jsonb_typeof(input->'source_evidence_date') <> 'string'
         or input->>'source_evidence_date'
           !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       )
     )
     or pg_catalog.jsonb_typeof(input->'entries') is distinct from 'array'
     or pg_catalog.jsonb_array_length(input->'entries') = 0 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_REVISION_INPUT_INVALID'
    );
  end if;

  begin
    operation_request := (input->>'operation_request_id')::uuid;
    expected_predecessor :=
      (input->>'expected_predecessor_revision')::bigint;
    effective_date_value := (input->>'effective_date')::date;
    source_evidence_date_value := case
      when input->'source_evidence_date' is null
        or input->'source_evidence_date' = 'null'::jsonb then null
      else (input->>'source_evidence_date')::date
    end;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_REVISION_INPUT_INVALID'
    );
  end;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(input->'entries') item(value)
    where pg_catalog.jsonb_typeof(item.value) <> 'object'
      or pg_catalog.jsonb_typeof(item.value->'player_id') <> 'string'
      or pg_catalog.btrim(coalesce(
        item.value->>'player_id', ''
      )) = ''
      or item.value->>'player_id' is distinct from
        pg_catalog.btrim(item.value->>'player_id')
      or not production_control.handicap_v1_json_decimal(
        item.value->'tournament_handicap'
      )
      or (
        item.value ? 'source_index'
        and item.value->'source_index' <> 'null'::jsonb
        and not production_control.handicap_v1_json_decimal(
          item.value->'source_index'
        )
      )
      or (
        item.value ? 'low_index'
        and item.value->'low_index' <> 'null'::jsonb
        and not production_control.handicap_v1_json_decimal(
          item.value->'low_index'
        )
      )
      or (
        item.value ? 'source_metadata'
        and pg_catalog.jsonb_typeof(item.value->'source_metadata') <> 'object'
      )
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_ENTRY_NUMERIC_INVALID'
    );
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(input->'entries') item(value)
    group by item.value->>'player_id'
    having pg_catalog.count(*) > 1
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_DUPLICATE_PLAYER_ID'
    );
  end if;

  -- Normalize decimal values before the idempotency comparison.  This makes
  -- semantically identical exact values such as "8.10", "8.1", and the JSON
  -- number 8.1 replay the same receipt, while any changed action field under
  -- the same request key fails closed.
  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'player_id', item.value->>'player_id',
      'tournament_handicap',
        pg_catalog.trim_scale(
          (item.value->>'tournament_handicap')::numeric
        ),
      'source_index', case
        when item.value->'source_index' is null
          or item.value->'source_index' = 'null'::jsonb then null
        else pg_catalog.trim_scale(
          (item.value->>'source_index')::numeric
        )
      end,
      'low_index', case
        when item.value->'low_index' is null
          or item.value->'low_index' = 'null'::jsonb then null
        else pg_catalog.trim_scale(
          (item.value->>'low_index')::numeric
        )
      end,
      'source_metadata', coalesce(
        item.value->'source_metadata', '{}'::jsonb
      )
    ) order by item.value->>'player_id'
  ) into canonical_entries
  from pg_catalog.jsonb_array_elements(input->'entries') item(value);

  database_request_hash := production_control.handicap_v1_hash(
    pg_catalog.jsonb_build_object(
      'operation', 'STAGE',
      'operation_request_id', operation_request,
      'actor_player_id', actor_player,
      'actor_auth_user_id', actor_auth_user,
      'expected_predecessor_revision', expected_predecessor,
      'effective_date', effective_date_value,
      'method', method_value,
      'source_metadata', source_metadata_value,
      'source_evidence_date', source_evidence_date_value,
      'entries', canonical_entries
    )
  );
  select value.* into receipt
  from scoring_authority.handicap_operation_receipts value
  where value.tournament_id = '2026'
    and value.operation = 'STAGE'
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.request_payload_hash = database_request_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_IDEMPOTENCY_CONFLICT',
      'operation_request_id', operation_request
    );
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(input->'entries') item(value)
    left join scoring_authority.tournament_players roster
      on roster.tournament_id = '2026'
     and roster.player_id = item.value->>'player_id'
     and roster.participation_status = 'ACTIVE'
    where roster.player_id is null
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_UNKNOWN_PLAYER_ID'
    );
  end if;

  select pg_catalog.count(*) into active_count
  from scoring_authority.tournament_players value
  where value.tournament_id = '2026'
    and value.participation_status = 'ACTIVE';
  if pg_catalog.jsonb_array_length(input->'entries') <> active_count
     or exists (
       select 1
       from scoring_authority.tournament_players roster
       left join pg_catalog.jsonb_array_elements(input->'entries') item(value)
         on item.value->>'player_id' = roster.player_id
       where roster.tournament_id = '2026'
         and roster.participation_status = 'ACTIVE'
         and item.value is null
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_INCOMPLETE_ACTIVE_ROSTER',
      'active_roster_count', active_count,
      'entry_count', pg_catalog.jsonb_array_length(input->'entries')
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('production-handicap-revision:2026', 0)
  );
  -- Close the concurrent first-use race: the same request may have committed
  -- while this transaction waited for the tournament mutation lock.
  select value.* into receipt
  from scoring_authority.handicap_operation_receipts value
  where value.tournament_id = '2026'
    and value.operation = 'STAGE'
    and value.operation_request_id = operation_request;
  if found then
    if receipt.declared_request_payload_hash = declared_hash
       and receipt.request_payload_hash = database_request_hash then
      return receipt.response || pg_catalog.jsonb_build_object(
        'idempotent', true
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_IDEMPOTENCY_CONFLICT',
      'operation_request_id', operation_request
    );
  end if;
  select pointer.revision_number, pointer.revision_id
    into current_revision, predecessor_id
  from scoring_authority.handicap_revision_current pointer
  where pointer.tournament_id = '2026' for update;
  current_revision := coalesce(current_revision, 0);
  if current_revision <> expected_predecessor then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'code', 'HANDICAP_PREDECESSOR_STALE',
      'expected_predecessor_revision', expected_predecessor,
      'current_revision', current_revision
    );
  end if;

  roster_hash :=
    production_control.handicap_v1_roster_fingerprint('2026');
  canonical_payload := pg_catalog.jsonb_build_object(
    'contract_version', 'production-handicap-revision-v1',
    'context_contract_version', 'production-handicap-context-v1',
    'tournament_id', '2026',
    'effective_date', effective_date_value,
    'method', method_value,
    'source_metadata', source_metadata_value,
    'source_evidence_date', source_evidence_date_value,
    'predecessor_revision', expected_predecessor,
    'roster_fingerprint', roster_hash,
    'entries', canonical_entries
  );
  canonical_hash := production_control.handicap_v1_hash(canonical_payload);
  select coalesce(pg_catalog.max(value.revision_number), 0) + 1
    into next_revision
  from scoring_authority.handicap_revisions value
  where value.tournament_id = '2026';

  insert into scoring_authority.handicap_revisions (
    tournament_id, revision_number, status, effective_date, method,
    source_metadata, source_evidence_date, canonical_fingerprint,
    roster_fingerprint, predecessor_revision, predecessor_revision_id,
    context_contract_version, created_by, created_by_auth_user_id
  ) values (
    '2026', next_revision, 'DRAFT', effective_date_value, method_value,
    source_metadata_value, source_evidence_date_value, canonical_hash,
    roster_hash, expected_predecessor, predecessor_id,
    'production-handicap-context-v1', actor_player, actor_auth_user
  ) returning revision_id into revision_id_value;

  insert into scoring_authority.handicap_revision_entries (
    revision_id, tournament_id, player_id, tournament_handicap,
    source_index, low_index, source_metadata
  )
  select revision_id_value, '2026', item.value->>'player_id',
    (item.value->>'tournament_handicap')::numeric,
    case when item.value->'source_index' is null
      or item.value->'source_index' = 'null'::jsonb then null
      else (item.value->>'source_index')::numeric end,
    case when item.value->'low_index' is null
      or item.value->'low_index' = 'null'::jsonb then null
      else (item.value->>'low_index')::numeric end,
    coalesce(item.value->'source_metadata', '{}'::jsonb)
  from pg_catalog.jsonb_array_elements(input->'entries') item(value)
  order by item.value->>'player_id';

  validation_value := production_control.validate_handicap_revision_v1(
    revision_id_value, expected_predecessor
  );
  audit_event_id_value := extensions.gen_random_uuid();
  response_value := pg_catalog.jsonb_build_object(
    'ok', true,
    'code', 'HANDICAP_REVISION_STAGED',
    'idempotent', false,
    'operation_request_id', operation_request,
    'revision_id', revision_id_value,
    'revision_number', next_revision,
    'status', 'DRAFT',
    'effective_date', effective_date_value,
    'canonical_fingerprint', canonical_hash,
    'changed_player_count', coalesce(
      (validation_value#>>'{summary,changed_player_count}')::integer, 0
    ),
    'affected_match_count', coalesce(
      (validation_value#>>'{summary,unstarted_refresh_count}')::integer, 0
    ) + coalesce(
      (validation_value#>>'{summary,started_preserved_count}')::integer, 0
    ),
    'audit_event_id', audit_event_id_value,
    'request_payload_hash', declared_hash,
    'receipt', pg_catalog.jsonb_build_object(
      'receipt_id', receipt_id_value,
      'operation_request_id', operation_request,
      'request_payload_hash', declared_hash,
      'status', 'STAGED'
    ),
    'validation', validation_value
  );

  insert into scoring_authority.handicap_audit_events (
    event_id, tournament_id, revision_id, action, actor_player_id,
    actor_auth_user_id, operation_request_id, request_payload_hash,
    canonical_fingerprint, before_state, after_state
  ) values (
    audit_event_id_value, '2026', revision_id_value, 'REVISION_STAGED',
    actor_player, actor_auth_user, operation_request,
    database_request_hash, canonical_hash,
    pg_catalog.jsonb_build_object(
      'predecessor_revision', expected_predecessor
    ),
    pg_catalog.jsonb_build_object(
      'revision_number', next_revision,
      'status', 'DRAFT',
      'entry_count', active_count,
      'changed_player_count', coalesce(
        (validation_value#>>'{summary,changed_player_count}')::integer, 0
      ),
      'affected_match_count', coalesce(
        (validation_value#>>'{summary,unstarted_refresh_count}')::integer, 0
      ) + coalesce(
        (validation_value#>>'{summary,started_preserved_count}')::integer, 0
      ),
      'validation', validation_value - 'changed_players'
        - 'unstarted_matches' - 'started_frozen_matches'
    )
  );
  insert into scoring_authority.handicap_operation_receipts (
    receipt_id, tournament_id, operation, operation_request_id,
    declared_request_payload_hash, request_payload_hash,
    actor_player_id, actor_auth_user_id, response
  ) values (
    receipt_id_value, '2026', 'STAGE', operation_request, declared_hash,
    database_request_hash, actor_player, actor_auth_user, response_value
  );
  insert into production_control.operation_audit_events (
    event_type, domain, tournament_id, actor, request_fingerprint,
    result, details
  ) values (
    'PRODUCTION_HANDICAP_REVISION_STAGED', 'HANDICAP_CONFIGURATION',
    '2026', actor_player, database_request_hash, 'SUCCEEDED',
    response_value - 'validation'
  );
  return response_value;
end;
$_$;


