--
-- Name: bind_annual_job_generation_v1(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.bind_annual_job_generation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare generation_id uuid; certification_context jsonb;
begin
  if new.tournament_id = '2026' then
    new.runtime_generation_id := null;
    return new;
  end if;
  if tg_table_schema='scoring_authority' and tg_table_name in (
      'competition_recalculation_jobs','net_skins_v1_recalculation_jobs','calcutta_v1_recalculation_jobs')
      and exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION') then
    certification_context:=production_control.current_certification_context_v1();
    -- A future setup job remains intentionally unbound until activation.
    if new.tournament_id is distinct from certification_context->>'current_tournament_id' then
      if not exists(select 1 from production_control.future_tournament_catalog_v1 catalog
        where catalog.tournament_id=new.tournament_id
          and catalog.tournament_year>(certification_context->>'current_tournament_year')::integer
          and catalog.lifecycle in('DRAFT','CONFIGURING','READY_FOR_ACTIVATION'))then
        raise exception using errcode='42501',message='CERTIFICATION_JOB_TARGET_DENIED';
      end if;
      new.runtime_generation_id:=null;
      return new;
    end if;
    perform production_control.assert_current_certification_future_context_v1(certification_context);
    select value.runtime_generation_id into strict generation_id
    from production_control.future_annual_runtime_generations_v1 value
    join production_control.current_tournament_pointer_v1 pointer
      on pointer.scope_key=certification_context->>'resource_id'
      and pointer.tournament_id=value.tournament_id
      and pointer.pointer_revision=value.pointer_revision
    join production_control.annual_scoring_runtime_authorities_v1 annual
      on annual.tournament_id=value.tournament_id
      and annual.runtime_generation_id=value.runtime_generation_id
      and annual.authority_generation_id=value.authority_generation_id
      and annual.admission_generation_id=value.admission_generation_id
      and annual.authority_status='ACTIVE'
    where value.tournament_id=new.tournament_id and value.generation_status='ACTIVE'
      and value.authority_generation_id::text=certification_context->>'authority_epoch_id';
    new.runtime_generation_id:=generation_id;
    return new;
  end if;
  select value.runtime_generation_id into generation_id
  from production_control.future_annual_runtime_generations_v1 value
  join production_control.current_tournament_pointer_v1 pointer
    on pointer.scope_key = 'BAGGER_INV_PRODUCTION'
   and pointer.tournament_id = value.tournament_id
   and pointer.pointer_revision = value.pointer_revision
  where value.tournament_id = new.tournament_id
    and value.generation_status = 'ACTIVE';
  -- Setup-time derived jobs are retained but deliberately unbound. No worker
  -- RPC below can claim a null generation.
  new.runtime_generation_id := generation_id;
  return new;
end;
$$;


ALTER FUNCTION scoring_authority.bind_annual_job_generation_v1() OWNER TO postgres;

--
-- Name: build_guide_course_context(text); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.build_guide_course_context(target_tournament text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  course_context_value jsonb;
begin
  if btrim(coalesce(target_tournament, '')) <> '2026' then return '[]'::jsonb; end if;
  with raw_context as (
    select m.match_id, m.round_number, m.format, m.match_revision,
      ss.snapshot_id, ss.snapshot_revision, ss.course_id, ss.tee,
      ss.rating, ss.slope, ss.par, ss.canonical_hash,
      ss.tournament_id as snapshot_tournament_id,
      ss.match_id as snapshot_match_id,
      ss.format as snapshot_format,
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'hole_number', mh.hole_number,
          'par', mh.par,
          'stroke_index', mh.stroke_index,
          'yardage', mh.yardage
        ) order by mh.hole_number)
        from scoring_authority.match_holes mh
        where mh.match_id = m.match_id and mh.snapshot_id = ss.snapshot_id
      ), '[]'::jsonb) as holes
    from scoring_authority.matches m
    join scoring_authority.scoring_snapshots ss on ss.snapshot_id = m.scoring_snapshot_id
    where m.tournament_id = target_tournament
  ), validated_context as (
    select raw_context.*,
      raw_context.snapshot_tournament_id = target_tournament
      and raw_context.snapshot_match_id = raw_context.match_id
      and raw_context.snapshot_format = raw_context.format
      and exists (
        select 1 from scoring_authority.rounds canonical_round
        where canonical_round.tournament_id = target_tournament
          and canonical_round.round_number = raw_context.round_number
          and canonical_round.format = raw_context.format
      )
      and btrim(raw_context.course_id) <> ''
      and btrim(raw_context.tee) <> ''
      and raw_context.rating is not null
      and raw_context.slope is not null and raw_context.slope > 0
      and jsonb_array_length(raw_context.holes) = 18
      and not exists (
        select 1 from generate_series(1, 18) expected(hole_number)
        where not exists (
          select 1 from jsonb_array_elements(raw_context.holes) hole
          where (hole->>'hole_number')::integer = expected.hole_number
        )
      )
      and not exists (
        select 1 from generate_series(1, 18) expected(stroke_index)
        where not exists (
          select 1 from jsonb_array_elements(raw_context.holes) hole
          where (hole->>'stroke_index')::integer = expected.stroke_index
        )
      )
      and raw_context.par = coalesce((
        select sum((hole->>'par')::integer)
        from jsonb_array_elements(raw_context.holes) hole
      ), 0) as context_valid
    from raw_context
  ), ranked_context as (
    select validated_context.*,
      row_number() over (
        partition by upper(btrim(validated_context.course_id)), upper(btrim(validated_context.tee))
        order by validated_context.snapshot_revision desc,
          validated_context.match_id
      ) as context_rank
    from validated_context
  ), selected_context as (
    select * from ranked_context where context_rank = 1
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'course_id', selected.course_id,
    'tee', selected.tee,
    'rating', selected.rating,
    'slope', selected.slope,
    'par', selected.par,
    'scoring_snapshot_id', selected.snapshot_id,
    'scoring_snapshot_fingerprint', selected.canonical_hash,
    'configuration_fingerprint', encode(extensions.digest(jsonb_build_object(
      'course_id', selected.course_id,
      'tee', selected.tee,
      'rating', selected.rating,
      'slope', selected.slope,
      'par', selected.par,
      'holes', selected.holes
    )::text, 'sha256'), 'hex'),
    'configuration_consistent', selected.context_valid and not exists (
      select 1 from ranked_context compared
      where upper(btrim(compared.course_id)) = upper(btrim(selected.course_id))
        and upper(btrim(compared.tee)) = upper(btrim(selected.tee))
        and (
          not compared.context_valid
          or compared.rating is distinct from selected.rating
          or compared.slope is distinct from selected.slope
          or compared.par is distinct from selected.par
          or compared.holes is distinct from selected.holes
        )
    ),
    'rounds', coalesce((
      select jsonb_agg(jsonb_build_object(
        'round_number', assignment.round_number,
        'format', assignment.format,
        'name', assignment.name,
        'status', assignment.status
      ) order by assignment.round_number, assignment.format)
      from (
        select distinct compared.round_number, compared.format, r.name, r.status
        from ranked_context compared
        join scoring_authority.rounds r
          on r.tournament_id = target_tournament and r.round_number = compared.round_number
          and r.format = compared.format
        where upper(btrim(compared.course_id)) = upper(btrim(selected.course_id))
          and upper(btrim(compared.tee)) = upper(btrim(selected.tee))
      ) assignment
    ), '[]'::jsonb),
    'holes', selected.holes
  ) order by selected.course_id, selected.tee), '[]'::jsonb)
  into course_context_value
  from selected_context selected;
  return course_context_value;
end;
$$;


ALTER FUNCTION scoring_authority.build_guide_course_context(target_tournament text) OWNER TO postgres;

--
-- Name: capture_finalized_scorecard_snapshot(text, text); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.capture_finalized_scorecard_snapshot(target_match text, actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  match_row scoring_authority.matches%rowtype;
  tournament_row scoring_authority.tournaments%rowtype;
  round_row scoring_authority.rounds%rowtype;
  scoring_row scoring_authority.scoring_snapshots%rowtype;
  presentation_row scoring_authority.game_center_presentations%rowtype;
  prior_row scoring_authority.finalized_scorecard_snapshots%rowtype;
  existing_row scoring_authority.finalized_scorecard_snapshots%rowtype;
  new_snapshot_id uuid := gen_random_uuid();
  next_snapshot_revision bigint;
  expected_participants integer;
  expected_scores_per_side integer;
  participant_count integer;
  hole_count integer;
  teams_value jsonb;
  participants_value jsonb;
  holes_value jsonb;
  hole_revisions jsonb;
  progress_value jsonb;
  source_value jsonb;
  payload_value jsonb;
  source_hash text;
  payload_hash_value text;
begin
  select * into match_row from scoring_authority.matches where match_id = btrim(coalesce(target_match, '')) for update;
  if not found then raise exception using errcode = 'P0001', message = 'ARCHIVE_MATCH_NOT_FOUND'; end if;
  if match_row.status <> 'FINAL' or not match_row.scorecard_complete or match_row.scored_holes <> 18
     or match_row.unresolved_mutations <> 0 or match_row.finalized_at is null or btrim(match_row.result_winner) = '' then
    raise exception using errcode = 'P0001', message = 'ARCHIVE_FINALIZATION_INELIGIBLE';
  end if;
  if match_row.format not in ('BB', 'SC', 'SI') then raise exception using errcode = 'P0001', message = 'ARCHIVE_FORMAT_INVALID'; end if;

  select * into tournament_row from scoring_authority.tournaments where tournament_id = match_row.tournament_id;
  select * into round_row from scoring_authority.rounds where tournament_id = match_row.tournament_id and round_number = match_row.round_number;
  select * into scoring_row from scoring_authority.scoring_snapshots where snapshot_id = match_row.scoring_snapshot_id;
  select * into presentation_row from scoring_authority.game_center_presentations where match_id = match_row.match_id;
  if tournament_row.tournament_id is null or round_row.tournament_id is null or scoring_row.snapshot_id is null
     or presentation_row.match_id is null or btrim(presentation_row.display_match_number) = ''
     or scoring_row.match_id <> match_row.match_id or scoring_row.format <> match_row.format
     or scoring_row.tournament_id <> match_row.tournament_id or jsonb_array_length(scoring_row.hole_definitions) <> 18 then
    raise exception using errcode = 'P0001', message = 'ARCHIVE_CANONICAL_CONTEXT_INCOMPLETE';
  end if;

  expected_participants := case when match_row.format = 'SI' then 2 else 4 end;
  expected_scores_per_side := case when match_row.format = 'BB' then 2 else 1 end;
  select count(*) into participant_count from scoring_authority.match_participants where match_id = match_row.match_id;
  if participant_count <> expected_participants
     or exists (
       select 1 from generate_series(1, 2) side(team_side)
       where (select count(*) from scoring_authority.match_participants mp where mp.match_id = match_row.match_id and mp.team_side = side.team_side)
         <> case when match_row.format = 'SI' then 1 else 2 end
     )
     or exists (
       select 1 from scoring_authority.match_participants mp
       left join scoring_authority.tournament_players tp
         on tp.tournament_id = match_row.tournament_id and tp.player_id = mp.player_id
       where mp.match_id = match_row.match_id
         and (tp.player_id is null or tp.team_side <> mp.team_side or tp.participation_status <> 'ACTIVE')
     ) then raise exception using errcode = 'P0001', message = 'ARCHIVE_PARTICIPANT_MAPPING_INVALID'; end if;

  select count(distinct hs.hole_number) into hole_count from scoring_authority.hole_scores hs where hs.match_id = match_row.match_id;
  if hole_count <> 18
     or (select count(*) from scoring_authority.match_holes mh where mh.match_id = match_row.match_id) <> 18
     or exists (
       select 1 from scoring_authority.hole_scores hs where hs.match_id = match_row.match_id and (
         not scoring_authority.valid_gross_scores(hs.team_1_gross_scores, expected_scores_per_side)
         or not scoring_authority.valid_gross_scores(hs.team_2_gross_scores, expected_scores_per_side)
         or jsonb_typeof(hs.team_1_strokes) <> 'array' or jsonb_array_length(hs.team_1_strokes) <> expected_scores_per_side
         or jsonb_typeof(hs.team_2_strokes) <> 'array' or jsonb_array_length(hs.team_2_strokes) <> expected_scores_per_side
       )
     ) then raise exception using errcode = 'P0001', message = 'ARCHIVE_HOLE_SET_INVALID'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'team_id', t.team_id, 'team_side', t.team_side, 'name', t.name
  ) order by t.team_side), '[]'::jsonb) into teams_value
  from scoring_authority.teams t where t.tournament_id = match_row.tournament_id;
  if jsonb_array_length(teams_value) <> 2 then raise exception using errcode = 'P0001', message = 'ARCHIVE_TEAM_MAPPING_INVALID'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'player_id', mp.player_id, 'display_name', p.display_name, 'team_side', mp.team_side,
    'player_slot', mp.player_slot, 'handicap_index', mp.handicap_index,
    'course_handicap', mp.course_handicap, 'playing_handicap', mp.playing_handicap,
    'final_strokes', mp.final_strokes
  ) order by mp.team_side, mp.player_slot), '[]'::jsonb) into participants_value
  from scoring_authority.match_participants mp join scoring_authority.players p using (player_id)
  where mp.match_id = match_row.match_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'hole_number', hs.hole_number, 'hole_revision', hs.hole_revision,
    'par', mh.par, 'stroke_index', mh.stroke_index, 'yardage', mh.yardage,
    'team_1_gross_scores', hs.team_1_gross_scores, 'team_2_gross_scores', hs.team_2_gross_scores,
    'team_1_strokes', hs.team_1_strokes, 'team_2_strokes', hs.team_2_strokes,
    'team_1_net_score', hs.team_1_net_score, 'team_2_net_score', hs.team_2_net_score,
    'hole_winner', hs.hole_winner
  ) order by hs.hole_number), '[]'::jsonb),
  coalesce(jsonb_object_agg(hs.hole_number::text, hs.hole_revision order by hs.hole_number), '{}'::jsonb)
  into holes_value, hole_revisions
  from scoring_authority.hole_scores hs join scoring_authority.match_holes mh
    on mh.match_id = hs.match_id and mh.hole_number = hs.hole_number
  where hs.match_id = match_row.match_id;

  progress_value := scoring_authority.match_progress(match_row.match_id, match_row.format);
  if coalesce((progress_value->>'scorecard_complete')::boolean, false) is not true
     or btrim(coalesce(progress_value->>'result_winner', '')) <> btrim(match_row.result_winner) then
    raise exception using errcode = 'P0001', message = 'ARCHIVE_RESULT_STATE_INCOHERENT';
  end if;

  source_value := jsonb_build_object(
    'schema_version', 'round-scorecards-v1',
    'tournament', jsonb_build_object('tournament_id', tournament_row.tournament_id, 'year', tournament_row.tournament_year, 'name', tournament_row.name),
    'round', jsonb_build_object('round_number', round_row.round_number, 'format', round_row.format, 'name', round_row.name),
    'match', jsonb_build_object(
      'match_id', match_row.match_id, 'display_number', presentation_row.display_match_number,
      'format', match_row.format, 'status', match_row.status, 'match_revision', match_row.match_revision,
      'result_winner', match_row.result_winner, 'running_result', match_row.running_result,
      'finalized_at', match_row.finalized_at
    ),
    'course', jsonb_build_object(
      'course_id', scoring_row.course_id, 'tee', scoring_row.tee, 'rating', scoring_row.rating,
      'slope', scoring_row.slope, 'par', scoring_row.par, 'scoring_snapshot_id', scoring_row.snapshot_id,
      'scoring_snapshot_revision', scoring_row.snapshot_revision, 'configuration_fingerprint', scoring_row.canonical_hash
    ),
    'teams', teams_value, 'participants', participants_value, 'holes', holes_value,
    'hole_revision_set', hole_revisions, 'result', progress_value
  );
  source_hash := encode(extensions.digest(source_value::text, 'sha256'), 'hex');
  payload_value := source_value || jsonb_build_object('source_fingerprint', source_hash);
  payload_hash_value := encode(extensions.digest(payload_value::text, 'sha256'), 'hex');

  select * into existing_row from scoring_authority.finalized_scorecard_snapshots
  where match_id = match_row.match_id and match_revision = match_row.match_revision;
  if found then
    if existing_row.source_fingerprint <> source_hash or existing_row.payload_hash <> payload_hash_value then
      raise exception using errcode = 'P0001', message = 'ARCHIVE_SNAPSHOT_REVISION_CONFLICT';
    end if;
    -- Google runtime retired: external delivery is not canonical authority.
    return jsonb_build_object('ok', true, 'created', false, 'snapshot_id', existing_row.snapshot_id,
      'snapshot_revision', existing_row.snapshot_revision, 'match_revision', existing_row.match_revision,
      'source_fingerprint', existing_row.source_fingerprint, 'payload_hash', existing_row.payload_hash);
  end if;

  select * into prior_row from scoring_authority.finalized_scorecard_snapshots
  where match_id = match_row.match_id and state = 'CURRENT' for update;
  select coalesce(max(snapshot_revision), 0) + 1 into next_snapshot_revision
  from scoring_authority.finalized_scorecard_snapshots where match_id = match_row.match_id;
  if prior_row.snapshot_id is not null then
    update scoring_authority.finalized_scorecard_snapshots set
      state = 'SUPERSEDED', superseded_at = now(), superseded_by_snapshot_id = null
    where snapshot_id = prior_row.snapshot_id;
  end if;
  insert into scoring_authority.finalized_scorecard_snapshots (
    snapshot_id, tournament_id, match_id, snapshot_revision, match_revision,
    scoring_snapshot_id, scoring_snapshot_revision, source_fingerprint, payload_hash,
    payload, state, finalized_at
  ) values (
    new_snapshot_id, match_row.tournament_id, match_row.match_id, next_snapshot_revision, match_row.match_revision,
    scoring_row.snapshot_id, scoring_row.snapshot_revision, source_hash, payload_hash_value,
    payload_value, 'CURRENT', match_row.finalized_at
  );
  if prior_row.snapshot_id is not null then
    update scoring_authority.finalized_scorecard_snapshots set superseded_by_snapshot_id = new_snapshot_id
    where snapshot_id = prior_row.snapshot_id;
  end if;
  -- Google runtime retired: external delivery is not canonical authority.
  -- Google runtime retired: external delivery is not canonical authority.
  insert into scoring_authority.audit_events (tournament_id, match_id, action, actor_id, metadata)
  values (match_row.tournament_id, match_row.match_id, 'FINALIZED_SCORECARD_SNAPSHOT_CREATED', coalesce(nullif(btrim(actor), ''), 'Supabase Finalization'),
    jsonb_build_object('snapshot_id', new_snapshot_id, 'snapshot_revision', next_snapshot_revision,
      'match_revision', match_row.match_revision, 'source_fingerprint', source_hash, 'payload_hash', payload_hash_value));
  return jsonb_build_object('ok', true, 'created', true, 'snapshot_id', new_snapshot_id,
    'snapshot_revision', next_snapshot_revision, 'match_revision', match_row.match_revision,
    'source_fingerprint', source_hash, 'payload_hash', payload_hash_value);
end;
$$;


ALTER FUNCTION scoring_authority.capture_finalized_scorecard_snapshot(target_match text, actor text) OWNER TO postgres;

--
-- Name: capture_scorecard_archive_transition(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.capture_scorecard_archive_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.status = 'FINAL' and old.status <> 'FINAL' then
    perform scoring_authority.capture_finalized_scorecard_snapshot(new.match_id, 'Supabase Finalization');
  elsif old.status = 'FINAL' and new.status <> 'FINAL' then
    perform scoring_authority.invalidate_finalized_scorecard_snapshot(new.match_id, new.match_revision, 'Supabase Reopen');
  end if;
  return new;
end;
$$;


ALTER FUNCTION scoring_authority.capture_scorecard_archive_transition() OWNER TO postgres;

--
-- Name: enqueue_annual_derived_v1_change(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_annual_derived_v1_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_match text;
  target_tournament text;
  current_tournament text;
  runtime_generation uuid;
  reason_value text;
  revision_value jsonb;
  prior_revision_value jsonb;
  engine_values text[];
  engine_value text;
begin
  if tg_table_schema <> 'scoring_authority'
     or tg_table_name not in (
       'hole_scores', 'matches', 'odds_published_snapshots',
       'net_skins_v1_result_revisions'
     ) then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_DERIVED_TRIGGER_SCOPE_INVALID';
  end if;
  if tg_table_name = 'hole_scores' then
    target_match := case when tg_op = 'DELETE'
      then old.match_id else new.match_id end;
    select value.tournament_id into target_tournament
    from scoring_authority.matches value
    where value.match_id = target_match;
    reason_value := 'CANONICAL_HOLE_SCORE_CHANGED';
    revision_value := pg_catalog.jsonb_build_object(
      'matchId', target_match,
      'holeNumber', case when tg_op = 'DELETE'
        then old.hole_number else new.hole_number end,
      'holeRevision', case when tg_op = 'DELETE'
        then old.hole_revision else new.hole_revision end
    );
    engine_values := array[
      'TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES',
      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
      'TOURNAMENT_FINAL_RECAP'
    ]::text[];
  elsif tg_table_name = 'matches' then
    target_match := new.match_id;
    target_tournament := new.tournament_id;
    reason_value := 'CANONICAL_MATCH_CHANGED';
    revision_value := pg_catalog.jsonb_build_object(
      'matchId', target_match,
      'matchRevision', new.match_revision,
      'status', new.status,
      'resultWinner', new.result_winner,
      'scorecardComplete', new.scorecard_complete
    );
    if tg_op='UPDATE' then
      prior_revision_value:=jsonb_build_object('matchId',old.match_id,'matchRevision',old.match_revision,
        'status',old.status,'resultWinner',old.result_winner,'scorecardComplete',old.scorecard_complete);
    else
      -- A canonical INSERT proves absence of this match in the prior source.
      prior_revision_value:=jsonb_build_object('matchId',target_match,'sourceAbsent',true);
    end if;
    engine_values := array[
      'TEAM_MOMENTUM', 'TOURNAMENT_STORYLINES',
      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
      'TOURNAMENT_FINAL_RECAP'
    ]::text[];
  elsif tg_table_name = 'odds_published_snapshots' then
    target_tournament := new.tournament_id;
    reason_value := 'OFFICIAL_ODDS_PUBLICATION_CHANGED';
    revision_value := pg_catalog.jsonb_build_object(
      'publicationRevision', new.publication_revision,
      'payloadHash', new.payload_hash,
      'isCurrentOfficial', new.is_current_official
    );
    engine_values := array[
      'TOURNAMENT_INTELLIGENCE', 'PROJECTION_EDITORIAL',
      'TOURNAMENT_FINAL_RECAP'
    ]::text[];
  else
    if new.is_current is not true then
      return new;
    end if;
    target_tournament := new.tournament_id;
    reason_value := 'NET_SKINS_CURRENT_RESULT_CHANGED';
    revision_value := pg_catalog.jsonb_build_object(
      'roundNumber', new.round_number,
      'resultRevision', new.result_revision,
      'payloadHash', new.payload_hash,
      'isCurrent', new.is_current
    );
    engine_values := array['TOURNAMENT_STORYLINES']::text[];
  end if;
  if target_tournament is null then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_DERIVED_TRIGGER_TOURNAMENT_REQUIRED';
  end if;

  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.tournament_id into strict current_tournament
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = production_control.canonical_execution_resource_id_v1();
  -- Setup and historical corrections for a non-current tournament do not
  -- create current-runtime work. Their own activation preparation owns their
  -- future generation and readiness markers.
  if target_tournament <> current_tournament then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if target_tournament = '2026' then
    if not exists (
      select 1 from scoring_authority.ingress_gates value
      where value.tournament_id = '2026' and value.state = 'OPEN'
        and value.authority = 'SUPABASE'
    ) then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ANNUAL_DERIVED_ADMISSION_CLOSED';
    end if;
  else
    select value.runtime_generation_id into runtime_generation
    from production_control.annual_scoring_runtime_authorities_v1 value
    where value.tournament_id = target_tournament
      and value.authority_status = 'ACTIVE'
      and value.admission_state = 'OPEN';
    if runtime_generation is null then
      raise exception using errcode = '55000',
        message = 'PRODUCTION_ANNUAL_DERIVED_RUNTIME_REQUIRED';
    end if;
  end if;

  if tg_table_name = 'hole_scores' or (tg_table_name = 'matches' and exists (
    select 1 from scoring_authority.score_derived_intents_v1 intent
    where intent.tournament_id = target_tournament and intent.match_id = target_match
      and intent.source_transaction = txid_current() and intent.family = 'COMPETITION')) then
    perform production_control.append_score_derived_intent_v1(
      target_tournament, target_match,
      (select round_number from scoring_authority.matches where match_id = target_match),
      'COMPETITION', reason_value, revision_value || jsonb_strip_nulls(jsonb_build_object(
        'mutationKey', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'mutation_key' else null end)), runtime_generation
    );
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  foreach engine_value in array engine_values loop
    insert into scoring_authority.competition_recalculation_jobs (
      tournament_id, round_number, engine_key, status,
      requested_source_revision, requested_at, started_at, completed_at,
      last_error_code, last_error_safe, runtime_generation_id,
      claim_token, claimed_by, lease_expires_at, updated_at
    ) values (
      target_tournament, 0, engine_value, 'PENDING',
      pg_catalog.jsonb_build_object(
        'reason', reason_value, 'revision', revision_value,
        'priorRevision', prior_revision_value, 'transactional', true
      ), pg_catalog.clock_timestamp(), null, null, null, null,
      runtime_generation, null, null, null, pg_catalog.clock_timestamp()
    ) on conflict (tournament_id, round_number, engine_key) do update set
      status = 'PENDING',
      requested_source_revision = excluded.requested_source_revision,
      requested_at = excluded.requested_at,
      started_at = null, completed_at = null,
      last_error_code = null, last_error_safe = null,
      runtime_generation_id = excluded.runtime_generation_id,
      claim_token = null, claimed_by = null, lease_expires_at = null,
      updated_at = excluded.updated_at;
  end loop;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_annual_derived_v1_change() OWNER TO postgres;

--
-- Name: enqueue_annual_net_skins_v1_change(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_annual_net_skins_v1_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_match_id text;
  match_value scoring_authority.matches%rowtype;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
begin
  target_match_id := case when tg_op = 'DELETE'
    then old.match_id else new.match_id end;
  select value.* into match_value
  from scoring_authority.matches value
  where value.match_id = target_match_id;
  if not found or match_value.tournament_id = '2026' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  select value.* into current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = match_value.tournament_id;
  if not found or current_value.state <> 'CONFIGURED' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  perform pg_catalog.pg_advisory_xact_lock_shared(
    production_control.scoring_admission_lock_key()
  );
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = production_control.canonical_execution_resource_id_v1();
  select value.* into strict generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = match_value.tournament_id
    and value.generation_status = 'ACTIVE';
  if pointer.tournament_id <> match_value.tournament_id
     or pointer.pointer_revision <> generation.pointer_revision then
    raise exception using errcode = '55000',
      message = 'PRODUCTION_ANNUAL_NET_SKINS_RUNTIME_REQUIRED';
  end if;
  if tg_table_name = 'hole_scores' or (tg_table_name = 'matches' and exists (
    select 1 from scoring_authority.score_derived_intents_v1 intent
    where intent.tournament_id = match_value.tournament_id
      and intent.match_id = target_match_id
      and intent.source_transaction = txid_current() and intent.family = 'COMPETITION')) then
  if exists (select 1 from scoring_authority.net_skins_v1_configuration_revisions revision
    cross join lateral jsonb_array_elements(revision.configuration_manifest->'rounds') configured
    where revision.configuration_revision_id = current_value.configuration_revision_id
      and (configured->>'round_number')::integer = match_value.round_number) then
    perform production_control.append_score_derived_intent_v1(
      match_value.tournament_id, target_match_id, match_value.round_number, 'NET_SKINS',
      case when tg_table_name = 'hole_scores' then 'CANONICAL_SCORE_CHANGED' else 'CANONICAL_MATCH_LIFECYCLE_CHANGED' end,
      jsonb_strip_nulls(jsonb_build_object('matchRevision', match_value.match_revision,
        'holeNumber', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'hole_number' else null end,
        'holeRevision', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'hole_revision' else null end,
        'mutationKey', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'mutation_key' else null end)), generation.runtime_generation_id
    );
  end if;
  else
  perform production_control.enqueue_annual_net_skins_v1_round(
    match_value.tournament_id, generation.runtime_generation_id,
    match_value.round_number,
    case when tg_table_name = 'hole_scores'
      then 'CANONICAL_SCORE_CHANGED'
      else 'CANONICAL_MATCH_LIFECYCLE_CHANGED' end,
    'production-net-skins-v1-trigger'
  );
  end if;
  return case when tg_op = 'DELETE' then old else new end;
exception
  when sqlstate '22023' then
    return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_annual_net_skins_v1_change() OWNER TO postgres;

--
-- Name: enqueue_calcutta_for_match_change(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_calcutta_for_match_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if old.status is distinct from new.status
      or old.result_winner is distinct from new.result_winner
      or old.scorecard_complete is distinct from new.scorecard_complete
      or old.finalized_at is distinct from new.finalized_at
      or ((old.status = 'FINAL' or new.status = 'FINAL') and old.match_revision is distinct from new.match_revision) then
    perform scoring_authority.enqueue_calcutta_job(new.tournament_id, 'OFFICIAL_MATCH_STATE_CHANGE',
      jsonb_build_object('matchId', new.match_id, 'priorStatus', old.status, 'status', new.status,
        'matchRevision', new.match_revision, 'scorecardComplete', new.scorecard_complete,
        'resultWinner', new.result_winner));
  end if;
  return new;
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_calcutta_for_match_change() OWNER TO postgres;

--
-- Name: enqueue_calcutta_job(text, text, jsonb); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_calcutta_job(target_tournament text, reason_value text, revision_value jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  insert into scoring_authority.competition_recalculation_jobs (
    tournament_id, round_number, engine_key, status, requested_source_revision,
    requested_at, updated_at
  ) values (
    target_tournament, 0, 'CALCUTTA', 'PENDING',
    jsonb_build_object('reason', reason_value, 'revision', coalesce(revision_value, '{}'::jsonb)),
    now(), now()
  ) on conflict (tournament_id, round_number, engine_key) do update set
    status = 'PENDING', requested_source_revision = excluded.requested_source_revision,
    requested_at = now(), started_at = null, completed_at = null,
    last_error_code = null, last_error_safe = null, updated_at = now();
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_calcutta_job(target_tournament text, reason_value text, revision_value jsonb) OWNER TO postgres;

--
-- Name: enqueue_competition_derived_job(text, text, text, jsonb); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_competition_derived_job(target_tournament text, target_engine text, reason_value text, revision_value jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  -- Legacy and canonical match triggers describe the same match revision.
  -- Include the canonical scorecard fact omitted by the legacy trigger; request
  -- reasons/provenance are not a new source or a new retry budget.
  if reason_value in('MATCH_CHANGE','OFFICIAL_RESULT_CHANGE') then
    revision_value:=revision_value||jsonb_build_object('scorecardComplete',(
      select m.scorecard_complete from scoring_authority.matches m
      where m.tournament_id=target_tournament and m.match_id=revision_value->>'matchId'
        and m.match_revision=(revision_value->>'matchRevision')::bigint));
  end if;
  insert into scoring_authority.competition_recalculation_jobs (
    tournament_id, round_number, engine_key, status, requested_source_revision,
    requested_at, updated_at
  ) values (
    target_tournament, 0, target_engine, 'PENDING',
    jsonb_build_object('reason', reason_value, 'revision', coalesce(revision_value, '{}'::jsonb)),
    now(), now()
  ) on conflict (tournament_id, round_number, engine_key) do update set
    status = 'PENDING', requested_source_revision = excluded.requested_source_revision,
    requested_at = now(), started_at = null, completed_at = null,
    last_error_code = null, last_error_safe = null, updated_at = now();
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_competition_derived_job(target_tournament text, target_engine text, reason_value text, revision_value jsonb) OWNER TO postgres;

--
-- Name: enqueue_derived_for_match_change(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_derived_for_match_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  perform scoring_authority.enqueue_competition_derived_job(
    new.tournament_id, 'TOURNAMENT_STORYLINES', 'MATCH_CHANGE',
    jsonb_build_object('matchId', new.match_id, 'matchRevision', new.match_revision,
      'status', new.status, 'resultWinner', new.result_winner)
  );
  if old.status is distinct from new.status
      or old.result_winner is distinct from new.result_winner
      or old.scorecard_complete is distinct from new.scorecard_complete
      or old.finalized_at is distinct from new.finalized_at then
    perform scoring_authority.enqueue_competition_derived_job(
      new.tournament_id, 'TEAM_MOMENTUM', 'OFFICIAL_RESULT_CHANGE',
      jsonb_build_object('matchId', new.match_id, 'matchRevision', new.match_revision,
        'status', new.status, 'resultWinner', new.result_winner)
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_derived_for_match_change() OWNER TO postgres;

--
-- Name: enqueue_net_skins_recalculation(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_net_skins_recalculation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  target_match scoring_authority.matches%rowtype;
  target_match_id text;
begin
  target_match_id := case when tg_op = 'DELETE' then old.match_id else new.match_id end;
  select * into target_match from scoring_authority.matches
  where match_id = target_match_id;
  if target_match.match_id is null then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;
  if exists (select 1 from scoring_authority.net_skins_configurations c
    where c.tournament_id = target_match.tournament_id and c.round_number = target_match.round_number and c.enabled) then
    insert into scoring_authority.competition_recalculation_jobs (
      tournament_id, round_number, engine_key, status, requested_source_revision, requested_at, updated_at
    ) values (target_match.tournament_id, target_match.round_number, 'NET_SKINS', 'PENDING',
      jsonb_build_object('matchId', target_match.match_id, 'matchRevision', target_match.match_revision,
        'reason', tg_table_name), now(), now())
    on conflict (tournament_id, round_number, engine_key) do update set
      status = 'PENDING', requested_source_revision = excluded.requested_source_revision,
      requested_at = now(), started_at = null, completed_at = null,
      last_error_code = null, last_error_safe = null, updated_at = now();
  end if;
  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_net_skins_recalculation() OWNER TO postgres;

--
-- Name: enqueue_production_calcutta_v1_change(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_production_calcutta_v1_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  row_payload jsonb := case when tg_op = 'DELETE'
    then pg_catalog.to_jsonb(old) else pg_catalog.to_jsonb(new) end;
  target_tournament text;
  target_match_id text;
  pointer production_control.current_tournament_pointer_v1%rowtype;
  generation production_control.future_annual_runtime_generations_v1%rowtype;
  current_value scoring_authority.calcutta_v1_current%rowtype;
  auction_manifest_value jsonb;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  resource_context jsonb;
  handling_activation_revision bigint;
begin
  if tg_table_name = 'matches' and tg_op = 'UPDATE' and exists (select 1 from production_control.late_r3_transactions_v1 where transaction_id=txid_current() and (to_jsonb(new)->>'match_id')=any(eligible_matches)) then
    if (to_jsonb(old)-array['match_revision','permission_revision','scoring_snapshot_id','updated_at','authority_updated_at']) is distinct from (to_jsonb(new)-array['match_revision','permission_revision','scoring_snapshot_id','updated_at','authority_updated_at']) then raise exception 'TOURNAMENT_SETUP_LIFECYCLE_TRIGGER_CHANGE_BLOCKED'; end if;
    return new;
  end if;
  if tg_table_name in ('rounds', 'matches') then
    target_tournament := row_payload->>'tournament_id';
  else
    target_match_id := row_payload->>'match_id';
    select match_value.tournament_id into target_tournament
    from scoring_authority.matches match_value
    where match_value.match_id = target_match_id;
  end if;
  select value.* into strict pointer
  from production_control.current_tournament_pointer_v1 value
  where value.scope_key = production_control.canonical_execution_resource_id_v1();
  if target_tournament is null
     or target_tournament is distinct from pointer.tournament_id then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  select value.* into current_value
  from scoring_authority.calcutta_v1_current value
  where value.tournament_id = target_tournament;
  if not found or current_value.state = 'NOT_CONFIGURED'
     or current_value.auction_revision = 0 then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION') then
    resource_context:=production_control.current_canonical_resource_context_v1();
    if target_tournament is distinct from resource_context->>'current_tournament_id' then
      return case when tg_op='DELETE' then old else new end;
    end if;
    handling_activation_revision:=(resource_context->>'activation_revision')::bigint;
  else
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or activation.read_cutover_phase <> 'OBSERVATION'
     or resource.scoring_authority <> 'SUPABASE'
     or resource.current_tournament_read_authority <> 'SUPABASE' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
    handling_activation_revision:=activation.activation_revision;
  end if;
  -- A supported last-entry clear retains a nonzero immutable revision, but
  -- supplies no financial facts to calculate. Revision existence is not demand.
  -- Check the complete current immutable identity before recognizing emptiness;
  -- a missing/stale/malformed auction must never become a silent skip.
  select value.auction_manifest into auction_manifest_value
  from scoring_authority.calcutta_v1_auction_fact_revisions value
  where value.auction_revision_id = current_value.auction_revision_id
    and value.tournament_id = target_tournament
    and value.auction_revision = current_value.auction_revision
    and value.auction_fingerprint = current_value.auction_fingerprint
    and value.auction_fingerprint = production_control.calcutta_v1_hash(value.auction_manifest);
  if not found then
    raise exception using errcode = '40001',
      message = 'PRODUCTION_CALCUTTA_AUCTION_REVISION_CONFLICT';
  end if;
  if jsonb_typeof(auction_manifest_value->'purchases') is distinct from 'array'
     or jsonb_typeof(auction_manifest_value->'ownership') is distinct from 'array' then
    raise exception using errcode = '22023',
      message = 'PRODUCTION_CALCUTTA_AUCTION_INPUT_INVALID';
  end if;
  if jsonb_array_length(auction_manifest_value->'purchases') = 0 then
    if auction_manifest_value is distinct from jsonb_build_object(
      'contract_version', 'production-calcutta-v1', 'state', 'AUCTION_COMPLETE',
      'auction_unit', 'PLAYER', 'entry_workflow', 'MANUAL_FINAL_AUCTION_FACTS',
      'currency_code', 'USD', 'tournament_id', target_tournament,
      'purchases', '[]'::jsonb, 'ownership', '[]'::jsonb, 'pot', 0)
       or current_value.state <> 'AUCTION_COMPLETE'
       or current_value.publication_state <> 'UNPUBLISHED'
       or current_value.result_revision <> 0
       or not exists (
         select 1 from scoring_authority.calcutta_v1_configuration_revisions value
         where value.configuration_revision_id = current_value.configuration_revision_id
           and value.tournament_id = target_tournament
           and value.configuration_revision = current_value.configuration_revision
           and value.configuration_fingerprint = current_value.configuration_fingerprint
           and value.configuration_fingerprint = production_control.calcutta_v1_hash(value.configuration_manifest)) then
      raise exception using errcode = '22023',
        message = 'PRODUCTION_CALCUTTA_AUCTION_INPUT_INVALID';
    end if;
    -- No direct job and no durable CALCUTTA intent. Explicit publish/enqueue
    -- guards remain unchanged and continue rejecting an auction without facts.
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if target_tournament = '2026' then
    if resource_context is null and resource.current_tournament_id <> '2026' then
      return case when tg_op = 'DELETE' then old else new end;
    end if;
    if tg_table_name = 'hole_scores' or (tg_table_name = 'matches' and exists (
      select 1 from scoring_authority.score_derived_intents_v1 intent
      where intent.tournament_id = target_tournament
        and intent.match_id = row_payload->>'match_id'
        and intent.source_transaction = txid_current() and intent.family = 'COMPETITION')) then
    perform production_control.append_score_derived_intent_v1(
      target_tournament, coalesce(row_payload->>'match_id', 'ROUND:' || (row_payload->>'round_number')),
      coalesce((row_payload->>'round_number')::integer, (select round_number from scoring_authority.matches where match_id = target_match_id)),
      'CALCUTTA', case when tg_table_name = 'hole_scores' then 'CANONICAL_SCORE_CHANGED'
        when tg_table_name = 'rounds' then 'CANONICAL_ROUND_LIFECYCLE_CHANGED' else 'CANONICAL_MATCH_LIFECYCLE_CHANGED' end,
      jsonb_strip_nulls(jsonb_build_object('matchRevision', row_payload->'match_revision',
        'holeNumber', row_payload->'hole_number', 'holeRevision', row_payload->'hole_revision',
        'mutationKey', row_payload->'mutation_key')), null
    );
    else
    perform production_control.enqueue_production_calcutta_v1(
      case
        when tg_table_name = 'hole_scores' then 'CANONICAL_SCORE_CHANGED'
        when tg_table_name = 'rounds'
          then 'CANONICAL_ROUND_LIFECYCLE_CHANGED'
        else 'CANONICAL_MATCH_LIFECYCLE_CHANGED'
      end,
      'production-calcutta-v1-trigger', false, null, null
    );
    end if;
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  select value.* into generation
  from production_control.future_annual_runtime_generations_v1 value
  where value.tournament_id = target_tournament
    and value.generation_status = 'ACTIVE'
    and value.pointer_revision = pointer.pointer_revision;
  if not found then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
    if tg_table_name = 'hole_scores' or (tg_table_name = 'matches' and exists (
      select 1 from scoring_authority.score_derived_intents_v1 intent
      where intent.tournament_id = target_tournament
        and intent.match_id = row_payload->>'match_id'
        and intent.source_transaction = txid_current() and intent.family = 'COMPETITION')) then
  perform production_control.append_score_derived_intent_v1(
      target_tournament, coalesce(row_payload->>'match_id', 'ROUND:' || (row_payload->>'round_number')),
      coalesce((row_payload->>'round_number')::integer, (select round_number from scoring_authority.matches where match_id = target_match_id)),
      'CALCUTTA', case when tg_table_name = 'hole_scores' then 'CANONICAL_SCORE_CHANGED'
        when tg_table_name = 'rounds' then 'CANONICAL_ROUND_LIFECYCLE_CHANGED' else 'CANONICAL_MATCH_LIFECYCLE_CHANGED' end,
      jsonb_strip_nulls(jsonb_build_object('matchRevision', row_payload->'match_revision',
        'holeNumber', row_payload->'hole_number', 'holeRevision', row_payload->'hole_revision',
        'mutationKey', row_payload->'mutation_key')), generation.runtime_generation_id
    );
    else
  perform production_control.enqueue_annual_calcutta_v1(
    target_tournament, generation.runtime_generation_id,
    handling_activation_revision,
    case
      when tg_table_name = 'hole_scores' then 'CANONICAL_SCORE_CHANGED'
      when tg_table_name = 'rounds'
        then 'CANONICAL_ROUND_LIFECYCLE_CHANGED'
      else 'CANONICAL_MATCH_LIFECYCLE_CHANGED'
    end,
    'production-calcutta-v1-trigger', false, null, null
  );
    end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_production_calcutta_v1_change() OWNER TO postgres;

--
-- Name: enqueue_production_net_skins_v1_change(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.enqueue_production_net_skins_v1_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'production_control', 'scoring_authority'
    AS $$
declare
  target_match_id text;
  match_value scoring_authority.matches%rowtype;
  current_value scoring_authority.net_skins_v1_configuration_current%rowtype;
  activation production_control.cutover_activation_state%rowtype;
  resource production_control.resource_scope%rowtype;
  resource_context jsonb;
begin
  target_match_id := case when tg_op = 'DELETE'
    then old.match_id else new.match_id end;
  select value.* into match_value
  from scoring_authority.matches value
  where value.match_id = target_match_id;
  if not found then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  select value.* into current_value
  from scoring_authority.net_skins_v1_configuration_current value
  where value.tournament_id = match_value.tournament_id;
  if not found or current_value.state <> 'CONFIGURED' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if exists(select 1 from production_control.canonical_resource_v1 where singleton and resource_class='CERTIFICATION') then
    resource_context:=production_control.current_canonical_resource_context_v1();
    if match_value.tournament_id<>'2026'
      or match_value.tournament_id is distinct from resource_context->>'current_tournament_id' then
      return case when tg_op='DELETE' then old else new end;
    end if;
  else
  select value.* into strict activation
  from production_control.cutover_activation_state value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  select value.* into strict resource
  from production_control.resource_scope value
  where value.scope_key = 'BAGGER_INV_PRODUCTION';
  if match_value.tournament_id <> '2026'
     or activation.state <> 'SCORING_COMMITTED'
     or activation.current_authority <> 'SUPABASE'
     or resource.scoring_authority <> 'SUPABASE' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  end if;

  if tg_table_name = 'hole_scores' or (tg_table_name = 'matches' and exists (
    select 1 from scoring_authority.score_derived_intents_v1 intent
    where intent.tournament_id = match_value.tournament_id
      and intent.match_id = target_match_id
      and intent.source_transaction = txid_current() and intent.family = 'COMPETITION')) then
  if exists (select 1 from scoring_authority.net_skins_v1_configuration_revisions revision
    cross join lateral jsonb_array_elements(revision.configuration_manifest->'rounds') configured
    where revision.configuration_revision_id = current_value.configuration_revision_id
      and (configured->>'round_number')::integer = match_value.round_number) then
    perform production_control.append_score_derived_intent_v1(
      match_value.tournament_id, target_match_id, match_value.round_number, 'NET_SKINS',
      case when tg_table_name = 'hole_scores' then 'CANONICAL_SCORE_CHANGED' else 'CANONICAL_MATCH_LIFECYCLE_CHANGED' end,
      jsonb_strip_nulls(jsonb_build_object('matchRevision', match_value.match_revision,
        'holeNumber', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'hole_number' else null end,
        'holeRevision', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'hole_revision' else null end,
        'mutationKey', case when tg_table_name = 'hole_scores' then (case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->'mutation_key' else null end)), null
    );
  end if;
  else
  perform production_control.enqueue_production_net_skins_v1_round(
    match_value.round_number,
    case when tg_table_name = 'hole_scores'
      then 'CANONICAL_SCORE_CHANGED'
      else 'CANONICAL_MATCH_LIFECYCLE_CHANGED' end,
    'production-net-skins-v1-trigger'
  );
  end if;
  return case when tg_op = 'DELETE' then old else new end;
exception
  when sqlstate '22023' then
    return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION scoring_authority.enqueue_production_net_skins_v1_change() OWNER TO postgres;

