CREATE FUNCTION scoring_authority.enqueue_storylines_for_score_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
