-- Name: guard_completed_history_course_identity(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.guard_completed_history_course_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
