ALTER FUNCTION scoring_authority.guard_completed_history_course_identity() OWNER TO postgres;

--
-- Name: guard_completed_history_pointer(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.guard_completed_history_pointer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if current_setting('scoring_authority.completed_history_import', true) <> 'on' then
    raise exception using errcode = '42501', message = 'COMPLETED_HISTORY_IMPORT_RPC_REQUIRED';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION scoring_authority.guard_completed_history_pointer() OWNER TO postgres;

--
-- Name: guard_draft_projection_write(); Type: FUNCTION; Schema: scoring_authority; Owner: postgres
--

CREATE FUNCTION scoring_authority.guard_draft_projection_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'scoring_authority', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if current_setting('scoring_authority.draft_projection_import', true) <> 'on' then
    raise exception 'Draft revisions are immutable outside the supported projection import operation.'
      using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end; $$;


