    status text NOT NULL,
    requested_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT account_deletion_requests_v1_check CHECK ((((status = 'COMPLETED'::text) AND (completed_at IS NOT NULL) AND (auth_user_id IS NULL)) OR ((status <> 'COMPLETED'::text) AND (completed_at IS NULL) AND (auth_user_id IS NOT NULL)))),
    CONSTRAINT account_deletion_requests_v1_status_check CHECK ((status = ANY (ARRAY['PENDING_ADMINISTRATIVE_HANDOFF'::text, 'PENDING_REVIEW_ACCESS_HANDOFF'::text, 'READY'::text, 'COMPLETED'::text])))
);


ALTER TABLE participant_identity.account_deletion_requests_v1 OWNER TO postgres;

--
-- Name: future_tournament_identity_contexts_v1; Type: TABLE; Schema: participant_identity; Owner: postgres
--

CREATE TABLE participant_identity.future_tournament_identity_contexts_v1 (
    tournament_id text NOT NULL,
    contract_version text NOT NULL,
    binding_revision bigint NOT NULL,
    source_identity_tournament_id text NOT NULL,
    source_context_revision bigint NOT NULL,
    source_configuration_fingerprint text NOT NULL,
    binding_fingerprint text NOT NULL,
    roster_count integer NOT NULL,
    enrolled_count integer NOT NULL,
    not_enrolled_count integer NOT NULL,
    status text NOT NULL,
    certified_by_player_id text NOT NULL,
    certified_by_auth_user_id uuid NOT NULL,
    certified_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    runtime_generation_id uuid NOT NULL,
    authority_generation_id uuid NOT NULL,
    admission_generation_id uuid NOT NULL,
    pointer_revision bigint NOT NULL,
    CONSTRAINT future_identity_generation_ids_distinct_v1 CHECK (((runtime_generation_id <> authority_generation_id) AND (runtime_generation_id <> admission_generation_id) AND (authority_generation_id <> admission_generation_id))),
    CONSTRAINT future_tournament_identity_c_source_configuration_fingerp_check CHECK ((source_configuration_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT future_tournament_identity_c_source_identity_tournament_i_check CHECK ((source_identity_tournament_id = '2026'::text)),
    CONSTRAINT future_tournament_identity_contex_source_context_revision_check CHECK ((source_context_revision > 0)),
    CONSTRAINT future_tournament_identity_contexts_v1_binding_revision_check CHECK ((binding_revision > 0)),
    CONSTRAINT future_tournament_identity_contexts_v1_check CHECK (((enrolled_count >= 0) AND (enrolled_count <= roster_count))),
    CONSTRAINT future_tournament_identity_contexts_v1_check1 CHECK (((not_enrolled_count >= 0) AND ((enrolled_count + not_enrolled_count) = roster_count))),
    CONSTRAINT future_tournament_identity_contexts_v1_contract_version_check CHECK ((contract_version = 'production-future-participant-identity-context-v1'::text)),
    CONSTRAINT future_tournament_identity_contexts_v1_pointer_revision_check CHECK ((pointer_revision > 1)),
    CONSTRAINT future_tournament_identity_contexts_v1_roster_count_check CHECK ((roster_count > 0)),
    CONSTRAINT future_tournament_identity_contexts_v1_status_check CHECK ((status = 'CERTIFIED'::text)),
    CONSTRAINT future_tournament_identity_contexts_v_binding_fingerprint_check CHECK ((binding_fingerprint ~ '^[0-9a-f]{64}$'::text))
);


ALTER TABLE participant_identity.future_tournament_identity_contexts_v1 OWNER TO postgres;

--
-- Name: future_tournament_participant_bindings_v1; Type: TABLE; Schema: participant_identity; Owner: postgres
--

CREATE TABLE participant_identity.future_tournament_participant_bindings_v1 (
    tournament_id text NOT NULL,
    player_id text NOT NULL,
    enrollment_state text NOT NULL,
    source_identity_tournament_id text,
    source_configuration_revision bigint,
    source_contact_fingerprint text,
    bound_link_revision bigint,
    binding_revision bigint NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    contact_state text NOT NULL,
    CONSTRAINT future_participant_binding_state_v2 CHECK ((((enrollment_state = 'ENROLLED'::text) AND (contact_state = 'APPROVED'::text) AND (source_identity_tournament_id = '2026'::text) AND (source_configuration_revision IS NOT NULL) AND (source_contact_fingerprint IS NOT NULL) AND (bound_link_revision IS NOT NULL)) OR ((enrollment_state = 'NOT_ENROLLED'::text) AND (contact_state = 'APPROVED'::text) AND (source_identity_tournament_id = '2026'::text) AND (source_configuration_revision IS NOT NULL) AND (source_contact_fingerprint IS NOT NULL) AND (bound_link_revision IS NULL)) OR ((enrollment_state = 'NOT_ENROLLED'::text) AND (contact_state = 'MISSING'::text) AND (source_identity_tournament_id IS NULL) AND (source_configuration_revision IS NULL) AND (source_contact_fingerprint IS NULL) AND (bound_link_revision IS NULL)))),
    CONSTRAINT future_tournament_participan_source_identity_tournament_i_check CHECK (((source_identity_tournament_id IS NULL) OR (source_identity_tournament_id = '2026'::text))),
    CONSTRAINT future_tournament_participant__source_contact_fingerprint_check CHECK (((source_contact_fingerprint IS NULL) OR (source_contact_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT future_tournament_participant_bindings_v1_contact_state_check CHECK ((contact_state = ANY (ARRAY['APPROVED'::text, 'MISSING'::text]))),
    CONSTRAINT future_tournament_participant_bindings_v_binding_revision_check CHECK ((binding_revision > 0)),
    CONSTRAINT future_tournament_participant_bindings_v_enrollment_state_check CHECK ((enrollment_state = ANY (ARRAY['ENROLLED'::text, 'NOT_ENROLLED'::text])))
);


ALTER TABLE participant_identity.future_tournament_participant_bindings_v1 OWNER TO postgres;

