    CONSTRAINT identity_config_import_runs_configuration_revision_check CHECK ((configuration_revision > 0)),
    CONSTRAINT identity_config_import_runs_source_fingerprint_check CHECK ((source_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT identity_config_import_runs_status_check CHECK ((status = ANY (ARRAY['APPLIED'::text, 'REVIEW_REQUIRED'::text, 'APPROVED'::text, 'REJECTED'::text])))
);


ALTER TABLE participant_identity.identity_config_import_runs OWNER TO postgres;

--
-- Name: identity_context_revisions; Type: TABLE; Schema: participant_identity; Owner: postgres
--

CREATE TABLE participant_identity.identity_context_revisions (
    tournament_id text NOT NULL,
    context_revision bigint DEFAULT 1 NOT NULL,
    configuration_fingerprint text,
