    CONSTRAINT future_match_google_compatibility_jobs__requirement_class_check CHECK ((requirement_class = ANY (ARRAY['REQUIRED_FOR_ROLLBACK_EVIDENCE'::text, 'OPTIONAL_ARCHIVE'::text]))),
    CONSTRAINT production_future_google_certified_writer_shape_v2 CHECK (((NOT writer_installed) OR ((writer_generation_id IS NOT NULL) AND (destination_workbook_id IS NOT NULL) AND (target_contract_fingerprint IS NOT NULL) AND (structural_fingerprint IS NOT NULL) AND (structural_runtime_revision IS NOT NULL) AND (structural_runtime_revision > 0)))),
    CONSTRAINT production_future_google_job_attempts_v2 CHECK ((attempts >= 0)),
    CONSTRAINT production_future_google_job_certified_v2 CHECK ((((status = 'CERTIFIED'::text) AND (certified_at IS NOT NULL) AND (readback_fingerprint IS NOT NULL) AND (jsonb_typeof(readback_checkpoint) = 'object'::text)) OR ((status <> 'CERTIFIED'::text) AND (certified_at IS NULL)))),
    CONSTRAINT production_future_google_job_manifest_v2 CHECK (((expected_manifest_fingerprint IS NULL) OR (expected_manifest_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_future_google_job_readback_v2 CHECK (((readback_fingerprint IS NULL) OR (readback_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_future_google_job_shape_v2 CHECK ((((status = 'PROCESSING'::text) AND (claim_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (claimed_by IS NOT NULL)) OR ((status <> 'PROCESSING'::text) AND (claim_token IS NULL) AND (lease_expires_at IS NULL) AND (claimed_by IS NULL)))),
    CONSTRAINT production_future_google_job_status_v2 CHECK ((status = ANY (ARRAY['PROVISIONING_REQUIRED'::text, 'PROCESSING'::text, 'RETRYABLE'::text, 'CERTIFIED'::text, 'NOT_REQUIRED'::text, 'BLOCKED'::text, 'FAILED'::text]))),
    CONSTRAINT production_future_google_structural_fingerprint_v2 CHECK (((structural_fingerprint IS NULL) OR (structural_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_future_google_target_fingerprint_v2 CHECK (((target_contract_fingerprint IS NULL) OR (target_contract_fingerprint ~ '^[0-9a-f]{64}$'::text)))
);


