-- Name: scoring_admission_closures; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.scoring_admission_closures (
    closure_id uuid DEFAULT extensions.gen_random_uuid() NOT NULL,
    closure_kind text DEFAULT 'LEGACY_ADMISSION'::text NOT NULL,
    prior_legacy_closure_id uuid,
    tournament_id text NOT NULL,
    authority text NOT NULL,
    authority_generation_id uuid NOT NULL,
    admission_generation_id uuid NOT NULL,
    deployment_id text NOT NULL,
    status text DEFAULT 'CLOSING'::text NOT NULL,
    opening_admission_revision bigint NOT NULL,
    closing_admission_revision bigint NOT NULL,
    closed_admission_revision bigint,
    lease_high_watermark bigint DEFAULT 0 NOT NULL,
    start_source_fingerprint text,
    final_source_fingerprint text,
    reconciliation_fingerprint text,
    lease_set_fingerprint text,
    supabase_match_revisions jsonb,
    google_checkpoints jsonb,
    external_fence_evidence_id uuid,
    google_writer_provider_fence_id uuid,
    google_writer_provider_verification_id uuid,
    close_request_fingerprint text NOT NULL,
    close_payload_hash text NOT NULL,
    closing_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    reopened_at timestamp with time zone,
    consumed_at timestamp with time zone,
    actor_id text NOT NULL,
    consumed_epoch_id uuid,
    boundary_mode text DEFAULT 'PROVIDER_FENCE_V2'::text NOT NULL,
    first_source_fingerprint text,
    first_source_captured_at timestamp with time zone,
    second_source_captured_at timestamp with time zone,
    supabase_shadow_fingerprint text,
    unexplained_difference_count integer,
    resource_class text DEFAULT 'PRODUCTION'::text NOT NULL,
    certification_resource_id text,
    prior_certification_closure_id uuid,
    CONSTRAINT production_scoring_admission_closure_kind_shape_check CHECK ((((resource_class = 'PRODUCTION'::text) AND (((closure_kind = 'LEGACY_ADMISSION'::text) AND (prior_legacy_closure_id IS NULL) AND (authority = 'GOOGLE'::text)) OR ((closure_kind = 'SUPABASE_INGRESS'::text) AND (prior_legacy_closure_id IS NOT NULL) AND (authority = 'SUPABASE'::text)))) OR ((resource_class = 'CERTIFICATION'::text) AND (closure_kind = 'SUPABASE_INGRESS'::text) AND (prior_legacy_closure_id IS NULL) AND (authority = 'SUPABASE'::text)))),
    CONSTRAINT production_scoring_closure_boundary_evidence_check CHECK ((((resource_class = 'PRODUCTION'::text) AND (((boundary_mode = 'PROVIDER_FENCE_V2'::text) AND (external_fence_evidence_id IS NOT NULL) AND (google_writer_provider_fence_id IS NOT NULL) AND (google_writer_provider_verification_id IS NOT NULL) AND (first_source_fingerprint IS NULL) AND (first_source_captured_at IS NULL) AND (second_source_captured_at IS NULL) AND (supabase_shadow_fingerprint IS NULL) AND (unexplained_difference_count IS NULL)) OR ((boundary_mode = 'MAINTENANCE_WINDOW_V1'::text) AND (external_fence_evidence_id IS NULL) AND (google_writer_provider_fence_id IS NULL) AND (google_writer_provider_verification_id IS NULL) AND ((status = ANY (ARRAY['CLOSING'::text, 'REOPENED'::text])) OR ((status = ANY (ARRAY['CLOSED'::text, 'CONSUMED'::text])) AND (first_source_fingerprint IS NOT NULL) AND (first_source_captured_at IS NOT NULL) AND (second_source_captured_at IS NOT NULL) AND (second_source_captured_at >= first_source_captured_at) AND (final_source_fingerprint = first_source_fingerprint) AND (final_source_fingerprint = supabase_shadow_fingerprint) AND (unexplained_difference_count = 0)))))) OR ((resource_class = 'CERTIFICATION'::text) AND (boundary_mode = 'CERTIFICATION_INGRESS_V1'::text) AND (external_fence_evidence_id IS NULL) AND (google_writer_provider_fence_id IS NULL) AND (google_writer_provider_verification_id IS NULL) AND (first_source_fingerprint IS NULL) AND (first_source_captured_at IS NULL) AND (second_source_captured_at IS NULL) AND (supabase_shadow_fingerprint IS NULL) AND (unexplained_difference_count IS NULL)))),
    CONSTRAINT production_scoring_closure_boundary_mode_check CHECK ((((resource_class = 'PRODUCTION'::text) AND (boundary_mode = ANY (ARRAY['PROVIDER_FENCE_V2'::text, 'MAINTENANCE_WINDOW_V1'::text]))) OR ((resource_class = 'CERTIFICATION'::text) AND (boundary_mode = 'CERTIFICATION_INGRESS_V1'::text)))),
    CONSTRAINT production_scoring_closure_difference_count_check CHECK (((unexplained_difference_count IS NULL) OR (unexplained_difference_count >= 0))),
    CONSTRAINT production_scoring_closure_first_source_check CHECK (((first_source_fingerprint IS NULL) OR (first_source_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_scoring_closure_shadow_check CHECK (((supabase_shadow_fingerprint IS NULL) OR (supabase_shadow_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT scoring_admission_closures_authority_check CHECK ((authority = ANY (ARRAY['GOOGLE'::text, 'SUPABASE'::text]))),
    CONSTRAINT scoring_admission_closures_check CHECK (((closed_admission_revision IS NULL) OR (closed_admission_revision >= closing_admission_revision))),
    CONSTRAINT scoring_admission_closures_check1 CHECK ((((status = 'CLOSING'::text) AND (closed_at IS NULL) AND (reopened_at IS NULL) AND (consumed_at IS NULL)) OR ((status = 'CLOSED'::text) AND (closed_at IS NOT NULL) AND (reopened_at IS NULL) AND (consumed_at IS NULL)) OR ((status = 'REOPENED'::text) AND (reopened_at IS NOT NULL) AND (consumed_at IS NULL)) OR ((status = 'CONSUMED'::text) AND (closed_at IS NOT NULL) AND (consumed_at IS NOT NULL) AND (consumed_epoch_id IS NOT NULL)))),
    CONSTRAINT scoring_admission_closures_check2 CHECK (((status = 'CLOSING'::text) OR ((closed_admission_revision IS NOT NULL) AND (final_source_fingerprint IS NOT NULL) AND (reconciliation_fingerprint IS NOT NULL) AND (lease_set_fingerprint IS NOT NULL) AND (jsonb_typeof(supabase_match_revisions) = 'object'::text) AND (jsonb_typeof(google_checkpoints) = 'object'::text)) OR (status = 'REOPENED'::text))),
    CONSTRAINT scoring_admission_closures_close_payload_hash_check CHECK ((close_payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT scoring_admission_closures_close_request_fingerprint_check CHECK ((close_request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT scoring_admission_closures_closing_admission_revision_check CHECK ((closing_admission_revision > 0)),
    CONSTRAINT scoring_admission_closures_closure_kind_check CHECK ((closure_kind = ANY (ARRAY['LEGACY_ADMISSION'::text, 'SUPABASE_INGRESS'::text]))),
    CONSTRAINT scoring_admission_closures_deployment_id_check CHECK ((deployment_id ~ '^dpl_[A-Za-z0-9]{8,64}$'::text)),
    CONSTRAINT scoring_admission_closures_final_source_fingerprint_check CHECK (((final_source_fingerprint IS NULL) OR (final_source_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT scoring_admission_closures_lease_high_watermark_check CHECK ((lease_high_watermark >= 0)),
    CONSTRAINT scoring_admission_closures_lease_set_fingerprint_check CHECK (((lease_set_fingerprint IS NULL) OR (lease_set_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT scoring_admission_closures_opening_admission_revision_check CHECK ((opening_admission_revision >= 0)),
    CONSTRAINT scoring_admission_closures_reconciliation_fingerprint_check CHECK (((reconciliation_fingerprint IS NULL) OR (reconciliation_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT scoring_admission_closures_resource_class_check CHECK ((resource_class = ANY (ARRAY['PRODUCTION'::text, 'CERTIFICATION'::text]))),
    CONSTRAINT scoring_admission_closures_resource_provenance CHECK ((((resource_class = 'PRODUCTION'::text) AND (certification_resource_id IS NULL) AND (prior_certification_closure_id IS NULL)) OR ((resource_class = 'CERTIFICATION'::text) AND (certification_resource_id IS NOT NULL) AND (closure_kind = 'SUPABASE_INGRESS'::text) AND (authority = 'SUPABASE'::text) AND (prior_legacy_closure_id IS NULL) AND (external_fence_evidence_id IS NULL) AND (google_writer_provider_fence_id IS NULL) AND (google_writer_provider_verification_id IS NULL) AND (COALESCE(google_checkpoints, '{}'::jsonb) = '{}'::jsonb)))),
    CONSTRAINT scoring_admission_closures_start_source_fingerprint_check CHECK (((start_source_fingerprint IS NULL) OR (start_source_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT scoring_admission_closures_status_check CHECK ((status = ANY (ARRAY['CLOSING'::text, 'CLOSED'::text, 'REOPENED'::text, 'CONSUMED'::text])))
);


