    CONSTRAINT vercel_writer_critical_waf_dispa_provider_response_status_check CHECK (((provider_response_status IS NULL) OR ((provider_response_status >= 400) AND (provider_response_status <= 599)))),
    CONSTRAINT vercel_writer_critical_waf_dispat_candidate_deployment_id_check CHECK ((candidate_deployment_id ~ '^dpl_[A-Za-z0-9]{8,64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_dispat_draft_custom_rule_count_check CHECK (((draft_custom_rule_count IS NULL) OR (draft_custom_rule_count = 1))),
