--
-- Name: vercel_writer_critical_waf_dispatches; Type: TABLE; Schema: production_control; Owner: postgres
--

CREATE TABLE production_control.vercel_writer_critical_waf_dispatches (
    dispatch_id uuid NOT NULL,
    epoch_id uuid NOT NULL,
    dispatch_request_id uuid NOT NULL,
    transition_request_id uuid NOT NULL,
    dispatch_step text NOT NULL,
    attempt integer NOT NULL,
    status text NOT NULL,
    request_fingerprint text NOT NULL,
    payload_hash text NOT NULL,
    provider_intent_fingerprint text NOT NULL,
    claimed_at timestamp with time zone NOT NULL,
    claim_expires_at timestamp with time zone NOT NULL,
    provider_dispatch_started_at timestamp with time zone,
    provider_result_observation_id uuid,
    provider_dispatch_result_id uuid,
    provider_result_fingerprint text,
    provider_observed_at timestamp with time zone,
    recorded_at timestamp with time zone,
    actor_id text NOT NULL,
    authenticated_actor_fingerprint text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT production_vercel_writer_critical_waf_dispatch_state_check CHECK (((claim_expires_at > claimed_at) AND (claim_expires_at <= (claimed_at + '00:00:15'::interval)) AND (((status = 'RESERVED'::text) AND (provider_dispatch_started_at IS NULL) AND (provider_result_observation_id IS NULL) AND (provider_dispatch_result_id IS NULL) AND (provider_result_fingerprint IS NULL) AND (provider_observed_at IS NULL) AND (recorded_at IS NULL)) OR ((status = 'PROVIDER_MUTATING'::text) AND (provider_dispatch_started_at IS NOT NULL) AND (provider_result_observation_id IS NULL) AND (provider_dispatch_result_id IS NULL) AND (provider_result_fingerprint IS NULL) AND (provider_observed_at IS NULL) AND (recorded_at IS NULL)) OR ((status = 'TARGET_CONFIRMED'::text) AND (provider_dispatch_started_at IS NOT NULL) AND (((dispatch_step = 'CRITICAL_RULE_INSERT'::text) AND (provider_result_observation_id IS NULL) AND (provider_dispatch_result_id IS NOT NULL)) OR ((dispatch_step <> 'CRITICAL_RULE_INSERT'::text) AND (provider_result_observation_id IS NOT NULL) AND (provider_dispatch_result_id IS NULL))) AND (provider_result_fingerprint IS NOT NULL) AND (provider_observed_at IS NOT NULL) AND (recorded_at IS NOT NULL)) OR ((status = 'OUTCOME_UNKNOWN'::text) AND (provider_dispatch_started_at IS NOT NULL) AND (provider_result_observation_id IS NULL) AND (provider_dispatch_result_id IS NOT NULL) AND (provider_result_fingerprint IS NOT NULL) AND (provider_observed_at IS NOT NULL) AND (recorded_at IS NOT NULL)) OR ((status = 'PROVIDER_REJECTED'::text) AND (provider_dispatch_started_at IS NOT NULL) AND (provider_result_observation_id IS NULL) AND (provider_dispatch_result_id IS NOT NULL) AND (provider_result_fingerprint IS NOT NULL) AND (provider_observed_at IS NOT NULL) AND (recorded_at IS NOT NULL))))),
    CONSTRAINT vercel_writer_critical_waf_d_authenticated_actor_fingerpr_check CHECK ((authenticated_actor_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_di_provider_intent_fingerprint_check CHECK ((provider_intent_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_di_provider_result_fingerprint_check CHECK (((provider_result_fingerprint IS NULL) OR (provider_result_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT vercel_writer_critical_waf_dispatches_actor_id_check CHECK (((btrim(actor_id) <> ''::text) AND (length(actor_id) <= 160))),
    CONSTRAINT vercel_writer_critical_waf_dispatches_attempt_check CHECK ((attempt = 1)),
    CONSTRAINT vercel_writer_critical_waf_dispatches_dispatch_step_check CHECK ((dispatch_step = ANY (ARRAY['CRITICAL_RULE_INSERT'::text, 'CRITICAL_DRAFT_ACTIVATE'::text, 'BASELINE_VERSION_ACTIVATE'::text]))),
    CONSTRAINT vercel_writer_critical_waf_dispatches_payload_hash_check CHECK ((payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_dispatches_request_fingerprint_check CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT vercel_writer_critical_waf_dispatches_status_check CHECK ((status = ANY (ARRAY['RESERVED'::text, 'PROVIDER_MUTATING'::text, 'TARGET_CONFIRMED'::text, 'OUTCOME_UNKNOWN'::text, 'PROVIDER_REJECTED'::text])))
);


