    CONSTRAINT authority_epochs_authority_after_check CHECK ((authority_after = ANY (ARRAY['GOOGLE'::text, 'SUPABASE'::text]))),
    CONSTRAINT authority_epochs_authority_before_check CHECK ((authority_before = ANY (ARRAY['GOOGLE'::text, 'SUPABASE'::text]))),
    CONSTRAINT authority_epochs_epoch_type_check CHECK ((epoch_type = ANY (ARRAY['CUTOVER'::text, 'ROLLBACK'::text, 'CERTIFICATION_INITIALIZATION'::text, 'CERTIFICATION_ANNUAL_TRANSITION'::text]))),
    CONSTRAINT authority_epochs_status_check CHECK ((status = ANY (ARRAY['PREPARED'::text, 'COMMITTED'::text, 'BLOCKED'::text, 'ABORTED'::text]))),
    CONSTRAINT production_authority_epoch_boundary_evidence_check CHECK ((((epoch_type <> ALL (ARRAY['CERTIFICATION_INITIALIZATION'::text, 'CERTIFICATION_ANNUAL_TRANSITION'::text])) AND ((boundary_mode = 'PROVIDER_FENCE_V2'::text) OR ((boundary_mode = 'MAINTENANCE_WINDOW_V1'::text) AND (external_fence_evidence_id IS NULL) AND (google_writer_provider_fence_id IS NULL) AND (google_writer_provider_verification_id IS NULL) AND (supabase_shadow_fingerprint IS NOT NULL)))) OR ((epoch_type = ANY (ARRAY['CERTIFICATION_INITIALIZATION'::text, 'CERTIFICATION_ANNUAL_TRANSITION'::text])) AND (boundary_mode = 'CERTIFICATION_INGRESS_V1'::text) AND (authority_before = 'SUPABASE'::text) AND (authority_after = 'SUPABASE'::text) AND (external_fence_evidence_id IS NULL) AND (google_writer_provider_fence_id IS NULL) AND (google_writer_provider_verification_id IS NULL) AND (google_checkpoints = '{}'::jsonb) AND (supabase_shadow_fingerprint IS NULL) AND (commit_source_fingerprint IS NULL) AND (commit_source_verified_at IS NULL)))),
    CONSTRAINT production_authority_epoch_boundary_mode_check CHECK ((((epoch_type <> ALL (ARRAY['CERTIFICATION_INITIALIZATION'::text, 'CERTIFICATION_ANNUAL_TRANSITION'::text])) AND (boundary_mode = ANY (ARRAY['PROVIDER_FENCE_V2'::text, 'MAINTENANCE_WINDOW_V1'::text]))) OR ((epoch_type = ANY (ARRAY['CERTIFICATION_INITIALIZATION'::text, 'CERTIFICATION_ANNUAL_TRANSITION'::text])) AND (boundary_mode = 'CERTIFICATION_INGRESS_V1'::text)))),
    CONSTRAINT production_authority_epoch_closed_admission_revision_check CHECK (((closed_admission_revision IS NULL) OR (closed_admission_revision > 0))),
    CONSTRAINT production_authority_epoch_closure_boundary_check CHECK (((closure_boundary_fingerprint IS NULL) OR (closure_boundary_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_authority_epoch_commit_source_check CHECK (((commit_source_fingerprint IS NULL) OR (commit_source_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_authority_epoch_deployment_commit_check CHECK ((deployment_commit ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT production_authority_epoch_prior_source_fingerprint_check CHECK (((prior_source_fingerprint IS NULL) OR (prior_source_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_authority_epoch_reconciliation_fingerprint_check CHECK ((reconciliation_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT production_authority_epoch_request_fingerprint_check CHECK (((request_fingerprint IS NULL) OR (request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_authority_epoch_shadow_check CHECK (((supabase_shadow_fingerprint IS NULL) OR (supabase_shadow_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT production_authority_epoch_source_fingerprint_check CHECK (((source_fingerprint IS NULL) OR (source_fingerprint ~ '^[0-9a-f]{64}$'::text)))
);


