    CONSTRAINT calcutta_v1_recalculation_jobs_delivery_attempts_check CHECK (((delivery_attempts >= 0) AND (delivery_attempts <= 5))),
    CONSTRAINT calcutta_v1_recalculation_jobs_delivery_cycle_check CHECK ((delivery_cycle > 0)),
    CONSTRAINT calcutta_v1_recalculation_jobs_delivery_error_class_check CHECK ((delivery_error_class = ANY (ARRAY['RETRYABLE'::text, 'TERMINAL'::text]))),
    CONSTRAINT calcutta_v1_recalculation_jobs_reason_check CHECK (((btrim(reason) <> ''::text) AND (length(reason) <= 120))),
    CONSTRAINT calcutta_v1_recalculation_jobs_request_fingerprint_check CHECK (((request_fingerprint IS NULL) OR (request_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT calcutta_v1_recalculation_jobs_request_payload_hash_check CHECK (((request_payload_hash IS NULL) OR (request_payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT calcutta_v1_recalculation_jobs_requested_by_check CHECK (((btrim(requested_by) <> ''::text) AND (length(requested_by) <= 160))),
    CONSTRAINT calcutta_v1_recalculation_jobs_source_fingerprint_check CHECK ((source_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calcutta_v1_recalculation_jobs_source_revision_check CHECK ((jsonb_typeof(source_revision) = 'object'::text)),
    CONSTRAINT calcutta_v1_recalculation_jobs_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'SUPERSEDED'::text])))
);


