    CONSTRAINT completed_history_scorecards_check CHECK ((((coverage_status = 'COMPLETE'::text) AND (recorded_holes = 18) AND (jsonb_array_length(hole_values) = 18)) OR ((coverage_status = 'PARTIAL'::text) AND (recorded_holes >= 1) AND (recorded_holes <= 17) AND (jsonb_array_length(hole_values) = 18)) OR ((coverage_status = 'UNAVAILABLE'::text) AND (recorded_holes = 0) AND (jsonb_array_length(hole_values) = ANY (ARRAY[0, 18]))))),
    CONSTRAINT completed_history_scorecards_coverage_status_check CHECK ((coverage_status = ANY (ARRAY['COMPLETE'::text, 'PARTIAL'::text, 'UNAVAILABLE'::text]))),
    CONSTRAINT completed_history_scorecards_entity_kind_check CHECK ((entity_kind = ANY (ARRAY['PLAYER'::text, 'PAIRING'::text, 'TEAM'::text]))),
    CONSTRAINT completed_history_scorecards_hole_values_check CHECK ((jsonb_typeof(hole_values) = 'array'::text)),
    CONSTRAINT completed_history_scorecards_player_slot_check CHECK ((player_slot = ANY (ARRAY[1, 2]))),
    CONSTRAINT completed_history_scorecards_recorded_holes_check CHECK (((recorded_holes >= 0) AND (recorded_holes <= 18))),
    CONSTRAINT completed_history_scorecards_score_semantics_check CHECK ((jsonb_typeof(score_semantics) = 'object'::text)),
    CONSTRAINT completed_history_scorecards_source_payload_check CHECK ((jsonb_typeof(source_payload) = 'object'::text)),
    CONSTRAINT completed_history_scorecards_team_side_check CHECK ((team_side = ANY (ARRAY[1, 2])))
);


